using System.Collections.Immutable;
using System.Globalization;
using MtgEngine.Domain.Enums;
using MtgEngine.Domain.Models;
using MtgEngine.Rules.Abilities;
using MtgEngine.Rules.Cards;
using MtgEngine.Rules.Engine;
using MtgEngine.Rules.Events;
using MtgEngine.Rules.Mana;
using MtgEngine.Rules.State;
using MtgEngine.Rules.Views;

namespace MtgEngine.Rules.Tests;

/// <summary>
/// What a compiled card actually does when it is played.
/// </summary>
/// <remarks>
/// Coverage counts cards whose every line the compiler could <em>read</em>. That is not the same
/// claim as the card being right: a template that maps "destroy target creature" to the wrong
/// target, or fires a trigger at the wrong moment, parses perfectly and plays wrongly. Nothing in
/// the coverage number would notice.
/// <para>
/// Testing all 32,765 cards one at a time is not possible, and would be the same mistake as
/// writing them one at a time. Testing each <em>template</em> is, and every card that uses a
/// template inherits its verification — so these tests are written per template, from the real
/// oracle wording, and played through a real game rather than asserted against the parse tree.
/// </para>
/// </remarks>
public sealed class CompiledCardBehaviourTests
{
    private static readonly CompiledPool Pool = new();

    /// <summary>A card built from real printed wording, so the template under test is the real one.</summary>
    private static CardDefinition Card(
        string name,
        string oracleText,
        CardType types = CardType.Instant,
        int? power = null,
        int? toughness = null,
        KeywordAbility keywords = KeywordAbility.None,
        params string[] subtypes) => new()
        {
            OracleId = "oracle-" + name.ToLowerInvariant().Replace(' ', '-'),
            Name = name,
            OracleText = oracleText,
            CardTypes = types,
            Power = power,
            Toughness = toughness,
            Keywords = keywords,
            Subtypes = subtypes,
        };

    /// <summary>A vanilla creature of one colour, for the protection rules.</summary>
    private static CardDefinition Coloured(string name, ManaColor colour) => new()
    {
        OracleId = "oracle-" + name.ToLowerInvariant().Replace(' ', '-'),
        Name = name,
        CardTypes = CardType.Creature,
        Power = 2,
        Toughness = 2,
        ColorIdentity = [colour],
        Colors = [colour],
    };

    private static (Game Game, Guid Alice, Guid Bob) InMainPhase()
    {
        var alice = Guid.Parse("11111111-1111-1111-1111-111111111111");
        var bob = Guid.Parse("22222222-2222-2222-2222-222222222222");
        var game = Game.Start(
            Guid.NewGuid(),
            [
                new PlayerSetup(alice, "Alice", 20, TestCards.Deck(40, "Alice")),
                new PlayerSetup(bob, "Bob", 20, TestCards.Deck(40, "Bob")),
            ],
            new GameRandom(1),
            startingPlayerId: alice,
            abilities: Pool);

        game.BeginPlay(withMulligans: false);
        TestCards.PassToStep(game, TurnStep.PrecombatMain);
        return (game, alice, bob);
    }

    /// <summary>
    /// Plays on until nothing is waiting.
    /// </summary>
    /// <remarks>
    /// It passes priority at least once even with an empty stack, because state-based actions
    /// run when a player would receive priority (CR 704.3) — returning early on "nothing on the
    /// stack" meant an Aura whose creature had just died was never checked, and the test read
    /// that as the rule not working.
    /// </remarks>
    private static void Settle(Game game)
    {
        Run(game);

        // The engine's founding invariant: state is a fold of the log, so a game rebuilt from its
        // events must equal the game that produced them. Checking it here is what makes each new
        // event pay for itself - an event the reducer handles differently from the emitter
        // diverges silently until something replays.
        //
        // The loop below is a separate method for one reason: this assertion used to sit after
        // it, and both of that loop's ordinary exits are `return`s, so it was reached only when
        // the guard ran out - which is to say almost never. Its own comment claimed every test
        // asserted the invariant while nearly none of them did, which is the worst state for a
        // check to be in: present, documented, and not running.
        Assert.Equal(game.State, GameReducer.Replay(game.Log));
    }

    /// <summary>Plays on until nothing is waiting, asserting nothing.</summary>
    private static void Run(Game game)
    {
        var passedOnce = false;

        for (var guard = 0; guard < 80; guard++)
        {
            if (game.State.Choice is { } choice)
            {
                game.Choose(
                    choice.PlayerId,
                    [.. choice.Options.Take(Math.Max(choice.MinPicks, 1)).Select(o => o.Id)]);
                continue;
            }

            if (passedOnce && game.State.Stack.IsEmpty && game.State.PendingTriggers.IsEmpty)
                return;

            if (game.State.Priority.Holder is not { } holder)
                return;

            game.PassPriority(holder);
            passedOnce = true;
        }
    }

    // ---- A quoted ability that is a static (CR 604.1, 613.1) -----------------

    /// <summary>
    /// Sedge Sliver: a group grant whose quotation is a static, applied in layer 7c.
    /// </summary>
    /// <remarks>
    /// <c>TryQuotedAbility</c> took a trigger, an activated ability or a mana ability and
    /// nothing else, so every card granting a <em>static</em> was refused at the frame with both
    /// halves of the sentence readable. The half that was missing is not the reading — the
    /// quotation compiles through the same static readers a printed line does — it is
    /// <em>where the effect lands</em>: a granted ability goes in layer 6, and a granted
    /// static's effect goes in whichever layer that effect belongs to, which here is 7c.
    /// <para>
    /// Two things are asserted that a grant applied to the source alone would also pass, and
    /// they are why this is the test for the family. The bonus reaches a <em>different</em>
    /// Sliver, so the ability is genuinely on each member of the group rather than on the card
    /// that printed it. And the condition inside the quotation is answered against the
    /// permanent <em>carrying</em> the ability, not the one that granted it: Alice controls the
    /// Swamp, so her Slivers grow and Bob's does not, which is what "you" means on an ability a
    /// permanent has (CR 109.5).
    /// </para>
    /// </remarks>
    [Fact]
    public void A_group_grant_of_a_static_pumps_each_member_and_reads_its_own_condition()
    {
        var sedge = Card(
            "Sedge Sliver Test",
            "All Sliver creatures have \"This creature gets +1/+1 as long as you control a"
                + " Swamp.\"\nAll Slivers have \"{B}: Regenerate this permanent.\"",
            CardType.Creature,
            power: 2,
            toughness: 2,
            subtypes: "Sliver");

        var compiled = CardCompiler.Compile(sedge);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        // The bonus is 7c and not layer 6, which is the whole of what this round built.
        Assert.Contains(
            compiled.Statics,
            s => s.Layer == EffectLayer.PowerToughnessModify
                && s.Id.Contains("static:", StringComparison.Ordinal));

        var otherSliver = Card(
            "Sedge Fellow Sliver Test", string.Empty, CardType.Creature,
            power: 2, toughness: 2, subtypes: "Sliver");

        var (game, alice, bob) = InMainPhase();
        var source = game.Create(alice, sedge, Zone.Battlefield);
        var mine = game.Create(alice, otherSliver, Zone.Battlefield);
        var theirs = game.Create(bob, otherSliver, Zone.Battlefield);
        Settle(game);

        int PowerOf(ObjectId id) =>
            Characteristics.Of(game.State, Pool, game.State.GetObject(id)).Power!.Value;

        // No Swamp anywhere: the ability is granted and its condition is false, so nothing moves.
        Assert.Equal(2, PowerOf(source));
        Assert.Equal(2, PowerOf(mine));
        Assert.Equal(2, PowerOf(theirs));

        game.Create(alice, TestCards.BasicLand("Swamp"), Zone.Battlefield);
        Settle(game);

        Assert.Equal(3, PowerOf(source));
        Assert.Equal(3, PowerOf(mine));

        // Bob controls no Swamp, and the ability his Sliver has says "you".
        Assert.Equal(2, PowerOf(theirs));
    }

    /// <summary>
    /// The granted bonus is applied after a base power and toughness is set (CR 613.4b, 613.4c).
    /// </summary>
    /// <remarks>
    /// The assertion the layer is for. Layer 6 is the only place the engine had to put anything
    /// a static ability granted, and a <c>+1/+1</c> put there would be added and then
    /// <em>erased</em> by the layer-7b effect that sets a base size — the creature would come out
    /// 0/1, exactly as though the grant had never happened, on a card that compiled clean.
    /// Reported in its own layer it survives, and 0/1 plus the granted +1/+1 is 1/2.
    /// </remarks>
    [Fact]
    public void A_granted_bonus_is_applied_after_a_base_size_is_set()
    {
        var sedge = Card(
            "Layered Sliver Test",
            "All Sliver creatures have \"This creature gets +1/+1 as long as you control a"
                + " Swamp.\"",
            CardType.Creature,
            power: 2,
            toughness: 2,
            subtypes: "Sliver");

        var shrink = Card(
            "Sliver Shrink Test",
            "Enchant creature\nEnchanted creature has base power and toughness 0/1.",
            CardType.Enchantment,
            subtypes: "Aura");

        Assert.True(
            CardCompiler.Compile(shrink).IsComplete,
            string.Join(" | ", CardCompiler.Compile(shrink).Unhandled));

        var (game, alice, _) = InMainPhase();
        game.Create(alice, sedge, Zone.Battlefield);
        game.Create(alice, TestCards.BasicLand("Swamp"), Zone.Battlefield);
        var victim = game.Create(
            alice,
            Card("Shrunk Sliver Test", string.Empty, CardType.Creature,
                power: 4, toughness: 4, subtypes: "Sliver"),
            Zone.Battlefield);

        var aura = TestCards.PutInHand(game, alice, shrink);
        game.CastSpell(alice, aura, [Target.ToPermanent(victim)]);
        Settle(game);

        var computed = Characteristics.Of(game.State, Pool, game.State.GetObject(victim));
        Assert.Equal(1, computed.Power);
        Assert.Equal(2, computed.Toughness);
    }

    /// <summary>
    /// Giant's Amulet: an Equipment granting its bearer a static about itself (CR 613.1f).
    /// </summary>
    /// <remarks>
    /// The permission is asserted twice over, because a keyword flag alone would also be set by
    /// a reader that granted hexproof outright and dropped the condition. The creature is
    /// untapped and an opponent's spell is refused; the creature is tapped and the same spell,
    /// from the same hand, on the same turn, is accepted.
    /// </remarks>
    [Fact]
    public void An_equipment_grants_its_bearer_a_static_about_itself()
    {
        var amulet = Card(
            "Giant's Amulet Test",
            "Equipped creature gets +0/+1 and has \"This creature has hexproof as long as it's"
                + " untapped.\"\nEquip {2}",
            CardType.Artifact,
            subtypes: "Equipment");

        var compiled = CardCompiler.Compile(amulet);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var equipment = game.Create(alice, amulet, Zone.Battlefield);
        var bearer = game.Create(alice, TestCards.Creature("Amulet Bearer Test", 2, 2), Zone.Battlefield);

        foreach (var _ in Enumerable.Range(0, 2))
        {
            var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
            game.ActivateAbility(alice, forest, "mana");
        }

        game.ActivateAbility(alice, equipment, "equip", [Target.ToPermanent(bearer)]);
        Settle(game);

        var equipped = Characteristics.Of(game.State, Pool, game.State.GetObject(bearer));
        Assert.Equal(2, equipped.Power);
        Assert.Equal(3, equipped.Toughness);
        Assert.True(equipped.Has(KeywordAbility.Hexproof));

        TestCards.PassUntil(
            game,
            () => game.State.ActivePlayerId == bob
                && game.State.CurrentStep == TurnStep.PrecombatMain);

        var bolt = TestCards.PutInHand(
            game, bob, Card("Amulet Bolt Test", "~ deals 3 damage to any target."));

        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(bob, bolt, [Target.ToPermanent(bearer)]));

        // Tapped, the condition inside the quotation is false and the same spell is legal.
        game.Tap(bearer);

        Assert.False(
            Characteristics.Of(game.State, Pool, game.State.GetObject(bearer))
                .Has(KeywordAbility.Hexproof));

        game.CastSpell(bob, bolt, [Target.ToPermanent(bearer)]);
        Settle(game);

        Assert.DoesNotContain(bearer, game.State.Battlefield);
    }

    /// <summary>
    /// Rune of Might: an Aura giving an Equipment a static about a <em>third</em> permanent.
    /// </summary>
    /// <remarks>
    /// The case that decides the shape of the whole feature. The effect is the Aura's — it exists
    /// exactly while the Aura is on the battlefield (CR 604.2) — the permanent carrying the
    /// ability is the Equipment, and the permanent it changes is the creature the Equipment is
    /// attached to. Three objects, and the middle one is the one the inner reader has to be
    /// handed: "equipped creature" is a question only the Equipment can answer.
    /// <para>
    /// Which is why the bearer is looked up from raw state rather than computed. Finding it by
    /// asking another permanent for its characteristics, from inside the layers, is the
    /// re-entrant read CR 613.8's hazard is about, and it has overflowed the stack here before.
    /// </para>
    /// </remarks>
    [Fact]
    public void An_aura_on_an_equipment_grants_a_static_about_what_the_equipment_holds()
    {
        var rune = Card(
            "Rune Of Might Test",
            "Enchant permanent\nWhen this Aura enters, draw a card.\n"
                + "As long as enchanted permanent is a creature, it gets +1/+1 and has trample.\n"
                + "As long as enchanted permanent is an Equipment, it has \"Equipped creature"
                + " gets +1/+1 and has trample.\"",
            CardType.Enchantment,
            subtypes: "Aura");

        var compiled = CardCompiler.Compile(rune);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var sword = Card("Rune Sword Test", "Equip {2}", CardType.Artifact, subtypes: "Equipment");

        var (game, alice, _) = InMainPhase();
        var equipment = game.Create(alice, sword, Zone.Battlefield);
        var bearer = game.Create(alice, TestCards.Creature("Rune Bearer Test", 2, 2), Zone.Battlefield);

        foreach (var _ in Enumerable.Range(0, 2))
        {
            var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
            game.ActivateAbility(alice, forest, "mana");
        }

        game.ActivateAbility(alice, equipment, "equip", [Target.ToPermanent(bearer)]);
        Settle(game);

        // The Equipment alone does nothing to the creature it holds.
        var bare = Characteristics.Of(game.State, Pool, game.State.GetObject(bearer));
        Assert.Equal(2, bare.Power);
        Assert.False(bare.Has(KeywordAbility.Trample));

        var card = TestCards.PutInHand(game, alice, rune);
        game.CastSpell(alice, card, [Target.ToPermanent(equipment)]);
        Settle(game);

        var aura = game.State.Battlefield
            .Select(game.State.GetObject)
            .Single(o => o.Card.Name == "Rune Of Might Test");

        Assert.Equal(equipment, aura.Permanent!.AttachedTo);

        // The Aura is on the Equipment, so the "is a creature" arm is not applying and the
        // Equipment is not a creature. Everything the creature gained came through the quotation.
        var held = Characteristics.Of(game.State, Pool, game.State.GetObject(bearer));
        Assert.Equal(3, held.Power);
        Assert.Equal(3, held.Toughness);
        Assert.True(held.Has(KeywordAbility.Trample));

        // And it is the Aura's effect: it ends when the Aura does (CR 604.2).
        game.Move(aura.Id, Zone.Graveyard, MoveCause.Destroy);
        Settle(game);

        var after = Characteristics.Of(game.State, Pool, game.State.GetObject(bearer));
        Assert.Equal(2, after.Power);
        Assert.False(after.Has(KeywordAbility.Trample));
    }

    /// <summary>
    /// Prison Barricade: a static a permanent has because of how it was cast (CR 607.2).
    /// </summary>
    /// <remarks>
    /// The gift already read a quoted trigger or activated ability; a quoted static is the third
    /// arm here as well, and the bearer is the permanent itself so nothing has to be looked for.
    /// <para>
    /// Both walls are on the board at once and only one of them was kicked, which is what makes
    /// the permission evidence rather than a coincidence: a reader that granted it outright, or
    /// one that lost the kicked flag across the resolution, would be indistinguishable from a
    /// test that only cast the kicked half.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_kicked_permanent_keeps_a_granted_static_and_attacks_with_it()
    {
        var barricade = new CardDefinition
        {
            OracleId = "oracle-prison-barricade-test",
            Name = "Prison Barricade Test",
            OracleText = "Defender\nKicker {1}\nIf this creature was kicked, it enters with a"
                + " +1/+1 counter on it and with \"This creature can attack as though it didn't"
                + " have defender.\"",
            CardTypes = CardType.Creature,
            ManaCostRaw = "{1}",
            Cmc = 1,
            Power = 1,
            Toughness = 3,
            Keywords = KeywordAbility.Defender,
        };

        var compiled = CardCompiler.Compile(barricade);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();

        foreach (var _ in Enumerable.Range(0, 3))
        {
            var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
            game.ActivateAbility(alice, forest, "mana");
        }

        var kickedCard = TestCards.PutInHand(game, alice, barricade);
        game.CastSpell(
            alice, kickedCard, [], variableValue: 0, tapToPay: null, modes: null, kicked: true);
        Settle(game);

        var plainCard = TestCards.PutInHand(game, alice, barricade);
        game.CastSpell(alice, plainCard, []);
        Settle(game);

        var walls = game.State.Battlefield
            .Select(game.State.GetObject)
            .Where(o => o.Card.Name == "Prison Barricade Test")
            .ToList();

        var kicked = walls.Single(o => o.WasKicked).Id;
        var plain = walls.Single(o => !o.WasKicked).Id;

        // The counter is the other half of the same printed sentence, and it says which is which.
        Assert.Equal(2, Characteristics.Of(game.State, Pool, game.State.GetObject(kicked)).Power);
        Assert.Equal(1, Characteristics.Of(game.State, Pool, game.State.GetObject(plain)).Power);

        PassTo(game, 3, TurnStep.DeclareAttackers);

        Assert.Null(CombatRules.CannotAttack(
            game.State, Pool, game.State.GetObject(kicked), alice, bob));

        Assert.Contains(
            "702.3b",
            CombatRules.CannotAttack(game.State, Pool, game.State.GetObject(plain), alice, bob)
                ?? string.Empty,
            StringComparison.Ordinal);

        game.DeclareAttackers(
            alice, new Dictionary<ObjectId, AttackTarget> { [kicked] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Settle(game);

        Assert.Equal(18, game.State.GetPlayer(bob).Life);
    }

    // ---- Damage --------------------------------------------------------------

    [Fact]
    public void Deals_damage_to_any_target_burns_a_player()
    {
        var bolt = Card("Bolt Test", "~ deals 3 damage to any target.");
        var (game, alice, bob) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, bolt);

        game.CastSpell(alice, card, [Target.ToPlayer(bob)]);
        Settle(game);

        Assert.Equal(17, game.State.GetPlayer(bob).Life);
    }

    [Fact]
    public void Deals_damage_to_any_target_can_kill_a_creature()
    {
        var bolt = Card("Bolt Test", "~ deals 3 damage to any target.");
        var (game, alice, bob) = InMainPhase();
        var bear = game.Create(bob, TestCards.Creature("Bear", 2, 2), Zone.Battlefield);
        var card = TestCards.PutInHand(game, alice, bolt);

        game.CastSpell(alice, card, [Target.ToPermanent(bear)]);
        Settle(game);

        Assert.Empty(game.State.Battlefield);
    }

    // ---- Removal -------------------------------------------------------------

    [Fact]
    public void Destroy_target_creature_destroys_it()
    {
        var murder = Card("Murder Test", "Destroy target creature.");
        var (game, alice, bob) = InMainPhase();
        var bear = game.Create(bob, TestCards.Creature("Bear", 5, 5), Zone.Battlefield);
        var card = TestCards.PutInHand(game, alice, murder);

        game.CastSpell(alice, card, [Target.ToPermanent(bear)]);
        Settle(game);

        Assert.Empty(game.State.Battlefield);
        Assert.Single(game.State.GetPlayer(bob).Graveyard);
    }

    [Fact]
    public void Exile_target_creature_exiles_rather_than_destroying()
    {
        var scour = Card("Exile Test", "Exile target creature.");
        var (game, alice, bob) = InMainPhase();
        var myr = game.Create(bob, TestCards.Indestructible("Myr"), Zone.Battlefield);
        var card = TestCards.PutInHand(game, alice, scour);

        game.CastSpell(alice, card, [Target.ToPermanent(myr)]);
        Settle(game);

        Assert.Empty(game.State.Battlefield);
        Assert.Single(game.State.Exile);
    }

    [Fact]
    public void Return_to_hand_bounces_to_the_owners_hand()
    {
        var unsummon = Card("Bounce Test", "Return target creature to its owner's hand.");
        var (game, alice, bob) = InMainPhase();
        var handBefore = game.State.GetPlayer(bob).Hand.Count;
        var bear = game.Create(bob, TestCards.Creature("Bear", 2, 2), Zone.Battlefield);
        var card = TestCards.PutInHand(game, alice, unsummon);

        game.CastSpell(alice, card, [Target.ToPermanent(bear)]);
        Settle(game);

        Assert.Empty(game.State.Battlefield);
        Assert.Equal(handBefore + 1, game.State.GetPlayer(bob).Hand.Count);
    }

    // ---- Cards and life ------------------------------------------------------

    [Fact]
    public void Draw_two_cards_draws_two()
    {
        var divination = Card("Draw Test", "Draw two cards.");
        var (game, alice, _) = InMainPhase();
        var before = game.State.GetPlayer(alice).Library.Count;
        var card = TestCards.PutInHand(game, alice, divination);

        game.CastSpell(alice, card);
        Settle(game);

        Assert.Equal(before - 2, game.State.GetPlayer(alice).Library.Count);
    }

    [Fact]
    public void You_gain_life_gains_it()
    {
        var salve = Card("Life Test", "You gain 5 life.");
        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, salve);

        game.CastSpell(alice, card);
        Settle(game);

        Assert.Equal(25, game.State.GetPlayer(alice).Life);
    }

    // ---- Markers written and read by nothing (CR 700.2d, 613.4c) -------------

    /// <summary>
    /// A shield counter spends itself instead of letting the damage land (CR 122.1d).
    /// </summary>
    /// <remarks>
    /// The stun counter's twin, and it was in exactly the same state: nine corpus cards put a
    /// shield counter on a creature, the compiler read the line, the counter went on, and nothing
    /// in the engine ever looked for it — so the creature took the damage and died on schedule.
    /// <para>
    /// It hid better than the stun counter did. Every card that grants one prints the rule as
    /// reminder text, so the card itself reads as though the shield worked, and any instrument
    /// that treats a card mentioning its own counter as a card consuming it is told the marker is
    /// fine. Reminder text is the rulebook printed on the card; it is not the card doing
    /// anything, and the audit now strips it before asking.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_shield_counter_is_spent_instead_of_the_damage_landing()
    {
        var aegis = Card("Shield Counter Test", "Put a shield counter on target creature.");
        var bolt = Card("Shield Counter Bolt Test", "~ deals 2 damage to target creature.");

        var compiled = CardCompiler.Compile(aegis);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var bear = game.Create(
            alice, TestCards.Creature("Shield Counter Bear Test", 2, 2), Zone.Battlefield);

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, aegis), [Target.ToPermanent(bear)]);
        Settle(game);

        Assert.Equal(
            1,
            game.State.GetObject(bear).Permanent!.Counters.GetValueOrDefault(CounterKinds.Shield));

        // Two damage on a 2/2 is lethal, and the whole question is whether it arrives at all.
        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, bolt), [Target.ToPermanent(bear)]);
        Settle(game);

        Assert.Contains(bear, game.State.Battlefield);
        Assert.Equal(0, game.State.GetObject(bear).Permanent!.DamageMarked);

        // Spent, not permanent: the counter stops one thing and then it is gone.
        Assert.Equal(
            0,
            game.State.GetObject(bear).Permanent!.Counters.GetValueOrDefault(CounterKinds.Shield));

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, bolt), [Target.ToPermanent(bear)]);
        Settle(game);

        Assert.DoesNotContain(bear, game.State.Battlefield);
    }

    /// <summary>
    /// The other half of CR 122.1d: destruction is replaced as well as damage.
    /// </summary>
    /// <remarks>
    /// Asserted separately because it is a separate arm reading the same counter, and because a
    /// shield that stopped damage but not "destroy target creature" would look implemented from
    /// every angle a damage test can see. "It can't be regenerated" is destruction too, and a
    /// shield counter is not regeneration.
    /// </remarks>
    [Theory]
    [InlineData("Destroy target creature.")]
    [InlineData("Destroy target creature. It can't be regenerated.")]
    public void A_shield_counter_is_spent_instead_of_the_destruction(string printed)
    {
        var aegis = Card("Shield Destroy Aegis Test", "Put a shield counter on target creature.");
        var doom = Card(
            "Shield Destroy Test " + printed.Length.ToString(CultureInfo.InvariantCulture),
            printed);

        var compiled = CardCompiler.Compile(doom);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var bear = game.Create(
            alice, TestCards.Creature("Shielded Doomed Bear Test", 2, 2), Zone.Battlefield);

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, aegis), [Target.ToPermanent(bear)]);
        Settle(game);

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, doom), [Target.ToPermanent(bear)]);
        Settle(game);

        Assert.Contains(bear, game.State.Battlefield);
        Assert.Equal(
            0,
            game.State.GetObject(bear).Permanent!.Counters.GetValueOrDefault(CounterKinds.Shield));

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, doom), [Target.ToPermanent(bear)]);
        Settle(game);

        Assert.DoesNotContain(bear, game.State.Battlefield);
    }

    /// <summary>
    /// "Choose one or both" on a triggered ability offers the second mode as well as the first.
    /// </summary>
    /// <remarks>
    /// CR 700.2d: a range, not a count, and the compiled ability carries both ends of it. Only the
    /// lower end was ever read, so the question stopped the moment the minimum was met and the
    /// "or both" half of the sentence could not be taken at all — on a card that compiled cleanly,
    /// played without an error and put a perfectly ordinary line in the log.
    /// <para>
    /// Both rows matter. The second is what the maximum is for; the first is what stops a range
    /// from becoming a requirement, and a fix that only offered more modes would have made
    /// "choose one or both" mean "choose both".
    /// </para>
    /// </remarks>
    [Theory]
    [InlineData(true, 23, 1)]
    [InlineData(false, 23, 0)]
    public void A_modal_trigger_offers_the_whole_range_it_was_compiled_with(
        bool takeTheSecond, int expectedLife, int expectedDrawn)
    {
        var jarl = new CardDefinition
        {
            OracleId = "oracle-modal-trigger-range-test",
            Name = "Modal Range Test",
            OracleText = "When ~ enters, choose one or both —" + "\n" + "• You gain 3 life."
                + "\n" + "• Draw a card.",
            CardTypes = CardType.Creature,
            Power = 2,
            Toughness = 2,
            ManaCostRaw = "{1}{W}",
        };

        var compiled = CardCompiler.Compile(jarl);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var trigger = compiled.Triggers.Single();
        Assert.Equal(1, trigger.ModesToChoose);
        Assert.Equal(2, trigger.ModesMax);

        var (game, alice, _) = InMainPhase();
        var before = game.State.GetPlayer(alice).Hand.Count;

        game.Create(alice, jarl, Zone.Battlefield);

        // By hand rather than through Settle, which answers every choice with its first option -
        // and which option is offered at all is the whole question here.
        PassUntilAsked(game);

        var first = game.State.Choice;
        Assert.NotNull(first);
        Assert.Equal(ChoiceKind.ChooseTriggerMode, first.Kind);

        // Below the minimum there is nothing to decline: two modes and no way out of picking one.
        Assert.Equal(2, first.Options.Count);

        game.Choose(alice, [first.Options[0].Id]);
        PassUntilAsked(game);

        // Past the minimum the question comes back with the mode not yet taken and a way to stop.
        var second = game.State.Choice;
        Assert.NotNull(second);
        Assert.Equal(ChoiceKind.ChooseTriggerMode, second.Kind);
        Assert.Equal(2, second.Options.Count);

        game.Choose(alice, [second.Options[takeTheSecond ? 0 : 1].Id]);
        Settle(game);

        Assert.Equal(expectedLife, game.State.GetPlayer(alice).Life);
        Assert.Equal(before + expectedDrawn, game.State.GetPlayer(alice).Hand.Count);
    }

    /// <summary>Passes priority until a question is outstanding, or nothing is left to pass.</summary>
    private static void PassUntilAsked(Game game)
    {
        for (var guard = 0; guard < 20 && game.State.Choice is null; guard++)
        {
            if (game.State.Priority.Holder is not { } holder)
                break;

            game.PassPriority(holder);
        }
    }

