    // ---- Mana abilities ------------------------------------------------------

    [Fact]
    public void A_tap_for_mana_line_adds_that_mana()
    {
        var forest = Card("Forest Test", "{T}: Add {G}.", CardType.Land);
        var (game, alice, _) = InMainPhase();
        var land = game.Create(alice, forest, Zone.Battlefield);

        game.ActivateAbility(alice, land, "mana");

        Assert.Equal(1, game.State.GetPlayer(alice).ManaPool[ManaColor.Green]);
    }

    [Fact]
    public void A_land_that_pays_double_sits_out_the_next_untap_step()
    {
        var vault = Card(
            "Sitting Vault Test",
            "{T}: Add {C}{C}. This land doesn't untap during your next untap step.",
            CardType.Land);

        var compiled = CardCompiler.Compile(vault);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var land = game.Create(alice, vault, Zone.Battlefield);

        game.ActivateAbility(alice, land, "mana");

        // Read before anything can change step: a mana pool empties at the end of every step and
        // phase (CR 500.4), so settling first would assert against an empty one.
        Assert.Equal(2, game.State.GetPlayer(alice).ManaPool.Colorless);
        Assert.True(game.State.GetObject(land).Permanent?.SkipsNextUntap);

        // Alice's own next untap step is the one it misses, so the turn has to come back round.
        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber == 3 && game.State.CurrentStep == TurnStep.PrecombatMain);

        Assert.True(game.State.GetObject(land).Permanent?.IsTapped);
    }

    /// <summary>
    /// A mana ability whose tail cannot be read is not read at all (CR 106.6).
    /// </summary>
    /// <remarks>
    /// This asserted "Dragon spells" as its unread example for as long as a restriction could
    /// only be a card-type mask. It is read now — a tribe goes through the shared filter
    /// vocabulary and is carried to the pool — so the example moved to a clause that genuinely
    /// has no answer, and the tribe is asserted the other way beneath it.
    /// <para>
    /// The property being guarded never changed and is the reason the reader fails closed: a land
    /// that taps for unrestricted mana is a strictly better card than the one printed, and it
    /// would look complete. Widening what can be read is only safe while what cannot be read
    /// still refuses the whole line.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_mana_ability_whose_tail_cannot_be_read_is_not_read_at_all()
    {
        // "Pay cumulative upkeep costs" names a purpose the restriction vocabulary has no way to
        // say, so the whole line goes unread rather than the land keeping the mana and losing
        // what it was for.
        var hoard = Card(
            "Dragon Hoard Test",
            "{T}: Add {R}. Spend this mana only to pay cumulative upkeep costs.",
            CardType.Land);

        var compiled = CardCompiler.Compile(hoard);

        Assert.False(compiled.IsComplete);
        Assert.Empty(compiled.Activated);
        Assert.Contains(compiled.Unhandled, u => u.Contains("cumulative", StringComparison.Ordinal));

        // The tribe that used to be this test's example: read, and read with its restriction
        // intact rather than as plain red mana.
        var lair = Card(
            "Dragon Lair Test",
            "{T}: Add {R}. Spend this mana only to cast Dragon spells.",
            CardType.Land);

        var dragons = CardCompiler.Compile(lair);
        Assert.True(dragons.IsComplete, string.Join(" | ", dragons.Unhandled));

        var produced = Assert.Single(Assert.Single(dragons.Activated).Produces);
        Assert.Equal("Dragon", produced.RestrictedTo);
        Assert.NotNull(produced.Restriction);
    }

    // ---- "That player" draws (CR 603.2) --------------------------------------

    [Fact]
    public void That_player_draws_means_the_player_the_trigger_was_about()
    {
        var font = Card(
            "Shared Font Test",
            "At the beginning of each player's draw step, that player draws an additional card.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(font);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, font, Zone.Battlefield);
        Settle(game);

        var aliceHeld = game.State.GetPlayer(alice).Hand.Count;
        var bobHeld = game.State.GetPlayer(bob).Hand.Count;

        // Bob's draw step: Bob draws his card and the extra one. Alice, who controls the
        // enchantment, draws nothing - "that player" is whoever the trigger was about.
        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber == 2 && game.State.CurrentStep == TurnStep.PrecombatMain);

        Assert.Equal(bobHeld + 2, game.State.GetPlayer(bob).Hand.Count);
        Assert.Equal(aliceHeld, game.State.GetPlayer(alice).Hand.Count);
    }

    [Fact]
    public void That_player_on_an_opponents_step_is_the_opponent()
    {
        // The same phrase on a trigger that only fires on somebody else's step. It compiled
        // before "that player" had an answer at all, so compiling proves nothing here.
        var toll = Card(
            "Evening Toll Test",
            "At the beginning of each opponent's end step, that player loses 2 life.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(toll);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, toll, Zone.Battlefield);
        Settle(game);

        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber == 2 && game.State.CurrentStep == TurnStep.PrecombatMain);

        // Through Alice's end step, which is not an opponent's, and into Bob's turn.
        Assert.Equal(20, game.State.GetPlayer(alice).Life);
        Assert.Equal(20, game.State.GetPlayer(bob).Life);

        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber == 3 && game.State.CurrentStep == TurnStep.PrecombatMain);

        // Bob's end step has now passed: Bob paid, not Alice.
        Assert.Equal(18, game.State.GetPlayer(bob).Life);
        Assert.Equal(20, game.State.GetPlayer(alice).Life);
    }

    // ---- A land arriving by its land drop, and the mana it then makes (CR 305.1) ----

    /// <summary>
    /// A shockland asks its question when it is <em>played</em>, and both answers still differ.
    /// </summary>
    /// <remarks>
    /// The shockland theory further down this file conjures the land straight onto the
    /// battlefield with <c>Game.Create</c>. That is not how a land reaches a battlefield in a
    /// game: it is played from hand as a special action (CR 305.1, 505.6b), which is a different
    /// path through the engine, and this repository has already had one whole-class bug living in
    /// exactly that gap - every "enters tapped" land arrived untapped, because the replacement
    /// was pinned to the zone a spell is in and a land drop never passes through it.
    /// <para>
    /// So the same card is played rather than conjured, and the assertion is carried one step
    /// further than the other test carries it: to the mana. Paying leaves the land upright and it
    /// taps for the colour its basic land type gives it (CR 305.6); declining taps it, and the
    /// engine refuses the tap, which is the half a test that only reads <c>IsTapped</c> never
    /// sees. Ten shocklands in the corpus ask this question, and the land soak that found them
    /// answers it 32 times a run.
    /// </para>
    /// </remarks>
    [Theory]
    [InlineData(true, 18, false)]
    [InlineData(false, 20, true)]
    public void A_shockland_played_as_a_land_drop_asks_the_same_question(
        bool pay, int expectedLife, bool expectTapped)
    {
        var shock = Card(
            "Dropped Shock Test",
            "As ~ enters, you may pay 2 life. If you don't, it enters tapped.",
            CardType.Land,
            subtypes: ["Mountain"]);

        var compiled = CardCompiler.Compile(shock);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var land = game.PlayLand(alice, TestCards.PutInHand(game, alice, shock));

        // The question is asked as it arrives, on this path too.
        var asked = game.State.Choice;
        Assert.NotNull(asked);

        var decline = asked.Options.Single(o => o.Label.Contains(
            "instead", StringComparison.OrdinalIgnoreCase));

        game.Choose(
            alice,
            [pay ? asked.Options.First(o => o.Id != decline.Id).Id : decline.Id]);

        Settle(game);

        Assert.Equal(expectedLife, game.State.GetPlayer(alice).Life);
        Assert.Equal(expectTapped, game.State.GetObject(land).Permanent!.IsTapped);

        // And the half that matters to a player: whether it makes mana this turn. The ability is
        // the intrinsic one CR 305.6 grants for the Mountain type - the card prints no mana line
        // at all - so this is the whole chain, from the land drop to the red mana.
        var mana = Assert.Single(ManaAbilitiesOf(game, land));
        Assert.Equal("{T}: Add {R}.", mana.Text);

        if (expectTapped)
        {
            Assert.Throws<InvalidOperationException>(
                () => game.ActivateAbility(alice, land, mana.Id));

            Assert.True(game.State.GetPlayer(alice).ManaPool.IsEmpty);
            return;
        }

        game.ActivateAbility(alice, land, mana.Id);
        Assert.Equal(1, game.State.GetPlayer(alice).ManaPool[ManaColor.Red]);
    }

    /// <summary>
    /// A land played from hand that enters tapped makes no mana until it has untapped.
    /// </summary>
    /// <remarks>
    /// Three facts that are only worth anything together, and which no test held together: the
    /// land drop applies the replacement, the tapped land is refused when it is asked for mana,
    /// and the untap step is what fixes that. Read apart, the middle one looks like a land that
    /// does not work - which is precisely the reading the land soak had to be built not to make,
    /// since 425 of the 826 lands it plays arrive tapped and every one of them is refused once
    /// before it produces anything.
    /// </remarks>
    [Fact]
    public void A_land_played_from_hand_that_enters_tapped_makes_mana_only_once_it_untaps()
    {
        var land = Card(
            "Dropped Tapped Test",
            "This land enters tapped.",
            CardType.Land,
            subtypes: ["Island"]);

        var compiled = CardCompiler.Compile(land);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var dropped = game.PlayLand(alice, TestCards.PutInHand(game, alice, land));
        Settle(game);

        Assert.True(game.State.GetObject(dropped).Permanent!.IsTapped);

        var mana = Assert.Single(ManaAbilitiesOf(game, dropped));
        Assert.Equal("{T}: Add {U}.", mana.Text);

        // It has the ability and cannot pay for it: the two are different questions, and only the
        // second one is about the tap (CR 602.5b).
        Assert.Throws<InvalidOperationException>(
            () => game.ActivateAbility(alice, dropped, mana.Id));

        Assert.True(game.State.GetPlayer(alice).ManaPool.IsEmpty);

        // Alice's own next turn, so her untap step has run (CR 502.1).
        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber == 3 && game.State.CurrentStep == TurnStep.PrecombatMain);

        Assert.False(game.State.GetObject(dropped).Permanent!.IsTapped);

        game.ActivateAbility(alice, dropped, mana.Id);
        Assert.Equal(1, game.State.GetPlayer(alice).ManaPool[ManaColor.Blue]);
    }

    /// <summary>
    /// A storage land asked to remove no counters is a legal activation that adds no mana.
    /// </summary>
    /// <remarks>
    /// What the land soak actually turned up. Eleven storage lands in the corpus were tapped with
    /// no counters on them, the engine accepted the activation, and no mana arrived - which reads
    /// exactly like a mana ability that does not work. It is not: "remove any number" includes
    /// none (CR 601.2b), and a payout of "one for each counter removed this way" is then nothing.
    /// <para>
    /// The theory further up this file spends one counter and three; nothing spent zero, so the
    /// one outcome that looks like a defect was the one nothing had written down. It is pinned
    /// here so the next reader of that soak's output does not have to work it out again - and so
    /// that a land which genuinely stopped producing would not be able to hide behind it.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_storage_land_asked_for_no_counters_is_activated_and_pays_out_nothing()
    {
        var land = Card(
            "Empty Storage Test",
            "{T}, Remove any number of storage counters from ~: "
                + "Add {C} for each storage counter removed this way.",
            CardType.Land);

        var compiled = CardCompiler.Compile(land);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var id = game.PlayLand(alice, TestCards.PutInHand(game, alice, land));
        Settle(game);

        Assert.Empty(game.State.GetObject(id).Permanent!.Counters);

        var mana = Assert.Single(ManaAbilitiesOf(game, id));
        game.ActivateAbility(alice, id, mana.Id);

        // Paid for, and worth nothing: the tap was spent and the pool is still empty.
        Assert.True(game.State.GetObject(id).Permanent!.IsTapped);
        Assert.True(game.State.GetPlayer(alice).ManaPool.IsEmpty);
    }

    // ---- A counter put on something the sentence names by role (CR 603.2) ----

    [Fact]
    public void A_counter_put_on_it_follows_the_target_the_sentence_chose()
    {
        // "It" used to mean the source unconditionally, so this card put its counter on itself
        // and left the creature it had just pumped alone.
        var graft = Card(
            "Grafting Rite Test",
            "When ~ enters, target creature you control gains flying until end of turn. "
                + "Put a +1/+1 counter on it.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(graft);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var first = game.Create(alice, TestCards.Creature("Rite Bear One Test", 2, 2), Zone.Battlefield);
        var second = game.Create(alice, TestCards.Creature("Rite Bear Two Test", 2, 2), Zone.Battlefield);

        var source = game.Create(alice, graft, Zone.Battlefield);
        Settle(game);

        // Whichever creature the harness targeted, the counter is on that one - and not on the
        // enchantment, which is where it used to go.
        var pumped = new[] { first, second }
            .Select(game.State.GetObject)
            .Single(o => Characteristics.Of(game.State, Pool, o).Has(KeywordAbility.Flying));

        Assert.Equal(
            1, pumped.Permanent?.Counters.GetValueOrDefault(CounterKinds.PlusOnePlusOne));

        Assert.Equal(
            0,
            game.State.GetObject(source).Permanent?.Counters
                .GetValueOrDefault(CounterKinds.PlusOnePlusOne));
    }

    [Fact]
    public void It_gets_a_bonus_follows_the_target_too()
    {
        // The same word in a different verb, and it had the same fault: "it" meant the source
        // whatever the sentence before it had done.
        var rite = Card(
            "Rousing Rite Test",
            "When ~ enters, untap target creature you control. It gets +2/+2 until end of turn.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(rite);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var first = game.Create(alice, TestCards.Creature("Roused Bear One Test", 2, 2), Zone.Battlefield);
        var second = game.Create(alice, TestCards.Creature("Roused Bear Two Test", 2, 2), Zone.Battlefield);

        game.Tap(first);
        game.Tap(second);

        game.Create(alice, rite, Zone.Battlefield);
        Settle(game);

        // Whichever one was untapped is the one that grew.
        var untapped = new[] { first, second }
            .Select(game.State.GetObject)
            .Single(o => o.Permanent?.IsTapped == false);

        var other = new[] { first, second }
            .Select(game.State.GetObject)
            .Single(o => o.Id != untapped.Id);

        Assert.Equal(4, Characteristics.PowerOf(game.State, Pool, untapped));
        Assert.Equal(2, Characteristics.PowerOf(game.State, Pool, other));
    }

    [Fact]
    public void A_counter_put_on_enchanted_creature_lands_on_the_host()
    {
        var graft = Card(
            "Grafting Aura Test",
            "Enchant creature\n"
                + "When ~ enters, put a +1/+1 counter on enchanted creature.",
            CardType.Enchantment,
            subtypes: "Aura");

        var compiled = CardCompiler.Compile(graft);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var theirs = game.Create(bob, TestCards.Creature("Grafted Bear Test", 2, 2), Zone.Battlefield);
        var mine = game.Create(alice, TestCards.Creature("Ungrafted Bear Test", 2, 2), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, graft);
        game.CastSpell(alice, card, [Target.ToPermanent(theirs)]);
        Settle(game);

        // On what the Aura is attached to - which is the opponent's creature, not the Aura and
        // not anything of Alice's.
        Assert.Equal(
            1,
            game.State.GetObject(theirs).Permanent?.Counters
                .GetValueOrDefault(CounterKinds.PlusOnePlusOne));

        Assert.Equal(
            0,
            game.State.GetObject(mine).Permanent?.Counters
                .GetValueOrDefault(CounterKinds.PlusOnePlusOne));
    }

    // ---- A token made under somebody else's control (CR 111.1) ---------------

    [Fact]
    public void Each_opponent_creates_a_token_gives_it_to_them_and_not_to_you()
    {
        var bribe = Card(
            "Hunted Bribe Test",
            "Each opponent creates a 1/1 white Soldier creature token.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(bribe);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, bribe);

        game.CastSpell(alice, card, []);
        Settle(game);

        var soldier = game.State.Battlefield.Select(game.State.GetObject)
            .Single(o => o.Card.Name == "Soldier");

        // Bob's, not Alice's - a token is created under a player's control, and which player is
        // what the sentence says rather than who cast it.
        Assert.Equal(bob, soldier.ControllerId);
        Assert.Equal(bob, soldier.OwnerId);
    }

    // ---- One "for each" tail, shared by the verbs that read a number ---------

    [Theory]
    [InlineData("Draw a card for each creature you control.")]
    [InlineData("You gain 1 life for each creature you control.")]
    [InlineData("~ deals 1 damage to any target for each creature you control.")]
    [InlineData("Mill a card for each creature you control.")]
    [InlineData("Each opponent discards a card for each creature you control.")]
    [InlineData("Put a +1/+1 counter on target creature for each creature you control.")]
    [InlineData("Create a 1/1 white Soldier creature token for each creature you control.")]
    public void Every_verb_that_reads_a_number_reads_the_for_each_tail(string text)
    {
        // Each of these was added on a different day, and each time only the verb in front of a
        // developer got the tail. The tail is one shared pattern now, so this asks all of them.
        var card = Card("For Each Test", text, CardType.Sorcery);

        var compiled = CardCompiler.Compile(card);

        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
    }

    // ---- Exiling the source as an activation cost (CR 118.3c, 400.7) --------

    [Fact]
    public void Exiling_the_source_is_paid_on_activation_and_not_on_resolution()
    {
        // Feldon's Cane's wording. The cost is what takes the artifact out of the game, so it is
        // gone the moment the ability is announced (CR 601.2h) - not when it resolves.
        var cane = Card(
            "Feldon's Reliquary Test",
            "{T}, Exile ~: Shuffle your graveyard into your library.",
            CardType.Artifact);

        var compiled = CardCompiler.Compile(cane);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var ability = Assert.Single(compiled.Activated);
        Assert.Equal(SelfCost.ExileSelf, ability.SelfCost);

        // The battlefield, not the graveyard: a permanent that exiles itself is standing on the
        // battlefield when it does it, and the graveyard sibling of this cost is a different
        // value with a different zone.
        Assert.Equal(Zone.Battlefield, ability.FunctionsFrom);

        var (game, alice, _) = InMainPhase();
        game.Create(alice, TestCards.Creature("Reliquary Bear Test", 2, 2), Zone.Graveyard);
        var source = game.Create(alice, cane, Zone.Battlefield);

        Assert.Single(game.State.GetPlayer(alice).Graveyard);

        game.ActivateAbility(alice, source, "a");

        // Paid, with the ability still on the stack and nothing resolved yet.
        Assert.NotEmpty(game.State.Stack);
        Assert.DoesNotContain(source, game.State.Battlefield);
        Assert.Single(game.State.GetPlayer(alice).Graveyard);

        var inExile = Assert.Single(
            game.State.Exile.Select(game.State.GetObject),
            o => string.Equals(o.Card.Name, cane.Name, StringComparison.Ordinal));

        // CR 400.7: what is in exile is a new object. The id that paid the cost names nothing,
        // which is exactly why nothing the ability does afterwards may look it back up.
        Assert.NotEqual(source, inExile.Id);
        Assert.False(game.State.TryGetObject(source, out _));

        Settle(game);

        Assert.Empty(game.State.GetPlayer(alice).Graveyard);
    }

    [Fact]
    public void Nobody_can_respond_to_the_exile_cost_by_sacrificing_the_permanent()
    {
        // The whole reason these are costs. Read as an effect, the exile would happen on
        // resolution, and the controller could sacrifice the artifact in reply to some removal
        // and keep the shuffle as well - two cards' worth of value out of one. Paid as a cost,
        // there is nothing left to sacrifice by the time anyone holds priority.
        var relic = Card(
            "Answered Reliquary Test",
            "{T}, Exile ~: Shuffle your graveyard into your library.\n"
                + "Sacrifice ~: You gain 2 life.",
            CardType.Artifact);

        var compiled = CardCompiler.Compile(relic);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.Equal(2, compiled.Activated.Count);

        var (game, alice, _) = InMainPhase();
        game.Create(alice, TestCards.Creature("Answered Bear Test", 2, 2), Zone.Graveyard);
        var source = game.Create(alice, relic, Zone.Battlefield);

        game.ActivateAbility(alice, source, "a");

        // Alice has priority back with her own ability on the stack, and the sacrifice outlet
        // printed on the same card is no longer hers to use: the permanent is in exile, and an
        // ability that functions from the battlefield cannot be activated from there (CR 602.5).
        var refused = Assert.Throws<InvalidOperationException>(
            () => game.ActivateAbility(alice, source, "a1"));

        Assert.Contains("No object", refused.Message, StringComparison.Ordinal);

        Settle(game);

        // The shuffle happened and no life was gained: the response was never available.
        Assert.Empty(game.State.GetPlayer(alice).Graveyard);
        Assert.Equal(20, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void The_ability_is_refused_a_second_time_because_the_cost_cannot_be_paid_twice()
    {
        // Fail closed: a cost the engine cannot charge leaves the ability unusable rather than
        // free. Once the permanent has exiled itself there is no second payment to make, and the
        // engine refuses the activation instead of running the effect for nothing.
        var cane = Card(
            "Spent Reliquary Test",
            "{T}, Exile ~: Shuffle your graveyard into your library.",
            CardType.Artifact);

        var (game, alice, _) = InMainPhase();
        game.Create(alice, TestCards.Creature("Spent Bear Test", 2, 2), Zone.Graveyard);
        var source = game.Create(alice, cane, Zone.Battlefield);

        game.ActivateAbility(alice, source, "a");
        Settle(game);

        Assert.Throws<InvalidOperationException>(() => game.ActivateAbility(alice, source, "a"));

        // And nothing ran the second time: one shuffle, one exile, one card in exile.
        Assert.Single(
            game.State.Exile.Select(game.State.GetObject),
            o => string.Equals(o.Card.Name, cane.Name, StringComparison.Ordinal));
    }

    [Fact]
    public void An_ability_paid_by_exiling_the_source_still_exiles_what_it_targeted()
    {
        // Hanged Executioner's shape with the mana taken off. Two objects end up in exile and
        // they are different ones: the source went there as the cost, the creature as the
        // effect. A pronoun that had followed the vanished source would exile it twice and leave
        // the creature alone.
        var warden = Card(
            "Vanishing Warden Test",
            "Exile ~: Exile target creature.",
            CardType.Artifact);

        var compiled = CardCompiler.Compile(warden);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.Equal(SelfCost.ExileSelf, Assert.Single(compiled.Activated).SelfCost);

        var (game, alice, bob) = InMainPhase();
        var bear = game.Create(bob, TestCards.Creature("Warded Bear Test", 2, 2), Zone.Battlefield);
        var source = game.Create(alice, warden, Zone.Battlefield);

        game.ActivateAbility(alice, source, "a", [Target.ToPermanent(bear)]);

        // The cost first, with the creature still on the battlefield and the ability unresolved.
        Assert.DoesNotContain(source, game.State.Battlefield);
        Assert.Contains(bear, game.State.Battlefield);

        Settle(game);

        var exiled = game.State.Exile.Select(game.State.GetObject).ToList();
        Assert.Contains(exiled, o => string.Equals(o.Card.Name, "Vanishing Warden Test", StringComparison.Ordinal));
        Assert.Contains(exiled, o => string.Equals(o.Card.Name, "Warded Bear Test", StringComparison.Ordinal));
        Assert.DoesNotContain(bear, game.State.Battlefield);
    }

    [Fact]
    public void Exiling_the_card_from_the_graveyard_is_still_the_graveyard_cost()
    {
        // The two costs are the same words with a zone on the end, and the battlefield reader
        // must not lift "Exile ~" out of the middle of the graveyard one - which would leave
        // "from your graveyard" behind as a cost item nothing can charge and refuse eighty lines
        // that already work.
        var scavenger = Card(
            "Graveyard Scavenger Test",
            "{5}, Exile ~ from your graveyard: You gain 5 life.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var compiled = CardCompiler.Compile(scavenger);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var ability = Assert.Single(compiled.Activated);
        Assert.Equal(SelfCost.ExileSelfFromGraveyard, ability.SelfCost);
        Assert.Equal(Zone.Graveyard, ability.FunctionsFrom);
    }

    [Fact]
    public void Exiling_the_card_from_hand_as_a_cost_is_left_unread()
    {
        // The Spirit Guides. The zone phrase is deliberately not swallowed: there is no self
        // cost that charges a card out of hand by exiling it, so the remainder fails to parse as
        // mana and the whole line stays unread. Granting the ability anyway would hand a player
        // a free red mana with nothing paid for it - the exact fail-open this compiler refuses.
        var guide = Card(
            "Spirit Guide Test",
            "Exile ~ from your hand: Add {R}.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var compiled = CardCompiler.Compile(guide);

        Assert.False(compiled.IsComplete);
        Assert.Contains("Exile ~ from your hand: Add {R}.", compiled.Unhandled);
        Assert.Empty(compiled.Activated);
    }

    [Theory]
    [InlineData("Reliquary Cane Test", "{T}, Exile ~: Shuffle your graveyard into your library.")]
    [InlineData("Reliquary Archive Test", "{2}, Exile ~: Target player shuffles their graveyard into their library. Draw a card.")]
    [InlineData("Reliquary Foundry Test", "{1}, {T}, Exile ~: Target player shuffles their graveyard into their library.")]
    [InlineData("Reliquary Effigy Test", "{4}, {T}, Exile ~: Exile target creature.")]
    [InlineData("Reliquary Amulet Test", "{5}, {T}, Exile ~: Exile target artifact, creature, or land. Activate only as a sorcery.")]
    [InlineData("Reliquary Vault Test", "{5}, {T}, Exile ~: Exile all nonland permanents.")]
    [InlineData("Reliquary Floor Test", "{2}, {T}, Exile ~: Exile all untapped creatures. Activate only as a sorcery.")]
    public void Every_printed_shape_of_the_exile_self_cost_reads(string name, string text)
    {
        // The real wordings from the cards this unblocked, each with the cost items in the order
        // they are printed: alone, after mana, and between mana and a tap symbol.
        var card = Card(name, text, CardType.Artifact);

        var compiled = CardCompiler.Compile(card);

        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.Contains(compiled.Activated, a => a.SelfCost == SelfCost.ExileSelf);
    }

    // ---- Counting a life change or a burn (CR 118.3, 119.3) ------------------

    [Fact]
    public void Damage_counted_off_the_board_scales_with_it()
    {
        var volley = Card(
            "Counted Volley Test",
            "~ deals 1 damage to any target for each creature you control.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(volley);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, TestCards.Creature("Volley Bear One Test", 2, 2), Zone.Battlefield);
        game.Create(alice, TestCards.Creature("Volley Bear Two Test", 2, 2), Zone.Battlefield);
        game.Create(alice, TestCards.Creature("Volley Bear Three Test", 2, 2), Zone.Battlefield);
        game.Create(bob, TestCards.Creature("Volley Enemy Bear Test", 2, 2), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, volley);
