    // ---- Counting a life change (CR 118.3) -----------------------------------

    [Fact]
    public void Life_counted_off_the_board_is_asked_of_whoever_the_sentence_names()
    {
        var tithe = Card(
            "Blood Tithe Test",
            "Each opponent loses 1 life for each creature you control.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(tithe);
