        game.Create(alice, TestCards.Creature("Tithe Bear Two Test", 2, 2), Zone.Battlefield);

        // Bob's creature is not one Alice controls, so it is not counted.
        game.Create(bob, TestCards.Creature("Tithe Enemy Bear Test", 2, 2), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, tithe);
