    // ---- Discarding a whole hand (CR 701.8a) ---------------------------------

    [Fact]
    public void Each_player_discards_their_own_hand_however_big_it_is()
    {
        var reckoning = Card(
            "Reckoning Test",
            "Each player discards their hand.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(reckoning);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();

        // Different sized hands, so a single number worked out by the compiler could not be
        // right for both.
        TestCards.PutInHand(game, alice, TestCards.Creature("Reckoned One Test", 1, 1));
        TestCards.PutInHand(game, alice, TestCards.Creature("Reckoned Two Test", 1, 1));
        TestCards.PutInHand(game, bob, TestCards.Creature("Reckoned Three Test", 1, 1));

        Assert.NotEqual(
            game.State.GetPlayer(alice).Hand.Count,
            game.State.GetPlayer(bob).Hand.Count);

