        Assert.Empty(game.State.GetPlayer(bob).Hand);
    }

    // ---- A permanent's timing permission (CR 702.8b) --------------------------

    /// <summary>
    /// A permanent holding the window open, and a spell it does not name shut out of it.
    /// </summary>
    /// <remarks>
    /// The whole family in one game, because the two halves only mean anything together. Yeva
    /// says "creature spells", so the creature is castable in a step that is not a main phase on
    /// a turn that is not Alice's — and the sorcery beside it in the same hand, at that same
    /// moment, is not. A permission read one word wider than the card is printed would pass the
    /// first assertion and fail nothing.
    /// </remarks>
    [Fact]
    public void A_permanents_flash_permission_covers_the_spells_it_names_and_no_others()
    {
        var herald = Card(
            "Flash Herald Test",
            "You may cast creature spells as though they had flash.",
            CardType.Creature,
            2,
            2);

        var compiled = CardCompiler.Compile(herald);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, herald, Zone.Battlefield);

        // Bob's turn, with Alice holding priority: no main phase of hers, and nothing about this
        // moment lets a sorcery-speed spell be cast.
        //
        // The two cards are put in hand after the turn has turned over, not before. A card held
        // across a cleanup step is discarded to hand size and comes back as a different object
        // (CR 400.7, 514.1), and the id this test is holding would name nothing.
        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber == 2
                && game.State.ActivePlayerId == bob
                && game.State.CurrentStep == TurnStep.PrecombatMain
                && game.State.Priority.Holder == alice);

        var bear = TestCards.PutInHand(
            game, alice, TestCards.Creature("Flashed Bear Test", 2, 2));

        var ritual = TestCards.PutInHand(
            game,
            alice,
            Card("Flash Ritual Test", "You gain 2 life.", CardType.Sorcery));

        Assert.False(game.State.IsSorcerySpeedFor(alice));

        // The sorcery first, so the refusal cannot be blamed on the stack the creature leaves
        // behind.
        var refused = Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, ritual, []));

        Assert.Contains("505.6a", refused.Message, StringComparison.Ordinal);

        var onStack = game.CastSpell(alice, bear, []);
        Assert.Equal(Zone.Stack, game.State.GetObject(onStack).Zone);
    }

    /// <summary>
    /// The window closes with the permanent, because nothing anywhere recorded that it was open.
    /// </summary>
    /// <remarks>
    /// CR 611.2c. This is what a timing permission compiled as a keyword grant on the card in
    /// hand would have got wrong in the other direction — the grant would be recomputed too, but
    /// the card would carry flash onto the stack and onto the battlefield, where the printed
    /// permission says nothing at all. Asked here as the one consequence a player can see.
    /// </remarks>
    [Fact]
    public void A_flash_permission_ends_when_the_permanent_granting_it_leaves()
    {
        var orrery = Card(
            "Flash Orrery Test",
            "You may cast spells as though they had flash.",
            CardType.Artifact);

        var compiled = CardCompiler.Compile(orrery);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var host = game.Create(alice, orrery, Zone.Battlefield);

        // Drawn after the turn has turned over, because a card held across a cleanup step is
        // discarded to hand size and comes back as a different object (CR 400.7, 514.1).
        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber == 2
                && game.State.ActivePlayerId == bob
                && game.State.CurrentStep == TurnStep.PrecombatMain
                && game.State.Priority.Holder == alice);

        var first = TestCards.PutInHand(
            game, alice, Card("Flash Rite One Test", "You gain 2 life.", CardType.Sorcery));

        var second = TestCards.PutInHand(
            game, alice, Card("Flash Rite Two Test", "You gain 2 life.", CardType.Sorcery));

        game.CastSpell(alice, first, []);
        Settle(game);

        // The permanent goes, and with it the permission - there is no state to sweep, which is
        // the point.
        game.Move(host, Zone.Graveyard, MoveCause.Destroy, alice);
        Settle(game);

        TestCards.PassUntil(
            game,
            () => game.State.ActivePlayerId == bob
                && game.State.CurrentStep == TurnStep.End
                && game.State.Priority.Holder == alice);

        var refused = Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, second, []));

        Assert.Contains("505.6a", refused.Message, StringComparison.Ordinal);
    }

    /// <summary>
    /// "Any player may cast Sliver spells as though they had flash" hands the window to the table.
    /// </summary>
    /// <remarks>
    /// Quick Sliver's subject is the one printing with no scope at all, and the difference from
    /// "You may cast" is the whole card. Both readings are asked in one game so that a scope
    /// silently defaulted to the controller would fail here rather than pass everywhere.
    /// </remarks>
    [Fact]
    public void An_any_player_permission_reaches_an_opponent_and_a_you_permission_does_not()
    {
        var shared = Card(
            "Shared Flash Sliver Test",
            "Any player may cast Sliver spells as though they had flash.",
            CardType.Creature,
            2,
            2,
            subtypes: "Sliver");

        var mine = Card(
            "Private Flash Beacon Test",
            "You may cast Goblin spells as though they had flash.",
            CardType.Enchantment);

        Assert.True(CardCompiler.Compile(shared).IsComplete);
        Assert.True(CardCompiler.Compile(mine).IsComplete);

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, shared, Zone.Battlefield);
        game.Create(alice, mine, Zone.Battlefield);

        var sliver = TestCards.PutInHand(
            game,
            bob,
            Card("Flashed Sliver Test", string.Empty, CardType.Creature, 1, 1, subtypes: "Sliver"));

        var goblin = TestCards.PutInHand(
            game,
            bob,
            Card("Flashed Goblin Test", string.Empty, CardType.Creature, 1, 1, subtypes: "Goblin"));

        // Alice's turn, Bob holding priority: an opponent of whoever controls both permanents.
        game.PassPriority(alice);
        Assert.Equal(bob, game.State.Priority.Holder);
        Assert.False(game.State.IsSorcerySpeedFor(bob));

        // The Goblin is named by a permission Alice is holding for herself, so Bob is not in it.
        var refused = Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(bob, goblin, []));

        Assert.Contains("505.6a", refused.Message, StringComparison.Ordinal);

        var onStack = game.CastSpell(bob, sliver, []);
        Assert.Equal(Zone.Stack, game.State.GetObject(onStack).Zone);
    }

    /// <summary>The window belongs to whoever controls the permanent now (CR 613.1b).</summary>
    /// <remarks>
    /// Control is layer 2, so "you" in "you may cast creature spells as though they had flash" is
    /// not the id the object was created with. Read from the stored controller instead, a stolen
    /// Yeva would go on lending its window to the player it was taken from and give the thief
    /// nothing - which is the engine's most-repeated bug wearing a new hat.
    /// </remarks>
    [Fact]
    public void A_stolen_permanent_lends_its_flash_permission_to_the_thief()
    {
        var herald = Card(
            "Stolen Flash Herald Test",
            "You may cast creature spells as though they had flash.",
            CardType.Creature,
            2,
            2);

        var threaten = Card(
            "Flash Threaten Test",
            "Gain control of target creature until end of turn. Untap that creature. "
                + "It gains haste until end of turn.");

        Assert.True(CardCompiler.Compile(herald).IsComplete);
        Assert.True(CardCompiler.Compile(threaten).IsComplete);

        var (game, alice, bob) = InMainPhase();
        var host = game.Create(alice, herald, Zone.Battlefield);

        // Bob's turn, and he takes it in his own main phase. Every card here is drawn after the
        // turn has turned over: one held across a cleanup step is discarded to hand size and
        // comes back as a different object (CR 400.7, 514.1).
        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber == 2
                && game.State.ActivePlayerId == bob
                && game.State.CurrentStep == TurnStep.PrecombatMain
                && game.State.Priority.Holder == bob);

        var hers = TestCards.PutInHand(
            game, alice, TestCards.Creature("Alice Bear Test", 2, 2));

        var his = TestCards.PutInHand(
            game, bob, TestCards.Creature("Bob Bear Test", 2, 2));

        var steal = TestCards.PutInHand(game, bob, threaten);

        game.CastSpell(bob, steal, [Target.ToPermanent(host)]);
        Settle(game);

        Assert.Equal(
            bob, Characteristics.ControllerOf(game.State, Pool, game.State.GetObject(host)));

        // His end step: not a main phase for anybody, so only the permission can allow a cast.
        TestCards.PassUntil(
            game,
            () => game.State.CurrentStep == TurnStep.End
                && game.State.Priority.Holder == bob);

        var onStack = game.CastSpell(bob, his, []);
        Assert.Equal(Zone.Stack, game.State.GetObject(onStack).Zone);

        // And Alice, who owns the creature and no longer controls it, has lost the window.
        game.PassPriority(bob);
        Assert.Equal(alice, game.State.Priority.Holder);

        var refused = Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, hers, []));

        Assert.Contains("505.6a", refused.Message, StringComparison.Ordinal);
    }

    /// <summary>
    /// The near-misses this reader has to refuse, and the reason each one is a refusal.
    /// </summary>
    /// <remarks>
    /// A timing permission read too widely is a strictly better card than the printed one, and
    /// the coverage number scores it as a win — so the refusals need a test of their own or
    /// nothing is watching them. Each line here is real printed wording that shares most of its
    /// words with the family above and means something else:
    /// <list type="bullet">
    /// <item>Rootwater Shaman qualifies the spells <em>after</em> the noun. Read as "Aura
    /// spells" it would hand instant speed to every Aura in the deck.</item>
    /// <item>Alchemist's Refuge and Borne Upon a Wind name a window that lasts a turn, and
    /// Quicksilver one that lasts while a permanent is tapped. A window this cannot read must
    /// not become a permanent permission - that refusal is the one that kept fifteen free-cast
    /// cards honest a round ago, and it is the same refusal here.</item>
    /// <item>Illusion Spinners is the singular self-permission with a condition on it: a static
    /// ability of a card in a hand, which is a different mechanism. Read here it would grant the
    /// permission and quietly drop the condition.</item>
    /// </list>
    /// </remarks>
    [Theory]
    [InlineData("You may cast Aura spells with enchant creature as though they had flash.")]
    [InlineData("You may cast spells this turn as though they had flash.")]
    [InlineData("You may cast creature spells this turn as though they had flash.")]
    [InlineData("During each opponent's end step, you may cast spells as though they had flash.")]
    [InlineData("As long as Quicksilver is tapped, you may cast spells as though they had flash.")]
    [InlineData("You may cast this spell as though it had flash if you control a Faerie.")]
    [InlineData("You may cast the first creature spell you cast each turn as though it had flash.")]
    public void A_flash_permission_this_reader_cannot_name_is_left_unread(string line)
    {
        var card = Card("Unread Flash Test", line, CardType.Enchantment);

        var compiled = CardCompiler.Compile(card);

        // The line comes back with the card's own name folded to "~", so the assertion is that
        // one line went unread and nothing was granted - not that the string round-tripped.
        Assert.Single(compiled.Unhandled);
        Assert.Empty(compiled.FlashPermissions);
    }

    /// <summary>
    /// The permission grants timing and nothing else — not a zone, and not a price.
    /// </summary>
    /// <remarks>
    /// The line that separates this family from the free-cast one it was decomposed out of. A
    /// Leyline of Anticipation does not let its controller cast the card in their graveyard;
    /// every question but the timing one is settled elsewhere in <c>Game.CastSpell</c> without
    /// consulting the permission at all. Asserted rather than assumed, because "as though it had
    /// flash" sits one clause away from "without paying its mana cost" on several of the cards
    /// this round measured.
    /// </remarks>
    [Fact]
    public void A_flash_permission_does_not_open_a_zone()
    {
        var orrery = Card(
            "Zone Flash Orrery Test",
            "You may cast spells as though they had flash.",
            CardType.Artifact);

        var (game, alice, _) = InMainPhase();
        game.Create(alice, orrery, Zone.Battlefield);

        var buried = game.Create(
            alice, TestCards.Creature("Buried Bear Test", 2, 2), Zone.Graveyard);

        var refused = Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, buried, []));

        Assert.Contains("A spell is cast from hand", refused.Message, StringComparison.Ordinal);
    }

    // ---- An Aura on a player keeps that player's clock (CR 303.4) ------------

    [Fact]
    public void An_aura_on_a_player_fires_on_that_players_upkeep_and_not_its_controllers()
    {
        var curse = Card(
            "Player Curse Test",
            "Enchant player\n"
                + "At the beginning of enchanted player's upkeep, you gain 2 life.",
            CardType.Enchantment,
            subtypes: "Aura");

        var compiled = CardCompiler.Compile(curse);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();

        var card = TestCards.PutInHand(game, alice, curse);
        game.CastSpell(alice, card, [Target.ToPlayer(bob)]);
        Settle(game);

        var before = game.State.GetPlayer(alice).Life;

        // Bob's upkeep, not Alice's: the Aura's clock runs on whoever it is on, and the two are
        // different players — which is the whole reason these cards are played.
        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber == 2 && game.State.CurrentStep == TurnStep.PrecombatMain);

        Assert.Equal(before + 2, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void An_aura_on_a_player_who_has_left_the_game_goes_to_the_graveyard()
    {
        // CR 704.5m: an Aura attached to an illegal player is put into its owner's graveyard, and
        // a player who has lost is no longer a player in the game (CR 800.4a). Only reachable at
        // three seats or more - at two, the game ends with the player, and nothing that happens
        // to the Aura afterwards can be seen.
        var curse = Card(
            "Departing Curse Test",
            "Enchant player\n"
                + "At the beginning of enchanted player's upkeep, you gain 2 life.",
            CardType.Enchantment,
            subtypes: "Aura");

        var compiled = CardCompiler.Compile(curse);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, seats) = FourPlayers();

        var card = TestCards.PutInHand(game, seats[0], curse);
        game.CastSpell(seats[0], card, [Target.ToPlayer(seats[1])]);
        Settle(game);

        var aura = Assert.Single(game.State.Battlefield);

        // The enchanted seat is knocked out, and the other three play on.
        var gun = game.Create(seats[0], TestCards.Creature("Departing Gun Test", 1, 1), Zone.Battlefield);
        game.MarkDamageToPlayer(seats[1], gun, 20);
        Settle(game);

        Assert.True(game.State.GetPlayer(seats[1]).HasLost);
        Assert.False(game.State.IsOver);

        Assert.DoesNotContain(aura, game.State.Battlefield);
        Assert.Contains(
            game.State.GetPlayer(seats[0]).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Departing Curse Test");
    }

    // ---- What kind of spell a cast trigger names (CR 603.2) ------------------

    [Fact]
    public void A_cast_trigger_naming_a_subtype_fires_only_for_that_subtype()
    {
        var chief = Card(
            "Goblin Chief Test",
            "Whenever you cast a Goblin spell, you gain 2 life.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(chief);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        game.Create(alice, chief, Zone.Battlefield);

        var goblin = Card("Cast Goblin Test", string.Empty, CardType.Creature, 1, 1, subtypes: "Goblin");
        var elf = Card("Cast Elf Test", string.Empty, CardType.Creature, 1, 1, subtypes: "Elf");

        var first = TestCards.PutInHand(game, alice, elf);
        game.CastSpell(alice, first, []);
        Settle(game);
        TestCards.PassUntil(game, () => game.State.Priority.Holder == alice, guard: 50);

        // Before this could tell a subtype from a card type, an unrecognised word meant "every
        // spell" and the Elf would have paid out too.
        Assert.Equal(20, game.State.GetPlayer(alice).Life);

        var second = TestCards.PutInHand(game, alice, goblin);
        game.CastSpell(alice, second, []);
        Settle(game);
        TestCards.PassUntil(game, () => game.State.Priority.Holder == alice, guard: 50);

        Assert.Equal(22, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void A_cast_trigger_naming_a_word_the_engine_does_not_know_is_left_unread()
    {
        // The failure this guards: an unknown word left no filter at all, and no filter means
        // every spell - a trigger that fires on everything is a strictly better card than the
        // one printed.
        var odd = Card(
            "Playtest Watcher Test",
            "Whenever you cast a playtest spell, you gain 2 life.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(odd);

        Assert.False(compiled.IsComplete);
        Assert.Contains(compiled.Unhandled, u => u.Contains("playtest", StringComparison.Ordinal));
    }

    // ---- Where a spell was cast from (CR 601.2) ------------------------------

    [Fact]
    public void A_trigger_about_where_a_spell_came_from_can_tell_the_zones_apart()
    {
        var watcher = Card(
            "Recursion Watcher Test",
            "Whenever you cast a spell from anywhere other than your hand, you gain 2 life.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(watcher);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        // The same card, castable from the graveyard as well as from hand.
        var bolt = new CardDefinition
        {
            OracleId = "oracle-zone-bolt",
            Name = "Zone Bolt Test",
            OracleText = "~ deals 1 damage to any target.\nFlashback {R}",
            CardTypes = CardType.Instant,
            ManaCostRaw = "{R}",
            Cmc = 1,
        };

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, watcher, Zone.Battlefield);

        var first = game.Create(alice, TestCards.BasicLand("Mountain"), Zone.Battlefield);
        // The same definition twice: a basic land's mana ability comes from its subtype, so a
        // differently named "Mountain" would not have one.
        var second = game.Create(alice, TestCards.BasicLand("Mountain"), Zone.Battlefield);

        // From hand: no trigger.
        var inHand = TestCards.PutInHand(game, alice, bolt);
        game.ActivateAbility(alice, first, "mana");
        game.CastSpell(alice, inHand, [Target.ToPlayer(bob)]);
        Settle(game);

        Assert.Equal(20, game.State.GetPlayer(alice).Life);

        // The same spell, now cast from the graveyard by flashback: the trigger fires.
        var inYard = game.State.GetPlayer(alice).Graveyard
            .Select(game.State.GetObject)
            .Single(o => o.Card.Name == "Zone Bolt Test");

        game.ActivateAbility(alice, second, "mana");
        game.CastSpell(alice, inYard.Id, [Target.ToPlayer(bob)]);
        Settle(game);

        Assert.Equal(22, game.State.GetPlayer(alice).Life);
    }

    // ---- "The basic land type of your choice" (CR 305.6, 305.7) --------------

    [Fact]
    public void A_land_told_to_become_a_chosen_basic_type_taps_for_the_type_that_was_named()
    {
        // Reef Shaman, and the shape twelve corpus cards print. The named form of this sentence
        // - "target land becomes an Island until end of turn" - has read for a round; what was
        // missing was the question, so the type is a player's answer rather than a word the
        // compiler could write down.
        //
        // Both halves are asserted because only one of them is the interesting one. That the land
        // taps for blue says the retyping happened; that it no longer taps for green says CR
        // 305.7 ran - the land's old land types went with it, and with them the intrinsic ability
        // CR 305.6 hung on the type it used to have.
        var shaper = Card(
            "Chosen Type Shaper Test",
            "{T}: Target land becomes the basic land type of your choice until end of turn.",
            CardType.Creature,
            1,
            1,

            // Haste only so the ability can be used the turn it arrives (CR 302.6).
            KeywordAbility.Haste);

        var compiled = CardCompiler.Compile(shaper);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var merfolk = game.Create(alice, shaper, Zone.Battlefield);
        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);

        // Before: a Forest, and one mana ability, and it is green.
        var printed = Assert.Single(ManaAbilitiesOf(game, forest));
        Assert.Equal("{T}: Add {G}.", printed.Text);

        game.ActivateAbility(alice, merfolk, "a", [Target.ToPermanent(forest)]);
        TestCards.PassUntil(
            game, () => game.State.Choice is { Kind: ChoiceKind.ChooseBasicLandType });

        // The offer is the five CR 305.6 names, and it does not depend on what is in play: this
        // board has no Island on it anywhere.
        var asked = game.State.Choice!;
        Assert.Equal(alice, asked.PlayerId);
        Assert.Equal(
            new[] { "Plains", "Island", "Swamp", "Mountain", "Forest" },
            asked.Options.Select(o => o.Id));

        game.Choose(asked.PlayerId, ["Island"]);
        Settle(game);

        // The land the player named, and nothing of what it was: one ability, and it is blue.
        var island = Assert.Single(ManaAbilitiesOf(game, forest));
        Assert.Equal("{T}: Add {U}.", island.Text);

        game.ActivateAbility(alice, forest, island.Id);
        Assert.Equal(1, game.State.GetPlayer(alice).ManaPool[ManaColor.Blue]);
        Assert.Equal(0, game.State.GetPlayer(alice).ManaPool[ManaColor.Green]);

        // And the duration is real. The answer builds an effect stamped with the turn number, so
        // it comes off in the cleanup step (CR 514.2) and the land is a Forest again - which is
        // why the compiler refuses this sentence when the card prints no duration at all.
        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber == 3 && game.State.CurrentStep == TurnStep.PrecombatMain);

        var back = Assert.Single(ManaAbilitiesOf(game, forest));
        Assert.Equal("{T}: Add {G}.", back.Text);
        game.ActivateAbility(alice, forest, back.Id);
        Assert.Equal(1, game.State.GetPlayer(alice).ManaPool[ManaColor.Green]);
    }

    [Fact]
    public void A_land_that_gains_a_chosen_basic_type_keeps_the_mana_it_had()
    {
        // Navigator's Compass - the same question with CR 305.7's other half behind it. "In
        // addition to its other types" keeps the land's own types and its rules text, so this
        // land taps for two colours; read as the replacement above it would tap for one, and the
        // card would be strictly worse than printed on every board.
        var compass = Card(
            "Chosen Type Compass Test",
            "{T}: Until end of turn, target land you control becomes the basic land type of "
                + "your choice in addition to its other types.",
            CardType.Artifact);

        var compiled = CardCompiler.Compile(compass);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var tool = game.Create(alice, compass, Zone.Battlefield);
        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);

        game.ActivateAbility(alice, tool, "a", [Target.ToPermanent(forest)]);
        TestCards.PassUntil(
            game, () => game.State.Choice is { Kind: ChoiceKind.ChooseBasicLandType });

        game.Choose(game.State.Choice!.PlayerId, ["Swamp"]);
        Settle(game);

        var texts = ManaAbilitiesOf(game, forest).Select(a => a.Text).ToList();
        Assert.Contains("{T}: Add {G}.", texts, StringComparer.Ordinal);
        Assert.Contains("{T}: Add {B}.", texts, StringComparer.Ordinal);

        // Two abilities and one land: the ids have to differ or an activation by id resolves
        // whichever came first (CR 305.6 grants one ability per type).
        var ids = ManaAbilitiesOf(game, forest).Select(a => a.Id).ToList();
        Assert.Equal(ids.Count, ids.Distinct(StringComparer.Ordinal).Count());

        var black = ManaAbilitiesOf(game, forest).Single(a => a.Text == "{T}: Add {B}.");
        game.ActivateAbility(alice, forest, black.Id);
        Assert.Equal(1, game.State.GetPlayer(alice).ManaPool[ManaColor.Black]);
    }

    [Fact]
    public void The_chosen_land_type_sentence_without_a_duration_is_left_unread()
    {
        // Thelonite Monk's half of the family, and the refusal is deliberate. What the answer
        // builds is an effect that ends in the cleanup step, so a sentence printed without a
        // duration would compile into a card that quietly undoes itself - and would count as
        // read while doing it. An indefinite retyping wants a duration this engine does not have,
        // not a looser pattern here.
        var monk = Card(
            "Undated Retype Test",
            "{T}: Target land becomes the basic land type of your choice.",
            CardType.Creature,
            1,
            1);

        var compiled = CardCompiler.Compile(monk);

        Assert.False(compiled.IsComplete);
        Assert.Contains(
            compiled.Unhandled,
            u => u.Contains("basic land type of your choice", StringComparison.Ordinal));
    }

    // ---- "Deals combat damage" with no recipient (CR 510.2) ------------------

    [Fact]
    public void Combat_damage_to_a_creature_counts_when_no_recipient_is_named()
    {
        var drum = Card(
            "War Drum Test",
            "Whenever a creature you control deals combat damage, you gain 2 life.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(drum);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, drum, Zone.Battlefield);
        var attacker = game.Create(alice, TestCards.Creature("Drum Attacker Test", 2, 2), Zone.Battlefield);
        var blocker = game.Create(bob, TestCards.Creature("Drum Blocker Test", 1, 4), Zone.Battlefield);

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);
        game.DeclareBlockers(
            bob,
            new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [attacker] = [blocker] });

        var before = game.State.GetPlayer(alice).Life;

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Settle(game);

        // Blocked, so no damage reached Bob - the whole two went to the blocker, and that is
        // still combat damage.
        Assert.Equal(20, game.State.GetPlayer(bob).Life);
        Assert.Equal(before + 2, game.State.GetPlayer(alice).Life);
    }

    // ---- A group trigger about blocking (CR 509.1h) --------------------------

    [Fact]
    public void A_group_becomes_blocked_trigger_needs_an_actual_blocker()
    {
        var horn = Card(
            "Warning Horn Test",
            "Whenever a creature you control becomes blocked, you gain 2 life.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(horn);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, horn, Zone.Battlefield);
        var attacker = game.Create(alice, TestCards.Creature("Horn Attacker Test", 2, 2), Zone.Battlefield);
        var blocker = game.Create(bob, TestCards.Creature("Horn Blocker Test", 2, 2), Zone.Battlefield);

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);

        var before = game.State.GetPlayer(alice).Life;

        game.DeclareBlockers(
            bob,
            new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [attacker] = [blocker] });

        Settle(game);

        // CR 509.1h: an attacker becomes blocked when a creature is declared as blocking it.
