    /// <summary>
    /// "Sacrifice this creature unless you pay {1} for each other creature you control."
    /// </summary>
    /// <remarks>
    /// The fourth payer word. "You" redirects nothing — the offer goes where an offer goes when
    /// nobody says otherwise, which is the controller of the ability making it — but it still has
    /// to be said out loud, because the reader's target arm would otherwise claim the sentence
    /// and charge whoever the consequence was aimed at.
    /// <para>
    /// Two other creatures make the upkeep cost {2}. A price read as the printed {1} would keep
    /// the creature alive off a single land, which is the direction this may not be wrong in.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_counted_upkeep_charged_to_you_is_paid_and_the_creature_survives()
    {
        var spirit = Card(
            "Counted Upkeep Test",
            "At the beginning of your upkeep, sacrifice ~ unless you pay {1} for each other "
                + "creature you control.",
            CardType.Creature,
            power: 3,
            toughness: 3);

        var compiled = CardCompiler.Compile(spirit);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var ghost = game.Create(alice, spirit, Zone.Battlefield);

        game.Create(alice, TestCards.Creature("Counted Upkeep Friend One", 1, 1), Zone.Battlefield);
        game.Create(alice, TestCards.Creature("Counted Upkeep Friend Two", 1, 1), Zone.Battlefield);

        PassTo(game, 3, TurnStep.Upkeep);

        foreach (var _ in Enumerable.Range(0, 2))
        {
            var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
            game.ActivateAbility(alice, forest, "mana");
        }

        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.OptionalPayment });

        // Asked of Alice — the ability's own controller — and priced at the two other creatures.
        Assert.Equal(alice, game.State.Choice!.PlayerId);
        Assert.Equal("{2}", game.Log.OfType<OptionalPaymentRequested>().Last().CostText);

        game.Choose(alice, ["yes"]);
        Settle(game);

        Assert.Contains(ghost, game.State.Battlefield);
    }

    /// <summary>The same upkeep one mana short: the creature is sacrificed.</summary>
    [Fact]
    public void A_counted_upkeep_one_mana_short_takes_the_creature()
    {
        var spirit = Card(
            "Short Upkeep Test",
            "At the beginning of your upkeep, sacrifice ~ unless you pay {1} for each other "
                + "creature you control.",
            CardType.Creature,
            power: 3,
            toughness: 3);

        var (game, alice, _) = InMainPhase();
        var ghost = game.Create(alice, spirit, Zone.Battlefield);

        game.Create(alice, TestCards.Creature("Short Upkeep Friend One", 1, 1), Zone.Battlefield);
        game.Create(alice, TestCards.Creature("Short Upkeep Friend Two", 1, 1), Zone.Battlefield);

        PassTo(game, 3, TurnStep.Upkeep);

        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, forest, "mana");

        Settle(game);

        Assert.DoesNotContain(ghost, game.State.Battlefield);
        Assert.Contains(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Short Upkeep Test");
    }

    /// <summary>
    /// A count the shared vocabulary cannot read leaves the line unread, not priced at nought.
    /// </summary>
    /// <remarks>
    /// The whole reason the computation is refused at compile time rather than answered with
    /// zero on the board. A price that comes to nothing is a ward nobody pays and a counterspell
    /// that counters nobody, and it compiles as a finished card — which the coverage census then
    /// scores as a win. Zero reached by <em>counting</em> is a different thing and is charged as
    /// printed: an empty graveyard really does make "for each card in your graveyard" free.
    /// </remarks>
    [Theory]
    [InlineData("Counter target spell unless its controller pays {1} for each rumor you have heard.")]
    [InlineData("Counter target spell unless its controller pays {X}, where X is the mood of the table.")]
    public void A_price_counting_something_unreadable_leaves_the_line_unread(string line)
    {
        var card = Card("Unreadable Price Test " + line.Length, line);

        var compiled = CardCompiler.Compile(card);
        Assert.False(compiled.IsComplete);
        Assert.Contains(compiled.Unhandled, l => l.Contains("unless", StringComparison.Ordinal));
    }

    /// <summary>
    /// A price whose symbols the mana parser drops is refused (CR 107.4c).
    /// </summary>
    /// <remarks>
    /// <c>ManaCostSpec.Parse</c> keeps the symbols it understands and drops the rest, so a snow
    /// or an untap symbol parses to an <em>empty</em> cost — and an offer costing nothing is one
    /// every player takes. Every printed symbol has to survive the parse or the line stays
    /// unread, which costs one snow cumulative upkeep and is the right side to be wrong on.
    /// <para>
    /// Energy was the third symbol in this hole and is not here any more: the offer can take
    /// payment in it, so it is read rather than refused — see the energy pair above.
    /// </para>
    /// </remarks>
    [Theory]
    [InlineData("At the beginning of your upkeep, tap ~ unless you pay {Q}.")]
    [InlineData("At the beginning of your upkeep, sacrifice ~ unless you pay {S}.")]
    public void A_price_the_mana_parser_cannot_keep_whole_is_refused(string line)
    {
        var card = Card(
            "Dropped Symbol Price Test " + line.Length, line, CardType.Creature, 2, 2);

        var compiled = CardCompiler.Compile(card);
        Assert.False(compiled.IsComplete);
    }

    /// <summary>
    /// "Sacrifice this creature unless you pay {E}{E}" — a price in energy (CR 107.4c).
    /// </summary>
    /// <remarks>
    /// The offer has taken payment in energy since it was written, and the price reader could not
    /// see it: its energy pattern wants the printed word "pay", and a keyword's price arrives as
    /// the symbols alone. So <c>ManaCostSpec.Parse</c> dropped the {E}s, the offer came out free,
    /// and Lathnu Hellion was a 4/4 haste nobody ever had to sacrifice — a card several classes
    /// better than the one printed, reported as fully read.
    /// </remarks>
    [Fact]
    public void An_energy_price_is_charged_out_of_the_energy_a_player_has()
    {
        var hellion = Card(
            "Energy Price Hellion Test",
            "At the beginning of your upkeep, sacrifice ~ unless you pay {E}{E}.",
            CardType.Creature,
            power: 4,
            toughness: 4);

        var compiled = CardCompiler.Compile(hellion);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();

        game.Create(
            alice,
            Card("Energy Price Battery Test", "When ~ enters, you get {E}{E}.", CardType.Artifact),
            Zone.Battlefield);

        var beast = game.Create(alice, hellion, Zone.Battlefield);
        Settle(game);

        Assert.Equal(2, game.State.GetPlayer(alice).Energy);

        PassTo(game, 3, TurnStep.Upkeep);
        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.OptionalPayment });

        game.Choose(alice, ["yes"]);
        Settle(game);

        Assert.Contains(beast, game.State.Battlefield);
        Assert.Equal(0, game.State.GetPlayer(alice).Energy);
    }

    /// <summary>The same price one energy short: the creature really goes (CR 118.3).</summary>
    [Fact]
    public void An_energy_price_one_counter_short_is_never_offered()
    {
        var hellion = Card(
            "Short Energy Hellion Test",
            "At the beginning of your upkeep, sacrifice ~ unless you pay {E}{E}.",
            CardType.Creature,
            power: 4,
            toughness: 4);

        var (game, alice, _) = InMainPhase();

        game.Create(
            alice,
            Card("Short Energy Battery Test", "When ~ enters, you get {E}.", CardType.Artifact),
            Zone.Battlefield);

        var beast = game.Create(alice, hellion, Zone.Battlefield);
        Settle(game);

        Assert.Equal(1, game.State.GetPlayer(alice).Energy);

        PassTo(game, 3, TurnStep.Upkeep);
        Settle(game);

        Assert.DoesNotContain(beast, game.State.Battlefield);
        Assert.Equal(1, game.State.GetPlayer(alice).Energy);
    }

    // ---- An Aura's buff and its rider (CR 613.1f) ----------------------------

    [Fact]
    public void An_aura_can_pump_and_restrict_in_one_sentence()
    {
        // The pattern read "gets +N/+N and has [keyword]" and, separately, "can't block" on its
        // own — but not the two joined, which is how the cards actually print it.
        var shackles = Card(
            "Heavy Shackles Test",
            "Enchant creature\nEnchanted creature gets +2/+2 and can't block.",
            CardType.Enchantment,
            subtypes: "Aura");

        var compiled = CardCompiler.Compile(shackles);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var theirs = game.Create(bob, TestCards.Creature("Shackled Bear Test", 2, 2), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, shackles);
        game.CastSpell(alice, card, [Target.ToPermanent(theirs)]);
        Settle(game);

        var computed = Characteristics.Of(game.State, Pool, game.State.GetObject(theirs));

        // Both halves, from one sentence: the buff and the restriction.
        Assert.Equal(4, computed.Power);
        Assert.True(computed.Has(KeywordAbility.CantBlock));
    }

    // ---- Regeneration, of three different things (CR 701.15) -----------------

    [Fact]
    public void Regenerating_a_target_shields_the_target_and_not_the_source()
    {
        var ward = Card(
            "Regeneration Ward Test",
            "Regenerate target creature.",
            CardType.Instant);

        var compiled = CardCompiler.Compile(ward);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var mine = game.Create(alice, TestCards.Creature("Shielded Bear Test", 2, 2), Zone.Battlefield);
        var other = game.Create(alice, TestCards.Creature("Unshielded Bear Test", 2, 2), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, ward);
        game.CastSpell(alice, card, [Target.ToPermanent(mine)]);
        Settle(game);

        Assert.Equal(1, game.State.GetObject(mine).Permanent?.RegenerationShields);
        Assert.Equal(0, game.State.GetObject(other).Permanent?.RegenerationShields);

        // And the shield is spent saving it: destroyed, it stays on the battlefield tapped with
        // its damage removed (CR 701.15a).
        game.Move(mine, Zone.Graveyard, MoveCause.Destroy);
        Settle(game);

        var saved = game.State.Battlefield.Select(game.State.GetObject)
            .Single(o => o.Card.Name == "Shielded Bear Test");

        Assert.True(saved.Permanent?.IsTapped);
        Assert.Equal(0, saved.Permanent?.RegenerationShields);
    }

    // ---- Irregular tribal plurals (CR 205.3m) --------------------------------

    [Fact]
    public void A_lord_naming_an_irregular_plural_still_finds_its_tribe()
    {
        // "Other Elves you control" named the creature type "Elve", which nothing is. The card
        // compiled, looked complete, and buffed nothing however many Elves were out.
        var lord = Card(
            "Elf Marshal Test",
            "Other Elves you control get +1/+1.",
            CardType.Creature,
            power: 2,
            toughness: 2,
            subtypes: "Elf");

        var compiled = CardCompiler.Compile(lord);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var elf = game.Create(
            alice,
            Card("Lesser Elf Test", string.Empty, CardType.Creature, 1, 1, subtypes: "Elf"),
            Zone.Battlefield);

        var goblin = game.Create(
            alice,
            Card("Bystander Goblin Test", string.Empty, CardType.Creature, 1, 1, subtypes: "Goblin"),
            Zone.Battlefield);

        var marshal = game.Create(alice, lord, Zone.Battlefield);

        Assert.Equal(2, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(elf)));
        Assert.Equal(1, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(goblin)));

        // "Other" still means other: the marshal is an Elf and does not pump itself.
        Assert.Equal(2, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(marshal)));
    }

    // ---- What a prevention shield filters on: combat state (CR 506.1, 509.1h) ----

    /// <summary>
    /// "By attacking creatures" is a question about the game, not about the card (CR 508.1g).
    /// </summary>
    /// <remarks>
    /// The commonest of the shapes this round read, and the one whose failure looks most like
    /// success: <c>SourceFilter</c> is a <see cref="SearchFilters"/> id asked of a printed card,
    /// so a reader that let the adjective fall through would compile Harmless Assault as "prevent
    /// all combat damage that would be dealt this turn by creatures" — a plain fog, and a
    /// strictly better card than the printed one.
    /// <para>
    /// The control is in the same combat damage step, under the same shield: the attacker's
    /// damage is prevented and the blocker's <em>arrives</em>. Nothing but the combat state
    /// separates the two, so a shield that had lost the word would show zero on both.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_shield_on_attacking_creatures_lets_the_blockers_damage_through()
    {
        var fog = Card(
            "Attacker Fog Test",
            "Prevent all combat damage that would be dealt this turn by attacking creatures.");

        var compiled = CardCompiler.Compile(fog);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var ox = game.Create(
            alice, TestCards.Creature("Fogged Ox Test", 2, 6), Zone.Battlefield);
        var guard = game.Create(
            bob, TestCards.Creature("Fogged Guard Test", 3, 6), Zone.Battlefield);

        // On the turn it has to work on: "this turn" ends the shield at cleanup (CR 514.2),
        // so a fog cast two turns early is gone before any of this.
        PassTo(game, 3, TurnStep.PrecombatMain);
        game.CastSpell(alice, TestCards.PutInHand(game, alice, fog), targets: null);
        ResolveStack(game);

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice, new Dictionary<ObjectId, AttackTarget> { [ox] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);
        game.DeclareBlockers(
            bob, new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [ox] = [guard] });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Settle(game);

        // The attacker is attacking, so its damage is prevented.
        Assert.Equal(0, game.State.GetObject(guard).Permanent?.DamageMarked);

        // The blocker is not, so its damage arrives. This is the assertion that fails if the
        // adjective was dropped.
        Assert.Equal(3, game.State.GetObject(ox).Permanent?.DamageMarked);
    }

    /// <summary>
    /// "By unblocked creatures" separates two attackers in one combat (CR 509.1h).
    /// </summary>
    /// <remarks>
    /// Snag. Both sources are attacking creatures dealing combat damage in the same step, and the
    /// only thing between them is whether blockers were declared for them — so this is the arm
    /// that a shield reading merely "attacking" would get wrong, as well as one reading
    /// "creatures".
    /// </remarks>
    [Fact]
    public void A_shield_on_unblocked_creatures_lets_the_blocked_attacker_through()
    {
        var snag = Card(
            "Unblocked Snag Test",
            "Prevent all combat damage that would be dealt by unblocked creatures this turn.");

        var compiled = CardCompiler.Compile(snag);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var free = game.Create(
            alice, TestCards.Creature("Snag Runner Test", 3, 6), Zone.Battlefield);
        var stopped = game.Create(
            alice, TestCards.Creature("Snag Charger Test", 2, 6), Zone.Battlefield);
        var wall = game.Create(
            bob, TestCards.Creature("Snag Wall Test", 0, 6), Zone.Battlefield);

        PassTo(game, 3, TurnStep.PrecombatMain);
        game.CastSpell(alice, TestCards.PutInHand(game, alice, snag), targets: null);
        ResolveStack(game);

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget>
            {
                [free] = AttackTarget.Player(bob),
                [stopped] = AttackTarget.Player(bob),
            });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);
        game.DeclareBlockers(
            bob, new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [stopped] = [wall] });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Settle(game);

        // The unblocked attacker is prevented: Bob is untouched by a creature that got through.
        Assert.Equal(20, game.State.GetPlayer(bob).Life);

        // The blocked one is not, and its damage arrives on the blocker.
        Assert.Equal(2, game.State.GetObject(wall).Permanent?.DamageMarked);
    }

    /// <summary>
    /// A static shield reading "attacking creatures you control" (CR 611.2c, 508.1g).
    /// </summary>
    /// <remarks>
    /// Dolmen Gate, and the victim side of the same question. The control is the same creature
    /// one turn later, in the other half of a combat: blocking is not attacking, so the shield
    /// has to let that damage through. A Gate read without the adjective makes every creature its
    /// controller has invulnerable, at home, for as long as it is on the battlefield — which no
    /// assertion about the attacking case alone would notice.
    /// </remarks>
    [Fact]
    public void A_static_shield_on_attacking_creatures_leaves_its_own_blocker_unshielded()
    {
        var gate = Card(
            "Attack Gate Test",
            "Prevent all combat damage that would be dealt to attacking creatures you control.",
            CardType.Artifact);

        var compiled = CardCompiler.Compile(gate);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, gate, Zone.Battlefield);
        // Vigilance so the ox is still untapped on the turn it has to block: attacking taps it
        // (CR 508.1f) and its controller's next untap step is two turns away.
        var ox = game.Create(
            alice,
            Card("Gate Ox Test", "Vigilance", CardType.Creature, 2, 6, KeywordAbility.Vigilance),
            Zone.Battlefield);
        var guard = game.Create(bob, TestCards.Creature("Gate Guard Test", 3, 6), Zone.Battlefield);

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice, new Dictionary<ObjectId, AttackTarget> { [ox] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);
        game.DeclareBlockers(
            bob, new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [ox] = [guard] });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Settle(game);

        // Attacking, so shielded — and the damage it deals still arrives, so this is a shield
        // rather than a combat that did not happen.
        Assert.Equal(0, game.State.GetObject(ox).Permanent?.DamageMarked);
        Assert.Equal(2, game.State.GetObject(guard).Permanent?.DamageMarked);

        // The same creature, the next turn, blocking instead. The Gate is still on the
        // battlefield and still Alice's; the only thing that changed is what the ox is doing.
        PassTo(game, 4, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            bob, new Dictionary<ObjectId, AttackTarget> { [guard] = AttackTarget.Player(alice) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);
        game.DeclareBlockers(
            alice, new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [guard] = [ox] });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Settle(game);

        Assert.Equal(3, game.State.GetObject(ox).Permanent?.DamageMarked);
    }

    /// <summary>
    /// "By creatures blocking it" is a relation to one permanent, not a description (CR 509.1g).
    /// </summary>
    /// <remarks>
    /// Armored Transport. No card filter can say this: the set is whichever creatures were
    /// declared as blockers for one particular permanent, and it changes twice a turn.
    /// <para>
    /// The control is the mirror image, and it is the whole reason there are two fields rather
    /// than one. The next turn the Transport <em>blocks</em>, so the creature dealing it combat
    /// damage is one it is blocking rather than one blocking it — and that damage has to arrive.
    /// A shield that had the relation the wrong way round passes the first half of this test and
    /// fails here; one that read the phrase as the bare "creatures" it leaves behind passes both
    /// halves of the first and fails here too.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_shield_naming_the_creatures_blocking_it_does_not_cover_the_ones_it_blocks()
    {
        var transport = Card(
            "Blocked Transport Test",
            "Vigilance\nPrevent all combat damage that would be dealt to ~ by creatures "
                + "blocking it.",
            CardType.Creature,
            power: 2,
            toughness: 8,

            // Vigilance for the same reason the Gate's ox has it: this test needs the same
            // permanent attacking on one turn and blocking on the next.
            keywords: KeywordAbility.Vigilance);

        var compiled = CardCompiler.Compile(transport);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var truck = game.Create(alice, transport, Zone.Battlefield);
        var guard = game.Create(
            bob, TestCards.Creature("Transport Guard Test", 3, 8), Zone.Battlefield);

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice, new Dictionary<ObjectId, AttackTarget> { [truck] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);
        game.DeclareBlockers(
            bob, new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [truck] = [guard] });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Settle(game);

        // Blocked by the guard, so the guard's damage is prevented — and the Transport's own
        // damage still lands, so the combat happened.
        Assert.Equal(0, game.State.GetObject(truck).Permanent?.DamageMarked);
        Assert.Equal(2, game.State.GetObject(guard).Permanent?.DamageMarked);

        // The mirror: now the guard attacks and the Transport blocks it. The guard is a creature
        // the Transport is blocking, which is the other relation, so its damage arrives.
        PassTo(game, 4, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            bob, new Dictionary<ObjectId, AttackTarget> { [guard] = AttackTarget.Player(alice) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);
        game.DeclareBlockers(
            alice, new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [guard] = [truck] });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Settle(game);

        Assert.Equal(3, game.State.GetObject(truck).Permanent?.DamageMarked);
    }

    /// <summary>
    /// "By creatures it's blocking" is the other relation, and it is not the same one (CR 509.1g).
    /// </summary>
    /// <remarks>
    /// Wall of Vapor. The positive case alone tells the two apart: the Wall is not an attacker, so
    /// a shield asking "is the source one of my blockers" finds nothing to match and lets the
    /// damage through. The pinger is the control for the description as opposed to the relation —
    /// it is a creature, it is Bob's, and the Wall is not blocking it, so its point of damage has
    /// to arrive and stay on the Wall through a combat that prevents three more.
    /// </remarks>
    [Fact]
    public void A_shield_naming_the_creatures_it_is_blocking_is_the_mirror_of_that()
    {
        var wall = Card(
            "Vapor Wall Test",
            "Prevent all damage that would be dealt to ~ by creatures it's blocking.",
            CardType.Creature,
            power: 0,
            toughness: 8,
            keywords: KeywordAbility.Defender);

        var compiled = CardCompiler.Compile(wall);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var vapor = game.Create(alice, wall, Zone.Battlefield);
        var charger = game.Create(
            bob, TestCards.Creature("Vapor Charger Test", 3, 8), Zone.Battlefield);
        var runner = game.Create(
            bob, TestCards.Creature("Vapor Runner Test", 3, 8), Zone.Battlefield);
        var pinger = game.Create(bob, Pinger("Vapor Pinger Test"), Zone.Battlefield);

        PassTo(game, 4, TurnStep.PrecombatMain);

        // A creature the Wall is not blocking, dealing it damage before any of this: the control
        // for "creature" as a description against "creature it is blocking" as a relation.
        TapLands(game, bob, 1);
        game.ActivateAbility(bob, pinger, "a", [Target.ToPermanent(vapor)]);
        ResolveStack(game);
        Assert.Equal(1, game.State.GetObject(vapor).Permanent?.DamageMarked);

        PassTo(game, 4, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            bob,
            new Dictionary<ObjectId, AttackTarget>
            {
                [charger] = AttackTarget.Player(alice),
                [runner] = AttackTarget.Player(alice),
            });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);
        game.DeclareBlockers(
            alice, new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [charger] = [vapor] });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Settle(game);

        // Still one, not four: the charger is a creature the Wall is blocking and the pinger is
        // not.
        Assert.Equal(1, game.State.GetObject(vapor).Permanent?.DamageMarked);

        // And the other attacker got through, so this is a shield round one permanent rather
        // than a fog.
        Assert.Equal(17, game.State.GetPlayer(alice).Life);
    }

    /// <summary>
    /// A shield whose victim is the creature the sentence in front of it chose (CR 615.1).
    /// </summary>
    /// <remarks>
    /// Djeru's Resolve. The pronoun is read only because a permanent target stands behind it in
    /// the same ability; the second half of this test is the same words with nothing behind them,
    /// which mean the permanent the ability is printed on and are left unread rather than guessed
    /// at. Favored Hoplite and Ignoble Soldier both print that and both stay unread.
    /// </remarks>
    [Fact]
    public void A_pronoun_shield_follows_the_creature_the_sentence_already_chose()
    {
        var resolve = Card(
            "Pronoun Resolve Test",
            "Untap target creature. Prevent all damage that would be dealt to it this turn.");

        var compiled = CardCompiler.Compile(resolve);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var orphan = CardCompiler.Compile(
            Card(
                "Orphan Pronoun Test",
                "Prevent all damage that would be dealt to it this turn."));

        // Nothing behind the pronoun, so nothing to point at, so no shield at all.
        Assert.False(orphan.IsComplete);

        var (game, alice, _) = InMainPhase();
        var shielded = game.Create(
            alice, TestCards.Creature("Resolve Shielded Test", 2, 4), Zone.Battlefield);
        var bystander = game.Create(
            alice, TestCards.Creature("Resolve Bystander Test", 2, 4), Zone.Battlefield);
        var pinger = game.Create(alice, Pinger("Resolve Pinger Test"), Zone.Battlefield);

        game.CastSpell(
            alice,
            TestCards.PutInHand(game, alice, resolve),
            [Target.ToPermanent(shielded)]);
        ResolveStack(game);

        TapLands(game, alice, 1);
        game.ActivateAbility(alice, pinger, "a", [Target.ToPermanent(shielded)]);
        ResolveStack(game);
        Assert.Equal(0, game.State.GetObject(shielded).Permanent?.DamageMarked);

        // The creature the sentence did not name takes the same point of damage.
        TapLands(game, alice, 1);
        game.ActivateAbility(alice, pinger, "a", [Target.ToPermanent(bystander)]);
        ResolveStack(game);
        Assert.Equal(1, game.State.GetObject(bystander).Permanent?.DamageMarked);
    }

    /// <summary>
    /// "~" in the victim slot of an activated ability is the permanent, not a description.
    /// </summary>
    /// <remarks>
    /// Trained Pronghorn and Stonewise Fortifier. It reads
    /// <see cref="ResolutionContext.PhysicalSourceId"/>, because what resolves is the ability and
    /// the shield goes round the creature — the same field the both-ways reader has used since
    /// Maze of Ith, now reachable from the ordinary "to …" clause.
    /// </remarks>
    [Fact]
    public void A_shield_around_the_permanent_that_printed_it_covers_that_permanent_alone()
    {
        var guard = Card(
            "Self Guard Test",
            "{1}: Prevent all damage that would be dealt to ~ this turn.",
            CardType.Creature,
            power: 2,
            toughness: 4);

        var compiled = CardCompiler.Compile(guard);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var mine = game.Create(alice, guard, Zone.Battlefield);
        var other = game.Create(
            alice, TestCards.Creature("Self Guard Bystander Test", 2, 4), Zone.Battlefield);
        var pinger = game.Create(alice, Pinger("Self Guard Pinger Test"), Zone.Battlefield);

        TapLands(game, alice, 1);
        game.ActivateAbility(alice, mine, "a");
        ResolveStack(game);

        TapLands(game, alice, 1);
        game.ActivateAbility(alice, pinger, "a", [Target.ToPermanent(mine)]);
        ResolveStack(game);
        Assert.Equal(0, game.State.GetObject(mine).Permanent?.DamageMarked);

        // Everything else on the same board takes it, which is what "~" alone means.
        TapLands(game, alice, 1);
        game.ActivateAbility(alice, pinger, "a", [Target.ToPermanent(other)]);
        ResolveStack(game);
        Assert.Equal(1, game.State.GetObject(other).Permanent?.DamageMarked);
    }

    /// <summary>
    /// Unblocked is a fact that does not exist until blockers have been declared (CR 509.1h).
    /// </summary>
    /// <remarks>
    /// An attacker in the declare attackers step is neither blocked nor unblocked, and answering
    /// "unblocked" for it would apply the shield for half a combat phase it was never meant to
    /// reach. The evidence is a life total that goes down before the declaration and stops going
    /// down after it, with the same source, the same shield and the same ability.
    /// </remarks>
    [Fact]
    public void An_unblocked_shield_says_nothing_until_blockers_are_declared()
    {
        var snag = Card(
            "Early Snag Test",
            "Prevent all damage that would be dealt by unblocked creatures this turn.");

        var compiled = CardCompiler.Compile(snag);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var pinger = game.Create(alice, Pinger("Early Snag Pinger Test"), Zone.Battlefield);

        PassTo(game, 3, TurnStep.PrecombatMain);
        game.CastSpell(alice, TestCards.PutInHand(game, alice, snag), targets: null);
        ResolveStack(game);

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice, new Dictionary<ObjectId, AttackTarget> { [pinger] = AttackTarget.Player(bob) });

        // Attacking, but nobody has declared blockers yet, so it is not an unblocked creature and
        // the shield does not cover it. The damage arrives.
        TapLands(game, alice, 1);
        game.ActivateAbility(alice, pinger, "a", [Target.ToPlayer(bob)]);
        ResolveStack(game);
        Assert.Equal(19, game.State.GetPlayer(bob).Life);

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);
        game.DeclareBlockers(bob, new Dictionary<ObjectId, IReadOnlyList<ObjectId>>());

        // Declared with nothing blocking it: now it is unblocked, and the same ability is
        // prevented.
        TapLands(game, alice, 1);
        game.ActivateAbility(alice, pinger, "a", [Target.ToPlayer(bob)]);
        ResolveStack(game);
        Assert.Equal(19, game.State.GetPlayer(bob).Life);
    }

    /// <summary>
    /// One adjective is read; a disjunction of two is left unread (CR 615.1).
    /// </summary>
    /// <remarks>
    /// The shield has one slot for a combat state, and "attacking or blocking creatures" is two.
    /// Collapsing it to either half is a different card, and collapsing it to neither is a fog, so
    /// the line stays unread — the fail-closed direction this family is judged by.
    /// <para>
    /// The positive half asserts the compiled shield <em>carries</em> the role rather than merely
    /// that the line was accepted. "Read the words and dropped one" and "read the words" produce
    /// the same coverage number, and only one of them is a card.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_combat_state_the_shield_has_no_slot_for_leaves_the_line_unread()
    {
        var both = CardCompiler.Compile(
            Card(
                "Both Roles Test",
                "Prevent all combat damage that would be dealt this turn by attacking or "
                    + "blocking creatures."));

        Assert.False(both.IsComplete);

        var one = CardCompiler.Compile(
            Card(
                "One Role Test",
                "Prevent all combat damage that would be dealt this turn by attacking "
                    + "creatures."));

        Assert.True(one.IsComplete, string.Join(" | ", one.Unhandled));

        var shield = Assert.IsType<PreventDescribedDamage>(one.Spell?.Effects.Single());
        Assert.Equal(CombatRole.Attacking, shield.SourceCombat);
        Assert.NotNull(shield.SourceFilter);
    }

    // ---- "That many" (CR 603.2) ----------------------------------------------

    [Fact]
    public void That_many_is_how_much_the_triggering_event_was_about()
    {
        var raider = Card(
            "Thieving Raider Test",
            "Whenever ~ deals combat damage to a player, draw that many cards.",
            CardType.Creature,
            power: 3,
            toughness: 3);

        var compiled = CardCompiler.Compile(raider);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, raider, Zone.Battlefield);

        // Pumped first, so the answer cannot come from the printed power: it is three on the
        // card and four in the damage the event carried.
        game.ChangeCounters(attacker, CounterKinds.PlusOnePlusOne, 1);

        // Turn 3, so the raider is no longer summoning sick.
        PassTo(game, 3, TurnStep.DeclareAttackers);

        // Counted here, after the draw step, so the turn's own draw is not in the total.
        var held = game.State.GetPlayer(alice).Hand.Count;
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Settle(game);

        Assert.Equal(16, game.State.GetPlayer(bob).Life);
        Assert.Equal(held + 4, game.State.GetPlayer(alice).Hand.Count);
    }

    [Fact]
    public void That_much_is_the_same_word_in_the_other_grammar()
    {
        // Cards are counted and life is measured, so the cards say "that many" of one and "that
        // much" of the other. One idea, and read as one.
        var leech = Card(
            "Thirsty Leech Test",
            "Whenever ~ deals combat damage to a player, you gain that much life.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var compiled = CardCompiler.Compile(leech);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, leech, Zone.Battlefield);

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Settle(game);

        Assert.Equal(18, game.State.GetPlayer(bob).Life);
        Assert.Equal(22, game.State.GetPlayer(alice).Life);
    }

    // ---- Skipping the draw step (CR 504.1) -----------------------------------

    [Fact]
    public void A_permanent_that_skips_the_draw_step_skips_it_for_its_controller_only()
    {
        var pact = Card(
            "Draw Pact Test",
            "Skip your draw step.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(pact);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, pact, Zone.Battlefield);

        var aliceHeld = game.State.GetPlayer(alice).Hand.Count;
        var bobHeld = game.State.GetPlayer(bob).Hand.Count;

        // Bob's turn: he draws.
        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber == 2 && game.State.CurrentStep == TurnStep.PrecombatMain);

        Assert.Equal(bobHeld + 1, game.State.GetPlayer(bob).Hand.Count);

        // Alice's next turn: she does not.
        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber == 3 && game.State.CurrentStep == TurnStep.PrecombatMain);

        Assert.Equal(aliceHeld, game.State.GetPlayer(alice).Hand.Count);
    }

    // ---- What an Aura calls what it is on (CR 303.4) -------------------------

    [Fact]
    public void An_aura_on_a_land_reads_every_line_that_names_it()
    {
        // Three matchers each carried their own idea of what an Aura calls the thing it is
        // attached to, and they had drifted: this card's first line was read and its second was
        // not, so it compiled as a land tax that never taxed anything.
        var choke = Card(
            "Land Choke Test",
            "Enchant land\n"
                + "Enchanted land doesn't untap during its controller's untap step.",
            CardType.Enchantment,
            subtypes: "Aura");

        var compiled = CardCompiler.Compile(choke);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var theirs = game.Create(bob, TestCards.BasicLand("Choked Forest Test"), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, choke);
        game.CastSpell(alice, card, [Target.ToPermanent(theirs)]);
        Settle(game);

        game.Tap(theirs);

        // Bob's untap step comes and the land stays tapped.
        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber == 2 && game.State.CurrentStep == TurnStep.PrecombatMain);

        Assert.True(game.State.GetObject(theirs).Permanent?.IsTapped);
    }

    // ---- Cards that read as complete and could never do anything -------------
    //
    // Every card below compiled with nothing unread, passed the legality gate, could be put in a
    // deck, cast or activated, and then changed nothing at all - which is strictly worse than an
    // unread card, because an unread card is refused and says so. They were found by an audit
    // that asks one question of the whole corpus: not "does this fault" but "could this ever do
    // anything". Each test here plays the card in a real game and watches it do the thing it
    // prints.

    /// <summary>
    /// A punisher wrapped round an offer asks both questions and runs the branch (CR 601.2b).
    /// </summary>
    /// <remarks>
    /// Rhystic Study. "You may draw a card unless that player pays {1}" is an offer inside an
    /// offer: the punisher reader takes the whole sentence and hands "you may draw a card" to the
    /// sentence parser, which builds a <c>MayPay</c> numbered from its own empty list - locator 0,
    /// exactly what the outer offer then took from its own. <c>EffectTree.Locate</c> answers null
    /// on a tie rather than guessing, so when the caster's answer came back the branch could not
    /// be found and <b>neither</b> question ever ran. Three cards: Rhystic Study, Mystic Remora,
    /// Complicate.
    /// <para>
    /// The card that was already here asserted <em>who</em> the offer was addressed to and said
    /// in its own remarks that what they answered was somebody else's business. That is the half
    /// that was broken, and it is what this asserts: the caster declines, and the enchantment's
    /// controller draws.
    /// </para>
    /// </remarks>
    [Fact]
    public void An_offer_inside_a_punisher_still_runs_when_the_price_is_declined()
    {
        var study = Card(
            "Silent Study Test",
            "Whenever an opponent casts a spell, you may draw a card unless that player pays {1}.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(study);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, study, Zone.Battlefield);

        // A land, so the price is one Bob could pay and the question is a real one. Without it
        // he is not asked at all (CR 118.3) and the test would prove only the cheaper half.
        game.Create(bob, Card("Study Island Test", "{T}: Add {U}.", CardType.Land), Zone.Battlefield);

        var bait = TestCards.PutInHand(game, bob, Card("Study Bait Test", "Draw a card."));
        TestCards.PassUntil(game, () => game.State.Priority.Holder == bob);

        var held = game.State.GetPlayer(alice).Hand.Count;
        game.CastSpell(bob, bait, []);

        // The price goes to the caster, which is the half that already worked.
        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.OptionalPayment });
        var price = game.State.Choice!;
        Assert.Equal(bob, price.PlayerId);
        game.Choose(bob, ["no"]);

        // And the draw is offered to the enchantment's controller, which is the half that was
        // never reached: the branch is found by locator, and both offers carried 0.
        var draw = game.State.Choice;
        Assert.NotNull(draw);
        Assert.Equal(ChoiceKind.OptionalPayment, draw!.Kind);
        Assert.Equal(alice, draw.PlayerId);
        game.Choose(alice, ["yes"]);

        Settle(game);

        Assert.Equal(held + 1, game.State.GetPlayer(alice).Hand.Count);
    }

    /// <summary>
    /// A cost modifier opening a sentence names a colour, not a creature type (CR 601.2f).
    /// </summary>
    /// <remarks>
    /// Herald of Kozilek. Every printed sentence begins with a capital, and the filter vocabulary
    /// read a capitalised word as a subtype before it asked whether it was a word the vocabulary
    /// already knew - so "Colorless spells you cast cost {1} less to cast" compiled into a
    /// discount on spells of the creature type <em>Colorless</em>, which no card is. The modifier
    /// existed, was attached to the permanent, was consulted on every cast and matched nothing.
    /// Four cards on the same shape: Herald of Kozilek, Eye of Ugin, Jhoira's Familiar and
    /// Urza's Filter, the last of them taxing nobody rather than discounting nobody.
    /// <para>
    /// The same mistake the mass static made when "Artifact creatures you control get +1/+1"
    /// became a lord for the creature type Artifact, one reader along and 129 cards heavier.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_colorless_discount_comes_off_a_colorless_spell()
    {
        var herald = Card(
            "Colorless Discount Test",
            "Colorless spells you cast cost {1} less to cast.",
            CardType.Artifact);

        var compiled = CardCompiler.Compile(herald);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        // Colourless because it has no colours, which is what devoid prints (CR 105.1, 702.114a).
        var drone = new CardDefinition
        {
            OracleId = "oracle-colorless-drone-test",
            Name = "Colorless Drone Test",
            OracleText = string.Empty,
            CardTypes = CardType.Creature,
            ManaCostRaw = "{2}",
            Cmc = 2,
            Power = 2,
            Toughness = 2,
        };

        // Without the discount, one mana is not enough for a two-mana spell.
        var (bare, aliceBare, _) = InMainPhase();
        game_TapForColourless(bare, aliceBare, 1);
        var refused = TestCards.PutInHand(bare, aliceBare, drone);
        Assert.Throws<InvalidOperationException>(() => bare.CastSpell(aliceBare, refused, []));

        // With it, the same one mana pays for the same spell.
        var (game, alice, _) = InMainPhase();
        game.Create(alice, herald, Zone.Battlefield);
        game_TapForColourless(game, alice, 1);

        var cast = TestCards.PutInHand(game, alice, drone);
        game.CastSpell(alice, cast, []);
        Assert.True(game.State.GetPlayer(alice).ManaPool.IsEmpty);
        Settle(game);

        Assert.Contains(
            game.State.Battlefield.Select(game.State.GetObject),
            o => o.Card.Name == "Colorless Drone Test");
    }

    /// <summary>One colourless mana per land, built and tapped on the spot.</summary>
    private static void game_TapForColourless(Game game, Guid playerId, int count)
    {
        for (var i = 0; i < count; i++)
        {
            var land = game.Create(
                playerId,
                Card($"Wastes Test {i}", "{T}: Add {C}.", CardType.Land),
                Zone.Battlefield);

            game.ActivateAbility(playerId, land, "mana");
        }
    }

    /// <summary>
    /// A trigger that acts on its card in a graveyard watches from there (CR 603.6).
    /// </summary>
    /// <remarks>
    /// Reach of Branches, and seven more. The compiler picks a trigger's functioning zone from
    /// its <em>condition</em>, which is all a condition can say, and defaults to the battlefield;
    /// "whenever a Forest you control enters" says nothing about where the card is. So eight
    /// instants and sorceries compiled complete and waited on a battlefield they can never reach
    /// - <c>Game.Consider</c> skips any ability whose source is not in its functioning zone - and
    /// not one of them ever came back. Spit Flame, Sosuke's Summons, Punishing Fire, Rekindled
    /// Flame, Killian's Confidence, Unconventional Tactics and Death of a Thousand Stings are
    /// the rest.
    /// <para>
    /// The zone is now read off the effect rather than the words, because the effect is the thing
    /// that knows: <c>ReturnSourceToHand</c> returns nothing unless the source is in a graveyard.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_spell_that_recurs_itself_triggers_from_the_graveyard()
    {
        var reach = Card(
            "Branch Reach Test",
            "Create a 2/5 green Treefolk creature token.\n"
                + "Whenever a Forest you control enters, you may return Branch Reach Test from "
                + "your graveyard to your hand.");

        var compiled = CardCompiler.Compile(reach);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        // The whole fix in one field, asserted before the game starts: an ability that acts on
        // its card in a graveyard has to be watching from the graveyard, and Game.Consider skips
        // any ability whose source is not in its functioning zone.
        var recursion = Assert.Single(compiled.Triggers);
        Assert.Equal(Zone.Graveyard, recursion.FunctionsFrom);

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, reach);

        game.CastSpell(alice, card, []);
        Settle(game);

        // It is in the graveyard, which is the only place the trigger could ever be watching from.
        Assert.Contains(
            game.State.GetPlayer(alice).Graveyard.Select(game.State.GetObject),
            o => o.Card.Name == "Branch Reach Test");

        var forest = TestCards.PutInHand(game, alice, TestCards.BasicLand("Forest"));
        game.PlayLand(alice, forest);

        // It has to reach the stack at all, which it never did while the ability was waiting on
        // a battlefield this card cannot be on.
        Assert.Contains(
            game.Log.OfType<AbilityTriggered>(),
            t => t.Text.Contains("from your graveyard", StringComparison.Ordinal));

        // And the offer it resolves into is the "you may".
        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.OptionalPayment });
        var offer = game.State.Choice!;
        Assert.Equal(alice, offer.PlayerId);
        game.Choose(alice, ["yes"]);

        Settle(game);

        Assert.Contains(
            game.State.GetPlayer(alice).Hand.Select(game.State.GetObject),
            o => o.Card.Name == "Branch Reach Test");

        Assert.DoesNotContain(
            game.State.GetPlayer(alice).Graveyard.Select(game.State.GetObject),
            o => o.Card.Name == "Branch Reach Test");
    }

    /// <summary>
    /// "A card named X or Y" is a search that will take either card (CR 701.23).
    /// </summary>
    /// <remarks>
    /// Bogbrew Witch, Dragonstorm Forecaster, Renowned Weaponsmith. The whole printed phrase went
    /// into the filter as one name, and no card is called "Festering Newt or Bubbling Cauldron",
    /// so the search offered nothing on three cards that compiled complete and had a working
    /// activation cost, a working tap and a working shuffle either side of it.
    /// <para>
    /// The whole phrase is still the first alternative the filter tries, so a card really named
    /// "Do or Die" is not split into two names it has not got. Nothing in the corpus needs that
    /// today - these three are every "named ... or ..." search there is - but a filter that
    /// cannot lose a card is worth more than one that is right about this printing.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_search_naming_two_cards_offers_both_of_them()
    {
        var witch = Card(
            "Two Name Search Test",
            "{T}: Search your library for a card named Newt Test or Cauldron Test, put it into "
                + "your hand, then shuffle.",
            CardType.Artifact);

        var compiled = CardCompiler.Compile(witch);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var source = game.Create(alice, witch, Zone.Battlefield);

        game.Create(alice, TestCards.Creature("Newt Test", 1, 1), Zone.Library);
        game.Create(alice, TestCards.Creature("Cauldron Test", 1, 1), Zone.Library);
        game.Create(alice, TestCards.Creature("Neither Test", 1, 1), Zone.Library);

        game.ActivateAbility(alice, source, compiled.Activated[0].Id);
        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.SearchLibrary });

        var offered = game.State.Choice!.Options!;
        Assert.Contains(offered, o => o.Label == "Newt Test");
        Assert.Contains(offered, o => o.Label == "Cauldron Test");
        Assert.DoesNotContain(offered, o => o.Label == "Neither Test");

        game.Choose(alice, [offered.First(o => o.Label == "Cauldron Test").Id]);
        Settle(game);

        Assert.Contains(
            game.State.GetPlayer(alice).Hand.Select(game.State.GetObject),
            o => o.Card.Name == "Cauldron Test");
    }

    /// <summary>
    /// A trigger naming a land type watches for a land, not for a creature (CR 205.3).
    /// </summary>
    /// <remarks>
    /// The largest of the five, and the one the audit could not see. Every card type has its own
    /// subtypes and the sets do not overlap, so the word alone settles which type is meant - and
    /// <c>Specs.SubtypeCardType</c> has said so since "for each Equipment you control" was found
    /// asking for a creature with the Equipment subtype. The trigger-condition reader never asked
    /// it. It paired every capitalised noun with <c>CardType.Creature</c>, with a comment saying
    /// a named type always is one in this position, so "whenever a Forest you control enters"
    /// compiled into a trigger watching for a <em>creature</em> with the land type Forest. There
    /// are none, and there can be none: the trigger was consulted on every event of every game
    /// and could not fire on any board that will ever be built.
    /// <para>
    /// 61 corpus cards print the shape, across every non-creature subtype the reader can meet -
    /// Vehicle, Aura, Forest, Equipment, Mountain, Shrine, Swamp, Gate, Island, Desert, Food,
    /// Cave, Clue, Curse. Baru, Fist of Krosa; Puresteel Paladin; Dread Presence; Guild Summit.
    /// </para>
    /// <para>
    /// It is invisible to a filter audit because a trigger condition is a compiled predicate and
    /// not a filter string - the same blind spot the mass-static check was written for, one
    /// reader along - which is why it was found by playing the card rather than by reading it.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_trigger_on_a_land_type_fires_for_the_land_and_not_for_another()
    {
        var baru = Card(
            "Land Type Trigger Test",
            "Whenever a Forest you control enters, you gain 2 life.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(baru);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, baru, Zone.Battlefield);

        var forest = TestCards.PutInHand(game, alice, TestCards.BasicLand("Forest"));
        game.PlayLand(alice, forest);
        Settle(game);

        Assert.Equal(22, game.State.GetPlayer(alice).Life);

        // A land of another type is not a Forest, so the trigger stays narrow: the fix widens
        // which card type answers, not which subtype.
        TestCards.PassUntil(
            game,
            () => game.State.ActivePlayerId == bob
                && game.State.CurrentStep == TurnStep.PrecombatMain);

        var island = TestCards.PutInHand(game, bob, TestCards.BasicLand("Island"));
        game.PlayLand(bob, island);
        Settle(game);

        Assert.Equal(22, game.State.GetPlayer(alice).Life);
    }

    // ---- Declining to untap (CR 502.3) ---------------------------------------

    [Fact]
    public void A_permanent_that_may_decline_to_untap_is_asked_and_the_rest_are_not()
    {
        var vault = Card(
            "Declining Vault Test",
            "You may choose not to untap ~ during your untap step.",
            CardType.Artifact);

        var compiled = CardCompiler.Compile(vault);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var choosy = game.Create(alice, vault, Zone.Battlefield);
        var ordinary = game.Create(
            alice, Card("Ordinary Vault Test", string.Empty, CardType.Artifact), Zone.Battlefield);

        game.Tap(choosy);
        game.Tap(ordinary);

        // Alice's next untap step.
        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.ChooseOptionalUntaps });

        var asked = game.State.Choice!;

        // Only the one that offers the choice is in the question - the other untapped with
        // everything else, because untapping is simultaneous and waiting would split it.
        var offered = Assert.Single(asked.Options);
        Assert.Equal("Declining Vault Test", offered.Label);
        Assert.False(game.State.GetObject(ordinary).Permanent?.IsTapped);

        // Decline: pick nothing, and it stays tapped.
        game.Choose(asked.PlayerId, []);

        Assert.True(game.State.GetObject(choosy).Permanent?.IsTapped);
    }

    // ---- An extra land drop (CR 305.2) ---------------------------------------

    [Fact]
    public void An_extra_land_drop_is_counted_and_is_not_shared_with_the_opponent()
    {
        var explorer = Card(
            "Extra Lands Test",
            "You may play an additional land on each of your turns.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(explorer);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();

        var first = TestCards.PutInHand(game, alice, TestCards.BasicLand("Extra Forest One Test"));
        var second = TestCards.PutInHand(game, alice, TestCards.BasicLand("Extra Forest Two Test"));
        var third = TestCards.PutInHand(game, alice, TestCards.BasicLand("Extra Forest Three Test"));

        game.Create(alice, explorer, Zone.Battlefield);

        // Two are legal and a third is not: it adds one, it does not lift the limit.
        game.PlayLand(alice, first);
        game.PlayLand(alice, second);
        Assert.Throws<InvalidOperationException>(() => game.PlayLand(alice, third));

        // And it is Alice's permission, not the table's. Dealt on Bob's own turn, because a hand
        // stocked before Alice's cleanup would be discarded down to seven first.
        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber == 2 && game.State.CurrentStep == TurnStep.PrecombatMain);

        var theirs = TestCards.PutInHand(game, bob, TestCards.BasicLand("Bob Forest One Test"));
        var alsoTheirs = TestCards.PutInHand(game, bob, TestCards.BasicLand("Bob Forest Two Test"));

        game.PlayLand(bob, theirs);
        Assert.Throws<InvalidOperationException>(() => game.PlayLand(bob, alsoTheirs));
    }

    // ---- Choosing a type as it enters (CR 614.12) ----------------------------

    [Fact]
    public void A_permanent_that_names_a_type_buffs_what_it_named_and_nothing_else()
    {
        var banner = Card(
            "Chosen Banner Test",
            "As ~ enters, choose a creature type.\n"
                + "Creatures of the chosen type get +1/+1.",
            CardType.Artifact);

        var compiled = CardCompiler.Compile(banner);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var goblin = game.Create(alice, Card("Chosen Goblin Test", string.Empty, CardType.Creature, 2, 2, subtypes: "Goblin"), Zone.Battlefield);
        var elf = game.Create(alice, Card("Chosen Elf Test", string.Empty, CardType.Creature, 2, 2, subtypes: "Elf"), Zone.Battlefield);

        game.Create(alice, banner, Zone.Battlefield);

        // Driven by hand rather than through Settle, which answers a question with its first
        // option - the point here is what the question is and what the board looks like while it
        // stands.
        game.PassPriority(alice);

        // The question is asked as it arrives, and until it is answered the banner buffs nothing
        // rather than everything.
        var asked = game.State.Choice;
        Assert.NotNull(asked);
        Assert.Equal(ChoiceKind.NameCharacteristic, asked.Kind);
        Assert.Equal(2, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(goblin)));

        game.Choose(asked.PlayerId, ["Elf"]);
        Settle(game);

        // The Elf grew and the Goblin did not: the tribe came from the answer, not the card.
        Assert.Equal(3, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(elf)));
        Assert.Equal(2, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(goblin)));
    }

    [Fact]
    public void A_land_that_names_a_colour_taps_for_that_colour_and_not_before()
    {
        var sanctum = Card(
            "Chosen Sanctum Test",
            "As ~ enters, choose a color.\n{T}: Add one mana of the chosen color.",
            CardType.Land);

        var compiled = CardCompiler.Compile(sanctum);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var land = game.Create(alice, sanctum, Zone.Battlefield);

        // Tapped before the question is answered: no mana, and not colourless mana either. A
        // permanent that has not chosen cannot tap for a colour it has not named.
        game.ActivateAbility(alice, land, "mana");
        Assert.True(game.State.GetPlayer(alice).ManaPool.IsEmpty);

        // A mana ability resolves without the game settling (CR 605.3b), so the question has
        // still not been asked at this point - which is exactly why the tap above produced
        // nothing.
        game.PassPriority(alice);

        var asked = game.State.Choice;
        Assert.NotNull(asked);
        game.Choose(asked.PlayerId, ["red"]);

        // Untap it and try again on a later turn.
        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber == 3 && game.State.CurrentStep == TurnStep.PrecombatMain);

        var back = game.State.Battlefield.Select(game.State.GetObject)
            .Single(o => o.Card.Name == "Chosen Sanctum Test");

        Assert.Equal("red", back.Chosen);

        game.ActivateAbility(alice, back.Id, "mana");
        Assert.Equal(1, game.State.GetPlayer(alice).ManaPool[ManaColor.Red]);
    }

    // ---- A card referred to by its literal printed name (CR 201.2a) ----------

    /// <remarks>
    /// The family these tests are about is one the compiler could not see, because the self-name
    /// substitution blanked a card's own name to "~" before any reader ran and a name filter has
    /// nothing left to filter on. Two rules are in play and they are not the same rule: CR 201.5
    /// governs the object a card names to mean *itself*, and CR 201.2a governs "named X", which
    /// asks every object whether it carries that name.
    /// <para>
    /// The trap the whole family sits on is that a name is capitalised and so is a subtype, and
    /// every reader in this compiler tells those apart by the capital letter alone. A name left in
    /// a noun phrase is read as a creature type, which is how "All Mountains are Plains" once
    /// compiled into a lord for the creature type Mountain - a card that read, played and matched
    /// nothing. Two of the tests below are that control and nothing else.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_count_of_cards_with_one_printed_name_ignores_the_rest_of_the_graveyard()
    {
        var inventory = Card(
            "Take Inventory Test",
            "Draw a card, then draw cards equal to the number of cards named ~ in your graveyard.");

        var compiled = CardCompiler.Compile(inventory);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();

        // Two of this card, and two that are not it. The graveyard holds four cards and the count
        // is two: the name is the filter, not the pile.
        game.Create(alice, inventory, Zone.Graveyard);
        game.Create(alice, inventory, Zone.Graveyard);
        game.Create(alice, Card("Lost Inventory Test", "Draw a card."), Zone.Graveyard);
        game.Create(alice, TestCards.Creature("Buried Inventory Bear Test", 2, 2), Zone.Graveyard);

        var card = TestCards.PutInHand(game, alice, inventory);
        var held = game.State.GetPlayer(alice).Hand.Count;

        game.CastSpell(alice, card, []);
        Settle(game);

        // One card, then two more: the spell itself is still on the stack while it resolves, so it
        // is not one of the two it counted.
        Assert.Equal(held - 1 + 3, game.State.GetPlayer(alice).Hand.Count);
    }

    /// <remarks>
    /// The other player's copy counts. The phrase is "on the battlefield", not "you control", and
    /// reading the first as the second is a smaller card than the printed one.
    /// </remarks>
    [Fact]
    public void A_creature_counting_its_own_name_leaves_itself_out_and_counts_every_seat()
    {
        var rats = Card(
            "Relentless Rats Test",
            "~ gets +1/+1 for each other creature on the battlefield named ~.",
            CardType.Creature,
            2,
            2,
            subtypes: "Rat");

        var compiled = CardCompiler.Compile(rats);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();

        var first = game.Create(alice, rats, Zone.Battlefield);
        game.Create(alice, rats, Zone.Battlefield);
        game.Create(bob, rats, Zone.Battlefield);

        // A Rat by type and not by name. It is the control: the noun vocabulary reads a
        // capitalised word as a subtype, and this one would be counted by a reader that did.
        var stray = game.Create(
            alice,
            Card("Sewer Rat Test", string.Empty, CardType.Creature, 1, 1, subtypes: "Rat"),
            Zone.Battlefield);

        Settle(game);

        // Three copies on the battlefield, so each sees the other two: 2/2 plus two.
        Assert.Equal(4, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(first)));
        Assert.Equal(4, Characteristics.ToughnessOf(game.State, Pool, game.State.GetObject(first)));

        // And the Rat that is only a Rat is untouched by all of it.
        Assert.Equal(1, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(stray)));
    }

    /// <remarks>
    /// The control that the rest of this section exists for. The name here is deliberately a word
    /// that is also a creature type, because that collision is the whole defect: read as a type,
    /// the count answers with the wrong permanent and the card still reports itself complete.
    /// </remarks>
    [Fact]
    public void A_name_that_is_also_a_creature_type_counts_the_name_and_not_the_type()
    {
        var sentinel = Card(
            "Griffin Sentinel Test",
            "~ gets +1/+1 for each creature you control named Griffin.",
            CardType.Creature,
            1,
            1,
            subtypes: "Wall");

        var compiled = CardCompiler.Compile(sentinel);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var watcher = game.Create(alice, sentinel, Zone.Battlefield);

        // One creature carries the name and is not the type; two carry the type and not the name.
        game.Create(
            alice,
            Card("Griffin", string.Empty, CardType.Creature, 2, 2, subtypes: "Bird"),
            Zone.Battlefield);
        game.Create(
            alice,
            Card("Sky Hunter Test", string.Empty, CardType.Creature, 2, 2, subtypes: "Griffin"),
            Zone.Battlefield);
        game.Create(
            alice,
            Card("Cloud Rider Test", string.Empty, CardType.Creature, 2, 2, subtypes: "Griffin"),
            Zone.Battlefield);

        Settle(game);

        // One, not two, and not three. A reader that took the word for a subtype would say two.
        Assert.Equal(2, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(watcher)));
    }

    [Fact]
    public void A_trigger_over_a_named_group_reaches_your_other_copies_and_nothing_else()
    {
        var stray = Card(
            "Charmed Stray Test",
            "When ~ enters, put a +1/+1 counter on each other creature you control named ~.",
            CardType.Creature,
            0,
            3,
            subtypes: "Cat");

        var compiled = CardCompiler.Compile(stray);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();

        var mine = game.Create(alice, stray, Zone.Battlefield);
        var theirs = game.Create(bob, stray, Zone.Battlefield);
        var decoy = game.Create(
            alice,
            Card("Alley Cat Test", string.Empty, CardType.Creature, 1, 1, subtypes: "Cat"),
            Zone.Battlefield);

        // Settled first, so the three arrivals already on the board have had their own triggers
        // and found nobody. A trigger held on the stack while the rest of the board is built up
        // resolves against a board that did not exist when it fired, which is a fact about this
        // test and not about the card.
        Settle(game);
        Assert.Equal(0, Counters(game, mine));

        var arriving = game.Create(alice, stray, Zone.Battlefield);
        Settle(game);

        // "Each other creature you control named ~" is three refusals at once: not the opponent's
        // copy, not a Cat of another name, and not the permanent whose trigger this is.
        Assert.Equal(1, Counters(game, mine));
        Assert.Equal(0, Counters(game, theirs));
        Assert.Equal(0, Counters(game, decoy));
        Assert.Equal(0, Counters(game, arriving));
    }

    private static int Counters(Game game, ObjectId id) =>
        game.State.GetObject(id).Permanent?.Counters.GetValueOrDefault("+1/+1") ?? 0;

    /// <remarks>
    /// The negated form, which is the same test with the answer turned round (CR 201.2c). It is
    /// checked as a *target legality* rather than as an effect, because that is where the printed
    /// clause does its work: a permanent of that name may not be chosen at all.
    /// </remarks>
    [Fact]
    public void A_permanent_not_named_refuses_that_name_and_takes_any_other()
    {
        var conjurer = Card(
            "Clever Conjurer Test",
            "{T}: Untap target permanent not named ~. Activate only as a sorcery.",
            CardType.Creature,
            0,
            3,
            subtypes: "Human");

        var compiled = CardCompiler.Compile(conjurer);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var untap = Assert.Single(compiled.Activated);

        var (game, alice, _) = InMainPhase();
        var mine = game.Create(alice, conjurer, Zone.Battlefield);
        var twin = game.Create(alice, conjurer, Zone.Battlefield);
        var bear = game.Create(alice, TestCards.Creature("Conjured Bear Test", 2, 2), Zone.Battlefield);

        // The ability costs a tap, so it waits out summoning sickness (CR 302.6).
        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber == 3 && game.State.CurrentStep == TurnStep.PrecombatMain);

        game.Tap(bear);
        game.Tap(twin);

        // The other Conjurer is tapped, untapping it would do something, and it is still not a
        // legal target: the clause is about the name and nothing else.
        Assert.Throws<InvalidOperationException>(
            () => game.ActivateAbility(alice, mine, untap.Id, [Target.ToPermanent(twin)]));

        game.ActivateAbility(alice, mine, untap.Id, [Target.ToPermanent(bear)]);
        Settle(game);

        Assert.False(game.State.GetObject(bear).Permanent?.IsTapped);
        Assert.True(game.State.GetObject(twin).Permanent?.IsTapped);
    }

    /// <remarks>
    /// The same name test asked as a *condition* rather than as a count, which is a different
    /// reader reaching the same vocabulary - and the reason the clause is lifted off in one place
    /// instead of taught to each of them.
    /// </remarks>
    [Fact]
    public void A_condition_on_controlling_another_of_the_same_name_is_answered_by_name()
    {
        var miscreant = Card(
            "Faerie Miscreant Test",
            "Flying\nWhen ~ enters, if you control another creature named ~, draw a card.",
            CardType.Creature,
            1,
            1,
            KeywordAbility.Flying,
            "Faerie");

        var compiled = CardCompiler.Compile(miscreant);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();

        // A Faerie of another name and the opponent's own copy: neither is "another creature you
        // control named ~", so the first arrival draws nothing.
        game.Create(
            alice,
            Card("Faerie Squire Test", string.Empty, CardType.Creature, 1, 1, subtypes: "Faerie"),
            Zone.Battlefield);
        game.Create(bob, miscreant, Zone.Battlefield);

        var held = game.State.GetPlayer(alice).Hand.Count;
        game.Create(alice, miscreant, Zone.Battlefield);
        Settle(game);

        Assert.Equal(held, game.State.GetPlayer(alice).Hand.Count);

        // A second copy of Alice's own, and now the condition is met.
        game.Create(alice, miscreant, Zone.Battlefield);
        Settle(game);

        Assert.Equal(held + 1, game.State.GetPlayer(alice).Hand.Count);
    }

    // ---- "Target artifact or enchantment" (CR 109.4) -------------------------

    [Fact]
    public void A_compound_target_accepts_either_type_and_not_a_third()
    {
        var disenchant = Card(
            "Disenchant Test",
            "Destroy target artifact or enchantment.",
            CardType.Instant);

        var compiled = CardCompiler.Compile(disenchant);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var relic = game.Create(bob, Card("Struck Relic Test", string.Empty, CardType.Artifact), Zone.Battlefield);
        var ward = game.Create(bob, Card("Struck Ward Test", string.Empty, CardType.Enchantment), Zone.Battlefield);
        var bear = game.Create(bob, TestCards.Creature("Spared Bear Test", 2, 2), Zone.Battlefield);

        // Either of the two named types is legal - the list is alternatives, not a permanent
        // that has to be both at once.
        var first = TestCards.PutInHand(game, alice, disenchant);
        game.CastSpell(alice, first, [Target.ToPermanent(relic)]);
        Settle(game);

        var second = TestCards.PutInHand(game, alice, disenchant);
        game.CastSpell(alice, second, [Target.ToPermanent(ward)]);
        Settle(game);

        Assert.Equal(2, game.State.GetPlayer(bob).Graveyard.Count);

        // And a third type is not.
        var third = TestCards.PutInHand(game, alice, disenchant);
        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, third, [Target.ToPermanent(bear)]));
    }

    [Fact]
    public void Two_adjectives_on_one_target_both_have_to_hold()
    {
        // The grammar had room for exactly one adjective, so a card naming two was refused
        // whole. Reading only the last one would have been worse than refusing: the card would
        // have compiled and then allowed a target its text forbids.
        var terror = Card(
            "Terror Test",
            "Destroy target nonartifact, nonblack creature.",
            CardType.Instant);

        var compiled = CardCompiler.Compile(terror);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var golem = game.Create(
            bob,
            Card("Spared Golem Test", string.Empty, CardType.Artifact | CardType.Creature, 2, 2),
            Zone.Battlefield);

        var zombie = game.Create(bob, Coloured("Spared Zombie Test", ManaColor.Black), Zone.Battlefield);
        var bear = game.Create(bob, TestCards.Creature("Struck Bear Test", 2, 2), Zone.Battlefield);

        // Each adjective refuses on its own account: the artifact fails the first, the black
        // creature the second. Either alone would have been legal had only the other been read.
        var atArtifact = TestCards.PutInHand(game, alice, terror);
        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, atArtifact, [Target.ToPermanent(golem)]));

        var atBlack = TestCards.PutInHand(game, alice, terror);
        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, atBlack, [Target.ToPermanent(zombie)]));

        // And the creature that is neither is destroyed.
        var atBear = TestCards.PutInHand(game, alice, terror);
        game.CastSpell(alice, atBear, [Target.ToPermanent(bear)]);
        Settle(game);

        Assert.Contains(
            game.State.GetPlayer(bob).Graveyard,
            id => game.State.Objects[id].Card.Name == "Struck Bear Test");

        Assert.Equal(2, game.State.Battlefield.Count);
    }

    [Fact]
    public void An_aura_that_enchants_a_land_may_not_be_put_on_a_creature()
    {
        // The subject used to collapse to "any permanent" for everything except creature, so an
        // Aura reading "enchant land" would go on a creature quite happily.
        var overgrowth = Card(
            "Land Aura Test",
            "Enchant land\nEnchanted land has \"{T}: Add {G}.\"",
            CardType.Enchantment,
            subtypes: "Aura");

        var (game, alice, _) = InMainPhase();
        var bear = game.Create(alice, TestCards.Creature("Unenchantable Bear Test", 2, 2), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, overgrowth);

        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, card, [Target.ToPermanent(bear)]));
    }

    // ---- No maximum hand size (CR 402.2) -------------------------------------

    [Fact]
    public void A_permanent_that_removes_the_hand_limit_removes_it_for_its_controller_only()
    {
        var reliquary = Card(
            "Reliquary Test",
            "You have no maximum hand size.",
            CardType.Artifact);

        var compiled = CardCompiler.Compile(reliquary);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, reliquary, Zone.Battlefield);

        for (var i = 0; i < 12; i++)
        {
            TestCards.PutInHand(game, alice, TestCards.Creature($"Alice Card {i} Test", 1, 1));
            TestCards.PutInHand(game, bob, TestCards.Creature($"Bob Card {i} Test", 1, 1));
        }

        var aliceHeld = game.State.GetPlayer(alice).Hand.Count;

        // Through Alice's cleanup and into Bob's turn.
        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber == 2 && game.State.CurrentStep == TurnStep.PrecombatMain);

        // Alice keeps every card; the limit is gone, not raised.
        Assert.Equal(aliceHeld, game.State.GetPlayer(alice).Hand.Count);

        // And it is hers alone - Bob still discards to seven at his own cleanup.
        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber == 3 && game.State.CurrentStep == TurnStep.PrecombatMain);

        Assert.Equal(7, game.State.GetPlayer(bob).Hand.Count);
    }

    // ---- Choosing a card in your graveyard (CR 609.4) ------------------------

    [Fact]
    public void An_untargeted_graveyard_return_chooses_on_resolution_and_is_filtered()
    {
        var raise = Card(
            "Unearthed Choice Test",
            "Return a creature card from your graveyard to your hand.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(raise);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        // "A creature card", not "target creature card": nothing is chosen as the spell is cast,
        // so there is no target for hexproof or a counterspell to argue with.
        Assert.Empty(compiled.Spell!.Targets);

        var (game, alice, bob) = InMainPhase();

        // A land first, so a chooser that ignored the filter would take it - the harness answers
        // with the first option it is offered.
        game.Create(alice, TestCards.BasicLand("Dead Forest Test"), Zone.Graveyard);
        game.Create(alice, TestCards.Creature("Dead Bear Test", 2, 2), Zone.Graveyard);

        // And a creature in the opponent's graveyard, which is not "your graveyard".
        game.Create(bob, TestCards.Creature("Enemy Corpse Test", 2, 2), Zone.Graveyard);

        var card = TestCards.PutInHand(game, alice, raise);
        game.CastSpell(alice, card, []);
        Settle(game);

        Assert.Contains(
            game.State.GetPlayer(alice).Hand,
            id => game.State.GetObject(id).Card.Name == "Dead Bear Test");

        Assert.Contains(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Dead Forest Test");

        Assert.Contains(
            game.State.GetPlayer(bob).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Enemy Corpse Test");
    }

    // ---- A token with a name of its own (CR 111.4) ---------------------------

    /// <summary>
    /// A token the card names arrives under that name, carrying what it was given.
    /// </summary>
    /// <remarks>
    /// The whole difficulty of this family is that a name is not a type. Everywhere else in the
    /// compiler a capitalised word beside a type line <em>is</em> a subtype - that is how
    /// "Soldier" is found in "a 1/1 white Soldier creature token" with no vocabulary of type
    /// names anywhere - and the name a card prints for its token stands in exactly that
    /// position. This engine has been bitten seven times by a capitalised word read as a type;
    /// "all Mountains are Plains" once compiled to a lord for the creature type Mountain,
    /// complete, played, and matching nothing at all.
    /// <para>
    /// So the assertion below is deliberately two-sided: the token has to be <em>called</em>
    /// Llanowar Elves, and it has to be a Elf Druid and not a "Llanowar Elves".
    /// </para>
    /// </remarks>
    [Fact]
    public void A_token_the_card_names_arrives_under_that_name_and_the_name_is_not_a_type()
    {
        var mentor = Card(
            "Named Token Mentor Test",
            "Create a 1/1 green Elf Druid creature token named Llanowar Elves. "
                + "It has \"{T}: Add {G}.\"",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(mentor);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        game.CastSpell(alice, TestCards.PutInHand(game, alice, mentor), []);
        Settle(game);

        var token = game.State.Battlefield
            .Select(game.State.GetObject)
            .Single(o => o.Card.CardTypes.HasFlag(CardType.Token));

        // The name the card printed, and nothing else standing in for it. Before this the token
        // was called "Elf Druid" - the subtypes joined together - which is the name of no card
        // anybody has printed.
        Assert.Equal("Llanowar Elves", token.Card.Name);

        // And the name went nowhere near the type line.
        Assert.Equal(["Elf", "Druid"], token.Card.Subtypes);
        Assert.DoesNotContain("Llanowar Elves", token.Card.Subtypes);

        // The ability printed as its own sentence after the token reached it, which it could not
        // before: the sentence that folds the two together stopped at the word "token", and every
        // token with a name had its ability behind the name.
        Assert.NotEmpty(Pool.ActivatedOf(token.Card));
    }

    /// <summary>
    /// Two cards printing the same token under two names make two different cards.
    /// </summary>
    /// <remarks>
    /// The control for the test above, and the reason the name has to reach the id. A token
    /// <em>is</em> a card definition and <c>CompiledPool</c> serves abilities by id, so two
    /// definitions sharing an id would have one card's token behaviour served for the other -
    /// silently, because both are the right size and colour on the board.
    /// </remarks>
    [Fact]
    public void A_differently_named_token_is_a_different_card_and_keeps_its_own_ability()
    {
        var mentor = Card(
            "Named Token Elves Test",
            "Create a 1/1 green Elf Druid creature token named Llanowar Elders. "
                + "It has \"{T}: Add {G}.\"",
            CardType.Sorcery);

        var lookout = Card(
            "Named Token Harrier Test",
            "Create a 1/1 white Kithkin Soldier creature token named Goldmeadow Harrier. "
                + "It has \"{W}, {T}: Tap target creature.\"",
            CardType.Sorcery);

        Assert.True(CardCompiler.Compile(lookout).IsComplete);

        var (game, alice, _) = InMainPhase();
        game.CastSpell(alice, TestCards.PutInHand(game, alice, mentor), []);
        Settle(game);
        game.CastSpell(alice, TestCards.PutInHand(game, alice, lookout), []);
        Settle(game);

        var tokens = game.State.Battlefield
            .Select(game.State.GetObject)
            .Where(o => o.Card.CardTypes.HasFlag(CardType.Token))
            .ToList();

        Assert.Equal(2, tokens.Count);

        var elder = tokens.Single(o => o.Card.Name == "Llanowar Elders");
        var harrier = tokens.Single(o => o.Card.Name == "Goldmeadow Harrier");

        // Two names, two ids, two sets of abilities. Equal ids here would be the pool serving one
        // card's token for the other, which is the failure this whole family is prone to.
        Assert.NotEqual(elder.Card.OracleId, harrier.Card.OracleId);

        // The Harrier's ability wants a target and the Elder's does not, so an ability served
        // from the wrong definition would be visible here rather than merely wrong.
        Assert.Empty(Pool.ActivatedOf(elder.Card)[0].Targets);
        Assert.NotEmpty(Pool.ActivatedOf(harrier.Card)[0].Targets);
    }

    /// <summary>
    /// A name that cannot be told from a type leaves the line unread.
    /// </summary>
    /// <remarks>
    /// The fail-closed half of the rule above. Handed to
    /// <see cref="SearchFilters.Matches(string, CardDefinition)"/> - the reader that decides what a capitalised word in a
    /// filter means - "Elf" answers as the subtype, so nothing downstream could tell the name
    /// from the type and the sentence is refused rather than compiled into whichever reading
    /// happened to win. No printed card names a token after its own creature type, so this costs
    /// nothing and holds the line for the day one does.
    /// </remarks>
    [Fact]
    public void A_token_name_that_cannot_be_told_from_a_type_leaves_the_line_unread()
    {
        var collides = Card(
            "Colliding Name Test",
            "Create a 1/1 green Elf creature token named Elf.",
            CardType.Sorcery);

        Assert.False(CardCompiler.Compile(collides).IsComplete);

        // And the same sentence with a name no type answers to reads perfectly, so the refusal
        // above is about the collision and not about the shape of the sentence.
        var distinct = Card(
            "Distinct Name Test",
            "Create a 1/1 green Elf creature token named Elfhame Courier.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(distinct);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
    }

    /// <summary>
    /// A legendary token the card names is held to one by its name, not by its type.
    /// </summary>
    /// <remarks>
    /// The name-first spelling - "create Marit Lage, a legendary 20/20 black Avatar creature
    /// token" - and the strongest control this family has. CR 704.5j groups by <em>name</em>, so
    /// two Marit Lages cannot both stay while a Marit Lage and a differently named Avatar can:
    /// the two tokens below share every printed characteristic except the name, so an engine
    /// matching on the type line would bin one of the second pair too.
    /// </remarks>
    [Fact]
    public void Two_tokens_of_one_name_meet_the_legend_rule_and_two_names_do_not()
    {
        var depths = Card(
            "Named Legend Depths Test",
            "Create Marit Lage, a legendary 20/20 black Avatar creature token with flying "
                + "and indestructible.",
            CardType.Sorcery);

        // The same token under another name. Same size, same colour, same subtype, same
        // keywords - only the name differs, which is the whole of what the control tests.
        var stage = Card(
            "Named Legend Stage Test",
            "Create Thespian Shade, a legendary 20/20 black Avatar creature token with flying "
                + "and indestructible.",
            CardType.Sorcery);

        Assert.True(CardCompiler.Compile(depths).IsComplete);
        Assert.True(CardCompiler.Compile(stage).IsComplete);

        var (game, alice, _) = InMainPhase();

        game.CastSpell(alice, TestCards.PutInHand(game, alice, depths), []);
        Settle(game);

        var made = game.State.Battlefield
            .Select(game.State.GetObject)
            .Single(o => o.Card.CardTypes.HasFlag(CardType.Token));

        Assert.Equal("Marit Lage", made.Card.Name);
        Assert.Contains("Legendary", made.Card.Supertypes);
        Assert.Equal(["Avatar"], made.Card.Subtypes);
        Assert.True(
            Characteristics.Of(game.State, Pool, made).Has(KeywordAbility.Indestructible));

        // A second one of the same name. Settle answers the legend rule with the first option it
        // is offered, so one of the two is in the graveyard by the time it returns.
        game.CastSpell(alice, TestCards.PutInHand(game, alice, depths), []);
        Settle(game);

        Assert.Single(
            game.State.Battlefield,
            id => game.State.GetObject(id).Card.Name == "Marit Lage");

        // The control. The Shade shares everything with the Lage except its name, and both stay.
        game.CastSpell(alice, TestCards.PutInHand(game, alice, stage), []);
        Settle(game);

        Assert.Single(
            game.State.Battlefield,
            id => game.State.GetObject(id).Card.Name == "Marit Lage");

        Assert.Single(
            game.State.Battlefield,
            id => game.State.GetObject(id).Card.Name == "Thespian Shade");
    }

    /// <summary>
    /// A named Equipment token is an artifact that can actually be attached.
    /// </summary>
    /// <remarks>
    /// The noncreature half of the family, where the name is the <em>whole</em> description: the
    /// card prints no size and no creature type, so the reader that finds a token's name in its
    /// subtypes had nothing to work with and the sentence went unread. And the equip cost is not
    /// decoration - an Equipment that cannot be attached is an artifact that does nothing, which
    /// is the direction this compiler must never fail in.
    /// </remarks>
    [Fact]
    public void A_named_equipment_token_is_no_creature_and_can_be_equipped()
    {
        var blacksmith = Card(
            "Named Equipment Test",
            "When ~ enters, create a colorless Equipment artifact token named Hill Axe with "
                + "\"Equipped creature gets +1/+0\" and equip {2}.",
            CardType.Creature, 2, 2);

        var compiled = CardCompiler.Compile(blacksmith);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        game.Create(alice, blacksmith, Zone.Battlefield);
        var bearer = game.Create(alice, TestCards.Creature("Axe Bearer Test", 2, 2), Zone.Battlefield);
        Settle(game);

        var axe = game.State.Battlefield
            .Single(id => game.State.GetObject(id).Card.Name == "Hill Axe");

        var made = game.State.GetObject(axe).Card;

        // An artifact and an Equipment, and emphatically not a creature: read through the
        // creature reader instead it would have been a 0/0 that the state-based actions bin the
        // moment it arrives.
        Assert.True(made.CardTypes.HasFlag(CardType.Artifact));
        Assert.False(made.CardTypes.HasFlag(CardType.Creature));
        Assert.Equal(["Equipment"], made.Subtypes);
        Assert.Null(made.Power);

        foreach (var _ in Enumerable.Range(0, 2))
        {
            var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
            game.ActivateAbility(alice, forest, "mana");
        }

        game.ActivateAbility(alice, axe, "equip", [Target.ToPermanent(bearer)]);
        Settle(game);

        Assert.Equal(3, Characteristics.Of(game.State, Pool, game.State.GetObject(bearer)).Power);
    }

    // ---- Choosing from a revealed hand (CR 701.16) ---------------------------

    [Fact]
    public void A_typed_hand_choice_offers_only_cards_of_that_type()
    {
        // The filter used to live inside the prompt, and the engine decided what a player could
        // pick by looking for the substring "nonland" in the sentence it was about to show them.
        // Every other kind quietly offered the whole hand.
        var grief = Card(
            "Grief Test",
            "Target opponent reveals their hand. You choose an instant or sorcery card from "
                + "it. That player discards that card.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(grief);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();

        TestCards.PutInHand(game, bob, TestCards.Creature("Held Bear Test", 2, 2));
        TestCards.PutInHand(game, bob, TestCards.BasicLand("Held Forest Test"));
        TestCards.PutInHand(
            game,
            bob,
            Card("Held Bolt Test", "~ deals 1 damage to any target.", CardType.Instant));

        var card = TestCards.PutInHand(game, alice, grief);
        game.CastSpell(alice, card, [Target.ToPlayer(bob)]);
        Settle(game);

        // The creature and the land went into Bob's hand first, and Settle answers with the
        // first option it is offered - so a chooser that ignored the kind would have taken one
        // of them. Only the instant is eligible, and only the instant is gone.
        Assert.Contains(
            game.State.GetPlayer(bob).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Held Bolt Test");

        Assert.Contains(
            game.State.GetPlayer(bob).Hand,
            id => game.State.GetObject(id).Card.Name == "Held Bear Test");

        Assert.Contains(
            game.State.GetPlayer(bob).Hand,
            id => game.State.GetObject(id).Card.Name == "Held Forest Test");
    }

    // ---- Half a fight (CR 701.12a) -------------------------------------------

    [Fact]
    public void A_one_way_fight_deals_no_damage_back()
    {
        var bite = Card(
            "Bite Down Test",
            "Target creature you control deals damage equal to its power to target creature "
                + "you don't control.",
            CardType.Instant);

        var compiled = CardCompiler.Compile(bite);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.Equal(2, compiled.Spell!.Targets.Count);

        var (game, alice, bob) = InMainPhase();
        var mine = game.Create(alice, TestCards.Creature("Biter Test", 3, 3), Zone.Battlefield);
        var theirs = game.Create(bob, TestCards.Creature("Bitten Test", 2, 4), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, bite);
        game.CastSpell(alice, card, [Target.ToPermanent(mine), Target.ToPermanent(theirs)]);
        Settle(game);

        // Three to theirs, and nothing back. A fight would have marked two on mine, which is the
        // whole difference between these cards and the ones that say "fights".
        Assert.Equal(3, game.State.GetObject(theirs).Permanent?.DamageMarked);
        Assert.Equal(0, game.State.GetObject(mine).Permanent?.DamageMarked);
    }

    // ---- "Its controller ..." (CR 608.2) -------------------------------------

    [Fact]
    public void Its_controller_finds_the_same_player_for_a_draw_as_for_a_life_loss()
    {
        // Both verbs go through one clause reader and one ownership lookup. The case worth
        // pinning is the one that made the lookup worth sharing: the target is gone by the time
        // the clause runs - destroyed a sentence earlier - and is a card in a graveyard under a
        // new id (CR 400.7). Whose it was is still a fact about the game.
        var drain = Card(
            "Controller Drain Test",
            "Destroy target creature. Its controller loses 2 life.",
            CardType.Sorcery);

        var gift = Card(
            "Controller Gift Test",
            "Destroy target creature. Its controller draws 1 card.",
            CardType.Sorcery);

        Assert.True(CardCompiler.Compile(drain).IsComplete);

        var compiled = CardCompiler.Compile(gift);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var theirs = game.Create(bob, TestCards.Creature("Drained Bear Test", 2, 2), Zone.Battlefield);

        var first = TestCards.PutInHand(game, alice, drain);
        game.CastSpell(alice, first, [Target.ToPermanent(theirs)]);
        Settle(game);

        Assert.Equal(18, game.State.GetPlayer(bob).Life);

        var other = game.Create(bob, TestCards.Creature("Gifted Bear Test", 2, 2), Zone.Battlefield);
        var before = game.State.GetPlayer(bob).Hand.Count;

        var second = TestCards.PutInHand(game, alice, gift);
        game.CastSpell(alice, second, [Target.ToPermanent(other)]);
        Settle(game);

        // Bob draws, not Alice: it is the destroyed creature's controller and not the caster.
        Assert.Equal(before + 1, game.State.GetPlayer(bob).Hand.Count);
    }

    // ---- A filter that asks the board, not the print (CR 613) ----------------

    /// <summary>
    /// "By creatures with flying" catches a creature an Aura just gave wings (CR 702.9a).
    /// </summary>
    /// <remarks>
    /// The whole of this section in one card. A filter id is a string asked of a
    /// <see cref="CardDefinition"/> everywhere in this compiler, and for a search, a hand filter
    /// or a count of a graveyard that is exactly right — a card in those zones has only what is
    /// printed on it. For a permanent it is wrong, and silently: the creature under the Aura has
    /// flying by CR 613 layer 6 and its card does not say so, so a shield reading the print
    /// prevents nothing at all.
    /// <para>
    /// The control is the second attacker in the same combat, under the same shield, with the
    /// same printed card and no Aura. Nothing but the granted keyword separates the two, so a
    /// filter that had gone back to reading the print would show both unprevented and one that
    /// answered "yes" to everything would show both prevented.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_fog_on_creatures_with_flying_catches_one_an_aura_gave_wings()
    {
        var fog = Card(
            "Wing Fog Test",
            "Prevent all combat damage that would be dealt this turn by creatures with flying.");

        var compiled = CardCompiler.Compile(fog);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var wings = Card(
            "Fog Wings Test",
            "Enchant creature" + (char)10 + "Enchanted creature has flying.",
            CardType.Enchantment, subtypes: "Aura");

        Assert.True(CardCompiler.Compile(wings).IsComplete);

        var (game, alice, bob) = InMainPhase();
        var winged = game.Create(
            alice, TestCards.Creature("Winged Ox Test", 2, 6), Zone.Battlefield);
        var grounded = game.Create(
            alice, TestCards.Creature("Grounded Ox Test", 3, 6), Zone.Battlefield);

        PassTo(game, 3, TurnStep.PrecombatMain);

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, wings), [Target.ToPermanent(winged)]);
        ResolveStack(game);

        // The keyword is granted rather than printed, which is the entire point of the test.
        Assert.True(
            Characteristics.Of(game.State, Pool, game.State.GetObject(winged))
                .Has(KeywordAbility.Flying));

        Assert.False(game.State.GetObject(grounded).Card.Keywords.HasFlag(KeywordAbility.Flying));

        game.CastSpell(alice, TestCards.PutInHand(game, alice, fog), targets: null);
        ResolveStack(game);

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget>
            {
                [winged] = AttackTarget.Player(bob),
                [grounded] = AttackTarget.Player(bob),
            });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Settle(game);

        // Three from the grounded ox and nothing from the winged one: 20 - 3. Reading the print
        // would let both through and leave Bob on 15.
        Assert.Equal(17, game.State.GetPlayer(bob).Life);
    }

    /// <summary>
    /// "By creatures with power 4 or less" reads the pumped size, not the printed one (CR 613.4).
    /// </summary>
    /// <remarks>
    /// Vine Snare. The number in the corner of the card is the value layer 7a starts from and not
    /// the answer, so this is the arm that a printed reading gets wrong in the direction that
    /// matters: a 2/2 pumped to 5/5 is exactly the creature the shield is not supposed to stop.
    /// <para>
    /// Both attackers print 2/2 and only one of them has been pumped, so the two assertions below
    /// cannot both hold unless the bound is being asked of the board.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_fog_on_power_four_or_less_lets_a_pumped_two_two_through()
    {
        var snare = Card(
            "Snare Fog Test",
            "Prevent all combat damage that would be dealt this turn by creatures with "
                + "power 4 or less.");

        var compiled = CardCompiler.Compile(snare);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var growth = Card("Snare Growth Test", "Target creature gets +3/+3 until end of turn.");
        Assert.True(CardCompiler.Compile(growth).IsComplete);

        var (game, alice, bob) = InMainPhase();
        var pumped = game.Create(
            alice, TestCards.Creature("Snare Runt Test", 2, 2), Zone.Battlefield);
        var small = game.Create(
            alice, TestCards.Creature("Snare Whelp Test", 2, 2), Zone.Battlefield);

        PassTo(game, 3, TurnStep.PrecombatMain);

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, growth), [Target.ToPermanent(pumped)]);
        ResolveStack(game);

        Assert.Equal(
            5, Characteristics.Of(game.State, Pool, game.State.GetObject(pumped)).Power);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, snare), targets: null);
        ResolveStack(game);

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget>
            {
                [pumped] = AttackTarget.Player(bob),
                [small] = AttackTarget.Player(bob),
            });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Settle(game);

        // Five from the pumped one, nothing from the 2/2 that still answers the bound. A printed
        // reading prevents both and leaves Bob on 20.
        Assert.Equal(15, game.State.GetPlayer(bob).Life);
    }

    /// <summary>
    /// "By creatures with no +1/+1 counters on them" counts what is on the permanent (CR 122.1).
    /// </summary>
    /// <remarks>
    /// Hindervines, and the one quality in this family that no card can ever carry: counters exist
    /// only on the battlefield, so the printed answer is not merely stale, there is nothing there
    /// to read. A filter asked of the card says "no counters" about every creature in the game.
    /// <para>
    /// The negation is the other half of it. "With no X" and "without X" are one meaning printed
    /// two ways and both come out as the vocabulary's own "non" prefix, so the counted creature
    /// must be the one the shield lets through.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_fog_on_creatures_with_no_counters_lets_the_counted_creature_through()
    {
        var vines = Card(
            "Vine Fog Test",
            "Prevent all combat damage that would be dealt this turn by creatures with "
                + "no +1/+1 counters on them.");

        var compiled = CardCompiler.Compile(vines);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var counter = Card("Vine Counter Test", "Put a +1/+1 counter on target creature.");
        Assert.True(CardCompiler.Compile(counter).IsComplete);

        var (game, alice, bob) = InMainPhase();
        var counted = game.Create(
            alice, TestCards.Creature("Vine Adder Test", 2, 2), Zone.Battlefield);
        var bare = game.Create(
            alice, TestCards.Creature("Vine Serpent Test", 2, 2), Zone.Battlefield);

        PassTo(game, 3, TurnStep.PrecombatMain);

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, counter), [Target.ToPermanent(counted)]);
        ResolveStack(game);

        Assert.Equal(
            1,
            game.State.GetObject(counted).Permanent!.Counters.GetValueOrDefault("+1/+1"));

        game.CastSpell(alice, TestCards.PutInHand(game, alice, vines), targets: null);
        ResolveStack(game);

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget>
            {
                [counted] = AttackTarget.Player(bob),
                [bare] = AttackTarget.Player(bob),
            });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Settle(game);

        // Three from the creature carrying a counter, nothing from the one without.
        Assert.Equal(17, game.State.GetPlayer(bob).Life);
    }

    /// <summary>
    /// A card in a library still answers the printed question (CR 613 orders permanents).
    /// </summary>
    /// <remarks>
    /// The other half of the two-form answer, and the reason the printed overload was kept rather
    /// than replaced. A search is not a question about the board: no continuous effect reaches a
    /// card in a library, so what is printed on it <em>is</em> what it has. The same filter id
    /// that reads a granted keyword off a permanent has to read the printed one here, and a
    /// counter — which only a permanent can carry — has to answer "none".
    /// </remarks>
    [Fact]
    public void The_same_filter_answers_a_library_card_from_its_print()
    {
        var flier = Card(
            "Printed Flier Test", string.Empty, CardType.Creature,
            power: 2, toughness: 2, keywords: KeywordAbility.Flying);

        var ground = Card(
            "Printed Walker Test", string.Empty, CardType.Creature, power: 2, toughness: 2);

        Assert.True(SearchFilters.Matches("creature&keyword:flying", flier));
        Assert.False(SearchFilters.Matches("creature&keyword:flying", ground));

        // The bound is the printed number, because that is the only number a card in a library
        // has (CR 613.4 modifies permanents).
        Assert.True(SearchFilters.Matches("creature&power<=4", ground));
        Assert.False(SearchFilters.Matches("creature&power>=4", ground));

        // No counters anywhere but the battlefield, so "with no +1/+1 counters" is true of every
        // card in a library and "with a +1/+1 counter" is true of none.
        Assert.True(SearchFilters.Matches("creature&noncounter:+1/+1", ground));
        Assert.False(SearchFilters.Matches("creature&counter:+1/+1", ground));
    }

    // ---- Flicker (CR 400.7) --------------------------------------------------

    [Fact]
    public void A_flickered_permanent_comes_back_as_a_new_object()
    {
        var watcher = Card(
            "Flicker Watcher Test",
            "When ~ enters, you gain 1 life.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var blur = Card(
            "Blur Test",
            "Exile target creature you control, then return that card to the battlefield "
                + "under its owner's control.",
            CardType.Instant);

        var compiled = CardCompiler.Compile(blur);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var before = game.Create(alice, watcher, Zone.Battlefield);
        Settle(game);

        Assert.Equal(21, game.State.GetPlayer(alice).Life);

        game.ChangeCounters(before, CounterKinds.PlusOnePlusOne, 2);
        Assert.Equal(4, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(before)));

        var card = TestCards.PutInHand(game, alice, blur);
        game.CastSpell(alice, card, [Target.ToPermanent(before)]);
        Settle(game);

        // It entered again, so the enters trigger fired again. That is the whole reason these
        // cards are played.
        Assert.Equal(22, game.State.GetPlayer(alice).Life);

        var after = game.State.Battlefield.Select(game.State.GetObject)
            .Single(o => o.Card.Name == "Flicker Watcher Test");

        // A different object (CR 400.7), and it kept nothing: the counters are gone with the
        // identity that had them.
        Assert.NotEqual(before, after.Id);
        Assert.Equal(2, Characteristics.PowerOf(game.State, Pool, after));
    }

    // ---- Two damages in one sentence (CR 601.2c) -----------------------------

    [Fact]
    public void A_spell_that_hurts_you_too_does_not_target_you()
    {
        var recoil = Card(
            "Backfire Bolt Test",
            "~ deals 3 damage to any target and 2 damage to you.",
            CardType.Instant);

        var compiled = CardCompiler.Compile(recoil);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        // One target, not two. A spell that damages you does not target you, and reading it as
        // a target would let the damage be redirected or the spell be countered for it.
        Assert.Single(compiled.Spell!.Targets);

        var (game, alice, bob) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, recoil);

        game.CastSpell(alice, card, [Target.ToPlayer(bob)]);
        Settle(game);

        Assert.Equal(17, game.State.GetPlayer(bob).Life);
        Assert.Equal(18, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void A_spell_with_two_targets_deals_each_of_them_its_own_amount()
    {
        var arc = Card(
            "Arc Trail Test",
            "~ deals 2 damage to target creature and 1 damage to target player or planeswalker.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(arc);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.Equal(2, compiled.Spell!.Targets.Count);

        var (game, alice, bob) = InMainPhase();
        var creature = game.Create(bob, TestCards.Creature("Arc Bear Test", 3, 3), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, arc);
        game.CastSpell(alice, card, [Target.ToPermanent(creature), Target.ToPlayer(bob)]);
        Settle(game);

        // Two and one, in that order - not two and two, and not one and two.
        Assert.Equal(2, game.State.GetObject(creature).Permanent?.DamageMarked);
        Assert.Equal(19, game.State.GetPlayer(bob).Life);
    }

    // ---- Damage divided as you choose (CR 601.2d) ----------------------------

    [Fact]
    public void Divided_damage_is_announced_as_the_spell_is_cast_and_dealt_as_announced()
    {
        var arrows = Card(
            "Forked Arrows Test",
            "~ deals 3 damage divided as you choose among one, two, or three targets.",
            CardType.Instant);

        var compiled = CardCompiler.Compile(arrows);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        // Three slots, and only the first is required - "one, two, or three" is at least one
        // and at most three.
        Assert.Equal(3, compiled.Spell!.Targets.Count);
        Assert.False(compiled.Spell.Targets[0].Optional);
        Assert.True(compiled.Spell.Targets[1].Optional);

        var (game, alice, bob) = InMainPhase();
        var first = game.Create(bob, TestCards.Creature("Struck One Test", 1, 1), Zone.Battlefield);
        var second = game.Create(bob, TestCards.Creature("Struck Two Test", 3, 3), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, arrows);
        game.CastSpell(
            alice,
            card,
            [Target.ToPermanent(first), Target.ToPermanent(second)],
            damageDivision: [1, 2]);

        Settle(game);

        // The 1/1 took its 1 and died; the 3/3 took 2 and lived. Both amounts came from the
        // announcement, and neither creature took the whole three.
        Assert.Contains(
            game.State.GetPlayer(bob).Graveyard.Select(game.State.GetObject),
            o => o.Card.Name == "Struck One Test");

        var survivor = game.State.Battlefield.Select(game.State.GetObject)
            .Single(o => o.Card.Name == "Struck Two Test");

        Assert.Equal(2, survivor.Permanent?.DamageMarked);
    }

    [Fact]
    public void A_divided_spell_refuses_a_division_that_does_not_add_up()
    {
        var arrows = Card(
            "Careless Arrows Test",
            "~ deals 3 damage divided as you choose among one, two, or three targets.",
            CardType.Instant);

        var (game, alice, bob) = InMainPhase();
        var first = game.Create(bob, TestCards.Creature("Spared One Test", 2, 2), Zone.Battlefield);
        var second = game.Create(bob, TestCards.Creature("Spared Two Test", 2, 2), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, arrows);

        // Two chosen and only two damage between them: the spell deals three and the announcement
        // has to spend all of it (CR 601.2d).
        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(
                alice,
                card,
                [Target.ToPermanent(first), Target.ToPermanent(second)],
                damageDivision: [1, 1]));

        // And a target given nothing is a target that should not have been chosen - which is how
        // you would aim a divided spell at one creature while appearing to spread it.
        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(
                alice,
                card,
                [Target.ToPermanent(first), Target.ToPermanent(second)],
                damageDivision: [3, 0]));
    }

    // ---- Searching more than one zone (CR 701.23a) ---------------------------

    /// <summary>
    /// "Search your library or graveyard for a card named ~" with the card in the graveyard.
    /// </summary>
    /// <remarks>
    /// A search normally takes one zone, and every part of the machinery was written around that:
    /// the candidates came from one list, the shuffle at the end was unconditional, and the
    /// request carried one player. The graveyard half is the half that proves the zone list is
    /// read rather than ignored - a compiler that dropped the extra zone would still pass a test
    /// where the card was in the library.
    /// </remarks>
    [Fact]
    public void A_two_zone_search_takes_the_card_out_of_the_graveyard()
    {
        var sought = Card("Sought Rune Test", string.Empty, CardType.Artifact);
        var spared = Card("Spared Rune Test", string.Empty, CardType.Artifact);

        var summoner = Card(
            "Rune Summoner Test",
            "When ~ enters, search your library or graveyard for a card named Sought Rune Test, "
                + "reveal it, and put it into your hand. If you search your library this way, "
                + "shuffle.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var compiled = CardCompiler.Compile(summoner);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();

        game.Create(alice, sought, Zone.Graveyard);

        // The control, in both searched zones: same artifact, different name. A search that read
        // the zone list and lost the filter would have offered it first.
        game.Create(alice, spared, Zone.Graveyard);
        game.Create(alice, spared, Zone.Library);

        game.Create(alice, summoner, Zone.Battlefield);
        Settle(game);

        // It left the graveyard...
        Assert.DoesNotContain(
            game.State.GetPlayer(alice).Graveyard.Select(game.State.GetObject),
            o => o.Card.Name == "Sought Rune Test");

        // ...and arrived in hand.
        Assert.Contains(
            game.State.GetPlayer(alice).Hand.Select(game.State.GetObject),
            o => o.Card.Name == "Sought Rune Test");

        // The control stayed where it was put, in both zones.
        Assert.Contains(
            game.State.GetPlayer(alice).Graveyard.Select(game.State.GetObject),
            o => o.Card.Name == "Spared Rune Test");

        Assert.DoesNotContain(
            game.State.GetPlayer(alice).Hand.Select(game.State.GetObject),
            o => o.Card.Name == "Spared Rune Test");
    }

    /// <summary>The same card with the same wording, found in the library instead.</summary>
    /// <remarks>
    /// The other half of the union, and it is a separate test rather than a second assertion
    /// because the two failures look nothing alike: a zone list read as "graveyard only" passes
    /// the test above and fails this one.
    /// </remarks>
    [Fact]
    public void The_same_two_zone_search_takes_the_card_out_of_the_library()
    {
        var sought = Card("Sought Rune Test", string.Empty, CardType.Artifact);
        var spared = Card("Spared Rune Test", string.Empty, CardType.Artifact);

        var summoner = Card(
            "Rune Summoner Test",
            "When ~ enters, search your library or graveyard for a card named Sought Rune Test, "
                + "reveal it, and put it into your hand. If you search your library this way, "
                + "shuffle.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var (game, alice, _) = InMainPhase();

        game.Create(alice, sought, Zone.Library);
        game.Create(alice, spared, Zone.Library);
        game.Create(alice, spared, Zone.Graveyard);

        var libraryBefore = game.State.GetPlayer(alice).Library.Count;

        game.Create(alice, summoner, Zone.Battlefield);
        Settle(game);

        Assert.Contains(
            game.State.GetPlayer(alice).Hand.Select(game.State.GetObject),
            o => o.Card.Name == "Sought Rune Test");

        // One card fewer in the library, and the one that left is the one it was told to find.
        Assert.Equal(libraryBefore - 1, game.State.GetPlayer(alice).Library.Count);

        Assert.DoesNotContain(
            game.State.GetPlayer(alice).Library.Select(game.State.GetObject),
            o => o.Card.Name == "Sought Rune Test");

        Assert.Contains(
            game.State.GetPlayer(alice).Library.Select(game.State.GetObject),
            o => o.Card.Name == "Spared Rune Test");
    }

    /// <summary>
    /// "Search your graveyard, hand, or library for a card named ~" with the card in hand.
    /// </summary>
    /// <remarks>
    /// The hand is the zone this family exists to reach: it is hidden (CR 400.2), so nothing
    /// before this could look into one at all, and a card found there moves out of a zone the
    /// searcher is otherwise not allowed to see. Here the searcher owns the hand, which is the
    /// easy case.
    /// </remarks>
    [Fact]
    public void A_three_zone_search_takes_the_card_out_of_the_hand()
    {
        var sought = Card("Sought Relic Test", string.Empty, CardType.Artifact);
        var spared = Card("Spared Relic Test", string.Empty, CardType.Artifact);

        var gate = Card(
            "Relic Gate Test",
            "When ~ enters, search your graveyard, hand, or library for a card named "
                + "Sought Relic Test and put it onto the battlefield. If you search your library "
                + "this way, shuffle.",
            CardType.Creature,
            power: 1,
            toughness: 1);

        var compiled = CardCompiler.Compile(gate);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();

        game.Create(alice, sought, Zone.Hand);
        game.Create(alice, spared, Zone.Hand);

        game.Create(alice, gate, Zone.Battlefield);
        Settle(game);

        // Out of the hand and onto the battlefield.
        Assert.DoesNotContain(
            game.State.GetPlayer(alice).Hand.Select(game.State.GetObject),
            o => o.Card.Name == "Sought Relic Test");

        Assert.Contains(
            game.State.Battlefield.Select(game.State.GetObject),
            o => o.Card.Name == "Sought Relic Test");

        // The control is still in hand, and never reached the battlefield.
        Assert.Contains(
            game.State.GetPlayer(alice).Hand.Select(game.State.GetObject),
            o => o.Card.Name == "Spared Relic Test");

        Assert.DoesNotContain(
            game.State.Battlefield.Select(game.State.GetObject),
            o => o.Card.Name == "Spared Relic Test");
    }

    /// <summary>
    /// The shuffle happens because a library was searched, and not otherwise (CR 701.23e).
    /// </summary>
    /// <remarks>
    /// "If you search your library this way, shuffle" is the rider every card in this family
    /// prints, and it is a condition rather than decoration: a search that only ever looked at a
    /// graveyard has nothing hidden to randomise. The unconditional shuffle the single-zone
    /// search did was invisible until a search could avoid the library altogether.
    /// </remarks>
    [Fact]
    public void A_search_that_never_reaches_a_library_does_not_shuffle_one()
    {
        var sought = Card("Sought Idol Test", string.Empty, CardType.Artifact);

        var digger = Card(
            "Idol Digger Test",
            "When ~ enters, search your graveyard for a card named Sought Idol Test, "
                + "reveal it, and put it into your hand.",
            CardType.Creature,
            power: 1,
            toughness: 1);

        var compiled = CardCompiler.Compile(digger);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        game.Create(alice, sought, Zone.Graveyard);

        var shufflesBefore = game.Log.OfType<LibraryShuffled>().Count();

        game.Create(alice, digger, Zone.Battlefield);
        Settle(game);

        // The card came out of the graveyard...
        Assert.Contains(
            game.State.GetPlayer(alice).Hand.Select(game.State.GetObject),
            o => o.Card.Name == "Sought Idol Test");

        // ...and no library was shuffled on the way.
        Assert.Equal(shufflesBefore, game.Log.OfType<LibraryShuffled>().Count());
    }

    /// <summary>The same search with the library in its zone list does shuffle.</summary>
    /// <remarks>
    /// The control for the test above. Without it, a build that had simply stopped shuffling
    /// would pass - and the shuffle is what stops a tutor telling its controller the order of
    /// everything it did not take.
    /// </remarks>
    [Fact]
    public void A_search_that_does_reach_a_library_shuffles_it()
    {
        var sought = Card("Sought Idol Test", string.Empty, CardType.Artifact);

        var seeker = Card(
            "Idol Seeker Test",
            "When ~ enters, search your library or graveyard for a card named Sought Idol Test, "
                + "reveal it, and put it into your hand. If you search your library this way, "
                + "shuffle.",
            CardType.Creature,
            power: 1,
            toughness: 1);

        var (game, alice, _) = InMainPhase();
        game.Create(alice, sought, Zone.Graveyard);

        var shufflesBefore = game.Log.OfType<LibraryShuffled>().Count();

        game.Create(alice, seeker, Zone.Battlefield);
        Settle(game);

        Assert.Contains(
            game.State.GetPlayer(alice).Hand.Select(game.State.GetObject),
            o => o.Card.Name == "Sought Idol Test");

        Assert.True(game.Log.OfType<LibraryShuffled>().Count() > shufflesBefore);
    }

    /// <summary>
    /// One instruction that empties a graveyard, a hand and a library at once - the extraction
    /// family (CR 701.23a), on Sowing Salt's printed wording.
    /// </summary>
    /// <remarks>
    /// Everything this family needs that a tutor does not is here at once: three zones in one
    /// search, zones that belong to somebody other than the player doing the searching, a filter
    /// whose name is not written on the card but taken from what the sentence before it exiled,
    /// and a destination of exile.
    /// <para>
    /// The control is a card of a different name sitting in all three of the same zones. It is
    /// the assertion that matters most here, because every plausible way of getting this wrong -
    /// dropping the filter, reading the sentinel as a subtype, taking the whole zone - shows up
    /// as the control moving and as nothing else.
    /// </para>
    /// </remarks>
    [Fact]
    public void An_extraction_takes_the_named_card_out_of_all_three_zones_at_once()
    {
        var sought = Card("Sought Tower Test", string.Empty, CardType.Land);
        var spared = Card("Spared Tower Test", string.Empty, CardType.Land);

        var salt = Card(
            "Salt Sower Test",
            "Exile target nonbasic land. Search its controller's graveyard, hand, and library "
                + "for all cards with the same name as that land and exile them. Then that "
                + "player shuffles.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(salt);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();

        var onBoard = game.Create(bob, sought, Zone.Battlefield);

        // One copy in each of the three zones the card names...
        game.Create(bob, sought, Zone.Graveyard);
        game.Create(bob, sought, Zone.Hand);
        game.Create(bob, sought, Zone.Library);

        // ...and a differently named card beside each of them.
        game.Create(bob, spared, Zone.Graveyard);
        game.Create(bob, spared, Zone.Hand);
        game.Create(bob, spared, Zone.Library);

        var card = TestCards.PutInHand(game, alice, salt);
        game.CastSpell(alice, card, [Target.ToPermanent(onBoard)]);

        var asked = SettleTakingEverything(game);

        // The question went to the caster, not to the player whose cards were being looked
        // through. Getting this the wrong way round would be a card that asks its victim to
        // choose what they lose.
        Assert.Equal(alice, asked);

        // Gone from every zone it was in.
        Assert.DoesNotContain(
            game.State.GetPlayer(bob).Graveyard.Select(game.State.GetObject),
            o => o.Card.Name == "Sought Tower Test");

        Assert.DoesNotContain(
            game.State.GetPlayer(bob).Hand.Select(game.State.GetObject),
            o => o.Card.Name == "Sought Tower Test");

        Assert.DoesNotContain(
            game.State.GetPlayer(bob).Library.Select(game.State.GetObject),
            o => o.Card.Name == "Sought Tower Test");

        // Four of them in exile: the permanent the spell targeted, and one from each zone.
        Assert.Equal(
            4,
            game.State.Exile.Select(game.State.GetObject)
                .Count(o => o.Card.Name == "Sought Tower Test"));

        // The control is untouched in all three zones, and none of it reached exile.
        Assert.Contains(
            game.State.GetPlayer(bob).Graveyard.Select(game.State.GetObject),
            o => o.Card.Name == "Spared Tower Test");

        Assert.Contains(
            game.State.GetPlayer(bob).Hand.Select(game.State.GetObject),
            o => o.Card.Name == "Spared Tower Test");

        Assert.Contains(
            game.State.GetPlayer(bob).Library.Select(game.State.GetObject),
            o => o.Card.Name == "Spared Tower Test");

        Assert.DoesNotContain(
            game.State.Exile.Select(game.State.GetObject),
            o => o.Card.Name == "Spared Tower Test");
    }

    /// <summary>
    /// Searching a hand shows the searcher what matched and nothing else (CR 400.2).
    /// </summary>
    /// <remarks>
    /// A <c>GameState</c> is never serialised to a client, so a search that reaches into an
    /// opponent's hand cannot be a peek at one - it has to be an event, and the event is the
    /// question. <see cref="PlayerViewProjector"/> sends a choice's options only to the player
    /// being asked, which is what lets the caster see the matching card in a hand they are
    /// otherwise not allowed to look at, while the rest of that hand stays where it was.
    /// </remarks>
    [Fact]
    public void An_extraction_shows_the_searcher_the_match_and_not_the_rest_of_the_hand()
    {
        var sought = Card("Sought Tower Test", string.Empty, CardType.Land);
        var secret = Card("Secret Tower Test", string.Empty, CardType.Land);

        var salt = Card(
            "Salt Sower Test",
            "Exile target nonbasic land. Search its controller's graveyard, hand, and library "
                + "for all cards with the same name as that land and exile them. Then that "
                + "player shuffles.",
            CardType.Sorcery);

        var (game, alice, bob) = InMainPhase();

        var onBoard = game.Create(bob, sought, Zone.Battlefield);
        game.Create(bob, sought, Zone.Hand);
        game.Create(bob, secret, Zone.Hand);

        var card = TestCards.PutInHand(game, alice, salt);
        game.CastSpell(alice, card, [Target.ToPermanent(onBoard)]);

        RunUntilSearchAsked(game);

        var choice = game.State.Choice;
        Assert.NotNull(choice);
        Assert.Equal(ChoiceKind.SearchLibrary, choice!.Kind);
        Assert.Equal(alice, choice.PlayerId);

        // The match in Bob's hand is among the options Alice is offered...
        Assert.Contains(choice.Options, o => o.Label == "Sought Tower Test");

        // ...and the card beside it, which the filter does not name, is not.
        Assert.DoesNotContain(choice.Options, o => o.Label == "Secret Tower Test");

        var forAlice = PlayerViewProjector.Project(game.State, alice, Pool);

        // Alice is asked the question and given its options.
        Assert.NotNull(forAlice.Choice?.Options);
        Assert.Contains(forAlice.Choice!.Options!, o => o.Label == "Sought Tower Test");

        // Bob's hand is still absent from her view of the board: what she may see is what the
        // question named, not the zone it came out of.
        Assert.Null(forAlice.Players.Single(p => p.PlayerId == bob).Hand);

        // And Bob, who is not being asked, is sent the question without its options.
        var forBob = PlayerViewProjector.Project(game.State, bob, Pool);
        Assert.Equal(alice, forBob.Choice?.PlayerId);
        Assert.Null(forBob.Choice?.Options);
    }

    /// <summary>Plays on until a search is the question on the table, and stops there.</summary>
    /// <remarks>
    /// The shared <see cref="Run"/> answers every question it meets, which leaves nothing to look
    /// at. What the search offers, and to whom, is the whole subject of the test that uses this.
    /// </remarks>
    private static void RunUntilSearchAsked(Game game)
    {
        for (var guard = 0; guard < 80; guard++)
        {
            if (game.State.Choice is { Kind: ChoiceKind.SearchLibrary })
                return;

            if (game.State.Choice is { } other)
            {
                game.Choose(
                    other.PlayerId,
                    [.. other.Options.Take(Math.Max(other.MinPicks, 1)).Select(o => o.Id)]);
                continue;
            }

            if (game.State.Priority.Holder is not { } holder)
                return;

            game.PassPriority(holder);
        }
    }

    /// <summary>
    /// Plays on until nothing is waiting, answering a search with every option it offers.
    /// </summary>
    /// <remarks>
    /// The shared <see cref="Run"/> takes the smallest legal answer, which for "all cards with
    /// that name" is one card - an extraction that took one copy and left the other two would
    /// pass every assertion about the zone it happened to take from.
    /// </remarks>
    /// <returns>Who was asked the search, or the empty id if nothing was.</returns>
    private static Guid SettleTakingEverything(Game game)
    {
        var asked = Guid.Empty;
        var passedOnce = false;

        for (var guard = 0; guard < 80; guard++)
        {
            if (game.State.Choice is { } choice)
            {
                if (choice.Kind == ChoiceKind.SearchLibrary)
                    asked = choice.PlayerId;

                game.Choose(
                    choice.PlayerId,
                    [.. choice.Options
                        .Take(Math.Max(choice.MinPicks, choice.Kind == ChoiceKind.SearchLibrary
                            ? choice.MaxPicks
                            : 1))
                        .Select(o => o.Id)]);
                continue;
            }

            if (passedOnce && game.State.Stack.IsEmpty && game.State.PendingTriggers.IsEmpty)
                break;

            if (game.State.Priority.Holder is not { } holder)
                break;

            game.PassPriority(holder);
            passedOnce = true;
        }

        Assert.Equal(game.State, GameReducer.Replay(game.Log));
        return asked;
    }

    // ---- Searching by name (CR 701.23) ---------------------------------------

    [Fact]
    public void A_search_for_a_card_named_this_finds_its_own_twin()
    {
        var twin = Card(
            "Sought Twin Test",
            "When ~ enters, search your library for a card named Sought Twin Test, "
                + "reveal it, put it into your hand, then shuffle.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var compiled = CardCompiler.Compile(twin);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();

        // A decoy that answers to every filter except the right one.
        game.Create(alice, TestCards.Creature("Wrong Twin Test", 2, 2), Zone.Library);
        game.Create(alice, twin, Zone.Library);

        var before = game.State.GetPlayer(alice).Hand.Count;
        game.Create(alice, twin, Zone.Battlefield);
        Settle(game);

        Assert.Equal(before + 1, game.State.GetPlayer(alice).Hand.Count);

        // The one it was told to find, and not the decoy that a filter matching anything would
        // have offered first.
        Assert.Contains(
            game.State.GetPlayer(alice).Hand.Select(game.State.GetObject),
            o => o.Card.Name == "Sought Twin Test");
    }

    // ---- Characteristic-defining power and toughness (CR 613.4a) -------------

    [Fact]
    public void A_defined_power_counts_the_board_and_still_takes_counters()
    {
        var nomad = Card(
            "Counting Nomad Test",
            "Counting Nomad Test's power and toughness are each equal to the number of "
                + "lands you control.",
            CardType.Creature,
            power: 0,
            toughness: 0);

        var compiled = CardCompiler.Compile(nomad);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.Create(alice, TestCards.BasicLand("Island"), Zone.Battlefield);
        game.Create(bob, TestCards.BasicLand("Swamp"), Zone.Battlefield);

        var it = game.Create(alice, nomad, Zone.Battlefield);

        // Alice's two lands, not Bob's three.
        Assert.Equal(2, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(it)));

        game.ChangeCounters(it, CounterKinds.PlusOnePlusOne, 1);

        // The counter is layer 7c and the definition is 7a, so the counter modifies what the
        // definition produced rather than being overwritten by it (CR 613.4a, 613.4c).
        Assert.Equal(3, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(it)));

        // And it keeps counting: a third land makes it bigger with nothing going back to adjust.
        game.Create(alice, TestCards.BasicLand("Mountain"), Zone.Battlefield);
        Assert.Equal(4, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(it)));
    }

    [Fact]
    public void A_defined_power_can_count_a_hand_or_a_graveyard()
    {
        var maro = Card(
            "Hand Maro Test",
            "Hand Maro Test's power and toughness are each equal to the number of cards in "
                + "your hand.",
            CardType.Creature,
            power: 0,
            toughness: 0);

        var ghoul = Card(
            "Yard Ghoul Test",
            "Yard Ghoul Test's power and toughness are each equal to the number of creature "
                + "cards in your graveyard.",
            CardType.Creature,
            power: 0,
            toughness: 0);

        Assert.True(CardCompiler.Compile(maro).IsComplete);
        Assert.True(CardCompiler.Compile(ghoul).IsComplete);

        var (game, alice, _) = InMainPhase();
        var counted = game.Create(alice, maro, Zone.Battlefield);
        var digger = game.Create(alice, ghoul, Zone.Battlefield);

        var before = game.State.GetPlayer(alice).Hand.Count;
        Assert.Equal(
            before, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(counted)));

        TestCards.PutInHand(game, alice, TestCards.Creature("Spare Card Test", 1, 1));
        Assert.Equal(
            before + 1,
            Characteristics.PowerOf(game.State, Pool, game.State.GetObject(counted)));

        // The graveyard is filtered, not just counted: a land in it is not a creature card.
        game.Create(alice, TestCards.BasicLand("Buried Forest Test"), Zone.Graveyard);
        Assert.Equal(0, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(digger)));

        game.Create(alice, TestCards.Creature("Buried Bear Test", 2, 2), Zone.Graveyard);
        Assert.Equal(1, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(digger)));
    }

    // ---- One sentence printed twice (CR 601.2c) ------------------------------

    [Fact]
    public void A_spell_that_prints_the_same_line_three_times_pumps_three_creatures()
    {
        var bounty = Card(
            "Bounty of Might Test",
            "Target creature gets +3/+3 until end of turn.\n"
                + "Target creature gets +3/+3 until end of turn.\n"
                + "Target creature gets +3/+3 until end of turn.",
            CardType.Instant);

        var compiled = CardCompiler.Compile(bounty);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.Equal(3, compiled.Spell!.Targets.Count);

        var (game, alice, _) = InMainPhase();
        var first = game.Create(alice, TestCards.Creature("Bounty One Test", 1, 1), Zone.Battlefield);
        var second = game.Create(alice, TestCards.Creature("Bounty Two Test", 1, 1), Zone.Battlefield);
        var third = game.Create(alice, TestCards.Creature("Bounty Three Test", 1, 1), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, bounty);
        game.CastSpell(
            alice,
            card,
            [Target.ToPermanent(first), Target.ToPermanent(second), Target.ToPermanent(third)]);

        Settle(game);

        // Three creatures chosen, three creatures pumped. Every effect used to point at the
        // first target, so one creature became a 10/10 and the other two were asked for and
        // then ignored.
        foreach (var id in new[] { first, second, third })
        {
            Assert.Equal(
                4, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(id)));
        }
    }

    // ---- Casting a card that is not in your hand (CR 601.3, 601.2b) ----------

    /// <summary>A card with a real price, so "without paying its mana cost" means something.</summary>
    /// <remarks>
    /// <see cref="Card"/> leaves the cost empty, which makes every fixture free and would let
    /// the offer tests below pass with the permission doing nothing at all. The mana value is
    /// set beside the printed cost rather than derived, because that is the number the offer's
    /// cap is compared against (CR 202.3).
    /// </remarks>
    private static CardDefinition Priced(string name, string cost, int manaValue) => new()
    {
        OracleId = "oracle-" + name.ToLowerInvariant().Replace(' ', '-'),
        Name = name,
        OracleText = "~ deals 1 damage to any target.",
        CardTypes = CardType.Instant,
        ManaCostRaw = cost,
        Cmc = manaValue,
    };

    /// <summary>Future Sight's own wording, with the private half of the reveal it pairs with.</summary>
    private static CardDefinition LibraryTopSight() => Card(
        "Sight Of The Deck Test",
        "You may look at the top card of your library any time.\n"
            + "You may play lands and cast spells from the top of your library.",
        CardType.Enchantment);

    [Fact]
    public void A_spell_may_be_cast_from_the_top_of_your_library_and_the_next_becomes_available()
    {
        var sight = LibraryTopSight();

        var compiled = CardCompiler.Compile(sight);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.True(compiled.ShowsTopOfLibrary);

        var permission = Assert.Single(compiled.LibraryTopPermissions);
        Assert.True(permission.Lands);
        Assert.True(permission.Spells);
        Assert.Null(permission.SpellFilter);

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, sight, Zone.Battlefield);

        // Two spells buried in that order, so the second is only reachable once the first has
        // gone. The whole claim of this family is that the top card is a position rather than a
        // card: playing one has to uncover the next without anything being told to.
        var underneath = game.Create(
            alice,
            Card("Second From The Top Test", "~ deals 2 damage to any target."),
            Zone.Library);
        var onTop = game.Create(
            alice,
            Card("First From The Top Test", "~ deals 3 damage to any target."),
            Zone.Library);

        Assert.Equal(onTop, game.State.GetPlayer(alice).Library[0]);

        // The permission grants a zone and not a look: the visibility is the other line on the
        // card, and it is that line the projection answers.
        var before = game.ViewFor(alice).Players.Single(p => p.PlayerId == alice);
        Assert.Equal("First From The Top Test", before.TopOfLibrary?.Name);

        game.CastSpell(alice, onTop, [Target.ToPlayer(bob)]);
        Settle(game);

        Assert.Equal(17, game.State.GetPlayer(bob).Life);

        // And the next card is now the one that may be cast - nothing was written onto it, and
        // nothing had to notice that the library moved.
        Assert.Equal(underneath, game.State.GetPlayer(alice).Library[0]);

        var after = game.ViewFor(alice).Players.Single(p => p.PlayerId == alice);
        Assert.Equal("Second From The Top Test", after.TopOfLibrary?.Name);

        game.CastSpell(alice, underneath, [Target.ToPlayer(bob)]);
        Settle(game);

        Assert.Equal(15, game.State.GetPlayer(bob).Life);
    }

    [Fact]
    public void A_land_may_be_played_from_the_top_of_your_library()
    {
        var oracle = Card(
            "Oracle Of The Deck Test",
            "You may look at the top card of your library any time.\n"
                + "You may play lands from the top of your library.",
            CardType.Creature,
            2,
            2);

        var compiled = CardCompiler.Compile(oracle);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var permission = Assert.Single(compiled.LibraryTopPermissions);
        Assert.True(permission.Lands);
        Assert.False(permission.Spells);

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, oracle, Zone.Battlefield);

        var spell = game.Create(
            alice,
            Card("Top Library Spell Test", "~ deals 3 damage to any target."),
            Zone.Library);
        var land = game.Create(alice, TestCards.BasicLand("Top Library Land Test"), Zone.Library);

        // CR 400.7: the card that was in the library stops existing when it leaves, so the
        // permanent to look for is the one the play returned and not the id that was buried.
        var onBattlefield = game.PlayLand(alice, land);

        Assert.Contains(onBattlefield, game.State.Battlefield);
        Assert.Equal(1, game.State.GetPlayer(alice).LandsPlayedThisTurn);
        Assert.Equal(spell, game.State.GetPlayer(alice).Library[0]);

        // The half this permission does not grant. "You may play lands from the top of your
        // library" says nothing about spells, and a permission read one word wider than the card
        // is a Future Sight wearing an Oracle of Mul Daya's name.
        var refused = Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, spell, [Target.ToPlayer(bob)]));

        Assert.Contains("cast from hand", refused.Message, StringComparison.Ordinal);
        Settle(game);
    }

    [Fact]
    public void Playing_the_top_card_covers_a_land_and_a_spell_alike()
    {
        // The printing that names neither noun. "You may play the top card of your library" is
        // whatever is up there, so it has to cover both halves - and it is worth its own test
        // because a reader that folded it into the two-noun sentence would have made both of
        // those nouns optional there.
        var citadel = Card(
            "Whole Top Card Test",
            "You may look at the top card of your library any time.\n"
                + "You may play the top card of your library.",
            CardType.Artifact);

        var compiled = CardCompiler.Compile(citadel);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var permission = Assert.Single(compiled.LibraryTopPermissions);
        Assert.True(permission.Lands);
        Assert.True(permission.Spells);
        Assert.Null(permission.SpellFilter);

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, citadel, Zone.Battlefield);

        var spell = game.Create(
            alice,
            Card("Whole Top Spell Test", "~ deals 3 damage to any target."),
            Zone.Library);
        var land = game.Create(alice, TestCards.BasicLand("Whole Top Land Test"), Zone.Library);

        var onBattlefield = game.PlayLand(alice, land);
        Assert.Contains(onBattlefield, game.State.Battlefield);

        Assert.Equal(spell, game.State.GetPlayer(alice).Library[0]);

        game.CastSpell(alice, spell, [Target.ToPlayer(bob)]);
        Settle(game);

        Assert.Equal(17, game.State.GetPlayer(bob).Life);
    }

    [Fact]
    public void Nothing_may_be_cast_from_a_library_without_a_permanent_saying_so()
    {
        var (game, alice, bob) = InMainPhase();

        var onTop = game.Create(
            alice,
            Card("Unpermitted Top Test", "~ deals 3 damage to any target."),
            Zone.Library);

        var refused = Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, onTop, [Target.ToPlayer(bob)]));

        Assert.Contains("cast from hand", refused.Message, StringComparison.Ordinal);

        // And the permission arrives with the permanent, which is what reading it off the
        // battlefield buys: there is no state anywhere saying whether it was ever open.
        game.Create(alice, LibraryTopSight(), Zone.Battlefield);
        game.CastSpell(alice, onTop, [Target.ToPlayer(bob)]);
        Settle(game);

        Assert.Equal(17, game.State.GetPlayer(bob).Life);
    }

    [Fact]
    public void The_permission_reaches_the_top_card_and_no_further()
    {
        var (game, alice, bob) = InMainPhase();
        game.Create(alice, LibraryTopSight(), Zone.Battlefield);

        var buried = game.Create(
            alice,
            Card("Buried Second Test", "~ deals 3 damage to any target."),
            Zone.Library);
        game.Create(
            alice,
            Card("Buried First Test", "~ deals 3 damage to any target."),
            Zone.Library);

        // "The top card of your library" is one card. A permission that let a player reach past
        // it would be a search of the whole deck at instant speed.
        var refused = Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, buried, [Target.ToPlayer(bob)]));

        Assert.Contains("cast from hand", refused.Message, StringComparison.Ordinal);
    }

    [Fact]
    public void A_cast_source_in_a_library_does_not_put_the_library_in_an_opponents_view()
    {
        var (game, alice, bob) = InMainPhase();
        game.Create(alice, LibraryTopSight(), Zone.Battlefield);

        game.Create(
            alice,
            Card("Private Second Test", "~ deals 2 damage to any target."),
            Zone.Library);
        game.Create(
            alice,
            Card("Private First Test", "~ deals 3 damage to any target."),
            Zone.Library);

        // The negative half, and the one this whole feature had to be built around: a library is
        // hidden from everyone (CR 401.2), and making one castable must not make it visible. The
        // permission is answered from the battlefield at the moment of the cast and never
        // reaches the projection, so the only thing an opponent gains is a card leaving a zone
        // they could already count.
        var theirs = game.ViewFor(bob);
        Assert.Null(theirs.Players.Single(p => p.PlayerId == alice).TopOfLibrary);
        Assert.Null(theirs.Players.Single(p => p.PlayerId == bob).TopOfLibrary);

        // Whatever the shape of the record, the bytes on the wire must not carry a card only
        // Alice may see - the assertion a flag cannot make.
        var json = System.Text.Json.JsonSerializer.Serialize(theirs);

        foreach (var id in game.State.GetPlayer(alice).Library)
        {
            Assert.DoesNotContain(
                game.State.GetObject(id).Card.Name, json, StringComparison.Ordinal);
        }

        // Even its owner sees only the one card the other line on the permanent shows them.
        var mine = game.ViewFor(alice);
        Assert.Equal(
            "Private First Test",
            mine.Players.Single(p => p.PlayerId == alice).TopOfLibrary?.Name);

        Assert.DoesNotContain(
            "Private Second Test",
            System.Text.Json.JsonSerializer.Serialize(mine),
            StringComparison.Ordinal);
    }

    [Fact]
    public void An_offer_to_cast_from_hand_is_spent_by_the_cast_that_takes_it()
    {
        var expertise = Card(
            "Expertise Offer Test",
            "You may cast a spell with mana value 3 or less from your hand "
                + "without paying its mana cost.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(expertise);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var first = game.Create(alice, Priced("Offered First Test", "{2}{R}", 3), Zone.Hand);
        var second = game.Create(alice, Priced("Offered Second Test", "{2}{R}", 3), Zone.Hand);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, expertise));

        // Resolved by hand rather than by settling, because settling passes priority and the
        // pass is where an untaken offer lapses. That is the window the printed sentence gives,
        // stretched to the next pass because casting cannot happen inside a resolution.
        game.PassPriority(alice);
        game.PassPriority(bob);

        var offer = Assert.Single(game.State.HandCastOffers);
        Assert.Equal(alice, offer.PlayerId);
        Assert.Equal(3, offer.MaxManaValue);

        // Alice has no mana at all, so the cast succeeding is proof the offer paid for it.
        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, first, [Target.ToPlayer(bob)]));

        game.CastSpell(alice, first, [Target.ToPlayer(bob)], freeFromHand: true);

        Assert.Empty(game.State.HandCastOffers);
        Assert.Single(game.Log.OfType<HandCastOfferSpent>());

        // The whole point of the count. Without it the permission stands until the pass and the
        // hand's second answer is free as well - a card strictly better than the printed one,
        // and one a test that casts only once cannot see.
        var refused = Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, second, [Target.ToPlayer(bob)], freeFromHand: true));

        Assert.Contains("601.2b", refused.Message, StringComparison.Ordinal);
        Assert.Contains(second, game.State.GetPlayer(alice).Hand);

        Settle(game);
        Assert.Equal(19, game.State.GetPlayer(bob).Life);
    }

    [Fact]
    public void An_offer_refuses_a_card_the_sentence_did_not_describe()
    {
        var expertise = Card(
            "Expertise Cap Test",
            "You may cast a spell with mana value 3 or less from your hand "
                + "without paying its mana cost.",
            CardType.Sorcery);

        Assert.True(CardCompiler.Compile(expertise).IsComplete);

        var (game, alice, bob) = InMainPhase();
        var dear = game.Create(alice, Priced("Too Dear Test", "{4}{R}", 5), Zone.Hand);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, expertise));
        game.PassPriority(alice);
        game.PassPriority(bob);

        Assert.Single(game.State.HandCastOffers);

        var refused = Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, dear, [Target.ToPlayer(bob)], freeFromHand: true));

        Assert.Contains("601.2b", refused.Message, StringComparison.Ordinal);

        // Refused and not spent: the offer is still there for a card that answers it.
        Assert.Single(game.State.HandCastOffers);
    }

    [Fact]
    public void An_offer_nobody_takes_lapses_on_the_next_pass()
    {
        var expertise = Card(
            "Expertise Lapse Test",
            "You may cast a spell from your hand without paying its mana cost.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(expertise);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var held = game.Create(alice, Priced("Left In Hand Test", "{2}{R}", 3), Zone.Hand);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, expertise));
        game.PassPriority(alice);
        game.PassPriority(bob);

        var offer = Assert.Single(game.State.HandCastOffers);
        Assert.Null(offer.MaxManaValue);
        Assert.Null(offer.SpellFilter);

        game.PassPriority(alice);

        Assert.Empty(game.State.HandCastOffers);
        Assert.Single(game.Log.OfType<HandCastOfferLapsed>());

        // Bob passes too so priority comes back round to Alice, who is the only player the
        // offer was ever made to and now has nothing to take.
        game.PassPriority(bob);

        var refused = Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, held, [Target.ToPlayer(bob)], freeFromHand: true));

        Assert.Contains("601.2b", refused.Message, StringComparison.Ordinal);
        Settle(game);
    }

    // ---- Mayhem (CR 702.181a) ------------------------------------------------

    [Fact]
    public void Mayhem_casts_from_the_graveyard_only_on_the_turn_it_was_discarded()
    {
        var bolt = new CardDefinition
        {
            OracleId = "oracle-mayhem-bolt",
            Name = "Mayhem Bolt Test",
            OracleText = "~ deals 2 damage to any target.\nMayhem {R}",
            CardTypes = CardType.Instant,
            ManaCostRaw = "{2}{R}",
            Cmc = 3,
        };

        var compiled = CardCompiler.Compile(bolt);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var mountain = game.Create(alice, TestCards.BasicLand("Mountain"), Zone.Battlefield);

        // A copy put straight into the graveyard was never discarded, so the card being there
        // is not permission - the same rule that stops a foretold card in exile being free.
        var never = game.Create(alice, bolt, Zone.Graveyard);
        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, never, [Target.ToPlayer(bob)]));

        var inHand = TestCards.PutInHand(game, alice, bolt);
        game.Move(inHand, Zone.Graveyard, MoveCause.Discard);

        // Picked by the stamp rather than by name or position: both copies are in the graveyard
        // and only one of them got there by being discarded.
        var discarded = game.State.GetPlayer(alice).Graveyard
            .Select(game.State.GetObject)
            .Single(o => o.DiscardedOnTurn == game.State.TurnNumber);

        game.ActivateAbility(alice, mountain, "mana");
        game.CastSpell(alice, discarded.Id, [Target.ToPlayer(bob)]);
        Settle(game);

        Assert.Equal(18, game.State.GetPlayer(bob).Life);
    }

    [Fact]
    public void Mayhem_is_over_when_the_turn_is()
    {
        var bolt = new CardDefinition
        {
            OracleId = "oracle-mayhem-late",
            Name = "Late Mayhem Test",
            OracleText = "~ deals 2 damage to any target.\nMayhem {R}",
            CardTypes = CardType.Instant,
            ManaCostRaw = "{2}{R}",
            Cmc = 3,
        };

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, TestCards.BasicLand("Mountain"), Zone.Battlefield);

        var inHand = TestCards.PutInHand(game, alice, bolt);
        game.Move(inHand, Zone.Graveyard, MoveCause.Discard);

        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber == 3 && game.State.CurrentStep == TurnStep.PrecombatMain);

        var stale = game.State.GetPlayer(alice).Graveyard
            .Select(game.State.GetObject)
            .Last(o => o.Card.Name == "Late Mayhem Test");

        // Two turns on, the stamp no longer matches the turn and the permission is gone. Without
        // this the card would be castable out of the graveyard for ever after.
        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, stale.Id, [Target.ToPlayer(bob)]));
    }

    // ---- Countering to exile (CR 701.5a) -------------------------------------

    [Fact]
    public void A_counterspell_that_exiles_puts_the_spell_nowhere_it_can_be_bought_back_from()
    {
        var authority = Card(
            "Assert Authority Test",
            "Counter target spell. If that spell is countered this way, exile it instead of "
                + "putting it into its owner's graveyard.",
            CardType.Instant);

        var compiled = CardCompiler.Compile(authority);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        // One effect, not two: countering and then exiling would be looking for a card the
        // first half has already moved somewhere else.
        var countering = Assert.IsType<CounterTargetSpell>(compiled.Spell!.Effects.Single());
        Assert.True(countering.ToExile);

        var (game, alice, bob) = InMainPhase();
        var bear = TestCards.Costed("Countered Bear Test", "{G}", 1);
        var threat = TestCards.PutInHand(game, alice, bear);
        var answer = TestCards.PutInHand(game, bob, authority);

        var land = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");

        var onStack = game.CastSpell(alice, threat, []);

        // Bob answers with the spell still on the stack, which is the only moment it can be
        // countered at all (CR 701.6a).
        game.PassPriority(alice);
        game.CastSpell(bob, answer, [Target.ToSpell(onStack)]);
        Settle(game);

        // Exile, not the graveyard - which is the whole point of the rider, and the difference
        // every card that recurs from a graveyard cares about.
        Assert.Empty(game.State.GetPlayer(alice).Graveyard);
        Assert.Contains(
            game.State.Exile.Select(game.State.GetObject),
            o => o.Card.Name == "Countered Bear Test");
    }

    // ---- A card that buys itself back (CR 602.5) -----------------------------

    [Fact]
    public void A_card_can_return_itself_from_the_graveyard()
    {
        var rats = Card(
            "Tunnel Rats Test",
            "{2}: Return ~ from your graveyard to the battlefield tapped.",
            CardType.Creature,
            power: 1,
            toughness: 1);

        var compiled = CardCompiler.Compile(rats);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        // The ability has to function where the card is. Left on the battlefield it would
        // compile perfectly and never once be offered to a player.
        Assert.Equal(Zone.Graveyard, compiled.Activated.Single().FunctionsFrom);

        var (game, alice, _) = InMainPhase();
        var first = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        var second = game.Create(alice, TestCards.BasicLand("Swamp"), Zone.Battlefield);
        var dead = game.Create(alice, rats, Zone.Graveyard);

        game.ActivateAbility(alice, first, "mana");
        game.ActivateAbility(alice, second, "mana");
        game.ActivateAbility(alice, dead, "a");
        Settle(game);

        // A new object on the battlefield (CR 400.7), found by name, and tapped as it says.
        var back = game.State.Battlefield.Select(game.State.GetObject)
            .Single(o => o.Card.Name == "Tunnel Rats Test");

        Assert.True(back.Permanent?.IsTapped);
        Assert.Empty(game.State.GetPlayer(alice).Graveyard);
    }

    // ---- A filter naming a subtype and a type (CR 109.4) ---------------------

    [Fact]
    public void A_subtype_and_type_filter_reads_as_both()
    {
        // The shape that was silently broken: the phrase names two alternatives, and the first
        // of them is a subtype *and* a card type. Read as one string it matched nothing at all.
        var seeker = Card(
            "Frontier Seeker Test",
            "When ~ enters, look at the top five cards of your library. You may reveal a "
                + "Mount creature card or a Plains card from among them and put it into your "
                + "hand. Put the rest on the bottom of your library in a random order.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var compiled = CardCompiler.Compile(seeker);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var filter = compiled.Triggers.Single().Effects
            .OfType<LookAndTake>().Single().FilterId;

        // Both halves survive, and the first is a conjunction rather than a phrase.
        Assert.Equal("Mount&creature|Plains", filter);

        var mount = new CardDefinition
        {
            OracleId = "oracle-test-mount",
            Name = "Test Mount",
            CardTypes = CardType.Creature,
            Subtypes = ["Mount"],
            Power = 2,
            Toughness = 2,
        };

        Assert.True(SearchFilters.Matches(filter, mount));
        Assert.True(SearchFilters.Matches(filter, TestCards.BasicLand("Plains")));

        // A Mount that is not a creature answers to neither half, which is the point of the
        // conjunction: "Mount creature card" is two requirements and not one name.
        var vehicle = new CardDefinition
        {
            OracleId = "oracle-test-vehicle-mount",
            Name = "Test Vehicle Mount",
            CardTypes = CardType.Artifact,
            Subtypes = ["Mount"],
        };

        Assert.False(SearchFilters.Matches(filter, vehicle));

        Assert.False(SearchFilters.Matches(filter, TestCards.Creature("Test Bear", 2, 2)));
    }

    // ---- State triggers (CR 603.8) -------------------------------------------

    [Fact]
    public void A_state_trigger_fires_when_its_condition_becomes_true()
    {
        var seasinger = Card(
            "Seasinger Test",
            "When you control no Islands, sacrifice ~.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var compiled = CardCompiler.Compile(seasinger);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var island = game.Create(alice, TestCards.BasicLand("Island"), Zone.Battlefield);
        var singer = game.Create(alice, seasinger, Zone.Battlefield);
        Settle(game);

        // An Island is on the battlefield, so the condition is false and nothing has happened.
        Assert.Equal(Zone.Battlefield, game.State.GetObject(singer).Zone);

        game.Move(island, Zone.Graveyard, MoveCause.Destroy);
        Settle(game);

        // The condition became true with no event to watch for - nothing "happened" to the
        // Seasinger at all - and it is in the graveyard.
        Assert.Contains(
            game.State.GetPlayer(alice).Graveyard.Select(game.State.GetObject),
            o => o.Card.Name == "Seasinger Test");
    }

    [Fact]
    public void A_state_trigger_does_not_fire_twice_for_one_condition()
    {
        // The failure this guards against is not a wrong answer but a hung game: a condition its
        // own resolution does not clear would trigger on every settle for ever (CR 603.8).
        var watcher = Card(
            "Islandless Watcher Test",
            "When you control no Islands, you gain 1 life.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(watcher);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        game.Create(alice, watcher, Zone.Battlefield);
        Settle(game);

        // True from the start, and worth exactly one life however many times the game settles.
        Assert.Equal(21, game.State.GetPlayer(alice).Life);

        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber == 3 && game.State.CurrentStep == TurnStep.PrecombatMain);

        Assert.Equal(21, game.State.GetPlayer(alice).Life);

        // An Island arrives and leaves: the condition became false and true again, so it fires
        // a second time and only a second time.
        var island = game.Create(alice, TestCards.BasicLand("Island"), Zone.Battlefield);
        Settle(game);
        Assert.Equal(21, game.State.GetPlayer(alice).Life);

        game.Move(island, Zone.Graveyard, MoveCause.Destroy);
        Settle(game);
        Assert.Equal(22, game.State.GetPlayer(alice).Life);
    }

    // ---- Colour negations in a target (CR 105.2) -----------------------------

    [Fact]
    public void Nonblack_excludes_black_and_includes_colourless()
    {
        var offering = Card(
            "Dark Offering Test",
            "Destroy target nonblack creature.",
            CardType.Instant);

        var compiled = CardCompiler.Compile(offering);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var black = game.Create(bob, Coloured("Black Bear Test", ManaColor.Black), Zone.Battlefield);
        var white = game.Create(bob, Coloured("White Bear Test", ManaColor.White), Zone.Battlefield);
        game.Create(bob, TestCards.Creature("Colourless Drone Test", 2, 2), Zone.Battlefield);

        var first = TestCards.PutInHand(game, alice, offering);
        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, first, [Target.ToPermanent(black)]));

        // A colourless creature is nonblack. It is the case that reads wrong at a glance - the
        // question is whether black is among its colours, not whether it has a colour at all.
        var drone = game.State.Battlefield.Select(game.State.GetObject)
            .Single(o => o.Card.Name == "Colourless Drone Test");

        game.CastSpell(alice, first, [Target.ToPermanent(drone.Id)]);
        Settle(game);

        // A new object in the graveyard, not the same one moved (CR 400.7), so it is found by
        // name rather than by the id it had on the battlefield.
        Assert.Contains(
            game.State.GetPlayer(bob).Graveyard.Select(game.State.GetObject),
            o => o.Card.Name == "Colourless Drone Test");

        var second = TestCards.PutInHand(game, alice, offering);
        game.CastSpell(alice, second, [Target.ToPermanent(white)]);
        Settle(game);

        Assert.Contains(
            game.State.GetPlayer(bob).Graveyard.Select(game.State.GetObject),
            o => o.Card.Name == "White Bear Test");
    }

    // ---- Mana that may only be spent on some things (CR 106.6) ---------------

    [Fact]
    public void Restricted_mana_pays_for_what_it_names_and_nothing_else()
    {
        var grove = Card(
            "Restricted Grove Test",
            "{T}: Add {G}. Spend this mana only to cast creature spells.",
            CardType.Land);

        var compiled = CardCompiler.Compile(grove);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var bear = TestCards.Costed("Restricted Bear Test", "{G}", 1);
        var bolt = new CardDefinition
        {
            OracleId = "oracle-restricted-bolt",
            Name = "Restricted Bolt Test",
            OracleText = "~ deals 1 damage to any target.",
            CardTypes = CardType.Instant,
            ManaCostRaw = "{G}",
            Cmc = 1,
        };

        var (game, alice, _) = InMainPhase();
        var land = game.Create(alice, grove, Zone.Battlefield);
        var spell = TestCards.PutInHand(game, alice, bolt);

        game.ActivateAbility(alice, land, "mana");

        // It is in the pool, and it is not ordinary green: the plain count is still zero.
        Assert.Equal(1, game.State.GetPlayer(alice).ManaPool.Total);
        Assert.Equal(0, game.State.GetPlayer(alice).ManaPool[ManaColor.Green]);

        // An instant is not a creature spell, so the only mana available cannot pay for it.
        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, spell, [Target.ToPlayer(alice)]));

        // The view keeps the two apart. A board that added them together would tell a player
        // they had a green mana for anything, which is the one thing this mana is not.
        var view = game.ViewFor(alice).Players.Single(p => p.PlayerId == alice);
        Assert.Empty(view.ManaPool);
        var floating = Assert.Single(view.RestrictedMana);
        Assert.Equal("G", floating.Symbol);
        Assert.Equal("casting creature spells", floating.SpendableOn);

        // The same mana pays for a creature, which is what the land said it was for.
        var creature = TestCards.PutInHand(game, alice, bear);
        game.CastSpell(alice, creature, []);

        Assert.True(game.State.GetPlayer(alice).ManaPool.IsEmpty);
    }

    [Fact]
    public void A_dual_land_offers_one_ability_per_colour()
    {
        // "Add {G} or {W}" is one ability with a choice in the rules; the engine cannot ask a
        // question inside a mana ability, so it becomes two abilities the player picks between.
        var dual = Card("Dual Test", "{T}: Add {G} or {W}.", CardType.Land);
        var (game, alice, _) = InMainPhase();
        var land = game.Create(alice, dual, Zone.Battlefield);

        Assert.Equal(2, Pool.ActivatedOf(dual).Count);

        game.ActivateAbility(alice, land, "mana1");

        Assert.Equal(1, game.State.GetPlayer(alice).ManaPool[ManaColor.White]);
    }

