    // ---- Prevention ----------------------------------------------------------------

    [Fact]
    public void A_prevention_shield_soaks_damage_and_the_rest_still_lands()
    {
        // CR 615.1: prevention is an amount, not an on/off replacement — three into a shield of
        // two still marks one.
        var shield = Card(
            "Shield Test",
            "Prevent the next 2 damage that would be dealt to target creature this turn.");

        var (game, alice, _) = InMainPhase();
        var bear = game.Create(alice, TestCards.Creature("Bear", 4, 4), Zone.Battlefield);
        var source = game.Create(alice, TestCards.Creature("Source", 1, 1), Zone.Battlefield);
        var card = TestCards.PutInHand(game, alice, shield);

        game.CastSpell(alice, card, [Target.ToPermanent(bear)]);
        Settle(game);

        game.MarkDamage(bear, 3, sourceId: source);
        Settle(game);

        var hit = game.State.GetObject(bear);
        Assert.Equal(1, hit.Permanent!.DamageMarked);
        Assert.Equal(0, hit.Permanent.DamageToPrevent);
    }

    [Fact]
    public void A_prevention_shield_on_a_player_soaks_damage_aimed_at_them()
    {
        // "Any target" has always included a player, and the shield was only ever kept on an
        // object - so this spell compiled, was legal to aim at a player, resolved, and did
        // nothing at all. The card looked implemented from every angle except the life total.
        var shield = Card(
            "Player Shield Test",
            "Prevent the next 2 damage that would be dealt to any target this turn.");

        var bolt = Card("Player Bolt Test", "~ deals 3 damage to any target.");

        var (game, alice, bob) = InMainPhase();
        var life = game.State.GetPlayer(bob).Life;

        var card = TestCards.PutInHand(game, alice, shield);
        game.CastSpell(alice, card, [Target.ToPlayer(bob)]);
        Settle(game);

        var second = TestCards.PutInHand(game, alice, bolt);
        game.CastSpell(alice, second, [Target.ToPlayer(bob)]);
        Settle(game);

        // Two of the three soaked, so one point gets through (CR 615.1).
        Assert.Equal(life - 1, game.State.GetPlayer(bob).Life);
    }

    [Fact]
    public void A_prevention_shield_does_not_survive_the_turn_that_bought_it()
    {
        // CR 514.2: the line says "this turn". Cleanup took the damage off and left the shield
        // standing, so a shield bought once went on soaking damage every turn after.
        var shield = Card(
            "Lasting Shield Test",
            "Prevent the next 2 damage that would be dealt to target creature this turn.");

        var (game, alice, _) = InMainPhase();
        var bear = game.Create(alice, TestCards.Creature("Shielded Bear Test", 4, 4), Zone.Battlefield);
        var source = game.Create(alice, TestCards.Creature("Shield Source Test", 1, 1), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, shield);
        game.CastSpell(alice, card, [Target.ToPermanent(bear)]);
        Settle(game);

        Assert.Equal(2, game.State.GetObject(bear).Permanent!.DamageToPrevent);

        TestCards.PassToTurn(game, game.State.TurnNumber + 1);

        Assert.Equal(0, game.State.GetObject(bear).Permanent!.DamageToPrevent);

        // And the damage lands in full, which is the half a player would notice.
        game.MarkDamage(bear, 2, sourceId: source);
        Settle(game);

        Assert.Equal(2, game.State.GetObject(bear).Permanent!.DamageMarked);
    }

    [Fact]
    public void A_shield_can_name_you_without_targeting_anyone()
    {
        // Every other phrasing of this line names a target; "you" names the controller and takes
        // no target at all, which is why it went unread rather than compiling to a shield with
        // nowhere to sit.
        var shield = Card(
            "Personal Shield Test",
            "Prevent the next 2 damage that would be dealt to you this turn.");

        var compiled = CardCompiler.Compile(shield);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var bolt = Card("Personal Bolt Test", "~ deals 3 damage to any target.");

        var (game, alice, bob) = InMainPhase();
        var life = game.State.GetPlayer(alice).Life;

        var card = TestCards.PutInHand(game, alice, shield);
        game.CastSpell(alice, card, []);
        Settle(game);

        // The shield is on the caster and on nobody else.
        Assert.Equal(2, game.State.GetPlayer(alice).DamageToPrevent);
        Assert.Equal(0, game.State.GetPlayer(bob).DamageToPrevent);

        var second = TestCards.PutInHand(game, alice, bolt);
        game.CastSpell(alice, second, [Target.ToPlayer(alice)]);
        Settle(game);

        Assert.Equal(life - 1, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void A_negated_creature_type_excludes_that_type_and_nothing_else()
    {
        // The negated card types were all spelled out in the adjective list; the negated creature
        // types could not be, there being some fifteen hundred of them. So "non-Human creature"
        // - the commonest of them, on thirty-four lines - was refused whole.
        var tap = Card(
            "Non Human Tap Test",
            "Tap target non-Human creature.",
            CardType.Instant);

        var compiled = CardCompiler.Compile(tap);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();

        var human = game.Create(
            bob,
            Card("Villager Test", string.Empty, CardType.Creature, 2, 2, subtypes: "Human"),
            Zone.Battlefield);

        var wall = game.Create(
            bob,
            Card("Barricade Test", string.Empty, CardType.Creature, 0, 4, subtypes: "Wall"),
            Zone.Battlefield);

        var atHuman = TestCards.PutInHand(game, alice, tap);
        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, atHuman, [Target.ToPermanent(human)]));

        var atWall = TestCards.PutInHand(game, alice, tap);
        game.CastSpell(alice, atWall, [Target.ToPermanent(wall)]);
        Settle(game);

        Assert.True(game.State.GetObject(wall).Permanent!.IsTapped);
        Assert.False(game.State.GetObject(human).Permanent!.IsTapped);
    }

    [Fact]
    public void A_discard_cost_may_ask_for_a_card_of_a_named_type()
    {
        // The cost read "discard a card" and nothing else, so every ability that asks for a
        // particular kind of card went unread - and the filter is the whole point of those
        // abilities, since paying with any card in hand would make them strictly better.
        var brute = Card(
            "Picky Discard Test",
            "Discard a creature card: ~ gets +2/+2 until end of turn.",
            CardType.Creature,
            1,
            1);

        var compiled = CardCompiler.Compile(brute);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var thug = game.Create(alice, brute, Zone.Battlefield);

        var land = TestCards.PutInHand(game, alice, TestCards.BasicLand("Island"));
        var beast = TestCards.PutInHand(game, alice, TestCards.Creature("Fodder Bear Test"));

        // A land is a card, and that is exactly what this cost does not accept.
        Assert.Throws<InvalidOperationException>(
            () => game.ActivateAbility(alice, thug, "a", costPayment: [land]));

        game.ActivateAbility(alice, thug, "a", costPayment: [beast]);
        Settle(game);

        Assert.Equal(3, Characteristics.Of(game.State, Pool, game.State.GetObject(thug)).Power);
        Assert.Contains(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Fodder Bear Test");
    }

    [Fact]
    public void One_or_two_targets_requires_the_first_and_not_the_second()
    {
        // A range, not a count, and not the same as "up to two" either: the first target is
        // required. Reading it as "up to two" would have let the spell be cast at nothing.
        var spell = Card(
            "Range Pump Test",
            "One or two target creatures get +1/+1 until end of turn.");

        var compiled = CardCompiler.Compile(spell);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var first = game.Create(alice, TestCards.Creature("Range One Test", 2, 2), Zone.Battlefield);
        var second = game.Create(alice, TestCards.Creature("Range Two Test", 2, 2), Zone.Battlefield);

        // Casting it at nothing is refused - that is the half "up to two" would have got wrong.
        var empty = TestCards.PutInHand(game, alice, spell);
        Assert.Throws<InvalidOperationException>(() => game.CastSpell(alice, empty, []));

        // One is enough.
        var single = TestCards.PutInHand(game, alice, spell);
        game.CastSpell(alice, single, [Target.ToPermanent(first)]);
        Settle(game);

        Assert.Equal(3, Characteristics.Of(game.State, Pool, game.State.GetObject(first)).Power);
        Assert.Equal(2, Characteristics.Of(game.State, Pool, game.State.GetObject(second)).Power);

        // And two is the ceiling, both of them pumped.
        var both = TestCards.PutInHand(game, alice, spell);
        game.CastSpell(alice, both, [Target.ToPermanent(first), Target.ToPermanent(second)]);
        Settle(game);

        Assert.Equal(4, Characteristics.Of(game.State, Pool, game.State.GetObject(first)).Power);
        Assert.Equal(3, Characteristics.Of(game.State, Pool, game.State.GetObject(second)).Power);
    }

    [Fact]
    public void A_trigger_can_deal_damage_to_a_group_rather_than_a_target()
    {
        // "~ deals 2 damage to each opponent" read; "it deals 2 damage to each opponent" - the
        // same instruction as a trigger writes it, the source having already been named - did
        // not, because that reader had only ever been given the target form.
        var bomb = Card(
            "Group Blast Test",
            "When ~ enters, it deals 2 damage to each opponent.",
            CardType.Creature,
            1,
            1);

        var compiled = CardCompiler.Compile(bomb);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var mine = game.State.GetPlayer(alice).Life;
        var theirs = game.State.GetPlayer(bob).Life;

        game.Create(alice, bomb, Zone.Battlefield);
        Settle(game);

        // Each opponent, and not the controller - the difference "each player" would have lost.
        Assert.Equal(theirs - 2, game.State.GetPlayer(bob).Life);
        Assert.Equal(mine, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void A_card_can_ask_whether_you_attacked_this_turn()
    {
        // The enters-with-counters reader already had a slot for a condition; the condition
        // vocabulary had no way to ask this one, so eighty-odd lines that ask it went unread.
        // It is a fact about the player: the creature that attacked need not still be there.
        var eager = Card(
            "Eager Recruit Test",
            "~ enters with a +1/+1 counter on it if you attacked this turn.",
            CardType.Creature,
            2,
            2);

        var compiled = CardCompiler.Compile(eager);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();

        // Nobody has attacked yet, so it arrives at its printed size.
        var early = game.Create(alice, eager, Zone.Battlefield);
        Settle(game);
        Assert.Equal(2, Characteristics.Of(game.State, Pool, game.State.GetObject(early)).Power);

        var soldier = game.Create(
            alice,
            Card("Charging Bear Test", string.Empty, CardType.Creature, 2, 2, KeywordAbility.Haste),
            Zone.Battlefield);

        TestCards.PassToStep(game, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [soldier] = AttackTarget.Player(bob) });
        Settle(game);

        var late = game.Create(alice, eager, Zone.Battlefield);
        Settle(game);

        Assert.Equal(3, Characteristics.Of(game.State, Pool, game.State.GetObject(late)).Power);
    }

    [Fact]
    public void A_creature_told_to_block_the_source_may_not_block_something_else()
    {
        // Provoke's shape: both halves named. Neither flag the engine had could say it - "must
        // be blocked" is satisfied by anyone blocking, and a lure compels everyone who can - so
        // the requirement had to be read from the blocker's side and carry the attacker with it.
        var provoker = Card(
            "Provoking Ogre Test",
            "Whenever ~ attacks, target creature blocks ~ this turn if able.",
            CardType.Creature,
            3,
            3,
            KeywordAbility.Haste);

        var compiled = CardCompiler.Compile(provoker);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var ogre = game.Create(alice, provoker, Zone.Battlefield);

        var decoy = game.Create(
            alice,
            Card("Second Attacker Test", string.Empty, CardType.Creature, 1, 1, KeywordAbility.Haste),
            Zone.Battlefield);

        var wall = game.Create(bob, TestCards.Creature("Told Wall Test", 0, 4), Zone.Battlefield);

        TestCards.PassToStep(game, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget>
            {
                [ogre] = AttackTarget.Player(bob),
                [decoy] = AttackTarget.Player(bob),
            });

        // The trigger targets, and "target creature" is not restricted to the defender's - so
        // the choice is answered here rather than left to Settle, which would take whichever
        // option came first.
        TestCards.PassUntil(game, () => game.State.Choice is not null);

        var asked = game.State.Choice!;
        var pick = asked.Options.Single(o => o.Id.EndsWith(wall.Value.ToString("N"), StringComparison.Ordinal));
        game.Choose(asked.PlayerId, [pick.Id]);
        Settle(game);

        TestCards.PassToStep(game, TurnStep.DeclareBlockers);

        // Blocking the other attacker does not discharge a requirement that named this one.
        Assert.Throws<InvalidOperationException>(() => game.DeclareBlockers(
            bob,
            new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [decoy] = new[] { wall } }));

        // Nor does declining to block at all.
        Assert.Throws<InvalidOperationException>(() => game.DeclareBlockers(
            bob,
            new Dictionary<ObjectId, IReadOnlyList<ObjectId>>()));

        // Blocking the creature that named it is legal.
        game.DeclareBlockers(
            bob,
            new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [ogre] = new[] { wall } });

        Assert.True(game.State.Combat.BlockersDeclared);
    }

    [Fact]
    public void Provoke_drags_a_blocker_out_and_unstraps_it_first()
    {
        // CR 702.39a. The keyword is one printed word standing for an attack trigger that both
        // untaps a creature and compels it to block the attacker - and a tapped creature cannot
        // block, so the untap is what makes the requirement mean anything at all.
        var provoker = Card(
            "Provoke Keyword Test",
            "Provoke",
            CardType.Creature,
            3,
            3,
            KeywordAbility.Haste);

        var compiled = CardCompiler.Compile(provoker);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var ogre = game.Create(alice, provoker, Zone.Battlefield);
        var wall = game.Create(bob, TestCards.Creature("Provoked Wall Test", 0, 4), Zone.Battlefield);

        game.Tap(wall);
        Assert.True(game.State.GetObject(wall).Permanent!.IsTapped);

        TestCards.PassToStep(game, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [ogre] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.Choice is not null);
        var asked = game.State.Choice!;
        var pick = asked.Options.Single(
            o => o.Id.EndsWith(wall.Value.ToString("N"), StringComparison.Ordinal));

        game.Choose(asked.PlayerId, [pick.Id]);
        Settle(game);

        // Untapped by the trigger, so it is able to block - and therefore must.
        Assert.False(game.State.GetObject(wall).Permanent!.IsTapped);

        TestCards.PassToStep(game, TurnStep.DeclareBlockers);

        Assert.Throws<InvalidOperationException>(() => game.DeclareBlockers(
            bob, new Dictionary<ObjectId, IReadOnlyList<ObjectId>>()));

        game.DeclareBlockers(
            bob, new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [ogre] = new[] { wall } });

        Assert.True(game.State.Combat.BlockersDeclared);
    }

    [Fact]
    public void Job_select_brings_the_equipment_its_own_wearer()
    {
        // CR 702.182a. The token is not described on the card - the keyword carries the whole
        // definition - and the attach names the thing the same effect just made, which is why
        // the two halves are one effect rather than two.
        var blade = Card(
            "Job Blade Test",
            "Job select\nEquipped creature gets +1/+1.\nEquip {2}",
            CardType.Artifact,
            subtypes: "Equipment");

        var compiled = CardCompiler.Compile(blade);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var equipment = game.Create(alice, blade, Zone.Battlefield);
        Settle(game);

        var hero = game.State.Battlefield
            .Select(game.State.GetObject)
            .Single(o => o.Card.Name == "Hero");

        Assert.Equal(1, hero.Card.Power);
        Assert.Equal(1, hero.Card.Toughness);

        // Attached, and the +1/+1 is the proof that the attachment took rather than the token
        // merely arriving beside it.
        Assert.Equal(hero.Id, game.State.GetObject(equipment).Permanent!.AttachedTo);
        Assert.Equal(2, Characteristics.Of(game.State, Pool, hero).Power);
    }

    [Fact]
    public void Reconfigure_attaches_detaches_and_stops_being_a_creature_while_worn()
    {
        // CR 702.151a and CR 702.151b. The type change is the half that distinguishes it from
        // equip: the card is a creature in its own right until it goes on somebody, and a
        // reading that left it a creature while attached would have it attacking on its own.
        var blade = Card(
            "Reconfiguring Blade Test",
            "Equipped creature gets +2/+2.\nReconfigure {2}",
            CardType.Artifact | CardType.Creature,
            1,
            3,
            subtypes: "Equipment");

        var compiled = CardCompiler.Compile(blade);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var sword = game.Create(alice, blade, Zone.Battlefield);
        var bear = game.Create(alice, TestCards.Creature("Wielder Bear Test", 2, 2), Zone.Battlefield);

        // Unattached, it is a creature of its own.
        Assert.True(Characteristics.Of(game.State, Pool, game.State.GetObject(sword)).IsCreature);

        foreach (var _ in Enumerable.Range(0, 2))
        {
            var land = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
            game.ActivateAbility(alice, land, "mana");
        }

        game.ActivateAbility(alice, sword, "reconfigure", [Target.ToPermanent(bear)]);
        Settle(game);

        Assert.Equal(bear, game.State.GetObject(sword).Permanent!.AttachedTo);
        Assert.Equal(4, Characteristics.Of(game.State, Pool, game.State.GetObject(bear)).Power);

        // Attached, it stops being a creature (CR 702.151b).
        Assert.False(Characteristics.Of(game.State, Pool, game.State.GetObject(sword)).IsCreature);

        foreach (var _ in Enumerable.Range(0, 2))
        {
            var land = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
            game.ActivateAbility(alice, land, "mana");
        }

        game.ActivateAbility(alice, sword, "unreconfigure");
        Settle(game);

        Assert.Null(game.State.GetObject(sword).Permanent!.AttachedTo);
        Assert.True(Characteristics.Of(game.State, Pool, game.State.GetObject(sword)).IsCreature);
        Assert.Equal(2, Characteristics.Of(game.State, Pool, game.State.GetObject(bear)).Power);
    }

    [Fact]
    public void An_aura_can_switch_off_the_abilities_of_what_it_enchants()
    {
        // CR 602.5c. The keyword vocabulary could already say "can't attack or block" and had no
        // way at all to say the clause that follows it on the same cards, so forty-odd lines
        // went unread for want of the shorter half.
        var pacifism = Card(
            "Total Pacifism Test",
            "Enchant creature\nEnchanted creature can't attack or block, and its activated "
                + "abilities can't be activated.",
            CardType.Enchantment,
            subtypes: "Aura");

        var compiled = CardCompiler.Compile(pacifism);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var pinger = Card(
            "Silenced Pinger Test",
            "{T}: ~ deals 1 damage to any target.",
            CardType.Creature,
            1,
            1);

        var (game, alice, bob) = InMainPhase();
        var creature = game.Create(alice, pinger, Zone.Battlefield);

        // Before the Aura lands the ability is reachable, which is what makes the refusal below
        // evidence of the Aura rather than of a card that never worked.
        Assert.Contains(
            Game.ActivatedAbilitiesOf(game.State, Pool, game.State.GetObject(creature)),
            a => a.Id == "a");

        var aura = TestCards.PutInHand(game, alice, pacifism);
        var land = game.Create(alice, TestCards.BasicLand("Plains"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");
        game.CastSpell(alice, aura, [Target.ToPermanent(creature)]);
        Settle(game);

        var why = Assert.Throws<InvalidOperationException>(
            () => game.ActivateAbility(alice, creature, "a", [Target.ToPlayer(bob)]));

        Assert.Contains("can't be activated", why.Message, StringComparison.Ordinal);
    }

    [Fact]
    public void A_predefined_token_arrives_with_the_ability_the_rule_gives_it()
    {
        // CR 111.10. The name is the whole definition - no card that makes a Blood token says
        // what one is - so the text comes from the rule. The token's body then goes through the
        // ordinary compiler, which is why this asserts the ability works rather than that the
        // token merely arrived.
        var maker = Card("Blood Maker Test", "When ~ enters, create a Blood token.",
            CardType.Creature, 1, 1);

        var compiled = CardCompiler.Compile(maker);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        game.Create(alice, maker, Zone.Battlefield);
        Settle(game);

        var blood = game.State.Battlefield
            .Select(game.State.GetObject)
            .Single(o => o.Card.Name == "Blood");

        Assert.Contains("Blood", blood.Card.Subtypes, StringComparer.Ordinal);

        // "{1}, {T}, Discard a card, Sacrifice this artifact: Draw a card" - the ability the rule
        // gives it, reachable rather than merely printed.
        Assert.Contains(
            Game.ActivatedAbilitiesOf(game.State, Pool, blood),
            a => !a.IsManaAbility);
    }

    [Fact]
    public void An_aura_trigger_can_pump_the_creature_it_is_already_on()
    {
        // The rewriter that reads "tap enchanted creature" needed the verb first, so a sentence
        // that leads with the subject went unread - and this one is a one-shot inside a trigger,
        // not the static that a bare "enchanted creature gets +1/+1" is.
        var blessing = Card(
            "Sudden Blessing Test",
            "Enchant creature\nWhen ~ enters, enchanted creature gains first strike "
                + "until end of turn.",
            CardType.Enchantment,
            subtypes: "Aura");

        var compiled = CardCompiler.Compile(blessing);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var bear = game.Create(alice, TestCards.Creature("Blessed Bear Test", 2, 2), Zone.Battlefield);

        Assert.False(
            Characteristics.Of(game.State, Pool, game.State.GetObject(bear))
                .Has(KeywordAbility.FirstStrike));

        var aura = TestCards.PutInHand(game, alice, blessing);
        var land = game.Create(alice, TestCards.BasicLand("Plains"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");
        game.CastSpell(alice, aura, [Target.ToPermanent(bear)]);
        Settle(game);

        // The creature the Aura is on, without the trigger having targeted it again.
        Assert.True(
            Characteristics.Of(game.State, Pool, game.State.GetObject(bear))
                .Has(KeywordAbility.FirstStrike));
    }

    [Fact]
    public void That_creature_in_a_trigger_means_what_the_trigger_was_about()
    {
        // With nothing targeted and nothing done yet, the pronoun can only be the trigger's
        // subject - there is no earlier clause for it to point back at. The guard matters: after
        // a clause that makes a token, "it" means the token, and answering with the trigger's
        // subject would pump the wrong creature and never fail.
        var warden = Card(
            "Haste Warden Test",
            "Whenever another creature you control enters, that creature gains haste "
                + "until end of turn.",
            CardType.Creature,
            2,
            2);

        var compiled = CardCompiler.Compile(warden);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var lord = game.Create(alice, warden, Zone.Battlefield);
        var newcomer = game.Create(alice, TestCards.Creature("Hasted Bear Test"), Zone.Battlefield);
        Settle(game);

        // The creature that entered, not the one whose ability it is - which is exactly the
        // distinction the pronoun carries.
        Assert.True(
            Characteristics.Of(game.State, Pool, game.State.GetObject(newcomer))
                .Has(KeywordAbility.Haste));

        Assert.False(
            Characteristics.Of(game.State, Pool, game.State.GetObject(lord))
                .Has(KeywordAbility.Haste));
    }

    [Fact]
    public void A_named_token_can_be_made_by_somebody_other_than_you()
    {
        // The creature-token reader had always understood "each opponent creates ..."; the named
        // one had only the bare "create", so the same sentence about a Treasure went unread.
        var bribe = Card("Bribe Test", "Each opponent creates a Treasure token.");

        var compiled = CardCompiler.Compile(bribe);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, bribe);
        var land = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");

        game.CastSpell(alice, card, targets: null);
        Settle(game);

        var treasures = game.State.Battlefield
            .Select(game.State.GetObject)
            .Where(o => o.Card.Name == "Treasure")
            .ToList();

        // One, and under the opponent's control - not the caster's, which is the whole of what
        // the subject contributes.
        var treasure = Assert.Single(treasures);
        Assert.Equal(bob, Characteristics.Of(game.State, Pool, treasure).ControllerId);
    }

    [Fact]
    public void A_targeted_discard_takes_from_that_player_and_nobody_else()
    {
        // The reader used to refuse this outright, on the grounds that the effect could only
        // name a group - which had stopped being true. At a table of more than two the two
        // readings are plainly different cards, which is what the refusal was protecting.
        var spell = Card("Targeted Discard Test", "Target player discards two cards.");

        var compiled = CardCompiler.Compile(spell);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var mine = game.State.GetPlayer(alice).Hand.Count;
        var theirs = game.State.GetPlayer(bob).Hand.Count;

        var card = TestCards.PutInHand(game, alice, spell);
        var land = game.Create(alice, TestCards.BasicLand("Swamp"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");

        game.CastSpell(alice, card, [Target.ToPlayer(bob)]);
        Settle(game);

        Assert.Equal(theirs - 2, game.State.GetPlayer(bob).Hand.Count);

        // The caster loses only the spell itself.
        Assert.Equal(mine, game.State.GetPlayer(alice).Hand.Count);
    }

    [Fact]
    public void A_creature_barred_from_one_attacker_may_still_block_another()
    {
        // The blanket can't-block flag says "blocks nothing"; this names one attacker and leaves
        // the creature free against everything else, which is the whole of the difference.
        var menacer = Card(
            "Barring Ogre Test",
            "{1}: Target creature can't block ~ this turn.",
            CardType.Creature,
            3,
            3,
            KeywordAbility.Haste);

        var compiled = CardCompiler.Compile(menacer);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var ogre = game.Create(alice, menacer, Zone.Battlefield);
        var other = game.Create(
            alice,
            Card("Other Attacker Test", string.Empty, CardType.Creature, 1, 1, KeywordAbility.Haste),
            Zone.Battlefield);

        var wall = game.Create(bob, TestCards.Creature("Barred Wall Test", 0, 4), Zone.Battlefield);

        var land = game.Create(alice, TestCards.BasicLand("Mountain"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");
        game.ActivateAbility(alice, ogre, "a", [Target.ToPermanent(wall)]);
        Settle(game);

        TestCards.PassToStep(game, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget>
            {
                [ogre] = AttackTarget.Player(bob),
                [other] = AttackTarget.Player(bob),
            });

        Settle(game);
        TestCards.PassToStep(game, TurnStep.DeclareBlockers);

        Assert.Throws<InvalidOperationException>(() => game.DeclareBlockers(
            bob, new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [ogre] = new[] { wall } }));

        // The other attacker is nothing to do with the restriction.
        game.DeclareBlockers(
            bob, new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [other] = new[] { wall } });

        Assert.True(game.State.Combat.BlockersDeclared);
    }

    [Fact]
    public void A_conditional_bonus_may_carry_an_ability_with_it()
    {
        // The consumer had always emitted the bonus and the ability independently; only the
        // pattern could not capture both at once, so a card granting both went unread while
        // either half alone read perfectly.
        var brute = Card(
            "Threshold Brute Test",
            "As long as you control a Swamp, ~ gets +2/+0 and can't block.",
            CardType.Creature,
            2,
            2);

        var compiled = CardCompiler.Compile(brute);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var ogre = game.Create(alice, brute, Zone.Battlefield);

        // Without the Swamp neither half applies, which is what makes the pair below evidence of
        // the condition rather than of a card that always did this.
        var before = Characteristics.Of(game.State, Pool, game.State.GetObject(ogre));
        Assert.Equal(2, before.Power);
        Assert.False(before.Has(KeywordAbility.CantBlock));

        game.Create(alice, TestCards.BasicLand("Swamp"), Zone.Battlefield);

        var after = Characteristics.Of(game.State, Pool, game.State.GetObject(ogre));
        Assert.Equal(4, after.Power);
        Assert.True(after.Has(KeywordAbility.CantBlock));
    }

    [Fact]
    public void Another_target_in_a_graveyard_excludes_the_card_that_said_it()
    {
        // The reader anchored on the word "target", and both the count and the "another" come
        // in front of it - so phrases the target grammar has understood all along never reached
        // it. On a death trigger the word earns its keep: the source is in that graveyard too.
        var reclaimer = Card(
            "Scrap Reclaimer Test",
            "When ~ dies, return another target artifact card from your graveyard to your hand.",
            CardType.Artifact | CardType.Creature,
            2,
            2);

        var compiled = CardCompiler.Compile(reclaimer);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var golem = game.Create(alice, reclaimer, Zone.Battlefield);

        var scrap = game.Create(
            alice,
            Card("Buried Scrap Test", string.Empty, CardType.Artifact),
            Zone.Graveyard);

        game.MarkDamage(golem, 2);
        TestCards.PassUntil(game, () => game.State.Choice is not null);

        // The Reclaimer is in the graveyard now too, and "another" is what keeps it off the list.
        var offered = game.State.Choice!.Options;
        Assert.Contains(offered, o => o.Id.EndsWith(scrap.Value.ToString("N"), StringComparison.Ordinal));
        Assert.DoesNotContain(
            offered,
            o => o.Label.Contains("Scrap Reclaimer Test", StringComparison.Ordinal));
    }

    [Fact]
    public void Suspecting_a_creature_gives_it_menace_and_stops_it_blocking()
    {
        // CR 701.60c. A designation rather than an ability, and it needs no expiry of its own:
        // "until it leaves the battlefield" is what a zone change already does to an effect
        // keyed on the old object (CR 400.7).
        var spell = Card("Suspicion Test", "Suspect target creature.");

        var compiled = CardCompiler.Compile(spell);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var bear = game.Create(bob, TestCards.Creature("Suspected Bear Test", 2, 2), Zone.Battlefield);

        var before = Characteristics.Of(game.State, Pool, game.State.GetObject(bear));
        Assert.False(before.Has(KeywordAbility.Menace));
        Assert.False(before.Has(KeywordAbility.CantBlock));

        var card = TestCards.PutInHand(game, alice, spell);
        var land = game.Create(alice, TestCards.BasicLand("Island"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");
        game.CastSpell(alice, card, [Target.ToPermanent(bear)]);
        Settle(game);

        var after = Characteristics.Of(game.State, Pool, game.State.GetObject(bear));
        Assert.True(after.Has(KeywordAbility.Menace));
        Assert.True(after.Has(KeywordAbility.CantBlock));
    }

    [Fact]
    public void A_decayed_creature_attacks_once_and_dies_after_the_damage()
    {
        // CR 702.147a. The sacrifice is a delayed trigger and not part of attacking, which is
        // the whole point: a decayed attacker deals its combat damage and dies afterwards.
        var zombie = Card(
            "Decayed Zombie Test",
            "Decayed",
            CardType.Creature,
            2,
            2,
            KeywordAbility.Haste);

        var compiled = CardCompiler.Compile(zombie);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var corpse = game.Create(alice, zombie, Zone.Battlefield);

        Assert.True(
            Characteristics.Of(game.State, Pool, game.State.GetObject(corpse))
                .Has(KeywordAbility.CantBlock));

        var life = game.State.GetPlayer(bob).Life;

        TestCards.PassToStep(game, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [corpse] = AttackTarget.Player(bob) });

        TestCards.PassToStep(game, TurnStep.PostcombatMain);

        // The damage landed, and only then did it go.
        Assert.Equal(life - 2, game.State.GetPlayer(bob).Life);
        Assert.DoesNotContain(corpse, game.State.Battlefield);
        Assert.Contains(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Decayed Zombie Test");
    }

    [Fact]
    public void A_goaded_creature_must_attack_and_may_not_attack_the_player_who_goaded_it()
    {
        // CR 701.15b. Two requirements in one designation, and the second only means anything at
        // a table of more than two - which is why this is the one test here that needs four
        // seats. In a duel a goaded creature simply has to attack, and that is correct.
        var spell = Card("Goading Test", "Goad target creature.");

        var compiled = CardCompiler.Compile(spell);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, seats) = FourPlayers();
        var (alice, bob, carol) = (seats[0], seats[1], seats[2]);

        var bear = game.Create(
            bob,
            Card("Goaded Bear Test", string.Empty, CardType.Creature, 2, 2, KeywordAbility.Haste),
            Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, spell);
        var land = game.Create(alice, TestCards.BasicLand("Mountain"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");
        game.CastSpell(alice, card, [Target.ToPermanent(bear)]);
        Settle(game);

        var computed = Characteristics.Of(game.State, Pool, game.State.GetObject(bear));

        // It must attack (CR 701.15b), and Alice is off the menu while anybody else is on it.
        Assert.True(computed.Has(KeywordAbility.MustAttack));
        Assert.Contains(alice, computed.GoadedBy);

        Assert.NotNull(CombatRules.CannotAttack(
            game.State, Pool, game.State.GetObject(bear), bob, alice));

        Assert.Null(CombatRules.CannotAttack(
            game.State, Pool, game.State.GetObject(bear), bob, carol));
    }

    [Fact]
    public void That_player_controls_names_the_player_the_trigger_was_about()
    {
        // Two hundred and twenty lines used this phrase and not one of them read. "That player"
        // is decided by the triggering event, not chosen (CR 603.2), and it is recorded on the
        // ability when it triggers because by the time targets are picked nothing else knows.
        var raider = Card(
            "Raiding Rogue Test",
            "Whenever ~ deals combat damage to a player, destroy target creature that player "
                + "controls.",
            CardType.Creature,
            2,
            2,
            KeywordAbility.Haste);

        var compiled = CardCompiler.Compile(raider);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, seats) = FourPlayers();
        var (alice, bob, carol) = (seats[0], seats[1], seats[2]);

        var rogue = game.Create(alice, raider, Zone.Battlefield);
        var theirs = game.Create(bob, TestCards.Creature("Struck Bear Test", 2, 2), Zone.Battlefield);
        var elsewhere = game.Create(carol, TestCards.Creature("Spared Bear Test", 2, 2), Zone.Battlefield);

        TestCards.PassToStep(game, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [rogue] = AttackTarget.Player(bob) });

        TestCards.PassUntil(
            game,
            () => game.State.Choice is { } asking
                && asking.Options.Any(o =>
                    o.Id.EndsWith(theirs.Value.ToString("N"), StringComparison.Ordinal)));

        Assert.Equal(18, game.State.GetPlayer(bob).Life);

        // The damaged player's creature is offered and a third player's is not, which is the
        // whole of what the phrase contributes - a reading that ignored it would offer both.
        var asked = game.State.Choice!;
        Assert.DoesNotContain(
            asked.Options,
            o => o.Id.EndsWith(elsewhere.Value.ToString("N"), StringComparison.Ordinal));

        game.Choose(
            asked.PlayerId,
            [asked.Options.Single(o =>
                o.Id.EndsWith(theirs.Value.ToString("N"), StringComparison.Ordinal)).Id]);

        Settle(game);

        Assert.DoesNotContain(theirs, game.State.Battlefield);
        Assert.Contains(elsewhere, game.State.Battlefield);
    }

    [Fact]
    public void A_manifested_card_arrives_as_a_two_two_and_can_be_paid_for_face_up()
    {
        // CR 701.40a and CR 701.40b. Nothing here describes a 2/2 - a face-down permanent
        // already is one - and nothing remembers a "real" card, because the card underneath was
        // never changed. Turning it up pays the card's own mana cost, which is what tells a
        // manifested permanent from a morphed one (CR 702.37e).
        var spell = Card("Manifesting Test", "Manifest the top card of your library.");

        var compiled = CardCompiler.Compile(spell);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();

        // A known creature card on top, so the face-up half has something to pay for.
        game.Create(alice, TestCards.Creature("Hidden Giant Test", 5, 5), Zone.Library);

        var card = TestCards.PutInHand(game, alice, spell);
        var land = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");
        game.CastSpell(alice, card, targets: null);
        Settle(game);

        var manifested = game.State.Battlefield
            .Select(game.State.GetObject)
            .Single(o => o.Permanent?.IsManifested == true);

        // Face down it is a 2/2 with no name of its own, whatever the card underneath says.
        var down = Characteristics.Of(game.State, Pool, manifested);
        Assert.Equal(2, down.Power);
        Assert.Equal(2, down.Toughness);

        game.TurnFaceUp(alice, manifested.Id);

        var up = Characteristics.Of(game.State, Pool, game.State.GetObject(manifested.Id));
        Assert.Equal(5, up.Power);
        Assert.False(game.State.GetObject(manifested.Id).Permanent!.IsManifested);
    }

    [Fact]
    public void Conniving_draws_then_discards_and_the_counter_depends_on_what_went()
    {
        // CR 701.50a. The draw happens as the effect resolves and the discard cannot - which
        // card goes is the player's to say, and whether it was a land decides the counter. So
        // this asserts both answers, because a reading that always gave the counter would pass
        // the happy path and be a strictly better card.
        var rogue = Card(
            "Conniving Rogue Test",
            "When ~ enters, it connives.",
            CardType.Creature,
            2,
            2);

        var compiled = CardCompiler.Compile(rogue);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();

        var land = TestCards.PutInHand(game, alice, TestCards.BasicLand("Island"));
        var spell = TestCards.PutInHand(game, alice, TestCards.Creature("Fodder Bear Test"));

        var first = game.Create(alice, rogue, Zone.Battlefield);
        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.Connive });

        var handBefore = game.State.GetPlayer(alice).Hand.Count;

        // Discarding a land earns nothing (CR 701.50a).
        game.Choose(game.State.Choice!.PlayerId, [land.Value.ToString("N")]);
        Settle(game);

        Assert.Equal(handBefore - 1, game.State.GetPlayer(alice).Hand.Count);
        Assert.Equal(2, Characteristics.Of(game.State, Pool, game.State.GetObject(first)).Power);

        // A nonland card does.
        var second = game.Create(alice, rogue, Zone.Battlefield);
        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.Connive });
        game.Choose(game.State.Choice!.PlayerId, [spell.Value.ToString("N")]);
        Settle(game);

        Assert.Equal(3, Characteristics.Of(game.State, Pool, game.State.GetObject(second)).Power);
    }

    [Fact]
    public void A_targeted_connive_draws_for_that_creatures_controller_and_grows_it()
    {
        // "Target creature you control connives" - the permanent named is the one that connives,
        // so it is its controller who draws and it that grows. Defaulting either to the source
        // would draw the right cards onto the wrong player.
        var spell = Card("Directed Connive Test", "Target creature you control connives.");

        var compiled = CardCompiler.Compile(spell);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var bear = game.Create(alice, TestCards.Creature("Conniving Bear Test", 2, 2), Zone.Battlefield);
        var fodder = TestCards.PutInHand(game, alice, TestCards.Creature("Discarded Bear Test"));

        var card = TestCards.PutInHand(game, alice, spell);
        var land = game.Create(alice, TestCards.BasicLand("Island"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");
        game.CastSpell(alice, card, [Target.ToPermanent(bear)]);

        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.Connive });
        game.Choose(game.State.Choice!.PlayerId, [fodder.Value.ToString("N")]);
        Settle(game);

        // The counter went on the creature the spell named, not on anything else.
        Assert.Equal(3, Characteristics.Of(game.State, Pool, game.State.GetObject(bear)).Power);
        Assert.Contains(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Discarded Bear Test");
    }

    [Fact]
    public void Manifest_dread_manifests_the_chosen_card_and_buries_the_other()
    {
        // CR 701.62a. Nothing moves until the player has chosen, because which card is
        // manifested is theirs to say - and the one they did not pick goes to the graveyard,
        // which is the half a reading that only manifested would silently drop.
        var spell = Card("Dread Test", "Manifest dread.");

        var compiled = CardCompiler.Compile(spell);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();

        // Two known cards on top, most recently created first.
        game.Create(alice, TestCards.Creature("Dread Second Test", 3, 3), Zone.Library);
        game.Create(alice, TestCards.Creature("Dread First Test", 4, 4), Zone.Library);

        var card = TestCards.PutInHand(game, alice, spell);
        var land = game.Create(alice, TestCards.BasicLand("Swamp"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");
        game.CastSpell(alice, card, targets: null);

        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.ManifestDread });

        var asked = game.State.Choice!;
        Assert.Equal(2, asked.Options.Count);

        var keep = asked.Options.Single(o => o.Label == "Dread Second Test");
        game.Choose(asked.PlayerId, [keep.Id]);
        Settle(game);

        var manifested = game.State.Battlefield
            .Select(game.State.GetObject)
            .Single(o => o.Permanent?.IsManifested == true);

        // Face down it is a 2/2 whatever the card underneath is, and the other one is buried.
        Assert.Equal(2, Characteristics.Of(game.State, Pool, manifested).Power);
        Assert.Contains(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Dread First Test");
    }

    [Fact]
    public void Exerting_costs_the_next_untap_and_declining_costs_nothing()
    {
        // CR 701.43a. A free yes-or-no with a consequence, which is what an optional payment of
        // nothing already is. Both answers are asserted: a reading that always exerted would
        // pass the interesting half and quietly take an untap the player never agreed to.
        var soldier = Card(
            "Exerting Soldier Test",
            "You may exert ~ as it attacks. When you do, it gets +2/+2 until end of turn.",
            CardType.Creature,
            2,
            2,
            KeywordAbility.Haste);

        var compiled = CardCompiler.Compile(soldier);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var trooper = game.Create(alice, soldier, Zone.Battlefield);

        TestCards.PassToStep(game, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [trooper] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.OptionalPayment });

        var asked = game.State.Choice!;
        game.Choose(asked.PlayerId, [asked.Options.First(o => o.Label.StartsWith("Exert", StringComparison.Ordinal)).Id]);
        Settle(game);

        // The payload happened and the untap is owed.
        Assert.Equal(4, Characteristics.Of(game.State, Pool, game.State.GetObject(trooper)).Power);
        Assert.True(game.State.GetObject(trooper).Permanent!.SkipsNextUntap);

        // And declining costs nothing at all. A fresh game, because the answer is made once per
        // attack and the first one has been given.
        var (second, carol, dave) = InMainPhase();
        var declining = second.Create(carol, soldier, Zone.Battlefield);

        TestCards.PassToStep(second, TurnStep.DeclareAttackers);
        second.DeclareAttackers(
            carol,
            new Dictionary<ObjectId, AttackTarget> { [declining] = AttackTarget.Player(dave) });

        TestCards.PassUntil(second, () => second.State.Choice is { Kind: ChoiceKind.OptionalPayment });

        var offer = second.State.Choice!;
        second.Choose(
            offer.PlayerId,
            [offer.Options.First(o => !o.Label.StartsWith("Exert", StringComparison.Ordinal)).Id]);

        Settle(second);

        Assert.Equal(2, Characteristics.Of(second.State, Pool, second.State.GetObject(declining)).Power);
        Assert.False(second.State.GetObject(declining).Permanent!.SkipsNextUntap);
    }

    [Fact]
    public void Populate_copies_a_creature_token_and_will_not_copy_a_real_card()
    {
        // CR 701.36a. Not a target - the choice is made on resolution, so nothing is picked when
        // the spell is cast. The nontoken creature is the discriminator: populate copies tokens
        // and only tokens, and a reading that offered the whole board would be a far better card.
        var spell = Card("Populating Test", "Populate.");

        var compiled = CardCompiler.Compile(spell);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();

        var token = game.Create(
            alice,
            Card("Saproling Token Test", string.Empty, CardType.Creature | CardType.Token, 1, 1),
            Zone.Battlefield);

        game.Create(alice, TestCards.Creature("Real Bear Test", 2, 2), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, spell);
        var land = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");
        game.CastSpell(alice, card, targets: null);

        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.Populate });

        var asked = game.State.Choice!;
        var only = Assert.Single(asked.Options);
        Assert.Equal(token.Value.ToString("N"), only.Id);

        game.Choose(asked.PlayerId, [only.Id]);
        Settle(game);

        var copies = game.State.Battlefield
            .Select(game.State.GetObject)
            .Count(o => o.Card.Name == "Saproling Token Test");

        Assert.Equal(2, copies);
    }

    [Fact]
    public void Exploit_offers_a_sacrifice_and_the_second_line_hears_about_it()
    {
        // CR 702.110a and CR 702.110b. Every exploit card is two lines, and the second one asks
        // a question a plain sacrifice cannot answer: sacrifices happen for all sorts of reasons
        // and nothing about the move says which of them this was. Hence an event of its own.
        var demon = Card(
            "Exploiting Demon Test",
            "Exploit\nWhen ~ exploits a creature, each opponent loses 2 life.",
            CardType.Creature,
            3,
            3);

        var compiled = CardCompiler.Compile(demon);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var fodder = game.Create(alice, TestCards.Creature("Exploited Bear Test", 2, 2), Zone.Battlefield);
        var life = game.State.GetPlayer(bob).Life;

        game.Create(alice, demon, Zone.Battlefield);
        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.Exploit });

        // Declining is on the same list as the creatures, because the card asks one question.
        var asked = game.State.Choice!;
        Assert.Contains(asked.Options, o => o.Id == "none");

        game.Choose(
            asked.PlayerId,
            [asked.Options.Single(o => o.Label == "Exploited Bear Test").Id]);

        Settle(game);

        Assert.DoesNotContain(fodder, game.State.Battlefield);
        Assert.Equal(life - 2, game.State.GetPlayer(bob).Life);
    }

    [Fact]
    public void Incubating_makes_a_double_faced_token_that_flips_into_a_creature()
    {
        // CR 701.53a and CR 111.10i. The counters go on in the same breath as the token is made,
        // because the rule says it enters with them - a creature that arrived at 0/0 and grew a
        // moment later would already have died to state-based actions.
        var spell = Card("Incubating Test", "Incubate 2.");

        var compiled = CardCompiler.Compile(spell);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, spell);

        foreach (var _ in Enumerable.Range(0, 3))
        {
            var source = game.Create(alice, TestCards.BasicLand("Island"), Zone.Battlefield);
            game.ActivateAbility(alice, source, "mana");
        }

        game.CastSpell(alice, card, targets: null);
        Settle(game);

        var incubator = game.State.Battlefield
            .Select(game.State.GetObject)
            .Single(o => o.Card.Name == "Incubator");

        // Front face: an artifact, not a creature, carrying the counters it entered with.
        Assert.False(Characteristics.Of(game.State, Pool, incubator).IsCreature);
        Assert.Equal(2, incubator.Permanent!.Counters[CounterKinds.PlusOnePlusOne]);

        game.ActivateAbility(alice, incubator.Id, "a");
        Settle(game);

        // Back face: a 0/0 Phyrexian, which the two counters keep alive.
        var flipped = Characteristics.Of(game.State, Pool, game.State.GetObject(incubator.Id));
        Assert.True(flipped.IsCreature);
        Assert.Equal(2, flipped.Power);
        Assert.Contains(incubator.Id, game.State.Battlefield);
    }

    [Fact]
    public void Blighting_puts_minus_counters_on_a_creature_you_choose()
    {
        // CR 701.68a. Bolster's mirror: the same request asking which candidate the counters go
        // on, differing in the set (bolster is forced onto the least tough, this is free) and in
        // which counter. The opponent's creature is the discriminator - it is yours to blight.
        var spell = Card("Blighting Test", "Blight 2.");

        var compiled = CardCompiler.Compile(spell);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();

        // Two of the caster's own, because one candidate is not a choice - the engine applies it
        // and asks nothing, which would leave the interesting half of this untested.
        var mine = game.Create(alice, TestCards.Creature("Blighted Bear Test", 3, 3), Zone.Battlefield);
        game.Create(alice, TestCards.Creature("Other Bear Test", 3, 3), Zone.Battlefield);
        var theirs = game.Create(bob, TestCards.Creature("Safe Bear Test", 3, 3), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, spell);
        var land = game.Create(alice, TestCards.BasicLand("Swamp"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");
        game.CastSpell(alice, card, targets: null);

        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.ChooseForCounters });

        // Both of the caster's are candidates and the opponent's is not - it is yours to blight.
        var asked = game.State.Choice!;
        Assert.Equal(2, asked.Options.Count);
        Assert.DoesNotContain(
            asked.Options,
            o => o.Id == theirs.Value.ToString("N"));

        game.Choose(asked.PlayerId, [mine.Value.ToString("N")]);
        Settle(game);

        Assert.Equal(1, Characteristics.Of(game.State, Pool, game.State.GetObject(mine)).Power);
        Assert.Equal(3, Characteristics.Of(game.State, Pool, game.State.GetObject(theirs)).Power);
    }

    [Fact]
    public void Discovering_offers_the_card_free_and_draws_it_if_you_decline()
    {
        // CR 701.57a. Cascade's twin, and the two things that separate them are both asserted:
        // the comparison is "N or less" where cascade is strictly less, and a declined discover
        // is drawn where a declined cascade stays in exile.
        var spell = Card("Discovering Test", "Discover 3.");

        var compiled = CardCompiler.Compile(spell);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();

        // Exactly three, so a strictly-less reading would exile past it and find nothing.
        game.Create(
            alice,
            new CardDefinition
            {
                OracleId = "oracle-discovered-bear-test",
                Name = "Discovered Bear Test",
                Cmc = 3,
                CardTypes = CardType.Creature,
                Power = 2,
                Toughness = 2,
            },
            Zone.Library);

        var card = TestCards.PutInHand(game, alice, spell);
        var land = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");
        game.CastSpell(alice, card, targets: null);
        Settle(game);

        // Found, exiled, and on offer.
        var offered = game.State.Exile
            .Select(game.State.GetObject)
            .SingleOrDefault(o => o.Card.Name == "Discovered Bear Test");

        Assert.NotNull(offered);
        Assert.True(offered.MayCastFree);
        Assert.True(offered.ToHandIfCastDeclined);

        // Declining draws it, which is the half cascade does not have.
        TestCards.PassToStep(game, TurnStep.PostcombatMain);

        Assert.Contains(
            game.State.GetPlayer(alice).Hand,
            id => game.State.GetObject(id).Card.Name == "Discovered Bear Test");
    }

    [Fact]
    public void A_warped_creature_leaves_at_end_of_turn_and_can_be_cast_again_later()
    {
        // CR 702.185a. Warp buys the turn it was cast on and nothing more: the permanent is
        // exiled at the next end step, and its owner may cast it properly once that turn has
        // ended. Both halves are asserted, because either alone is a different card - the first
        // without the second is a spell that eats itself.
        var raider = Card(
            "Warping Raider Test",
            "Warp {1}{R}",
            CardType.Creature,
            3,
            3);

        var compiled = CardCompiler.Compile(raider);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, raider);

        foreach (var _ in Enumerable.Range(0, 2))
        {
            var source = game.Create(alice, TestCards.BasicLand("Mountain"), Zone.Battlefield);
            game.ActivateAbility(alice, source, "mana");
        }

        game.CastSpell(alice, card, targets: null, alternativeCost: true);
        Settle(game);

        var arrived = game.State.Battlefield
            .Select(game.State.GetObject)
            .Single(o => o.Card.Name == "Warping Raider Test");

        // It is here for this turn, which is what warp is for.
        Assert.Equal(3, Characteristics.Of(game.State, Pool, arrived).Power);

        TestCards.PassToTurn(game, game.State.TurnNumber + 1);

        // And gone at the end step, into exile, remembering how it left.
        var exiled = game.State.Exile
            .Select(game.State.GetObject)
            .Single(o => o.Card.Name == "Warping Raider Test");

        Assert.NotNull(exiled.WarpedOnTurn);
        Assert.DoesNotContain(arrived.Id, game.State.Battlefield);
    }

    [Fact]
    public void Becoming_a_chosen_creature_type_replaces_the_types_it_had()
    {
        // CR 205.1b: changing a permanent's creature types removes the ones it had, unless the
        // card says "in addition to its other types" - and this one does not. The Bear going
        // away is the assertion that matters; a reading that only added would leave a card that
        // answers to two tribes at once.
        var shifter = Card(
            "Shapeshifting Test",
            "{1}: ~ becomes the creature type of your choice until end of turn.",
            CardType.Creature,
            2,
            2,
            subtypes: "Bear");

        var compiled = CardCompiler.Compile(shifter);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var creature = game.Create(alice, shifter, Zone.Battlefield);

        // A Goblin somewhere in the game, so the type is on the offered list.
        game.Create(alice, Card("Goblin Scout Test", string.Empty, CardType.Creature, 1, 1,
            subtypes: "Goblin"), Zone.Library);

        var land = game.Create(alice, TestCards.BasicLand("Mountain"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");
        game.ActivateAbility(alice, creature, "a");

        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.ChooseCreatureType });

        var asked = game.State.Choice!;
        Assert.Contains(asked.Options, o => o.Id == "Goblin");

        game.Choose(asked.PlayerId, ["Goblin"]);
        Settle(game);

        var computed = Characteristics.Of(game.State, Pool, game.State.GetObject(creature));
        Assert.True(computed.HasSubtype("Goblin"));
        Assert.False(computed.HasSubtype("Bear"));
    }

    [Fact]
    public void Clashing_asks_both_players_then_pays_out_only_to_the_higher_card()
    {
        // CR 701.30a-d. The decisions come before the winner is worked out, because they change
        // what winning does - and the win is strictly higher, so a tie pays nobody. Both halves
        // are asserted, since a reading that always paid out would look right on the happy path.
        var spell = Card(
            "Clashing Test",
            "Clash with an opponent. If you win, draw a card.");

        var compiled = CardCompiler.Compile(spell);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();

        // A five on top for the caster, a one for the opponent.
        game.Create(alice, Expensive("Big Clash Card Test", 5), Zone.Library);
        game.Create(bob, Expensive("Small Clash Card Test", 1), Zone.Library);

        var card = TestCards.PutInHand(game, alice, spell);
        var land = game.Create(alice, TestCards.BasicLand("Island"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");

        var handBefore = game.State.GetPlayer(alice).Hand.Count;
        game.CastSpell(alice, card, targets: null);

        // Each clashing player is asked where their revealed card goes, in turn order.
        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.ClashKeepOnTop });
        Assert.Equal(alice, game.State.Choice!.PlayerId);
        game.Choose(alice, ["bottom"]);

        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.ClashKeepOnTop });
        Assert.Equal(bob, game.State.Choice!.PlayerId);
        game.Choose(bob, ["top"]);

        Settle(game);

        // Five beats one, so the caster drew - and not the card they put on the bottom. The
        // spell itself left hand as it was cast, so the count comes back to where it started.
        Assert.Equal(handBefore, game.State.GetPlayer(alice).Hand.Count);
        Assert.DoesNotContain(
            game.State.GetPlayer(alice).Hand,
            id => game.State.GetObject(id).Card.Name == "Big Clash Card Test");
    }

    /// <summary>A card of a stated mana value, for the clash comparison.</summary>
    private static CardDefinition Expensive(string name, int manaValue) => new()
    {
        OracleId = "oracle-" + name.ToLowerInvariant().Replace(' ', '-'),
        Name = name,
        Cmc = manaValue,
        CardTypes = CardType.Sorcery,
    };

    [Fact]
    public void Encore_makes_a_token_per_opponent_each_aimed_at_one_of_them()
    {
        // CR 702.141a. The tokens are not created attacking - encore is sorcery-speed, so there
        // is no combat yet. They are created with a requirement instead, and the four-seat table
        // is what makes that requirement mean anything: one token per opponent, each barred from
        // attacking anybody but its own.
        var singer = Card(
            "Encore Singer Test",
            "Encore {2}",
            CardType.Creature,
            2,
            2);

        var compiled = CardCompiler.Compile(singer);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, seats) = FourPlayers();
        var (alice, bob, carol) = (seats[0], seats[1], seats[2]);

        var dead = game.Create(alice, singer, Zone.Graveyard);

        foreach (var _ in Enumerable.Range(0, 2))
        {
            var land = game.Create(alice, TestCards.BasicLand("Mountain"), Zone.Battlefield);
            game.ActivateAbility(alice, land, "mana");
        }

        game.ActivateAbility(alice, dead, "encore");
        Settle(game);

        var tokens = game.State.Battlefield
            .Select(game.State.GetObject)
            .Where(o => o.Card.Name == "Encore Singer Test")
            .ToList();

        // One per opponent, three at a four-seat table.
        Assert.Equal(3, tokens.Count);

        // Each is aimed at exactly one opponent, and refused anywhere else.
        var aimed = tokens
            .Select(o => Characteristics.Of(game.State, Pool, o).MustAttackPlayer)
            .ToList();

        Assert.Equal(3, aimed.Distinct().Count());
        Assert.DoesNotContain(alice, aimed);

        var atBob = tokens.Single(o =>
            Characteristics.Of(game.State, Pool, o).MustAttackPlayer == bob);

        Assert.Null(CombatRules.CannotAttack(game.State, Pool, atBob, alice, bob));
        Assert.NotNull(CombatRules.CannotAttack(game.State, Pool, atBob, alice, carol));
    }

    [Fact]
    public void The_Ring_tempts_you_and_its_abilities_arrive_one_temptation_at_a_time()
    {
        // CR 701.54a-c. The Ring is an emblem the rules hand out, not a card, so its wording
        // lives in the comprehensive rules and its abilities are granted to the bearer as its
        // characteristics are computed. Each is "as long as the Ring has tempted you N or more
        // times", so they accumulate - which is what this walks up.
        // An enchantment, so the only creature on the board is the one meant to bear the Ring -
        // a second candidate would make the choice ambiguous and this test about Settle's taste.
        var tempter = Card(
            "Tempting Test",
            "When ~ enters, the Ring tempts you.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(tempter);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var bearer = game.Create(alice, TestCards.Creature("Ring Bearer Test", 2, 2), Zone.Battlefield);

        // Before any temptation it is an ordinary creature.
        var before = Characteristics.Of(game.State, Pool, game.State.GetObject(bearer));
        Assert.False(before.IsLegendary);
        Assert.False(before.CantBeBlockedByGreaterPower);

        // One temptation: the only creature is chosen without asking, and gets the first ability.
        game.Create(alice, tempter, Zone.Battlefield);
        Settle(game);

        Assert.Equal(1, game.State.GetPlayer(alice).RingTemptations);
        Assert.Equal(bearer, game.State.GetPlayer(alice).RingBearer);

        var carried = Characteristics.Of(game.State, Pool, game.State.GetObject(bearer));
        Assert.True(carried.IsLegendary);
        Assert.True(carried.CantBeBlockedByGreaterPower);

        // And a bigger creature may not block it, which is what that flag is for.
        var bigger = game.Create(bob, TestCards.Creature("Bigger Blocker Test", 5, 5), Zone.Battlefield);
        Assert.NotNull(CombatRules.CannotBlock(
            game.State, Pool, game.State.GetObject(bigger), game.State.GetObject(bearer), bob));

        // A second temptation brings the second ability, and no more than that.
        game.Create(alice, tempter, Zone.Battlefield);
        Settle(game);

        Assert.Equal(2, game.State.GetPlayer(alice).RingTemptations);

        var twice = Characteristics.Of(game.State, Pool, game.State.GetObject(bearer));
        Assert.Contains(twice.GrantedTriggers, a => a.Id == "the-ring-2");
        Assert.DoesNotContain(twice.GrantedTriggers, a => a.Id == "the-ring-3");
    }

    [Fact]
    public void A_creature_that_escaped_arrives_with_counters_and_one_cast_normally_does_not()
    {
        // CR 702.139b. Not the same as entering with counters: they arrive only when the
        // creature got here by escaping, and by the time the permanent exists the spell that
        // knew that is a different object (CR 400.7). Both halves are asserted, because a
        // reading that always gave the counters would pass the interesting one.
        var horror = Card(
            "Escaping Horror Test",
            "Escape—{1}{B}, Exile two other cards from your graveyard."
                + "\n~ escapes with a +1/+1 counter on it.",
            CardType.Creature,
            2,
            2);

        var compiled = CardCompiler.Compile(horror);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();

        // Cast from hand: no escape, no counter.
        var fromHand = TestCards.PutInHand(game, alice, horror);

        foreach (var _ in Enumerable.Range(0, 2))
        {
            var land = game.Create(alice, TestCards.BasicLand("Swamp"), Zone.Battlefield);
            game.ActivateAbility(alice, land, "mana");
        }

        game.CastSpell(alice, fromHand, targets: null);
        Settle(game);

        var plain = game.State.Battlefield
            .Select(game.State.GetObject)
            .Single(o => o.Card.Name == "Escaping Horror Test");

        Assert.Equal(2, Characteristics.Of(game.State, Pool, plain).Power);
        Assert.False(plain.Permanent!.Counters.ContainsKey(CounterKinds.PlusOnePlusOne));

        // Now the same card cast out of the graveyard for its escape cost.
        var buried = game.Create(alice, horror, Zone.Graveyard);
        var fuel = Enumerable.Range(0, 2)
            .Select(i => game.Create(alice, TestCards.Creature($"Escape Fuel {i} Test"), Zone.Graveyard))
            .ToList();

        foreach (var _ in Enumerable.Range(0, 2))
        {
            var land = game.Create(alice, TestCards.BasicLand("Swamp"), Zone.Battlefield);
            game.ActivateAbility(alice, land, "mana");
        }

        game.CastSpell(alice, buried, targets: null, costPayment: fuel);
        Settle(game);

        var escaped = game.State.Battlefield
            .Select(game.State.GetObject)
            .Single(o => o.Card.Name == "Escaping Horror Test" && o.Id != plain.Id);

        // The counter is the whole difference between the two halves of this test.
        Assert.Equal(1, escaped.Permanent!.Counters[CounterKinds.PlusOnePlusOne]);
        Assert.Equal(3, Characteristics.Of(game.State, Pool, escaped).Power);
    }

    [Fact]
    public void A_chosen_return_may_name_a_phrase_and_may_exclude_the_source()
    {
        // The noun was a single word, so "a basic land" and "another creature" went unread -
        // both of which the target grammar has understood for a long time. "Another" is the half
        // that earns the test: on a creature's own enter trigger it is the difference between
        // bouncing something else and bouncing itself.
        var bouncer = Card(
            "Bouncing Bear Test",
            "When ~ enters, return another creature you control to its owner's hand.",
            CardType.Creature,
            2,
            2);

        var compiled = CardCompiler.Compile(bouncer);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var other = game.Create(alice, TestCards.Creature("Bounced Bear Test", 1, 1), Zone.Battlefield);

        var arrival = game.Create(alice, bouncer, Zone.Battlefield);
        Settle(game);

        // The other creature went; the one whose ability it is stayed, which is what "another"
        // contributes and the only thing that distinguishes this from bouncing itself.
        Assert.DoesNotContain(other, game.State.Battlefield);
        Assert.Contains(arrival, game.State.Battlefield);
        Assert.Contains(
            game.State.GetPlayer(alice).Hand,
            id => game.State.GetObject(id).Card.Name == "Bounced Bear Test");
    }

    [Fact]
    public void A_trigger_can_sweep_a_group_naming_the_source_as_it()
    {
        // The player-scope reader was widened to "it deals" earlier for the same reason: a
        // trigger has already named its source, so the sentence that follows says "it". The two
        // halves of one grammar had drifted apart and only one of them was fixed.
        var bomb = Card(
            "Sweeping Bomb Test",
            "When ~ enters, it deals 2 damage to each other creature.",
            CardType.Creature,
            3,
            3);

        var compiled = CardCompiler.Compile(bomb);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var mine = game.Create(alice, TestCards.Creature("Swept Bear Test", 2, 2), Zone.Battlefield);
        var theirs = game.Create(bob, TestCards.Creature("Swept Ogre Test", 4, 4), Zone.Battlefield);

        var source = game.Create(alice, bomb, Zone.Battlefield);
        Settle(game);

        // Everything but the source, on both sides of the table - "other" is about the source
        // and not about who controls what.
        Assert.DoesNotContain(mine, game.State.Battlefield);
        Assert.Equal(2, game.State.GetObject(theirs).Permanent!.DamageMarked);
        Assert.Equal(0, game.State.GetObject(source).Permanent!.DamageMarked);
    }

    [Fact]
    public void A_creature_told_to_attack_must_be_declared_if_it_can()
    {
        // The block reader's mirror. The engine already models "attacks each combat if able" as
        // a keyword, so this is that keyword granted for a turn - and the requirement is checked
        // over the whole declaration (CR 508.1d), not creature by creature.
        var lure = Card("Compelling Test", "Target creature attacks this turn if able.");

        var compiled = CardCompiler.Compile(lure);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        // The caster's own creature, so "this turn" is a turn it can actually attack on. Aimed at
        // an opponent's creature on your own turn the line does nothing, which is the card
        // working rather than a gap.
        var (game, alice, _) = InMainPhase();
        var mine = game.Create(
            alice,
            Card("Compelled Bear Test", string.Empty, CardType.Creature, 2, 2, KeywordAbility.Haste),
            Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, lure);
        var land = game.Create(alice, TestCards.BasicLand("Mountain"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");
        game.CastSpell(alice, card, [Target.ToPermanent(mine)]);
        Settle(game);

        Assert.True(
            Characteristics.Of(game.State, Pool, game.State.GetObject(mine))
                .Has(KeywordAbility.MustAttack));

        TestCards.PassToStep(game, TurnStep.DeclareAttackers);

        // Declaring nothing is refused while that creature could go, and declaring it is fine -
        // the requirement is checked over the whole set (CR 508.1d), not creature by creature.
        Assert.NotNull(CombatRules.IllegalAttackSet(game.State, Pool, alice, []));
        Assert.Null(CombatRules.IllegalAttackSet(game.State, Pool, alice, [mine]));
    }

    [Fact]
    public void It_after_a_self_pump_means_the_source_and_not_a_target()
    {
        // "~ gains indestructible until end of turn. Tap it." - the pronoun reader wanted a
        // prior target and there is none, so nine cards stopped on two words. What decides is
        // the effect the sentence before produced, not its wording: only a self-pump says that
        // clause was about "~", so a token created a moment earlier cannot be mistaken for it.
        var brute = Card(
            "Self Tapping Test",
            "{1}, Sacrifice another creature: ~ gains indestructible until end of turn. Tap it.",
            CardType.Creature,
            3,
            3);

        var compiled = CardCompiler.Compile(brute);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var ogre = game.Create(alice, brute, Zone.Battlefield);
        var fodder = game.Create(alice, TestCards.Creature("Sacrificed Bear Test"), Zone.Battlefield);
        var land = game.Create(alice, TestCards.BasicLand("Swamp"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");

        Assert.False(game.State.GetObject(ogre).Permanent!.IsTapped);

        game.ActivateAbility(alice, ogre, "a", costPayment: [fodder]);
        Settle(game);

        // Both halves landed on the source: the grant and the tap.
        Assert.True(
            Characteristics.Of(game.State, Pool, game.State.GetObject(ogre))
                .Has(KeywordAbility.Indestructible));

        Assert.True(game.State.GetObject(ogre).Permanent!.IsTapped);
    }

    [Fact]
    public void An_impulse_draw_exiles_a_card_you_may_play_this_turn()
    {
        // CR 601.3e: permission to play from exile, paying as normal - which is a different
        // thing from a free cast. One effect for two printed sentences, because the second
        // names what the first produced and an effect never sees the events of the one before.
        var spell = Card(
            "Impulse Exile Test",
            "Exile the top card of your library. You may play that card this turn.");

        var compiled = CardCompiler.Compile(spell);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        game.Create(alice, TestCards.Creature("Impulsed Bear Test", 2, 2), Zone.Library);

        var card = TestCards.PutInHand(game, alice, spell);

        foreach (var _ in Enumerable.Range(0, 3))
        {
            var land = game.Create(alice, TestCards.BasicLand("Mountain"), Zone.Battlefield);
            game.ActivateAbility(alice, land, "mana");
        }

        game.CastSpell(alice, card, targets: null);
        Settle(game);

        var exiled = game.State.Exile
            .Select(game.State.GetObject)
            .Single(o => o.Card.Name == "Impulsed Bear Test");

        Assert.Equal(game.State.TurnNumber, exiled.MayPlayUntilTurn);

        // And it is castable from exile, paying its cost as normal.
        game.CastSpell(alice, exiled.Id, targets: null);
        Settle(game);

        Assert.Contains(
            game.State.Battlefield,
            id => game.State.GetObject(id).Card.Name == "Impulsed Bear Test");
    }

    [Fact]
    public void A_slow_flicker_exiles_now_and_returns_at_the_end_step()
    {
        // CR 603.7b. The immediate flicker does both moves at once; this one has to name the
        // exiled card afterwards, and a card that changes zones is a new object (CR 400.7) - so
        // the delayed trigger is made where the id the exile produced is still in hand.
        var spell = Card(
            "Slow Flicker Test",
            "Exile target creature. Return that card to the battlefield under its owner's "
                + "control at the beginning of the next end step.");

        var compiled = CardCompiler.Compile(spell);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var theirs = game.Create(bob, TestCards.Creature("Blinked Bear Test", 2, 2), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, spell);
        var land = game.Create(alice, TestCards.BasicLand("Island"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");
        game.CastSpell(alice, card, [Target.ToPermanent(theirs)]);
        Settle(game);

        // Gone now, and waiting in exile rather than back already.
        Assert.DoesNotContain(theirs, game.State.Battlefield);
        Assert.Contains(
            game.State.Exile,
            id => game.State.GetObject(id).Card.Name == "Blinked Bear Test");

        TestCards.PassToStep(game, TurnStep.End);
        Settle(game);

        // Back at the end step, and under its owner's control - not the caster's, which is the
        // half a reading that returned it to whoever cast the spell would get wrong.
        var back = game.State.Battlefield
            .Select(game.State.GetObject)
            .Single(o => o.Card.Name == "Blinked Bear Test");

        Assert.Equal(bob, Characteristics.Of(game.State, Pool, back).ControllerId);
    }

    [Fact]
    public void A_beacon_shuffles_itself_back_instead_of_reaching_the_graveyard()
    {
        // The card is still on the stack as the effect resolves and reaches the graveyard a
        // moment later under a new id (CR 400.7). So the shuffle names the id it has now and the
        // settle follows it forward - the same way a deferred branch finds what its spell became.
        var beacon = Card(
            "Beacon Test",
            "Target player draws a card. Shuffle ~ into its owner's library.");

        var compiled = CardCompiler.Compile(beacon);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, beacon);
        var land = game.Create(alice, TestCards.BasicLand("Plains"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");

        var libraryBefore = game.State.GetPlayer(alice).Library.Count;

        game.CastSpell(alice, card, [Target.ToPlayer(bob)]);
        Settle(game);

        // Back in the deck rather than the graveyard, which is the whole of what it does.
        Assert.DoesNotContain(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Beacon Test");

        Assert.Equal(libraryBefore + 1, game.State.GetPlayer(alice).Library.Count);
        Assert.Contains(
            game.State.GetPlayer(alice).Library,
            id => game.State.GetObject(id).Card.Name == "Beacon Test");
    }

    [Fact]
    public void The_longer_play_window_survives_the_turn_in_between_and_ends_on_the_next_one()
    {
        // "Until the end of your next turn" is a different duration from "this turn", and the
        // difference only shows across the turn that separates them. Alice exiles on turn 1, and
        // the card has to still be playable on turn 3 - her next - having lived through Bob's.
        var seer = Card(
            "Long Window Test",
            "Exile the top card of your library. Until the end of your next turn, you may play"
                + " that card.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(seer);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, seer);
        var land = game.Create(alice, TestCards.BasicLand("Mountain"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");

        game.CastSpell(alice, card, targets: null);
        Settle(game);

        var exiled = game.State.Exile
            .Select(game.State.GetObject)
            .Single();

        // Recorded as the turn it started on, not as a deadline - the deadline is not knowable
        // yet, since an extra turn taken in between would move it.
        Assert.Equal(1, exiled.MayPlayThroughOwnersNextTurn);
        Assert.Null(exiled.MayPlayUntilTurn);

        // Through Bob's whole turn, still granted.
        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber == 2 && game.State.CurrentStep == TurnStep.End);

        Assert.NotNull(game.State.GetObject(exiled.Id).MayPlayThroughOwnersNextTurn);

        // Alice's next turn: the window is still open, which is the whole point of the duration.
        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber == 3 && game.State.CurrentStep == TurnStep.PrecombatMain);

        Assert.NotNull(game.State.GetObject(exiled.Id).MayPlayThroughOwnersNextTurn);

        // And it runs out when that turn ends, rather than lingering for the rest of the game.
        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber == 4 && game.State.CurrentStep == TurnStep.PrecombatMain);

        Assert.Null(game.State.GetObject(exiled.Id).MayPlayThroughOwnersNextTurn);
    }

    /// <summary>Builds a prepare card: a creature holding a spell it can be asked for a copy of.</summary>
    private static CardDefinition PrepareCard(
        string frontText,
        string backText,
        CardType backType,
        KeywordAbility frontKeywords = KeywordAbility.None) =>
        new()
        {
            OracleId = "oracle-prepare-" + backType.ToString().ToLowerInvariant(),
            Name = "Prepared Pilot Test",
            CardTypes = CardType.Creature,
            Power = 2,
            Toughness = 2,
            ManaCostRaw = "{2}{U}",
            Faces =
            [
                new CardFace
                {
                    Name = "Prepared Pilot Test",
                    CardTypes = CardType.Creature,
                    Power = 2,
                    Toughness = 2,
                    ManaCostRaw = "{2}{U}",
                    Keywords = frontKeywords,
                    OracleText = frontText,
                },
                new CardFace
                {
                    Name = "Prepared Spell Test",
                    CardTypes = backType,
                    ManaCostRaw = "{U}",
                    OracleText = backText,
                },
            ],
        };

    [Fact]
    public void A_prepared_permanent_casts_a_copy_of_its_spell_and_stops_being_prepared()
    {
        var pilot = PrepareCard("~ enters prepared.", "Draw a card.", CardType.Instant);

        var compiled = CardCompiler.Compile(pilot);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        // The back face is not a half: nobody may cast it from hand for its cost. It looks
        // exactly like one - a second face with a printed cost - so this is the assertion that
        // stops the layout handing out a free extra spell.
        Assert.Empty(compiled.Halves);
        Assert.NotNull(compiled.PreparedSpell);

        var (game, alice, _) = InMainPhase();
        var permanent = game.Create(alice, pilot, Zone.Battlefield);

        Assert.True(game.State.GetObject(permanent).Permanent!.IsPrepared);

        var land = game.Create(alice, TestCards.BasicLand("Island"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");

        var handBefore = game.State.GetPlayer(alice).Hand.Count;

        game.CastSpell(alice, permanent, targets: null, prepared: true);

        // The permanent is not what went on the stack: it is still on the battlefield, under the
        // same id, having never become a new object.
        Assert.Contains(permanent, game.State.Battlefield);
        Assert.False(game.State.GetObject(permanent).Permanent!.IsPrepared);

        Settle(game);

        Assert.Equal(handBefore + 1, game.State.GetPlayer(alice).Hand.Count);

        // And the spell is spent - it cannot be cast a second time off the same preparation.
        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, permanent, targets: null, prepared: true));
    }

    [Fact]
    public void A_prepared_sorcery_keeps_its_own_faces_timing()
    {
        // The creature holding the spell has flash in this printing, and it makes no difference:
        // what is being cast is the sorcery behind it, so the sorcery's timing rule applies.
        var pilot = PrepareCard(
            "~ enters prepared.", "Draw a card.", CardType.Sorcery, KeywordAbility.Flash);

        var compiled = CardCompiler.Compile(pilot);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var permanent = game.Create(alice, pilot, Zone.Battlefield);
        var land = game.Create(alice, TestCards.BasicLand("Island"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");

        TestCards.PassUntil(
            game,
            () => game.State.ActivePlayerId == bob && game.State.CurrentStep == TurnStep.Upkeep);

        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, permanent, targets: null, prepared: true));
    }

    [Fact]
    public void Life_gained_this_way_is_however_much_the_clause_before_it_took()
    {
        // The number is not printed anywhere on the card: it is what the sentence before this one
        // just did. Three opponents at 3 life each is 9 gained, which is the assertion - a fixed
        // reading would give 3 and look right at a two-player table.
        var tithe = Card(
            "Blood Drain Test",
            "Each opponent loses 3 life. You gain life equal to the life lost this way.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(tithe);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var alice = Guid.Parse("11111111-1111-1111-1111-111111111111");
        var bob = Guid.Parse("22222222-2222-2222-2222-222222222222");
        var carol = Guid.Parse("33333333-3333-3333-3333-333333333333");

        var game = Game.Start(
            Guid.NewGuid(),
            [
                new PlayerSetup(alice, "Alice", 20, TestCards.Deck(40, "Alice")),
                new PlayerSetup(bob, "Bob", 20, TestCards.Deck(40, "Bob")),
                new PlayerSetup(carol, "Carol", 20, TestCards.Deck(40, "Carol")),
            ],
            new GameRandom(1),
            startingPlayerId: alice,
            abilities: Pool);

        game.BeginPlay(withMulligans: false);
        TestCards.PassToStep(game, TurnStep.PrecombatMain);

        var others = new[] { bob, carol };
        var lifeBefore = game.State.GetPlayer(alice).Life;

        var card = TestCards.PutInHand(game, alice, tithe);
        var land = game.Create(alice, TestCards.BasicLand("Swamp"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");

        game.CastSpell(alice, card, targets: null);
        Settle(game);

        foreach (var other in others)
            Assert.Equal(lifeBefore - 3, game.State.GetPlayer(other).Life);

        Assert.Equal(lifeBefore + 6, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void A_search_for_up_to_two_cards_fetches_both()
    {
        var cultivate = Card(
            "Cultivate Test",
            "Search your library for up to two basic land cards, put them onto the battlefield"
                + " tapped, then shuffle.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(cultivate);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        // A library with basics in it, because the default test deck is all creatures and a
        // search that finds nothing shuffles without ever asking - which would pass this test
        // while fetching nothing at all.
        var alice = Guid.Parse("11111111-1111-1111-1111-111111111111");
        var bob = Guid.Parse("22222222-2222-2222-2222-222222222222");
        var forests = Enumerable.Range(1, 20).Select(_ => TestCards.BasicLand("Forest")).ToList();

        var game = Game.Start(
            Guid.NewGuid(),
            [
                new PlayerSetup(alice, "Alice", 20, forests),
                new PlayerSetup(bob, "Bob", 20, TestCards.Deck(40, "Bob")),
            ],
            new GameRandom(1),
            startingPlayerId: alice,
            abilities: Pool);

        game.BeginPlay(withMulligans: false);
        TestCards.PassToStep(game, TurnStep.PrecombatMain);

        var card = TestCards.PutInHand(game, alice, cultivate);
        var land = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");

        var landsBefore = game.State.Battlefield.Count;
        var libraryBefore = game.State.GetPlayer(alice).Library.Count;

        game.CastSpell(alice, card, targets: null);

        // The search is asked for as the spell resolves, not as it is cast.
        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.SearchLibrary });

        var choice = game.State.Choice!;

        // The ceiling is what the plural buys; failing to find is still allowed (CR 701.23c).
        Assert.Equal(2, choice.MaxPicks);
        Assert.Equal(0, choice.MinPicks);

        var picked = choice.Options.Take(2).Select(o => o.Id).ToList();
        Assert.Equal(2, picked.Count);

        game.Choose(alice, picked);
        Settle(game);

        // Both, and both tapped. Counted as a delta because the Forest tapped for mana is on
        // the battlefield too, and an absolute count would pass while fetching only one.
        Assert.Equal(landsBefore + 2, game.State.Battlefield.Count);
        Assert.Equal(libraryBefore - 2, game.State.GetPlayer(alice).Library.Count);

        var arrived = game.State.Battlefield
            .Select(game.State.GetObject)
            .Where(o => o.Card.CardTypes.HasFlag(CardType.Land) && o.Permanent?.IsTapped == true)
            .ToList();

        Assert.Equal(3, arrived.Count);
    }

    [Fact]
    public void An_extra_land_drop_lasts_the_turn_and_not_past_it()
    {
        var explore = Card(
            "Explore Test",
            "You may play an additional land this turn. Draw a card.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(explore);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, explore);
        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, forest, "mana");

        // The turn's own land drop, spent before the spell so the extra one is the only thing
        // that can allow the second.
        var first = TestCards.PutInHand(game, alice, TestCards.BasicLand("Plains"));
        game.PlayLand(alice, first);

        var second = TestCards.PutInHand(game, alice, TestCards.BasicLand("Plains"));
        Assert.Throws<InvalidOperationException>(() => game.PlayLand(alice, second));

        game.CastSpell(alice, card, targets: null);
        Settle(game);

        Assert.Equal(1, game.State.GetPlayer(alice).ExtraLandDropsThisTurn);
        game.PlayLand(alice, second);

        // It is granted for this turn, not permanently: on the next one the allowance is back to
        // the single drop CR 505.6b gives, which is what the reset exists to do.
        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber == 3 && game.State.CurrentStep == TurnStep.PrecombatMain);

        Assert.Equal(0, game.State.GetPlayer(alice).ExtraLandDropsThisTurn);

        var third = TestCards.PutInHand(game, alice, TestCards.BasicLand("Plains"));
        game.PlayLand(alice, third);

        var fourth = TestCards.PutInHand(game, alice, TestCards.BasicLand("Plains"));
        Assert.Throws<InvalidOperationException>(() => game.PlayLand(alice, fourth));
    }

    [Fact]
    public void Mana_kept_through_the_step_is_only_what_the_ability_made()
    {
        var ventmaw = Card(
            "Ventmaw Test",
            "Whenever ~ attacks, add {R}{R}{R}. Until end of turn, you don't lose this mana as"
                + " steps and phases end.",
            CardType.Creature,
            power: 3,
            toughness: 3);

        var compiled = CardCompiler.Compile(ventmaw);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, ventmaw, Zone.Battlefield);
        var mountain = game.Create(alice, TestCards.BasicLand("Mountain"), Zone.Battlefield);

        // Alice's own next turn, so the creature is not summoning sick.
        PassTo(game, 3, TurnStep.DeclareAttackers);

        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        Settle(game);

        // A Mountain tapped in the same step, so the pool holds more than the trigger made. That
        // extra mana has no permission and has to go, which is the assertion the whole design
        // turns on - keeping the pool rather than the amount would hand it over for free.
        game.ActivateAbility(alice, mountain, "mana");

        Assert.Equal(4, game.State.GetPlayer(alice).ManaPool[ManaColor.Red]);

        // Past the step boundary: three survive, the Mountain's does not.
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.PostcombatMain);

        Assert.Equal(3, game.State.GetPlayer(alice).ManaPool[ManaColor.Red]);

        // And it is gone by the next turn, because the permission ran out with this one.
        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber == 4 && game.State.CurrentStep == TurnStep.PrecombatMain);

        Assert.Equal(0, game.State.GetPlayer(alice).ManaPool[ManaColor.Red]);
    }

    [Fact]
    public void Firebending_mana_lasts_the_combat_and_not_the_turn()
    {
        var roku = Card(
            "Firebender Test",
            "Firebending 2",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var compiled = CardCompiler.Compile(roku);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, roku, Zone.Battlefield);

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        Settle(game);

        Assert.Equal(2, game.State.GetPlayer(alice).ManaPool[ManaColor.Red]);

        // Through the rest of combat, which is more than one step boundary.
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Assert.Equal(2, game.State.GetPlayer(alice).ManaPool[ManaColor.Red]);

        // But not past combat: this duration is shorter than the turn, and reading it as
        // "until end of turn" would leave the mana up for the whole second main phase.
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.PostcombatMain);
        Assert.Equal(0, game.State.GetPlayer(alice).ManaPool[ManaColor.Red]);
    }

    [Fact]
    public void A_land_put_onto_the_battlefield_from_hand_does_not_spend_the_land_drop()
    {
        var spiral = Card(
            "Growth Spiral Test",
            "Draw a card. You may put a land card from your hand onto the battlefield.",
            CardType.Instant);

        var compiled = CardCompiler.Compile(spiral);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, spiral);
        var island = game.Create(alice, TestCards.BasicLand("Island"), Zone.Battlefield);
        game.ActivateAbility(alice, island, "mana");

        var inHand = TestCards.PutInHand(game, alice, TestCards.BasicLand("Forest"));

        game.CastSpell(alice, card, targets: null);
        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.ChooseCardInHand });

        var choice = game.State.Choice!;

        // "You may": declining has to be allowed, which a mandatory discard's machinery does not
        // do on its own.
        Assert.Equal(0, choice.MinPicks);

        game.Choose(alice, [inHand.Value.ToString("N")]);
        Settle(game);

        Assert.Contains(game.State.Battlefield, id => game.State.GetObject(id).Card.Name == "Forest");

        // The land drop is untouched: putting a land onto the battlefield is not playing one
        // (CR 305.1). Reading it as a play would silently cost the turn's land drop, which is a
        // strictly worse card every turn the player had not spent it yet.
        Assert.Equal(0, game.State.GetPlayer(alice).LandsPlayedThisTurn);
    }

    [Fact]
    public void A_spell_that_exiles_itself_with_time_counters_starts_its_own_suspend()
    {
        var blade = Card(
            "Arc Blade Test",
            "~ deals 2 damage to any target. Exile ~ with three time counters on it."
                + "\nSuspend 3-{2}{R}",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(blade);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, blade);

        foreach (var _ in Enumerable.Range(0, 3))
        {
            var land = game.Create(alice, TestCards.BasicLand("Mountain"), Zone.Battlefield);
            game.ActivateAbility(alice, land, "mana");
        }

        game.CastSpell(alice, card, [Target.ToPlayer(bob)]);
        Settle(game);

        Assert.Equal(18, game.State.GetPlayer(bob).Life);

        // In exile rather than the graveyard, and waiting rather than merely exiled: the card's
        // own suspend ability is what ticks it down and casts it, and it reads this state.
        var waiting = game.State.Exile
            .Select(game.State.GetObject)
            .Single(o => o.Card.Name == "Arc Blade Test");

        Assert.Equal(3, waiting.TimeCounters);
        Assert.Equal(alice, waiting.SuspendedBy);

        Assert.DoesNotContain(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Arc Blade Test");
    }

    [Fact]
    public void Domain_counts_basic_land_types_and_not_lands()
    {
        var tribute = Card(
            "Domain Gain Test",
            "You gain 1 life for each basic land type among lands you control.",
            CardType.Instant);

        var compiled = CardCompiler.Compile(tribute);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();

        // Three Forests and one Island: two types, not four lands. Counting the lands would give
        // 4 life here, which is the whole distinction domain is about.
        foreach (var _ in Enumerable.Range(0, 3))
            game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);

        var island = game.Create(alice, TestCards.BasicLand("Island"), Zone.Battlefield);
        game.ActivateAbility(alice, island, "mana");

        var before = game.State.GetPlayer(alice).Life;

        var card = TestCards.PutInHand(game, alice, tribute);
        game.CastSpell(alice, card, targets: null);
        Settle(game);

        Assert.Equal(before + 2, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void An_extra_turn_comes_before_the_turn_order_resumes()
    {
        var walk = Card("Time Walk Test", "Take an extra turn after this one.", CardType.Sorcery);

        var compiled = CardCompiler.Compile(walk);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        // Three players, because at two seats an extra turn is indistinguishable from the turn
        // order simply skipping somebody - and skipping is not what the card does.
        var alice = Guid.Parse("11111111-1111-1111-1111-111111111111");
        var bob = Guid.Parse("22222222-2222-2222-2222-222222222222");
        var carol = Guid.Parse("33333333-3333-3333-3333-333333333333");

        var game = Game.Start(
            Guid.NewGuid(),
            [
                new PlayerSetup(alice, "Alice", 20, TestCards.Deck(40, "Alice")),
                new PlayerSetup(bob, "Bob", 20, TestCards.Deck(40, "Bob")),
                new PlayerSetup(carol, "Carol", 20, TestCards.Deck(40, "Carol")),
            ],
            new GameRandom(1),
            startingPlayerId: alice,
            abilities: Pool);

        game.BeginPlay(withMulligans: false);
        TestCards.PassToStep(game, TurnStep.PrecombatMain);

        var card = TestCards.PutInHand(game, alice, walk);
        var land = game.Create(alice, TestCards.BasicLand("Island"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");

        game.CastSpell(alice, card, targets: null);
        Settle(game);

        // Queued, not taken: the current turn has to finish first.
        Assert.Equal(alice, game.State.ActivePlayerId);
        Assert.Equal([alice], game.State.ExtraTurns);

        TestCards.PassUntil(game, () => game.State.TurnNumber == 2);

        // Alice again, rather than Bob - and the queue is spent.
        Assert.Equal(alice, game.State.ActivePlayerId);
        Assert.Empty(game.State.ExtraTurns);

        // And afterwards the order resumes where it left off: Bob, who was skipped over rather
        // than passed by.
        TestCards.PassUntil(game, () => game.State.TurnNumber == 3);
        Assert.Equal(bob, game.State.ActivePlayerId);
    }

    [Fact]
    public void A_powerstone_arrives_tapped_and_its_mana_cannot_cast_a_nonartifact()
    {
        var forge = Card(
            "Powerstone Forge Test",
            "When ~ enters, create a tapped Powerstone token.",
            CardType.Artifact);

        var compiled = CardCompiler.Compile(forge);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        game.Create(alice, forge, Zone.Battlefield);
        Settle(game);

        var stone = game.State.Battlefield
            .Select(game.State.GetObject)
            .Single(o => o.Card.Name == "Powerstone");

        // "Tapped" is the modifier the grammar was missing; without it the token would arrive
        // ready to use a turn early.
        Assert.True(stone.Permanent!.IsTapped);

        // And the restriction is the whole of what a Powerstone is (CR 111.10h): mana that had
        // lost it would be a strictly better token than the card makes. The token's own text goes
        // through the ordinary compiler, so this is asserted against what that produced.
        var token = CardCompiler.Compile(stone.Card);
        Assert.True(token.IsComplete, string.Join(" | ", token.Unhandled));

        var mana = Assert.Single(token.Activated);
        Assert.Contains(mana.Produces, produced => produced.Restriction is not null);
    }

    [Fact]
    public void Powerstone_mana_refuses_a_nonartifact_spell_but_pays_for_an_ability()
    {
        // The negative restriction is not the positive one said backwards. "Spend only to cast
        // artifact spells" would also forbid the activation below; this wording does not, and
        // reading the two the same way makes the token quietly worse than CR 111.10h describes.
        var restriction = EffectPhrase.RestrictionFor(
            "This mana can't be spent to cast a nonartifact spell.");

        Assert.NotNull(restriction);

        Assert.True(restriction!.Value.Allows(ManaPurpose.CastSpell, CardType.Artifact));
        Assert.False(restriction.Value.Allows(ManaPurpose.CastSpell, CardType.Creature));

        // Activating anything at all is still fine - an equip cost, a creature's own ability.
        Assert.True(restriction.Value.Allows(ManaPurpose.ActivateAbility, CardType.Creature));
        Assert.True(restriction.Value.Allows(ManaPurpose.Other, CardType.None));
    }

    [Fact]
