            abilities: Pool);

        game.BeginPlay(withMulligans: false);
        TestCards.PassToStep(game, TurnStep.PrecombatMain);

        var card = TestCards.PutInHand(game, alice, tutor);
        var land = game.Create(alice, TestCards.BasicLand("Island"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");

        game.CastSpell(alice, card, targets: null);

        // "You may search" is offered as a yes/no by the general optional wrapper, so the search
        // itself only happens once that is accepted - which is also what keeps an optional search
        // from being read as a mandatory one.
        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.OptionalPayment });
        game.Choose(alice, ["yes"]);

        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.SearchLibrary });

        var offered = game.State.Choice!.Options.Select(o => o.Label).Distinct().ToList();

        // "With mana value 3" is exact. Reading it as a ceiling would offer the {1} artifact as
        // well, which is a strictly better tutor than the card prints.
        Assert.Equal(["Exact Relic Test"], offered);
    }

    [Fact]
    public void A_token_copy_of_that_creature_copies_the_one_the_trigger_was_about()
    {
        var mimic = Card(
            "Dying Mimic Test",
            "Whenever another creature you control dies, create a token that's a copy of that"
                + " creature, except it isn't legendary.",
            CardType.Creature,
            power: 1,
            toughness: 1);

        var compiled = CardCompiler.Compile(mimic);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        game.Create(alice, mimic, Zone.Battlefield);

        var hero = new CardDefinition
        {
            OracleId = "oracle-mimic-hero-test",
            Name = "Mimic Hero Test",
            CardTypes = CardType.Creature,
            Supertypes = ["Legendary"],
            Power = 3,
            Toughness = 3,
        };

        var dying = game.Create(alice, hero, Zone.Battlefield);
        game.Move(dying, Zone.Graveyard, MoveCause.Destroy);
        Settle(game);

        // The copy is of the creature that died - neither a target nor the permanent with the
        // ability, which is the case a null target index could not previously express.
        var token = game.State.Battlefield
            .Select(game.State.GetObject)
            .Single(o => o.Card.Name == "Mimic Hero Test");

        Assert.Equal(3, token.Card.Power);

        // And the rider is honoured, so the legend rule does not eat it (CR 704.5j).
        Assert.False(Characteristics.Of(game.State, Pool, token).IsLegendary);
    }

    [Fact]
    public void A_permanent_that_demands_a_sacrifice_goes_when_the_cost_is_declined()
    {
