    [Fact]
    public void A_pump_and_a_granted_ability_are_two_effects_in_two_layers()
    {
        var boon = Card(
            "Ability Boon Test",
            "Until end of turn, target creature gets +2/+2 and gains \"{T}: Add {G}\".",
            CardType.Instant);

        var compiled = CardCompiler.Compile(boon);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        // Two effects, because power is layer 7c and an added ability is layer 6 - one effect
        // cannot be in both (CR 613.1f, 613.4c).
        Assert.Equal(2, compiled.Spell!.Effects.Count);

        var (game, alice, _) = InMainPhase();
        var bear = game.Create(alice, TestCards.Creature("Boon Bear Test", 2, 2), Zone.Battlefield);

