        game.ActivateAbility(alice, land, "mana");

        game.CastSpell(alice, card, [Target.ToPermanent(bear)]);
        Settle(game);

        var now = Characteristics.Of(game.State, Pool, game.State.GetObject(bear));
        Assert.Equal(4, now.Power);
        Assert.Equal(4, now.Toughness);
        Assert.Single(now.GrantedActivated);
    }

    [Fact]
    public void A_group_can_be_granted_a_quoted_ability()
    {
        var anthem = Card(
            "Ability Anthem Test",
            "Until end of turn, creatures you control gain \"{T}: Add {G}\".",
            CardType.Instant);

        var compiled = CardCompiler.Compile(anthem);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var mine = game.Create(alice, TestCards.Creature("Anthem Mine Test", 2, 2), Zone.Battlefield);
        var theirs = game.Create(bob, TestCards.Creature("Anthem Theirs Test", 2, 2), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, anthem);
        var land = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
