    [Fact]
    public void Total_power_sums_what_the_creatures_are_now_rather_than_counting_them()
    {
        var gate = Card(
            "Total Power Test",
            "{T}: Draw a card. Activate only if creatures you control have total power 6 or"
                + " greater.",
            CardType.Artifact);

        var compiled = CardCompiler.Compile(gate);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var engine = game.Create(alice, gate, Zone.Battlefield);

        // Two 2/2s: four power across two creatures, so counting creatures would say two and the
        // sum says four. Neither reaches six.
        game.Create(alice, TestCards.Creature("Total One Test", 2, 2), Zone.Battlefield);
        game.Create(alice, TestCards.Creature("Total Two Test", 2, 2), Zone.Battlefield);

        Assert.Throws<InvalidOperationException>(() => game.ActivateAbility(alice, engine, "a"));

        // One more 2/2 makes six.
        game.Create(alice, TestCards.Creature("Total Three Test", 2, 2), Zone.Battlefield);

        var handBefore = game.State.GetPlayer(alice).Hand.Count;
        game.ActivateAbility(alice, engine, "a");
        Settle(game);

        Assert.Equal(handBefore + 1, game.State.GetPlayer(alice).Hand.Count);
    }

    [Fact]
    public void A_zero_zero_devourer_survives_because_the_counters_land_before_the_check()
    {
        // Thromok and Famished Worldsire are printed 0/0, so devour is not decoration for them:
        // if the counters arrived after state-based actions ran, the creature would be in the
        // graveyard before it ever ate anything.
        var thromok = Card(
            "Devour Test",
            "Devour 2",
            CardType.Creature,
            power: 0,
            toughness: 0);

        var compiled = CardCompiler.Compile(thromok);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var first = game.Create(alice, TestCards.Creature("Devour Food One Test", 1, 1), Zone.Battlefield);
        var second = game.Create(alice, TestCards.Creature("Devour Food Two Test", 1, 1), Zone.Battlefield);

        var eater = game.Create(alice, thromok, Zone.Battlefield);

        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.Devour });

        // "Any number", so declining is allowed - and the devourer itself is not on the menu.
        var choice = game.State.Choice!;
        Assert.Equal(0, choice.MinPicks);
        Assert.DoesNotContain(choice.Options, o => o.Id == eater.Value.ToString("N"));

        game.Choose(alice, [first.Value.ToString("N"), second.Value.ToString("N")]);
        Settle(game);

        // Two creatures at two counters each: a 4/4, still on the battlefield.
        Assert.Contains(eater, game.State.Battlefield);

        var grown = Characteristics.Of(game.State, Pool, game.State.GetObject(eater));
        Assert.Equal(4, grown.Power);
        Assert.Equal(4, grown.Toughness);

        Assert.DoesNotContain(first, game.State.Battlefield);
        Assert.DoesNotContain(second, game.State.Battlefield);
    }

