    [Fact]
    public void Ward_can_charge_life_instead_of_mana()
    {
        var sentinel = Card(
            "Ward Life Test",
            "Ward—Pay 3 life",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var compiled = CardCompiler.Compile(sentinel);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var warded = game.Create(alice, sentinel, Zone.Battlefield);

        var bolt = Card("Ward Life Bolt Test", "~ deals 3 damage to any target.", CardType.Instant);

        TestCards.PassUntil(
            game,
            () => game.State.ActivePlayerId == bob && game.State.CurrentStep == TurnStep.PrecombatMain);

        // Put in hand after the turn has passed: a card sitting through a cleanup can be
        // discarded to hand size, and then there is no card to cast.
        var card = TestCards.PutInHand(game, bob, bolt);
        var land = game.Create(bob, TestCards.BasicLand("Mountain"), Zone.Battlefield);
        game.ActivateAbility(bob, land, "mana");

        game.CastSpell(bob, card, [Target.ToPermanent(warded)]);

        // The ward trigger offers Bob the life payment; the offer is the whole of what this adds.
        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.OptionalPayment });
        Assert.Equal(bob, game.State.Choice!.PlayerId);

        var bobBefore = game.State.GetPlayer(bob).Life;
        game.Choose(bob, ["yes"]);
        Settle(game);

        Assert.Equal(bobBefore - 3, game.State.GetPlayer(bob).Life);
    }

    [Fact]
    public void A_permanent_kept_by_the_mana_that_paid_for_it_reads_what_was_actually_spent()
    {
        var kicker = new CardDefinition
        {
            OracleId = "oracle-spent-mana-test",
            Name = "Spent Mana Test",
            CardTypes = CardType.Creature,
            ManaCostRaw = "{B}",
            Cmc = 1,
            Power = 3,
            Toughness = 3,
            OracleText = "When ~ enters, sacrifice it unless {B} was spent to cast it.",
        };

        var compiled = CardCompiler.Compile(kicker);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        // Paid for with a Swamp: it stays. What was spent travels with the card as the spell
