        // once it has arrived under a new id (CR 400.7).
        Assert.Single(SurvivorsOf(kicker, "Swamp"));
    }

    [Fact]
    public void A_permanent_not_paid_for_in_the_right_colour_sacrifices_itself()
    {
        // The same card cast off a Forest. The generic cost can be paid by any colour, so this
        // is a legal cast that still fails the condition - which is the whole of what these
        // cards are for.
        var kicker = new CardDefinition
        {
            OracleId = "oracle-spent-mana-wrong-test",
            Name = "Spent Mana Wrong Test",
            CardTypes = CardType.Creature,
            ManaCostRaw = "{1}",
            Cmc = 1,
            Power = 3,
            Toughness = 3,
            OracleText = "When ~ enters, sacrifice it unless {B} was spent to cast it.",
        };

        Assert.Empty(SurvivorsOf(kicker, "Forest"));
    }

    /// <summary>Casts a one-mana creature off a single basic and returns what survived.</summary>
    private static IReadOnlyList<ObjectId> SurvivorsOf(CardDefinition creature, string basic)
    {
        var (game, alice, _) = InMainPhase();
        var land = game.Create(alice, TestCards.BasicLand(basic), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");

        var card = TestCards.PutInHand(game, alice, creature);
        game.CastSpell(alice, card, targets: null);
        Settle(game);

        return [.. game.State.Battlefield.Where(
            id => game.State.GetObject(id).Card.Name == creature.Name)];
    }

    [Fact]
    public void Preventing_all_damage_shields_a_creature_for_the_whole_turn()
    {
        var fog = Card(
            "Blanket Shield Test",
            "Prevent all damage that would be dealt to target creature this turn.",
            CardType.Instant);

        var compiled = CardCompiler.Compile(fog);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var bear = game.Create(alice, TestCards.Creature("Shield Bear Test", 2, 2), Zone.Battlefield);

        var land = game.Create(alice, TestCards.BasicLand("Plains"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");

        var card = TestCards.PutInHand(game, alice, fog);
        game.CastSpell(alice, card, [Target.ToPermanent(bear)]);
        Settle(game);

        // A 2/2 taking five, twice: with a numbered shield the second would get through, which is
        // exactly the difference between "the next N damage" and "all damage".
        var bolt = Card("Shield Bolt Test", "~ deals 5 damage to any target.", CardType.Instant);

        // Alice shoots her own creature, so priority stays where the test can reach it. Whose
        // spell it is makes no difference to a shield that prevents all damage.
        foreach (var _ in Enumerable.Range(0, 2))
        {
            var mountain = game.Create(alice, TestCards.BasicLand("Mountain"), Zone.Battlefield);
            game.ActivateAbility(alice, mountain, "mana");

            var shot = TestCards.PutInHand(game, alice, bolt);
            game.CastSpell(alice, shot, [Target.ToPermanent(bear)]);
            Settle(game);
        }

        Assert.Contains(bear, game.State.Battlefield);
        Assert.Equal(0, game.State.GetObject(bear).Permanent!.DamageMarked);
    }

    [Fact]
    public void Tapping_and_freezing_keeps_a_creature_down_through_its_next_untap()
    {
        var freezer = Card(
            "Freezer Test",
            "Whenever ~ deals combat damage to a creature, tap that creature and it doesn't untap"
                + " during its controller's next untap step.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var compiled = CardCompiler.Compile(freezer);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, freezer, Zone.Battlefield);
        var blocker = game.Create(bob, TestCards.Creature("Frozen Wall Test", 0, 4), Zone.Battlefield);

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);
        game.DeclareBlockers(
            bob,
            new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [attacker] = [blocker] });

        // Damage is dealt in the combat damage step, so the trigger cannot have fired until the
        // game has walked there.
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Settle(game);

        Assert.True(game.State.GetObject(blocker).Permanent!.IsTapped);
        Assert.True(game.State.GetObject(blocker).Permanent!.SkipsNextUntap);

        // Through Bob's untap step it stays down - which is the half a plain tap would miss.
        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber == 4 && game.State.CurrentStep == TurnStep.PrecombatMain);

        Assert.True(game.State.GetObject(blocker).Permanent!.IsTapped);
    }

    [Fact]
    public void Returning_that_card_reanimates_what_the_trigger_was_about()
    {
        var shepherd = Card(
            "Shepherd Test",
            "Whenever another creature you control dies, return that card to the battlefield"
                + " under your control.",
            CardType.Creature,
            power: 1,
            toughness: 1);

        var compiled = CardCompiler.Compile(shepherd);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        game.Create(alice, shepherd, Zone.Battlefield);

        var doomed = game.Create(
            alice, TestCards.Creature("Shepherd Sheep Test", 2, 2), Zone.Battlefield);

        game.Move(doomed, Zone.Graveyard, MoveCause.Destroy);
        Settle(game);

        // Back on the battlefield as a new object, and no longer in the graveyard: the id the
        // trigger carried named the permanent, and what returns is the card it became.
        Assert.Contains(
            game.State.Battlefield,
            id => game.State.GetObject(id).Card.Name == "Shepherd Sheep Test");

        Assert.DoesNotContain(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Shepherd Sheep Test");
    }

    [Fact]
    public void Its_controller_searches_their_own_library_not_yours()
    {
        var punisher = Card(
            "Landfall Punisher Test",
            "Whenever a land enters, its controller may search their library for a basic land"
                + " card, put it onto the battlefield tapped, then shuffle.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(punisher);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var alice = Guid.Parse("11111111-1111-1111-1111-111111111111");
        var bob = Guid.Parse("22222222-2222-2222-2222-222222222222");

        var basics = Enumerable.Range(1, 30).Select(_ => TestCards.BasicLand("Forest")).ToList();

        var game = Game.Start(
            Guid.NewGuid(),
            [
                new PlayerSetup(alice, "Alice", 20, TestCards.Deck(40, "Alice")),
                new PlayerSetup(bob, "Bob", 20, basics),
            ],
            new GameRandom(1),
            startingPlayerId: alice,
            abilities: Pool);

        game.BeginPlay(withMulligans: false);
        TestCards.PassToStep(game, TurnStep.PrecombatMain);

        game.Create(alice, punisher, Zone.Battlefield);

        // Bob's land enters, so Bob is the one offered the search - of Bob's library, which is
        // the only one with basics in it. Alice's deck has none, so a reading that pointed the
        // search at the controller of the enchantment would find nothing at all.
        game.Create(bob, TestCards.BasicLand("Island"), Zone.Battlefield);

        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.SearchLibrary });

        Assert.Equal(bob, game.State.Choice!.PlayerId);
    }

    [Fact]
    public void The_owner_picks_which_end_of_their_library_a_permanent_goes_to()
    {
        var bounce = Card(
            "Library End Test",
            "The owner of target nonland permanent puts it on their choice of the top or bottom"
                + " of their library.",
            CardType.Instant);

        var compiled = CardCompiler.Compile(bounce);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var theirs = game.Create(bob, TestCards.Creature("Filed Bear Test", 2, 2), Zone.Battlefield);

        var land = game.Create(alice, TestCards.BasicLand("Island"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");

        var card = TestCards.PutInHand(game, alice, bounce);
        game.CastSpell(alice, card, [Target.ToPermanent(theirs)]);

        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.LibraryEnd });

        // Bob's creature, so Bob decides - not the player who cast the spell. A card that let the
        // caster choose would be a strictly better removal spell than the one printed.
        Assert.Equal(bob, game.State.Choice!.PlayerId);

        game.Choose(bob, ["bottom"]);
        Settle(game);

        var library = game.State.GetPlayer(bob).Library;
        Assert.Equal("Filed Bear Test", game.State.GetObject(library[^1]).Card.Name);
        Assert.DoesNotContain(theirs, game.State.Battlefield);
    }

    [Fact]
    public void A_group_can_be_stopped_from_blocking_and_the_filter_is_respected()
    {
        var fog = Card(
            "Ground Fog Test",
            "Creatures without flying can't block this turn.",
            CardType.Instant);

        var compiled = CardCompiler.Compile(fog);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var grounded = game.Create(bob, TestCards.Creature("Fog Ground Test", 2, 2), Zone.Battlefield);

        var flier = game.Create(
            bob,
            Card("Fog Flier Test", string.Empty, CardType.Creature, 2, 2, KeywordAbility.Flying),
            Zone.Battlefield);

        var land = game.Create(alice, TestCards.BasicLand("Island"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");

        var card = TestCards.PutInHand(game, alice, fog);
        game.CastSpell(alice, card, targets: null);
        Settle(game);

        // "Without flying" is part of the group, so the flier keeps its block.
        Assert.True(
            Characteristics.Of(game.State, Pool, game.State.GetObject(grounded))
                .Has(KeywordAbility.CantBlock));

        Assert.False(
            Characteristics.Of(game.State, Pool, game.State.GetObject(flier))
                .Has(KeywordAbility.CantBlock));
    }

    [Fact]
