    [Fact]
    public void Redirected_damage_is_still_dealt_just_somewhere_else()
    {
        var wall = Card(
            "Redirect Wall Test",
            "{T}: The next 2 damage that would be dealt to ~ this turn is dealt to target"
                + " creature you control instead.",
            CardType.Creature,
            power: 0,
            toughness: 6);

        var compiled = CardCompiler.Compile(wall);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var shielded = game.Create(alice, wall, Zone.Battlefield);
        var scapegoat = game.Create(
            alice, TestCards.Creature("Redirect Goat Test", 1, 5), Zone.Battlefield);

        PassTo(game, 3, TurnStep.PrecombatMain);
        game.ActivateAbility(alice, shielded, "a", [Target.ToPermanent(scapegoat)]);
        Settle(game);

        var bolt = Card("Redirect Bolt Test", "~ deals 3 damage to any target.", CardType.Instant);
        var mountain = game.Create(alice, TestCards.BasicLand("Mountain"), Zone.Battlefield);
        game.ActivateAbility(alice, mountain, "mana");

        var shot = TestCards.PutInHand(game, alice, bolt);
        game.CastSpell(alice, shot, [Target.ToPermanent(shielded)]);
