    [Fact]
    public void Looking_at_a_hand_is_recorded_as_a_look_and_not_as_a_reveal()
    {
        var peek = Card(
            "Look At Hand Test",
            "Look at target opponent's hand.",
            CardType.Instant);

        var compiled = CardCompiler.Compile(peek);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        TestCards.PutInHand(game, bob, TestCards.Creature("Peeked Card Test", 1, 1));

        var land = game.Create(alice, TestCards.BasicLand("Island"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");

        var card = TestCards.PutInHand(game, alice, peek);
        game.CastSpell(alice, card, [Target.ToPlayer(bob)]);
        Settle(game);

        // Recorded as a look by Alice at Bob's hand. Reusing the reveal event would say the whole
        // table saw it, which is more than the card grants.
        var looked = Assert.Single(game.Log.OfType<HandLookedAt>());

        Assert.Equal(alice, looked.ViewerId);
        Assert.Equal(bob, looked.PlayerId);
        Assert.Empty(game.Log.OfType<CardsRevealed>());
    }

    [Fact]
    public void A_three_way_or_list_names_one_target_that_may_be_any_of_them()
    {
        var naturalize = Card(
            "Or List Test",
            "Destroy target artifact, enchantment, or creature with flying.",
            CardType.Instant);

        var compiled = CardCompiler.Compile(naturalize);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var spec = Assert.Single(compiled.Spell!.Targets);

        var (game, alice, _) = InMainPhase();

        var artifact = game.Create(
            alice, Card("Or Artifact Test", string.Empty, CardType.Artifact), Zone.Battlefield);

        var flier = game.Create(
            alice,
            Card("Or Flier Test", string.Empty, CardType.Creature, 2, 2, KeywordAbility.Flying),
            Zone.Battlefield);

        var grounded = game.Create(
            alice, TestCards.Creature("Or Ground Test", 2, 2), Zone.Battlefield);

        bool Legal(ObjectId id) =>
            spec.ObjectFilter?.Invoke(game.State, Pool, game.State.GetObject(id), alice) != false;

        // Any of the three types, and the trailing qualifier binds only to the last one: a
        // grounded creature is not a legal target, an artifact with no flying still is.
        Assert.True(Legal(artifact));
        Assert.True(Legal(flier));
        Assert.False(Legal(grounded));
    }

    [Fact]
    public void Paying_the_flash_surcharge_buys_timing_and_not_a_discount()
    {
        var beast = new CardDefinition
        {
            OracleId = "oracle-flash-surcharge-test",
            Name = "Flash Surcharge Test",
            CardTypes = CardType.Creature,
            ManaCostRaw = "{1}{G}",
            Cmc = 2,
            Power = 3,
            Toughness = 3,
            OracleText = "You may cast ~ as though it had flash if you pay {2} more to cast it.",
        };

        var compiled = CardCompiler.Compile(beast);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();

        // Bob's turn, where a creature could not normally be cast at all.
        TestCards.PassUntil(
            game,
            () => game.State.ActivePlayerId == bob
                && game.State.Priority.Holder == alice);

        var card = TestCards.PutInHand(game, alice, beast);

        foreach (var _ in Enumerable.Range(0, 4))
        {
            var land = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
            game.ActivateAbility(alice, land, "mana");
        }

        // Without paying, the timing rule still refuses it.
        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, card, targets: null));

        game.CastSpell(alice, card, targets: null, withFlash: true);
        Settle(game);

        Assert.Contains(
            game.State.Battlefield,
            id => game.State.GetObject(id).Card.Name == "Flash Surcharge Test");

        // Four mana gone, not two: the surcharge is added to the printed cost rather than
        // replacing it.
        Assert.Equal(0, game.State.GetPlayer(alice).ManaPool.Total);
    }

