            alice,
            Card("Freerunning Assassin Test", string.Empty, CardType.Creature, 2, 2,
                KeywordAbility.None, "Assassin"),
            Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, blade);

        foreach (var _ in Enumerable.Range(0, 2))
        {
            var swamp = game.Create(alice, TestCards.BasicLand("Swamp"), Zone.Battlefield);
            game.ActivateAbility(alice, swamp, "mana");
        }

        // Nothing has connected yet, so the cheaper cost is not on offer and two mana is not
        // enough for the printed one.
        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, card, targets: null, alternativeCost: true));

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [assassin] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.PostcombatMain);

        Assert.True(game.State.GetPlayer(alice).AssassinOrCommanderConnectedThisTurn);

        foreach (var _ in Enumerable.Range(0, 2))
        {
            var swamp = game.Create(alice, TestCards.BasicLand("Swamp"), Zone.Battlefield);
            game.ActivateAbility(alice, swamp, "mana");
        }

        // Drawn now rather than held across the turn: a card waiting in hand through a cleanup
        // can be discarded to hand size, and then there is nothing to cast.
        var afterCombat = TestCards.PutInHand(game, alice, blade);
        game.CastSpell(alice, afterCombat, targets: null, alternativeCost: true);
        Settle(game);

        Assert.Contains(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Freerunning Blade Test");
    }

    [Fact]
    public void A_prototyped_spell_costs_less_and_keeps_the_smaller_body()
    {
        var golem = new CardDefinition
        {
            OracleId = "oracle-prototype-test",
            Name = "Prototype Golem Test",
            CardTypes = CardType.Artifact | CardType.Creature,
            ManaCostRaw = "{6}",
            Cmc = 6,
            Power = 6,
            Toughness = 6,
            OracleText = "Prototype {2}{G} — 2/2",
        };

        var compiled = CardCompiler.Compile(golem);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();

        foreach (var _ in Enumerable.Range(0, 3))
        {
            var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
            game.ActivateAbility(alice, forest, "mana");
        }

        var card = TestCards.PutInHand(game, alice, golem);

        // Three mana is not the printed six, so only the prototype cost can pay for it.
        game.CastSpell(alice, card, targets: null, prototyped: true);
        Settle(game);

        var arrived = game.State.Battlefield
            .Select(game.State.GetObject)
            .Single(o => o.Card.Name == "Prototype Golem Test");

        // The choice outlives the stack: the permanent keeps the smaller body (CR 718.2).
        Assert.True(arrived.WasPrototyped);

        var now = Characteristics.Of(game.State, Pool, arrived);
        Assert.Equal(2, now.Power);
        Assert.Equal(2, now.Toughness);
    }

    [Fact]
    public void The_same_card_cast_normally_keeps_its_printed_body()
    {
        var golem = new CardDefinition
        {
            OracleId = "oracle-prototype-normal-test",
