    [Fact]
    public void A_depletion_land_spends_itself_when_the_last_counter_goes()
    {
        var land = Card(
            "Depletion Land Test",
            "{T}, Remove a depletion counter from ~: Add {U}{U}. If there are no depletion"
                + " counters on ~, sacrifice it.",
            CardType.Land);

        var compiled = CardCompiler.Compile(land);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var mine = game.Create(alice, land, Zone.Battlefield);
        game.AddCounters(mine, "depletion", 2);

        game.ActivateAbility(alice, mine, compiled.Activated.Single().Id);
        Settle(game);

        // One counter left, so it survives and the mana is in the pool.
        Assert.Contains(mine, game.State.Battlefield);
        Assert.Equal(2, game.State.GetPlayer(alice).ManaPool[ManaColor.Blue]);

        // Round to Alice's next turn so the land untaps in the ordinary way.
        PassTo(game, 3, TurnStep.PrecombatMain);

        game.ActivateAbility(alice, mine, compiled.Activated.Single().Id);
        Settle(game);

        // The last one has gone, so the land goes with it.
        Assert.DoesNotContain(mine, game.State.Battlefield);
    }

    [Fact]
    public void A_miracle_is_offered_only_for_the_first_card_drawn_each_turn()
    {
        var wrath = new CardDefinition
        {
            OracleId = "oracle-miracle-test",
            Name = "Miracle Wrath Test",
            CardTypes = CardType.Sorcery,
            ManaCostRaw = "{6}{W}",
            Cmc = 7,
            OracleText = "Miracle {W}" + "\n" + "Draw a card.",
        };

        var compiled = CardCompiler.Compile(wrath);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var alice = Guid.Parse("11111111-1111-1111-1111-111111111111");
        var bob = Guid.Parse("22222222-2222-2222-2222-222222222222");

        var deck = Enumerable.Range(0, 30).Select(_ => wrath).ToList();

        var game = Game.Start(
            Guid.NewGuid(),
            [
                new PlayerSetup(alice, "Alice", 20, deck),
                new PlayerSetup(bob, "Bob", 20, TestCards.Deck(40, "Bob")),
            ],
            new GameRandom(1),
            startingPlayerId: alice,
            abilities: Pool);

        game.BeginPlay(withMulligans: false);

        // The offer is a window that closes when its player passes priority (CR 601.2b), so the
        // loop stops the moment it appears rather than walking past it.
        for (var guard = 0; guard < 80; guard++)
        {
            if (game.State.GetPlayer(alice).Hand.Any(
                id => game.State.GetObject(id).MayCastFree))
            {
                break;
            }

            if (game.State.Choice is { } pending)
            {
                game.Choose(
                    pending.PlayerId,
                    pending.MinPicks > 0 ? [pending.Options[0].Id] : []);
            }
            else if (game.State.Priority.Holder is { } holder)
                game.PassPriority(holder);
            else
                break;
        }

        var offered = game.State.GetPlayer(alice).Hand
            .Select(game.State.GetObject)
            .Where(o => o.MayCastFree)
            .ToList();

        // The drawn card is on offer for its miracle cost, not for nothing: the offer carries a
        // price, which is what separates this from a cascade.
        var miracle = Assert.Single(offered);
        Assert.Equal("{W}", miracle.OfferedCost);
    }

    [Fact]
    public void A_sacrifice_trigger_obeys_the_noun_it_names()
    {
        var altar = Card(
            "Sacrifice Noun Test",
            "Whenever you sacrifice a creature, you gain 1 life.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(altar);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        game.Create(alice, altar, Zone.Battlefield);

        var land = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        var before = game.State.GetPlayer(alice).Life;

        // A land is not a creature. The noun used to be matched and discarded, so this fired.
        game.Move(land, Zone.Graveyard, MoveCause.Sacrifice);
        Settle(game);

        Assert.Equal(before, game.State.GetPlayer(alice).Life);

        var bear = game.Create(alice, TestCards.Creature("Sacrificed Bear Test", 2, 2), Zone.Battlefield);
        game.Move(bear, Zone.Graveyard, MoveCause.Sacrifice);
        Settle(game);

        Assert.Equal(before + 1, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void Another_excludes_the_permanent_whose_ability_it_is()
    {
        var altar = Card(
            "Sacrifice Another Test",
            "Whenever you sacrifice another permanent, you gain 1 life.",
            CardType.Creature,
            power: 1,
            toughness: 1);

