        var (game, alice, _) = InMainPhase();
        var self = game.Create(alice, altar, Zone.Battlefield);
        var before = game.State.GetPlayer(alice).Life;

        // Sacrificing itself is not "another permanent" (CR 109.5).
        game.Move(self, Zone.Graveyard, MoveCause.Sacrifice);
        Settle(game);

        Assert.Equal(before, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void A_counter_conditional_on_the_cast_zone_reads_where_it_came_from()
    {
        var angel = Card(
            "Divinity Test",
            "~ enters with a divinity counter on it if you cast it from your hand.",
            CardType.Creature,
            power: 4,
            toughness: 4);

        var compiled = CardCompiler.Compile(angel);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, angel);

        game.CastSpell(alice, card, targets: null);
        Settle(game);

        var cast = game.State.Battlefield
            .Select(game.State.GetObject)
            .Single(o => o.Card.Name == "Divinity Test");

        Assert.Equal(Zone.Hand, cast.CastFromZone);
        Assert.Equal(1, cast.Permanent!.Counters.GetValueOrDefault("divinity"));

        // Put onto the battlefield instead of cast: the condition is false, so no counter.
        var reanimated = game.Create(alice, angel, Zone.Battlefield);
        Settle(game);

        Assert.Null(game.State.GetObject(reanimated).CastFromZone);
        Assert.Equal(0, game.State.GetObject(reanimated).Permanent!.Counters.GetValueOrDefault("divinity"));
    }

    [Fact]
    public void Tapping_several_creatures_as_a_cost_charges_all_of_them()
    {
        var engine = Card(
            "Tap Two Test",
            "Tap two untapped creatures you control: Draw a card.",
            CardType.Artifact);

        var compiled = CardCompiler.Compile(engine);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var ability = Assert.Single(compiled.Activated);
        var cost = Assert.Single(ability.ChosenCosts);

        // Two, not one: the count rides on the cost because the target grammar names one thing.
        Assert.Equal(2, cost.Count);
        Assert.Equal(ChosenCostKind.TapPermanents, cost.Kind);

        var (game, alice, _) = InMainPhase();
        var box = game.Create(alice, engine, Zone.Battlefield);

        var first = game.Create(alice, TestCards.Creature("Tap Crew One Test", 1, 1), Zone.Battlefield);
        var second = game.Create(alice, TestCards.Creature("Tap Crew Two Test", 1, 1), Zone.Battlefield);

        PassTo(game, 3, TurnStep.PrecombatMain);

        var handBefore = game.State.GetPlayer(alice).Hand.Count;
        game.ActivateAbility(alice, box, ability.Id, targets: null, costPayment: [first, second]);
        Settle(game);

        Assert.Equal(handBefore + 1, game.State.GetPlayer(alice).Hand.Count);
        Assert.True(game.State.GetObject(first).Permanent!.IsTapped);
        Assert.True(game.State.GetObject(second).Permanent!.IsTapped);
    }

    [Fact]
    public void A_cost_written_after_another_may_name_the_permanent_by_pronoun()
    {
        var quest = Card(
            "Quest Pronoun Test",
            "Remove three quest counters from ~ and sacrifice it: Draw a card.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(quest);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var relic = game.Create(alice, quest, Zone.Battlefield);
        game.AddCounters(relic, "quest", 3);

        var handBefore = game.State.GetPlayer(alice).Hand.Count;
        game.ActivateAbility(alice, relic, compiled.Activated.Single().Id);
        Settle(game);

        // Both halves of the cost were paid: the counters went and so did the permanent.
        Assert.Equal(handBefore + 1, game.State.GetPlayer(alice).Hand.Count);
        Assert.DoesNotContain(relic, game.State.Battlefield);
    }

    [Fact]
    public void Returning_itself_to_hand_is_a_cost_paid_before_the_ability_resolves()
    {
        var wheel = Card(
            "Self Bounce Test",
            "Return ~ to its owner's hand: Draw a card.",
            CardType.Artifact);

        var compiled = CardCompiler.Compile(wheel);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var relic = game.Create(alice, wheel, Zone.Battlefield);

        var handBefore = game.State.GetPlayer(alice).Hand.Count;
        game.ActivateAbility(alice, relic, compiled.Activated.Single().Id);

        // Paid as the ability is announced, before it resolves - so it is already in hand while
        // the draw is still on the stack, and nothing can kill it in reply to stop the payment.
        Assert.DoesNotContain(relic, game.State.Battlefield);

        Settle(game);

        // The card itself plus the card drawn.
        Assert.Equal(handBefore + 2, game.State.GetPlayer(alice).Hand.Count);
    }

    [Fact]
    public void Conditional_evasion_switches_off_when_its_condition_stops_holding()
    {
        var sneak = Card(
            "Conditional Evasion Test",
            "~ can't be blocked as long as you control an artifact.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var compiled = CardCompiler.Compile(sneak);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var creature = game.Create(alice, sneak, Zone.Battlefield);

        // No artifact yet, so the evasion is not there.
        Assert.False(
            Characteristics.Of(game.State, Pool, game.State.GetObject(creature))
                .Has(KeywordAbility.CantBeBlocked));

        var relic = game.Create(
            alice, Card("Evasion Relic Test", string.Empty, CardType.Artifact), Zone.Battlefield);

        Assert.True(
            Characteristics.Of(game.State, Pool, game.State.GetObject(creature))
                .Has(KeywordAbility.CantBeBlocked));

        // And it goes away again with the artifact: "as long as" is a condition the game keeps
        // asking, not a one-off check when the permanent arrived.
        game.Move(relic, Zone.Graveyard, MoveCause.Destroy);
        Settle(game);

        Assert.False(
            Characteristics.Of(game.State, Pool, game.State.GetObject(creature))
                .Has(KeywordAbility.CantBeBlocked));
    }

    [Fact]
    public void Cant_attack_unless_is_the_same_restriction_with_the_condition_turned_round()
    {
        var brute = Card(
            "Unless Attack Test",
            "~ can't attack unless you control another artifact.",
            CardType.Creature,
            power: 3,
            toughness: 3);

        var compiled = CardCompiler.Compile(brute);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var creature = game.Create(alice, brute, Zone.Battlefield);

        // No artifact, so the restriction is on - which the engine models as defender
        // (CR 702.3b: defender is exactly "can't attack").
        Assert.True(
            Characteristics.Of(game.State, Pool, game.State.GetObject(creature))
                .Has(KeywordAbility.Defender));

        game.Create(
            alice, Card("Unless Relic Test", string.Empty, CardType.Artifact), Zone.Battlefield);

        // With one, the condition holds and the restriction lifts.
        Assert.False(
            Characteristics.Of(game.State, Pool, game.State.GetObject(creature))
                .Has(KeywordAbility.Defender));
    }

    [Fact]
    public void Defending_player_is_read_off_the_attack_the_creature_is_making()
    {
        var raider = Card(
            "Defender Board Test",
            "~ can't be blocked as long as defending player controls an artifact.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var compiled = CardCompiler.Compile(raider);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, raider, Zone.Battlefield);

        game.Create(
            bob, Card("Defender Relic Test", string.Empty, CardType.Artifact), Zone.Battlefield);

        // Not attacking yet, so there is no defending player and the evasion is off. Answering
        // "nobody controls an artifact" is the honest reading before attackers are declared.
        Assert.False(
            Characteristics.Of(game.State, Pool, game.State.GetObject(attacker))
                .Has(KeywordAbility.CantBeBlocked));

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        // Now the defender is known, and it is Bob's board the condition asks about.
        Assert.True(
            Characteristics.Of(game.State, Pool, game.State.GetObject(attacker))
                .Has(KeywordAbility.CantBeBlocked));
    }

    [Fact]
    public void A_graveyard_count_can_ask_about_one_kind_of_card()
    {
        var brute = Card(
            "Delirium Brute Test",
            "~ has flying as long as there are four or more creature cards in your graveyard.",
            CardType.Creature,
            power: 3,
            toughness: 3);

        var compiled = CardCompiler.Compile(brute);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var creature = game.Create(alice, brute, Zone.Battlefield);

        // Four cards in the graveyard, but only three are creatures - the unfiltered count would
        // already say yes here, which is exactly the difference being tested.
        for (var i = 0; i < 3; i++)
        {
            var body = game.Create(
                alice, TestCards.Creature($"Delirium Body {i} Test", 1, 1), Zone.Battlefield);

            game.Move(body, Zone.Graveyard, MoveCause.Destroy);
        }

        var land = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.Move(land, Zone.Graveyard, MoveCause.Destroy);
        Settle(game);

        Assert.Equal(4, game.State.GetPlayer(alice).Graveyard.Count);

        Assert.False(
            Characteristics.Of(game.State, Pool, game.State.GetObject(creature))
                .Has(KeywordAbility.Flying));

        // A fourth creature card tips it.
        var last = game.Create(
            alice, TestCards.Creature("Delirium Body Last Test", 1, 1), Zone.Battlefield);

        game.Move(last, Zone.Graveyard, MoveCause.Destroy);
        Settle(game);

        Assert.True(
            Characteristics.Of(game.State, Pool, game.State.GetObject(creature))
                .Has(KeywordAbility.Flying));
    }

    [Fact]
    public void A_none_condition_reads_an_adjective_as_part_of_the_noun()
    {
        var brute = Card(
            "No Untapped Test",
            "~ has flying as long as you control no untapped lands.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var compiled = CardCompiler.Compile(brute);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var creature = game.Create(alice, brute, Zone.Battlefield);
        var land = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);

        // An untapped land, so the condition fails. Reading only the noun would have asked "no
        // lands", which is the same answer here but the wrong question.
        Assert.False(
            Characteristics.Of(game.State, Pool, game.State.GetObject(creature))
                .Has(KeywordAbility.Flying));

        // Tapping it satisfies "no untapped lands" while the land is still there - which is
        // exactly what a reading that dropped the adjective could not tell apart.
        game.ActivateAbility(alice, land, "mana");

        Assert.True(
            Characteristics.Of(game.State, Pool, game.State.GetObject(creature))
                .Has(KeywordAbility.Flying));
    }

    [Fact]
    public void A_condition_can_ask_about_a_qualified_permanent()
    {
        var brute = Card(
            "Qualified Condition Test",
            "~ has flying as long as you control a creature with power 4 or greater.",
            CardType.Creature,
            power: 1,
            toughness: 1);

        var compiled = CardCompiler.Compile(brute);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var creature = game.Create(alice, brute, Zone.Battlefield);

        // A creature, but not a big enough one - the qualifier is the whole question, and a
        // reading that dropped it would already say yes here.
        game.Create(alice, TestCards.Creature("Qualified Small Test", 2, 2), Zone.Battlefield);

        Assert.False(
            Characteristics.Of(game.State, Pool, game.State.GetObject(creature))
                .Has(KeywordAbility.Flying));

        game.Create(alice, TestCards.Creature("Qualified Big Test", 5, 5), Zone.Battlefield);

        Assert.True(
            Characteristics.Of(game.State, Pool, game.State.GetObject(creature))
                .Has(KeywordAbility.Flying));
    }

    /// <summary>
    /// "~ deals damage equal to twice the number of Vehicles you control to any target."
    /// </summary>
    /// <remarks>
    /// A multiplier is the same amount as "2 damage for each X" with the fixed part spelled as a
    /// word, so it is read into the per-thing number rather than given a mechanism of its own.
    /// Every verb that already carries a count gets it at once — damage, life and draw all took
    /// the multiplier from the one place the count is built.
    /// </remarks>
    [Fact]
    public void A_count_can_be_multiplied_by_a_word()
    {
        var blast = Card(
            "Doubled Count Test",
            "~ deals damage equal to twice the number of lands you control to any target.");

        var compiled = CardCompiler.Compile(blast);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var victim = game.Create(bob, TestCards.Creature("Doubled Victim Test", 9, 9), Zone.Battlefield);

        var lands = Enumerable.Range(0, 3)
            .Select(_ => game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield))
            .ToList();

        game.ActivateAbility(alice, lands[0], "mana");

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, blast), [Target.ToPermanent(victim)]);

        Settle(game);

        // Three lands, doubled: six, not three. The un-multiplied reading is the one this test
        // exists to catch, because it is plausible and quietly halves every card that says it.
        Assert.Equal(6, game.State.GetObject(victim).Permanent!.DamageMarked);
    }

    /// <summary>
    /// "~ deals damage equal to the number of colors among permanents you control to any target."
    /// </summary>
    /// <remarks>
    /// Like domain, this counts something *about* the permanents rather than how many there are,
    /// which the group grammar cannot express: five green permanents are one colour, and one
    /// Bant creature is three. Colour comes off the computed characteristics, so a permanent that
    /// has been made another colour counts as that colour (CR 105.2, 613.1e).
    /// </remarks>
    [Fact]
    public void Colours_among_a_group_are_counted_once_each()
    {
        var prism = Card(
            "Colour Count Test",
            "~ deals damage equal to the number of colors among permanents you control "
                + "to any target.");

        var compiled = CardCompiler.Compile(prism);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var victim = game.Create(bob, TestCards.Creature("Colour Victim Test", 9, 9), Zone.Battlefield);

        // Two greens and a white: two colours, not three permanents.
        game.Create(alice, Coloured("Colour Green One Test", ManaColor.Green), Zone.Battlefield);
        game.Create(alice, Coloured("Colour Green Two Test", ManaColor.Green), Zone.Battlefield);
        game.Create(alice, Coloured("Colour White Test", ManaColor.White), Zone.Battlefield);

        var land = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, prism), [Target.ToPermanent(victim)]);

        Settle(game);

        Assert.Equal(2, game.State.GetObject(victim).Permanent!.DamageMarked);
    }

    /// <summary>
    /// "~ deals damage equal to the number of instant and sorcery cards in your graveyard."
    /// </summary>
    /// <remarks>
    /// The printed "and" between two card types means either, not both — no card is an instant
    /// *and* a sorcery, so the conjunctive reading counts zero every time and the card silently
    /// does nothing. Juxtaposition is the opposite ("artifact creature cards" does mean both),
    /// which is why the split is on the word rather than on the type list.
    /// </remarks>
    [Fact]
    public void Two_card_types_joined_by_and_count_either_one()
    {
        var flame = Card(
            "Type Pair Count Test",
            "~ deals damage equal to the number of instant and sorcery cards in your graveyard "
                + "to any target.");

        var compiled = CardCompiler.Compile(flame);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var victim = game.Create(bob, TestCards.Creature("Type Pair Victim Test", 9, 9), Zone.Battlefield);

        game.Create(alice, Card("Type Pair Instant Test", "Draw a card."), Zone.Graveyard);
        game.Create(
            alice,
            Card("Type Pair Sorcery Test", "Draw a card.", CardType.Sorcery),
            Zone.Graveyard);

        // A creature card in the same graveyard is not counted: "either of these two types" is
        // still a filter, and a reader that fell back to counting every card would pass without.
        game.Create(alice, TestCards.Creature("Type Pair Body Test", 1, 1), Zone.Graveyard);

        var land = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, flame), [Target.ToPermanent(victim)]);

        Settle(game);

        Assert.Equal(2, game.State.GetObject(victim).Permanent!.DamageMarked);
    }

    /// <summary>
    /// "As long as you're the monarch, ~ gets +1/+1" (CR 725.1).
    /// </summary>
    /// <remarks>
    /// The reader for this existed and had never fired: the pattern wanted a space in front of
    /// the contraction, and no card prints "you 're the monarch". A condition that silently never
    /// holds is worse than one that is missing — the card compiles, plays, and is quietly a
    /// vanilla creature — which is why this is asserted true rather than just compiled.
    /// </remarks>
    [Fact]
    public void The_monarch_condition_reads_the_contraction_cards_actually_print()
    {
        var courtier = Card(
            "Monarch Condition Test",
            "As long as you're the monarch, ~ gets +2/+2.",
            CardType.Creature,
            power: 1,
            toughness: 1);

        var compiled = CardCompiler.Compile(courtier);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var knight = game.Create(alice, courtier, Zone.Battlefield);
        Settle(game);

        Assert.Null(game.State.MonarchId);
        Assert.Equal(1, Characteristics.Of(game.State, Pool, game.State.GetObject(knight)).Power);

        game.Create(alice, Card(
            "Monarch Condition Crown Test",
            "When ~ enters, you become the monarch.",
            CardType.Creature,
            power: 1,
            toughness: 1), Zone.Battlefield);

        Settle(game);

        Assert.Equal(alice, game.State.MonarchId);
        Assert.Equal(3, Characteristics.Of(game.State, Pool, game.State.GetObject(knight)).Power);
    }

    /// <summary>
    /// "When ~ enters, if there are no creatures on the battlefield, draw a card."
    /// </summary>
    /// <remarks>
    /// A question about the whole board rather than about one side, which the controls-reader
    /// could not ask: it had no way to say "anybody's". The case that separates the two readings
    /// is the only one worth asserting — you control no creatures and an opponent does — because
    /// a reader that quietly answered "you control no creatures" instead passes every other
    /// arrangement and is wrong at the only table that matters.
    /// </remarks>
    [Fact]
    public void An_emptiness_condition_asks_about_the_whole_board_not_your_half()
    {
        var ward = Card(
            "Empty Board Test",
            "When ~ enters, if there are no creatures on the battlefield, draw a card.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(ward);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();

        // Alice controls no creatures; Bob controls one. "You control no creatures" is true here
        // and "there are no creatures on the battlefield" is false, so the two readings disagree.
        game.Create(bob, TestCards.Creature("Empty Board Opponent Test", 1, 1), Zone.Battlefield);
        Settle(game);

        var before = game.State.GetPlayer(alice).Hand.Count;

        game.Create(alice, ward, Zone.Battlefield);
        Settle(game);

        Assert.Equal(before, game.State.GetPlayer(alice).Hand.Count);
    }

    /// <summary>
    /// "As long as you control three or more creatures with different powers, ~ gets +2/+2."
    /// </summary>
    /// <remarks>
    /// Distinct values rather than a tally: three 2/2s are one power and fail it. The counting
    /// reader would have taken this sentence first — "three or more creatures" is exactly its
    /// shape — and then failed on the qualifier, ending the read, so the specific question is
    /// asked before the general one. Power is computed rather than printed, which is why the
    /// sizes here are chosen so that the bonus the condition grants cannot collapse two of them
    /// together and switch itself back off (CR 613.4).
    /// </remarks>
    [Fact]
    public void A_condition_can_count_distinct_powers_rather_than_creatures()
    {
        var council = Card(
            "Distinct Power Test",
            "As long as you control three or more creatures with different powers, ~ gets +2/+2.",
            CardType.Creature,
            power: 1,
            toughness: 1);

        var compiled = CardCompiler.Compile(council);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var measured = game.Create(alice, council, Zone.Battlefield);

        // Three creatures, two of them the same size: two distinct powers, so it is off. A plain
        // count of creatures would have turned it on here.
        game.Create(alice, TestCards.Creature("Distinct Power Twin One Test", 2, 2), Zone.Battlefield);
        game.Create(alice, TestCards.Creature("Distinct Power Twin Two Test", 2, 2), Zone.Battlefield);
        Settle(game);

        Assert.Equal(
            1, Characteristics.Of(game.State, Pool, game.State.GetObject(measured)).Power);

        // A third size turns it on. Four rather than three, so that the +2/+2 this grants takes
        // the subject to 3 without landing on a power something else already has.
        game.Create(alice, TestCards.Creature("Distinct Power Third Test", 4, 4), Zone.Battlefield);
        Settle(game);

        Assert.Equal(
            3, Characteristics.Of(game.State, Pool, game.State.GetObject(measured)).Power);
    }

    // ---- A condition in the middle of an effect (CR 608.2c) -------------------

    /// <summary>"If you control a Swamp, destroy target nonblack creature." — Horobi's Whisper.</summary>
    /// <remarks>
    /// Both halves of this sentence had been readable for a long time and there was no way to say
    /// them together: <c>BoardConditions</c> is the condition vocabulary the statics, the
    /// activation restrictions and the trigger's intervening "if" all share, and <c>OnlyIf</c> is
    /// the wrapper that guards effects with one — but nothing let a plain sentence reach either.
    /// 94 cards were one line short with both halves of that line already understood.
    /// <para>
    /// This "if" is <em>not</em> an intervening one and is checked once, as the instruction is
    /// carried out (CR 608.2c). CR 603.4 gives the double check only to an "if" immediately
    /// following a trigger condition, and says outright that everywhere else the word has its
    /// normal English meaning.
    /// </para>
    /// <para>
    /// Both states are asserted, because that is the only thing that separates this reader from
    /// the mistake it is one line away from: a condition quietly defaulted to true compiles, plays,
    /// and passes every test that only ever satisfies it. The spell is cast at the same creature
    /// twice, once with the Swamp and once without.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_condition_inside_an_effect_is_checked_when_the_effect_resolves()
    {
        var whisper = Card(
            "Conditional Destroy Test", "If you control a Swamp, destroy target nonblack creature.");

        var compiled = CardCompiler.Compile(whisper);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var bear = game.Create(bob, TestCards.Creature("Conditional Bear Test", 2, 2), Zone.Battlefield);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, whisper), [Target.ToPermanent(bear)]);
        Settle(game);

        // No Swamp, so the spell resolved and the condition refused it. The card is in the
        // graveyard either way, which is why the creature is what this asserts on.
        Assert.Contains(bear, game.State.Battlefield);

        game.Create(alice, TestCards.BasicLand("Swamp"), Zone.Battlefield);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, whisper), [Target.ToPermanent(bear)]);
        Settle(game);

        Assert.DoesNotContain(bear, game.State.Battlefield);
        Assert.Single(game.State.GetPlayer(bob).Graveyard);
    }

    /// <summary>"If you control an artifact, draw a card and you gain 2 life."</summary>
    /// <remarks>
    /// The guarded half is the <em>whole</em> remainder, and this is what says so. Handing the
    /// conjunction to the sentence splitter instead would guard the draw and leave the life gain
    /// unconditional — a card strictly better than the one printed, and one that would look
    /// right in every test that satisfies the condition. So a remainder the parser cannot read
    /// leaves the sentence unread rather than falling through to that split.
    /// </remarks>
    [Fact]
    public void A_conditional_sentence_guards_everything_after_the_comma()
    {
        var relic = Card(
            "Conditional Pair Test", "If you control an artifact, draw a card and you gain 2 life.");

        var compiled = CardCompiler.Compile(relic);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();

        var held = game.State.GetPlayer(alice).Hand.Count;
        game.CastSpell(alice, TestCards.PutInHand(game, alice, relic), targets: null);
        Settle(game);

        // The copy that was put in hand to be cast is gone and nothing replaced it, and the life
        // gain the "and" joined to the draw stayed behind with it.
        Assert.Equal(held, game.State.GetPlayer(alice).Hand.Count);
        Assert.Equal(20, game.State.GetPlayer(alice).Life);

        game.Create(alice, Card("Conditional Relic Test", string.Empty, CardType.Artifact), Zone.Battlefield);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, relic), targets: null);
        Settle(game);

        Assert.Equal(held + 1, game.State.GetPlayer(alice).Hand.Count);
        Assert.Equal(22, game.State.GetPlayer(alice).Life);
    }

    // ---- A pump that also grants, said about the source ----------------------

    /// <summary>"{2}{U}{U}: ~ gets +2/+2 and gains flying until end of turn." — Mistform Stalker.</summary>
    /// <remarks>
    /// The targeted twin of this sentence has worked for a long time and the source form stopped
    /// at the size, so every card saying it about itself was unread — 34 corpus occurrences, and
    /// 37 more in the pronoun form below. Both halves are asserted, because a reader that took
    /// the sentence and dropped the grant would compile perfectly and still be a weaker card.
    /// <para>
    /// The refusal is asserted beside it: a card that got the +2/+2 without the rest of what it
    /// said would look implemented, so the reader has to drop the whole line, and that is the
    /// answer the targeted reader already gives. The grant it refuses is chosen deliberately.
    /// This control first named phasing, which was ungrantable only because the word was missing
    /// from <c>EffectPhrase.Keywords</c>; when a later round wrote that word down for
    /// "enchanted permanent has phasing", the control failed while nothing about this reader had
    /// changed. A negative control anchored to a gap in that table re-arms every time the table
    /// grows, and it is under active expansion. Protection from a creature type cannot be closed
    /// that way: the table holds one flag per colour and the ability takes a quality, so no
    /// dictionary line can carry it. Diregraf Escort is short on exactly this line and no other.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_self_pump_grants_its_keyword_in_the_same_sentence()
    {
        var stalker = Card(
            "Self Pump Grant Test",
            "{2}{U}{U}: ~ gets +2/+2 and gains flying until end of turn.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var compiled = CardCompiler.Compile(stalker);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var creature = game.Create(alice, stalker, Zone.Battlefield);

        foreach (var name in new[] { "Island", "Island", "Mountain", "Mountain" })
            game.ActivateAbility(alice, game.Create(alice, TestCards.BasicLand(name), Zone.Battlefield), "mana");

        game.ActivateAbility(alice, creature, "a");
        Settle(game);

        var computed = Characteristics.Of(game.State, Pool, game.State.GetObject(creature));
        Assert.Equal(4, computed.Power);
        Assert.True(computed.Has(KeywordAbility.Flying));

        var unreadable = CardCompiler.Compile(Card(
            "Self Pump Refusal Test",
            "{2}{U}{U}: ~ gets +2/+2 and gains protection from Zombies until end of turn.",
            CardType.Creature,
            power: 2,
            toughness: 2));

        // Whole or nothing: the size is not kept without the grant that shared its sentence.
        Assert.False(unreadable.IsComplete);
        Assert.Contains(
            unreadable.Unhandled,
            line => line.Contains("protection from Zombies", StringComparison.Ordinal));
    }

    /// <summary>
    /// "Gain control of target creature until end of turn. Untap that creature. It gets +2/+0 and
    /// gains haste until end of turn." — Malevolent Whispers.
    /// </summary>
    /// <remarks>
    /// The pronoun carries the grant to whatever the sentences before it named, which on this
    /// card is a creature the caster does not own. That is what makes it the right test: all
    /// three clauses have to land on the same permanent, and the haste is the only one of them a
    /// stolen creature notices — without it the card gains a creature that cannot attack, which
    /// is the whole point of the spell.
    /// </remarks>
    [Fact]
    public void A_pronoun_pump_grants_its_keyword_to_the_creature_it_took()
    {
        var whispers = Card(
            "Pronoun Grant Test",
            "Gain control of target creature until end of turn. Untap that creature. "
                + "It gets +2/+0 and gains haste until end of turn.");

        var compiled = CardCompiler.Compile(whispers);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var theirs = game.Create(bob, TestCards.Creature("Borrowed Ogre Test", 3, 3), Zone.Battlefield);
        var card = TestCards.PutInHand(game, alice, whispers);

        game.CastSpell(alice, card, [Target.ToPermanent(theirs)]);
        Settle(game);

        var computed = Characteristics.Of(game.State, Pool, game.State.GetObject(theirs));
        Assert.Equal(alice, computed.ControllerId);
        Assert.Equal(5, computed.Power);
        Assert.True(computed.Has(KeywordAbility.Haste));
    }

    // ---- The trigger subject grammar, applied to attacking and to two nouns ---

    /// <summary>
    /// "Whenever a Dragon you control attacks, ..." — Utvara Hellkite and twenty-odd others.
    /// </summary>
    /// <remarks>
    /// The attack trigger had one hand-written reader for the plainest form of it, so the tribe,
    /// the colour, the "another", the opponent's side and the power qualifier were all missing
    /// from attacking while sitting in the shared subject grammar for entering and dying. Adding
    /// the verb to that grammar reaches 35 corpus lines at once and deletes the hand-written one.
    /// <para>
    /// The Bear attacks first and alone, which is the assertion that matters: a reader that lost
    /// the tribe would fire here, and the coverage number would not move a point either way.
    /// </para>
    /// </remarks>
    [Fact]
    public void An_attack_trigger_reads_the_tribe_in_its_subject()
    {
        var watcher = Card(
            "Dragon Watcher Test",
            "Whenever a Dragon you control attacks, you gain 2 life.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(watcher);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, watcher, Zone.Battlefield);

        var bear = game.Create(alice, TestCards.Creature("Untribal Bear Test"), Zone.Battlefield);
        var dragon = game.Create(
            alice,
            Card("Hellkite Test", string.Empty, CardType.Creature, 4, 4, KeywordAbility.None, "Dragon"),
            Zone.Battlefield);

        TestCards.PassToTurn(game, 3);
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [bear] = AttackTarget.Player(bob) });

        Settle(game);
        Assert.Equal(20, game.State.GetPlayer(alice).Life);

        TestCards.PassToTurn(game, 5);
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [dragon] = AttackTarget.Player(bob) });

        Settle(game);
        Assert.Equal(22, game.State.GetPlayer(alice).Life);
    }

    /// <summary>
    /// "Whenever a Wolf or Werewolf you control deals combat damage to a player, draw a card." —
    /// Tovolar, Dire Overlord.
    /// </summary>
    /// <remarks>
    /// One noun in the subject was read and two were not, on 36 corpus lines whose every other
    /// part — the scope, the side, the qualifier, the verb — this grammar already handled. All
    /// three creatures connect in one combat so that the two halves and the refusal are read off
    /// the same declaration: a reader that took only the first noun draws one card here, one that
    /// dropped the filter draws three, and the printed card draws two.
    /// </remarks>
    [Fact]
    public void A_trigger_subject_can_name_either_of_two_types()
    {
        var tovolar = Card(
            "Two Noun Test",
            "Whenever a Wolf or Werewolf you control deals combat damage to a player, draw a card.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(tovolar);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, tovolar, Zone.Battlefield);

        var wolf = game.Create(
            alice,
            Card("Pack Wolf Test", string.Empty, CardType.Creature, 1, 1, KeywordAbility.None, "Wolf"),
            Zone.Battlefield);

        var werewolf = game.Create(
            alice,
            Card("Moon Howler Test", string.Empty, CardType.Creature, 1, 1, KeywordAbility.None, "Werewolf"),
            Zone.Battlefield);

        var bear = game.Create(alice, TestCards.Creature("Untribal Bear Test", 1, 1), Zone.Battlefield);

        TestCards.PassToTurn(game, 3);
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);

        var held = game.State.GetPlayer(alice).Hand.Count;

        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget>
            {
                [wolf] = AttackTarget.Player(bob),
                [werewolf] = AttackTarget.Player(bob),
                [bear] = AttackTarget.Player(bob),
            });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Settle(game);

        Assert.Equal(held + 2, game.State.GetPlayer(alice).Hand.Count);
    }

    /// <summary>
    /// "Whenever ~ deals combat damage to a player or planeswalker, ..." — Storrev, Devkarin Lich.
    /// </summary>
    /// <remarks>
    /// The recipient of the damage is a list on 29 corpus lines and the reader took one noun, so
    /// a creature that hit a planeswalker satisfied nothing. Which permanent took the damage is
    /// asked of the object rather than of its card, for the same reason the attacking subject is.
    /// <para>
    /// A battle is named by the same reader and is not tested, because nothing in this engine can
    /// attack one yet: <c>AttackTarget</c> holds a player or a planeswalker and has no third
    /// case. The gap is in combat rather than in this grammar, which is why the noun is read here
    /// instead of the line being refused.
    /// </para>
    /// </remarks>
    [Fact]
    public void Combat_damage_to_a_planeswalker_answers_the_or_clause()
    {
        var lich = Card(
            "Damage Recipient Test",
            "Whenever ~ deals combat damage to a player or planeswalker, you gain 3 life.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var compiled = CardCompiler.Compile(lich);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, lich, Zone.Battlefield);
        var walker = game.Create(bob, Walker("Attacked Walker Test", 5, "+1: You gain 1 life."), Zone.Battlefield);

        TestCards.PassToTurn(game, 3);
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.At(bob, walker) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Settle(game);

        // The planeswalker took the damage, so Bob's life is untouched and the trigger still fired.
        Assert.Equal(20, game.State.GetPlayer(bob).Life);
        Assert.Equal(23, game.State.GetPlayer(alice).Life);
    }

    // ---- Tapping the permanent that says so -----------------------------------

    /// <summary>"Whenever another creature dies, tap ~." — Fleshmad Steed.</summary>
    /// <remarks>
    /// The untap half of this pair has been read for a long time and the tap half had no reader
    /// at all, which is the wrong way round to be missing: every one of the twelve corpus lines
    /// saying it is a drawback, so leaving it unread made each of those cards strictly better
    /// than printed. No new effect was needed — <c>TapTarget</c> already asks the shared subject
    /// resolver which permanent it means, and naming the source is an argument to it.
    /// </remarks>
    [Fact]
    public void A_permanent_can_be_told_to_tap_itself()
    {
        var steed = Card(
            "Self Tap Test",
            "Whenever another creature dies, tap ~.",
            CardType.Creature,
            power: 3,
            toughness: 1);

        var compiled = CardCompiler.Compile(steed);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var horse = game.Create(alice, steed, Zone.Battlefield);
        var doomed = game.Create(alice, TestCards.Creature("Doomed Bear Test"), Zone.Battlefield);

        Assert.False(game.State.GetObject(horse).Permanent!.IsTapped);

        var murder = TestCards.PutInHand(game, alice, Card("Self Tap Murder Test", "Destroy target creature."));
        game.CastSpell(alice, murder, [Target.ToPermanent(doomed)]);
        Settle(game);

        Assert.True(game.State.GetObject(horse).Permanent!.IsTapped);
    }

    // ---- Counting the first spell of a kind each turn --------------------------

    /// <summary>
    /// "Whenever you cast your first noncreature spell each turn, ..." — Valeria Richards.
    /// </summary>
    /// <remarks>
    /// The creature spell is cast <em>first</em> on purpose, and it is what the test is for. The
    /// count has to be the count of noncreature spells and not of spells: reading it as "your
    /// first spell each turn" would have the Bear use up the trigger and the instant behind it
    /// would do nothing, which is a card that fires roughly never in a real game.
    /// <para>
    /// The third cast is the other half of the same question. Both are answered from
    /// <c>NoncreatureSpellsCastThisTurn</c>, which the reducer keeps for exactly this shape, so
    /// the reading is exact rather than an approximation of "once each turn" — see the note on
    /// <c>NthEachTurn</c> for the ten corpus lines whose type the player does not count and which
    /// are therefore left unread.
    /// </para>
    /// </remarks>
    [Fact]
    public void The_first_noncreature_spell_each_turn_is_counted_by_type()
    {
        var valeria = Card(
            "First Noncreature Test",
            "Whenever you cast your first noncreature spell each turn, you gain 2 life.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(valeria);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        game.Create(alice, valeria, Zone.Battlefield);

        game.CastSpell(
            alice,
            TestCards.PutInHand(game, alice, TestCards.Creature("First Cast Bear Test")),
            targets: null);

        Settle(game);
        Assert.Equal(20, game.State.GetPlayer(alice).Life);

        game.CastSpell(
            alice,
            TestCards.PutInHand(game, alice, Card("First Instant Test", "You gain 1 life.")),
            targets: null);

        Settle(game);
        Assert.Equal(23, game.State.GetPlayer(alice).Life);

        game.CastSpell(
            alice,
            TestCards.PutInHand(game, alice, Card("Second Instant Test", "You gain 1 life.")),
            targets: null);

        Settle(game);
        Assert.Equal(24, game.State.GetPlayer(alice).Life);
    }

    // ---- The counted-group vocabulary (CR 107.3) -----------------------------

    /// <summary>
    /// "For each +1/+1 counter on this creature" — counting what is on the source.
    /// </summary>
    /// <remarks>
    /// Four spellings of one question, and the reason they are a <c>Theory</c> rather than four
    /// tests is that they are the same count: "this creature" and "it" both name the object the
    /// ability is printed on (CR 700.7), and the plural is only how the "number of" wording
    /// declines the noun. Each of the three was a separate refusal — the commonest counted group
    /// in the corpus, "the number of +1/+1 counters on it", was turned away by one letter.
    /// <para>
    /// The last row names no kind at all, which is a different question answered in nearly the
    /// same words: every counter, of every kind (CR 122.1). Three is the answer that separates
    /// it from a lookup of a counter called "", which would be nought.
    /// </para>
    /// </remarks>
    /// <remarks>
    /// Each row carries its own card name, and that is not tidiness: the compiled pool is keyed by
    /// oracle id, two fixtures sharing a name share an id, and the pool then serves one row's
    /// behaviour for another. It throws here rather than passing quietly, which is the only reason
    /// this note is short.
    /// </remarks>
    [Theory]
    [InlineData("This", "you gain 1 life for each +1/+1 counter on this creature.")]
    [InlineData("It", "you gain 1 life for each +1/+1 counter on it.")]
    [InlineData("Number", "you gain X life, where X is the number of +1/+1 counters on it.")]
    [InlineData("Untyped", "you gain 1 life for each counter on it.")]
    public void A_count_of_the_counters_on_the_source_reads_every_spelling(
        string which, string tail)
    {
        var idol = Card(
            "Counted Counters " + which + " Test",
            "~ enters with three +1/+1 counters on it.\nWhen ~ enters, " + tail,
            CardType.Creature,
            power: 1,
            toughness: 1);

        var compiled = CardCompiler.Compile(idol);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        game.Create(alice, idol, Zone.Battlefield);
        Settle(game);

        Assert.Equal(23, game.State.GetPlayer(alice).Life);
    }

    /// <summary>
    /// "For each creature on the battlefield" — a count is already confined to one zone.
    /// </summary>
    /// <remarks>
    /// Bob's creature is what the test is for. The words name no controller, so the count is
    /// every creature and not the caster's; a reading that quietly kept "you control" would give
    /// two here and would be a smaller card than the one printed.
    /// </remarks>
    [Fact]
    public void A_count_over_the_battlefield_includes_every_controller()
    {
        var congregate = Card(
            "Congregate Test",
            "You gain 1 life for each creature on the battlefield.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(congregate);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, TestCards.Creature("Congregate Bear One Test", 2, 2), Zone.Battlefield);
        game.Create(alice, TestCards.Creature("Congregate Bear Two Test", 2, 2), Zone.Battlefield);
        game.Create(bob, TestCards.Creature("Congregate Enemy Test", 2, 2), Zone.Battlefield);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, congregate), []);
        Settle(game);

        Assert.Equal(23, game.State.GetPlayer(alice).Life);
    }

    /// <summary>
    /// "For each opponent you have" — the possessive spelled out, and no narrower for it.
    /// </summary>
    /// <remarks>
    /// One, not two. The distinction the number makes is the whole test: a reading that took the
    /// tail as part of the group would have found nothing and gained nought, and one that counted
    /// players rather than opponents would gain two at a two-player table.
    /// </remarks>
    [Fact]
    public void A_count_of_opponents_you_have_counts_opponents_and_not_players()
    {
        var levy = Card(
            "Opponents You Have Test",
            "You gain 1 life for each opponent you have.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(levy);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        game.CastSpell(alice, TestCards.PutInHand(game, alice, levy), []);
        Settle(game);

        Assert.Equal(21, game.State.GetPlayer(alice).Life);
    }

    /// <summary>
    /// "For each Aura attached to this creature" — counting a pair, not a permanent.
    /// </summary>
    /// <remarks>
    /// Attachment is a fact about two permanents together, which is why the group grammar cannot
    /// express it and why this counts by walking the battlefield for what points back at the
    /// source. Two Auras rather than one, so that a reader answering "is anything attached"
    /// instead of "how many" fails here.
    /// <para>
    /// The trigger is on another creature arriving rather than on this one, because the Auras
    /// have to be on before the count is taken and an enters trigger resolves before anything
    /// could enchant it.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_count_of_what_is_attached_reads_the_sources_own_auras()
    {
        var knight = Card(
            "Attached Count Test",
            "Whenever another creature you control enters, "
                + "you gain 1 life for each Aura attached to this creature.",
            CardType.Creature,
            power: 1,
            toughness: 1);

        var compiled = CardCompiler.Compile(knight);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var hero = game.Create(alice, knight, Zone.Battlefield);

        foreach (var name in new[] { "Attached Aura One Test", "Attached Aura Two Test" })
        {
            var aura = Card(
                name,
                "Enchant creature\nEnchanted creature gets +0/+1.",
                CardType.Enchantment,
                subtypes: "Aura");

            game.CastSpell(
                alice, TestCards.PutInHand(game, alice, aura), [Target.ToPermanent(hero)]);

            Settle(game);
        }

        var before = game.State.GetPlayer(alice).Life;
        game.Create(alice, TestCards.Creature("Attached Bear Test", 2, 2), Zone.Battlefield);
        Settle(game);

        Assert.Equal(before + 2, game.State.GetPlayer(alice).Life);
    }

    /// <summary>
    /// "For each artifact and/or enchantment you control" — alternatives, written with a slash.
    /// </summary>
    /// <remarks>
    /// Two, not three and not one. The Bear is there so that a reading which dropped the noun
    /// and counted permanents fails, and the pair is there so that a reading which took only one
    /// side of the slash fails.
    /// </remarks>
    [Fact]
    public void A_count_can_name_two_kinds_with_a_slash()
    {
        var nettlecyst = Card(
            "And Or Count Test",
            "You gain 1 life for each artifact and/or enchantment you control.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(nettlecyst);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        game.Create(
            alice,
            Card("And Or Artifact Test", string.Empty, CardType.Artifact),
            Zone.Battlefield);

        game.Create(
            alice,
            Card("And Or Enchantment Test", string.Empty, CardType.Enchantment),
            Zone.Battlefield);

        game.Create(alice, TestCards.Creature("And Or Bear Test", 2, 2), Zone.Battlefield);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, nettlecyst), []);
        Settle(game);

        Assert.Equal(22, game.State.GetPlayer(alice).Life);
    }

    /// <summary>
    /// "For each card in your library" — the third pile, beside the hand and the graveyard.
    /// </summary>
    /// <remarks>
    /// Asserted against the library as it actually stands rather than against a number written
    /// here, because the opening draw has already taken from it and a hard-coded total would be
    /// testing the deck size instead of the count.
    /// </remarks>
    [Fact]
    public void A_count_can_ask_the_library()
    {
        var oracle = Card(
            "Library Count Test",
            "You gain 1 life for each card in your library.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(oracle);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        game.CastSpell(alice, TestCards.PutInHand(game, alice, oracle), []);

        var left = game.State.GetPlayer(alice).Library.Count;
        Settle(game);

        Assert.Equal(20 + left, game.State.GetPlayer(alice).Life);
    }

    /// <summary>
    /// A subtype that is not a creature type names the card type it belongs to (CR 205.3).
    /// </summary>
    /// <remarks>
    /// The failure this exists to stop was invisible: reading every capitalised noun as a
    /// creature type made "for each Equipment you control" ask for a <em>creature</em> with the
    /// Equipment subtype, of which there are none. The card compiled, reported itself complete,
    /// resolved, and gained nothing — measured at 20 life where the card says 22. 945 corpus
    /// cards name a subtype from the artifact, enchantment or land lists.
    /// </remarks>
    [Fact]
    public void A_subtype_that_is_not_a_creature_type_still_counts()
    {
        var levy = Card(
            "Equipment Count Test",
            "You gain 1 life for each Equipment you control.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(levy);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();

        foreach (var name in new[] { "Gear One Test", "Gear Two Test" })
        {
            game.Create(
                alice,
                Card(name, string.Empty, CardType.Artifact, subtypes: "Equipment"),
                Zone.Battlefield);
        }

        game.CastSpell(alice, TestCards.PutInHand(game, alice, levy), []);
        Settle(game);

        Assert.Equal(22, game.State.GetPlayer(alice).Life);
    }

    /// <summary>
    /// "Target Nissa planeswalker" — the subtype with its card type printed after it.
    /// </summary>
    /// <remarks>
    /// "Target Nissa" was already read and this was not, on 38 cards, because the word after the
    /// subtype was consumed and thrown away. It cannot be thrown away: the planeswalker types are
    /// eighty proper names sharing no list with the creature types, so the subtype table would
    /// have to hold all of them and go stale every set. The printed word says which type it is.
    /// <para>
    /// The Bear is here to prove the type half is doing work. Without it the walker alone would
    /// pass a reading that had kept the creature default and simply found nothing else.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_named_planeswalker_can_be_targeted_by_its_type()
    {
        var hunt = Card(
            "Walker Hunt Test", "Destroy target Nissa planeswalker.", CardType.Sorcery);

        var compiled = CardCompiler.Compile(hunt);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        game.Create(bob, TestCards.Creature("Walker Bear Test", 2, 2), Zone.Battlefield);

        var walker = game.Create(
            bob,
            Card("Walker Nissa Test", string.Empty, CardType.Planeswalker, subtypes: "Nissa"),
            Zone.Battlefield);

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, hunt), [Target.ToPermanent(walker)]);

        Settle(game);

        Assert.DoesNotContain(walker, game.State.Battlefield);
    }

    /// <summary>
    /// "For each red or green creature you control" — one adjective naming two colours.
    /// </summary>
    /// <remarks>
    /// The only place in the adjective vocabulary where a word is an alternative rather than one
    /// more thing that has to be true, and the reason all seventeen were lost is ordering: "red"
    /// alone matched, leaving " or green creature" for a noun with no room for it.
    /// <para>
    /// Three creatures, two of which qualify. The blue one is what separates this from a reading
    /// that dropped the colours, and having one of each named colour separates it from a reading
    /// that kept only the first.
    /// </para>
    /// </remarks>
    /// <summary>
    /// "As long as you control a red or white permanent" — the same pair inside a condition.
    /// </summary>
    /// <remarks>
    /// The condition grammar reaches the same noun vocabulary, so the colour pair arrives there
    /// too — and this is the test that says the reading is the printed one rather than a
    /// condition that is quietly always true. The blue permanent is the whole point: a static
    /// that switched on for any permanent at all would pass every other assertion here.
    /// </remarks>
    [Fact]
    public void A_colour_pair_in_a_condition_is_one_noun_and_not_a_join()
    {
        var lord = Card(
            "Colour Pair Condition Test",
            "As long as you control a red or white permanent, ~ gets +1/+1.",
            CardType.Creature,
            power: 1,
            toughness: 1);

        var compiled = CardCompiler.Compile(lord);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var self = game.Create(alice, lord, Zone.Battlefield);

        int? Power() => Characteristics.PowerOf(game.State, Pool, game.State.GetObject(self));

        Assert.Equal(1, Power());

        game.Create(alice, Coloured("Colour Cond Blue Test", ManaColor.Blue), Zone.Battlefield);
        Assert.Equal(1, Power());

        game.Create(alice, Coloured("Colour Cond White Test", ManaColor.White), Zone.Battlefield);
        Assert.Equal(2, Power());
    }

    [Fact]
    public void A_count_can_name_two_colours_as_alternatives()
    {
        var tally = Card(
            "Colour Pair Test",
            "You gain 1 life for each red or green creature you control.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(tally);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        game.Create(alice, Coloured("Colour Red Test", ManaColor.Red), Zone.Battlefield);
        game.Create(alice, Coloured("Colour Green Test", ManaColor.Green), Zone.Battlefield);
        game.Create(alice, Coloured("Colour Blue Test", ManaColor.Blue), Zone.Battlefield);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, tally), []);
        Settle(game);

        Assert.Equal(22, game.State.GetPlayer(alice).Life);
    }

    /// <summary>
    /// "Whenever one or more creatures you control attack, draw that many cards."
    /// </summary>
    /// <remarks>
    /// The trigger fires once for the batch (CR 508.1) and the amount is the batch's size, which
    /// is why this was refused for as long as the declaration carried no number: it compiled, it
    /// fired, and it drew nothing. Two attackers rather than one is the whole assertion — a
    /// reading that fired correctly and then took "that many" as one would pass at half strength.
    /// </remarks>
    [Fact]
    public void One_or_more_attackers_is_a_number_the_trigger_can_use()
    {
        var radha = Card(
            "Batch Attack Test",
            "Whenever one or more creatures you control attack, draw that many cards.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(radha);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, radha, Zone.Battlefield);

        var first = game.Create(
            alice, TestCards.Creature("Batch Attacker One Test", 2, 2), Zone.Battlefield);
        var second = game.Create(
            alice, TestCards.Creature("Batch Attacker Two Test", 2, 2), Zone.Battlefield);

        PassTo(game, 3, TurnStep.DeclareAttackers);

        var held = game.State.GetPlayer(alice).Hand.Count;

        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget>
            {
                [first] = AttackTarget.Player(bob),
                [second] = AttackTarget.Player(bob),
            });

        Settle(game);

        Assert.Equal(held + 2, game.State.GetPlayer(alice).Hand.Count);
    }

    /// <summary>
    /// "Whenever you cast your first enchantment spell each turn, you gain 2 life."
    /// </summary>
    /// <remarks>
    /// The instant is cast first on purpose, and it is what the test is for. The count has to be
    /// of enchantment spells and not of spells: reading it as "your first spell each turn" would
    /// have the instant use up the trigger and the enchantment behind it would do nothing.
    /// <para>
    /// The second enchantment is the other half. Both are answered from the cards the player
    /// actually cast, so the reading is exact rather than an approximation through the ability's
    /// once-per-turn flag — which is per (permanent, ability) and would fire for a permanent that
    /// arrived after the turn's first enchantment had already been cast.
    /// </para>
    /// </remarks>
    [Fact]
    public void The_first_spell_of_a_named_kind_each_turn_is_counted_by_that_kind()
    {
        var altar = Card(
            "First Enchantment Test",
            "Whenever you cast your first enchantment spell each turn, you gain 2 life.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(altar);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        game.Create(alice, altar, Zone.Battlefield);

        game.CastSpell(
            alice,
            TestCards.PutInHand(
                game, alice, Card("First Kind Instant Test", "You gain 1 life.")),
            targets: null);

        Settle(game);
        Assert.Equal(21, game.State.GetPlayer(alice).Life);

        // The enchantments carry no text of their own, so every life total below is the trigger
        // and nothing else - a spell that also gained life would leave the two indistinguishable.
        game.CastSpell(
            alice,
            TestCards.PutInHand(
                game, alice, Card("First Kind Charm Test", string.Empty, CardType.Enchantment)),
            targets: null);

        Settle(game);
        Assert.Equal(23, game.State.GetPlayer(alice).Life);

        game.CastSpell(
            alice,
            TestCards.PutInHand(
                game, alice, Card("Second Kind Charm Test", string.Empty, CardType.Enchantment)),
            targets: null);

        Settle(game);

        // Unmoved: the second enchantment this turn is not the first one.
        Assert.Equal(23, game.State.GetPlayer(alice).Life);
    }

    // ---- The verbs that can carry a count ------------------------------------

    /// <summary>
    /// "Create a Treasure token for each creature you control."
    /// </summary>
    /// <remarks>
    /// The creature-token reader has carried a count tail for a long time and the named-token
    /// reader beside it never did, which is an accident of which was written first rather than
    /// anything about tokens: how many of a thing to make has nothing to do with whether its
    /// characteristics are printed or named.
    /// </remarks>
    [Fact]
    public void A_named_token_is_made_once_for_each_thing_counted()
    {
        var hoard = Card(
            "Counted Treasure Test",
            "Create a Treasure token for each creature you control.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(hoard);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        game.Create(alice, TestCards.Creature("Treasure Bear One Test", 2, 2), Zone.Battlefield);
        game.Create(alice, TestCards.Creature("Treasure Bear Two Test", 2, 2), Zone.Battlefield);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, hoard), []);
        Settle(game);

        Assert.Equal(
            2,
            game.State.Battlefield.Select(game.State.GetObject)
                .Count(o => o.Card.Name == "Treasure"));
    }

    /// <summary>
    /// "Target player discards a card for each creature you control." — Mind Sludge's shape.
    /// </summary>
    /// <remarks>
    /// "Each opponent discards a card for each creature you control" read and this did not, which
    /// is not a fact about discarding: the imperative form had been given the shared count tail
    /// and the targeted form had not.
    /// </remarks>
    [Fact]
    public void A_targeted_player_discards_once_for_each_thing_counted()
    {
        var sludge = Card(
            "Counted Sludge Test",
            "Target player discards a card for each creature you control.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(sludge);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, TestCards.Creature("Sludge Bear One Test", 2, 2), Zone.Battlefield);
        game.Create(alice, TestCards.Creature("Sludge Bear Two Test", 2, 2), Zone.Battlefield);

        var held = game.State.GetPlayer(bob).Hand.Count;

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, sludge), [Target.ToPlayer(bob)]);

        Settle(game);

        Assert.Equal(held - 2, game.State.GetPlayer(bob).Hand.Count);
    }

    /// <summary>
    /// "Target opponent loses 2 life for each Swamp you control." — Last Stand's shape.
    /// </summary>
    /// <remarks>
    /// Two per creature rather than one, so that a reading which dropped the printed number and
    /// counted one apiece fails here rather than passing at half strength.
    /// </remarks>
    [Fact]
    public void A_targeted_player_loses_life_once_for_each_thing_counted()
    {
        var stand = Card(
            "Counted Stand Test",
            "Target opponent loses 2 life for each creature you control.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(stand);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, TestCards.Creature("Stand Bear One Test", 2, 2), Zone.Battlefield);
        game.Create(alice, TestCards.Creature("Stand Bear Two Test", 2, 2), Zone.Battlefield);

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, stand), [Target.ToPlayer(bob)]);

        Settle(game);

        Assert.Equal(16, game.State.GetPlayer(bob).Life);
    }

    // ---- X measured on a permanent rather than counted (CR 107.3) ------------

    /// <summary>
    /// "Target creature gets +X/+0 until end of turn, where X is its power." — Onward.
    /// </summary>
    /// <remarks>
    /// "Its" is the creature the head targeted, and the head is the only thing that says so: this
    /// sentence names one permanent and the pronoun can mean nothing else. A phrase whose head
    /// targets a player, or two things, is refused rather than guessed — Dying Wish targets a
    /// player and means the enchanted creature, and reading the player's power would give a card
    /// that resolves and does nothing.
    /// </remarks>
    [Fact]
    public void X_can_be_the_power_of_the_creature_the_sentence_targeted()
    {
        var onward = Card(
            "Onward Test",
            "Target creature gets +X/+0 until end of turn, where X is its power.");

        var compiled = CardCompiler.Compile(onward);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var bear = game.Create(alice, TestCards.Creature("Onward Bear Test", 2, 2), Zone.Battlefield);

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, onward), [Target.ToPermanent(bear)]);

        Settle(game);

        // Doubled, not incremented: the bonus is the power it had, so a 2/2 becomes a 4/2.
        Assert.Equal(4, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(bear)));
        Assert.Equal(2, Characteristics.ToughnessOf(game.State, Pool, game.State.GetObject(bear)));
    }

    /// <summary>
    /// The same clause with no target: "its" is what the trigger was about.
    /// </summary>
    /// <remarks>
    /// The other arm, and the one that keeps an Aura honest. An Aura saying "when enchanted
    /// creature dies, ... where X is its power" means the creature and not itself, and an Aura has
    /// no power at all — so answering with the source would give nought on every printing of that
    /// shape. Reading the trigger's subject answers both: here the subject <em>is</em> the source,
    /// and on the Aura it is not.
    /// </remarks>
    [Fact]
    public void X_can_be_the_power_of_the_creature_the_trigger_was_about()
    {
        var giant = Card(
            "Trigger Power Test",
            "When ~ enters, you gain X life, where X is its power.",
            CardType.Creature,
            power: 3,
            toughness: 3);

        var compiled = CardCompiler.Compile(giant);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        game.Create(alice, giant, Zone.Battlefield);
        Settle(game);

        Assert.Equal(23, game.State.GetPlayer(alice).Life);
    }

    // ---- A pronoun naming what the sentence before it chose ------------------

    /// <summary>
    /// "Target creature you control gets +1/+2 until end of turn. It fights target creature you
    /// don't control." — Epic Confrontation.
    /// </summary>
    /// <remarks>
    /// Twenty cards write the fight as its own sentence, so the first fighter is not named there
    /// at all. The pump is what makes the test mean something: the fight is resolved after it, so
    /// a 2/2 hits for three and kills a 2/2 while surviving the two coming back — which only
    /// happens if the creature that fights is the one that was pumped.
    /// </remarks>
    [Fact]
    public void A_fight_can_name_the_creature_the_sentence_before_it_chose()
    {
        var confrontation = Card(
            "Epic Confrontation Test",
            "Target creature you control gets +1/+2 until end of turn. "
                + "It fights target creature you don't control.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(confrontation);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var mine = game.Create(alice, TestCards.Creature("Fight Mine Test", 2, 2), Zone.Battlefield);
        var theirs = game.Create(bob, TestCards.Creature("Fight Theirs Test", 2, 2), Zone.Battlefield);

        game.CastSpell(
            alice,
            TestCards.PutInHand(game, alice, confrontation),
            [Target.ToPermanent(mine), Target.ToPermanent(theirs)]);

        Settle(game);

        Assert.DoesNotContain(theirs, game.State.Battlefield);
        Assert.Contains(mine, game.State.Battlefield);
    }

    /// <summary>
    /// "~ deals 2 damage to that creature" — the pronoun as the object of a burn.
    /// </summary>
    /// <remarks>
    /// Destroy, exile and tap all took the pronoun through the shared object reader and damage
    /// never did, on thirty-six cards. Only the reading that resolves to a target the card has
    /// already chosen is taken: <c>DealDamage</c> carries a target index and nothing else, so a
    /// pronoun meaning the <em>trigger's</em> subject has nowhere to go, and answering it with
    /// the last target is the mistake that once made "whenever ~ blocks a creature, destroy that
    /// creature" destroy the blocker.
    /// </remarks>
    [Fact]
    public void Damage_can_name_the_permanent_the_sentence_before_it_chose()
    {
        var jolt = Card(
            "Pronoun Burn Test",
            "Tap target creature. ~ deals 2 damage to that creature.");

        var compiled = CardCompiler.Compile(jolt);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var ox = game.Create(bob, TestCards.Creature("Pronoun Burn Ox Test", 3, 3), Zone.Battlefield);

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, jolt), [Target.ToPermanent(ox)]);

        Settle(game);

        // The same permanent took both halves of the sentence.
        Assert.True(game.State.GetObject(ox).Permanent!.IsTapped);
        Assert.Equal(2, game.State.GetObject(ox).Permanent!.DamageMarked);
    }

    /// <summary>
    /// "Gain control of that creature until end of turn" — the theft aimed at a pronoun.
    /// </summary>
    [Fact]
    public void A_theft_can_name_the_permanent_the_sentence_before_it_chose()
    {
        var press = Card(
            "Pronoun Theft Test",
            "Tap target creature. Gain control of that creature until end of turn.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(press);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var ox = game.Create(bob, TestCards.Creature("Pronoun Theft Ox Test", 3, 3), Zone.Battlefield);

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, press), [Target.ToPermanent(ox)]);

        Settle(game);

        Assert.Equal(
            alice,
            Characteristics.Of(game.State, Pool, game.State.GetObject(ox)).ControllerId);
    }

    /// <summary>
    /// "Its controller loses 1 life for each creature you control" — the counted form.
    /// </summary>
    /// <remarks>
    /// The clause already read with a printed number; what it could not do was take the count
    /// tail every other life verb has. Both effects behind it carry an <c>Amount</c>, so asking
    /// for the tail was the whole of the work.
    /// </remarks>
    [Fact]
    public void A_targets_controller_loses_life_once_for_each_thing_counted()
    {
        var downfall = Card(
            "Counted Downfall Test",
            "Destroy target creature. Its controller loses 1 life for each creature you control.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(downfall);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, TestCards.Creature("Downfall Bear One Test", 2, 2), Zone.Battlefield);
        game.Create(alice, TestCards.Creature("Downfall Bear Two Test", 2, 2), Zone.Battlefield);
        var ox = game.Create(bob, TestCards.Creature("Downfall Ox Test", 3, 3), Zone.Battlefield);

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, downfall), [Target.ToPermanent(ox)]);

        Settle(game);

        Assert.DoesNotContain(ox, game.State.Battlefield);

        // Two, counted off Alice's board rather than off the creature that just died.
        Assert.Equal(18, game.State.GetPlayer(bob).Life);
    }

    /// <summary>
    /// "When ~ dies, you may have it deal 1 damage to any target." — Goblin Arsonist.
    /// </summary>
    /// <remarks>
    /// The optional ping, spelt the way the cards print it. "Have it deal" is "it deals" with the
    /// verb in the bare infinitive, so the sentence is rewritten and handed back to the parser
    /// rather than given an effect of its own: every damage wording already read arrives here
    /// working, and fourteen distinct ones across the family were checked.
    /// <para>
    /// The decline half is what makes it a test. A reader that dropped the two words would deal
    /// the damage every time and pass any assertion written only about accepting — and a trigger
    /// that always pings is a different card from one that offers to.
    /// </para>
    /// </remarks>
    [Theory]
    [InlineData(true, 19)]
    [InlineData(false, 20)]
    public void An_optional_ping_is_only_dealt_when_the_offer_is_taken(bool accept, int life)
    {
        var arsonist = Card(
            "Optional Ping Test",
            "When ~ dies, you may have it deal 1 damage to any target.",
            CardType.Creature,
            power: 1,
            toughness: 1);

        var compiled = CardCompiler.Compile(arsonist);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var goblin = game.Create(alice, arsonist, Zone.Battlefield);

        game.MarkDamage(goblin, 1);

        // The target is chosen as the trigger goes on the stack (CR 603.3d); the offer is made
        // when it resolves, which is why the two questions arrive in this order.
        TestCards.PassUntil(game, () => game.State.Choice is not null);

        var aiming = game.State.Choice!;
        Assert.Equal(ChoiceKind.ChooseTriggerTargets, aiming.Kind);
        game.Choose(alice, [aiming.Options!.Single(o => o.Id == $"player:{bob:N}").Id]);

        // By hand rather than through Settle, which answers every question with its first option
        // — and which of the two answers is taken is the whole of what this test is about.
        for (var guard = 0; guard < 20 && game.State.Choice is null; guard++)
        {
            if (game.State.Priority.Holder is not { } holder)
                break;

            game.PassPriority(holder);
        }

        var offer = game.State.Choice;
        Assert.NotNull(offer);
        Assert.Equal(ChoiceKind.OptionalPayment, offer.Kind);

        var no = offer.Options.Single(o => o.Label.Contains(
            "decline", StringComparison.OrdinalIgnoreCase));

        game.Choose(alice, [accept ? offer.Options.First(o => o.Id != no.Id).Id : no.Id]);
        Settle(game);

        Assert.Equal(life, game.State.GetPlayer(bob).Life);
    }

    /// <summary>
    /// "Whenever a Beast you control enters, you may have it deal 4 damage to target opponent
    /// or planeswalker." — Aether Charge, and the card the rewrite has to refuse.
    /// </summary>
    /// <remarks>
    /// "It" is the Beast, not the enchantment that said so, and the source of damage is not a
    /// detail: lifelink, deathtouch and every "whenever this deals damage" trigger read it. The
    /// engine's damage effects deal from the permanent the ability is on, so the only reading
    /// available here would attribute the ping to the wrong permanent — and an unread line is
    /// better than a card that plays as a different one.
    /// <para>
    /// The refusal is decided by whether the trigger's own event carries an object, which is the
    /// same allow-list "that creature" is resolved through. It needed the flag to be carried into
    /// the offer's branches, where it had been dropped: an offer inside a trigger is still inside
    /// that trigger, and until this the branches were read as though there were no trigger at all.
    /// </para>
    /// </remarks>
    [Fact]
    public void An_optional_ping_is_refused_when_it_names_the_triggering_permanent()
    {
        var charge = Card(
            "Optional Ping Refusal Test",
            "Whenever a Beast you control enters, you may have it deal 4 damage to target "
                + "opponent or planeswalker.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(charge);

        Assert.False(compiled.IsComplete);
        Assert.Contains(
            compiled.Unhandled,
            line => line.Contains("you may have it deal", StringComparison.Ordinal));

        // The same sentence about the source reads, which is what makes the refusal a decision
        // about the pronoun rather than about the shape.
        var forerunner = Card(
            "Optional Ping Source Test",
            "Whenever a Beast you control enters, you may have ~ deal 4 damage to target "
                + "opponent or planeswalker.",
            CardType.Enchantment);

        Assert.True(
            CardCompiler.Compile(forerunner).IsComplete,
            string.Join(" | ", CardCompiler.Compile(forerunner).Unhandled));
    }

    /// <summary>
    /// "When ~ attacks or blocks, sacrifice it at end of combat." — Mardu Blazebringer.
    /// </summary>
    /// <remarks>
    /// A delayed triggered ability (CR 603.7) waiting for the end of combat step (CR 511.1)
    /// rather than for an end step. The engine already fires delayed abilities as a step is
    /// entered and already knows how to sacrifice the permanent that promised it, so the whole of
    /// this is a moment the grammar could not name.
    /// <para>
    /// The assertion that it is still on the battlefield when combat damage is dealt is the one
    /// that matters. Reading the tail as "sacrifice it now" also compiles, also plays, and takes
    /// the attacker off the board before it has hit anything.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_delayed_sacrifice_waits_for_the_end_of_combat()
    {
        var brute = Card(
            "End Of Combat Sacrifice Test",
            "When ~ attacks or blocks, sacrifice it at end of combat.",
            CardType.Creature,
            power: 5,
            toughness: 1);

        var compiled = CardCompiler.Compile(brute);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var ogre = game.Create(alice, brute, Zone.Battlefield);

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [ogre] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.CombatDamage);

        // Still attacking when the damage is dealt: the sacrifice is owed, not done.
        Assert.Contains(ogre, game.State.Battlefield);

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.PostcombatMain);
        Settle(game);

        // Five damage got through, and only then did it go. The card in the graveyard is a new
        // object (CR 400.7), so it is found by what it is rather than by the id it used to have.
        Assert.Equal(15, game.State.GetPlayer(bob).Life);
        Assert.DoesNotContain(ogre, game.State.Battlefield);
        Assert.Contains(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == brute.Name);
    }

    /// <summary>
    /// "When ~ attacks or blocks, return it to its owner's hand at end of combat." — Phantom
    /// Whelp.
    /// </summary>
    /// <remarks>
    /// The same delay with a different verb, and the reason the verb is mapped rather than passed
    /// through: the engine's delayed vocabulary spells the bounce "return-to-hand", and anything
    /// it does not recognise falls to its default arm — which is a sacrifice. Handing it the
    /// printed word would have put the creature in the graveyard, which is a card nobody would
    /// play twice.
    /// </remarks>
    [Fact]
    public void A_delayed_bounce_puts_the_attacker_in_hand_and_not_in_the_graveyard()
    {
        var whelp = Card(
            "End Of Combat Bounce Test",
            "When ~ attacks or blocks, return it to its owner's hand at end of combat.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var compiled = CardCompiler.Compile(whelp);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var pup = game.Create(alice, whelp, Zone.Battlefield);

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [pup] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.PostcombatMain);
        Settle(game);

        // A card that changes zone becomes a new object (CR 400.7), so both halves are asked of
        // what is there rather than of the id that attacked.
        Assert.DoesNotContain(pup, game.State.Battlefield);
        Assert.DoesNotContain(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == whelp.Name);
        Assert.Contains(
            game.State.GetPlayer(alice).Hand,
            id => game.State.GetObject(id).Card.Name == whelp.Name);
    }

    /// <summary>
    /// "Put a +4/+4 counter on each creature you control" — the counter the engine cannot put.
    /// </summary>
    /// <remarks>
    /// The group counter reader took the sign of the printed counter and nothing else, so every
    /// power/toughness counter that was not +1/+1 or -1/-1 compiled to the +1/+1 one — a
    /// definition byte-identical to the card that really does print +1/+1. It read as complete
    /// and did a quarter of what it said.
    /// <para>
    /// CR 122.1a is what makes it wrong rather than merely approximate: a +X/+Y counter adds X to
    /// power and Y to toughness, for any X and Y. This engine works power and toughness out from
    /// exactly two counter names, so there is no honest way to put a +4/+4 counter yet — keeping
    /// it under its printed name would put a counter on the permanent, write it to the log, and
    /// change no characteristic at all. Refusing is the only reading that does not lie.
    /// </para>
    /// <para>
    /// Latent when it was found — nine corpus cards print such a counter and all nine are
    /// incomplete for other reasons — which is exactly why it is worth a test: the day one of
    /// them is finished, nothing else would have noticed.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_group_counter_the_engine_cannot_model_is_refused_rather_than_shrunk()
    {
        var chorus = Card(
            "Group Counter Refusal Test",
            "When ~ enters, put a +4/+4 counter on each creature you control.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var compiled = CardCompiler.Compile(chorus);

        Assert.False(compiled.IsComplete);
        Assert.Contains(
            compiled.Unhandled,
            line => line.Contains("+4/+4 counter on each creature", StringComparison.Ordinal));

        // The same sentence with the counter the engine does model still reads, and still plays:
        // a refusal that also broke the working sibling would pass the assertion above.
        var anthem = Card(
            "Group Counter Sibling Test",
            "When ~ enters, put a +1/+1 counter on each creature you control.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var works = CardCompiler.Compile(anthem);
        Assert.True(works.IsComplete, string.Join(" | ", works.Unhandled));

        var (game, alice, _) = InMainPhase();
        var bear = game.Create(alice, TestCards.Creature("Group Counter Bear Test", 2, 2), Zone.Battlefield);

        game.Create(alice, anthem, Zone.Battlefield);
        Settle(game);

        Assert.Equal(
            1,
            game.State.GetObject(bear).Permanent!.Counters
                .GetValueOrDefault(CounterKinds.PlusOnePlusOne));

        Assert.Equal(3, Characteristics.Of(game.State, Pool, game.State.GetObject(bear)).Power);
    }

    /// <summary>
    /// "Put a +2/+2 counter on target creature" — the same refusal on the targeted verb.
    /// </summary>
    /// <remarks>
    /// One vocabulary, so the refusal is made once where the printed counter is named and every
    /// verb that puts one inherits it. The targeted form failed differently and just as quietly:
    /// the counter kept its printed name, so the definition did differ from the +1/+1 one — a
    /// fingerprint would not have flagged it — and the permanent ended up holding a counter
    /// called "+2/+2" that nothing in the layers reads.
    /// <para>
    /// A named counter — charge, depletion, storage — is untouched by this, and the assertion
    /// below is what keeps the refusal from swallowing them: the engine has never cared which
    /// counter names exist, only which two change power and toughness.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_targeted_counter_the_engine_cannot_model_is_refused_but_a_named_one_is_not()
    {
        var swell = Card(
            "Targeted Counter Refusal Test",
            "Put a +2/+2 counter on target creature.",
            CardType.Instant);

        Assert.False(CardCompiler.Compile(swell).IsComplete);

        var charging = Card(
            "Targeted Named Counter Test",
            "Put a charge counter on target artifact.",
            CardType.Instant);

        var works = CardCompiler.Compile(charging);
        Assert.True(works.IsComplete, string.Join(" | ", works.Unhandled));

        var (game, alice, _) = InMainPhase();
        var relic = game.Create(
            alice,
            Card("Named Counter Relic Test", string.Empty, CardType.Artifact),
            Zone.Battlefield);

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, charging), [Target.ToPermanent(relic)]);

        Settle(game);

        Assert.Equal(1, game.State.GetObject(relic).Permanent!.Counters.GetValueOrDefault("charge"));
    }

    // ---- Endure: counters or a Spirit, whichever you pick (CR 701.63a) -------

    /// <summary>
    /// "When ~ enters, it endures 2."
    /// </summary>
    /// <remarks>
    /// CR 701.63a: the permanent's controller "creates an N/N white Spirit creature token unless
    /// they put N +1/+1 counters on that permanent" — one free choice with two outcomes, which is
    /// the offer machinery with an empty cost. Both branches are played, because an offer whose
    /// second branch does nothing looks exactly like one that works from the first branch alone.
    /// </remarks>
    [Fact]
    public void An_endure_puts_the_counters_on_when_that_is_what_its_controller_picks()
    {
        var nurturer = Card(
            "Endure Counters Test",
            "When ~ enters, it endures 2.",
            CardType.Creature,
            power: 1,
            toughness: 1);

        var compiled = CardCompiler.Compile(nurturer);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var druid = game.Create(alice, nurturer, Zone.Battlefield);

        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.OptionalPayment });

        var asked = game.State.Choice!;
        game.Choose(
            asked.PlayerId,
            [asked.Options.First(o => o.Label.StartsWith("Put", StringComparison.Ordinal)).Id]);

        Settle(game);

        Assert.Equal(
            2,
            game.State.GetObject(druid).Permanent!.Counters
                .GetValueOrDefault(CounterKinds.PlusOnePlusOne));

        // And no Spirit: the two outcomes are alternatives, not a pair.
        Assert.DoesNotContain(
            game.State.Battlefield,
            id => game.State.GetObject(id).Card.Name == "Spirit");
    }

    /// <summary>The other branch of the same offer — the Spirit, and no counters.</summary>
    /// <remarks>
    /// The token is built by running "create a 2/2 white Spirit creature token" back through the
    /// token reader rather than assembling a second definition, so the Spirit endure makes is the
    /// same object every other card's Spirit is. Its size and colour are asserted here because a
    /// token of the wrong size compiles perfectly.
    /// </remarks>
    [Fact]
    public void An_endure_makes_a_white_spirit_of_its_own_size_when_the_counters_are_declined()
    {
        var vanguard = Card(
            "Endure Spirit Test",
            "When ~ enters, it endures 2.",
            CardType.Creature,
            power: 1,
            toughness: 1);

        var (game, alice, _) = InMainPhase();
        var soldier = game.Create(alice, vanguard, Zone.Battlefield);

        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.OptionalPayment });

        var asked = game.State.Choice!;
        game.Choose(
            asked.PlayerId,
            [asked.Options.First(o => o.Label.StartsWith("Create", StringComparison.Ordinal)).Id]);

        Settle(game);

        Assert.Equal(
            0,
            game.State.GetObject(soldier).Permanent!.Counters
                .GetValueOrDefault(CounterKinds.PlusOnePlusOne));

        var spirit = game.State.Battlefield
            .Select(game.State.GetObject)
            .Single(o => o.Card.Name == "Spirit");

        Assert.Equal(alice, spirit.ControllerId);
        Assert.Equal(2, spirit.Card.Power);
        Assert.Equal(2, spirit.Card.Toughness);
        Assert.Contains(ManaColor.White, spirit.Card.Colors);
    }

    /// <summary>"~ endures X" is refused, because the Spirit has no size until X does.</summary>
    /// <remarks>
    /// The token is a card definition and its power and toughness are part of its identity, so it
    /// cannot be named before X is known. Three corpus cards spell endure that way and they stay
    /// unread rather than being given a Spirit of some guessed size.
    /// </remarks>
    [Fact]
    public void An_endure_whose_size_is_a_variable_is_refused()
    {
        var initiate = Card(
            "Endure Variable Test",
            "{X}{B}, {T}: ~ endures X.",
            CardType.Creature,
            power: 1,
            toughness: 1);

        Assert.False(CardCompiler.Compile(initiate).IsComplete);
    }

    // ---- "Otherwise": the else branch of a bare conditional (CR 608.2c) ------

    /// <summary>
    /// "If you control a Demon, you gain 2 life. Otherwise, you lose 1 life."
    /// </summary>
    /// <remarks>
    /// Both ways round in one test, because an else branch that never runs and a then branch that
    /// always runs are the two ways this can be wrong and each looks correct from the other side.
    /// </remarks>
    [Fact]
    public void An_otherwise_branch_runs_exactly_when_the_condition_does_not()
    {
        var annex = Card(
            "Otherwise Branch Test",
            "If you control an artifact, you gain 3 life. Otherwise, you lose 1 life.",
            CardType.Instant);

        var compiled = CardCompiler.Compile(annex);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        game.Create(
            alice,
            Card("Otherwise Relic Test", string.Empty, CardType.Artifact),
            Zone.Battlefield);

        var before = game.State.GetPlayer(alice).Life;
        game.CastSpell(alice, TestCards.PutInHand(game, alice, annex));
        Settle(game);

        Assert.Equal(before + 3, game.State.GetPlayer(alice).Life);

        // The same card with the condition unmet takes the other branch, and only the other one.
        var (second, carol, _) = InMainPhase();
        var start = second.State.GetPlayer(carol).Life;

        second.CastSpell(carol, TestCards.PutInHand(second, carol, annex));
        Settle(second);

        Assert.Equal(start - 1, second.State.GetPlayer(carol).Life);
    }

    /// <summary>An "Otherwise" with no question in front of it is not read.</summary>
    /// <remarks>
    /// The word only means anything as the second half of a conditional. Read on its own it would
    /// compile into an instruction that always happens, which is a strictly different card — so
    /// the pairing is what admits it, and a lone else branch leaves the line unread.
    /// </remarks>
    [Fact]
    public void An_otherwise_with_no_conditional_in_front_of_it_is_unread()
    {
        var orphan = Card(
            "Otherwise Orphan Test",
            "Draw a card. Otherwise, you gain 2 life.",
            CardType.Instant);

        Assert.False(CardCompiler.Compile(orphan).IsComplete);
    }

    /// <summary>An else branch may not choose a target of its own (CR 601.2c).</summary>
    /// <remarks>
    /// Targets are chosen and checked as the spell is cast, so a branch that will not run would
    /// still make the card uncastable for want of something to aim it at. No corpus card is
    /// written that way; the guard costs nothing and stops the reader inventing a requirement the
    /// printed card does not have. The "if" half may target, as it always could — what is refused
    /// is the second target, so the contrast is asserted rather than assumed.
    /// </remarks>
    [Fact]
    public void An_otherwise_branch_that_chooses_its_own_target_is_refused()
    {
        var both = Card(
            "Otherwise Two Targets Test",
            "If you control an artifact, destroy target creature. "
                + "Otherwise, destroy target artifact.",
            CardType.Instant);

        Assert.False(CardCompiler.Compile(both).IsComplete);

        var one = Card(
            "Otherwise One Target Test",
            "Destroy target creature. If you control an artifact, you gain 3 life. "
                + "Otherwise, you lose 1 life.",
            CardType.Instant);

        var reads = CardCompiler.Compile(one);
        Assert.True(reads.IsComplete, string.Join(" | ", reads.Unhandled));
        Assert.Single(reads.Spell!.Targets);
    }

    // ---- "It deals damage equal to its power" (CR 613.1) --------------------

    /// <summary>
    /// "When ~ enters, it deals damage equal to its power to each opponent."
    /// </summary>
    /// <remarks>
    /// The amount is the source's power <em>as the ability resolves</em>, not as the card was
    /// printed, so an anthem on the table makes the damage larger. A 2/2 under a +1/+1 anthem
    /// dealing 2 would pass every check a reviewer could run except this one.
    /// </remarks>
    [Fact]
    public void A_pronoun_deals_the_sources_power_counting_what_the_layers_add()
    {
        var redcap = Card(
            "Power Damage Test",
            "When ~ enters, it deals damage equal to its power to each opponent.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var compiled = CardCompiler.Compile(redcap);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        game.Create(
            alice,
            Card(
                "Power Damage Anthem Test",
                "Creatures you control get +1/+1.",
                CardType.Enchantment),
            Zone.Battlefield);

        var before = game.State.GetPlayer(bob).Life;
        var mine = game.State.GetPlayer(alice).Life;

        game.Create(alice, redcap, Zone.Battlefield);
        Settle(game);

        // Three, not the printed two - and to the opponent only.
        Assert.Equal(before - 3, game.State.GetPlayer(bob).Life);
        Assert.Equal(mine, game.State.GetPlayer(alice).Life);
    }

    /// <summary>
    /// The same sentence where "it" cannot mean the source is left unread.
    /// </summary>
    /// <remarks>
    /// Both the damage's source and the power measured are the permanent with the ability, so the
    /// pronoun is only honoured where it can mean that permanent and nothing else.
    /// <para>
    /// Fiendlash is the card that proves it matters: "whenever equipped creature is dealt damage,
    /// it deals damage equal to its power to target player or planeswalker" compiled with the
    /// <em>Equipment</em> as the damage source and the Equipment's power as the amount, which is
    /// no power at all — a card that read as complete and dealt nothing. An Aura or Equipment's
    /// trigger is about its host, never about itself, so those conditions now say so.
    /// </para>
    /// <para>
    /// The other refusal is a pronoun after a target: "Tap target creature. It deals damage equal
    /// to its power…" means the tapped creature, and this effect could only ever deal the
    /// source's power from the source.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_pronoun_that_cannot_mean_the_source_leaves_the_damage_unread()
    {
        var lash = Card(
            "Power Damage Equipment Test",
            "Whenever equipped creature is dealt damage, it deals damage equal to its power to "
                + "target player or planeswalker.\nEquip {3}",
            CardType.Artifact,
            subtypes: "Equipment");

        Assert.False(CardCompiler.Compile(lash).IsComplete);

        var afterTarget = Card(
            "Power Damage After Target Test",
            "Tap target creature. It deals damage equal to its power to any target.",
            CardType.Instant);

        Assert.False(CardCompiler.Compile(afterTarget).IsComplete);

        // The shape it is being kept apart from: the source naming itself, which still reads.
        var berserker = Card(
            "Power Damage Self Test",
            "When ~ dies, it deals damage equal to its power to any target.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var reads = CardCompiler.Compile(berserker);
        Assert.True(reads.IsComplete, string.Join(" | ", reads.Unhandled));
    }

    // ---- A trigger about an attached permanent names it (CR 603.2) ----------

    /// <summary>
    /// "When enchanted creature is dealt damage, destroy it."
    /// </summary>
    /// <remarks>
    /// An Aura's trigger is about the permanent it is attached to (CR 603.2), and the event it
    /// fires on carries that permanent's id — so "it" is the host and never the Aura, which is a
    /// thing the reader now says rather than assumes. The test attacks the
    /// question from the side that would hide a mistake: a second creature is on the board and
    /// has to survive, because a reader that destroyed whatever it found first would look right
    /// with only one creature in play.
    /// </remarks>
    [Fact]
    public void A_trigger_about_an_enchanted_creature_names_it_for_the_pronoun_that_follows()
    {
        var wound = Card(
            "Mortal Referent Test",
            "Enchant creature\nWhen enchanted creature is dealt damage, destroy it.",
            CardType.Enchantment,
            subtypes: "Aura");

        var compiled = CardCompiler.Compile(wound);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var cursed = game.Create(bob, TestCards.Creature("Referent Ogre Test", 4, 4), Zone.Battlefield);
        var bystander = game.Create(
            bob, TestCards.Creature("Referent Bystander Test", 4, 4), Zone.Battlefield);

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, wound), [Target.ToPermanent(cursed)]);

        Settle(game);

        var ping = Card("Referent Ping Test", "~ deals 1 damage to any target.", CardType.Instant);
        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, ping), [Target.ToPermanent(cursed)]);

        Settle(game);

        // One point of damage is nowhere near lethal on a 4/4: only the trigger can kill it.
        Assert.DoesNotContain(cursed, game.State.Battlefield);
        Assert.Contains(bystander, game.State.Battlefield);
    }

    /// <summary>
    /// "When enchanted permanent becomes untapped, destroy it" stays unread.
    /// </summary>
    /// <remarks>
    /// Untapping looks like its twin and is not: several permanents untap at once and the event
    /// carries a set of ids, so nothing can answer "which one was this about". Admitting it would
    /// compile a trigger that resolves and destroys nothing — the tapping form beside it is
    /// asserted here too, so the difference is the event and not the pattern.
    /// </remarks>
    [Fact]
    public void An_untap_trigger_names_no_object_and_its_pronoun_is_refused()
    {
        var onUntap = Card(
            "Untap Referent Test",
            "Enchant permanent\nWhen enchanted permanent becomes untapped, destroy it.",
            CardType.Enchantment,
            subtypes: "Aura");

        Assert.False(CardCompiler.Compile(onUntap).IsComplete);

        var onTap = Card(
            "Tap Referent Test",
            "Enchant land\nWhen enchanted land becomes tapped, destroy it.",
            CardType.Enchantment,
            subtypes: "Aura");

        var reads = CardCompiler.Compile(onTap);
        Assert.True(reads.IsComplete, string.Join(" | ", reads.Unhandled));
    }

    // ---- Counted amounts: what the number is counting ------------------------

    /// <summary>
    /// "You gain 2 life for each creature that died this turn" (CR 700.4).
    /// </summary>
    /// <remarks>
    /// Nineteen corpus cards multiply by the graveyard's intake rather than by the board, and
    /// the two are different numbers on every turn anything has died. The survivor on the
    /// battlefield is what separates them: a reader that counted creatures would say one.
    /// <para>
    /// Game-wide and not "yours", because none of those cards names a player — CR 700.4 defines
    /// "dies" and says nothing about whose creature it was.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_count_of_creatures_that_died_this_turn_counts_the_deaths()
    {
        var wake = Card("Died Count Test", "You gain 2 life for each creature that died this turn.");
        var shrink = Card("Died Shrink Test", "Target creature gets -3/-3 until end of turn.");

        var compiled = CardCompiler.Compile(wake);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var first = game.Create(bob, TestCards.Creature("Died One Test", 2, 2), Zone.Battlefield);
        var second = game.Create(bob, TestCards.Creature("Died Two Test", 2, 2), Zone.Battlefield);
        game.Create(bob, TestCards.Creature("Died Survivor Test", 4, 4), Zone.Battlefield);

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, shrink), [Target.ToPermanent(first)]);
        Settle(game);

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, shrink), [Target.ToPermanent(second)]);
        Settle(game);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, wake));
        Settle(game);

        // Two died and one is still standing. 24 is the deaths, 22 would be the board, and 20 is
        // the answer a count that came out at nought gives — which is the failure this whole
        // vocabulary is written to avoid, because the card compiles either way.
        Assert.Equal(24, game.State.GetPlayer(alice).Life);
    }

    /// <summary>
    /// "You gain 2 life for each creature in your party" (CR 700.8).
    /// </summary>
    /// <remarks>
    /// A party is up to one Cleric, one Rogue, one Warrior and one Wizard, so it is not a count
    /// of creatures at all — eight Clerics are a party of one.
    /// <para>
    /// CR 700.8b is what the board here is built for: a creature that could fill two of the roles
    /// fills only one, and the number is taken the way that gives the highest result. Assigned in
    /// board order, the Cleric Rogue takes the Cleric slot and the plain Cleric is left with
    /// nowhere to go — a party of one, where the rules say two. So the reader is a matching and
    /// not a first-come assignment, and 22 rather than 24 is what the greedy walk would leave.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_party_is_counted_as_the_assignment_that_fills_the_most_roles()
    {
        var feast = Card("Party Feast Test", "You gain 2 life for each creature in your party.");

        var compiled = CardCompiler.Compile(feast);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();

        game.Create(
            alice,
            Card(
                "Party Duelist Test", string.Empty, CardType.Creature,
                power: 2, toughness: 2, keywords: KeywordAbility.None, "Cleric", "Rogue"),
            Zone.Battlefield);

        game.Create(
            alice,
            Card(
                "Party Healer Test", string.Empty, CardType.Creature,
                power: 1, toughness: 1, keywords: KeywordAbility.None, "Cleric"),
            Zone.Battlefield);

        game.Create(
            alice,
            Card(
                "Party Ox Test", string.Empty, CardType.Creature,
                power: 3, toughness: 3, keywords: KeywordAbility.None, "Ox"),
            Zone.Battlefield);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, feast));
        Settle(game);

        // Two roles filled from three creatures: 26 would be a count of creatures, 22 a greedy
        // assignment, 20 no count at all.
        Assert.Equal(24, game.State.GetPlayer(alice).Life);
    }

    /// <summary>
    /// "You gain 2 life for each experience counter you have" (CR 122.1).
    /// </summary>
    /// <remarks>
    /// A counter on the <em>player</em>, so the counter phrase beside it in the vocabulary cannot
    /// answer it: that one looks for "counters on" a permanent, and this has nothing to be on.
    /// Sixteen corpus cards read the total back this way.
    /// </remarks>
    [Fact]
    public void A_count_of_experience_counters_multiplies_by_what_the_player_has()
    {
        var rite = Card("Experience Count Rite Test", "You get an experience counter.");
        var feast = Card(
            "Experience Count Test", "You gain 2 life for each experience counter you have.");

        var compiled = CardCompiler.Compile(feast);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();

        game.CastSpell(alice, TestCards.PutInHand(game, alice, rite));
        Settle(game);
        game.CastSpell(alice, TestCards.PutInHand(game, alice, rite));
        Settle(game);

        Assert.Equal(2, game.State.GetPlayer(alice).ExperienceCounters);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, feast));
        Settle(game);

        // Two counters at two life each. 20 is the count coming out at nought, which is what a
        // card that reads the phrase and cannot answer it would leave behind.
        Assert.Equal(24, game.State.GetPlayer(alice).Life);
    }

    /// <summary>
    /// "You gain 2 life for each card you've drawn this turn" (CR 121.1).
    /// </summary>
    /// <remarks>
    /// The player already keeps the tally, because a draw is an event and the fold counts them.
    /// Nothing here has to remember which cards they were — a card drawn and then discarded still
    /// counts, which is why the hand is the wrong pile to look in and this is not that count.
    /// </remarks>
    [Fact]
    public void A_count_of_cards_drawn_this_turn_counts_the_draws_and_not_the_hand()
    {
        var ledger = Card(
            "Drawn Ledger Test", "You gain 2 life for each card you've drawn this turn.");

        var study = Card("Drawn Study Test", "Draw two cards.");

        var compiled = CardCompiler.Compile(ledger);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();

        game.CastSpell(alice, TestCards.PutInHand(game, alice, study));
        Settle(game);

        var drawn = game.State.GetPlayer(alice).CardsDrawnThisTurn;
        Assert.Equal(2, drawn);

        // The hand is a different number from the draws by now — the two spells put into it
        // by hand were never drawn — so a reader that counted the hand cannot pass this.
        Assert.NotEqual(drawn, game.State.GetPlayer(alice).Hand.Count);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, ledger));
        Settle(game);

        Assert.Equal(24, game.State.GetPlayer(alice).Life);
    }

    /// <summary>
    /// "You gain 3 life for each creature attacking you" — Blessed Reversal (CR 506.3).
    /// </summary>
    /// <remarks>
    /// Only a player, a planeswalker or a battle can be attacked, and they are three different
    /// things to attack: a creature aimed at your planeswalker is not attacking <em>you</em>, even
    /// though you are the defending player either way. The board here has one of each, so a reader
    /// that counted every attacker whose defending player is you would say nine rather than six.
    /// </remarks>
    [Fact]
    public void A_count_of_creatures_attacking_you_leaves_out_the_one_on_a_planeswalker()
    {
        var reversal = Card(
            "Attacking Count Test", "You gain 3 life for each creature attacking you.");

        var compiled = CardCompiler.Compile(reversal);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();

        var walker = game.Create(
            alice,
            new CardDefinition
            {
                OracleId = "oracle-attacking-count-walker",
                Name = "Attacking Count Walker Test",
                CardTypes = CardType.Planeswalker,
                StartingLoyalty = 5,
            },
            Zone.Battlefield);

        var one = game.Create(bob, TestCards.Creature("Attacking One Test", 1, 1), Zone.Battlefield);
        var two = game.Create(bob, TestCards.Creature("Attacking Two Test", 1, 1), Zone.Battlefield);
        var atWalker = game.Create(
            bob, TestCards.Creature("Attacking Walker Test", 1, 1), Zone.Battlefield);

        game.Create(bob, TestCards.Creature("Attacking Homebody Test", 1, 1), Zone.Battlefield);

        PassTo(game, 2, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            bob,
            new Dictionary<ObjectId, AttackTarget>
            {
                [one] = AttackTarget.Player(alice),
                [two] = AttackTarget.Player(alice),
                [atWalker] = AttackTarget.At(alice, walker),
            });

        // Blockers are not declared yet, so nobody has priority in the blockers step; the
        // attackers step gives it back to the active player first and then round to Alice.
        TestCards.PassUntil(game, () => game.State.Priority.Holder == alice);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, reversal));
        Settle(game);

        // Two are attacking Alice; the third is attacking her planeswalker and the fourth stayed
        // home. 26 is the two, 29 would be all three attackers, and 20 a count of nought.
        Assert.Equal(26, game.State.GetPlayer(alice).Life);
    }

    /// <summary>
    /// "Draw a card for each color among permanents you control" — Chromatic Orrery (CR 105.2).
    /// </summary>
    /// <remarks>
    /// The same count that "the number of colors among permanents you control" asks for, written
    /// singular — thirteen corpus cards say it that way and the pattern was plural-only, so the
    /// difference between the two was one letter. It counts <em>colours</em> and not permanents,
    /// which the colourless artifact on the board is there to prove: three permanents, two
    /// colours, and a reader counting the group would draw three.
    /// </remarks>
    [Fact]
    public void A_count_of_colours_among_permanents_counts_colours_and_not_permanents()
    {
        var orrery = Card(
            "Colour Draw Test", "Draw a card for each color among permanents you control.");

        var compiled = CardCompiler.Compile(orrery);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();

        game.Create(alice, Coloured("Colour Count White Test", ManaColor.White), Zone.Battlefield);
        game.Create(alice, Coloured("Colour Count Green Test", ManaColor.Green), Zone.Battlefield);
        game.Create(
            alice,
            Card("Colour Count Relic Test", string.Empty, CardType.Artifact),
            Zone.Battlefield);

        var before = game.State.GetPlayer(alice).Library.Count;

        game.CastSpell(alice, TestCards.PutInHand(game, alice, orrery));
        Settle(game);

        Assert.Equal(before - 2, game.State.GetPlayer(alice).Library.Count);
    }

    /// <summary>
    /// "Draw cards equal to the number of differently named lands you control" (CR 201.1).
    /// </summary>
    /// <remarks>
    /// Audience with Trostani and All-Fates Scroll ask this about tokens and about lands, and it
    /// is a count of names rather than of permanents — so the second Forest adds nothing. Three
    /// lands and two names: a reader that ignored the words in front would draw three.
    /// </remarks>
    [Fact]
    public void A_count_of_differently_named_permanents_counts_the_names()
    {
        var scroll = Card(
            "Named Count Test",
            "Draw cards equal to the number of differently named lands you control.");

        var compiled = CardCompiler.Compile(scroll);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();

        game.Create(alice, TestCards.BasicLand("Named Count Forest Test"), Zone.Battlefield);
        game.Create(alice, TestCards.BasicLand("Named Count Forest Test"), Zone.Battlefield);
        game.Create(alice, TestCards.BasicLand("Named Count Island Test"), Zone.Battlefield);

        var before = game.State.GetPlayer(alice).Library.Count;

        game.CastSpell(alice, TestCards.PutInHand(game, alice, scroll));
        Settle(game);

        Assert.Equal(before - 2, game.State.GetPlayer(alice).Library.Count);
    }

    /// <summary>
    /// "Target creature gets +1/+1 until end of turn for each basic land type among lands you
    /// control" - Power Armor, and a counted pump that is not counting permanents.
    /// </summary>
    /// <remarks>
    /// A pump whose size is not known until it applies carries its group phrase inside the
    /// generated effect's id, and the id is all the definition gets - so both ends have to read
    /// that phrase the same way. They now read it with the <em>same</em> function, which is what
    /// lets a count that is not a walk of the battlefield reach a pump at all: domain counts basic
    /// land types (CR 305.6), so five Forests are one and this board of three lands is two.
    /// <para>
    /// The counts that read "it" are refused at both ends instead, and deliberately: a floating
    /// effect made by a spell is handed a null source when characteristics are computed, so a
    /// pump counting "the +1/+1 counters on it" would have nothing to read and would quietly come
    /// out at nought on a card that compiled clean.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_counted_pump_can_count_something_that_is_not_a_group_of_permanents()
    {
        var armour = Card(
            "Domain Pump Test",
            "Target creature gets +1/+1 until end of turn for each basic land type among "
                + "lands you control.");

        var compiled = CardCompiler.Compile(armour);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();

        game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.Create(alice, TestCards.BasicLand("Island"), Zone.Battlefield);

        var bear = game.Create(
            alice, TestCards.Creature("Domain Pump Bear Test", 2, 2), Zone.Battlefield);

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, armour), [Target.ToPermanent(bear)]);

        Settle(game);

        // Three lands and two basic land types. 4/4 is the types, 5/5 would be the lands, and
        // 2/2 is the count coming out at nought on a card that compiled complete.
        Assert.Equal(4, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(bear)));
        Assert.Equal(4, Characteristics.ToughnessOf(game.State, Pool, game.State.GetObject(bear)));
    }

    /// <summary>
    /// "Target creature has base power and toughness 4/4 until end of turn" — layer 7b (CR 613.4b).
    /// </summary>
    /// <remarks>
    /// The counter is the whole test. A base size is <em>set</em> in sublayer 7b and a +1/+1
    /// counter modifies in 7c, so a 2/2 with a counter set to 4/4 is a 5/5. Read as a pump — the
    /// nearest reader that already existed, and the one a hurry would reach for — the same board
    /// would be a 7/7, and read as a plain overwrite it would be a 4/4. All three compile; only
    /// one of them is the printed card.
    /// <para>
    /// 61 corpus cards print the shape and none of them could be read, because "has" is a
    /// different verb from "becomes" and the animation grammar begins at the second.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_base_power_and_toughness_is_set_under_the_counters()
    {
        var shrink = Card(
            "Base Size Test",
            "Target creature has base power and toughness 4/4 until end of turn.");

        var compiled = CardCompiler.Compile(shrink);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var bear = game.Create(
            alice, TestCards.Creature("Base Size Bear Test", 2, 2), Zone.Battlefield);

        game.ChangeCounters(bear, CounterKinds.PlusOnePlusOne, 1);

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, shrink), [Target.ToPermanent(bear)]);
        Settle(game);

        // 4/4 set in 7b, then the counter in 7c. A pump would read 7/7; ignoring the counter, 4/4.
        Assert.Equal(5, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(bear)));
        Assert.Equal(5, Characteristics.ToughnessOf(game.State, Pool, game.State.GetObject(bear)));
    }

    /// <summary>
    /// The same setting said of the permanent whose ability it is, with a keyword beside it.
    /// </summary>
    /// <remarks>
    /// The self form is a separate reader for the reason every reader in this family is: the
    /// target grammar begins at a target phrase and the source is not a target. The duration is
    /// printed twice on this wording — once after the size and once after the keyword — which is
    /// why the pattern has two places to find it.
    /// </remarks>
    [Fact]
    public void A_base_size_on_the_source_arrives_with_its_keyword()
    {
        var mimic = Card(
            "Base Size Self Test",
            "{2}: ~ has base power and toughness 3/3 until end of turn and gains first strike "
                + "until end of turn.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var compiled = CardCompiler.Compile(mimic);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var creature = game.Create(alice, mimic, Zone.Battlefield);
        game.ChangeCounters(creature, CounterKinds.PlusOnePlusOne, 1);

        foreach (var _ in Enumerable.Range(0, 2))
        {
            var source = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
            game.ActivateAbility(alice, source, "mana");
        }

        game.ActivateAbility(alice, creature, "a");
        Settle(game);

        var now = Characteristics.Of(game.State, Pool, game.State.GetObject(creature));
        Assert.Equal(4, now.Power);
        Assert.True(now.Has(KeywordAbility.FirstStrike));

        // "Until end of turn" on both halves, so both are gone by the next turn: the printed 2/2
        // plus its counter, and no first strike.
        PassToMainPhaseOfTurn(game, 2);

        var later = Characteristics.Of(game.State, Pool, game.State.GetObject(creature));
        Assert.Equal(3, later.Power);
        Assert.False(later.Has(KeywordAbility.FirstStrike));
    }

    /// <summary>
    /// "~ becomes an artifact creature until end of turn" — the Vehicle wording (CR 205.1b).
    /// </summary>
    /// <remarks>
    /// The animation that prints no size, because the permanent it is printed on already has one.
    /// Both assertions are about what the reader must <em>not</em> do: setting a size here would
    /// overwrite the number the Vehicle is played for, and replacing the subtype would stop it
    /// being a Vehicle — which is the type its own crew ability and every "Vehicles you control"
    /// lord is looking for. CR 205.1b names this exact phrase and says every prior card type and
    /// subtype is kept.
    /// </remarks>
    [Fact]
    public void An_animation_with_no_size_leaves_the_vehicle_its_own()
    {
        var truck = Card(
            "Vehicle Animation Test",
            "{2}: ~ becomes an artifact creature until end of turn.",
            CardType.Artifact,
            power: 4,
            toughness: 4,
            subtypes: "Vehicle");

        var compiled = CardCompiler.Compile(truck);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var vehicle = game.Create(alice, truck, Zone.Battlefield);

        Assert.False(
            Characteristics.Of(game.State, Pool, game.State.GetObject(vehicle)).IsCreature);

        foreach (var _ in Enumerable.Range(0, 2))
        {
            var source = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
            game.ActivateAbility(alice, source, "mana");
        }

        game.ActivateAbility(alice, vehicle, "a");
        Settle(game);

        var now = Characteristics.Of(game.State, Pool, game.State.GetObject(vehicle));
        Assert.True(now.IsCreature);
        Assert.True(now.CardTypes.HasFlag(CardType.Artifact));

        // Its own printed size, not a size this reader invented.
        Assert.Equal(4, now.Power);
        Assert.Equal(4, now.Toughness);

        // Still a Vehicle: the phrase keeps every subtype (CR 205.1b).
        Assert.Contains("Vehicle", now.Subtypes, StringComparer.OrdinalIgnoreCase);
    }

    /// <summary>
    /// "In addition to its other types" adds the type rather than replacing it (CR 205.1b).
    /// </summary>
    /// <remarks>
    /// The two halves of CR 205.1 are one phrase apart and do opposite things. Without the words,
    /// 205.1a replaces the permanent's subtypes from the same set; with them, 205.1b keeps every
    /// one. A Vampire told to become a Demon "in addition to its other types" is both, and reading
    /// it as the replacement takes away the type the rest of the board is counting — on a card
    /// that says in print that it does not.
    /// <para>
    /// 20 corpus cards print this shape with a duration on it. The ones without are refused: the
    /// effect built here ends in the cleanup step, and a permanent type change is a different card.
    /// </para>
    /// </remarks>
    [Fact]
    public void An_added_type_keeps_the_one_the_permanent_had()
    {
        var rite = Card(
            "Added Type Test",
            "{2}: Target creature becomes a Demon in addition to its other types until end of turn.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(rite);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        // The same sentence with no duration is a permanent type change, which this engine cannot
        // express - so it is refused rather than quietly undone in the cleanup step.
        var forGood = Card(
            "Added Type Forever Test",
            "{2}: Target creature becomes a Demon in addition to its other types.",
            CardType.Enchantment);

        Assert.False(CardCompiler.Compile(forGood).IsComplete);

        var (game, alice, _) = InMainPhase();
        var shrine = game.Create(alice, rite, Zone.Battlefield);

        var vampire = new CardDefinition
        {
            OracleId = "oracle-added-type-vampire-test",
            Name = "Added Type Vampire Test",
            CardTypes = CardType.Creature,
            Subtypes = ["Vampire"],
            Power = 2,
            Toughness = 2,
        };

        var biter = game.Create(alice, vampire, Zone.Battlefield);

        foreach (var _ in Enumerable.Range(0, 2))
        {
            var source = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
            game.ActivateAbility(alice, source, "mana");
        }

        game.ActivateAbility(alice, shrine, "a", [Target.ToPermanent(biter)]);
        Settle(game);

        var now = Characteristics.Of(game.State, Pool, game.State.GetObject(biter));
        Assert.Contains("Demon", now.Subtypes, StringComparer.OrdinalIgnoreCase);
        Assert.Contains("Vampire", now.Subtypes, StringComparer.OrdinalIgnoreCase);
    }

    /// <summary>
    /// The same phrase on a sized animation — "a 4/4 Illusion creature in addition to its other
    /// types until end of turn" (CR 205.1b).
    /// </summary>
    /// <remarks>
    /// 17 corpus cards print the tail on an animation that also names a size, and every one of
    /// them was lost twice over: the keyword clause before it is written <c>[a-z ,]+?</c>, so it
    /// swallowed "haste in addition to its other types", handed that to the keyword table, and the
    /// refusal took the whole sentence down. The phrase is now its own group, which is what lets
    /// the two readings be told apart at all.
    /// </remarks>
    [Fact]
    public void A_sized_animation_can_add_its_type_instead_of_replacing_it()
    {
        var glaze = Card(
            "Sized Addition Test",
            "{2}: ~ becomes a 4/4 Illusion creature with flying in addition to its other types "
                + "until end of turn.",
            CardType.Artifact,
            subtypes: "Vehicle");

        var compiled = CardCompiler.Compile(glaze);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var relic = game.Create(alice, glaze, Zone.Battlefield);

        foreach (var _ in Enumerable.Range(0, 2))
        {
            var source = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
            game.ActivateAbility(alice, source, "mana");
        }

        game.ActivateAbility(alice, relic, "a");
        Settle(game);

        var now = Characteristics.Of(game.State, Pool, game.State.GetObject(relic));

        Assert.Equal(4, now.Power);
        Assert.True(now.IsCreature);
        Assert.True(now.Has(KeywordAbility.Flying));

        // Both types: the one the sentence names and the one the permanent had.
        Assert.Contains("Illusion", now.Subtypes, StringComparer.OrdinalIgnoreCase);
        Assert.Contains("Vehicle", now.Subtypes, StringComparer.OrdinalIgnoreCase);
    }

    /// <summary>
    /// A replacing type change takes only the subtypes from its own set (CR 205.1a).
    /// </summary>
    /// <remarks>
    /// "The new subtype replaces any existing subtypes <em>from the appropriate set</em>" —
    /// creature types, land types, artifact types and the rest are separate sets, and a change to
    /// one leaves the others alone. This reader used to clear the whole list, so an animated basic
    /// land stopped being a Forest; landwalk reads the computed land types, not the printed ones,
    /// so a Forest that had got up and walked could no longer be walked past.
    /// <para>
    /// The comment justifying the old behaviour cited 205.1b, which is the rule that says the
    /// opposite.
    /// </para>
    /// </remarks>
    [Fact]
    public void An_animated_land_keeps_the_land_type_it_had()
    {
        var awaken = Card(
            "Land Animation Test",
            "Target land you control becomes a 3/3 Elemental creature until end of turn.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(awaken);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, awaken), [Target.ToPermanent(forest)]);
        Settle(game);

        var now = Characteristics.Of(game.State, Pool, game.State.GetObject(forest));

        Assert.Equal(3, now.Power);
        Assert.True(now.CardTypes.HasFlag(CardType.Creature));
        Assert.True(now.CardTypes.HasFlag(CardType.Land));

        // The creature type it was given, and the land type it already had. Both.
        Assert.Contains("Elemental", now.Subtypes, StringComparer.OrdinalIgnoreCase);
        Assert.Contains("Forest", now.Subtypes, StringComparer.OrdinalIgnoreCase);
    }

    /// <summary>
    /// "Becomes a Dragon with base power and toughness 4/4 and gains flying" (CR 205.1a, 613.4b).
    /// </summary>
    /// <remarks>
    /// The same animation with its size printed after the noun instead of before it, which is 23
    /// corpus cards the earlier pattern could not see. Three things are asserted that a looser
    /// reader gets wrong: the creature type <em>replaces</em> the one it had, because this wording
    /// carries no "in addition"; the size is set under the counter rather than added to it; and no
    /// card type is conferred, because the sentence names none — a permanent that became a
    /// creature on the strength of a word the card did not print would be a different card.
    /// </remarks>
    [Fact]
    public void A_size_printed_after_the_type_still_sets_it()
    {
        var polymorph = Card(
            "Late Size Test",
            "Until end of turn, target creature becomes a Dragon with base power and toughness "
                + "4/4 and gains flying.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(polymorph);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();

        // TestCards.Creature prints the subtype Bear, which is what the Dragon has to displace.
        var bear = game.Create(
            alice, TestCards.Creature("Late Size Bear Test", 2, 2), Zone.Battlefield);

        game.ChangeCounters(bear, CounterKinds.PlusOnePlusOne, 1);

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, polymorph), [Target.ToPermanent(bear)]);
        Settle(game);

        var now = Characteristics.Of(game.State, Pool, game.State.GetObject(bear));

        Assert.Equal(5, now.Power);
        Assert.True(now.Has(KeywordAbility.Flying));

        Assert.Contains("Dragon", now.Subtypes, StringComparer.OrdinalIgnoreCase);
        Assert.DoesNotContain("Bear", now.Subtypes, StringComparer.OrdinalIgnoreCase);

        // Nothing but a creature: the sentence names no card type, so none is conferred.
        Assert.False(now.CardTypes.HasFlag(CardType.Artifact));
    }

    /// <summary>
    /// Radiance: "~ deals 2 damage to target creature and each other creature that shares a
    /// color with it" (CR 608.2h, 105.2).
    /// </summary>
    /// <remarks>
    /// One sentence about two things, and the reader cuts it into the two sentences the parser
    /// already reads — "deals 2 damage to target creature" and "deals 2 damage to each creature"
    /// — then tells the group which target to compare against.
    /// <para>
    /// Four wrong readings are asserted against, and each has its own creature on the board. The
    /// target must take 2 and not 4: the printed word is "each <em>other</em>", so the group has
    /// to leave the sibling out or the card doubles its own damage. A creature of another colour
    /// must take none, which is what fails if the comparison is dropped and the sweep becomes a
    /// board wipe. A colourless creature must take none either, because CR 105.2c gives it no
    /// colour to share. And the second red creature must take 2, which is what fails if the
    /// group half is never built at all.
    /// </para>
    /// </remarks>
    [Fact]
    public void Radiance_reaches_every_creature_sharing_the_targets_colour()
    {
        var beam = Card(
            "Peer Colour Beam Test",
            "~ deals 2 damage to target creature and each other creature that shares a color "
                + "with it.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(beam);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        static CardDefinition Painted(string name, ManaColor? colour) => new()
        {
            OracleId = "oracle-" + name.ToLowerInvariant().Replace(' ', '-'),
            Name = name,
            CardTypes = CardType.Creature,
            Power = 4,
            Toughness = 4,
            Colors = colour is { } shade ? [shade] : [],
            ColorIdentity = colour is { } identity ? [identity] : [],
        };

        var (game, alice, bob) = InMainPhase();

        var aimed = game.Create(
            bob, Painted("Peer Colour Aimed Test", ManaColor.Red), Zone.Battlefield);

        var alsoRed = game.Create(
            bob, Painted("Peer Colour Also Red Test", ManaColor.Red), Zone.Battlefield);

        var green = game.Create(
            bob, Painted("Peer Colour Green Test", ManaColor.Green), Zone.Battlefield);

        var colourless = game.Create(
            bob, Painted("Peer Colour Void Test", null), Zone.Battlefield);

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, beam), [Target.ToPermanent(aimed)]);

        Settle(game);

        int Damage(ObjectId id) => game.State.GetObject(id).Permanent!.DamageMarked;

        Assert.Equal(2, Damage(aimed));
        Assert.Equal(2, Damage(alsoRed));
        Assert.Equal(0, Damage(green));
        Assert.Equal(0, Damage(colourless));
    }

    /// <summary>
    /// "Target creature and all other creatures with the same name as that creature get -3/-3
    /// until end of turn" (CR 201.2a).
    /// </summary>
    /// <remarks>
    /// The same reader with the other comparison, and the half it exercises is the pump rather
    /// than the sweep — the group becomes a <c>PumpGroup</c> here and a <c>ToEachPermanent</c>
    /// above, so between them both arms of the decoration are played. The stranger on the board
    /// is the wrong reading: a group with no comparison is a one-sided board wipe.
    /// </remarks>
    [Fact]
    public void A_group_can_be_named_by_the_targets_name()
    {
        var blight = Card(
            "Peer Name Blight Test",
            "Target creature and all other creatures with the same name as that creature get "
                + "-3/-3 until end of turn.",
            CardType.Instant);

        var compiled = CardCompiler.Compile(blight);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();

        var twin = TestCards.Creature("Peer Name Twin Test", 2, 2);
        var aimed = game.Create(bob, twin, Zone.Battlefield);
        var sibling = game.Create(bob, twin, Zone.Battlefield);

        var stranger = game.Create(
            bob, TestCards.Creature("Peer Name Stranger Test", 2, 2), Zone.Battlefield);

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, blight), [Target.ToPermanent(aimed)]);

        Settle(game);

        Assert.DoesNotContain(aimed, game.State.Battlefield);
        Assert.DoesNotContain(sibling, game.State.Battlefield);

        Assert.Contains(stranger, game.State.Battlefield);
        Assert.Equal(
            2, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(stranger)));
    }

    /// <summary>
    /// "Destroy target creature that was dealt damage this turn" (CR 120.3, 514.2).
    /// </summary>
    /// <remarks>
    /// A clause about the target's <em>history</em>, printed after the owner clause where the
    /// "with …" qualifier grammar could not reach it. The wrong reading is the one that drops it:
    /// the card would be Murder, aimable at anything, and would read as complete while being
    /// strictly better than printed — so the undamaged creature is asserted illegal here.
    /// <para>
    /// Two shapes are asserted <em>unread</em> beside it, and both are deliberate. "That
    /// <em>dealt</em> damage this turn" is the opposite sentence — the creature that dealt it —
    /// and two corpus cards print it. And a phrase that can name a planeswalker is refused
    /// because CR 306.7 removes loyalty counters instead of marking damage, so nothing in the
    /// state remembers a planeswalker was dealt any: compiled, those cards could never choose the
    /// damaged planeswalker they print, and nothing would look unfinished.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_target_may_be_narrowed_to_one_dealt_damage_this_turn()
    {
        var blow = Card(
            "Dealt Damage Blow Test",
            "Destroy target creature that was dealt damage this turn.",
            CardType.Instant);

        var compiled = CardCompiler.Compile(blow);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var spec = Assert.Single(compiled.Spell!.Targets);

        var (game, alice, bob) = InMainPhase();

        var hurt = game.Create(
            bob, TestCards.Creature("Dealt Damage Wounded Test", 4, 4), Zone.Battlefield);

        var whole = game.Create(
            bob, TestCards.Creature("Dealt Damage Whole Test", 4, 4), Zone.Battlefield);

        var gun = game.Create(
            alice, TestCards.Creature("Dealt Damage Gun Test", 1, 1), Zone.Battlefield);

        // One damage on a 4/4 — enough to have been dealt damage, not enough to die to it.
        game.MarkDamage(hurt, 1, sourceId: gun);

        bool Legal(ObjectId id) =>
            spec.ObjectFilter?.Invoke(game.State, Pool, game.State.GetObject(id), alice) != false;

        Assert.True(Legal(hurt));
        Assert.False(Legal(whole));

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, blow), [Target.ToPermanent(hurt)]);
        Settle(game);

        Assert.DoesNotContain(hurt, game.State.Battlefield);
        Assert.Contains(whole, game.State.Battlefield);

        // The creature that *dealt* the damage, which is the other sentence entirely.
        Assert.False(
            CardCompiler.Compile(Card(
                "Dealt Damage Dealer Test",
                "Destroy target creature that dealt damage this turn.",
                CardType.Instant)).IsComplete);

        // A phrase that can name a planeswalker, refused by construction.
        Assert.False(
            CardCompiler.Compile(Card(
                "Dealt Damage Walker Test",
                "Destroy target creature or planeswalker an opponent controls that was dealt "
                    + "damage this turn.",
                CardType.Instant)).IsComplete);
    }

    /// <summary>
    /// "Creatures you control get +1/+1 until end of turn. Untap them." (CR 609.2)
    /// </summary>
    /// <remarks>
    /// A sentence that says nothing on its own: "them" is whichever set the sentence before it
    /// chose, and it is resolved from the effects already built rather than from the words. Two
    /// wrong readings are asserted against — untapping the whole board, which is what a group
    /// with no ownership clause would do, and untapping nothing, which is what a dangling pronoun
    /// left the card doing before. The opponent's tapped creature settles the first.
    /// </remarks>
    [Fact]
    public void Untap_them_untaps_the_group_the_sentence_before_named()
    {
        var roar = Card(
            "Untap Them Group Test",
            "Creatures you control get +1/+1 until end of turn. Untap them.",
            CardType.Instant);

        var compiled = CardCompiler.Compile(roar);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();

        var mine = game.Create(
            alice, TestCards.Creature("Untap Them Mine Test", 2, 2), Zone.Battlefield);

        var alsoMine = game.Create(
            alice, TestCards.Creature("Untap Them Also Mine Test", 2, 2), Zone.Battlefield);

        var theirs = game.Create(
            bob, TestCards.Creature("Untap Them Theirs Test", 2, 2), Zone.Battlefield);

        game.Tap(mine);
        game.Tap(alsoMine);
        game.Tap(theirs);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, roar), []);
        Settle(game);

        Assert.False(game.State.GetObject(mine).Permanent!.IsTapped);
        Assert.False(game.State.GetObject(alsoMine).Permanent!.IsTapped);

        // The same set the pump found, and no wider than it.
        Assert.True(game.State.GetObject(theirs).Permanent!.IsTapped);

        Assert.Equal(3, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(mine)));
        Assert.Equal(2, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(theirs)));
    }

    /// <summary>
    /// "Put a +1/+1 counter on up to three target creatures. Untap them." (CR 115.1)
    /// </summary>
    /// <remarks>
    /// The other thing "them" can mean, and the reading that has to be all of them: untapping
    /// only the most recent target is the same shape of bug the plural "those creatures" had in
    /// the skip-untap tail, and it gives a strictly weaker card. All three are asserted untapped.
    /// </remarks>
    [Fact]
    public void Untap_them_untaps_every_target_the_sentence_before_chose()
    {
        var guidance = Card(
            "Untap Them Targets Test",
            "Put a +1/+1 counter on up to three target creatures. Untap them.",
            CardType.Instant);

        var compiled = CardCompiler.Compile(guidance);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();

        var chosen = Enumerable.Range(0, 3)
            .Select(i => game.Create(
                alice,
                TestCards.Creature($"Untap Them Target {i} Test", 2, 2),
                Zone.Battlefield))
            .ToList();

        foreach (var id in chosen)
            game.Tap(id);

        game.CastSpell(
            alice,
            TestCards.PutInHand(game, alice, guidance),
            [.. chosen.Select(Target.ToPermanent)]);

        Settle(game);

        foreach (var id in chosen)
        {
            var creature = game.State.GetObject(id);
            Assert.False(creature.Permanent!.IsTapped);
            Assert.Equal(
                1, creature.Permanent.Counters.GetValueOrDefault(CounterKinds.PlusOnePlusOne));
        }
    }

    /// <summary>
    /// "Create a 1/1 white Soldier creature token, then attach ~ to it." (CR 701.3a)
    /// </summary>
    /// <remarks>
    /// Living weapon written out on cards that do not print the keyword. "It" is the token the
    /// sentence before it made, which has no id until that effect resolves — so the two are one
    /// effect rather than two, the way the keyword already compiles.
    /// <para>
    /// The reader sits <em>after</em> the targeted "attach ~ to it", not before it, and that
    /// order is asserted here: the two sentences are the same string, and claiming this one
    /// first took sixteen corpus lines away from "return target creature card … and attach ~ to
    /// it" — a reader stealing from its neighbour while the coverage number went up. The last
    /// assertion is that neighbour, still reading its own way.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_token_made_and_then_worn_is_one_effect()
    {
        var blade = Card(
            "Written Weapon Test",
            "When ~ enters, create a 1/1 white Soldier creature token, then attach ~ to it.\n"
                + "Equipped creature gets +2/+2.",
            CardType.Artifact,
            subtypes: "Equipment");

        var compiled = CardCompiler.Compile(blade);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var equipment = game.Create(alice, blade, Zone.Battlefield);
        Settle(game);

        var soldier = game.State.Battlefield.Single(
            id => game.State.GetObject(id).Card.Name == "Soldier");

        Assert.Equal(soldier, game.State.GetObject(equipment).Permanent?.AttachedTo);

        // The token is printed 1/1, so the buff is the proof that the attaching half happened
        // rather than the token merely arriving.
        var worn = Characteristics.Of(game.State, Pool, game.State.GetObject(soldier));
        Assert.Equal(3, worn.Power);
        Assert.Equal(3, worn.Toughness);

        // Several tokens, and "it" names none of them.
        Assert.False(
            CardCompiler.Compile(Card(
                "Written Weapon Many Test",
                "When ~ enters, create two 1/1 white Soldier creature tokens, then attach ~ to "
                    + "it.",
                CardType.Artifact,
                subtypes: "Equipment")).IsComplete);

        // The neighbour this reader must not take: here "it" is the card that was targeted.
        var raise = CardCompiler.Compile(Card(
            "Written Weapon Raise Test",
            "When ~ enters, return target creature card from your graveyard to the battlefield "
                + "and attach ~ to it.",
            CardType.Artifact,
            subtypes: "Equipment"));

        Assert.True(raise.IsComplete, string.Join(" | ", raise.Unhandled));
        Assert.Contains(raise.Triggers[0].Effects, e => e is AttachSourceTo);
        Assert.DoesNotContain(raise.Triggers[0].Effects, e => e is CreateTokenAndAttachSource);
    }

    /// <summary>
    /// "When ~ enters, sacrifice it unless you sacrifice another creature."
    /// </summary>
    /// <remarks>
    /// Three words the ransom reader could not take, all in its cost half: "another", a number
    /// above three, and "their owner's hand" beside "its". The article was the awkward one —
    /// <c>an?</c> was tried before <c>another</c> and matched its first letter, leaving the noun
    /// as "nother creature" — which is why the fix is an ordering and not a new alternative.
    /// <para>
    /// "Another" is accepted and not acted on. That is safe only because this ransom is always on
    /// the source: the single permanent the word excludes is the source itself, and paying with it
    /// puts it in the graveyard exactly as declining would (CR 109.5).
    /// </para>
    /// </remarks>
    [Fact]
    public void A_ransom_can_ask_for_another_creature()
    {
        var ogre = Card(
            "Ransom Another Test",
            "When ~ enters, sacrifice it unless you sacrifice another creature.",
            CardType.Creature,
            power: 4,
            toughness: 4);

        var compiled = CardCompiler.Compile(ogre);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var goat = game.Create(
            alice, TestCards.Creature("Ransom Goat Test", 1, 1), Zone.Battlefield);

        var brute = game.Create(alice, ogre, Zone.Battlefield);

        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.PayOrSacrifice });

        game.Choose(alice, [goat.Value.ToString("N")]);
        Settle(game);

        // The ransom was paid, so the ogre stays and the goat is gone.
        Assert.DoesNotContain(goat, game.State.Battlefield);
        Assert.Contains(brute, game.State.Battlefield);
    }

    /// <summary>
    /// "When ~ enters, sacrifice it unless you sacrifice four creatures."
    /// </summary>
    /// <remarks>
    /// The count words stopped at five in one place and at three in another, and the two
    /// disagreeing is what makes this worth its own test: a number the pattern accepted but the
    /// counter did not would have asked for one creature instead of four — a card strictly
    /// cheaper than the one printed, which is the failure this project refuses to ship.
    /// </remarks>
    [Fact]
    public void A_ransom_asks_for_every_creature_the_number_names()
    {
        var idol = Card(
            "Ransom Four Test",
            "When ~ enters, sacrifice it unless you sacrifice four creatures.",
            CardType.Creature,
            power: 6,
            toughness: 6);

        var compiled = CardCompiler.Compile(idol);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();

        var fodder = Enumerable.Range(0, 4)
            .Select(i => game.Create(
                alice, TestCards.Creature($"Ransom Fodder {i} Test", 1, 1), Zone.Battlefield))
            .ToList();

        var statue = game.Create(alice, idol, Zone.Battlefield);

        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.PayOrSacrifice });

        // Four are demanded, not one: paying three is not paying.
        Assert.Equal(4, game.State.Choice!.MaxPicks);

        game.Choose(alice, [.. fodder.Select(id => id.Value.ToString("N"))]);
        Settle(game);

        Assert.Contains(statue, game.State.Battlefield);

        foreach (var id in fodder)
            Assert.DoesNotContain(id, game.State.Battlefield);
    }

    // ---- Offers whose cost is not mana ---------------------------------------

    /// <summary>
    /// A pool serving a definition built by hand rather than compiled from rules text.
    /// </summary>
    /// <remarks>
    /// Every other test in this file plays a card the compiler read, which is the whole point of
    /// the file. The four below cannot yet: the effect they exercise is engine machinery whose
    /// reader is being written separately, and a test that waited for the reader would be a test
    /// of two things that fails for either. It answers about spells only — nothing else in these
    /// games has an ability at all.
    /// </remarks>
    private sealed class HandBuilt : IAbilitySource
    {
        private readonly Dictionary<string, SpellDefinition> _spells = [];

        public IReadOnlyList<TriggeredAbilityDefinition> TriggersOf(CardDefinition card) => [];

        public SpellDefinition? SpellOf(CardDefinition card) =>
            _spells.GetValueOrDefault(card.OracleId);

        public HandBuilt WithSpell(CardDefinition card, SpellDefinition spell)
        {
            _spells[card.OracleId] = spell;
            return this;
        }
    }

    private static (Game Game, Guid Alice, Guid Bob) InMainPhaseWith(IAbilitySource abilities)
    {
        var alice = Guid.Parse("11111111-1111-1111-1111-111111111111");
        var bob = Guid.Parse("22222222-2222-2222-2222-222222222222");
        var game = Game.Start(
            Guid.NewGuid(),
            [
                new PlayerSetup(alice, "Alice", 20, TestCards.Deck(40, "Alice")),
                new PlayerSetup(bob, "Bob", 20, TestCards.Deck(40, "Bob")),
            ],
            new GameRandom(1),
            startingPlayerId: alice,
            abilities: abilities);

        game.BeginPlay(withMulligans: false);
        TestCards.PassToStep(game, TurnStep.PrecombatMain);
        return (game, alice, bob);
    }

    /// <summary>
    /// A sorcery offering one chosen cost, with a different life total behind each answer.
    /// </summary>
    /// <remarks>
    /// The two branches are told apart by the number they leave rather than by whether anything
    /// happened, so a test cannot pass on an engine that simply ran neither. Gaining is paying
    /// and losing is declining, and no other card in these games touches life.
    /// <para>
    /// The offer sits on a <em>sorcery</em> deliberately. A spell does not survive its own
    /// resolution (CR 400.7), so the locator that finds the branch again has to be resolved when
    /// the offer is made rather than when it is answered — the failure that hid until the first
    /// spell-sourced offer, and one a permanent's ability cannot reproduce.
    /// </para>
    /// </remarks>
    private static (HandBuilt Pool, CardDefinition Card) OfferPaidBy(
        string name, string text, ChosenCostKind kind, string? what)
    {
        var card = Card(name, text, CardType.Sorcery);

        var pool = new HandBuilt().WithSpell(card, new SpellDefinition
        {
            Effects =
            [
                new MayPay(
                    Mana.ManaCostSpec.Parse(string.Empty),
                    IfYouDo: [new ChangeLife(3)],
                    IfYouDont: [new ChangeLife(-2)],
                    ChosenKind: kind,
                    ChosenCount: 1,
                    ChosenWhat: what is null
                        ? null
                        : EffectPhrase.Specs.Parse("target " + what)),
            ],
        });

        return (pool, card);
    }

    /// <summary>
    /// "You may sacrifice a creature. If you do, ..." — an offer priced in permanents
    /// (CR 118.12a).
    /// </summary>
    /// <remarks>
    /// The assertion that earns its place is the creature's absence. An engine that ran "if you
    /// do" without ever taking the payment passes every life-total check in this test and plays
    /// a card strictly cheaper than the one printed, which is exactly the failure this project
    /// refuses to ship — so the board is asserted before the life total is.
    /// </remarks>
    [Fact]
    public void An_offer_can_charge_a_sacrifice_and_the_creature_really_goes()
    {
        var (pool, pact) = OfferPaidBy(
            "Chosen Sacrifice Offer Test",
            "You may sacrifice a creature. If you do, you gain 3 life. If you don't, you lose "
                + "2 life.",
            ChosenCostKind.SacrificePermanents,
            "creature");

        var (game, alice, _) = InMainPhaseWith(pool);
        var goat = game.Create(
            alice, TestCards.Creature("Chosen Cost Goat Test", 1, 1), Zone.Battlefield);
        var card = TestCards.PutInHand(game, alice, pact);

        game.CastSpell(alice, card);
        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.OptionalPayment });

        // The question is the objects themselves rather than yes and no, and picking none of
        // them is the decline — which is why it has no floor and a ceiling of the whole cost.
        var offer = game.State.Choice!;
        Assert.Equal(0, offer.MinPicks);
        Assert.Equal(1, offer.MaxPicks);
        Assert.Contains(offer.Options, o => o.Id == goat.Value.ToString("N"));

        game.Choose(alice, [goat.Value.ToString("N")]);
        Settle(game);

        // Paid: the creature left the battlefield, and went to the graveyard rather than
        // vanishing — a sacrifice is a move, and something has to be there afterwards.
        Assert.DoesNotContain(goat, game.State.Battlefield);
        Assert.Contains(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Chosen Cost Goat Test");

        // And the branch behind the payment ran.
        Assert.Equal(23, game.State.GetPlayer(alice).Life);
    }

    /// <summary>
    /// The same offer turned down: picking nothing is how a player says no.
    /// </summary>
    /// <remarks>
    /// The half that is easy to get wrong. An empty answer reaching the paying arm would spend
    /// nothing and run "if you do" anyway, which is the same free card the test above guards
    /// against, approached from the other side — so this asserts both that the creature is still
    /// there and that the <em>other</em> branch is what ran.
    /// </remarks>
    [Fact]
    public void Picking_nothing_declines_a_chosen_cost_and_runs_the_other_branch()
    {
        var (pool, pact) = OfferPaidBy(
            "Chosen Decline Offer Test",
            "You may sacrifice a creature. If you do, you gain 3 life. If you don't, you lose "
                + "2 life.",
            ChosenCostKind.SacrificePermanents,
            "creature");

        var (game, alice, _) = InMainPhaseWith(pool);
        var goat = game.Create(
            alice, TestCards.Creature("Chosen Decline Goat Test", 1, 1), Zone.Battlefield);
        var card = TestCards.PutInHand(game, alice, pact);

        game.CastSpell(alice, card);
        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.OptionalPayment });

        game.Choose(alice, []);
        Settle(game);

        Assert.Contains(goat, game.State.Battlefield);
        Assert.Equal(18, game.State.GetPlayer(alice).Life);
    }

    /// <summary>
    /// A player with nothing legal to pay with is not asked at all (CR 118.3).
    /// </summary>
    /// <remarks>
    /// A cost cannot be paid in part, so a board holding fewer than the cost names is not a
    /// decision — and stopping the game to put a question with one possible answer is how a
    /// game stalls in front of a player who has nothing to click. The mana arm has skipped the
    /// question for the same reason since it was written; this asserts the selection arm does,
    /// by looking for the offer in the log rather than for its absence right now.
    /// </remarks>
    [Fact]
    public void An_offer_nobody_can_pay_is_never_put_to_them()
    {
        var (pool, pact) = OfferPaidBy(
            "Chosen Unpayable Offer Test",
            "You may sacrifice a creature. If you do, you gain 3 life. If you don't, you lose "
                + "2 life.",
            ChosenCostKind.SacrificePermanents,
            "creature");

        var (game, alice, _) = InMainPhaseWith(pool);
        var card = TestCards.PutInHand(game, alice, pact);

        game.CastSpell(alice, card);
        Settle(game);

        Assert.DoesNotContain(
            game.Log, e => e is ChoiceRequested { Choice.Kind: ChoiceKind.OptionalPayment });
        Assert.Equal(18, game.State.GetPlayer(alice).Life);
    }

    /// <summary>
    /// The same offer priced in cards: "unless that player discards a card" (CR 701.9a).
    /// </summary>
    /// <remarks>
    /// The kind ward was refused for. It is worth its own test rather than trusting the
    /// sacrifice one, because where the payment comes from and where it goes are the only things
    /// that differ between the kinds: a discard that read the battlefield would offer nothing
    /// and quietly decline for a player holding seven cards.
    /// </remarks>
    [Fact]
    public void A_chosen_cost_can_take_a_card_out_of_a_hand()
    {
        var (pool, ransom) = OfferPaidBy(
            "Chosen Discard Offer Test",
            "You may discard a card. If you do, you gain 3 life. If you don't, you lose 2 life.",
            ChosenCostKind.DiscardCards,
            what: null);

        var (game, alice, _) = InMainPhaseWith(pool);
        var card = TestCards.PutInHand(game, alice, ransom);

        game.CastSpell(alice, card);

        // Counted with the spell already on the stack, so the one card missing at the end is the
        // one that was pitched rather than the one that was cast.
        var held = game.State.GetPlayer(alice).Hand.Count;

        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.OptionalPayment });
        var pitched = game.State.Choice!.Options[0];

        game.Choose(alice, [pitched.Id]);
        Settle(game);

        Assert.Equal(held - 1, game.State.GetPlayer(alice).Hand.Count);
        Assert.Contains(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == pitched.Label);
        Assert.Equal(23, game.State.GetPlayer(alice).Life);
    }

    // ---- Batched attacks, and spells counted by kind -------------------------

    /// <summary>
    /// A pool serving triggers written by hand rather than compiled from rules text.
    /// </summary>
    /// <remarks>
    /// The sibling of <see cref="HandBuilt"/>, one ability kind along, and here for the same
    /// reason: the six tests below exercise engine machinery whose reader is being written
    /// separately, and a test that waited for the reader would be a test of two things that fails
    /// for either. The printed wording is on the card and on the ability text, so what the
    /// machinery is <em>for</em> is legible even while the compiler still refuses the line.
    /// </remarks>
    private sealed class HandBuiltTriggers : IAbilitySource
    {
        private readonly Dictionary<string, TriggeredAbilityDefinition> _triggers = [];

        public IReadOnlyList<TriggeredAbilityDefinition> TriggersOf(CardDefinition card) =>
            _triggers.TryGetValue(card.OracleId, out var trigger) ? [trigger] : [];

        public HandBuiltTriggers WithTrigger(
            CardDefinition card, TriggeredAbilityDefinition trigger)
        {
            _triggers[card.OracleId] = trigger;
            return this;
        }
    }

    /// <summary>"Draw that many cards", for a trigger about a batch (CR 603.2).</summary>
    private static DrawCards DrawThatMany() =>
        new(new Amount(1) { Counter = context => context.SubjectAmount ?? 0 });

    /// <summary>
    /// "Whenever one or more creatures you control attack, draw that many cards" (CR 508.1).
    /// </summary>
    /// <remarks>
    /// Twenty-eight corpus lines are shaped this way and six of them go on to say "that many" —
    /// "add that much mana", "create that many Treasure tokens". The whole family was refused
    /// rather than shipped because the declaration reached the trigger carrying no number, so
    /// every one of them fired and then did nothing at all: a card that compiles, counts as
    /// covered, and is blank on the table.
    /// <para>
    /// Three attackers and not one, because a batch of one is the number every wrong
    /// implementation also produces.
    /// </para>
    /// </remarks>
    [Fact]
    public void An_attack_declaration_says_how_many_creatures_were_in_it()
    {
        var horn = Card(
            "Batch Horn Test",
            "Whenever one or more creatures you control attack, draw that many cards.",
            CardType.Artifact);

        var pool = new HandBuiltTriggers().WithTrigger(horn, new TriggeredAbilityDefinition
        {
            Id = "batch-draw",
            Text = horn.OracleText,
            Triggers = static (e, state, source) =>
                e is AttackersDeclared declared
                && declared.Attackers.Keys.Any(id =>
                    state.TryGetObject(id, out var attacker)
                    && attacker.ControllerId == source.ControllerId),
            Effects = [DrawThatMany()],
        });

        var (game, alice, bob) = InMainPhaseWith(pool);
        game.Create(alice, horn, Zone.Battlefield);

        var attackers = Enumerable.Range(0, 3)
            .Select(i => game.Create(
                alice, TestCards.Creature($"Batch Attacker {i} Test", 2, 2), Zone.Battlefield))
            .ToList();

        PassTo(game, 3, TurnStep.DeclareAttackers);
        var drawn = game.State.GetPlayer(alice).CardsDrawnThisTurn;

        game.DeclareAttackers(
            alice,
            attackers.ToDictionary(id => id, _ => AttackTarget.Player(bob)));

        Settle(game);

        Assert.Equal(drawn + 3, game.State.GetPlayer(alice).CardsDrawnThisTurn);
        Assert.Equal(game.State, GameReducer.Replay(game.Log));
    }

    /// <summary>
    /// "Whenever one or more Dragons you control attack, draw that many cards" (CR 603.2).
    /// </summary>
    /// <remarks>
    /// The number the sentence wants is the number of <em>Dragons</em>, and answering with the
    /// size of the whole declaration prints a strictly better card than the one on the table —
    /// four of the six corpus lines that say "that many" about an attack name a narrower group
    /// than "creatures you control": Dragons, Dinosaurs, Birds, Treefolk.
    /// <para>
    /// So the attack is deliberately mixed. Two Dragons and a Bear draw two, and every reading
    /// that takes the batch size instead draws three — which is the failure this asserts against
    /// rather than the one it asserts for.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_narrower_attack_trigger_counts_only_the_creatures_it_names()
    {
        var lord = Card(
            "Batch Dragon Test",
            "Whenever one or more Dragons you control attack, draw that many cards.",
            CardType.Artifact);

        var pool = new HandBuiltTriggers().WithTrigger(lord, new TriggeredAbilityDefinition
        {
            Id = "batch-dragons",
            Text = lord.OracleText,
            Triggers = static (e, state, source) =>
                e is AttackersDeclared declared
                && declared.Attackers.Keys.Any(id =>
                    state.TryGetObject(id, out var attacker)
                    && attacker.ControllerId == source.ControllerId
                    && attacker.Card.Subtypes.Contains("Dragon", StringComparer.Ordinal)),
            Effects = [DrawThatMany()],
        });

        var (game, alice, bob) = InMainPhaseWith(pool);
        game.Create(alice, lord, Zone.Battlefield);

        var first = game.Create(
            alice,
            Card("Batch Dragon One Test", string.Empty, CardType.Creature, 2, 2, subtypes: "Dragon"),
            Zone.Battlefield);

        var second = game.Create(
            alice,
            Card("Batch Dragon Two Test", string.Empty, CardType.Creature, 2, 2, subtypes: "Dragon"),
            Zone.Battlefield);

        var bear = game.Create(
            alice, TestCards.Creature("Batch Bear Test", 2, 2), Zone.Battlefield);

        PassTo(game, 3, TurnStep.DeclareAttackers);
        var drawn = game.State.GetPlayer(alice).CardsDrawnThisTurn;

        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget>
            {
                [first] = AttackTarget.Player(bob),
                [second] = AttackTarget.Player(bob),
                [bear] = AttackTarget.Player(bob),
            });

        Settle(game);

        Assert.Equal(drawn + 2, game.State.GetPlayer(alice).CardsDrawnThisTurn);
        Assert.Equal(game.State, GameReducer.Replay(game.Log));
    }

    /// <summary>A permanent that watches for the first spell of one card type each turn.</summary>
    private static (HandBuiltTriggers Pool, CardDefinition Card) FirstOfKindWatcher(
        string name, CardType kind)
    {
        var watcher = Card(
            name,
            $"Whenever you cast your first {kind.ToString().ToLowerInvariant()} spell each turn, "
                + "you gain 2 life.",
            CardType.Artifact);

        var pool = new HandBuiltTriggers().WithTrigger(watcher, new TriggeredAbilityDefinition
        {
            Id = "first-of-kind",
            Text = watcher.OracleText,

            // The state a trigger is offered is the one *before* its event (CR 603.2), so the
            // spell being cast has not been counted yet and "first" is a count of nought. Reading
            // it after the event would need a state the predicate is never given, and the
            // off-by-one is the difference between a card that never fires and one that fires on
            // the second spell.
            Triggers = (e, state, source) =>
                e is SpellCastEvent cast
                && cast.PlayerId == source.ControllerId
                && state.TryGetObject(cast.StackId, out var spell)
                && spell.Card.CardTypes.HasFlag(kind)
                && state.GetPlayer(cast.PlayerId).SpellsCastThisTurnOfKind(kind) == 0,
            Effects = [new ChangeLife(2)],
        });

        return (pool, watcher);
    }

    /// <summary>
    /// "Whenever you cast your first enchantment spell each turn" fires once, for that kind.
    /// </summary>
    /// <remarks>
    /// Fifteen corpus lines ask this, and <c>PlayerState</c> kept two counts — every spell and
    /// every noncreature spell — neither of which can answer it. The instant cast first is the
    /// half that catches a reading taken from the total: it is a spell, it is not an enchantment,
    /// and the enchantment after it is still the first of its kind.
    /// </remarks>
    [Fact]
    public void A_first_spell_of_a_kind_trigger_ignores_the_other_kinds()
    {
        var (pool, watcher) = FirstOfKindWatcher(
            "First Enchantment Test", CardType.Enchantment);

        var (game, alice, _) = InMainPhaseWith(pool);
        game.Create(alice, watcher, Zone.Battlefield);

        var bolt = Card("First Kind Instant Test", string.Empty);
        var charm = Card("First Kind Charm Test", string.Empty, CardType.Enchantment);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, bolt));
        Settle(game);
        Assert.Equal(20, game.State.GetPlayer(alice).Life);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, charm));
        Settle(game);
        Assert.Equal(22, game.State.GetPlayer(alice).Life);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, charm));
        Settle(game);
        Assert.Equal(22, game.State.GetPlayer(alice).Life);
        Assert.Equal(game.State, GameReducer.Replay(game.Log));
    }

    /// <summary>
    /// A permanent that arrives after the first of its kind has been cast waits for next turn.
    /// </summary>
    /// <remarks>
    /// This is the case that decides the whole design, and the reason the tempting shortcut was
    /// refused. <c>TriggeredAbilityDefinition.OncePerTurn</c> is kept per (permanent, ability),
    /// so a permanent put onto the battlefield <em>after</em> an enchantment had already been
    /// cast this turn still has its one firing in hand and takes it on the second enchantment —
    /// a card strictly better than the one printed, and one nothing else in the suite can see.
    /// <para>
    /// The turn afterwards is asserted as well, because "it never fires" passes the first half of
    /// this test just as cleanly as "it fires when it should not" fails it.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_permanent_that_arrives_after_the_first_of_its_kind_does_not_fire()
    {
        var (pool, watcher) = FirstOfKindWatcher(
            "Late Enchantment Test", CardType.Enchantment);

        var (game, alice, _) = InMainPhaseWith(pool);
        var charm = Card("Late Kind Charm Test", string.Empty, CardType.Enchantment);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, charm));
        Settle(game);

        // Onto the battlefield without a settle, which would hand priority on and leave nobody
        // able to cast the second enchantment - the arrival is what this test is about, and it
        // needs no state-based action to have happened.
        game.Create(alice, watcher, Zone.Battlefield);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, charm));
        Settle(game);

        Assert.Equal(20, game.State.GetPlayer(alice).Life);

        // Its own turn round again, and the count it reads has been cleared with the rest.
        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber >= 3
                && game.State.CurrentStep >= TurnStep.PrecombatMain
                && game.State.Priority.Holder == alice);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, charm));
        Settle(game);

        Assert.Equal(22, game.State.GetPlayer(alice).Life);
        Assert.Equal(game.State, GameReducer.Replay(game.Log));
    }

    /// <summary>
    /// A spell answering to two of the named subtypes at once is counted once (CR 601.2i).
    /// </summary>
    /// <remarks>
    /// "Your first outlaw spell each turn" is five creature types asked as one question — an
    /// outlaw is an Assassin, Mercenary, Pirate, Rogue or Warlock — and a tally kept per subtype
    /// would have to be summed to answer it, which counts a Pirate Rogue twice and makes its
    /// second spell the third. Keeping the cards and asking them is what avoids the sum.
    /// </remarks>
    [Fact]
    public void A_spell_answering_to_two_named_subtypes_is_counted_once()
    {
        var (game, alice, _) = InMainPhase();

        var brigand = Card(
            "Outlaw Count Test", string.Empty, CardType.Creature, 2, 2,
            subtypes: ["Pirate", "Rogue"]);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, brigand));
        Settle(game);

        var outlaws = new[] { "Assassin", "Mercenary", "Pirate", "Rogue", "Warlock" };
        var player = game.State.GetPlayer(alice);

        Assert.Equal(1, player.SpellsCastThisTurnOfKind(CardType.Creature, outlaws));

        // The type has to agree as well as the subtype: an outlaw is a creature that is one of
        // those, and the same words on an enchantment are not an outlaw spell.
        Assert.Equal(0, player.SpellsCastThisTurnOfKind(CardType.Enchantment, outlaws));

        // And the mask is an alternation, so "instant or sorcery" is one question rather than
        // two counts added - which is only safe while nothing can be both.
        Assert.Equal(0, player.SpellsCastThisTurnOfKind(CardType.Instant | CardType.Sorcery));
        Assert.Equal(1, player.SpellsCastThisTurnOfKind(CardType.None));
    }

    // ---- What a turn remembers ------------------------------------------------

    /// <summary>Plays on until the given turn has reached its first main phase.</summary>
    /// <remarks>
    /// Stopping on the turn number alone stops somewhere inside the untap and upkeep steps, and
    /// two of the tests below are about facts that the untap step changes. Naming the step as
    /// well is what makes "on the opponent's turn" mean a moment rather than a range.
    /// </remarks>
    private static void PassToMainPhaseOfTurn(Game game, int turnNumber) =>
        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber >= turnNumber
                && game.State.CurrentStep >= TurnStep.PrecombatMain);

    /// <summary>
    /// "As long as ~ entered this turn" is about the turn it arrived on, and no other.
    /// </summary>
    /// <remarks>
    /// Eighty-seven corpus cards ask it, including the whole cycle of lands whose second mana
    /// ability reads "Activate only if this land entered this turn". A permanent that arrived on
    /// an earlier turn has to answer no, which is the half a stored flag gets wrong by never being
    /// cleared — so the turn number is compared rather than a flag being set and reset.
    /// </remarks>
    [Fact]
    public void A_permanent_entered_this_turn_only_on_the_turn_it_arrived()
    {
        var (game, alice, _) = InMainPhase();
        var pit = game.Create(alice, TestCards.BasicLand("Entered Turn Pit"), Zone.Battlefield);
        Settle(game);

        Assert.True(game.State.EnteredThisTurn(pit));
        Assert.Equal(
            game.State.TurnNumber, game.State.GetObject(pit).Permanent!.EnteredOnTurn);

        PassToMainPhaseOfTurn(game, game.State.TurnNumber + 1);

        Assert.False(game.State.EnteredThisTurn(pit));
        Assert.Equal(game.State, GameReducer.Replay(game.Log));
    }

    /// <summary>
    /// The two permanents on the board disagree, which is the whole of what the question is for.
    /// </summary>
    /// <remarks>
    /// A test that only ever has one permanent cannot tell "entered this turn" from "is on the
    /// battlefield". The second creature arrives a turn later, so a reader that answered from the
    /// board rather than from the turn would light both of them up.
    /// <para>
    /// It also exercises the other way onto the battlefield. A token is <em>created</em> there and
    /// was never anywhere else (CR 111.1), while a creature spell <em>moves</em> there as it
    /// resolves — two different arms of the fold, and an "enters" fact recorded in only one of
    /// them has been an engine bug here before.
    /// </para>
    /// </remarks>
    [Fact]
    public void Only_the_permanent_that_arrived_this_turn_says_it_entered_this_turn()
    {
        var (game, alice, _) = InMainPhase();
        var veteran = game.Create(
            alice, TestCards.Creature("Entered Turn Veteran", 2, 2), Zone.Battlefield);
        Settle(game);

        PassToMainPhaseOfTurn(game, game.State.TurnNumber + 2);
        Assert.Equal(alice, game.State.ActivePlayerId);

        var recruit = Card(
            "Entered Turn Recruit", string.Empty, CardType.Creature, power: 2, toughness: 2);
        game.CastSpell(alice, TestCards.PutInHand(game, alice, recruit));
        Settle(game);

        var arrived = game.State.Battlefield
            .Single(id => game.State.GetObject(id).Card.Name == "Entered Turn Recruit");

        Assert.True(game.State.EnteredThisTurn(arrived));
        Assert.False(game.State.EnteredThisTurn(veteran));
    }

    /// <summary>
    /// Entering this turn is not summoning sickness, and this is the turn they disagree on.
    /// </summary>
    /// <remarks>
    /// The substitution is tempting and wrong. CR 302.6 keeps summoning sickness until the
    /// permanent's controller's <em>next</em> turn begins, so a creature that arrived on Alice's
    /// turn still has it all through Bob's turn — while "as long as ~ entered this turn" is
    /// emphatically off during that turn. The two agree only on the turn the permanent arrived,
    /// and diverge on the next one, which is the turn combat happens on: a reader built on the
    /// sickness flag would have been wrong exactly where it mattered and right everywhere it was
    /// easy to check.
    /// <para>
    /// The third stop is the question worth being explicit about: when the turn comes back round
    /// to Alice, does the permanent "enter this turn" again? No. It is the turn it arrived on, not
    /// a window that reopens each time its controller's turn does — and by then the sickness has
    /// gone, so the two flags have swapped which of them is true and still neither says yes.
    /// </para>
    /// </remarks>
    [Fact]
    public void Entering_this_turn_is_not_summoning_sickness()
    {
        var (game, alice, _) = InMainPhase();
        var bear = game.Create(
            alice, TestCards.Creature("Entered Turn Bear", 2, 2), Zone.Battlefield);
        Settle(game);

        var arrivedOn = game.State.TurnNumber;
        Assert.True(game.State.EnteredThisTurn(bear));
        Assert.True(game.State.GetObject(bear).Permanent!.HasSummoningSickness);

        // Bob's turn. Still sick (CR 302.6), and it did not enter this turn.
        PassToMainPhaseOfTurn(game, arrivedOn + 1);
        Assert.NotEqual(alice, game.State.ActivePlayerId);
        Assert.True(game.State.GetObject(bear).Permanent!.HasSummoningSickness);
        Assert.False(game.State.EnteredThisTurn(bear));

        // Alice's turn again. The sickness is gone and the answer has not changed.
        PassToMainPhaseOfTurn(game, arrivedOn + 2);
        Assert.Equal(alice, game.State.ActivePlayerId);
        Assert.False(game.State.GetObject(bear).Permanent!.HasSummoningSickness);
        Assert.False(game.State.EnteredThisTurn(bear));
        Assert.Equal(game.State, GameReducer.Replay(game.Log));
    }

    /// <summary>
    /// "If a nonland permanent left the battlefield this turn" — void's first half.
    /// </summary>
    /// <remarks>
    /// Sixteen corpus lines say "nonland" — which is not decoration: a fetchland sacrificing itself
    /// would otherwise turn every one of them on for free, on a board where nothing the card is
    /// about has happened. Void is an ability word and so has no rule of its own (CR 207.2c); only
    /// its other half, "a spell was warped this turn", is defined anywhere (CR 702.185c).
    /// <para>
    /// Exile is the other half. A creature exiled has left the battlefield and has not died
    /// (CR 700.4), so the departure count moves and the death count does not — one recorded fact
    /// answering two questions that a single flag would have run together.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_permanent_leaving_the_battlefield_is_recorded_and_lands_can_be_left_out()
    {
        var (game, _, bob) = InMainPhase();
        var bear = game.Create(bob, TestCards.Creature("Departing Bear", 2, 2), Zone.Battlefield);
        var forest = game.Create(bob, TestCards.BasicLand("Departing Forest"), Zone.Battlefield);
        var ox = game.Create(bob, TestCards.Creature("Departing Ox", 3, 3), Zone.Battlefield);
        Settle(game);

        Assert.Equal(0, game.State.PermanentsLeftBattlefieldThisTurn());

        game.Move(bear, Zone.Graveyard, MoveCause.Destroy);
        Settle(game);

        Assert.Equal(1, game.State.PermanentsLeftBattlefieldThisTurn());
        Assert.Equal(1, game.State.PermanentsLeftBattlefieldThisTurn(nonlandOnly: true));
        Assert.True(game.State.CreatureDiedThisTurn);

        // A land leaving is a departure, and is not one void asks about.
        game.Move(forest, Zone.Graveyard, MoveCause.Sacrifice);
        Settle(game);

        Assert.Equal(2, game.State.PermanentsLeftBattlefieldThisTurn());
        Assert.Equal(1, game.State.PermanentsLeftBattlefieldThisTurn(nonlandOnly: true));

        // Exiled is gone from the battlefield without having died.
        game.Move(ox, Zone.Exile, MoveCause.Exile);
        Settle(game);

        Assert.Equal(3, game.State.PermanentsLeftBattlefieldThisTurn());
        Assert.Equal(2, game.State.PermanentsLeftBattlefieldThisTurn(nonlandOnly: true));
        Assert.Equal(1, game.State.CreaturesDiedThisTurn());

        // "If a creature left the battlefield under your control this turn" names a type as well
        // as a player, and the land and the exiled creature are told apart by it.
        Assert.Equal(
            2, game.State.PermanentsLeftBattlefieldThisTurn(types: CardType.Creature));

        // It is a fact about the turn, and the turn ends.
        PassToMainPhaseOfTurn(game, game.State.TurnNumber + 1);

        Assert.Equal(0, game.State.PermanentsLeftBattlefieldThisTurn());
        Assert.False(game.State.CreatureDiedThisTurn);
        Assert.Equal(game.State, GameReducer.Replay(game.Log));
    }

    /// <summary>
    /// Revolt: "if a permanent left the battlefield <em>under your control</em> this turn".
    /// </summary>
    /// <remarks>
    /// This is the case a game-wide flag gets wrong, and it gets it wrong in the direction that
    /// still plays: 26 corpus lines say "under your control" and 5 more say "you controlled", and
    /// on every one of them an opponent's creature dying must <em>not</em> turn the card on. A
    /// reader built on "did anything leave" would be strictly better than printed on all 31, and
    /// nothing about the card would say so.
    /// <para>
    /// The two halves are asserted against each other rather than separately, because that is what
    /// makes the test fail on an unscoped implementation: an engine that ignored the scope would
    /// give both players the same answer, and both assertions here would have to be true at once.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_departure_is_recorded_against_the_player_who_controlled_it()
    {
        var (game, alice, bob) = InMainPhase();
        var hers = game.Create(bob, TestCards.Creature("Revolt Bear", 2, 2), Zone.Battlefield);
        Settle(game);

        game.Move(hers, Zone.Graveyard, MoveCause.Destroy);
        Settle(game);

        Assert.Equal(1, game.State.PermanentsLeftBattlefieldThisTurn(bob));
        Assert.Equal(0, game.State.PermanentsLeftBattlefieldThisTurn(alice));

        // Void is the one shape in the family that really is game-wide, and it still sees it.
        Assert.Equal(1, game.State.PermanentsLeftBattlefieldThisTurn(nonlandOnly: true));

        var mine = game.Create(alice, TestCards.Creature("Revolt Ox", 3, 3), Zone.Battlefield);
        game.Move(mine, Zone.Exile, MoveCause.Exile);
        Settle(game);

        Assert.Equal(1, game.State.PermanentsLeftBattlefieldThisTurn(alice));
        Assert.Equal(1, game.State.PermanentsLeftBattlefieldThisTurn(bob));
        Assert.Equal(2, game.State.PermanentsLeftBattlefieldThisTurn());

        // Only one of them died, and only one of them was Bob's.
        Assert.Equal(1, game.State.CreaturesDiedThisTurn(controllerId: bob));
        Assert.Equal(0, game.State.CreaturesDiedThisTurn(controllerId: alice));
        Assert.Equal(game.State, GameReducer.Replay(game.Log));
    }

    /// <summary>
    /// A stolen permanent that dies left under the control of whoever had taken it (CR 613.1b).
    /// </summary>
    /// <remarks>
    /// This is the case the scoping gets wrong if it is read off the departing object. Control is
    /// layer 2, so <c>obj.ControllerId</c> is only where control <em>started</em> — it is not
    /// rewritten when an effect takes the permanent — and a revolt card belonging to the thief
    /// would have stayed off while the victim's turned on. The fold cannot compute the answer, so
    /// the engine puts it on the move; this is the test that says the stamp is happening and is
    /// being read.
    /// <para>
    /// The two assertions are each other's control: an engine reading the stored controller passes
    /// neither, and an engine that simply gave both players the same answer fails the second.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_stolen_permanent_leaves_under_the_control_of_whoever_took_it()
    {
        var treason = Card(
            "Revolt Treason Test",
            "Gain control of target creature until end of turn.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(treason);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var bear = game.Create(bob, TestCards.Creature("Revolt Stolen Bear", 2, 2), Zone.Battlefield);

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, treason), [Target.ToPermanent(bear)]);
        Settle(game);

        game.Move(bear, Zone.Graveyard, MoveCause.Destroy);
        Settle(game);

        // It died under Alice's control, however it started, and however Bob's copy of the object
        // still reads.
        Assert.Equal(1, game.State.PermanentsLeftBattlefieldThisTurn(alice));
        Assert.Equal(0, game.State.PermanentsLeftBattlefieldThisTurn(bob));
        Assert.Equal(game.State, GameReducer.Replay(game.Log));
    }

    /// <summary>
    /// Celebration: "two or more nonland permanents entered the battlefield under your control
    /// this turn".
    /// </summary>
    /// <remarks>
    /// A different question from "did <em>this</em> permanent enter this turn", and about thirty
    /// corpus lines past it: nine for celebration itself, eight for "an artifact entered under your
    /// control this turn", and the rest spread over creatures, planeswalkers and single cards
    /// naming a subtype.
    /// <para>
    /// The land is what the test turns on. Two permanents entering is not celebration if one of
    /// them is a land, and a reader that counted permanents rather than nonland permanents would
    /// be turned on by a land drop plus anything — which is most turns of most games.
    /// </para>
    /// </remarks>
    [Fact]
    public void Permanents_that_entered_under_your_control_are_counted_without_the_lands()
    {
        var (game, alice, bob) = InMainPhase();

        game.Create(alice, TestCards.BasicLand("Celebration Forest"), Zone.Battlefield);
        var relic = game.Create(
            alice,
            Card("Celebration Relic", string.Empty, CardType.Artifact),
            Zone.Battlefield);
        Settle(game);

        // A land and an artifact is one nonland permanent, and celebration wants two.
        Assert.Equal(2, game.State.PermanentsEnteredThisTurn(alice));
        Assert.Equal(1, game.State.PermanentsEnteredThisTurn(alice, nonlandOnly: true));
        Assert.Equal(1, game.State.PermanentsEnteredThisTurn(alice, types: CardType.Artifact));

        game.Create(alice, TestCards.Creature("Celebration Bear", 2, 2), Zone.Battlefield);
        Settle(game);

        Assert.Equal(2, game.State.PermanentsEnteredThisTurn(alice, nonlandOnly: true));

        // "Another creature entered under your control this turn" is the same count with the
        // asking permanent taken out - and the relic is not a creature either way.
        Assert.Equal(
            1, game.State.PermanentsEnteredThisTurn(alice, types: CardType.Creature));
        Assert.Equal(
            0,
            game.State.PermanentsEnteredThisTurn(
                alice, types: CardType.Artifact, except: relic));

        // It is scoped to a player, and Bob has played nothing.
        Assert.Equal(0, game.State.PermanentsEnteredThisTurn(bob));

        PassToMainPhaseOfTurn(game, game.State.TurnNumber + 1);

        Assert.Equal(0, game.State.PermanentsEnteredThisTurn(alice));
        Assert.Equal(game.State, GameReducer.Replay(game.Log));
    }

    /// <summary>
    /// A permanent that entered and left in the same turn still entered.
    /// </summary>
    /// <remarks>
    /// The reason the arrivals are recorded rather than swept off the battlefield. Counting
    /// permanents stamped with this turn number would be free and would answer this one wrongly:
    /// a token created and sacrificed before the trigger looks is not there to be counted, and
    /// celebration does not ask what is on the board — it asks what arrived.
    /// </remarks>
    [Fact]
    public void A_permanent_that_entered_and_left_this_turn_is_still_counted_as_having_entered()
    {
        var (game, alice, _) = InMainPhase();

        var spark = game.Create(
            alice,
            Card("Celebration Spark", string.Empty, CardType.Creature | CardType.Token, 1, 1),
            Zone.Battlefield);
        game.Create(alice, TestCards.Creature("Celebration Second", 2, 2), Zone.Battlefield);
        Settle(game);

        game.Move(spark, Zone.Graveyard, MoveCause.Sacrifice);
        Settle(game);

        Assert.DoesNotContain(spark, game.State.Battlefield);
        Assert.Equal(2, game.State.PermanentsEnteredThisTurn(alice, nonlandOnly: true));
        Assert.Equal(game.State, GameReducer.Replay(game.Log));
    }

    /// <summary>
    /// "The number of creatures that died this turn", and the nontoken half of it.
    /// </summary>
    /// <remarks>
    /// Nineteen corpus cards multiply by this count and six of them say "nontoken", which a bool
    /// cannot answer at all and a single count answers wrongly: a board of tokens dying would
    /// otherwise make Rise of the Dread Marn and Gadrak twice the cards they are printed as. The
    /// token flag is a printed card type here, so the two counts come off the same record.
    /// </remarks>
    [Fact]
    public void Creatures_that_died_this_turn_are_counted_and_tokens_can_be_left_out()
    {
        var (game, _, bob) = InMainPhase();
        var first = game.Create(bob, TestCards.Creature("Died Count First", 2, 2), Zone.Battlefield);
        var second = game.Create(bob, TestCards.Creature("Died Count Second", 2, 2), Zone.Battlefield);
        var spirit = game.Create(
            bob,
            Card("Died Count Spirit", string.Empty, CardType.Creature | CardType.Token, 1, 1),
            Zone.Battlefield);
        Settle(game);

        game.Move(first, Zone.Graveyard, MoveCause.Destroy);
        game.Move(second, Zone.Graveyard, MoveCause.Destroy);
        game.Move(spirit, Zone.Graveyard, MoveCause.Destroy);
        Settle(game);

        Assert.Equal(3, game.State.CreaturesDiedThisTurn());
        Assert.Equal(2, game.State.CreaturesDiedThisTurn(nontokenOnly: true));
        Assert.True(game.State.CreatureDiedThisTurn);

        PassToMainPhaseOfTurn(game, game.State.TurnNumber + 1);

        Assert.Equal(0, game.State.CreaturesDiedThisTurn());
        Assert.False(game.State.CreatureDiedThisTurn);
    }

    /// <summary>
    /// "You descended this turn" is a permanent card reaching your graveyard (CR 700.11).
    /// </summary>
    /// <remarks>
    /// The rule defines the word and it is not about the graveyard's contents: descending is a
    /// card <em>arriving</em>, from anywhere, and CR 700.11 says in as many words that none of
    /// them need still be there. So the four things that look like it and are not each get an
    /// assertion — a mill counts as much as a death, a token is not a card (CR 111.7), an instant
    /// is not a permanent card, and it is another player's graveyard that decides whose count
    /// moves.
    /// <para>
    /// Descend 4 and descend 8 are deliberately not this, and nothing here should be taken as
    /// covering them: those read "there are four or more permanent cards in your graveyard", which
    /// is a count of the zone right now and needs no watcher at all.
    /// </para>
    /// </remarks>
    [Fact]
    public void Descending_counts_permanent_cards_reaching_your_graveyard_from_anywhere()
    {
        var (game, alice, bob) = InMainPhase();
        var bear = game.Create(alice, TestCards.Creature("Descend Bear", 2, 2), Zone.Battlefield);
        var husk = game.Create(
            alice,
            Card("Descend Husk", string.Empty, CardType.Creature | CardType.Token, 1, 1),
            Zone.Battlefield);
        var forest = game.Create(alice, TestCards.BasicLand("Descend Forest"), Zone.Library);
        var jolt = game.Create(alice, Card("Descend Jolt", string.Empty), Zone.Hand);
        Settle(game);

        Assert.Equal(0, game.State.GetPlayer(alice).TimesDescendedThisTurn);

        // A creature card dying is a permanent card put into its owner's graveyard.
        game.Move(bear, Zone.Graveyard, MoveCause.Destroy);
        Settle(game);
        Assert.Equal(1, game.State.GetPlayer(alice).TimesDescendedThisTurn);

        // "From anywhere": milled off the library counts exactly as much as dying does.
        game.Move(forest, Zone.Graveyard, MoveCause.Mill);
        Settle(game);
        Assert.Equal(2, game.State.GetPlayer(alice).TimesDescendedThisTurn);

        // A token is not a card, so it descends nobody.
        game.Move(husk, Zone.Graveyard, MoveCause.Destroy);
        Settle(game);
        Assert.Equal(2, game.State.GetPlayer(alice).TimesDescendedThisTurn);

        // Nor is an instant a permanent card.
        game.Move(jolt, Zone.Graveyard, MoveCause.Discard);
        Settle(game);
        Assert.Equal(2, game.State.GetPlayer(alice).TimesDescendedThisTurn);

        // It is that player's graveyard the rule names, and Bob's has had nothing in it.
        Assert.Equal(0, game.State.GetPlayer(bob).TimesDescendedThisTurn);

        PassToMainPhaseOfTurn(game, game.State.TurnNumber + 1);

        Assert.Equal(0, game.State.GetPlayer(alice).TimesDescendedThisTurn);
        Assert.Equal(game.State, GameReducer.Replay(game.Log));
    }

    /// <summary>
    /// "You get an experience counter", and it is still there next turn (CR 122.1).
    /// </summary>
    /// <remarks>
    /// Sixteen commanders hand these out and eighteen cards read the total back as "for each
    /// experience counter you have"; nothing in the corpus removes one. The turn boundary is the
    /// assertion that matters: every other number that arrived on <c>PlayerState</c> beside this
    /// one is cleared when a turn begins, and clearing this one would make every card that reads
    /// it a strictly worse card than the one printed, with nothing failing to say so.
    /// <para>
    /// Hand-built, like the four spells further up this file: the effect is engine machinery whose
    /// reader is being written separately, and a test that waited for the reader would be a test
    /// of two things that fails for either.
    /// </para>
    /// </remarks>
    [Fact]
    public void An_experience_counter_is_kept_past_the_turn_that_gave_it()
    {
        var rite = Card("Experience Rite Test", "You get an experience counter.", CardType.Sorcery);
        var pool = new HandBuilt().WithSpell(
            rite, new SpellDefinition { Effects = [new GainExperience(1)] });

        var (game, alice, bob) = InMainPhaseWith(pool);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, rite));
        Settle(game);
        Assert.Equal(1, game.State.GetPlayer(alice).ExperienceCounters);

        // They accumulate, which is the whole of what "for each experience counter you have" is
        // multiplying by.
        game.CastSpell(alice, TestCards.PutInHand(game, alice, rite));
        Settle(game);
        Assert.Equal(2, game.State.GetPlayer(alice).ExperienceCounters);
        Assert.Equal(0, game.State.GetPlayer(bob).ExperienceCounters);

        PassToMainPhaseOfTurn(game, game.State.TurnNumber + 1);

        Assert.Equal(2, game.State.GetPlayer(alice).ExperienceCounters);
        Assert.Equal(game.State, GameReducer.Replay(game.Log));
    }

    // ---- Cost modification, prevention, and restricted mana ------------------

    /// <summary>
    /// A card pool written out rather than compiled, for engine capability with no reader yet.
    /// </summary>
    /// <remarks>
    /// <see cref="HandBuilt"/> above answers about spells and nothing else; these tests need
    /// activated abilities and cost modifiers as well, which is the whole of the difference.
    /// <para>
    /// Every other test in this file compiles real oracle wording, which is the right way to test
    /// a template: the card the engine plays is the card that was printed. These capabilities
    /// have no template yet — reading the sentences is the other half of the work — so what is
    /// under test here is the engine's answer once it has been told, and the wording each
    /// definition stands for is quoted on the card it is attached to.
    /// </para>
    /// </remarks>
    private sealed class HandWritten : IAbilitySource, ICostModifierSource
    {
        private readonly Dictionary<string, List<ActivatedAbilityDefinition>> _activated = [];
        private readonly Dictionary<string, List<CostModifier>> _modifiers = [];
        private readonly Dictionary<string, SpellDefinition> _spells = [];

        public IReadOnlyList<TriggeredAbilityDefinition> TriggersOf(CardDefinition card) => [];

        public SpellDefinition? SpellOf(CardDefinition card) =>
            _spells.GetValueOrDefault(card.OracleId);

        public IReadOnlyList<ActivatedAbilityDefinition> ActivatedOf(CardDefinition card) =>
            _activated.TryGetValue(card.OracleId, out var abilities) ? abilities : [];

        public IReadOnlyList<CostModifier> CostModifiersOf(CardDefinition card) =>
            _modifiers.TryGetValue(card.OracleId, out var found) ? found : [];

        public HandWritten Give(CardDefinition card, ActivatedAbilityDefinition ability)
        {
            if (!_activated.TryGetValue(card.OracleId, out var abilities))
                _activated[card.OracleId] = abilities = [];

            abilities.Add(ability);
            return this;
        }

        public HandWritten Give(CardDefinition card, CostModifier modifier)
        {
            if (!_modifiers.TryGetValue(card.OracleId, out var found))
                _modifiers[card.OracleId] = found = [];

            found.Add(modifier);
            return this;
        }

        public HandWritten Give(CardDefinition card, SpellDefinition spell)
        {
            _spells[card.OracleId] = spell;
            return this;
        }
    }

    /// <summary>A land with nothing printed on it, so only the hand-written ability speaks.</summary>
    private static readonly CardDefinition HandLand = new()
    {
        OracleId = "oracle-hand-written-land",
        Name = "Hand Written Land Test",
        CardTypes = CardType.Land,
    };

    private static readonly ActivatedAbilityDefinition TapsForGreen = new()
    {
        Id = "mana",
        Text = "{T}: Add {G}.",
        RequiresTap = true,
        Produces = [new ManaProduction(ManaColor.Green)],
    };

    /// <summary>
    /// The same mana ability, with a restriction on what the mana it makes may pay for.
    /// </summary>
    /// <remarks>
    /// Produced by an ability rather than pushed into the pool, because the question these ask
    /// is what a real payment does with it — a pool built by hand answers about
    /// <see cref="ManaPayment"/> and says nothing about whether the engine ever tells it what a
    /// payment is for.
    /// </remarks>
    private static ActivatedAbilityDefinition TapsForRestrictedGreen(
        ManaRestriction restriction) => new()
        {
            Id = "mana",
            Text = "{T}: Add {G}.",
            RequiresTap = true,
            Produces = [new ManaProduction(ManaColor.Green, 1, restriction)],
        };

    /// <summary>An ability priced at {2}, so a discount of {1} is visible in the pool.</summary>
    private static readonly ActivatedAbilityDefinition PricedAtTwo = new()
    {
        Id = "ping",
        Text = "{2}: Nothing happens.",
        ManaCost = ManaCostSpec.Parse("{2}"),
    };

    /// <summary>Puts lands on the battlefield and taps them, so a cost has something to pay it.</summary>
    private static void TapForGreen(Game game, Guid playerId, int count)
    {
        for (var i = 0; i < count; i++)
            game.ActivateAbility(playerId, game.Create(playerId, HandLand, Zone.Battlefield), "mana");
    }

    private static void PassToMainPhaseOf(Game game, Guid playerId) =>
        TestCards.PassUntil(
            game,
            () => game.State.ActivePlayerId == playerId
                && game.State.CurrentStep == TurnStep.PrecombatMain);

    /// <summary>
    /// "Spells your opponents cast cost {1} more to cast" — 24 corpus lines (CR 601.2f).
    /// </summary>
    /// <remarks>
    /// The assertion that catches the wrong reading is the first one, not the second. The only
    /// cost modification the engine had walked the <em>caster's own</em> battlefield and applied
    /// whatever it found there, so a modifier scoped to opponents would have taxed its own
    /// controller — a card that reads as printed and plays as its own opposite.
    /// </remarks>
    [Fact]
    public void A_tax_on_your_opponents_spells_leaves_your_own_alone()
    {
        var statue = new CardDefinition
        {
            OracleId = "oracle-opponent-tax-test",
            Name = "Opponent Tax Test",
            OracleText = "Spells your opponents cast cost {1} more to cast.",
            CardTypes = CardType.Artifact,
        };

        var pool = new HandWritten()
            .Give(HandLand, TapsForGreen)
            .Give(statue, new CostModifier
            {
                Amount = 1,
                Change = CostChange.Increase,
                Who = PlayerScope.EachOpponent,
            });

        var (game, alice, bob) = InMainPhaseWith(pool);
        game.Create(alice, statue, Zone.Battlefield);

        var mine = TestCards.PutInHand(
            game, alice, TestCards.Costed("Untaxed Bear Test", "{G}", 1));

        TapForGreen(game, alice, 1);
        game.CastSpell(alice, mine, []);
        Assert.True(game.State.GetPlayer(alice).ManaPool.IsEmpty);
        Settle(game);

        // Bob is the opponent the statue names, so the same spell costs him {1}{G}.
        PassToMainPhaseOf(game, bob);
        var theirs = TestCards.PutInHand(
            game, bob, TestCards.Costed("Taxed Bear Test", "{G}", 1));

        TapForGreen(game, bob, 1);
        Assert.Throws<InvalidOperationException>(() => game.CastSpell(bob, theirs, []));

        TapForGreen(game, bob, 1);
        game.CastSpell(bob, theirs, []);
        Assert.True(game.State.GetPlayer(bob).ManaPool.IsEmpty);
        Settle(game);
    }

    /// <summary>
    /// "Activated abilities of creatures you control cost {2} less to activate" (CR 602.2b).
    /// </summary>
    /// <remarks>
    /// An activated ability's cost had no modifier hook at all — it went straight from the
    /// definition to the pool — so all 55 corpus lines of this shape were inert.
    /// <para>
    /// Two scopes rather than one, and this is the test that tells them apart. "Abilities
    /// <em>you activate</em>" asks who is paying; "abilities <em>of creatures you control</em>"
    /// asks whose permanent the ability sits on, and says nothing about who activates it. Bob
    /// activating his own creature's ability answers yes to neither.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_discount_on_abilities_of_creatures_you_control_misses_an_opponents_creature()
    {
        var familiar = new CardDefinition
        {
            OracleId = "oracle-ability-discount-test",
            Name = "Ability Discount Test",
            OracleText = "Activated abilities of creatures you control cost {1} less to activate.",
            CardTypes = CardType.Artifact,
        };

        var pinger = TestCards.Costed("Discounted Pinger Test", "{1}", 1);

        var pool = new HandWritten()
            .Give(HandLand, TapsForGreen)
            .Give(pinger, PricedAtTwo)
            .Give(familiar, new CostModifier
            {
                Amount = 1,
                Kind = CostModifierKind.ActivatedAbilities,
                FilterId = "creature",
                Who = PlayerScope.EachPlayer,
                SourceController = PlayerScope.You,
            });

        var (game, alice, bob) = InMainPhaseWith(pool);
        game.Create(alice, familiar, Zone.Battlefield);
        var hers = game.Create(alice, pinger, Zone.Battlefield);

        TapForGreen(game, alice, 1);
        game.ActivateAbility(alice, hers, "ping");
        Assert.True(game.State.GetPlayer(alice).ManaPool.IsEmpty);
        Settle(game);

        PassToMainPhaseOf(game, bob);
        var theirs = game.Create(bob, pinger, Zone.Battlefield);

        TapForGreen(game, bob, 1);
        Assert.Throws<InvalidOperationException>(() => game.ActivateAbility(bob, theirs, "ping"));

        TapForGreen(game, bob, 1);
        game.ActivateAbility(bob, theirs, "ping");
        Assert.True(game.State.GetPlayer(bob).ManaPool.IsEmpty);
        Settle(game);
    }

    /// <summary>
    /// "This ability costs {1} less to activate" is a permanent talking about itself.
    /// </summary>
    /// <remarks>
    /// Read as "abilities you activate cost {1} less" it would discount every other permanent its
    /// controller has, which is a strictly better card — the failure this file exists to catch.
    /// </remarks>
    [Fact]
    public void A_self_discount_reaches_no_other_permanents_abilities()
    {
        var machine = TestCards.Costed("Self Discount Test", "{1}", 1);
        var other = TestCards.Costed("Undiscounted Pinger Test", "{1}", 1);

        var pool = new HandWritten()
            .Give(HandLand, TapsForGreen)
            .Give(machine, PricedAtTwo)
            .Give(other, PricedAtTwo)
            .Give(machine, new CostModifier
            {
                Amount = 1,
                Kind = CostModifierKind.ActivatedAbilities,
                SourceOnly = true,
            });

        var (game, alice, _) = InMainPhaseWith(pool);
        var itself = game.Create(alice, machine, Zone.Battlefield);
        var neighbour = game.Create(alice, other, Zone.Battlefield);

        TapForGreen(game, alice, 1);
        game.ActivateAbility(alice, itself, "ping");
        Assert.True(game.State.GetPlayer(alice).ManaPool.IsEmpty);

        // The permanent beside it pays the printed price.
        TapForGreen(game, alice, 1);
        Assert.Throws<InvalidOperationException>(
            () => game.ActivateAbility(alice, neighbour, "ping"));

        TapForGreen(game, alice, 1);
        game.ActivateAbility(alice, neighbour, "ping");
        Assert.True(game.State.GetPlayer(alice).ManaPool.IsEmpty);
        Settle(game);
    }

    /// <summary>
    /// CR 601.2f states the order: increases first, then reductions.
    /// </summary>
    /// <remarks>
    /// The other order is not a rounding difference. A {1}{G} spell taxed {2} and discounted {2}
    /// costs {1}{G} the way the rule says it; reducing first floors the discount against a cost
    /// that only has {1} of generic in it and then charges the whole tax on top, leaving {2}{G}.
    /// Two green mana is exactly the amount that tells the two apart.
    /// </remarks>
    [Fact]
    public void A_cost_increase_is_applied_before_a_cost_reduction()
    {
        var tax = new CardDefinition
        {
            OracleId = "oracle-order-tax-test",
            Name = "Order Tax Test",
            OracleText = "Spells cost {2} more to cast.",
            CardTypes = CardType.Enchantment,
        };

        var rebate = new CardDefinition
        {
            OracleId = "oracle-order-rebate-test",
            Name = "Order Rebate Test",
            OracleText = "Spells you cast cost {2} less to cast.",
            CardTypes = CardType.Enchantment,
        };

        var pool = new HandWritten()
            .Give(HandLand, TapsForGreen)
            .Give(tax, new CostModifier
            {
                Amount = 2,
                Change = CostChange.Increase,
                Who = PlayerScope.EachPlayer,
            })
            .Give(rebate, new CostModifier { Amount = 2, Who = PlayerScope.You });

        var (game, alice, _) = InMainPhaseWith(pool);
        game.Create(alice, tax, Zone.Battlefield);
        game.Create(alice, rebate, Zone.Battlefield);

        var spell = TestCards.PutInHand(
            game, alice, TestCards.Costed("Balanced Bear Test", "{1}{G}", 2));

        TapForGreen(game, alice, 2);
        game.CastSpell(alice, spell, []);

        Assert.True(game.State.GetPlayer(alice).ManaPool.IsEmpty);
        Settle(game);
    }

    /// <summary>
    /// "Spells you cast from your graveyard cost {1} less to cast" (CR 601.2f, 400.1).
    /// </summary>
    /// <remarks>
    /// The zone has to be read on the modifier <em>and</em> at the payment, or not at all. A
    /// modifier carrying a zone that nothing consulted applies its reduction from every zone,
    /// which makes a narrow card into a broad one — worse than leaving the line unread.
    /// <para>
    /// Both halves are on the board at once, so the assertion is what is left in the pool rather
    /// than whether the spell was castable: a zone that went unread would take {2} off a {2}{G}
    /// spell instead of {1}, and both readings can pay for it out of three mana.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_reduction_that_names_a_zone_applies_only_from_that_zone()
    {
        var fromHand = new CardDefinition
        {
            OracleId = "oracle-zone-hand-test",
            Name = "Zone Hand Test",
            OracleText = "Spells you cast from your hand cost {1} less to cast.",
            CardTypes = CardType.Enchantment,
        };

        var fromGraveyard = new CardDefinition
        {
            OracleId = "oracle-zone-graveyard-test",
            Name = "Zone Graveyard Test",
            OracleText = "Spells you cast from your graveyard cost {1} less to cast.",
            CardTypes = CardType.Enchantment,
        };

        var pool = new HandWritten()
            .Give(HandLand, TapsForGreen)
            .Give(fromHand, new CostModifier { Amount = 1, FromZone = Zone.Hand })
            .Give(fromGraveyard, new CostModifier { Amount = 1, FromZone = Zone.Graveyard });

        var (game, alice, _) = InMainPhaseWith(pool);
        game.Create(alice, fromHand, Zone.Battlefield);
        game.Create(alice, fromGraveyard, Zone.Battlefield);

        var spell = TestCards.PutInHand(
            game, alice, TestCards.Costed("Zoned Bear Test", "{2}{G}", 3));

        TapForGreen(game, alice, 3);
        game.CastSpell(alice, spell, []);

        // One reduction, not two: the spell was cast from hand and cost {1}{G}.
        Assert.Equal(1, game.State.GetPlayer(alice).ManaPool[ManaColor.Green]);
        Settle(game);
    }

    /// <summary>A three-damage instant, for the prevention effects to be measured against.</summary>
    private static CardDefinition BurnCard(string name) => new()
    {
        OracleId = "oracle-" + name.ToLowerInvariant().Replace(' ', '-'),
        Name = name,
        OracleText = "~ deals 3 damage to any target.",
        CardTypes = CardType.Instant,
    };

    private static SpellDefinition BurnAPlayer() => new()
    {
        Targets = [new TargetSpec { Kind = TargetKind.Player, Description = "any player" }],
        Effects = [new DealDamage(new Amount(3))],
    };

    private static SpellDefinition BurnACreature() => new()
    {
        Targets =
        [
            new TargetSpec
            {
                Kind = TargetKind.Permanent,
                Description = "target creature",
                ObjectFilter = (state, abilities, obj, _) =>
                    Characteristics.Of(state, abilities, obj).IsCreature,
            },
        ],
        Effects = [new DealDamage(new Amount(3))],
    };

    private static CardDefinition WardCard(string name, string text) => new()
    {
        OracleId = "oracle-" + name.ToLowerInvariant().Replace(' ', '-'),
        Name = name,
        OracleText = text,
        CardTypes = CardType.Instant,
    };

    /// <summary>
    /// "Prevent all combat damage that would be dealt this turn" is not a fog for burn.
    /// </summary>
    /// <remarks>
    /// Fifteen corpus lines print exactly that sentence, and it is the commonest prevention
    /// wording there is. One word separates it from the shield that stops everything, and a
    /// prevention effect that ignored the word would turn every fog into a blanket ward.
    /// </remarks>
    [Fact]
    public void A_prevention_of_combat_damage_lets_a_burn_spell_through()
    {
        var combatWard = WardCard(
            "Combat Ward Test", "Prevent all combat damage that would be dealt this turn.");
        var anyWard = WardCard(
            "Any Ward Test", "Prevent all damage that would be dealt this turn.");
        var burn = BurnCard("Prevention Burn Test");

        var pool = new HandWritten()
            .Give(burn, BurnAPlayer())
            .Give(combatWard, new SpellDefinition
            {
                Effects =
                [
                    new PreventDescribedDamage { Kind = DamageKind.Combat },
                ],
            })
            .Give(anyWard, new SpellDefinition
            {
                Effects = [new PreventDescribedDamage()],
            });

        var (game, alice, _) = InMainPhaseWith(pool);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, combatWard), []);
        Settle(game);

        game.CastSpell(
            game.State.Priority.Holder ?? alice,
            TestCards.PutInHand(game, alice, burn),
            [Target.ToPlayer(alice)]);
        Settle(game);

        // Not combat damage, so the combat shield never watched for it.
        Assert.Equal(17, game.State.GetPlayer(alice).Life);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, anyWard), []);
        Settle(game);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, burn), [Target.ToPlayer(alice)]);
        Settle(game);

        Assert.Equal(17, game.State.GetPlayer(alice).Life);
    }

    /// <summary>
    /// "Prevent all damage that would be dealt to creatures you control" (CR 615.1).
    /// </summary>
    /// <remarks>
    /// The shape the engine's only prevention could not express at all. A countdown shield
    /// (CR 615.7) is created per target, so a sentence that names a described group rather than a
    /// target had nowhere to be put — and there are 97 such cards.
    /// <para>
    /// Bob's creature is the case that catches the wrong reading: a prevention that forgot whose
    /// creatures it named would fog the whole board, which is a different and much stronger card.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_prevention_for_creatures_you_control_does_not_shield_an_opponents()
    {
        var ward = WardCard(
            "Group Ward Test", "Prevent all damage that would be dealt to creatures you control.");
        var burn = BurnCard("Group Burn Test");

        var pool = new HandWritten()
            .Give(burn, BurnACreature())
            .Give(ward, new SpellDefinition
            {
                Effects =
                [
                    new PreventDescribedDamage
                    {
                        PermanentFilter = "creature",
                        PermanentController = PlayerScope.You,
                    },
                ],
            });

        var (game, alice, bob) = InMainPhaseWith(pool);
        var hers = game.Create(alice, TestCards.Creature("Warded Bear Test", 2, 2), Zone.Battlefield);
        var theirs = game.Create(bob, TestCards.Creature("Exposed Bear Test", 2, 2), Zone.Battlefield);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, ward), []);
        Settle(game);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, burn), [Target.ToPermanent(hers)]);
        Settle(game);

        Assert.Equal(0, game.State.GetObject(hers).Permanent?.DamageMarked);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, burn), [Target.ToPermanent(theirs)]);
        Settle(game);

        Assert.DoesNotContain(theirs, game.State.Battlefield);

        // Written and read back while the shield is still standing, so a field lost on the way
        // through - the filter, the scope - shows up as two states that disagree rather than as a
        // card that quietly stops being narrow.
        Assert.Single(game.State.Preventions);
        Assert.Equal(
            game.State,
            GameReducer.Replay(EventLogSerializer.Read(EventLogSerializer.Write(game.Log))));
    }

    /// <summary>
    /// CR 615.10: a numbered prevention from a static effect caps each damage event separately.
    /// </summary>
    /// <remarks>
    /// The distinction the engine did not have. CR 615.7's shield is a pool of points that runs
    /// out; this is a cap that applies again to the next event, which is why Daunting Defender
    /// keeps saving its Clerics all game. Two identical burn spells tell the two apart: a shield
    /// of one prevents one damage once, and this prevents one from each.
    /// </remarks>
    [Fact]
    public void A_numbered_prevention_applies_again_to_the_next_damage_event()
    {
        var ward = WardCard(
            "Capped Ward Test",
            "If a source would deal damage to you, prevent 1 of that damage.");
        var burn = BurnCard("Capped Burn Test");

        var pool = new HandWritten()
            .Give(burn, BurnAPlayer())
            .Give(ward, new SpellDefinition
            {
                Effects =
                [
                    new PreventDescribedDamage { Amount = 1, Players = PlayerScope.You },
                ],
            });

        var (game, alice, _) = InMainPhaseWith(pool);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, ward), []);
        Settle(game);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, burn), [Target.ToPlayer(alice)]);
        Settle(game);
        Assert.Equal(18, game.State.GetPlayer(alice).Life);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, burn), [Target.ToPlayer(alice)]);
        Settle(game);

        // Two, not three: nothing was spent the first time.
        Assert.Equal(16, game.State.GetPlayer(alice).Life);
    }

    /// <summary>
    /// A prevention effect that says "this turn" ends with the turn (CR 514.2).
    /// </summary>
    /// <remarks>
    /// The failure this guards against has already happened once here, on the countdown shield:
    /// cleanup took the damage off and left the shield standing, so a fog bought on one turn went
    /// on fogging every turn afterwards. It is derived from the turn the effect was made on
    /// rather than announced by an event of its own, so there is nothing to forget to emit.
    /// </remarks>
    [Fact]
    public void A_prevention_that_says_this_turn_is_gone_next_turn()
    {
        var ward = WardCard(
            "Expiring Ward Test", "Prevent all damage that would be dealt this turn.");
        var burn = BurnCard("Expiring Burn Test");

        var pool = new HandWritten()
            .Give(burn, BurnAPlayer())
            .Give(ward, new SpellDefinition { Effects = [new PreventDescribedDamage()] });

        var (game, alice, _) = InMainPhaseWith(pool);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, ward), []);
        Settle(game);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, burn), [Target.ToPlayer(alice)]);
        Settle(game);
        Assert.Equal(20, game.State.GetPlayer(alice).Life);

        PassToMainPhaseOfTurn(game, 3);
        Assert.Empty(game.State.Preventions);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, burn), [Target.ToPlayer(alice)]);
        Settle(game);
        Assert.Equal(17, game.State.GetPlayer(alice).Life);

        // The new event carries a whole record rather than a name into a registry, so the one
        // thing that could go wrong quietly is the way back in: a log that writes and will not
        // read is a saved game the players lose.
        Assert.Equal(
            game.State,
            GameReducer.Replay(EventLogSerializer.Read(EventLogSerializer.Write(game.Log))));
    }

    /// <summary>
    /// "Spend this mana only to cast Dragon spells" (CR 106.6) — the tribe the type mask cannot say.
    /// </summary>
    /// <remarks>
    /// A restriction could name a purpose and a mask of card types and nothing else, which reads
    /// about half the wordings the corpus prints. The filter is the shared vocabulary, so the
    /// tribe, a negation, a supertype and a colour count all arrive together.
    /// <para>
    /// The Human is the case that catches the wrong reading: it is a creature spell, which is
    /// everything the type mask could ask about, and it is not a Dragon.
    /// </para>
    /// </remarks>
    [Fact]
    public void Mana_restricted_to_a_tribe_refuses_a_creature_of_another_one()
    {
        var dragon = new CardDefinition
        {
            OracleId = "oracle-restricted-dragon-test",
            Name = "Restricted Dragon Test",
            CardTypes = CardType.Creature,
            Subtypes = ["Dragon"],
            ManaCostRaw = "{G}",
            Cmc = 1,
        };

        var human = TestCards.Costed("Restricted Human Test", "{G}", 1);

        var pool = ManaPool.Empty.AddRestricted(
            new RestrictedMana(
                ManaColor.Green,
                new ManaRestriction(ManaPurpose.CastSpell, CardType.Creature))
            {
                FilterId = "Dragon",
            });

        Assert.NotNull(ManaPayment.Pay(
            pool, ManaCostSpec.Parse("{G}"), spend: ManaSpend.Casting(dragon, Zone.Hand)));

        Assert.Null(ManaPayment.Pay(
            pool, ManaCostSpec.Parse("{G}"), spend: ManaSpend.Casting(human, Zone.Hand)));
    }

    /// <summary>
    /// "Spend this mana only to cast a noncreature spell", and the colour counts beside it.
    /// </summary>
    /// <remarks>
    /// A negation cannot be said with a type mask at all: the mask is a set of types the card has
    /// to have one of, and "noncreature" is the one it must not. Both go through the same filter
    /// vocabulary the tutors use, so neither needed a reader of its own.
    /// </remarks>
    [Fact]
    public void Mana_restricted_to_noncreature_spells_refuses_a_creature()
    {
        var bolt = new CardDefinition
        {
            OracleId = "oracle-restricted-noncreature-test",
            Name = "Restricted Noncreature Test",
            CardTypes = CardType.Instant,
            ManaCostRaw = "{G}",
            Cmc = 1,
            Colors = [ManaColor.Green, ManaColor.Red],
        };

        var bear = TestCards.Costed("Restricted Noncreature Bear Test", "{G}", 1);

        var noncreature = ManaPool.Empty.AddRestricted(
            new RestrictedMana(ManaColor.Green, new ManaRestriction(ManaPurpose.CastSpell, default))
            {
                FilterId = "noncreature",
            });

        Assert.NotNull(ManaPayment.Pay(
            noncreature, ManaCostSpec.Parse("{G}"), spend: ManaSpend.Casting(bolt, Zone.Hand)));

        Assert.Null(ManaPayment.Pay(
            noncreature, ManaCostSpec.Parse("{G}"), spend: ManaSpend.Casting(bear, Zone.Hand)));

        // "Spend this mana only to cast a multicolored spell": two colours, not two of anything
        // else, which is why it could not go in the colour table (CR 105.4).
        var multicoloured = ManaPool.Empty.AddRestricted(
            new RestrictedMana(ManaColor.Green, new ManaRestriction(ManaPurpose.CastSpell, default))
            {
                FilterId = "multicolored",
            });

        Assert.NotNull(ManaPayment.Pay(
            multicoloured, ManaCostSpec.Parse("{G}"), spend: ManaSpend.Casting(bolt, Zone.Hand)));

        Assert.Null(ManaPayment.Pay(
            multicoloured, ManaCostSpec.Parse("{G}"), spend: ManaSpend.Casting(bear, Zone.Hand)));
    }

    /// <summary>
    /// "Spend this mana only to cast spells from your graveyard" (CR 106.6, 400.1).
    /// </summary>
    [Fact]
    public void Mana_restricted_to_a_zone_refuses_a_spell_cast_from_anywhere_else()
    {
        var bear = TestCards.Costed("Restricted Zone Bear Test", "{G}", 1);

        var pool = ManaPool.Empty.AddRestricted(
            new RestrictedMana(ManaColor.Green, new ManaRestriction(ManaPurpose.CastSpell, default))
            {
                FromZone = Zone.Graveyard,
            });

        Assert.NotNull(ManaPayment.Pay(
            pool, ManaCostSpec.Parse("{G}"), spend: ManaSpend.Casting(bear, Zone.Graveyard)));

        Assert.Null(ManaPayment.Pay(
            pool, ManaCostSpec.Parse("{G}"), spend: ManaSpend.Casting(bear, Zone.Hand)));
    }

    /// <summary>
    /// "Spend this mana only to cast your commander" (CR 903.3) — Jeweled Lotus.
    /// </summary>
    /// <remarks>
    /// Not something a card filter can answer. Which card is a commander is a fact about this
    /// game and this player, and the same card in somebody else's deck is not one — so it is
    /// asked of the payment rather than of the card.
    /// </remarks>
    [Fact]
    public void Mana_restricted_to_your_commander_pays_for_nothing_else()
    {
        var general = TestCards.Costed("Restricted Commander Test", "{G}", 1);

        var pool = ManaPool.Empty.AddRestricted(
            new RestrictedMana(ManaColor.Green, new ManaRestriction(ManaPurpose.CastSpell, default))
            {
                CommanderOnly = true,
            });

        Assert.NotNull(ManaPayment.Pay(
            pool,
            ManaCostSpec.Parse("{G}"),
            spend: ManaSpend.Casting(general, Zone.Command, isCommander: true)));

        Assert.Null(ManaPayment.Pay(
            pool, ManaCostSpec.Parse("{G}"), spend: ManaSpend.Casting(general, Zone.Command)));
    }

    /// <summary>A card with morph, and an artifact type the face-down spell does not have.</summary>
    /// <remarks>
    /// An artifact creature on purpose. CR 702.37a casts it as "a 2/2 face-down creature with no
    /// text, no name, no subtypes, and no mana cost", so every question asked about the spell has
    /// two answers available — the printed card's and the face-down one's — and they differ in
    /// exactly one respect that a cost modifier and a restricted mana can both read.
    /// </remarks>
    private static readonly CardDefinition MorphMyr = new()
    {
        OracleId = "oracle-face-down-cast-test",
        Name = "Face Down Cast Test",
        OracleText = "Morph {2}{G}",
        CardTypes = CardType.Artifact | CardType.Creature,
        Subtypes = ["Myr"],
        ManaCostRaw = "{4}{G}",
        Cmc = 5,
        Power = 4,
        Toughness = 4,
    };

    private static readonly SpellDefinition MorphedForTwoGreen = new()
    {
        MorphCost = ManaCostSpec.Parse("{2}{G}"),
    };

    /// <summary>Taps <paramref name="count"/> of one hand-written land for its mana.</summary>
    private static void TapEach(Game game, Guid playerId, CardDefinition land, int count)
    {
        for (var i = 0; i < count; i++)
            game.ActivateAbility(playerId, game.Create(playerId, land, Zone.Battlefield), "mana");
    }

    /// <summary>
    /// A face-down creature spell is a spell being cast, so the board's taxes reach it (CR 601.2f).
    /// </summary>
    /// <remarks>
    /// The one cast in the engine that went straight from a literal <c>{3}</c> to the pool. Every
    /// other cast had its cost passed through CR 601.2f; this one did not, so a face-down spell
    /// was cast under a Thalia for {3} and no cost modifier on the board could see it.
    /// <para>
    /// The discount is the assertion that catches the wrong reading, and it is why the card is an
    /// artifact creature rather than a creature. Reading the modifiers against the card
    /// <em>underneath</em> would find an artifact spell and take {2} off — a face-down spell that
    /// is cheaper for what it is hiding, which is the direction that costs a game rather than a
    /// refusal. CR 702.37a says the spell is a 2/2 creature with no subtypes; the artifact type
    /// is on the card, not on what is being cast.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_tax_on_every_spell_reaches_a_spell_cast_face_down()
    {
        var sphere = new CardDefinition
        {
            OracleId = "oracle-face-down-tax-test",
            Name = "Face Down Tax Test",
            OracleText = "Spells cost {1} more to cast.",
            CardTypes = CardType.Artifact,
        };

        var foundry = new CardDefinition
        {
            OracleId = "oracle-face-down-discount-test",
            Name = "Face Down Discount Test",
            OracleText = "Artifact spells you cast cost {2} less to cast.",
            CardTypes = CardType.Artifact,
        };

        var pool = new HandWritten()
            .Give(HandLand, TapsForGreen)
            .Give(MorphMyr, MorphedForTwoGreen)
            .Give(sphere, new CostModifier
            {
                Amount = 1,
                Change = CostChange.Increase,
                Who = PlayerScope.EachPlayer,
            })
            .Give(foundry, new CostModifier { Amount = 2, FilterId = "artifact" });

        var (game, alice, _) = InMainPhaseWith(pool);
        game.Create(alice, sphere, Zone.Battlefield);
        game.Create(alice, foundry, Zone.Battlefield);

        var myr = TestCards.PutInHand(game, alice, MorphMyr);

        // {3} taxed {1} and discounted nothing. Three is what the printed cost of a face-down
        // spell has always been, so this is the assertion that fails on the old engine.
        TapForGreen(game, alice, 3);
        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, myr, [], faceDown: true));

        TapForGreen(game, alice, 1);
        game.CastSpell(alice, myr, [], faceDown: true);
        Assert.True(game.State.GetPlayer(alice).ManaPool.IsEmpty);
        Settle(game);
    }

    /// <summary>
    /// "Spend this mana only to cast creature spells" pays for one cast face down (CR 106.6).
    /// </summary>
    /// <remarks>
    /// The other half of the same omission. A face-down cast was paid with no
    /// <see cref="ManaSpend"/> at all, so every restricted mana in the pool answered the default
    /// question — neither a cast nor an activation — and refused. A player holding three mana
    /// that may only cast creatures could not cast a creature.
    /// <para>
    /// The artifact-restricted mana is the wrong reading, and the same one the tax test catches
    /// from the other side: the card underneath is an artifact, and the spell is not.
    /// </para>
    /// </remarks>
    [Fact]
    public void Mana_restricted_to_creature_spells_pays_for_a_spell_cast_face_down()
    {
        var nest = new CardDefinition
        {
            OracleId = "oracle-face-down-creature-mana-test",
            Name = "Face Down Creature Mana Test",
            OracleText = "{T}: Add {G}. Spend this mana only to cast creature spells.",
            CardTypes = CardType.Land,
        };

        var vault = new CardDefinition
        {
            OracleId = "oracle-face-down-artifact-mana-test",
            Name = "Face Down Artifact Mana Test",
            OracleText = "{T}: Add {G}. Spend this mana only to cast artifact spells.",
            CardTypes = CardType.Land,
        };

        var pool = new HandWritten()
            .Give(nest, TapsForRestrictedGreen(new ManaRestriction(
                ManaPurpose.CastSpell, CardType.Creature)))
            .Give(vault, TapsForRestrictedGreen(new ManaRestriction(
                ManaPurpose.CastSpell, CardType.Artifact)))
            .Give(MorphMyr, MorphedForTwoGreen);

        var (game, alice, _) = InMainPhaseWith(pool);
        var myr = TestCards.PutInHand(game, alice, MorphMyr);

        TapEach(game, alice, vault, 3);
        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, myr, [], faceDown: true));

        TapEach(game, alice, nest, 3);
        game.CastSpell(alice, myr, [], faceDown: true);

        // The three that could not pay are still there, which is what says the other three did.
        var left = game.State.GetPlayer(alice).ManaPool;
        Assert.Equal(3, left.Restricted.Count);
        Assert.All(
            left.Restricted,
            mana => Assert.False(mana.Allows(
                ManaSpend.Casting(Characteristics.FaceDownSpell, Zone.Hand))));

        Settle(game);
    }

    /// <summary>
    /// "Spend this mana only to cast spells" pays for no special action (CR 106.6).
    /// </summary>
    /// <remarks>
    /// <see cref="ManaPurpose.Other"/> is zero, and every flag "has" zero — so a restriction that
    /// named a purpose said yes to every payment that names none. Six of the 43 corpus cards that
    /// make restricted mana were affected, all of them "spend this mana only to activate
    /// abilities": Omen Hawker's mana foretold, plotted, suspended and unlocked doors.
    /// Foretelling is a special action and nothing is cast (CR 702.143a).
    /// <para>
    /// The card under test says "only to cast spells" rather than Omen Hawker's wording because
    /// that is the general form of the fault. The others escape only because their type mask
    /// cannot match a payment with no card behind it, which is a coincidence of what the compiler
    /// has read rather than a rule.
    /// </para>
    /// <para>
    /// The Powerstone is the wrong reading in the other direction, and it is why the fix cannot
    /// simply refuse every unnamed purpose. "This mana can't be spent to cast a nonartifact
    /// spell" forbids one kind of cast and nothing else — a Powerstone that could not pay a
    /// foretell cost would be a worse token than CR 111.10h describes.
    /// </para>
    /// <para>
    /// The last assertion is the one that stops this passing on mana that pays for nothing at
    /// all: the same restricted mana still casts a spell.
    /// </para>
    /// </remarks>
    [Fact]
    public void Mana_that_may_only_be_cast_with_pays_for_no_special_action()
    {
        var ziggurat = new CardDefinition
        {
            OracleId = "oracle-cast-only-mana-test",
            Name = "Cast Only Mana Test",
            OracleText = "{T}: Add {G}. Spend this mana only to cast spells.",
            CardTypes = CardType.Land,
        };

        var powerstone = new CardDefinition
        {
            OracleId = "oracle-powerstone-mana-test",
            Name = "Powerstone Mana Test",
            OracleText =
                "{T}: Add {G}. This mana can't be spent to cast a nonartifact spell.",
            CardTypes = CardType.Land,
        };

        var omen = new CardDefinition
        {
            OracleId = "oracle-foretold-sorcery-test",
            Name = "Foretold Sorcery Test",
            OracleText = "Foretell {G}",
            CardTypes = CardType.Sorcery,
            ManaCostRaw = "{4}",
            Cmc = 4,
        };

        var pool = new HandWritten()
            .Give(ziggurat, TapsForRestrictedGreen(new ManaRestriction(
                ManaPurpose.CastSpell, default)))
            .Give(powerstone, TapsForRestrictedGreen(new ManaRestriction(
                ManaPurpose.CastSpell | ManaPurpose.ActivateAbility, CardType.Artifact)
            {
                TypesOnlyWhenCasting = true,
            }))
            .Give(omen, new SpellDefinition { ForetellCost = ManaCostSpec.Parse("{G}") });

        var (game, alice, _) = InMainPhaseWith(pool);
        var foretold = TestCards.PutInHand(game, alice, omen);

        // Foretelling costs {2} and casts nothing (CR 702.143a).
        TapEach(game, alice, ziggurat, 2);
        Assert.Throws<InvalidOperationException>(() => game.Foretell(alice, foretold));

        TapEach(game, alice, powerstone, 2);
        game.Foretell(alice, foretold);

        var left = game.State.GetPlayer(alice).ManaPool;
        Assert.Equal(2, left.Restricted.Count);

        var bear = TestCards.PutInHand(
            game, alice, TestCards.Costed("Cast Only Bear Test", "{G}{G}", 2));
        game.CastSpell(alice, bear, []);
        Assert.True(game.State.GetPlayer(alice).ManaPool.IsEmpty);
        Settle(game);
    }

    // ---- Layer 6: losing every ability, and attacking despite defender -------

    /// <summary>
    /// A pool serving static abilities written out rather than compiled from rules text.
    /// </summary>
    /// <remarks>
    /// The same trade <see cref="HandBuilt"/> and <see cref="HandWritten"/> make, one layer
    /// further along. What the tests below exercise is CR 613's layer 6 — an effect that takes
    /// every ability away, and a permission to attack through defender — and neither sentence has
    /// a template yet; reading them is the other half of the work. The real oracle wording of
    /// each is quoted on the card the definition is attached to, so when the compiler learns one
    /// of these sentences the test becomes an ordinary template test by deleting a pool.
    /// </remarks>
    private sealed class HandWrittenStatics : IAbilitySource
    {
        private readonly Dictionary<string, List<ContinuousEffectDefinition>> _statics = [];
        private readonly Dictionary<string, List<TriggeredAbilityDefinition>> _triggers = [];
        private readonly Dictionary<string, List<ActivatedAbilityDefinition>> _activated = [];
        private readonly Dictionary<string, List<ReplacementEffectDefinition>> _replacements = [];
        private readonly Dictionary<string, SpellDefinition> _spells = [];
        private readonly Dictionary<string, ContinuousEffectDefinition> _floating = [];

        public IReadOnlyList<TriggeredAbilityDefinition> TriggersOf(CardDefinition card) =>
            _triggers.TryGetValue(card.OracleId, out var found) ? found : [];

        public IReadOnlyList<ActivatedAbilityDefinition> ActivatedOf(CardDefinition card) =>
            _activated.TryGetValue(card.OracleId, out var found) ? found : [];

        public IReadOnlyList<ReplacementEffectDefinition> ReplacementsOf(CardDefinition card) =>
            _replacements.TryGetValue(card.OracleId, out var found) ? found : [];

        public IReadOnlyList<ContinuousEffectDefinition> StaticsOf(CardDefinition card) =>
            _statics.TryGetValue(card.OracleId, out var found) ? found : [];

        public SpellDefinition? SpellOf(CardDefinition card) =>
            _spells.GetValueOrDefault(card.OracleId);

        public ContinuousEffectDefinition? FloatingEffect(string definitionId) =>
            _floating.GetValueOrDefault(definitionId);

        public HandWrittenStatics Give(CardDefinition card, ContinuousEffectDefinition effect)
        {
            if (!_statics.TryGetValue(card.OracleId, out var found))
                _statics[card.OracleId] = found = [];

            found.Add(effect);
            return this;
        }

        public HandWrittenStatics Give(CardDefinition card, TriggeredAbilityDefinition trigger)
        {
            if (!_triggers.TryGetValue(card.OracleId, out var found))
                _triggers[card.OracleId] = found = [];

            found.Add(trigger);
            return this;
        }

        public HandWrittenStatics Give(CardDefinition card, ActivatedAbilityDefinition ability)
        {
            if (!_activated.TryGetValue(card.OracleId, out var found))
                _activated[card.OracleId] = found = [];

            found.Add(ability);
            return this;
        }

        public HandWrittenStatics Give(CardDefinition card, ReplacementEffectDefinition effect)
        {
            if (!_replacements.TryGetValue(card.OracleId, out var found))
                _replacements[card.OracleId] = found = [];

            found.Add(effect);
            return this;
        }

        public HandWrittenStatics Give(CardDefinition card, SpellDefinition spell)
        {
            _spells[card.OracleId] = spell;
            return this;
        }

        /// <summary>An effect a resolved spell leaves behind, looked up by the id it recorded.</summary>
        public HandWrittenStatics Floating(ContinuousEffectDefinition effect)
        {
            _floating[effect.Id] = effect;
            return this;
        }
    }

    /// <summary>"All creatures lose all abilities" — Humility's first half (CR 613.1f).</summary>
    /// <remarks>
    /// Declared rather than written into <c>Apply</c>, which is the only way to say it: the
    /// keywords come off the creature being computed, but the creature's own static abilities
    /// have to stop being offered at all, and that decision is made before any of them runs.
    /// </remarks>
    private static readonly ContinuousEffectDefinition CreaturesLoseAllAbilities = new()
    {
        Id = "test-lose-all-abilities",
        Layer = EffectLayer.Ability,
        RemovesAllAbilities = true,
        Applies = (_, source, builder) => source is not null && builder.IsCreature,
        Apply = (_, _, _) => { },
    };

    /// <summary>"Target creature loses all abilities until end of turn" (CR 613.1f).</summary>
    /// <remarks>
    /// The same removal arriving the other way — as an effect a spell left behind rather than as
    /// a permanent's static ability. It asks nothing about what it applies to, because a floating
    /// effect is already aimed: the ids it affects were fixed when it was created (CR 613.7b).
    /// </remarks>
    private static readonly ContinuousEffectDefinition LosesAllAbilitiesUntilEndOfTurn = new()
    {
        Id = "test-lose-all-abilities-eot",
        Layer = EffectLayer.Ability,
        RemovesAllAbilities = true,
        Applies = (_, _, _) => true,
        Apply = (_, _, _) => { },
    };

    /// <summary>"Other creatures you control get +1/+1" — a lord, in layer 7c (CR 613.4c).</summary>
    /// <remarks>
    /// Controller is not asked, deliberately: <c>Applies</c> is handed the source as a raw object
    /// and cannot compute whose it is, which is a gap recorded in the feature doc rather than one
    /// to work around here. What is under test is whether the bonus survives the lord losing its
    /// abilities, and every creature in these games belongs to the same player.
    /// </remarks>
    private static readonly ContinuousEffectDefinition OtherCreaturesGetPlusOne = new()
    {
        Id = "test-lord",
        Layer = EffectLayer.PowerToughnessModify,
        Applies = (_, source, builder) =>
            source is not null && builder.IsCreature && builder.Subject.Id != source.Id,
        Apply = (_, _, builder) => builder.Modify(1, 1),
    };

    /// <summary>
    /// "This creature can attack as though it didn't have defender" (CR 609.4, 702.3b).
    /// </summary>
    private static readonly ContinuousEffectDefinition MayAttackDespiteDefender = new()
    {
        Id = "test-attack-as-though-no-defender",
        Layer = EffectLayer.Ability,
        Applies = (_, source, builder) => source is not null && builder.Subject.Id == source.Id,
        Apply = (_, _, builder) => builder.MayAttackAsThoughNoDefender = true,
    };

    /// <summary>An Aura-style grant of one activated ability to every other creature.</summary>
    private static ContinuousEffectDefinition Grants(
        string id, ActivatedAbilityDefinition ability) => new()
        {
            Id = id,
            Layer = EffectLayer.Ability,
            Applies = (_, source, builder) =>
                source is not null && builder.IsCreature && builder.Subject.Id != source.Id,
            Apply = (_, _, builder) => builder.GrantedActivated.Add(ability),
        };

    /// <summary>A free activated ability that gains life, so activating it is visible.</summary>
    private static ActivatedAbilityDefinition GainsLife(string id) => new()
    {
        Id = id,
        Text = "Gain 1 life.",
        Effects = [new ChangeLife(1)],
    };

    /// <summary>
    /// "All creatures lose all abilities" takes the keywords and silences the lord (CR 613.1f).
    /// </summary>
    /// <remarks>
    /// Both halves of what losing every ability means, and they are reached by different code.
    /// The keyword is a characteristic and comes off the creature being computed; the lord's
    /// bonus is a continuous effect belonging to a permanent that is no longer allowed to produce
    /// one, and nothing about the creature receiving it knows that.
    /// <para>
    /// Played rather than asserted on the layers, because the question that matters is whether
    /// the game agrees. A 2/2 flier that has lost flying is blocked by a 1/1 on the ground, the
    /// block stands, and the attack is stopped — every one of those is the engine reading the
    /// computed characteristics, and the flier's own printed keyword would have refused the block
    /// outright a moment before.
    /// </para>
    /// </remarks>
    /// <summary>
    /// Losing all abilities takes the printed activated, triggered and replacement abilities too
    /// (CR 613.1f).
    /// </summary>
    /// <remarks>
    /// The layers alone are not the whole rule. Keywords and static abilities are characteristics
    /// and were removed by the layer work; the other three kinds are read from the <em>card</em>
    /// at three separate sites in <c>Game</c>, and each had to be told to ask the computed
    /// characteristics first. Until they were, a silenced permanent kept its button, still
    /// triggered, and still replaced events — while reporting no keywords, which is the kind of
    /// half-applied rule that is harder to notice than an unapplied one.
    /// <para>
    /// CR 603.2b gives the trigger case as its own example: with "all creatures lose all
    /// abilities" on the battlefield, a creature entering does not trigger its own enters ability.
    /// </para>
    /// </remarks>
    [Fact]
    public void Losing_all_abilities_silences_the_button_the_trigger_and_the_replacement()
    {
        var bearer = new CardDefinition
        {
            OracleId = "oracle-silenced-bearer",
            Name = "Silenced Bearer Test",
            CardTypes = CardType.Creature,
            Power = 2,
            Toughness = 2,
        };

        var silencer = new CardDefinition
        {
            OracleId = "oracle-silencer-enchantment",
            Name = "Silencer Enchantment Test",
            CardTypes = CardType.Enchantment,
        };

        // The replacement lives on a second creature, because a permanent that replaces its own
        // death with exile has not died (CR 700.4) and its own dies trigger correctly does not
        // fire - which would leave the trigger half of this test proving nothing.
        var shield = new CardDefinition
        {
            OracleId = "oracle-silenced-shield",
            Name = "Silenced Shield Test",
            CardTypes = CardType.Creature,
            Power = 1,
            Toughness = 1,
        };

        var pool = new HandWrittenStatics()
            .Give(bearer, new ActivatedAbilityDefinition
            {
                Id = "gain",
                Text = "You gain 2 life.",
                Effects = [new ChangeLife(new Amount(2))],
            })
            .Give(bearer, new TriggeredAbilityDefinition
            {
                Id = "dies",
                Text = "When this creature dies, you gain 5 life.",
                Triggers = TriggerConditions.Parse("~ dies")!,
                Effects = [new ChangeLife(new Amount(5))],
            })
            .Give(shield, new ReplacementEffectDefinition
            {
                Id = "shield",
                FunctionsFrom = Zone.Battlefield,
                Applies = (e, _, source) =>
                    e is ObjectMoved { To: Zone.Graveyard } gone && gone.OldId == source.Id,
                Replace = (e, _, _) => [((ObjectMoved)e) with { To = Zone.Exile }],
            })
            .Give(silencer, CreaturesLoseAllAbilities);

        // ---- with their abilities: the button pays, the death pays, the shield exiles.
        var (loud, alice, _) = InMainPhaseWith(pool);
        var speaker = loud.Create(alice, bearer, Zone.Battlefield);
        var guard = loud.Create(alice, shield, Zone.Battlefield);
        var life = loud.State.GetPlayer(alice).Life;

        loud.ActivateAbility(alice, speaker, "gain");
        Settle(loud);
        Assert.Equal(life + 2, loud.State.GetPlayer(alice).Life);

        loud.Move(speaker, Zone.Graveyard, MoveCause.Destroy);
        Settle(loud);
        Assert.Equal(life + 7, loud.State.GetPlayer(alice).Life);

        loud.Move(guard, Zone.Graveyard, MoveCause.Destroy);
        Settle(loud);
        Assert.Single(loud.State.Exile);

        // ---- silenced: none of the three speaks.
        var (quiet, bob, _) = InMainPhaseWith(pool);
        var muted = quiet.Create(bob, bearer, Zone.Battlefield);
        var mutedGuard = quiet.Create(bob, shield, Zone.Battlefield);
        quiet.Create(bob, silencer, Zone.Battlefield);
        var before = quiet.State.GetPlayer(bob).Life;

        Assert.Throws<InvalidOperationException>(
            () => quiet.ActivateAbility(bob, muted, "gain"));

        quiet.Move(muted, Zone.Graveyard, MoveCause.Destroy);
        Settle(quiet);
        Assert.Equal(before, quiet.State.GetPlayer(bob).Life);

        quiet.Move(mutedGuard, Zone.Graveyard, MoveCause.Destroy);
        Settle(quiet);

        // No replacement, so it is in the graveyard beside the other one rather than in exile.
        Assert.Empty(quiet.State.Exile);
        Assert.Equal(2, quiet.State.GetPlayer(bob).Graveyard.Count);
    }

    [Fact]
    public void A_creature_that_loses_all_abilities_stops_flying_and_stops_being_a_lord()
    {
        var lord = Card(
            "Lose All Lord Test",
            "Flying\nOther creatures you control get +1/+1.",
            CardType.Creature,
            2,
            2,
            keywords: KeywordAbility.Flying);

        var quieting = Card(
            "Lose All Humility Test", "All creatures lose all abilities.", CardType.Enchantment);

        var pool = new HandWrittenStatics()
            .Give(lord, OtherCreaturesGetPlusOne)
            .Give(quieting, CreaturesLoseAllAbilities);

        var (game, alice, bob) = InMainPhaseWith(pool);

        var flier = game.Create(alice, lord, Zone.Battlefield);
        var grunt = game.Create(
            alice, TestCards.Creature("Lose All Grunt Test", 2, 2), Zone.Battlefield);
        var footman = game.Create(
            bob, TestCards.Creature("Lose All Footman Test", 1, 1), Zone.Battlefield);

        // The lord is doing both halves of its job, and the flier cannot be blocked from
        // the ground (CR 702.9b).
        Assert.Equal(3, Characteristics.Of(game.State, pool, game.State.GetObject(grunt)).Power);
        Assert.True(
            Characteristics.Of(game.State, pool, game.State.GetObject(flier))
                .Has(KeywordAbility.Flying));
        Assert.NotNull(CombatRules.CannotBlock(
            game.State, pool, game.State.GetObject(footman), game.State.GetObject(flier), bob));

        game.Create(bob, quieting, Zone.Battlefield);

        var stripped = Characteristics.Of(game.State, pool, game.State.GetObject(flier));
        Assert.True(stripped.HasLostAllAbilities);
        Assert.False(stripped.Has(KeywordAbility.Flying));

        // CR 613.6: the bonus is gone because the ability producing it was removed in layer 6,
        // which is before layer 7c was ever reached.
        Assert.Equal(2, Characteristics.Of(game.State, pool, game.State.GetObject(grunt)).Power);

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice, new Dictionary<ObjectId, AttackTarget> { [flier] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);
        game.DeclareBlockers(
            bob, new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [flier] = [footman] });

        Assert.Single(game.State.Combat.Blocked);

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Settle(game);

        // Blocked by a creature that could not have blocked it an hour ago, so nothing got
        // through - and the 1/1 that stood in front of a 2/2 is dead.
        Assert.Equal(20, game.State.GetPlayer(bob).Life);
        Assert.DoesNotContain(footman, game.State.Battlefield);
    }

    /// <summary>
    /// A spell can strip a lord for the turn, and the board notices (CR 613.1f, 613.7b).
    /// </summary>
    /// <remarks>
    /// The other half of the family, and the one the compiler will reach first: a third of the
    /// printed wordings are "until end of turn, target creature loses all abilities …" rather
    /// than an Aura or a Humility. It arrives as a floating effect, which is a different route
    /// through the layers — nothing on the battlefield produces it, and the permanent it silences
    /// is not the permanent whose characteristics are being computed when the silence matters.
    /// <para>
    /// The effect is aimed at the lord and asserted on the <em>grunt</em> for exactly that
    /// reason. A removal that only worked on the creature it was pointed at would pass every
    /// assertion about the lord and leave the anthem running, which is the failure this is here
    /// to catch.
    /// </para>
    /// <para>
    /// The spell is <see cref="PumpUntilEndOfTurn"/> carrying a definition id, which is what
    /// every "until end of turn" continuous effect already is; nothing new was needed for this
    /// half beyond a name for the effect. The printed wordings pair it with a base power and
    /// toughness, which is <c>GenerativeEffects.SetPowerToughnessId</c> in layer 7b and exists.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_spell_that_strips_a_lord_takes_the_anthem_with_it()
    {
        var lord = Card(
            "Snakeform Lord Test",
            "Flying\nOther creatures you control get +1/+1.",
            CardType.Creature,
            2,
            2,
            keywords: KeywordAbility.Flying);

        var snakeform = Card(
            "Snakeform Test",
            "Target creature loses all abilities until end of turn.",
            CardType.Instant);

        var pool = new HandWrittenStatics()
            .Give(lord, OtherCreaturesGetPlusOne)
            .Give(snakeform, new SpellDefinition
            {
                Targets = [EffectPhrase.Specs.TargetCreature],
                Effects = [new PumpUntilEndOfTurn(LosesAllAbilitiesUntilEndOfTurn.Id)],
            })
            .Floating(LosesAllAbilitiesUntilEndOfTurn);

        var (game, alice, bob) = InMainPhaseWith(pool);

        var flier = game.Create(alice, lord, Zone.Battlefield);
        var grunt = game.Create(
            alice, TestCards.Creature("Snakeform Grunt Test", 2, 2), Zone.Battlefield);
        var footman = game.Create(
            bob, TestCards.Creature("Snakeform Footman Test", 1, 1), Zone.Battlefield);

        Assert.Equal(3, Characteristics.Of(game.State, pool, game.State.GetObject(grunt)).Power);

        PassTo(game, 3, TurnStep.PrecombatMain);

        var inHand = TestCards.PutInHand(game, alice, snakeform);
        game.CastSpell(alice, inHand, [Target.ToPermanent(flier)]);
        Settle(game);

        var stripped = Characteristics.Of(game.State, pool, game.State.GetObject(flier));
        Assert.True(stripped.HasLostAllAbilities);
        Assert.False(stripped.Has(KeywordAbility.Flying));
        Assert.Equal(2, Characteristics.Of(game.State, pool, game.State.GetObject(grunt)).Power);

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice, new Dictionary<ObjectId, AttackTarget> { [flier] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);
        game.DeclareBlockers(
            bob, new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [flier] = [footman] });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Settle(game);

        Assert.Equal(20, game.State.GetPlayer(bob).Life);
        Assert.DoesNotContain(footman, game.State.Battlefield);
    }

    /// <summary>
    /// An ability granted after the loss survives it, and one granted before does not (CR 613.7).
    /// </summary>
    /// <remarks>
    /// Layer 6 adds and removes in the same layer, so the order is the timestamp order and
    /// nothing else — a grant applied before the removal is wiped by it, and a grant applied
    /// after is simply an ability the creature has. The two enchantments differ only in when they
    /// arrived, which is the whole assertion: the same board in the other order gives the other
    /// answer.
    /// <para>
    /// Asked of the game rather than of the layers, because a granted ability that cannot be
    /// activated has not been granted. <c>Game.ActivateAbility</c> looks the ability up through
    /// the computed characteristics, so the wiped one is not there to find and the surviving one
    /// resolves and gains the life.
    /// </para>
    /// </remarks>
    [Fact]
    public void An_ability_granted_after_the_loss_survives_and_one_granted_before_does_not()
    {
        var early = Card(
            "Lose All Early Test",
            "Other creatures you control have \"Gain 1 life.\"",
            CardType.Enchantment);

        var quieting = Card(
            "Lose All Silence Test", "All creatures lose all abilities.", CardType.Enchantment);

        var late = Card(
            "Lose All Late Test",
            "Other creatures you control have \"Gain 1 life.\"",
            CardType.Enchantment);

        var pool = new HandWrittenStatics()
            .Give(early, Grants("test-grant-early", GainsLife("early")))
            .Give(quieting, CreaturesLoseAllAbilities)
            .Give(late, Grants("test-grant-late", GainsLife("late")));

        var (game, alice, _) = InMainPhaseWith(pool);

        // Timestamps come from the order they arrived (CR 613.7d), so this order is the test.
        var bear = game.Create(
            alice, TestCards.Creature("Lose All Bear Test", 2, 2), Zone.Battlefield);
        game.Create(alice, early, Zone.Battlefield);
        game.Create(alice, quieting, Zone.Battlefield);
        game.Create(alice, late, Zone.Battlefield);

        var offered = Game.ActivatedAbilitiesOf(game.State, pool, game.State.GetObject(bear));
        Assert.Equal(["late"], offered.Select(a => a.Id));

        Assert.Throws<InvalidOperationException>(
            () => game.ActivateAbility(alice, bear, "early"));

        var before = game.State.GetPlayer(alice).Life;
        game.ActivateAbility(alice, bear, "late");
        Settle(game);

        Assert.Equal(before + 1, game.State.GetPlayer(alice).Life);
    }

    /// <summary>
    /// "This creature can attack as though it didn't have defender" (CR 609.4, 702.3b).
    /// </summary>
    /// <remarks>
    /// A permission, and the difference from removing the keyword is asserted rather than
    /// assumed: the wall still has defender afterwards, because CR 609.4 says an "as though"
    /// effect applies to the stated effect and to nothing else. A card that pumps creatures with
    /// defender still finds this one, which is why the permission could not be spelled as "take
    /// the keyword off" — the two are different cards and there are cards that tell them apart.
    /// <para>
    /// The control wall shares everything except the permission, so a rule that simply stopped
    /// checking defender would fail here. And the attack is played out to damage rather than
    /// stopping at the declaration, because the declaration is only half of what the permission
    /// has to survive.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_creature_with_defender_attacks_when_an_effect_says_it_may()
    {
        var rampart = Card(
            "Defender Attack Test",
            "Defender\nThis creature can attack as though it didn't have defender.",
            CardType.Creature,
            3,
            4,
            keywords: KeywordAbility.Defender);

        var wall = Card(
            "Defender Control Test", "Defender", CardType.Creature, 3, 4,
            keywords: KeywordAbility.Defender);

        var pool = new HandWrittenStatics().Give(rampart, MayAttackDespiteDefender);

        var (game, alice, bob) = InMainPhaseWith(pool);
        var permitted = game.Create(alice, rampart, Zone.Battlefield);
        var refused = game.Create(alice, wall, Zone.Battlefield);

        // The permission does not take the keyword away (CR 609.4).
        var computed = Characteristics.Of(game.State, pool, game.State.GetObject(permitted));
        Assert.True(computed.Has(KeywordAbility.Defender));
        Assert.True(computed.MayAttackAsThoughNoDefender);

        PassTo(game, 3, TurnStep.DeclareAttackers);

        Assert.Null(CombatRules.CannotAttack(
            game.State, pool, game.State.GetObject(permitted), alice, bob));
        Assert.Contains(
            "702.3b",
            CombatRules.CannotAttack(game.State, pool, game.State.GetObject(refused), alice, bob)
                ?? string.Empty,
            StringComparison.Ordinal);

        // The whole declaration is refused when it contains the wall without the permission
        // (CR 508.1a), which is the shape a board would hit if it offered the wrong one.
        Assert.Throws<InvalidOperationException>(
            () => game.DeclareAttackers(alice, new Dictionary<ObjectId, AttackTarget>
            {
                [permitted] = AttackTarget.Player(bob),
                [refused] = AttackTarget.Player(bob),
            }));

        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [permitted] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Settle(game);

        Assert.Equal(17, game.State.GetPlayer(bob).Life);
    }

    /// <summary>
    /// A coloured creature that survives a two-damage ping, so the damage can be counted.
    /// </summary>
    /// <remarks>
    /// Toughness 3 rather than the usual 2 is the point of it. A radiance spell that wrongly
    /// included its own target would deal that creature four damage and kill it, and on a board of
    /// 2/2s that is indistinguishable from the two damage the card really does deal — both boards
    /// end with a dead creature. The number has to be readable for the test to be able to fail.
    /// <para>
    /// No colours at all is a legal argument and a deliberate case: CR 105.2c makes such an object
    /// colourless, and a colourless creature shares a colour with nothing, including another
    /// colourless creature.
    /// </para>
    /// </remarks>
    private static CardDefinition ColouredCreature(string name, params ManaColor[] colours) =>
        new()
        {
            OracleId = "oracle-" + name.ToLowerInvariant().Replace(' ', '-'),
            Name = name,
            CardTypes = CardType.Creature,
            Power = 2,
            Toughness = 3,
            Colors = [.. colours],
            ColorIdentity = [.. colours],
        };

    /// <summary>
    /// Radiance: "deals 2 damage to target creature and each other creature that shares a color
    /// with it" (CR 601.2c, 609.2).
    /// </summary>
    /// <remarks>
    /// The family this capability was built for — 10 corpus cards, every one of them a radiance
    /// line from Ravnica, and all of them blocked on the same thing: a group filter that can see
    /// the creature the same spell targeted. Neither existing delegate could say it.
    /// <c>ObjectFilter</c> sees only the candidate, and <c>SourceFilter</c> sees the permanent
    /// whose ability is asking — which for a spell is the spell, not anything it chose.
    /// <para>
    /// The two halves are different kinds of thing and the board is built so that a test cannot
    /// pass by confusing them. The target is targeted: chosen as the spell is cast (CR 601.2c) and
    /// checked again on resolution (CR 608.2b). The group is not targeted at all: it is found while
    /// the spell resolves, so it reaches a creature its controller could not have chosen and it
    /// cannot make the spell fizzle.
    /// </para>
    /// <para>
    /// The four damage assertions can each fail on their own, and each catches a different wrong
    /// reading. Two damage on the target rather than four is the one that catches "each
    /// <em>other</em>" being dropped. Two damage on Alice's own red creature catches a filter that
    /// quietly scoped itself to the caster's opponents, which no radiance card says. Nothing on
    /// the blue creature and nothing on the colourless one catch the failure mode this whole
    /// mechanism is shaped around — a peer comparison that cannot find its sibling and matches
    /// everything instead, which on this card is a one-sided board wipe rather than a ping.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_radiance_spell_finds_only_the_creatures_that_share_a_colour_with_its_target()
    {
        var beam = Card(
            "Radiance Beam Test",
            "Radiance — This spell deals 2 damage to target creature and each other creature "
                + "that shares a color with it.",
            CardType.Sorcery);

        var sharesAColour = EffectPhrase.Specs.TargetCreature with
        {
            Description = "each other creature that shares a color with it",
            PeerFilter = PeerFilters.Other(PeerFilters.SharesAColour),
        };

        var pool = new HandWrittenStatics().Give(beam, new SpellDefinition
        {
            Targets = [EffectPhrase.Specs.TargetCreature],
            Effects =
            [
                new DealDamage(2, 0),
                new ToEachPermanent(GroupAction.Damage, sharesAColour, 2, PeerIndex: 0),
            ],
        });

        var (game, alice, bob) = InMainPhaseWith(pool);

        var chosen = game.Create(
            bob, ColouredCreature("Radiance Target Test", ManaColor.Red), Zone.Battlefield);
        var alsoRed = game.Create(
            alice, ColouredCreature("Radiance Ally Test", ManaColor.Red), Zone.Battlefield);
        var blue = game.Create(
            bob, ColouredCreature("Radiance Bystander Test", ManaColor.Blue), Zone.Battlefield);
        var colourless = game.Create(
            alice, ColouredCreature("Radiance Golem Test"), Zone.Battlefield);

        var inHand = TestCards.PutInHand(game, alice, beam);
        game.CastSpell(alice, inHand, [Target.ToPermanent(chosen)]);
        Settle(game);

        // Nothing died, so every number below is still readable.
        Assert.Contains(chosen, game.State.Battlefield);
        Assert.Contains(alsoRed, game.State.Battlefield);

        Assert.Equal(2, DamageOn(game, chosen));
        Assert.Equal(2, DamageOn(game, alsoRed));
        Assert.Equal(0, DamageOn(game, blue));
        Assert.Equal(0, DamageOn(game, colourless));
    }

    /// <summary>
    /// "Exile target creature and all other creatures with the same name as that creature"
    /// (CR 201.2a, 608.2h).
    /// </summary>
    /// <remarks>
    /// The second family, 19 corpus cards across creatures, permanents, lands, artifacts and
    /// enchantments — Bile Blight, Echoing Courage, Maelstrom Pulse, Sever the Bloodline. The
    /// wording is written here as Sever the Bloodline prints it because the exile is what makes
    /// this the harder half: the spell removes its own sibling and <em>then</em> describes a group
    /// by that sibling's name.
    /// <para>
    /// A permanent that leaves the battlefield becomes a new object under a new id (CR 400.7), so
    /// by the time the group is gathered the chosen creature's id names nothing. CR 608.2h is the
    /// rule that says what to do: an effect needing information about an object no longer in the
    /// zone it was expected to be in uses that object's last known information. The engine follows
    /// the id forward through its own log, which is the same machinery a death trigger already
    /// uses to find the card its permanent became.
    /// </para>
    /// <para>
    /// Both halves of the assertion matter and they fail in opposite directions. The two surviving
    /// twins being exiled is what breaks if the sibling cannot be followed past the first effect —
    /// the group would come back empty and the card would read as plain single-target removal. The
    /// stranger surviving is what breaks if a sibling that cannot be found is treated as no
    /// restriction, which turns a two-mana exile into a board wipe. A third copy sits under Alice
    /// rather than Bob because the printed line says "all other creatures" and names no
    /// controller; Declaration in Stone is the printing that adds one, and it adds words to do it.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_group_named_by_its_target_still_finds_them_after_the_target_has_gone()
    {
        var sever = Card(
            "Sever Bloodline Test",
            "Exile target creature and all other creatures with the same name as that creature.",
            CardType.Sorcery);

        var twin = TestCards.Creature("Bloodline Twin Test", 2, 2);
        var stranger = TestCards.Creature("Bloodline Stranger Test", 2, 2);

        var sameName = EffectPhrase.Specs.TargetCreature with
        {
            Description = "all other creatures with the same name as that creature",
            PeerFilter = PeerFilters.Other(PeerFilters.HasTheSameName),
        };

        var pool = new HandWrittenStatics().Give(sever, new SpellDefinition
        {
            Targets = [EffectPhrase.Specs.TargetCreature],
            Effects =
            [
                new ExileTarget(0),
                new ToEachPermanent(GroupAction.Exile, sameName, PeerIndex: 0),
            ],
        });

        var (game, alice, bob) = InMainPhaseWith(pool);

        var chosen = game.Create(bob, twin, Zone.Battlefield);
        var theirOther = game.Create(bob, twin, Zone.Battlefield);
        var mine = game.Create(alice, twin, Zone.Battlefield);
        var bystander = game.Create(bob, stranger, Zone.Battlefield);

        var inHand = TestCards.PutInHand(game, alice, sever);
        game.CastSpell(alice, inHand, [Target.ToPermanent(chosen)]);
        Settle(game);

        Assert.DoesNotContain(chosen, game.State.Battlefield);
        Assert.DoesNotContain(theirOther, game.State.Battlefield);
        Assert.DoesNotContain(mine, game.State.Battlefield);
        Assert.Contains(bystander, game.State.Battlefield);

        // Three creatures, and the sorcery itself went to a graveyard rather than exile.
        Assert.Equal(3, game.State.Exile.Count);
    }

    /// <summary>
    /// A group whose sibling cannot be determined affects nothing, not everything (CR 608.2b).
    /// </summary>
    /// <remarks>
    /// The guard, played rather than asserted on the delegate, because the delegate is not where
    /// this would go wrong. A comparison against a sibling has to answer somehow when there is no
    /// sibling to compare against, and the convenient answer — pass, because there is nothing to
    /// fail against — matches every permanent on the battlefield. On the cards that want this
    /// mechanism that is the difference between a two-damage ping and a one-sided wipe, and it
    /// would arrive silently: the card compiles, the spell resolves, the log records a legal
    /// sweep.
    /// <para>
    /// CR 608.2b is the rule, not a preference: "If part of the effect requires information about
    /// an illegal target, it fails to determine any such information. Any part of the effect that
    /// requires that information won't happen." So <c>TargetSpec.Accepts</c> refuses in one place
    /// and no filter has to remember to.
    /// </para>
    /// <para>
    /// The destroy on the target is what stops this passing vacuously. Without it, an engine that
    /// dropped the whole spell on the floor would satisfy every assertion below.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_group_that_cannot_find_its_sibling_affects_nothing_rather_than_everything()
    {
        var pulse = Card(
            "Missing Sibling Test",
            "Destroy target creature and all other creatures with the same name as that creature.",
            CardType.Sorcery);

        var sameName = EffectPhrase.Specs.TargetCreature with
        {
            Description = "all other creatures with the same name as that creature",
            PeerFilter = PeerFilters.Other(PeerFilters.HasTheSameName),
        };

        var pool = new HandWrittenStatics().Give(pulse, new SpellDefinition
        {
            Targets = [EffectPhrase.Specs.TargetCreature],
            Effects =
            [
                new DestroyTarget(0),

                // Index 1, and the spell has one target. Nothing compiled would say this; it is
                // the cheapest way to reach the branch a card reaches only when an id can no
                // longer be followed at all.
                new ToEachPermanent(GroupAction.Destroy, sameName, PeerIndex: 1),
            ],
        });

        var (game, alice, bob) = InMainPhaseWith(pool);

        var twin = TestCards.Creature("Missing Sibling Twin Test", 2, 2);

        var chosen = game.Create(bob, twin, Zone.Battlefield);
        var theirOther = game.Create(bob, twin, Zone.Battlefield);
        var mine = game.Create(alice, twin, Zone.Battlefield);

        var inHand = TestCards.PutInHand(game, alice, pulse);
        game.CastSpell(alice, inHand, [Target.ToPermanent(chosen)]);
        Settle(game);

        // The spell resolved: its targeted half happened.
        Assert.DoesNotContain(chosen, game.State.Battlefield);

        // Its group half did not, and would have taken both of these with it.
        Assert.Contains(theirOther, game.State.Battlefield);
        Assert.Contains(mine, game.State.Battlefield);
    }

    /// <summary>Damage marked on a permanent this turn (CR 120.3), for the radiance test.</summary>
    private static int DamageOn(Game game, ObjectId id) =>
        game.State.GetObject(id).Permanent?.DamageMarked ?? -1;

    /// <summary>
    /// "If ~ would be put into a graveyard from anywhere, exile it instead" (CR 614.1c).
    /// </summary>
    /// <remarks>
    /// The commonest line on the back face of a card that must not come back — 25 faces carry it,
    /// and each one left its whole card unplayable, because a card is only playable when every
    /// face reads. "From anywhere" is why the effect functions from no particular zone: the same
    /// sentence catches the card being milled or discarded, not only dying, and a replacement
    /// restricted to the battlefield would let both through.
    /// </remarks>
    [Fact]
    public void A_card_that_replaces_its_own_death_goes_where_it_says()
    {
        var revenant = Card(
            "Graveyard Exile Test",
            "If ~ would be put into a graveyard from anywhere, exile it instead.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var compiled = CardCompiler.Compile(revenant);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var ghost = game.Create(alice, revenant, Zone.Battlefield);
        Settle(game);

        game.Move(ghost, Zone.Graveyard, MoveCause.Destroy);
        Settle(game);

        Assert.DoesNotContain(ghost, game.State.Battlefield);
        Assert.Empty(game.State.GetPlayer(alice).Graveyard);
        Assert.Single(game.State.Exile);
    }

    /// <summary>
    /// The same replacement with the other destination the corpus prints: the bottom of the
    /// library rather than exile.
    /// </summary>
    /// <remarks>
    /// One reader for both, because they are one sentence with a different ending — and the
    /// position matters as much as the zone. A card sent to the *top* of its owner's library
    /// instead of the bottom is drawn again next turn, which is a materially better card than the
    /// one printed.
    /// </remarks>
    [Fact]
    public void The_same_replacement_can_send_it_to_the_bottom_of_the_library()
    {
        var wanderer = Card(
            "Graveyard Library Test",
            "If ~ would be put into a graveyard from anywhere, put it on the bottom of its "
                + "owner's library instead.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var compiled = CardCompiler.Compile(wanderer);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var pilgrim = game.Create(alice, wanderer, Zone.Battlefield);
        Settle(game);

        var libraryBefore = game.State.GetPlayer(alice).Library.Count;

        game.Move(pilgrim, Zone.Graveyard, MoveCause.Destroy);
        Settle(game);

        Assert.Empty(game.State.GetPlayer(alice).Graveyard);
        Assert.Equal(libraryBefore + 1, game.State.GetPlayer(alice).Library.Count);

        // The bottom, not the top: the last card in the library is the one that just left.
        var bottom = game.State.GetPlayer(alice).Library[^1];
        Assert.Equal("Graveyard Library Test", game.State.GetObject(bottom).Card.Name);
    }

    /// <summary>
    /// "{2}: ~ becomes a 3/3 Elemental artifact creature with haste until end of turn. It's
    /// still a land." (CR 205.1b, 613.1d)
    /// </summary>
    /// <remarks>
    /// The whole animation grammar was already here — power, toughness, subtype, keywords, the
    /// "still a land" tail — and reachable only through a target phrase, so every land that
    /// animates <em>itself</em> went unread. That is the same split the pump readers already
    /// carry: the source is not a target, and a pattern that starts at "target" cannot see it.
    /// <para>
    /// The artifact half is asserted because it is the half that can silently go missing. An
    /// animated land that is quietly not an artifact dodges artifact removal, which makes it a
    /// better card than the one printed.
    /// </para>
    /// </remarks>
    /// <summary>
    /// "Ward — Sacrifice a creature." (CR 702.21a)
    /// </summary>
    /// <remarks>
    /// Ward's cost had been read as mana or life only, and the reader said why: the offer had no
    /// way to ask a player which card to give up. Now that the engine can charge a chosen cost,
    /// the third currency is the same ability with the same shape — so this is a wiring change,
    /// not a new mechanic.
    /// <para>
    /// The noun goes through the shared filter vocabulary, so a noun it does not know leaves the
    /// line unread rather than taxing an opponent a permanent of any kind. That would be a harder
    /// ward than the one printed, which is the direction this project refuses to be wrong in.
    /// </para>
    /// </remarks>
    [Fact]
    public void Ward_can_charge_a_creature_rather_than_mana()
    {
        var sentinel = Card(
            "Ward Sacrifice Test",
            "Ward\u2014Sacrifice a creature.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var compiled = CardCompiler.Compile(sentinel);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var guarded = game.Create(alice, sentinel, Zone.Battlefield);

        // Bob has a creature to give up and a removal spell to aim at the warded one.
        var tribute = game.Create(
            bob, TestCards.Creature("Ward Tribute Test", 1, 1), Zone.Battlefield);

        var bolt = Card("Ward Bolt Sacrifice Test", "Destroy target creature.");
        Assert.True(CardCompiler.Compile(bolt).IsComplete);

        TestCards.PassToTurn(game, 2);
        TestCards.PassToStep(game, TurnStep.PrecombatMain);
        Assert.Equal(bob, game.State.ActivePlayerId);

        foreach (var _ in Enumerable.Range(0, 2))
        {
            var land = game.Create(bob, TestCards.BasicLand("Mountain"), Zone.Battlefield);
            game.ActivateAbility(bob, land, "mana");
        }

        game.CastSpell(
            bob, TestCards.PutInHand(game, bob, bolt), [Target.ToPermanent(guarded)]);

        // The ward triggers on Bob's own spell and asks Bob, not Alice: the tax falls on whoever
        // aimed at it (CR 702.21a).
        TestCards.PassUntil(
            game, () => game.State.Choice is { Kind: ChoiceKind.OptionalPayment });

        Assert.Equal(bob, game.State.Choice!.PlayerId);

        game.Choose(bob, [tribute.Value.ToString("N")]);
        Settle(game);

        // Paid: the tribute is gone, the ward did not counter the spell, and the bolt resolved.
        Assert.DoesNotContain(tribute, game.State.Battlefield);
        Assert.DoesNotContain(guarded, game.State.Battlefield);
    }

    /// <summary>
    /// The same ward, declined: the spell is countered and nothing is paid.
    /// </summary>
    /// <remarks>
    /// The half that proves the tax is real. A ward that always let the spell through would pass
    /// the test above unchanged, because that one only asserts what happens when the price is met.
    /// </remarks>
    [Fact]
    public void A_ward_that_is_not_paid_counters_the_spell()
    {
        var sentinel = Card(
            "Ward Decline Test",
            "Ward\u2014Sacrifice a creature.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        Assert.True(CardCompiler.Compile(sentinel).IsComplete);

        var (game, alice, bob) = InMainPhase();
        var guarded = game.Create(alice, sentinel, Zone.Battlefield);
        var tribute = game.Create(
            bob, TestCards.Creature("Ward Decline Tribute Test", 1, 1), Zone.Battlefield);

        var bolt = Card("Ward Bolt Decline Test", "Destroy target creature.");

        TestCards.PassToTurn(game, 2);
        TestCards.PassToStep(game, TurnStep.PrecombatMain);

        foreach (var _ in Enumerable.Range(0, 2))
        {
            var land = game.Create(bob, TestCards.BasicLand("Mountain"), Zone.Battlefield);
            game.ActivateAbility(bob, land, "mana");
        }

        game.CastSpell(
            bob, TestCards.PutInHand(game, bob, bolt), [Target.ToPermanent(guarded)]);

        TestCards.PassUntil(
            game, () => game.State.Choice is { Kind: ChoiceKind.OptionalPayment });

        // Refusing to pay: an empty answer.
        game.Choose(bob, []);
        Settle(game);

        // The spell was countered, so the warded creature lives and the tribute is untouched.
        Assert.Contains(guarded, game.State.Battlefield);
        Assert.Contains(tribute, game.State.Battlefield);
    }

    /// <summary>
    /// "When ~ is put into a graveyard from the battlefield, draw a card." (CR 700.4)
    /// </summary>
    /// <remarks>
    /// CR 700.4 defines "dies" as exactly that phrase, so the two are one event written two ways.
    /// Every trigger template here is written against "dies", so a card saying it the long way
    /// was not read at all while the same card saying "dies" was — the same asymmetry the
    /// enters-the-battlefield rewrite exists to remove, and 130 corpus lines use the long
    /// spelling.
    /// <para>
    /// The rewrite is anchored on "from the battlefield" and nothing else. "Put into a graveyard
    /// from <em>anywhere</em>" is a different event that also catches a card being milled or
    /// discarded, and rewriting that one to "dies" would quietly narrow it to permanents.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_death_trigger_can_be_spelled_the_long_way()
    {
        var martyr = Card(
            "Long Death Test",
            "When ~ is put into a graveyard from the battlefield, draw a card.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var compiled = CardCompiler.Compile(martyr);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var saint = game.Create(alice, martyr, Zone.Battlefield);
        Settle(game);

        var before = game.State.GetPlayer(alice).Hand.Count;

        game.Move(saint, Zone.Graveyard, MoveCause.Destroy);
        Settle(game);

        Assert.Equal(before + 1, game.State.GetPlayer(alice).Hand.Count);
    }

    /// <summary>
    /// The rewrite leaves "put into a graveyard from anywhere" alone.
    /// </summary>
    /// <remarks>
    /// The guard on the test above. "From anywhere" catches a card milled or discarded as well as
    /// one that died, so rewriting it to "dies" would narrow the card to permanents — a different,
    /// smaller card than the one printed. Asserted by milling the card straight out of the
    /// library, where a death trigger must not fire but this one must.
    /// </remarks>
    [Fact]
    public void The_long_spelling_is_not_applied_to_from_anywhere()
    {
        var haunt = Card(
            "Anywhere Graveyard Test",
            "If ~ would be put into a graveyard from anywhere, exile it instead.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var compiled = CardCompiler.Compile(haunt);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();

        // Straight from the library to the graveyard: never on the battlefield, so nothing that
        // reads "dies" could apply, and the replacement still has to.
        var milled = game.Create(alice, haunt, Zone.Library);
        game.Move(milled, Zone.Graveyard, MoveCause.Mill);
        Settle(game);

        Assert.Empty(game.State.GetPlayer(alice).Graveyard);
        Assert.Single(game.State.Exile);
    }

    /// <summary>
    /// "As long as ~ entered this turn, ~ gets +2/+2."
    /// </summary>
    /// <remarks>
    /// Summoning sickness is the tempting substitute and a different question. Sickness runs until
    /// its controller's <em>next</em> untap step (CR 302.6), so a creature that arrived on your
    /// turn still has it all through the opponent's turn, while "entered this turn" is already
    /// false there. The assertion that separates them is the one worth having.
    /// </remarks>
    [Fact]
    public void A_condition_can_ask_whether_the_permanent_arrived_this_turn()
    {
        var newcomer = Card(
            "Entered This Turn Test",
            "As long as ~ entered this turn, ~ gets +2/+2.",
            CardType.Creature,
            power: 1,
            toughness: 1);

        var compiled = CardCompiler.Compile(newcomer);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var arrival = game.Create(alice, newcomer, Zone.Battlefield);
        Settle(game);

        Assert.Equal(
            3, Characteristics.Of(game.State, Pool, game.State.GetObject(arrival)).Power);

        // The opponent's turn: still summoning sick, and no longer "entered this turn".
        TestCards.PassToTurn(game, 2);

        Assert.True(game.State.GetObject(arrival).Permanent!.HasSummoningSickness);
        Assert.Equal(
            1, Characteristics.Of(game.State, Pool, game.State.GetObject(arrival)).Power);
    }

    /// <summary>
    /// "As long as a permanent left the battlefield under your control this turn, ~ gets +2/+2."
    /// </summary>
    /// <remarks>
    /// Every printed spelling of this scopes it to the asker's own permanents, so the case that
    /// matters is an <em>opponent's</em> permanent dying: a game-wide reading answers yes there and
    /// makes 25 cards strictly easier than they print. That is the assertion this test exists for;
    /// the positive half would pass either way.
    /// </remarks>
    [Fact]
    public void A_departure_condition_counts_only_your_own_permanents()
    {
        var revolt = Card(
            "Departure Test",
            "As long as a permanent left the battlefield under your control this turn, "
                + "~ gets +2/+2.",
            CardType.Creature,
            power: 1,
            toughness: 1);

        var compiled = CardCompiler.Compile(revolt);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var watcher = game.Create(alice, revolt, Zone.Battlefield);

        var theirs = game.Create(
            bob, TestCards.Creature("Departure Theirs Test", 1, 1), Zone.Battlefield);

        var yours = game.Create(
            alice, TestCards.Creature("Departure Yours Test", 1, 1), Zone.Battlefield);

        Settle(game);
        Assert.Equal(
            1, Characteristics.Of(game.State, Pool, game.State.GetObject(watcher)).Power);

        // An opponent's permanent leaving must not switch it on.
        game.Move(theirs, Zone.Graveyard, MoveCause.Destroy);
        Settle(game);

        Assert.Equal(
            1, Characteristics.Of(game.State, Pool, game.State.GetObject(watcher)).Power);

        // One of yours does.
        game.Move(yours, Zone.Graveyard, MoveCause.Destroy);
        Settle(game);

        Assert.Equal(
            3, Characteristics.Of(game.State, Pool, game.State.GetObject(watcher)).Power);
    }

    /// <summary>
    /// "As long as two or more nonland permanents entered the battlefield under your control this
    /// turn, ~ gets +2/+2."
    /// </summary>
    /// <remarks>
    /// The count, the type and the word "another" are the only things that vary across this
    /// family, so one reader covers it. Both narrowings are asserted here: a land arriving does not
    /// count towards "nonland", and the permanent asking counts towards its own condition — it is
    /// "two or more permanents", not "two or more <em>other</em> permanents" (CR 109.5).
    /// </remarks>
    [Fact]
    public void An_arrival_condition_counts_the_kind_it_names()
    {
        var landfall = Card(
            "Arrival Count Test",
            "As long as two or more nonland permanents entered the battlefield under your "
                + "control this turn, ~ gets +2/+2.",
            CardType.Creature,
            power: 1,
            toughness: 1);

        var compiled = CardCompiler.Compile(landfall);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var counter = game.Create(alice, landfall, Zone.Battlefield);
        Settle(game);

        // One nonland permanent so far - itself.
        Assert.Equal(
            1, Characteristics.Of(game.State, Pool, game.State.GetObject(counter)).Power);

        // A land is not a nonland permanent, so this changes nothing.
        game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        Settle(game);

        Assert.Equal(
            1, Characteristics.Of(game.State, Pool, game.State.GetObject(counter)).Power);

        game.Create(alice, TestCards.Creature("Arrival Second Test", 1, 1), Zone.Battlefield);
        Settle(game);

        Assert.Equal(
            3, Characteristics.Of(game.State, Pool, game.State.GetObject(counter)).Power);
    }

    /// <summary>
    /// "As long as you descended this turn, ~ gets +2/+2." (CR 700.11)
    /// </summary>
    /// <remarks>
    /// Descending is a permanent card reaching your graveyard from <em>anywhere</em>, so a card
    /// milled straight out of the library counts as much as one that died — which is the case
    /// asserted here, because a reader built on death alone would pass every other arrangement.
    /// An instant is not a permanent card (CR 110.4a) and must not count.
    /// </remarks>
    [Fact]
    public void Descending_counts_a_permanent_card_reaching_the_graveyard_from_anywhere()
    {
        var crab = Card(
            "Descend Crab Test",
            "As long as you descended this turn, ~ gets +2/+2.",
            CardType.Creature,
            power: 1,
            toughness: 1);

        var compiled = CardCompiler.Compile(crab);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var watcher = game.Create(alice, crab, Zone.Battlefield);
        Settle(game);

        Assert.Equal(
            1, Characteristics.Of(game.State, Pool, game.State.GetObject(watcher)).Power);

        // An instant reaching the graveyard is not a permanent card, so it is not a descent.
        var burn = game.Create(alice, Card("Descend Instant Test", "Draw a card."), Zone.Library);
        game.Move(burn, Zone.Graveyard, MoveCause.Mill);
        Settle(game);

        Assert.Equal(
            1, Characteristics.Of(game.State, Pool, game.State.GetObject(watcher)).Power);

        // A creature card milled out of the library is.
        var milled = game.Create(
            alice, TestCards.Creature("Descend Milled Test", 1, 1), Zone.Library);

        game.Move(milled, Zone.Graveyard, MoveCause.Mill);
        Settle(game);

        Assert.Equal(
            3, Characteristics.Of(game.State, Pool, game.State.GetObject(watcher)).Power);
    }

    /// <summary>
    /// A deferred question raised by a <em>granted</em> ability has to reach the player
    /// (CR 113.10, 601.2b).
    /// </summary>
    /// <remarks>
    /// Every deferred question is answered by finding the effect again on the card that asked, and
    /// a granted ability is not on that card — it is held against the permanent it was granted to,
    /// under (source, ability) — so the lookup needs the source id. Five call sites omitted it, and
    /// the failure is silent all the way down: the trigger fires, goes on the stack with the right
    /// source, resolves, and emits the request; the locator then returns nothing and the request is
    /// dropped with no choice, no log line, and no error.
    /// <para>
    /// Found while building granted ward, which was played in a real game, measured inert — the
    /// spell resolved untaxed and no question was asked — and reverted rather than shipped. Ward is
    /// only the loudest case: this affected optional payments, clashes, coin flips, hand choices
    /// and permanent choices alike, for every granted ability.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_granted_ability_can_still_ask_its_question()
    {
        var banner = Card(
            "Granted Question Test",
            "Creatures you control have " + "\"" + "When this creature dies, you may pay {1}. "
                + "If you do, draw a card." + "\"",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(banner);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        game.Create(alice, banner, Zone.Battlefield);

        var bearer = game.Create(
            alice, TestCards.Creature("Granted Bearer Test", 2, 2), Zone.Battlefield);

        // Mana floated first: the offer is skipped without asking when the player plainly cannot
        // take it, which would hide the very failure this test is about.
        var land = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");

        var before = game.State.GetPlayer(alice).Hand.Count;

        game.Move(bearer, Zone.Graveyard, MoveCause.Destroy);

        // The assertion that matters: the question is actually put. Before the source id was
        // threaded through, the request was raised and then silently dropped here.
        TestCards.PassUntil(
            game, () => game.State.Choice is { Kind: ChoiceKind.OptionalPayment });

        Assert.Equal(alice, game.State.Choice!.PlayerId);

        game.Choose(alice, ["yes"]);
        Settle(game);

        Assert.Equal(before + 1, game.State.GetPlayer(alice).Hand.Count);
    }

    /// <summary>
    /// A counted party is the largest assignment the board allows (CR 700.8b).
    /// </summary>
    /// <remarks>
    /// There were two answers to this rule in the compiler and one of them was wrong. The counted
    /// form kept its own walk that gave each creature the first role it could fill and moved on,
    /// so a Cleric Rogue arriving before a plain Cleric took the Cleric slot and left the plain
    /// one nothing — a party of one where CR 700.8b entitles the player to count two. It now
    /// delegates to the matcher the condition form already used, which re-houses a role that is
    /// already taken.
    /// <para>
    /// The comment that stood over the greedy version said the choice was "not a choice worth
    /// asking about: the size is the same either way". That is the claim the rule exists to deny,
    /// and it read as a justification, which is how a wrong answer survives being looked at.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_counted_party_takes_the_assignment_that_fills_the_most_roles()
    {
        var totem = Card(
            "Party Count Match Test",
            "~'s power and toughness are each equal to the number of creatures in your party.",
            CardType.Creature,
            power: 0,
            toughness: 0);

        var compiled = CardCompiler.Compile(totem);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var idol = game.Create(alice, totem, Zone.Battlefield);

        // Order is the whole test: the dual-class creature arrives first, so a walk that spends it
        // on the Cleric slot leaves the plain Cleric nowhere to go and reports one.
        game.Create(alice, new CardDefinition
        {
            OracleId = "oracle-party-match-dual",
            Name = "Party Match Dual Test",
            CardTypes = CardType.Creature,
            Subtypes = ["Cleric", "Rogue"],
            Power = 1,
            Toughness = 1,
        }, Zone.Battlefield);

        game.Create(alice, new CardDefinition
        {
            OracleId = "oracle-party-match-plain",
            Name = "Party Match Plain Test",
            CardTypes = CardType.Creature,
            Subtypes = ["Cleric"],
            Power = 1,
            Toughness = 1,
        }, Zone.Battlefield);

        Settle(game);

        // Cleric Rogue counted as the Rogue, plain Cleric as the Cleric.
        Assert.Equal(
            2, Characteristics.Of(game.State, Pool, game.State.GetObject(idol)).Power);
    }

    /// <summary>
    /// An animation confers the colours and the creature type it prints, not only the P/T
    /// (CR 105.2, 205.3m).
    /// </summary>
    /// <remarks>
    /// Azorius Keyrune prints "a 2/2 white and blue Bird artifact creature" and became a
    /// colourless, typeless 2/2 that compiled as a complete card. That is a different card in
    /// front of protection from blue, in front of removal naming a Bird, and in front of any lord.
    /// 264 corpus cards print the shape, 202 naming a type and 72 a colour.
    /// <para>
    /// The colours arrive as one effect rather than one each, because becoming a colour
    /// <em>sets</em> the colours rather than adding to them — two effects in the same layer each
    /// cleared what the last wrote, and the first pass at this fix produced a Bird that was blue
    /// and not white. Asserting both colours is what caught that.
    /// </para>
    /// </remarks>
    [Fact]
    public void An_animation_confers_the_colours_and_type_it_prints()
    {
        var keyrune = Card(
            "Keyrune Identity Test",
            "{W}{U}: ~ becomes a 2/2 white and blue Bird artifact creature with flying until "
                + "end of turn.",
            CardType.Artifact);

        var compiled = CardCompiler.Compile(keyrune);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var rune = game.Create(alice, keyrune, Zone.Battlefield);

        var before = Characteristics.Of(game.State, Pool, game.State.GetObject(rune));
        Assert.Empty(before.Subtypes);

        foreach (var basic in new[] { "Plains", "Island" })
        {
            var land = game.Create(alice, TestCards.BasicLand(basic), Zone.Battlefield);
            game.ActivateAbility(alice, land, "mana");
        }

        game.ActivateAbility(alice, rune, "a");
        Settle(game);

        var now = Characteristics.Of(game.State, Pool, game.State.GetObject(rune));

        Assert.Equal(2, now.Power);
        Assert.True(now.CardTypes.HasFlag(CardType.Creature));
        Assert.True(now.CardTypes.HasFlag(CardType.Artifact));
        Assert.True(now.Has(KeywordAbility.Flying));

        Assert.Contains("Bird", now.Subtypes, StringComparer.OrdinalIgnoreCase);

        // Both colours, not the last one written.
        Assert.Contains(ManaColor.White, now.Colors);
        Assert.Contains(ManaColor.Blue, now.Colors);
        Assert.Equal(2, now.Colors.Count);
    }

    /// <summary>
    /// A cost modifier the compiler reads reaches a game that is actually played (CR 601.2f).
    /// </summary>
    /// <remarks>
    /// The end-to-end assertion for a seam this project has already been caught on twice. The
    /// grid, the interface and <c>Game</c>'s use of it were all built and tested before anything
    /// implemented <c>ICostModifierSource</c> — so every corpus card that printed a discount
    /// compiled one, and no game ever applied it. Compiling a modifier is not the claim; casting
    /// a two-drop for one mana is.
    /// </remarks>
    [Fact]
    public void A_compiled_cost_modifier_reaches_a_played_game()
    {
        var rock = Card(
            "Cost Modifier Reach Test",
            "Creature spells you cast cost {1} less to cast.",
            CardType.Artifact);

        var compiled = CardCompiler.Compile(rock);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.NotEmpty(compiled.CostModifiers);

        var (game, alice, _) = InMainPhase();
        game.Create(alice, rock, Zone.Battlefield);

        var land = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");

        // {1}{G} discounted to {G}: one Forest pays for it, and would not otherwise.
        var bear = TestCards.Costed("Cost Modifier Bear Test", "{1}{G}", 2);
        var cast = game.CastSpell(alice, TestCards.PutInHand(game, alice, bear));
        Settle(game);

        Assert.Contains(
            game.State.Battlefield,
            id => game.State.GetObject(id).Card.Name == "Cost Modifier Bear Test");
    }

    // ---- Layer 1: copiable values (CR 613.2a, 707) --------------------------

    /// <summary>
    /// The real compiled pool with one hand-written spell in front of it.
    /// </summary>
    /// <remarks>
    /// Everything on the board in the copy tests below is read by the actual compiler from
    /// actual oracle wording; the single thing written by hand is the sentence the compiler
    /// cannot yet read — "becomes a copy of target creature until end of turn". So what is under
    /// test is the engine half arriving in a real game with real compiled cards on the
    /// battlefield, rather than a pool of hand-built abilities agreeing with itself: the copy's
    /// abilities are the ones <see cref="CardCompiler"/> produced for the copied card, and if
    /// they were not, no assertion below would hold.
    /// <para>
    /// Every member is delegated, including the ones that look irrelevant. A pool that answered
    /// "no" to a question the engine asks would change how the game plays for reasons that have
    /// nothing to do with copying, which is the kind of test-only difference this file has been
    /// caught by before.
    /// </para>
    /// </remarks>
    private sealed class CompiledWithSpell : IAbilitySource, ICostModifierSource
    {
        private readonly CompiledPool _compiled = new();
        private readonly Dictionary<string, SpellDefinition> _spells = [];
        private readonly Dictionary<string, List<ReplacementEffectDefinition>> _replacements = [];

        public CompiledWithSpell Give(CardDefinition card, SpellDefinition spell)
        {
            _spells[card.OracleId] = spell;
            return this;
        }

        public CompiledWithSpell Give(CardDefinition card, ReplacementEffectDefinition effect)
        {
            if (!_replacements.TryGetValue(card.OracleId, out var found))
                _replacements[card.OracleId] = found = [];

            found.Add(effect);
            return this;
        }

        public SpellDefinition? SpellOf(CardDefinition card) =>
            _spells.GetValueOrDefault(card.OracleId) ?? _compiled.SpellOf(card);

        public IReadOnlyList<TriggeredAbilityDefinition> TriggersOf(CardDefinition card) =>
            _compiled.TriggersOf(card);

        public IReadOnlyList<ActivatedAbilityDefinition> ActivatedOf(CardDefinition card) =>
            _compiled.ActivatedOf(card);

        public IReadOnlyList<ContinuousEffectDefinition> StaticsOf(CardDefinition card) =>
            _compiled.StaticsOf(card);

        public IReadOnlyList<ReplacementEffectDefinition> ReplacementsOf(CardDefinition card) =>
            _replacements.TryGetValue(card.OracleId, out var found)
                ? [.. found, .. _compiled.ReplacementsOf(card)]
                : _compiled.ReplacementsOf(card);

        public KeywordAbility GrantedKeywords(CardDefinition card) =>
            _compiled.GrantedKeywords(card);

        public SpellDefinition? AdventureOf(CardDefinition card) => _compiled.AdventureOf(card);

        public string? AdventureCostOf(CardDefinition card) => _compiled.AdventureCostOf(card);

        public SpellDefinition? PreparedSpellOf(CardDefinition card) =>
            _compiled.PreparedSpellOf(card);

        public string? PreparedCostOf(CardDefinition card) => _compiled.PreparedCostOf(card);

        public bool PreparedIsInstantOf(CardDefinition card) =>
            _compiled.PreparedIsInstantOf(card);

        public int DevourCountOf(CardDefinition card) => _compiled.DevourCountOf(card);

        public int AmplifyCountOf(CardDefinition card) => _compiled.AmplifyCountOf(card);

        public bool HasReadAhead(CardDefinition card) => _compiled.HasReadAhead(card);

        public ManaCostSpec? MiracleCostOf(CardDefinition card) => _compiled.MiracleCostOf(card);

        public IReadOnlyList<CardHalf> HalvesOf(CardDefinition card) => _compiled.HalvesOf(card);

        public bool HasFuse(CardDefinition card) => _compiled.HasFuse(card);

        public IReadOnlyList<CostModifier> CostModifiersOf(CardDefinition card) =>
            _compiled.CostModifiersOf(card);

        public bool ShowsTopOfLibrary(CardDefinition card) => _compiled.ShowsTopOfLibrary(card);

        public bool RemovesHandLimit(CardDefinition card) => _compiled.RemovesHandLimit(card);

        public IReadOnlyList<HandSizeChange> HandSizeChangesOf(CardDefinition card) =>
            _compiled.HandSizeChangesOf(card);

        public ChoiceOnEntry ChoosesOnEntry(CardDefinition card) => _compiled.ChoosesOnEntry(card);

        public int ExtraLandDrops(CardDefinition card) => _compiled.ExtraLandDrops(card);

        public bool MayDeclineUntap(CardDefinition card) => _compiled.MayDeclineUntap(card);

        public bool SkipsDrawStep(CardDefinition card) => _compiled.SkipsDrawStep(card);

        public bool RevealsTopOfLibrary(CardDefinition card) =>
            _compiled.RevealsTopOfLibrary(card);

        public bool MayBeginOnBattlefield(CardDefinition card) =>
            _compiled.MayBeginOnBattlefield(card);

        public IReadOnlyList<CastLimit> CastLimitsOf(CardDefinition card) =>
            _compiled.CastLimitsOf(card);

        public string? AttacksOnlyIfDefenderControls(CardDefinition card) =>
            _compiled.AttacksOnlyIfDefenderControls(card);

        public ContinuousEffectDefinition? FloatingEffect(string definitionId) =>
            _compiled.FloatingEffect(definitionId);
    }

    /// <summary>
    /// "Target creature becomes a copy of another target creature until end of turn" — the
    /// spell half of a copy effect, written out because no template reads it yet.
    /// </summary>
    /// <remarks>
    /// It is <see cref="PumpUntilEndOfTurn"/> carrying a definition id, which is what every
    /// until-end-of-turn continuous effect in the engine already is; the copy needed no new
    /// effect and no new event. What a reader has to do beyond this is choose the card at
    /// resolution time — <c>GenerativeEffects.CopyId(Characteristics.CardOf(state, abilities,
    /// original))</c> rather than a card fixed when the pool was built — which is a second
    /// target and an <c>IEffect</c>, and lives in <c>Effects.cs</c>.
    /// </remarks>
    private static SpellDefinition BecomesACopyOf(CardDefinition card) => new()
    {
        Targets = [EffectPhrase.Specs.TargetCreature],
        Effects = [new PumpUntilEndOfTurn(GenerativeEffects.CopyId(card))],
    };

    /// <summary>The id a permanent is about to have, whichever way it is arriving (CR 111.1).</summary>
    /// <remarks>
    /// The same two shapes <c>CardCompiler.Arriving</c> reads, written out because that one is
    /// internal to the engine. A permanent created on the battlefield never moved there, which
    /// is the half every entry replacement in this engine was once missing.
    /// </remarks>
    private static ObjectId? ArrivingAs(GameEvent e, GameObject source) => e switch
    {
        ObjectMoved { To: Zone.Battlefield } moved when moved.OldId == source.Id => moved.NewId,
        ObjectCreated { Zone: Zone.Battlefield } made when made.Id == source.Id => made.Id,
        _ => null,
    };

    /// <summary>
    /// "You may have this creature enter as a copy of any creature on the battlefield" — the
    /// replacement half of a copy effect, written out because no template reads it yet.
    /// </summary>
    /// <remarks>
    /// It needs no machinery the engine did not have: a replacement effect returns events, and
    /// one of them is the copy. What it does need is the <em>order</em> — the copy effect is
    /// emitted before the arrival it replaces. Triggers are collected against the state as it
    /// stands just after the event that caused them (CR 603.6), so a permanent that becomes a
    /// copy in the event <em>after</em> its own arrival has already been asked what its enters
    /// abilities are and answered with the copying card's. CR 707.5 says the copy's
    /// enters-the-battlefield abilities have a chance to trigger, and gives Wall of Omens as the
    /// example.
    /// <para>
    /// Written as "you may" in the printed text and taken unconditionally here, because what a
    /// reader has to add is the question — which creature, and whether to copy at all — and that
    /// is <c>ChoiceOnEntry</c> plus an effect, not anything about the copy.
    /// </para>
    /// </remarks>
    private static ReplacementEffectDefinition EntersAsACopyOf(CardDefinition card) => new()
    {
        Id = "enters-as-a-copy",

        // Null, not Battlefield: a permanent created on the battlefield was never anywhere else,
        // and one that resolves off the stack is replaced while it is still a spell (CR 614.6).
        FunctionsFrom = null,
        Applies = (e, _, source) => ArrivingAs(e, source) is not null,
        Replace = (e, _, source) =>
        [
            // Before the arrival, not after it. Reversed, the permanent is still a copy with the
            // right name and the right size and the copied card's enters ability simply never
            // fires — measured, not assumed: the test below reads 20 life instead of 22 and
            // every other assertion in it stays green.
            new ContinuousEffectCreated(
                Guid.NewGuid(),
                GenerativeEffects.CopyId(card),
                [ArrivingAs(e, source)!.Value],

                // No duration: this is what the permanent is, not something done to it for a
                // turn (CR 707.5).
                UntilEndOfTurn: null),
            e,
        ],
    };

    /// <summary>
    /// A copy of a two-faced permanent still has both faces (CR 707.8).
    /// </summary>
    /// <remarks>
    /// The copiable values travel inside the effect's name, so every field left out of that name
    /// is a field the copy silently does not have — and the faces are the field this repository
    /// has already been caught dropping once, in the game log, where it cost every transform in
    /// every stored game. A copy that came back with no faces would be a permanent that can
    /// never turn over, and nothing else about it would look wrong.
    /// </remarks>
    [Fact]
    public void A_copy_of_a_two_faced_permanent_keeps_both_faces()
    {
        var twoFaced = new CardDefinition
        {
            OracleId = "oracle-copy-two-faced-test",
            Name = "Copy Two Faced Test",
            CardTypes = CardType.Creature,
            Power = 2,
            Toughness = 2,
            Faces =
            [
                new CardFace
                {
                    Name = "Copy Two Faced Test",
                    CardTypes = CardType.Creature,
                    Power = 2,
                    Toughness = 2,
                },
                new CardFace
                {
                    Name = "Copy Two Faced Back Test",
                    CardTypes = CardType.Creature,
                    Power = 5,
                    Toughness = 5,
                },
            ],
        };

        var shape = Card(
            "Copy Two Faced Shape Test",
            "Target creature becomes a copy of another target creature until end of turn.");

        var pool = new CompiledWithSpell().Give(shape, BecomesACopyOf(twoFaced));
        var (game, alice, _) = InMainPhaseWith(pool);

        var shifter = game.Create(
            alice, TestCards.Creature("Copy Two Faced Shifter Test", 1, 1), Zone.Battlefield);

        PassTo(game, 3, TurnStep.PrecombatMain);

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, shape), [Target.ToPermanent(shifter)]);
        Settle(game);

        var now = Characteristics.Of(game.State, pool, game.State.GetObject(shifter));

        Assert.Equal("Copy Two Faced Test", now.Name);
        Assert.Equal(2, now.Card.Faces.Count);
        Assert.Equal("Copy Two Faced Back Test", now.Card.Faces[1].Name);
    }

    /// <summary>
    /// A permanent can enter the battlefield already a copy, and the copied card's own enters
    /// ability triggers (CR 707.5).
    /// </summary>
    /// <remarks>
    /// The other half of the family, and the larger one: measured on the corpus, 73 cards say
    /// "as a copy of" against 76 that say "becomes a copy of".
    /// <para>
    /// The life total is the assertion that matters. Every characteristic below would be just as
    /// green if the copy had been applied one event too late — the permanent would still be a
    /// 4/4 with the right name, and the trigger the rule promises would simply never have
    /// existed. That is the failure mode this whole family has: correct-looking and silent.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_permanent_can_enter_already_a_copy_and_its_enters_ability_fires()
    {
        var original = Card(
            "Enter Copy Original Test",
            "When ~ enters, you gain 2 life.",
            CardType.Creature,
            4,
            4);

        var compiled = CardCompiler.Compile(original);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var clone = Card(
            "Enter Copy Clone Test",
            "You may have this creature enter as a copy of any creature on the battlefield.",
            CardType.Creature,
            0,
            0);

        var pool = new CompiledWithSpell().Give(clone, EntersAsACopyOf(original));
        var (game, alice, _) = InMainPhaseWith(pool);

        var arrived = game.Create(alice, clone, Zone.Battlefield);
        Settle(game);

        var now = Characteristics.Of(game.State, pool, game.State.GetObject(arrived));

        Assert.Equal("Enter Copy Original Test", now.Name);
        Assert.Equal(4, now.Power);
        Assert.Equal(4, now.Toughness);

        // The rule's own worked example: the copy has the copied card's enters trigger, so its
        // controller gains the life (CR 707.5).
        Assert.Equal(22, game.State.GetPlayer(alice).Life);

        // Nothing ends it, so it is still a copy two turns later. This is what the permanent is
        // rather than a spell's until-end-of-turn effect on it.
        PassTo(game, 3, TurnStep.PrecombatMain);
        Settle(game);

        Assert.Equal(
            "Enter Copy Original Test",
            Characteristics.Of(game.State, pool, game.State.GetObject(arrived)).Name);
    }

    /// <summary>
    /// A permanent that becomes a copy has the copied card's abilities, and they play
    /// (CR 707.2a).
    /// </summary>
    /// <remarks>
    /// The assertion that earns its place is not the size. A copy effect that got power,
    /// toughness, types and colours right and gave the permanent none of the copied card's
    /// behaviour would pass every characteristic check and be the wrong card at the only moment
    /// anybody notices — so the trigger is made to fire and the activated ability is made to
    /// resolve, in one turn, on two creatures that printed nothing at all.
    /// <para>
    /// The two life totals are the whole test: 1 from the copied <c>{T}</c> ability and 3 from
    /// the copied attack trigger, against a starting 20. An engine that copied the numbers and
    /// dropped the abilities leaves Alice on 20 with every other assertion still green.
    /// </para>
    /// <para>
    /// The copy is asserted to have gone at the start of the next turn as well. The effect is a
    /// layer, not a rewrite of the object (CR 613.1): nothing was written into the permanent, so
    /// nothing has to be taken back off it when the duration runs out.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_permanent_that_becomes_a_copy_has_the_copied_cards_abilities()
    {
        var original = Card(
            "Copy Original Test",
            "Whenever ~ attacks, you gain 3 life.\n{T}: You gain 1 life.",
            CardType.Creature,
            3,
            3,
            KeywordAbility.Flying,
            "Bird");

        var compiled = CardCompiler.Compile(original);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var shape = Card(
            "Copy Shape Test",
            "Target creature becomes a copy of another target creature until end of turn.");

        var pool = new CompiledWithSpell().Give(shape, BecomesACopyOf(original));
        var (game, alice, bob) = InMainPhaseWith(pool);

        // The card being copied, on the battlefield — which is where a reader would take the
        // copiable values from (CR 707.2).
        game.Create(alice, original, Zone.Battlefield);

        // Two creatures with nothing printed on them, so every ability either of them uses below
        // can only have come from the copy.
        var attacker = game.Create(
            alice, TestCards.Creature("Copy Blank Attacker Test", 1, 1), Zone.Battlefield);
        var tapper = game.Create(
            alice, TestCards.Creature("Copy Blank Tapper Test", 1, 1), Zone.Battlefield);

        Assert.Empty(Game.ActivatedAbilitiesOf(game.State, pool, game.State.GetObject(tapper)));

        PassTo(game, 3, TurnStep.PrecombatMain);

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, shape), [Target.ToPermanent(attacker)]);
        Settle(game);

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, shape), [Target.ToPermanent(tapper)]);
        Settle(game);

        var now = Characteristics.Of(game.State, pool, game.State.GetObject(attacker));

        // The name is a copiable value, and the one the legend rule and every "same name" check
        // are asking about (CR 707.2).
        Assert.Equal("Copy Original Test", now.Name);
        Assert.Equal(original.OracleId, now.Card.OracleId);
        Assert.Equal(3, now.Power);
        Assert.Equal(3, now.Toughness);
        Assert.True(now.Has(KeywordAbility.Flying));
        Assert.Contains("Bird", now.Subtypes, StringComparer.OrdinalIgnoreCase);

        // A subtype and a colour are replaced rather than added to: the blank creature was a
        // green Bear, and the copied card is a colourless Bird (CR 707.2, 105.2).
        Assert.DoesNotContain("Bear", now.Subtypes, StringComparer.OrdinalIgnoreCase);
        Assert.Empty(now.Colors);

        // The cheap reader agrees with the full computation, which is what lets the statics
        // gatherer use it without recursing.
        Assert.Equal(
            now.Card.OracleId,
            Characteristics.CardOf(game.State, pool, game.State.GetObject(attacker)).OracleId);

        // The copied card rides inside the effect's name, which makes it much the largest thing
        // this engine puts in a log. Asserted through the persistence door as well as through
        // the fold, because a name that cannot be stored and read back is a saved game whose
        // permanent comes back as itself.
        Assert.Equal(
            game.State,
            GameReducer.Replay(EventLogSerializer.Read(EventLogSerializer.Write(game.Log))));

        // The copied activated ability is offered, and resolves: 20 -> 21.
        var granted = Assert.Single(
            Game.ActivatedAbilitiesOf(game.State, pool, game.State.GetObject(tapper)));

        game.ActivateAbility(alice, tapper, granted.Id);
        Settle(game);
        Assert.Equal(21, game.State.GetPlayer(alice).Life);

        // The copied trigger fires: 21 -> 24, and the 1/1 hits for 3.
        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Settle(game);

        Assert.Equal(24, game.State.GetPlayer(alice).Life);
        Assert.Equal(17, game.State.GetPlayer(bob).Life);

        // The duration runs out and the permanent is simply itself again (CR 514.2).
        PassTo(game, 4, TurnStep.Upkeep);
        Settle(game);

        var after = Characteristics.Of(game.State, pool, game.State.GetObject(attacker));
        Assert.Equal("Copy Blank Attacker Test", after.Name);
        Assert.Equal(1, after.Power);
        Assert.False(after.Has(KeywordAbility.Flying));
        Assert.Empty(Game.ActivatedAbilitiesOf(game.State, pool, game.State.GetObject(tapper)));
    }

    /// <summary>
    /// A copy of a lord brings the lord's static ability with it (CR 707.2a).
    /// </summary>
    /// <remarks>
    /// The half that no amount of care inside the copied permanent could produce. A static
    /// ability is not a characteristic of the permanent that has it — it is an effect on
    /// everything else — so the copy is asserted on a <em>third</em> creature that the spell
    /// never touched. Nothing about that creature knows a copy happened.
    /// <para>
    /// This is the assertion that fails when the layers gather static abilities from each
    /// permanent's printed card instead of the card it currently is, which is what they did:
    /// the copy came out the right size, with the right name, and quietly anthem-less.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_copy_of_a_lord_brings_the_anthem_with_it()
    {
        var lord = Card(
            "Copy Lord Test",
            "Other creatures you control get +2/+2.",
            CardType.Creature,
            2,
            2);

        var compiled = CardCompiler.Compile(lord);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var shape = Card(
            "Copy Lord Shape Test",
            "Target creature becomes a copy of another target creature until end of turn.");

        var pool = new CompiledWithSpell().Give(shape, BecomesACopyOf(lord));
        var (game, alice, _) = InMainPhaseWith(pool);

        var shifter = game.Create(
            alice, TestCards.Creature("Copy Lord Shifter Test", 1, 1), Zone.Battlefield);
        var grunt = game.Create(
            alice, TestCards.Creature("Copy Lord Grunt Test", 1, 1), Zone.Battlefield);

        Assert.Equal(1, Characteristics.Of(game.State, pool, game.State.GetObject(grunt)).Power);

        PassTo(game, 3, TurnStep.PrecombatMain);

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, shape), [Target.ToPermanent(shifter)]);
        Settle(game);

        // The bystander is pumped by an ability that belongs to a card nobody put on the
        // battlefield.
        Assert.Equal(3, Characteristics.Of(game.State, pool, game.State.GetObject(grunt)).Power);

        // "Other creatures", so the copy does not pump itself — the anthem is being read from
        // the copy's perspective rather than blanket-applied.
        Assert.Equal(2, Characteristics.Of(game.State, pool, game.State.GetObject(shifter)).Power);

        PassTo(game, 4, TurnStep.Upkeep);
        Settle(game);

        Assert.Equal(1, Characteristics.Of(game.State, pool, game.State.GetObject(grunt)).Power);
    }

    /// <summary>
    /// A copy takes the copiable values and leaves everything else where it was (CR 707.2).
    /// </summary>
    /// <remarks>
    /// CR 707.2's second half is a list of what is <em>not</em> copied, and two of its entries
    /// are checkable on one permanent: counters and status. The counters are the interesting
    /// one, because getting them right is a statement about the layers rather than about
    /// copying — a +1/+1 counter applies in layer 7c (CR 613.4c), long after the copy has
    /// rewritten the printed numbers in layer 1a, so a 1/1 that entered with a counter and then
    /// copies a 3/3 is a 4/4 and not a 3/3.
    /// <para>
    /// An implementation that wrote the copied values into the permanent would answer 3/3 here
    /// and look entirely reasonable doing it.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_copy_keeps_its_own_counters_and_its_own_tapped_status()
    {
        var original = Card("Copy Counter Original Test", string.Empty, CardType.Creature, 3, 3);

        var grown = Card(
            "Copy Counter Shifter Test",
            "~ enters with a +1/+1 counter on it.",
            CardType.Creature,
            1,
            1);

        var compiled = CardCompiler.Compile(grown);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var shape = Card(
            "Copy Counter Shape Test",
            "Target creature becomes a copy of another target creature until end of turn.");

        var pool = new CompiledWithSpell().Give(shape, BecomesACopyOf(original));
        var (game, alice, _) = InMainPhaseWith(pool);

        var shifter = game.Create(alice, grown, Zone.Battlefield);
        Settle(game);

        Assert.Equal(2, Characteristics.Of(game.State, pool, game.State.GetObject(shifter)).Power);

        PassTo(game, 3, TurnStep.PrecombatMain);
        game.Tap(shifter);

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, shape), [Target.ToPermanent(shifter)]);
        Settle(game);

        var now = Characteristics.Of(game.State, pool, game.State.GetObject(shifter));

        // 3/3 printed on the copied card, plus the counter this permanent already had.
        Assert.Equal(4, now.Power);
        Assert.Equal(4, now.Toughness);
        Assert.Equal("Copy Counter Original Test", now.Name);

        // Status is not a copiable value: it was tapped before it was anything else.
        Assert.True(game.State.GetObject(shifter).Permanent!.IsTapped);
        Assert.Equal(
            1,
            game.State.GetObject(shifter).Permanent!.Counters
                .GetValueOrDefault(CounterKinds.PlusOnePlusOne));
    }

    [Fact]
    public void A_permanent_can_animate_itself()
    {
        var quarry = Card(
            "Self Animation Test",
            "{2}: ~ becomes a 3/3 Elemental artifact creature with haste until end of turn. "
                + "It's still a land.",
            CardType.Land);

        var compiled = CardCompiler.Compile(quarry);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var land = game.Create(alice, quarry, Zone.Battlefield);

        var before = Characteristics.Of(game.State, Pool, game.State.GetObject(land));
        Assert.False(before.CardTypes.HasFlag(CardType.Creature));

        // Two lands' worth of mana to pay with, floated before the ability is activated.
        foreach (var _ in Enumerable.Range(0, 2))
        {
            var source = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
            game.ActivateAbility(alice, source, "mana");
        }

        game.ActivateAbility(alice, land, "a");
        Settle(game);

        var now = Characteristics.Of(game.State, Pool, game.State.GetObject(land));

        Assert.Equal(3, now.Power);
        Assert.Equal(3, now.Toughness);
        Assert.True(now.Has(KeywordAbility.Haste));

        // All three types at once: it gained creature and artifact and kept land.
        Assert.True(now.CardTypes.HasFlag(CardType.Creature));
        Assert.True(now.CardTypes.HasFlag(CardType.Artifact));
        Assert.True(now.CardTypes.HasFlag(CardType.Land));
    }

    /// <summary>
    /// The same animation without the word "artifact" leaves the permanent alone about it.
    /// </summary>
    /// <remarks>
    /// The twin of the test above, and the reason the type is read from the sentence rather than
    /// always granted: a reader that handed out artifact to every animation would make a great
    /// many creatures answer to removal they were never meant to.
    /// </remarks>
    [Fact]
    public void An_animation_that_does_not_say_artifact_does_not_grant_it()
    {
        var grove = Card(
            "Self Animation Plain Test",
            "{2}: ~ becomes a 3/3 Elemental creature until end of turn. It's still a land.",
            CardType.Land);

        var compiled = CardCompiler.Compile(grove);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var land = game.Create(alice, grove, Zone.Battlefield);

        foreach (var _ in Enumerable.Range(0, 2))
        {
            var source = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
            game.ActivateAbility(alice, source, "mana");
        }

        game.ActivateAbility(alice, land, "a");
        Settle(game);

        var now = Characteristics.Of(game.State, Pool, game.State.GetObject(land));

        Assert.True(now.CardTypes.HasFlag(CardType.Creature));
        Assert.False(now.CardTypes.HasFlag(CardType.Artifact));
        Assert.True(now.CardTypes.HasFlag(CardType.Land));
    }

    /// <summary>
    /// "Living metal" — the Vehicle is an artifact creature while it is your turn (CR 702.161a).
    /// </summary>
    /// <remarks>
    /// A theory over both turns, because the interesting half is the one where nothing happens: a
    /// test that only played the controller's own turn would pass just as well against a reader
    /// that animated the Vehicle for good, and that is a strictly better card — it would block.
    /// So the off-turn half is asserted as a refused block rather than as a characteristic, which
    /// is the difference a player would actually see.
    /// <para>
    /// 13 faces carry the line, every one the back of a two-faced card, so each held back a whole
    /// card: a card is playable only when every face of it reads.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_vehicle_with_living_metal_is_a_creature_only_on_its_controllers_turn()
    {
        var vehicle = Card(
            "Living Metal Test", "Living metal", CardType.Artifact, 4, 4, subtypes: "Vehicle");

        var compiled = CardCompiler.Compile(vehicle);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var truck = game.Create(alice, vehicle, Zone.Battlefield);
        var raider = game.Create(
            bob, TestCards.Creature("Living Metal Raider Test", 2, 2), Zone.Battlefield);

        // Alice's turn: an artifact creature, and still a Vehicle. "In addition to its other
        // types" is the half a reader that overwrote the type line would lose, and nothing about
        // the Vehicle playing as a creature would show it.
        var mine = Characteristics.Of(game.State, Pool, game.State.GetObject(truck));
        Assert.True(mine.IsCreature);
        Assert.True(mine.CardTypes.HasFlag(CardType.Artifact));
        Assert.Contains("Vehicle", mine.Subtypes);
        Assert.Equal(4, mine.Power);

        // Bob's turn, and it is a bare artifact again — so it cannot be declared as a blocker,
        // which is what a Vehicle animated for good would have been allowed to do (CR 509.1a).
        PassTo(game, 2, TurnStep.DeclareAttackers);
        Assert.False(
            Characteristics.Of(game.State, Pool, game.State.GetObject(truck)).IsCreature);

        game.DeclareAttackers(
            bob, new Dictionary<ObjectId, AttackTarget> { [raider] = AttackTarget.Player(alice) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);

        Assert.Throws<InvalidOperationException>(
            () => game.DeclareBlockers(
                alice,
                new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [raider] = [truck] }));

        // Alice's own turn again, and it attacks under its own power with nothing crewing it,
        // which is the whole of what the keyword buys.
        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice, new Dictionary<ObjectId, AttackTarget> { [truck] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Settle(game);

        Assert.Equal(16, game.State.GetPlayer(bob).Life);
    }

    /// <summary>
    /// "Artifact creatures you control get +1/+1" — a lord whose noun is not a creature type
    /// (CR 613.4c).
    /// </summary>
    /// <remarks>
    /// The negative assertions are the test. The pattern this replaced picked the tribe reading
    /// off a capital letter, and every sentence begins with one, so this line compiled to a lord
    /// for the creature <em>type</em> "Artifact" — which no card in the game has. It read as
    /// complete, it played without error, and it buffed nothing at all, on 27 corpus lines.
    /// <para>
    /// A mass static with too wide a noun passes every positive test there is, so the plain bear
    /// and the opponent's artifact creature are here to fail one. The noun now comes from the
    /// shared table every target phrase reads, which is what makes "artifact creature" two card
    /// types rather than a word to guess at.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_lord_reads_its_noun_from_the_type_table_rather_than_from_a_capital_letter()
    {
        var lord = Card(
            "Etherium Lord Test",
            "Artifact creatures you control get +1/+1.",
            CardType.Artifact | CardType.Creature, 2, 2);

        var compiled = CardCompiler.Compile(lord);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, lord, Zone.Battlefield);

        var golem = game.Create(
            alice,
            Card("Etherium Golem Test", string.Empty, CardType.Artifact | CardType.Creature, 2, 2),
            Zone.Battlefield);

        var bear = game.Create(
            alice, TestCards.Creature("Etherium Bear Test", 2, 2), Zone.Battlefield);

        var theirs = game.Create(
            bob,
            Card("Etherium Thief Test", string.Empty, CardType.Artifact | CardType.Creature, 2, 2),
            Zone.Battlefield);

        Settle(game);

        Assert.Equal(3, Characteristics.Of(game.State, Pool, game.State.GetObject(golem)).Power);

        // Flesh is not metal, and a lord that cannot tell the difference is the bug.
        Assert.Equal(2, Characteristics.Of(game.State, Pool, game.State.GetObject(bear)).Power);

        // "You control" is half the sentence, and the half a wide noun would also swallow.
        Assert.Equal(2, Characteristics.Of(game.State, Pool, game.State.GetObject(theirs)).Power);
    }

    /// <summary>
    /// "Creature tokens you control get +1/+1" — a lord over tokens (CR 111.1, 613.4c).
    /// </summary>
    /// <remarks>
    /// 21 corpus lines, and the noun is the whole of what was missing: "creature token" is a card
    /// type and a fact about where the permanent came from, which the shared table already knew
    /// and this pattern had no way to ask for. The printed bear is what proves the second half is
    /// being asked — a lord reading only "creature" pumps it too and passes on the token alone.
    /// </remarks>
    [Fact]
    public void A_lord_over_creature_tokens_leaves_the_printed_creatures_alone()
    {
        var general = Card(
            "Phantom Lord Test",
            "Creature tokens you control get +1/+1.",
            CardType.Creature, 2, 2);

        var compiled = CardCompiler.Compile(general);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        game.Create(alice, general, Zone.Battlefield);

        var token = game.Create(
            alice, TestCards.Token("Phantom Token Test", 1, 1), Zone.Battlefield);

        var printed = game.Create(
            alice, TestCards.Creature("Phantom Bear Test", 2, 2), Zone.Battlefield);

        Settle(game);

        Assert.Equal(2, Characteristics.Of(game.State, Pool, game.State.GetObject(token)).Power);
        Assert.Equal(2, Characteristics.Of(game.State, Pool, game.State.GetObject(printed)).Power);
        Assert.Equal(2, Characteristics.Of(game.State, Pool, game.State.GetObject(token)).Toughness);
    }

    /// <summary>
    /// "Other Goblin creatures you control attack each combat if able" — a requirement over a
    /// group (CR 508.1d).
    /// </summary>
    /// <remarks>
    /// The single-creature form was read years before the group form, and the two now share one
    /// path: the requirement is a keyword flag, and the attack declaration reads that flag off the
    /// computed characteristics of every creature the attacking player controls, so a flag granted
    /// in layer 6 is enforced without a second rule anywhere.
    /// <para>
    /// Both negatives matter and both are printed on the card. "Other" is why the source itself
    /// may sit out, and "Goblin" is why the bear may — a group requirement that compelled either
    /// would look identical from the Goblin's side.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_group_combat_requirement_compels_the_group_and_nothing_else()
    {
        var rabblemaster = new CardDefinition
        {
            OracleId = "oracle-rabble-test",
            Name = "Rabble Lord Test",
            OracleText = "Other Goblin creatures you control attack each combat if able.",
            CardTypes = CardType.Creature,
            Subtypes = ["Goblin"],
            Power = 2,
            Toughness = 2,
        };

        var compiled = CardCompiler.Compile(rabblemaster);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var lord = game.Create(alice, rabblemaster, Zone.Battlefield);

        var goblin = game.Create(
            alice,
            new CardDefinition
            {
                OracleId = "oracle-rabble-goblin-test",
                Name = "Rabble Goblin Test",
                CardTypes = CardType.Creature,
                Subtypes = ["Goblin"],
                Power = 1,
                Toughness = 1,
            },
            Zone.Battlefield);

        var bear = game.Create(
            alice, TestCards.Creature("Rabble Bear Test", 2, 2), Zone.Battlefield);

        Settle(game);

        // Turn 3 is Alice's again, so nothing on her side is summoning sick (CR 302.6).
        PassTo(game, 3, TurnStep.DeclareAttackers);

        // The Goblin is able to attack and is not in the batch, so the declaration is illegal.
        Assert.Throws<InvalidOperationException>(
            () => game.DeclareAttackers(
                alice,
                new Dictionary<ObjectId, AttackTarget> { [bear] = AttackTarget.Player(bob) }));

        // The Goblin alone is legal: the lord is excluded by "other" and the bear is not a Goblin.
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [goblin] = AttackTarget.Player(bob) });

        Assert.Contains(goblin, game.State.Combat.Attackers.Keys);
        Assert.DoesNotContain(lord, game.State.Combat.Attackers.Keys);
    }

    /// <summary>
    /// "Whenever an enchantment you control enters <em>and whenever</em> you fully unlock a Room"
    /// — one ability with two trigger conditions (CR 603.1, 709.5i).
    /// </summary>
    /// <remarks>
    /// 17 cards print this and every one of them prints it the same way. Both halves are asserted
    /// firing and both are asserted <em>not</em> firing for the opponent's copy of the same event,
    /// because "you control" and "you fully unlock" are the only things separating this ability
    /// from one that watches the whole table.
    /// <para>
    /// The Room half is the more delicate: fully unlocking is getting the <em>last</em> door
    /// (CR 709.5i), and a trigger reads the state as it was before the event, so a predicate that
    /// simply counted the open doors would have counted one too few and never fired at all.
    /// </para>
    /// </remarks>
    [Fact]
    public void An_ability_with_two_trigger_conditions_fires_on_either_of_them()
    {
        var eerie = Card(
            "Eerie Leech Test",
            "Eerie — Whenever an enchantment you control enters and whenever you fully "
                + "unlock a Room, each opponent loses 1 life.",
            CardType.Creature, 2, 2);

        var compiled = CardCompiler.Compile(eerie);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, eerie, Zone.Battlefield);
        Settle(game);

        Assert.Equal(20, game.State.GetPlayer(bob).Life);

        // The first condition: an enchantment you control enters.
        game.Create(
            alice, Card("Eerie Shrine Test", string.Empty, CardType.Enchantment), Zone.Battlefield);

        Settle(game);
        Assert.Equal(19, game.State.GetPlayer(bob).Life);

        // One an opponent controls is not one you control.
        game.Create(
            bob, Card("Eerie Idol Test", string.Empty, CardType.Enchantment), Zone.Battlefield);

        Settle(game);
        Assert.Equal(19, game.State.GetPlayer(bob).Life);

        // Bob's turn, and Bob's Room. "You fully unlock" is Alice, so neither the Room arriving
        // nor its second door opening is anything this ability watches.
        PassTo(game, 2, TurnStep.PrecombatMain);

        var theirRoom = TestCards.PutInHand(game, bob, Room());
        for (var i = 0; i < 6; i++)
            game.AddMana(bob, ManaColor.Red);

        game.CastSpell(bob, theirRoom, [], half: 0);
        Settle(game);

        var theirs = game.State.Battlefield.Single(
            id => game.State.GetObject(id).ControllerId == bob
                && game.State.GetObject(id).Card.Name == "Test Vents // Test Maze");

        game.UnlockDoor(bob, theirs, 1);
        Settle(game);

        Assert.Equal(19, game.State.GetPlayer(bob).Life);

        // Alice's own Room. It is an enchantment entering under her control, so the first
        // condition takes a life on the way in — one life and not two, which is the assertion
        // that says a Room arriving with one door open is not yet fully unlocked (CR 709.5d).
        PassTo(game, 3, TurnStep.PrecombatMain);

        var myRoom = TestCards.PutInHand(game, alice, Room());
        for (var i = 0; i < 6; i++)
            game.AddMana(alice, ManaColor.Red);

        game.CastSpell(alice, myRoom, [], half: 0);
        Settle(game);

        Assert.Equal(18, game.State.GetPlayer(bob).Life);

        // ...and the second condition takes another when the last door opens.
        var mine = game.State.Battlefield.Single(
            id => game.State.GetObject(id).ControllerId == alice
                && game.State.GetObject(id).Card.Name == "Test Vents // Test Maze");

        game.UnlockDoor(alice, mine, 1);
        Settle(game);

        Assert.Equal(17, game.State.GetPlayer(bob).Life);
    }

    // ---- Two restrictions in one sentence (CR 602.5b, 602.5d) ---------------------

    /// <summary>
    /// "Activate only during your turn and only once each turn" — Licia, Sanguine Tribune.
    /// </summary>
    /// <remarks>
    /// Each half read on its own and the conjunction did not, so 92 corpus lines went unread over
    /// the word "and". Both halves are asserted separately here because a reader that folded the
    /// two into one field would pass a test of either alone: the second activation proves the cap
    /// and the opponent's turn proves the phase.
    /// </remarks>
    [Fact]
    public void An_ability_restricted_twice_keeps_both_restrictions()
    {
        var licia = Card(
            "Twice Restricted Test",
            "Pay 5 life: Put three +1/+1 counters on ~. "
                + "Activate only during your turn and only once each turn.",
            CardType.Creature,
            power: 4,
            toughness: 4);

        var compiled = CardCompiler.Compile(licia);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var vampire = game.Create(alice, licia, Zone.Battlefield);

        game.ActivateAbility(alice, vampire, "a");
        Settle(game);

        Assert.Equal(15, game.State.GetPlayer(alice).Life);
        Assert.Equal(
            3,
            game.State.GetObject(vampire).Permanent!.Counters
                .GetValueOrDefault(CounterKinds.PlusOnePlusOne));

        // The cap: a second try on the same turn is refused before any life is paid.
        var again = Assert.Throws<InvalidOperationException>(
            () => game.ActivateAbility(alice, vampire, "a"));

        Assert.Contains("602.5b", again.Message, StringComparison.Ordinal);
        Assert.Equal(15, game.State.GetPlayer(alice).Life);

        // The phase: a fresh turn resets the cap, and it is Bob's, so the other half refuses.
        // Played on until Alice actually holds priority, because otherwise the refusal would be
        // about priority (CR 117.1) and the test would prove nothing about the timing rule.
        TestCards.PassUntil(
            game,
            () => game.State.ActivePlayerId == bob
                && game.State.CurrentStep == TurnStep.PrecombatMain
                && game.State.Priority.Holder == alice);

        var wrongTurn = Assert.Throws<InvalidOperationException>(
            () => game.ActivateAbility(alice, vampire, "a"));

        Assert.Contains("602.5d", wrongTurn.Message, StringComparison.Ordinal);
        Assert.Equal(15, game.State.GetPlayer(alice).Life);
    }

    // ---- Lords without an ownership clause (CR 613.4c) ----------------------------

    /// <summary>
    /// "All Sliver creatures get +1/+1" — Muscle Sliver, which pumps the Slivers across the table.
    /// </summary>
    /// <remarks>
    /// A mass static with no "you control" clause names every permanent that answers the
    /// description, and this defaulted to the controller's own — the identical bug already found
    /// and fixed in the granted-ability reader beside it, "a hive lord that quietly stopped at the
    /// table edge", still standing here on 46 corpus cards. Every one of them compiled as
    /// complete and applied to half the board, which is the failure this project most wants to
    /// avoid: it does not refuse, it succeeds wrongly.
    /// </remarks>
    [Fact]
    public void A_lord_with_no_ownership_clause_reaches_the_whole_board()
    {
        var muscle = Card(
            "Muscle Sliver Test",
            "All Sliver creatures get +1/+1.",
            CardType.Creature,
            power: 1,
            toughness: 1,
            subtypes: "Sliver");

        var compiled = CardCompiler.Compile(muscle);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var theirs = new CardDefinition
        {
            OracleId = "oracle-their-sliver-test",
            Name = "Their Sliver Test",
            CardTypes = CardType.Creature,
            Power = 2,
            Toughness = 2,
            Subtypes = ["Sliver"],
        };

        var (game, alice, bob) = InMainPhase();
        var lord = game.Create(alice, muscle, Zone.Battlefield);
        var opposing = game.Create(bob, theirs, Zone.Battlefield);
        var unrelated = game.Create(bob, TestCards.Creature("Sliverless Test", 2, 2), Zone.Battlefield);

        // The lord pumps itself — "All", not "Other" — and it pumps the opponent's Sliver too.
        Assert.Equal(2, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(lord)));
        Assert.Equal(3, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(opposing)));

        // And nothing that is not a Sliver, which is what says the filter still reads the noun.
        Assert.Equal(2, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(unrelated)));
    }

    // ---- Base power and toughness as a static (CR 613.4b) ------------------------

    /// <summary>
    /// "Other creatures have base power and toughness 1/1" — Godhead of Awe.
    /// </summary>
    /// <remarks>
    /// Layer 7b was reachable only from the Spacecraft station reader, so every card that sets a
    /// creature's base power and toughness from a static went unread. The layer is what the last
    /// assertion is about: setting happens before modifying, so a +1/+1 counter on a creature
    /// shrunk to 1/1 makes it 2/2 rather than being overwritten (CR 613.4b, 613.4c).
    /// </remarks>
    [Fact]
    public void A_mass_static_can_set_base_power_and_toughness()
    {
        var godhead = Card(
            "Godhead Test",
            "Flying\nOther creatures have base power and toughness 1/1.",
            CardType.Creature,
            power: 4,
            toughness: 4,
            keywords: KeywordAbility.Flying);

        var compiled = CardCompiler.Compile(godhead);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var avatar = game.Create(alice, godhead, Zone.Battlefield);
        var mine = game.Create(alice, TestCards.Creature("Godhead Ally Test", 3, 3), Zone.Battlefield);
        var theirs = game.Create(bob, TestCards.Creature("Godhead Foe Test", 5, 5), Zone.Battlefield);

        // "Other" keeps it off itself, and the missing ownership clause reaches across the table.
        var itself = Characteristics.Of(game.State, Pool, game.State.GetObject(avatar));
        Assert.Equal(4, itself.Power);
        Assert.Equal(4, itself.Toughness);

        var ally = Characteristics.Of(game.State, Pool, game.State.GetObject(mine));
        Assert.Equal(1, ally.Power);
        Assert.Equal(1, ally.Toughness);

        var foe = Characteristics.Of(game.State, Pool, game.State.GetObject(theirs));
        Assert.Equal(1, foe.Power);
        Assert.Equal(1, foe.Toughness);

        // Set in 7b, modified in 7c: the counter counts on top of the 1/1 rather than under it.
        game.ChangeCounters(theirs, CounterKinds.PlusOnePlusOne, 1);
        Settle(game);

        var counted = Characteristics.Of(game.State, Pool, game.State.GetObject(theirs));
        Assert.Equal(2, counted.Power);
        Assert.Equal(2, counted.Toughness);
    }

    /// <summary>
    /// "Enchanted creature has base power and toughness 0/2" — Reduce in Stature.
    /// </summary>
    /// <remarks>
    /// The same layer reached through the attachment grammar rather than the group one. It is a
    /// separate reader and so needs its own test: the two share a pattern shape and nothing else.
    /// </remarks>
    [Fact]
    public void An_aura_can_set_base_power_and_toughness()
    {
        var shrink = Card(
            "Reduce In Stature Test",
            "Enchant creature\nEnchanted creature has base power and toughness 0/2.",
            CardType.Enchantment,
            subtypes: "Aura");

        var compiled = CardCompiler.Compile(shrink);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var victim = game.Create(bob, TestCards.Creature("Shrunk Test", 5, 5), Zone.Battlefield);
        var bystander = game.Create(bob, TestCards.Creature("Unshrunk Test", 5, 5), Zone.Battlefield);

        foreach (var _ in Enumerable.Range(0, 3))
        {
            var island = game.Create(alice, TestCards.BasicLand("Island"), Zone.Battlefield);
            game.ActivateAbility(alice, island, "mana");
        }

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, shrink), [Target.ToPermanent(victim)]);
        Settle(game);

        var shrunk = Characteristics.Of(game.State, Pool, game.State.GetObject(victim));
        Assert.Equal(0, shrunk.Power);
        Assert.Equal(2, shrunk.Toughness);

        // Only what it is attached to: an Aura that shrank the whole board would pass every
        // assertion above.
        Assert.Equal(5, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(bystander)));
    }

    /// <summary>
    /// "Enchanted artifact is a creature with base power and toughness 5/5 in addition to its
    /// other types" — Ensoul Artifact.
    /// </summary>
    /// <remarks>
    /// The same layer 7b reached alongside the layer 4 the station reader uses, on an attachment
    /// rather than on the source. The last assertion is the reason the pattern demands "in
    /// addition to its other types" rather than assuming it: an animated artifact that had
    /// quietly stopped being an artifact would dodge artifact removal, which is the reading that
    /// makes the card better than printed.
    /// </remarks>
    [Fact]
    public void An_aura_can_animate_what_it_is_attached_to()
    {
        var ensoul = Card(
            "Ensoul Test",
            "Enchant artifact\n"
                + "Enchanted artifact is a creature with base power and toughness 5/5 "
                + "in addition to its other types.",
            CardType.Enchantment,
            subtypes: "Aura");

        var compiled = CardCompiler.Compile(ensoul);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var trinket = new CardDefinition
        {
            OracleId = "oracle-ensoul-trinket-test",
            Name = "Ensoul Trinket Test",
            CardTypes = CardType.Artifact,
        };

        var (game, alice, _) = InMainPhase();
        var artifact = game.Create(alice, trinket, Zone.Battlefield);

        // Not a creature until the Aura arrives, which is what says the layer is doing the work.
        Assert.False(Characteristics.Of(game.State, Pool, game.State.GetObject(artifact)).IsCreature);

        foreach (var _ in Enumerable.Range(0, 3))
        {
            var island = game.Create(alice, TestCards.BasicLand("Island"), Zone.Battlefield);
            game.ActivateAbility(alice, island, "mana");
        }

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, ensoul), [Target.ToPermanent(artifact)]);
        Settle(game);

        var animated = Characteristics.Of(game.State, Pool, game.State.GetObject(artifact));
        Assert.True(animated.IsCreature);
        Assert.Equal(5, animated.Power);
        Assert.Equal(5, animated.Toughness);

        // "In addition to": it is still an artifact, so artifact removal still finds it.
        Assert.True(animated.CardTypes.HasFlag(CardType.Artifact));

        // Set in 7b, so a counter added in 7c stacks on top rather than being overwritten.
        game.ChangeCounters(artifact, CounterKinds.PlusOnePlusOne, 1);
        Settle(game);

        Assert.Equal(
            6, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(artifact)));
    }

    // ---- A bonus and a quoted ability in one sentence (CR 613.1f, 613.4c) --------

    /// <summary>
    /// "Enchanted creature gets +2/+2 and has "{T}: This creature deals 1 damage to any target.""
    /// — Arcane Teachings.
    /// </summary>
    /// <remarks>
    /// Two complete grammars that never met. <c>Enchanted creature has "{T}: Add {B}"</c> read and
    /// <c>Enchanted creature gets +2/+2 and has flying</c> read, and the two joined did not: the
    /// attached-buff reader's keyword slot has no quotation mark in it, and the grant reader's
    /// pattern went from the group straight to the word "has". 52 cards print the pair.
    /// <para>
    /// Both halves are asserted, and both are asserted <em>off</em> the creature next to it. A
    /// grant is invisible from the card that gives it, so a predicate that is too generous looks
    /// exactly like one that works — which is how the filter bugs in this family were found.
    /// </para>
    /// </remarks>
    [Fact]
    public void An_aura_can_give_a_bonus_and_a_quoted_ability_in_one_sentence()
    {
        var teachings = Card(
            "Arcane Teachings Test",
            "Enchant creature\n"
                + "Enchanted creature gets +2/+2 and has "
                + "\"{T}: This creature deals 1 damage to any target.\"",
            CardType.Enchantment,
            subtypes: "Aura");

        var compiled = CardCompiler.Compile(teachings);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();

        // Haste, because the granted ability costs a tap and a creature that arrived this turn
        // cannot pay one (CR 302.6).
        var student = game.Create(
            alice,
            Card("Taught Bear Test", string.Empty, CardType.Creature, 2, 2, KeywordAbility.Haste),
            Zone.Battlefield);

        var bystander = game.Create(
            alice, TestCards.Creature("Untaught Bear Test", 2, 2), Zone.Battlefield);

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, teachings), [Target.ToPermanent(student)]);
        Settle(game);

        // The bonus, in layer 7c.
        Assert.Equal(4, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(student)));

        // And the ability, in layer 6 — played rather than counted, because a granted ability
        // that goes on the stack has to be found a second time to resolve.
        var granted = Game.ActivatedAbilitiesOf(game.State, Pool, game.State.GetObject(student))
            .Single(a => a.Id.StartsWith("granted:", StringComparison.Ordinal));

        game.ActivateAbility(alice, student, granted.Id, [Target.ToPlayer(bob)]);
        Settle(game);

        Assert.Equal(19, game.State.GetPlayer(bob).Life);

        // Neither half reaches the creature standing beside it.
        Assert.Equal(2, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(bystander)));
        Assert.Empty(GrantedIdsOf(game, bystander));
    }

    // ---- Names a card calls itself by ----------------------------------------

    /// <summary>
    /// An Alchemy rebalance is named "A-Something" and its text says "Something".
    /// </summary>
    /// <remarks>
    /// The self-reference stripping was built from the printed name and the part before its
    /// comma, so for "A-Elderleaf Mentor" it looked for "A-Elderleaf Mentor" twice while the card
    /// says "When Elderleaf Mentor enters". Neither matched, the name was never turned into "~",
    /// and every self-referring line on the card went unread. 216 playable cards carry the prefix
    /// and 116 of them name themselves without it.
    /// <para>
    /// Both spellings are asserted, because five of these cards do print their own prefixed name
    /// and the fix has to be a widening rather than a swap. What makes both work is the order:
    /// the longer name is replaced first, so a line saying the prefixed form never becomes "A-~".
    /// </para>
    /// </remarks>
    [Fact]
    public void A_rebalanced_card_answers_to_its_name_with_or_without_the_prefix()
    {
        var bare = Card(
            "A-Elderleaf Mentor Test",
            "When Elderleaf Mentor Test enters, create a 1/1 green Elf Warrior creature token.",
            CardType.Creature,
            3,
            2);

        var compiled = CardCompiler.Compile(bare);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        game.Create(alice, bare, Zone.Battlefield);
        Settle(game);

        Assert.Contains(
            game.State.Battlefield,
            id => game.State.GetObject(id).Card.Name == "Elf Warrior");

        // The prefixed spelling still reads, which is the half a swap would have lost.
        var prefixed = Card(
            "A-Elderleaf Herald Test",
            "When A-Elderleaf Herald Test enters, create a 1/1 green Elf Warrior creature token.",
            CardType.Creature,
            3,
            2);

        var second = CardCompiler.Compile(prefixed);
        Assert.True(second.IsComplete, string.Join(" | ", second.Unhandled));

        // And the line the compiler kept holds no card name at all — a compiled line still
        // carrying its own name is exactly what this defect looked like from the outside.
        Assert.All(
            CardCompiler.Lines(bare),
            line => Assert.DoesNotContain("Elderleaf", line, StringComparison.Ordinal));

        Assert.All(
            CardCompiler.Lines(prefixed),
            line => Assert.DoesNotContain("Elderleaf", line, StringComparison.Ordinal));
    }

    // ---- Replacements that change an amount ----------------------------------

    /// <summary>
    /// "If a source you control would deal damage ..., it deals double that damage instead."
    /// </summary>
    /// <remarks>
    /// Angrath's Marauders, and the head of the largest replacement family left in the corpus.
    /// Both halves are asserted because the ownership clause is the whole card: a doubler that
    /// read "a source" where the card says "a source you control" doubles the damage aimed at its
    /// own controller, and nothing on the board would say so.
    /// </remarks>
    [Fact]
    public void A_damage_doubler_doubles_its_controllers_damage_and_not_an_opponents()
    {
        var marauders = Card(
            "Damage Doubler Test",
            "If a source you control would deal damage to a permanent or player, it deals "
                + "double that damage to that permanent or player instead.",
            CardType.Creature,
            4,
            4);

        var compiled = CardCompiler.Compile(marauders);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, marauders, Zone.Battlefield);
        var theirs = game.Create(bob, TestCards.Creature("Opposing Pinger Test", 1, 1), Zone.Battlefield);

        var bolt = TestCards.PutInHand(
            game, alice, Card("Doubled Bolt Test", "~ deals 3 damage to any target."));

        game.CastSpell(alice, bolt, [Target.ToPlayer(bob)]);
        Settle(game);

        Assert.Equal(14, game.State.GetPlayer(bob).Life);

        // The negative that matters: damage from a permanent the opponent controls is not
        // "a source you control", and passes through at its printed size.
        game.MarkDamageToPlayer(alice, theirs, 3, isCombat: false);
        Settle(game);

        Assert.Equal(17, game.State.GetPlayer(alice).Life);
    }

    /// <summary>Two doublers make a 2-power creature deal 8, and not an infinite amount.</summary>
    /// <remarks>
    /// CR 614.5's own worked example, word for word, and the reason a replacement that emits a
    /// bigger version of the event it replaced is safe to write at all: each effect gets one
    /// opportunity per event and does not re-enter its own output. Without that this reader would
    /// not fail a test — it would hang the game — so the number is asserted rather than assumed.
    /// <para>
    /// It also plays the ordering question (CR 616.1): with two applicable replacements the engine
    /// holds the event and asks which to apply first, and the answer cannot change the total.
    /// </para>
    /// <para>
    /// The rule's example is a <em>creature</em>, and so is this, for a reason worth knowing. The
    /// held event is re-emitted after the resolution that produced it has finished, so a
    /// <em>spell</em>'s damage comes back to be replaced when the spell has already left the stack
    /// and its object no longer exists (CR 400.7) — and every source test in the engine, this one
    /// and the player prevention shield and infect alike, reads the source by id and finds
    /// nothing. A creature is still on the battlefield, which is why the ordering question is
    /// answerable at all.
    /// </para>
    /// </remarks>
    [Fact]
    public void Two_damage_doublers_multiply_once_each()
    {
        var marauders = Card(
            "Stacked Doubler Test",
            "If a source you control would deal damage to a permanent or player, it deals "
                + "double that damage to that permanent or player instead.",
            CardType.Creature,
            4,
            4);

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, marauders, Zone.Battlefield);
        game.Create(alice, marauders, Zone.Battlefield);

        var attacker = game.Create(
            alice, TestCards.Creature("Doubled Attacker Test", 2, 2), Zone.Battlefield);

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        // The replacement-order question (CR 616.1) has to be answered for combat to finish, and
        // which of the two is taken first cannot change the total.
        for (var guard = 0; guard < 40 && game.State.CurrentStep != TurnStep.EndOfCombat; guard++)
        {
            if (game.State.Choice is { } question)
            {
                game.Choose(question.PlayerId, [question.Options[0].Id]);
                continue;
            }

            if (game.State.CurrentStep == TurnStep.DeclareBlockers
                && !game.State.Combat.BlockersDeclared)
            {
                game.DeclareBlockers(bob, new Dictionary<ObjectId, IReadOnlyList<ObjectId>>());
                continue;
            }

            if (game.State.Priority.Holder is not { } holder)
                break;

            game.PassPriority(holder);
        }

        Settle(game);

        Assert.Equal(12, game.State.GetPlayer(bob).Life);
    }

    /// <summary>
    /// "If a red source you control would deal damage to an opponent or a permanent an opponent
    /// controls, it deals that much damage plus 2 instead."
    /// </summary>
    /// <remarks>
    /// Torbran, and the same family with all three slots narrowed at once — a colour on the
    /// source, a side on the recipient, and addition rather than multiplication. Each is asserted
    /// off a case that differs in exactly one of them, because a filter that is too generous looks
    /// identical to one that works from the card that carries it.
    /// </remarks>
    [Fact]
    public void A_colour_restricted_damage_bonus_reaches_only_the_damage_the_card_describes()
    {
        var thane = Card(
            "Red Thane Test",
            "If a red source you control would deal damage to an opponent or a permanent an "
                + "opponent controls, it deals that much damage plus 2 instead.",
            CardType.Creature,
            2,
            2);

        var compiled = CardCompiler.Compile(thane);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var red = new CardDefinition
        {
            OracleId = "oracle-thane-red-bolt-test",
            Name = "Thane Red Bolt Test",
            OracleText = "~ deals 3 damage to any target.",
            CardTypes = CardType.Instant,
            ColorIdentity = [ManaColor.Red],
            Colors = [ManaColor.Red],
        };

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, thane, Zone.Battlefield);
        var mine = game.Create(alice, TestCards.Creature("Friendly Wall Test", 0, 6), Zone.Battlefield);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, red), [Target.ToPlayer(bob)]);
        Settle(game);

        Assert.Equal(15, game.State.GetPlayer(bob).Life);

        // Colourless: the same spell without the colour the card names.
        var plain = TestCards.PutInHand(
            game, alice, Card("Colorless Bolt Test", "~ deals 3 damage to any target."));

        game.CastSpell(alice, plain, [Target.ToPlayer(bob)]);
        Settle(game);

        Assert.Equal(12, game.State.GetPlayer(bob).Life);

        // And a red source you control aimed at a permanent *you* control, which the recipient
        // clause excludes.
        var second = TestCards.PutInHand(game, alice, red);
        game.CastSpell(alice, second, [Target.ToPermanent(mine)]);
        Settle(game);

        Assert.Equal(3, game.State.GetObject(mine).Permanent?.DamageMarked);
    }

    /// <summary>
    /// "If one or more +1/+1 counters would be put on a creature you control, that many plus one
    /// +1/+1 counters are put on it instead."
    /// </summary>
    /// <remarks>
    /// Hardened Scales. CR 614.16 is what makes one reader over the counter event enough — it
    /// applies to counters from a resolving spell and to counters from another replacement alike.
    /// <para>
    /// The sign guard is asserted directly, because it is the dangerous half: a counter being
    /// <em>removed</em> is the same event counted the other way, and an effect that read it would
    /// take two counters off where the card says nothing at all.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_counter_multiplier_adds_to_counters_arriving_and_not_to_counters_leaving()
    {
        var scales = Card(
            "Hardened Scales Test",
            "If one or more +1/+1 counters would be put on a creature you control, that many "
                + "plus one +1/+1 counters are put on it instead.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(scales);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, scales, Zone.Battlefield);

        var mine = game.Create(alice, TestCards.Creature("Scaled Bear Test", 2, 2), Zone.Battlefield);
        var theirs = game.Create(bob, TestCards.Creature("Unscaled Bear Test", 2, 2), Zone.Battlefield);

        var grow = TestCards.PutInHand(
            game, alice, Card("Scaling Growth Test", "Put two +1/+1 counters on target creature."));

        game.CastSpell(alice, grow, [Target.ToPermanent(mine)]);
        Settle(game);

        Assert.Equal(5, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(mine)));

        // Not a creature its controller controls, so nothing is added.
        var other = TestCards.PutInHand(
            game, alice, Card("Second Growth Test", "Put two +1/+1 counters on target creature."));

        game.CastSpell(alice, other, [Target.ToPermanent(theirs)]);
        Settle(game);

        Assert.Equal(4, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(theirs)));

        // And taking one off takes exactly one off.
        game.ChangeCounters(mine, CounterKinds.PlusOnePlusOne, -1);
        Settle(game);

        Assert.Equal(4, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(mine)));
    }

    /// <summary>"If you would gain life, you gain that much life plus 1 instead."</summary>
    /// <remarks>
    /// Angel of Vitality. Life loss is the same event with the sign flipped, so the negative here
    /// is not a nicety: a reader without the guard would have turned every payment and every point
    /// of drain into a bigger one, and the life total is the only place it would ever have shown.
    /// </remarks>
    [Fact]
    public void A_life_gain_bonus_applies_to_gain_and_leaves_loss_alone()
    {
        var angel = Card(
            "Vitality Angel Test",
            "If you would gain life, you gain that much life plus 1 instead.",
            CardType.Creature,
            2,
            3);

        var compiled = CardCompiler.Compile(angel);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, angel, Zone.Battlefield);

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, Card("Bigger Salve Test", "You gain 5 life.")));

        Settle(game);
        Assert.Equal(26, game.State.GetPlayer(alice).Life);

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, Card("Self Drain Test", "You lose 3 life.")));

        Settle(game);
        Assert.Equal(23, game.State.GetPlayer(alice).Life);

        // And it is the controller's own gain, not everybody's.
        game.CastSpell(
            alice,
            TestCards.PutInHand(game, alice, Card("Shared Salve Test", "Target player gains 5 life.")),
            [Target.ToPlayer(bob)]);

        Settle(game);
        Assert.Equal(25, game.State.GetPlayer(bob).Life);
    }

    /// <summary>"If an opponent would gain life, that player loses that much life instead."</summary>
    /// <remarks>
    /// Tainted Remedy — the same family turned inside out, and the one arm where the replacement
    /// emits an event of the opposite sign. Its own controller gaining life is the negative, and
    /// the reason the two halves of the sentence are checked against each other when it compiles.
    /// </remarks>
    [Fact]
    public void Life_an_opponent_would_gain_can_be_turned_into_life_lost()
    {
        var remedy = Card(
            "Tainted Remedy Test",
            "If an opponent would gain life, that player loses that much life instead.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(remedy);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, remedy, Zone.Battlefield);

        game.CastSpell(
            alice,
            TestCards.PutInHand(game, alice, Card("Poisoned Gift Test", "Target player gains 4 life.")),
            [Target.ToPlayer(bob)]);

        Settle(game);
        Assert.Equal(16, game.State.GetPlayer(bob).Life);

        game.CastSpell(
            alice,
            TestCards.PutInHand(game, alice, Card("Honest Gift Test", "Target player gains 4 life.")),
            [Target.ToPlayer(alice)]);

        Settle(game);
        Assert.Equal(24, game.State.GetPlayer(alice).Life);
    }

    /// <summary>"If a creature an opponent controls would die, exile it instead."</summary>
    /// <remarks>
    /// Stone of Erech, and the graveyard-hate half of the replacement family. CR 700.4 is the rule
    /// that makes one event enough — "dies" is exactly "put into a graveyard from the
    /// battlefield", whatever put it there, so a creature destroyed and a creature sacrificed are
    /// the same event to watch.
    /// <para>
    /// The ownership clause is asserted from both sides, because a filter that is too generous is
    /// invisible from the card that carries it: a version reading "a creature" would eat its own
    /// controller's creatures too, and the board would look the same until somebody wanted a
    /// graveyard.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_death_replacement_reaches_only_the_creatures_its_clause_names()
    {
        var stone = Card(
            "Erech Stone Test",
            "If a creature an opponent controls would die, exile it instead.",
            CardType.Artifact);

        var compiled = CardCompiler.Compile(stone);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, stone, Zone.Battlefield);

        var theirs = game.Create(bob, TestCards.Creature("Exiled Bear Test", 2, 2), Zone.Battlefield);
        var mine = game.Create(alice, TestCards.Creature("Buried Bear Test", 2, 2), Zone.Battlefield);

        game.CastSpell(
            alice,
            TestCards.PutInHand(game, alice, Card("Erech Murder Test", "Destroy target creature.")),
            [Target.ToPermanent(theirs)]);

        Settle(game);

        Assert.Empty(game.State.GetPlayer(bob).Graveyard);
        Assert.Single(game.State.Exile, id => game.State.GetObject(id).Card.Name == "Exiled Bear Test");

        // A creature its controller controls dies the ordinary way.
        game.CastSpell(
            alice,
            TestCards.PutInHand(
                game, alice, Card("Second Erech Murder Test", "Destroy target creature.")),
            [Target.ToPermanent(mine)]);

        Settle(game);

        Assert.Contains(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Buried Bear Test");
    }

    /// <summary>"If ~ would die, put it on top of its owner's library instead."</summary>
    /// <remarks>
    /// Gravebane Zombie — the same replacement pointed at itself and at a different destination.
    /// The destination is read rather than defaulted: exile is the harshest of the three the
    /// corpus prints, and a card that says "on top of its owner's library" and got exile would be
    /// a strictly worse card reading as complete.
    /// </remarks>
    [Fact]
    public void A_permanent_can_replace_its_own_death_with_a_trip_to_its_library()
    {
        var zombie = Card(
            "Gravebane Test",
            "If ~ would die, put it on top of its owner's library instead.",
            CardType.Creature,
            3,
            1);

        var compiled = CardCompiler.Compile(zombie);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var walker = game.Create(bob, zombie, Zone.Battlefield);
        var before = game.State.GetPlayer(bob).Library.Count;

        game.CastSpell(
            alice,
            TestCards.PutInHand(
                game, alice, Card("Gravebane Murder Test", "Destroy target creature.")),
            [Target.ToPermanent(walker)]);

        Settle(game);

        Assert.Empty(game.State.GetPlayer(bob).Graveyard);
        Assert.Equal(before + 1, game.State.GetPlayer(bob).Library.Count);
        Assert.Equal(
            "Gravebane Test",
            game.State.GetObject(game.State.GetPlayer(bob).Library[0]).Card.Name);
    }

    // ---- Costs ---------------------------------------------------------------

    /// <summary>
    /// "You may pay {W}{U}{B}{R}{G} rather than pay this spell's mana cost" (CR 118.9).
    /// </summary>
    /// <remarks>
    /// The Bringer cycle. The second half of this test is the whole point of the reader and the
    /// reason the family was left unread before it: an alternative cost is <em>optional</em>
    /// (CR 118.9b), and the engine's other route takes one unconditionally, so a card compiled
    /// that way could never again be cast for the cost printed on it.
    /// </remarks>
    [Fact]
    public void An_alternative_mana_cost_can_be_taken_or_left()
    {
        var bringer = new CardDefinition
        {
            OracleId = "oracle-bringer-test",
            Name = "Bringer Test",
            OracleText = "You may pay {W}{U}{B}{R}{G} rather than pay ~'s mana cost.",
            CardTypes = CardType.Creature,
            ManaCostRaw = "{7}",
            Cmc = 7,
            Power = 5,
            Toughness = 5,
        };

        var compiled = CardCompiler.Compile(bringer);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();

        foreach (var basic in new[] { "Plains", "Island", "Swamp", "Mountain", "Forest" })
        {
            var land = game.Create(alice, TestCards.BasicLand(basic), Zone.Battlefield);
            game.ActivateAbility(alice, land, "mana");
        }

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, bringer), targets: null, alternativeCost: true);

        Settle(game);

        Assert.Single(
            game.State.Battlefield, id => game.State.GetObject(id).Card.Name == "Bringer Test");

        // And the printed cost still works, which is the half that a zone-based alternative cost
        // would have taken away.
        foreach (var _ in Enumerable.Range(0, 7))
        {
            var land = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
            game.ActivateAbility(alice, land, "mana");
        }

        game.CastSpell(alice, TestCards.PutInHand(game, alice, bringer));
        Settle(game);

        Assert.Equal(
            2,
            game.State.Battlefield.Count(
                id => game.State.GetObject(id).Card.Name == "Bringer Test"));
    }

    /// <summary>
    /// "As an additional cost to cast this spell, sacrifice two creatures" (CR 601.2f).
    /// </summary>
    /// <remarks>
    /// Bankrupt in Blood. The reader had read this cost with a count of one for a while and
    /// refused every printing that names a bigger number — the count is carried by the cost rather
    /// than by the words, which is why the noun is singularised before the target grammar sees it.
    /// <para>
    /// The refusal is asserted too. A cost checked before it is spent (CR 601.2h) is the
    /// difference between a spell that cannot be cast and one that is cast for half its price.
    /// </para>
    /// </remarks>
    [Fact]
    public void An_additional_cost_can_name_more_than_one_creature()
    {
        var bankrupt = Card(
            "Blood Bankruptcy Test",
            "As an additional cost to cast ~, sacrifice two creatures.\nDraw three cards.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(bankrupt);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();

        var fodder = Enumerable.Range(0, 2)
            .Select(i => game.Create(
                alice, TestCards.Creature($"Bankrupt Fodder {i} Test", 1, 1), Zone.Battlefield))
            .ToList();

        var card = TestCards.PutInHand(game, alice, bankrupt);

        // One creature is not two, and the whole cost is checked before any of it is spent.
        Assert.ThrowsAny<InvalidOperationException>(
            () => game.CastSpell(alice, card, [], costPayment: [fodder[0]]));

        Assert.Equal(2, game.State.Battlefield.Count);

        var before = game.State.GetPlayer(alice).Hand.Count;
        game.CastSpell(alice, card, [], costPayment: fodder);
        Settle(game);

        Assert.Empty(game.State.Battlefield);
        Assert.Equal(before - 1 + 3, game.State.GetPlayer(alice).Hand.Count);
    }

    /// <summary>
    /// "{1}, Return a land you control to its owner's hand: Create a 1/1 blue Illusion creature
    /// token with flying." — Meloku the Clouded Mirror.
    /// </summary>
    /// <remarks>
    /// The one chosen cost that takes a permanent without spending it (CR 701.20a) had only ever
    /// been reached through ninjutsu, which builds it by hand; the printed sentence had no reader
    /// at all, and the counted sacrifice and discard beside it had none either.
    /// <para>
    /// It is asserted as an <em>ability</em> cost rather than as an additional cost on a spell,
    /// and that is a finding rather than a preference: the cast path's chosen-cost loop has no arm
    /// for this kind and drops through to a graveyard move, so a spell compiled with it would bin
    /// the land it was meant to pick up. The compiler refuses that shape until the engine can say
    /// it.
    /// </para>
    /// </remarks>
    [Fact]
    public void An_ability_cost_can_be_a_permanent_returned_to_its_owners_hand()
    {
        var mirror = Card(
            "Clouded Mirror Test",
            "Flying\n{1}, Return a land you control to its owner's hand: Create a 1/1 blue "
                + "Illusion creature token with flying.",
            CardType.Creature,
            2,
            4,
            KeywordAbility.Flying);

        var compiled = CardCompiler.Compile(mirror);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var source = game.Create(alice, mirror, Zone.Battlefield);

        var tapped = game.Create(alice, TestCards.BasicLand("Island"), Zone.Battlefield);
        var spent = game.Create(alice, TestCards.BasicLand("Island"), Zone.Battlefield);
        game.ActivateAbility(alice, tapped, "mana");

        game.ActivateAbility(alice, source, "a", targets: null, costPayment: [spent]);
        Settle(game);

        // Home rather than to a graveyard, and the token is what it bought.
        Assert.Contains(
            game.State.GetPlayer(alice).Hand,
            id => game.State.GetObject(id).Card.Name == "Island");

        Assert.Contains(
            game.State.Battlefield,
            id => game.State.GetObject(id).Card.Name == "Illusion");

        Assert.DoesNotContain(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Island");
    }

    // ---- Cost modifiers, read off the card (CR 601.2f, 602.2b) --------------

    /// <summary>A land the compiler reads, so nothing on the path under test is hand written.</summary>
    private static readonly CardDefinition ModifierForest = new()
    {
        OracleId = "oracle-cost-modifier-forest-test",
        Name = "Cost Modifier Forest Test",
        OracleText = "{T}: Add {G}.",
        CardTypes = CardType.Land,
    };

    /// <summary>Adds one more green to the pool, from a land whose text was compiled.</summary>
    private static void TapCompiledForest(Game game, Guid playerId, int count)
    {
        for (var i = 0; i < count; i++)
        {
            game.ActivateAbility(
                playerId,
                game.Create(playerId, ModifierForest, Zone.Battlefield),
                "mana");
        }
    }

    /// <summary>
    /// "Spells your opponents cast cost {2} more to cast" — God-Pharaoh's Statue (CR 601.2f).
    /// </summary>
    /// <remarks>
    /// The engine could apply every cell of the cost grid and no card could say any of them:
    /// nothing implemented <c>ICostModifierSource</c>, so <c>Game</c>'s pattern match found no
    /// source and the whole capability was unreachable from a printed line. This is the compiled
    /// half of that seam, played through a real cast.
    /// <para>
    /// The first assertion is the one that catches the wrong reading. The only cost modification
    /// this engine used to have walked the <em>caster's own</em> battlefield, so a tax scoped to
    /// opponents read that way is a card that prints one thing and plays its opposite.
    /// </para>
    /// <para>
    /// The compiled card carries a modifier and no reducer, and that is asserted rather than
    /// assumed: <c>Game.ModifiersOn</c> reads both lists and translates a reducer into the
    /// modifier it equals, so a card emitting both would be taxed or discounted twice.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_compiled_tax_on_opponents_spells_spares_its_own_controller()
    {
        var statue = Card(
            "Compiled Opponent Tax Test",
            "Spells your opponents cast cost {2} more to cast.",
            CardType.Artifact);

        Assert.Single(Pool.CostModifiersOf(statue));
        Assert.Empty(((IAbilitySource)Pool).CostReducersOf(statue));

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, statue, Zone.Battlefield);

        // Alice controls it, so Alice is not among the opponents it names.
        var hers = TestCards.PutInHand(
            game, alice, TestCards.Costed("Untaxed Compiled Bear Test", "{G}", 1));

        TapCompiledForest(game, alice, 1);
        game.CastSpell(alice, hers, []);
        Assert.True(game.State.GetPlayer(alice).ManaPool.IsEmpty);
        Settle(game);

        PassToMainPhaseOf(game, bob);
        var theirs = TestCards.PutInHand(
            game, bob, TestCards.Costed("Taxed Compiled Bear Test", "{G}", 1));

        TapCompiledForest(game, bob, 1);
        Assert.Throws<InvalidOperationException>(() => game.CastSpell(bob, theirs, []));

        // {G} plus the {2} it is taxed, and no more: the increase touches generic mana only.
        TapCompiledForest(game, bob, 2);
        game.CastSpell(bob, theirs, []);
        Assert.True(game.State.GetPlayer(bob).ManaPool.IsEmpty);
        Settle(game);
    }

    /// <summary>
    /// "Noncreature spells cost {1} more to cast" — Thorn of Amethyst (CR 601.2f).
    /// </summary>
    /// <remarks>
    /// The bare form names nobody, and naming nobody means everybody — its own controller
    /// included. That is the entire difference between this card and the one above, and reading
    /// the two the same way turns a symmetrical prison into a one-sided one.
    /// </remarks>
    [Fact]
    public void A_compiled_bare_tax_is_paid_by_its_own_controller()
    {
        var thorn = Card(
            "Compiled Bare Tax Test",
            "Noncreature spells cost {1} more to cast.",
            CardType.Artifact);

        var gain = new CardDefinition
        {
            OracleId = "oracle-compiled-taxed-instant-test",
            Name = "Compiled Taxed Instant Test",
            OracleText = "You gain 1 life.",
            CardTypes = CardType.Instant,
            ManaCostRaw = "{G}",
        };

        var (game, alice, _) = InMainPhase();
        game.Create(alice, thorn, Zone.Battlefield);

        // A creature spell is not what the line names, so it costs what it prints.
        var bear = TestCards.PutInHand(
            game, alice, TestCards.Costed("Compiled Unnamed Bear Test", "{G}", 1));

        TapCompiledForest(game, alice, 1);
        game.CastSpell(alice, bear, []);
        Settle(game);

        var instant = TestCards.PutInHand(game, alice, gain);

        TapCompiledForest(game, alice, 1);
        Assert.Throws<InvalidOperationException>(() => game.CastSpell(alice, instant, []));

        TapCompiledForest(game, alice, 1);
        game.CastSpell(alice, instant, []);
        Assert.True(game.State.GetPlayer(alice).ManaPool.IsEmpty);
        Settle(game);
    }

    /// <summary>
    /// "Activated abilities of lands you control cost {1} less to activate" — Blossoming
    /// Tortoise (CR 602.2b).
    /// </summary>
    /// <remarks>
    /// Two scopes, and this is what tells them apart on a compiled card. "Lands you control"
    /// says whose permanent the ability sits on and nothing at all about who activates it, so it
    /// is read as <c>SourceController</c> and not as <c>Who</c>. Bob's land is the same card
    /// with the same ability and pays the printed price, because it is not one Alice controls.
    /// </remarks>
    [Fact]
    public void A_compiled_discount_on_your_lands_abilities_misses_an_opponents_land()
    {
        var tortoise = Card(
            "Compiled Land Discount Test",
            "Activated abilities of lands you control cost {1} less to activate.",
            CardType.Creature,
            3,
            3);

        var well = new CardDefinition
        {
            OracleId = "oracle-compiled-discounted-well-test",
            Name = "Compiled Discounted Well Test",
            OracleText = "{2}: You gain 1 life.",
            CardTypes = CardType.Land,
        };

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, tortoise, Zone.Battlefield);
        var hers = game.Create(alice, well, Zone.Battlefield);

        TapCompiledForest(game, alice, 1);
        game.ActivateAbility(alice, hers, "a");
        Assert.True(game.State.GetPlayer(alice).ManaPool.IsEmpty);
        Settle(game);

        PassToMainPhaseOf(game, bob);
        var theirs = game.Create(bob, well, Zone.Battlefield);

        TapCompiledForest(game, bob, 1);
        Assert.Throws<InvalidOperationException>(() => game.ActivateAbility(bob, theirs, "a"));

        TapCompiledForest(game, bob, 1);
        game.ActivateAbility(bob, theirs, "a");
        Assert.True(game.State.GetPlayer(bob).ManaPool.IsEmpty);
        Settle(game);
    }

    /// <summary>
    /// "Spells you cast from your graveyard cost {1} less to cast" — Patrician Geist (CR 400.1).
    /// </summary>
    /// <remarks>
    /// The zone has to be read on the modifier and on the cost together. A reduction that
    /// carried the words and then applied from anywhere would make every spell in hand cheaper
    /// as well, which is a strictly better card than the unread one — so the assertion that
    /// earns this its place is the one about the spell still in hand.
    /// </remarks>
    [Fact]
    public void A_compiled_graveyard_discount_does_not_reach_a_spell_cast_from_hand()
    {
        var geist = Card(
            "Compiled Graveyard Discount Test",
            "Spells you cast from your graveyard cost {1} less to cast.",
            CardType.Creature,
            2,
            2);

        var flashback = new CardDefinition
        {
            OracleId = "oracle-compiled-flashback-discount-test",
            Name = "Compiled Flashback Discount Test",
            OracleText = "You gain 3 life.\nFlashback {2}",
            CardTypes = CardType.Sorcery,
            ManaCostRaw = "{4}",
        };

        var fromHand = new CardDefinition
        {
            OracleId = "oracle-compiled-undiscounted-hand-test",
            Name = "Compiled Undiscounted Hand Test",
            OracleText = "You gain 3 life.",
            CardTypes = CardType.Sorcery,
            ManaCostRaw = "{2}",
        };

        var (game, alice, _) = InMainPhase();
        game.Create(alice, geist, Zone.Battlefield);

        // Flashback for {2}, less the {1} the graveyard is worth.
        var buried = game.Create(alice, flashback, Zone.Graveyard);
        TapCompiledForest(game, alice, 1);
        game.CastSpell(alice, buried);
        Settle(game);

        Assert.Equal(23, game.State.GetPlayer(alice).Life);

        // The same discount does not follow a spell cast from hand (CR 400.1).
        var held = TestCards.PutInHand(game, alice, fromHand);
        TapCompiledForest(game, alice, 1);
        Assert.Throws<InvalidOperationException>(() => game.CastSpell(alice, held));

        TapCompiledForest(game, alice, 1);
        game.CastSpell(alice, held);
        Settle(game);

        Assert.Equal(26, game.State.GetPlayer(alice).Life);
    }

    // ---- An alternative cost of nothing (CR 118.9) ---------------------------

    /// <summary>A land the compiler reads, so the mana on this path is compiled too.</summary>
    private static readonly CardDefinition FreeCastMountain = new()
    {
        OracleId = "oracle-free-cast-mountain-test",
        Name = "Free Cast Mountain Test",
        OracleText = "{T}: Add {R}.",
        CardTypes = CardType.Land,
        Subtypes = ["Mountain"],
    };

    /// <summary>Mogg Salvage's wording, whose whole cost the board decides.</summary>
    private static readonly CardDefinition FreeCastSalvage = new()
    {
        OracleId = "oracle-free-cast-salvage-test",
        Name = "Free Cast Salvage Test",
        OracleText = "If an opponent controls an Island and you control a Mountain, you may "
            + "cast this spell without paying its mana cost.\nDestroy target artifact.",
        CardTypes = CardType.Instant,
        ManaCostRaw = "{2}{R}",
    };

    /// <summary>
    /// "If …, you may cast this spell without paying its mana cost" — the second phrasing
    /// CR 118.9 gives for an alternative cost, and the one that costs nothing.
    /// </summary>
    /// <remarks>
    /// The card has to survive both halves of the offer, so the test spends the same board
    /// twice. The free cast taps nothing — asserted against the lands themselves rather than
    /// against a pool, because a pool that was filled and emptied looks the same afterwards as
    /// one that was never touched. Then the *second* copy is cast on the same board with the
    /// same condition true, and it costs {2}{R}: an alternative cost is announced by the caster
    /// (CR 118.9b, 601.2b), so a card that could no longer be cast for its printed cost would be
    /// a different card from the one printed.
    /// <para>
    /// That is the whole reason this compiles to a <see cref="ConditionalCost"/> rather than to
    /// the engine's other route. <c>AlternativeCastZone</c> is taken <em>unconditionally</em>
    /// whenever the card is in the zone that offers it, and reading a free cast from hand that
    /// way would leave the printed cost unreachable — the failure that still keeps More Than
    /// Meets the Eye unread.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_free_alternative_cost_is_announced_and_never_taken_by_default()
    {
        var (game, alice, bob) = InMainPhase();

        game.Create(bob, TestCards.BasicLand("Island"), Zone.Battlefield);
        var mountains = new[]
        {
            game.Create(alice, FreeCastMountain, Zone.Battlefield),
            game.Create(alice, FreeCastMountain, Zone.Battlefield),
            game.Create(alice, FreeCastMountain, Zone.Battlefield),
        };

        var relic = Card("Free Cast Relic Test", string.Empty, CardType.Artifact);
        var first = game.Create(bob, relic, Zone.Battlefield);
        var second = game.Create(bob, relic, Zone.Battlefield);

        var free = TestCards.PutInHand(game, alice, FreeCastSalvage);
        game.CastSpell(alice, free, [Target.ToPermanent(first)], alternativeCost: true);
        Settle(game);

        Assert.DoesNotContain(first, game.State.Battlefield);
        Assert.All(
            mountains,
            id => Assert.False(game.State.GetObject(id).Permanent!.IsTapped));

        // The same board, the same condition, and no announcement: the printed cost is what is
        // charged, and with no mana in the pool there is nothing to charge it against.
        var paid = TestCards.PutInHand(game, alice, FreeCastSalvage);
        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, paid, [Target.ToPermanent(second)]));

        foreach (var id in mountains)
            game.ActivateAbility(alice, id, "mana");

        game.CastSpell(alice, paid, [Target.ToPermanent(second)]);
        Settle(game);

        Assert.DoesNotContain(second, game.State.Battlefield);
        Assert.All(mountains, id => Assert.True(game.State.GetObject(id).Permanent!.IsTapped));
    }

    /// <summary>
    /// The offer is refused when the board does not make it, and the refusal names its rule.
    /// </summary>
    /// <remarks>
    /// Kept apart from the cast above because it is a different mistake and has to stay a
    /// different answer: a card with no such offer at all is a client sending a flag the card
    /// never had, while a card whose condition is false is a player who has misread the board.
    /// Here nobody controls an Island, so the condition is false and the spell may only be cast
    /// for {2}{R}.
    /// </remarks>
    [Fact]
    public void A_free_alternative_cost_is_refused_when_its_condition_is_false()
    {
        var (game, alice, bob) = InMainPhase();

        game.Create(alice, FreeCastMountain, Zone.Battlefield);
        var relic = game.Create(
            bob, Card("Free Cast Relic Test", string.Empty, CardType.Artifact), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, FreeCastSalvage);

        var refused = Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, card, [Target.ToPermanent(relic)], alternativeCost: true));

        Assert.Contains("118.9a", refused.Message, StringComparison.Ordinal);
        Assert.Contains(relic, game.State.Battlefield);
    }

    // ---- Somebody else's arrival, replaced (CR 614.1d) -----------------------

    /// <summary>Renata's wording, on a creature that is not the one arriving.</summary>
    private static readonly CardDefinition AdditionalCounterLord = new()
    {
        OracleId = "oracle-additional-counter-lord-test",
        Name = "Additional Counter Lord Test",
        OracleText = "Each other creature you control enters with an additional +1/+1 counter on it.",
        CardTypes = CardType.Creature,
        Subtypes = ["Elf"],
        Power = 2,
        Toughness = 2,
    };

    /// <summary>
    /// "Each other creature you control enters with an additional +1/+1 counter on it" — an
    /// entry replacement that belongs to somebody else's arrival (CR 614.1d).
    /// </summary>
    /// <remarks>
    /// Three assertions, and the second and third are the ones that catch a wrong reading.
    /// A mass line with an ownership clause that applied to the whole board is the defect this
    /// file has already recorded on 83 cards of a different shape, so Bob's creature arriving at
    /// its printed size is what proves the clause was read. And the lord itself arrives with no
    /// counter: the replacement pipeline builds an arriving object from its own event and offers
    /// it its own replacements — the branch that lets a token copy enter with the counters its
    /// card names — so without the identity check this line would quietly hand itself the
    /// counter it only ever gives to others.
    /// </remarks>
    [Fact]
    public void A_group_entry_replacement_counts_only_its_controllers_other_arrivals()
    {
        var (game, alice, bob) = InMainPhase();

        var lord = game.Create(alice, AdditionalCounterLord, Zone.Battlefield);
        Assert.Equal(2, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(lord)));

        var mine = game.Create(
            alice, TestCards.Creature("Additional Counter Bear Test", 2, 2), Zone.Battlefield);
        var theirs = game.Create(
            bob, TestCards.Creature("Additional Counter Bear Test", 2, 2), Zone.Battlefield);
        Settle(game);

        Assert.Equal(
            1, game.State.GetObject(mine).Permanent!.Counters[CounterKinds.PlusOnePlusOne]);
        Assert.Equal(3, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(mine)));

        Assert.DoesNotContain(
            CounterKinds.PlusOnePlusOne, game.State.GetObject(theirs).Permanent!.Counters);
        Assert.Equal(2, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(theirs)));
    }

    /// <summary>
    /// "Each planeswalker you control enters with an additional loyalty counter on it" — Oath of
    /// Gideon, the same line with the counter a planeswalker keeps its loyalty in (CR 614.1d).
    /// </summary>
    /// <remarks>
    /// The counter's name is where this family has to refuse rather than read. Power and
    /// toughness are worked out from the two counters <c>CounterKinds</c> names and loyalty from
    /// a third; a "vigilance counter" would be recorded under its printed name and read by
    /// nothing, so the card would compile complete and grant no vigilance. One corpus card says
    /// that and is left unread on purpose.
    /// </remarks>
    [Fact]
    public void A_group_entry_replacement_can_add_a_loyalty_counter()
    {
        var oath = new CardDefinition
        {
            OracleId = "oracle-additional-counter-oath-test",
            Name = "Additional Counter Oath Test",
            OracleText =
                "Each planeswalker you control enters with an additional loyalty counter on it.",
            CardTypes = CardType.Enchantment,
        };

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, oath, Zone.Battlefield);

        var walker = Walker("Additional Counter Walker Test", 3, string.Empty);
        var mine = game.Create(alice, walker, Zone.Battlefield);
        var theirs = game.Create(bob, walker, Zone.Battlefield);
        Settle(game);

        Assert.Equal(4, game.State.GetObject(mine).Permanent!.Counters[CounterKinds.Loyalty]);
        Assert.Equal(3, game.State.GetObject(theirs).Permanent!.Counters[CounterKinds.Loyalty]);
    }

    // ---- "It" in a conditional static, on both sides of the word ------------

    /// <summary>
    /// "As long as ~ is untapped, it gets +0/+2" — the pronoun means the card, not a host.
    /// </summary>
    /// <remarks>
    /// The reader took every subject that was not "~" for the thing an Aura is attached to, so
    /// "it" reached <c>AttachedTo</c> — which is null on a creature, because a creature is not
    /// attached to anything. **29 corpus lines applied to no object at all**, 17 of them on
    /// cards that were otherwise complete and where that static is the card's only one: Castle
    /// Raptors computed 3/3 instead of 3/5, Fleecemane Lion never became hexproof, Adanto
    /// Vanguard never grew while attacking.
    /// <para>
    /// Nothing could see it. The card declares a static, so it is not inert to the guard that
    /// looks for cards which compile and do nothing; it names no subtype, so the subtype
    /// invariant has nothing to check; and an effect that applies to no object throws nothing,
    /// computes fine and replays exactly — which is every assertion the soak makes.
    /// </para>
    /// <para>
    /// Both arms are asserted here because either one alone passes a reader that is wrong the
    /// other way. The equipped case is the one that pins the order: "As long as ~ is equipped,
    /// it gets +1/+1" contains the word "equipped" and still means the card, so what the
    /// condition <em>names</em> has to be asked before the attachment words are.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_pronoun_subject_is_whatever_the_condition_in_front_of_it_named()
    {
        var raptors = Card(
            "Untapped Pronoun Test",
            "As long as ~ is untapped, it gets +0/+2.",
            CardType.Creature, 3, 3);

        var lightbringer = Card(
            "Equipped Pronoun Test",
            "As long as ~ is equipped, it gets +1/+1.",
            CardType.Creature, 2, 3);

        var aura = Card(
            "Pronoun Host Aura Test",
            "Enchant permanent" + (char)10
                + "As long as enchanted permanent is a creature, it gets +2/+2.",
            CardType.Enchantment, null, null, KeywordAbility.None, "Aura");

        var (game, alice, _) = InMainPhase();

        // The card talking about itself, with nothing attached to anything.
        var bird = game.Create(alice, raptors, Zone.Battlefield);
        Settle(game);
        Assert.Equal(5, Characteristics.ToughnessOf(game.State, Pool, game.State.GetObject(bird)));

        game.Tap(bird);
        Settle(game);
        Assert.Equal(3, Characteristics.ToughnessOf(game.State, Pool, game.State.GetObject(bird)));

        // The same reading where a host does exist, which is what stops "it" being resolved by
        // looking for an attachment: the Equipment is attached to the creature, and the bonus
        // still belongs to the creature the condition named.
        var cat = game.Create(alice, lightbringer, Zone.Battlefield);
        Settle(game);
        Assert.Equal(2, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(cat)));

        var sword = game.Create(
            alice,
            Card("Pronoun Equipment Test", "Equip {2}", CardType.Artifact,
                null, null, KeywordAbility.None, "Equipment"),
            Zone.Battlefield);

        game.Attach(sword, cat);
        Settle(game);
        Assert.Equal(3, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(cat)));

        // And the other arm, unchanged: on an Aura the condition names the enchanted permanent,
        // so the pronoun does too — the Aura is not a creature and could not use the bonus.
        var bear = game.Create(
            alice, TestCards.Creature("Pronoun Host Bear Test", 2, 2), Zone.Battlefield);
        var attached = game.Create(alice, aura, Zone.Battlefield);
        game.Attach(attached, bear);
        Settle(game);

        Assert.Equal(4, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(bear)));
    }

    /// <summary>
    /// "Harmonize {3}{G}" — cast from the graveyard for that cost, then exiled (CR 702.180a).
    /// </summary>
    /// <remarks>
    /// The card is cast both ways here, and the second half is the one that earns the test. An
    /// alternative cast route taken unconditionally would read as a card that can only ever be
    /// played out of the graveyard, and a test that only harmonized it would pass against that.
    /// So the same card is also cast from hand for its printed cost, and the two casts are told
    /// apart by where the sorcery ends up: harmonize exiles it, the ordinary cast does not.
    /// <para>
    /// The refused cast is what pins the price. Without it a reader that lost the cost entirely
    /// and cast the card for nothing would look identical from the life total.
    /// </para>
    /// <para>
    /// What this does not exercise is CR 702.180a's second static ability — "tapping up to one
    /// untapped creature you control" and the reduction by that creature's power — which is not
    /// built. "Up to one" is why the card is still complete without it: tapping nothing is a
    /// legal way to pay, so every cast this allows is one the rules allow, at the printed price
    /// or dearer.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_harmonized_card_is_cast_from_the_graveyard_for_its_own_cost_and_then_exiled()
    {
        var stories = new CardDefinition
        {
            OracleId = "oracle-harmonize-test",
            Name = "Harmonize Test",
            OracleText = "You gain 3 life.\nHarmonize {3}{G}",
            CardTypes = CardType.Sorcery,
            ManaCostRaw = "{1}{G}",
        };

        var compiled = CardCompiler.Compile(stories);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();

        // Four mana, not the two it costs from hand: the graveyard route charges the harmonize
        // cost and nothing else.
        var buried = game.Create(alice, stories, Zone.Graveyard);
        TapCompiledForest(game, alice, 3);
        Assert.Throws<InvalidOperationException>(() => game.CastSpell(alice, buried));

        TapCompiledForest(game, alice, 1);
        game.CastSpell(alice, buried);
        Settle(game);

        Assert.Equal(23, game.State.GetPlayer(alice).Life);

        // CR 702.180a's third static ability: exiled instead of going anywhere else as it leaves
        // the stack, which is what stops the same card being harmonized every turn.
        Assert.Contains(
            game.State.Exile.Select(game.State.GetObject),
            o => o.Card.Name == "Harmonize Test");

        Assert.DoesNotContain(
            game.State.Contents(Zone.Graveyard, alice).Select(game.State.GetObject),
            o => o.Card.Name == "Harmonize Test");

        // And the printed cost still works. A route that replaced the mana cost rather than
        // adding a way to cast from the graveyard would have made this two mana short.
        var held = TestCards.PutInHand(game, alice, stories);
        TapCompiledForest(game, alice, 2);
        game.CastSpell(alice, held);
        Settle(game);

        Assert.Equal(26, game.State.GetPlayer(alice).Life);

        // Cast from hand it is an ordinary sorcery: the exile belongs to the harmonize cast, not
        // to the card.
        Assert.Contains(
            game.State.Contents(Zone.Graveyard, alice).Select(game.State.GetObject),
            o => o.Card.Name == "Harmonize Test");
    }

    /// <summary>
    /// "This land enters tapped. As it enters, choose a color." (CR 305.1, 614.12).
    /// </summary>
    /// <remarks>
    /// Two facts on one line, and every matcher in the compiler is anchored to a whole line — so
    /// the pair matched nothing while each half matched on its own. Thirteen colour-fixing lands
    /// print them together.
    /// <para>
    /// Both halves are asserted because reading either one alone is a different and wrong card:
    /// a land that names a colour and arrives untapped is strictly better than the one printed,
    /// and one that arrives tapped and never names a colour taps for nothing at all.
    /// </para>
    /// <para>
    /// The last assertion is the refusal. Five of the thirteen say "choose a color <em>other
    /// than</em> red", and <c>ChoiceOnEntry</c> names a kind of choice with nowhere to put an
    /// excluded colour — so those stay unread rather than being offered the colour the card
    /// forbids.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_land_that_enters_tapped_and_names_a_colour_does_both()
    {
        var haven = Card(
            "Entering Haven Test",
            "This land enters tapped. As it enters, choose a color."
                + "\n{T}: Add one mana of the chosen color.",
            CardType.Land);

        var compiled = CardCompiler.Compile(haven);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var land = game.Create(alice, haven, Zone.Battlefield);

        // The first sentence: a replacement, so it is already tapped before anyone has priority.
        Assert.True(game.State.GetObject(land).Permanent!.IsTapped);

        // The second: the question is asked as it arrives, and answered by the player.
        game.PassPriority(alice);

        var asked = game.State.Choice;
        Assert.NotNull(asked);
        Assert.Equal(ChoiceKind.NameCharacteristic, asked.Kind);
        game.Choose(asked.PlayerId, ["blue"]);

        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber == 3 && game.State.CurrentStep == TurnStep.PrecombatMain);

        var back = game.State.Battlefield.Select(game.State.GetObject)
            .Single(o => o.Card.Name == "Entering Haven Test");

        Assert.Equal("blue", back.Chosen);
        Assert.False(back.Permanent!.IsTapped);

        game.ActivateAbility(alice, back.Id, "mana");
        Assert.Equal(1, game.State.GetPlayer(alice).ManaPool[ManaColor.Blue]);

        // The excluded-colour printing is refused whole rather than read as an open choice.
        var thriving = Card(
            "Thriving Entering Test",
            "This land enters tapped. As it enters, choose a color other than red."
                + "\n{T}: Add {C}.",
            CardType.Land);

        Assert.Contains(
            "~ enters tapped. As it enters, choose a color other than red.",
            CardCompiler.Compile(thriving).Unhandled);
    }

    /// <summary>
    /// "Disturb {1}{W}" — cast from the graveyard, arriving with the back face up (CR 702.146a).
    /// </summary>
    /// <remarks>
    /// Flashback's shape with one difference, and it is the whole mechanic: the card comes back
    /// as its <em>other</em> face. 31 faces carry this line, and each held back a whole card,
    /// because a card is playable only when every face of it reads.
    /// <para>
    /// The turn-over is derived at resolution rather than carried on an event: the object already
    /// records the zone it was cast from and the card already says which zone turns it over, so a
    /// replay reaches the same permanent without an event whose only job is to hold a flag.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_disturbed_card_comes_back_as_its_other_face()
    {
        var spirit = new CardDefinition
        {
            OracleId = "oracle-disturb-test",
            Name = "Disturb Front Test",
            CardTypes = CardType.Creature,
            Power = 2,
            Toughness = 2,
            ManaCostRaw = "{1}{W}",
            OracleText = "Disturb {1}{W}",
            Faces =
            [
                new CardFace
                {
                    Name = "Disturb Front Test",
                    CardTypes = CardType.Creature,
                    Power = 2,
                    Toughness = 2,
                    ManaCostRaw = "{1}{W}",
                    OracleText = "Disturb {1}{W}",
                },
                new CardFace
                {
                    Name = "Disturb Back Test",
                    CardTypes = CardType.Creature,
                    Power = 1,
                    Toughness = 4,
                    Keywords = KeywordAbility.Flying,
                },
            ],
        };

        var compiled = CardCompiler.Compile(spirit);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();

        var dead = game.Create(alice, spirit, Zone.Graveyard);

        foreach (var _ in Enumerable.Range(0, 2))
        {
            var land = game.Create(alice, TestCards.BasicLand("Plains"), Zone.Battlefield);
            game.ActivateAbility(alice, land, "mana");
        }

        game.CastSpell(alice, dead);
        Settle(game);

        // It is on the battlefield as the back face: 1/4 flier, not the 2/2 that died.
        var returned = game.State.Battlefield
            .Select(game.State.GetObject)
            .Single(o => o.Card.Name.StartsWith("Disturb ", StringComparison.Ordinal));

        Assert.Equal("Disturb Back Test", returned.Card.Name);
        Assert.Equal(1, returned.Permanent!.FaceIndex);

        var now = Characteristics.Of(game.State, Pool, returned);
        Assert.Equal(1, now.Power);
        Assert.Equal(4, now.Toughness);
        Assert.True(now.Has(KeywordAbility.Flying));

        // Nothing is left in the graveyard to disturb a second time.
        Assert.Empty(game.State.GetPlayer(alice).Graveyard);
    }

    // ---- Conditions about the board the vocabulary could not ask ------------

    /// <summary>
    /// "As long as you control your commander, ~ gets +2/+2" — the lieutenant cycle (CR 903.3).
    /// </summary>
    /// <remarks>
    /// Being a commander is an attribute of the <em>card</em> rather than of the object
    /// representing it (CR 903.3), so the question is asked by oracle id. A commander that dies
    /// and is recast is a new object every time (CR 400.7), and a reader that remembered an
    /// object would answer "no" from the second cast onwards.
    /// <para>
    /// Bob's copy of the same card is the assertion that matters. It is pumped by nothing while
    /// Alice's commander is on the battlefield, because he has no commander at all — and a
    /// reader that asked "is a commander out" rather than "is <em>yours</em> out" passes every
    /// other line here and fails only that one.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_lieutenant_is_pumped_only_by_its_own_controllers_commander()
    {
        const string commanderId = "oracle-lieutenant-test-general";

        var general = new CardDefinition
        {
            OracleId = commanderId,
            Name = "Lieutenant Test General",
            CardTypes = CardType.Creature,
            Supertypes = ["Legendary"],
            Power = 3,
            Toughness = 3,
        };

        var soldier = Card(
            "Lieutenant Test",
            "As long as you control your commander, ~ gets +2/+2.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var compiled = CardCompiler.Compile(soldier);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var alice = Guid.Parse("11111111-1111-1111-1111-111111111111");
        var bob = Guid.Parse("22222222-2222-2222-2222-222222222222");

        var game = Game.Start(
            Guid.NewGuid(),
            [
                new PlayerSetup(
                    alice,
                    "Alice",
                    40,
                    TestCards.Deck(40, "Alice").Concat([general]).ToList())
                {
                    CommanderOracleId = commanderId,
                },
                new PlayerSetup(bob, "Bob", 40, TestCards.Deck(40, "Bob")),
            ],
            new GameRandom(1),
            startingPlayerId: alice,
            abilities: Pool);

        game.BeginPlay(withMulligans: false);
        TestCards.PassToStep(game, TurnStep.PrecombatMain);

        var hers = game.Create(alice, soldier, Zone.Battlefield);
        var his = game.Create(bob, soldier, Zone.Battlefield);

        // The commander starts in the command zone, which is not the battlefield (CR 903.6).
        Assert.Equal(2, Characteristics.Of(game.State, Pool, game.State.GetObject(hers)).Power);

        var onBoard = game.Create(alice, general, Zone.Battlefield);
        Settle(game);

        Assert.Equal(4, Characteristics.Of(game.State, Pool, game.State.GetObject(hers)).Power);
        Assert.Equal(2, Characteristics.Of(game.State, Pool, game.State.GetObject(his)).Power);

        // And off again when it leaves. A static re-asks its question continuously, and these
        // cards are printed to be switched off by removing the commander.
        game.Move(onBoard, Zone.Exile, MoveCause.Exile);
        Settle(game);

        Assert.Equal(2, Characteristics.Of(game.State, Pool, game.State.GetObject(hers)).Power);
    }

    /// <summary>
    /// "As long as there are five or more mana values among cards in your graveyard, ~ gets
    /// +2/+2" — distinct mana values, not a count of cards (CR 202.3).
    /// </summary>
    /// <remarks>
    /// The graveyard is filled with five cards carrying four values first, and the assertion is
    /// that nothing happens. A reader that counted cards — the count sitting immediately beside
    /// this one — passes every other line in this test and turns the bonus on a card early. The
    /// fifth value then arrives as a new cost rather than as a fifth card, which is the same
    /// distinction taken from the other side.
    /// </remarks>
    [Fact]
    public void A_mana_value_count_counts_the_values_and_not_the_cards()
    {
        var scholar = Card(
            "Mana Value Test",
            "As long as there are five or more mana values among cards in your graveyard, "
                + "~ gets +2/+2.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var compiled = CardCompiler.Compile(scholar);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var creature = game.Create(alice, scholar, Zone.Battlefield);

        // Five cards, four values: two of them cost the same, which is the whole difference
        // between this question and the card count printed one line away from it.
        (string Name, int Cost)[] buried =
        [
            ("Mana Value Filler A", 1),
            ("Mana Value Filler B", 1),
            ("Mana Value Filler C", 2),
            ("Mana Value Filler D", 3),
            ("Mana Value Filler E", 4),
        ];

        foreach (var (name, cost) in buried)
        {
            game.Create(
                alice,
                new CardDefinition
                {
                    OracleId = "oracle-" + name.ToLowerInvariant().Replace(' ', '-'),
                    Name = name,
                    CardTypes = CardType.Instant,
                    Cmc = cost,
                },
                Zone.Graveyard);
        }

        Settle(game);

        Assert.Equal(5, game.State.GetPlayer(alice).Graveyard.Count);
        Assert.Equal(2, Characteristics.Of(game.State, Pool, game.State.GetObject(creature)).Power);

        game.Create(
            alice,
            new CardDefinition
            {
                OracleId = "oracle-mana-value-fifth",
                Name = "Mana Value Fifth",
                CardTypes = CardType.Instant,
                Cmc = 5,
            },
            Zone.Graveyard);

        Settle(game);

        Assert.Equal(4, Characteristics.Of(game.State, Pool, game.State.GetObject(creature)).Power);
    }

    /// <summary>
    /// "As long as you have a full party, ~ gets +2/+2" — four roles filled at once (CR 700.8c).
    /// </summary>
    /// <remarks>
    /// CR 700.8b is what this test exists for, and the board is shaped to fail two different
    /// wrong readings of it. It starts as a Cleric Rogue, a Warrior and a Wizard: three roles
    /// filled, because that one creature cannot be both of the two it could be — which is where
    /// a reader that asked "is a Cleric out, is a Rogue out" independently turns the bonus on a
    /// creature early.
    /// <para>
    /// The party is then completed by a plain <em>Cleric</em>, and that is the second reading.
    /// Filling the roles in order and never revisiting gives the Cleric slot to the Cleric Rogue
    /// and then has nothing left for the Rogue slot; the count has to be taken the way that
    /// gives the highest result, which means moving the Cleric slot onto the newcomer and
    /// handing the Cleric Rogue to the Rogue slot.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_full_party_counts_each_creature_for_only_one_of_its_roles()
    {
        var captain = Card(
            "Party Test",
            "As long as you have a full party, ~ gets +2/+2.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var compiled = CardCompiler.Compile(captain);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var creature = game.Create(alice, captain, Zone.Battlefield);

        game.Create(
            alice,
            Card(
                "Party Test Scout", string.Empty, CardType.Creature, 1, 1,
                KeywordAbility.None, "Cleric", "Rogue"),
            Zone.Battlefield);

        game.Create(
            alice,
            Card(
                "Party Test Soldier", string.Empty, CardType.Creature, 1, 1,
                KeywordAbility.None, "Warrior"),
            Zone.Battlefield);

        game.Create(
            alice,
            Card(
                "Party Test Mage", string.Empty, CardType.Creature, 1, 1,
                KeywordAbility.None, "Wizard"),
            Zone.Battlefield);

        Settle(game);

        Assert.Equal(2, Characteristics.Of(game.State, Pool, game.State.GetObject(creature)).Power);

        game.Create(
            alice,
            Card(
                "Party Test Priest", string.Empty, CardType.Creature, 1, 1,
                KeywordAbility.None, "Cleric"),
            Zone.Battlefield);

        Settle(game);

        Assert.Equal(4, Characteristics.Of(game.State, Pool, game.State.GetObject(creature)).Power);
    }

    /// <summary>
    /// "When ~ enters, if it was bargained, ..." — the flag read off the permanent that arrives
    /// rather than off the spell that was cast (CR 702.166b).
    /// </summary>
    /// <remarks>
    /// The sentence form of this was already read, and it is answered on the stack where the
    /// spell still exists. Seven cards ask it as an intervening-if on a permanent instead, and
    /// that is a different object from the spell (CR 400.7) — so the fact has to have ridden the
    /// zone change, exactly as kicker's does.
    /// <para>
    /// The theory drives both halves because the case that matters is the one where nothing
    /// happens: a wrapper that ignored the condition gains the life either way, and a test that
    /// only bargained could not tell it from a correct one.
    /// </para>
    /// </remarks>
    [Theory]
    [InlineData(true, 23)]
    [InlineData(false, 20)]
    public void A_bargained_permanent_still_knows_it_after_it_arrives(
        bool bargained, int expectedLife)
    {
        var ouphe = Card(
            "Bargain Enters Test",
            "Bargain\nWhen ~ enters, if it was bargained, you gain 3 life.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var compiled = CardCompiler.Compile(ouphe);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();

        var relic = game.Create(
            alice,
            Card("Bargain Enters Relic", string.Empty, CardType.Artifact),
            Zone.Battlefield);

        game.CastSpell(
            alice,
            TestCards.PutInHand(game, alice, ouphe),
            targets: null,
            costPayment: bargained ? [relic] : null,
            bargained: bargained);

        Settle(game);

        Assert.Equal(expectedLife, game.State.GetPlayer(alice).Life);

        // And the cost was really paid — a bargain that took nothing would gain the life anyway.
        Assert.Equal(!bargained, game.State.Battlefield.Contains(relic));
    }

    /// <summary>
    /// "When ~ enters, if there is no monarch, you become the monarch" — the third state of a
    /// field that is usually asked about as two (CR 725.1).
    /// </summary>
    /// <remarks>
    /// There is no monarch in a game until an effect makes one, and the six cards that ask this
    /// are the ones that hand the crown out. Reading the clause as "somebody else is the
    /// monarch" — the reading already beside it — would make every one of them fire exactly when
    /// it must not, and the card would compile and play as a way of <em>taking</em> the crown.
    /// <para>
    /// Bob's copy entering while Alice already wears it is that assertion.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_crown_that_asks_for_no_monarch_only_creates_one()
    {
        var crown = Card(
            "No Monarch Test",
            "When ~ enters, if there is no monarch, you become the monarch.",
            CardType.Artifact);

        var compiled = CardCompiler.Compile(crown);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();

        Assert.Null(game.State.MonarchId);

        game.Create(alice, crown, Zone.Battlefield);
        Settle(game);

        Assert.Equal(alice, game.State.MonarchId);

        game.Create(bob, crown, Zone.Battlefield);
        Settle(game);

        Assert.Equal(alice, game.State.MonarchId);
    }

    /// <summary>
    /// "As long as there are two or more ki counters on ~, ~ gets +2/+2" — a threshold of
    /// counters, asked with the subject at the back (CR 122.1).
    /// </summary>
    /// <remarks>
    /// The same question the vocabulary already answered with the subject at the front, and
    /// thirty-nine lines print it this way round: every permanent that collects counters and
    /// does something once it has enough of them.
    /// <para>
    /// One counter is asserted as well as two, because a reader that ignored the number and
    /// asked "does it have any" passes both of the other assertions. Three counters of a
    /// different name are asserted too, for the reader that asks "does it have any counter".
    /// And it goes off again, because a static is not a one-way switch.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_counter_threshold_asks_for_the_number_and_the_name()
    {
        var shrine = Card(
            "Ki Counter Test",
            "As long as there are two or more ki counters on ~, ~ gets +2/+2.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var compiled = CardCompiler.Compile(shrine);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var creature = game.Create(alice, shrine, Zone.Battlefield);

        Assert.Equal(2, Characteristics.Of(game.State, Pool, game.State.GetObject(creature)).Power);

        // Three of somebody else's counter is not one of these.
        game.ChangeCounters(creature, "brick", 3);
        Settle(game);
        Assert.Equal(2, Characteristics.Of(game.State, Pool, game.State.GetObject(creature)).Power);

        game.ChangeCounters(creature, "ki", 1);
        Settle(game);
        Assert.Equal(2, Characteristics.Of(game.State, Pool, game.State.GetObject(creature)).Power);

        game.ChangeCounters(creature, "ki", 1);
        Settle(game);
        Assert.Equal(4, Characteristics.Of(game.State, Pool, game.State.GetObject(creature)).Power);

        game.ChangeCounters(creature, "ki", -1);
        Settle(game);
        Assert.Equal(2, Characteristics.Of(game.State, Pool, game.State.GetObject(creature)).Power);
    }

    /// <summary>
    /// "~ has flying as long as ~ has three or more +1/+1 counters on it" — the counter written
    /// as a number, with a threshold in front of it.
    /// </summary>
    /// <remarks>
    /// A second sentence off the same reader, and a different word order into it. The counter
    /// name is the interesting half: it is stored as it prints rather than lowercased, so a
    /// reader that normalised "+1/+1" the way it normalises "ki" would go looking for a counter
    /// nothing in the engine ever puts on — and the keyword would simply never be granted.
    /// </remarks>
    [Fact]
    public void A_numbered_counter_keeps_the_name_it_is_stored_under()
    {
        var mirror = Card(
            "Plus Counter Test",
            "~ has flying as long as ~ has three or more +1/+1 counters on it.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var compiled = CardCompiler.Compile(mirror);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var creature = game.Create(alice, mirror, Zone.Battlefield);

        game.ChangeCounters(creature, CounterKinds.PlusOnePlusOne, 2);
        Settle(game);

        Assert.False(
            Characteristics.Of(game.State, Pool, game.State.GetObject(creature))
                .Has(KeywordAbility.Flying));

        game.ChangeCounters(creature, CounterKinds.PlusOnePlusOne, 1);
        Settle(game);

        Assert.True(
            Characteristics.Of(game.State, Pool, game.State.GetObject(creature))
                .Has(KeywordAbility.Flying));

        game.ChangeCounters(creature, CounterKinds.PlusOnePlusOne, -1);
        Settle(game);

        Assert.False(
            Characteristics.Of(game.State, Pool, game.State.GetObject(creature))
                .Has(KeywordAbility.Flying));
    }

    /// <summary>
    /// "As long as you control exactly one creature, ~ gets +3/+1" — a window rather than a
    /// threshold.
    /// </summary>
    /// <remarks>
    /// Both of the comparisons already in the counting reader are wrong for this in a way that
    /// plays: "one or more" leaves the bonus on once a second creature arrives, and "one or
    /// fewer" leaves it on with none at all. So the second creature is the assertion — and it is
    /// somebody else's first, because "you control" is a question about your half of the board
    /// and a reader that counted the whole battlefield would fail there instead.
    /// </remarks>
    [Fact]
    public void An_exact_count_is_switched_off_by_one_creature_too_many()
    {
        var loner = Card(
            "Exactly One Test",
            "As long as you control exactly one creature, ~ gets +3/+1.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var compiled = CardCompiler.Compile(loner);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var creature = game.Create(alice, loner, Zone.Battlefield);
        Settle(game);

        Assert.Equal(5, Characteristics.Of(game.State, Pool, game.State.GetObject(creature)).Power);

        game.Create(bob, TestCards.Creature("Exactly One Bystander", 1, 1), Zone.Battlefield);
        Settle(game);

        Assert.Equal(5, Characteristics.Of(game.State, Pool, game.State.GetObject(creature)).Power);

        game.Create(alice, TestCards.Creature("Exactly One Friend", 1, 1), Zone.Battlefield);
        Settle(game);

        Assert.Equal(2, Characteristics.Of(game.State, Pool, game.State.GetObject(creature)).Power);
    }

    /// <summary>
    /// "At the beginning of the end step, if no creatures are on the battlefield, sacrifice ~" —
    /// the sweeper enchantments that clear up after themselves.
    /// </summary>
    /// <remarks>
    /// The same emptiness the vocabulary already read as "there are no creatures on the
    /// battlefield", printed the other way round on the four sweeper enchantments that ask it.
    /// The two wordings are rewritten onto one reader rather than given one each, so the answer
    /// has only one place to drift from.
    /// <para>
    /// It is asked of the whole battlefield and not of your half of it, so Bob's creature keeps
    /// the enchantment alive through a whole end step — a reader that counted only Alice's would
    /// sacrifice it a turn early. The second half is what the existing test of the other wording
    /// does not have: that one asserts only that nothing happens, and a condition that is never
    /// true passes it.
    /// </para>
    /// </remarks>
    [Fact]
    public void An_empty_board_condition_counts_everybodys_creatures()
    {
        var plague = Card(
            "Empty Board Sweeper Test",
            "At the beginning of the end step, if no creatures are on the battlefield, "
                + "sacrifice ~.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(plague);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var enchantment = game.Create(alice, plague, Zone.Battlefield);
        var bystander = game.Create(
            bob, TestCards.Creature("Empty Board Sweeper Bystander", 1, 1), Zone.Battlefield);

        PassTo(game, 1, TurnStep.End);
        Settle(game);

        Assert.Contains(enchantment, game.State.Battlefield);

        game.Move(bystander, Zone.Graveyard, MoveCause.Destroy);
        PassTo(game, 2, TurnStep.End);
        Settle(game);

        Assert.DoesNotContain(enchantment, game.State.Battlefield);
    }

    /// <summary>
    /// Devotion counts mana symbols, not permanents (CR 700.5).
    /// </summary>
    /// <remarks>
    /// The whole God cycle turns on this and nothing else could ask it: the counting reader
    /// beside it tallies permanents, and one permanent costing {B}{B}{B} is three devotion while
    /// three permanents costing {1} are none. Both of those are asserted here, because a reader
    /// that counted permanents would pass a test that only ever put black cards on the board.
    /// <para>
    /// The opponent's black permanent is the other half. Devotion is yours, and control is
    /// computed rather than stored (CR 613.1b) — a reader that counted the whole battlefield
    /// would let an opponent switch your God off for you.
    /// </para>
    /// </remarks>
    [Fact]
    public void Devotion_counts_mana_symbols_and_not_permanents()
    {
        var god = Card(
            "Devotion Test God",
            "As long as your devotion to black is less than five, ~ gets +3/+3.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var compiled = CardCompiler.Compile(god);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var idol = game.Create(alice, god, Zone.Battlefield);
        Settle(game);

        int PowerOfIdol() =>
            Characteristics.Of(game.State, Pool, game.State.GetObject(idol)).Power ?? 0;

        Assert.Equal(5, PowerOfIdol());

        // Three permanents, no black symbols between them: devotion is still zero.
        foreach (var n in new[] { 1, 2, 3 })
        {
            game.Create(
                alice, TestCards.Costed("Devotion Test Peasant " + n, "{1}", 1), Zone.Battlefield);
        }

        Settle(game);
        Assert.Equal(5, PowerOfIdol());

        // One permanent, three black symbols: devotion is three, still short of five.
        game.Create(
            alice, TestCards.Costed("Devotion Test Acolyte", "{B}{B}{B}", 3), Zone.Battlefield);
        Settle(game);
        Assert.Equal(5, PowerOfIdol());

        // Somebody else's black permanent is somebody else's devotion.
        game.Create(
            bob, TestCards.Costed("Devotion Test Rival", "{B}{B}{B}", 3), Zone.Battlefield);
        Settle(game);
        Assert.Equal(5, PowerOfIdol());

        // Five symbols across two permanents: no longer less than five, and the bonus goes.
        game.Create(
            alice, TestCards.Costed("Devotion Test Zealot", "{B}{B}", 2), Zone.Battlefield);
        Settle(game);
        Assert.Equal(2, PowerOfIdol());
    }

    /// <summary>
    /// A two-colour devotion counts a hybrid symbol once, not once per colour (CR 700.5).
    /// </summary>
    /// <remarks>
    /// "Devotion to white and black" is the number of symbols that are white, black, or both —
    /// a union rather than a sum. Six {W/B} symbols are six devotion, and the sum reading would
    /// make them twelve, so this card would already be switched off in the first assertion
    /// rather than the last. That is the only difference the two readings ever produce, and it
    /// is invisible to a test that uses single-coloured costs.
    /// </remarks>
    [Fact]
    public void A_two_colour_devotion_counts_a_hybrid_symbol_once()
    {
        var god = Card(
            "Hybrid Devotion Test God",
            "As long as your devotion to white and black is less than seven, ~ gets +3/+3.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var compiled = CardCompiler.Compile(god);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var idol = game.Create(alice, god, Zone.Battlefield);

        game.Create(
            alice,
            TestCards.Costed("Hybrid Devotion Test Choir", "{W/B}{W/B}{W/B}{W/B}{W/B}{W/B}", 6),
            Zone.Battlefield);

        Settle(game);

        Assert.Equal(
            5, Characteristics.Of(game.State, Pool, game.State.GetObject(idol)).Power);

        // The seventh symbol is the one that reaches the threshold.
        game.Create(
            alice, TestCards.Costed("Hybrid Devotion Test Deacon", "{W/B}", 1), Zone.Battlefield);
        Settle(game);

        Assert.Equal(
            2, Characteristics.Of(game.State, Pool, game.State.GetObject(idol)).Power);
    }

    /// <summary>
    /// "If there are no depletion counters on this land, sacrifice it" — a count at zero.
    /// </summary>
    /// <remarks>
    /// The lands that pay themselves out in counters and then go away all ask this, and it
    /// cannot share the "one or more" comparison with the count set to zero: that comparison is
    /// <em>at least</em>, which is true of every permanent on the battlefield, so the land would
    /// sacrifice itself the turn it arrived. The counter is put on first here for exactly that
    /// reason — a reader with the comparison the wrong way round passes a test that never has a
    /// counter to find.
    /// </remarks>
    [Fact]
    public void An_absent_counter_condition_is_false_while_a_counter_remains()
    {
        var quarry = Card(
            "Depleted Test Quarry",
            "At the beginning of the end step, if there are no charge counters on ~, "
                + "sacrifice ~.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(quarry);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var mine = game.Create(alice, quarry, Zone.Battlefield);
        game.ChangeCounters(mine, CounterKinds.Charge, 1);

        PassTo(game, 1, TurnStep.End);
        Settle(game);

        Assert.Contains(mine, game.State.Battlefield);

        game.ChangeCounters(mine, CounterKinds.Charge, -1);

        PassTo(game, 2, TurnStep.End);
        Settle(game);

        Assert.DoesNotContain(mine, game.State.Battlefield);
    }

    /// <summary>
    /// "Activate only if ~'s power is 3 or greater" — one permanent's power, as computed.
    /// </summary>
    /// <remarks>
    /// Read from the computed characteristics and not from the printed card (CR 613.4), because
    /// a card asking about its own power is always one whose power something else is expected to
    /// have changed — here a +1/+1 counter, which is what the cards that ask this are printed
    /// beside. Taking the counter off again is the other half: a condition that latches on is a
    /// condition nothing would notice was wrong.
    /// </remarks>
    [Fact]
    public void A_self_power_condition_reads_the_power_the_layers_computed()
    {
        var otter = Card(
            "Self Power Test",
            "~ has flying as long as ~'s power is 3 or greater.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var compiled = CardCompiler.Compile(otter);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var creature = game.Create(alice, otter, Zone.Battlefield);
        Settle(game);

        bool Flies() =>
            Characteristics.Of(game.State, Pool, game.State.GetObject(creature))
                .Has(KeywordAbility.Flying);

        Assert.False(Flies());

        game.ChangeCounters(creature, CounterKinds.PlusOnePlusOne, 1);
        Settle(game);

        Assert.True(Flies());

        game.ChangeCounters(creature, CounterKinds.PlusOnePlusOne, -1);
        Settle(game);

        Assert.False(Flies());
    }

    /// <summary>
    /// "More cards in hand than each opponent" means every one of them, not any of them.
    /// </summary>
    /// <remarks>
    /// The tie is the assertion. "More than" is strict, so level hands leave the card off, and a
    /// reader that took the comparison as "or equal" would pass every test that only ever looked
    /// at a player who was clearly ahead. The two hands are levelled by hand rather than assumed
    /// level, because what the opening draw leaves is not part of what this card asks.
    /// </remarks>
    [Fact]
    public void A_largest_hand_condition_needs_to_beat_every_opponent()
    {
        var hoarder = Card(
            "Largest Hand Test",
            "~ has flying as long as you have more cards in hand than each opponent.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var compiled = CardCompiler.Compile(hoarder);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var creature = game.Create(alice, hoarder, Zone.Battlefield);

        void Discard(Guid who) =>
            game.Move(game.State.GetPlayer(who).Hand[0], Zone.Graveyard, MoveCause.Discard);

        while (game.State.GetPlayer(alice).Hand.Count > game.State.GetPlayer(bob).Hand.Count)
            Discard(alice);

        while (game.State.GetPlayer(bob).Hand.Count > game.State.GetPlayer(alice).Hand.Count)
            Discard(bob);

        Settle(game);

        Assert.Equal(
            game.State.GetPlayer(alice).Hand.Count, game.State.GetPlayer(bob).Hand.Count);

        bool Flies() =>
            Characteristics.Of(game.State, Pool, game.State.GetObject(creature))
                .Has(KeywordAbility.Flying);

        Assert.False(Flies());

        Discard(bob);
        Settle(game);

        Assert.True(Flies());
    }

    /// <summary>
    /// "Fewer than seven cards in hand" is strict, and "seven or fewer" is not.
    /// </summary>
    /// <remarks>
    /// Kozilek draws up to seven, so the difference between the two readings is a free card off
    /// a full hand. The assertion is taken <em>at</em> the number the card names, which is the
    /// only place the two comparisons disagree — every count on either side of it reads the same
    /// whichever one is wrong.
    /// </remarks>
    [Fact]
    public void A_strict_hand_threshold_is_off_at_the_number_it_names()
    {
        var titan = Card(
            "Strict Hand Test",
            "~ has flying as long as you have fewer than three cards in hand.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var compiled = CardCompiler.Compile(titan);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var creature = game.Create(alice, titan, Zone.Battlefield);

        void Discard() =>
            game.Move(game.State.GetPlayer(alice).Hand[0], Zone.Graveyard, MoveCause.Discard);

        while (game.State.GetPlayer(alice).Hand.Count > 3)
            Discard();

        Settle(game);

        bool Flies() =>
            Characteristics.Of(game.State, Pool, game.State.GetObject(creature))
                .Has(KeywordAbility.Flying);

        Assert.Equal(3, game.State.GetPlayer(alice).Hand.Count);
        Assert.False(Flies());

        Discard();
        Settle(game);

        Assert.Equal(2, game.State.GetPlayer(alice).Hand.Count);
        Assert.True(Flies());
    }

    /// <summary>
    /// "As long as ~ is renowned" reads the designation, not what put it there (CR 702.112b).
    /// </summary>
    /// <remarks>
    /// Renowned is a marker with no other rules meaning, and it outlives every counter renown
    /// gave the creature. So the counters are taken off again here and the card stays on — a
    /// reader that answered this by looking for +1/+1 counters would pass the first assertion
    /// and fail the last, and nothing else in the suite would tell the two apart.
    /// </remarks>
    [Fact]
    public void A_renowned_condition_reads_the_designation_and_not_the_counters()
    {
        var champion = Card(
            "Renowned Condition Test",
            "Renown 1\n~ has flying as long as ~ is renowned.",
            CardType.Creature,
            power: 2,
            toughness: 2,
            keywords: KeywordAbility.Haste);

        var compiled = CardCompiler.Compile(champion);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, champion, Zone.Battlefield);
        Settle(game);

        bool Flies() =>
            Characteristics.Of(game.State, Pool, game.State.GetObject(attacker))
                .Has(KeywordAbility.Flying);

        Assert.False(Flies());

        TestCards.PassUntil(
            game,
            () => game.State.ActivePlayerId == alice
                && game.State.CurrentStep == TurnStep.DeclareAttackers);

        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Settle(game);

        Assert.True(Flies());

        // The counter renown gave it comes off; the designation does not.
        game.ChangeCounters(attacker, CounterKinds.PlusOnePlusOne, -1);
        Settle(game);

        Assert.Equal(
            2, Characteristics.Of(game.State, Pool, game.State.GetObject(attacker)).Power);

        Assert.True(Flies());
    }

    /// <summary>
    /// "As long as you have exactly 1 life" is a window, not a threshold.
    /// </summary>
    /// <remarks>
    /// Both thresholds are wrong for it in a way that plays: "or more" leaves the reward on for
    /// a healthy player and "or less" leaves it on for a dying one. So the assertions sit on
    /// either side of the number, and the second of them is the one a threshold reading fails.
    /// </remarks>
    [Fact]
    public void An_exact_life_total_is_a_window_and_not_a_threshold()
    {
        var martyr = Card(
            "Exact Life Test",
            "~ has flying as long as you have exactly 1 life.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var compiled = CardCompiler.Compile(martyr);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var creature = game.Create(alice, martyr, Zone.Battlefield);
        Settle(game);

        bool Flies() =>
            Characteristics.Of(game.State, Pool, game.State.GetObject(creature))
                .Has(KeywordAbility.Flying);

        Assert.False(Flies());

        game.ChangeLife(alice, 1 - game.State.GetPlayer(alice).Life);
        Settle(game);

        Assert.Equal(1, game.State.GetPlayer(alice).Life);
        Assert.True(Flies());

        // Gaining a life switches it off, which "one or less" would not.
        game.ChangeLife(alice, 1);
        Settle(game);

        Assert.False(Flies());
    }

    /// <summary>
    /// "There is a Desert card in your graveyard" — the same clause without the contraction.
    /// </summary>
    /// <remarks>
    /// One apostrophe was the whole of what this cost. It is worth more than the five cards that
    /// print it, because the disjunction reader can only join halves it can each read: a wording
    /// missed here is missed again in every clause containing it.
    /// <para>
    /// The opponent's graveyard is asserted separately. "Your graveyard" is one pile, and a
    /// reader that searched every graveyard would be turned on by the card an opponent discarded.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_graveyard_card_condition_reads_the_uncontracted_wording()
    {
        var camel = Card(
            "Uncontracted Graveyard Test",
            "~ has flying as long as there is a Desert card in your graveyard.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var compiled = CardCompiler.Compile(camel);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var desert = Card(
            "Buried Desert Test", string.Empty, CardType.Land, subtypes: "Desert");

        var (game, alice, bob) = InMainPhase();
        var creature = game.Create(alice, camel, Zone.Battlefield);
        Settle(game);

        bool Flies() =>
            Characteristics.Of(game.State, Pool, game.State.GetObject(creature))
                .Has(KeywordAbility.Flying);

        Assert.False(Flies());

        game.Create(bob, desert, Zone.Graveyard);
        Settle(game);

        Assert.False(Flies());

        game.Create(alice, desert, Zone.Graveyard);
        Settle(game);

        Assert.True(Flies());
    }

    /// <summary>
    /// Two conditions joined by "or" are true when either one of them is.
    /// </summary>
    /// <remarks>
    /// Solitary Camel's wording, and neither half is new: the board question and the graveyard
    /// question were both already read, and only the word between them was missing.
    /// <para>
    /// It is the graveyard half that is asserted, and the omission is deliberate rather than an
    /// oversight. <c>you control a Desert</c> compiles and then never fires — measured, in a
    /// game, against a Land whose subtype is Desert — because the target grammar does not know
    /// that word as a permanent noun, while <c>you control a Forest</c> and <c>you control an
    /// Elf</c> both answer correctly. That is a gap in <c>EffectPhrase.Specs</c> rather than in
    /// the condition vocabulary, and asserting the dead half here would enshrine it.
    /// </para>
    /// <para>
    /// The card is exiled rather than destroyed on the way back down, because destroying it
    /// would put it in the graveyard and leave the condition true by the other half — which is a
    /// test that passes whether the "or" works or not.
    /// </para>
    /// </remarks>
    [Fact]
    public void Two_conditions_joined_by_or_are_true_when_either_is()
    {
        var camel = Card(
            "Joined Or Test",
            "~ has flying as long as you control a Desert or there is a Desert card in "
                + "your graveyard.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var compiled = CardCompiler.Compile(camel);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var desert = Card("Joined Or Desert Test", string.Empty, CardType.Land, subtypes: "Desert");

        var (game, alice, _) = InMainPhase();
        var creature = game.Create(alice, camel, Zone.Battlefield);
        Settle(game);

        bool Flies() =>
            Characteristics.Of(game.State, Pool, game.State.GetObject(creature))
                .Has(KeywordAbility.Flying);

        Assert.False(Flies());

        var buried = game.Create(alice, desert, Zone.Graveyard);
        Settle(game);

        Assert.True(Flies());

        game.Move(buried, Zone.Exile, MoveCause.Exile);
        Settle(game);

        Assert.False(Flies());
    }

    /// <summary>
    /// "You control an artifact and an enchantment" — the half that leaves its subject out.
    /// </summary>
    /// <remarks>
    /// English drops a repeated subject and a parser cannot, so the second half is read again
    /// with the first half's subject put back. Both halves are asserted alone, because an "and"
    /// read as an "or" — or a second half quietly answered by the first — turns on with one
    /// permanent out and passes any test that puts both down at once.
    /// </remarks>
    [Fact]
    public void Two_conditions_joined_by_and_share_the_subject_the_second_leaves_out()
    {
        var naomi = Card(
            "Joined And Test",
            "~ has flying as long as you control an artifact and an enchantment.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var compiled = CardCompiler.Compile(naomi);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var creature = game.Create(alice, naomi, Zone.Battlefield);
        Settle(game);

        bool Flies() =>
            Characteristics.Of(game.State, Pool, game.State.GetObject(creature))
                .Has(KeywordAbility.Flying);

        Assert.False(Flies());

        var relic = game.Create(
            alice, Card("Joined And Relic Test", string.Empty, CardType.Artifact),
            Zone.Battlefield);

        Settle(game);

        Assert.False(Flies());

        var shrine = game.Create(
            alice, Card("Joined And Shrine Test", string.Empty, CardType.Enchantment),
            Zone.Battlefield);

        Settle(game);

        Assert.True(Flies());

        // Losing either half loses the card, which an "or" reading would not.
        game.Move(relic, Zone.Graveyard, MoveCause.Destroy);
        Settle(game);

        Assert.False(Flies());
        Assert.Contains(shrine, game.State.Battlefield);
    }

    /// <summary>
    /// "Seven or more cards are in your graveyard" — threshold's count, said backwards.
    /// </summary>
    /// <remarks>
    /// The same question the counting reader already answers with the pile moved to the back of
    /// the sentence, so it is rewritten onto that reader rather than given one of its own: two
    /// copies of a count are two places for it to drift, and the card filter travels with it.
    /// <para>
    /// The sixth card is the assertion. A threshold read as "six or more" is on one card early
    /// and looks identical at every other size of graveyard, which is exactly the kind of
    /// off-by-one a test that fills a graveyard to ten would never see.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_reversed_graveyard_count_is_off_one_card_short()
    {
        var lurker = Card(
            "Reversed Threshold Test",
            "~ has flying as long as seven or more cards are in your graveyard.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var compiled = CardCompiler.Compile(lurker);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var creature = game.Create(alice, lurker, Zone.Battlefield);

        bool Flies() =>
            Characteristics.Of(game.State, Pool, game.State.GetObject(creature))
                .Has(KeywordAbility.Flying);

        // Somebody else's pile is not yours, however deep it gets.
        foreach (var n in Enumerable.Range(1, 9))
        {
            game.Create(
                bob, TestCards.Creature("Reversed Threshold Rival " + n, 1, 1), Zone.Graveyard);
        }

        foreach (var n in Enumerable.Range(1, 6))
        {
            game.Create(
                alice, TestCards.Creature("Reversed Threshold Corpse " + n, 1, 1),
                Zone.Graveyard);
        }

        Settle(game);

        Assert.Equal(6, game.State.GetPlayer(alice).Graveyard.Count);
        Assert.False(Flies());

        game.Create(
            alice, TestCards.Creature("Reversed Threshold Corpse 7", 1, 1), Zone.Graveyard);

        Settle(game);

        Assert.Equal(7, game.State.GetPlayer(alice).Graveyard.Count);
        Assert.True(Flies());
    }

    /// <summary>
    /// A join whose halves are not conditions leaves the whole line unread.
    /// </summary>
    /// <remarks>
    /// The disjunction reader is the only one here that multiplies rather than adds, so it is
    /// the only one that could invent a condition out of a word it happened to find. Both halves
    /// having to parse is what stops it, and this is that rule asserted rather than described.
    /// <para>
    /// "You win the flip" is a real clause that is simply not a board question, so the card must
    /// stay in <c>Unhandled</c> rather than compile with a condition nobody printed — a condition
    /// silently true is a conditional card played as an unconditional one.
    /// </para>
    /// <para>
    /// It used to assert the same of "a red or white permanent", on the reasoning that it is one
    /// noun with a colour choice in it and not two conditions. That reasoning is still exactly
    /// right and the conclusion no longer follows: the <em>noun</em> grammar reads the colour pair
    /// now, so the line is read whole rather than split, and
    /// <see cref="A_colour_pair_in_a_condition_is_one_noun_and_not_a_join"/> plays it to show the
    /// reading is the printed one. What this test guards is the disjunction reader inventing a
    /// condition, which is the second case and not the first.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_join_whose_halves_are_not_conditions_leaves_the_line_unread()
    {
        var chance = Card(
            "Unjoinable Chance Test",
            "As long as you control a creature or you win the flip, ~ gets +1/+1.",
            CardType.Creature,
            power: 1,
            toughness: 1);

        Assert.False(CardCompiler.Compile(chance).IsComplete);
    }

    // ---- Where a card is, and what is on it ---------------------------------

    /// <summary>
    /// "If ~ is on the battlefield", "if ~ is on the stack", "if ~ is in the command zone or on
    /// the battlefield" — one reader for all seven zones (CR 400.1).
    /// </summary>
    /// <remarks>
    /// The preposition was the whole of what was missing. The vocabulary read "in your
    /// graveyard" and nothing else, so a card asking about the battlefield, the stack or the
    /// command zone went unread while the same card asking about a graveyard was answered — and
    /// the battlefield arm that was written could never fire, because it wanted the words "in
    /// the the battlefield".
    /// <para>
    /// Asserted with two zones the permanent is not in as well as the one it is. A condition
    /// silently defaulted to true — the failure this whole file exists to avoid — passes the
    /// first assertion and fails the second, and the negated form is the same trap reversed.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_zone_condition_reads_the_preposition_the_card_prints()
    {
        var (game, alice, _) = InMainPhase();

        int Drawn(string name, string condition)
        {
            var card = Card(
                name, $"When ~ enters, if {condition}, draw a card.", CardType.Enchantment);

            var compiled = CardCompiler.Compile(card);
            Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

            var before = game.State.GetPlayer(alice).Hand.Count;

            game.Create(alice, card, Zone.Battlefield);
            Settle(game);

            return game.State.GetPlayer(alice).Hand.Count - before;
        }

        // Where it is: the intervening-if is asked as the permanent arrives, and it has arrived.
        Assert.Equal(1, Drawn("Zone Battlefield Test", "~ is on the battlefield"));

        // Where it is not. A spell is on the stack and a permanent is not (CR 400.1), so this
        // is the assertion that a reader answering "true" to everything cannot pass.
        Assert.Equal(0, Drawn("Zone Stack Test", "~ is on the stack"));

        // Either of two zones, and it is the second one that answers. The disjunction is read
        // here rather than by the and/or combinator, which needs both halves to stand alone.
        Assert.Equal(
            1, Drawn("Zone Command Test", "~ is in the command zone or on the battlefield"));

        // The same question inverted. Reading the negation as the affirmative draws here.
        Assert.Equal(0, Drawn("Zone Absent Test", "~ isn't on the battlefield"));
    }

    /// <summary>
    /// "As long as ~ is attached to a creature" — an attachment asking about its host (CR 701.3a).
    /// </summary>
    /// <remarks>
    /// The opposite end of the question the adjectives already answered: "~ is equipped" asks
    /// what is attached to this permanent, and this asks what this permanent is attached to. An
    /// Equipment cannot ask the first about itself at all, so the two are not one reader.
    /// <para>
    /// The second card is what proves the noun is read rather than merely the attachment. "A
    /// creature you control" is off on an opponent's creature, and a reader that answered
    /// "attached to anything" passes every assertion the first card makes.
    /// </para>
    /// </remarks>
    [Fact]
    public void An_attachment_can_ask_what_it_is_attached_to()
    {
        var blade = Card(
            "Attached Host Test",
            "~ has flying as long as ~ is attached to a creature.",
            CardType.Artifact, null, null, KeywordAbility.None, "Equipment");

        var banner = Card(
            "Attached Ally Test",
            "~ has flying as long as ~ is attached to a creature you control.",
            CardType.Artifact, null, null, KeywordAbility.None, "Equipment");

        foreach (var card in new[] { blade, banner })
        {
            var compiled = CardCompiler.Compile(card);
            Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        }

        var (game, alice, bob) = InMainPhase();

        var mine = game.Create(alice, blade, Zone.Battlefield);
        var ours = game.Create(alice, banner, Zone.Battlefield);

        var theirs = game.Create(
            bob, TestCards.Creature("Attached Rival Test", 2, 2), Zone.Battlefield);
        var friend = game.Create(
            alice, TestCards.Creature("Attached Friend Test", 2, 2), Zone.Battlefield);

        bool Flies(ObjectId id) =>
            Characteristics.Of(game.State, Pool, game.State.GetObject(id))
                .Has(KeywordAbility.Flying);

        Settle(game);

        Assert.False(Flies(mine));
        Assert.False(Flies(ours));

        // An Equipment may equip any creature, so on an opponent's one "a creature" is true and
        // "a creature you control" is not — the whole of the difference between the two clauses.
        game.Attach(mine, theirs);
        game.Attach(ours, theirs);
        Settle(game);

        Assert.True(Flies(mine));
        Assert.False(Flies(ours));

        game.Attach(ours, friend);
        Settle(game);

        Assert.True(Flies(ours));

        // And off again when the host goes, because a static is not a one-way switch.
        game.Move(theirs, Zone.Graveyard, MoveCause.Destroy);
        Settle(game);

        Assert.False(Flies(mine));
    }

    /// <summary>"Whenever ~ attacks, if it's modified" — CR 700.9.</summary>
    /// <remarks>
    /// One printed word for three facts, none of which any card spells out: a counter on it, an
    /// Equipment attached to it, or an Aura attached to it that its own controller controls. All
    /// three were already askable one at a time, so this composes them rather than adding state.
    /// <para>
    /// The Aura half is the narrow one and its assertion is an opponent's Aura, which modifies
    /// nothing however much it changes the creature. A reader that treated any attachment as a
    /// modification passes every other assertion here.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_permanent_can_ask_whether_it_is_modified()
    {
        var knight = Card(
            "Modified Knight Test",
            "~ has flying as long as it's modified.",
            CardType.Creature, 2, 2);

        var compiled = CardCompiler.Compile(knight);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var creature = game.Create(alice, knight, Zone.Battlefield);

        bool Flies() =>
            Characteristics.Of(game.State, Pool, game.State.GetObject(creature))
                .Has(KeywordAbility.Flying);

        Settle(game);
        Assert.False(Flies());

        // A counter of any kind (CR 122.1), and off again when it goes.
        game.AddCounters(creature, CounterKinds.PlusOnePlusOne, 1);
        Assert.True(Flies());

        game.AddCounters(creature, CounterKinds.PlusOnePlusOne, -1);
        Assert.False(Flies());

        // An opponent's Aura is not a modification, which is the one asymmetry in the rule.
        var theirAura = game.Create(
            bob,
            Card(
                "Modified Rival Aura Test", "Enchant creature", CardType.Enchantment,
                null, null, KeywordAbility.None, "Aura"),
            Zone.Battlefield);

        game.Attach(theirAura, creature);
        Settle(game);
        Assert.False(Flies());

        // An Equipment counts whoever controls it, which is where the rule stops being symmetric.
        var sword = game.Create(
            alice,
            Card(
                "Modified Sword Test", "Equip {2}", CardType.Artifact,
                null, null, KeywordAbility.None, "Equipment"),
            Zone.Battlefield);

        game.Attach(sword, creature);
        Settle(game);
        Assert.True(Flies());

        // Take the Equipment away and the opponent's Aura is still attached and still does not
        // count, which is what says the Equipment arm was carrying that assertion and not the
        // Aura beside it.
        game.Move(sword, Zone.Graveyard, MoveCause.Destroy);
        Settle(game);
        Assert.False(Flies());

        // Your own Aura does count. Without this the controller test could be inverted, or
        // simply never true, and every other assertion here would still pass.
        var myAura = game.Create(
            alice,
            Card(
                "Modified Own Aura Test", "Enchant creature", CardType.Enchantment,
                null, null, KeywordAbility.None, "Aura"),
            Zone.Battlefield);

        game.Attach(myAura, creature);
        Settle(game);
        Assert.True(Flies());
    }

    /// <summary>"At the beginning of combat on your turn, if ~ has counters on it, ..."</summary>
    /// <remarks>
    /// Any counter of any kind, which the two named readers beside it cannot ask because each is
    /// given a name to look for. The cards printing this are the ones that then move or remove
    /// <em>all</em> of them, so the kind is exactly what they do not care about.
    /// </remarks>
    [Fact]
    public void An_unnamed_counter_condition_is_true_of_any_kind()
    {
        var monolith = Card(
            "Any Counter Test",
            "~ has flying as long as ~ has counters on it.",
            CardType.Creature, 2, 2);

        var compiled = CardCompiler.Compile(monolith);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var creature = game.Create(alice, monolith, Zone.Battlefield);

        bool Flies() =>
            Characteristics.Of(game.State, Pool, game.State.GetObject(creature))
                .Has(KeywordAbility.Flying);

        Settle(game);
        Assert.False(Flies());

        // A kind nothing else in this file asks for, because the reader is not allowed to have
        // a list of kinds: a card that had one would be asking the named question instead.
        game.AddCounters(creature, "quest", 1);
        Assert.True(Flies());

        game.AddCounters(creature, "quest", -1);
        Assert.False(Flies());
    }

    /// <summary>"~ has infect as long as an opponent is poisoned" — CR 122.1f.</summary>
    /// <remarks>
    /// The word rather than the count: the rule defines "poisoned" as one or more poison
    /// counters, so this is the tally the vocabulary already keeps at a threshold of one. Your
    /// own poison is the assertion that matters — a reader that asked the controller instead of
    /// the opponents is right exactly half the time, and a test that only poisoned the opponent
    /// could not tell the two apart.
    /// </remarks>
    [Fact]
    public void A_poison_condition_can_be_asked_as_a_word_rather_than_a_count()
    {
        var stalker = Card(
            "Poisoned Word Test",
            "~ has flying as long as an opponent is poisoned.",
            CardType.Creature, 2, 2);

        var compiled = CardCompiler.Compile(stalker);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var creature = game.Create(alice, stalker, Zone.Battlefield);

        var carrier = game.Create(
            alice,
            Card(
                "Poisoned Word Carrier Test", "Infect", CardType.Creature, 2, 2,
                keywords: KeywordAbility.Infect),
            Zone.Battlefield);

        bool Flies() =>
            Characteristics.Of(game.State, Pool, game.State.GetObject(creature))
                .Has(KeywordAbility.Flying);

        Settle(game);
        Assert.False(Flies());

        // Poisoning yourself is not poisoning an opponent (CR 102.1).
        game.MarkDamageToPlayer(alice, carrier, 1, isCombat: false);
        Settle(game);

        Assert.Equal(1, game.State.GetPlayer(alice).PoisonCounters);
        Assert.False(Flies());

        game.MarkDamageToPlayer(bob, carrier, 1, isCombat: false);
        Settle(game);

        Assert.Equal(1, game.State.GetPlayer(bob).PoisonCounters);
        Assert.True(Flies());
    }

    /// <summary>"Whenever ~ attacks, if defending player is poisoned, ..."</summary>
    /// <remarks>
    /// "Defending player" is one particular opponent rather than any of them, and which one is
    /// knowable only from the combat state: it is whoever this permanent is attacking. Outside
    /// combat it names nobody and the condition is false, which is the right answer for a bonus
    /// that only exists while the creature is attacking somebody — and it is the assertion that
    /// separates this reader from the one above, since the same poisoned opponent is on the
    /// board throughout.
    /// </remarks>
    [Fact]
    public void A_defending_player_condition_names_nobody_outside_combat()
    {
        var rat = Card(
            "Defender Poison Test",
            "~ gets +1/+1 as long as defending player is poisoned.",
            CardType.Creature, 2, 2);

        var compiled = CardCompiler.Compile(rat);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var creature = game.Create(alice, rat, Zone.Battlefield);

        var carrier = game.Create(
            alice,
            Card(
                "Defender Poison Carrier Test", "Infect", CardType.Creature, 2, 2,
                keywords: KeywordAbility.Infect),
            Zone.Battlefield);

        game.MarkDamageToPlayer(bob, carrier, 1, isCombat: false);
        Settle(game);

        int Power() =>
            Characteristics.Of(game.State, Pool, game.State.GetObject(creature)).Power ?? 0;

        // Bob is poisoned and nobody is defending, so the condition has no player to ask about.
        Assert.Equal(1, game.State.GetPlayer(bob).PoisonCounters);
        Assert.Equal(2, Power());

        TestCards.PassToTurn(game, 3);
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);

        game.DeclareAttackers(alice, new Dictionary<ObjectId, AttackTarget>
        {
            [creature] = AttackTarget.Player(bob),
        });

        Assert.Equal(3, Power());
    }

    /// <summary>
    /// "As long as your opponents control no creatures", "as long as no opponent controls a
    /// creature" — one question printed two ways round.
    /// </summary>
    /// <remarks>
    /// The two wordings are the same question at any number of seats, so the second is rewritten
    /// onto the first rather than given a reader: the noun keeps going through one filter
    /// vocabulary and the negation keeps one place to live.
    /// <para>
    /// Your own creature is the assertion that matters. The subject test in this reader was a
    /// three-letter prefix, and "your opponents control" begins with the same three letters as
    /// "you control" — so the obvious spelling of it reads a card about their board as one about
    /// yours and inverts every card that says it.
    /// </para>
    /// </remarks>
    [Fact]
    public void An_opponents_emptiness_condition_ignores_your_own_board()
    {
        var ward = Card(
            "Opponents Empty Test",
            "~ has flying as long as your opponents control no creatures.",
            CardType.Creature, 2, 2);

        var mirror = Card(
            "No Opponent Controls Test",
            "~ has flying as long as no opponent controls a creature.",
            CardType.Creature, 2, 2);

        var (game, alice, bob) = InMainPhase();

        var first = game.Create(alice, ward, Zone.Battlefield);
        var second = game.Create(alice, mirror, Zone.Battlefield);

        bool Flies(ObjectId id) =>
            Characteristics.Of(game.State, Pool, game.State.GetObject(id))
                .Has(KeywordAbility.Flying);

        foreach (var card in new[] { ward, mirror })
        {
            var compiled = CardCompiler.Compile(card);
            Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        }

        // Two creatures of Alice's own are on the board already, and neither card cares.
        Settle(game);

        Assert.True(Flies(first));
        Assert.True(Flies(second));

        var rival = game.Create(
            bob, TestCards.Creature("Opponents Empty Rival Test", 1, 1), Zone.Battlefield);

        Settle(game);

        Assert.False(Flies(first));
        Assert.False(Flies(second));

        // And on again when their board empties: a static re-asks its question.
        game.Move(rival, Zone.Graveyard, MoveCause.Destroy);
        Settle(game);

        Assert.True(Flies(first));
        Assert.True(Flies(second));
    }

    /// <summary>
    /// "As long as no creatures attacked this turn", "if you didn't attack with a creature this
    /// turn" — the attack flag read the other way round.
    /// </summary>
    /// <remarks>
    /// Declaring no attackers is not attacking (CR 508.1), and the flag the reducer sets says
    /// so, which is what makes a negation of it meaningful at all. The two clauses are not each
    /// other: one player not having attacked says nothing about the other seats, so "no
    /// creatures attacked" asks the whole table and is a separate arm rather than a negation of
    /// the single-player one.
    /// </remarks>
    [Fact]
    public void A_negated_attack_condition_reads_the_flag_the_declaration_sets()
    {
        var watcher = Card(
            "Nobody Attacked Test",
            "~ has flying as long as no creatures attacked this turn.",
            CardType.Creature, 2, 2);

        var pacifist = Card(
            "You Didnt Attack Test",
            "~ has flying as long as you didn't attack with a creature this turn.",
            CardType.Creature, 2, 2);

        foreach (var card in new[] { watcher, pacifist })
        {
            var compiled = CardCompiler.Compile(card);
            Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        }

        var (game, alice, bob) = InMainPhase();

        var first = game.Create(alice, watcher, Zone.Battlefield);
        var second = game.Create(alice, pacifist, Zone.Battlefield);
        var bear = game.Create(
            alice, TestCards.Creature("Nobody Attacked Bear Test", 2, 2), Zone.Battlefield);

        bool Flies(ObjectId id) =>
            Characteristics.Of(game.State, Pool, game.State.GetObject(id))
                .Has(KeywordAbility.Flying);

        Settle(game);

        Assert.True(Flies(first));
        Assert.True(Flies(second));

        TestCards.PassToTurn(game, 3);
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);

        // Still nobody: a turn has gone by in which no attack was declared, and the flag is
        // cleared at the start of each turn rather than accumulating.
        Assert.True(Flies(first));
        Assert.True(Flies(second));

        game.DeclareAttackers(alice, new Dictionary<ObjectId, AttackTarget>
        {
            [bear] = AttackTarget.Player(bob),
        });

        Assert.False(Flies(first));
        Assert.False(Flies(second));
    }

    /// <summary>
    /// "Three or more instant and/or sorcery cards in your graveyard" — a pile named by a phrase.
    /// </summary>
    /// <remarks>
    /// The noun in that slot had been a single word, which is one word short of the commonest
    /// filtered pile the cards print: thirty-five corpus lines name two card types with the
    /// cards' own "and/or". That shorthand means a card answering to <em>either</em> of them
    /// (CR 109.4), so it is normalised to the "or" the shared filter vocabulary already spells
    /// rather than taught to that vocabulary as a word of its own.
    /// </remarks>
    [Fact]
    public void A_graveyard_count_reads_a_pile_named_by_two_card_types()
    {
        var wolverine = Card(
            "Spelleater Test",
            "~ has double strike as long as there are three or more instant "
                + "and/or sorcery cards in your graveyard.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var compiled = CardCompiler.Compile(wolverine);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var beast = game.Create(alice, wolverine, Zone.Battlefield);

        bool Doubles() =>
            Characteristics.Of(game.State, Pool, game.State.GetObject(beast))
                .Has(KeywordAbility.DoubleStrike);

        void Bin(CardDefinition card) => game.Move(
            TestCards.PutInHand(game, alice, card), Zone.Graveyard, MoveCause.Discard);

        // Three cards in the graveyard and not one of them counts. An unfiltered count would
        // already say yes here, which is the half a reader that dropped the phrase gets wrong.
        for (var i = 0; i < 3; i++)
            Bin(TestCards.Creature($"Spelleater Body {i} Test", 1, 1));

        Assert.False(Doubles());

        Bin(Card("Spelleater Bolt Test", "You gain 1 life."));
        Bin(Card("Spelleater Ritual Test", "You gain 1 life.", CardType.Sorcery));

        // One of each type and still short: "and/or" is a list a card answers any of, so both
        // count towards one total rather than being asked for separately.
        Assert.False(Doubles());

        Bin(Card("Spelleater Shock Test", "You gain 1 life."));

        Assert.True(Doubles());

        // And off again when the pile shrinks below the threshold - a static is not a latch.
        // The card is found by name rather than by position: a graveyard is a pile with the
        // newest card on top, so the last index is the oldest card in it.
        var shock = game.State.GetPlayer(alice).Graveyard
            .Single(id => game.State.GetObject(id).Card.Name == "Spelleater Shock Test");

        game.Move(shock, Zone.Exile, MoveCause.Exile);

        Assert.False(Doubles());
        Settle(game);
    }

    /// <summary>
    /// "An artifact card is in your graveyard" — the pile question with its subject at the front.
    /// </summary>
    /// <remarks>
    /// The engine read "there's an artifact card in your graveyard" and not this, which is the
    /// shape this file has been caught missing before: a condition with two printed word orders
    /// and a reader for one of them. Both spellings now share one pattern and one rewrite, so
    /// they cannot come to disagree about what an artifact card is.
    /// </remarks>
    [Fact]
    public void A_graveyard_condition_reads_the_word_order_that_leads_with_the_card()
    {
        var mage = Card(
            "Windwright Test",
            "~ has flying as long as an artifact card is in your graveyard.",
            CardType.Creature,
            power: 1,
            toughness: 2);

        var compiled = CardCompiler.Compile(mage);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var flier = game.Create(alice, mage, Zone.Battlefield);

        bool Flies() =>
            Characteristics.Of(game.State, Pool, game.State.GetObject(flier))
                .Has(KeywordAbility.Flying);

        // A card in the graveyard that is not an artifact: a reader that lost the noun on the
        // way through the rewrite would already be answering yes.
        var body = game.Create(
            alice, TestCards.Creature("Windwright Body Test", 1, 1), Zone.Battlefield);

        game.Move(body, Zone.Graveyard, MoveCause.Destroy);
        Settle(game);

        Assert.False(Flies());

        var relic = Card(
            "Windwright Relic Test", string.Empty, CardType.Artifact);

        game.Move(
            TestCards.PutInHand(game, alice, relic), Zone.Graveyard, MoveCause.Discard);

        Settle(game);

        Assert.True(Flies());
    }

    /// <summary>
    /// "There are no cards in your graveyard" — the same count at zero, which is its own question.
    /// </summary>
    /// <remarks>
    /// It cannot be folded into "one or fewer". The comparison the numbered arm builds is
    /// at-most, and the cards printing this are turned <em>off</em> by a single card arriving —
    /// so a threshold of one would leave the bonus on for a graveyard that is not empty.
    /// </remarks>
    [Fact]
    public void An_empty_graveyard_is_a_condition_the_counting_reader_cannot_reach()
    {
        var titan = Card(
            "Gorilla Titan Test",
            "~ gets +4/+4 as long as there are no cards in your graveyard.",
            CardType.Creature,
            power: 4,
            toughness: 4);

        var compiled = CardCompiler.Compile(titan);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var ape = game.Create(alice, titan, Zone.Battlefield);
        Settle(game);

        Assert.Empty(game.State.GetPlayer(alice).Graveyard);
        Assert.Equal(8, Characteristics.Of(game.State, Pool, game.State.GetObject(ape)).Power);

        game.Move(
            TestCards.PutInHand(game, alice, Card("Gorilla Fodder Test", "You gain 1 life.")),
            Zone.Graveyard,
            MoveCause.Discard);

        Settle(game);

        Assert.Single(game.State.GetPlayer(alice).Graveyard);
        Assert.Equal(4, Characteristics.Of(game.State, Pool, game.State.GetObject(ape)).Power);
    }

    /// <summary>
    /// "You've cast an instant or sorcery spell this turn" — a kind neither tally can be asked.
    /// </summary>
    /// <remarks>
    /// The two counters beside this reader answer "spells" and "noncreature spells", and the
    /// commonest kind the cards actually name is neither. The answer comes from the cards cast
    /// this turn, which the state keeps for exactly this family (CR 601.2i), through the shared
    /// card-filter vocabulary — so a phrase that vocabulary cannot name leaves the clause unread
    /// rather than falling back to a wider count than the card asked for.
    /// </remarks>
    [Theory]
    [InlineData(true)]
    [InlineData(false)]
    public void A_spell_count_clause_can_name_a_kind_the_two_tallies_cannot(bool sorcerous)
    {
        var frog = Card(
            "Leapfrog Test",
            "~ has flying as long as you've cast an instant or sorcery spell this turn.",
            CardType.Creature,
            power: 1,
            toughness: 3);

        var compiled = CardCompiler.Compile(frog);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var spell = sorcerous
            ? Card("Leapfrog Bolt Test", "You gain 1 life.")
            : new CardDefinition
            {
                OracleId = "oracle-leapfrog-ogre-test",
                Name = "Leapfrog Ogre Test",
                OracleText = string.Empty,
                CardTypes = CardType.Creature,
                ManaCostRaw = "{1}",
                Cmc = 1,
                Power = 1,
                Toughness = 1,
            };

        var (game, alice, _) = InMainPhase();
        var swimmer = game.Create(alice, frog, Zone.Battlefield);

        bool Flies() =>
            Characteristics.Of(game.State, Pool, game.State.GetObject(swimmer))
                .Has(KeywordAbility.Flying);

        // Nothing cast yet, so the clause is off whichever spell is about to be cast. Asked
        // without settling first: passing priority would move the game on, and this reader is
        // about the turn rather than about anything waiting to happen.
        Assert.False(Flies());

        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, forest, "mana");
        game.CastSpell(alice, TestCards.PutInHand(game, alice, spell), []);
        Settle(game);

        // One spell either way, so the count is awake in both runs and only the kind differs -
        // which is what tells this reader apart from the plain tally it sits beside.
        Assert.Equal(1, game.State.GetPlayer(alice).SpellsCastThisTurn);
        Assert.Equal(sorcerous, Flies());
    }

    /// <summary>
    /// "There are five or more Islands on the battlefield" — everybody's permanents, not yours.
    /// </summary>
    /// <remarks>
    /// The emptiness half of this sentence has been rewritten onto the ownership readers for as
    /// long as they have existed; the counted and singular halves had not, so every card asking
    /// about the whole board went unread. Both are rewritten onto a subject that names no side,
    /// because a question about the battlefield is about everybody's permanents (CR 400.1) — and
    /// the opponent's Islands are what a "you control" reading would silently drop.
    /// </remarks>
    [Fact]
    public void A_battlefield_condition_counts_permanents_on_both_sides()
    {
        var serpent = Card(
            "Harbor Serpent Test",
            "~ can't attack unless there are five or more Islands on the battlefield.",
            CardType.Creature,
            power: 5,
            toughness: 5);

        var crasher = Card(
            "Glacial Crasher Test",
            "~ can't attack unless there is a Mountain on the battlefield.",
            CardType.Creature,
            power: 5,
            toughness: 5);

        foreach (var card in new[] { serpent, crasher })
        {
            var compiled = CardCompiler.Compile(card);
            Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        }

        var (game, alice, bob) = InMainPhase();
        var swimmer = game.Create(alice, serpent, Zone.Battlefield);
        var walker = game.Create(alice, crasher, Zone.Battlefield);

        TestCards.PassToTurn(game, 3);
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);

        string? Stopped(ObjectId id) => CombatRules.CannotAttack(
            game.State, Pool, game.State.GetObject(id), alice, bob);

        Assert.NotNull(Stopped(swimmer));
        Assert.NotNull(Stopped(walker));

        // Four is not five, and every one of them is Bob's - which is the point: a reader that
        // asked whose permanents they were would never reach the number at all.
        for (var i = 0; i < 4; i++)
            game.Create(bob, TestCards.BasicLand("Island"), Zone.Battlefield);

        Assert.NotNull(Stopped(swimmer));

        game.Create(bob, TestCards.BasicLand("Island"), Zone.Battlefield);

        Assert.Null(Stopped(swimmer));

        // The singular arm is a different rewrite and needs its own land to prove it.
        Assert.NotNull(Stopped(walker));

        game.Create(bob, TestCards.BasicLand("Mountain"), Zone.Battlefield);

        Assert.Null(Stopped(walker));
    }

    /// <summary>
    /// "Activate only if ~ entered this turn or if you control a basic land" — the repeated "if".
    /// </summary>
    /// <remarks>
    /// English repeats the conjunction's "if" and a parser cannot, so the second half arrived at
    /// the condition vocabulary still carrying a word no reader there expects and the whole
    /// clause was refused. Both halves had worked on their own for rounds; the cycle of five
    /// lands printing this sentence was unread for one repeated word.
    /// </remarks>
    [Fact]
    public void A_condition_that_repeats_its_if_after_the_conjunction_is_read()
    {
        var gathering = Card(
            "Gathering Place Test",
            "{T}: Add {G} or {W}. Activate only if ~ entered this turn or if you control "
                + "a basic land.",
            CardType.Land);

        var compiled = CardCompiler.Compile(gathering);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var land = game.Create(alice, gathering, Zone.Battlefield);

        // The turn it arrived, the first half answers on its own and the second is not needed.
        game.ActivateAbility(alice, land, compiled.Activated[0].Id);
        Assert.False(game.State.GetPlayer(alice).ManaPool.IsEmpty);

        PassToMainPhaseOfTurn(game, game.State.TurnNumber + 2);

        // CR 500.4 empties the pool as each step ends, so nothing is left over from above.
        Assert.True(game.State.GetPlayer(alice).ManaPool.IsEmpty);

        // A turn later neither half holds, and the ability is refused rather than quietly
        // allowed - which is what an unread condition would have produced.
        Assert.Throws<InvalidOperationException>(
            () => game.ActivateAbility(alice, land, compiled.Activated[0].Id));

        game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);

        game.ActivateAbility(alice, land, compiled.Activated[0].Id);
        Assert.False(game.State.GetPlayer(alice).ManaPool.IsEmpty);
    }

    /// <summary>
    /// "If an opponent has more life than you" — two totals compared, not one against a number.
    /// </summary>
    /// <remarks>
    /// The threshold reader beside it cannot answer this however alike the words look: there is
    /// no number in the sentence at all. Equal totals are the case that separates a comparison
    /// from a guess, and they are what the first run asserts.
    /// </remarks>
    [Theory]
    [InlineData(0, 0)]
    [InlineData(6, 5)]
    public void A_life_comparison_asks_whether_an_opponent_is_ahead(int lose, int gain)
    {
        var angel = Card(
            "Linvala Test",
            "When ~ enters, if an opponent has more life than you, you gain 5 life.",
            CardType.Creature,
            power: 5,
            toughness: 5);

        var compiled = CardCompiler.Compile(angel);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();

        if (lose > 0)
        {
            game.CastSpell(
                alice,
                TestCards.PutInHand(game, alice, Card("Linvala Drain Test", "You lose 6 life.")),
                []);

            Settle(game);
        }

        var before = game.State.GetPlayer(alice).Life;
        Assert.Equal(lose > 0, before < game.State.GetPlayer(bob).Life);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, angel), []);
        Settle(game);

        Assert.Equal(before + gain, game.State.GetPlayer(alice).Life);
    }

    /// <summary>
    /// "Then if you have more life than an opponent, draw a card" — the comparison the other way.
    /// </summary>
    /// <remarks>
    /// Written as its own arm rather than as the sentence above with the direction flipped,
    /// because the quantifier moves with it: "an opponent has more life than you" asks each of
    /// them about my one total, and this asks my one total about each of them. Reading one as
    /// the other is a pair of inversions that cancel at two seats and disagree at three.
    /// </remarks>
    [Theory]
    [InlineData(0, 1)]
    [InlineData(6, 0)]
    public void A_life_comparison_asks_whether_you_are_ahead(int lose, int drawn)
    {
        var cache = Card(
            "Survival Cache Test",
            "You gain 2 life. Then if you have more life than an opponent, draw a card.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(cache);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();

        if (lose > 0)
        {
            game.CastSpell(
                alice,
                TestCards.PutInHand(game, alice, Card("Survival Drain Test", "You lose 6 life.")),
                []);

            Settle(game);
        }

        var drewBefore = game.State.GetPlayer(alice).CardsDrawnThisTurn;

        game.CastSpell(alice, TestCards.PutInHand(game, alice, cache), []);
        Settle(game);

        // The life gain lands either way, so the spell demonstrably resolved in both runs and
        // only the second sentence's condition differs.
        Assert.Equal(20 - lose + 2, game.State.GetPlayer(alice).Life);
        Assert.Equal(20, game.State.GetPlayer(bob).Life);
        Assert.Equal(drewBefore + drawn, game.State.GetPlayer(alice).CardsDrawnThisTurn);
    }

    /// <summary>
    /// "Unless a player has no cards in hand" — anybody at all, the asker included.
    /// </summary>
    /// <remarks>
    /// A third answer rather than a synonym for either of the two beside it, and the board that
    /// tells them apart is the one where the empty hand is your own: "an opponent has no cards
    /// in hand" says no there, and the card says yes.
    /// </remarks>
    [Fact]
    public void An_empty_hand_condition_can_ask_about_any_player_at_the_table()
    {
        var prototype = Card(
            "Lupine Prototype Test",
            "~ can't attack or block unless a player has no cards in hand.",
            CardType.Creature,
            power: 5,
            toughness: 5);

        var compiled = CardCompiler.Compile(prototype);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var golem = game.Create(alice, prototype, Zone.Battlefield);

        TestCards.PassToTurn(game, 3);
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);

        string? Stopped() => CombatRules.CannotAttack(
            game.State, Pool, game.State.GetObject(golem), alice, bob);

        Assert.NotEmpty(game.State.GetPlayer(alice).Hand);
        Assert.NotEmpty(game.State.GetPlayer(bob).Hand);
        Assert.NotNull(Stopped());

        // Alice's own hand, which is the half that separates this from "an opponent has none".
        foreach (var held in game.State.GetPlayer(alice).Hand.ToList())
            game.Move(held, Zone.Graveyard, MoveCause.Discard);

        Settle(game);

        Assert.NotEmpty(game.State.GetPlayer(bob).Hand);
        Assert.Null(Stopped());
    }

    /// <summary>
    /// "If at least two white mana was spent to cast ~" � one colour of the record, not the total.
    /// </summary>
    /// <remarks>
    /// The symbol form beside it cannot say this: "{W}{W}" asks for exactly two symbols and a
    /// number written as a word has none to repeat, so "at least three" and "these three" are not
    /// the same question. Every row here spends two mana, which is the point � a reader that
    /// answered from the total would pass all four with the colour ignored.
    /// <para>
    /// "Of the same color" names no colour at all, so it is the largest single colour rather than
    /// the coloured total: two mana of two colours is not two of one.
    /// </para>
    /// </remarks>
    [Theory]
    [InlineData("if at least two white mana was spent to cast it", "Plains", "Plains", true)]
    [InlineData("if at least two white mana was spent to cast it", "Plains", "Island", false)]
    [InlineData("if at least two mana of the same color was spent to cast it", "Island", "Island", true)]
    [InlineData("if at least two mana of the same color was spent to cast it", "Island", "Forest", false)]
    public void A_clause_about_one_colour_of_mana_spent_reads_that_colour(
        string clause, string first, string second, bool fires)
    {
        var tag = clause.Contains("same color", StringComparison.Ordinal) ? "Same" : "White";

        var spell = new CardDefinition
        {
            OracleId = "oracle-colour-spent-" + tag + first + second,
            Name = "Colour Spend Test " + tag + " " + first + " " + second,
            OracleText = "When ~ enters, " + clause + ", you gain 4 life.",
            CardTypes = CardType.Creature,
            ManaCostRaw = "{2}",
            Cmc = 2,
            Power = 1,
            Toughness = 1,
        };

        var compiled = CardCompiler.Compile(spell);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, spell);

        foreach (var basic in new[] { first, second })
        {
            var land = game.Create(alice, TestCards.BasicLand(basic), Zone.Battlefield);
            game.ActivateAbility(alice, land, "mana");
        }

        var before = game.State.GetPlayer(alice).Life;
        game.CastSpell(alice, card, []);
        Settle(game);

        Assert.Equal(before + (fires ? 4 : 0), game.State.GetPlayer(alice).Life);
    }

    /// <summary>
    /// "As long as ~ has no shell counters on it" � the counter clause read the other way round.
    /// </summary>
    /// <remarks>
    /// Both spellings of absence are here because they are not one spelling: "has no charge
    /// counters" puts the zero in the quantifier and "doesn't have a +1/+1 counter" negates the
    /// verb and keeps the article, so folding the second onto the first would need "a" to mean
    /// none. The counter of a different name is what separates this from "has no counters at
    /// all", and taking the counter off again is what separates a static from a latch.
    /// </remarks>
    [Theory]
    [InlineData("~ has flying as long as ~ has no shell counters on it.", "shell")]
    [InlineData("~ has flying as long as ~ doesn't have a +1/+1 counter on it.", "+1/+1")]
    public void An_absent_counter_condition_is_on_until_that_counter_arrives(
        string oracle, string kind)
    {
        var hatchling = Card(
            "Absent Counter Test " + kind, oracle, CardType.Creature, power: 2, toughness: 2);

        var compiled = CardCompiler.Compile(hatchling);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var creature = game.Create(alice, hatchling, Zone.Battlefield);
        Settle(game);

        bool Flies() =>
            Characteristics.Of(game.State, Pool, game.State.GetObject(creature))
                .Has(KeywordAbility.Flying);

        Assert.True(Flies());

        // A counter of another name buys nothing. A reader asking "any counter at all" passes
        // the assertions on either side of this one.
        game.AddCounters(creature, "quest", 1);
        Settle(game);

        Assert.True(Flies());

        game.AddCounters(creature, kind, 1);
        Settle(game);

        Assert.False(Flies());

        game.AddCounters(creature, kind, -1);
        Settle(game);

        Assert.True(Flies());
    }

    /// <summary>
    /// "If three or more creatures are attacking" � a count of the declaration, and a description
    /// of what is in it.
    /// </summary>
    /// <remarks>
    /// Every watcher here is on the defending player's side, because that is who prints this: the
    /// Trap cycle asks about the attack being made against it, and a reading scoped to the asker
    /// would be true exactly when the printed card is false.
    /// <para>
    /// Two declarations, because a single one cannot say both halves of any of these. The second
    /// combat is what turns "exactly one" on and "two or more" off, and a reader that answered
    /// "one or more" to both would need it to be caught.
    /// </para>
    /// </remarks>
    [Fact]
    public void An_attacking_condition_counts_and_describes_the_declaration()
    {
        // The printed frame is a Trap's alternative cost, which is where the corpus puts this
        // clause; the statics below are the same condition somewhere a static can be measured.
        var trap = Card(
            "Attacking Trap Test",
            "If three or more creatures are attacking, you may pay {U} rather than pay ~'s mana cost."
                + (char)10 + "Draw two cards.");

        Assert.True(CardCompiler.Compile(trap).IsComplete);

        CardDefinition Watcher(string name, string condition) => Card(
            name,
            "~ gets +2/+2 as long as " + condition + ".",
            CardType.Creature,
            power: 1,
            toughness: 1);

        var two = Watcher("Attacking Two Test", "two or more creatures are attacking");
        var three = Watcher("Attacking Three Test", "three or more creatures are attacking");
        var zombies = Watcher("Attacking Zombie Watch Test", "a Zombie is attacking");
        var vampires = Watcher("Attacking Vampire Watch Test", "a Vampire is attacking");
        var lone = Watcher("Attacking Lone Test", "exactly one creature is attacking");

        foreach (var watcher in new[] { two, three, zombies, vampires, lone })
        {
            var built = CardCompiler.Compile(watcher);
            Assert.True(built.IsComplete, string.Join(" | ", built.Unhandled));
        }

        var (game, alice, bob) = InMainPhase();

        var watchers = new[] { two, three, zombies, vampires, lone }
            .Select(card => game.Create(bob, card, Zone.Battlefield))
            .ToList();

        var zombie = game.Create(
            alice,
            Card("Attacking Zombie Test", string.Empty, CardType.Creature, 2, 2,
                KeywordAbility.None, "Zombie"),
            Zone.Battlefield);

        var bear = game.Create(
            alice, TestCards.Creature("Attacking Bear Test", 2, 2), Zone.Battlefield);

        Settle(game);

        int Power(int which) =>
            Characteristics.Of(game.State, Pool, game.State.GetObject(watchers[which])).Power ?? 0;

        // Nothing is attacking yet, so every one of them is off.
        for (var i = 0; i < watchers.Count; i++)
            Assert.Equal(1, Power(i));

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(alice, new Dictionary<ObjectId, AttackTarget>
        {
            [zombie] = AttackTarget.Player(bob),
            [bear] = AttackTarget.Player(bob),
        });

        Assert.Equal(3, Power(0));
        Assert.Equal(1, Power(1));
        Assert.Equal(3, Power(2));
        Assert.Equal(1, Power(3));
        Assert.Equal(1, Power(4));

        // A second declaration, one attacker this time, and every answer above that could have
        // been a constant changes.
        PassTo(game, 5, TurnStep.DeclareAttackers);
        game.DeclareAttackers(alice, new Dictionary<ObjectId, AttackTarget>
        {
            [bear] = AttackTarget.Player(bob),
        });

        Assert.Equal(1, Power(0));
        Assert.Equal(1, Power(2));
        Assert.Equal(3, Power(4));

        Settle(game);
    }

    /// <summary>
    /// "~ is blocked" � one or more blockers were declared for it (CR 509.1h).
    /// </summary>
    /// <remarks>
    /// Not the negation of "~ is blocking" beside it: those are opposite sides of the same
    /// combat and a creature can be neither. The printed frame is an activation restriction,
    /// which is asserted to compile; the static is where the condition can be watched turning on.
    /// </remarks>
    [Fact]
    public void A_blocked_condition_waits_for_blockers_to_be_declared()
    {
        var crawler = Card(
            "Blocked Crawler Test",
            "{R}: ~ gets +1/+0 until end of turn. Activate only if ~ is blocked.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var printed = CardCompiler.Compile(crawler);
        Assert.True(printed.IsComplete, string.Join(" | ", printed.Unhandled));

        var lurker = Card(
            "Blocked Static Test",
            "~ gets +2/+0 as long as ~ is blocked.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var compiled = CardCompiler.Compile(lurker);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, lurker, Zone.Battlefield);
        var wall = game.Create(bob, TestCards.Creature("Blocked Wall Test", 0, 4), Zone.Battlefield);
        Settle(game);

        int Power() =>
            Characteristics.Of(game.State, Pool, game.State.GetObject(attacker)).Power ?? 0;

        Assert.Equal(2, Power());

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        // Attacking is not being blocked, which is the half a reader keyed on combat alone
        // would get wrong.
        Assert.Equal(2, Power());

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);
        game.DeclareBlockers(bob, new Dictionary<ObjectId, IReadOnlyList<ObjectId>>
        {
            [attacker] = [wall],
        });

        Assert.Equal(4, Power());

        Settle(game);
    }

    /// <summary>
    /// "Four or more permanent types among cards in your graveyard" � a narrower list than
    /// delirium's (CR 110.4 against CR 205.2a).
    /// </summary>
    /// <remarks>
    /// The instant and the sorcery are the whole test. They are two card types and no permanent
    /// types at all, so a reader that shared delirium's list would open this door on a graveyard
    /// the printed card leaves it shut on � and the delirium card beside it, which really is on
    /// with those two, is what proves the two lists are still different.
    /// </remarks>
    [Fact]
    public void A_permanent_type_count_does_not_count_the_types_that_are_never_permanents()
    {
        var door = Card(
            "Permanent Types Test",
            "~ has flying as long as there are two or more permanent types among cards in "
                + "your graveyard.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var delirium = Card(
            "Delirium Types Test",
            "~ has flying as long as there are two or more card types among cards in "
                + "your graveyard.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        foreach (var card in new[] { door, delirium })
        {
            var built = CardCompiler.Compile(card);
            Assert.True(built.IsComplete, string.Join(" | ", built.Unhandled));
        }

        var (game, alice, _) = InMainPhase();
        var permanents = game.Create(alice, door, Zone.Battlefield);
        var types = game.Create(alice, delirium, Zone.Battlefield);
        Settle(game);

        bool Flies(ObjectId id) =>
            Characteristics.Of(game.State, Pool, game.State.GetObject(id))
                .Has(KeywordAbility.Flying);

        Assert.False(Flies(permanents));
        Assert.False(Flies(types));

        game.Create(alice, Card("Graveyard Bolt Test", "~ deals 1 damage to any target."), Zone.Graveyard);
        game.Create(
            alice,
            Card("Graveyard Ritual Test", "You gain 1 life.", CardType.Sorcery),
            Zone.Graveyard);

        Settle(game);

        // Two card types and no permanent types, so the two cards disagree � which is the only
        // arrangement that can tell the lists apart.
        Assert.False(Flies(permanents));
        Assert.True(Flies(types));

        game.Create(alice, TestCards.Creature("Graveyard Bear Test", 2, 2), Zone.Graveyard);
        game.Create(alice, TestCards.BasicLand("Forest"), Zone.Graveyard);
        Settle(game);

        Assert.True(Flies(permanents));
    }

    /// <summary>
    /// "You had another creature enter the battlefield under your control this turn" � the same
    /// fact as the clause beside it, with the subject moved to the front.
    /// </summary>
    /// <remarks>
    /// English turns the verb into an infinitive when it does that, and a parser cannot, so the
    /// two word orders had to be one pattern rather than two readers. "Another" is asserted in
    /// both: the permanent asking arrives like any other and would otherwise answer yes about
    /// itself (CR 109.5).
    /// </remarks>
    [Theory]
    [InlineData("you had another creature enter the battlefield under your control this turn")]
    [InlineData("another creature entered the battlefield under your control this turn")]
    public void An_arrival_condition_reads_both_word_orders(string condition)
    {
        var stag = Card(
            "Arrival Wording Test " + condition.Length,
            "~ gets +2/+2 as long as " + condition + ".",
            CardType.Creature,
            power: 1,
            toughness: 1);

        var compiled = CardCompiler.Compile(stag);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var counter = game.Create(alice, stag, Zone.Battlefield);
        Settle(game);

        int Power() =>
            Characteristics.Of(game.State, Pool, game.State.GetObject(counter)).Power ?? 0;

        // Its own arrival is in the list and "another" takes it out again.
        Assert.Equal(1, Power());

        game.Create(alice, TestCards.Creature("Arrival Friend Test", 2, 2), Zone.Battlefield);
        Settle(game);

        Assert.Equal(3, Power());
    }

    /// <summary>
    /// An arrival clause that names a creature type, and one that names an opponent's board.
    /// </summary>
    /// <remarks>
    /// The type table this reader used to be given knows only card types, so a creature type
    /// reached it, came back null, and took the whole line away from every reader below �
    /// claiming a clause and then refusing it. The noun now falls through to the shared
    /// card-filter vocabulary, and the Bear arriving first is what proves the filter is real.
    /// <para>
    /// Whose board is the other half, and the artifact Alice plays is what proves it: a reader
    /// that ignored the side would be turned on by the asker's own permanent.
    /// </para>
    /// </remarks>
    [Fact]
    public void An_arrival_condition_can_name_a_creature_type_and_an_opponents_board()
    {
        var cavalier = Card(
            "Arrival Tribe Test",
            "~ gets +2/+2 as long as another Knight entered the battlefield under your control "
                + "this turn.",
            CardType.Creature,
            power: 1,
            toughness: 1);

        var trap = Card(
            "Arrival Opponent Test",
            "~ gets +2/+2 as long as an opponent had an artifact enter the battlefield under "
                + "their control this turn.",
            CardType.Creature,
            power: 1,
            toughness: 1);

        foreach (var card in new[] { cavalier, trap })
        {
            var built = CardCompiler.Compile(card);
            Assert.True(built.IsComplete, string.Join(" | ", built.Unhandled));
        }

        var (game, alice, bob) = InMainPhase();
        var knightWatch = game.Create(alice, cavalier, Zone.Battlefield);
        var artifactWatch = game.Create(alice, trap, Zone.Battlefield);
        Settle(game);

        int Power(ObjectId id) =>
            Characteristics.Of(game.State, Pool, game.State.GetObject(id)).Power ?? 0;

        Assert.Equal(1, Power(knightWatch));
        Assert.Equal(1, Power(artifactWatch));

        // A creature that is not a Knight, so the filter has something to refuse.
        game.Create(alice, TestCards.Creature("Arrival Peasant Test", 2, 2), Zone.Battlefield);
        Settle(game);

        Assert.Equal(1, Power(knightWatch));

        game.Create(
            alice,
            Card("Arrival Knight Test", string.Empty, CardType.Creature, 2, 2,
                KeywordAbility.None, "Knight"),
            Zone.Battlefield);

        Settle(game);

        Assert.Equal(3, Power(knightWatch));

        // Alice's own artifact is on the wrong side of the table for the second card.
        game.Create(
            alice, Card("Arrival Mine Test", string.Empty, CardType.Artifact), Zone.Battlefield);

        Settle(game);

        Assert.Equal(1, Power(artifactWatch));

        game.Create(
            alice, Card("Arrival Theirs Test", string.Empty, CardType.Artifact), Zone.Battlefield,
            controllerId: bob);

        Settle(game);

        Assert.Equal(3, Power(artifactWatch));
    }

    /// <summary>
    /// "If a creature died under your control this turn" � a death on one side of the table.
    /// </summary>
    /// <remarks>
    /// Not the game-wide death count this file already reads. Bob's creature dying is the
    /// assertion that separates them: answered without the side, the card would be turned on by
    /// the opponent's loss, which is strictly better than printed and would still play.
    /// <para>
    /// The exiled creature is the second narrowing. Dying is battlefield to graveyard and nothing
    /// else (CR 700.4), so a creature that left the battlefield another way must not count.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_death_condition_can_be_scoped_to_your_own_side()
    {
        var steward = Card(
            "Died Under Control Test",
            "~ gets +2/+2 as long as a creature died under your control this turn.",
            CardType.Creature,
            power: 1,
            toughness: 1);

        var gourmand = Card(
            "Died Human Test",
            "~ gets +2/+2 as long as another Human died under your control this turn.",
            CardType.Creature,
            power: 1,
            toughness: 1);

        foreach (var card in new[] { steward, gourmand })
        {
            var built = CardCompiler.Compile(card);
            Assert.True(built.IsComplete, string.Join(" | ", built.Unhandled));
        }

        var (game, alice, bob) = InMainPhase();
        var anyDeath = game.Create(alice, steward, Zone.Battlefield);
        var humanDeath = game.Create(alice, gourmand, Zone.Battlefield);
        Settle(game);

        int Power(ObjectId id) =>
            Characteristics.Of(game.State, Pool, game.State.GetObject(id)).Power ?? 0;

        Assert.Equal(1, Power(anyDeath));
        Assert.Equal(1, Power(humanDeath));

        // The opponent's loss is not yours.
        var theirs = game.Create(bob, TestCards.Creature("Died Theirs Test", 2, 2), Zone.Battlefield);
        game.Move(theirs, Zone.Graveyard, MoveCause.Destroy);
        Settle(game);

        Assert.Equal(1, Power(anyDeath));

        // Nor is leaving the battlefield some other way.
        var exiled = game.Create(alice, TestCards.Creature("Died Exiled Test", 2, 2), Zone.Battlefield);
        game.Move(exiled, Zone.Exile, MoveCause.Exile);
        Settle(game);

        Assert.Equal(1, Power(anyDeath));

        var bear = game.Create(alice, TestCards.Creature("Died Bear Test", 2, 2), Zone.Battlefield);
        game.Move(bear, Zone.Graveyard, MoveCause.Destroy);
        Settle(game);

        Assert.Equal(3, Power(anyDeath));

        // A Bear is not a Human, so the named half is still off.
        Assert.Equal(1, Power(humanDeath));

        var human = game.Create(
            alice,
            Card("Died Human Villager Test", string.Empty, CardType.Creature, 2, 2,
                KeywordAbility.None, "Human"),
            Zone.Battlefield);

        game.Move(human, Zone.Graveyard, MoveCause.Destroy);
        Settle(game);

        Assert.Equal(3, Power(humanDeath));
    }

    /// <summary>
    /// "As long as an opponent owns a card in exile" � exile is shared, so this asks whose card.
    /// </summary>
    /// <remarks>
    /// A card in exile has no controller to ask (CR 400.1 makes the zone a shared one), so
    /// ownership is the only question there is. Both halves are asserted against the same two
    /// exiled cards: a reader that ignored the owner would turn both cards on at the first one.
    /// </remarks>
    [Fact]
    public void An_exile_condition_asks_who_owns_the_card_rather_than_who_exiled_it()
    {
        var warden = Card(
            "Exile Theirs Test",
            "~ gets +2/+2 as long as an opponent owns a card in exile.",
            CardType.Creature,
            power: 1,
            toughness: 1);

        var monstrosity = Card(
            "Exile Yours Test",
            "~ gets +2/+2 as long as you own a card in exile.",
            CardType.Creature,
            power: 1,
            toughness: 1);

        foreach (var card in new[] { warden, monstrosity })
        {
            var built = CardCompiler.Compile(card);
            Assert.True(built.IsComplete, string.Join(" | ", built.Unhandled));
        }

        var (game, alice, bob) = InMainPhase();
        var theirs = game.Create(alice, warden, Zone.Battlefield);
        var mine = game.Create(alice, monstrosity, Zone.Battlefield);
        Settle(game);

        int Power(ObjectId id) =>
            Characteristics.Of(game.State, Pool, game.State.GetObject(id)).Power ?? 0;

        Assert.Equal(1, Power(theirs));
        Assert.Equal(1, Power(mine));

        // Alice's own card. She exiles it herself, so a reader keyed on who did the exiling
        // rather than on who owns the card would answer this the same way for both.
        game.Move(game.State.GetPlayer(alice).Hand[0], Zone.Exile, MoveCause.Exile);
        Settle(game);

        Assert.Equal(1, Power(theirs));
        Assert.Equal(3, Power(mine));

        game.Move(game.State.GetPlayer(bob).Hand[0], Zone.Exile, MoveCause.Exile);
        Settle(game);

        Assert.Equal(3, Power(theirs));
    }

    /// <summary>
    /// "Unless an opponent has been dealt damage this turn" � the perfect tense of a fact this
    /// file already reads.
    /// </summary>
    /// <remarks>
    /// A tense is not a question, so it belongs in the existing pattern rather than in a reader
    /// of its own � and it is the whole of what one <c>unless</c> tail needed to become readable.
    /// The refusal before the damage is the half that matters: an attack restriction whose
    /// condition never reads is a creature that can always attack.
    /// </remarks>
    [Fact]
    public void An_attack_restriction_reads_the_perfect_tense_of_damage_dealt()
    {
        // Haste, because the card that prints this clause has it — and without it the refusal
        // before the damage would be summoning sickness rather than the condition, which is a
        // test that passes whether the condition reads or not.
        var goblin = Card(
            "Bloodcrazed Test",
            "Haste" + (char)10
                + "~ can't attack unless an opponent has been dealt damage this turn.",
            CardType.Creature,
            power: 2,
            toughness: 2,
            keywords: KeywordAbility.Haste);

        var compiled = CardCompiler.Compile(goblin);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, goblin, Zone.Battlefield);

        string? Stopped() => CombatRules.CannotAttack(
            game.State, Pool, game.State.GetObject(attacker), alice, bob);

        Assert.NotNull(Stopped());

        var bolt = TestCards.PutInHand(
            game, alice, Card("Bloodcrazed Bolt Test", "~ deals 2 damage to any target."));

        var mountain = game.Create(alice, TestCards.BasicLand("Mountain"), Zone.Battlefield);
        game.ActivateAbility(alice, mountain, "mana");
        game.CastSpell(alice, bolt, [Target.ToPlayer(bob)]);
        Settle(game);

        Assert.Equal(18, game.State.GetPlayer(bob).Life);
        Assert.Null(Stopped());
    }

    /// <summary>
    /// "Unless you have max speed" — speed 4 and nothing less (CR 702.179e).
    /// </summary>
    /// <remarks>
    /// The three assertions on the way up are the point. Speed rises one step a turn at most
    /// (CR 702.179b), so a reader that answered "you have any speed at all" — which is what
    /// "start your engines" gives you for free — would pass a test that only looked at the two
    /// ends, and the card would be unrestricted from the moment its engine started.
    /// </remarks>
    [Fact]
    public void A_max_speed_condition_waits_for_the_top_of_the_range()
    {
        var godseeker = Card(
            "Max Speed Test",
            "Haste" + (char)10 + "~ can't attack or block unless you have max speed.",
            CardType.Creature,
            power: 5,
            toughness: 4,
            keywords: KeywordAbility.Haste);

        var compiled = CardCompiler.Compile(godseeker);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var hazoret = game.Create(alice, godseeker, Zone.Battlefield);

        game.Create(
            alice,
            Card("Max Speed Racer Test", "Start your engines!", CardType.Creature, 2, 2),
            Zone.Battlefield);

        Settle(game);

        string? Stopped() => CombatRules.CannotAttack(
            game.State, Pool, game.State.GetObject(hazoret), alice, bob);

        Assert.Equal(1, game.State.GetPlayer(alice).Speed);
        Assert.NotNull(Stopped());

        // One step a turn, and only on the turns Alice is the active player.
        foreach (var turn in (int[])[1, 3, 5])
        {
            if (turn > 1)
            {
                TestCards.PassUntil(
                    game,
                    () => game.State.TurnNumber >= turn
                        && game.State.CurrentStep == TurnStep.PrecombatMain
                        && game.State.Priority.Holder == alice);
            }

            var drain = TestCards.PutInHand(
                game, alice, Card("Max Speed Drain Test", "Each opponent loses 1 life."));

            game.CastSpell(alice, drain, targets: null);
            Settle(game);

            // Two, then three: neither is max speed, and both are more than none.
            if (game.State.GetPlayer(alice).Speed < 4)
                Assert.NotNull(Stopped());
        }

        Assert.Equal(4, game.State.GetPlayer(alice).Speed);
        Assert.Null(Stopped());
    }

    // ---- Board conditions: sameness, colour census and the negatives ---------

    [Fact]
    public void A_colour_census_counts_permanents_and_not_mana_symbols()
    {
        // The five Djinns, each naming its own colour. "Or is tied for most common" is the
        // half that decides most boards, because a Djinn is itself a permanent of the colour
        // it names and can only ever draw level rather than pull ahead.
        var djinn = new CardDefinition
        {
            OracleId = "oracle-colour-census-test",
            Name = "Colour Census Test",
            OracleText = "~ gets -2/-2 as long as red is the most common color among all "
                + "permanents or is tied for most common.",
            CardTypes = CardType.Creature,
            Power = 5,
            Toughness = 5,
            Colors = [ManaColor.Red],
            ColorIdentity = [ManaColor.Red],
        };

        var compiled = CardCompiler.Compile(djinn);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var self = game.Create(alice, djinn, Zone.Battlefield);
        game.Create(bob, Coloured("Census Blue One Test", ManaColor.Blue), Zone.Battlefield);
        game.Create(bob, Coloured("Census Blue Two Test", ManaColor.Blue), Zone.Battlefield);
        Settle(game);

        // One red permanent against two blue ones: red is not the commonest and is not tied.
        Assert.Equal(5, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(self)));

        game.Create(alice, Coloured("Census Red Two Test", ManaColor.Red), Zone.Battlefield);
        Settle(game);

        // Two each is a tie, which the clause counts.
        Assert.Equal(3, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(self)));

        // A colourless permanent is no colour at all (CR 105.2), so it joins no tally and
        // cannot break the tie. A census that counted permanents rather than colours would
        // move here.
        game.Create(
            alice,
            Card("Census Colourless Test", string.Empty, CardType.Artifact),
            Zone.Battlefield);

        Settle(game);
        Assert.Equal(3, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(self)));

        game.Create(bob, Coloured("Census Blue Three Test", ManaColor.Blue), Zone.Battlefield);
        Settle(game);

        // Three blue to two red: no longer tied, so the penalty lifts.
        Assert.Equal(5, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(self)));
    }

    [Fact]
    public void A_shared_colour_condition_asks_the_aura_about_its_host()
    {
        // Heroic Defiance. "It" on an Aura is the creature it is attached to and never the
        // Aura itself, which is colourless here - a reading that asked the Aura would share a
        // colour with nothing and hand out the bonus on every board.
        var aura = Card(
            "Shared Colour Aura Test",
            "Enchant creature\nEnchanted creature gets +3/+3 unless it shares a color with the "
                + "most common color among all permanents or a color tied for most common.",
            CardType.Enchantment,
            subtypes: "Aura");

        var compiled = CardCompiler.Compile(aura);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var host = game.Create(alice, Coloured("Shared Colour Host Test", ManaColor.Green), Zone.Battlefield);
        var card = TestCards.PutInHand(game, alice, aura);

        game.CastSpell(alice, card, [Target.ToPermanent(host)]);
        Settle(game);

        game.Create(bob, Coloured("Shared Colour Blue One Test", ManaColor.Blue), Zone.Battlefield);
        game.Create(bob, Coloured("Shared Colour Blue Two Test", ManaColor.Blue), Zone.Battlefield);
        Settle(game);

        // Two blue permanents against one green host: blue is the commonest colour, the host
        // does not share it, so the "unless" is unsatisfied and the bonus applies.
        Assert.Equal(5, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(host)));

        game.Create(alice, Coloured("Shared Colour Green One Test", ManaColor.Green), Zone.Battlefield);
        game.Create(alice, Coloured("Shared Colour Green Two Test", ManaColor.Green), Zone.Battlefield);
        Settle(game);

        // Three green to two blue, and the host is green: it shares the commonest colour, so
        // the bonus is off.
        Assert.Equal(2, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(host)));
    }

    [Fact]
    public void Same_name_and_different_names_are_opposite_questions_about_one_board()
    {
        // Endless Atlas asks for a group that agrees; Field of the Dead asks for a spread that
        // does not. They are one reader because only the comparison differs - and they are
        // tested on one board because that is the only place a reader answering "how many
        // groups" instead of "how big is the largest" gives itself away.
        var alike = Card(
            "Same Name Test",
            "~ gets +1/+1 as long as you control three or more lands with the same name.",
            CardType.Creature, power: 2, toughness: 2);

        var varied = Card(
            "Different Names Test",
            "~ gets +1/+1 as long as you control seven or more lands with different names.",
            CardType.Creature, power: 2, toughness: 2);

        foreach (var card in (CardDefinition[])[alike, varied])
        {
            var compiled = CardCompiler.Compile(card);
            Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        }

        var (game, alice, _) = InMainPhase();
        var grouped = game.Create(alice, alike, Zone.Battlefield);
        var spread = game.Create(alice, varied, Zone.Battlefield);

        var forests = new List<ObjectId>();
        foreach (var _ in Enumerable.Range(0, 3))
            forests.Add(game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield));

        Settle(game);

        int PowerOf(ObjectId id) =>
            Characteristics.PowerOf(game.State, Pool, game.State.GetObject(id)) ?? 0;

        // Three Forests are three lands with one name between them.
        Assert.Equal(3, PowerOf(grouped));
        Assert.Equal(2, PowerOf(spread));

        foreach (var land in (string[])["Island", "Swamp", "Mountain", "Plains", "Cave", "Desert"])
            game.Create(alice, TestCards.BasicLand(land), Zone.Battlefield);

        Settle(game);

        // Nine lands, seven names: both hold at once, which a reader confusing the two counts
        // could still pass. The step below is what tells them apart.
        Assert.Equal(3, PowerOf(grouped));
        Assert.Equal(3, PowerOf(spread));

        foreach (var extra in forests.Take(2))
            game.Move(extra, Zone.Graveyard, MoveCause.Destroy);

        Settle(game);

        // Seven lands, seven names, no two alike: the spread survives and the group does not.
        Assert.Equal(2, PowerOf(grouped));
        Assert.Equal(3, PowerOf(spread));
    }

    [Fact]
    public void An_at_least_threshold_is_the_same_count_written_the_other_way()
    {
        var coatl = Card(
            "At Least Test",
            "~ has deathtouch as long as you control at least three other enchantments.",
            CardType.Creature, power: 2, toughness: 2);

        var compiled = CardCompiler.Compile(coatl);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var self = game.Create(alice, coatl, Zone.Battlefield);

        bool Deadly() => Characteristics.Of(game.State, Pool, game.State.GetObject(self))
            .Has(KeywordAbility.Deathtouch);

        foreach (var name in (string[])["At Least Enchantment One Test", "At Least Enchantment Two Test"])
            game.Create(alice, Card(name, string.Empty, CardType.Enchantment), Zone.Battlefield);

        Settle(game);
        Assert.False(Deadly());

        // A creature is not an enchantment, so the noun is still doing its work at the
        // threshold rather than the count simply reaching three.
        game.Create(alice, TestCards.Creature("At Least Bystander Test"), Zone.Battlefield);
        Settle(game);
        Assert.False(Deadly());

        game.Create(
            alice,
            Card("At Least Enchantment Three Test", string.Empty, CardType.Enchantment),
            Zone.Battlefield);

        Settle(game);
        Assert.True(Deadly());
    }

    [Fact]
    public void A_full_hand_condition_is_the_hellbent_one_inverted()
    {
        var pet = Card(
            "Card In Hand Test",
            "~ has flying as long as you have a card in hand.",
            CardType.Creature, power: 2, toughness: 2);

        var compiled = CardCompiler.Compile(pet);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var creature = game.Create(alice, pet, Zone.Battlefield);

        bool Flying() => Characteristics.Of(game.State, Pool, game.State.GetObject(creature))
            .Has(KeywordAbility.Flying);

        Assert.NotEmpty(game.State.GetPlayer(alice).Hand);
        Assert.True(Flying());

        // "A card" is "one or more", so it goes off at nought and nowhere else - the opposite
        // end of the same pattern that already read "no cards in hand".
        foreach (var held in game.State.GetPlayer(alice).Hand.ToList())
            game.Move(held, Zone.Graveyard, MoveCause.Discard);

        Settle(game);

        Assert.Empty(game.State.GetPlayer(alice).Hand);
        Assert.False(Flying());
    }

    [Fact]
    public void Nothing_having_died_is_the_complement_of_something_having()
    {
        // Titan Hunter punishes a turn in which nothing died, and the positive form beside it
        // is on every card that rewards one. Both are on the board at once, because a
        // negation read as its own record rather than as the complement would let them agree.
        var quiet = Card(
            "Nothing Died Test",
            "~ has flying as long as no creatures died this turn.",
            CardType.Creature, power: 2, toughness: 2);

        var bloody = Card(
            "Something Died Test",
            "~ has flying as long as a creature died this turn.",
            CardType.Creature, power: 2, toughness: 2);

        foreach (var card in (CardDefinition[])[quiet, bloody])
        {
            var compiled = CardCompiler.Compile(card);
            Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        }

        var (game, alice, _) = InMainPhase();
        var peaceful = game.Create(alice, quiet, Zone.Battlefield);
        var bloodied = game.Create(alice, bloody, Zone.Battlefield);
        var victim = game.Create(alice, TestCards.Creature("Died This Turn Victim Test"), Zone.Battlefield);
        Settle(game);

        bool Flies(ObjectId id) =>
            Characteristics.Of(game.State, Pool, game.State.GetObject(id)).Has(KeywordAbility.Flying);

        Assert.True(Flies(peaceful));
        Assert.False(Flies(bloodied));

        game.Move(victim, Zone.Graveyard, MoveCause.Destroy);
        Settle(game);

        Assert.False(Flies(peaceful));
        Assert.True(Flies(bloodied));
    }

    [Fact]
    public void Not_having_cast_a_spell_is_the_complement_of_having_cast_one()
    {
        var sphinx = Card(
            "Not Cast Test",
            "~ has hexproof as long as you haven't cast a spell this turn.",
            CardType.Creature, power: 2, toughness: 2);

        var eager = Card(
            "Have Cast Test",
            "~ has hexproof as long as you've cast a spell this turn.",
            CardType.Creature, power: 2, toughness: 2);

        foreach (var card in (CardDefinition[])[sphinx, eager])
        {
            var compiled = CardCompiler.Compile(card);
            Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        }

        var (game, alice, _) = InMainPhase();
        var idle = game.Create(alice, sphinx, Zone.Battlefield);
        var busy = game.Create(alice, eager, Zone.Battlefield);
        Settle(game);

        bool Hexproof(ObjectId id) =>
            Characteristics.Of(game.State, Pool, game.State.GetObject(id)).Has(KeywordAbility.Hexproof);

        Assert.True(Hexproof(idle));
        Assert.False(Hexproof(busy));

        TestCards.PassUntil(game, () => game.State.Priority.Holder == alice);

        var spell = TestCards.PutInHand(game, alice, Card("Cast Marker Test", "You gain 1 life."));
        game.CastSpell(alice, spell, targets: null);
        Settle(game);

        Assert.False(Hexproof(idle));
        Assert.True(Hexproof(busy));
    }

    [Theory]
    [InlineData(true, 20)]
    [InlineData(false, 18)]
    public void An_unkicked_clause_fires_only_when_the_kicker_went_unpaid(bool kicked, int life)
    {
        // Sphinx of Lost Truths' second half. The flag has to survive the move onto the
        // battlefield either way round (CR 400.7, CR 607.2), and a negation read as "the flag
        // is missing" rather than "the flag is false" would fire on a permanent that had
        // simply gone.
        var sphinx = new CardDefinition
        {
            OracleId = "oracle-kicker-negation-test",
            Name = "Kicker Negation Test",
            OracleText = "Kicker {1}" + (char)10 + "When ~ enters, if ~ wasn't kicked, you lose 2 life.",
            CardTypes = CardType.Creature,
            ManaCostRaw = "{1}",
            Cmc = 1,
            Power = 2,
            Toughness = 2,
        };

        var compiled = CardCompiler.Compile(sphinx);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, sphinx);

        foreach (var _ in Enumerable.Range(0, 2))
        {
            var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
            game.ActivateAbility(alice, forest, "mana");
        }

        game.CastSpell(
            alice, card, targets: null, variableValue: 0, tapToPay: null, modes: null, kicked: kicked);

        Settle(game);

        Assert.Equal(life, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void A_plural_noun_reaches_the_filter_vocabulary_on_the_emptiness_arm()
    {
        // "An opponent controls no basic lands" - the arm of this pattern whose noun arrives
        // plural. Two words in it, so the six-word plural list could not touch it, and the
        // reader used to claim the clause and then refuse it, taking the line from everything
        // below as well.
        var mauling = Card(
            "No Basic Lands Test",
            "~ gets +2/+2 as long as an opponent controls no basic lands.",
            CardType.Creature, power: 2, toughness: 2);

        var compiled = CardCompiler.Compile(mauling);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var self = game.Create(alice, mauling, Zone.Battlefield);
        Settle(game);

        Assert.Equal(4, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(self)));

        // A land that is not basic leaves the clause true, which is what says the word "basic"
        // survived the trip through the filter vocabulary rather than being dropped with the
        // plural.
        game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.Create(bob, Card("Nonbasic Land Test", string.Empty, CardType.Land), Zone.Battlefield);
        Settle(game);

        Assert.Equal(4, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(self)));

        game.Create(bob, TestCards.BasicLand("Island"), Zone.Battlefield);
        Settle(game);

        Assert.Equal(2, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(self)));
    }

    [Theory]
    [InlineData(true, 20)]
    [InlineData(false, 22)]
    public void A_defending_player_emptiness_asks_the_seat_being_attacked(bool theirs, int life)
    {
        // Fear of the Dark. Played at three seats deliberately: at two, "defending player" and
        // "an opponent" pick out the same person and this test could not tell them apart. The
        // seat that is not being attacked always controls a Glimmer, so a reader asking any
        // opponent would refuse the gain on both rows.
        var fear = Card(
            "Defending Glimmer Test",
            "Whenever ~ attacks, if defending player controls no Glimmer creatures, you gain 2 life.",
            CardType.Creature, power: 2, toughness: 2);

        var compiled = CardCompiler.Compile(fear);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        CardDefinition Glimmer(string name) => Card(
            name, string.Empty, CardType.Creature | CardType.Enchantment, 1, 1, subtypes: "Glimmer");

        var alice = Guid.Parse("11111111-1111-1111-1111-111111111111");
        var bob = Guid.Parse("22222222-2222-2222-2222-222222222222");
        var carol = Guid.Parse("33333333-3333-3333-3333-333333333333");

        var game = Game.Start(
            Guid.NewGuid(),
            [
                new PlayerSetup(alice, "Alice", 20, TestCards.Deck(40, "Alice")),
                new PlayerSetup(bob, "Bob", 20, TestCards.Deck(40, "Bob")),
                new PlayerSetup(carol, "Carol", 20, TestCards.Deck(40, "Carol")),
            ],
            new GameRandom(1),
            startingPlayerId: alice,
            abilities: Pool);

        game.BeginPlay(withMulligans: false);
        TestCards.PassToStep(game, TurnStep.PrecombatMain);

        var attacker = game.Create(alice, fear, Zone.Battlefield);
        game.Create(carol, Glimmer("Carol Glimmer Test"), Zone.Battlefield);

        if (theirs)
            game.Create(bob, Glimmer("Bob Glimmer Test"), Zone.Battlefield);

        Settle(game);

        // Three seats, so Alice's second turn is turn four rather than turn three.
        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber >= 4 && game.State.CurrentStep == TurnStep.DeclareAttackers);

        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        Settle(game);

        Assert.Equal(life, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void A_commander_condition_tells_any_commander_from_your_own()
    {
        // CR 903.3d: "controlling a commander" is a permanent on the battlefield that *is* a
        // commander, whoever designated it - so an opponent's commander you have taken answers
        // "a commander" and not "your commander". Twenty-two cards print the wide form and the
        // lieutenant cycle prints the narrow one, and a single reader for both would either
        // refuse a free cast that is printed or hand out a bonus that is not.
        var anyone = Card(
            "Any Commander Test",
            "~ has flying as long as you control a commander.",
            CardType.Creature, power: 2, toughness: 2);

        var own = Card(
            "Own Commander Test",
            "~ has flying as long as you control your commander.",
            CardType.Creature, power: 2, toughness: 2);

        foreach (var card in (CardDefinition[])[anyone, own])
        {
            var compiled = CardCompiler.Compile(card);
            Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        }

        static CardDefinition General(string name) => new()
        {
            OracleId = "oracle-" + name.ToLowerInvariant().Replace(' ', '-'),
            Name = name,
            CardTypes = CardType.Creature,
            Supertypes = ["Legendary"],
            Power = 3,
            Toughness = 3,
        };

        var hers = General("Alice General Test");
        var his = General("Bob General Test");

        var alice = Guid.Parse("11111111-1111-1111-1111-111111111111");
        var bob = Guid.Parse("22222222-2222-2222-2222-222222222222");

        var game = Game.Start(
            Guid.NewGuid(),
            [
                new PlayerSetup(alice, "Alice", 40, [.. TestCards.Deck(40, "Alice"), hers])
                {
                    CommanderOracleId = hers.OracleId,
                },
                new PlayerSetup(bob, "Bob", 40, [.. TestCards.Deck(40, "Bob"), his])
                {
                    CommanderOracleId = his.OracleId,
                },
            ],
            new GameRandom(3),
            startingPlayerId: alice,
            abilities: Pool);

        game.BeginPlay(withMulligans: false);
        TestCards.PassToStep(game, TurnStep.PrecombatMain);

        var wide = game.Create(alice, anyone, Zone.Battlefield);
        var narrow = game.Create(alice, own, Zone.Battlefield);
        Settle(game);

        bool Flies(ObjectId id) =>
            Characteristics.Of(game.State, Pool, game.State.GetObject(id)).Has(KeywordAbility.Flying);

        // Both commanders are in the command zone, which is not the battlefield.
        Assert.False(Flies(wide));
        Assert.False(Flies(narrow));

        // Bob's commander, under Alice's control. This is the board the two clauses disagree
        // on, and the only one that can tell a wide reader from a narrow one.
        game.Create(bob, his, Zone.Battlefield, controllerId: alice);
        Settle(game);

        Assert.True(Flies(wide));
        Assert.False(Flies(narrow));

        game.Create(alice, hers, Zone.Battlefield);
        Settle(game);

        Assert.True(Flies(wide));
        Assert.True(Flies(narrow));
    }

    /// <summary>
    /// A game is day, night, or neither — and "neither" is a state, not the absence of one.
    /// </summary>
    /// <remarks>
    /// CR 731.1: a game begins with neither designation and keeps it until something makes it one
    /// of the two, after which it always has exactly one of them. So a two-valued reading is wrong
    /// in the direction that plays: "not day" is true of a game that has never had a designation
    /// at all, and ten of the thirteen corpus cards asking a day-night question are the permanents
    /// that make it day as they arrive — each of them would put the sun back up in the middle of
    /// the night.
    /// <para>
    /// All three are asserted against the same three boards in turn, because no single board can
    /// tell a three-valued reader from a two-valued one. The designations are reached the way a
    /// game reaches them rather than by writing the field: a daybound permanent makes it day
    /// (CR 702.145d), and a turn in which nobody casts a spell makes it night (CR 731.2a).
    /// </para>
    /// </remarks>
    [Fact]
    public void A_day_night_condition_reads_the_designation_the_game_has()
    {
        var night = Card(
            "Nightfall Sky Test",
            "~ has flying as long as it's night.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var day = Card(
            "Daylight Sky Test",
            "~ has flying as long as it's day.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var neither = Card(
            "Twilight Sky Test",
            "~ has flying as long as it's neither day nor night.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        foreach (var card in (CardDefinition[])[night, day, neither])
        {
            var compiled = CardCompiler.Compile(card);
            Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        }

        var (game, alice, _) = InMainPhase();

        var afterDark = game.Create(alice, night, Zone.Battlefield);
        var inTheSun = game.Create(alice, day, Zone.Battlefield);
        var atDusk = game.Create(alice, neither, Zone.Battlefield);

        bool Flies(ObjectId id) =>
            Characteristics.Of(game.State, Pool, game.State.GetObject(id))
                .Has(KeywordAbility.Flying);

        Settle(game);

        // Neither, which is where every game starts and where it has stayed.
        Assert.Null(game.State.IsDay);
        Assert.False(Flies(afterDark));
        Assert.False(Flies(inTheSun));
        Assert.True(Flies(atDusk));

        game.Create(alice, DayboundSky(), Zone.Battlefield);
        Settle(game);

        Assert.True(game.State.IsDay);
        Assert.False(Flies(afterDark));
        Assert.True(Flies(inTheSun));
        Assert.False(Flies(atDusk));

        // Nobody casts anything for a turn, so the untap step of the next one turns it to night.
        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber == 2 && game.State.CurrentStep == TurnStep.Upkeep);

        Settle(game);

        Assert.False(game.State.IsDay);
        Assert.True(Flies(afterDark));
        Assert.False(Flies(inTheSun));
        Assert.False(Flies(atDusk));
    }

    /// <summary>A werewolf, which is how a game is made to have a designation at all.</summary>
    /// <remarks>
    /// Two faces because a daybound permanent turns over when the designation changes, and a
    /// permanent with nowhere to turn to is not the card this test is about.
    /// </remarks>
    private static CardDefinition DayboundSky() => new()
    {
        OracleId = "oracle-daybound-sky-test",
        Name = "Daybound Sky Test",
        CardTypes = CardType.Creature,
        Keywords = KeywordAbility.Daybound,
        Power = 2,
        Toughness = 2,
        ManaCostRaw = "{1}{R}",
        Faces =
        [
            new CardFace
            {
                Name = "Daybound Sky Test",
                CardTypes = CardType.Creature,
                Keywords = KeywordAbility.Daybound,
                Power = 2,
                Toughness = 2,
                OracleText = "Daybound",
            },
            new CardFace
            {
                Name = "Nightbound Sky Test",
                CardTypes = CardType.Creature,
                Keywords = KeywordAbility.Nightbound,
                Power = 3,
                Toughness = 3,
                OracleText = "Nightbound",
            },
        ],
    };

    /// <summary>"As long as ~ has three or more counters on it" — a threshold with no name.</summary>
    /// <remarks>
    /// The sum across every kind is what the clause asks: a permanent carrying two +1/+1 counters
    /// and one quest counter has three counters on it (CR 122.1a). That is exactly the board here,
    /// and the assertion that matters is the sibling card asking for three <em>+1/+1</em> counters
    /// being off on it — a reader that had quietly counted only the commonest kind, or only the
    /// largest pile, passes every other assertion in this test.
    /// <para>
    /// It replaced a "one or more" spelling that no card in the corpus prints, so the widening is
    /// one alternative fewer rather than one more.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_nameless_counter_threshold_sums_every_kind()
    {
        var nameless = Card(
            "Counter Tally Test",
            "~ has flying as long as it has three or more counters on it.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var named = Card(
            "Named Tally Test",
            "~ has flying as long as it has three or more +1/+1 counters on it.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        foreach (var card in (CardDefinition[])[nameless, named])
        {
            var compiled = CardCompiler.Compile(card);
            Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        }

        var (game, alice, _) = InMainPhase();
        var anyKind = game.Create(alice, nameless, Zone.Battlefield);
        var oneKind = game.Create(alice, named, Zone.Battlefield);

        bool Flies(ObjectId id) =>
            Characteristics.Of(game.State, Pool, game.State.GetObject(id))
                .Has(KeywordAbility.Flying);

        Settle(game);
        Assert.False(Flies(anyKind));
        Assert.False(Flies(oneKind));

        foreach (var id in (ObjectId[])[anyKind, oneKind])
        {
            game.AddCounters(id, CounterKinds.PlusOnePlusOne, 2);
            game.AddCounters(id, "quest", 1);
        }

        Settle(game);

        // Three counters between two kinds. The nameless threshold is met; the named one is not.
        Assert.True(Flies(anyKind));
        Assert.False(Flies(oneKind));

        // And it is not a one-way switch: taking one off puts it back below the threshold.
        game.AddCounters(anyKind, "quest", -1);
        Settle(game);

        Assert.False(Flies(anyKind));

        // The named reader beside it still works on the board that defeats it here, which is what
        // stops this test passing because the neighbour is broken rather than because it is narrow.
        game.AddCounters(oneKind, CounterKinds.PlusOnePlusOne, 1);
        Settle(game);

        Assert.True(Flies(oneKind));
    }

    /// <summary>"As long as ~ has a shield counter on him" — the subject named as a person.</summary>
    /// <remarks>
    /// Four corpus cards write the pronoun this way and every one of them is a named character;
    /// the clause is otherwise word for word the one beside it, so the whole of the difference is
    /// "him" against "it". Asserted off with a counter of another name as well as with none,
    /// because a reader that widened the pronoun and lost the name would pass the on/off pair on
    /// its own.
    /// </remarks>
    [Fact]
    public void A_counter_clause_can_name_its_subject_as_him()
    {
        var hero = Card(
            "Shield Bearer Test",
            "~ has flying as long as ~ has a shield counter on him.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var compiled = CardCompiler.Compile(hero);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var captain = game.Create(alice, hero, Zone.Battlefield);

        bool Flies() =>
            Characteristics.Of(game.State, Pool, game.State.GetObject(captain))
                .Has(KeywordAbility.Flying);

        Settle(game);
        Assert.False(Flies());

        // A counter, but not the one the card names.
        game.AddCounters(captain, "conqueror", 1);
        Settle(game);

        Assert.False(Flies());

        game.AddCounters(captain, "shield", 1);
        Settle(game);

        Assert.True(Flies());

        game.AddCounters(captain, "shield", -1);
        Settle(game);

        Assert.False(Flies());
    }

    /// <summary>
    /// "An opponent has more cards in hand than you" is not the negation of "you have more than
    /// each opponent".
    /// </summary>
    /// <remarks>
    /// A table where one opponent holds exactly as many cards as you satisfies neither clause, so
    /// neither can be derived from the other however tempting the shape looks: "each opponent" is
    /// all of them and "an opponent" is any one of them (CR 102.1). Both facts need three seats to
    /// state — at two, "any" and "all" are the same person and the tie is the only case left that
    /// separates them.
    /// </remarks>
    [Fact]
    public void A_hand_comparison_asked_of_an_opponent_is_not_the_negation_of_the_other()
    {
        var envious = Card(
            "Envious Rival Test",
            "~ has flying as long as an opponent has more cards in hand than you.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var greedy = Card(
            "Greedy Rival Test",
            "~ has flying as long as you have more cards in hand than each opponent.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        foreach (var card in (CardDefinition[])[envious, greedy])
        {
            var compiled = CardCompiler.Compile(card);
            Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        }

        var (game, alice, bob, carol) = InMainPhaseAtThreeSeats();

        var behind = game.Create(alice, envious, Zone.Battlefield);
        var ahead = game.Create(alice, greedy, Zone.Battlefield);

        bool Flies(ObjectId id) =>
            Characteristics.Of(game.State, Pool, game.State.GetObject(id))
                .Has(KeywordAbility.Flying);

        void HoldExactly(Guid who, int cards)
        {
            while (game.State.GetPlayer(who).Hand.Count > cards)
                game.Move(game.State.GetPlayer(who).Hand[0], Zone.Graveyard, MoveCause.Discard);
        }

        // Alice is behind Carol and ahead of Bob, which is the ordinary middle of a three-seat
        // table and the board a two-seat test can never produce.
        HoldExactly(alice, 3);
        HoldExactly(bob, 2);
        HoldExactly(carol, 4);
        Settle(game);

        Assert.True(Flies(behind));
        Assert.False(Flies(ahead));

        // Carol draws level. Nobody holds strictly more than anybody, so both clauses are off —
        // the case that proves one is not the other's negation.
        HoldExactly(carol, 3);
        Settle(game);

        Assert.False(Flies(behind));
        Assert.False(Flies(ahead));

        // And with Alice ahead of both, the other clause turns on and this one stays off.
        HoldExactly(bob, 1);
        HoldExactly(carol, 2);
        Settle(game);

        Assert.False(Flies(behind));
        Assert.True(Flies(ahead));
    }

    /// <summary>
    /// "An opponent controls three or more creatures" is one opponent's board, not the table's.
    /// </summary>
    /// <remarks>
    /// The plural clause beside it — "your opponents control three or more creatures" — pools
    /// them, and the two only disagree at more than two seats: two opponents with two creatures
    /// each answer the pooled question and not this one. Every card that prints the singular
    /// punishes a <em>player</em> for their own board, so a pooled reading would turn each of them
    /// on at a table where nobody has done anything (CR 102.1).
    /// </remarks>
    [Fact]
    public void An_opponent_controlling_a_count_is_asked_of_each_opponent_separately()
    {
        var singular = Card(
            "Any Rival Board Test",
            "~ has flying as long as an opponent controls three or more creatures.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var pooled = Card(
            "Pooled Rival Board Test",
            "~ has flying as long as your opponents control three or more creatures.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        foreach (var card in (CardDefinition[])[singular, pooled])
        {
            var compiled = CardCompiler.Compile(card);
            Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        }

        var (game, alice, bob, carol) = InMainPhaseAtThreeSeats();

        var eachInTurn = game.Create(alice, singular, Zone.Battlefield);
        var together = game.Create(alice, pooled, Zone.Battlefield);

        bool Flies(ObjectId id) =>
            Characteristics.Of(game.State, Pool, game.State.GetObject(id))
                .Has(KeywordAbility.Flying);

        game.Create(bob, TestCards.Creature("Rival Bear One"), Zone.Battlefield);
        game.Create(bob, TestCards.Creature("Rival Bear Two"), Zone.Battlefield);
        Settle(game);

        // Two creatures on one opponent's board and nothing anywhere else: neither clause is met.
        Assert.False(Flies(eachInTurn));
        Assert.False(Flies(together));

        game.Create(carol, TestCards.Creature("Rival Bear Three"), Zone.Battlefield);
        game.Create(carol, TestCards.Creature("Rival Bear Four"), Zone.Battlefield);
        Settle(game);

        // Four creatures across two opponents, and nobody has three. The pooled clause is on and
        // the singular one is off — the board the two exist to disagree about.
        Assert.False(Flies(eachInTurn));
        Assert.True(Flies(together));

        game.Create(carol, TestCards.Creature("Rival Bear Five"), Zone.Battlefield);
        Settle(game);

        Assert.True(Flies(eachInTurn));
        Assert.True(Flies(together));

        // Alice's own board is not an opponent's, however large it gets — the assertion that
        // stops a reader which forgot whose permanents it was counting.
        var (mine, mineAlice, _, _) = InMainPhaseAtThreeSeats();
        var lonely = mine.Create(mineAlice, singular, Zone.Battlefield);

        for (var i = 0; i < 4; i++)
            mine.Create(mineAlice, TestCards.Creature($"Own Bear {i}"), Zone.Battlefield);

        Settle(mine);

        Assert.False(
            Characteristics.Of(mine.State, Pool, mine.State.GetObject(lonely))
                .Has(KeywordAbility.Flying));
    }

    /// <summary>Three seats, because "an opponent" and "each opponent" are one player at two.</summary>
    private static (Game Game, Guid Alice, Guid Bob, Guid Carol) InMainPhaseAtThreeSeats()
    {
        var alice = Guid.Parse("11111111-1111-1111-1111-111111111111");
        var bob = Guid.Parse("22222222-2222-2222-2222-222222222222");
        var carol = Guid.Parse("33333333-3333-3333-3333-333333333333");

        var game = Game.Start(
            Guid.NewGuid(),
            [
                new PlayerSetup(alice, "Alice", 20, TestCards.Deck(40, "Alice")),
                new PlayerSetup(bob, "Bob", 20, TestCards.Deck(40, "Bob")),
                new PlayerSetup(carol, "Carol", 20, TestCards.Deck(40, "Carol")),
            ],
            new GameRandom(1),
            startingPlayerId: alice,
            abilities: Pool);

        game.BeginPlay(withMulligans: false);
        TestCards.PassToStep(game, TurnStep.PrecombatMain);
        return (game, alice, bob, carol);
    }

    [Fact]
    public void A_hellbent_condition_counts_the_hand_it_names()
    {
        var brute = Card(
            "Hellbent Test",
            "~ has flying as long as you have no cards in hand.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var compiled = CardCompiler.Compile(brute);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var creature = game.Create(alice, brute, Zone.Battlefield);
        Assert.NotEmpty(game.State.GetPlayer(alice).Hand);

        Assert.False(
            Characteristics.Of(game.State, Pool, game.State.GetObject(creature))
                .Has(KeywordAbility.Flying));

        // Emptying the hand turns it on. How many cards a player holds is public even though the
        // cards themselves are not (CR 400.2), which is why a card may ask at all.
        foreach (var held in game.State.GetPlayer(alice).Hand.ToList())
            game.Move(held, Zone.Graveyard, MoveCause.Discard);

        Settle(game);

        Assert.Empty(game.State.GetPlayer(alice).Hand);

        Assert.True(
            Characteristics.Of(game.State, Pool, game.State.GetObject(creature))
                .Has(KeywordAbility.Flying));
    }

    // ---- Evasion -------------------------------------------------------------

    [Fact]
    public void A_creature_that_cannot_block_is_refused_as_a_blocker()
    {
        var coward = Card("Coward Test", "~ can't block.", CardType.Creature, 2, 2);
        var (game, alice, bob) = InMainPhase();

        var attacker = game.Create(alice, TestCards.Creature("Attacker", 2, 2), Zone.Battlefield);
        var blocker = game.Create(bob, coward, Zone.Battlefield);

        var why = CombatRules.CannotBlock(
            game.State, Pool, game.State.GetObject(blocker), game.State.GetObject(attacker), bob);

        Assert.NotNull(why);
        Assert.Contains("cannot block", why, StringComparison.Ordinal);
    }

    [Fact]
    public void Landwalk_is_unblockable_only_while_the_defender_has_that_land()
    {
        var walker = Card(
            "Walker Test", "Swampwalk", CardType.Creature, 2, 2,
            keywords: KeywordAbility.Swampwalk);

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, walker, Zone.Battlefield);
        var blocker = game.Create(bob, TestCards.Creature("Blocker", 2, 2), Zone.Battlefield);

        // No Swamp yet: an ordinary block is legal.
        Assert.Null(CombatRules.CannotBlock(
            game.State, Pool, game.State.GetObject(blocker), game.State.GetObject(attacker), bob));

        game.Create(bob, TestCards.BasicLand("Swamp"), Zone.Battlefield);

        Assert.NotNull(CombatRules.CannotBlock(
            game.State, Pool, game.State.GetObject(blocker), game.State.GetObject(attacker), bob));
    }

    // ---- Triggers off the turn itself (CR 603.1) -----------------------------

    /// <summary>Plays on to a given step of a given turn, so a phase trigger can be caught.</summary>
    private static void PassTo(Game game, int turn, TurnStep step) =>
        TestCards.PassUntil(
            game, () => game.State.TurnNumber >= turn && game.State.CurrentStep >= step);

    [Fact]
    public void An_upkeep_trigger_waits_for_its_controllers_upkeep()
    {
        var oracle = Card(
            "Upkeep Test",
            "At the beginning of your upkeep, you gain 2 life.",
            CardType.Enchantment);

        var (game, alice, _) = InMainPhase();
        game.Create(alice, oracle, Zone.Battlefield);

        // Turn 2 is the opponent's. "Your upkeep" is not their upkeep, so nothing happens.
        PassTo(game, 2, TurnStep.Draw);
        Assert.Equal(20, game.State.GetPlayer(alice).Life);

        PassTo(game, 3, TurnStep.Draw);
        Assert.Equal(22, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void An_each_player_upkeep_trigger_fires_on_both_turns()
    {
        var oracle = Card(
            "Every Upkeep Test",
            "At the beginning of each player's upkeep, you gain 1 life.",
            CardType.Enchantment);

        var (game, alice, _) = InMainPhase();
        game.Create(alice, oracle, Zone.Battlefield);

        PassTo(game, 2, TurnStep.Draw);
        Assert.Equal(21, game.State.GetPlayer(alice).Life);

        PassTo(game, 3, TurnStep.Draw);
        Assert.Equal(22, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void An_end_step_trigger_fires_in_the_ending_phase_not_the_upkeep()
    {
        var oracle = Card(
            "End Step Test",
            "At the beginning of your end step, you gain 3 life.",
            CardType.Enchantment);

        var (game, alice, _) = InMainPhase();
        game.Create(alice, oracle, Zone.Battlefield);

        // Still turn 1, and the end step has not been reached.
        Assert.Equal(20, game.State.GetPlayer(alice).Life);

        PassTo(game, 1, TurnStep.Cleanup);
        Assert.Equal(23, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void A_beginning_of_combat_trigger_fires_before_attackers_are_declared()
    {
        var oracle = Card(
            "Combat Test",
            "At the beginning of combat on your turn, you gain 1 life.",
            CardType.Enchantment);

        var (game, alice, _) = InMainPhase();
        game.Create(alice, oracle, Zone.Battlefield);

        PassTo(game, 1, TurnStep.DeclareAttackers);
        Assert.Equal(21, game.State.GetPlayer(alice).Life);
    }

    // ---- Triggers off something changing zones -------------------------------

    [Fact]
    public void Landfall_fires_when_a_land_its_controller_owns_arrives()
    {
        // The bug this is here for: a zone change gives the object a new identity (CR 400.7), and
        // the predicate looked the new id up in the state as it was *before* the move — where it
        // does not exist. Every "something enters" trigger on the board was dead, and no test
        // said so because there was none.
        var cobra = Card(
            "Landfall Test",
            "Whenever a land you control enters, you gain 2 life.",
            CardType.Creature, 2, 1);

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, cobra, Zone.Battlefield);

        var forest = TestCards.PutInHand(game, alice, TestCards.BasicLand("Forest"));
        game.PlayLand(alice, forest);
        Settle(game);

        Assert.Equal(22, game.State.GetPlayer(alice).Life);

        // A land the opponent plays is not "a land you control".
        TestCards.PassUntil(game, () => game.State.ActivePlayerId == bob
            && game.State.CurrentStep == TurnStep.PrecombatMain);

        var theirs = TestCards.PutInHand(game, bob, TestCards.BasicLand("Island"));
        game.PlayLand(bob, theirs);
        Settle(game);

        Assert.Equal(22, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void Another_creature_you_control_entering_does_not_count_the_source_itself()
    {
        var watcher = Card(
            "Another Enters Test",
            "Whenever another creature you control enters, you gain 1 life.",
            CardType.Creature, 1, 1);

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, watcher, Zone.Battlefield);
        Settle(game);

        // The watcher's own arrival is excluded by "another".
        Assert.Equal(20, game.State.GetPlayer(alice).Life);

        game.Create(alice, TestCards.Creature("Friend", 2, 2), Zone.Battlefield);
        Settle(game);
        Assert.Equal(21, game.State.GetPlayer(alice).Life);

        // Nor does a creature somebody else controls, nor a land.
        game.Create(bob, TestCards.Creature("Stranger", 2, 2), Zone.Battlefield);
        game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        Settle(game);
        Assert.Equal(21, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void Another_creature_dying_counts_only_creatures()
    {
        var vulture = Card(
            "Death Watch Test",
            "Whenever another creature dies, you gain 1 life.",
            CardType.Creature, 2, 2);

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, vulture, Zone.Battlefield);

        var bear = game.Create(bob, TestCards.Creature("Bear", 2, 2), Zone.Battlefield);
        game.MarkDamage(bear, 2);
        Settle(game);

        Assert.Equal(21, game.State.GetPlayer(alice).Life);
    }

    // ---- Triggers off combat and targeting -----------------------------------

    [Fact]
    public void Becoming_blocked_triggers_only_when_a_blocker_is_actually_declared()
    {
        var menacer = Card(
            "Becomes Blocked Test",
            "Whenever ~ becomes blocked, you gain 4 life.",
            CardType.Creature, 2, 2);

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, menacer, Zone.Battlefield);
        var blocker = game.Create(bob, TestCards.Creature("Blocker", 1, 4), Zone.Battlefield);

        // CR 302.6: it cannot attack the turn it arrived, so the test waits for its controller's
        // next turn rather than reaching into the permanent's status.
        TestCards.PassToTurn(game, 3);
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice, new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);
        game.DeclareBlockers(
            bob, new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [attacker] = [blocker] });
        Settle(game);

        Assert.Equal(24, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void Becoming_the_target_of_a_spell_triggers_as_the_spell_is_cast()
    {
        var wary = Card(
            "Targeted Test",
            "Whenever ~ becomes the target of a spell or ability, you gain 5 life.",
            CardType.Creature, 2, 2);

        var (game, alice, bob) = InMainPhase();
        var creature = game.Create(alice, wary, Zone.Battlefield);

        var bolt = TestCards.PutInHand(
            game, alice, Card("Pinprick Test", "~ deals 1 damage to target creature."));

        game.CastSpell(alice, bolt, [Target.ToPermanent(creature)]);
        Settle(game);

        Assert.Equal(25, game.State.GetPlayer(alice).Life);
        Assert.NotEqual(bob, alice);
    }

    [Fact]
    public void A_cast_trigger_reads_the_spells_type()
    {
        var mage = Card(
            "Cast Watch Test",
            "Whenever you cast an instant or sorcery spell, you gain 1 life.",
            CardType.Creature, 1, 1);

        var (game, alice, _) = InMainPhase();
        game.Create(alice, mage, Zone.Battlefield);

        var instant = TestCards.PutInHand(
            game, alice, Card("Cantrip Test", "Draw a card."));
        game.CastSpell(alice, instant, []);
        Settle(game);

        Assert.Equal(21, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void Gaining_life_triggers_on_the_controllers_own_gain_only()
    {
        var angel = Card(
            "Life Watch Test",
            "Whenever you gain life, put a +1/+1 counter on it.",
            CardType.Creature, 1, 1);

        var (game, alice, bob) = InMainPhase();
        var creature = game.Create(alice, angel, Zone.Battlefield);

        var salve = TestCards.PutInHand(game, alice, Card("Salve Test", "You gain 2 life."));
        game.CastSpell(alice, salve, []);
        Settle(game);

        Assert.Equal(
            1,
            game.State.GetObject(creature).Permanent!.Counters
                .GetValueOrDefault(CounterKinds.PlusOnePlusOne));

        // The opponent gaining life is not "you gain life". The card is dealt after the turn
        // passes, not before: cleanup discards down to hand size (CR 514.1), and a spare card
        // handed over early is exactly the one that gets pitched.
        TestCards.PassUntil(game, () => game.State.ActivePlayerId == bob
            && game.State.CurrentStep == TurnStep.PrecombatMain);
        var theirs = TestCards.PutInHand(game, bob, Card("Their Salve Test", "You gain 2 life."));
        game.CastSpell(bob, theirs, []);
        Settle(game);

        Assert.Equal(
            1,
            game.State.GetObject(creature).Permanent!.Counters
                .GetValueOrDefault(CounterKinds.PlusOnePlusOne));
    }

    // ---- Keyword abilities that expand to something else ---------------------

    [Fact]
    public void Flanking_weakens_the_blocker_but_spares_another_flanker()
    {
        var knight = Card(
            "Flanking Test", "Flanking", CardType.Creature, 2, 2,
            keywords: KeywordAbility.Flanking);

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, knight, Zone.Battlefield);
        var plain = game.Create(bob, TestCards.Creature("Plain", 1, 2), Zone.Battlefield);
        var flanker = game.Create(
            bob,
            Card("Other Flanker Test", "Flanking", CardType.Creature, 1, 2,
                keywords: KeywordAbility.Flanking),
            Zone.Battlefield);

        TestCards.PassToTurn(game, 3);
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice, new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);
        game.DeclareBlockers(
            bob,
            new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [attacker] = [plain, flanker] });

        TestCards.PassUntil(game, () => game.State.PendingTriggers.IsEmpty && game.State.Stack.IsEmpty);

        Assert.Equal(0, Characteristics.Of(game.State, Pool, game.State.GetObject(plain)).Power);

        // CR 702.25a spares a blocker that has flanking itself.
        Assert.Equal(1, Characteristics.Of(game.State, Pool, game.State.GetObject(flanker)).Power);
    }

    [Fact]
    public void Devoid_makes_the_permanent_colourless()
    {
        var eldrazi = new CardDefinition
        {
            OracleId = "oracle-devoid-test",
            Name = "Devoid Test",
            OracleText = "Devoid",
            CardTypes = CardType.Creature,
            Power = 2,
            Toughness = 2,
