    }

    [Fact]
    public void Modular_arrives_with_its_counters_already_on_it()
    {
        // A replacement, not a trigger (CR 614.1c): it is never on the battlefield without them,
        // so nothing can respond in between and no ability sees it arrive bare.
        var golem = Card("Modular Test", "Modular 3", CardType.Creature | CardType.Artifact, 0, 0);

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, golem);

        game.CastSpell(alice, card, []);
        Settle(game);

        var permanent = game.State.Battlefield
            .Select(game.State.GetObject)
            .Single(o => o.Card.Name == "Modular Test");

        Assert.Equal(
            3, permanent.Permanent!.Counters.GetValueOrDefault(CounterKinds.PlusOnePlusOne));
        Assert.Equal(3, Characteristics.Of(game.State, Pool, permanent).Power);
    }

