        Settle(game);

        Assert.Equal(18, game.State.GetPlayer(bob).Life);
        Assert.Equal(22, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void A_nontoken_trigger_ignores_the_tokens_it_is_written_to_exclude()
    {
        var watcher = Card(
            "Nontoken Watch Test",
            "Whenever another nontoken creature you control enters, you gain 1 life.",
            CardType.Creature, 2, 2);

        var (game, alice, _) = InMainPhase();
        game.Create(alice, watcher, Zone.Battlefield);
        Settle(game);

        game.Create(alice, TestCards.Creature("Bear", 2, 2), Zone.Battlefield);
        Settle(game);
        Assert.Equal(21, game.State.GetPlayer(alice).Life);

        // CR 111.1: a token is not a card, and this trigger says so out loud. The words that
        // make the difference are the whole point of the card, so a token arriving has to be
        // the one arrival that does not pay.
        game.Create(
            alice,
            new CardDefinition
            {
                OracleId = "oracle-goblin-token-test",
                Name = "Goblin Token Test",
                CardTypes = CardType.Creature | CardType.Token,
                Power = 1,
                Toughness = 1,
            },
            Zone.Battlefield);
        Settle(game);
        Assert.Equal(21, game.State.GetPlayer(alice).Life);

        // And it arrived - otherwise the line above would be proving that nothing happened
        // rather than that the trigger declined to count it.
        Assert.Contains(
            game.State.Objects.Values,
            o => o.Zone == Zone.Battlefield && o.Card.Name == "Goblin Token Test");
    }

    [Fact]
