    [Fact]
    public void An_intervening_if_about_the_source_reads_the_sources_own_state()
    {
        // Two cards with the same trigger and opposite clauses, in one game, at one upkeep -
        // so whichever fires, the other one proves the clause was actually read.
        var whenTapped = Card(
            "Tapped Clause Test",
            "At the beginning of your upkeep, if this creature is tapped, you gain 5 life.",
            CardType.Creature, 2, 2);

        var whenUntapped = Card(
            "Untapped Clause Test",
            "At the beginning of your upkeep, if this creature is untapped, you gain 3 life.",
            CardType.Creature, 2, 2);

        var (game, alice, _) = InMainPhase();
        game.Create(alice, whenTapped, Zone.Battlefield);
        game.Create(alice, whenUntapped, Zone.Battlefield);
        Settle(game);

        var before = game.State.GetPlayer(alice).Life;

        // Alice's next turn: both untapped after the untap step, so only the second one pays.
        PassTo(game, 3, TurnStep.Upkeep);
        Settle(game);

        Assert.Equal(before + 3, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void An_intervening_if_about_the_sources_type_reads_what_it_is()
    {
        var text = "At the beginning of your upkeep, if this permanent is an enchantment, "
            + "you gain 2 life.";

        var (game, alice, _) = InMainPhase();
        game.Create(alice, Card("Enchantment Clause Test", text, CardType.Enchantment), Zone.Battlefield);
        game.Create(
            alice,
            Card("Creature Clause Test", text, CardType.Creature, 2, 2),
            Zone.Battlefield);
        Settle(game);

        var before = game.State.GetPlayer(alice).Life;

        PassTo(game, 3, TurnStep.Upkeep);
        Settle(game);

        // Same sentence on both, and only the one that is an enchantment pays.
        Assert.Equal(before + 2, game.State.GetPlayer(alice).Life);
    }

    [Theory]
    [InlineData(1, 0)]
    [InlineData(2, 1)]
    public void A_life_gain_clause_counts_what_was_gained_and_not_the_current_total(
        int gains, int expectedDraws)
    {
        // Two life a spell: one cast is under the bar and two clears it. Run as two separate
        // games so neither half can be reading life the other half gained.
        var watcher = Card(
            "Threshold Gain Test",
            "At the beginning of your end step, if you gained 3 or more life this turn, "
                + "draw a card.",
            CardType.Enchantment);

        var gain = Card("Small Gain Test", "You gain 2 life.");

        var (game, alice, _) = InMainPhase();
        game.Create(alice, watcher, Zone.Battlefield);

        foreach (var _ in Enumerable.Range(0, gains))
        {
            var card = TestCards.PutInHand(game, alice, gain);
            game.CastSpell(alice, card, []);
        }

        var handBefore = game.State.GetPlayer(alice).Hand.Count;
        Settle(game);

        Assert.Equal(gains * 2, game.State.GetPlayer(alice).LifeGainedThisTurn);

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.End);
        Settle(game);

        // The life is gained either way; the clause is what decides whether the card is drawn.
        Assert.Equal(handBefore + expectedDraws, game.State.GetPlayer(alice).Hand.Count);
    }

    [Theory]
    [InlineData(3, 2)]
    [InlineData(1, 0)]
    public void A_clause_comparing_two_boards_counts_both_of_them(int theirLands, int gain)
    {
        var watcher = Card(
            "Land Envy Test",
            "At the beginning of your upkeep, if an opponent controls more lands than you, "
                + "you gain 2 life.",
            CardType.Enchantment);

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, watcher, Zone.Battlefield);
        game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);

        foreach (var _ in Enumerable.Range(0, theirLands))
            game.Create(bob, TestCards.BasicLand("Island"), Zone.Battlefield);

        var before = game.State.GetPlayer(alice).Life;

        PassTo(game, 3, TurnStep.Upkeep);
        Settle(game);

        // Three of theirs against one of Alice's beats it; one against one does not, because
        // "more" is strict.
        Assert.Equal(before + gain, game.State.GetPlayer(alice).Life);
    }

    [Theory]
    [InlineData(2, 2)]
    [InlineData(1, 0)]
    public void A_count_can_name_a_permanent_by_more_than_its_type(int attackers, int gain)
    {
        var watcher = Card(
            "Tapped Count Test",
            "At the beginning of your end step, if you control two or more tapped creatures, "
                + "you gain 2 life.",
            CardType.Enchantment);

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, watcher, Zone.Battlefield);

        var army = Enumerable.Range(0, 2)
            .Select(i => game.Create(
                alice, TestCards.Creature("Tapped Count Soldier " + i, 1, 1), Zone.Battlefield))
            .ToList();

        var before = game.State.GetPlayer(alice).Life;

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            army.Take(attackers).ToDictionary(id => id, _ => AttackTarget.Player(bob)));

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.End);
        Settle(game);

        // Attacking taps them (CR 508.1f), so the end step finds as many tapped creatures as
        // Alice sent - which is what makes "tapped creatures" a different count from "creatures".
        Assert.Equal(before + gain, game.State.GetPlayer(alice).Life);
    }

    [Theory]
    [InlineData(true, 2)]
    [InlineData(false, 0)]
    public void A_spell_count_clause_tells_the_two_kinds_apart(bool noncreature, int gain)
    {
        // The clause names noncreature spells, so a creature spell must not satisfy it. Counting
        // every spell would answer a narrower question with a wider number - the failure mode
        // this reader is shaped to avoid.
        var watcher = Card(
            "Spell Count Test",
            "At the beginning of your end step, if you've cast a noncreature spell this turn, "
                + "you gain 2 life.",
            CardType.Enchantment);

        var spell = noncreature
            ? Card("Counted Instant Test", "You gain 0 life.")
            : new CardDefinition
            {
                OracleId = "oracle-counted-creature-test",
                Name = "Counted Creature Test",
                OracleText = string.Empty,
                CardTypes = CardType.Creature,
                ManaCostRaw = "{1}",
                Cmc = 1,
                Power = 1,
                Toughness = 1,
            };

        var (game, alice, _) = InMainPhase();
        game.Create(alice, watcher, Zone.Battlefield);
        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, forest, "mana");

        var card = TestCards.PutInHand(game, alice, spell);
        game.CastSpell(alice, card, []);

        var before = game.State.GetPlayer(alice).Life;
        Settle(game);

        Assert.Equal(1, game.State.GetPlayer(alice).SpellsCastThisTurn);
        Assert.Equal(
            noncreature ? 1 : 0, game.State.GetPlayer(alice).NoncreatureSpellsCastThisTurn);

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.End);
        Settle(game);

        Assert.Equal(before + gain, game.State.GetPlayer(alice).Life);
    }

    [Theory]
    [InlineData(1)]
    [InlineData(3)]
    public void A_plural_combat_trigger_fires_once_however_many_connected(int attackers)
    {
        // CR 603.2 with CR 510.2: the damage is dealt simultaneously, so "one or more" is one
        // trigger. Reusing the singular reader would have fired it once per creature, and the
        // card would have paid three times for a sentence that says once.
        var watcher = Card(
            "Plural Damage Test",
            "Whenever one or more creatures you control deal combat damage to a player, "
                + "you gain 1 life.",
            CardType.Enchantment);

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, watcher, Zone.Battlefield);

        var army = Enumerable.Range(0, 3)
            .Select(i => game.Create(
                alice, TestCards.Creature("Plural Soldier " + i, 1, 1), Zone.Battlefield))
            .ToList();

        var before = game.State.GetPlayer(alice).Life;

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            army.Take(attackers).ToDictionary(id => id, _ => AttackTarget.Player(bob)));

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Settle(game);

        Assert.Equal(20 - attackers, game.State.GetPlayer(bob).Life);
        Assert.Equal(before + 1, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void A_plural_combat_trigger_stays_silent_when_nothing_it_names_connected()
    {
        var watcher = Card(
            "Plural Flier Test",
            "Whenever one or more creatures you control with flying deal combat damage to a "
                + "player, you gain 4 life.",
            CardType.Enchantment);

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, watcher, Zone.Battlefield);
        var grounded = game.Create(
            alice, TestCards.Creature("Grounded Test", 2, 2), Zone.Battlefield);

        var before = game.State.GetPlayer(alice).Life;

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [grounded] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Settle(game);

        // It connected, so the batch event fired - and the description in the sentence is what
        // decides, which is the half a plural reader could most easily drop.
        Assert.Equal(18, game.State.GetPlayer(bob).Life);
        Assert.Equal(before, game.State.GetPlayer(alice).Life);
    }

    [Theory]
    [InlineData("+1/+1", 2)]
    [InlineData("-1/-1", 0)]
    public void A_counter_trigger_reads_which_kind_of_counter_arrived(string kind, int gain)
    {
        // The sentence names +1/+1 counters, so any counter at all is the wrong answer - the
        // same mistake as counting every spell for a clause about noncreature ones.
        var watcher = Card(
            "Counter Watch Test",
            "Whenever one or more +1/+1 counters are put on ~, you gain 2 life.",
            CardType.Creature, 2, 2);

        // Named for the counter it puts: the two theory cases are two different cards, and the
        // compiled pool refuses to serve one card's behaviour under another's id.
        var putter = Card(
            "Counter Putter " + kind + " Test",
            "Put a " + kind + " counter on target creature.");

        var (game, alice, _) = InMainPhase();
        var watched = game.Create(alice, watcher, Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, putter);
        game.CastSpell(alice, card, [Target.ToPermanent(watched)]);

        var before = game.State.GetPlayer(alice).Life;
        Settle(game);

        // The counter went on either way; only one of them is the one the card watches for.
        Assert.Equal(
            1,
            game.State.GetObject(watched).Permanent?.Counters.GetValueOrDefault(kind) ?? 0);

        Assert.Equal(before + gain, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void It_means_the_creature_the_trigger_was_about_and_not_the_card_that_said_it()
    {
        // CR 603.1. Only one event reported what it was about, so every other trigger reported
        // nothing and "it" fell through to meaning the permanent with the ability: this card put
        // the counter on itself, every time, and nothing failed. The two creatures are told
        // apart by which one ends up bigger.
        var shepherd = Card(
            "Counter Shepherd Test",
            "Whenever another creature you control enters, put a +1/+1 counter on it.",
            CardType.Creature, 2, 2);

        var (game, alice, _) = InMainPhase();
        var source = game.Create(alice, shepherd, Zone.Battlefield);
        Settle(game);

        var arrival = game.Create(
            alice, TestCards.Creature("Counter Arrival Test", 1, 1), Zone.Battlefield);
        Settle(game);

        Assert.Equal(
            1,
            game.State.GetObject(arrival).Permanent?.Counters.GetValueOrDefault("+1/+1") ?? 0);

        Assert.Equal(
            0,
            game.State.GetObject(source).Permanent?.Counters.GetValueOrDefault("+1/+1") ?? 0);
    }

    [Fact]
    public void A_pronoun_the_reader_cannot_resolve_still_leaves_the_card_unread()
    {
        // Destroy, exile and tap take a pronoun now, and the rule about what a pronoun may mean
        // did not move with them: with nothing targeted there is no referent this reader can
        // see, and the fallback would be the permanent with the ability. "Whenever ~ blocks a
        // creature, destroy that creature" would have destroyed the blocker.
        Assert.False(CardCompiler.Compile(
            Card("Dangling Destroy Test", "Destroy it.")).IsComplete);

        Assert.False(CardCompiler.Compile(
            Card("Dangling Exile Test", "Exile that creature.")).IsComplete);

        // With a target in the same sentence there is a referent, and it is used.
        Assert.True(CardCompiler.Compile(
            Card("Chained Exile Test", "Tap target creature. Exile it.")).IsComplete);
    }

    [Fact]
    public void That_player_means_the_one_who_drew_and_not_the_cards_controller()
    {
        // A draw is a zone change, and nothing told the trigger which player it was about - so
        // "that player" resolved to nobody and the effect emitted no events at all. The card
        // compiled, the trigger fired, and the game was simply not played: a failure with no
        // symptom, which is why it is asserted on the opponent's life rather than on the log.
        var watcher = Card(
            "Draw Punish Test",
            "Whenever an opponent draws a card, that player loses 2 life.",
            CardType.Enchantment);

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, watcher, Zone.Battlefield);
        Settle(game);

        TestCards.PassToTurn(game, 2);
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.PrecombatMain);
        Settle(game);

        // Bob drew for his turn and paid for it; Alice, who controls the enchantment, did not.
        Assert.Equal(18, game.State.GetPlayer(bob).Life);
        Assert.Equal(20, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void That_player_means_the_one_whose_creature_died()
    {
        // Massacre Wurm's shape. A dying creature's controller is a battlefield fact, and the
        // card is its owner's the moment it is in the graveyard (CR 108.4, CR 109.5) - so the
        // object as it last was is the one that knows whose it was.
        var wurm = Card(
            "Death Toll Test",
            "Whenever a creature an opponent controls dies, that player loses 2 life.",
            CardType.Creature, 6, 5);

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, wurm, Zone.Battlefield);

        var theirs = game.Create(bob, TestCards.Creature("Doomed Test", 1, 1), Zone.Battlefield);
        Settle(game);

        game.Move(theirs, Zone.Graveyard, MoveCause.Destroy);
        Settle(game);

        Assert.Equal(18, game.State.GetPlayer(bob).Life);
        Assert.Equal(20, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void It_means_the_creature_that_connected_and_not_the_one_watching()
    {
        // "It" after "deals combat damage to a player" can only be the creature that dealt it -
        // the other participant is a player, not an object.
        var regent = Card(
            "Connect Counter Test",
            "Whenever another creature you control deals combat damage to a player, "
                + "put a +1/+1 counter on it.",
            CardType.Creature, 2, 2);

        var (game, alice, bob) = InMainPhase();
        var watcher = game.Create(alice, regent, Zone.Battlefield);
        var attacker = game.Create(
            alice, TestCards.Creature("Connecting Test", 2, 2), Zone.Battlefield);
        Settle(game);

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Settle(game);

        Assert.Equal(
            1,
            game.State.GetObject(attacker).Permanent?.Counters.GetValueOrDefault("+1/+1") ?? 0);

        Assert.Equal(
            0,
            game.State.GetObject(watcher).Permanent?.Counters.GetValueOrDefault("+1/+1") ?? 0);
    }

    [Fact]
    public void That_player_means_the_one_whose_land_arrived()
    {
        // Polluted Bonds' shape. An object created rather than moved carries its controller on
        // the event, and nothing was reading it - so "that player" meant nobody and neither half
        // of the sentence happened.
        var bonds = Card(
            "Land Toll Test",
            "Whenever a land enters under an opponent's control, that player loses 2 life "
                + "and you gain 2 life.",
            CardType.Enchantment);

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, bonds, Zone.Battlefield);
        Settle(game);

        game.Create(bob, TestCards.BasicLand("Island"), Zone.Battlefield);
        Settle(game);

        Assert.Equal(18, game.State.GetPlayer(bob).Life);
        Assert.Equal(22, game.State.GetPlayer(alice).Life);

        // Alice's own land is not an opponent's, so nothing moves.
        game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        Settle(game);

        Assert.Equal(18, game.State.GetPlayer(bob).Life);
        Assert.Equal(22, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void An_auras_it_means_the_creature_it_is_on_and_not_the_aura()
    {
        // Unstable Mutation's shape. The trigger fires on a step, which is about no object at
        // all, so "it" fell back to the permanent with the ability: the Aura put the counter on
        // itself, shrinking nothing, and the creature it was written to wear down was untouched.
        var mutation = Card(
            "Wasting Aura Test",
            "Enchant creature" + (char)10
                + "At the beginning of the upkeep of enchanted creature's controller, "
                + "put a -1/-1 counter on it.",
            CardType.Enchantment, null, null, KeywordAbility.None, "Aura");

        var (game, alice, _) = InMainPhase();
        var bear = game.Create(alice, TestCards.Creature("Wasting Host Test", 3, 3), Zone.Battlefield);
        var aura = game.Create(alice, mutation, Zone.Battlefield);
        game.Attach(aura, bear);
        Settle(game);

        PassTo(game, 3, TurnStep.Upkeep);
        Settle(game);

        Assert.Equal(
            1,
            game.State.GetObject(bear).Permanent?.Counters.GetValueOrDefault("-1/-1") ?? 0);

        Assert.Equal(
            0,
            game.State.GetObject(aura).Permanent?.Counters.GetValueOrDefault("-1/-1") ?? 0);
    }

    [Fact]
    public void That_much_life_means_what_the_sentence_before_it_just_took()
    {
        // A drain is two clauses and one number, and the number belongs to the first: "that
        // much" is not the triggering event's amount, because a spell has no triggering event.
        // The gain resolved to nothing, so every drain in the game took life and gave none -
        // and the card compiled, cast and resolved without complaint.
        var drain = Card(
            "That Much Drain Test", "Each opponent loses 2 life and you gain that much life.");

        var (game, alice, bob) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, drain);
        game.CastSpell(alice, card, []);
        Settle(game);

        Assert.Equal(18, game.State.GetPlayer(bob).Life);
        Assert.Equal(22, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void A_gain_that_reads_its_own_clause_is_not_fed_by_the_gain_itself()
    {
        // The running amount counts life lost and damage dealt and deliberately not life
        // gained: the gain is usually the clause doing the asking, and counting it would make
        // the number grow down the card. Two drains in one spell each take their own amount.
        var twice = Card(
            "Double Drain Test",
            "Each opponent loses 1 life and you gain that much life. "
                + "Each opponent loses 3 life and you gain that much life.");

        var (game, alice, bob) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, twice);
        game.CastSpell(alice, card, []);
        Settle(game);

        Assert.Equal(16, game.State.GetPlayer(bob).Life);
        Assert.Equal(24, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void A_mass_effect_naming_a_tribe_or_a_land_type_finds_them()
    {
        // The group grammar folded plurals for the six card types and nothing else, so a tribe
        // or a land type stayed plural and the filter went looking for a subtype called
        // "Islands" - which no card has. Boil destroyed no Islands, and compiled, cast and
        // resolved without complaint.
        var boil = Card("Boil Test", "Destroy all Islands.");

        var (game, alice, bob) = InMainPhase();
        var island = game.Create(bob, TestCards.BasicLand("Island"), Zone.Battlefield);
        var forest = game.Create(bob, TestCards.BasicLand("Forest"), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, boil);
        game.CastSpell(alice, card, []);
        Settle(game);

        Assert.DoesNotContain(island, game.State.Battlefield);
        Assert.Contains(forest, game.State.Battlefield);
    }

    [Fact]
    public void A_mass_effect_naming_a_creature_tribe_finds_only_that_tribe()
    {
        var crusade = Card("Tribe Sweep Test", "Destroy all Goblins.");

        var (game, alice, bob) = InMainPhase();
        var goblin = game.Create(
            bob,
            Card("Sweep Goblin Test", string.Empty, CardType.Creature, 1, 1,
                KeywordAbility.None, "Goblin"),
            Zone.Battlefield);

        var bear = game.Create(bob, TestCards.Creature("Sweep Bear Test", 2, 2), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, crusade);
        game.CastSpell(alice, card, []);
        Settle(game);

        Assert.DoesNotContain(goblin, game.State.Battlefield);
        Assert.Contains(bear, game.State.Battlefield);
    }

    [Fact]
    public void A_mass_pump_naming_a_colour_finds_that_colour()
    {
        // The adjective vocabulary had every colour's negation and none of the colours: there
        // was a reading for "nonwhite creature" and none at all for "white creature". The
        // sentence still compiled, because a capitalised word with no other reading is taken for
        // a creature type - so "White creatures get +2/+0" looked for a tribe called White and
        // pumped nothing.
        var charge = Card("Colour Pump Test", "White creatures get +2/+0 until end of turn.");

        var (game, alice, _) = InMainPhase();
        var soldier = game.Create(alice, Coloured("Pump White Bear", ManaColor.White), Zone.Battlefield);
        var other = game.Create(alice, Coloured("Pump Blue Bear", ManaColor.Blue), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, charge);
        game.CastSpell(alice, card, []);
        Settle(game);

        var pool = new CompiledPool();

        Assert.Equal(4, Characteristics.PowerOf(game.State, pool, game.State.GetObject(soldier)));
        Assert.Equal(2, Characteristics.PowerOf(game.State, pool, game.State.GetObject(other)));
    }

    [Fact]
    public void A_mass_pump_naming_the_attackers_finds_them()
    {
        // Same defect, different word: "Attacking" at the start of a sentence is capitalised by
        // position, and the adjective slot was matched case-sensitively - so it fell through to
        // the tribe reading, like the colours did.
        var blast = Card("Blast Pump Test", "Attacking creatures get +2/+0 until end of turn.");

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, TestCards.Creature("Blast Attacker", 2, 2), Zone.Battlefield);
        var home = game.Create(alice, TestCards.Creature("Blast Homebody", 2, 2), Zone.Battlefield);

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        var card = TestCards.PutInHand(game, alice, blast);
        game.CastSpell(alice, card, []);
        Settle(game);

        var pool = new CompiledPool();

        Assert.Equal(4, Characteristics.PowerOf(game.State, pool, game.State.GetObject(attacker)));
        Assert.Equal(2, Characteristics.PowerOf(game.State, pool, game.State.GetObject(home)));
    }

    [Fact]
    public void A_mass_effect_naming_basic_lands_spares_the_others()
    {
        // "Nonbasic" had a reading and "basic" had none, the same gap the colours were in.
        var wave = Card("Basic Sweep Test", "Destroy all basic lands.");

        var (game, alice, bob) = InMainPhase();
        var island = game.Create(bob, TestCards.BasicLand("Island"), Zone.Battlefield);
        var tower = game.Create(
            bob, Card("Nonbasic Tower Test", string.Empty, CardType.Land), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, wave);
        game.CastSpell(alice, card, []);
        Settle(game);

        Assert.DoesNotContain(island, game.State.Battlefield);
        Assert.Contains(tower, game.State.Battlefield);
    }

    [Fact]
    public void Modified_means_a_counter_or_something_attached()
    {
        // CR 701.48a: three unrelated things under one word, like historic. A counter is enough
        // on its own, and a creature with neither is not modified however large it is.
        var purge = Card("Modified Sweep Test", "Destroy all modified creatures.");

        var (game, alice, bob) = InMainPhase();
        // Counters put on by the creature's own arrival, since nothing else in the harness
        // places one directly.
        var counted = game.Create(
            bob,
            Card("Counted Test", "When ~ enters, put a +1/+1 counter on it.",
                CardType.Creature, 1, 1),
            Zone.Battlefield);
        var plain = game.Create(bob, TestCards.Creature("Plain Test", 5, 5), Zone.Battlefield);
        var worn = game.Create(bob, TestCards.Creature("Worn Test", 2, 2), Zone.Battlefield);

        var aura = game.Create(
            bob,
            Card("Sweep Aura Test", "Enchant creature", CardType.Enchantment,
                null, null, KeywordAbility.None, "Aura"),
            Zone.Battlefield);

        game.Attach(aura, worn);
        Settle(game);

        Assert.Equal(
            1,
            game.State.GetObject(counted).Permanent?.Counters.GetValueOrDefault("+1/+1") ?? 0);

        var card = TestCards.PutInHand(game, alice, purge);
        game.CastSpell(alice, card, []);
        Settle(game);

        Assert.DoesNotContain(counted, game.State.Battlefield);
        Assert.DoesNotContain(worn, game.State.Battlefield);
        Assert.Contains(plain, game.State.Battlefield);
    }

    [Fact]
    public void A_granted_evasion_keyword_is_enforced_in_combat()
    {
        // The blocking rules have played fear since combat was built; the word for granting it
        // was never written into the table the compiler reads, so a card that hands it out
        // compiled to a grant of nothing. Found by diffing that table against the enum.
        var scare = Card("Fear Grant Test", "Target creature gains fear until end of turn.");

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, TestCards.Creature("Feared Test", 2, 2), Zone.Battlefield);
        var greenBlocker = game.Create(bob, Coloured("Green Blocker Test", ManaColor.Green), Zone.Battlefield);

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        var card = TestCards.PutInHand(game, alice, scare);
        game.CastSpell(alice, card, [Target.ToPermanent(attacker)]);
        Settle(game);

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);

        // CR 702.36b: a green creature is neither an artifact nor black, so it may not block.
        var refused = Assert.Throws<InvalidOperationException>(() =>
            game.DeclareBlockers(
                bob,
                new Dictionary<ObjectId, IReadOnlyList<ObjectId>>
                {
                    [attacker] = [greenBlocker],
                }));

        Assert.Contains("fear", refused.Message, StringComparison.OrdinalIgnoreCase);
    }

    [Fact]
    public void Counting_instant_and_sorcery_cards_counts_either_of_them()
    {
        // "And" joining two card types means a card answering to either: nothing is an instant
        // and a sorcery at once, so reading it as a conjunction counts zero every time.
        var tarmo = Card(
            "Graveyard Sage Test",
            "~'s power is equal to the number of instant and sorcery cards in your graveyard.",
            CardType.Creature, 0, 4);

        var (game, alice, _) = InMainPhase();
        var sage = game.Create(alice, tarmo, Zone.Battlefield);

        game.Create(alice, Card("Yard Instant Test", string.Empty), Zone.Graveyard);
        game.Create(alice, Card("Yard Sorcery Test", string.Empty, CardType.Sorcery), Zone.Graveyard);
        game.Create(alice, TestCards.Creature("Yard Bear Test", 2, 2), Zone.Graveyard);
        Settle(game);

        var pool = new CompiledPool();
        var obj = game.State.GetObject(sage);

        // The instant and the sorcery, and not the creature.
        Assert.Equal(2, Characteristics.PowerOf(game.State, pool, obj));
        Assert.Equal(4, Characteristics.ToughnessOf(game.State, pool, obj));
    }

    [Fact]
    public void Counting_creatures_on_the_battlefield_counts_everyones()
    {
        var mirror = Card(
            "Mirror Totem Test",
            "~'s power and toughness are each equal to the number of creatures on the battlefield.",
            CardType.Creature, 0, 0);

        var (game, alice, bob) = InMainPhase();
        var totem = game.Create(alice, mirror, Zone.Battlefield);
        game.Create(alice, TestCards.Creature("Mirror Mine Test", 1, 1), Zone.Battlefield);
        game.Create(bob, TestCards.Creature("Mirror Theirs Test", 1, 1), Zone.Battlefield);
        Settle(game);

        var pool = new CompiledPool();

        // Both players' creatures and itself: the phrase names no owner, so neither does the count.
        Assert.Equal(3, Characteristics.PowerOf(game.State, pool, game.State.GetObject(totem)));
    }

    [Fact]
    public void A_defining_ability_may_set_one_stat_and_leave_the_other_printed()
    {
        // CR 604.3. "Power and toughness are each equal to" was read and "power is equal to" was
        // not - the same sentence with one stat in it. The half the sentence does not mention
        // keeps its printed value, which is the part a pair-only reader had nowhere to put.
        var totem = Card(
            "Defined Power Test",
            "~'s power is equal to the number of creatures you control.",
            CardType.Creature, 0, 3);

        var (game, alice, _) = InMainPhase();
        var totemId = game.Create(alice, totem, Zone.Battlefield);
        game.Create(alice, TestCards.Creature("Defined Friend One", 1, 1), Zone.Battlefield);
        game.Create(alice, TestCards.Creature("Defined Friend Two", 1, 1), Zone.Battlefield);
        Settle(game);

        var pool = new CompiledPool();
        var obj = game.State.GetObject(totemId);

        // Three creatures: the two friends and the totem itself.
        Assert.Equal(3, Characteristics.PowerOf(game.State, pool, obj));
        Assert.Equal(3, Characteristics.ToughnessOf(game.State, pool, obj));

        // And the toughness is the printed 3 rather than a copy of the count: with one friend
        // gone the power moves and the toughness does not.
        var friend = game.State.Battlefield
            .Select(game.State.GetObject)
            .First(o => o.Card.Name == "Defined Friend One");

        game.Move(friend.Id, Zone.Graveyard, MoveCause.Destroy);
        Settle(game);

        var after = game.State.GetObject(totemId);
        Assert.Equal(2, Characteristics.PowerOf(game.State, pool, after));
        Assert.Equal(3, Characteristics.ToughnessOf(game.State, pool, after));
    }

    [Fact]
    public void Monstrosity_puts_the_counters_on_once_and_triggers_on_the_designation()
    {
        // CR 701.32a and 701.32b. The designation is what makes this different from adapt: a
        // creature that picked up +1/+1 counters some other way can still become monstrous, and
        // one that already is gets nothing however many counters it has lost since.
        var hydra = new CardDefinition
        {
            OracleId = "oracle-monstrosity-test",
            Name = "Monstrosity Test",
            OracleText = "{G}: Monstrosity 2." + (char)10
                + "When ~ becomes monstrous, you gain 3 life.",
            CardTypes = CardType.Creature,
            ManaCostRaw = "{G}",
            Cmc = 1,
            Power = 1,
            Toughness = 1,
        };

        var (game, alice, _) = InMainPhase();
        var id = game.Create(alice, hydra, Zone.Battlefield);

        var before = game.State.GetPlayer(alice).Life;

        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, forest, "mana");
        game.ActivateAbility(alice, id, "a");
        Settle(game);

        Assert.Equal(
            2,
            game.State.GetObject(id).Permanent?.Counters.GetValueOrDefault("+1/+1") ?? 0);

        Assert.True(game.State.GetObject(id).Permanent?.IsMonstrous);
        Assert.Equal(before + 3, game.State.GetPlayer(alice).Life);

        // Already monstrous: no more counters, and the trigger does not fire a second time.
        var second = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, second, "mana");
        game.ActivateAbility(alice, id, "a");
        Settle(game);

        Assert.Equal(
            2,
            game.State.GetObject(id).Permanent?.Counters.GetValueOrDefault("+1/+1") ?? 0);

        Assert.Equal(before + 3, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void A_permanent_created_on_the_battlefield_still_enters_with_its_counters()
    {
        // CR 111.1: a token is created there and was never anywhere else, so it is not among the
        // objects the replacement pipeline walks when its own arrival is being replaced - and its
        // own replacements are exactly the ones that decide how it arrives. Every entry
        // replacement was written against the move, so this arrived bare.
        var phantom = Card(
            "Created Counters Test",
            "~ enters with two +1/+1 counters on it.",
            CardType.Creature, 1, 1);

        var (game, alice, _) = InMainPhase();
        var id = game.Create(alice, phantom, Zone.Battlefield);
        Settle(game);

        Assert.Equal(
            2, game.State.GetObject(id).Permanent?.Counters.GetValueOrDefault("+1/+1") ?? 0);
    }

    [Fact]
    public void A_land_created_on_the_battlefield_still_enters_tapped()
    {
        // The same gap in the other entry replacement, and the reason the reader is shared: all
        // five were the same cast to ObjectMoved and wrong in the same way.
        var land = Card("Created Tapped Test", "~ enters tapped.", CardType.Land);

        var (game, alice, _) = InMainPhase();
        var id = game.Create(alice, land, Zone.Battlefield);
        Settle(game);

        Assert.True(game.State.GetObject(id).Permanent?.IsTapped);
    }

    [Theory]
    [InlineData("Forest", "Island", 2)]
    [InlineData("Forest", "Forest", 1)]
    public void Sunburst_counts_the_colours_that_were_spent(
        string first, string second, int counters)
    {
        // CR 702.43a. The colours spent, not the colours in the cost: this costs {2}, names no
        // colour at all, and what it enters with depends entirely on which lands paid for it.
        var golem = new CardDefinition
        {
            OracleId = "oracle-sunburst-test",
            Name = "Sunburst Test",
            OracleText = "Sunburst",
            CardTypes = CardType.Creature,
            ManaCostRaw = "{2}",
            Cmc = 2,
            Power = 0,
            Toughness = 4,
        };

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, golem);

        foreach (var basic in new[] { first, second })
        {
            var land = game.Create(alice, TestCards.BasicLand(basic), Zone.Battlefield);
            game.ActivateAbility(alice, land, "mana");
        }

        game.CastSpell(alice, card, []);
        Settle(game);

        var id = game.State.Battlefield
            .Select(game.State.GetObject)
            .First(o => o.Card.Name == "Sunburst Test")
            .Id;

        Assert.Equal(
            counters,
            game.State.GetObject(id).Permanent?.Counters.GetValueOrDefault("+1/+1") ?? 0);
    }

    [Theory]
    [InlineData("if {U} was spent to cast this spell", "Island", "Island", true)]
    [InlineData("if {U} was spent to cast this spell", "Forest", "Forest", false)]
    [InlineData("if {U}{U} was spent to cast it", "Island", "Island", true)]
    [InlineData("if {U}{U} was spent to cast it", "Island", "Forest", false)]
    [InlineData("if at least two mana was spent to cast it", "Forest", "Island", true)]
    public void A_clause_about_the_mana_spent_reads_what_actually_paid(
        string clause, string first, string second, bool fires)
    {
        // CR 202.2. The mana that paid, not the mana the cost named: this costs {2} and names no
        // colour, so the answer depends entirely on which lands were tapped. The record is kept
        // on the object from the moment it is cast, because the pool has moved on by the time
        // anything asks.
        var spell = new CardDefinition
        {
            OracleId = "oracle-spent-" + clause.GetHashCode(StringComparison.Ordinal),
            Name = "Spent Test " + clause.GetHashCode(StringComparison.Ordinal),
            OracleText = "When ~ enters, " + clause + ", you gain 4 life.",
            CardTypes = CardType.Creature,
            ManaCostRaw = "{2}",
            Cmc = 2,
            Power = 1,
            Toughness = 1,
        };

        Assert.True(CardCompiler.Compile(spell).IsComplete);

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, spell);

        foreach (var basic in new[] { first, second })
        {
            var land = game.Create(alice, TestCards.BasicLand(basic), Zone.Battlefield);
            game.ActivateAbility(alice, land, "mana");
        }

        var before = game.State.GetPlayer(alice).Life;
        game.CastSpell(alice, card, []);
        Settle(game);

        Assert.Equal(before + (fires ? 4 : 0), game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void An_oblivion_ring_printed_as_two_lines_gives_the_card_back()
    {
        // The pair has to be read together: an exile compiled without its return is removal that
        // never gives the card back, which is a strictly better card than the one printed.
        var ring = Card(
            "Two Line Ring Test",
            "When ~ enters, exile target creature an opponent controls." + (char)10
                + "When ~ leaves the battlefield, return the exiled card to the battlefield "
                + "under its owner's control.",
            CardType.Enchantment);

        Assert.True(CardCompiler.Compile(ring).IsComplete);

        var (game, alice, bob) = InMainPhase();
        var victim = game.Create(bob, TestCards.Creature("Ringed Bear Test", 2, 2), Zone.Battlefield);
        var ringId = game.Create(alice, ring, Zone.Battlefield);
        Settle(game);

        Assert.DoesNotContain(victim, game.State.Battlefield);

        // And it comes back when the ring goes, under its owner's control rather than the
        // exiler's (CR 400.7 makes it a new object either way).
        game.Move(ringId, Zone.Graveyard, MoveCause.Destroy);
        Settle(game);

        var returned = game.State.Battlefield
            .Select(game.State.GetObject)
            .SingleOrDefault(o => o.Card.Name == "Ringed Bear Test");

        Assert.NotNull(returned);
        Assert.Equal(bob, returned.ControllerId);
    }

    [Fact]
    public void A_lord_that_names_a_keyword_buffs_only_the_creatures_that_have_it()
    {
        // The qualifier slot the lord grammar was missing.
        var (game, alice, _) = InMainPhase();
        game.Create(
            alice,
            Card("Flying Lord Test", "Other creatures you control with flying get +2/+2.",
                CardType.Creature, 2, 2),
