        var flier = game.Create(
            alice,
            Card("Lord Flier Test", "Flying", CardType.Creature, 1, 1, KeywordAbility.Flying),
            Zone.Battlefield);

        var grounded = game.Create(
            alice, TestCards.Creature("Lord Grounded Test", 1, 1), Zone.Battlefield);

        Settle(game);

        var pool = new CompiledPool();

        Assert.Equal(3, Characteristics.PowerOf(game.State, pool, game.State.GetObject(flier)));
        Assert.Equal(1, Characteristics.PowerOf(game.State, pool, game.State.GetObject(grounded)));
    }

    [Fact]
    public void A_keyword_lord_reads_what_a_creature_is_now_and_not_what_was_printed()
    {
        // Asked of the computed characteristics like everything else in this file: a creature
        // given flying by a spell joins the lord's flock, and a lord reading the printed card
        // would never see it.
        var (game, alice, _) = InMainPhase();
        game.Create(
            alice,
            Card("Wingward Lord Test", "Other creatures you control with flying get +2/+2.",
