        Assert.Equal(3, Characteristics.PowerOf(game.State, pool, game.State.GetObject(grounded)));
    }

    [Theory]
    [InlineData(true, 2)]
    [InlineData(false, 0)]
    public void A_kicked_creature_arrives_with_its_counters(bool kicked, int counters)
    {
        // CR 702.33e, and readable only because the kicker flag survives the move onto the
        // battlefield: the spell that was kicked and the permanent that arrives are different
        // objects (CR 400.7), and CR 607.2 carries the fact across.
        var beast = new CardDefinition
        {
            OracleId = "oracle-kicked-counters-test",
            Name = "Kicked Counters Test",
            OracleText = "Kicker {1}" + (char)10
                + "If ~ was kicked, it enters with two +1/+1 counters on it.",
            CardTypes = CardType.Creature,
            ManaCostRaw = "{1}",
            Cmc = 1,
            Power = 2,
            Toughness = 2,
        };

        Assert.True(CardCompiler.Compile(beast).IsComplete);

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, beast);

        foreach (var _ in Enumerable.Range(0, 2))
        {
            var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
            game.ActivateAbility(alice, forest, "mana");
        }

        game.CastSpell(
            alice, card, targets: null, variableValue: 0, tapToPay: null, modes: null,
            kicked: kicked);

        Settle(game);

        var id = game.State.Battlefield
            .Select(game.State.GetObject)
            .First(o => o.Card.Name == "Kicked Counters Test")
            .Id;

        Assert.Equal(
            counters,
            game.State.GetObject(id).Permanent?.Counters.GetValueOrDefault("+1/+1") ?? 0);
    }

    [Fact]
    public void A_filtered_dig_takes_only_a_card_the_sentence_allows()
    {
        // "You may reveal a creature card from among them and put that card into your hand" -
        // the same dig as "put one of them into your hand" with a filter on what may be taken.
        // The take was already optional (the choice allows none), so "you may" adds nothing the
        // mechanism did not already do; what the filter adds is a rule about which card.
        var dig = Card(
            "Revealing Dig Test",
            "Look at the top five cards of your library. You may reveal a creature card from "
                + "among them and put that card into your hand. Put the rest on the bottom of "
                + "your library in a random order.");

        Assert.True(CardCompiler.Compile(dig).IsComplete);

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, dig);
        var handBefore = game.State.GetPlayer(alice).Hand.Count;
        var libraryBefore = game.State.GetPlayer(alice).Library.Count;

        game.CastSpell(alice, card, []);
        Settle(game);

        // Settle answers the choice with the first option, so one card was taken and the rest
        // went back: the library is one shorter, not five, and the hand is the size it was -
        // the dig itself left it and the taken card replaced it.
        Assert.Equal(libraryBefore - 1, game.State.GetPlayer(alice).Library.Count);
        Assert.Equal(handBefore, game.State.GetPlayer(alice).Hand.Count);
        Assert.Single(game.State.GetPlayer(alice).Graveyard);
    }

    [Theory]
    [InlineData("~ deals damage", 1)]
    [InlineData("~ deals combat damage", 1)]
    [InlineData("~ deals noncombat damage", 0)]
    public void A_damage_trigger_with_no_named_recipient_reads_the_kind_of_damage(
        string condition, int gain)
    {
        // The recipient was mandatory, so the bare forms went unread. A sentence that names no
        // recipient means any of them - and whether the damage has to be combat damage is a
        // separate question, which is why the two are read as two groups.
        var watcher = Card(
            "Damage Watch " + condition.GetHashCode(StringComparison.Ordinal),
            "Whenever " + condition + ", you gain 1 life.",
            CardType.Creature, 2, 2);

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, watcher, Zone.Battlefield);

        var before = game.State.GetPlayer(alice).Life;

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Settle(game);

        // Combat damage: the first two fire, and the one that asks for noncombat damage does not.
        Assert.Equal(18, game.State.GetPlayer(bob).Life);
        Assert.Equal(before + gain, game.State.GetPlayer(alice).Life);
    }

    [Theory]
    [InlineData("scry", "Scry 2.", 1)]
    [InlineData("scry", "Surveil 2.", 0)]
    [InlineData("surveil", "Surveil 2.", 1)]
    [InlineData("surveil", "Scry 2.", 0)]
    public void A_scry_trigger_tells_scrying_and_surveilling_apart(
        string watched, string doing, int gain)
    {
        // CR 701.42a: surveil is the same look with a different destination, so the two are told
        // apart by that flag rather than by two readers - and a card that watches one must not
        // fire on the other.
        var watcher = Card(
            "Look Watcher " + watched,
