    }

    [Fact]
    public void A_static_that_asks_whether_it_is_equipped_reads_what_is_attached()
    {
        // CR 301.5c: equipped is a fact about the Equipment rather than about the creature, so
        // it is asked of the battlefield - and an Aura attached to the same creature is not
        // Equipment, which is the distinction the second half checks.
        var soldier = Card(
            "Equipped Static Test",
            "As long as ~ is equipped, ~ gets +1/+1.",
            CardType.Creature, 2, 2);

        var (game, alice, _) = InMainPhase();
        var id = game.Create(alice, soldier, Zone.Battlefield);

        var aura = game.Create(
            alice,
            Card("Static Aura Test", "Enchant creature", CardType.Enchantment,
                null, null, KeywordAbility.None, "Aura"),
            Zone.Battlefield);

        game.Attach(aura, id);
        Settle(game);

        var pool = new CompiledPool();

        Assert.Equal(2, Characteristics.PowerOf(game.State, pool, game.State.GetObject(id)));

        var sword = game.Create(
            alice,
            Card("Static Sword Test", "Equip {2}", CardType.Artifact,
                null, null, KeywordAbility.None, "Equipment"),
            Zone.Battlefield);

        game.Attach(sword, id);
        Settle(game);

        Assert.Equal(3, Characteristics.PowerOf(game.State, pool, game.State.GetObject(id)));
    }

    [Fact]
    public void Another_in_a_presence_check_excludes_the_permanent_asking()
    {
        // CR 109.5. Every adjective in this slot already worked and this one word did not, which
        // is the difference between a card that turns itself on and one that needs a friend -
        // and a creature counting itself would be permanently switched on.
        var loner = Card(
            "Another Check Test",
            "As long as you control another creature, ~ gets +2/+2.",
            CardType.Creature, 2, 2);

        var (game, alice, bob) = InMainPhase();
        var id = game.Create(alice, loner, Zone.Battlefield);
        Settle(game);

        var pool = new CompiledPool();

        // Alone: it does not count itself.
        Assert.Equal(2, Characteristics.PowerOf(game.State, pool, game.State.GetObject(id)));

        // An opponent's creature is not one you control either.
        game.Create(bob, TestCards.Creature("Another Theirs Test", 1, 1), Zone.Battlefield);
        Settle(game);
        Assert.Equal(2, Characteristics.PowerOf(game.State, pool, game.State.GetObject(id)));

        game.Create(alice, TestCards.Creature("Another Friend Test", 1, 1), Zone.Battlefield);
        Settle(game);
        Assert.Equal(4, Characteristics.PowerOf(game.State, pool, game.State.GetObject(id)));
    }

    [Fact]
    public void An_auras_conditional_static_asks_about_its_host_and_buffs_its_host()
    {
        // Both halves are about the enchanted permanent and neither is about the Aura: the Aura
        // is not a creature, so a reading that asked about itself would never turn on, and one
        // that buffed itself would put the bonus somewhere it cannot be used.
        var aura = Card(
            "Host Condition Test",
            "Enchant permanent" + (char)10
                + "As long as enchanted permanent is a creature, it gets +2/+2.",
            CardType.Enchantment, null, null, KeywordAbility.None, "Aura");

        var (game, alice, _) = InMainPhase();
        var bear = game.Create(alice, TestCards.Creature("Host Bear Test", 2, 2), Zone.Battlefield);
        var rock = game.Create(
            alice, Card("Host Rock Test", string.Empty, CardType.Artifact), Zone.Battlefield);

        var onRock = game.Create(alice, aura, Zone.Battlefield);
        game.Attach(onRock, rock);
        Settle(game);

        var pool = new CompiledPool();

        // On an artifact the condition is false, and the bear beside it is untouched either way.
        Assert.Equal(2, Characteristics.PowerOf(game.State, pool, game.State.GetObject(bear)));

        // Moved onto the creature, the condition holds and the creature is what grows.
        game.Attach(onRock, bear);
        Settle(game);

        Assert.Equal(4, Characteristics.PowerOf(game.State, pool, game.State.GetObject(bear)));
    }

    [Theory]
    [InlineData("As long as you control a Swamp, enchanted creature gets +2/+2.")]
    [InlineData("Enchanted creature gets +2/+2 as long as you control a Swamp.")]
    public void An_aura_naming_its_host_buffs_the_host_whichever_way_round_it_reads(string line)
    {
