    [Fact]
    public void Target_player_discards_and_the_caster_keeps_their_hand()
    {
        var spell = Card("Targeted Discard Test", "Target player discards two cards.");

        var (game, alice, bob) = InMainPhase();

        foreach (var i in Enumerable.Range(0, 3))
        {
            TestCards.PutInHand(game, bob, TestCards.Creature($"Bob Card {i} Test"));
            TestCards.PutInHand(game, alice, TestCards.Creature($"Alice Card {i} Test"));
        }

        var card = TestCards.PutInHand(game, alice, spell);
        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, forest, "mana");

        var aliceBefore = game.State.GetPlayer(alice).Hand.Count;
        var bobBefore = game.State.GetPlayer(bob).Hand.Count;
        game.CastSpell(alice, card, [Target.ToPlayer(bob)]);
        Settle(game);

        // Two fewer than he held, counting the opening hand he was dealt.
        Assert.Equal(bobBefore - 2, game.State.GetPlayer(bob).Hand.Count);

        // Alice loses only the spell she cast. A discard that fell back to "you" would take two
        // more from her, which is the mistake a scope-shaped implementation makes.
        Assert.Equal(aliceBefore - 1, game.State.GetPlayer(alice).Hand.Count);
    }

