    // ---- Offering to sacrifice one of your own (CR 701.16a) ------------------

    [Fact]
    public void You_may_sacrifice_another_creature_offers_your_others_and_not_itself()
    {
        var altar = Card(
            "Sacrifice Offer Test",
            "When ~ enters, you may sacrifice another creature. If you do, you gain 3 life.",
            CardType.Creature, 1, 1);

        var compiled = CardCompiler.Compile(altar);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var fodder = game.Create(alice, TestCards.Creature("Offered Fodder Test", 1, 1), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, altar);
        game.CastSpell(alice, card, targets: null);
        TestCards.PassUntil(game, () => game.State.Choice is not null);

        // First the offer itself, which names what it is asking rather than a price it has not
        // got: a free "you may" used to put "Pay " on the button with nothing after it.
        var offer = game.State.Choice!;
        Assert.Equal("Sacrifice another creature", offer.Options[0].Label);
        game.Choose(alice, [offer.Options[0].Id]);

        TestCards.PassUntil(game, () => game.State.Choice is not null);
        var which = game.State.Choice!;

        // "Another" is the source excluding itself, so the altar is not on its own menu.
        Assert.Single(which.Options);
        Assert.Equal("Offered Fodder Test", which.Options[0].Label);

        game.Choose(alice, [which.Options[0].Id]);
        Settle(game);

        Assert.Equal(23, game.State.GetPlayer(alice).Life);
        Assert.Contains(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Offered Fodder Test");
        Assert.False(game.State.TryGetObject(fodder, out _));
    }

