    // ---- Looking at the top of the library, with a filter (CR 701.20a) -------

    [Fact]
    public void A_search_that_shuffles_first_leaves_the_card_on_top()
    {
        var tutor = Card(
            "Top Tutor Test",
            "Search your library for a Merfolk card, reveal it, then shuffle and put that card "
                + "on top.");

        var compiled = CardCompiler.Compile(tutor);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        game.Create(
            alice,
            Card("Tutored Merfolk Test", string.Empty, CardType.Creature, 2, 2,
                KeywordAbility.None, "Merfolk"),
            Zone.Library);

        var card = TestCards.PutInHand(game, alice, tutor);
        game.CastSpell(alice, card, targets: null);
        TestCards.PassUntil(game, () => game.State.Choice is not null);

        var found = game.State.Choice!.Options.Single(
            o => o.Label == "Tutored Merfolk Test");
        game.Choose(alice, [found.Id]);
        Settle(game);

        // On top of the shuffled library, not shuffled into it: the two steps happen in the
        // order the card prints them, and doing the move first would hide the card at random.
        var top = game.State.GetPlayer(alice).Library[0];
        Assert.Equal("Tutored Merfolk Test", game.State.GetObject(top).Card.Name);
    }

    [Fact]
    public void A_search_can_name_more_than_one_kind_of_card()
    {
        var tutor = Card(
            "Compound Tutor Test",
            "Search your library for a creature or land card, reveal it, put it into your hand, "
                + "then shuffle.");

        var compiled = CardCompiler.Compile(tutor);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        game.Create(alice, TestCards.Creature("Tutored Creature Test", 2, 2), Zone.Library);
        game.Create(alice, TestCards.BasicLand("Tutored Forest Test"), Zone.Library);

