        game.CastSpell(alice, card, targets: null);
        TestCards.PassUntil(game, () => game.State.Choice is not null);

        var offered = game.State.Choice!.Options.Select(o => o.Label).ToList();

        // A tutor that finds less than the card allows is as wrong as one that finds more, so
        // both named kinds have to be on the list.
        Assert.Contains("Tutored Creature Test", offered);
