    }

    [Fact]
    public void A_compound_filter_offers_either_kind_and_nothing_else()
    {
        var dig = Card(
            "Compound Dig Test",
            "Look at the top three cards of your library. You may reveal a creature or land card "
                + "from among them and put it into your hand. Put the rest on the bottom of your "
                + "library in a random order.");

        var compiled = CardCompiler.Compile(dig);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();

        // Stacked bottom-up: the instant ends on top of the other two.
        game.Create(alice, TestCards.Creature("Compound Creature Test", 2, 2), Zone.Library);
        game.Create(alice, TestCards.BasicLand("Compound Forest Test"), Zone.Library);
        game.Create(alice, Card("Compound Bolt Test", "You gain 1 life."), Zone.Library);

