        game.CastSpell(alice, card, targets: null);
        TestCards.PassUntil(game, () => game.State.Choice is not null);

        var offered = game.State.Choice!.Options.Select(o => o.Label).ToList();

        // Either of the two named kinds, and not the instant that was also seen.
