    [Fact]
    public void A_filtered_look_offers_only_the_cards_the_card_names()
    {
        var dig = Card(
            "Filtered Dig Test",
            "Look at the top three cards of your library. You may reveal a creature card from "
                + "among them and put it into your hand. Put the rest on the bottom of your "
                + "library in a random order.");

        var compiled = CardCompiler.Compile(dig);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();

        // Stacked from the bottom up, so the creature ends up under two lands.
        game.Create(alice, TestCards.Creature("Dug Creature Test", 2, 2), Zone.Library);
        game.Create(alice, TestCards.BasicLand("Dug Forest Test"), Zone.Library);
        game.Create(alice, TestCards.BasicLand("Dug Plains Test"), Zone.Library);

        var card = TestCards.PutInHand(game, alice, dig);
        game.CastSpell(alice, card, targets: null);

        TestCards.PassUntil(game, () => game.State.Choice is not null);
        var choice = game.State.Choice!;
        Assert.Equal(ChoiceKind.LookAndTake, choice.Kind);

        // Three cards were looked at and only the creature may be taken - which is the whole
        // difference between this and the unfiltered dig it is built from.
        Assert.Single(choice.Options);
        Assert.Equal("Dug Creature Test", choice.Options[0].Label);

        game.Choose(alice, [choice.Options[0].Id]);
        Settle(game);

        Assert.Contains(
            game.State.GetPlayer(alice).Hand,
            id => game.State.GetObject(id).Card.Name == "Dug Creature Test");
    }

    /// <summary>
    /// A filtered look with nothing matching is declined without anybody being asked (CR 118.3).
    /// </summary>
    /// <remarks>
    /// It used to be asked, and this test used to assert that it was: the game stopped on a
    /// LookAndTake choice with an empty option list, and the only answer to it was the one the
    /// engine could have given on the player's behalf. That is the zero-card discard's mistake in
    /// a second place - a question with one possible answer is not a question - and a test written
    /// against the behaviour it produced is how it survived. What the card does is unchanged;
    /// what it no longer does is stop the game to say so.
    /// </remarks>
    [Fact]
    public void A_filtered_look_with_nothing_matching_is_declined_without_asking()
    {
        var dig = Card(
            "Declined Dig Test",
            "Look at the top two cards of your library. You may reveal a creature card from "
                + "among them and put it into your hand. Put the rest on the bottom of your "
                + "library in a random order.");

        var (game, alice, _) = InMainPhase();
        game.Create(alice, TestCards.BasicLand("Declined Forest Test"), Zone.Library);
        game.Create(alice, TestCards.BasicLand("Declined Plains Test"), Zone.Library);

        var card = TestCards.PutInHand(game, alice, dig);
        game.CastSpell(alice, card, targets: null);
        Settle(game);

        Assert.DoesNotContain(
            game.Log.OfType<ChoiceRequested>(), e => e.Choice.Kind == ChoiceKind.LookAndTake);

        Assert.DoesNotContain(
            game.State.GetPlayer(alice).Hand,
            id => game.State.GetObject(id).Card.Name.StartsWith("Declined ", StringComparison.Ordinal));

        // "Put the rest on the bottom" still happened, which is the half that would have been
        // lost had the request simply been dropped instead of resolved with no pick.
        var bottom = game.State.GetPlayer(alice).Library
            .TakeLast(2)
            .Select(id => game.State.GetObject(id).Card.Name)
            .ToHashSet(StringComparer.Ordinal);

        Assert.Equal(
            new HashSet<string>(StringComparer.Ordinal)
            {
                "Declined Forest Test",
                "Declined Plains Test",
            },
            bottom);
    }

    // ---- Mana abilities with a cost that is not mana (CR 605.1a) -------------

    [Fact]
    public void A_mana_ability_can_cost_a_counter()
    {
        var land = Card(
            "Charge Land Test",
            "{T}, Remove a charge counter from Charge Land Test: Add one mana of any color.",
            CardType.Land);

        var compiled = CardCompiler.Compile(land);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        // One ability per colour, because which colour is a choice and a mana ability has no
        // resolution to make one in (CR 605.3b).
        Assert.Equal(5, compiled.Activated.Count);
        Assert.All(compiled.Activated, a => Assert.Equal(("charge", 1), a.CounterCost));

        var (game, alice, _) = InMainPhase();
        var permanent = game.Create(alice, land, Zone.Battlefield);
        game.ChangeCounters(permanent, "charge", 1);

        game.ActivateAbility(alice, permanent, compiled.Activated[0].Id);
        Settle(game);

        // Spent, and the pool drops the kind entirely rather than keeping a zero.
        Assert.False(
            game.State.GetObject(permanent).Permanent!.Counters.ContainsKey("charge"));
        Assert.Equal(1, game.State.GetPlayer(alice).ManaPool.Total);

        // And with no counter left there is nothing to pay with.
        Assert.Throws<InvalidOperationException>(
            () => game.ActivateAbility(alice, permanent, compiled.Activated[0].Id));
    }

    [Fact]
    public void A_mana_ability_can_cost_tapping_another_creature()
    {
        var dryad = Card(
            "Loam Dryad Test",
            "{T}, Tap an untapped creature you control: Add one mana of any color.",
            CardType.Creature, 0, 1);

        var compiled = CardCompiler.Compile(dryad);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.All(compiled.Activated, a => Assert.Single(a.ChosenCosts));

        var (game, alice, _) = InMainPhase();
        var source = game.Create(alice, dryad, Zone.Battlefield);
