    }

    // ---- Banding (CR 702.22) -------------------------------------------------

    [Fact]
    public void A_creature_blocked_by_banding_has_its_damage_divided_by_the_defender()
    {
        var wall = Card("Banding Wall Test", "Banding", CardType.Creature, 0, 4);

        var compiled = CardCompiler.Compile(wall);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.True(compiled.GrantedKeywords.HasFlag(KeywordAbility.Banding));

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, TestCards.Creature("Banded Attacker Test", 3, 3), Zone.Battlefield);
        var banded = game.Create(bob, wall, Zone.Battlefield);
        var plain = game.Create(bob, TestCards.Creature("Plain Blocker Test", 0, 4), Zone.Battlefield);

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);
        game.DeclareBlockers(bob, new Dictionary<ObjectId, IReadOnlyList<ObjectId>>
        {
            [attacker] = [banded, plain],
        });

        TestCards.PassUntil(game, () => game.State.Choice is not null);
        var choice = game.State.Choice!;
        Assert.Equal(ChoiceKind.DivideCombatDamage, choice.Kind);

        // CR 702.22j: the one exception to CR 510.1c. Alice attacked, and Bob divides - which is
        // the whole point of blocking with a creature that has banding.
        Assert.Equal(bob, choice.PlayerId);

        // And Bob may put it all on the creature that can take it.
        game.Choose(bob, [
            plain.Value.ToString("N"),
            plain.Value.ToString("N"),
            plain.Value.ToString("N"),
        ]);
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);

        Assert.Equal(3, game.State.GetObject(plain).Permanent!.DamageMarked);
        Assert.Equal(0, game.State.GetObject(banded).Permanent!.DamageMarked);
    }

    [Fact]
    public void Without_banding_the_attacker_still_divides()
    {
        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, TestCards.Creature("Unbanded Attacker Test", 3, 3), Zone.Battlefield);
        var first = game.Create(bob, TestCards.Creature("First Wall Test", 0, 4), Zone.Battlefield);
        var second = game.Create(bob, TestCards.Creature("Second Wall Test", 0, 4), Zone.Battlefield);

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);
        game.DeclareBlockers(bob, new Dictionary<ObjectId, IReadOnlyList<ObjectId>>
        {
            [attacker] = [first, second],
        });

        TestCards.PassUntil(game, () => game.State.Choice is not null);

        // The ordinary rule, so that the test above is about banding and not about two blockers.
        Assert.Equal(alice, game.State.Choice!.PlayerId);
    }

    // ---- Recover (CR 702.59) -------------------------------------------------

    [Fact]
    public void Recover_offers_the_card_back_when_a_creature_dies_and_exiles_it_if_declined()
    {
        var card = Card("Recover Test", "You gain 2 life.\nRecover {0}");

        var compiled = CardCompiler.Compile(card);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        game.Create(alice, card, Zone.Graveyard);
        var doomed = game.Create(alice, TestCards.Creature("Recover Fodder Test", 1, 1), Zone.Battlefield);

        // The creature dies, which is the only thing recover watches.
        game.Move(doomed, Zone.Graveyard, MoveCause.Destroy);
        TestCards.PassUntil(game, () => game.State.Choice is not null);

        var choice = game.State.Choice!;
        Assert.Equal(alice, choice.PlayerId);

        var decline = choice.Options.Single(o => o.Label.Contains("exiled", StringComparison.Ordinal));
        game.Choose(alice, [decline.Id]);
        Settle(game);

        // Declining is not free: the card leaves the graveyard for exile, so it cannot be
        // offered again the next time something dies.
        Assert.DoesNotContain(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Recover Test");
        Assert.Contains(
            game.State.Exile, id => game.State.GetObject(id).Card.Name == "Recover Test");
    }

    [Fact]
    public void Recover_returns_the_card_to_hand_when_the_cost_is_paid()
    {
        var card = Card("Recover Paid Test", "You gain 2 life.\nRecover {0}");

        var (game, alice, _) = InMainPhase();
        game.Create(alice, card, Zone.Graveyard);
        var doomed = game.Create(alice, TestCards.Creature("Paid Fodder Test", 1, 1), Zone.Battlefield);

        game.Move(doomed, Zone.Graveyard, MoveCause.Destroy);
        TestCards.PassUntil(game, () => game.State.Choice is not null);

        var pay = game.State.Choice!.Options.Single(
            o => o.Label.Contains("take it back", StringComparison.Ordinal));
        game.Choose(alice, [pay.Id]);
        Settle(game);

        Assert.Contains(
            game.State.GetPlayer(alice).Hand,
            id => game.State.GetObject(id).Card.Name == "Recover Paid Test");
    }

    // ---- Afflict and dethrone (CR 702.130, 702.105) --------------------------

    [Fact]
    public void Afflict_costs_the_defender_life_for_blocking()
    {
        var creature = Card("Afflict Test", "Afflict 3", CardType.Creature, 2, 2);

        var compiled = CardCompiler.Compile(creature);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, creature, Zone.Battlefield);
        var blocker = game.Create(bob, TestCards.Creature("Afflicted Blocker Test", 3, 3), Zone.Battlefield);

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);
        game.DeclareBlockers(bob, new Dictionary<ObjectId, IReadOnlyList<ObjectId>>
        {
            [attacker] = [blocker],
        });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);

        // Three from afflict and nothing from combat, since a blocked creature deals its damage
        // to the blocker - which is why afflict is worth printing at all.
        Assert.Equal(17, game.State.GetPlayer(bob).Life);
    }

    [Fact]
    public void Dethrone_grows_only_when_the_defender_is_ahead()
    {
        var creature = Card("Dethrone Test", "Dethrone", CardType.Creature, 2, 2);

        var compiled = CardCompiler.Compile(creature);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, creature, Zone.Battlefield);

        // Both on 20, so the defender is tied for most life - which the rule counts.
        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });
        Settle(game);

        Assert.Equal(
            1, game.State.GetObject(attacker).Permanent!.Counters[CounterKinds.PlusOnePlusOne]);

        // Bob is now behind, having taken the hit, so the next attack earns nothing.
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Assert.True(game.State.GetPlayer(bob).Life < game.State.GetPlayer(alice).Life);

        PassTo(game, 5, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });
        Settle(game);

        Assert.Equal(
            1, game.State.GetObject(attacker).Permanent!.Counters[CounterKinds.PlusOnePlusOne]);
    }

    // ---- Jump-start (CR 702.132) ---------------------------------------------

    [Fact]
    public void Jump_start_casts_from_the_graveyard_for_a_discard_and_then_exiles()
    {
        var spell = Card("Jump Start Test", "You gain 3 life.\nJump-start");

        var compiled = CardCompiler.Compile(spell);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var card = game.Create(alice, spell, Zone.Graveyard);
        var fuel = TestCards.PutInHand(game, alice, TestCards.BasicLand("Forest"));

        // Its own mana cost, not a stated one - which is what separates jump-start from
        // flashback, and the reason a card with no printed cost is free here.
        game.CastSpell(alice, card, targets: null, costPayment: [fuel]);
        Settle(game);

        Assert.Equal(23, game.State.GetPlayer(alice).Life);
        Assert.Contains(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Forest");

        // Exiled rather than returned, so it cannot be jump-started a second time.
        Assert.DoesNotContain(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Jump Start Test");
        Assert.Contains(
            game.State.Exile, id => game.State.GetObject(id).Card.Name == "Jump Start Test");
    }

    // ---- Modes as a range, entwine and escalate (CR 700.2d, 702.42, 702.101) --

    [Fact]
    public void Choose_one_or_both_lets_both_be_taken()
    {
        var charm = Card(
            "Or Both Test",
            "Choose one or both —\n• You gain 3 life.\n• You draw a card.");

        var compiled = CardCompiler.Compile(charm);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.Equal(1, compiled.Spell!.ModesToChoose);
        Assert.Equal(2, compiled.Spell.ModesMax);

        var (game, alice, _) = InMainPhase();
        for (var i = 0; i < 6; i++)
        {
            var land = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
            game.ActivateAbility(alice, land, "mana");
        }
        var hand = game.State.GetPlayer(alice).Hand.Count;

        var card = TestCards.PutInHand(game, alice, charm);
        game.CastSpell(alice, card, targets: null, modes: [0, 1]);
        Settle(game);

        // Both modes, from one cast and for no extra cost - which is what the card says and what
        // the engine flatly refused while the header was read as a single number.
        Assert.Equal(23, game.State.GetPlayer(alice).Life);

        // The card left the hand to be cast and the second mode put one back, so the count is one
        // above where it started rather than back where it was.
        Assert.Equal(hand + 1, game.State.GetPlayer(alice).Hand.Count);
    }

    [Fact]
    public void Entwine_takes_every_mode_for_a_price()
    {
        var charm = Card(
            "Entwine Test",
            "Choose one —\n• You gain 3 life.\n• You draw a card."
            + "\nEntwine {2}");

        var compiled = CardCompiler.Compile(charm);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.NotNull(compiled.Spell!.EntwineCost);

        var (game, alice, _) = InMainPhase();
        for (var i = 0; i < 2; i++)
        {
            var land = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
            game.ActivateAbility(alice, land, "mana");
        }

        var card = TestCards.PutInHand(game, alice, charm);

        // Entwine is all or nothing: it is not a wider range, so one mode with the cost paid is
        // as illegal as both without it.
        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, card, targets: null, modes: [0], entwined: true));

        game.CastSpell(alice, card, targets: null, modes: [0, 1], entwined: true);
        Settle(game);

        Assert.Equal(23, game.State.GetPlayer(alice).Life);
        Assert.True(game.State.GetPlayer(alice).ManaPool.IsEmpty);
    }

    [Fact]
    public void Escalate_charges_again_for_every_mode_past_the_first()
    {
        var charm = Card(
            "Escalate Test",
            "Choose one or more —\n• You gain 3 life.\n• You gain 5 life."
            + "\nEscalate {2}");

        var compiled = CardCompiler.Compile(charm);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.Equal(1, compiled.Spell!.ModesToChoose);
        Assert.Equal(2, compiled.Spell.ModesMax);

        var (game, alice, _) = InMainPhase();
        for (var i = 0; i < 1; i++)
        {
            var land = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
            game.ActivateAbility(alice, land, "mana");
        }

        var card = TestCards.PutInHand(game, alice, charm);

        // One mana in the pool buys one mode. The second costs {2} more, and the spell is refused
        // rather than cast for what is printed on it.
        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, card, targets: null, modes: [0, 1]));

        game.CastSpell(alice, card, targets: null, modes: [1]);
        Settle(game);

        Assert.Equal(25, game.State.GetPlayer(alice).Life);
    }

    // ---- Blocking (CR 509.1) -------------------------------------------------

    [Fact]
    public void A_creature_that_blocks_an_additional_creature_blocks_two_attackers()
    {
        var wall = Card(
            "Extra Block Test",
            "This creature can block an additional creature each combat.",
            CardType.Creature, 1, 6);

        var compiled = CardCompiler.Compile(wall);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var first = game.Create(alice, TestCards.Creature("First Raider Test", 2, 2), Zone.Battlefield);
        var second = game.Create(alice, TestCards.Creature("Second Raider Test", 2, 2), Zone.Battlefield);
        var blocker = game.Create(bob, wall, Zone.Battlefield);

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(alice, new Dictionary<ObjectId, AttackTarget>
        {
            [first] = AttackTarget.Player(bob),
            [second] = AttackTarget.Player(bob),
        });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);
        game.DeclareBlockers(bob, new Dictionary<ObjectId, IReadOnlyList<ObjectId>>
        {
            [first] = [blocker],
            [second] = [blocker],
        });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);

        // Nothing got through, and it took both attackers' damage - which is what blocking two
        // costs, and the reason the limit exists to be lifted.
        Assert.Equal(20, game.State.GetPlayer(bob).Life);
        Assert.Equal(4, game.State.GetObject(blocker).Permanent!.DamageMarked);
    }

    [Fact]
    public void Creatures_too_small_cannot_block_it()
    {
        var bully = Card(
            "Big Bully Test",
            "Creatures with power less than Big Bully Test's power can't block it.",
            CardType.Creature, 4, 4);

        var compiled = CardCompiler.Compile(bully);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, bully, Zone.Battlefield);
        var small = game.Create(bob, TestCards.Creature("Small Blocker Test", 2, 2), Zone.Battlefield);
        var equal = game.Create(bob, TestCards.Creature("Equal Blocker Test", 4, 4), Zone.Battlefield);

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);

        var refused = Assert.Throws<InvalidOperationException>(
            () => game.DeclareBlockers(bob, new Dictionary<ObjectId, IReadOnlyList<ObjectId>>
            {
                [attacker] = [small],
            }));
        Assert.Contains("509.1b", refused.Message, StringComparison.Ordinal);

        // "Less than", not "less than or equal to": a creature of the same power may block.
        game.DeclareBlockers(bob, new Dictionary<ObjectId, IReadOnlyList<ObjectId>>
        {
            [attacker] = [equal],
        });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Assert.Equal(20, game.State.GetPlayer(bob).Life);
    }

    [Fact]
    public void A_lure_compels_every_creature_that_could_block_it()
    {
        var lure = Card(
            "Lure Test",
            "All creatures able to block Lure Test do so.",
            CardType.Creature, 1, 1);

        var compiled = CardCompiler.Compile(lure);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, lure, Zone.Battlefield);
        var other = game.Create(alice, TestCards.Creature("Ignored Raider Test", 3, 3), Zone.Battlefield);
        var willing = game.Create(bob, TestCards.Creature("Willing Blocker Test", 1, 1), Zone.Battlefield);
        var reluctant = game.Create(bob, TestCards.Creature("Reluctant Blocker Test", 1, 1), Zone.Battlefield);

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(alice, new Dictionary<ObjectId, AttackTarget>
        {
            [attacker] = AttackTarget.Player(bob),
            [other] = AttackTarget.Player(bob),
        });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);

        // Blocking nothing is not an option while a lure is attacking.
        var none = Assert.Throws<InvalidOperationException>(
            () => game.DeclareBlockers(bob, ImmutableDictionary<ObjectId, IReadOnlyList<ObjectId>>.Empty));
        Assert.Contains("509.1c", none.Message, StringComparison.Ordinal);

        // Nor is sending one of them at the other attacker instead - which is the whole point of
        // the card, and the case a "must block" flag checked per attacker would have missed.
        var elsewhere = Assert.Throws<InvalidOperationException>(
            () => game.DeclareBlockers(bob, new Dictionary<ObjectId, IReadOnlyList<ObjectId>>
            {
                [attacker] = [willing],
                [other] = [reluctant],
            }));
        Assert.Contains("509.1c", elsewhere.Message, StringComparison.Ordinal);

        game.DeclareBlockers(bob, new Dictionary<ObjectId, IReadOnlyList<ObjectId>>
        {
            [attacker] = [willing, reluctant],
        });

        // Two creatures blocking one attacker means its controller divides the damage (CR 510.1c).
        TestCards.PassUntil(game, () => game.State.Choice is not null);
        game.Choose(alice, [willing.Value.ToString("N")]);

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);

        // Both were dragged onto the 1/1, so the 3/3 that was not a lure got through unblocked.
        Assert.Equal(17, game.State.GetPlayer(bob).Life);
    }

    [Fact]
    public void A_lure_with_menace_cannot_compel_a_lone_blocker()
    {
        // CR 509.1c against CR 702.111b. A requirement is obeyed only as far as it can be without
        // violating a restriction. A single creature is "able to block" a menace attacker in every
        // sense but the one that counts - it cannot be the only one - so with one creature to hand
        // the lure compels nothing. Flying is the easy version of this and already has a test: the
        // creature plainly cannot block at all. Menace is the version that needs the count, and
        // deleting the check breaks no other test, because everywhere else the set check refuses
        // the illegal declaration afterwards. Here there is no legal declaration to refuse - the
        // engine would demand a block that it would then reject, and the game would stop.
        var lure = Card(
            "Menacing Lure Test",
            "Menace\nAll creatures able to block Menacing Lure Test do so.",
            CardType.Creature, 3, 3, KeywordAbility.Menace);

        var compiled = CardCompiler.Compile(lure);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, lure, Zone.Battlefield);
        var lone = game.Create(bob, TestCards.Creature("Lone Blocker Test", 1, 1), Zone.Battlefield);

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(alice, new Dictionary<ObjectId, AttackTarget>
        {
            [attacker] = AttackTarget.Player(bob),
        });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);

        // Blocking alone is still illegal, lure or no lure.
        var alone = Assert.Throws<InvalidOperationException>(
            () => game.DeclareBlockers(bob, new Dictionary<ObjectId, IReadOnlyList<ObjectId>>
            {
                [attacker] = [lone],
            }));
        Assert.Contains("702.111b", alone.Message, StringComparison.Ordinal);

        // And so blocking with nothing is what the rules leave, rather than a refusal.
        game.DeclareBlockers(bob, ImmutableDictionary<ObjectId, IReadOnlyList<ObjectId>>.Empty);

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Assert.Equal(17, game.State.GetPlayer(bob).Life);
    }

    [Fact]
    public void A_creature_that_cannot_block_the_lure_is_not_compelled()
    {
        var lure = Card(
            "Flying Lure Test",
            "Flying\nAll creatures able to block Flying Lure Test do so.",
            CardType.Creature, 1, 1, KeywordAbility.Flying);

        var compiled = CardCompiler.Compile(lure);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, lure, Zone.Battlefield);
        var grounded = game.Create(bob, TestCards.Creature("Grounded Test", 2, 2), Zone.Battlefield);

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);

        // "Able to block" is the condition, and a creature without flying or reach is not able -
        // so declaring no blocks is legal and the requirement has nothing to say.
        game.DeclareBlockers(bob, ImmutableDictionary<ObjectId, IReadOnlyList<ObjectId>>.Empty);
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);

        Assert.Equal(19, game.State.GetPlayer(bob).Life);
        Assert.Equal(0, game.State.GetObject(grounded).Permanent!.DamageMarked);
    }

    // ---- For Mirrodin! (CR 702.161) ------------------------------------------

    [Fact]
    public void For_Mirrodin_brings_a_rebel_and_attaches_the_equipment_to_it()
    {
        var sword = Card(
            "Mirrodin Sword Test",
            "For Mirrodin!\nEquipped creature gets +1/+1.",
            CardType.Artifact, null, null, KeywordAbility.None, "Equipment");

        var compiled = CardCompiler.Compile(sword);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        game.Create(alice, sword, Zone.Battlefield);
        Settle(game);

        var rebel = game.State.Battlefield.Single(
            id => game.State.GetObject(id).Card.Name == "Rebel");
        var equipment = game.State.Battlefield.Single(
            id => game.State.GetObject(id).Card.Name == "Mirrodin Sword Test");

        // A 2/2 red Rebel, not living weapon's 0/0 Germ - which is the whole difference between
        // an Equipment that needs help and one that does not.
        var computed = Characteristics.Of(game.State, Pool, game.State.GetObject(rebel));
        Assert.Equal(3, computed.Power);
        Assert.Contains(ManaColor.Red, computed.Colors);

        Assert.Equal(rebel, game.State.GetObject(equipment).Permanent?.AttachedTo);
    }

    // ---- Casualty (CR 702.153) -----------------------------------------------

    [Fact]
    public void Casualty_sacrifices_a_big_enough_creature_and_copies_the_spell()
    {
        var bolt = Card("Casualty Bolt Test", "You gain 2 life.\nCasualty 2");

        var compiled = CardCompiler.Compile(bolt);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.NotNull(compiled.Spell!.CopyingCost);

        var (game, alice, _) = InMainPhase();

        var small = game.Create(alice, TestCards.Creature("Too Small Test", 1, 1), Zone.Battlefield);
        var big = game.Create(alice, TestCards.Creature("Big Enough Test", 2, 2), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, bolt);

        // "Power 2 or greater" is the price, and a 1/1 does not pay it.
        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(
                alice, card, targets: null, costPayment: [small], conspired: true));

        game.CastSpell(alice, card, targets: null, costPayment: [big], conspired: true);
        Settle(game);

        // Two resolutions - the spell and its copy - so four life.
        Assert.Equal(24, game.State.GetPlayer(alice).Life);

        // And the creature was sacrificed rather than tapped: casualty and conspire share the
        // mechanism but not the price.
        Assert.DoesNotContain(
            game.State.Battlefield, id => game.State.GetObject(id).Card.Name == "Big Enough Test");
        Assert.Contains(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Big Enough Test");
    }

    // ---- Embalm and eternalize (CR 702.128, 702.129) -------------------------

    [Fact]
    public void Eternalize_exiles_the_card_and_leaves_a_four_four_black_zombie()
    {
        var priest = new CardDefinition
        {
            OracleId = "oracle-eternalize-priest-test",
            Name = "Eternal Priest Test",
            OracleText = "Eternalize {0}",
            CardTypes = CardType.Creature,
            ManaCostRaw = "{2}{W}",
            ColorIdentity = [ManaColor.White],
            Colors = [ManaColor.White],
            Subtypes = ["Cleric"],
            Power = 2,
            Toughness = 1,
        };

        var compiled = CardCompiler.Compile(priest);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var buried = game.Create(alice, priest, Zone.Graveyard);

        game.ActivateAbility(alice, buried, "eternalize");
        Settle(game);

        var token = game.State.Battlefield.Single(
            id => game.State.GetObject(id).Card.Name == "Eternal Priest Test");

        var computed = Characteristics.Of(game.State, Pool, game.State.GetObject(token));

        // A 4/4 rather than the printed 2/1, black rather than white, and a Zombie on top of
        // what it already was.
        Assert.Equal(4, computed.Power);
        Assert.Equal(4, computed.Toughness);
        Assert.Contains(ManaColor.Black, computed.Colors);
        Assert.DoesNotContain(ManaColor.White, computed.Colors);
        Assert.True(computed.HasSubtype("Zombie"));
        Assert.True(computed.HasSubtype("Cleric"));

        // And the card paid for it out of the graveyard.
        Assert.Contains(
            game.State.Exile, id => game.State.GetObject(id).Card.Name == "Eternal Priest Test");
    }

