    // ---- Mentor (CR 702.134) -------------------------------------------------

    [Fact]
    public void Mentor_can_only_pick_an_attacker_smaller_than_itself()
    {
        var mentor = Card("Mentor Test", "Mentor", CardType.Creature, 3, 3);

        var compiled = CardCompiler.Compile(mentor);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var teacher = game.Create(alice, mentor, Zone.Battlefield);
        var student = game.Create(alice, TestCards.Creature("Small Student Test", 1, 1), Zone.Battlefield);
        var equal = game.Create(alice, TestCards.Creature("Equal Peer Test", 3, 3), Zone.Battlefield);

        TestCards.PassToTurn(game, 3);
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget>
            {
                [teacher] = AttackTarget.Player(bob),
                [student] = AttackTarget.Player(bob),
                [equal] = AttackTarget.Player(bob),
            });

        for (var guard = 0; guard < 40 && game.State.Choice is null; guard++)
        {
            if (game.State.Priority.Holder is { } holder)
                game.PassPriority(holder);
            else
                break;
        }

        var choice = game.State.Choice;
        Assert.NotNull(choice);

        var offered = choice!.Options.Select(o => o.Label).ToList();

        // Only the smaller attacker. The equal one is out because "lesser" is not "at most", and
        // the mentor is out for the same reason - nothing has power less than its own.
        Assert.Contains(offered, label => label.Contains("Small Student", StringComparison.Ordinal));
        Assert.DoesNotContain(offered, label => label.Contains("Equal Peer", StringComparison.Ordinal));
        Assert.DoesNotContain(offered, label => label.Contains("Mentor Test", StringComparison.Ordinal));

        game.Choose(choice.PlayerId, [choice.Options[0].Id]);
        Settle(game);

        Assert.Equal(
            1, game.State.GetObject(student).Permanent?.Counters.GetValueOrDefault("+1/+1", 0));
    }

    // ---- Battle cry (CR 702.90) ----------------------------------------------

    [Fact]
    public void Battle_cry_pumps_the_other_attackers_and_not_the_crier()
    {
        var crier = Card("Battle Crier Test", "Battle cry", CardType.Creature, 1, 1);

        var compiled = CardCompiler.Compile(crier);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var shouter = game.Create(alice, crier, Zone.Battlefield);
        var friend = game.Create(alice, TestCards.Creature("Cried Friend Test", 2, 2), Zone.Battlefield);
        var sitter = game.Create(alice, TestCards.Creature("Stay Home Test", 2, 2), Zone.Battlefield);

        TestCards.PassToTurn(game, 3);
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget>
            {
                [shouter] = AttackTarget.Player(bob),
                [friend] = AttackTarget.Player(bob),
            });

        Settle(game);

        // The other attacker is bigger; the crier is not, and neither is the creature that
        // stayed home. "Each other attacking creature" excludes on both counts.
        Assert.Equal(3, Characteristics.Of(game.State, Pool, game.State.GetObject(friend)).Power);
        Assert.Equal(1, Characteristics.Of(game.State, Pool, game.State.GetObject(shouter)).Power);
        Assert.Equal(2, Characteristics.Of(game.State, Pool, game.State.GetObject(sitter)).Power);
    }

    // ---- Paying from the graveyard -------------------------------------------

    [Fact]
    public void An_additional_cost_can_exile_a_card_from_your_own_graveyard()
    {
        var spell = Card(
            "Graveyard Fuel Test",
            "As an additional cost to cast ~, exile a creature card from your graveyard.\n"
                + "You gain 3 life.");

        var compiled = CardCompiler.Compile(spell);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();

        var fuel = game.Create(alice, TestCards.Creature("Fuel Bear Test", 2, 2), Zone.Graveyard);
        var wrongType = game.Create(
            alice, Card("Fuel Instant Test", "Draw a card."), Zone.Graveyard);
        var wrongPlayer = game.Create(
            bob, TestCards.Creature("Their Fuel Test", 2, 2), Zone.Graveyard);

        var card = TestCards.PutInHand(game, alice, spell);

        // Not any card - the cost says a creature card.
        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, card, targets: null, costPayment: [wrongType]));

        // And not out of somebody else's graveyard.
        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, card, targets: null, costPayment: [wrongPlayer]));

        game.CastSpell(alice, card, targets: null, costPayment: [fuel]);
        Settle(game);

        Assert.Equal(23, game.State.GetPlayer(alice).Life);

        // Paid, not merely named: the card is out of the graveyard and in exile.
        Assert.DoesNotContain(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Fuel Bear Test");
        Assert.Contains(
            game.State.Exile,
            id => game.State.GetObject(id).Card.Name == "Fuel Bear Test");
    }

    // ---- Missing an untap step -----------------------------------------------

    [Fact]
    public void A_creature_told_to_skip_its_untap_step_misses_exactly_one()
    {
        var binder = Card(
            "Frost Binder Test",
            "When ~ enters, tap target creature an opponent controls. "
                + "That creature doesn't untap during its controller's next untap step.",
            CardType.Creature, 2, 2);

        var compiled = CardCompiler.Compile(binder);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var theirs = game.Create(bob, TestCards.Creature("Frozen Bear Test", 2, 2), Zone.Battlefield);

        game.Create(alice, binder, Zone.Battlefield);
        Settle(game);

        Assert.True(game.State.GetObject(theirs).Permanent?.IsTapped);
        Assert.True(game.State.GetObject(theirs).Permanent?.SkipsNextUntap);

        // Bob's untap step comes and goes without it.
        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber == 2 && game.State.CurrentStep == TurnStep.PrecombatMain);

        Assert.True(game.State.GetObject(theirs).Permanent?.IsTapped);

        // Exactly one: the flag is spent by being honoured, so the turn after that it untaps.
        Assert.False(game.State.GetObject(theirs).Permanent?.SkipsNextUntap);

        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber == 4 && game.State.CurrentStep == TurnStep.PrecombatMain);

        Assert.False(game.State.GetObject(theirs).Permanent?.IsTapped);
    }

    [Fact]
    public void A_plural_freeze_holds_every_creature_it_named()
    {
        var snowDay = Card(
            "Snow Day Test",
            "Tap up to two target creatures. Those creatures don't untap during "
                + "their controller's next untap step.",
            CardType.Instant);

        var compiled = CardCompiler.Compile(snowDay);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var first = game.Create(bob, TestCards.Creature("Frozen One Test", 2, 2), Zone.Battlefield);
        var second = game.Create(bob, TestCards.Creature("Frozen Two Test", 2, 2), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, snowDay);
        game.CastSpell(alice, card, [Target.ToPermanent(first), Target.ToPermanent(second)]);
        Settle(game);

        // Both, not just the last one named - which is what freezing by the last target index
        // alone would have produced, and it would have looked entirely correct on one creature.
        Assert.True(game.State.GetObject(first).Permanent?.SkipsNextUntap);
        Assert.True(game.State.GetObject(second).Permanent?.SkipsNextUntap);

        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber == 2 && game.State.CurrentStep == TurnStep.PrecombatMain);

        Assert.True(game.State.GetObject(first).Permanent?.IsTapped);
        Assert.True(game.State.GetObject(second).Permanent?.IsTapped);
    }

    // ---- Ingest (CR 702.114) -------------------------------------------------

    [Fact]
    public void Ingest_exiles_from_the_player_it_hit_and_not_from_you()
    {
        var eldrazi = Card("Ingest Drone Test", "Ingest", CardType.Creature, 1, 1);

        var compiled = CardCompiler.Compile(eldrazi);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, eldrazi, Zone.Battlefield);

        TestCards.PassToTurn(game, 3);
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);

        // Counted here rather than at the start: both players draw on the way to turn three, and
        // a baseline taken before that would blame the draws on the ingest.
        var mine = game.State.GetPlayer(alice).Library.Count;
        var theirs = game.State.GetPlayer(bob).Library.Count;

        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);
        game.DeclareBlockers(bob, new Dictionary<ObjectId, IReadOnlyList<ObjectId>>());
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Settle(game);

        // "That player" is the one the damage was dealt to. Exiling from the controller's own
        // library instead would be the opposite card, and both counts are checked for that.
        Assert.Equal(theirs - 1, game.State.GetPlayer(bob).Library.Count);
        Assert.Equal(mine, game.State.GetPlayer(alice).Library.Count);

        Assert.NotEmpty(game.State.Exile);
    }

    [Fact]
    public void A_graveyard_target_can_name_two_types_and_accept_either()
    {
        var recall = Card(
            "Recall Either Test",
            "When ~ enters, return target instant or sorcery card from your graveyard to your hand.",
            CardType.Creature, 2, 2);

        var compiled = CardCompiler.Compile(recall);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();

        var instant = game.Create(
            alice, Card("Buried Instant Two Test", "Draw a card."), Zone.Graveyard);
        game.Create(
            alice,
            Card("Buried Creature Two Test", string.Empty, CardType.Creature, 2, 2),
            Zone.Graveyard);

        game.Create(alice, recall, Zone.Battlefield);

        for (var guard = 0; guard < 40 && game.State.Choice is null; guard++)
        {
            if (game.State.Priority.Holder is { } holder)
                game.PassPriority(holder);
            else
                break;
        }

        var choice = game.State.Choice;
        Assert.NotNull(choice);

        var offered = choice!.Options.Select(o => o.Label).ToList();

        // Either type is acceptable and nothing else is - the two sides are alternatives, not
        // the intersection that a list of required types means everywhere else.
        Assert.Contains(offered, label => label.Contains("Buried Instant Two", StringComparison.Ordinal));
        Assert.DoesNotContain(
            offered, label => label.Contains("Buried Creature Two", StringComparison.Ordinal));

        game.Choose(choice.PlayerId, [choice.Options[0].Id]);
        Settle(game);

        Assert.Contains(
            game.State.GetPlayer(alice).Hand,
            id => game.State.GetObject(id).Card.Name == "Buried Instant Two Test");

        Assert.NotEqual(default, instant);
    }

    // ---- Offspring (CR 702.171) ----------------------------------------------

    [Fact]
    public void Offspring_paid_for_brings_a_one_one_copy_and_unpaid_brings_nothing()
    {
        var beast = new CardDefinition
        {
            OracleId = "oracle-offspring-beast-test",
            Name = "Offspring Beast Test",
            OracleText = "Offspring {0}",
            CardTypes = CardType.Creature,
            ManaCostRaw = "{0}",
            Power = 4,
            Toughness = 4,
        };

        var compiled = CardCompiler.Compile(beast);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();

        // Cast without paying: one creature, its printed size.
        game.CastSpell(alice, TestCards.PutInHand(game, alice, beast), targets: null);
        Settle(game);

        Assert.Single(
            game.State.Battlefield,
            id => game.State.GetObject(id).Card.Name == "Offspring Beast Test");

        TestCards.PassUntil(game, () => game.State.Priority.Holder == alice);

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, beast), targets: null, offspring: true);
        Settle(game);

        var copies = game.State.Battlefield
            .Select(id => game.State.GetObject(id))
            .Where(o => o.Card.Name == "Offspring Beast Test")
            .ToList();

        Assert.Equal(3, copies.Count);

        // The copy is a 1/1 token, not another 4/4: the size is the whole point of the cost.
        var token = copies.Single(o => o.Card.CardTypes.HasFlag(CardType.Token));
        Assert.Equal(1, Characteristics.Of(game.State, Pool, token).Power);
        Assert.Equal(1, Characteristics.Of(game.State, Pool, token).Toughness);

        Assert.Equal(2, copies.Count(o => !o.Card.CardTypes.HasFlag(CardType.Token)));
    }

    // ---- Replicate (CR 702.55) -----------------------------------------------

    [Fact]
    public void Replicate_makes_one_copy_per_payment_and_charges_for_each()
    {
        var bolt = new CardDefinition
        {
            OracleId = "oracle-replicate-bolt-test",
            Name = "Replicate Bolt Test",
            OracleText = "You gain 2 life.\nReplicate {1}",
            CardTypes = CardType.Sorcery,
            ManaCostRaw = "{0}",
        };

        var compiled = CardCompiler.Compile(bolt);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();

        foreach (var name in new[] { "Forest", "Plains" })
        {
            var land = game.Create(alice, TestCards.BasicLand(name), Zone.Battlefield);
            game.ActivateAbility(alice, land, "mana");
        }

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, bolt), targets: null, replicated: 2);
        Settle(game);

        // Three resolutions - the original and two copies - so six life.
        Assert.Equal(26, game.State.GetPlayer(alice).Life);

        // And it was paid for: two lands' worth of mana is gone.
        Assert.True(game.State.GetPlayer(alice).ManaPool.IsEmpty);
    }

    [Fact]
    public void Replicating_more_times_than_you_can_pay_for_is_refused()
    {
        // The number is the caster's to choose, and each choice costs. A replicate that copied
        // without charging would be an arbitrary number of free spells.
        var bolt = new CardDefinition
        {
            OracleId = "oracle-replicate-greed-test",
            Name = "Replicate Greed Test",
            OracleText = "You gain 2 life.\nReplicate {1}",
            CardTypes = CardType.Sorcery,
            ManaCostRaw = "{0}",
        };

        var (game, alice, _) = InMainPhase();

        var land = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");

        var card = TestCards.PutInHand(game, alice, bolt);

        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, card, targets: null, replicated: 3));

        // One payment is affordable, and still gets a copy.
        game.CastSpell(alice, card, targets: null, replicated: 1);
        Settle(game);

        Assert.Equal(24, game.State.GetPlayer(alice).Life);
    }

    // ---- Plot (CR 702.169) ---------------------------------------------------

    [Fact]
    public void A_plotted_card_waits_a_turn_and_then_costs_nothing()
    {
        var scheme = new CardDefinition
        {
            OracleId = "oracle-plot-scheme-test",
            Name = "Plot Scheme Test",
            OracleText = "Plot {0}\nYou gain 5 life.",
            CardTypes = CardType.Sorcery,
            ManaCostRaw = "{9}",
            Cmc = 9,
        };

        var compiled = CardCompiler.Compile(scheme);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, scheme);

        game.Plot(alice, card);

        var waiting = game.State.Exile.Single(
            id => game.State.GetObject(id).Card.Name == "Plot Scheme Test");

        // Not this turn: "on a later turn" is the price of the discount.
        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, waiting, targets: null));

        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber == 3
                && game.State.CurrentStep == TurnStep.PrecombatMain
                && game.State.Priority.Holder == alice
                && game.State.Stack.IsEmpty);

        // Cast from exile against a printed {9}, with no mana at all.
        Assert.True(game.State.GetPlayer(alice).ManaPool.IsEmpty);
        game.CastSpell(alice, waiting, targets: null);
        Settle(game);

        Assert.Equal(25, game.State.GetPlayer(alice).Life);
    }

