    [Fact]
    public void An_aura_that_says_you_control_enchanted_creature_takes_it()
    {
        var mindControl = Card(
            "Spirit Away Test",
            "Enchant creature\nYou control enchanted creature.",
            CardType.Enchantment, null, null, KeywordAbility.None, "Aura");

        var compiled = CardCompiler.Compile(mindControl);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var theirs = game.Create(bob, TestCards.Creature("Stolen Bear Test", 2, 2), Zone.Battlefield);

