    }

    [Fact]
    public void Up_to_two_means_one_is_enough()
    {
        // The half that was wrong before any of this: the engine demanded a target for every
        // spec it had, so "up to two" meant "exactly two" and a card with one legal target could
        // not be cast at all.
        var spell = Card(
            "Half Plunder Test",
