        game.ActivateAbility(alice, land, "mana");

        game.CastSpell(alice, card, [Target.ToCard(only)]);
        Settle(game);

        Assert.Contains(
            game.State.GetPlayer(alice).Hand,
            id => game.State.GetObject(id).Card.Name == "Lonely Buried Test");
    }

    // ---- Enters with X counters (CR 601.2b) ----------------------------------

    [Fact]
    public void A_creature_that_enters_with_X_counters_is_the_size_that_was_paid_for()
    {
        var oracle = new CardDefinition
        {
            OracleId = "oracle-x-counters-test",
            Name = "X Counters Test",
            OracleText = "~ enters with X +1/+1 counters on it.",
            CardTypes = CardType.Creature,
            Power = 0,
            Toughness = 0,
            ManaCostRaw = "{X}{G}",
        };

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, oracle);

        foreach (var _ in Enumerable.Range(0, 4))
        {
            var land = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
            game.ActivateAbility(alice, land, "mana");
        }

        game.CastSpell(alice, card, targets: null, variableValue: 3);
        Settle(game);

        var creature = game.State.Battlefield.Single(
            id => game.State.GetObject(id).Card.Name == "X Counters Test");

        // A printed 0/0 that arrives with no counters dies to state-based actions before anyone
        // sees it, so being on the battlefield at all is half the assertion.
        Assert.Equal(
            3,
            Characteristics.Of(game.State, new CompiledPool(), game.State.GetObject(creature)).Power);
    }

    // ---- Buyback (CR 702.27) -------------------------------------------------

    [Fact]
    public void A_bought_back_spell_resolves_and_returns_to_hand()
    {
        var oracle = Kicked("Buyback Test", "{1}", "Buyback {2}\nYou gain 3 life.");

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, oracle);

        foreach (var _ in Enumerable.Range(0, 3))
        {
            var land = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
            game.ActivateAbility(alice, land, "mana");
        }

        game.CastSpell(
            alice, card, targets: null, variableValue: 0, tapToPay: null, modes: null,
            kicked: false, costPayment: null, faceDown: false, delve: null, buyback: true);

        Settle(game);

        // It did what it says and came back — the whole point of paying the extra.
        Assert.Equal(23, game.State.GetPlayer(alice).Life);
        Assert.Contains(
            game.State.GetPlayer(alice).Hand,
            id => game.State.GetObject(id).Card.Name == "Buyback Test");
        Assert.DoesNotContain(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Buyback Test");
    }

    [Fact]
    public void The_same_spell_without_buyback_goes_to_the_graveyard()
    {
        var oracle = Kicked("No Buyback Test", "{1}", "Buyback {2}\nYou gain 3 life.");

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, oracle);

        // One mana: enough for the printed cost, not for the buyback.
        var land = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");

        game.CastSpell(alice, card, targets: null);
        Settle(game);

        Assert.Equal(23, game.State.GetPlayer(alice).Life);
        Assert.Contains(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "No Buyback Test");
    }

    // ---- Fabricate (CR 702.122) ----------------------------------------------

    private static CardDefinition Fabricator(string name) => new()
    {
        OracleId = "oracle-" + name.ToLowerInvariant().Replace(' ', '-'),
        Name = name,
        OracleText = "Fabricate 2",
        CardTypes = CardType.Creature,
        Power = 2,
        Toughness = 2,
        ManaCostRaw = "{2}",
    };

    [Fact]
    public void Fabricate_takes_the_counters_when_that_is_the_answer()
    {
        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, Fabricator("Counter Fabricator Test"));

        foreach (var _ in Enumerable.Range(0, 2))
        {
            var land = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
            game.ActivateAbility(alice, land, "mana");
        }

        game.CastSpell(alice, card, targets: null);

        // Settle answers with the first option, which is the counters.
        Settle(game);

        var creature = game.State.Battlefield.Single(
            id => game.State.GetObject(id).Card.Name == "Counter Fabricator Test");

        Assert.Equal(
            4,
            Characteristics.Of(game.State, new CompiledPool(), game.State.GetObject(creature)).Power);

        Assert.DoesNotContain(
            game.State.Battlefield, id => game.State.GetObject(id).Card.Name == "Servo");
    }

    [Fact]
    public void Fabricate_makes_servos_when_that_is_the_answer()
    {
        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, Fabricator("Servo Fabricator Test"));

        foreach (var _ in Enumerable.Range(0, 2))
        {
            var land = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
            game.ActivateAbility(alice, land, "mana");
        }

        game.CastSpell(alice, card, targets: null);

        // SettleDeclining answers with the last option, which is the tokens. Fabricate has no
        // "no" — declining is the other half of the choice, not nothing happening.
        SettleDeclining(game);

        var creature = game.State.Battlefield.Single(
            id => game.State.GetObject(id).Card.Name == "Servo Fabricator Test");

        Assert.Equal(
            2,
            Characteristics.Of(game.State, new CompiledPool(), game.State.GetObject(creature)).Power);

        Assert.Equal(
            2,
            game.State.Battlefield.Count(
                id => game.State.GetObject(id).Card.Name == "Servo"));
    }

    // ---- Delayed abilities that owe the player something (CR 603.7) ----------

    [Fact]
    public void A_delayed_draw_arrives_next_upkeep_and_not_before()
    {
        var spell = Card(
            "Delayed Draw Test",
            "You gain 3 life.\nDraw a card at the beginning of the next turn's upkeep.");

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, spell);
        var land = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");

        game.CastSpell(alice, card, targets: null);
        Settle(game);

        // The life is immediate; the card is not.
        Assert.Equal(23, game.State.GetPlayer(alice).Life);
        var afterCast = game.State.GetPlayer(alice).Hand.Count;

        // The very next upkeep is the opponent's, and that is the one the card names.
        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber == 2 && game.State.CurrentStep >= TurnStep.Draw);

        Assert.Equal(afterCast + 1, game.State.GetPlayer(alice).Hand.Count);
    }

    // ---- Counterspells that name a kind of spell (CR 115.1) ------------------

    [Fact]
    public void A_counter_aimed_at_creature_spells_refuses_anything_else()
    {
        var counter = Card("Creature Counter Test", "Counter target creature spell.");

        var (game, alice, bob) = InMainPhase();

        for (var i = 0; i < 4; i++)
        {
            var land = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
            game.ActivateAbility(alice, land, "mana");
        }

        TestCards.PassToTurn(game, 2);
        var bolt = TestCards.PutInHand(game, bob, Card("Counted Bolt Test", "Draw a card."));
        game.CastSpell(bob, bolt, targets: null);

        var answer = TestCards.PutInHand(game, alice, counter);
        var onStack = game.State.Stack.Single();

        // An instant is not a creature spell, and aiming at it is refused outright rather than
        // fizzling later — the target was never legal (CR 601.2c).
        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, answer, [Target.ToSpell(onStack)]));
    }

    [Fact]
    public void A_counter_aimed_at_creature_spells_stops_a_creature()
    {
        var counter = Card("Creature Stopper Test", "Counter target creature spell.");

        var (game, alice, bob) = InMainPhase();
        var theirLand = game.Create(bob, TestCards.BasicLand("Forest"), Zone.Battlefield);

        // A creature spell is sorcery speed, so Bob needs his own main phase with an empty stack.
        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber == 2
                && game.State.CurrentStep == TurnStep.PrecombatMain
                && game.State.Priority.Holder == bob);

        // Dealt now rather than on turn one: a hand of eight is discarded down to seven at
        // cleanup, and the counter is what would go.
        var answer = TestCards.PutInHand(game, alice, counter);
        var bear = TestCards.PutInHand(game, bob, TestCards.Creature("Counted Bear Test"));
        game.ActivateAbility(bob, theirLand, "mana");
        game.CastSpell(bob, bear, targets: null);

        // CR 117.3c: the caster keeps priority, so Bob passes before Alice can answer.
        game.PassPriority(bob);

        game.CastSpell(alice, answer, [Target.ToSpell(game.State.Stack.Single())]);
        Settle(game);

        Assert.DoesNotContain(
            game.State.Battlefield,
            id => game.State.GetObject(id).Card.Name == "Counted Bear Test");
    }

    // ---- Auras that stop a creature attacking or blocking --------------------

    [Fact]
    public void An_aura_can_stop_the_creature_it_enchants_attacking()
    {
        var pacifism = Card(
            "Rest Aura Test",
            "Enchant creature\nEnchanted creature can't attack or block.",
            CardType.Enchantment,
            subtypes: "Aura");

        var (game, alice, bob) = InMainPhase();
        var bear = game.Create(alice, TestCards.Creature("Rested Bear Test"), Zone.Battlefield);
        var free = game.Create(alice, TestCards.Creature("Free Bear Test"), Zone.Battlefield);

        Enchant(game, alice, pacifism, bear);
        Settle(game);

        TestCards.PassToTurn(game, 3);
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);

        // The enchanted one cannot attack; the one beside it can, which is what shows the
        // restriction came from the Aura and not from the board being unable to attack at all.
        Assert.Throws<InvalidOperationException>(() => game.DeclareAttackers(
            alice, new Dictionary<ObjectId, AttackTarget> { [bear] = AttackTarget.Player(bob) }));

        game.DeclareAttackers(
            alice, new Dictionary<ObjectId, AttackTarget> { [free] = AttackTarget.Player(bob) });
    }

    // ---- Reveal a hand and take from it (CR 701.16) --------------------------

    [Fact]
    public void The_caster_picks_from_the_opponents_hand_and_the_opponent_loses_it()
    {
        var spell = Card(
            "Duress Test",
            "Target opponent reveals their hand. You choose a nonland card from it. "
                + "That player discards that card.");

        var (game, alice, bob) = InMainPhase();

        // Bob's hand holds a land first, so a chooser that ignored the filter would take it —
        // Settle answers with the first option it is offered.
        TestCards.PutInHand(game, bob, TestCards.BasicLand("Island"));
        TestCards.PutInHand(game, bob, TestCards.Creature("Secret Bear Test"));

        var card = TestCards.PutInHand(game, alice, spell);
        var land = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");

        var bobBefore = game.State.GetPlayer(bob).Hand.Count;
        game.CastSpell(alice, card, [Target.ToPlayer(bob)]);
        Settle(game);

        Assert.Equal(bobBefore - 1, game.State.GetPlayer(bob).Hand.Count);
        Assert.Contains(
            game.State.GetPlayer(bob).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Secret Bear Test");

        // The land was not eligible and is still in hand.
        Assert.Contains(
            game.State.GetPlayer(bob).Hand,
            id => game.State.GetObject(id).Card.Name == "Island");
    }

    [Fact]
    public void An_unqualified_card_offers_the_whole_hand_including_lands()
    {
        // The narrowed wordings all read; the plain one did not, because the noun was stripped
        // only when an adjective stood in front of it. The land is the proof: under any filter
        // it would be ineligible, so if it can be taken then no filter was applied.
        var spell = Card(
            "Mind Rot Choice Test",
            "Target player reveals their hand. You choose a card from it. "
                + "That player discards that card.");

        var compiled = CardCompiler.Compile(spell);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();

        TestCards.PutInHand(game, bob, TestCards.BasicLand("Island"));
        TestCards.PutInHand(game, bob, TestCards.Creature("Kept Bear Test"));

        var card = TestCards.PutInHand(game, alice, spell);
        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, forest, "mana");

        game.CastSpell(alice, card, [Target.ToPlayer(bob)]);

        // The choice is examined rather than answered: what "a card" means is the set the
        // caster is offered, and Settle would pick one of them and tell us nothing about the
        // rest. The land is the proof - under any filter this line could carry, it would not
        // be on the list.
        TestCards.PassUntil(game, () => game.State.Choice is not null);

        var offered = game.State.Choice!.Options;
        Assert.Contains(offered, o => o.Label.Contains("Island", StringComparison.Ordinal));
        Assert.Contains(offered, o => o.Label.Contains("Bear", StringComparison.Ordinal));
    }

    // ---- "It can't be regenerated" (CR 701.19c) ------------------------------

    [Fact]
    public void A_destroy_that_forbids_regeneration_gets_through_a_shield()
    {
        var wall = Card(
            "Regenerator Test",
            "{G}: Regenerate ~.",
            CardType.Creature,
            2,
            2);

        // One player owns everything, so the test never has to hand priority across a turn just
        // to raise a shield. Destroying your own creature is perfectly legal.
        var (game, alice, _) = InMainPhase();
        var creature = game.Create(alice, wall, Zone.Battlefield);
        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, forest, "mana");
        game.ActivateAbility(alice, creature, "a");
        Settle(game);

        // The shield is up: an ordinary destroy is replaced by tapping.
        var plain = TestCards.PutInHand(
            game, alice, Card("Plain Kill Test", "Destroy target creature."));

        var land = game.Create(alice, TestCards.BasicLand("Plains"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");
        game.CastSpell(alice, plain, [Target.ToPermanent(creature)]);
        Settle(game);

        Assert.Contains(creature, game.State.Battlefield);

        // Put the shield back up, then use a kill that forbids regeneration.
        var forest2 = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, forest2, "mana");
        game.ActivateAbility(alice, creature, "a");
        Settle(game);

        var harder = TestCards.PutInHand(
            game,
            alice,
            Card("Hard Kill Test", "Destroy target creature. It can't be regenerated."));

        var land2 = game.Create(alice, TestCards.BasicLand("Plains"), Zone.Battlefield);
        game.ActivateAbility(alice, land2, "mana");
        game.CastSpell(alice, harder, [Target.ToPermanent(creature)]);
        Settle(game);

        Assert.DoesNotContain(creature, game.State.Battlefield);
    }

    // ---- Edicts: each opponent sacrifices (CR 609.4, 701.17) -----------------

    [Fact]
    public void Each_opponent_sacrifices_and_the_caster_does_not()
    {
        var spell = Card("Edict Test", "Each opponent sacrifices a creature.");

        var (game, alice, bob) = InMainPhase();
        var mine = game.Create(alice, TestCards.Creature("Safe Bear Test"), Zone.Battlefield);
        game.Create(bob, TestCards.Creature("Doomed Bear Test"), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, spell);
        var land = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");
        game.CastSpell(alice, card, targets: null);
        Settle(game);

        // Bob loses his; Alice keeps hers. An edict that asked the controller would have taken
        // the wrong creature and left the right one alone.
        Assert.DoesNotContain(
            game.State.Battlefield,
            id => game.State.GetObject(id).Card.Name == "Doomed Bear Test");
        Assert.Contains(mine, game.State.Battlefield);
    }

    [Fact]
    public void A_targeted_edict_reads_the_wording_the_cards_actually_use()
    {
        // "Of their choice" is what the effect does anyway - the sacrificing player picks - and
        // the group reader had always allowed the phrase. The targeted one had not, so the
        // commonest wording of a targeted edict, some thirty lines of it, went unread.
        var spell = Card(
            "Diabolic Edict Test",
            "Target player sacrifices a creature of their choice.");

        var compiled = CardCompiler.Compile(spell);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var mine = game.Create(alice, TestCards.Creature("Untouched Bear Test"), Zone.Battlefield);
        game.Create(bob, TestCards.Creature("Chosen Bear Test"), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, spell);
        var land = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");
        game.CastSpell(alice, card, [Target.ToPlayer(bob)]);
        Settle(game);

        // Only the player named loses anything - that being the difference between this and the
        // group edict beside it.
        Assert.DoesNotContain(
            game.State.Battlefield,
            id => game.State.GetObject(id).Card.Name == "Chosen Bear Test");
        Assert.Contains(mine, game.State.Battlefield);
    }

    [Fact]
    public void An_opponent_with_nothing_to_give_is_simply_skipped()
    {
        // CR 609.4: a choice with no legal options is not a stalled game — the effect does as
        // much as it can, which here is nothing at all.
        var spell = Card("Empty Edict Test", "Each opponent sacrifices a creature.");

        var (game, alice, bob) = InMainPhase();
        var mine = game.Create(alice, TestCards.Creature("Untouched Bear Test"), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, spell);
        var land = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");
        game.CastSpell(alice, card, targets: null);
        Settle(game);

        Assert.Contains(mine, game.State.Battlefield);
        Assert.False(game.State.IsWaitingForChoice);
        _ = bob;
    }

    // ---- Amounts counted from the board (CR 107.3) ---------------------------

    [Fact]
    public void Life_gained_for_each_creature_counts_only_the_ones_that_match()
    {
        var spell = Card("Per Each Test", "You gain 2 life for each creature you control.");

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, TestCards.Creature("Mine A Test"), Zone.Battlefield);
        game.Create(alice, TestCards.Creature("Mine B Test"), Zone.Battlefield);
        game.Create(alice, TestCards.Creature("Mine C Test"), Zone.Battlefield);
        game.Create(bob, TestCards.Creature("Theirs Test"), Zone.Battlefield);
        game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, spell);
        var land = game.Create(alice, TestCards.BasicLand("Plains"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");
        game.CastSpell(alice, card, targets: null);
        Settle(game);

        // Three creatures of Alice's, two life each. The opponent's creature and her own land
        // must not count — six is the only total that gets both of those right.
        Assert.Equal(26, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void Drawing_equal_to_a_count_is_one_card_each()
    {
        var spell = Card(
            "Equal Draw Test", "Draw cards equal to the number of creatures you control.");

        var (game, alice, _) = InMainPhase();
        game.Create(alice, TestCards.Creature("Draw A Test"), Zone.Battlefield);
        game.Create(alice, TestCards.Creature("Draw B Test"), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, spell);
        var land = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");

        var before = game.State.GetPlayer(alice).Hand.Count;
        game.CastSpell(alice, card, targets: null);
        Settle(game);

        // Two creatures, two cards, minus the one cast.
        Assert.Equal(before - 1 + 2, game.State.GetPlayer(alice).Hand.Count);
    }

    // ---- Exile until this leaves the battlefield (CR 400.7) ------------------

    [Fact]
    public void The_exiled_card_comes_back_when_the_permanent_that_took_it_goes()
    {
        var ring = Card(
            "Ring Test",
            "When ~ enters, exile target creature an opponent controls until ~ leaves the battlefield.",
            CardType.Enchantment);

        var (game, alice, bob) = InMainPhase();
        var bear = game.Create(bob, TestCards.Creature("Ringed Bear Test", 2, 2), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, ring);
        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, forest, "mana");
        game.CastSpell(alice, card, targets: null);
        Settle(game);

        Assert.DoesNotContain(bear, game.State.Battlefield);
        Assert.DoesNotContain(
            game.State.Battlefield,
            id => game.State.GetObject(id).Card.Name == "Ringed Bear Test");

        // Destroy the enchantment; the creature returns, under its owner's control.
        var ringOnBattlefield = game.State.Battlefield.Single(
            id => game.State.GetObject(id).Card.Name == "Ring Test");

        var bolt = TestCards.PutInHand(
            game, alice, Card("Ring Bolt Test", "Destroy target enchantment."));

        var forest2 = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, forest2, "mana");
        game.CastSpell(alice, bolt, [Target.ToPermanent(ringOnBattlefield)]);
        Settle(game);

        var returned = game.State.Battlefield.Single(
            id => game.State.GetObject(id).Card.Name == "Ringed Bear Test");

        // CR 400.7: it comes back as a new object, and it is its owner's — not the exiler's.
        Assert.NotEqual(bear, returned);
        Assert.Equal(bob, game.State.GetObject(returned).ControllerId);
    }

    [Fact]
    public void A_second_ring_gives_back_only_what_it_took()
    {
        var ring = Card(
            "Twin Ring Test",
            "When ~ enters, exile target creature an opponent controls until ~ leaves the battlefield.",
            CardType.Enchantment);

        var (game, alice, bob) = InMainPhase();
        game.Create(bob, TestCards.Creature("First Bear Test", 2, 2), Zone.Battlefield);
        game.Create(bob, TestCards.Creature("Second Bear Test", 3, 3), Zone.Battlefield);

        for (var i = 0; i < 2; i++)
        {
            var card = TestCards.PutInHand(game, alice, ring);
            var land = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
            game.ActivateAbility(alice, land, "mana");
            game.CastSpell(alice, card, targets: null);
            Settle(game);
        }

        // Both bears are gone.
        Assert.DoesNotContain(
            game.State.Battlefield, id => game.State.GetObject(id).ControllerId == bob);

        // Destroy one ring: exactly one bear comes back, not both.
        var oneRing = game.State.Battlefield.First(
            id => game.State.GetObject(id).Card.Name == "Twin Ring Test");

        var bolt = TestCards.PutInHand(
            game, alice, Card("Twin Bolt Test", "Destroy target enchantment."));

        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, forest, "mana");
        game.CastSpell(alice, bolt, [Target.ToPermanent(oneRing)]);
        Settle(game);

        Assert.Single(
            game.State.Battlefield, id => game.State.GetObject(id).ControllerId == bob);
    }

    // ---- Token copies (CR 707.2) ---------------------------------------------

    [Fact]
    public void A_token_copy_takes_the_printed_card_and_not_what_was_done_to_it()
    {
        var mirror = Card(
            "Mirror Test",
            "When ~ enters, create a token that's a copy of target creature you control.",
            CardType.Enchantment);

        var (game, alice, _) = InMainPhase();
        var bear = game.Create(alice, TestCards.Creature("Copied Bear Test", 2, 2), Zone.Battlefield);

        // Counters are not copiable values (CR 707.2), so the copy is a 2/2 and not a 4/4. The
        // bear is the only creature Alice controls, so the trigger has exactly one legal target
        // and the test is not at the mercy of which one gets picked.
        var pump = TestCards.PutInHand(
            game, alice, Card("Counter Pump Test", "Put two +1/+1 counters on target creature."));

        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, forest, "mana");
        game.CastSpell(alice, pump, [Target.ToPermanent(bear)]);
        Settle(game);

        Assert.Equal(
            4,
            Characteristics.Of(game.State, new CompiledPool(), game.State.GetObject(bear)).Power);

        var enchantment = TestCards.PutInHand(game, alice, mirror);
        var forest2 = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, forest2, "mana");
        game.CastSpell(alice, enchantment, targets: null);
        Settle(game);

        var copy = game.State.Battlefield
            .Select(id => game.State.GetObject(id))
            .Single(o => o.Card.Name == "Copied Bear Test"
                && o.Card.CardTypes.HasFlag(CardType.Token));

        Assert.Equal(2, Characteristics.Of(game.State, new CompiledPool(), copy).Power);
    }

    // ---- Copying spells, and storm (CR 707.10, 702.40) -----------------------

    [Fact]
    public void Storm_copies_once_for_each_spell_cast_before_it()
    {
        var bolt = Card("Storm Bolt Test", "~ deals 1 damage to any target.\nStorm");

        var (game, alice, bob) = InMainPhase();

        for (var i = 0; i < 6; i++)
        {
            var land = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
            game.ActivateAbility(alice, land, "mana");
        }

        // Two cantrips first, so the storm spell is the third of the turn and copies twice.
        for (var i = 0; i < 2; i++)
        {
            var cantrip = TestCards.PutInHand(
                game, alice, Card($"Storm Cantrip {i} Test", "Draw a card."));

            game.CastSpell(alice, cantrip, targets: null);
            Settle(game);
        }

        var storm = TestCards.PutInHand(game, alice, bolt);
        game.CastSpell(alice, storm, [Target.ToPlayer(bob)]);
        Settle(game);

        // Three damage: the spell and its two copies. One copy, or three, would be a different
        // number — and no copies at all would be 1.
        Assert.Equal(17, game.State.GetPlayer(bob).Life);

        // CR 707.10: a copy is not a card, so only the real one is in the graveyard.
        Assert.Single(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Storm Bolt Test");
    }

