    // ---- An Aura's clock runs on its host's controller (CR 506.2) ------------

    [Fact]
    public void An_aura_upkeep_trigger_follows_the_enchanted_creatures_controller()
    {
        var curse = Card(
            "Aura Clock Test",
            "Enchant creature\nAt the beginning of the upkeep of enchanted creature's "
                + "controller, you gain 1 life.",
            CardType.Enchantment, null, null, KeywordAbility.None, "Aura");

        var compiled = CardCompiler.Compile(curse);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var host = game.Create(bob, TestCards.Creature("Cursed Creature Test", 1, 1), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, curse);
        game.CastSpell(alice, card, targets: [Target.ToPermanent(host)]);
        Settle(game);

        var before = game.State.GetPlayer(alice).Life;

        // Bob's upkeep is turn 2. The Aura is Alice's, and it is Bob's clock that runs it - which
        // is the difference between this and "the beginning of your upkeep", and the reason most
        // of these cards are printed at all.
        PassTo(game, 2, TurnStep.Upkeep);
        Settle(game);
        Assert.Equal(before + 1, game.State.GetPlayer(alice).Life);

        // Alice's own upkeep is not the enchanted creature's controller's, so nothing happens.
        PassTo(game, 3, TurnStep.Upkeep);
        Settle(game);
        Assert.Equal(before + 1, game.State.GetPlayer(alice).Life);
    }

    // ---- "Cast or copy" (CR 707.10) ------------------------------------------

    [Fact]
    public void Cast_or_copy_counts_the_copy_as_well_as_the_cast()
    {
        var watcher = Card(
            "Copy Watcher Test",
            "Whenever you cast or copy an instant or sorcery spell, you gain 1 life.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(watcher);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var spell = Card("Copied Spell Test", "You gain 3 life.\nCasualty 1");

        var (game, alice, _) = InMainPhase();
        game.Create(alice, watcher, Zone.Battlefield);
        var fodder = game.Create(alice, TestCards.Creature("Copy Fodder Test", 1, 1), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, spell);
        game.CastSpell(alice, card, targets: null, costPayment: [fodder], conspired: true);

        // Driven by hand rather than through Settle. Two of the watcher's triggers wait at once -
        // one for the cast, one for the copy - and their controller orders them (CR 603.3b);
        // Settle answers every question with its first option, which an ordering question refuses
        // outright because the same trigger cannot be put first twice.
        for (var guard = 0; guard < 60; guard++)
        {
            if (game.State.Choice is { } pending)
            {
                game.Choose(
                    pending.PlayerId,
                    pending.MaxPicks > 1
                        ? [.. pending.Options.Select(o => o.Id)]
                        : [pending.Options[0].Id]);

                continue;
            }

            if (game.State.Stack.IsEmpty)
                break;

            if (game.State.Priority.Holder is { } holder)
                game.PassPriority(holder);
            else
                break;
        }

        // The spell and its copy each gain 3, and the watcher sees both events: a copy is put on
        // the stack without being cast (CR 707.10), so nothing about the cast event sees it and
        // the trigger has to read both.
        Assert.Equal(28, game.State.GetPlayer(alice).Life);
    }

    // ---- Cycling triggers (CR 702.29a) ---------------------------------------

    [Fact]
    public void A_when_you_cycle_trigger_fires_on_cycling_it()
    {
        var card = Card(
            "Cycle Trigger Test",
            "Cycling {0}\nWhen you cycle ~, you gain 2 life.",
            CardType.Creature, 2, 2);

        var compiled = CardCompiler.Compile(card);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var inHand = TestCards.PutInHand(game, alice, card);
        var handBefore = game.State.GetPlayer(alice).Hand.Count;

        game.ActivateAbility(alice, inHand, "cycling");
        Settle(game);

        // Cycling is the activation, so the trigger fires off it - and the draw the keyword
        // itself gives still happens, which is what keeps the hand count level.
        Assert.Equal(22, game.State.GetPlayer(alice).Life);
        Assert.Equal(handBefore, game.State.GetPlayer(alice).Hand.Count);
        Assert.Contains(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Cycle Trigger Test");
    }

    // ---- A group creature connecting (CR 510.2) ------------------------------

    [Fact]
    public void A_creature_you_control_dealing_combat_damage_triggers_for_your_side_only()
    {
        var watcher = Card(
            "Damage Watcher Test",
            "Whenever a creature you control deals combat damage to a player, you gain 1 life.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(watcher);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, watcher, Zone.Battlefield);
        var mine = game.Create(alice, TestCards.Creature("Connecting Test", 2, 2), Zone.Battlefield);
        var theirs = game.Create(bob, TestCards.Creature("Their Attacker Test", 2, 2), Zone.Battlefield);

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [mine] = AttackTarget.Player(bob) });
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Settle(game);

        Assert.Equal(21, game.State.GetPlayer(alice).Life);
        Assert.Equal(18, game.State.GetPlayer(bob).Life);

        // Bob's creature connecting is not "a creature you control", so Alice gains nothing from
        // it - the side of the board is part of the trigger, not decoration.
        PassTo(game, 4, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            bob,
            new Dictionary<ObjectId, AttackTarget> { [theirs] = AttackTarget.Player(alice) });
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Settle(game);

        // 21 from her own hit, minus the 2 she has just taken, and nothing gained: if Bob's
        // creature had triggered it too she would be on 20.
        Assert.Equal(19, game.State.GetPlayer(alice).Life);
    }

    // ---- "Another target" (CR 115.1) -----------------------------------------

    [Fact]
    public void Another_target_creature_never_means_the_source()
    {
        var captain = Card(
            "Another Target Test",
            "Whenever ~ attacks, another target creature gets +2/+2 until end of turn.",
            CardType.Creature, 2, 2);

        var compiled = CardCompiler.Compile(captain);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, captain, Zone.Battlefield);
        var ally = game.Create(alice, TestCards.Creature("Pumped Ally Test", 1, 1), Zone.Battlefield);

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });
        Settle(game);

        // The ally grew and the source did not: "another" is the source leaving itself out, and
        // it has to hold when the ability resolves as well as when its target was chosen.
        Assert.Equal(3, Characteristics.Of(game.State, Pool, game.State.GetObject(ally)).Power);
        Assert.Equal(2, Characteristics.Of(game.State, Pool, game.State.GetObject(attacker)).Power);
    }

    // ---- "Up to one target" (CR 115.1) ---------------------------------------

    [Fact]
    public void Up_to_one_target_may_be_aimed_or_left_alone()
    {
        var bolt = Card(
            "Up To One Test",
            "Up To One Test deals 2 damage to up to one target creature.");

        var compiled = CardCompiler.Compile(bolt);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.Single(compiled.Spell!.Targets);
        Assert.True(compiled.Spell.Targets[0].Optional);

        var (game, alice, bob) = InMainPhase();
        var creature = game.Create(bob, TestCards.Creature("Aimed At Test", 3, 3), Zone.Battlefield);

        var aimed = TestCards.PutInHand(game, alice, bolt);
        game.CastSpell(alice, aimed, targets: [Target.ToPermanent(creature)]);
        Settle(game);

        Assert.Equal(2, game.State.GetObject(creature).Permanent!.DamageMarked);
    }

    [Fact]
    public void Up_to_one_target_can_be_cast_at_nothing()
    {
        var bolt = Card(
            "Up To None Test",
            "Up To None Test deals 2 damage to up to one target creature.");

        var (game, alice, bob) = InMainPhase();
        var creature = game.Create(bob, TestCards.Creature("Unaimed Test", 3, 3), Zone.Battlefield);

        // "Up to" means the target may be left unchosen, and the spell still resolves. A spell
        // that required one would be refused here.
        var card = TestCards.PutInHand(game, alice, bolt);
        game.CastSpell(alice, card, targets: []);
        Settle(game);

        Assert.Equal(0, game.State.GetObject(creature).Permanent!.DamageMarked);
        Assert.Contains(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Up To None Test");
    }

    // ---- Seeing the top of your own library (CR 401.2) ------------------------

    [Fact]
    public void A_permanent_that_shows_the_top_card_shows_it_only_to_its_controller()
    {
        var lens = Card(
            "Top Lens Test",
            "You may look at the top card of your library any time.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(lens);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.True(compiled.ShowsTopOfLibrary);

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, lens, Zone.Battlefield);

        var mine = Views.PlayerViewProjector.Project(game.State, alice, Pool)
            .Players.Single(p => p.PlayerId == alice);

        var top = game.State.GetObject(game.State.GetPlayer(alice).Library[0]).Card.Name;
        Assert.Equal(top, mine.TopOfLibrary?.Name);

        // The half that matters: nobody else sees it. A library is hidden from everyone including
        // its owner (CR 401.2), and this line lifts that for exactly one player.
        var theirs = Views.PlayerViewProjector.Project(game.State, bob, Pool)
            .Players.Single(p => p.PlayerId == alice);

        Assert.Null(theirs.TopOfLibrary);
    }

    [Fact]
    public void Playing_with_the_top_card_revealed_shows_it_to_everyone()
    {
        var oracle = Card(
            "Revealed Top Test",
            "Play with the top card of your library revealed.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(oracle);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.True(compiled.RevealsTopOfLibrary);
        Assert.False(compiled.ShowsTopOfLibrary);

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, oracle, Zone.Battlefield);

        var top = game.State.GetObject(game.State.GetPlayer(alice).Library[0]).Card.Name;

        // Revealed is revealed: the opponent sees the same card, which is the difference between
        // this line and "you may look at the top card of your library any time".
        foreach (var viewer in new[] { alice, bob })
        {
            var seat = Views.PlayerViewProjector.Project(game.State, viewer, Pool)
                .Players.Single(p => p.PlayerId == alice);

            Assert.Equal(top, seat.TopOfLibrary?.Name);
        }
    }

    [Fact]
    public void Without_such_a_permanent_nobody_sees_the_top_card()
    {
        var (game, alice, _) = InMainPhase();

        var mine = Views.PlayerViewProjector.Project(game.State, alice, Pool)
            .Players.Single(p => p.PlayerId == alice);

        Assert.Null(mine.TopOfLibrary);
    }

    // ---- "Defending player controls" (CR 506.2) ------------------------------

    [Fact]
    public void Defending_player_controls_names_the_other_side_of_the_combat()
    {
        var raider = Card(
            "Defender Tapper Test",
            "Whenever ~ attacks, tap target creature defending player controls.",
            CardType.Creature, 2, 2);

        var compiled = CardCompiler.Compile(raider);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, raider, Zone.Battlefield);
        var mine = game.Create(alice, TestCards.Creature("My Own Test", 1, 1), Zone.Battlefield);
        var theirs = game.Create(bob, TestCards.Creature("Their Blocker Test", 1, 1), Zone.Battlefield);

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });
        Settle(game);

        // Only the defender's creature answers to the phrase, so that is the one that taps -
        // Alice's own is on the battlefield throughout and is never a legal choice.
        Assert.True(game.State.GetObject(theirs).Permanent!.IsTapped);
        Assert.False(game.State.GetObject(mine).Permanent!.IsTapped);
    }

    // ---- Counters on a whole group (CR 121.2) --------------------------------

    [Fact]
    public void A_counter_on_each_other_creature_leaves_the_source_out()
    {
        var captain = Card(
            "Group Counter Test",
            "When ~ enters, put a +1/+1 counter on each other creature you control.",
            CardType.Creature, 1, 1);

        var compiled = CardCompiler.Compile(captain);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var mine = game.Create(alice, TestCards.Creature("Counted Ally Test", 1, 1), Zone.Battlefield);
        var theirs = game.Create(bob, TestCards.Creature("Counted Enemy Test", 1, 1), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, captain);
        game.CastSpell(alice, card, targets: null);
        Settle(game);

        var source = game.State.Battlefield.Single(
            id => game.State.GetObject(id).Card.Name == "Group Counter Test");

        Assert.Equal(1, game.State.GetObject(mine).Permanent!.Counters[CounterKinds.PlusOnePlusOne]);

        // "Other" leaves the source out, and "you control" leaves the opponent's out.
        Assert.False(
            game.State.GetObject(source).Permanent!.Counters.ContainsKey(CounterKinds.PlusOnePlusOne));
        Assert.False(
            game.State.GetObject(theirs).Permanent!.Counters.ContainsKey(CounterKinds.PlusOnePlusOne));
    }

    // ---- Cost reducers (CR 601.2f) -------------------------------------------

    [Fact]
    public void A_reducer_takes_generic_mana_off_the_spells_it_names()
    {
        var altar = Card(
            "Reducer Altar Test",
            "Creature spells you cast cost {1} less to cast.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(altar);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.Single(compiled.CostModifiers);

        var bear = new CardDefinition
        {
            OracleId = "oracle-reduced-bear-test",
            Name = "Reduced Bear Test",
            CardTypes = CardType.Creature,
            Power = 2,
            Toughness = 2,
            ManaCostRaw = "{2}",
        };

        var (game, alice, _) = InMainPhase();
        game.Create(alice, altar, Zone.Battlefield);

        // One mana for a two-mana creature: it is only castable because of the discount.
        var land = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");

        var card = TestCards.PutInHand(game, alice, bear);
        game.CastSpell(alice, card, targets: null);
        Settle(game);

        Assert.Contains(
            game.State.Battlefield,
            id => game.State.GetObject(id).Card.Name == "Reduced Bear Test");
    }

    [Fact]
    public void A_reducer_leaves_alone_what_it_does_not_name()
    {
        var altar = Card(
            "Narrow Reducer Test",
            "Creature spells you cast cost {1} less to cast.",
            CardType.Enchantment);

        var bolt = new CardDefinition
        {
            OracleId = "oracle-undiscounted-test",
            Name = "Undiscounted Test",
            OracleText = "You gain 1 life.",
            CardTypes = CardType.Instant,
            ManaCostRaw = "{2}",
        };

        var (game, alice, _) = InMainPhase();
        game.Create(alice, altar, Zone.Battlefield);

        var land = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");

        var card = TestCards.PutInHand(game, alice, bolt);

        // An instant is not a creature spell, so the one mana is still one short.
        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, card, targets: null));
    }

    [Fact]
    public void A_reducer_cannot_pay_a_coloured_pip()
    {
        var altar = Card(
            "Pip Reducer Test",
            "Creature spells you cast cost {2} less to cast.",
            CardType.Enchantment);

        var drake = new CardDefinition
        {
            OracleId = "oracle-pip-drake-test",
            Name = "Pip Drake Test",
            CardTypes = CardType.Creature,
            Power = 2,
            Toughness = 2,
            ManaCostRaw = "{1}{U}",
        };

        var (game, alice, _) = InMainPhase();
        game.Create(alice, altar, Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, drake);

        // CR 601.2f: a reduction comes off the generic part. With no blue mana the {U} is still
        // owed, however large the discount - otherwise a Dragon would be castable off two
        // Islands.
        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, card, targets: null));
    }

    // ---- Energy (CR 107.4c) --------------------------------------------------

    [Fact]
    public void An_offer_can_be_priced_in_life()
    {
        var card = Card(
            "Life Offer Test",
            "At the beginning of your upkeep, you may pay 2 life. If you do, draw a card.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(card);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        game.Create(alice, card, Zone.Battlefield);

        var hand = game.State.GetPlayer(alice).Hand.Count;

        PassTo(game, 3, TurnStep.Upkeep);
        TestCards.PassUntil(game, () => game.State.Choice is not null);

        var offer = game.State.Choice!;
        Assert.Equal(ChoiceKind.OptionalPayment, offer.Kind);
        game.Choose(alice, ["yes"]);
        Settle(game);

        // Life is a price here, not an effect: read through the free branch it would have been
        // parsed as something that happens and taken the whole offer down with it.
        Assert.Equal(18, game.State.GetPlayer(alice).Life);
        Assert.True(game.State.GetPlayer(alice).Hand.Count > hand);
    }

    [Fact]
    public void An_offer_priced_in_life_is_not_made_when_it_cannot_be_paid()
    {
        var card = Card(
            "Steep Life Offer Test",
            "At the beginning of your upkeep, you may pay 25 life. If you do, draw a card.",
            CardType.Enchantment);

        var (game, alice, _) = InMainPhase();
        game.Create(alice, card, Zone.Battlefield);

        // CR 118.4: life may be paid down to zero and no further, and 25 is more than Alice has.
        PassTo(game, 3, TurnStep.PrecombatMain);
        Settle(game);

        Assert.Equal(20, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void An_offer_can_be_priced_in_energy()
    {
        var card = Card(
            "Energy Offer Test",
            "When ~ enters, you get {E}{E}.\nAt the beginning of your upkeep, you may pay {E}{E}. "
                + "If you do, you gain 3 life.",
            CardType.Artifact);

        var compiled = CardCompiler.Compile(card);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var spell = TestCards.PutInHand(game, alice, card);
        game.CastSpell(alice, spell, targets: null);
        Settle(game);

        Assert.Equal(2, game.State.GetPlayer(alice).Energy);

        PassTo(game, 3, TurnStep.Upkeep);
        TestCards.PassUntil(game, () => game.State.Choice is not null);

        var offer = game.State.Choice!;
        Assert.Equal(ChoiceKind.OptionalPayment, offer.Kind);
        game.Choose(alice, ["yes"]);
        Settle(game);

        // Spent as energy, not looked for in the mana pool - which is empty, and which a cost of
        // "{E}{E}" read as mana would have been asked for.
        Assert.Equal(23, game.State.GetPlayer(alice).Life);
        Assert.Equal(0, game.State.GetPlayer(alice).Energy);
    }



    [Fact]
    public void Energy_is_gained_on_entering_and_spent_to_activate()
    {
        var battery = Card(
            "Energy Test",
            "When ~ enters, you get {E}{E}{E}.\nPay {E}{E}: Draw a card.",
            CardType.Artifact);

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, battery);

        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, forest, "mana");
        game.CastSpell(alice, card, targets: null);
        Settle(game);

        Assert.Equal(3, game.State.GetPlayer(alice).Energy);

        var onBattlefield = game.State.Battlefield.Single(
            id => game.State.GetObject(id).Card.Name == "Energy Test");

        var handBefore = game.State.GetPlayer(alice).Hand.Count;
        game.ActivateAbility(alice, onBattlefield, "a");
        Settle(game);

        Assert.Equal(1, game.State.GetPlayer(alice).Energy);
        Assert.Equal(handBefore + 1, game.State.GetPlayer(alice).Hand.Count);

        // One energy left and the ability wants two: it cannot be activated, and no mana in the
        // world helps — which is the whole reason energy is not a mana symbol.
        Assert.Throws<InvalidOperationException>(
            () => game.ActivateAbility(alice, onBattlefield, "a"));
        Assert.Equal(1, game.State.GetPlayer(alice).Energy);
    }

    // ---- Evasion: can't be blocked by ... (CR 509.1b) ------------------------

    private static string? TryBlock(Game game, Guid defender, ObjectId attacker, ObjectId blocker)
    {
        try
        {
            game.DeclareBlockers(
                defender,
                new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [attacker] = [blocker] });

            return null;
        }
        catch (InvalidOperationException e)
        {
            return e.Message;
        }
    }

    [Fact]
    public void A_creature_that_cannot_be_blocked_by_small_creatures_turns_them_away()
    {
        var sneak = Keyworded(
            "Sneaky Test", "~ can't be blocked by creatures with power 2 or less.");

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, sneak, Zone.Battlefield);
        var small = game.Create(bob, TestCards.Creature("Small Bear Test", 2, 2), Zone.Battlefield);
        var large = game.Create(bob, TestCards.Creature("Large Bear Test", 3, 3), Zone.Battlefield);

        TestCards.PassToTurn(game, 3);
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice, new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);

        Assert.NotNull(TryBlock(game, bob, attacker, small));

        // The same declaration with a big enough creature is fine, which is what shows the
        // restriction is about the blocker's power and not about blocking at all.
        Assert.Null(TryBlock(game, bob, attacker, large));
    }

    [Fact]
    public void Can_t_be_blocked_by_a_named_kind_reads_through_the_ordinary_target_grammar()
    {
        var sneak = Keyworded(
            "Artifact Dodger Test", "~ can't be blocked by artifact creatures.");

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, sneak, Zone.Battlefield);

        var golem = game.Create(
            bob,
            Card("Golem Test", string.Empty, CardType.Artifact | CardType.Creature),
            Zone.Battlefield);

        var bear = game.Create(bob, TestCards.Creature("Flesh Bear Test"), Zone.Battlefield);

        TestCards.PassToTurn(game, 3);
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice, new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);

        Assert.NotNull(TryBlock(game, bob, attacker, golem));
        Assert.Null(TryBlock(game, bob, attacker, bear));
    }

    // ---- Effects on the attached permanent (CR 701.3) ------------------------

    private static ObjectId Enchant(Game game, Guid who, CardDefinition aura, ObjectId onto)
    {
        var inHand = TestCards.PutInHand(game, who, aura);
        var land = game.Create(who, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(who, land, "mana");
        game.CastSpell(who, inHand, [Target.ToPermanent(onto)]);

        return inHand;
    }

    [Fact]
    public void An_aura_can_tap_the_creature_it_enchants()
    {
        var aura = Card(
            "Tapping Aura Test",
            "Enchant creature\nWhen ~ enters, tap enchanted creature.",
            CardType.Enchantment,
            subtypes: "Aura");

        var (game, alice, bob) = InMainPhase();
        var bear = game.Create(bob, TestCards.Creature("Tapped Bear Test"), Zone.Battlefield);
        var other = game.Create(bob, TestCards.Creature("Other Bear Test"), Zone.Battlefield);

        Enchant(game, alice, aura, bear);
        Settle(game);

        // The enchanted one, and only the enchanted one.
        Assert.True(game.State.GetObject(bear).Permanent?.IsTapped);
        Assert.False(game.State.GetObject(other).Permanent?.IsTapped);
    }

    [Fact]
    public void An_aura_can_destroy_what_it_enchants_and_honours_indestructible()
    {
        // The verb goes through the ordinary vocabulary, so the rules that come with it come too:
        // an indestructible creature is not destroyed (CR 702.12b), and nothing here had to know
        // that separately.
        var aura = Card(
            "Dooming Aura Test",
            "Enchant creature\nWhen ~ enters, destroy enchanted creature.",
            CardType.Enchantment,
            subtypes: "Aura");

        var (game, alice, bob) = InMainPhase();
        var tough = game.Create(bob, TestCards.Indestructible("Tough Wall Test"), Zone.Battlefield);

        Enchant(game, alice, aura, tough);
        Settle(game);

        Assert.Contains(tough, game.State.Battlefield);

        var frail = game.Create(bob, TestCards.Creature("Frail Bear Test"), Zone.Battlefield);
        Enchant(game, alice, aura, frail);
        Settle(game);

        Assert.DoesNotContain(frail, game.State.Battlefield);
    }

    // ---- Living weapon (CR 702.90) -------------------------------------------

    [Fact]
    public void Living_weapon_brings_a_germ_and_wears_itself_on_it()
    {
        var blade = Card(
            "Living Blade Test",
            "Living weapon\nEquipped creature gets +2/+2.\nEquip {2}",
            CardType.Artifact,
            subtypes: "Equipment");

        var (game, alice, _) = InMainPhase();
        var equipment = TestCards.PutInHand(game, alice, blade);

        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, forest, "mana");
        game.CastSpell(alice, equipment, targets: null);
        Settle(game);

        var germ = game.State.Battlefield.SingleOrDefault(
            id => game.State.GetObject(id).Card.Name == "Germ");

        Assert.NotEqual(default, germ);

        // The Germ is printed 0/0 and only survives because the Equipment is on it — which is
        // both the joke and the proof that the attaching half actually happened.
        var computed = Characteristics.Of(game.State, new CompiledPool(), game.State.GetObject(germ));
        Assert.Equal(2, computed.Power);
        Assert.Equal(2, computed.Toughness);

        var onBattlefield = game.State.Battlefield.Single(
            id => game.State.GetObject(id).Card.Name == "Living Blade Test");
        Assert.Equal(germ, game.State.GetObject(onBattlefield).Permanent?.AttachedTo);
    }

    // ---- Delve (CR 702.66) ---------------------------------------------------

    [Fact]
    public void Delve_exiles_graveyard_cards_to_pay_for_generic_mana()
    {
        var oracle = Kicked("Delve Test", "{4}", "Delve\nDraw a card.");

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, oracle);

        var fodder = Enumerable.Range(0, 3)
            .Select(i => game.Create(alice, TestCards.Creature($"Fodder {i} Test"), Zone.Graveyard))
            .ToList();

        // One land plus three exiled cards pays {4}. One land alone would not.
        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, forest, "mana");

        var handBefore = game.State.GetPlayer(alice).Hand.Count;
        game.CastSpell(
            alice, card, targets: null, variableValue: 0, tapToPay: null, modes: null,
            kicked: false, costPayment: null, faceDown: false, delve: fodder);

        Settle(game);

        Assert.Equal(handBefore - 1 + 1, game.State.GetPlayer(alice).Hand.Count);
        foreach (var spent in fodder)
            Assert.DoesNotContain(spent, game.State.GetPlayer(alice).Graveyard);
    }

    [Fact]
    public void Delve_cannot_reach_into_someone_elses_graveyard()
    {
        var oracle = Kicked("Delve Scope Test", "{4}", "Delve\nDraw a card.");

        var (game, alice, bob) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, oracle);

        var theirs = game.Create(bob, TestCards.Creature("Their Fodder Test"), Zone.Graveyard);

        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, forest, "mana");

        Assert.Throws<InvalidOperationException>(() => game.CastSpell(
            alice, card, targets: null, variableValue: 0, tapToPay: null, modes: null,
            kicked: false, costPayment: null, faceDown: false, delve: [theirs]));
    }

    // ---- Echo (CR 702.29) ----------------------------------------------------

    /// <summary>An echo creature, cheap enough to cast with one land.</summary>
    private static CardDefinition Echoing(string name) => new()
    {
        OracleId = "oracle-" + name.ToLowerInvariant().Replace(' ', '-'),
        Name = name,
        OracleText = "Echo {1}",
        CardTypes = CardType.Creature,
        Power = 3,
        Toughness = 3,
        ManaCostRaw = "{1}",
    };

    [Fact]
    public void Echo_is_not_owed_on_the_turn_it_arrives_and_is_owed_on_the_next_upkeep()
    {
        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, Echoing("Echo Test"));

        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, forest, "mana");
        game.CastSpell(alice, card, targets: null);
        Settle(game);

        var creature = game.State.Battlefield.First(
            id => game.State.GetObject(id).Card.Name == "Echo Test");

        // It arrived this turn, so no upkeep of its controller's has passed: it is still here.
        Assert.Contains(creature, game.State.Battlefield);

        // Alice's next upkeep. Nothing is paid, so it is sacrificed.
        SettleDeclining(game);
        TestCards.PassToTurn(game, 3);
        SettleDeclining(game);

        Assert.DoesNotContain(
            game.State.Battlefield,
            id => game.State.GetObject(id).Card.Name == "Echo Test");
    }

    [Fact]
    public void Echo_paid_keeps_the_creature_and_is_never_asked_again()
    {
        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, Echoing("Paid Echo Test"));

        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, forest, "mana");
        game.CastSpell(alice, card, targets: null);
        Settle(game);

        // A land to pay the echo with on the next upkeep, and Settle takes the first option —
        // which is to pay.
        game.Create(alice, TestCards.BasicLand("Plains"), Zone.Battlefield);
        TestCards.PassUntil(
            game, () => game.State.TurnNumber >= 3 && game.State.CurrentStep == TurnStep.Upkeep);

        var mana = game.State.Battlefield.First(
            id => game.State.GetObject(id).Card.Name == "Plains");
        game.ActivateAbility(alice, mana, "mana");
        Settle(game);

        // Surviving is not enough on its own — a creature nobody asked about also survives. The
        // offer has to have been made and answered.
        Assert.Contains(
            game.Log,
            e => e is OptionalPaymentRequested { PlayerId: var who } && who == alice);
        Assert.Contains(
            game.State.Battlefield,
            id => game.State.GetObject(id).Card.Name == "Paid Echo Test");

        var offersSoFar = game.Log.Count(e => e is OptionalPaymentRequested);

        // The counter is spent, so a later upkeep asks nothing and it survives with no mana up.
        TestCards.PassToTurn(game, 5);
        SettleDeclining(game);

        Assert.Equal(offersSoFar, game.Log.Count(e => e is OptionalPaymentRequested));
        Assert.Contains(
            game.State.Battlefield,
            id => game.State.GetObject(id).Card.Name == "Paid Echo Test");
    }

    // ---- Bloodthirst (CR 702.54) ---------------------------------------------

    [Fact]
    public void Bloodthirst_arrives_bigger_only_when_an_opponent_has_bled_this_turn()
    {
        var oracle = new CardDefinition
        {
            OracleId = "oracle-bloodthirst-test",
            Name = "Bloodthirst Test",
            OracleText = "Bloodthirst 2",
            CardTypes = CardType.Creature,
            Power = 1,
            Toughness = 1,
            ManaCostRaw = "{1}",
        };

        var (game, alice, bob) = InMainPhase();

        // First copy, on an unbloodied board: it arrives as printed.
        var plain = TestCards.PutInHand(game, alice, oracle);
        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, forest, "mana");
        game.CastSpell(alice, plain, targets: null);
        Settle(game);

        var arrived = game.State.Battlefield.First(
            id => game.State.GetObject(id).Card.Name == "Bloodthirst Test");
        Assert.Equal(1, Characteristics.Of(game.State, new CompiledPool(), game.State.GetObject(arrived)).Power);

        // Now bleed the opponent, and a second copy arrives with the counters.
        var bolt = TestCards.PutInHand(
            game, alice, Card("Bloodthirst Bolt Test", "~ deals 2 damage to any target."));
        var forest2 = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, forest2, "mana");
        game.CastSpell(alice, bolt, [Target.ToPlayer(bob)]);
        Settle(game);

        Assert.Equal(18, game.State.GetPlayer(bob).Life);

        var second = TestCards.PutInHand(game, alice, oracle);
        var forest3 = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, forest3, "mana");
        game.CastSpell(alice, second, targets: null);
        Settle(game);

        var bigger = game.State.Battlefield
            .Where(id => game.State.GetObject(id).Card.Name == "Bloodthirst Test")
            .Select(id => Characteristics.Of(
                game.State, new CompiledPool(), game.State.GetObject(id)).Power)
            .OrderBy(p => p)
            .ToList();

        // One of each: the first still 1/1, the second 3/3. A bloodthirst that triggered rather
        // than replaced would have grown both, or neither.
        Assert.Equal([1, 3], bigger);
    }

    // ---- Ward (CR 702.21) ----------------------------------------------------

    /// <summary>Answers every choice with the last option — declining anything optional.</summary>
    private static void SettleDeclining(Game game)
    {
        var passedOnce = false;

        for (var guard = 0; guard < 80; guard++)
        {
            if (game.State.Choice is { } choice)
            {
                game.Choose(choice.PlayerId, [choice.Options[^1].Id]);
                continue;
            }

            if (passedOnce && game.State.Stack.IsEmpty && game.State.PendingTriggers.IsEmpty)
                return;

            if (game.State.Priority.Holder is not { } holder)
                return;

            game.PassPriority(holder);
            passedOnce = true;
        }
    }

    [Fact]
    public void Ward_counters_an_opponents_spell_when_they_will_not_pay()
    {
        var (game, alice, bob) = InMainPhase();
        var warded = game.Create(
            alice, Keyworded("Ward Test", "Ward {2}"), Zone.Battlefield);

        TestCards.PassToTurn(game, 2);
        var bolt = TestCards.PutInHand(
            game, bob, Card("Ward Bolt Test", "Destroy target creature."));

        game.CastSpell(bob, bolt, [Target.ToPermanent(warded)]);

        // Bob declines to pay, so his spell is countered and the creature lives.
        SettleDeclining(game);

        Assert.Contains(warded, game.State.Battlefield);
        Assert.Contains(
            game.State.GetPlayer(bob).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Ward Bolt Test");
    }

    [Fact]
    public void Ward_cannot_counter_a_spell_that_cannot_be_countered()
    {
        // CR 701.6a against CR 702.21b. Ward's "counter it" is a different effect from a
        // counterspell's - it has no target, which is the whole point of ward - so it carries its
        // own copy of the can't-be-countered check, and only the counterspell's copy was tested.
        // Declining to pay is what puts the question, and the spell resolves anyway.
        var (game, alice, bob) = InMainPhase();
        var warded = game.Create(
            alice, Keyworded("Uncounterable Ward Test", "Ward {2}"), Zone.Battlefield);

        TestCards.PassToTurn(game, 2);
        var bolt = TestCards.PutInHand(
            game, bob,
            Card("Unstoppable Bolt Test", "This spell can't be countered.\nDestroy target creature."));

        game.CastSpell(bob, bolt, [Target.ToPermanent(warded)]);

        // Bob declines the tax, the trigger resolves, and it counters nothing.
        SettleDeclining(game);

        Assert.DoesNotContain(warded, game.State.Battlefield);
    }

    [Fact]
    public void Ward_does_not_tax_its_own_controller()
    {
        // CR 702.21a: only an opponent's spell triggers it. Alice targets her own warded
        // creature and nothing is countered — the spell resolves and kills it.
        var (game, alice, _) = InMainPhase();
        var warded = game.Create(
            alice, Keyworded("Self Ward Test", "Ward {2}"), Zone.Battlefield);

        var bolt = TestCards.PutInHand(
            game, alice, Card("Self Ward Bolt Test", "Destroy target creature."));

        game.CastSpell(alice, bolt, [Target.ToPermanent(warded)]);
        SettleDeclining(game);

        Assert.DoesNotContain(warded, game.State.Battlefield);
    }

    // ---- Affinity (CR 702.40) ------------------------------------------------

    [Fact]
    public void Affinity_takes_one_generic_off_for_each_artifact_you_control()
    {
        // {4} with two artifacts out is {2}: exactly two lands pays for it, and a third would
        // make the test pass whether or not the reduction happened.
        var oracle = Kicked("Affinity Test", "{4}", "Affinity for artifacts\nDraw a card.");

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, oracle);

        game.Create(alice, Card("Trinket A Test", string.Empty, CardType.Artifact), Zone.Battlefield);
        game.Create(alice, Card("Trinket B Test", string.Empty, CardType.Artifact), Zone.Battlefield);

        foreach (var _ in Enumerable.Range(0, 2))
        {
            var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
            game.ActivateAbility(alice, forest, "mana");
        }

        var handBefore = game.State.GetPlayer(alice).Hand.Count;
        game.CastSpell(alice, card);
        Settle(game);

        Assert.Equal(handBefore - 1 + 1, game.State.GetPlayer(alice).Hand.Count);
    }

    [Fact]
    public void Affinity_counts_only_what_it_names_and_only_yours()
    {
        // An opponent's artifacts do not make your spell cheaper, and neither does a land.
        var oracle = Kicked("Affinity Scope Test", "{4}", "Affinity for artifacts\nDraw a card.");

        var (game, alice, bob) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, oracle);

        game.Create(bob, Card("Their Trinket Test", string.Empty, CardType.Artifact), Zone.Battlefield);
        game.Create(alice, Card("My Trinket Test", string.Empty, CardType.Artifact), Zone.Battlefield);

        // One artifact of mine, so {4} becomes {3} — and three mana is not enough.
        foreach (var _ in Enumerable.Range(0, 2))
        {
            var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
            game.ActivateAbility(alice, forest, "mana");
        }

        Assert.Throws<InvalidOperationException>(() => game.CastSpell(alice, card));
        Assert.Contains(card, game.State.GetPlayer(alice).Hand);
    }

    [Fact]
    public void Affinity_never_removes_a_coloured_requirement()
    {
        // CR 601.2f: reductions take generic mana only. Six artifacts do not make {2}{G} free.
        var oracle = Kicked("Affinity Colour Test", "{2}{G}", "Affinity for artifacts\nDraw a card.");

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, oracle);

        foreach (var i in Enumerable.Range(0, 6))
        {
            game.Create(
                alice,
                Card($"Colour Trinket {i} Test", string.Empty, CardType.Artifact),
                Zone.Battlefield);
        }

        // No mana at all: the {G} still has to be paid.
        Assert.Throws<InvalidOperationException>(() => game.CastSpell(alice, card));

        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, forest, "mana");

        var handBefore = game.State.GetPlayer(alice).Hand.Count;
        game.CastSpell(alice, card);
        Settle(game);

        Assert.Equal(handBefore - 1 + 1, game.State.GetPlayer(alice).Hand.Count);
    }

    // ---- Permanents that do not untap (CR 502.3) -----------------------------

    [Fact]
    public void A_permanent_that_doesnt_untap_stays_tapped_through_its_untap_step()
    {
        var oracle = Keyworded(
            "Sleeper Test",
            "~ doesn't untap during your untap step.");

        var (game, alice, _) = InMainPhase();
        var sleeper = game.Create(alice, oracle, Zone.Battlefield);
        var ordinary = game.Create(alice, TestCards.Creature("Waker Test"), Zone.Battlefield);

        game.Tap(sleeper);
        game.Tap(ordinary);

        Assert.True(game.State.GetObject(sleeper).Permanent?.IsTapped);
        Assert.True(game.State.GetObject(ordinary).Permanent?.IsTapped);

        TestCards.PassToTurn(game, 3);

        // The one with the restriction is still tapped; the one beside it untapped, which is what
        // shows the untap step ran at all.
        Assert.True(game.State.GetObject(sleeper).Permanent?.IsTapped);
        Assert.False(game.State.GetObject(ordinary).Permanent?.IsTapped);
    }

    [Fact]
    public void An_aura_holds_down_the_creature_it_enchants_and_lets_go_when_it_leaves()
    {
        // The restriction is on a permanent whose own text says nothing about untapping, which is
        // why it is computed rather than stored: when the Aura goes, the creature untaps again.
        var aura = Card(
            "Shackle Test",
            "Enchant creature\nEnchanted creature doesn't untap during its controller's untap step.",
            CardType.Enchantment,
            subtypes: "Aura");

        var (game, alice, _) = InMainPhase();
        var bear = game.Create(alice, TestCards.Creature("Held Bear Test"), Zone.Battlefield);
        game.Tap(bear);

        var shackle = TestCards.PutInHand(game, alice, aura);
        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, forest, "mana");
        game.CastSpell(alice, shackle, [Target.ToPermanent(bear)]);
        Settle(game);

        TestCards.PassToTurn(game, 3);
        Assert.True(game.State.GetObject(bear).Permanent?.IsTapped);

        // Destroy the Aura, and the next untap step frees the creature.
        var bolt = TestCards.PutInHand(
            game, alice, Card("Shackle Bolt Test", "Destroy target enchantment."));
        var forest2 = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, forest2, "mana");
        // CR 400.7: the Aura on the battlefield is not the card that was in hand.
        var onBattlefield = game.State.Battlefield.First(
            id => game.State.GetObject(id).Card.Name == "Shackle Test");

        game.CastSpell(alice, bolt, [Target.ToPermanent(onBattlefield)]);
        Settle(game);

        TestCards.PassToTurn(game, 5);
        Assert.False(game.State.GetObject(bear).Permanent?.IsTapped);
    }

    // ---- Toxic, and the trigger's subject (CR 702.164, 603.2) ----------------

    /// <summary>A creature with a keyword line and nothing else.</summary>
    private static CardDefinition Keyworded(string name, string oracleText) => new()
    {
        OracleId = "oracle-" + name.ToLowerInvariant().Replace(' ', '-'),
        Name = name,
        OracleText = oracleText,
        CardTypes = CardType.Creature,
        Power = 3,
        Toughness = 3,
        ManaCostRaw = "{3}",
    };

    [Fact]
    public void Toxic_poisons_the_player_it_hit_and_not_its_controller()
    {
        // The whole point of the trigger's subject: "that player" is decided by the event, and
        // the way to be wrong about it is to poison the wrong person — which is exactly what
        // scoping it to the controller would do.
        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, Keyworded("Toxic Test", "Toxic 2"), Zone.Battlefield);

        TestCards.PassToTurn(game, 3);
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice, new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);
        game.DeclareBlockers(bob, new Dictionary<ObjectId, IReadOnlyList<ObjectId>>());
        TestCards.PassUntil(game, () => game.State.CurrentStep >= TurnStep.EndOfCombat);

        Assert.Equal(17, game.State.GetPlayer(bob).Life);
        Assert.Equal(2, game.State.GetPlayer(bob).PoisonCounters);
        Assert.Equal(0, game.State.GetPlayer(alice).PoisonCounters);
    }

    [Fact]
    public void Toxic_does_nothing_when_the_damage_is_not_combat_damage()
    {
        // CR 702.164a is about combat damage only, and the trigger condition is what enforces it.
        var (game, alice, bob) = InMainPhase();
        var pinger = game.Create(
            alice,
            Keyworded(
                "Toxic Pinger Test",
                "Toxic 2\n{T}: ~ deals 1 damage to any target."),
            Zone.Battlefield);

        TestCards.PassToTurn(game, 3);
        game.ActivateAbility(alice, pinger, "a", [Target.ToPlayer(bob)]);
        Settle(game);

        Assert.Equal(19, game.State.GetPlayer(bob).Life);
        Assert.Equal(0, game.State.GetPlayer(bob).PoisonCounters);
    }

    // ---- Typecycling (CR 702.29) ---------------------------------------------

    [Fact]
    public void Basic_landcycling_discards_the_card_and_fetches_a_basic()
    {
        var oracle = Kicked("Landcycler Test", "{5}", "Basic landcycling {1}");

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, oracle);

        // Two candidates, the wrong one first: a search that ignored its filter would offer the
        // Bear as the first option and the test would catch it.
        game.Create(alice, TestCards.Creature("Library Bear Test"), Zone.Library);
        game.Create(alice, TestCards.BasicLand("Forest"), Zone.Library);

        var plains = game.Create(alice, TestCards.BasicLand("Plains"), Zone.Battlefield);
        game.ActivateAbility(alice, plains, "mana");

        game.ActivateAbility(alice, card, "typecycling");
        Settle(game);

        // CR 702.29a: the discard is a cost, so it happens whether or not anything responds.
        Assert.DoesNotContain(card, game.State.GetPlayer(alice).Hand);
        Assert.Contains(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Landcycler Test");

        Assert.Contains(
            game.State.GetPlayer(alice).Hand,
            id => game.State.GetObject(id).Card.Name == "Forest");
        Assert.Contains(
            game.State.GetPlayer(alice).Library,
            id => game.State.GetObject(id).Card.Name == "Library Bear Test");
    }

    [Fact]
    public void Typecycling_is_not_castable_and_not_a_draw()
    {
        // The whole point of the keyword family is that it is a search, not the draw plain
        // cycling gives — a card fetched this way is chosen, not dealt.
        var oracle = Kicked("Forestcycler Test", "{5}", "Forestcycling {1}");

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, oracle);

        game.Create(alice, TestCards.Creature("Deep Bear Test"), Zone.Library);
        game.Create(alice, TestCards.BasicLand("Forest"), Zone.Library);

        var plains = game.Create(alice, TestCards.BasicLand("Plains"), Zone.Battlefield);
        game.ActivateAbility(alice, plains, "mana");

        game.ActivateAbility(alice, card, "typecycling");
        Settle(game);

        Assert.Contains(
            game.State.GetPlayer(alice).Hand,
            id => game.State.GetObject(id).Card.Name == "Forest");

        // The card on top was not drawn — it is still in the library.
        Assert.Contains(
            game.State.GetPlayer(alice).Library,
            id => game.State.GetObject(id).Card.Name == "Deep Bear Test");
    }

    // ---- Soulshift (CR 702.46) -----------------------------------------------

    /// <summary>A Spirit with a mana value, for soulshift to reach or fail to reach.</summary>
    private static CardDefinition Spirit(string name, int cmc, string oracleText = "") => new()
    {
        OracleId = "oracle-" + name.ToLowerInvariant().Replace(' ', '-'),
        Name = name,
        OracleText = oracleText,
        CardTypes = CardType.Creature,
        Subtypes = ["Spirit"],
        Power = 2,
        Toughness = 2,
        ManaCostRaw = "{" + cmc + "}",
        Cmc = cmc,
    };

    [Fact]
    public void Soulshift_returns_a_cheap_enough_Spirit_when_the_creature_dies()
    {
        // The dying creature is itself a Spirit in a graveyard, and at mana value 2 it is out of
        // reach of its own Soulshift 1 — so the cap is the only thing deciding what is legal, and
        // there is exactly one card it can name.
        var (game, alice, _) = InMainPhase();
        var dying = game.Create(alice, Spirit("Soulshift Test", 2, "Soulshift 1"), Zone.Battlefield);
        game.Create(alice, Spirit("Cheap Spirit Test", 1), Zone.Graveyard);
        game.Create(alice, Spirit("Dear Spirit Test", 5), Zone.Graveyard);

        var bolt = TestCards.PutInHand(
            game, alice, Card("Spirit Bolt Test", "Destroy target creature."));

        game.CastSpell(alice, bolt, [Target.ToPermanent(dying)]);
        Settle(game);

        Assert.Contains(
            game.State.GetPlayer(alice).Hand,
            id => game.State.GetObject(id).Card.Name == "Cheap Spirit Test");
        Assert.Contains(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Dear Spirit Test");
    }

    [Fact]
    public void Soulshift_with_nothing_in_reach_does_nothing()
    {
        // Same card, same board, one number different: with nothing legal to name the ability is
        // removed rather than resolving for no effect (CR 603.3d).
        var (game, alice, _) = InMainPhase();
        var dying = game.Create(alice, Spirit("Soulshift Cap Test", 5, "Soulshift 1"), Zone.Battlefield);
        game.Create(alice, Spirit("Dear Spirit Test", 5), Zone.Graveyard);

        var bolt = TestCards.PutInHand(
            game, alice, Card("Cap Bolt Test", "Destroy target creature."));

        game.CastSpell(alice, bolt, [Target.ToPermanent(dying)]);
        Settle(game);

        Assert.DoesNotContain(
            game.State.GetPlayer(alice).Hand,
            id => game.State.GetObject(id).Card.Name == "Dear Spirit Test");
        Assert.Contains(
            game.Log,
            e => e is TriggerRemovedForNoTargets);
    }

    // ---- Additional costs (CR 601.2f) ----------------------------------------

    [Fact]
    public void An_additional_cost_is_paid_before_the_spell_goes_on_the_stack()
    {
        var oracle = Kicked(
            "Additional Cost Test", "{1}",
            "As an additional cost to cast this spell, sacrifice a creature.\nDraw two cards.");

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, oracle);

        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, forest, "mana");

        var bear = game.Create(alice, TestCards.Creature("Cost Bear Test"), Zone.Battlefield);
        var handBefore = game.State.GetPlayer(alice).Hand.Count;

        game.CastSpell(
            alice, card, targets: null, variableValue: 0, tapToPay: null, modes: null,
            kicked: false, costPayment: [bear]);

        // CR 601.2f: the cost is paid as the spell is cast, so the creature is already gone while
        // the spell is still on the stack and could still be countered.
        // CR 400.7: the card in the graveyard is a new object, so it is found by name — the id
        // that was on the battlefield is not the id that landed.
        Assert.DoesNotContain(bear, game.State.Battlefield);
        Assert.Contains(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Cost Bear Test");

        Settle(game);
        Assert.Equal(handBefore - 1 + 2, game.State.GetPlayer(alice).Hand.Count);
    }

    [Fact]
    public void A_spell_whose_additional_cost_goes_unpaid_is_not_cast()
    {
        var oracle = Kicked(
            "Unpaid Cost Test", "{1}",
            "As an additional cost to cast this spell, sacrifice a creature.\nDraw two cards.");

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, oracle);

        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, forest, "mana");

        // No creature offered, and none to offer. CR 601.2h: the cost cannot be paid, so the
        // spell is not cast at all rather than being cast for free.
        Assert.Throws<InvalidOperationException>(() => game.CastSpell(alice, card));
        Assert.Contains(card, game.State.GetPlayer(alice).Hand);
    }

    // ---- Kicker (CR 702.33) --------------------------------------------------

    /// <summary>A kicker card, with a printed cost for the kicker to add to.</summary>
    /// <remarks>
    /// The mana value is separate from the printed cost because nothing in the test helpers
    /// parses one into the other, and some templates read it — cascade looks for a card cheaper
    /// than this one, and a spell that thinks it costs nothing finds nothing.
    /// </remarks>
    private static CardDefinition Kicked(
        string name, string manaCost, string oracleText, int cmc = 0) => new()
        {
            OracleId = "oracle-" + name.ToLowerInvariant().Replace(' ', '-'),
            Name = name,
            OracleText = oracleText,
            CardTypes = CardType.Instant,
            ManaCostRaw = manaCost,
            Cmc = cmc,
        };

    [Fact]
    public void A_kicked_spell_pays_more_and_does_more()
    {
        var bolt = Kicked(
            "Kicker Test", "{1}",
            "~ deals 2 damage to any target.\nKicker {1}\nIf this spell was kicked, you gain 3 life.");

        var (game, alice, bob) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, bolt);

        foreach (var _ in Enumerable.Range(0, 2))
        {
            var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
            game.ActivateAbility(alice, forest, "mana");
        }

        game.CastSpell(
            alice, card, [Target.ToPlayer(bob)], variableValue: 0, tapToPay: null, modes: null,
            kicked: true);

        Settle(game);

        Assert.Equal(18, game.State.GetPlayer(bob).Life);
        Assert.Equal(23, game.State.GetPlayer(alice).Life);
    }

    [Theory]
    [InlineData(true, 3)]
    [InlineData(false, 0)]
    public void A_permanent_remembers_across_resolution_that_it_was_kicked(bool kicked, int gain)
    {
        // CR 400.7 says a zone change makes a new object that remembers nothing; CR 607.2 makes
        // this the exception. The spell knew it was kicked and the permanent has to still know,
        // and the two are different objects with different ids - which is exactly the kind of
        // fact that goes missing without anything failing.
        var beast = new CardDefinition
        {
            OracleId = "oracle-kicked-beast-test",
            Name = "Kicked Beast Test",
            OracleText = "Kicker {1}" + (char)10
                + "When ~ enters, if it was kicked, you gain 3 life.",
            CardTypes = CardType.Creature,
            ManaCostRaw = "{1}",
            Cmc = 1,
            Power = 2,
            Toughness = 2,
        };

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, beast);

        foreach (var _ in Enumerable.Range(0, 2))
        {
            var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
            game.ActivateAbility(alice, forest, "mana");
        }

        var before = game.State.GetPlayer(alice).Life;

        game.CastSpell(
            alice, card, targets: null, variableValue: 0, tapToPay: null, modes: null,
            kicked: kicked);

        Settle(game);

        Assert.Contains(
            game.State.Battlefield,
            id => game.State.GetObject(id).Card.Name == "Kicked Beast Test");

        Assert.Equal(before + gain, game.State.GetPlayer(alice).Life);
    }

    [Theory]
    [InlineData(true, 4)]
    [InlineData(false, 0)]
    public void A_permanent_pays_the_cast_clause_only_if_it_was_actually_cast(
        bool cast, int gain)
    {
        // The same card, reaching the battlefield two ways. Cast from hand it was cast; put
        // there directly it was not, and the trigger fires either way - the clause is the only
        // thing between them.
        var card = new CardDefinition
        {
            OracleId = "oracle-cast-clause-test",
            Name = "Cast Clause Test",
            OracleText = "When ~ enters, if you cast it, you gain 4 life.",
            CardTypes = CardType.Creature,
            ManaCostRaw = "{1}",
            Cmc = 1,
            Power = 2,
            Toughness = 2,
        };

        var (game, alice, _) = InMainPhase();
        var before = game.State.GetPlayer(alice).Life;

        if (cast)
        {
            var inHand = TestCards.PutInHand(game, alice, card);
            var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
            game.ActivateAbility(alice, forest, "mana");
            game.CastSpell(alice, inHand, []);
        }
        else
        {
            game.Create(alice, card, Zone.Battlefield);
        }

        Settle(game);

        Assert.Contains(
            game.State.Battlefield, id => game.State.GetObject(id).Card.Name == "Cast Clause Test");

        Assert.Equal(before + gain, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void The_same_spell_unkicked_costs_less_and_skips_the_kicked_half()
    {
        var bolt = Kicked(
            "Unkicked Test", "{1}",
            "~ deals 2 damage to any target.\nKicker {1}\nIf this spell was kicked, you gain 3 life.");

        var (game, alice, bob) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, bolt);

        // One mana only — enough for the printed cost, not for the kicker.
        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, forest, "mana");

        game.CastSpell(alice, card, [Target.ToPlayer(bob)]);
        Settle(game);

        Assert.Equal(18, game.State.GetPlayer(bob).Life);
        Assert.Equal(20, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void Kicking_a_spell_that_has_no_kicker_is_refused()
    {
        var plain = Kicked("No Kicker Test", "{1}", "You gain 2 life.");

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, plain);
        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, forest, "mana");

        var ex = Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(
                alice, card, targets: null, variableValue: 0, tapToPay: null, modes: null,
                kicked: true));

        Assert.Contains("702.33a", ex.Message, StringComparison.Ordinal);
    }

    [Fact]
    public void A_kicked_clause_with_its_own_target_indexes_past_the_spells_own()
    {
        // The clause is parsed on its own, so its target numbering starts at zero and has to be
        // shifted by what the spell already asks for. Getting this wrong points the kicked half
        // at the spell's target and silently does the wrong thing.
        var bolt = Kicked(
            "Two Target Kicker Test", "{1}",
            "~ deals 2 damage to any target.\nKicker {1}\n"
                + "If this spell was kicked, tap target creature.");

        var (game, alice, bob) = InMainPhase();
        var bear = game.Create(bob, TestCards.Creature("Bear", 3, 3), Zone.Battlefield);
        var card = TestCards.PutInHand(game, alice, bolt);

        foreach (var _ in Enumerable.Range(0, 2))
        {
            var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
            game.ActivateAbility(alice, forest, "mana");
        }

        game.CastSpell(
            alice, card, [Target.ToPlayer(bob), Target.ToPermanent(bear)],
            variableValue: 0, tapToPay: null, modes: null, kicked: true);

        Settle(game);

        Assert.Equal(18, game.State.GetPlayer(bob).Life);
        Assert.True(game.State.GetObject(bear).Permanent!.IsTapped);
    }

    // ---- Conditional enters-tapped (CR 614.1c) -------------------------------

    /// <summary>A land whose arrival depends on the board it arrives into.</summary>
    private static CardDefinition SlowLand(string name, string oracleText) => new()
    {
        OracleId = "oracle-" + name.ToLowerInvariant().Replace(' ', '-'),
        Name = name,
        CardTypes = CardType.Land,
        Subtypes = ["Forest"],
        OracleText = oracleText,
    };

    [Fact]
    public void A_slow_land_arrives_tapped_only_while_the_condition_fails()
    {
        var land = SlowLand(
            "Slow Land Test", "~ enters tapped unless you control two or more other lands.");

        var (game, alice, _) = InMainPhase();

        // One other land: the condition fails, so the replacement applies and it comes in tapped.
        game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        var first = TestCards.PutInHand(game, alice, land);
        game.PlayLand(alice, first);
        Settle(game);

        var arrived = game.State.Battlefield
            .Select(game.State.GetObject)
            .Single(o => o.Card.Name == "Slow Land Test");

        Assert.True(arrived.Permanent!.IsTapped);
    }

    [Fact]
    public void The_same_land_arrives_untapped_once_the_condition_holds()
    {
        var land = SlowLand(
            "Fast Land Test", "~ enters tapped unless you control two or more other lands.");

        var (game, alice, _) = InMainPhase();

        foreach (var _ in Enumerable.Range(0, 2))
            game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, land);
        game.PlayLand(alice, card);
        Settle(game);

        var arrived = game.State.Battlefield
            .Select(game.State.GetObject)
            .Single(o => o.Card.Name == "Fast Land Test");

        // CR 614.1c: the replacement simply does not apply, so nothing has to untap it after.
        Assert.False(arrived.Permanent!.IsTapped);
    }

    [Fact]
    public void An_unconditional_enters_tapped_land_still_arrives_tapped()
    {
        var land = SlowLand("Plain Tapped Test", "~ enters tapped.");

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, land);
        game.PlayLand(alice, card);
        Settle(game);

        Assert.True(
            game.State.Battlefield
                .Select(game.State.GetObject)
                .Single(o => o.Card.Name == "Plain Tapped Test")
                .Permanent!.IsTapped);
    }

    [Fact]
    public void A_condition_the_engine_cannot_read_leaves_the_land_unread()
    {
        // Reading it loosely would produce a land that comes in untapped when it should not —
        // a strictly better card, and one nothing downstream could notice.
        var land = SlowLand(
            "Odd Land Test", "~ enters tapped unless you have descended this turn.");

        Assert.False(CardCompiler.Compile(land).IsComplete);
    }

    // ---- Auras and Equipment (CR 701.3c) -------------------------------------

    [Fact]
    public void An_equipment_gives_its_bearer_both_the_bonus_and_the_keyword()
    {
        var sword = Card(
            "Sword Test",
            "Equipped creature gets +2/+2 and has trample.\nEquip {2}",
            CardType.Artifact, subtypes: "Equipment");

        var (game, alice, _) = InMainPhase();
        var equipment = game.Create(alice, sword, Zone.Battlefield);
        var bearer = game.Create(alice, TestCards.Creature("Bearer", 2, 2), Zone.Battlefield);

        foreach (var _ in Enumerable.Range(0, 2))
        {
            var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
            game.ActivateAbility(alice, forest, "mana");
        }

        game.ActivateAbility(alice, equipment, "equip", [Target.ToPermanent(bearer)]);
        Settle(game);

        var armed = Characteristics.Of(game.State, Pool, game.State.GetObject(bearer));
        Assert.Equal(4, armed.Power);
        Assert.True(armed.Has(KeywordAbility.Trample));
    }

    [Fact]
    public void An_aura_that_only_grants_a_keyword_grants_it()
    {
        var wings = Card(
            "Wings Test",
