        Assert.Equal(30, game.State.GetPlayer(alice).Life);
    }

    // ---- Targeting a card in a graveyard (CR 404.2) --------------------------

    [Fact]
    public void Raising_a_creature_card_brings_it_back_to_hand()
    {
        var raise = Card("Raise Dead Test", "Return target creature card from your graveyard to your hand.");
        var (game, alice, _) = InMainPhase();

        var corpse = game.Create(alice, TestCards.Creature("Corpse", 2, 2), Zone.Graveyard);
        var handBefore = game.State.GetPlayer(alice).Hand.Count;
        var card = TestCards.PutInHand(game, alice, raise);

        game.CastSpell(alice, card, [Target.ToCard(corpse)]);
        Settle(game);

        // Held N, dealt the spell (N+1), cast it (N), returned the creature (N+1).
        Assert.Equal(handBefore + 1, game.State.GetPlayer(alice).Hand.Count);
        Assert.Contains(
            game.State.GetPlayer(alice).Hand,
            id => game.State.GetObject(id).Card.Name == "Corpse");
    }

    [Fact]
    public void Reanimation_puts_it_onto_the_battlefield_instead()
    {
