    [Fact]
    public void A_graveyard_target_will_not_accept_a_card_of_the_wrong_type()
    {
        var raise = Card("Typed Raise Test", "Return target creature card from your graveyard to your hand.");
        var (game, alice, _) = InMainPhase();

        var land = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Graveyard);
        var card = TestCards.PutInHand(game, alice, raise);

