    // ---- Effects over a whole group of permanents ----------------------------

    [Fact]
    public void A_wrath_destroys_every_creature_and_spares_the_indestructible()
    {
        var wrath = Card("Wrath Test", "Destroy all creatures.");
        var (game, alice, bob) = InMainPhase();

        var mine = game.Create(alice, TestCards.Creature("Mine", 2, 2), Zone.Battlefield);
        var theirs = game.Create(bob, TestCards.Creature("Theirs", 5, 5), Zone.Battlefield);
        var myr = game.Create(bob, TestCards.Indestructible("Myr"), Zone.Battlefield);
        var land = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, wrath);
        game.CastSpell(alice, card, []);
        Settle(game);

        Assert.DoesNotContain(mine, game.State.Battlefield);
        Assert.DoesNotContain(theirs, game.State.Battlefield);

        // CR 702.12b: indestructible survives, and the sweeper still resolved for everything else.
        Assert.Contains(myr, game.State.Battlefield);

        // It says creatures, so the land is untouched.
        Assert.Contains(land, game.State.Battlefield);
    }

    [Fact]
    public void Every_sweeper_verb_goes_through_the_same_effect()
    {
        var (game, alice, bob) = InMainPhase();

        var tapper = TestCards.PutInHand(
            game, alice, Card("Mass Tap Test", "Tap all creatures your opponents control."));

        var mine = game.Create(alice, TestCards.Creature("Mine", 2, 2), Zone.Battlefield);
        var theirs = game.Create(bob, TestCards.Creature("Theirs", 2, 2), Zone.Battlefield);

        game.CastSpell(alice, tapper, []);
        Settle(game);

        Assert.True(game.State.GetObject(theirs).Permanent!.IsTapped);
        Assert.False(game.State.GetObject(mine).Permanent!.IsTapped);

        // Exile ignores indestructible, where destroy does not.
        var myr = game.Create(bob, TestCards.Indestructible("Myr"), Zone.Battlefield);
        var exiler = TestCards.PutInHand(
            game, alice, Card("Mass Exile Test", "Exile all creatures."));

        game.CastSpell(alice, exiler, []);
        Settle(game);

        Assert.DoesNotContain(myr, game.State.Battlefield);
        Assert.Equal(3, game.State.Exile.Count);
    }

    [Fact]
    public void Damage_to_each_creature_is_damage_and_kills_only_what_it_should()
    {
        var pyroclasm = Card("Pyroclasm Test", "~ deals 2 damage to each creature.");
        var (game, alice, bob) = InMainPhase();

        var small = game.Create(alice, TestCards.Creature("Small", 2, 2), Zone.Battlefield);
        var big = game.Create(bob, TestCards.Creature("Big", 3, 3), Zone.Battlefield);
        var card = TestCards.PutInHand(game, alice, pyroclasm);

        game.CastSpell(alice, card, []);
        Settle(game);

        Assert.DoesNotContain(small, game.State.Battlefield);
        Assert.Contains(big, game.State.Battlefield);
        Assert.Equal(2, game.State.GetObject(big).Permanent!.DamageMarked);
    }

    [Fact]
    public void A_one_sided_sweeper_reads_whose_creatures_it_names()
    {
        var sweep = Card(
            "One Sided Test", "Creatures your opponents control get -2/-2 until end of turn.");

        var (game, alice, bob) = InMainPhase();
        var mine = game.Create(alice, TestCards.Creature("Mine", 2, 2), Zone.Battlefield);
        var small = game.Create(bob, TestCards.Creature("Small", 2, 2), Zone.Battlefield);
        var big = game.Create(bob, TestCards.Creature("Big", 4, 4), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, sweep);
        game.CastSpell(alice, card, []);
        Settle(game);

        // Toughness fell to zero, so state-based actions took it (CR 704.5f).
        Assert.DoesNotContain(small, game.State.Battlefield);
        Assert.Equal(2, Characteristics.Of(game.State, Pool, game.State.GetObject(big)).Power);
        Assert.Equal(2, Characteristics.Of(game.State, Pool, game.State.GetObject(mine)).Power);
    }

    [Fact]
    public void A_mass_pump_does_not_reach_a_creature_that_arrives_afterwards()
    {
        // "Until end of turn" fixes the set as it resolves (CR 611.2) — unlike a static ability,
        // which would keep catching new arrivals. The difference is the whole reason this is an
        // effect and the lords are statics.
        var rally = Card("Rally Test", "Creatures you control get +2/+2 until end of turn.");
        var (game, alice, _) = InMainPhase();

        var early = game.Create(alice, TestCards.Creature("Early", 1, 1), Zone.Battlefield);
        var card = TestCards.PutInHand(game, alice, rally);

        game.CastSpell(alice, card, []);
        Settle(game);

        Assert.Equal(3, Characteristics.Of(game.State, Pool, game.State.GetObject(early)).Power);

        var late = game.Create(alice, TestCards.Creature("Late", 1, 1), Zone.Battlefield);
        Settle(game);

        Assert.Equal(1, Characteristics.Of(game.State, Pool, game.State.GetObject(late)).Power);
    }

