    // ---- Look at the top, keep one (CR 701.20a) ------------------------------

    [Fact]
    public void Looking_at_the_top_and_keeping_one_buries_the_rest()
    {
        var impulse = Card(
            "Impulse Test",
            "Look at the top four cards of your library. Put one of them into your hand "
                + "and the rest on the bottom of your library in a random order.");

        var (game, alice, _) = InMainPhase();
        var handBefore = game.State.GetPlayer(alice).Hand.Count;
        var libraryBefore = game.State.GetPlayer(alice).Library.Count;
        var card = TestCards.PutInHand(game, alice, impulse);

        game.CastSpell(alice, card, []);
        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.LookAndTake });

        var choice = game.State.Choice!;
        Assert.Equal(4, choice.Options!.Count);

        var wanted = choice.Options[2];
        game.Choose(alice, [wanted.Id]);
        Settle(game);

        // Held N, was dealt the spell (N+1), cast it (N), took one of the four (N+1).
        Assert.Equal(handBefore + 1, game.State.GetPlayer(alice).Hand.Count);
        Assert.Contains(
            game.State.GetPlayer(alice).Hand,
            id => game.State.GetObject(id).Card.Name == wanted.Label);

        // The other three went to the bottom, so the library is one shorter and no cards vanished.
        Assert.Equal(libraryBefore - 1, game.State.GetPlayer(alice).Library.Count);
    }

    [Fact]
    public void Taking_none_of_them_is_a_legal_answer()
    {
        var impulse = Card(
            "Reluctant Impulse Test",
            "Look at the top two cards of your library. Put one of them into your hand "
                + "and the rest on the bottom of your library in a random order.");

        var (game, alice, _) = InMainPhase();
        var libraryBefore = game.State.GetPlayer(alice).Library.Count;
        var card = TestCards.PutInHand(game, alice, impulse);

        game.CastSpell(alice, card, []);
        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.LookAndTake });

        game.Choose(alice, []);
        Settle(game);

        // Nothing taken, nothing lost — both cards went to the bottom.
        Assert.Equal(libraryBefore, game.State.GetPlayer(alice).Library.Count);
    }

    // ---- Intervening-if triggers (CR 603.4) ----------------------------------

    [Fact]
    public void An_intervening_if_stops_the_trigger_from_firing_at_all()
    {
        var oracle = Card(
            "Intervening If Test",
            "At the beginning of your upkeep, if you control an artifact, you gain 3 life.",
            CardType.Enchantment);

        var (game, alice, _) = InMainPhase();
        game.Create(alice, oracle, Zone.Battlefield);

        // No artifact, so it does not trigger — not "triggers and does nothing".
        PassTo(game, 3, TurnStep.Draw);
        Assert.Equal(20, game.State.GetPlayer(alice).Life);
        Assert.DoesNotContain(game.Log, e => e is AbilityTriggered t && t.Text.Contains(
            "Intervening If Test", StringComparison.Ordinal));

        game.Create(alice, Card("Trinket Test", string.Empty, CardType.Artifact), Zone.Battlefield);

        PassTo(game, 5, TurnStep.Draw);
        Assert.Equal(23, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void The_condition_is_checked_again_on_resolution()
    {
        // CR 603.4 checks it twice, and the second check is the whole point: a permanent that was
        // there when the upkeep began and has since gone stops the ability doing anything. A card
        // that only checked once would be a different card, and which way it differs depends on
        // what happened in between.
        var oracle = Card(
            "Second Check Test",
            "At the beginning of your upkeep, if you control an artifact, you gain 3 life.",
            CardType.Enchantment);

        var (game, alice, _) = InMainPhase();
        game.Create(alice, oracle, Zone.Battlefield);
        var trinket = game.Create(
            alice, Card("Fragile Trinket Test", string.Empty, CardType.Artifact), Zone.Battlefield);

        // Stop in the upkeep with the trigger on the stack, then destroy the artifact before it
        // resolves.
        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber >= 3
                && game.State.CurrentStep == TurnStep.Upkeep
                && !game.State.Stack.IsEmpty);

        TestCards.PassUntil(game, () => game.State.Priority.Holder == alice);
        var bolt = TestCards.PutInHand(
            game, alice, Card("Trinket Bolt Test", "Destroy target artifact."));

        game.CastSpell(alice, bolt, [Target.ToPermanent(trinket)]);
        Settle(game);

        // It triggered, but the condition failed the second time — so no life.
        Assert.Equal(20, game.State.GetPlayer(alice).Life);
    }

    // ---- Conditional statics (CR 604.3) --------------------------------------

    [Fact]
    public void A_threshold_bonus_appears_and_disappears_with_the_condition()
    {
        // Not a trigger and not a one-shot: the bonus is there while the condition holds and gone
        // when it stops, with nothing remembering it either way. That is what recomputing
        // characteristics from scratch buys, and what the previous engine could not express.
        var brute = Card(
            "Threshold Test",
            "~ gets +3/+3 as long as there are three or more cards in your graveyard.",
            CardType.Creature, 2, 2);

        var (game, alice, _) = InMainPhase();
        var creature = game.Create(alice, brute, Zone.Battlefield);

        Assert.Equal(2, Characteristics.Of(game.State, Pool, game.State.GetObject(creature)).Power);

        // Fill the graveyard by casting three throwaway spells.
        foreach (var i in Enumerable.Range(0, 3))
        {
            TestCards.PassUntil(game, () => game.State.Priority.Holder == alice);
            var filler = TestCards.PutInHand(
                game, alice, Card($"Filler {i} Test", "You gain 1 life."));

            game.CastSpell(alice, filler, []);
            Settle(game);
        }

        Assert.Equal(3, game.State.GetPlayer(alice).Graveyard.Count);
        Assert.Equal(5, Characteristics.Of(game.State, Pool, game.State.GetObject(creature)).Power);
    }

    [Fact]
    public void A_condition_about_controlling_something_reads_the_negative_too()
    {
        // "You control no creatures" is the same question backwards, and getting the negation
        // wrong reads correctly and plays inverted — so both directions are checked against the
        // same board.
        var loner = Card(
            "Loner Test",
            "~ gets +2/+2 as long as you control no artifacts.",
            CardType.Creature, 1, 1);

        var (game, alice, _) = InMainPhase();
        var creature = game.Create(alice, loner, Zone.Battlefield);

        Assert.Equal(3, Characteristics.Of(game.State, Pool, game.State.GetObject(creature)).Power);

        var trinket = game.Create(
            alice, Card("Trinket Test", string.Empty, CardType.Artifact), Zone.Battlefield);

        Assert.Equal(1, Characteristics.Of(game.State, Pool, game.State.GetObject(creature)).Power);
        Assert.NotEqual(default, trinket);
    }

    [Fact]
    public void A_condition_about_life_can_ask_about_an_opponent()
    {
        var predator = Card(
            "Predator Test",
            "~ gets +3/+3 as long as an opponent has 15 or less life.",
            CardType.Creature, 2, 2);

        var (game, alice, bob) = InMainPhase();
        var creature = game.Create(alice, predator, Zone.Battlefield);

        Assert.Equal(2, Characteristics.Of(game.State, Pool, game.State.GetObject(creature)).Power);

        var bolt = TestCards.PutInHand(
            game, alice, Card("Big Bolt Test", "~ deals 6 damage to target player."));

        game.CastSpell(alice, bolt, [Target.ToPlayer(bob)]);
        Settle(game);

        Assert.Equal(14, game.State.GetPlayer(bob).Life);
        Assert.Equal(5, Characteristics.Of(game.State, Pool, game.State.GetObject(creature)).Power);
    }

    [Fact]
    public void A_bonus_that_only_applies_on_your_turn_goes_away_on_theirs()
    {
        var duellist = Card(
            "Daytime Test", "During your turn, ~ has first strike.", CardType.Creature, 2, 2);

        var (game, alice, bob) = InMainPhase();
        var creature = game.Create(alice, duellist, Zone.Battlefield);

        Assert.True(Characteristics.Of(game.State, Pool, game.State.GetObject(creature))
            .Has(KeywordAbility.FirstStrike));

        TestCards.PassUntil(game, () => game.State.ActivePlayerId == bob);

        Assert.False(Characteristics.Of(game.State, Pool, game.State.GetObject(creature))
            .Has(KeywordAbility.FirstStrike));
    }

    // ---- Uncounterable spells (CR 701.6a) ------------------------------------

    [Fact]
    public void A_spell_that_cannot_be_countered_resolves_anyway()
    {
        var stubborn = Card(
            "Uncounterable Test", "This spell can't be countered.\nYou gain 5 life.");

        var (game, alice, bob) = InMainPhase();

        TestCards.PassUntil(game, () => game.State.ActivePlayerId == bob
            && game.State.CurrentStep == TurnStep.PrecombatMain
            && game.State.Priority.Holder == bob);

        var card = TestCards.PutInHand(game, bob, stubborn);
        var onStack = game.CastSpell(bob, card, []);

        TestCards.PassUntil(game, () => game.State.Priority.Holder == alice);
        var counter = TestCards.PutInHand(
            game, alice, Card("Plain Counter Test", "Counter target spell."));

        // Targeting is legal — the spell is a legal target, it just cannot be countered
        // (CR 701.6a is about the *effect*, not about targeting).
        game.CastSpell(alice, counter, [Target.ToSpell(onStack)]);
        Settle(game);

        Assert.Equal(25, game.State.GetPlayer(bob).Life);
    }

    [Fact]
    public void The_same_spell_without_that_line_is_countered()
    {
        var ordinary = Card("Counterable Test", "You gain 5 life.");

        var (game, alice, bob) = InMainPhase();

        TestCards.PassUntil(game, () => game.State.ActivePlayerId == bob
            && game.State.CurrentStep == TurnStep.PrecombatMain
            && game.State.Priority.Holder == bob);

        var card = TestCards.PutInHand(game, bob, ordinary);
        var onStack = game.CastSpell(bob, card, []);

        TestCards.PassUntil(game, () => game.State.Priority.Holder == alice);
        var counter = TestCards.PutInHand(
            game, alice, Card("Second Counter Test", "Counter target spell."));

        game.CastSpell(alice, counter, [Target.ToSpell(onStack)]);
        Settle(game);

        Assert.Equal(20, game.State.GetPlayer(bob).Life);
    }

    // ---- The "it" pronoun ----------------------------------------------------

    [Fact]
    public void It_means_the_target_the_sentence_before_named()
    {
        var trick = Card(
            "Pronoun Test", "Tap target creature. Destroy it.");

        var (game, alice, bob) = InMainPhase();
        var bear = game.Create(bob, TestCards.Creature("Bear", 2, 2), Zone.Battlefield);
        var other = game.Create(bob, TestCards.Creature("Other", 2, 2), Zone.Battlefield);
        var card = TestCards.PutInHand(game, alice, trick);

        game.CastSpell(alice, card, [Target.ToPermanent(bear)]);
        Settle(game);

        // One target, two effects — and the second found the same creature rather than asking
        // for another.
        Assert.DoesNotContain(bear, game.State.Battlefield);
        Assert.Contains(other, game.State.Battlefield);
    }

    [Fact]
    public void A_pronoun_with_nothing_to_refer_to_leaves_the_card_unread()
    {
        // "It" on a card that has targeted nothing means something else entirely — a token just
        // created, a card just revealed — and guessing would aim the effect at whatever happened
        // to be last.
        var odd = Card("Dangling Pronoun Test", "Destroy it.");

        Assert.False(CardCompiler.Compile(odd).IsComplete);
    }

    // ---- Coin flips (CR 705.2) -----------------------------------------------

    [Fact]
    public void A_coin_flip_runs_one_branch_or_the_other_and_never_both()
    {
        var gamble = Card(
            "Coin Test",
            "Flip a coin. If you win the flip, you gain 4 life. If you lose the flip, you lose 2 life.");

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, gamble);

        game.CastSpell(alice, card, []);
        Settle(game);

        // The game is seeded, so the outcome is fixed for this run — but the test asserts the
        // *property* rather than the seed's answer, because a test that encodes which way the
        // coin came down would break the day the shuffle algorithm changed.
        var life = game.State.GetPlayer(alice).Life;
        Assert.True(life is 24 or 18, $"life was {life}");

        // Exactly one flip, and it is in the log as an outcome rather than as a roll.
        Assert.Single(game.Log, e => e is CoinFlipped);
    }

    [Fact]
    public void A_deferred_question_nested_inside_another_branch_is_found_and_run()
    {
        // This used to be refused. MayPay, ChooseAndMove and FlipCoin each carry an index back to
        // themselves, and the engine resolved that against the ability's *top-level* effects — so
        // nested inside a wrapper, the index named the wrapper and the lookup found the wrong
        // record or none. Refusing the card was the honest answer to that.
        //
        // The lookup now walks the whole effect tree, so the nesting is fine and the card is
        // claimed. The test is kept pointing at the same shape, asserting the capability instead
        // of the limitation.
        var nested = Card(
            "Nested Question Test",
            "You may pay {1}. If you do, sacrifice a creature you control.");

        var compiled = CardCompiler.Compile(nested);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var doomed = game.Create(alice, TestCards.Creature("Nested Bear Test"), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, nested);

        foreach (var _ in Enumerable.Range(0, 2))
        {
            var land = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
            game.ActivateAbility(alice, land, "mana");
        }

        game.CastSpell(alice, card, targets: null);
        Settle(game);

        Assert.DoesNotContain(doomed, game.State.Battlefield);
    }

    [Fact]
    public void The_flip_that_happened_is_what_a_replay_reads()
    {
        // The same rule the shuffle follows: the log records what came down, not the seed that
        // produced it, so a stored game cannot come out differently on another machine.
        var gamble = Card(
            "Replayed Coin Test",
            "Flip a coin. If you win the flip, you gain 4 life. If you lose the flip, you lose 2 life.");

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, gamble);

        game.CastSpell(alice, card, []);
        Settle(game);

        var flipped = game.Log.OfType<CoinFlipped>().Single();
        var expected = flipped.Won ? 24 : 18;

        Assert.Equal(expected, game.State.GetPlayer(alice).Life);
        Assert.Equal(expected, GameReducer.Replay(game.Log).GetPlayer(alice).Life);
    }

    // ---- The counterspell tax (CR 601.2b) ------------------------------------

    [Fact]
    public void A_taxing_counterspell_asks_the_other_player_and_counters_when_they_decline()
    {
        var leak = Card(
            "Mana Leak Test", "Counter target spell unless its controller pays {1}.");

        var (game, alice, bob) = InMainPhase();

        // Bob casts something for Alice to answer.
        TestCards.PassUntil(game, () => game.State.ActivePlayerId == bob
            && game.State.CurrentStep == TurnStep.PrecombatMain
            && game.State.Priority.Holder == bob);

        // Floated up front, so this test is about the decline and not about where the mana came
        // from. An offer he plainly could not take - no pool and no untapped land - would be
        // answered for him rather than put to him (CR 118.3).
        var bobsForest = game.Create(bob, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(bob, bobsForest, "mana");

        var threat = TestCards.PutInHand(game, bob, Card("Threat Test", "You gain 6 life."));

        // A card becomes a new object when it moves to the stack (CR 400.7), so the id to target
        // is the one casting returns — not the one it had in hand.
        var onStack = game.CastSpell(bob, threat, []);

        TestCards.PassUntil(game, () => game.State.Priority.Holder == alice);
        var counter = TestCards.PutInHand(game, alice, leak);
        game.CastSpell(alice, counter, [Target.ToSpell(onStack)]);

        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.OptionalPayment });

        // The offer goes to *Bob* — it is his spell being taxed, not Alice's.
        Assert.Equal(bob, game.State.Choice!.PlayerId);

        game.Choose(bob, ["no"]);
        Settle(game);

        // He declined, so the spell was countered and he gained nothing.
        Assert.Equal(20, game.State.GetPlayer(bob).Life);
        Assert.Empty(game.State.Stack);
    }

    [Fact]
    public void Paying_the_tax_lets_the_spell_through()
    {
        var leak = Card(
            "Paid Leak Test", "Counter target spell unless its controller pays {1}.");

        var (game, alice, bob) = InMainPhase();

        TestCards.PassUntil(game, () => game.State.ActivePlayerId == bob
            && game.State.CurrentStep == TurnStep.PrecombatMain
            && game.State.Priority.Holder == bob);

        // Bob floats the mana before casting, which is one of the two ways to pay now: mana
        // already in the pool still answers the question. Tapping the land after being asked is
        // the other, and CR 605.3a is why - see the mid-resolution section further down.
        var forest = game.Create(bob, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(bob, forest, "mana");

        var threat = TestCards.PutInHand(game, bob, Card("Second Threat Test", "You gain 6 life."));

        // A card becomes a new object when it moves to the stack (CR 400.7), so the id to target
        // is the one casting returns — not the one it had in hand.
        var onStack = game.CastSpell(bob, threat, []);

        TestCards.PassUntil(game, () => game.State.Priority.Holder == alice);
        var counter = TestCards.PutInHand(game, alice, leak);
        game.CastSpell(alice, counter, [Target.ToSpell(onStack)]);

        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.OptionalPayment });
        game.Choose(bob, ["yes"]);
        Settle(game);

        Assert.Equal(26, game.State.GetPlayer(bob).Life);
    }

    // ---- Optional payments (CR 601.2b) ---------------------------------------

    [Fact]
    public void An_optional_payment_asks_and_runs_the_branch_the_answer_names()
    {
        var oracle = Card(
            "May Pay Test",
            "At the beginning of your upkeep, you may pay {1}. If you do, you gain 4 life.",
            CardType.Enchantment);

        var (game, alice, _) = InMainPhase();
        game.Create(alice, oracle, Zone.Battlefield);

        // Mana has to be floating before the question is asked: this engine cannot activate a
        // mana ability inside a resolution, so the player floats it the way they would for any
        // other cost.
        var land = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);

        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber >= 3 && game.State.CurrentStep == TurnStep.Upkeep);

        game.ActivateAbility(alice, land, "mana");
        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.OptionalPayment });

        var choice = game.State.Choice!;
        Assert.Equal(alice, choice.PlayerId);

        game.Choose(alice, ["yes"]);
        Settle(game);

        Assert.Equal(24, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void An_offer_with_no_cost_is_the_same_machinery_with_nothing_to_pay()
    {
        var oracle = Card(
            "May Draw Test",
            "At the beginning of your upkeep, you may draw a card.",
            CardType.Enchantment);

        var (game, alice, _) = InMainPhase();
        game.Create(alice, oracle, Zone.Battlefield);

        TestCards.PassUntil(
            game,
            () => game.State.Choice is { Kind: ChoiceKind.OptionalPayment }
                || game.State.TurnNumber >= 4);

        var choice = game.State.Choice!;
        Assert.Equal(alice, choice.PlayerId);

        var before = game.State.GetPlayer(alice).Hand.Count;
        game.Choose(alice, ["yes"]);
        Settle(game);

        Assert.Equal(before + 1, game.State.GetPlayer(alice).Hand.Count);
    }

    [Fact]
    public void A_target_phrase_containing_the_word_or_is_not_always_an_alternation()
    {
        // "Target attacking or blocking creature" is one phrase with a two-word adjective, not a
        // choice between "attacking" and "blocking creature". Splitting on "or" first read it as
        // the latter, produced no phrase at all, and lost every card that names a creature in
        // combat — while "target artifact or enchantment" genuinely is an alternation.
        var bolt = Card("Combat Bolt Test", "~ deals 2 damage to target attacking or blocking creature.");
        var split = Card("Disenchant Test", "Destroy target artifact or enchantment.");

        Assert.True(CardCompiler.Compile(bolt).IsComplete);
        Assert.True(CardCompiler.Compile(split).IsComplete);

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, TestCards.Creature("Attacker", 2, 2), Zone.Battlefield);
        var idle = game.Create(bob, TestCards.Creature("Idle", 2, 2), Zone.Battlefield);
        var card = TestCards.PutInHand(game, alice, bolt);

        // Nothing is attacking yet, so there is no legal target and the cast is refused.
        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, card, [Target.ToPermanent(idle)]));

        Assert.Contains(attacker, game.State.Battlefield);
    }

    [Fact]
    public void Declining_an_optional_payment_runs_the_other_branch()
    {
        var oracle = Card(
            "Upkeep Toll Test",
            "At the beginning of your upkeep, you may pay {1}. If you don't, sacrifice it.",
            CardType.Enchantment);

        var (game, alice, _) = InMainPhase();
        var enchantment = game.Create(alice, oracle, Zone.Battlefield);
        var land = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);

        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber >= 3 && game.State.CurrentStep == TurnStep.Upkeep);

        game.ActivateAbility(alice, land, "mana");
        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.OptionalPayment });

        game.Choose(alice, ["no"]);
        Settle(game);

        Assert.DoesNotContain(enchantment, game.State.Battlefield);
    }

    [Fact]
    public void An_offer_the_player_plainly_cannot_take_is_not_put_to_them()
    {
        // A question with one possible answer is not a question, and stopping the game to ask it
        // is worse than answering it: the player has no mana and nothing to decide.
        var oracle = Card(
            "Unpayable Toll Test",
            "At the beginning of your upkeep, you may pay {5}. If you don't, sacrifice it.",
            CardType.Enchantment);

        var (game, alice, _) = InMainPhase();
        var enchantment = game.Create(alice, oracle, Zone.Battlefield);

        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber >= 3 && game.State.CurrentStep == TurnStep.Draw);

        Assert.DoesNotContain(enchantment, game.State.Battlefield);
    }

    // ---- Tokens (CR 111.1) ---------------------------------------------------

    [Fact]
    public void A_described_token_arrives_with_the_size_colour_type_and_keyword_it_names()
    {
        var call = Card(
            "Token Test",
            "Create two 1/1 white Soldier creature tokens with flying.");

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, call);

        game.CastSpell(alice, card, []);
        Settle(game);

        Assert.Equal(2, game.State.Battlefield.Count);

        var token = game.State.GetObject(game.State.Battlefield[0]);
        Assert.Equal("Soldier", token.Card.Name);
        Assert.Equal(1, token.Card.Power);
        Assert.Contains("Soldier", token.Card.Subtypes);
        Assert.Contains(ManaColor.White, token.Card.ColorIdentity);
        Assert.True(
            Characteristics.Of(game.State, Pool, token).Has(KeywordAbility.Flying));
    }

    [Fact]
    public void A_treasure_can_actually_be_cracked_for_mana()
    {
        // The commonest token in the game. Its ability is defined by name rather than printed on
        // the card that makes it (CR 111.9), so nothing about the maker says whether it works —
        // only playing one does.
        var sleuth = Card("Treasure Maker Test", "Create a Treasure token.");

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, sleuth);

        game.CastSpell(alice, card, []);
        Settle(game);

        var treasure = game.State.Battlefield
            .Select(game.State.GetObject)
            .Single(o => o.Card.Name == "Treasure");

        // "Add one mana of any color" is one printed ability offering a choice, and the engine
        // has nowhere to ask a question inside a mana ability — they do not use the stack
        // (CR 605.3b). So it compiles to one ability per colour, and a player picking a button
        // reaches the same board as one picking a colour. Deliberate, and visible here.
        var abilities = Game.ActivatedAbilitiesOf(game.State, Pool, treasure);
        Assert.Equal(5, abilities.Count);

        game.ActivateAbility(alice, treasure.Id, abilities[0].Id);

        // Sacrificed for the mana, and the mana is in the pool.
        Assert.DoesNotContain(treasure.Id, game.State.Battlefield);
        Assert.False(game.State.GetPlayer(alice).ManaPool.IsEmpty);
    }

    [Fact]
    public void A_clue_can_be_cracked_to_draw()
    {
        var sleuth = Card("Clue Maker Test", "Investigate.");

        var (game, alice, _) = InMainPhase();
        var handBefore = game.State.GetPlayer(alice).Hand.Count;
        var card = TestCards.PutInHand(game, alice, sleuth);

        game.CastSpell(alice, card, []);
        Settle(game);

        var clue = game.State.Battlefield
            .Select(game.State.GetObject)
            .Single(o => o.Card.Name == "Clue");

        foreach (var _ in Enumerable.Range(0, 2))
        {
            var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
            game.ActivateAbility(alice, forest, "mana");
        }

        var ability = Game.ActivatedAbilitiesOf(game.State, Pool, clue).Single();
        game.ActivateAbility(alice, clue.Id, ability.Id);
        Settle(game);

        // Held N, was dealt the maker (N+1), cast it (N), cracked the Clue and drew (N+1).
        Assert.Equal(handBefore + 1, game.State.GetPlayer(alice).Hand.Count);
        Assert.DoesNotContain(clue.Id, game.State.Battlefield);
    }

    [Fact]
    public void A_token_with_a_quoted_ability_actually_has_that_ability()
    {
        // A token *is* a card definition, so the quoted text becomes its rules text and the pool
        // compiles it on demand like any other card. No new machinery — which is the payoff for
        // having built tokens as cards rather than as a special case.
        var summon = Card(
            "Devil Token Test",
            "Create a 1/1 red Devil creature token with \"When this creature dies, "
                + "it deals 1 damage to any target.\"");

        var (game, alice, bob) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, summon);

        game.CastSpell(alice, card, []);
        Settle(game);

        var devil = game.State.Battlefield
            .Select(game.State.GetObject)
            .Single(o => o.Card.Name == "Devil");

        // The trigger is on the token, from the text it was created with.
        Assert.Single(Pool.TriggersOf(devil.Card));

        game.MarkDamage(devil.Id, 1);
        TestCards.PassUntil(game, () => game.State.Choice is not null);

        // The option carries the target's id, so it is picked by that rather than by its label —
        // the label exists to be unambiguous to a person, not to a test.
        var choice = game.State.Choice!;
        Assert.Equal(ChoiceKind.ChooseTriggerTargets, choice.Kind);

        game.Choose(
            alice,
            [choice.Options!.Single(o => o.Id == $"player:{bob:N}").Id]);

        Settle(game);

        Assert.Equal(19, game.State.GetPlayer(bob).Life);
    }

    [Fact]
    public void A_token_ability_printed_as_its_own_sentence_reaches_the_token()
    {
        // "Create N tokens. They have "X."" is the same instruction as "with "X."", printed the
        // way most of the Eldrazi do. It was unread not because any word in it was unknown - both
        // sentences read on their own - but because nothing joined them, so the ability had
        // nothing to attach to and the whole line went unread with it.
        var brood = Card(
            "Spawn Maker Test",
            "Create two 0/1 colorless Eldrazi Spawn creature tokens. "
                + "They have \"Sacrifice this creature: Add {C}.\"");

        var compiled = CardCompiler.Compile(brood);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        game.CastSpell(alice, TestCards.PutInHand(game, alice, brood), []);
        Settle(game);

        var spawn = game.State.Battlefield
            .Select(game.State.GetObject)
            .Where(o => o.Card.Name == "Eldrazi Spawn")
            .ToList();

        Assert.Equal(2, spawn.Count);

        // Both tokens carry the ability, not just the first: the fold happens once and the count
        // is read from the same sentence.
        foreach (var token in spawn)
            Assert.NotEmpty(Pool.ActivatedOf(token.Card));
    }

    [Fact]
    public void A_token_whose_quoted_ability_cannot_be_read_leaves_the_line_unread()
    {
        // Otherwise it would arrive as a vanilla creature of the right size — which looks right
        // on the board and plays as a different card. The unreadable clause is invented, so
        // that implementing a real mechanic can never turn this test green by accident.
        var summon = Card(
            "Unreadable Token Test",
            "Create a 1/1 red Devil creature token with \"When this creature dies, "
                + "frobnicate target creature.\"");

        Assert.False(CardCompiler.Compile(summon).IsComplete);
    }

    /// <summary>
    /// A granted keyword the flags cannot carry becomes a line of the token's own text.
    /// </summary>
    /// <remarks>
    /// Half-implementing it would be worse than not reading it - a 1/1 with "banding" compiled as
    /// a plain 1/1 looks finished and plays as a different card - and for a long while the reader
    /// therefore refused every word missing from its keyword table. It did not have to: a token
    /// <em>is</em> a card definition, the compiler has read a bare keyword line on a card's own
    /// text since long before this, and a printed token card says "Banding" in its text box
    /// exactly that way. So the word goes where the quoted abilities go, and the promise is kept
    /// by the same probe: the minted token has to compile completely or the line stays unread.
    /// <para>
    /// Toxic is the word that pays for this - 15 corpus cards mint a Phyrexian Mite "with toxic 1
    /// and 'this creature can't block'", and toxic has never been a flag in this engine. It is a
    /// trigger the compiler builds from the word, which no keyword table could have held.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_token_keyword_the_flags_cannot_carry_becomes_a_line_of_the_tokens_own_text()
    {
        var odd = Card("Odd Token Test", "Create a 1/1 white Soldier creature token with banding.");

        var compiled = CardCompiler.Compile(odd);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        game.CastSpell(alice, TestCards.PutInHand(game, alice, odd), []);
        Settle(game);

        var soldier = game.State.Battlefield
            .Single(id => game.State.GetObject(id).Card.Name == "Soldier");

        // Off the computed characteristics, which is the only reading that means anything: the
        // word reached the token as rules text and came back out as the keyword.
        Assert.True(Characteristics.Of(game.State, Pool, game.State.GetObject(soldier))
            .Has(KeywordAbility.Banding));

        // And the refusal is still there for a word nothing can read. Invented, so that
        // implementing a real mechanic can never turn this half green by accident.
        var nonsense = Card(
            "Odder Token Test",
            "Create a 1/1 white Soldier creature token with frobnication.");

        Assert.False(CardCompiler.Compile(nonsense).IsComplete);
    }

    [Fact]
    public void Investigate_makes_a_Clue_because_that_is_all_it_means()
    {
        var sleuth = Card("Investigate Test", "Investigate.");
        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, sleuth);

        game.CastSpell(alice, card, []);
        Settle(game);

        Assert.Single(game.State.Battlefield);
        Assert.Equal("Clue", game.State.GetObject(game.State.Battlefield[0]).Card.Name);
    }

    [Fact]
    public void A_token_made_by_a_trigger_is_seen_by_the_triggers_watching_for_arrivals()
    {
        // The bug this covers: a token is created on the battlefield (CR 111.1) and never moves
        // there, so an "enters" trigger watching only for a move never saw one.
        var watcher = Card(
            "Token Watcher Test",
            "Whenever another creature you control enters, you gain 1 life.",
            CardType.Creature, 1, 1);

        var (game, alice, _) = InMainPhase();
        game.Create(alice, watcher, Zone.Battlefield);

        var call = TestCards.PutInHand(
            game, alice, Card("Muster Test", "Create a 1/1 white Soldier creature token."));

        game.CastSpell(alice, call, []);
        Settle(game);

        Assert.Equal(21, game.State.GetPlayer(alice).Life);
    }

    // ---- Activation costs beyond mana (CR 601.2f) ----------------------------

    [Fact]
    public void Paying_life_as_a_cost_takes_the_life_and_is_refused_when_it_cannot_be_paid()
    {
        var pump = Card(
            "Life Cost Test",
