    // ---- Evasion keywords (CR 509.1b) ----------------------------------------

    /// <summary>Why the blocker may not block the attacker, or null if it may.</summary>
    private static string? WhyNoBlock(Game game, ObjectId blocker, ObjectId attacker, Guid defender) =>
        CombatRules.CannotBlock(
            game.State, Pool, game.State.GetObject(blocker), game.State.GetObject(attacker),
            defender);

    [Fact]
    public void Fear_admits_only_artifact_and_black_blockers()
    {
        var scary = Card(
            "Fear Test", "Fear", CardType.Creature, 2, 2, keywords: KeywordAbility.Fear);

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, scary, Zone.Battlefield);

        var green = game.Create(bob, Coloured("Green Blocker", ManaColor.Green), Zone.Battlefield);
        var black = game.Create(bob, Coloured("Black Blocker", ManaColor.Black), Zone.Battlefield);
        var golem = game.Create(
            bob,
            Card("Golem Test", string.Empty, CardType.Creature | CardType.Artifact, 2, 2),
            Zone.Battlefield);

        Assert.NotNull(WhyNoBlock(game, green, attacker, bob));
        Assert.Null(WhyNoBlock(game, black, attacker, bob));
        Assert.Null(WhyNoBlock(game, golem, attacker, bob));
    }

    [Fact]
    public void A_creature_that_blocks_only_fliers_cannot_stop_anything_else()
    {
        // The mirror of reach, and untested in both directions: the wall stops a flier and lets
        // everything on the ground walk past it.
        // Reach as well as the restriction: a creature that may block only fliers still needs a
        // way to block one, which is why the printed cards with this line all carry flying or
        // reach. Without it the first rule refuses the block and the restriction is never asked.
        var wall = Card(
            "Cloud Wall Test", "Reach\n~ can block only creatures with flying.",
            CardType.Creature, 0, 4,
            keywords: KeywordAbility.BlocksOnlyFlying | KeywordAbility.Reach);

        var (game, alice, bob) = InMainPhase();
        var blocker = game.Create(bob, wall, Zone.Battlefield);

        var footman = game.Create(alice, TestCards.Creature("Ground Footman Test", 2, 2), Zone.Battlefield);
        var drake = game.Create(
            alice,
            Card("Cloud Drake Test", "Flying", CardType.Creature, 2, 2, keywords: KeywordAbility.Flying),
            Zone.Battlefield);

        Assert.NotNull(WhyNoBlock(game, blocker, footman, bob));
        Assert.Null(WhyNoBlock(game, blocker, drake, bob));
    }

    /// <summary>Every landwalk, against its own land type (CR 702.14).</summary>
    /// <remarks>
    /// `Landwalks` is five near-identical arms and only two of them - swampwalk and islandwalk -
    /// were ever reached by a test. Swapping any of the other three for a keyword nothing has
    /// changed no result, which is the same shape as reach against flying: a list of alternatives
    /// where the tested entry stands in for the rest and nothing checks that it can.
    /// </remarks>
    [Theory]
    [InlineData(KeywordAbility.Swampwalk, "Swamp")]
    [InlineData(KeywordAbility.Forestwalk, "Forest")]
    [InlineData(KeywordAbility.Islandwalk, "Island")]
    [InlineData(KeywordAbility.Mountainwalk, "Mountain")]
    [InlineData(KeywordAbility.Plainswalk, "Plains")]
    public void Each_landwalk_is_unblockable_over_its_own_land(KeywordAbility walk, string landType)
    {
        var walker = Card(
            $"{landType} Walker Test", walk.ToString(), CardType.Creature, 2, 2, keywords: walk);

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, walker, Zone.Battlefield);
        var blocker = game.Create(bob, TestCards.Creature($"{landType} Blocker Test", 2, 2), Zone.Battlefield);

        // Nothing to walk over yet, so the block is fine.
        Assert.Null(WhyNoBlock(game, blocker, attacker, bob));

        game.Create(bob, TestCards.BasicLand(landType), Zone.Battlefield);

        var refused = WhyNoBlock(game, blocker, attacker, bob);
        Assert.NotNull(refused);
        Assert.Contains("702.14", refused, StringComparison.Ordinal);
    }

    [Fact]
    public void Horsemanship_admits_only_other_horsemen()
    {
        // CR 702.5b: flying's older cousin, and the only evasion keyword the suite had never
        // named once. The engine implements it; nothing asked it anything.
        var rider = Card(
            "Horseman Test", "Horsemanship", CardType.Creature, 2, 2,
            keywords: KeywordAbility.Horsemanship);

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, rider, Zone.Battlefield);

        var footman = game.Create(bob, TestCards.Creature("Footman Test", 2, 2), Zone.Battlefield);
        var mounted = game.Create(
            bob,
            Card("Other Horseman Test", "Horsemanship", CardType.Creature, 2, 2,
                keywords: KeywordAbility.Horsemanship),
            Zone.Battlefield);

        Assert.NotNull(WhyNoBlock(game, footman, attacker, bob));
        Assert.Null(WhyNoBlock(game, mounted, attacker, bob));
    }

    [Fact]
    public void Intimidate_admits_artifacts_and_creatures_sharing_a_colour()
    {
        // CR 702.13b: fear by colour. The colour half needs a coloured attacker to mean anything,
        // which is why the keyword needs a card built rather than the plain fixture.
        var sneak = new CardDefinition
        {
            OracleId = "oracle-intimidate-test",
            Name = "Intimidate Test",
            CardTypes = CardType.Creature,
            Power = 2,
            Toughness = 2,
            Colors = [ManaColor.Red],
            ColorIdentity = [ManaColor.Red],
            Keywords = KeywordAbility.Intimidate,
        };

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, sneak, Zone.Battlefield);

        var green = game.Create(bob, Coloured("Intimidate Green Test", ManaColor.Green), Zone.Battlefield);
        var red = game.Create(bob, Coloured("Intimidate Red Test", ManaColor.Red), Zone.Battlefield);
        var golem = game.Create(
            bob,
            Card("Intimidate Golem Test", string.Empty, CardType.Creature | CardType.Artifact, 2, 2),
            Zone.Battlefield);

        Assert.NotNull(WhyNoBlock(game, green, attacker, bob));
        Assert.Null(WhyNoBlock(game, red, attacker, bob));
        Assert.Null(WhyNoBlock(game, golem, attacker, bob));
    }

    [Fact]
    public void Shadow_separates_the_two_halves_of_the_board_in_both_directions()
    {
        var ghost = Card(
            "Shadow Test", "Shadow", CardType.Creature, 2, 2, keywords: KeywordAbility.Shadow);

        var (game, alice, bob) = InMainPhase();
        var shadowed = game.Create(alice, ghost, Zone.Battlefield);
        var ordinary = game.Create(bob, TestCards.Creature("Ordinary", 2, 2), Zone.Battlefield);
        var otherGhost = game.Create(
            bob,
            Card("Shadow Blocker Test", "Shadow", CardType.Creature, 2, 2,
                keywords: KeywordAbility.Shadow),
            Zone.Battlefield);

        // A creature without shadow cannot block one with it...
        Assert.NotNull(WhyNoBlock(game, ordinary, shadowed, bob));
        Assert.Null(WhyNoBlock(game, otherGhost, shadowed, bob));

        // ...and a creature with shadow cannot block one without it, which is what makes shadow
        // different from every other evasion keyword.
        var mundane = game.Create(alice, TestCards.Creature("Mundane", 2, 2), Zone.Battlefield);
        Assert.NotNull(WhyNoBlock(game, otherGhost, mundane, bob));
    }

    [Fact]
    public void Skulk_reads_power_as_it_stands_and_not_as_printed()
    {
        var sneak = Card(
            "Skulk Test", "Skulk", CardType.Creature, 2, 2, keywords: KeywordAbility.Skulk);

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, sneak, Zone.Battlefield);
        var small = game.Create(bob, TestCards.Creature("Small", 1, 1), Zone.Battlefield);
        var big = game.Create(bob, TestCards.Creature("Big", 4, 4), Zone.Battlefield);

        Assert.Null(WhyNoBlock(game, small, attacker, bob));
        Assert.NotNull(WhyNoBlock(game, big, attacker, bob));

        // A lord raising the small blocker's power takes the block away, because skulk compares
        // current power (CR 702.17b) rather than what is printed.
        game.Create(
            bob,
            Card("Skulk Lord Test", "Other creatures you control get +2/+2.", CardType.Enchantment),
            Zone.Battlefield);

        Assert.NotNull(WhyNoBlock(game, small, attacker, bob));
    }

    [Fact]
    public void Flashback_casts_it_from_the_graveyard_and_exiles_it_afterwards()
    {
        var bolt = new CardDefinition
        {
            OracleId = "oracle-flashback-test",
            Name = "Flashback Test",
            OracleText = "You gain 3 life.\nFlashback {1}",
            CardTypes = CardType.Sorcery,
            ManaCostRaw = "{4}",
        };

        var (game, alice, _) = InMainPhase();
        var card = game.Create(alice, bolt, Zone.Graveyard);
        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, forest, "mana");

        // Cast from the graveyard for {1} rather than from hand for {4}.
        game.CastSpell(alice, card);
        Settle(game);

        Assert.Equal(23, game.State.GetPlayer(alice).Life);

        // CR 702.34a: exiled instead of going back to the graveyard, so it cannot be cast again.
        Assert.Single(game.State.Exile);
        Assert.Empty(game.State.GetPlayer(alice).Graveyard);
    }

    [Fact]
    public void A_card_without_flashback_still_cannot_be_cast_from_the_graveyard()
    {
        var plain = new CardDefinition
        {
            OracleId = "oracle-no-flashback-test",
            Name = "No Flashback Test",
            OracleText = "You gain 3 life.",
            CardTypes = CardType.Sorcery,
            ManaCostRaw = "{1}",
        };

        var (game, alice, _) = InMainPhase();
        var card = game.Create(alice, plain, Zone.Graveyard);
        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, forest, "mana");

        var ex = Assert.Throws<InvalidOperationException>(() => game.CastSpell(alice, card));
        Assert.Contains("from hand", ex.Message, StringComparison.Ordinal);
    }

    [Fact]
    public void Unearth_brings_it_back_hasty_and_takes_it_away_at_end_of_turn()
    {
        var ghoul = Card(
            "Unearth Test", "Unearth {1}", CardType.Creature, 3, 3);

        var (game, alice, _) = InMainPhase();
        var card = game.Create(alice, ghoul, Zone.Graveyard);
        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, forest, "mana");

        game.ActivateAbility(alice, card, "unearth");
        Settle(game);

        var back = game.State.Battlefield
            .Select(game.State.GetObject)
            .Single(o => o.Card.Name == "Unearth Test");

        // CR 702.83a gives it haste, so it can attack the turn it returns.
        Assert.True(Characteristics.Of(game.State, Pool, back).Has(KeywordAbility.Haste));

        TestCards.PassUntil(game, () => game.State.CurrentStep >= TurnStep.Cleanup);

        // ...and exiles it at the beginning of the next end step, not the graveyard.
        Assert.Single(game.State.Exile);
        Assert.DoesNotContain(back.Id, game.State.Battlefield);
    }

    // ---- Convoke and improvise (CR 702.51a, 702.56a) -------------------------

    /// <summary>A card with a printed mana cost, so a cost reduction has something to reduce.</summary>
    private static CardDefinition Priced(
        string name, string manaCost, string oracleText, CardType types = CardType.Sorcery) => new()
        {
            OracleId = "oracle-" + name.ToLowerInvariant().Replace(' ', '-'),
            Name = name,
            OracleText = oracleText,
            CardTypes = types,
            ManaCostRaw = manaCost,
        };

    [Fact]
    public void Convoking_creatures_pay_part_of_the_cost_and_end_up_tapped()
    {
        var spell = Priced("Convoke Test", "{3}", "Convoke\nYou gain 5 life.");

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, spell);

        var helpers = Enumerable.Range(0, 3)
            .Select(i => game.Create(alice, TestCards.Creature($"Helper {i}", 1, 1), Zone.Battlefield))
            .ToList();

        // No mana at all: the whole {3} is paid by tapping.
        game.CastSpell(alice, card, targets: null, variableValue: 0, tapToPay: helpers);
        Settle(game);

        Assert.Equal(25, game.State.GetPlayer(alice).Life);
        Assert.All(helpers, id => Assert.True(game.State.GetObject(id).Permanent!.IsTapped));
    }

    [Fact]
    public void A_convoking_creature_pays_its_own_colour_where_the_cost_asks_for_one()
    {
        var spell = Priced("Coloured Convoke Test", "{G}{G}", "Convoke\nYou gain 3 life.");

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, spell);

        var green = game.Create(alice, Coloured("Green Helper", ManaColor.Green), Zone.Battlefield);
        var alsoGreen = game.Create(alice, Coloured("Second Helper", ManaColor.Green), Zone.Battlefield);

        game.CastSpell(alice, card, targets: null, variableValue: 0, tapToPay: [green, alsoGreen]);
        Settle(game);

        Assert.Equal(23, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void A_creature_of_the_wrong_colour_cannot_pay_a_coloured_symbol()
    {
        // CR 702.51a: a convoking creature pays {1} or one mana of *its own* colour. A red
        // creature does not pay a {G}, and the cast is refused rather than quietly succeeding.
        var spell = Priced("Wrong Colour Test", "{G}{G}", "Convoke\nYou gain 3 life.");

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, spell);

        var red = game.Create(alice, Coloured("Red Helper", ManaColor.Red), Zone.Battlefield);
        var alsoRed = game.Create(alice, Coloured("Second Red", ManaColor.Red), Zone.Battlefield);

        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, card, targets: null, variableValue: 0,
                tapToPay: [red, alsoRed]));

        // Nothing was spent: CR 601.2h pays the cost as one act or not at all.
        Assert.False(game.State.GetObject(red).Permanent!.IsTapped);
    }

    [Fact]
    public void Improvise_taps_artifacts_and_never_pays_a_coloured_symbol()
    {
        var spell = Priced("Improvise Test", "{2}{U}", "Improvise\nYou gain 4 life.");

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, spell);

        var artifacts = Enumerable.Range(0, 2)
            .Select(i => game.Create(
                alice,
                Card($"Trinket {i}", string.Empty, CardType.Artifact),
                Zone.Battlefield))
            .ToList();

        var island = game.Create(alice, TestCards.BasicLand("Island"), Zone.Battlefield);
        game.ActivateAbility(alice, island, "mana");

        // The two artifacts cover the {2}; the {U} still has to come from the pool.
        game.CastSpell(alice, card, targets: null, variableValue: 0, tapToPay: artifacts);
        Settle(game);

        Assert.Equal(24, game.State.GetPlayer(alice).Life);
    }

    // ---- Crew, and tapping as a cost (CR 702.122a, 118.12) -------------------

    [Fact]
    public void Crewing_taps_enough_power_and_turns_the_vehicle_into_a_creature()
    {
        var vehicle = Card(
            "Vehicle Test", "Crew 3", CardType.Artifact, 4, 4, subtypes: "Vehicle");

        var (game, alice, _) = InMainPhase();
        var truck = game.Create(alice, vehicle, Zone.Battlefield);
        var ox = game.Create(alice, TestCards.Creature("Ox", 2, 2), Zone.Battlefield);
        var goat = game.Create(alice, TestCards.Creature("Goat", 1, 1), Zone.Battlefield);

        Assert.False(
            Characteristics.Of(game.State, Pool, game.State.GetObject(truck)).IsCreature);

        game.ActivateAbility(alice, truck, "crew", targets: null, costPayment: [ox, goat]);
        Settle(game);

        var crewed = Characteristics.Of(game.State, Pool, game.State.GetObject(truck));
        Assert.True(crewed.IsCreature);

        // It keeps every type it already had — a crewed Vehicle is an artifact creature.
        Assert.True(crewed.CardTypes.HasFlag(CardType.Artifact));

        // The crew are tapped, not spent.
        Assert.True(game.State.GetObject(ox).Permanent!.IsTapped);
        Assert.Contains(ox, game.State.Battlefield);
    }

    [Fact]
    public void Crew_refuses_a_crew_that_does_not_add_up()
    {
        var vehicle = Card(
            "Heavy Vehicle Test", "Crew 5", CardType.Artifact, 6, 6, subtypes: "Vehicle");

        var (game, alice, _) = InMainPhase();
        var truck = game.Create(alice, vehicle, Zone.Battlefield);
        var goat = game.Create(alice, TestCards.Creature("Goat", 1, 1), Zone.Battlefield);

        var ex = Assert.Throws<InvalidOperationException>(
            () => game.ActivateAbility(alice, truck, "crew", targets: null, costPayment: [goat]));

        Assert.Contains("702.122a", ex.Message, StringComparison.Ordinal);

        // CR 601.2h: nothing was spent, so the goat is still upright.
        Assert.False(game.State.GetObject(goat).Permanent!.IsTapped);
    }

    [Fact]
    public void A_creature_that_arrived_this_turn_can_still_crew()
    {
        // CR 302.6 is about a permanent's own {T} ability, not about being tapped to pay for
        // someone else's — so summoning sickness does not stop a fresh creature crewing.
        var vehicle = Card(
            "Fresh Crew Test", "Crew 2", CardType.Artifact, 3, 3, subtypes: "Vehicle");

        var (game, alice, _) = InMainPhase();
        var truck = game.Create(alice, vehicle, Zone.Battlefield);
        var fresh = game.Create(alice, TestCards.Creature("Fresh", 2, 2), Zone.Battlefield);

        Assert.True(game.State.GetObject(fresh).Permanent!.HasSummoningSickness);

        game.ActivateAbility(alice, truck, "crew", targets: null, costPayment: [fresh]);
        Settle(game);

        Assert.True(Characteristics.Of(game.State, Pool, game.State.GetObject(truck)).IsCreature);
    }

    // ---- Delayed triggered abilities (CR 603.7) ------------------------------

    [Fact]
    public void A_delayed_sacrifice_waits_for_the_end_step_and_then_happens_once()
    {
        var hasty = Card(
            "Delayed Sacrifice Test",
            "When ~ enters, sacrifice it at the beginning of the next end step.",
            CardType.Creature, 4, 4);

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, hasty);

        game.CastSpell(alice, card, []);
        Settle(game);

        var creature = game.State.Battlefield
            .Select(game.State.GetObject)
            .Single(o => o.Card.Name == "Delayed Sacrifice Test");

        // Still here for the rest of the turn — that is the whole point of the delay.
        Assert.Single(game.State.Delayed);
        Assert.Contains(creature.Id, game.State.Battlefield);

        TestCards.PassUntil(game, () => game.State.CurrentStep >= TurnStep.Cleanup);

        Assert.DoesNotContain(creature.Id, game.State.Battlefield);
        Assert.Empty(game.State.Delayed);
    }

    [Fact]
    public void A_delayed_ability_whose_subject_has_gone_does_nothing_at_all()
    {
        // CR 603.7c: if the object is no longer in the zone the ability expected, the ability
        // does nothing — including to the new object that took its place.
        var hasty = Card(
            "Vanishing Test",
            "When ~ enters, exile it at the beginning of the next end step.",
            CardType.Creature, 2, 2);

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, hasty);

        game.CastSpell(alice, card, []);
        Settle(game);

        var creature = game.State.Battlefield
            .Select(game.State.GetObject)
            .Single(o => o.Card.Name == "Vanishing Test");

        game.MarkDamage(creature.Id, 2);
        Settle(game);
        Assert.Single(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Vanishing Test");

        TestCards.PassUntil(game, () => game.State.CurrentStep >= TurnStep.Cleanup);

        // It died before the end step, so it is in the graveyard and not in exile.
        Assert.Empty(game.State.Exile);
        Assert.Empty(game.State.Delayed);
    }

    // ---- Abilities granted by another permanent (CR 613.1f) ------------------

    [Fact]
    public void An_aura_can_grant_a_whole_ability_and_the_land_can_use_it()
    {
        // Layer 6 adds abilities, not only keywords. Asking the *card* what it can do reports no
        // such ability and refuses the activation, which is why the engine and the board both ask
        // the computed characteristics instead.
        var aura = Card(
            "Granting Aura Test",
            "Enchant land\nEnchanted land has \"{T}: Add {B}\".",
            CardType.Enchantment, subtypes: "Aura");

        var (game, alice, _) = InMainPhase();
        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        var card = TestCards.PutInHand(game, alice, aura);

        game.CastSpell(alice, card, [Target.ToPermanent(forest)]);
        Settle(game);

        var granted = Game.ActivatedAbilitiesOf(game.State, Pool, game.State.GetObject(forest))
            .Single(a => a.Id.StartsWith("granted:", StringComparison.Ordinal));

        game.ActivateAbility(alice, forest, granted.Id);

        Assert.Equal(1, game.State.GetPlayer(alice).ManaPool.Colored
            .GetValueOrDefault(ManaColor.Black));

        // The land keeps its own ability too — two abilities, and the player says which.
        Assert.Equal(
            2, Game.ActivatedAbilitiesOf(game.State, Pool, game.State.GetObject(forest)).Count);
    }

    [Fact]
    public void A_granted_ability_goes_away_with_the_permanent_that_granted_it()
    {
        var lord = Card(
            "Granting Lord Test",
            "Other creatures you control have \"{T}: You gain 1 life\".",
            CardType.Creature, 2, 2);

        var (game, alice, _) = InMainPhase();
        var granter = game.Create(alice, lord, Zone.Battlefield);
        var bear = game.Create(alice, TestCards.Creature("Bear", 2, 2), Zone.Battlefield);
        Settle(game);

        Assert.Single(Game.ActivatedAbilitiesOf(game.State, Pool, game.State.GetObject(bear)));

        // The bug the layer system exists to prevent, in its ability-granting form.
        game.MarkDamage(granter, 2);
        Settle(game);

        Assert.Empty(Game.ActivatedAbilitiesOf(game.State, Pool, game.State.GetObject(bear)));
    }

    // ---- Static abilities over a group (CR 613) ------------------------------

    [Fact]
    public void A_lord_pumps_your_creatures_and_stops_when_it_leaves()
    {
        var lord = Card(
            "Lord Test",
            "Other creatures you control get +1/+1.",
            CardType.Creature, 2, 2);

        var (game, alice, bob) = InMainPhase();
        var anthem = game.Create(alice, lord, Zone.Battlefield);
        var mine = game.Create(alice, TestCards.Creature("Mine", 2, 2), Zone.Battlefield);
        var theirs = game.Create(bob, TestCards.Creature("Theirs", 2, 2), Zone.Battlefield);
        Settle(game);

        Assert.Equal(3, Characteristics.Of(game.State, Pool, game.State.GetObject(mine)).Power);

        // "Other" excludes the lord itself, and "you control" excludes the opponent's.
        Assert.Equal(2, Characteristics.Of(game.State, Pool, game.State.GetObject(anthem)).Power);
        Assert.Equal(2, Characteristics.Of(game.State, Pool, game.State.GetObject(theirs)).Power);

        // The bug the layer system exists to prevent: the lord dies and the buff stays on.
        game.MarkDamage(anthem, 2);
        Settle(game);

        Assert.Equal(2, Characteristics.Of(game.State, Pool, game.State.GetObject(mine)).Power);
    }

    [Fact]
    public void A_tribal_lord_only_pumps_its_tribe()
    {
        var lord = Card(
            "Tribal Test",
