    // ---- A mana ability names the player who tapped for it ------------------

    /// <summary>
    /// Manabarbs: "Whenever a player taps a land for mana, ~ deals 1 damage to that player."
    /// The damage follows the mana, not the enchantment, so the controller taking it and the
    /// opponent taking it are different outcomes and both are asserted.
    /// </summary>
    /// <remarks>
    /// The trigger fired before this and hit nobody: mana is added by an event that names the
    /// player it went to, and nothing read that name, so "that player" resolved to null and the
    /// damage was emitted against no one. Nothing failed - the card compiled, the ability
    /// triggered, and the game simply was not played.
    /// </remarks>
    [Theory]
    [InlineData(true)]
    [InlineData(false)]
    public void A_trigger_on_tapping_a_land_for_mana_damages_the_player_who_tapped(bool mine)
    {
        var barbs = new CardDefinition
        {
            OracleId = "oracle-mana-barbs-test",
            Name = "Mana Barbs Test",
            OracleText = "Whenever a player taps a land for mana, ~ deals 1 damage to that player.",
            CardTypes = CardType.Enchantment,
            ManaCostRaw = "{2}{R}",
        };

        var compiled = CardCompiler.Compile(barbs);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, barbs, Zone.Battlefield);

        var tapper = mine ? alice : bob;
        var land = game.Create(tapper, TestCards.BasicLand("Mountain"), Zone.Battlefield);
        game.ActivateAbility(tapper, land, "mana");

        Settle(game);

        Assert.Equal(19, game.State.GetPlayer(tapper).Life);
        Assert.Equal(20, game.State.GetPlayer(mine ? bob : alice).Life);
    }

    // ---- A spell's colour is not its colour identity ------------------------

    /// <summary>
    /// "Whenever you cast a black spell" asks what the spell <em>is</em> (CR 202.2). A card's
    /// colour identity also counts the mana symbols in its rules text (CR 903.4), so a devoid
    /// spell and Bosh, Iron Golem both carry a colour they are not - and the trigger fired on
    /// them.
    /// </summary>
    /// <remarks>
    /// The two lists disagree on 1,158 nonland cards in the corpus, and every colour question in
    /// the engine was answered from the wrong one because that was the only list the card model
    /// carried.
    /// </remarks>
    [Theory]
    [InlineData(true, 21)]
    [InlineData(false, 20)]
    public void A_cast_trigger_naming_a_colour_reads_the_colour_not_the_identity(
        bool actuallyBlack, int expected)
    {
        var watcher = new CardDefinition
        {
            OracleId = "oracle-black-cast-watcher",
            Name = "Black Cast Watcher Test",
            OracleText = "Whenever you cast a black spell, you gain 1 life.",
            CardTypes = CardType.Enchantment,
            ManaCostRaw = "{B}",
        };

        var compiled = CardCompiler.Compile(watcher);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        // Both carry a black identity. Only one of them is a black card: the other is the shape
        // of a devoid spell, whose identity keeps the black its cost is paid with while the card
        // itself is colourless.
        var spell = new CardDefinition
        {
            OracleId = "oracle-black-cast-subject-" + actuallyBlack,
            Name = "Cast Subject Test " + actuallyBlack,
            CardTypes = CardType.Sorcery,
            ManaCostRaw = "{B}",
            ColorIdentity = [ManaColor.Black],
            Colors = actuallyBlack ? [ManaColor.Black] : [],
        };

        var (game, alice, _) = InMainPhase();
        game.Create(alice, watcher, Zone.Battlefield);

        var swamp = game.Create(alice, TestCards.BasicLand("Swamp"), Zone.Battlefield);
        game.ActivateAbility(alice, swamp, "mana");

        game.CastSpell(alice, TestCards.PutInHand(game, alice, spell), targets: null);
        Settle(game);

        Assert.Equal(expected, game.State.GetPlayer(alice).Life);
    }

    // ---- A spell's mana value counts the X it was cast for ------------------

    /// <summary>
    /// "Whenever you cast a spell with mana value 5 or greater" is a question about the spell on
    /// the stack, where X equals the value announced as it was cast (CR 107.3a) rather than the
    /// zero it is in every other zone (CR 107.3g). Cast for X=5, a {X}{R} spell has mana value 6;
    /// its printed cost says 1, and reading the card instead of the spell meant it never fired.
    /// </summary>
    [Theory]
    [InlineData(5, 21)]
    [InlineData(1, 20)]
    public void A_cast_trigger_on_mana_value_counts_the_X_that_was_paid(int x, int expected)
    {
        var watcher = new CardDefinition
        {
            OracleId = "oracle-mana-value-watcher",
            Name = "Mana Value Watcher Test",
            OracleText = "Whenever you cast a spell with mana value 5 or greater, you gain 1 life.",
            CardTypes = CardType.Enchantment,
            ManaCostRaw = "{R}",
        };

        var compiled = CardCompiler.Compile(watcher);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        // Printed mana value 1, whatever X turns out to be.
        var surge = new CardDefinition
        {
            OracleId = "oracle-mana-value-surge",
            Name = "Mana Value Surge Test",
            OracleText = "~ deals X damage to any target.",
            CardTypes = CardType.Instant,
            ManaCostRaw = "{X}{R}",
            Colors = [ManaColor.Red],
            ColorIdentity = [ManaColor.Red],
        };

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, watcher, Zone.Battlefield);

        foreach (var _ in Enumerable.Range(0, x + 1))
        {
            var land = game.Create(alice, TestCards.BasicLand("Mountain"), Zone.Battlefield);
            game.ActivateAbility(alice, land, "mana");
        }

        game.CastSpell(
            alice,
            TestCards.PutInHand(game, alice, surge),
            [Target.ToPlayer(bob)],
            variableValue: x);

        Settle(game);

        Assert.Equal(expected, game.State.GetPlayer(alice).Life);
    }

    // ---- A block trigger reads the creature, not the card -------------------

    /// <summary>
    /// "Whenever ~ blocks a creature with flying" asks whether the attacker has flying *now*
    /// (CR 613), not whether it was printed with it. The attacker here is a vanilla 2/2 given
    /// flying by an enchantment its controller owns, and blocking it triggers.
    /// </summary>
    /// <remarks>
    /// It could not be asked at all before: a trigger predicate was handed the source object with
    /// no ability source beside it, so it could not reach the layers and every question of this
    /// kind had to be answered from the printed card. The granted case is the whole point of the
    /// theory - a printed flier proves the filter, and only the granted one proves it is reading
    /// the object.
    /// </remarks>
    [Theory]
    [InlineData(true, 4)]
    [InlineData(false, 2)]
    public void A_block_trigger_naming_a_keyword_reads_the_granted_one(bool granted, int expected)
    {
        var ambusher = Card(
            "Flying Ambusher Test",
            "Whenever ~ blocks a creature with flying, ~ gets +2/+2 until end of turn.",
            CardType.Creature,
            power: 2,
            toughness: 5,

            // Reach, because a creature that cannot block a flier never gets to ask the
            // question (CR 702.9b), and toughness enough to survive the blow so its power
            // can be read afterwards rather than off a card in a graveyard.
            keywords: KeywordAbility.Reach);

        var compiled = CardCompiler.Compile(ambusher);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var blocker = game.Create(bob, ambusher, Zone.Battlefield);
        var attacker = game.Create(
            alice, TestCards.Creature("Grounded Attacker Test", 2, 2), Zone.Battlefield);

        if (granted)
        {
            game.Create(
                alice,
                Card(
                    "Wind Chorus Test",
                    "Creatures you control have flying.",
                    CardType.Enchantment),
                Zone.Battlefield);
        }

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);
        game.DeclareBlockers(
            bob,
            new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [attacker] = [blocker] });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.CombatDamage);
        Settle(game);

        Assert.Equal(
            expected,
            Characteristics.Of(game.State, Pool, game.State.GetObject(blocker)).Power);
    }

    // ---- One sentence, two continuous effects, one group --------------------

    /// <summary>
    /// "Creatures you control get +1/+1 and gain vigilance until end of turn" is one sentence
    /// applying two effects to the same group, and it is only yours that get either.
    /// </summary>
    /// <remarks>
    /// The mass pump had two branches - a group word for the singular "gets", none needed for the
    /// plural "get" - and the mass grant had only the first, so the same card was read when it
    /// said "get +1/+1" and not when it said "gain vigilance". 192 corpus lines took the second
    /// spelling, 112 of them in this combined form.
    /// </remarks>
    [Fact]
    public void A_mass_pump_can_grant_a_keyword_in_the_same_sentence()
    {
        var cry = Card(
            "Marshaling Cry Test",
            "Creatures you control get +1/+1 and gain vigilance until end of turn.",
            CardType.Instant);

        var compiled = CardCompiler.Compile(cry);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var mine = game.Create(alice, TestCards.Creature("Cry Soldier Test", 2, 2), Zone.Battlefield);
        var theirs = game.Create(bob, TestCards.Creature("Cry Rival Test", 2, 2), Zone.Battlefield);

        var land = game.Create(alice, TestCards.BasicLand("Plains"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");
        game.CastSpell(alice, TestCards.PutInHand(game, alice, cry), targets: null);
        Settle(game);

        var pumped = Characteristics.Of(game.State, Pool, game.State.GetObject(mine));
        Assert.Equal(3, pumped.Power);
        Assert.Equal(3, pumped.Toughness);
        Assert.True(pumped.Has(KeywordAbility.Vigilance));

        // The other half of "you control": an opponent's creature gets neither effect, which a
        // sentence read as "all creatures" would give both.
        var untouched = Characteristics.Of(game.State, Pool, game.State.GetObject(theirs));
        Assert.Equal(2, untouched.Power);
        Assert.False(untouched.Has(KeywordAbility.Vigilance));
    }

    // ---- A restricted mana ability is still a mana ability ------------------

    /// <summary>
    /// "Activate only once each turn" caps how often a mana ability may be used. It does not stop
    /// it being a mana ability, which never uses the stack (CR 605.3b).
    /// </summary>
    /// <remarks>
    /// Both restrictions open with the same three words as "Activate only if you control a
    /// Plains", so the timing reader matched them, failed to read them as a board condition, and
    /// refused the line. The whole thing then fell through to the general activated-ability path,
    /// where it compiled into an ability that goes on the stack and can be responded to - a
    /// different card, quietly. 110 corpus lines cap a mana ability this way and 588 restrict one
    /// to sorcery speed.
    /// </remarks>
    [Fact]
    public void A_capped_mana_ability_is_still_a_mana_ability()
    {
        var vault = new CardDefinition
        {
            OracleId = "oracle-capped-mana-vault-test",
            Name = "Capped Vault Test",
            // No tap symbol, so the second attempt below is refused by the printed cap rather
            // than by the permanent already being tapped - which would prove nothing.
            OracleText = "{1}: Add {C}{C}. Activate only once each turn.",
            CardTypes = CardType.Land,
        };

        var compiled = CardCompiler.Compile(vault);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var only = Assert.Single(compiled.Activated);
        Assert.True(only.IsManaAbility);
        Assert.Equal(1, only.MaxActivationsPerTurn);

        var (game, alice, _) = InMainPhase();
        var land = game.Create(alice, vault, Zone.Battlefield);

        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, forest, "mana");

        game.ActivateAbility(alice, land, only.Id);

        // A mana ability resolves where it stands, so the mana is in the pool and nothing is
        // waiting for anyone to pass.
        Assert.Equal(2, game.State.GetPlayer(alice).ManaPool.Colorless);
        Assert.True(game.State.Stack.IsEmpty);

        // And the cap is real. The permanent is untapped and the mana to pay again is sitting in
        // the pool, so the only thing refusing is the printed sentence.
        Assert.Throws<InvalidOperationException>(
            () => game.ActivateAbility(alice, land, only.Id));
    }

    // ---- A keyword list with a costed keyword in it -------------------------

    /// <summary>
    /// "Flying, ward {2}" is a keyword line with one keyword that carries a cost, and both halves
    /// have to survive it: the creature flies and the ward still taxes.
    /// </summary>
    /// <remarks>
    /// A keyword line is read whole or not at all - half a list is a card that does half of what
    /// it prints - and the plain reader can only see keywords that are flags on the card. So one
    /// ward in the list took the whole line down: "Flying" was read, "Ward {2}" was read, and
    /// "Flying, ward {2}" was not. 55 corpus lines are that shape.
    /// </remarks>
    [Fact]
    public void A_keyword_list_can_carry_a_costed_keyword()
    {
        var sentry = new CardDefinition
        {
            OracleId = "oracle-flying-ward-sentry-test",
            Name = "Flying Ward Sentry Test",
            OracleText = "Flying, ward {2}",
            CardTypes = CardType.Creature,
            Keywords = KeywordAbility.Flying,
            Power = 2,
            Toughness = 2,
            ManaCostRaw = "{1}{U}",
        };

        var compiled = CardCompiler.Compile(sentry);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        // The ward half became a trigger; the flying half is a flag and needs no compiling.
        Assert.Single(compiled.Triggers, t => t.Id == "ward");

        var (game, alice, bob) = InMainPhase();
        var warded = game.Create(bob, sentry, Zone.Battlefield);

        Assert.True(
            Characteristics.Of(game.State, Pool, game.State.GetObject(warded))
                .Has(KeywordAbility.Flying));

        // An opponent targeting it sets the tax going. Its own controller would not - ward only
        // triggers on an opponent's spell (CR 702.21a) - so this is the half worth driving.
        var bolt = Card("Ward Probe Bolt Test", "~ deals 3 damage to any target.", CardType.Instant);
        var land = game.Create(alice, TestCards.BasicLand("Mountain"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");
        game.CastSpell(alice, TestCards.PutInHand(game, alice, bolt), [Target.ToPermanent(warded)]);

        Assert.Contains(
            game.Log.OfType<AbilityTriggered>(),
            t => string.Equals(t.AbilityId, "ward", StringComparison.Ordinal));
    }

    // ---- A triggered ability can offer modes --------------------------------

    /// <summary>
    /// "When ~ enters, choose one — • You gain 3 life. • Draw a card." The controller picks as
    /// the ability goes on the stack (CR 603.3c), and only the picked mode happens.
    /// </summary>
    /// <remarks>
    /// Modal <em>spells</em> have worked since the modes were built, because a spell's modes are
    /// chosen while it is being cast and never have to leave the engine to ask. An ability is
    /// put on the stack in the middle of settling, so the question has to become a pending choice
    /// and be resumed - the same machinery the ability's targets already use. 71 corpus lines
    /// open a trigger with a menu.
    /// </remarks>
    [Theory]
    [InlineData(0, 23, 0)]
    [InlineData(1, 20, 1)]
    public void A_triggered_ability_can_offer_modes(int pick, int expectedLife, int expectedDrawn)
    {
        var oracle = new CardDefinition
        {
            OracleId = "oracle-modal-trigger-test",
            Name = "Modal Herald Test",
            OracleText = "When ~ enters, choose one —\n• You gain 3 life.\n• Draw a card.",
            CardTypes = CardType.Creature,
            Power = 2,
            Toughness = 2,
            ManaCostRaw = "{1}{W}",
        };

        var compiled = CardCompiler.Compile(oracle);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.Equal(2, compiled.Triggers.Single().Modes.Count);

        var (game, alice, _) = InMainPhase();
        var before = game.State.GetPlayer(alice).Hand.Count;

        game.Create(alice, oracle, Zone.Battlefield);

        // Passed by hand rather than through Settle, which answers every choice with its first
        // option - and the whole question here is which option was taken.
        for (var guard = 0; guard < 20 && game.State.Choice is null; guard++)
        {
            if (game.State.Priority.Holder is not { } holder)
                break;

            game.PassPriority(holder);
        }

        // The ability is waiting to be put on the stack and cannot be until the mode is picked.
        var asked = game.State.Choice;
        Assert.NotNull(asked);
        Assert.Equal(ChoiceKind.ChooseTriggerMode, asked.Kind);
        Assert.Equal(2, asked.Options.Count);

        game.Choose(alice, [asked.Options[pick].Id]);
        Settle(game);

        Assert.Equal(expectedLife, game.State.GetPlayer(alice).Life);
        Assert.Equal(before + expectedDrawn, game.State.GetPlayer(alice).Hand.Count);
    }

    // ---- The monarch (CR 725) -----------------------------------------------

    /// <summary>
    /// "When ~ enters, you become the monarch." Thirty-five cards say exactly that and nothing
    /// else about the designation.
    /// </summary>
    [Fact]
    public void An_enters_trigger_can_make_you_the_monarch()
    {
        var herald = Card(
            "Monarch Herald Test",
            "When ~ enters, you become the monarch.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var compiled = CardCompiler.Compile(herald);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        Assert.Null(game.State.MonarchId);

        game.Create(alice, herald, Zone.Battlefield);
        Settle(game);

        Assert.Equal(alice, game.State.MonarchId);
    }

    /// <summary>
    /// The first of the monarch's two inherent abilities (CR 725.2): at the beginning of the
    /// monarch's end step, that player draws a card. Nobody else's end step does anything.
    /// </summary>
    [Fact]
    public void The_monarch_draws_at_their_own_end_step()
    {
        var (game, alice, bob) = InMainPhase();
        game.Create(alice, Card(
            "Monarch Crown Test", "When ~ enters, you become the monarch.",
            CardType.Creature, power: 1, toughness: 1), Zone.Battlefield);

        Settle(game);
        Assert.Equal(alice, game.State.MonarchId);

        var mine = game.State.GetPlayer(alice).Hand.Count;
        var theirs = game.State.GetPlayer(bob).Hand.Count;

        // Alice is the active player, so the next end step is hers.
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.End);
        Settle(game);

        Assert.Equal(mine + 1, game.State.GetPlayer(alice).Hand.Count);
        Assert.Equal(theirs, game.State.GetPlayer(bob).Hand.Count);
    }

    /// <summary>
    /// The second (CR 725.2): whenever a creature deals combat damage to the monarch, its
    /// controller becomes the monarch. This is what makes the crown worth attacking for.
    /// </summary>
    [Fact]
    public void Combat_damage_to_the_monarch_takes_the_crown()
    {
        var (game, alice, bob) = InMainPhase();
        game.Create(alice, Card(
            "Monarch Throne Test", "When ~ enters, you become the monarch.",
            CardType.Enchantment), Zone.Battlefield);

        Settle(game);
        Assert.Equal(alice, game.State.MonarchId);

        // Bob's creature, on Alice's turn, so Bob has to wait for his own combat - the crown is
        // taken by attacking its holder, and Alice cannot attack herself.
        var raider = game.Create(bob, TestCards.Creature("Crown Raider Test", 2, 2), Zone.Battlefield);

        TestCards.PassUntil(game, () => game.State.TurnNumber == 2
            && game.State.CurrentStep == TurnStep.DeclareAttackers);

        game.DeclareAttackers(
            bob,
            new Dictionary<ObjectId, AttackTarget> { [raider] = AttackTarget.Player(alice) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Settle(game);

        Assert.Equal(bob, game.State.MonarchId);
        Assert.Equal(18, game.State.GetPlayer(alice).Life);
    }

    /// <summary>
    /// The crown goes to whoever controls the creature *now* (CR 725.2, 613.1b).
    /// </summary>
    /// <remarks>
    /// The test above uses a creature its controller has had all along, so the stored controller
    /// and the real one agree and the rule cannot tell them apart. Taking the monarch's own
    /// creature and hitting them with it separates the two: the stored controller is still the
    /// monarch, which the rule reads as "the monarch damaged themselves" and declines to move
    /// the crown at all.
    /// </remarks>
    [Fact]
    public void The_crown_goes_to_whoever_controls_the_creature_now()
    {
        var (game, alice, bob) = InMainPhase();
        game.Create(alice, Card(
            "Stolen Crown Throne Test", "When ~ enters, you become the monarch.",
            CardType.Enchantment), Zone.Battlefield);

        Settle(game);
        Assert.Equal(alice, game.State.MonarchId);

        var bear = game.Create(alice, TestCards.Creature("Turncoat Bear Test", 2, 2), Zone.Battlefield);

        var threaten = Card(
            "Crown Threaten Test",
            "Gain control of target creature until end of turn. Untap that creature. "
                + "It gains haste until end of turn.");
        var land = game.Create(bob, TestCards.BasicLand("Forest"), Zone.Battlefield);

        TestCards.PassUntil(game, () => game.State.TurnNumber == 2
            && game.State.CurrentStep == TurnStep.PrecombatMain);

        // Dealt into hand here rather than earlier: a card put in hand before the turn passes is
        // a different object by the time it is cast, because cleanup moved it (CR 400.7).
        var card = TestCards.PutInHand(game, bob, threaten);
        game.ActivateAbility(bob, land, "mana");
        game.CastSpell(bob, card, [Target.ToPermanent(bear)]);
        Settle(game);

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            bob, new Dictionary<ObjectId, AttackTarget> { [bear] = AttackTarget.Player(alice) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Settle(game);

        Assert.Equal(bob, game.State.MonarchId);
    }

    /// <summary>An animated land takes the crown too (CR 725.2, 613 layer 4).</summary>
    /// <remarks>
    /// The companion to the test above: that one is about *who* controls the creature, this one
    /// about whether it is a creature at all. A land animated this turn is, and a rule reading
    /// the printed type sees only a land. Nothing gives it summoning sickness either - its
    /// controller has had it since the turn began (CR 302.6), which is what makes manlands work.
    /// </remarks>
    [Fact]
    public void An_animated_land_takes_the_crown()
    {
        var (game, alice, bob) = InMainPhase();
        game.Create(alice, Card(
            "Animated Crown Throne Test", "When ~ enters, you become the monarch.",
            CardType.Enchantment), Zone.Battlefield);

        Settle(game);
        Assert.Equal(alice, game.State.MonarchId);

        var manland = game.Create(bob, TestCards.BasicLand("Forest"), Zone.Battlefield);
        var payment = game.Create(bob, TestCards.BasicLand("Forest"), Zone.Battlefield);

        TestCards.PassUntil(game, () => game.State.TurnNumber == 2
            && game.State.CurrentStep == TurnStep.PrecombatMain);

        var awaken = TestCards.PutInHand(game, bob, Card(
            "Awaken Crown Test",
            "Until end of turn, target land you control becomes a 3/3 Elemental creature."));

        game.ActivateAbility(bob, payment, "mana");
        game.CastSpell(bob, awaken, [Target.ToPermanent(manland)]);
        Settle(game);

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            bob, new Dictionary<ObjectId, AttackTarget> { [manland] = AttackTarget.Player(alice) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Settle(game);

        Assert.Equal(bob, game.State.MonarchId);
        Assert.Equal(17, game.State.GetPlayer(alice).Life);
    }

    // ---- Transforming a permanent (CR 712.2) --------------------------------

    /// <summary>
    /// A permanent with two faces turns over, and everything about it changes with the face: its
    /// name, its power and toughness, its keywords and its abilities.
    /// </summary>
    /// <remarks>
    /// The object's card is *swapped* for the face's characteristics rather than the face being
    /// remembered beside it. That is what makes this small: the layers, the ability source and
    /// the view all read one definition, and after the swap every one of them reads the face the
    /// permanent is on without knowing faces exist. The assertions below go through
    /// <c>Characteristics.Of</c> for exactly that reason - if the swap were cosmetic they would
    /// still report the front face.
    /// <para>
    /// This is the mechanic, not the cards: no printed card compiles to it yet, because the
    /// compiler still leaves the `//` between the halves unread. 853 corpus cards are waiting on
    /// the other half of the work.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_permanent_with_two_faces_can_turn_over()
    {
        var werewolf = new CardDefinition
        {
            OracleId = "oracle-two-faced-test",
            Name = "Quiet Villager Test",
            CardTypes = CardType.Creature,
            Power = 1,
            Toughness = 1,
            ManaCostRaw = "{1}{G}",
            Faces =
            [
                new CardFace
                {
                    Name = "Quiet Villager Test",
                    CardTypes = CardType.Creature,
                    Power = 1,
                    Toughness = 1,
                    ManaCostRaw = "{1}{G}",
                },
                new CardFace
                {
                    Name = "Howling Villager Test",
                    CardTypes = CardType.Creature,
                    Power = 3,
                    Toughness = 3,
                    Keywords = KeywordAbility.Trample,
                },
            ],
        };

        var (game, alice, _) = InMainPhase();
        var villager = game.Create(alice, werewolf, Zone.Battlefield);

        var quiet = Characteristics.Of(game.State, Pool, game.State.GetObject(villager));
        Assert.Equal(1, quiet.Power);
        Assert.False(quiet.Has(KeywordAbility.Trample));
        Assert.Equal(0, game.State.GetObject(villager).Permanent!.FaceIndex);

        game.Transform(villager);

        var howling = Characteristics.Of(game.State, Pool, game.State.GetObject(villager));
        Assert.Equal(3, howling.Power);
        Assert.Equal(3, howling.Toughness);
        Assert.True(howling.Has(KeywordAbility.Trample));
        Assert.Equal("Howling Villager Test", game.State.GetObject(villager).Card.Name);
        Assert.Equal(1, game.State.GetObject(villager).Permanent!.FaceIndex);

        // And back, which is what keeps the face list travelling with the swapped-in definition.
        game.Transform(villager);
        Assert.Equal(1, Characteristics.Of(
            game.State, Pool, game.State.GetObject(villager)).Power);

        Settle(game);
    }

    /// <summary>
    /// A transformed permanent has its back face's <em>abilities</em>, not only its numbers.
    /// </summary>
    /// <remarks>
    /// This is the half that makes the swap worth doing. The ability source is keyed by oracle id
    /// and the face's definition carries its own - the card's, with the face's index after it -
    /// so the pool compiles that face's text and finds the ability there, at the moment the
    /// permanent is showing it. Nothing in the pool, the activation path or the layers was told
    /// about faces.
    /// </remarks>
    [Fact]
    public void A_transformed_permanent_has_its_back_faces_abilities()
    {
        var moon = new CardDefinition
        {
            OracleId = "oracle-transform-abilities-test",
            Name = "Sleeping Warden Test",
            CardTypes = CardType.Creature,
            Power = 1,
            Toughness = 1,
            ManaCostRaw = "{1}{W}",
            Faces =
            [
                new CardFace
                {
                    Name = "Sleeping Warden Test",
                    CardTypes = CardType.Creature,
                    Power = 1,
                    Toughness = 1,
                    ManaCostRaw = "{1}{W}",
                },
                new CardFace
                {
                    Name = "Waking Warden Test",
                    CardTypes = CardType.Creature,
                    Power = 2,
                    Toughness = 2,

                    // Haste, because the tap cost is otherwise refused for summoning sickness
                    // (CR 302.6) - which the engine got right on the first run of this test. It
                    // is on the face rather than the card, so it is also the keyword half of the
                    // same claim.
                    Keywords = KeywordAbility.Haste,
                    OracleText = "{T}: You gain 2 life.",
                },
            ],
        };

        // The card is its front face while it is anywhere but showing its back (CR 712.8a), and
        // the front face here says nothing at all.
        Assert.Empty(CardCompiler.Compile(moon).Activated);

        var (game, alice, _) = InMainPhase();
        var warden = game.Create(alice, moon, Zone.Battlefield);

        Assert.Empty(Game.ActivatedAbilitiesOf(game.State, Pool, game.State.GetObject(warden)));

        game.Transform(warden);

        var offered = Game.ActivatedAbilitiesOf(game.State, Pool, game.State.GetObject(warden));
        var only = Assert.Single(offered);

        game.ActivateAbility(alice, warden, only.Id);
        Settle(game);

        Assert.Equal(22, game.State.GetPlayer(alice).Life);
    }

    /// <summary>
    /// A werewolf turns over at the upkeep when nobody cast a spell the turn before, and stays as
    /// it is when somebody did.
    /// </summary>
    /// <remarks>
    /// The whole day-night cycle as those cards print it is one question about the *previous*
    /// turn, and the state had no memory of it - only of this turn. It is carried forward as the
    /// turn changes rather than reconstructed, because a fold may not read the log.
    /// <para>
    /// A theory rather than one case: the interesting half is the one where nothing happens, and
    /// a test that only played the quiet turn would pass just as well against a trigger that
    /// ignored its condition entirely.
    /// </para>
    /// </remarks>
    [Theory]
    [InlineData(false, 1)]
    [InlineData(true, 0)]
    public void A_werewolf_turns_over_when_nobody_cast_a_spell(bool cast, int expectedFace)
    {
        var werewolf = new CardDefinition
        {
            OracleId = "oracle-werewolf-test",
            Name = "Village Watcher Test",
            CardTypes = CardType.Creature,
            Power = 1,
            Toughness = 1,
            ManaCostRaw = "{1}{G}",
            Faces =
            [
                new CardFace
                {
                    Name = "Village Watcher Test",
                    CardTypes = CardType.Creature,
                    Power = 1,
                    Toughness = 1,
                    ManaCostRaw = "{1}{G}",
                    OracleText =
                        "At the beginning of each upkeep, if no spells were cast last turn, "
                        + "transform ~.",
                },
                new CardFace
                {
                    Name = "Howling Watcher Test",
                    CardTypes = CardType.Creature,
                    Power = 3,
                    Toughness = 3,
                    OracleText =
                        "At the beginning of each upkeep, if a player cast two or more spells "
                        + "last turn, transform ~.",
                },
            ],
        };

        var compiled = CardCompiler.Compile(werewolf);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var watcher = game.Create(alice, werewolf, Zone.Battlefield);

        if (cast)
        {
            var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
            game.ActivateAbility(alice, forest, "mana");

            var growth = Card("Watcher Growth Test", "You gain 1 life.", CardType.Instant);
            game.CastSpell(alice, TestCards.PutInHand(game, alice, growth), targets: null);
            Settle(game);
        }

        TestCards.PassUntil(game, () => game.State.TurnNumber == 2
            && game.State.CurrentStep == TurnStep.Upkeep);

        Settle(game);

        Assert.Equal(expectedFace, game.State.GetObject(watcher).Permanent!.FaceIndex);
        Assert.Equal(
            expectedFace == 1 ? 3 : 1,
            Characteristics.Of(game.State, Pool, game.State.GetObject(watcher)).Power);
    }

    // ---- Day and night (CR 731) ---------------------------------------------

    /// <summary>
    /// A daybound permanent makes it day when it is neither (CR 702.145d); a quiet turn then
    /// makes it night (CR 502.2); and becoming night turns the permanent over (CR 702.145c).
    /// </summary>
    /// <remarks>
    /// Three rules that only mean anything together, which is why they are one test. The game
    /// starts as neither day nor night and stays that way until a card says otherwise - and while
    /// it is neither, the untap-step check does not happen at all (CR 731.2).
    /// </remarks>
    [Fact]
    public void A_daybound_permanent_makes_it_day_and_a_quiet_turn_makes_it_night()
    {
        var werewolf = new CardDefinition
        {
            OracleId = "oracle-daybound-test",
            Name = "Moonlit Scout Test",
            CardTypes = CardType.Creature,
            Keywords = KeywordAbility.Daybound,
            Power = 2,
            Toughness = 2,
            ManaCostRaw = "{1}{R}",
            Faces =
            [
                new CardFace
                {
                    Name = "Moonlit Scout Test",
                    CardTypes = CardType.Creature,
                    Keywords = KeywordAbility.Daybound,
                    Power = 2,
                    Toughness = 2,
                    OracleText = "Daybound",
                },
                new CardFace
                {
                    Name = "Moonlit Howler Test",
                    CardTypes = CardType.Creature,
                    Keywords = KeywordAbility.Nightbound,
                    Power = 4,
                    Toughness = 4,
                    OracleText = "Nightbound",
                },
            ],
        };

        var compiled = CardCompiler.Compile(werewolf);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        Assert.Null(game.State.IsDay);

        var scout = game.Create(alice, werewolf, Zone.Battlefield);
        Settle(game);

        // CR 702.145d: it was neither, and a daybound permanent is on the battlefield.
        Assert.True(game.State.IsDay);
        Assert.Equal(0, game.State.GetObject(scout).Permanent!.FaceIndex);

        // Nobody casts anything for a turn, so the untap step of the next one turns it to night
        // and the scout turns over with it.
        TestCards.PassUntil(game, () => game.State.TurnNumber == 2
            && game.State.CurrentStep == TurnStep.Upkeep);

        Settle(game);

        Assert.False(game.State.IsDay);
        Assert.Equal(1, game.State.GetObject(scout).Permanent!.FaceIndex);
        Assert.Equal(
            4, Characteristics.Of(game.State, Pool, game.State.GetObject(scout)).Power);
    }

    // ---- Saddle, and "while saddled" ----------------------------------------

    /// <summary>
    /// Saddle N taps other creatures with total power N to saddle a Mount (CR 702.171a), the
    /// Mount's own trigger asks whether it is saddled, and being saddled ends with the turn.
    /// </summary>
    /// <remarks>
    /// Crew's cost with a different consequence - the same measured-rather-than-counted tap - so
    /// what is worth driving is the half crew does not have: the status, the trigger that reads
    /// it, and the fact that it is gone next turn. "While saddled" is read as a board condition
    /// hung off an ordinary attack trigger rather than as a shape of its own, which is why a
    /// "while" the board reader cannot answer leaves the whole trigger unread.
    /// </remarks>
    [Fact]
    public void A_saddled_mount_triggers_and_stops_being_saddled_at_end_of_turn()
    {
        var mount = Card(
            "Test Warhorse",
            "Saddle 2\nWhenever ~ attacks while saddled, it gets +2/+2 until end of turn.",
            CardType.Creature,
            power: 2,
            toughness: 2,
            keywords: KeywordAbility.Haste,
            subtypes: "Mount");

        var compiled = CardCompiler.Compile(mount);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var saddling = Assert.Single(compiled.Activated, a => a.Id == "saddle");
        Assert.Equal(ActivationTiming.SorceryOnly, saddling.Timing);

        var (game, alice, bob) = InMainPhase();
        var horse = game.Create(alice, mount, Zone.Battlefield);
        var rider = game.Create(alice, TestCards.Creature("Test Rider", 2, 2), Zone.Battlefield);

        game.ActivateAbility(alice, horse, "saddle", costPayment: [rider]);
        Settle(game);

        Assert.True(game.State.GetObject(horse).Permanent!.IsSaddled);
        Assert.True(game.State.GetObject(rider).Permanent!.IsTapped);

        // This turn's combat, not a later one: being saddled ends with the turn, so passing to a
        // turn three declare-attackers step tests the cleanup rather than the trigger - which is
        // what the first version of this did, and it read as the trigger not working.
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [horse] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.CombatDamage);
        Settle(game);

        Assert.Equal(
            4, Characteristics.Of(game.State, Pool, game.State.GetObject(horse)).Power);

        // CR 514.2: saddled is until end of turn, and it goes with the damage.
        TestCards.PassUntil(game, () => game.State.TurnNumber == 2);
        Assert.False(game.State.GetObject(horse).Permanent!.IsSaddled);
    }

    // ---- Bargain (CR 702.166) -----------------------------------------------

    /// <summary>
    /// Bargain is an optional additional cost - sacrifice an artifact, enchantment or token - and
    /// the clause that reads it back happens only when it was paid.
    /// </summary>
    /// <remarks>
    /// Kicker's shape with a different cost, and deliberately not kicker's flag: the two clauses
    /// are linked to their own ability (CR 607.2), so a card printing both would need each half to
    /// answer for its own. The theory drives both halves because the interesting one is the case
    /// where the clause does *not* happen - a test that only bargained would pass against a
    /// wrapper that ignored the flag entirely.
    /// </remarks>
    [Theory]
    [InlineData(true, 23)]
    [InlineData(false, 20)]
    public void A_bargained_spell_does_the_extra_thing(bool bargained, int expectedLife)
    {
        var offer = Card(
            "Bargain Test Offer",
            "Bargain\nDraw a card. If this spell was bargained, you gain 3 life.",
            CardType.Instant);

        var compiled = CardCompiler.Compile(offer);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.NotNull(compiled.Spell!.BargainCost);

        var (game, alice, _) = InMainPhase();

        var relic = game.Create(
            alice, Card("Bargain Test Relic", string.Empty, CardType.Artifact), Zone.Battlefield);

        var land = game.Create(alice, TestCards.BasicLand("Mountain"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");

        var hand = game.State.GetPlayer(alice).Hand.Count;

        game.CastSpell(
            alice,
            TestCards.PutInHand(game, alice, offer),
            targets: null,
            costPayment: bargained ? [relic] : null,
            bargained: bargained);

        Settle(game);

        Assert.Equal(expectedLife, game.State.GetPlayer(alice).Life);

        // The card is drawn either way; only the extra thing depends on the cost. Counted from
        // before the spell was put in hand, so: one in, one out to the stack, one drawn.
        Assert.Equal(hand + 1, game.State.GetPlayer(alice).Hand.Count);

        // And the cost was really paid - a bargain that took nothing would gain the life anyway.
        Assert.Equal(!bargained, game.State.Battlefield.Contains(relic));
    }

    // ---- "Must be blocked if able" (CR 509.1c) ------------------------------

    /// <summary>
    /// A creature that must be blocked if able compels **one** blocker, not all of them - and
    /// compels nothing when the defender has nothing that could block it.
    /// </summary>
    /// <remarks>
    /// The weaker of the two block requirements, and a different rule rather than a smaller lure:
    /// a lure ("all creatures able to block this do so") compels every creature that can. Both
    /// are checked, separately, because a creature carrying both is answered by neither alone.
    /// </remarks>
    [Fact]
    public void A_creature_that_must_be_blocked_compels_one_blocker()
    {
        var bully = Card(
            "Test Provoker",
            "~ must be blocked if able.",
            CardType.Creature,
            power: 2,
            toughness: 2,

            // Haste, because it is created this turn and the point of the test is the block
            // requirement rather than CR 302.6.
            keywords: KeywordAbility.Haste);

        var compiled = CardCompiler.Compile(bully);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, bully, Zone.Battlefield);
        var blocker = game.Create(bob, TestCards.Creature("Test Bystander", 1, 4), Zone.Battlefield);

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);

        // Declining to block is illegal while something could.
        Assert.Throws<InvalidOperationException>(() => game.DeclareBlockers(
            bob, new Dictionary<ObjectId, IReadOnlyList<ObjectId>>()));

        // Blocking with the one creature that can is enough - "if able" asks for one, and the
        // lure that asks for all of them is a different sentence.
        game.DeclareBlockers(
            bob,
            new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [attacker] = [blocker] });

        Assert.True(game.State.Combat.BlockersDeclared);
    }

    // ---- The shockland: a replacement with two different outcomes -----------

    /// <summary>
    /// "As ~ enters, you may pay 2 life. If you don't, it enters tapped." Paying leaves it
    /// upright and two life lighter; declining taps it and costs nothing.
    /// </summary>
    /// <remarks>
    /// The one shape in the corpus where *both* outcomes differ from the event - arriving upright
    /// and free is the thing the card never does - which is why the replacement needed somewhere
    /// to say what declining means rather than falling back to "the event happens as it was".
    /// </remarks>
    [Theory]
    [InlineData(true, 18, false)]
    [InlineData(false, 20, true)]
    public void A_shockland_asks_and_both_answers_are_different(
        bool pay, int expectedLife, bool expectTapped)
    {
        var shock = new CardDefinition
        {
            OracleId = "oracle-shockland-test",
            Name = "Test Sacred Foundry",
            OracleText = "As ~ enters, you may pay 2 life. If you don't, it enters tapped.",
            CardTypes = CardType.Land,
        };

        var compiled = CardCompiler.Compile(shock);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var land = game.Create(alice, shock, Zone.Battlefield);

        // The question is asked as it arrives, and both answers are on the menu.
        var asked = game.State.Choice;
        Assert.NotNull(asked);
        Assert.Equal(ChoiceKind.OrderReplacements, asked.Kind);

        var decline = asked.Options.Single(o => o.Label.Contains(
            "instead", StringComparison.OrdinalIgnoreCase));

        game.Choose(
            alice,
            [pay ? asked.Options.First(o => o.Id != decline.Id).Id : decline.Id]);

        Settle(game);

        Assert.Equal(expectedLife, game.State.GetPlayer(alice).Life);
        Assert.Equal(expectTapped, game.State.GetObject(land).Permanent!.IsTapped);
    }

    // ---- Enlist (CR 702.154) ------------------------------------------------

    /// <summary>
    /// Enlist offers a tap as the creature attacks, and the attacker gets the tapped creature's
    /// power. Declining is always on the menu, because the rule says "up to one".
    /// </summary>
    /// <remarks>
    /// This was recorded as declined - "needs a runtime-amount pump the engine does not have" -
    /// and re-checking the standing refusals found the note stale: the pump arrived rounds ago and
    /// what was actually missing was somewhere to ask a question as an attack is declared. The
    /// theory drives both answers because "up to one" means the declining half is the card too.
    /// </remarks>
    [Theory]
    [InlineData(true, 5)]
    [InlineData(false, 2)]
    public void An_enlisting_attacker_takes_the_power_of_what_it_taps(bool enlist, int expected)
    {
        var captain = Card(
            "Test Enlisting Captain",
            "Enlist",
            CardType.Creature,
            power: 2,
            toughness: 2,
            keywords: KeywordAbility.Enlist | KeywordAbility.Haste);

        var compiled = CardCompiler.Compile(captain);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, captain, Zone.Battlefield);

        // Three power, and no summoning sickness - a creature that could not have attacked
        // cannot be enlisted either (CR 702.154a).
        var helper = game.Create(alice, TestCards.Creature("Test Recruit", 3, 3), Zone.Battlefield);
        TestCards.PassUntil(game, () => game.State.TurnNumber == 2);
        TestCards.PassUntil(game, () => game.State.TurnNumber == 3
            && game.State.CurrentStep == TurnStep.DeclareAttackers);

        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        var asked = game.State.Choice;
        Assert.NotNull(asked);
        Assert.Equal(ChoiceKind.Enlist, asked.Kind);

        var decline = asked.Options.Single(o => o.Label.Contains(
            "nobody", StringComparison.OrdinalIgnoreCase));

        game.Choose(
            alice,
            [enlist ? asked.Options.First(o => o.Id != decline.Id).Id : decline.Id]);

        Assert.Equal(
            expected, Characteristics.Of(game.State, Pool, game.State.GetObject(attacker)).Power);

        // The tap is the cost, so it happens exactly when the creature was enlisted.
        Assert.Equal(enlist, game.State.GetObject(helper).Permanent!.IsTapped);
    }

    // ---- Support, and "each of" ---------------------------------------------

    /// <summary>
    /// "Support N" is an instruction with its words taken out (CR 701.41a), and which words come
    /// back depends on the card: only a permanent says "other".
    /// </summary>
    /// <remarks>
    /// Put back before anything else reads the line, because what is left - "put a +1/+1 counter
    /// on each of up to two target creatures" - is a sentence this grammar already understands.
    /// The "each of" is removed by the same pass for the same reason: "on each of up to two
    /// target creatures" and "on up to two target creatures" are one instruction, and the engine
    /// already makes one effect per target. 83 cards say it the long way.
    /// </remarks>
    [Fact]
    public void Support_puts_a_counter_on_each_of_up_to_that_many_creatures()
    {
        var relief = Card("Test Relief", "Support 2", CardType.Instant);

        var compiled = CardCompiler.Compile(relief);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.Equal(2, compiled.Spell!.Targets.Count);

        var (game, alice, _) = InMainPhase();
        var first = game.Create(alice, TestCards.Creature("Test Recruit One", 1, 1), Zone.Battlefield);
        var second = game.Create(alice, TestCards.Creature("Test Recruit Two", 2, 2), Zone.Battlefield);

        var land = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");

        game.CastSpell(
            alice,
            TestCards.PutInHand(game, alice, relief),
            [Target.ToPermanent(first), Target.ToPermanent(second)]);

        Settle(game);

        // One counter each, not two on one: "each of" is what the sentence is about.
        Assert.Equal(2, Characteristics.Of(game.State, Pool, game.State.GetObject(first)).Power);
        Assert.Equal(3, Characteristics.Of(game.State, Pool, game.State.GetObject(second)).Power);
    }

    /// <summary>
    /// "Up to two target creatures each get +2/+2 and gain first strike until end of turn" -
    /// two targets, both halves on each of them.
    /// </summary>
    /// <remarks>
    /// The distributive "each" comes out before anything reads the line: the engine makes one
    /// effect per target either way, and the word only says so out loud. Removed strictly between
    /// a target phrase and its verb, so the "each" that is a quantifier - "each creature you
    /// control gets +1/+1" - is left alone, which the compiler probe checked in the same run.
    /// <para>
    /// The second verb has to agree too. The multi-target rewrite makes the sentence singular to
    /// parse it, and "gets +2/+2 and **gain** first strike" is refused by the combined matcher
    /// that wants "and gains" - so a sentence with two verbs was read only when it had one.
    /// </para>
    /// </remarks>
    [Fact]
    public void Two_targets_each_get_both_halves_of_the_sentence()
    {
        var rally = Card(
            "Test Rallying Cry",
            "Up to two target creatures each get +2/+2 and gain first strike until end of turn.",
            CardType.Instant);

        var compiled = CardCompiler.Compile(rally);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.Equal(2, compiled.Spell!.Targets.Count);

        var (game, alice, _) = InMainPhase();
        var first = game.Create(alice, TestCards.Creature("Test Rally One", 1, 1), Zone.Battlefield);
        var second = game.Create(alice, TestCards.Creature("Test Rally Two", 2, 2), Zone.Battlefield);

        var land = game.Create(alice, TestCards.BasicLand("Plains"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");

        game.CastSpell(
            alice,
            TestCards.PutInHand(game, alice, rally),
            [Target.ToPermanent(first), Target.ToPermanent(second)]);

        Settle(game);

        foreach (var (id, printed) in new[] { (first, 1), (second, 2) })
        {
            var computed = Characteristics.Of(game.State, Pool, game.State.GetObject(id));
            Assert.Equal(printed + 2, computed.Power);
            Assert.True(computed.Has(KeywordAbility.FirstStrike));
        }
    }

    [Fact]
    public void A_target_that_left_in_response_is_skipped_and_the_rest_still_happen()
    {
        // CR 608.2b. A spell is countered on resolution only when *every* target has become
        // illegal; with one still legal it resolves and does as much as it can with the rest.
        // That leaves an effect holding an id that no longer names a permanent, and the guard
        // for it cannot be reached by any single-target spell, because those are countered
        // before an effect ever runs. Without the guard the reducer is asked to move something
        // out of a zone it already left and refuses - a crash in the middle of a resolution
        // rather than a wrong answer.
        var strike = Card(
            "Test Twin Strike", "Destroy up to two target creatures.", CardType.Instant);

        var compiled = CardCompiler.Compile(strike);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.Equal(2, compiled.Spell!.Targets.Count);

        var (game, alice, bob) = InMainPhase();
        var doomed = game.Create(bob, TestCards.Creature("Test Twin Doomed", 1, 1), Zone.Battlefield);
        var escaped = game.Create(bob, TestCards.Creature("Test Twin Escaped", 2, 2), Zone.Battlefield);

        var land = game.Create(alice, TestCards.BasicLand("Plains"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");

        game.CastSpell(
            alice,
            TestCards.PutInHand(game, alice, strike),
            [Target.ToPermanent(doomed), Target.ToPermanent(escaped)]);

        // Gone before it resolves, which is the commonest way a target stops being legal.
        game.Move(escaped, Zone.Graveyard, MoveCause.Destroy);

        Settle(game);

        Assert.DoesNotContain(doomed, game.State.Battlefield);
    }

    [Fact]
    public void A_bounce_target_that_left_in_response_is_skipped()
    {
        // The same rule as above, on the other effect that moves a permanent. Destroy and bounce
        // each keep their own guard, so one test cannot stand for both.
        var recall = Card(
            "Test Twin Recall",
            "Return up to two target creatures to their owners' hands.",
            CardType.Instant);

        var compiled = CardCompiler.Compile(recall);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.Equal(2, compiled.Spell!.Targets.Count);

        var (game, alice, bob) = InMainPhase();
        var returned = game.Create(bob, TestCards.Creature("Test Recall Home", 1, 1), Zone.Battlefield);
        var escaped = game.Create(bob, TestCards.Creature("Test Recall Escaped", 2, 2), Zone.Battlefield);

        var land = game.Create(alice, TestCards.BasicLand("Island"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");

        game.CastSpell(
            alice,
            TestCards.PutInHand(game, alice, recall),
            [Target.ToPermanent(returned), Target.ToPermanent(escaped)]);

        game.Move(escaped, Zone.Graveyard, MoveCause.Destroy);

        Settle(game);

        Assert.DoesNotContain(returned, game.State.Battlefield);
        Assert.Contains(game.State.GetPlayer(bob).Hand, id => game.State.GetObject(id).Card.Name == "Test Recall Home");
    }

    /// <summary>
    /// "Counter target spell unless its controller pays {2}. Scry 1." - a sentence after the
    /// offer no longer stops the offer being read.
    /// </summary>
    /// <remarks>
    /// The offer was registered only at the top of a whole phrase. A line with a second sentence
    /// after it is split into sentences, and the first sentence then reached a reader that had
    /// never been told about it - so the line was unread while each of its halves read alone. A
    /// corpus sweep for exactly that shape found seven lines in 32,765 cards and six were this
    /// one, which is also why the general fear about conjunctions was misplaced.
    /// <para>
    /// The borrowed parse has to be shifted, too: it is built against a list of one and aims at
    /// target zero, which is only the right index when the offer is the whole phrase.
    /// </para>
    /// </remarks>
    [Fact]
    public void An_offer_still_reads_with_a_sentence_after_it()
    {
        var refusal = Card(
            "Test Toll Collector",
            "Counter target spell unless its controller pays {2}. Scry 1.",
            CardType.Instant);

        var compiled = CardCompiler.Compile(refusal);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        // One target - the spell - and both halves of the line, in the order it says them.
        Assert.Single(compiled.Spell!.Targets);
        Assert.Equal(2, compiled.Spell.Effects.Count);
        Assert.IsType<MayPay>(compiled.Spell.Effects[0]);

        // The offer aims at the spell that is actually there, which is the half the shift is for.
        var offer = (MayPay)compiled.Spell.Effects[0];
        Assert.Equal(0, offer.AskTargetController);
    }

    // ---- "Other" in a group phrase ------------------------------------------

    /// <summary>
    /// "Other creatures you control get +1/+1" pumps everything the controller has except the
    /// permanent whose ability it is.
    /// </summary>
    /// <remarks>
    /// Found by sweeping the corpus for unread lines that a *single removal* would make readable:
    /// dropping the word "other" unlocked **127 distinct lines**, which is a gap rather than a
    /// licence - a lord that pumps itself is a different card. So the word is lifted off before
    /// the noun is read and put back as a filter, layered onto whatever the phrase already asked
    /// for rather than replacing it: the source is one more thing the group is not, not the only
    /// thing.
    /// <para>
    /// The assertion that matters is the lord's own power. A test that only checked the other
    /// creature would pass just as well against a reader that ignored the word.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_lord_that_says_other_does_not_pump_itself()
    {
        var lord = Card(
            "Test Pack Leader",
            "Other creatures you control get +1/+1.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var compiled = CardCompiler.Compile(lord);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var leader = game.Create(alice, lord, Zone.Battlefield);
        var friend = game.Create(alice, TestCards.Creature("Test Pack Member", 1, 1), Zone.Battlefield);
        var stranger = game.Create(bob, TestCards.Creature("Test Stranger", 1, 1), Zone.Battlefield);

        Settle(game);

        Assert.Equal(2, Characteristics.Of(game.State, Pool, game.State.GetObject(leader)).Power);
        Assert.Equal(2, Characteristics.Of(game.State, Pool, game.State.GetObject(friend)).Power);
        Assert.Equal(1, Characteristics.Of(game.State, Pool, game.State.GetObject(stranger)).Power);

        // Two of them would pump each other and neither would pump itself.
        var second = game.Create(alice, lord, Zone.Battlefield);
        Settle(game);

        Assert.Equal(3, Characteristics.Of(game.State, Pool, game.State.GetObject(leader)).Power);
        Assert.Equal(3, Characteristics.Of(game.State, Pool, game.State.GetObject(second)).Power);
    }

    // ---- Counting counters rather than permanents ---------------------------

    /// <summary>
    /// "For each charge counter on ~" counts what is *on* one permanent, not how many permanents
    /// there are - the same words asking a different question.
    /// </summary>
    /// <remarks>
    /// Found by breaking the "for each" tails down by what follows them: counting counters on the
    /// source is 26 corpus lines across four spellings, differing only in whether the permanent is
    /// named "~" or "it". Both mean the source, because a counting phrase has no target of its own
    /// to point at.
    /// <para>
    /// The tilde also had to be let into the noun class the counting phrases share. It is safe
    /// where "+" and "/" are not: those two turned "target creature gets +2/+2" into a target
    /// called "creature gets +2/+2", which is why the class excludes them and still does - the
    /// "+1/+1 counter on ~" spellings remain unread for that reason.
    /// </para>
    /// </remarks>
    [Fact]
    public void An_amount_can_count_the_counters_on_the_source()
    {
        var reliquary = Card(
            "Test Charge Reliquary",
            "{T}: You gain 1 life for each charge counter on ~.",
            CardType.Artifact);

        var compiled = CardCompiler.Compile(reliquary);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var relic = game.Create(alice, reliquary, Zone.Battlefield);

        game.AddCounters(relic, "charge", 3);
        game.ActivateAbility(alice, relic, compiled.Activated.Single().Id);
        Settle(game);

        Assert.Equal(23, game.State.GetPlayer(alice).Life);
    }

    /// <summary>
    /// "…, then attach ~ to it" attaches the source to the creature the sentence before it chose.
    /// </summary>
    /// <remarks>
    /// The grammar already read this the other way round - "attach it to target creature you
    /// control", where the pronoun is the Equipment. Here the pronoun is the *destination*, and
    /// it means what every other "it" in this grammar means: the target already chosen. 16 corpus
    /// lines end this way, and they were unread while their mirror image was not.
    /// </remarks>
    [Fact]
    public void Equipment_can_attach_itself_to_what_the_sentence_just_targeted()
    {
        // Equipment rather than an Aura: an Aura that reaches the battlefield attached to
        // nothing is put into its owner's graveyard by state-based action (CR 704.5m), so the
        // fixture would be gone before its own trigger resolved. Equipment simply sits there.
        var bond = Card(
            "Test Binding Vow",
            "When ~ enters, put a +1/+1 counter on target creature, then attach ~ to it.",
            CardType.Artifact,
            subtypes: "Equipment");

        var compiled = CardCompiler.Compile(bond);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var bear = game.Create(alice, TestCards.Creature("Test Bound Bear", 2, 2), Zone.Battlefield);

        game.Create(alice, bond, Zone.Battlefield);
        Settle(game);

        // Both halves aimed at the same creature: the counter went on it and the Aura is on it.
        Assert.Equal(3, Characteristics.Of(game.State, Pool, game.State.GetObject(bear)).Power);

        var aura = game.State.Battlefield
            .Select(game.State.GetObject)
            .Single(o => o.Card.OracleId == bond.OracleId);

        Assert.Equal(bear, aura.Permanent!.AttachedTo);
    }

    // ---- A fold has to be total ---------------------------------------------

    /// <summary>
    /// An event about an object that is no longer there folds to "nothing happens", not to an
    /// exception.
    /// </summary>
    /// <remarks>
    /// Found by an ability that attached its source to a target: the source was an Aura that
    /// state-based actions had already buried (CR 704.5m), the attach was emitted anyway, and the
    /// reducer's arm asked for the object outright and threw - taking the whole game down for
    /// something the rules answer with "then it does not happen".
    /// <para>
    /// Every arm that changes one object by id now asks whether it is there. This checks the
    /// shapes together rather than one test each, because what is being asserted is the *rule*
    /// and not any of them in particular - and a new arm that forgets it is what the test is for.
    /// The zone-change arm is deliberately not in the list: a move naming a missing object, or
    /// one leaving a zone it is not in, is an emitter bug and its loud complaint is worth keeping.
    /// </para>
    /// </remarks>
    [Fact]
    public void An_event_about_a_departed_object_folds_to_nothing()
    {
        var (game, _, _) = InMainPhase();
        var before = game.State;
        var gone = ObjectId.New();

        GameEvent[] about =
        [
            new PermanentAttached(gone, null),
            new DamageMarked(gone, 2),
            new CountersChanged(gone, "+1/+1", 1),
            new BecameMonstrous(gone),
            new CharacteristicChosen(gone, "red"),
            new RegenerationShieldsChanged(gone, 1),
            new PreventionChanged(gone, 1),
            new ObjectCeasedToExist(gone, Zone.Battlefield),
            new SpellKicked(gone),
            new SpellBargained(gone),
            new SpellMultikicked(gone, 2),
            new PermanentTransformed(gone, 1),
            new PermanentSaddled(gone),
        ];

        foreach (var e in about)
        {
            var after = GameReducer.Apply(before, e);
            Assert.Equal(before, after);
        }

    }

    // ---- Blinking yourself, and coming back turned over ---------------------

    /// <summary>
    /// "Exile ~, then return it to the battlefield transformed under your control" - the source
    /// leaves, comes back as a new object (CR 400.7), and arrives showing its other face.
    /// </summary>
    /// <remarks>
    /// The targeted form of this sentence was already read; the *self* form was not, on 28 corpus
    /// lines. They are kept apart rather than folded together because a card that blinks itself is
    /// usually doing it to arrive as its other face, which is a thing the targeted form never says
    /// - and which only became expressible when transform did.
    /// <para>
    /// What comes back is a new object, so nothing it had before travels with it. The counter put
    /// on it here is what proves that, and it is the assertion a test of the face alone would
    /// miss.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_permanent_can_blink_itself_and_return_transformed()
    {
        var pilgrim = new CardDefinition
        {
            OracleId = "oracle-self-blink-test",
            Name = "Test Wandering Pilgrim",
            OracleText = "{3}: Exile ~, then return it to the battlefield transformed under your control.",
            CardTypes = CardType.Creature,
            Power = 1,
            Toughness = 1,
            ManaCostRaw = "{1}{U}",
            Faces =
            [
                new CardFace
                {
                    Name = "Test Wandering Pilgrim",
                    CardTypes = CardType.Creature,
                    Power = 1,
                    Toughness = 1,
                    OracleText = "{3}: Exile ~, then return it to the battlefield transformed under your control.",
                },
                new CardFace
                {
                    Name = "Test Returned Pilgrim",
                    CardTypes = CardType.Creature,
                    Power = 4,
                    Toughness = 4,
                },
            ],
        };

        var compiled = CardCompiler.Compile(pilgrim);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var walker = game.Create(alice, pilgrim, Zone.Battlefield);
        game.AddCounters(walker, "+1/+1", 1);

        foreach (var _ in Enumerable.Range(0, 3))
        {
            var land = game.Create(alice, TestCards.BasicLand("Island"), Zone.Battlefield);
            game.ActivateAbility(alice, land, "mana");
        }

        game.ActivateAbility(alice, walker, compiled.Activated.Single().Id);
        Settle(game);

        // A new object, so the old id is gone and the counter did not come with it.
        Assert.DoesNotContain(walker, game.State.Battlefield);

        var returned = game.State.Battlefield
            .Select(game.State.GetObject)
            .Single(o => o.Card.Faces.Count > 1);

        Assert.Equal(1, returned.Permanent!.FaceIndex);
        Assert.Equal(4, Characteristics.Of(game.State, Pool, returned).Power);
        Assert.Empty(returned.Permanent.Counters);
    }

    /// <summary>
    /// "Up to two **other** target creatures" excludes the permanent whose ability it is - and
    /// the singular of that sentence has read since the target grammar was built.
    /// </summary>
    /// <remarks>
    /// The rewrite that turns a counted target phrase into a singular one to parse it did not
    /// allow the word between the number and "target", so "another target creature" read and "two
    /// other target creatures" did not, on 46 corpus lines. The rewrite now says "another", which
    /// is how the singular grammar already spells it - so every reader that handled one of those
    /// handles all of them, and nothing new had to learn what "other" means.
    /// </remarks>
    [Fact]
    public void A_counted_target_phrase_can_exclude_the_source()
    {
        var herald = Card(
            "Test Counter Herald",
            "When ~ enters, put a +1/+1 counter on up to two other target creatures.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var compiled = CardCompiler.Compile(herald);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.Equal(2, compiled.Triggers.Single().Targets.Count);

        // Both targets exclude the source, so the herald cannot be offered as one of them.
        Assert.All(
            compiled.Triggers.Single().Targets,
            spec => Assert.NotNull(spec.SourceFilter));

        var (game, alice, _) = InMainPhase();
        var first = game.Create(alice, TestCards.Creature("Test Herald One", 1, 1), Zone.Battlefield);
        var second = game.Create(alice, TestCards.Creature("Test Herald Two", 1, 1), Zone.Battlefield);

        var source = game.Create(alice, herald, Zone.Battlefield);
        Settle(game);

        // Which of the two got which counter is the harness's choice, not the card's - it answers
        // every question with its first option. What the card decides is that the herald is not
        // among the answers, so that is what is asserted: two counters went out, and none of them
        // to the source.
        Assert.Empty(game.State.GetObject(source).Permanent!.Counters);

        var given = new[] { first, second }
            .Select(game.State.GetObject)
            .Sum(o => o.Permanent!.Counters.TryGetValue("+1/+1", out var many) ? many : 0);

        Assert.Equal(2, given);
    }

    /// <summary>
    /// "That creature" is "it" with more words: both mean the target the sentence before chose.
    /// </summary>
    /// <remarks>
    /// The pronoun readers for the verbs that take one - untap, tap, destroy, exile, return -
    /// have accepted both spellings for a long time. The three that grant or pump accepted only
    /// "it", so "Put a +1/+1 counter on target creature. **That creature** gains indestructible
    /// until end of turn" was unread while the same card saying "it" was, on 19 corpus lines.
    /// <para>
    /// Both halves are asserted because the point is that they meet on the same creature: the
    /// counter and the keyword have to land on the one thing the spell targeted.
    /// </para>
    /// </remarks>
    [Fact]
    public void That_creature_means_the_same_thing_as_it()
    {
        var blessing = Card(
            "Test Steadfast Blessing",
            "Put a +1/+1 counter on target creature. That creature gains indestructible until end of turn.",
            CardType.Instant);

        var compiled = CardCompiler.Compile(blessing);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.Single(compiled.Spell!.Targets);

        var (game, alice, _) = InMainPhase();
        var bear = game.Create(alice, TestCards.Creature("Test Blessed Bear", 2, 2), Zone.Battlefield);

        var land = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");

        game.CastSpell(
            alice,
            TestCards.PutInHand(game, alice, blessing),
            [Target.ToPermanent(bear)]);

        Settle(game);

        var computed = Characteristics.Of(game.State, Pool, game.State.GetObject(bear));
        Assert.Equal(3, computed.Power);
        Assert.True(computed.Has(KeywordAbility.Indestructible));
    }

    // ---- "You may" with nothing to pay --------------------------------------

    /// <summary>
    /// "Whenever ~ attacks, you may draw a card" - the controller is asked, and declining does
    /// nothing at all.
    /// </summary>
    /// <remarks>
    /// The commonest optional effect in the game and it had no reader: 45 corpus lines say "you
    /// may [something]" with no price attached, and every one of them read with the two words
    /// taken off. Taking them off is not an option - a trigger that always draws is a different
    /// card - so the sentence becomes the free offer the engine already had for "you may sacrifice
    /// a creature. If you do, …", with the sentence's own words as the button.
    /// <para>
    /// It is read **last**, after every reader that knows a particular "you may", so the general
    /// shape never takes a sentence one of those would have understood better.
    /// </para>
    /// </remarks>
    [Theory]
    [InlineData(true, 1)]
    [InlineData(false, 0)]
    public void An_optional_trigger_effect_can_be_declined(bool accept, int expectedDrawn)
    {
        var scout = Card(
            "Test Opportunist",
            "Whenever ~ attacks, you may draw a card.",
            CardType.Creature,
            power: 2,
            toughness: 2,
            keywords: KeywordAbility.Haste);

        var compiled = CardCompiler.Compile(scout);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, scout, Zone.Battlefield);

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        var hand = game.State.GetPlayer(alice).Hand.Count;

        // By hand rather than through Settle, which answers every question with its first option
        // - and which of the two answers is taken is the whole of what this test is about.
        for (var guard = 0; guard < 20 && game.State.Choice is null; guard++)
        {
            if (game.State.Priority.Holder is not { } holder)
                break;

            game.PassPriority(holder);
        }

        var asked = game.State.Choice;
        Assert.NotNull(asked);

        var no = asked.Options.Single(o => o.Label.Contains(
            "decline", StringComparison.OrdinalIgnoreCase));

        game.Choose(
            alice,
            [accept ? asked.Options.First(o => o.Id != no.Id).Id : no.Id]);

        Settle(game);

        Assert.Equal(hand + expectedDrawn, game.State.GetPlayer(alice).Hand.Count);
    }

    /// <summary>
    /// "Target nonland permanent card in your graveyard" - a type word with a type taken out of
    /// it, and a land in the graveyard is not a legal choice.
    /// </summary>
    /// <remarks>
    /// "Permanent card" read and "nonland permanent card" did not, on 7 corpus lines, for two
    /// reasons at once: the phrase pattern took a single-word noun, and the type table it hands
    /// that noun to has no entry for a type with a type removed. The word is now lifted off before
    /// the table is asked, so every noun the table knows keeps working with it in front.
    /// <para>
    /// The land in the graveyard is the assertion that matters. A test with only the creature in
    /// it would pass against a reader that ignored the word entirely.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_nonland_permanent_card_target_will_not_take_a_land()
    {
        var raising = Card(
            "Test Grave Recall",
            "Return target nonland permanent card from your graveyard to your hand.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(raising);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var spec = Assert.Single(compiled.Spell!.Targets);
        Assert.Equal(TargetKind.CardInGraveyard, spec.Kind);

        var (game, alice, _) = InMainPhase();
        var bear = game.Create(alice, TestCards.Creature("Test Buried Bear", 2, 2), Zone.Graveyard);
        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Graveyard);

        Assert.True(spec.ObjectFilter!.Invoke(
            game.State, Pool, game.State.GetObject(bear), alice));

        Assert.False(spec.ObjectFilter.Invoke(
            game.State, Pool, game.State.GetObject(forest), alice));
    }

    /// <summary>
    /// A search for a card "with mana value N or greater" offers only the cards that are, and a
    /// search for "N or less" offers only the cards that are not.
    /// </summary>
    /// <remarks>
    /// The search grammar had a cap and no floor, so "or less" read and "or greater" did not, on
    /// 16 corpus lines. Two nullable numbers rather than a signed range, because a card names one
    /// or the other and never both - and two nulls say "no limit" without a sentinel.
    /// <para>
    /// Driven through the offered list rather than the compiled record: what a limit is *for* is
    /// which cards a player may pick, and a floor stored and never consulted would pass a test
    /// that only read the effect back.
    /// </para>
    /// </remarks>
    [Theory]
    [InlineData("6 or greater", "Test Heavy Relic")]
    [InlineData("2 or less", "Test Light Relic")]
    public void A_search_can_have_a_floor_as_well_as_a_cap(string limit, string expected)
    {
        // A name per case: the pool refuses two different cards under one oracle id, and the
        // helper derives the id from the name - so a theory that varies the text has to vary the
        // name with it.
        var seeker = Card(
            "Test Relic Seeker " + limit.Split(' ')[0],
            $"When ~ enters, search your library for an artifact card with mana value {limit}, "
                + "reveal it, put it into your hand, then shuffle.",
            CardType.Creature,
            power: 1,
            toughness: 1);

        var compiled = CardCompiler.Compile(seeker);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var heavy = new CardDefinition
        {
            OracleId = "oracle-heavy-relic-test",
            Name = "Test Heavy Relic",
            CardTypes = CardType.Artifact,
            Cmc = 7,
            ManaCostRaw = "{7}",
        };

        var light = new CardDefinition
        {
            OracleId = "oracle-light-relic-test",
            Name = "Test Light Relic",
            CardTypes = CardType.Artifact,
            Cmc = 1,
            ManaCostRaw = "{1}",
        };

        var (game, alice, _) = InMainPhase();
        game.Create(alice, heavy, Zone.Library);
        game.Create(alice, light, Zone.Library);
        game.Create(alice, seeker, Zone.Battlefield);

        for (var guard = 0; guard < 20 && game.State.Choice is null; guard++)
        {
            if (game.State.Priority.Holder is not { } holder)
                break;

            game.PassPriority(holder);
        }

        var asked = game.State.Choice;
        Assert.NotNull(asked);

        // Only the one the limit admits is on the menu. The other relic is in the same library.
        Assert.Contains(asked.Options, o => o.Label.Contains(expected, StringComparison.Ordinal));
        Assert.DoesNotContain(
            asked.Options,
            o => o.Label.Contains("Relic", StringComparison.Ordinal)
                && !o.Label.Contains(expected, StringComparison.Ordinal));
    }

    // ---- "If you do" after something that was not a choice ------------------

    /// <summary>
    /// "Tap target untapped creature you control. If you do, you gain 2 life." - the second half
    /// happens only if the first half actually did.
    /// </summary>
    /// <remarks>
    /// The engine understood "if you do" only after a *may* - after an offer, where the answer is
    /// a choice. This is the other half of the phrase: after a **mandatory** action, where the
    /// question is whether the action came off at all. 14 corpus lines.
    /// <para>
    /// "Happened" is read as "produced events", which is the engine's own record of something
    /// occurring - an approximation in one direction only, and stated rather than hidden. The
    /// theory drives both sides: a creature that is already tapped is the case where the
    /// instruction is given and nothing happens, and a test with only the working side would pass
    /// against an effect that ignored the condition.
    /// </para>
    /// </remarks>
    [Theory]
    [InlineData(false, 22)]
    [InlineData(true, 20)]
    public void The_rest_happens_only_if_the_first_part_did(bool alreadyTapped, int expectedLife)
    {
        // "Target creature", not "target *untapped* creature": an already-tapped creature is
        // not a legal target for the latter, so the spell could not be cast at all and the case
        // this is about - a legal target the action whiffs on - would never be reached. The
        // engine refusing that target is correct, and it is what the first version of this test
        // ran into.
        var rite = Card(
            "Test Binding Rite",
            "Tap target creature you control. If you do, you gain 2 life.",
            CardType.Instant);

        var compiled = CardCompiler.Compile(rite);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var bear = game.Create(alice, TestCards.Creature("Test Rite Bear", 2, 2), Zone.Battlefield);

        var land = game.Create(alice, TestCards.BasicLand("Plains"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");

        if (alreadyTapped)
            game.Tap(bear);

        game.CastSpell(
            alice,
            TestCards.PutInHand(game, alice, rite),
            [Target.ToPermanent(bear)]);

        Settle(game);

        Assert.Equal(expectedLife, game.State.GetPlayer(alice).Life);
    }

    // ---- Losing every ability, and a bonus with a clock ---------------------

    /// <summary>
    /// "Enchanted creature loses all abilities and has base power and toughness 1/1" (CR 613.1f).
    /// </summary>
    /// <remarks>
    /// The Aura half of ability removal, and the half where the interesting failure lives. Taking
    /// the keywords off is something an <c>Apply</c> could do; what it cannot do is stop the
    /// silenced permanent's own static abilities being <em>offered</em>, because that decision is
    /// made before any effect is applied and about a permanent that is not the one being
    /// computed. So the enchanted creature is a lord, and the assertion that matters is about the
    /// creature standing next to it: an implementation that only emptied the keywords would pass
    /// every assertion about the Aura's own victim and leave the anthem running.
    /// </remarks>
    [Fact]
    public void An_aura_can_take_every_ability_from_what_it_enchants()
    {
        var transmutation = Card(
            "Kasmina's Transmutation Test",
            "Enchant creature\n"
                + "Enchanted creature loses all abilities and has base power and toughness 1/1.",
            CardType.Enchantment,
            subtypes: "Aura");

        var lord = Card(
            "Transmuted Lord Test",
            "Flying\nOther creatures you control get +1/+1.",
            CardType.Creature,
            3,
            3,
            KeywordAbility.Flying);

        var compiled = CardCompiler.Compile(transmutation);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var flier = game.Create(alice, lord, Zone.Battlefield);
        var grunt = game.Create(
            alice, TestCards.Creature("Transmuted Grunt Test", 2, 2), Zone.Battlefield);

        Assert.Equal(3, Characteristics.Of(game.State, Pool, game.State.GetObject(grunt)).Power);

        game.CastSpell(
            alice,
            TestCards.PutInHand(game, alice, transmutation),
            [Target.ToPermanent(flier)]);

        Settle(game);

        var silenced = Characteristics.Of(game.State, Pool, game.State.GetObject(flier));
        Assert.True(silenced.HasLostAllAbilities);
        Assert.False(silenced.Has(KeywordAbility.Flying));

        // Layer 7b, so the size the Aura names replaces the printed one rather than adding to it.
        Assert.Equal(1, silenced.Power);
        Assert.Equal(1, silenced.Toughness);

        // CR 613.6: the anthem is gone because the ability producing it was removed in layer 6,
        // before layer 7c was ever reached. This is the assertion the flag exists for.
        Assert.Equal(2, Characteristics.Of(game.State, Pool, game.State.GetObject(grunt)).Power);
    }

    /// <summary>
    /// "All creatures lose all abilities and have base power and toughness 1/1" - Humility.
    /// </summary>
    /// <remarks>
    /// The same removal said about a group rather than about one attachment, and the card the
    /// engine's hand-written fixture for this had been imitating for as long as the fixture
    /// existed. It reaches across the table, which is what "all creatures" says and what a mass
    /// static with no ownership clause has been caught getting wrong before.
    /// </remarks>
    [Fact]
    public void Humility_takes_every_creatures_abilities_and_its_size()
    {
        var humility = Card(
            "Humility Test",
            "All creatures lose all abilities and have base power and toughness 1/1.",
            CardType.Enchantment);

        var lord = Card(
            "Humbled Lord Test",
            "Flying\nOther creatures you control get +1/+1.",
            CardType.Creature,
            3,
            3,
            KeywordAbility.Flying);

        var compiled = CardCompiler.Compile(humility);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var flier = game.Create(alice, lord, Zone.Battlefield);
        var grunt = game.Create(
            alice, TestCards.Creature("Humbled Grunt Test", 2, 2), Zone.Battlefield);
        var theirs = game.Create(
            bob, TestCards.Creature("Humbled Stranger Test", 4, 4), Zone.Battlefield);

        game.Create(alice, humility, Zone.Battlefield);
        Settle(game);

        var quieted = Characteristics.Of(game.State, Pool, game.State.GetObject(flier));
        Assert.True(quieted.HasLostAllAbilities);
        Assert.False(quieted.Has(KeywordAbility.Flying));
        Assert.Equal(1, quieted.Power);

        Assert.Equal(1, Characteristics.Of(game.State, Pool, game.State.GetObject(grunt)).Power);

        // Across the table too: "all creatures" names nobody's in particular, and a mass static
        // that quietly meant "you control" is the shape this compiler has already shipped once.
        Assert.Equal(1, Characteristics.Of(game.State, Pool, game.State.GetObject(theirs)).Power);
    }

    /// <summary>
    /// "Until end of turn, target creature loses all abilities and becomes a blue Frog with base
    /// power and toughness 1/1" - Turn to Frog (CR 613.1d, 613.1f, 613.4b).
    /// </summary>
    /// <remarks>
    /// The removal arriving as an effect a spell left behind rather than as anything's static
    /// ability, and one sentence landing in three layers at once. The clause is read by splitting
    /// it off and handing the rest of the sentence back to the animation grammar, so what this
    /// proves is that the two halves still agree about which creature they are talking about -
    /// the failure a rewrite of this kind would produce is a spell that asks for two targets.
    /// </remarks>
    [Fact]
    public void A_spell_can_turn_a_lord_into_a_frog_for_the_turn()
    {
        var frog = Card(
            "Turn to Frog Test",
            "Until end of turn, target creature loses all abilities and becomes a blue Frog "
                + "with base power and toughness 1/1.",
            CardType.Instant);

        var lord = Card(
            "Frogged Lord Test",
            "Flying\nOther creatures you control get +1/+1.",
            CardType.Creature,
            3,
            3,
            KeywordAbility.Flying);

        var compiled = CardCompiler.Compile(frog);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        // One target, not two: the sentence names its creature once, and a rewrite that let both
        // halves read the phrase would make the spell ask its controller to choose twice.
        Assert.Single(compiled.Spell!.Targets);

        var (game, alice, _) = InMainPhase();
        var flier = game.Create(alice, lord, Zone.Battlefield);
        var grunt = game.Create(
            alice, TestCards.Creature("Frogged Grunt Test", 2, 2), Zone.Battlefield);

        game.CastSpell(
            alice,
            TestCards.PutInHand(game, alice, frog),
            [Target.ToPermanent(flier)]);

        Settle(game);

        var toad = Characteristics.Of(game.State, Pool, game.State.GetObject(flier));
        Assert.True(toad.HasLostAllAbilities);
        Assert.False(toad.Has(KeywordAbility.Flying));
        Assert.Equal(1, toad.Power);
        Assert.Contains("Frog", toad.Subtypes, StringComparer.OrdinalIgnoreCase);
        Assert.Contains(ManaColor.Blue, toad.Colors);
        Assert.Equal(2, Characteristics.Of(game.State, Pool, game.State.GetObject(grunt)).Power);

        // And it is the turn's effect it says it is: cleanup takes all three layers back off.
        TestCards.PassToTurn(game, 2);

        var restored = Characteristics.Of(game.State, Pool, game.State.GetObject(flier));
        Assert.False(restored.HasLostAllAbilities);
        Assert.True(restored.Has(KeywordAbility.Flying));
        Assert.Equal(3, restored.Power);
        Assert.Equal(3, Characteristics.Of(game.State, Pool, game.State.GetObject(grunt)).Power);
    }

    /// <summary>
    /// "Target creature gets +2/+2 and has trample for as long as ~ remains tapped" (CR 611.2b).
    /// </summary>
    /// <remarks>
    /// The Couriers' sentence - one clause, two layers, and a duration that is a condition rather
    /// than a turn number. Untapping the source is what ends it, and the last assertion is what
    /// separates an ending from a pause: CR 611.2b says the effect is over and does not begin
    /// again, so tapping the source a second time must not bring the old bonus back.
    /// <para>
    /// The mana cost and the tribal filter of the printed cards are dropped so the ability can be
    /// activated on turn one; the sentence under test is theirs word for word.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_bonus_held_while_the_source_is_tapped_ends_when_it_untaps()
    {
        var weaponry = new CardDefinition
        {
            OracleId = "oracle-courier-weaponry-test",
            Name = "Courier Weaponry Test",
            OracleText = "{T}: Target creature gets +2/+2 and has trample "
                + "for as long as ~ remains tapped.",
            CardTypes = CardType.Artifact,
            ManaCostRaw = "{2}",
            Cmc = 2,
        };

        var compiled = CardCompiler.Compile(weaponry);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var bear = game.Create(
            alice, TestCards.Creature("Couriered Bear Test", 2, 2), Zone.Battlefield);
        var gear = game.Create(alice, weaponry, Zone.Battlefield);

        game.ActivateAbility(alice, gear, "a", [Target.ToPermanent(bear)]);
        Settle(game);

        var armed = Characteristics.Of(game.State, Pool, game.State.GetObject(bear));
        Assert.Equal(4, armed.Power);
        Assert.True(armed.Has(KeywordAbility.Trample));

        // It outlives the turn, which an until-end-of-turn pump would not.
        TestCards.PassToTurn(game, 2);
        Assert.Equal(4, Characteristics.Of(game.State, Pool, game.State.GetObject(bear)).Power);

        // Alice's untap step unties it, through the ordinary rule rather than by hand.
        TestCards.PassToTurn(game, 3);
        Settle(game);

        var disarmed = Characteristics.Of(game.State, Pool, game.State.GetObject(bear));
        Assert.Equal(2, disarmed.Power);
        Assert.False(disarmed.Has(KeywordAbility.Trample));

        // Ended, not paused: the condition becoming true again does not restart it.
        game.Tap(gear);
        Settle(game);
        Assert.Equal(2, Characteristics.Of(game.State, Pool, game.State.GetObject(bear)).Power);
    }

    /// <summary>
    /// "That creature doesn't untap during its controller's untap step for as long as ~ remains
    /// tapped" (CR 502.3, 611.2b).
    /// </summary>
    /// <remarks>
    /// The pronoun form: the sentence before it tapped a target, and this one is about that same
    /// creature rather than about another. Twenty-one corpus cards print the pair, and the
    /// restriction they impose is one the engine already had - only the duration was missing.
    /// </remarks>
    [Fact]
    public void A_creature_tapped_this_way_stays_down_while_the_source_is_tapped()
    {
        var squid = new CardDefinition
        {
            OracleId = "oracle-sand-squid-test",
            Name = "Sand Squid Test",
            OracleText = "{T}: Tap target creature. That creature doesn't untap during its "
                + "controller's untap step for as long as ~ remains tapped.",
            CardTypes = CardType.Artifact,
            ManaCostRaw = "{3}",
            Cmc = 3,
        };

        var compiled = CardCompiler.Compile(squid);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var theirs = game.Create(
            bob, TestCards.Creature("Squidded Bear Test", 2, 2), Zone.Battlefield);
        var trap = game.Create(alice, squid, Zone.Battlefield);

        game.ActivateAbility(alice, trap, "a", [Target.ToPermanent(theirs)]);
        Settle(game);

        Assert.True(game.State.GetObject(theirs).Permanent?.IsTapped);
        Assert.True(
            Characteristics.Of(game.State, Pool, game.State.GetObject(theirs)).DoesNotUntap);

        // Bob's own untap step comes and goes and the creature is still down.
        TestCards.PassToTurn(game, 2);
        Settle(game);
        Assert.True(game.State.GetObject(theirs).Permanent?.IsTapped);

        // Alice's untap step frees the trap, which ends the restriction (CR 611.2b) - and only
        // then does Bob get his creature back, on the untap step after that.
        TestCards.PassToTurn(game, 3);
        Settle(game);
        Assert.False(
            Characteristics.Of(game.State, Pool, game.State.GetObject(theirs)).DoesNotUntap);
        Assert.True(game.State.GetObject(theirs).Permanent?.IsTapped);

        TestCards.PassToTurn(game, 4);
        Settle(game);
        Assert.False(game.State.GetObject(theirs).Permanent?.IsTapped);
    }

    /// <summary>
    /// "Target permanent gains indestructible for as long as you control ~" (CR 611.2b, 613.1f).
    /// </summary>
    /// <remarks>
    /// The third verb the duration is printed with, and the one whose ending is visible without
    /// reading any characteristic: the creature simply dies. The source leaving the battlefield
    /// is enough to end it - a permanent that has left is a different object (CR 400.7), so the
    /// condition names nothing and is false whatever else it asks.
    /// <para>
    /// The printed cards hang this on an enters trigger; here it is an activated ability so that
    /// the source can be removed independently of the creature it protected. The clause is the
    /// same one and is read by the same pattern.
    /// </para>
    /// </remarks>
    [Fact]
    public void Indestructible_held_while_you_control_the_source_ends_when_it_leaves()
    {
        var aegis = new CardDefinition
        {
            OracleId = "oracle-aegis-relic-test",
            Name = "Aegis Relic Test",
            OracleText = "{T}: Target creature gains indestructible for as long as you control ~.",
            CardTypes = CardType.Artifact,
            ManaCostRaw = "{2}",
            Cmc = 2,
        };

        var doom = Card("Aegis Doom Blade Test", "Destroy target creature.", CardType.Instant);

        var compiled = CardCompiler.Compile(aegis);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var bear = game.Create(
            alice, TestCards.Creature("Aegis Bear Test", 2, 2), Zone.Battlefield);
        var relic = game.Create(alice, aegis, Zone.Battlefield);

        game.ActivateAbility(alice, relic, "a", [Target.ToPermanent(bear)]);
        Settle(game);

        Assert.True(
            Characteristics.Of(game.State, Pool, game.State.GetObject(bear))
                .Has(KeywordAbility.Indestructible));

        // Alice's next turn, because settling the activation spent the priority she cast with.
        PassToMainPhaseOfTurn(game, 3);

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, doom), [Target.ToPermanent(bear)]);
        Settle(game);

        Assert.Contains(bear, game.State.Battlefield);

        // The relic goes, and the shield goes with it rather than outliving its source.
        game.Move(relic, Zone.Graveyard, MoveCause.Destroy);
        Settle(game);

        Assert.False(
            Characteristics.Of(game.State, Pool, game.State.GetObject(bear))
                .Has(KeywordAbility.Indestructible));

        PassToMainPhaseOfTurn(game, 5);

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, doom), [Target.ToPermanent(bear)]);
        Settle(game);

        Assert.DoesNotContain(bear, game.State.Battlefield);
    }

    // ---- Counting a zone rather than the board ------------------------------

    /// <summary>
    /// "Where X is the number of creature cards in your graveyard" counts a *pile*, and counts
    /// only the cards the noun in front admits.
    /// </summary>
    /// <remarks>
    /// The counting vocabulary walked the battlefield, so "the number of creatures you control"
    /// read and "the number of creature cards in your graveyard" did not. The sweep put "where X
    /// is …" at the top with 295 lines, and this is what most of them were waiting on - the same
    /// question about a different pile.
    /// <para>
    /// A noun the type table does not know leaves the phrase unread rather than counting
    /// everything: "the number of Zombie cards" is not "the number of cards". The land in the
    /// graveyard is what proves the noun is being read at all.
    /// </para>
    /// </remarks>
    [Fact]
    public void An_amount_can_count_the_cards_in_a_graveyard()
    {
        var surge = Card(
            "Test Graveyard Surge",
            "Target creature gets +X/+0 until end of turn, where X is the number of creature cards in your graveyard.",
            CardType.Instant);

        var compiled = CardCompiler.Compile(surge);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var bear = game.Create(alice, TestCards.Creature("Test Surge Bear", 2, 2), Zone.Battlefield);

        game.Create(alice, TestCards.Creature("Test Dead One", 1, 1), Zone.Graveyard);
        game.Create(alice, TestCards.Creature("Test Dead Two", 1, 1), Zone.Graveyard);

        // Not a creature, so it is not counted - which is the half that proves the noun is read.
        game.Create(alice, TestCards.BasicLand("Forest"), Zone.Graveyard);

        var land = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");

        game.CastSpell(
            alice,
            TestCards.PutInHand(game, alice, surge),
            [Target.ToPermanent(bear)]);

        Settle(game);

        Assert.Equal(4, Characteristics.Of(game.State, Pool, game.State.GetObject(bear)).Power);
    }

    // ---- "Creature token" is a noun, not two nouns --------------------------

    /// <summary>
    /// "Target creature token" is a creature and a token, and a creature that is not a token is
    /// not a legal choice.
    /// </summary>
    /// <remarks>
    /// The noun alternation in the target pattern is **ordered**, and "creature" sat in front of
    /// "creature token" - so the bare word won, the leftover " token" had nowhere to go, and the
    /// phrase failed. The compounds are in front of the bare words now, which is the whole fix;
    /// the type table gained the pairs to go with them.
    /// <para>
    /// The non-token creature is what carries the test. A version with only the token in it would
    /// pass against a reader that took "creature" and dropped the rest - which is exactly what the
    /// pattern did.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_creature_token_target_will_not_take_a_creature_card()
    {
        var jolt = Card("Test Token Jolt", "Destroy target creature token.", CardType.Instant);

        var compiled = CardCompiler.Compile(jolt);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var spec = Assert.Single(compiled.Spell!.Targets);

        var (game, alice, _) = InMainPhase();

        var real = game.Create(alice, TestCards.Creature("Test Real Bear", 2, 2), Zone.Battlefield);
        var token = game.Create(
            alice,
            new CardDefinition
            {
                OracleId = "oracle-test-bear-token",
                Name = "Test Bear Token",
                CardTypes = CardType.Creature | CardType.Token,
                Power = 2,
                Toughness = 2,
            },
            Zone.Battlefield);

        Assert.True(spec.ObjectFilter!.Invoke(
            game.State, Pool, game.State.GetObject(token), alice));

        Assert.False(spec.ObjectFilter.Invoke(
            game.State, Pool, game.State.GetObject(real), alice));
    }

    /// <summary>
    /// "Creature tokens you control get +1/+1 until end of turn" pumps the tokens and nothing
    /// else.
    /// </summary>
    /// <remarks>
    /// The bear is what carries this test. The group noun is read by an ordered alternation in
    /// which the bare word "creature" sat in front of the compound, so a sentence that said
    /// "creature token" matched "creature" and left the rest over. A version of this test with
    /// only the token on the battlefield would have passed against exactly that reader - it
    /// pumps a superset, and a superset looks right until something outside it is standing there
    /// to be measured.
    /// <para>
    /// Played rather than asserted against the parse tree, because the group is resolved as the
    /// effect resolves (CR 611.2) and it is the resolution that has to pick the right pile.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_pump_aimed_at_creature_tokens_leaves_a_real_creature_alone()
    {
        var muster = Card(
            "Test Token Muster", "Creature tokens you control get +1/+1 until end of turn.");

        var compiled = CardCompiler.Compile(muster);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();

        var bear = game.Create(alice, TestCards.Creature("Test Muster Bear", 2, 2), Zone.Battlefield);
        var token = game.Create(
            alice,
            new CardDefinition
            {
                OracleId = "oracle-test-muster-token",
                Name = "Test Muster Token",
                CardTypes = CardType.Creature | CardType.Token,
                Power = 1,
                Toughness = 1,
            },
            Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, muster);
        game.CastSpell(alice, card, []);
        Settle(game);

        Assert.Equal(2, Characteristics.Of(game.State, Pool, game.State.GetObject(token)).Power);
        Assert.Equal(2, Characteristics.Of(game.State, Pool, game.State.GetObject(bear)).Power);
    }

    // ---- Entering as a copy (CR 707.5) ---------------------------------------

    /// <summary>The printed Clone, word for word (CR 707.5).</summary>
    private static CardDefinition Cloning(string name, string what = "any creature on the battlefield") =>
        Card(
            name,
            "You may have this creature enter as a copy of " + what + ".",
            CardType.Creature,
            0,
            0);

    /// <summary>
    /// Plays on, answering the copy question with the permanent whose name is given.
    /// </summary>
    /// <remarks>
    /// <see cref="Settle"/> takes the first option of everything and <see cref="SettleDeclining"/>
    /// takes the last, and neither can say <em>which</em> creature. The whole point of this
    /// family is that the choice is a real one, so the tests have to be able to make it — and
    /// picking by the label proves the labels are the thing a person could pick from, which is
    /// the standard the rest of the choices in this engine are held to.
    /// </remarks>
    private static void SettleCopying(Game game, string wanted)
    {
        var passedOnce = false;

        for (var guard = 0; guard < 80; guard++)
        {
            if (game.State.Choice is { } choice)
            {
                var pick = choice.Options.FirstOrDefault(
                    o => o.Label.Contains(wanted, StringComparison.Ordinal));

                game.Choose(
                    choice.PlayerId,
                    pick is not null
                        ? [pick.Id]
                        : [.. choice.Options.Take(Math.Max(choice.MinPicks, 1)).Select(o => o.Id)]);

                continue;
            }

            if (passedOnce && game.State.Stack.IsEmpty && game.State.PendingTriggers.IsEmpty)
                break;

            if (game.State.Priority.Holder is not { } holder)
                break;

            game.PassPriority(holder);
            passedOnce = true;
        }

        // The copied card rides whole inside the effect's name, which makes it much the largest
        // thing this engine puts in a log — and the choice that produced it is an event too.
        Assert.Equal(game.State, GameReducer.Replay(game.Log));
    }

    /// <summary>
    /// A compiled Clone asks which creature to copy, and the copy's own enters ability fires
    /// (CR 707.5).
    /// </summary>
    /// <remarks>
    /// The life total is the assertion that matters. Every characteristic below would be just as
    /// green if the copy had been applied one event too late — the permanent would still have the
    /// right name and the right size, and the trigger the rule promises would simply never have
    /// existed, because triggers are collected against the state just after the event that caused
    /// them (CR 603.6). That is this whole family's failure mode: correct-looking and silent.
    /// <para>
    /// The two options are asserted as well. A reader that copied <em>something</em> without
    /// asking would pass every other line here while taking a decision away from the player, and
    /// the engine has been caught answering for people three times before.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_compiled_clone_enters_as_a_copy_of_the_creature_its_controller_names()
    {
        var wall = Card(
            "Copy Reader Wall Test",
            "When this creature enters, you gain 2 life.",
            CardType.Creature,
            0,
            4);

        var clone = Cloning("Copy Reader Clone Test");

        Assert.True(
            CardCompiler.Compile(clone).IsComplete,
            string.Join(" | ", CardCompiler.Compile(clone).Unhandled));

        var (game, alice, _) = InMainPhase();

        game.Create(alice, wall, Zone.Battlefield);
        game.Create(alice, TestCards.Creature("Copy Reader Bear Test", 2, 2), Zone.Battlefield);
        Settle(game);

        // Taken after the Wall's own arrival, which fired its own trigger: what is being measured
        // is the copy's, and starting from 20 would have counted both as one.
        var before = game.State.GetPlayer(alice).Life;

        var arrived = game.Create(alice, clone, Zone.Battlefield);

        // The game has stopped and is asking. Both creatures are on the menu, each named, plus
        // the "you may" arm — three ways for this permanent to arrive.
        var asked = Assert.IsType<PendingChoice>(game.State.Choice);
        Assert.Equal(ChoiceKind.OrderReplacements, asked.Kind);
        Assert.Equal(3, asked.Options.Count);
        Assert.Contains(asked.Options, o => o.Label.Contains("Copy Reader Wall Test", StringComparison.Ordinal));
        Assert.Contains(asked.Options, o => o.Label.Contains("Copy Reader Bear Test", StringComparison.Ordinal));

        SettleCopying(game, "Copy Reader Wall Test");

        var now = Characteristics.Of(game.State, Pool, game.State.GetObject(arrived));

        Assert.Equal("Copy Reader Wall Test", now.Name);
        Assert.Equal(0, now.Power);
        Assert.Equal(4, now.Toughness);

        // CR 707.5's own worked example, with Wall of Omens' life instead of its card: the copy
        // has the copied card's enters trigger, and it had a chance to fire.
        Assert.Equal(before + 2, game.State.GetPlayer(alice).Life);

        // Nothing ends it. This is what the permanent is, not a spell's effect on it.
        PassTo(game, 3, TurnStep.PrecombatMain);
        Settle(game);

        Assert.Equal(
            "Copy Reader Wall Test",
            Characteristics.Of(game.State, Pool, game.State.GetObject(arrived)).Name);
    }

    /// <summary>"You may" is an offer, and declining leaves the permanent itself (CR 614.1b).</summary>
    /// <remarks>
    /// The half a reader is most likely to drop, because taking it always looks like the better
    /// play and a card that always copies passes every other test in this section. It is printed
    /// as a choice, and a 0/0 that arrives as itself and dies to state-based actions is the
    /// outcome the player asked for.
    /// </remarks>
    [Fact]
    public void A_clone_may_decline_to_copy_anything()
    {
        var (game, alice, _) = InMainPhase();

        game.Create(alice, TestCards.Creature("Copy Decline Bear Test", 2, 2), Zone.Battlefield);
        Settle(game);

        var arrived = game.Create(alice, Cloning("Copy Decline Clone Test"), Zone.Battlefield);
        SettleDeclining(game);

        // A 0/0 that copied nothing is put into its owner's graveyard (CR 704.5f), which is what
        // the printed card does and the clearest evidence the copy did not happen.
        Assert.DoesNotContain(arrived, game.State.Battlefield);
    }

    /// <summary>
    /// A copy has the copied card's abilities <em>instead of</em> its own (CR 707.2a).
    /// </summary>
    /// <remarks>
    /// "A copy doesn't wind up with two values of each ability." The engine used to hand the
    /// copied abilities to the permanent while leaving its printed ones in place, because the two
    /// readers that answer "what can this permanent do" asked the object's own card. A permanent
    /// with both cards' abilities plays every test about the copied ones green.
    /// <para>
    /// Two assertions, and they fail in opposite directions. The empty activated list is the
    /// printed ability being <em>gone</em>; the life total is the copied trigger being
    /// <em>there</em>. An engine that dropped both, or kept both, fails one of them.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_copy_loses_its_own_abilities_and_gains_the_copied_cards()
    {
        var original = Card(
            "Copy Instead Original Test",
            "When this creature enters, you gain 2 life.",
            CardType.Creature,
            3,
            3);

        var mimic = Card(
            "Copy Instead Mimic Test",
            "You may have this creature enter as a copy of any creature on the battlefield.\n"
                + "{T}: You gain 5 life.",
            CardType.Creature,
            1,
            1);

        Assert.True(
            CardCompiler.Compile(mimic).IsComplete,
            string.Join(" | ", CardCompiler.Compile(mimic).Unhandled));

        var (game, alice, _) = InMainPhase();

        game.Create(alice, original, Zone.Battlefield);
        Settle(game);

        // After the original's own arrival, so the copy's trigger is measured on its own.
        var before = game.State.GetPlayer(alice).Life;

        var arrived = game.Create(alice, mimic, Zone.Battlefield);
        SettleCopying(game, "Copy Instead Original Test");

        var copy = game.State.GetObject(arrived);

        Assert.Equal("Copy Instead Original Test", Characteristics.Of(game.State, Pool, copy).Name);

        // Its own printed ability is not a copiable value of the card it copied, so it is gone.
        Assert.Empty(Game.ActivatedAbilitiesOf(game.State, Pool, copy));

        // And the copied one is here: 2 life, once, from the copied enters trigger. Five would
        // have meant the printed ability survived; nothing would have meant neither was read.
        Assert.Equal(before + 2, game.State.GetPlayer(alice).Life);
    }

    /// <summary>
    /// A copy enters tapped and with counters when the copied card says so (CR 707.5).
    /// </summary>
    /// <remarks>
    /// The rule's own example is a Clone of Skyshroud Behemoth, which enters tapped with two fade
    /// counters. Both come from replacement effects printed on the <em>copied</em> card, and the
    /// engine gathered replacements from the arriving object's own card — where there are none —
    /// so the copy arrived untapped and empty. Nothing about it looked wrong.
    /// <para>
    /// The clone is <em>cast</em> here rather than put onto the battlefield, and that is the
    /// point of the test rather than dressing. A permanent spell is still on the stack while its
    /// own arrival is being replaced, so the copy effect names the id it is about to have and not
    /// the id it has — and a reader that asked about the spell found no copy at all. Every other
    /// test in this section creates its clone directly, where the two ids are the same, and every
    /// one of them stayed green while this path did nothing.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_copy_arrives_as_the_copied_cards_own_replacements_leave_it()
    {
        var behemoth = Card(
            "Copy Arrives Original Test",
            "This creature enters tapped.\nThis creature enters with two +1/+1 counters on it.",
            CardType.Creature,
            3,
            3);

        Assert.True(
            CardCompiler.Compile(behemoth).IsComplete,
            string.Join(" | ", CardCompiler.Compile(behemoth).Unhandled));

        var (game, alice, _) = InMainPhase();

        game.Create(alice, behemoth, Zone.Battlefield);
        Settle(game);

        PassTo(game, 3, TurnStep.PrecombatMain);

        var clone = Cloning("Copy Arrives Clone Test");
        var spell = TestCards.PutInHand(game, alice, clone);

        game.CastSpell(alice, spell, targets: null);
        SettleCopying(game, "Copy Arrives Original Test");

        // Cast, so the permanent is a new object under a new id (CR 400.7) - found by name
        // rather than by the id the card had in hand.
        var copy = game.State.Battlefield
            .Select(game.State.GetObject)
            .Single(o => string.Equals(
                o.Card.OracleId, clone.OracleId, StringComparison.Ordinal));

        Assert.True(copy.Permanent!.IsTapped);
        Assert.Equal(2, copy.Permanent.Counters.GetValueOrDefault(CounterKinds.PlusOnePlusOne));

        // 3/3 printed plus the two counters the copied card brought with it.
        Assert.Equal(5, Characteristics.Of(game.State, Pool, copy).Power);
    }

    /// <summary>
    /// "Except it's an enchantment in addition to its other types" (CR 707.9b).
    /// </summary>
    /// <remarks>
    /// The exception is applied to the <em>card</em> handed to the copy rather than as a second
    /// effect on top of it, which is what CR 707.9b says: the modified value becomes part of the
    /// copy's copiable values. That is why a Copy Artifact does not stop being an enchantment
    /// when something else copies it, and why the same machinery reads "except it's 7/7" without
    /// knowing anything about sizes.
    /// </remarks>
    [Fact]
    public void An_exception_to_the_copy_changes_the_card_that_is_copied()
    {
        var engine = Card(
            "Copy Except Artifact Test",
            "{T}: You gain 1 life.",
            CardType.Artifact);

        var copier = Card(
            "Copy Except Test",
            "You may have this enchantment enter as a copy of any artifact on the battlefield, "
                + "except it's an enchantment in addition to its other types.",
            CardType.Enchantment);

        Assert.True(
            CardCompiler.Compile(copier).IsComplete,
            string.Join(" | ", CardCompiler.Compile(copier).Unhandled));

        var (game, alice, _) = InMainPhase();

        game.Create(alice, engine, Zone.Battlefield);
        Settle(game);

        var arrived = game.Create(alice, copier, Zone.Battlefield);
        SettleCopying(game, "Copy Except Artifact Test");

        var now = Characteristics.Of(game.State, Pool, game.State.GetObject(arrived));

        Assert.Equal("Copy Except Artifact Test", now.Name);
        Assert.True(now.CardTypes.HasFlag(CardType.Artifact));
        Assert.True(now.CardTypes.HasFlag(CardType.Enchantment));

        // The abilities still come from the copied card: CR 707.9b changes a characteristic and
        // nothing else, so the exception must not cost the copy what it copied.
        Assert.Single(Game.ActivatedAbilitiesOf(game.State, Pool, game.State.GetObject(arrived)));
    }

    /// <summary>"Except it's 7/7" replaces the size and keeps everything else (CR 707.9b).</summary>
    [Fact]
    public void An_exception_can_give_the_copy_a_different_size()
    {
        var gargantuan = Card(
            "Copy Size Test",
            "You may have this creature enter as a copy of any creature on the battlefield, "
                + "except it's 7/7.",
            CardType.Creature,
            7,
            7);

        Assert.True(
            CardCompiler.Compile(gargantuan).IsComplete,
            string.Join(" | ", CardCompiler.Compile(gargantuan).Unhandled));

        var (game, alice, _) = InMainPhase();

        game.Create(alice, TestCards.Creature("Copy Size Bear Test", 2, 2), Zone.Battlefield);
        Settle(game);

        var arrived = game.Create(alice, gargantuan, Zone.Battlefield);
        SettleCopying(game, "Copy Size Bear Test");

        var now = Characteristics.Of(game.State, Pool, game.State.GetObject(arrived));

        Assert.Equal("Copy Size Bear Test", now.Name);
        Assert.Equal(7, now.Power);
        Assert.Equal(7, now.Toughness);
    }

    /// <summary>
    /// One exception clause can add a type and a keyword at once (CR 707.9a, 707.9b).
    /// </summary>
    /// <remarks>
    /// Malleable Impostor's printed wording. Two clauses joined by "and", which is what the
    /// splitter is for — and the pair is worth a test of its own because a splitter that took
    /// the sentence whole would match neither clause and refuse the card, while one that split
    /// too eagerly would silently drop the half it could not read.
    /// </remarks>
    [Fact]
    public void An_exception_can_add_a_type_and_a_keyword_at_once()
    {
        var impostor = Card(
            "Copy Compound Test",
            "You may have this creature enter as a copy of a creature you control, except it's "
                + "a Faerie Shapeshifter in addition to its other types and it has flying.",
            CardType.Creature,
            0,
            0);

        Assert.True(
            CardCompiler.Compile(impostor).IsComplete,
            string.Join(" | ", CardCompiler.Compile(impostor).Unhandled));

        var (game, alice, _) = InMainPhase();

        game.Create(alice, TestCards.Creature("Copy Compound Bear Test", 2, 2), Zone.Battlefield);
        Settle(game);

        var arrived = game.Create(alice, impostor, Zone.Battlefield);
        SettleCopying(game, "Copy Compound Bear Test");

        var now = Characteristics.Of(game.State, Pool, game.State.GetObject(arrived));

        Assert.Equal("Copy Compound Bear Test", now.Name);
        Assert.Equal(2, now.Power);
        Assert.True(now.Has(KeywordAbility.Flying));

        // "In addition to", so the copied Bear is still a Bear.
        Assert.Contains("Faerie", now.Subtypes, StringComparer.OrdinalIgnoreCase);
        Assert.Contains("Shapeshifter", now.Subtypes, StringComparer.OrdinalIgnoreCase);
        Assert.Contains("Bear", now.Subtypes, StringComparer.OrdinalIgnoreCase);
    }

    /// <summary>
    /// A copy of a copy copies what the first copy became, not what it was printed as
    /// (CR 707.2b, 707.3).
    /// </summary>
    /// <remarks>
    /// "The copy's copiable values become the copied information. Objects that copy the object
    /// will use the new copiable values." Until a reader existed, nothing could build this
    /// position: the only copies the engine could make were fixed before the game started, so
    /// the second copy was always copying a card rather than a permanent that had become one.
    /// <para>
    /// The two clones say different things on purpose. The second copies "a creature you
    /// control", and the only creature its controller has is the first clone — so the choice
    /// cannot accidentally land on the original, and a second clone that read the printed card
    /// would come back a 0/0 named after itself and die to state-based actions.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_copy_of_a_copy_takes_the_first_copys_values()
    {
        var (game, alice, bob) = InMainPhase();

        // The original belongs to Bob, so "a creature you control" cannot reach it.
        game.Create(bob, TestCards.Creature("Copy Chain Bear Test", 4, 4), Zone.Battlefield);
        Settle(game);

        var first = game.Create(alice, Cloning("Copy Chain First Test"), Zone.Battlefield);
        SettleCopying(game, "Copy Chain Bear Test");

        Assert.Equal(
            "Copy Chain Bear Test",
            Characteristics.Of(game.State, Pool, game.State.GetObject(first)).Name);

        var second = game.Create(
            alice, Cloning("Copy Chain Second Test", "a creature you control"), Zone.Battlefield);

        // The option is named for what the first clone *is*, which is half the point: a player
        // choosing from this list is reading the board, not the card that was cast.
        var asked = Assert.IsType<PendingChoice>(game.State.Choice);
        Assert.Contains(
            asked.Options, o => o.Label.Contains("Copy Chain Bear Test", StringComparison.Ordinal));

        SettleCopying(game, "Copy Chain Bear Test");

        var now = Characteristics.Of(game.State, Pool, game.State.GetObject(second));

        Assert.Equal("Copy Chain Bear Test", now.Name);
        Assert.Equal(4, now.Power);
        Assert.Equal(4, now.Toughness);
    }

    /// <summary>The legend rule reads the name a permanent has now (CR 704.5j, 707.2).</summary>
    /// <remarks>
    /// A name is a copiable value, so a copy of a legend is a second legend of that name and one
    /// of them has to go. The check grouped permanents by their <em>printed</em> name, which
    /// asked which card each one came from — the one thing the rule is not about — so a Clone of
    /// a commander sat happily beside it.
    /// </remarks>
    [Fact]
    public void The_legend_rule_counts_the_name_a_copy_has_taken()
    {
        var legend = new CardDefinition
        {
            OracleId = "oracle-copy-legend-test",
            Name = "Copy Legend Test",
            CardTypes = CardType.Creature,
            Supertypes = ["Legendary"],
            Power = 3,
            Toughness = 3,
        };

        var (game, alice, _) = InMainPhase();

        game.Create(alice, legend, Zone.Battlefield);
        Settle(game);

        game.Create(alice, Cloning("Copy Legend Clone Test"), Zone.Battlefield);
        SettleCopying(game, "Copy Legend Test");

        // One of the two is in the graveyard, and which one was the player's choice - what
        // matters here is that the question was asked at all.
        var legends = game.State.Battlefield
            .Select(game.State.GetObject)
            .Count(o => string.Equals(
                Characteristics.Of(game.State, Pool, o).Name,
                "Copy Legend Test",
                StringComparison.Ordinal));

        Assert.Equal(1, legends);
    }

    /// <summary>The board is shown what the permanent is, not what it was printed as (CR 707.3).</summary>
    /// <remarks>
    /// The view is the only place a player meets any of this. Projected from the printed card, a
    /// Clone kept its own name, its own art and its own rules text while the engine played it as
    /// something else — and the abilities beside it, which already came from the computed
    /// characteristics, were a list of things the displayed card does not say.
    /// </remarks>
    [Fact]
    public void The_board_is_shown_the_card_a_copy_became()
    {
        var original = Card(
            "Copy View Original Test",
            "{T}: You gain 1 life.",
            CardType.Creature,
            5,
            5);

        var (game, alice, _) = InMainPhase();

        game.Create(alice, original, Zone.Battlefield);
        Settle(game);

        var arrived = game.Create(alice, Cloning("Copy View Clone Test"), Zone.Battlefield);
        SettleCopying(game, "Copy View Original Test");

        var shown = game.ViewFor(alice).Battlefield.Single(o => o.Id == arrived.Value);

        Assert.Equal("Copy View Original Test", shown.Name);
        Assert.Equal(original.OracleId, shown.OracleId);
        Assert.Equal("{T}: You gain 1 life.", shown.OracleText);
        Assert.Equal(5, shown.PrintedPower);
        Assert.Single(shown.Abilities);
    }

    /// <summary>
    /// A token copy is a copy of what the permanent is, and keeps both its faces
    /// (CR 707.3, 707.8a).
    /// </summary>
    /// <remarks>
    /// Two fields that were being read off the printed card and are copiable values of the
    /// permanent. The faces are the one this repository has already been caught dropping once, in
    /// the game log, where it cost every transform in every stored game — a token with one face
    /// looks exactly like a token that can turn over, right up until somebody tries.
    /// </remarks>
    [Fact]
    public void A_token_copy_copies_the_permanent_rather_than_the_printed_card()
    {
        var twoFaced = new CardDefinition
        {
            OracleId = "oracle-copy-token-two-faced-test",
            Name = "Copy Token Front Test",
            CardTypes = CardType.Creature,
            Power = 3,
            Toughness = 3,
            Faces =
            [
                new CardFace
                {
                    Name = "Copy Token Front Test",
                    CardTypes = CardType.Creature,
                    Power = 3,
                    Toughness = 3,
                },
                new CardFace
                {
                    Name = "Copy Token Back Test",
                    CardTypes = CardType.Creature,
                    Power = 6,
                    Toughness = 6,
                },
            ],
        };

        var making = Card(
            "Copy Token Maker Test",
            "Create a token that's a copy of target creature.",
            CardType.Sorcery);

        Assert.True(
            CardCompiler.Compile(making).IsComplete,
            string.Join(" | ", CardCompiler.Compile(making).Unhandled));

        var (game, alice, _) = InMainPhase();

        game.Create(alice, twoFaced, Zone.Battlefield);
        Settle(game);

        var clone = game.Create(alice, Cloning("Copy Token Clone Test"), Zone.Battlefield);
        SettleCopying(game, "Copy Token Front Test");

        PassTo(game, 3, TurnStep.PrecombatMain);

        // The token is made from the clone, which is not what the clone's card says it is.
        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, making), [Target.ToPermanent(clone)]);
        Settle(game);

        var token = game.State.Battlefield
            .Select(game.State.GetObject)
            .Single(o => o.Card.CardTypes.HasFlag(CardType.Token));

        Assert.Equal("Copy Token Front Test", token.Card.Name);
        Assert.Equal(3, token.Card.Power);

        // CR 707.8a: the token is double-faced too, and can transform.
        Assert.Equal(2, token.Card.Faces.Count);
        Assert.Equal("Copy Token Back Test", token.Card.Faces[1].Name);
    }

    /// <summary>
    /// A permanent already on the battlefield becomes a copy of a target, and stops being one
    /// when the turn ends (CR 613.2a, 514.2).
    /// </summary>
    /// <remarks>
    /// Mirage Mirror's wording, which is the whole "becomes a copy" family that reads cleanly: an
    /// activated ability, one target, and a duration the engine can express. It is the other half
    /// of this feature from the Clone family — that one decides what a permanent is as it
    /// arrives, this one changes what one already here is.
    /// <para>
    /// The life total is the assertion that earns its place. An effect that copied the numbers
    /// and dropped the abilities would pass every characteristic check below and be the wrong
    /// card at the only moment anyone notices, so the copied ability is made to resolve.
    /// </para>
    /// <para>
    /// The last two assertions are the duration. A copy effect is a layer rather than something
    /// written into the object (CR 613.1), so when it wears off the permanent is simply itself
    /// again and nothing had to be taken back off it.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_permanent_becomes_a_copy_of_its_target_until_end_of_turn()
    {
        var mirror = Card(
            "Copy Mirror Test",
            "{2}: This artifact becomes a copy of target artifact, creature, enchantment, or "
                + "land until end of turn.",
            CardType.Artifact);

        Assert.True(
            CardCompiler.Compile(mirror).IsComplete,
            string.Join(" | ", CardCompiler.Compile(mirror).Unhandled));

        var original = Card(
            "Copy Mirror Original Test",
            "{T}: You gain 3 life.",
            CardType.Creature,
            4,
            4);

        var (game, alice, _) = InMainPhase();

        var glass = game.Create(alice, mirror, Zone.Battlefield);
        var subject = game.Create(alice, original, Zone.Battlefield);
        Settle(game);

        // Wait a turn so the copy is not summoning sick when it taps for the copied ability.
        PassTo(game, 3, TurnStep.PrecombatMain);

        for (var i = 0; i < 2; i++)
        {
            var land = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
            game.ActivateAbility(alice, land, "mana");
        }

        var changing = Assert.Single(
            Game.ActivatedAbilitiesOf(game.State, Pool, game.State.GetObject(glass)));

        game.ActivateAbility(alice, glass, changing.Id, [Target.ToPermanent(subject)]);
        Settle(game);

        var now = Characteristics.Of(game.State, Pool, game.State.GetObject(glass));

        Assert.Equal("Copy Mirror Original Test", now.Name);
        Assert.Equal(4, now.Power);
        Assert.Equal(4, now.Toughness);
        Assert.True(now.CardTypes.HasFlag(CardType.Creature));

        // The copied ability is the one the mirror now offers, and it resolves.
        var before = game.State.GetPlayer(alice).Life;
        var borrowed = Assert.Single(
            Game.ActivatedAbilitiesOf(game.State, Pool, game.State.GetObject(glass)));

        game.ActivateAbility(alice, glass, borrowed.Id);
        Settle(game);

        Assert.Equal(before + 3, game.State.GetPlayer(alice).Life);

        PassTo(game, 4, TurnStep.Upkeep);
        Settle(game);

        var after = Characteristics.Of(game.State, Pool, game.State.GetObject(glass));

        Assert.Equal("Copy Mirror Test", after.Name);
        Assert.False(after.CardTypes.HasFlag(CardType.Creature));
    }

    // ---- Dice rolling (CR 706) -----------------------------------------------

    /// <summary>Recruitment Drive: the row the number lands in is the row that happens.</summary>
    /// <remarks>
    /// The assertion is written against the logged outcome rather than a known number, because
    /// the number is the randomness under test: whatever came up, the tokens on the table have
    /// to be the ones that row prints and no other row's.
    /// </remarks>
    [Fact]
    public void A_results_table_runs_the_row_the_die_lands_in()
    {
        var drive = Card(
            "Recruitment Drive Test",
            "Roll a d20.\n"
                + "1—9 | Create two 1/1 white Soldier creature tokens.\n"
                + "10—19 | Create two 2/2 white Knight creature tokens.\n"
                + "20 | Create three 2/2 white Knight creature tokens.",
            CardType.Sorcery);

        Assert.True(CardCompiler.Compile(drive).IsComplete);

        var (game, alice, _) = InMainPhase();
        game.CastSpell(alice, TestCards.PutInHand(game, alice, drive));
        Settle(game);

        var rolled = Assert.Single(game.Log.OfType<DiceRolled>());
        Assert.Equal(20, rolled.Sides);
        Assert.InRange(rolled.Result, 1, 20);

        var tokens = game.State.Battlefield
            .Select(game.State.GetObject)
            .Where(o => o.Card.Name is "Soldier" or "Knight")
            .ToList();

        var (name, count) = rolled.Result switch
        {
            <= 9 => ("Soldier", 2),
            <= 19 => ("Knight", 2),
            _ => ("Knight", 3),
        };

        Assert.Equal(count, tokens.Count);
        Assert.All(tokens, t => Assert.Equal(name, t.Card.Name));
    }

    /// <summary>Contact Other Plane: rows that scry and draw, picked by range (CR 706.3a).</summary>
    [Fact]
    public void A_row_of_several_sentences_runs_whole()
    {
        var contact = Card(
            "Contact Other Plane Test",
            "Roll a d20.\n"
                + "1—9 | Draw two cards.\n"
                + "10—19 | Scry 2, then draw two cards.\n"
                + "20 | Scry 3, then draw three cards.");

        Assert.True(CardCompiler.Compile(contact).IsComplete);

        var (game, alice, _) = InMainPhase();
        var before = game.State.GetPlayer(alice).Hand.Count;
        game.CastSpell(alice, TestCards.PutInHand(game, alice, contact));
        Settle(game);

        var rolled = Assert.Single(game.Log.OfType<DiceRolled>());

        // The spell is put into the hand and cast back out of it, so the count it started at is
        // the count it returns to, plus whatever the row drew.
        var drawn = rolled.Result == 20 ? 3 : 2;
        Assert.Equal(before + drawn, game.State.GetPlayer(alice).Hand.Count);
    }

    /// <summary>
    /// The roll is in the log as its outcome, so a resumed game reads it instead of re-rolling
    /// — the rule every shuffle and coin flip here already follows.
    /// </summary>
    [Fact]
    public void A_roll_replays_from_its_logged_outcome_not_the_dice()
    {
        var purse = Card(
            "Everfull Sac Test",
            "{T}, Sacrifice ~: Roll a six-sided die. You gain life equal to the result.",
            CardType.Artifact);

        Assert.True(CardCompiler.Compile(purse).IsComplete);

        var (game, alice, _) = InMainPhase();
        var bauble = game.Create(alice, purse, Zone.Battlefield);
        game.ActivateAbility(alice, bauble, "a");
        Settle(game);

        var rolled = Assert.Single(game.Log.OfType<DiceRolled>());
        Assert.Equal(20 + rolled.Result, game.State.GetPlayer(alice).Life);

        // A different seed on resume must make no difference: the outcome is already history.
        var resumed = Game.Resume([.. game.Log], new GameRandom(987654), Pool);
        Assert.Equal(game.State, resumed.State);
    }

    /// <summary>Two games from two seeds do not always roll the same number.</summary>
    /// <remarks>
    /// The counterpart of the replay test above, and the pair is the whole contract: the same
    /// log is always the same game, and a fresh game is not condemned to the same dice.
    /// </remarks>
    [Fact]
    public void Seeded_games_roll_their_own_numbers()
    {
        var roller = Card("Bare Roller Test", "{T}: Roll a d20.", CardType.Artifact);
        Assert.True(CardCompiler.Compile(roller).IsComplete);

        var seen = new HashSet<int>();

        foreach (var seed in Enumerable.Range(1, 8))
        {
            var (game, alice) = InMainPhaseSeeded(seed);
            var die = game.Create(alice, roller, Zone.Battlefield);
            game.ActivateAbility(alice, die, "a");
            Settle(game);

            seen.Add(Assert.Single(game.Log.OfType<DiceRolled>()).Result);
        }

        Assert.True(seen.Count > 1, "eight seeds all rolled the same number");
    }

    /// <summary>
    /// Dissatisfied Customer: "If the result is 3 or less, you lose that much life" — the
    /// conditional sentence is a row, and "that much" is the number rolled (CR 706.4).
    /// </summary>
    [Fact]
    public void An_if_the_result_sentence_runs_only_in_its_range()
    {
        var customer = Card(
            "Dissatisfied Customer Test",
            "When ~ enters, roll a six-sided die. If the result is 3 or less, you lose that much life.",
            CardType.Creature,
            power: 3,
            toughness: 1);

        Assert.True(CardCompiler.Compile(customer).IsComplete);

        var (game, alice, _) = InMainPhase();
        game.Create(alice, customer, Zone.Battlefield);
        Settle(game);

        var rolled = Assert.Single(game.Log.OfType<DiceRolled>());
        var expected = rolled.Result <= 3 ? 20 - rolled.Result : 20;

        Assert.Equal(expected, game.State.GetPlayer(alice).Life);
    }

    /// <summary>Brazen Dwarf: "whenever you roll one or more dice" fires on a roll (CR 706.5).</summary>
    [Fact]
    public void A_dice_watcher_fires_when_its_controller_rolls()
    {
        var dwarf = Card(
            "Brazen Dwarf Test",
            "Whenever you roll one or more dice, ~ deals 1 damage to each opponent.",
            CardType.Creature,
            power: 1,
            toughness: 3);

        var roller = Card("Six Roller Test", "{T}: Roll a six-sided die.", CardType.Artifact);

        Assert.True(CardCompiler.Compile(dwarf).IsComplete);
        Assert.True(CardCompiler.Compile(roller).IsComplete);

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, dwarf, Zone.Battlefield);
        var die = game.Create(alice, roller, Zone.Battlefield);

        // Nothing is settled before the activation: settling passes priority at least once, so
        // it would be Bob's to hold and Alice's activation illegal (CR 117.1).
        Assert.Equal(20, game.State.GetPlayer(bob).Life);

        game.ActivateAbility(alice, die, "a");
        Settle(game);

        Assert.Single(game.Log.OfType<DiceRolled>());
        Assert.Equal(19, game.State.GetPlayer(bob).Life);
    }

    /// <summary>An opponent's roll is not "you roll", and wakes nobody else's watcher.</summary>
    [Fact]
    public void A_dice_watcher_ignores_an_opponents_roll()
    {
        var dwarf = Card(
            "Brazen Dwarf Test",
            "Whenever you roll one or more dice, ~ deals 1 damage to each opponent.",
            CardType.Creature,
            power: 1,
            toughness: 3);

        var roller = Card("Six Roller Test", "{T}: Roll a six-sided die.", CardType.Artifact);

        var (game, alice, bob) = InMainPhase();

        // Bob has the watcher; Alice rolls. Bob's dwarf must stay quiet.
        game.Create(bob, dwarf, Zone.Battlefield);
        var die = game.Create(alice, roller, Zone.Battlefield);
        game.ActivateAbility(alice, die, "a");
        Settle(game);

        Assert.Single(game.Log.OfType<DiceRolled>());
        Assert.Equal(20, game.State.GetPlayer(alice).Life);
        Assert.Equal(20, game.State.GetPlayer(bob).Life);
    }

    /// <summary>
    /// Monoxa, Midway Manager: a threshold watcher whose follow-up clauses each read the
    /// number rolled (CR 706.4) — every keyword she has afterwards is the roll's doing.
    /// </summary>
    [Fact]
    public void Threshold_clauses_read_the_number_rolled()
    {
        var monoxa = Card(
            "Monoxa Test",
            "Whenever you roll a 3 or higher, ~ gains first strike until end of turn. If the"
                + " roll was 4 or higher, it gains menace until end of turn. If the roll was 5"
                + " or higher, it gains lifelink until end of turn.\n{6}: Roll a six-sided die.",
            CardType.Creature,
            power: 3,
            toughness: 3);

        Assert.True(CardCompiler.Compile(monoxa).IsComplete);

        var (game, alice, _) = InMainPhase();
        var manager = game.Create(alice, monoxa, Zone.Battlefield);
        game.AddMana(alice, null, 6);
        game.ActivateAbility(alice, manager, "a");
        Settle(game);

        var rolled = Assert.Single(game.Log.OfType<DiceRolled>());
        var computed = Characteristics.Of(game.State, Pool, game.State.GetObject(manager));

        Assert.Equal(rolled.Result >= 3, computed.Has(KeywordAbility.FirstStrike));
        Assert.Equal(rolled.Result >= 4, computed.Has(KeywordAbility.Menace));
        Assert.Equal(rolled.Result >= 5, computed.Has(KeywordAbility.Lifelink));
    }

    /// <summary>
    /// Spiked Pit Trap: a target chosen before the roll is what the rows aim at afterwards
    /// (CR 601.2c) — the die decides the row, never the victim.
    /// </summary>
    [Fact]
    public void A_target_chosen_before_the_roll_is_what_the_rows_hit()
    {
        var trap = Card(
            "Spiked Pit Test",
            "{5}, {T}, Sacrifice ~: Choose target creature, then roll a d20.\n"
                + "1—9 | ~ deals 5 damage to that creature.\n"
                + "10—20 | ~ deals 5 damage to that creature. Create a Treasure token.",
            CardType.Artifact);

        Assert.True(CardCompiler.Compile(trap).IsComplete);

        var (game, alice, bob) = InMainPhase();
        var bear = game.Create(bob, TestCards.Creature("Bear", 4, 4), Zone.Battlefield);
        var pit = game.Create(alice, trap, Zone.Battlefield);
        game.AddMana(alice, null, 5);
        game.ActivateAbility(alice, pit, "a", [Target.ToPermanent(bear)]);
        Settle(game);

        var rolled = Assert.Single(game.Log.OfType<DiceRolled>());

        // Five damage kills the 4/4 whichever row ran; the Treasure is the high rows' extra.
        Assert.DoesNotContain(
            game.State.Battlefield.Select(game.State.GetObject), o => o.Card.Name == "Bear");
        Assert.Equal(
            rolled.Result >= 10,
            game.State.Battlefield.Select(game.State.GetObject)
                .Any(o => o.Card.Name == "Treasure"));
    }

    /// <summary>
    /// Pixie Guide rolls an extra die and ignores the lowest (CR 706.2b) — and per CR 706.6 the
    /// ignored die never happened: one outcome in the log, one trigger for the watchers.
    /// </summary>
    [Fact]
    public void An_extra_die_keeps_the_highest_and_the_ignored_die_never_happened()
    {
        var pixie = Card(
            "Pixie Guide Test",
            "If you would roll one or more dice, instead roll that many dice plus one and"
                + " ignore the lowest roll.",
            CardType.Creature,
            power: 1,
            toughness: 3,
            keywords: KeywordAbility.Flying);

        var roller = Card("Bare Roller Test", "{T}: Roll a d20.", CardType.Artifact);

        Assert.True(CardCompiler.Compile(pixie).IsComplete);

        // The same seed twice: once alone, once with the Guide. The first die of both games is
        // the same draw, so keeping the higher of two can never come out below rolling one.
        var (alone, aliceAlone) = InMainPhaseSeeded(7);
        var soloDie = alone.Create(aliceAlone, roller, Zone.Battlefield);
        alone.ActivateAbility(aliceAlone, soloDie, "a");
        Settle(alone);
        var unaided = Assert.Single(alone.Log.OfType<DiceRolled>());

        var (game, alice) = InMainPhaseSeeded(7);
        game.Create(alice, pixie, Zone.Battlefield);
        var die = game.Create(alice, roller, Zone.Battlefield);
        game.ActivateAbility(alice, die, "a");
        Settle(game);

        var request = Assert.Single(game.Log.OfType<DiceRollRequested>());
        Assert.Equal(1, request.ExtraDice);

        var helped = Assert.Single(game.Log.OfType<DiceRolled>());
        Assert.True(
            helped.Result >= unaided.Result,
            $"keeping the higher of two dice rolled {helped.Result}, below the single {unaided.Result}");
    }

    /// <summary>
    /// Netherese Puzzle-Ward's second ability: the highest natural result is the die's own face
    /// (CR 706.2) — a d4 pays out on 4, and on nothing else.
    /// </summary>
    [Fact]
    public void The_highest_natural_result_watcher_reads_the_face()
    {
        var ward = Card(
            "Perfect Illumination Test",
            "Whenever you roll a die's highest natural result, draw a card.",
            CardType.Enchantment);

        var roller = Card("Four Roller Test", "{T}: Roll a four-sided die.", CardType.Artifact);

        Assert.True(CardCompiler.Compile(ward).IsComplete);
        Assert.True(CardCompiler.Compile(roller).IsComplete);

        var (game, alice, _) = InMainPhase();
        game.Create(alice, ward, Zone.Battlefield);
        var die = game.Create(alice, roller, Zone.Battlefield);
        var before = game.State.GetPlayer(alice).Hand.Count;
        game.ActivateAbility(alice, die, "a");
        Settle(game);

        var rolled = Assert.Single(game.Log.OfType<DiceRolled>());
        Assert.Equal(4, rolled.Sides);
        Assert.Equal(
            before + (rolled.Natural == 4 ? 1 : 0),
            game.State.GetPlayer(alice).Hand.Count);
    }

