    /// <summary>What stays honestly unread: modifiers, multi-dice, and the graveyard watcher.</summary>
    /// <remarks>
    /// Each of these is a card the machinery this round could half-run, and half-running any of
    /// them prints a different card: a modified roll read as unmodified lands in the wrong row,
    /// "roll two and choose" decided by the engine takes the player's choice away, and a
    /// "natural 20" trigger compiled to the battlefield would simply never fire from the
    /// graveyard it watches.
    /// </remarks>
    [Fact]
    public void Modified_and_multi_dice_rolls_stay_unread()
    {
        var modified = Card(
            "Diviner Test",
            "Roll a d20 and add the number of cards in your hand.\n"
                + "1—14 | Draw X cards.\n"
                + "15+ | Scry X, then draw X cards.");

        var chooseOne = Card(
            "Valiant Endeavor Test",
            "Roll two d6 and choose one result. Destroy each creature with power greater than"
                + " or equal to that result. Then create a number of 2/2 white Knight creature"
                + " tokens with vigilance equal to the other result.",
            CardType.Sorcery);

        var natural = Card(
            "Critical Hit Test",
            "Target creature gains double strike until end of turn.\n"
                + "When you roll a natural 20, return ~ from your graveyard to your hand.");

        Assert.False(CardCompiler.Compile(modified).IsComplete);
        Assert.False(CardCompiler.Compile(chooseOne).IsComplete);
        Assert.False(CardCompiler.Compile(natural).IsComplete);
    }

    /// <summary>
    /// A Spacecraft's station bar shares the row shape exactly — "10+ | Flying" — and must not
    /// fold into the line above it, because that line rolls no dice (CR 706.3b cuts both ways).
    /// </summary>
    /// <remarks>
    /// What the guard is worth is measured on the far side of it: the station threshold reads
    /// that bar (CR 721.2), so a fold that swallowed it would take a whole ability off the card
    /// and leave a Spacecraft that never becomes a creature — while reading, by every count
    /// here, as a card compiled correctly. The line reader is the only place that can tell the
    /// two bars apart, because it is the only place that can still see the line above.
    /// </remarks>
    [Fact]
    public void A_station_bar_is_not_a_results_row()
    {
        var skiff = Card(
            "Rescue Skiff Test",
            "Station (Tap another creature you control: Put charge counters equal to its"
                + " power on this Spacecraft. Station only as a sorcery. It's an artifact"
                + " creature at 10+.)\n10+ | Flying",
            CardType.Artifact,
            subtypes: "Spacecraft");

        var lines = CardCompiler.Lines(skiff).ToList();

        // Two lines, not one: the bar stayed its own line, whole and in front of the compiler.
        Assert.Equal(2, lines.Count);
        Assert.Equal("10+ | Flying", lines[1]);

        Assert.True(CardCompiler.Compile(skiff).IsComplete);
    }

    // ---- Sagas (CR 714) ------------------------------------------------------

    /// <summary>A three-chapter Saga whose chapters are each visible in the life total.</summary>
    private static CardDefinition ThreeChapterSaga() => Card(
        "Test Chronicle",
        "I \u2014 You gain 1 life.\nII \u2014 You gain 2 life.\nIII \u2014 You gain 4 life.",
        CardType.Enchantment,
        null,
        null,
        KeywordAbility.None,
        "Saga");

    /// <summary>
    /// A Saga arrives with a lore counter already on it and its first chapter fires (CR 714.3a).
    /// </summary>
    /// <remarks>
    /// Nothing on the card says so. CR 714.3a gives every Saga the intrinsic ability, which is
    /// why it is compiled in rather than read - and why it is worth a test: an intrinsic nobody
    /// printed is exactly the kind of rule that gets left out and never noticed, because the
    /// card still enters, still sits on the battlefield, and simply never begins.
    /// </remarks>
    [Fact]
    public void A_Saga_arrives_with_a_lore_counter_and_reads_its_first_chapter()
    {
        var saga = ThreeChapterSaga();
        Assert.True(
            CardCompiler.Compile(saga).IsComplete,
            string.Join(" | ", CardCompiler.Compile(saga).Unhandled));

        var (game, alice, _) = InMainPhase();
        var before = game.State.GetPlayer(alice).Life;
        var card = TestCards.PutInHand(game, alice, saga);

        game.CastSpell(alice, card, []);
        Settle(game);

        var permanent = game.State.Battlefield
            .Select(game.State.GetObject)
            .Single(o => o.Card.Name == "Test Chronicle");

        Assert.Equal(1, permanent.Permanent!.Counters.GetValueOrDefault(CounterKinds.Lore));
        Assert.Equal(before + 1, game.State.GetPlayer(alice).Life);
    }

    /// <summary>
    /// The Saga advances as its controller's precombat main phase begins (CR 714.3c), and only
    /// its controller's.
    /// </summary>
    /// <remarks>
    /// The opponent's turn is what carries this test. A version that only checked "it reached
    /// chapter II eventually" would pass against an implementation that advanced every Saga on
    /// every turn - which would run a three-chapter Saga out in two turns instead of three, and
    /// would look right in every assertion about the final chapter.
    /// </remarks>
    [Fact]
    public void A_Saga_advances_only_on_its_controllers_turn()
    {
        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, ThreeChapterSaga());

        game.CastSpell(alice, card, []);
        Settle(game);

        ObjectId Saga() => game.State.Battlefield
            .Single(id => game.State.GetObject(id).Card.Name == "Test Chronicle");

        int Lore() => game.State.GetObject(Saga())
            .Permanent!.Counters.GetValueOrDefault(CounterKinds.Lore);

        // Bob's turn. His precombat main phase begins and puts a counter on nothing of Alice's.
        TestCards.PassUntil(
            game,
            () => game.State.ActivePlayerId != alice
                && game.State.CurrentStep == TurnStep.PrecombatMain);

        Settle(game);
        Assert.Equal(1, Lore());

        // Alice's next precombat main is the one that advances it.
        TestCards.PassUntil(
            game,
            () => game.State.ActivePlayerId == alice
                && game.State.CurrentStep == TurnStep.PrecombatMain);

        Settle(game);
        Assert.Equal(2, Lore());
    }

    /// <summary>
    /// The final chapter resolves before the Saga is sacrificed (CR 714.4).
    /// </summary>
    /// <remarks>
    /// The ordering is the whole rule. The counter that reaches the final chapter number is the
    /// same counter that triggers it, so at the instant the sacrifice condition becomes true the
    /// ability has not resolved - and 714.4 says so explicitly, holding the sacrifice back while
    /// the Saga "is the source of a chapter ability that has triggered but not yet left the
    /// stack".
    /// <para>
    /// Read the other way round, every Saga in the game would be sacrificed one resolution early
    /// and its last chapter would never happen. The life total is what proves which way round it
    /// went: the Saga being in the graveyard is true under both readings.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_Sagas_final_chapter_resolves_before_it_is_sacrificed()
    {
        var (game, alice, _) = InMainPhase();
        var before = game.State.GetPlayer(alice).Life;
        var card = TestCards.PutInHand(game, alice, ThreeChapterSaga());

        game.CastSpell(alice, card, []);
        Settle(game);

        TestCards.PassUntil(
            game,
            () => game.State.Battlefield.All(
                id => game.State.GetObject(id).Card.Name != "Test Chronicle"));

        Settle(game);

        // 1 + 2 + 4: every chapter ran, including the one that finished it.
        Assert.Equal(before + 7, game.State.GetPlayer(alice).Life);

        Assert.Contains(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Test Chronicle");
    }

    /// <summary>
    /// "II, III — [effect]" is two chapter abilities, not one (CR 714.2c).
    /// </summary>
    /// <remarks>
    /// One printed line, and it has to run twice - so it cannot be compiled as a single ability
    /// that fires when the count is "II or III". The life total counts the firings.
    /// </remarks>
    [Fact]
    public void A_chapter_line_naming_two_numerals_runs_at_each_of_them()
    {
        var saga = Card(
            "Test Refrain",
            "I \u2014 You gain 1 life.\nII, III \u2014 You gain 2 life.",
            CardType.Enchantment,
            null,
            null,
            KeywordAbility.None,
            "Saga");

        var compiled = CardCompiler.Compile(saga);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.Equal(3, compiled.Triggers.Count(t => t.Chapter is not null));

        var (game, alice, _) = InMainPhase();
        var before = game.State.GetPlayer(alice).Life;
        var card = TestCards.PutInHand(game, alice, saga);

        game.CastSpell(alice, card, []);
        Settle(game);

        TestCards.PassUntil(
            game,
            () => game.State.Battlefield.All(
                id => game.State.GetObject(id).Card.Name != "Test Refrain"));

        Settle(game);

        // 1 + 2 + 2, not 1 + 2.
        Assert.Equal(before + 5, game.State.GetPlayer(alice).Life);
    }
    // ---- Mutate (CR 702.140) -------------------------------------------------

    /// <summary>Dreamtail Heron, whose wording is the whole mutate template.</summary>
    private static CardDefinition MutateHeron() => Card(
        "Test Dreamtail Heron",
        "Mutate {3}{U} (If you cast this spell for its mutate cost, put it over or under target "
            + "non-Human creature you own. They mutate into the creature on top plus all "
            + "abilities from under it.)\nFlying\nWhenever this creature mutates, draw a card.",
        CardType.Creature,
        3,
        4,

        // A flag as well as a printed line, exactly as the card database has it: the compiler
        // reads a bare keyword line only so as not to report it unread, because the flag is
        // already there (CR 702.1).
        KeywordAbility.Flying,
        "Bird");

    /// <summary>Mysterious Egg: a mutate host whose whole text is a mutate trigger.</summary>
    /// <remarks>
    /// Printed with no mutate cost of its own, which makes it the card that proves CR 702.140e:
    /// once something is over it, this trigger is on a card that is no longer the one the
    /// permanent's characteristics come from, and it still has to fire.
    /// </remarks>
    private static CardDefinition MutateEgg() => Card(
        "Test Mysterious Egg",
        "Whenever this creature mutates, put a +1/+1 counter on it.",
        CardType.Creature,
        0,
        1,
        subtypes: "Egg");

    /// <summary>Enough basics for Dreamtail Heron's {3}{U} and the Hemophage's {2}{B}.</summary>
    /// <remarks>
    /// Named rather than counted because a mutate cost is coloured, and a basic taps for the
    /// colour of its own land type (CR 305.6): "three and a blue" is three Forests and an Island,
    /// not four of anything.
    /// </remarks>
    private static readonly string[] ThreeAndBlue = ["Forest", "Forest", "Forest", "Island"];

    private static readonly string[] TwoAndBlack = ["Forest", "Forest", "Swamp"];

    /// <summary>Mutates a creature on the battlefield, paying the cost with basics.</summary>
    private static void Mutate(
        Game game,
        Guid player,
        CardDefinition card,
        ObjectId host,
        IReadOnlyList<string> lands,
        bool onTop)
    {
        var spell = TestCards.PutInHand(game, player, card);

        foreach (var basic in lands)
        {
            var land = game.Create(player, TestCards.BasicLand(basic), Zone.Battlefield);
            game.ActivateAbility(player, land, "mana");
        }

        game.CastSpell(
            player, spell, [Target.ToPermanent(host)], mutated: true, mutateOnTop: onTop);
    }

    /// <summary>
    /// CR 730.2a: a merged permanent has the characteristics of its topmost component.
    /// </summary>
    [Fact]
    public void Mutating_over_a_creature_takes_the_new_cards_characteristics()
    {
        var (game, alice, _) = InMainPhase();
        var host = game.Create(alice, MutateEgg(), Zone.Battlefield);

        Mutate(game, alice, MutateHeron(), host, ThreeAndBlue, onTop: true);
        Settle(game);

        // CR 730.2c: the same object it was, so it is still findable by the id it had.
        var merged = game.State.GetObject(host);
        var now = Characteristics.Of(game.State, Pool, merged);

        Assert.Equal("Test Dreamtail Heron", now.Name);

        // 3/4 from the Heron, plus the +1/+1 counter the Egg's own trigger put on underneath.
        Assert.Equal(4, now.Power);
        Assert.Equal(5, now.Toughness);
        Assert.True(now.Has(KeywordAbility.Flying));
    }

    /// <summary>
    /// CR 702.140e: the permanent has every component's abilities, whichever card is on top.
    /// </summary>
    /// <remarks>
    /// The Egg's trigger is the one that matters. After the merge it is printed on a card that is
    /// no longer the permanent's - the whole engine reads characteristics from the topmost card -
    /// so a mutate that only swapped the card would leave it silently unwatched. It fires here,
    /// on the very event that buried it.
    /// </remarks>
    [Fact]
    public void A_mutated_permanent_keeps_the_abilities_of_the_card_under_it()
    {
        var (game, alice, _) = InMainPhase();
        var host = game.Create(alice, MutateEgg(), Zone.Battlefield);

        Mutate(game, alice, MutateHeron(), host, ThreeAndBlue, onTop: true);
        Settle(game);

        var merged = game.State.GetObject(host);

        Assert.Equal(
            1, merged.Permanent!.Counters.GetValueOrDefault(CounterKinds.PlusOnePlusOne));

        Assert.Equal(
            [MutateEgg().OracleId], merged.MergedComponents.Select(c => c.OracleId));
    }

    /// <summary>CR 702.140c: the spell's own trigger fires too, on the merge it caused.</summary>
    [Fact]
    public void The_mutating_cards_own_trigger_fires_when_it_merges()
    {
        var (game, alice, _) = InMainPhase();
        var host = game.Create(alice, MutateEgg(), Zone.Battlefield);
        var before = game.State.GetPlayer(alice).Library.Count;

        Mutate(game, alice, MutateHeron(), host, ThreeAndBlue, onTop: true);
        Settle(game);

        Assert.Equal(before - 1, game.State.GetPlayer(alice).Library.Count);
    }

    /// <summary>
    /// CR 702.140c: put under, the permanent keeps its own characteristics and gains only the
    /// abilities.
    /// </summary>
    [Fact]
    public void Mutating_under_a_creature_leaves_its_characteristics_alone()
    {
        var (game, alice, _) = InMainPhase();
        var host = game.Create(alice, MutateEgg(), Zone.Battlefield);

        Mutate(game, alice, MutateHeron(), host, ThreeAndBlue, onTop: false);
        Settle(game);

        var merged = game.State.GetObject(host);
        var now = Characteristics.Of(game.State, Pool, merged);

        // Still the Egg, still its own size before counters - and still flying, because a keyword
        // is an ability and the Heron is underneath (CR 702.140e).
        Assert.Equal("Test Mysterious Egg", now.Name);
        Assert.Equal(1, now.Power);
        Assert.True(now.Has(KeywordAbility.Flying));
    }

    /// <summary>
    /// CR 702.140c again: the spell does not enter the battlefield, it merges.
    /// </summary>
    /// <remarks>
    /// The failure this rules out is the loudest one available and the easiest to write by
    /// accident: a mutating creature spell that resolves the ordinary way leaves two creatures on
    /// the table instead of one.
    /// </remarks>
    [Fact]
    public void A_mutating_creature_spell_does_not_enter_the_battlefield_of_its_own()
    {
        var (game, alice, _) = InMainPhase();
        var host = game.Create(alice, MutateEgg(), Zone.Battlefield);

        Mutate(game, alice, MutateHeron(), host, ThreeAndBlue, onTop: true);
        Settle(game);

        var creatures = game.State.Battlefield
            .Select(game.State.GetObject)
            .Where(o => o.Card.CardTypes.HasFlag(CardType.Creature))
            .ToList();

        Assert.Single(creatures);
        Assert.Equal(host, creatures[0].Id);
        Assert.Empty(game.State.Stack);
    }

    /// <summary>
    /// CR 730.3: when a merged permanent leaves, every card it was made of goes with it.
    /// </summary>
    /// <remarks>
    /// The half a partial implementation loses, and it loses a card out of the game: with only
    /// the topmost component moved, the creature underneath is simply gone the moment the stack
    /// dies. Two cards went onto the battlefield here and two have to come off it.
    /// </remarks>
    [Fact]
    public void Every_card_of_a_merged_permanent_goes_to_the_graveyard()
    {
        var (game, alice, bob) = InMainPhase();
        var host = game.Create(alice, MutateEgg(), Zone.Battlefield);

        Mutate(game, alice, MutateHeron(), host, ThreeAndBlue, onTop: true);
        Settle(game);

        var kill = TestCards.PutInHand(
            game, bob, Card("Test Mutate Murder", "Destroy target creature."));

        TestCards.PassUntil(game, () => game.State.Priority.Holder == bob);
        game.CastSpell(bob, kill, [Target.ToPermanent(host)]);
        Settle(game);

        var yard = game.State.GetPlayer(alice).Graveyard
            .Select(id => game.State.GetObject(id).Card.Name)
            .ToList();

        Assert.Contains("Test Dreamtail Heron", yard);
        Assert.Contains("Test Mysterious Egg", yard);
    }

    /// <summary>
    /// CR 702.140b: with its target gone it is no longer a mutating creature spell, and resolves
    /// as an ordinary creature spell rather than failing to resolve.
    /// </summary>
    /// <remarks>
    /// This is CR 608.3b's exception, and it is worth a test of its own because the ordinary rule
    /// is exactly wrong here: a spell whose every target is illegal does not resolve at all
    /// (CR 608.2b), which would put the creature in its owner's graveyard. The card is supposed
    /// to arrive.
    /// </remarks>
    [Fact]
    public void A_mutating_spell_whose_target_died_arrives_as_an_ordinary_creature()
    {
        var (game, alice, bob) = InMainPhase();
        var host = game.Create(alice, MutateEgg(), Zone.Battlefield);

        Mutate(game, alice, MutateHeron(), host, ThreeAndBlue, onTop: true);

        // In response, the creature it was going to merge with dies.
        TestCards.PassUntil(game, () => game.State.Priority.Holder == bob);
        var kill = TestCards.PutInHand(
            game, bob, Card("Test Mutate Doom", "Destroy target creature."));

        game.CastSpell(bob, kill, [Target.ToPermanent(host)]);
        Settle(game);

        var heron = game.State.Battlefield
            .Select(game.State.GetObject)
            .SingleOrDefault(o => o.Card.Name == "Test Dreamtail Heron");

        Assert.NotNull(heron);
        Assert.Empty(heron!.MergedComponents);
        Assert.DoesNotContain(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Test Dreamtail Heron");
    }

    /// <summary>CR 702.140a: the target has to be a non-Human creature.</summary>
    [Fact]
    public void Mutate_refuses_a_Human()
    {
        var (game, alice, _) = InMainPhase();
        var human = game.Create(
            alice,
            Card("Test Mutate Soldier", string.Empty, CardType.Creature, 2, 2, subtypes: "Human"),
            Zone.Battlefield);

        var spell = TestCards.PutInHand(game, alice, MutateHeron());
        TapLands(game, alice, 4);

        Assert.Throws<InvalidOperationException>(() => game.CastSpell(
            alice, spell, [Target.ToPermanent(human)], mutated: true, mutateOnTop: true));
    }

    /// <summary>
    /// CR 702.140: "the number of times this creature has mutated" counts the stack.
    /// </summary>
    /// <remarks>
    /// Four corpus cards read X this way, and every one of them is a card that does nothing at
    /// all if the clause is left to mean "a number the caster chose" - which on a creature spell
    /// nobody casts for X is zero.
    /// </remarks>
    [Fact]
    public void The_number_of_times_it_has_mutated_is_how_many_cards_are_under_it()
    {
        var hemophage = Card(
            "Test Insatiable Hemophage",
            "Mutate {2}{B}\nDeathtouch\nWhenever this creature mutates, each opponent loses X "
                + "life and you gain X life, where X is the number of times this creature has "
                + "mutated.",
            CardType.Creature,
            2,
            3,
            KeywordAbility.Deathtouch,
            "Nightmare");

        var (game, alice, bob) = InMainPhase();
        var host = game.Create(alice, MutateEgg(), Zone.Battlefield);

        Mutate(game, alice, hemophage, host, TwoAndBlack, onTop: true);
        Settle(game);

        // One card under it, so one life each way.
        Assert.Equal(19, game.State.GetPlayer(bob).Life);
        Assert.Equal(21, game.State.GetPlayer(alice).Life);

        Mutate(game, alice, MutateHeron(), host, ThreeAndBlue, onTop: false);
        Settle(game);

        // Two cards under it now, and the Hemophage is still on top watching for it.
        Assert.Equal(17, game.State.GetPlayer(bob).Life);
        Assert.Equal(23, game.State.GetPlayer(alice).Life);
        Assert.Equal(2, game.State.GetObject(host).TimesMutated);
    }

    /// <summary>
    /// CR 702.140d: an ability watching for any creature mutating sees somebody else's merge.
    /// </summary>
    [Fact]
    public void A_watcher_sees_another_creature_you_control_mutate()
    {
        var symbiote = Card(
            "Test Essence Symbiote",
            "Whenever a creature you control mutates, put a +1/+1 counter on that creature and "
                + "you gain 2 life.",
            CardType.Creature,
            2,
            2,
            subtypes: "Beast");

        var (game, alice, _) = InMainPhase();
        game.Create(alice, symbiote, Zone.Battlefield);
        var host = game.Create(alice, MutateEgg(), Zone.Battlefield);
        var before = game.State.GetPlayer(alice).Life;

        Mutate(game, alice, MutateHeron(), host, ThreeAndBlue, onTop: true);
        Settle(game);

        Assert.Equal(before + 2, game.State.GetPlayer(alice).Life);

        // One from the Egg's own trigger and one from the Symbiote's, which is what "that
        // creature" has to have meant.
        Assert.Equal(
            2,
            game.State.GetObject(host).Permanent!.Counters
                .GetValueOrDefault(CounterKinds.PlusOnePlusOne));
    }

    /// <summary>
    /// CR 730.2a: the merge is a copiable effect, and the copiable values are the topmost card's.
    /// </summary>
    /// <remarks>
    /// Which is what makes a copy of a mutated permanent a copy of the card on top and nothing
    /// else. It holds here without a line of copy code, because the topmost component <em>is</em>
    /// <c>GameObject.Card</c> and that is what <c>Characteristics.CardOf</c> answers with; the
    /// components' abilities live where a grant lives and are not copiable. Asserted so that a
    /// later change to either half has to notice.
    /// </remarks>
    [Fact]
    public void The_copiable_values_of_a_mutated_permanent_are_the_top_cards()
    {
        var (game, alice, _) = InMainPhase();
        var host = game.Create(alice, MutateEgg(), Zone.Battlefield);

        Mutate(game, alice, MutateHeron(), host, ThreeAndBlue, onTop: true);
        Settle(game);

        var merged = game.State.GetObject(host);

        Assert.Equal(
            "Test Dreamtail Heron",
            Characteristics.CardOf(game.State, Pool, merged).Name);
    }

    /// <summary>The board is told what the permanent is made of (CR 730.2).</summary>
    [Fact]
    public void The_view_shows_the_cards_under_a_mutated_permanent()
    {
        var (game, alice, _) = InMainPhase();
        var host = game.Create(alice, MutateEgg(), Zone.Battlefield);

        Mutate(game, alice, MutateHeron(), host, ThreeAndBlue, onTop: true);
        Settle(game);

        var view = Views.PlayerViewProjector.Project(game.State, alice, Pool);
        var merged = view.Battlefield.Single(o => o.Name == "Test Dreamtail Heron");

        var under = Assert.Single(merged.MergedUnder);
        Assert.Equal("Test Mysterious Egg", under.Name);
    }

    /// <summary>A stored game comes back as the same stack of cards (CR 730.2).</summary>
    /// <remarks>
    /// The event that merges carries no cards of its own - it names the spell and reads the card
    /// off it - so this is the check that the reducer and the serializer agree about what a
    /// merged permanent is. <c>Settle</c> already replays the log; this one goes through the
    /// stored text as well, which is what persistence actually does.
    /// </remarks>
    [Fact]
    public void A_mutated_permanent_survives_being_written_out_and_read_back()
    {
        var (game, alice, _) = InMainPhase();
        var host = game.Create(alice, MutateEgg(), Zone.Battlefield);

        Mutate(game, alice, MutateHeron(), host, ThreeAndBlue, onTop: true);
        Settle(game);

        var reloaded = GameReducer.Replay(
            EventLogSerializer.Read(EventLogSerializer.Write(game.Log)));

        Assert.Equal(game.State, reloaded);
        Assert.Equal(
            "Test Mysterious Egg",
            Assert.Single(reloaded.GetObject(host).MergedComponents).Name);
    }

    // ---- The initiative and Undercity (CR 726, CR 701.49d) --------------------

    /// <summary>
    /// "Venture into Undercity" starts Undercity, not the default dungeon (CR 701.49d).
    /// </summary>
    /// <remarks>
    /// The line this round exists for: it was deliberately unread while Undercity's bottommost
    /// room could not be said, because a pattern loose enough to admit it would have sent
    /// nineteen cards into Lost Mine of Phandelver — a different dungeon with different rooms —
    /// while looking implemented. Now that Undercity ships, the named venture has to prove it
    /// arrives in the dungeon it names.
    /// </remarks>
    [Fact]
    public void A_named_venture_enters_Undercity_not_the_default_dungeon()
    {
        var delver = Card(
            "Undercity Delver Test",
            "When ~ enters, venture into Undercity.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var compiled = CardCompiler.Compile(delver);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        game.Create(alice, delver, Zone.Battlefield);
        Settle(game);

        var dungeon = DungeonOf(game, alice);
        Assert.NotNull(dungeon);
        Assert.Equal(Dungeons.Undercity, dungeon.Card.Name);
        Assert.Equal("Secret Entrance", game.State.GetPlayer(alice).DungeonRoom);

        // Entering it grants no designation: venturing into Undercity and taking the
        // initiative are different instructions, and only the second confers the first.
        Assert.Null(game.State.InitiativeId);
    }

    /// <summary>
    /// "When ~ enters, you take the initiative." — nineteen cards say exactly this, and taking
    /// the initiative is venturing into Undercity (CR 726.1, CR 726.2).
    /// </summary>
    [Fact]
    public void Taking_the_initiative_ventures_into_Undercity()
    {
        var herald = Card(
            "Initiative Herald Test",
            "When ~ enters, you take the initiative.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var compiled = CardCompiler.Compile(herald);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        Assert.Null(game.State.InitiativeId);

        game.Create(alice, herald, Zone.Battlefield);
        Settle(game);

        Assert.Equal(alice, game.State.InitiativeId);

        var dungeon = DungeonOf(game, alice);
        Assert.NotNull(dungeon);
        Assert.Equal(Dungeons.Undercity, dungeon.Card.Name);
        Assert.Equal("Secret Entrance", game.State.GetPlayer(alice).DungeonRoom);
    }

    /// <summary>
    /// Taking the initiative while already in a dungeon advances that dungeon (CR 701.49d): a
    /// named venture decides what is started, never what is advanced.
    /// </summary>
    [Fact]
    public void Taking_the_initiative_while_already_in_a_dungeon_advances_that_dungeon()
    {
        var (game, alice, _) = InMainPhase();

        Venture(game, alice);
        Assert.Equal(
            Dungeons.LostMineOfPhandelver, DungeonOf(game, alice)?.Card.Name);

        game.Create(alice, Card(
            "Initiative Spelunker Test",
            "When ~ enters, you take the initiative.",
            CardType.Creature, power: 2, toughness: 2), Zone.Battlefield);
        Settle(game);

        // The venture followed Lost Mine's arrows out of Cave Entrance — the settled game
        // answered the fork with its first arrow — and no Undercity appeared beside it: a
        // player owns one dungeon at a time (CR 309.3).
        Assert.Equal(alice, game.State.InitiativeId);
        Assert.Equal(
            Dungeons.LostMineOfPhandelver, DungeonOf(game, alice)?.Card.Name);
        Assert.Equal("Goblin Lair", game.State.GetPlayer(alice).DungeonRoom);
    }

    /// <summary>
    /// A holder instructed to take the initiative takes it again: no second designation, but
    /// the venture happens all the same (CR 726.5).
    /// </summary>
    [Fact]
    public void Taking_the_initiative_again_ventures_again_without_a_second_designation()
    {
        var (game, alice, _) = InMainPhase();

        game.Create(alice, Card(
            "Initiative Repeat Test",
            "When ~ enters, you take the initiative.",
            CardType.Creature, power: 2, toughness: 2), Zone.Battlefield);
        Settle(game);

        Assert.Equal(alice, game.State.InitiativeId);
        Assert.Equal("Secret Entrance", game.State.GetPlayer(alice).DungeonRoom);

        game.Create(alice, Card(
            "Initiative Repeat Two Test",
            "When ~ enters, you take the initiative.",
            CardType.Creature, power: 2, toughness: 2), Zone.Battlefield);
        Settle(game);

        // Still one holder, and the marker moved: the second taking ventured out of Secret
        // Entrance along its first arrow.
        Assert.Equal(alice, game.State.InitiativeId);
        Assert.Equal("Forge", game.State.GetPlayer(alice).DungeonRoom);
    }

    /// <summary>
    /// The first inherent ability (CR 726.2): at the beginning of the upkeep of the player who
    /// has the initiative, that player ventures into Undercity. Nobody else's upkeep does.
    /// </summary>
    [Fact]
    public void The_initiative_holder_ventures_at_their_own_upkeep()
    {
        var (game, alice, bob) = InMainPhase();

        game.Create(alice, Card(
            "Initiative Watch Test",
            "When ~ enters, you take the initiative.",
            CardType.Creature, power: 2, toughness: 2), Zone.Battlefield);
        Settle(game);
        Assert.Equal("Secret Entrance", game.State.GetPlayer(alice).DungeonRoom);

        // Bob's whole turn passes: his upkeep ventures nothing, because the ability belongs to
        // the upkeep of the player who has the initiative.
        TestCards.PassToTurn(game, 2);
        Assert.Equal(bob, game.State.ActivePlayerId);
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.PrecombatMain);
        Assert.Equal("Secret Entrance", game.State.GetPlayer(alice).DungeonRoom);

        // Alice's upkeep ventures, and Secret Entrance forks, so the venture is mid-question
        // when her turn begins — the room choice is the proof the venture ran with no card cast.
        TestCards.PassUntil(
            game, () => game.State.Choice is { Kind: ChoiceKind.VentureRoom });
        Assert.Equal(3, game.State.TurnNumber);

        game.Choose(alice, ["Lost Well"]);
        Settle(game);

        Assert.Equal("Lost Well", game.State.GetPlayer(alice).DungeonRoom);
    }

    /// <summary>
    /// The second inherent ability (CR 726.2): combat damage to the holder hands the initiative
    /// to the attacker — once for the whole batch, however many creatures connected — and the
    /// taker ventures into their own Undercity for it.
    /// </summary>
    /// <remarks>
    /// "One or more creatures a player controls" is one trigger, so two unblocked attackers must
    /// produce one taking and one venture: a marker past Secret Entrance would mean the batch
    /// was taken twice, the second of them a CR 726.5 re-take the rule does not have. The test
    /// also holds the condition vocabulary to account: Alice's herald watches her own end step
    /// for "if you have the initiative", which is true the turn she takes it and false after
    /// Bob's raiders take it away.
    /// </remarks>
    [Fact]
    public void Combat_damage_to_the_holder_takes_the_initiative_once_per_batch()
    {
        var seer = Card(
            "Initiative Seer Test",
            "When ~ enters, you take the initiative.\n"
                + "At the beginning of your end step, if you have the initiative, "
                + "put a +1/+1 counter on this creature.",
            CardType.Creature,
            power: 1,
            toughness: 4);

        var compiled = CardCompiler.Compile(seer);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var watcher = game.Create(alice, seer, Zone.Battlefield);
        Settle(game);
        Assert.Equal(alice, game.State.InitiativeId);

        var first = game.Create(
            bob, TestCards.Creature("Initiative Raider Test", 2, 2), Zone.Battlefield);
        var second = game.Create(
            bob, TestCards.Creature("Initiative Raider Two Test", 2, 2), Zone.Battlefield);

        // Alice's own end step, while she still holds it: the condition is true and the
        // counter lands.
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.End);
        Settle(game);
        Assert.Equal(
            1,
            game.State.GetObject(watcher).Permanent!.Counters
                .GetValueOrDefault(CounterKinds.PlusOnePlusOne));

        TestCards.PassUntil(game, () => game.State.TurnNumber == 2
            && game.State.CurrentStep == TurnStep.DeclareAttackers);

        game.DeclareAttackers(bob, new Dictionary<ObjectId, AttackTarget>
        {
            [first] = AttackTarget.Player(alice),
            [second] = AttackTarget.Player(alice),
        });

        // Nothing blocks, the damage lands, and the venture's search finds nothing in an
        // all-creature library, so no question interrupts the walk to end of combat.
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Settle(game);

        // Bob took it exactly once: he owns his own Undercity with the marker still on the
        // topmost room, and Alice's dungeon did not move.
        Assert.Equal(bob, game.State.InitiativeId);
        Assert.Equal(16, game.State.GetPlayer(alice).Life);
        Assert.Equal(Dungeons.Undercity, DungeonOf(game, bob)?.Card.Name);
        Assert.Equal("Secret Entrance", game.State.GetPlayer(bob).DungeonRoom);
        Assert.Equal("Secret Entrance", game.State.GetPlayer(alice).DungeonRoom);

        // Alice's next end step: the condition is false now, and the counter count holds.
        TestCards.PassUntil(game, () => game.State.TurnNumber == 3
            && game.State.CurrentStep == TurnStep.End);
        Settle(game);
        Assert.Equal(
            1,
            game.State.GetObject(watcher).Permanent!.Counters
                .GetValueOrDefault(CounterKinds.PlusOnePlusOne));
    }

    /// <summary>
    /// A room ability can target a player, chosen as the ability goes on the stack (CR 603.3d):
    /// Undercity's other side, down through Forge and Trap!.
    /// </summary>
    /// <remarks>
    /// Trap! is the only room in either shipped dungeon that targets a player, and a granted
    /// trigger's targets are the lookup that was blind once already — found by card and ability
    /// id with no source, so the trigger resolved with nothing to aim at. The life has to move,
    /// or that hole has quietly reopened for the player-shaped target.
    /// </remarks>
    [Fact]
    public void A_room_that_targets_a_player_drains_whoever_was_chosen()
    {
        var (game, alice, bob) = InMainPhase();

        var bear = game.Create(
            alice, TestCards.Creature("Trapfinder Bear Test"), Zone.Battlefield);

        game.Create(alice, Card(
            "Trapfinder Test",
            "When ~ enters, venture into Undercity.",
            CardType.Creature, power: 2, toughness: 2), Zone.Battlefield);
        Settle(game);

        VentureTo(game, alice, "Forge", "Trap!");

        // Forge put its two counters on whichever creature the settled game chose.
        Assert.Equal(
            2,
            game.State.Battlefield
                .Select(game.State.GetObject)
                .Sum(o => o.Permanent is { } p
                    ? p.Counters.GetValueOrDefault(CounterKinds.PlusOnePlusOne)
                    : 0));
        Assert.Contains(bear, game.State.Battlefield);

        // Trap! took 5 life from exactly one player — whichever was picked, the total says the
        // room's target resolved rather than fizzling.
        Assert.Equal(
            35,
            game.State.GetPlayer(alice).Life + game.State.GetPlayer(bob).Life);
        Assert.Equal("Trap!", game.State.GetPlayer(alice).DungeonRoom);
    }

    /// <summary>
    /// Undercity's bottommost room, the one that blocked the whole mechanic: reveal the top
    /// ten, put a creature from among them onto the battlefield with three +1/+1 counters, it
    /// gains hexproof until your next turn, then shuffle — and completing the dungeon happens
    /// after all of that (CR 309.6, CR 309.7).
    /// </summary>
    [Fact]
    public void The_bottom_of_Undercity_puts_a_revealed_creature_out_dressed_and_shuffles()
    {
        var (game, alice, bob) = InMainPhase();

        game.Create(alice, Card(
            "Throne Walker Test",
            "When ~ enters, venture into Undercity.",
            CardType.Creature, power: 2, toughness: 2), Zone.Battlefield);
        Settle(game);
        Assert.Equal("Secret Entrance", game.State.GetPlayer(alice).DungeonRoom);

        // Down the token side of the dungeon: Lost Well scries, Stash makes a Treasure,
        // Catacombs a 4/1 menace Skeleton — all plain ventures advancing Undercity (CR 701.49d).
        VentureTo(game, alice, "Lost Well", "Stash", "Catacombs");

        Assert.Equal(Dungeons.Undercity, DungeonOf(game, alice)?.Card.Name);
        Assert.Contains(
            game.State.Battlefield,
            id => game.State.GetObject(id).Card.Name == "Treasure");

        var skeleton = game.State.Battlefield
            .Select(game.State.GetObject)
            .Single(o => o.Card.Name == "Skeleton");
        Assert.True(Now(game, skeleton.Id).Has(KeywordAbility.Menace));

        var inLibrary = game.State.GetPlayer(alice).Library.Count;

        VentureTo(game, alice, "Throne of the Dead Three");

        // One creature came out of the ten revealed; the other nine were shuffled back in.
        Assert.Equal(inLibrary - 1, game.State.GetPlayer(alice).Library.Count);

        var throned = game.State.Battlefield
            .Select(game.State.GetObject)
            .Single(o => o.Permanent is { } p
                && p.Counters.GetValueOrDefault(CounterKinds.PlusOnePlusOne) == 3);
        Assert.StartsWith("Alice", throned.Card.Name, StringComparison.Ordinal);
        Assert.True(Now(game, throned.Id).Has(KeywordAbility.Hexproof));

        // The Throne is the bottommost room, so the dungeon completed as its ability finished —
        // after the creature arrived, or the room would have done nothing (CR 309.6).
        Assert.Null(DungeonOf(game, alice));
        Assert.Contains(
            Dungeons.Undercity, game.State.GetPlayer(alice).CompletedDungeons);

        // "Until your next turn" (CR 611.2b): hexproof holds through Bob's whole turn and is
        // gone as Alice's next begins.
        TestCards.PassToTurn(game, 2);
        Assert.Equal(bob, game.State.ActivePlayerId);
        Assert.True(Now(game, throned.Id).Has(KeywordAbility.Hexproof));

        TestCards.PassToTurn(game, 3);
        Assert.Equal(alice, game.State.ActivePlayerId);
        Assert.False(Now(game, throned.Id).Has(KeywordAbility.Hexproof));
    }

    // ---- Classes (CR 716) ----------------------------------------------------

    /// <summary>Enough untapped basics for a generic cost, tapped for mana.</summary>
    private static void TapLands(Game game, Guid player, int count)
    {
        for (var i = 0; i < count; i++)
        {
            var land = game.Create(player, TestCards.BasicLand("Forest"), Zone.Battlefield);
            game.ActivateAbility(player, land, "mana");
        }
    }

    /// <summary>A two-bar Class whose every section is visible from outside.</summary>
    /// <remarks>
    /// The level 2 section is a static ability and the level 3 section a trigger, because those
    /// are the two that are gated differently and the two that can silently be wrong: a static
    /// that applies a level early looks like a card that is simply good, and a trigger that fires
    /// early looks like nothing at all.
    /// </remarks>
    private static CardDefinition TwoBarClass() => Card(
        "Test Talent",
        "When Test Talent enters, you gain 1 life.\n"
            + "{1}: Level 2\n"
            + "Creatures you control get +1/+1.\n"
            + "{2}: Level 3\n"
            + "When Test Talent becomes level 3, you gain 5 life.",
        CardType.Enchantment,
        null,
        null,
        KeywordAbility.None,
        "Class");

    /// <summary>
    /// A Class starts at level 1, so only its top section is doing anything (CR 716.2d, 716.3).
    /// </summary>
    [Fact]
    public void A_Class_starts_at_level_one_with_only_its_top_section_working()
    {
        var talent = TwoBarClass();
        var compiled = CardCompiler.Compile(talent);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var before = game.State.GetPlayer(alice).Life;
        var bear = game.Create(alice, TestCards.Creature("Test Class Bear", 2, 2), Zone.Battlefield);
        var card = TestCards.PutInHand(game, alice, talent);

        game.CastSpell(alice, card, []);
        Settle(game);

        var klass = game.State.Battlefield
            .Select(game.State.GetObject)
            .Single(o => o.Card.Name == "Test Talent");

        Assert.Equal(1, klass.Permanent!.Level);

        // The top section is always on (CR 716.3).
        Assert.Equal(before + 1, game.State.GetPlayer(alice).Life);

        // The level 2 anthem is not. This is the assertion the whole mechanic turns on: without
        // the gate every Class would arrive with all of its text switched on at once.
        Assert.Equal(2, Characteristics.Of(game.State, Pool, game.State.GetObject(bear)).Power);
    }

    /// <summary>
    /// Paying a level bar switches its section on (CR 716.2a).
    /// </summary>
    [Fact]
    public void Paying_a_level_bar_switches_on_the_section_under_it()
    {
        var (game, alice, _) = InMainPhase();
        var bear = game.Create(alice, TestCards.Creature("Test Class Bear", 2, 2), Zone.Battlefield);
        var card = TestCards.PutInHand(game, alice, TwoBarClass());

        game.CastSpell(alice, card, []);
        Settle(game);

        var klass = game.State.Battlefield
            .Single(id => game.State.GetObject(id).Card.Name == "Test Talent");

        TapLands(game, alice, 3);
        game.ActivateAbility(alice, klass, "level2", []);
        Settle(game);

        Assert.Equal(2, game.State.GetObject(klass).Permanent!.Level);
        Assert.Equal(3, Characteristics.Of(game.State, Pool, game.State.GetObject(bear)).Power);
    }

    /// <summary>
    /// A level bar can only be activated from the level below it (CR 716.2a).
    /// </summary>
    /// <remarks>
    /// Without it a Class is bought once at its top level for one activation, and every bar
    /// underneath is decoration. The refusal is what makes the mechanic cost what it says.
    /// </remarks>
    [Fact]
    public void A_level_bar_cannot_be_reached_without_paying_the_one_below_it()
    {
        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, TwoBarClass());

        game.CastSpell(alice, card, []);
        Settle(game);

        var klass = game.State.Battlefield
            .Single(id => game.State.GetObject(id).Card.Name == "Test Talent");

        TapLands(game, alice, 6);

        Assert.Throws<InvalidOperationException>(
            () => game.ActivateAbility(alice, klass, "level3", []));

        Assert.Equal(1, game.State.GetObject(klass).Permanent!.Level);
    }

    /// <summary>
    /// "When this Class becomes level N" fires as the level is reached (CR 716.2a).
    /// </summary>
    /// <remarks>
    /// It is printed inside the section its own level switches on, and a trigger reads the state
    /// as it was before the event — where the Class is still on the level below. Gated like
    /// everything else in its section it would refuse the one event it exists for.
    /// </remarks>
    [Fact]
    public void A_Class_announces_the_level_it_has_just_reached()
    {
        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, TwoBarClass());

        game.CastSpell(alice, card, []);
        Settle(game);

        var klass = game.State.Battlefield
            .Single(id => game.State.GetObject(id).Card.Name == "Test Talent");

        TapLands(game, alice, 6);
        game.ActivateAbility(alice, klass, "level2", []);
        Settle(game);

        var before = game.State.GetPlayer(alice).Life;

        game.ActivateAbility(alice, klass, "level3", []);
        Settle(game);

        Assert.Equal(3, game.State.GetObject(klass).Permanent!.Level);
        Assert.Equal(before + 5, game.State.GetPlayer(alice).Life);
    }
    // ---- What a counter's name says about power and toughness (CR 122.1c) ----

    /// <summary>
    /// A card that prints -1/-1 counters gets -1/-1 counters (CR 122.1c).
    /// </summary>
    /// <remarks>
    /// The reader for this family chose the counter with an inverted test - "if the printed kind
    /// is not +1/+1 and not -1/-1, keep it, otherwise +1/+1" - so every printed -1/-1 became its
    /// opposite. Thirty-two corpus cards say it and sixteen of them compiled complete, which is
    /// to say the pool served them: Carnifex Demon arrived an 8/8 where the card says 4/4, Grim
    /// Poppet a 7/7 where it says 1/1, Shrewd Hatchling a 10/10 where it says 2/2.
    /// <para>
    /// Nothing in the suite could see it. The line read, the card compiled complete, the counters
    /// went on and were logged, and the creature was simply larger than the cardboard - the one
    /// outcome this compiler exists to make impossible. Both the size and the counter's own name
    /// are asserted, because either alone passes while the other is wrong.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_creature_that_enters_with_minus_counters_is_smaller_not_bigger()
    {
        var demon = Card(
            "Carnifex Demon Test",
            "~ enters with two -1/-1 counters on it.",
            CardType.Creature,
            power: 6,
            toughness: 6);

        var compiled = CardCompiler.Compile(demon);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var id = game.Create(alice, demon, Zone.Battlefield);
        Settle(game);

        var arrived = game.State.GetObject(id);
        Assert.Equal(
            2, arrived.Permanent!.Counters.GetValueOrDefault(CounterKinds.MinusOneMinusOne));
        Assert.Equal(
            0, arrived.Permanent!.Counters.GetValueOrDefault(CounterKinds.PlusOnePlusOne));

        var size = Characteristics.Of(game.State, Pool, arrived);
        Assert.Equal(4, size.Power);
        Assert.Equal(4, size.Toughness);
    }

    /// <summary>
    /// A +1/+0 counter moves power and leaves toughness alone (CR 122.1c).
    /// </summary>
    /// <remarks>
    /// Layer 7c read power and toughness out of a list of two counter names, so a counter called
    /// anything else went onto the permanent, into the log, and did nothing at all. Clockwork
    /// Beast is printed 0/4 and arrives with seven +1/+0 counters; before this it arrived as a
    /// 0/4 whose whole card is about managing counters that had no effect.
    /// <para>
    /// The number word is the other half of the same line. The shared number reader has known
    /// "six" and "seven" all along and this family's own pattern stopped at "five", which is why
    /// a card printing a number one higher was unread rather than misread.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_counter_that_names_only_power_moves_only_power()
    {
        var beast = Card(
            "Clockwork Beast Test",
            "~ enters with seven +1/+0 counters on it.",
            CardType.Creature,
            power: 0,
            toughness: 4);

        var compiled = CardCompiler.Compile(beast);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var id = game.Create(alice, beast, Zone.Battlefield);
        Settle(game);

        var arrived = game.State.GetObject(id);
        Assert.Equal(7, arrived.Permanent!.Counters.GetValueOrDefault("+1/+0"));

        var size = Characteristics.Of(game.State, Pool, arrived);
        Assert.Equal(7, size.Power);
        Assert.Equal(4, size.Toughness);
    }

    /// <summary>
    /// Two counters of different names are added up, not netted (CR 122.1c).
    /// </summary>
    /// <remarks>
    /// The old computation was a single number - pluses minus minuses - and that shape cannot
    /// hold this board: a permanent carrying a +1/+0 and a -0/-1 is one bigger in one direction
    /// and one smaller in the other. It is the case that decides whether the rule was implemented
    /// or merely widened, and it is why the layer now keeps a pair rather than a delta.
    /// </remarks>
    [Fact]
    public void Counters_of_two_names_move_power_and_toughness_separately()
    {
        var golem = Card(
            "Counter Pair Test",
            "~ enters with a +1/+0 counter on it.\nWhen ~ enters, put a -0/-1 counter on ~.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var compiled = CardCompiler.Compile(golem);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var id = game.Create(alice, golem, Zone.Battlefield);
        Settle(game);

        var size = Characteristics.Of(game.State, Pool, game.State.GetObject(id));
        Assert.Equal(3, size.Power);
        Assert.Equal(1, size.Toughness);
    }

    /// <summary>
    /// The counter arrives on "her" and on "him" as readily as on "it" (CR 614.1c).
    /// </summary>
    /// <remarks>
    /// A card whose creature has a gender says so, and the pattern spelled only the neuter
    /// pronoun - so Big Bertha and Michelangelo went unread for one word in a sentence otherwise
    /// identical to the one beside them. Written as a Theory because the three rows are the same
    /// rule and nothing else about them differs.
    /// </remarks>
    [Theory]
    [InlineData("it")]
    [InlineData("her")]
    [InlineData("him")]
    public void The_pronoun_a_card_uses_for_itself_does_not_change_the_rule(string pronoun)
    {
        var spike = Card(
            "Spike Hatcher " + pronoun + " Test",
            "~ enters with six +1/+1 counters on " + pronoun + ".",
            CardType.Creature,
            power: 0,
            toughness: 0);

        var compiled = CardCompiler.Compile(spike);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var id = game.Create(alice, spike, Zone.Battlefield);
        Settle(game);

        // A 0/0 that did not get its counters is dead before anything can measure it, so the
        // permanent still being on the battlefield is half the assertion.
        Assert.Contains(id, game.State.Battlefield);

        var size = Characteristics.Of(game.State, Pool, game.State.GetObject(id));
        Assert.Equal(6, size.Power);
        Assert.Equal(6, size.Toughness);
    }

    /// <summary>
    /// Adamant: the condition printed in front of the sentence (CR 614.1c).
    /// </summary>
    /// <remarks>
    /// The trailing spelling - "...on it if a creature died this turn" - has been read for a
    /// while, and the clause vocabulary that answers it could already answer this one: "at least
    /// three white mana was spent to cast ~" is a question the board reader has understood since
    /// the mana record was kept. Only the word order was new, and the whole adamant cycle sat
    /// unread behind it.
    /// <para>
    /// The false row spends exactly as much mana as the true one, which is what makes it worth
    /// running: a reader that answered from the total rather than from the colour would pass both
    /// rows, and the counter would arrive on a card that did not earn it.
    /// </para>
    /// </remarks>
    [Theory]
    [InlineData("Plains", true)]
    [InlineData("Island", false)]
    public void A_condition_printed_before_the_sentence_is_asked_the_same_way(
        string third, bool earned)
    {
        var paladin = new CardDefinition
        {
            OracleId = "oracle-adamant-paladin-" + third,
            Name = "Ardenvale Paladin " + third + " Test",
            OracleText = "If at least three white mana was spent to cast ~, "
                + "~ enters with a +1/+1 counter on it.",
            CardTypes = CardType.Creature,
            ManaCostRaw = "{2}{W}",
            Cmc = 3,
            Power = 2,
            Toughness = 2,
        };

        var compiled = CardCompiler.Compile(paladin);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, paladin);

        foreach (var basic in new[] { "Plains", "Plains", third })
        {
            var land = game.Create(alice, TestCards.BasicLand(basic), Zone.Battlefield);
            game.ActivateAbility(alice, land, "mana");
        }

        game.CastSpell(alice, card, []);
        Settle(game);

        var arrived = game.State.Battlefield
            .Select(game.State.GetObject)
            .Single(o => o.Card.Name == paladin.Name);

        Assert.Equal(earned ? 3 : 2, Characteristics.Of(game.State, Pool, arrived).Power);
    }

    /// <summary>
    /// "Where X is the number of ..." is the counted number, said another way (CR 614.1c).
    /// </summary>
    /// <remarks>
    /// Magic writes this count three ways and the compiler accepted one. "For each other creature
    /// on the battlefield" and "with X +1/+1 counters on it, where X is the number of other
    /// creatures on the battlefield" are one instruction, and every card carrying the second was
    /// filed under a shape of its own in the work queue - so a family worth a dozen cards looked
    /// like a dozen unrelated one-offs.
    /// <para>
    /// Bob's creature is in the count and the beetle is not. "Other" is honoured by when the
    /// question is asked rather than by a filter: a replacement runs before the move is folded
    /// in, so the permanent arriving is not yet on the battlefield it is counting (CR 400.7).
    /// </para>
    /// </remarks>
    [Fact]
    public void A_counted_number_reads_the_same_group_however_the_card_spells_it()
    {
        var beetle = Card(
            "Stag Beetle Test",
            "~ enters with X +1/+1 counters on it, "
                + "where X is the number of other creatures on the battlefield.",
            CardType.Creature,
            power: 0,
            toughness: 0);

        var compiled = CardCompiler.Compile(beetle);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, TestCards.Creature("Stag Beetle Friend Test", 2, 2), Zone.Battlefield);
        game.Create(bob, TestCards.Creature("Stag Beetle Enemy Test", 2, 2), Zone.Battlefield);

        var id = game.Create(alice, beetle, Zone.Battlefield);
        Settle(game);

        var size = Characteristics.Of(game.State, Pool, game.State.GetObject(id));
        Assert.Equal(2, size.Power);
        Assert.Equal(2, size.Toughness);
    }

    /// <summary>
    /// "A number of ... equal to the number of ..." is that same count, spelled out (CR 614.1c).
    /// </summary>
    /// <remarks>
    /// The third spelling, and the one that also declines the noun: "for each creature card in
    /// your graveyard" and "equal to the number of creature cards in your graveyard" ask the same
    /// zone the same question, and the table the zone reader looks that noun up in is written
    /// singular. The plural found nothing, so the count came back unreadable - the same
    /// declension defect that once cost every "creatures with flying" line, found again in the
    /// other half of the vocabulary.
    /// </remarks>
    [Fact]
    public void A_counted_number_reads_a_zone_group_named_in_the_plural()
    {
        var lurcher = Card(
            "Rhizome Lurcher Test",
            "~ enters with a number of +1/+1 counters on it "
                + "equal to the number of creature cards in your graveyard.",
            CardType.Creature,
            power: 0,
            toughness: 0);

        var compiled = CardCompiler.Compile(lurcher);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        game.Create(alice, TestCards.Creature("Lurcher Dead One Test", 2, 2), Zone.Graveyard);
        game.Create(alice, TestCards.Creature("Lurcher Dead Two Test", 2, 2), Zone.Graveyard);
        game.Create(alice, TestCards.Creature("Lurcher Dead Three Test", 2, 2), Zone.Graveyard);

        // A land in the same graveyard, so a reader that counted cards rather than creature
        // cards reads four here and fails rather than passing on a coincidence.
        game.Create(alice, TestCards.BasicLand("Lurcher Dead Land Test"), Zone.Graveyard);

        var id = game.Create(alice, lurcher, Zone.Battlefield);
        Settle(game);

        var size = Characteristics.Of(game.State, Pool, game.State.GetObject(id));
        Assert.Equal(3, size.Power);
        Assert.Equal(3, size.Toughness);
    }

    // ---- Granting a whole ability to a group (CR 613.1f) ---------------------

    private static IReadOnlyList<string> GrantedIdsOf(Game game, ObjectId id) =>
    [
        .. Game.ActivatedAbilitiesOf(game.State, Pool, game.State.GetObject(id))
            .Select(a => a.Id)
            .Where(a => a.StartsWith("granted:", StringComparison.Ordinal)),
    ];

    /// <summary>
    /// "Lands you control have [ability]" reaches the lands and nothing else.
    /// </summary>
    /// <remarks>
    /// The creature is what carries this test. The filter behind this line checked the tribe and
    /// who controlled the permanent and never once asked what type it was — so before the noun
    /// was read, every permanent its controller owned was handed the ability, and a line that
    /// says "lands" gave a bear the mana ability of an Island.
    /// <para>
    /// Nothing about that is visible from the card: it grants an ability rather than taking one
    /// away, so the only symptom is a board that can do slightly more than it should.
    /// </para>
    /// </remarks>
    [Fact]
    public void An_ability_granted_to_lands_does_not_reach_a_creature()
    {
        var chant = Card(
            "Test Land Chant",
            "Lands you control have \"{T}: Add {B}.\"",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(chant);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var land = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        var bear = game.Create(alice, TestCards.Creature("Test Grant Bear", 2, 2), Zone.Battlefield);
        var theirs = game.Create(bob, TestCards.BasicLand("Forest"), Zone.Battlefield);
        var card = TestCards.PutInHand(game, alice, chant);

        game.CastSpell(alice, card, []);
        Settle(game);

        Assert.NotEmpty(GrantedIdsOf(game, land));
        Assert.Empty(GrantedIdsOf(game, bear));

        // And not the opponent's land either. Without this the fixture cannot see the difference
        // between "lands you control" and "lands": every permanent on the board belonged to the
        // caster, so a filter that ignored control entirely passed. Mutation testing found it -
        // deleting the control check broke no test.
        Assert.Empty(GrantedIdsOf(game, theirs));
    }

    /// <summary>
    /// "All Slivers have [ability]" reaches the Slivers, wherever they are (CR 613.1f).
    /// </summary>
    /// <remarks>
    /// The line never says the word "creature", and the pattern behind it required one — so
    /// twenty-seven Slivers in the corpus went unread while the six spelling it out as "All
    /// Sliver creatures" were fine. The bear is here because a tribe is a filter, not a mood:
    /// "all" means every Sliver on the battlefield, including an opponent's, and still means
    /// only Slivers.
    /// </remarks>
    [Fact]
    public void A_bare_tribe_grant_reaches_that_tribe_and_no_one_else()
    {
        var hive = Card(
            "Test Hive Chant",
            "All Slivers have \"{T}: Add {G}.\"",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(hive);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();

        var mine = game.Create(
            alice,
            Card("Test Muscle Sliver", string.Empty, CardType.Creature, 1, 1, KeywordAbility.None, "Sliver"),
            Zone.Battlefield);

        var theirs = game.Create(
            bob,
            Card("Test Metallic Sliver", string.Empty, CardType.Creature, 1, 1, KeywordAbility.None, "Sliver"),
            Zone.Battlefield);

        var bear = game.Create(alice, TestCards.Creature("Test Hive Bear", 2, 2), Zone.Battlefield);
        var card = TestCards.PutInHand(game, alice, hive);

        game.CastSpell(alice, card, []);
        Settle(game);

        Assert.NotEmpty(GrantedIdsOf(game, mine));

        // "All" is not "you control".
        Assert.NotEmpty(GrantedIdsOf(game, theirs));

        Assert.Empty(GrantedIdsOf(game, bear));
    }
    /// <summary>
    /// A granted ability that uses the stack resolves as itself, not as nothing.
    /// </summary>
    /// <remarks>
    /// Every granted ability in the corpus until now has been a mana ability, and a mana ability
    /// never uses the stack (CR 605.3b) - it resolves the instant it is activated, out of the
    /// definition that was just found. Anything else goes on the stack as an id, and what the id
    /// means is looked up again when it resolves. This asks whether that lookup can still find an
    /// ability the card does not have.
    /// </remarks>
    [Fact]
    public void A_granted_ability_that_uses_the_stack_still_does_what_it_says()
    {
        var chant = Card(
            "Test Draw Chant",
            "Creatures you control have \"{T}: Draw a card.\"",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(chant);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        // Haste, because the granted ability costs a tap and a creature that arrived this turn
        // cannot pay it (CR 302.6). The rule is right and the fixture was wrong.
        var bear = game.Create(
            alice,
            Card("Test Draw Bear", string.Empty, CardType.Creature, 2, 2, KeywordAbility.Haste),
            Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, chant);

        game.CastSpell(alice, card, []);
        Settle(game);

        var granted = Game.ActivatedAbilitiesOf(game.State, Pool, game.State.GetObject(bear))
            .Single(a => a.Id.StartsWith("granted:", StringComparison.Ordinal));

        var before = game.State.GetPlayer(alice).Hand.Count;

        game.ActivateAbility(alice, bear, granted.Id, []);
        Settle(game);

        Assert.Equal(before + 1, game.State.GetPlayer(alice).Hand.Count);
    }
    /// <summary>
    /// A granted <em>triggered</em> ability watches on behalf of the permanent it was given to.
    /// </summary>
    /// <remarks>
    /// The trigger is not on the creature's card and never will be, so a card-keyed lookup
    /// cannot find it either to watch with or to resolve - the same trap the activated abilities
    /// were in, one step further along, because a trigger has to be found twice: once when the
    /// event happens and again when the ability resolves.
    /// <para>
    /// The bear without the chant is what carries this: a version with only the enchanted
    /// creature in it would pass against an implementation that gave the trigger to everything.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_granted_triggered_ability_fires_for_the_creature_it_was_given_to()
    {
        var chant = Card(
            "Test Dirge Chant",
            "Creatures you control have \"When this creature dies, you gain 3 life.\"",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(chant);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var mine = game.Create(alice, TestCards.Creature("Test Dirge Bear", 2, 2), Zone.Battlefield);
        var theirs = game.Create(bob, TestCards.Creature("Test Dirge Ogre", 2, 2), Zone.Battlefield);
        var card = TestCards.PutInHand(game, alice, chant);

        game.CastSpell(alice, card, []);
        Settle(game);

        var before = game.State.GetPlayer(alice).Life;

        game.Move(theirs, Zone.Graveyard, MoveCause.Destroy);
        Settle(game);

        // Not their creature: the chant says "creatures you control".
        Assert.Equal(before, game.State.GetPlayer(alice).Life);

        game.Move(mine, Zone.Graveyard, MoveCause.Destroy);
        Settle(game);

        Assert.Equal(before + 3, game.State.GetPlayer(alice).Life);
    }
    // ---- Level up (CR 711) ---------------------------------------------------

    /// <summary>Student of Warfare, printed exactly as it is (CR 711.1).</summary>
    /// <remarks>
    /// The keywords passed in are the point of the fixture rather than a detail of it. A card
    /// database builds its keyword list from the whole rules text, so a real leveler arrives
    /// carrying first strike <em>and</em> double strike before it has been levelled once - and a
    /// 1/1 with both is a strictly better card than the one printed. Handing them over here is
    /// what lets the test see whether the mechanic takes them back off.
    /// </remarks>
    private static CardDefinition WarfareStudent() => Card(
        "Test Warfare Student",
        "Level up {W} ({W}: Put a level counter on this. Level up only as a sorcery.)\n"
            + "LEVEL 2-6\n"
            + "3/3\n"
            + "First strike\n"
            + "LEVEL 7+\n"
            + "4/4\n"
            + "Double strike",
        CardType.Creature,
        1,
        1,
        KeywordAbility.FirstStrike | KeywordAbility.DoubleStrike,
        "Human",
        "Knight");

    /// <summary>Levels a permanent up, tapping that many Plains for each activation.</summary>
    private static void LevelUp(
        Game game, Guid player, ObjectId permanent, int times, int lands = 1)
    {
        for (var i = 0; i < times; i++)
        {
            for (var paid = 0; paid < lands; paid++)
            {
                var plains = game.Create(player, TestCards.BasicLand("Plains"), Zone.Battlefield);
                game.ActivateAbility(player, plains, "mana");
            }

            game.ActivateAbility(player, permanent, "levelup", []);
            Settle(game);
        }
    }

    /// <summary>How many level counters a permanent is carrying.</summary>
    private static int LevelsOn(Game game, ObjectId permanent) =>
        game.State.GetObject(permanent).Permanent!.Counters.GetValueOrDefault(CounterKinds.Level);

    /// <summary>
    /// A leveler is the card that is printed until its counters reach a level symbol (CR 711.3).
    /// </summary>
    /// <remarks>
    /// The counter at level 1 is what carries this. Student of Warfare's first symbol is
    /// "LEVEL 2-6", so there is a level the card has been paid for and is still its printed self -
    /// and an implementation that switched the first band on at the first counter would pass a
    /// test that only looked at nothing and then at plenty.
    /// <para>
    /// The two keyword assertions before that are the other half. Both are printed flags on the
    /// card, put there by a database reading the whole text, and neither is an ability the
    /// creature has until it has been levelled to the symbol that names it.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_leveler_is_its_printed_self_until_the_counters_reach_a_symbol()
    {
        var student = WarfareStudent();
        var compiled = CardCompiler.Compile(student);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var knight = game.Create(alice, student, Zone.Battlefield);

        var printed = Characteristics.Of(game.State, Pool, game.State.GetObject(knight));
        Assert.Equal(1, printed.Power);
        Assert.Equal(1, printed.Toughness);
        Assert.False(printed.Keywords.HasFlag(KeywordAbility.FirstStrike));
        Assert.False(printed.Keywords.HasFlag(KeywordAbility.DoubleStrike));

        LevelUp(game, alice, knight, 1);

        Assert.Equal(1, LevelsOn(game, knight));

        var below = Characteristics.Of(game.State, Pool, game.State.GetObject(knight));
        Assert.Equal(1, below.Power);
        Assert.Equal(1, below.Toughness);
        Assert.False(below.Keywords.HasFlag(KeywordAbility.FirstStrike));

        LevelUp(game, alice, knight, 1);

        var reached = Characteristics.Of(game.State, Pool, game.State.GetObject(knight));
        Assert.Equal(3, reached.Power);
        Assert.Equal(3, reached.Toughness);
        Assert.True(reached.Keywords.HasFlag(KeywordAbility.FirstStrike));

        // The band it has not reached is still off.
        Assert.False(reached.Keywords.HasFlag(KeywordAbility.DoubleStrike));
    }

    /// <summary>
    /// The symbol a leveler has reached replaces the one below it (CR 711.3).
    /// </summary>
    /// <remarks>
    /// Not "adds to": the last band of Student of Warfare prints double strike and does not
    /// print first strike, so a creature that reaches it stops having first strike. An
    /// implementation that accumulated bands would leave both flags set, look perfectly correct
    /// in play, and be a different card to anything that asks which keywords it has.
    /// </remarks>
    [Fact]
    public void The_symbol_a_leveler_reaches_replaces_the_one_below_it()
    {
        var (game, alice, _) = InMainPhase();
        var knight = game.Create(alice, WarfareStudent(), Zone.Battlefield);

        LevelUp(game, alice, knight, 7);

        Assert.Equal(7, LevelsOn(game, knight));

        var top = Characteristics.Of(game.State, Pool, game.State.GetObject(knight));
        Assert.Equal(4, top.Power);
        Assert.Equal(4, top.Toughness);
        Assert.True(top.Keywords.HasFlag(KeywordAbility.DoubleStrike));
        Assert.False(top.Keywords.HasFlag(KeywordAbility.FirstStrike));
    }

    /// <summary>
    /// A band sets the size in layer 7b, so a +1/+1 counter still counts on top (CR 711.4).
    /// </summary>
    /// <remarks>
    /// The sublayer is the whole assertion. Setting a leveler's size in 7c would add the band's
    /// numbers to the printed ones and make this a 4/4 before the counter and a 5/5 after; doing
    /// it in 7b makes the band the base the counter is added to, which is what the rule says and
    /// the only reading under which a levelled 3/3 with a +1/+1 counter is a 4/4.
    /// </remarks>
    [Fact]
    public void A_bands_size_is_set_before_counters_are_added()
    {
        var (game, alice, _) = InMainPhase();
        var knight = game.Create(alice, WarfareStudent(), Zone.Battlefield);

        LevelUp(game, alice, knight, 2);
        Assert.Equal(3, Characteristics.Of(game.State, Pool, game.State.GetObject(knight)).Power);

        var boost = TestCards.PutInHand(
            game, alice, Card("Test Level Boost", "Put a +1/+1 counter on target creature."));

        TapLands(game, alice, 1);
        game.CastSpell(alice, boost, [Target.ToPermanent(knight)]);
        Settle(game);

        var grown = Characteristics.Of(game.State, Pool, game.State.GetObject(knight));
        Assert.Equal(4, grown.Power);
        Assert.Equal(4, grown.Toughness);
    }

    /// <summary>
    /// Levelling up can only be done at sorcery speed (CR 711.2a, 602.5d).
    /// </summary>
    /// <remarks>
    /// The restriction is printed only in the reminder text, which the compiler strips as noise
    /// before it reads anything - so it is written into the ability rather than read off the
    /// card, and this is the only thing that can tell whether that was done.
    /// </remarks>
    [Fact]
    public void Levelling_up_is_refused_outside_a_main_phase()
    {
        var (game, alice, _) = InMainPhase();
        var knight = game.Create(alice, WarfareStudent(), Zone.Battlefield);
        var plains = game.Create(alice, TestCards.BasicLand("Plains"), Zone.Battlefield);

        TestCards.PassToStep(game, TurnStep.BeginningOfCombat);
        game.ActivateAbility(alice, plains, "mana");

        var refused = Assert.Throws<InvalidOperationException>(
            () => game.ActivateAbility(alice, knight, "levelup", []));

        Assert.Contains("602.5d", refused.Message, StringComparison.Ordinal);
        Assert.Equal(0, LevelsOn(game, knight));
    }

    /// <summary>Enclave Cryptologist, whose bands are two different activated abilities.</summary>
    private static CardDefinition LevelCryptologist() => Card(
        "Test Level Cryptologist",
        "Level up {U} ({U}: Put a level counter on this. Level up only as a sorcery.)\n"
            + "LEVEL 1-2\n"
            + "0/1\n"
            + "{T}: Draw a card, then discard a card.\n"
            + "LEVEL 3+\n"
            + "0/1\n"
            + "{T}: Draw a card.",
        CardType.Creature,
        0,
        1,
        KeywordAbility.None,
        "Merfolk",
        "Wizard");

    /// <summary>Levels a permanent up, paying {1}{U} for each activation.</summary>
    private static void LevelUpBlue(Game game, Guid player, ObjectId permanent, int times)
    {
        for (var i = 0; i < times; i++)
        {
            for (var paid = 0; paid < 2; paid++)
            {
                var island = game.Create(player, TestCards.BasicLand("Island"), Zone.Battlefield);
                game.ActivateAbility(player, island, "mana");
            }

            game.ActivateAbility(player, permanent, "levelup", []);
            Settle(game);
        }
    }

    /// <summary>
    /// An activated ability under a level symbol waits for its band, and stops when the band does
    /// (CR 711.3).
    /// </summary>
    /// <remarks>
    /// The third kind of gate, and the one that could have been wired to nothing without any
    /// other test noticing: a static that applies early looks like a card that is simply good and
    /// a trigger that fires early looks like nothing at all, but an activated ability is offered
    /// or refused and both directions have to be checked. The band the creature has left is
    /// checked while it is untapped, so the refusal can only be about the level.
    /// </remarks>
    [Fact]
    public void An_ability_under_a_level_symbol_waits_for_its_band_and_stops_after_it()
    {
        var mage = LevelCryptologist();
        var compiled = CardCompiler.Compile(mage);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var wizard = game.Create(alice, mage, Zone.Battlefield);

        // A turn of its own, so that tapping is never what a refusal is about (CR 302.6).
        TestCards.PassToTurn(game, 3);
        TestCards.PassToStep(game, TurnStep.PrecombatMain);

        var abilities = Game.ActivatedAbilitiesOf(game.State, Pool, game.State.GetObject(wizard));
        var lower = abilities.Single(a => a.Id.StartsWith("l1", StringComparison.Ordinal)).Id;
        var upper = abilities.Single(a => a.Id.StartsWith("l3", StringComparison.Ordinal)).Id;

        // Nothing yet: the first symbol starts at one counter, and there are none.
        Assert.Throws<InvalidOperationException>(
            () => game.ActivateAbility(alice, wizard, lower, []));

        LevelUpBlue(game, alice, wizard, 1);

        // In the first band, and not the second.
        Assert.Throws<InvalidOperationException>(
            () => game.ActivateAbility(alice, wizard, upper, []));

        var handBefore = game.State.GetPlayer(alice).Hand.Count;
        var graveyardBefore = game.State.GetPlayer(alice).Graveyard.Count;

        game.ActivateAbility(alice, wizard, lower, []);
        Settle(game);

        // Drew one and pitched one, so the hand is the size it was and the graveyard is not.
        Assert.Equal(handBefore, game.State.GetPlayer(alice).Hand.Count);
        Assert.Equal(graveyardBefore + 1, game.State.GetPlayer(alice).Graveyard.Count);

        // Past the first band. Its ability is gone, and the next one has arrived.
        LevelUpBlue(game, alice, wizard, 2);
        Assert.Equal(3, LevelsOn(game, wizard));

        TestCards.PassToTurn(game, 5);
        TestCards.PassToStep(game, TurnStep.PrecombatMain);

        Assert.Throws<InvalidOperationException>(
            () => game.ActivateAbility(alice, wizard, lower, []));

        var beforeDraw = game.State.GetPlayer(alice).Hand.Count;
        game.ActivateAbility(alice, wizard, upper, []);
        Settle(game);

        Assert.Equal(beforeDraw + 1, game.State.GetPlayer(alice).Hand.Count);
    }

    /// <summary>Kabira Vindicator, whose bands are two different anthems.</summary>
    private static CardDefinition LevelVindicator() => Card(
        "Test Level Vindicator",
        "Level up {2}{W} ({2}{W}: Put a level counter on this. Level up only as a sorcery.)\n"
            + "LEVEL 2-4\n"
            + "3/6\n"
            + "Other creatures you control get +1/+1.\n"
            + "LEVEL 5+\n"
            + "4/8\n"
            + "Other creatures you control get +2/+2.",
        CardType.Creature,
        2,
        4,
        KeywordAbility.None,
        "Human",
        "Knight");

    /// <summary>
    /// A static ability under a level symbol waits for its band, and is replaced by the next
    /// one (CR 711.3).
    /// </summary>
    /// <remarks>
    /// A static is the gate that can be wrong in silence: an anthem applying a band early looks
    /// like a card that is simply good, and one that never stops applying looks like nothing at
    /// all until two bands are on at once. Its gate is also a different argument from the
    /// activated one - the permanent arrives as the effect's <em>source</em> rather than as the
    /// thing being computed - so it could have been wired to the wrong object and still passed
    /// every other test here.
    /// <para>
    /// The Vindicator's own size is asserted alongside, because "other creatures" means it does
    /// not pump itself: at the first band it is the 3/6 the symbol prints and not a 4/7.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_static_under_a_level_symbol_waits_for_its_band_and_is_replaced_by_the_next()
    {
        var vindicator = LevelVindicator();
        var compiled = CardCompiler.Compile(vindicator);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var knight = game.Create(alice, vindicator, Zone.Battlefield);
        var bear = game.Create(alice, TestCards.Creature("Test Level Bear", 2, 2), Zone.Battlefield);

        int PowerOf(ObjectId id) =>
            Characteristics.Of(game.State, Pool, game.State.GetObject(id)).Power ?? 0;

        // Nothing yet. Without the gate every band of the card would be on at once.
        Assert.Equal(2, PowerOf(bear));
        Assert.Equal(2, PowerOf(knight));

        LevelUp(game, alice, knight, 2, lands: 3);

        Assert.Equal(3, PowerOf(bear));
        Assert.Equal(3, PowerOf(knight));
        Assert.Equal(6, Characteristics.Of(game.State, Pool, game.State.GetObject(knight)).Toughness);

        LevelUp(game, alice, knight, 3, lands: 3);
        Assert.Equal(5, LevelsOn(game, knight));

        // +2/+2, not +3/+3: the second band replaces the first rather than stacking with it.
        Assert.Equal(4, PowerOf(bear));
        Assert.Equal(4, PowerOf(knight));
    }

    // ---- "It deals" - the source spelled as a pronoun (CR 120.2b) ------------

    /// <summary>
    /// A pronoun that can only mean the source deals the damage from the source.
    /// </summary>
    /// <remarks>
    /// "It deals 2 damage to each creature and each player" is the same instruction as "~ deals
    /// 2 damage to each creature and each player", and the compiler reads it as that sentence:
    /// the word is normalised on the way in rather than given a reader of its own, so every
    /// damage shape the named form already understood arrives working.
    /// <para>
    /// The giant's own damage is the assertion worth having. "Each creature" includes the one
    /// that said it, and a reading that aimed the sentence at the source's opponents - or at
    /// the ability rather than the permanent - would leave it untouched and still look right
    /// everywhere else on the board.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_pronoun_that_can_only_mean_the_source_deals_the_damage_from_it()
    {
        var giant = Card(
            "Magma Giant Test",
            "When ~ enters, it deals 2 damage to each creature and each player.",
            CardType.Creature,
            3,
            3);

        var compiled = CardCompiler.Compile(giant);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var bystander = game.Create(
            bob, TestCards.Creature("Magma Bystander Test", 3, 3), Zone.Battlefield);

        var arrival = game.Create(alice, giant, Zone.Battlefield);
        Settle(game);

        Assert.Equal(18, game.State.GetPlayer(alice).Life);
        Assert.Equal(18, game.State.GetPlayer(bob).Life);
        Assert.Equal(2, game.State.GetObject(bystander).Permanent!.DamageMarked);
        Assert.Equal(2, game.State.GetObject(arrival).Permanent!.DamageMarked);
    }

    /// <summary>
    /// The pronoun reaches every damage sentence the named form already read.
    /// </summary>
    /// <remarks>
    /// This is the whole argument for normalising the word instead of writing a reader for it.
    /// Two narrow pronoun readers already existed - "it deals N damage to &lt;target&gt;" and the
    /// group form - and both are anchored whole, so a sentence with a second clause on the end
    /// fell outside them while the identical sentence naming the source read. Two damages in one
    /// sentence is one of those: 310 corpus cards print the pronoun form of a damage sentence,
    /// and 46 of them complete once the two spellings are one sentence.
    /// <para>
    /// The second half is not a target (CR 601.2c), so the trigger chooses one thing and not two
    /// - a spell that damages you does not target you, and reading it as a target would let the
    /// damage be redirected.
    /// </para>
    /// </remarks>
    [Fact]
    public void The_pronoun_reaches_the_damage_sentences_the_named_form_already_read()
    {
        var club = Card(
            "Billy Club Test",
            "When ~ enters, it deals 2 damage to any target and 1 damage to you.",
            CardType.Creature,
            1,
            1);

        var compiled = CardCompiler.Compile(club);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.Single(compiled.Triggers[0].Targets);

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, club, Zone.Battlefield);
        TestCards.PassUntil(game, () => game.State.Choice is not null);

        // Picked by the target's id rather than by its label, the way the token test above does:
        // the label exists to be unambiguous to a person.
        var choice = game.State.Choice!;
        Assert.Equal(ChoiceKind.ChooseTriggerTargets, choice.Kind);
        game.Choose(alice, [choice.Options!.Single(o => o.Id == $"player:{bob:N}").Id]);
        Settle(game);

        Assert.Equal(18, game.State.GetPlayer(bob).Life);
        Assert.Equal(19, game.State.GetPlayer(alice).Life);
    }

    /// <summary>
    /// A pronoun whose antecedent is not the source is left unread.
    /// </summary>
    /// <remarks>
    /// CR 120.2b: the ability specifies which object deals the damage, and reading the wrong one
    /// is not a detail - lifelink, deathtouch and every "whenever this deals damage" trigger read
    /// the source, and a spell has no power for "equal to its power" to find. So the word is only
    /// normalised where the last thing the line named before it was the source. Three printed
    /// shapes name something else, and all three stay unread:
    /// <list type="bullet">
    /// <item>the trigger names another object - Warstorm Surge, Be'lakor, Stalking Vengeance,
    /// Fiendlash (6 corpus cards);</item>
    /// <item>an earlier sentence targeted a creature and the pronoun is that creature - Deadshot,
    /// Assert Perfection, Venom Blast, Bionic Blow (4 cards);</item>
    /// <item>the trigger names the source <em>or</em> another object and the text cannot say
    /// which entered - Hawkeye, Trick Shot.</item>
    /// </list>
    /// <para>
    /// Each is asserted as a pair, and the pair is what stops the test going vacuous: the same
    /// card with the source named outright <em>does</em> read, so what is being refused is the
    /// pronoun and not the sentence.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_pronoun_whose_antecedent_is_not_the_source_is_left_unread()
    {
        static bool Reads(string name, string text, CardType types, int? power, int? toughness) =>
            CardCompiler.Compile(Card(name, text, types, power, toughness)).IsComplete;

        // The trigger names the creature that entered, not the enchantment that said so.
        Assert.False(Reads(
            "Warstorm Pronoun Test",
            "Whenever a creature you control enters, it deals damage equal to its power "
                + "to any target.",
            CardType.Enchantment,
            null,
            null));

        Assert.True(Reads(
            "Warstorm Named Test",
            "Whenever a creature you control enters, ~ deals damage equal to its power "
                + "to any target.",
            CardType.Enchantment,
            null,
            null));

        // The sentence before it targeted a creature, and that creature is what deals the damage.
        Assert.False(Reads(
            "Deadshot Pronoun Test",
            "Tap target creature. It deals damage equal to its power to another target creature.",
            CardType.Sorcery,
            null,
            null));

        Assert.True(Reads(
            "Deadshot Named Test",
            "Tap target creature. ~ deals damage equal to its power to another target creature.",
            CardType.Sorcery,
            null,
            null));

        // "~ or another Hero" names two candidates and the text cannot say which arrived.
        Assert.False(Reads(
            "Hawkeye Pronoun Test",
            "Whenever ~ or another Hero you control enters, it deals damage equal to the number "
                + "of Heroes you control to any target.",
            CardType.Creature,
            3,
            3));

        Assert.True(Reads(
            "Hawkeye Named Test",
            "Whenever ~ or another Hero you control enters, ~ deals damage equal to the number "
                + "of Heroes you control to any target.",
            CardType.Creature,
            3,
            3));
    }

    /// <summary>
    /// The two words in the middle of a sentence about something else are left where they stand.
    /// </summary>
    /// <remarks>
    /// "A creature you control with a +1/+1 counter on it deals combat damage to a player" and
    /// "any amount of damage it deals to a creature" both contain the words this normalisation
    /// rewrites, and in neither is the pronoun the sentence's subject - the first means the
    /// counter's creature and the second is reminder text. A rewrite that fired there would break
    /// lines that read today, so the pronoun is only taken where it opens a clause.
    /// <para>
    /// Played rather than compiled, because a line can be corrupted and still compile into
    /// something. The counter is on the attacker and the draw is what proves the trigger found
    /// the creature the sentence meant.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_pronoun_that_is_not_a_subject_is_left_where_it_stands()
    {
        var research = Card(
            "Counter Research Test",
            "Whenever a creature you control with a +1/+1 counter on it deals combat damage "
                + "to a player, you may draw a card.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(research);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, research, Zone.Battlefield);

        var attacker = game.Create(
            alice, TestCards.Creature("Counted Attacker Test", 2, 2), Zone.Battlefield);

        game.ChangeCounters(attacker, CounterKinds.PlusOnePlusOne, 1);

        // Turn 3, so the attacker is no longer summoning sick.
        PassTo(game, 3, TurnStep.DeclareAttackers);

        var held = game.State.GetPlayer(alice).Hand.Count;
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        // "You may draw" is offered as a yes/no by the general optional wrapper, and the offer
        // arriving at all is half the assertion: the trigger found the attacker.
        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.OptionalPayment });
        game.Choose(alice, ["yes"]);

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Settle(game);

        Assert.Equal(17, game.State.GetPlayer(bob).Life);
        Assert.Equal(held + 1, game.State.GetPlayer(alice).Hand.Count);
    }

    // ---- A sweep of small templates (round thirteen) --------------------------

    /// <summary>
    /// "Activated abilities of artifacts can't be activated" - Null Rod (CR 602.5c).
    /// </summary>
    /// <remarks>
    /// Two halves, and the second is the one worth the test: the restriction has to reach every
    /// artifact and stop at the edge of the group it names. A reader that applied to whatever it
    /// was handed would pass the first assertion and switch off the whole board.
    /// <para>
    /// Mana abilities go with the rest (CR 602.5c draws no distinction), which is what makes a
    /// Null Rod stop a Sol Ring - so the artifact under it is given a mana ability rather than a
    /// convenient one.
    /// </para>
    /// </remarks>
    [Fact]
    public void An_effect_can_switch_off_every_artifacts_activated_abilities()
    {
        var rod = Card(
            "Null Rod Test",
            "Activated abilities of artifacts can't be activated.",
            CardType.Artifact);

        var compiled = CardCompiler.Compile(rod);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var ring = Card("Silenced Ring Test", "{T}: Add {C}{C}.", CardType.Artifact);
        var elf = Card(
            "Unsilenced Elf Test", "{T}: Add {C}{C}.", CardType.Creature, 1, 1,
            KeywordAbility.Haste);

        var (game, alice, _) = InMainPhase();
        var artifact = game.Create(alice, ring, Zone.Battlefield);
        var creature = game.Create(alice, elf, Zone.Battlefield);

        // Before the rod arrives the artifact taps like anything else.
        Assert.False(
            Characteristics.Of(game.State, Pool, game.State.GetObject(artifact))
                .AbilitiesCantBeActivated);

        game.Create(alice, rod, Zone.Battlefield);
        Settle(game);

        Assert.True(
            Characteristics.Of(game.State, Pool, game.State.GetObject(artifact))
                .AbilitiesCantBeActivated);

        var refused = Assert.Throws<InvalidOperationException>(
            () => game.ActivateAbility(alice, artifact, "mana"));

        // The reason matters: "no such ability" would pass this line while proving nothing.
        Assert.Contains("602.5c", refused.Message, StringComparison.Ordinal);

        // The creature is not an artifact, so its identical ability is untouched. This is the
        // half that fails when the group filter is dropped.
        Assert.False(
            Characteristics.Of(game.State, Pool, game.State.GetObject(creature))
                .AbilitiesCantBeActivated);

        game.ActivateAbility(alice, creature, "mana");
        Settle(game);
    }

    /// <summary>
    /// "Enchanted permanent doesn't untap during its controller's untap step and its activated
    /// abilities can't be activated" - Encrust (CR 502.3, 602.5c).
    /// </summary>
    /// <remarks>
    /// One sentence, two restrictions, and the second clause is why the family went unread: the
    /// untap reader matched everything up to the full stop and the trailing "and" left the line
    /// on the floor. Both halves are asserted because they are separate continuous effects, and
    /// an Aura printing only the untap clause must not acquire the other.
    /// </remarks>
    [Fact]
    public void An_aura_can_hold_a_permanent_down_and_silence_it_in_one_sentence()
    {
        var encrust = Card(
            "Encrust Test",
            "Enchant artifact or creature\n"
                + "Enchanted permanent doesn't untap during its controller's untap step and "
                + "its activated abilities can't be activated.",
            CardType.Enchantment,
            subtypes: "Aura");

        var compiled = CardCompiler.Compile(encrust);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var ring = game.Create(
            alice, Card("Encrusted Ring Test", "{T}: Add {C}{C}.", CardType.Artifact),
            Zone.Battlefield);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, encrust), [Target.ToPermanent(ring)]);
        Settle(game);

        var held = Characteristics.Of(game.State, Pool, game.State.GetObject(ring));

        Assert.True(held.DoesNotUntap);
        Assert.True(held.AbilitiesCantBeActivated);

        Assert.Throws<InvalidOperationException>(
            () => game.ActivateAbility(alice, ring, "mana"));
    }

    /// <summary>
    /// "{2}{G}: This creature can attack this turn as though it didn't have defender"
    /// (CR 702.3b, 609.4).
    /// </summary>
    /// <remarks>
    /// The permission is asked where the attack is declared and nowhere else, so the creature
    /// still <em>has</em> defender the whole time. That is the assertion that matters: taking the
    /// keyword away for the turn would let it attack too, and would quietly shrink every card
    /// that counts creatures with defender.
    /// </remarks>
    [Fact]
    public void A_wall_let_through_for_the_turn_still_has_defender()
    {
        var wall = Card(
            "Nestguard Test",
            "Defender\n{2}{G}: This creature can attack this turn as though it didn't have "
                + "defender.",
            CardType.Creature, 2, 4, KeywordAbility.Defender);

        var compiled = CardCompiler.Compile(wall);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var guard = game.Create(alice, wall, Zone.Battlefield);

        TestCards.PassToTurn(game, 3);
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.PrecombatMain
            && game.State.Priority.Holder == alice);

        Assert.False(
            Characteristics.Of(game.State, Pool, game.State.GetObject(guard))
                .MayAttackAsThoughNoDefender);

        game.AddMana(alice, ManaColor.Green);
        game.AddMana(alice, null, 2);
        game.ActivateAbility(alice, guard, "a");
        Settle(game);

        var let = Characteristics.Of(game.State, Pool, game.State.GetObject(guard));

        Assert.True(let.MayAttackAsThoughNoDefender);
        Assert.True(let.Has(KeywordAbility.Defender));

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [guard] = AttackTarget.Player(bob) });

        Assert.Contains(guard, game.State.Combat.Attackers.Keys);
    }

    /// <summary>The same permission handed to something else - Assault Formation.</summary>
    [Fact]
    public void The_permission_can_be_given_to_another_creature()
    {
        var formation = Card(
            "Assault Formation Test",
            "{1}{G}: Target creature with defender can attack this turn as though it didn't "
                + "have defender.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(formation);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var banner = game.Create(alice, formation, Zone.Battlefield);
        var wall = game.Create(
            alice,
            Card(
                "Plain Wall Test", "Defender", CardType.Creature, 0, 4,
                KeywordAbility.Defender),
            Zone.Battlefield);

        game.AddMana(alice, ManaColor.Green);
        game.AddMana(alice, null, 1);
        game.ActivateAbility(alice, banner, "a", [Target.ToPermanent(wall)]);
        Settle(game);

        var let = Characteristics.Of(game.State, Pool, game.State.GetObject(wall));

        Assert.True(let.MayAttackAsThoughNoDefender);
        Assert.True(let.Has(KeywordAbility.Defender));
    }

    /// <summary>
    /// "{W}: ~ gains protection from the color of your choice until end of turn" - Jareth
    /// (CR 702.16a).
    /// </summary>
    /// <remarks>
    /// The colour is named on resolution rather than when the ability is activated, so the
    /// question is the last thing the ability does and the answer decides which flag lands. The
    /// self form shares its effect with the targeted one - a null index means the source - which
    /// is why this went unread for want of a pattern rather than for want of machinery.
    /// </remarks>
    [Fact]
    public void A_creature_can_ward_itself_against_a_colour_it_names()
    {
        var jareth = Card(
            "Leonine Titan Test",
            "{W}: ~ gains protection from the color of your choice until end of turn.",
            CardType.Creature, 4, 7);

        var compiled = CardCompiler.Compile(jareth);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var cat = game.Create(alice, jareth, Zone.Battlefield);

        game.AddMana(alice, ManaColor.White);
        game.ActivateAbility(alice, cat, "a");

        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.ChooseColor });

        var asked = game.State.Choice!;
        game.Choose(asked.PlayerId, [nameof(ManaColor.Red)]);
        Settle(game);

        var warded = Characteristics.Of(game.State, Pool, game.State.GetObject(cat));

        Assert.True(warded.Has(KeywordAbility.ProtectionFromRed));
        Assert.False(warded.Has(KeywordAbility.ProtectionFromWhite));
    }

    /// <summary>"{U}: Put this creature on top of its owner's library" - Wayward Soul.</summary>
    /// <remarks>
    /// Owner rather than controller, and the top of the library rather than the bottom: both are
    /// printed, and both are the kind of detail a move effect gets wrong silently. The card is
    /// asserted to be the top card by identity, not by count.
    /// </remarks>
    [Fact]
    public void A_permanent_can_put_itself_back_on_top_of_its_library()
    {
        var soul = Card(
            "Wayward Soul Test",
            "Flying\n{U}: Put this creature on top of its owner's library.",
            CardType.Creature, 2, 2, KeywordAbility.Flying);

        var compiled = CardCompiler.Compile(soul);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var spirit = game.Create(alice, soul, Zone.Battlefield);

        game.AddMana(alice, ManaColor.Blue);
        game.ActivateAbility(alice, spirit, "a");
        Settle(game);

        Assert.DoesNotContain(spirit, game.State.Battlefield);

        var top = game.State.GetPlayer(alice).Library[0];
        Assert.Equal("Wayward Soul Test", game.State.GetObject(top).Card.Name);
    }

    /// <summary>
    /// "Whenever this creature becomes blocked, it gets +2/+2 until end of turn for each
    /// creature blocking it" - Rabid Elephant.
    /// </summary>
    /// <remarks>
    /// Rampage without the free first blocker, and the single blocker is the whole test: rampage
    /// gives nothing here and this gives one bonus. Reading the two shapes as one would have made
    /// eight cards wrong in whichever direction the fold went.
    /// </remarks>
    [Fact]
    public void A_blocked_creature_can_count_every_blocker_including_the_first()
    {
        var elephant = Card(
            "Rabid Elephant Test",
            "Whenever ~ becomes blocked, it gets +2/+2 until end of turn for each creature "
                + "blocking it.",
            CardType.Creature, 3, 3);

        var compiled = CardCompiler.Compile(elephant);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, elephant, Zone.Battlefield);
        var blocker = game.Create(bob, TestCards.Creature("Lone Elk Test", 1, 1), Zone.Battlefield);

        TestCards.PassToTurn(game, 3);
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);
        game.DeclareBlockers(
            bob, new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [attacker] = [blocker] });

        Settle(game);

        // One blocker, one bonus: a 3/3 becomes a 5/5 where a rampaging one would still be 3/3.
        Assert.Equal(
            5, Characteristics.Of(game.State, Pool, game.State.GetObject(attacker)).Power);
    }

    /// <summary>
    /// "Whenever this creature becomes blocked, you may untap it and remove it from combat"
    /// - the Gustcloaks (CR 506.4).
    /// </summary>
    /// <remarks>
    /// The removal is what this exists to prove, and it is not the same as the creature dying or
    /// leaving: it stays on the battlefield, untapped, and simply stops being an attacking
    /// creature - so the blocker it was facing deals it no combat damage and takes none.
    /// </remarks>
    [Fact]
    public void A_blocked_creature_can_untap_and_step_out_of_combat()
    {
        var gustcloak = Card(
            "Gustcloak Test",
            "Whenever ~ becomes blocked, you may untap it and remove it from combat.",
            CardType.Creature, 2, 2);

        var compiled = CardCompiler.Compile(gustcloak);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, gustcloak, Zone.Battlefield);
        var blocker = game.Create(bob, TestCards.Creature("Gust Blocker Test", 3, 3), Zone.Battlefield);

        TestCards.PassToTurn(game, 3);
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        // Attacking taps it, which is what makes the untap half visible.
        Assert.True(game.State.GetObject(attacker).Permanent!.IsTapped);

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);
        game.DeclareBlockers(
            bob, new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [attacker] = [blocker] });

        // Settle takes the first option, which is the offer.
        Settle(game);

        Assert.False(game.State.GetObject(attacker).Permanent!.IsTapped);
        Assert.DoesNotContain(attacker, game.State.Combat.Attackers.Keys);
        Assert.DoesNotContain(attacker, game.State.Combat.Blocked);

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.End);

        // A 3/3 blocker never got to swing at it, and it is still on the battlefield.
        Assert.Contains(attacker, game.State.Battlefield);
        Assert.Equal(0, game.State.GetObject(attacker).Permanent!.DamageMarked);
        Assert.Equal(20, game.State.GetPlayer(bob).Life);
        Assert.Contains(blocker, game.State.Battlefield);
    }

    /// <summary>"Counter target spell. Its controller mills two cards" - Psychic Strike.</summary>
    /// <remarks>
    /// "Its controller" is the third verb of a clause the engine already read for life and for
    /// draws, and it finds its player the same way: through the target, followed into the
    /// graveyard the countered spell now sits in (CR 400.7). By the time the mill happens the
    /// spell is not a spell any more, which is exactly the case a naive lookup returns nobody
    /// for - so the assertion is on the opponent's library, not on the effect firing.
    /// </remarks>
    [Fact]
    public void A_counterspell_can_mill_the_countered_spells_controller()
    {
        var strike = Card(
            "Psychic Strike Test", "Counter target spell. Its controller mills two cards.");

        var compiled = CardCompiler.Compile(strike);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();

        TestCards.PassUntil(game, () => game.State.ActivePlayerId == bob
            && game.State.CurrentStep == TurnStep.PrecombatMain
            && game.State.Priority.Holder == bob);

        var before = game.State.GetPlayer(bob).Library.Count;

        var onStack = game.CastSpell(
            bob, TestCards.PutInHand(game, bob, Card("Milled Gain Test", "You gain 5 life.")), []);

        TestCards.PassUntil(game, () => game.State.Priority.Holder == alice);
        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, strike), [Target.ToSpell(onStack)]);

        Settle(game);

        // Countered, so no life; and two cards off the top of the caster's own library.
        Assert.Equal(20, game.State.GetPlayer(bob).Life);
        Assert.Equal(before - 2, game.State.GetPlayer(bob).Library.Count);
        Assert.Equal(3, game.State.GetPlayer(bob).Graveyard.Count);
    }

    // ---- One vocabulary, several readers (r14) --------------------------------

    /// <summary>
    /// "Whenever ~ deals combat damage to a player, that player sacrifices a creature of their
    /// choice" - Demon of Loathing, Cabal Executioner.
    /// </summary>
    /// <remarks>
    /// The edict's subject, not its verb. "Each opponent sacrifices a creature of their choice"
    /// has read for as long as the effect has existed and this had not, because the edict reader
    /// carried its own two-word list of players while the shared player vocabulary next door
    /// spells seven. The instruction, the effect and the question asked are identical; only the
    /// subject differed, and 42 corpus cards sat behind that difference.
    /// <para>
    /// "That player" is the trigger's subject (CR 603.2), which is the case worth playing rather
    /// than merely compiling: the sacrifice has to reach the player the damage was dealt to and
    /// nobody else, so Alice keeps her creature and Bob loses his.
    /// </para>
    /// </remarks>
    [Fact]
    public void An_edict_can_name_the_player_its_trigger_was_about()
    {
        var demon = Card(
            "Loathing Demon Test",
            "Whenever ~ deals combat damage to a player, "
                + "that player sacrifices a creature of their choice.",
            CardType.Creature, 3, 3);

        var compiled = CardCompiler.Compile(demon);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, demon, Zone.Battlefield);
        var mine = game.Create(alice, TestCards.Creature("Loathing Keeper Test"), Zone.Battlefield);
        var theirs = game.Create(bob, TestCards.Creature("Loathing Victim Test"), Zone.Battlefield);
        var theirLand = game.Create(bob, TestCards.BasicLand("Swamp"), Zone.Battlefield);

        TestCards.PassToTurn(game, 3);
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice, new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);
        game.DeclareBlockers(bob, new Dictionary<ObjectId, IReadOnlyList<ObjectId>>());
        PlayOnAnswering(game, () => game.State.CurrentStep >= TurnStep.EndOfCombat);

        // The damaged player pays, and only a creature: the land beside it is not what the
        // sentence asked for, and the attacker's controller is not who it asked.
        Assert.DoesNotContain(theirs, game.State.Battlefield);
        Assert.Contains(theirLand, game.State.Battlefield);
        Assert.Contains(mine, game.State.Battlefield);
        Assert.Equal(17, game.State.GetPlayer(bob).Life);
    }

    /// <summary>
    /// "Whenever a creature dies, that creature's controller sacrifices a land of their choice"
    /// - Burning Sands, Earthlink.
    /// </summary>
    /// <remarks>
    /// The same edict with the other kind of subject: a player the event names by relation to an
    /// object rather than directly (CR 603.2), which the vocabulary spells "the subject's
    /// controller" once the guard has decided the words are not about a target. Worth its own
    /// test because it is the arm where getting it wrong is invisible - the enchantment's own
    /// controller is a plausible reading, and it would take the land off the wrong player.
    /// </remarks>
    [Fact]
    public void An_edict_can_name_the_controller_of_the_permanent_a_trigger_was_about()
    {
        var sands = Card(
            "Burning Sands Test",
            "Whenever a creature dies, that creature's controller sacrifices a land of their choice.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(sands);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, sands, Zone.Battlefield);
        var myLand = game.Create(alice, TestCards.BasicLand("Plains"), Zone.Battlefield);
        var theirLand = game.Create(bob, TestCards.BasicLand("Mountain"), Zone.Battlefield);
        var doomed = game.Create(bob, TestCards.Creature("Sands Victim Test"), Zone.Battlefield);

        var kill = TestCards.PutInHand(
            game, alice, Card("Sands Removal Test", "Destroy target creature."));

        game.CastSpell(alice, kill, [Target.ToPermanent(doomed)]);
        Settle(game);

        // The dead creature's controller loses a land; the enchantment's controller does not.
        Assert.DoesNotContain(theirLand, game.State.Battlefield);
        Assert.Contains(myLand, game.State.Battlefield);
    }

    /// <summary>
    /// "~ gets +1/+0 for each basic land type among lands you control" - Kavu Scout's domain.
    /// </summary>
    /// <remarks>
    /// Domain is not a count of permanents at all - it counts the five basic land types at
    /// CR 305.6, so five Forests are one and a dual land is two - and the shared counting
    /// vocabulary has answered it since it was written. The static pump beside it had its own
    /// three-arm vocabulary and could only walk the battlefield through a target filter, so this
    /// sentence went unread on eighteen cards while the *floating* version of the same pump
    /// counted domain correctly, because that one reads the shared vocabulary back off its own
    /// generated name.
    /// <para>
    /// The two land types are deliberately printed on three lands: a reader that counted
    /// permanents would say three here, and one that counts types says two.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_static_pump_counts_anything_the_shared_vocabulary_counts()
    {
        var scout = Card(
            "Domain Scout Test",
            "~ gets +1/+0 for each basic land type among lands you control.",
            CardType.Creature, 1, 1);

        var compiled = CardCompiler.Compile(scout);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var kavu = game.Create(alice, scout, Zone.Battlefield);

        Assert.Equal(1, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(kavu)));

        foreach (var name in new[] { "Forest", "Forest", "Island" })
            game.Create(alice, TestCards.BasicLand(name), Zone.Battlefield);

        Assert.Equal(3, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(kavu)));
        Assert.Equal(1, Characteristics.ToughnessOf(game.State, Pool, game.State.GetObject(kavu)));
    }

    /// <summary>
    /// "~'s power and toughness are each equal to the number of creature cards in all graveyards"
    /// - Mortivore, Magnivore, Terravore.
    /// </summary>
    /// <remarks>
    /// The same defect one reader over. The characteristic-defining reader knew exactly two piles
    /// - "your hand" and "your graveyard" - so Mortivore was unread beside Lhurgoyf, whose card
    /// is the same sentence about one graveyard. "All graveyards" is a pile the shared vocabulary
    /// has always been able to count; the gap was never the sentence, it was which of the two
    /// vocabularies the sentence happened to reach.
    /// <para>
    /// One creature card in each graveyard, so a reading that counted only the controller's would
    /// say one and pass a laxer assertion. The land in a graveyard is there for the other half:
    /// the noun still has to filter.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_defined_power_counts_every_graveyard_when_the_card_says_all()
    {
        var lhurgoyf = Card(
            "All Graveyards Test",
            "~'s power and toughness are each equal to the number of creature cards "
                + "in all graveyards.",
            CardType.Creature, 0, 0);

        var compiled = CardCompiler.Compile(lhurgoyf);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var goyf = game.Create(alice, lhurgoyf, Zone.Battlefield);

        game.Create(alice, TestCards.Creature("Buried Mine Test"), Zone.Graveyard);
        game.Create(bob, TestCards.Creature("Buried Theirs Test"), Zone.Graveyard);
        game.Create(bob, TestCards.BasicLand("Island"), Zone.Graveyard);

        Assert.Equal(2, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(goyf)));
        Assert.Equal(2, Characteristics.ToughnessOf(game.State, Pool, game.State.GetObject(goyf)));
    }

    /// <summary>
    /// "Destroy all artifacts, creatures, and enchantments" - Nevinyrral's Disk, Purify,
    /// Cleansing Nova.
    /// </summary>
    /// <remarks>
    /// The group grammar has read "artifact or enchantment" for a long time; these lines are the
    /// same group with the printed conjunction spelled the other way, and sixteen wipes were
    /// unread for the word "and" alone.
    /// <para>
    /// The plural on every element is what tells a union apart from one noun with a compound
    /// adjective, which is why the reader tests it before folding the plural away. The land here
    /// is the assertion that matters most: a sweeper that had quietly become "destroy all
    /// permanents" would pass every other line in this test.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_sweeper_can_name_several_kinds_joined_by_and()
    {
        var disk = Card(
            "Disk Sweeper Test", "Destroy all artifacts, creatures, and enchantments.");

        var compiled = CardCompiler.Compile(disk);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var artifact = game.Create(
            alice, Card("Swept Artifact Test", "", CardType.Artifact), Zone.Battlefield);
        var enchantment = game.Create(
            alice, Card("Swept Enchantment Test", "", CardType.Enchantment), Zone.Battlefield);
        var creature = game.Create(bob, TestCards.Creature("Swept Bear Test"), Zone.Battlefield);
        var land = game.Create(bob, TestCards.BasicLand("Forest"), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, disk);
        game.CastSpell(alice, card, targets: null);
        Settle(game);

        Assert.DoesNotContain(artifact, game.State.Battlefield);
        Assert.DoesNotContain(enchantment, game.State.Battlefield);
        Assert.DoesNotContain(creature, game.State.Battlefield);
        Assert.Contains(land, game.State.Battlefield);
    }

    /// <summary>
    /// "Destroy target nonland permanent. Its controller creates a 3/3 green Beast creature
    /// token" - Beast Within, Generous Gift, Pongify.
    /// </summary>
    /// <remarks>
    /// "Its controller" is a player named by relation to something the spell <em>targeted</em>,
    /// which no <see cref="PlayerScope"/> can say - a scope is a relation to the controller of
    /// the ability. The life, draw and mill verbs already had an effect apiece for it; creating a
    /// token did not, so 36 corpus cards ended on a sentence the rest of that family reads.
    /// <para>
    /// The awkward half is that the target is gone by the time the token is made: the sentence in
    /// front destroyed it, and the permanent is a card in a graveyard under a new id (CR 400.7).
    /// Whose it was is still a fact about the game, which is what the shared ownership reader is
    /// for - so the assertion is on who controls the Beast, not merely that one exists.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_token_can_be_made_for_the_controller_of_what_was_targeted()
    {
        var beastWithin = Card(
            "Beast Within Test",
            "Destroy target nonland permanent. "
                + "Its controller creates a 3/3 green Beast creature token.");

        var compiled = CardCompiler.Compile(beastWithin);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var doomed = game.Create(bob, TestCards.Creature("Within Victim Test"), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, beastWithin);
        game.CastSpell(alice, card, [Target.ToPermanent(doomed)]);
        Settle(game);

        Assert.DoesNotContain(doomed, game.State.Battlefield);

        var beast = Assert.Single(
            game.State.Battlefield.Select(game.State.GetObject),
            o => o.Card.Subtypes.Contains("Beast"));

        Assert.Equal(bob, beast.ControllerId);
        Assert.Equal(3, Characteristics.PowerOf(game.State, Pool, beast));
    }

    /// <summary>
    /// "Whenever you attack with two or more creatures, draw a card" - the attack trigger with a
    /// count on it (CR 508.1).
    /// </summary>
    /// <remarks>
    /// One trigger for the whole declaration, exactly as the bare "whenever you attack" is, with
    /// the group counted out of the attackers the event carries. Both halves are asserted because
    /// only the negative one can fail quietly: a condition that ignored its own count would fire
    /// on every attack, which is a strictly better card than the one printed and nothing
    /// downstream could tell.
    /// </remarks>
    [Fact]
    public void An_attack_trigger_can_require_more_than_one_attacker()
    {
        var herald = Card(
            "Attack Count Test",
            "Whenever you attack with two or more creatures, draw a card.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(herald);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        Assert.Equal(0, DrawnWhileAttackingWith(herald, 1));
        Assert.Equal(1, DrawnWhileAttackingWith(herald, 2));
    }

    /// <summary>
    /// Plays on to a condition, answering whatever the game stops to ask on the way.
    /// </summary>
    /// <remarks>
    /// <see cref="TestCards.PassUntil"/> deliberately throws on an outstanding question, so that
    /// a test which was not expecting one is told rather than left to time out. A test whose
    /// whole subject <em>is</em> the question needs the other behaviour, and the first option is
    /// the answer when the assertion is about who was asked rather than what they picked.
    /// </remarks>
    private static void PlayOnAnswering(Game game, Func<bool> until)
    {
        for (var guard = 0; guard < 60 && !until(); guard++)
        {
            if (game.State.Choice is { } choice)
            {
                game.Choose(
                    choice.PlayerId,
                    [.. choice.Options.Take(Math.Max(choice.MinPicks, 1)).Select(o => o.Id)]);

                continue;
            }

            if (game.State.Priority.Holder is not { } holder)
                return;

            game.PassPriority(holder);
        }
    }

    /// <summary>How many cards the attacking player drew from declaring that many attackers.</summary>
    private static int DrawnWhileAttackingWith(CardDefinition watcher, int howMany)
    {
        var (game, alice, bob) = InMainPhase();
        game.Create(alice, watcher, Zone.Battlefield);

        var creatures = Enumerable
            .Range(0, 2)
            .Select(i => game.Create(
                alice,
                TestCards.Creature(
                    "Attack Count Bear " + i.ToString(System.Globalization.CultureInfo.InvariantCulture)
                        + " Test"),
                Zone.Battlefield))
            .ToList();

        TestCards.PassToTurn(game, 3);
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);

        var before = game.State.GetPlayer(alice).Hand.Count;

        game.DeclareAttackers(
            alice,
            creatures.Take(howMany).ToDictionary(id => id, _ => AttackTarget.Player(bob)));

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);
        game.DeclareBlockers(bob, new Dictionary<ObjectId, IReadOnlyList<ObjectId>>());

        return game.State.GetPlayer(alice).Hand.Count - before;
    }

    // ---- Round fifteen: readers that grew a private copy of a shared vocabulary ----

    /// <summary>A spell of one colour, which <see cref="Card"/> has no parameter for.</summary>
    private static CardDefinition ColouredSpell(string name, string text, ManaColor colour) => new()
    {
        OracleId = "oracle-" + name.ToLowerInvariant().Replace(' ', '-'),
        Name = name,
        OracleText = text,
        CardTypes = CardType.Instant,
        ColorIdentity = [colour],
        Colors = [colour],
    };

    /// <summary>
    /// "Counter target red spell" reads the colour the permanent grammar already knew.
    /// </summary>
    /// <remarks>
    /// The spell grammar and the permanent grammar are two readers of one adjective, and only
    /// one of them had the word. The spell one knew card types and nothing else, so "counter
    /// target red spell" was refused while "destroy target red permanent" — the same adjective,
    /// one line away — read perfectly. The typed-spell pattern claims the sentence before the
    /// noun grammar sees it, so there was no second chance, and fourteen corpus cards sat one
    /// adjective short: both Elemental Blasts, Gainsay, Douse, Deathgrip, Lifeforce.
    /// <para>
    /// Answered by the <em>search</em> vocabulary rather than the permanent one, deliberately. A
    /// spell on the stack is a card, so "tapped" and "attacking" have no answer about it and are
    /// refused rather than answered "no" — which is what routing this through the permanent
    /// adjectives would have done.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_counter_aimed_at_a_colour_takes_that_colour_and_refuses_another()
    {
        var blast = Card("Colour Blast Test", "Counter target red spell.");

        var compiled = CardCompiler.Compile(blast);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();

        var burn = TestCards.PutInHand(
            game, alice, ColouredSpell("Red Burn Test", "You gain 2 life.", ManaColor.Red));

        var answer = TestCards.PutInHand(game, alice, blast);

        game.CastSpell(alice, burn, []);
        game.CastSpell(alice, answer, [Target.ToSpell(game.State.Stack[0])]);
        Settle(game);

        // Countered, so the life was never gained and the card is in the graveyard.
        Assert.Equal(20, game.State.GetPlayer(alice).Life);
        Assert.Contains(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Red Burn Test");

        // And a blue spell is not a red one, so aiming at it is refused outright (CR 601.2c).
        var chill = TestCards.PutInHand(
            game, alice, ColouredSpell("Blue Chill Test", "You gain 2 life.", ManaColor.Blue));
        var second = TestCards.PutInHand(
            game, alice, Card("Colour Blast Encore Test", "Counter target red spell."));

        game.CastSpell(alice, chill, []);

        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, second, [Target.ToSpell(game.State.Stack[0])]));
    }

    /// <summary>
    /// A search filter accepts the colour counts its own matcher has always answered.
    /// </summary>
    /// <remarks>
    /// One vocabulary in two halves that had drifted apart: the half answering a filter at
    /// runtime has read "multicolored" and "monocolored" for as long as the cost modifiers have
    /// printed the words, and the half deciding whether the compiler will accept them at all had
    /// never been told. The second assertion is the point — the runtime half needs no change,
    /// because it knew the word the whole time.
    /// </remarks>
    [Fact]
    public void A_search_filter_accepts_the_colour_counts_its_matcher_answers()
    {
        var tutor = Card(
            "Prismatic Tutor Test",
            "Search your library for a multicolored creature card, reveal it, put it into "
                + "your hand, then shuffle.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(tutor);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var gold = new CardDefinition
        {
            OracleId = "oracle-gold-hybrid-test",
            Name = "Gold Hybrid Test",
            CardTypes = CardType.Creature,
            Power = 2,
            Toughness = 2,
            Colors = [ManaColor.Red, ManaColor.Green],
        };

        var mono = new CardDefinition
        {
            OracleId = "oracle-mono-hybrid-test",
            Name = "Mono Hybrid Test",
            CardTypes = CardType.Creature,
            Power = 2,
            Toughness = 2,
            Colors = [ManaColor.Green],
        };

        Assert.True(SearchFilters.Matches("multicolored", gold));
        Assert.False(SearchFilters.Matches("multicolored", mono));
        Assert.True(SearchFilters.Matches("monocolored", mono));
    }

    /// <summary>
    /// "And/or" is a spelling of "or" everywhere except between mana symbols.
    /// </summary>
    /// <remarks>
    /// The counting vocabulary has spelled the slash back into "or" for as long as it has had a
    /// group grammar, and no other reader was told. So "the number of artifacts and/or
    /// enchantments you control" read, while "each white and/or blue creature", "each other
    /// Merfolk and/or Knight you control" and eleven more went unread — each defeated by the
    /// same three characters in a different reader. It is normalised once now, beside the quotes
    /// and the dashes.
    /// </remarks>
    [Fact]
    public void An_and_or_list_reads_as_the_or_list_it_spells()
    {
        var cinder = Card(
            "Prismatic Cinder Test",
            "Prismatic Cinder Test deals 1 damage to each white and/or blue creature.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(cinder);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();

        var white = game.Create(
            alice, Coloured("And Or White Test", ManaColor.White), Zone.Battlefield);
        var blue = game.Create(
            alice, Coloured("And Or Blue Test", ManaColor.Blue), Zone.Battlefield);
        var green = game.Create(
            alice, Coloured("And Or Green Test", ManaColor.Green), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, cinder);
        game.CastSpell(alice, card, []);
        Settle(game);

        Assert.Equal(1, game.State.GetObject(white).Permanent!.DamageMarked);
        Assert.Equal(1, game.State.GetObject(blue).Permanent!.DamageMarked);
        Assert.Equal(0, game.State.GetObject(green).Permanent!.DamageMarked);
    }

    /// <summary>
    /// A kicker written with the same three characters is still two payable halves.
    /// </summary>
    /// <remarks>
    /// Between mana symbols the slash is not a spelling of "or" at all: "Kicker {B} and/or {R}"
    /// is a cost with two halves that may <em>both</em> be paid, and "add mana in any
    /// combination of {R} and/or {G}" is the same word again. The first cut of the rewrite above
    /// took those too and cost fourteen cards that had been reading for months — every Volver,
    /// every Battlemage, Archangel of Wrath, Illuminate, Grand Warlord Radha. Thirteen gained
    /// and fourteen lost is what a count reports as a quiet net minus one, and only a diff of
    /// the whole complete set can show.
    /// </remarks>
    [Fact]
    public void An_and_or_between_mana_symbols_is_left_exactly_as_printed()
    {
        var volver = Card(
            "Kicked Volver Test",
            "Kicker {1}{U} and/or {B}\n"
                + "If Kicked Volver Test was kicked with its {1}{U} kicker, it enters with two "
                + "+1/+1 counters on it.\n"
                + "If Kicked Volver Test was kicked with its {B} kicker, it enters with a "
                + "+1/+1 counter on it.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var compiled = CardCompiler.Compile(volver);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
    }

    /// <summary>
    /// Drawing for each of a group reads when the sentence says who draws.
    /// </summary>
    /// <remarks>
    /// Two readers of one verb, and neither held both vocabularies. The bare imperative "draw a
    /// card for each creature you control" reached the counted-group grammar; the form with a
    /// subject reached the player grammar and had no counted tail at all — though its reader had
    /// been asking for one all along and getting an unmatched group back. The discard and the
    /// mill beside it have carried the tail for ages.
    /// <para>
    /// The tail is <em>read</em>, not merely matched, and that is worth more than the six cards
    /// it looked like it was worth. Giving the pattern the group and leaving the reader on the
    /// bare number completed six corpus cards that would each have drawn exactly one card for
    /// ever — a gain on the count and a loss in the game. Fail-closed, they go back to unread,
    /// and the shape reads for every group the shared vocabulary can actually count.
    /// </para>
    /// </remarks>
    [Fact]
    public void Drawing_for_each_of_a_group_counts_the_group()
    {
        var muse = Card(
            "Counted Muse Test",
            "You draw a card for each creature you control.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(muse);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        game.Create(alice, TestCards.Creature("Counted Muse Bear One Test"), Zone.Battlefield);
        game.Create(alice, TestCards.Creature("Counted Muse Bear Two Test"), Zone.Battlefield);
        game.Create(alice, TestCards.Creature("Counted Muse Bear Three Test"), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, muse);
        var before = game.State.GetPlayer(alice).Hand.Count;

        game.CastSpell(alice, card, []);
        Settle(game);

        // Three creatures, three cards — and the spell itself has left the hand.
        Assert.Equal(before - 1 + 3, game.State.GetPlayer(alice).Hand.Count);

        // A group the shared vocabulary cannot count leaves the line unread rather than
        // drawing one card and calling the card complete.
        var vague = Card(
            "Vague Muse Test",
            "Each other player discards a card. You draw a card for each card discarded this way.",
            CardType.Sorcery);

        Assert.False(CardCompiler.Compile(vague).IsComplete);
    }

    /// <summary>
    /// A defining ability counts a pile its own reader's two arms refused.
    /// </summary>
    /// <remarks>
    /// The defining reader gained a fall-through to the shared counting vocabulary a round ago,
    /// and three <c>return null</c>s above it meant most phrases could never reach it: its own
    /// two-pile arm got the last word over the shared reader underneath. So "the number of cards
    /// in your graveyard" was refused while "the number of cards in all graveyards" — the same
    /// sentence, one word apart — fell past both arms and read perfectly. The arms now answer
    /// what they know and fall through when they do not.
    /// </remarks>
    [Fact]
    public void A_defining_ability_counts_an_untyped_pile_through_the_shared_reader()
    {
        var wight = Card(
            "Untyped Wight Test",
            "Untyped Wight Test's power and toughness are each equal to the number of cards "
                + "in your graveyard.",
            CardType.Creature,
            power: 0,
            toughness: 0);

        var hoarder = Card(
            "Typed Hoarder Test",
            "Typed Hoarder Test's power and toughness are each equal to the number of "
                + "creature cards in your hand.",
            CardType.Creature,
            power: 0,
            toughness: 0);

        var wightCompiled = CardCompiler.Compile(wight);
        Assert.True(wightCompiled.IsComplete, string.Join(" | ", wightCompiled.Unhandled));

        var hoarderCompiled = CardCompiler.Compile(hoarder);
        Assert.True(hoarderCompiled.IsComplete, string.Join(" | ", hoarderCompiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var it = game.Create(alice, wight, Zone.Battlefield);

        Assert.Equal(0, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(it)));

        // Untyped, so a land in the graveyard counts exactly as a creature card does — which is
        // the whole of what the private pile arm could not say.
        game.Create(alice, TestCards.BasicLand("Untyped Wight Forest Test"), Zone.Graveyard);
        game.Create(alice, TestCards.Creature("Untyped Wight Bear Test"), Zone.Graveyard);

        Assert.Equal(2, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(it)));
    }

    /// <summary>
    /// A union of groups folds a tribe's plural the way a single group does.
    /// </summary>
    /// <remarks>
    /// The group grammar was taught to fold a capitalised run's plural — the fix that stopped
    /// Boil asking for the type "Islands", which no card has. The union reader sits sixty lines
    /// below it and kept the seven-word regex that fix exists to patch around, so "destroy all
    /// Zombies and Skeletons" was refused while "destroy all Zombies" read. One vocabulary, two
    /// readers, and only one of them ever got the fix.
    /// </remarks>
    [Fact]
    public void A_union_of_tribes_destroys_both_and_leaves_the_rest()
    {
        var plague = Card(
            "Tribal Plague Test", "Destroy all Zombies and Skeletons.", CardType.Sorcery);

        var compiled = CardCompiler.Compile(plague);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();

        var zombie = game.Create(
            alice,
            Card("Union Zombie Test", string.Empty, CardType.Creature, 2, 2,
                KeywordAbility.None, "Zombie"),
            Zone.Battlefield);

        var skeleton = game.Create(
            alice,
            Card("Union Skeleton Test", string.Empty, CardType.Creature, 1, 1,
                KeywordAbility.None, "Skeleton"),
            Zone.Battlefield);

        var goblin = game.Create(
            alice,
            Card("Union Goblin Test", string.Empty, CardType.Creature, 1, 1,
                KeywordAbility.None, "Goblin"),
            Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, plague);
        game.CastSpell(alice, card, []);
        Settle(game);

        Assert.DoesNotContain(zombie, game.State.Battlefield);
        Assert.DoesNotContain(skeleton, game.State.Battlefield);
        Assert.Contains(goblin, game.State.Battlefield);
    }

    /// <summary>
    /// A plural subtype in a target phrase is the type it is the plural of.
    /// </summary>
    /// <remarks>
    /// The target grammar read a capitalised word as a subtype and never folded its plural, so
    /// "target Mounts" asked for the creature type "Mounts", which no card has — it compiled,
    /// passed the deck gate and found nothing. The group grammar next door has folded one since
    /// the Boil fix. Both readers of one noun, and only one of them had it.
    /// <para>
    /// It surfaced through the "and/or" normalisation above, which turned a phrase the noun
    /// harvester could not cut into one it could, and the satisfiability invariant reported the
    /// filter as unsatisfiable the same afternoon. That is the guard doing exactly its job:
    /// nobody was looking at this reader.
    /// </para>
    /// <para>
    /// "Cyclops" and "Bolas" join "Plains" and "Aurochs" as spelled the same either way. They
    /// had escaped the singulariser only because nothing had ever handed it a subtype from this
    /// reader, and folding them would ask for "Cyclop" and "Bola" — the Locus and Pegasus
    /// mistake, one reader further out.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_plural_subtype_is_folded_and_a_word_that_only_looks_plural_is_not()
    {
        var herd = Card("Mount Herd Test", "Destroy all Mounts.", CardType.Sorcery);
        var aimed = Card("Mount Aim Test", "Destroy target Mounts.", CardType.Sorcery);
        var eye = Card("Cyclops Aim Test", "Destroy target Cyclops.", CardType.Sorcery);

        foreach (var one in new[] { herd, aimed, eye })
        {
            var check = CardCompiler.Compile(one);
            Assert.True(check.IsComplete, one.Name + ": " + string.Join(" | ", check.Unhandled));
        }

        var (game, alice, _) = InMainPhase();

        var mount = game.Create(
            alice,
            Card("Aimed Mount Test", string.Empty, CardType.Creature, 2, 2,
                KeywordAbility.None, "Mount"),
            Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, aimed);
        game.CastSpell(alice, card, [Target.ToPermanent(mount)]);
        Settle(game);

        // Aimed at the plural and it found the singular type, rather than compiling into a
        // filter that matches nothing and refusing every target the card allows.
        Assert.DoesNotContain(mount, game.State.Battlefield);
    }

    /// <summary>
    /// A subtype named in a graveyard is the card type that subtype belongs to.
    /// </summary>
    /// <remarks>
    /// The graveyard reader assumed every capitalised noun was a creature type. That is not a
    /// gap, it is a card that plays wrong in silence: "return target Equipment card from your
    /// graveyard" asked for a card that is both a creature and an Equipment, of which there are
    /// none — and reported itself completely understood. The shared table that settles which
    /// card type a subtype implies was written to end exactly this, and the fix landed in the
    /// permanent grammar and never here, so one word read two ways depending on the zone.
    /// </remarks>
    [Fact]
    public void An_equipment_card_in_a_graveyard_is_an_artifact_and_not_a_creature()
    {
        var recall = Card(
            "Armoury Recall Test",
            "Return target Equipment card from your graveyard to your hand.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(recall);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();

        var blade = game.Create(
            alice,
            Card("Buried Blade Test", string.Empty, CardType.Artifact, null, null,
                KeywordAbility.None, "Equipment"),
            Zone.Graveyard);

        var card = TestCards.PutInHand(game, alice, recall);
        game.CastSpell(alice, card, [Target.ToCard(blade)]);
        Settle(game);

        Assert.Contains(
            game.State.GetPlayer(alice).Hand,
            id => game.State.GetObject(id).Card.Name == "Buried Blade Test");
    }

    // ---- One vocabulary, read the same way by every grammar (CR 109.4, 310.1) ----

    /// <summary>
    /// The adjectives a search phrase reads are the adjectives a graveyard phrase reads.
    /// </summary>
    /// <remarks>
    /// The graveyard reader had a private adjective vocabulary of exactly one word - "nonland" -
    /// beside a shared card-filter vocabulary that has known the colours, the supertypes, the
    /// negations and the conjunctions for as long as searches have existed, and its own pattern
    /// admitted a single noun. So "target legendary creature card from your graveyard" never
    /// reached a reader at all: the phrase did not match, and nothing got the chance to refuse it
    /// for a word the compiler already knew. Sixteen corpus cards print an adjective in this slot.
    /// </remarks>
    [Fact]
    public void An_adjective_in_a_graveyard_phrase_narrows_it_like_a_search_filter()
    {
        var rebirth = Card(
            "Legend Rebirth Test",
            "Return target legendary creature card from your graveyard to your hand.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(rebirth);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();

        var legend = game.Create(
            alice,
            new CardDefinition
            {
                OracleId = "oracle-buried-legend-test",
                Name = "Buried Legend Test",
                CardTypes = CardType.Creature,
                Supertypes = ["Legendary"],
                Power = 2,
                Toughness = 2,
            },
            Zone.Graveyard);

        var ordinary = game.Create(
            alice, TestCards.Creature("Buried Commoner Test"), Zone.Graveyard);

        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, forest, "mana");

        // The adjective is the whole of the restriction: an ordinary creature card in the same
        // graveyard is not a legal target, which is what tells this apart from the phrase
        // without it.
        var wrong = TestCards.PutInHand(game, alice, rebirth);
        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, wrong, [Target.ToCard(ordinary)]));

        var card = TestCards.PutInHand(game, alice, rebirth);
        game.CastSpell(alice, card, [Target.ToCard(legend)]);
        Settle(game);

        Assert.Contains(
            game.State.GetPlayer(alice).Hand,
            id => game.State.GetObject(id).Card.Name == "Buried Legend Test");
    }

    /// <summary>
    /// A search may name one adjective and no type at all.
    /// </summary>
    /// <remarks>
    /// The filter vocabulary is asked for a phrase of at least <em>two</em> words by the search
    /// reader and of at least one by the reader that describes a spell on the stack, and nothing
    /// but the number differed - so "counter target red spell" was read while "search your
    /// library for a red card" was not. One word is a card type or a subtype nearly always, and
    /// both of those are answered before this; the case the second word was excluding was the
    /// bare adjective, which is the only case it was ever asked about.
    /// </remarks>
    [Fact]
    public void A_search_may_name_a_colour_with_no_type_beside_it()
    {
        var raid = Card(
            "Crimson Raid Test",
            "Search your library for a red card, reveal it, put it into your hand, then shuffle.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(raid);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.Equal("red", compiled.Spell!.Effects.OfType<SearchLibrary>().Single().FilterId);

        var (game, alice, _) = InMainPhase();
        game.Create(alice, Coloured("Raid Blue Bear Test", ManaColor.Blue), Zone.Library);
        game.Create(alice, Coloured("Raid Red Bear Test", ManaColor.Red), Zone.Library);

        var card = TestCards.PutInHand(game, alice, raid);
        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, forest, "mana");

        game.CastSpell(alice, card, targets: null);
        Settle(game);

        // The colour is a real filter and not a word that was skipped: the blue creature in the
        // same library is not what the search may take.
        Assert.Contains(
            game.State.GetPlayer(alice).Hand,
            id => game.State.GetObject(id).Card.Name == "Raid Red Bear Test");

        Assert.DoesNotContain(
            game.State.GetPlayer(alice).Hand,
            id => game.State.GetObject(id).Card.Name == "Raid Blue Bear Test");
    }

    /// <summary>
    /// A sweeper reads the hyphenated adjectives a target phrase reads.
    /// </summary>
    /// <remarks>
    /// The target grammar's noun class has carried the hyphen for months, with a comment beside
    /// it saying two spellings of one sentence should not read differently - and the group
    /// classes next to it did not have it. So "destroy target non-Elf creature" was read and
    /// "destroy all non-Elf creatures" was not: the phrase could not even be captured out of the
    /// sentence, so the adjective vocabulary that answers it was never asked. Thirty-eight corpus
    /// cards name a hyphenated adjective in front of a plural noun.
    /// </remarks>
    [Fact]
    public void A_sweeper_may_name_a_negated_creature_type()
    {
        var purge = Card(
            "Elf Purge Test", "Destroy all non-Elf creatures.", CardType.Sorcery);

        var compiled = CardCompiler.Compile(purge);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();

        var elf = game.Create(
            alice,
            Card("Purge Elf Test", string.Empty, CardType.Creature, 2, 2, KeywordAbility.None, "Elf"),
            Zone.Battlefield);

        var goblin = game.Create(
            bob,
            Card(
                "Purge Goblin Test",
                string.Empty,
                CardType.Creature,
                2,
                2,
                KeywordAbility.None,
                "Goblin"),
            Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, purge);
        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, forest, "mana");

        game.CastSpell(alice, card, targets: null);
        Settle(game);

        Assert.Contains(elf, game.State.Battlefield);
        Assert.DoesNotContain(goblin, game.State.Battlefield);
    }

    /// <summary>
    /// And so does a lord, which had the same hole one grammar further in.
    /// </summary>
    /// <remarks>
    /// Two things had to be true for "Non-Elf creatures you control get +1/+1" to read, and
    /// neither was: the static reader's noun class stopped at the hyphen, so the phrase came out
    /// as the word "Non"; and the adjective vocabulary it hands the phrase to answered a negated
    /// card type and a negated colour but not a negated creature type, which is what the hyphen
    /// says (CR 702.73a settles the awkward case - a changeling is every creature type, so it is
    /// a non-Elf no more than it is a non-Wall). Widening the first alone would have been worse
    /// than leaving it: the phrase would have reached the tribe reading and become a lord for a
    /// creature type spelled "Non-Elf", which no card has, compiling as complete and pumping
    /// nothing.
    /// </remarks>
    [Fact]
    public void A_lord_may_name_a_negated_creature_type()
    {
        var banner = Card(
            "Outsider Banner Test",
            "Non-Elf creatures you control get +1/+1.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(banner);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, banner, Zone.Battlefield);

        var elf = game.Create(
            alice,
            Card(
                "Banner Elf Test",
                string.Empty,
                CardType.Creature,
                2,
                2,
                KeywordAbility.None,
                "Elf"),
            Zone.Battlefield);

        var other = game.Create(
            alice, TestCards.Creature("Banner Outsider Test", 2, 2), Zone.Battlefield);

        var theirs = game.Create(
            bob, TestCards.Creature("Banner Their Outsider Test", 2, 2), Zone.Battlefield);

        Settle(game);

        var pool = new CompiledPool();

        Assert.Equal(2, Characteristics.PowerOf(game.State, pool, game.State.GetObject(elf)));
        Assert.Equal(3, Characteristics.PowerOf(game.State, pool, game.State.GetObject(other)));
        Assert.Equal(2, Characteristics.PowerOf(game.State, pool, game.State.GetObject(theirs)));
    }

    /// <summary>
    /// A battle is a permanent, and the type tables now say so (CR 110.4a, 310.1).
    /// </summary>
    /// <remarks>
    /// The target grammar's noun alternation had spelled out "battle or X" for months while the
    /// table behind it had no entry for the word, so every one of those alternatives was dead the
    /// moment it matched. Zero cards were blocked by it, which is exactly why it is worth
    /// closing: a pattern that says a word is read and a table that says it is not is where the
    /// next divergence starts, and the same missing entry really was blocking the graveyard
    /// phrase one reader over.
    /// </remarks>
    [Fact]
    public void A_graveyard_phrase_may_name_a_battle_beside_a_creature()
    {
        var escort = Card(
            "Wildwood Escort Test",
            "Return target creature or battle card from your graveyard to your hand.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(escort);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();

        var battle = game.Create(
            alice,
            new CardDefinition
            {
                OracleId = "oracle-buried-siege-test",
                Name = "Buried Siege Test",
                CardTypes = CardType.Battle,
                Subtypes = ["Siege"],
            },
            Zone.Graveyard);

        var land = game.Create(alice, TestCards.BasicLand("Buried Waste Test"), Zone.Graveyard);

        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, forest, "mana");

        // Either type will do and nothing else will: a land card in the same graveyard answers
        // to neither half.
        var wrong = TestCards.PutInHand(game, alice, escort);
        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, wrong, [Target.ToCard(land)]));

        var card = TestCards.PutInHand(game, alice, escort);
        game.CastSpell(alice, card, [Target.ToCard(battle)]);
        Settle(game);

        Assert.Contains(
            game.State.GetPlayer(alice).Hand,
            id => game.State.GetObject(id).Card.Name == "Buried Siege Test");
    }

    // ---- The frame around a quoted ability (CR 613.1f) ------------------------

    [Fact]
    public void A_condition_switches_a_granted_ability_on_and_off()
    {
        // The composition, not the ability. The quoted half has read for rounds; what the
        // compiler could not read was the sentence around it — the reader that owns a condition
        // has a keyword slot with no quotation mark in it, and the reader that owns a quoted
        // ability has no condition. Neither needed new vocabulary.
        var vial = Card(
            "Conditional Grant Vial Test",
            "As long as you control a Cleric, ~ has \"Whenever a creature you control dies, "
                + "each opponent loses 1 life and you gain 1 life.\"",
            CardType.Artifact);

        var compiled = CardCompiler.Compile(vial);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var relic = game.Create(alice, vial, Zone.Battlefield);
        var bear = game.Create(alice, TestCards.Creature("Vial Bear Test", 2, 2), Zone.Battlefield);
        Settle(game);

        Assert.Empty(
            Characteristics.Of(game.State, Pool, game.State.GetObject(relic)).GrantedTriggers);

        // No Cleric, so the creature dies and nothing happens. Asserted before the Cleric
        // arrives, because a grant that was never conditional would pass every check below.
        game.MarkDamage(bear, 2);
        Settle(game);

        Assert.Equal(20, game.State.GetPlayer(alice).Life);
        Assert.Equal(20, game.State.GetPlayer(bob).Life);

        game.Create(
            alice,
            Card("Vial Cleric Test", string.Empty, CardType.Creature, 1, 1, subtypes: "Cleric"),
            Zone.Battlefield);

        var second =
            game.Create(alice, TestCards.Creature("Vial Bear Two Test", 2, 2), Zone.Battlefield);
        Settle(game);

        Assert.Single(
            Characteristics.Of(game.State, Pool, game.State.GetObject(relic)).GrantedTriggers);

        // And it is a trigger the game can find twice — once when the event happens, to know it
        // is watching, and again when the ability resolves, to know what it does.
        game.MarkDamage(second, 2);
        Settle(game);

        Assert.Equal(21, game.State.GetPlayer(alice).Life);
        Assert.Equal(19, game.State.GetPlayer(bob).Life);
    }

    [Fact]
    public void A_conditional_frame_grants_a_bonus_and_an_ability_from_one_sentence()
    {
        // Threshold, the commonest printing of the frame. The bonus is layer 7c and the ability
        // is layer 6, so one sentence is two effects behind one condition (CR 613.1f, 613.4c).
        var werewolf = Card(
            "Threshold Frame Test",
            "As long as there are seven or more cards in your graveyard, ~ gets +2/+2 and has "
                + "\"When ~ dies, you lose 4 life.\"",
            CardType.Creature,
            2,
            2);

        var compiled = CardCompiler.Compile(werewolf);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var wolf = game.Create(alice, werewolf, Zone.Battlefield);
        Settle(game);

        var below = Characteristics.Of(game.State, Pool, game.State.GetObject(wolf));
        Assert.Equal(2, below.Power);
        Assert.Empty(below.GrantedTriggers);

        foreach (var i in Enumerable.Range(0, 7))
        {
            game.Create(
                alice,
                TestCards.Creature(
                    string.Create(CultureInfo.InvariantCulture, $"Buried Threshold {i} Test"), 1, 1),
                Zone.Graveyard);
        }

        Settle(game);

        var above = Characteristics.Of(game.State, Pool, game.State.GetObject(wolf));
        Assert.Equal(4, above.Power);
        Assert.Equal(4, above.Toughness);
        Assert.Single(above.GrantedTriggers);

        // Four damage kills the 4/4 it now is, and the granted trigger is what takes the life.
        game.MarkDamage(wolf, 4);
        Settle(game);

        Assert.Equal(16, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void A_keyword_and_a_quoted_ability_in_one_sentence_both_land()
    {
        // "Enchanted creature has haste and "<ability>"" — the quotation is a conjunct of the
        // "has", and the clause fold could not see it: a clause beginning with a quotation mark
        // is a subject with a sentence after it until the verb is put back in front of it.
        var aura = Card(
            "Haste And Grant Aura Test",
            "Enchant creature\nEnchanted creature has haste and "
                + "\"{T}: ~ deals 1 damage to any target.\"",
            CardType.Enchantment,
            subtypes: "Aura");

        var compiled = CardCompiler.Compile(aura);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var bear =
            game.Create(alice, TestCards.Creature("Prowess Bear Test", 2, 2), Zone.Battlefield);
        var plain =
            game.Create(alice, TestCards.Creature("Plain Bear Test", 2, 2), Zone.Battlefield);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, aura), [Target.ToPermanent(bear)]);
        Settle(game);

        Assert.True(
            Characteristics.Of(game.State, Pool, game.State.GetObject(bear))
                .Keywords.HasFlag(KeywordAbility.Haste));

        var granted = Game.ActivatedAbilitiesOf(game.State, Pool, game.State.GetObject(bear))
            .Single(a => a.Id.StartsWith("granted:", StringComparison.Ordinal));

        game.ActivateAbility(alice, bear, granted.Id, [Target.ToPlayer(bob)]);
        Settle(game);

        Assert.Equal(19, game.State.GetPlayer(bob).Life);

        // The creature the Aura is not on gets neither half. A grant is invisible from the card
        // that gives it, so a filter that is too generous looks exactly like one that works.
        var other = Characteristics.Of(game.State, Pool, game.State.GetObject(plain));
        Assert.False(other.Keywords.HasFlag(KeywordAbility.Haste));
        Assert.Empty(Game.ActivatedAbilitiesOf(game.State, Pool, game.State.GetObject(plain)));
    }

    [Fact]
    public void A_keyword_list_ending_in_a_quoted_ability_reads_whole()
    {
        // The longest join in the corpus, with a quotation on the end of it. The fold tries the
        // longest span first and backtracks, which is what keeps "first strike, trample" one
        // clause and the quotation another.
        var blade = Card(
            "Long List Equipment Test",
            "Equipped creature gets +5/+5 and has first strike, trample, indestructible, haste, "
                + "and \"Whenever ~ deals combat damage to a creature, exile that creature.\""
                + "\nEquip {2}",
            CardType.Artifact,
            subtypes: "Equipment");

        var compiled = CardCompiler.Compile(blade);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var equipment = game.Create(alice, blade, Zone.Battlefield);
        var bearer =
            game.Create(alice, TestCards.Creature("Kaldra Bearer Test", 2, 2), Zone.Battlefield);

        foreach (var _ in Enumerable.Range(0, 2))
        {
            var land = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
            game.ActivateAbility(alice, land, "mana");
        }

        game.ActivateAbility(alice, equipment, "equip", [Target.ToPermanent(bearer)]);
        Settle(game);

        var worn = Characteristics.Of(game.State, Pool, game.State.GetObject(bearer));

        Assert.Equal(7, worn.Power);
        Assert.Equal(7, worn.Toughness);
        Assert.True(worn.Keywords.HasFlag(KeywordAbility.FirstStrike));
        Assert.True(worn.Keywords.HasFlag(KeywordAbility.Trample));
        Assert.True(worn.Keywords.HasFlag(KeywordAbility.Indestructible));
        Assert.True(worn.Keywords.HasFlag(KeywordAbility.Haste));
        Assert.Single(worn.GrantedTriggers);
    }

    [Fact]
    public void A_comma_inside_a_quotation_is_not_a_clause_join()
    {
        // The join inside a granted ability is not a join. A splitter that cannot tell the two
        // apart cuts the ability in half — the mistake that once put an orphaned quotation mark
        // at the top of the work queue as the largest blocker in the corpus.
        var aura = Card(
            "Quoted Comma Aura Test",
            "Enchant creature\nEnchanted creature has vigilance and "
                + "\"At the beginning of your end step, create a 1/1 white Human creature "
                + "token.\"",
            CardType.Enchantment,
            subtypes: "Aura");

        var compiled = CardCompiler.Compile(aura);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var bear =
            game.Create(alice, TestCards.Creature("Called Bear Test", 2, 2), Zone.Battlefield);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, aura), [Target.ToPermanent(bear)]);
        Settle(game);

        var wearer = Characteristics.Of(game.State, Pool, game.State.GetObject(bear));
        Assert.True(wearer.Keywords.HasFlag(KeywordAbility.Vigilance));
        Assert.Single(wearer.GrantedTriggers);

        var before = game.State.Battlefield.Count;

        TestCards.PassToStep(game, TurnStep.End);
        Settle(game);

        // And the sentence that survived the split is one the game can run.
        Assert.Equal(before + 1, game.State.Battlefield.Count);
    }

    [Fact]
    public void A_frame_it_reads_around_an_ability_it_cannot_leaves_the_whole_line_unread()
    {
        // The rule the whole composition turns on. A permanent given the half of a sentence the
        // compiler happened to understand is neither the printed card nor a refusable one, and
        // no instrument here can see the difference: coverage counts lines, and this would score
        // as progress.
        var half = Card(
            "Half Read Frame Test",
            "As long as you control a Cleric, ~ gets +2/+2 and has "
                + "\"Whenever ~ yodels, you win the game.\"",
            CardType.Creature,
            2,
            2);

        var compiled = CardCompiler.Compile(half);

        Assert.False(compiled.IsComplete);
        Assert.Empty(compiled.Statics);

        var (game, alice, _) = InMainPhase();
        var creature = game.Create(alice, half, Zone.Battlefield);
        game.Create(
            alice,
            Card("Yodel Cleric Test", string.Empty, CardType.Creature, 1, 1, subtypes: "Cleric"),
            Zone.Battlefield);

        Settle(game);

        // Not even the bonus, which is the half a fold that wrote as it went would have kept.
        Assert.Equal(2, Characteristics.Of(game.State, Pool, game.State.GetObject(creature)).Power);
    }

    [Fact]
    public void The_wordings_beside_the_new_frames_still_read_as_they_did()
    {
        // A widened reader can eat a neighbour's clause with every instrument green — the corpus
        // diff, coverage, the ratchet and the mechanic sweep all counted it as a gain the one
        // time it happened. So the neighbours are played rather than counted.
        var plainAura = Card(
            "Plain Conjunction Aura Test",
            "Enchant creature\nEnchanted creature gets +2/+2 and has flying.",
            CardType.Enchantment,
            subtypes: "Aura");

        Assert.True(CardCompiler.Compile(plainAura).IsComplete);

        var (game, alice, _) = InMainPhase();
        var bear =
            game.Create(alice, TestCards.Creature("Neighbour Bear Test", 2, 2), Zone.Battlefield);

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, plainAura), [Target.ToPermanent(bear)]);
        Settle(game);

        var worn = Characteristics.Of(game.State, Pool, game.State.GetObject(bear));
        Assert.Equal(4, worn.Power);
        Assert.True(worn.Keywords.HasFlag(KeywordAbility.Flying));
        Assert.Empty(worn.GrantedActivated);
        Assert.Empty(worn.GrantedTriggers);

        // The conditional static that has owned this frame all along still owns it, and is still
        // conditional: read by the arm that puts the condition back rather than by the wrapper.
        var conditional = Card(
            "Plain Conditional Test",
            "As long as you control a Demon, ~ gets +2/+2.",
            CardType.Creature,
            2,
            2);

        Assert.True(CardCompiler.Compile(conditional).IsComplete);

        var ogre = game.Create(alice, conditional, Zone.Battlefield);
        Settle(game);

        Assert.Equal(2, Characteristics.Of(game.State, Pool, game.State.GetObject(ogre)).Power);

        game.Create(
            alice,
            Card("Neighbour Demon Test", string.Empty, CardType.Creature, 1, 1, subtypes: "Demon"),
            Zone.Battlefield);

        Settle(game);

        Assert.Equal(4, Characteristics.Of(game.State, Pool, game.State.GetObject(ogre)).Power);
    }

    [Fact]
    public void A_group_grant_did_not_become_a_self_grant_or_a_grant_to_everybody()
    {
        // "~" is a subject of the grant pattern now, and it names no noun and no scope. Read one
        // test too late it would fall through to the group filter and hand the ability to every
        // permanent its controller owns; read one test too early it would take the group forms
        // with it. The permanent that must *not* get the ability is what this asserts.
        var lord = Card(
            "Neighbour Group Grant Test",
            "Creatures you control have \"{T}: You gain 1 life.\"",
            CardType.Enchantment);

        Assert.True(CardCompiler.Compile(lord).IsComplete);

        var (game, alice, bob) = InMainPhase();
        var enchantment = game.Create(alice, lord, Zone.Battlefield);
        var mine =
            game.Create(alice, TestCards.Creature("Group Grant Mine Test", 2, 2), Zone.Battlefield);
        var theirs =
            game.Create(bob, TestCards.Creature("Group Grant Theirs Test", 2, 2), Zone.Battlefield);

        Settle(game);

        Assert.Single(Game.ActivatedAbilitiesOf(game.State, Pool, game.State.GetObject(mine)));
        Assert.Empty(Game.ActivatedAbilitiesOf(game.State, Pool, game.State.GetObject(theirs)));

        // The enchantment is not a creature, so the noun keeps it out of its own ability.
        Assert.Empty(
            Game.ActivatedAbilitiesOf(game.State, Pool, game.State.GetObject(enchantment)));
    }

    // ---- "This way": what a resolution did, named by a later sentence (CR 608.2) ----

    /// <summary>Plays on until this player may cast a sorcery again (CR 117.1, 307.1).</summary>
    /// <remarks>
    /// Settling a spell leaves the game wherever the passes took it, which is not reliably a main
    /// phase and not reliably this player's priority - so a second cast in the same test threw
    /// "you do not have priority" on three tests out of four and passed on the fourth by accident
    /// of timing. Asked as a condition rather than as a step, because both halves have to hold.
    /// </remarks>
    private static void UntilTheyMayCastAgain(Game game, Guid player) =>
        TestCards.PassUntil(
            game,
            () => game.State.Stack.IsEmpty
                && game.State.CurrentStep == TurnStep.PrecombatMain
                && game.State.ActivePlayerId == player
                && game.State.Priority.Holder == player);

    /// <summary>
    /// "Destroy all creatures. You gain 2 life for each creature destroyed this way."
    /// </summary>
    /// <remarks>
    /// The whole family in one sentence. CR 608.2 lets a resolution use information about what
    /// happened during itself, and nothing in this engine wrote any of it down — so the count is
    /// not of the board, of the turn, or of anything a state can be asked: it is of what the
    /// sentence in front of it just did, and only a record kept across the effect loop can answer.
    /// <para>
    /// Two creatures are left alive under an opponent's control to make the assertion mean
    /// something. A count that quietly read the battlefield instead would answer zero here, and
    /// zero is exactly what a card doing nothing looks like.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_count_reads_what_this_resolution_just_did()
    {
        var wrath = Card(
            "Wrath Count Test",
            "Destroy all creatures. You gain 2 life for each creature destroyed this way.",
            CardType.Sorcery);

        Assert.True(CardCompiler.Compile(wrath).IsComplete);

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, TestCards.Creature("Wrath Count Mine A", 2, 2), Zone.Battlefield);
        game.Create(alice, TestCards.Creature("Wrath Count Mine B", 2, 2), Zone.Battlefield);
        game.Create(bob, TestCards.Creature("Wrath Count Theirs", 2, 2), Zone.Battlefield);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, wrath), []);
        Settle(game);

        Assert.DoesNotContain(
            game.State.Battlefield,
            id => game.State.GetObject(id).Card.CardTypes.HasFlag(CardType.Creature));

        Assert.Equal(26, game.State.GetPlayer(alice).Life);
        Assert.Equal(20, game.State.GetPlayer(bob).Life);
    }

    /// <summary>
    /// The verb picks out which of the resolution's doings are counted, not the position.
    /// </summary>
    /// <remarks>
    /// The record accumulates rather than replacing, which is only safe because the printed word
    /// says what to count: "for each creature destroyed this way" on a spell that destroyed lands
    /// as well must not count the lands. Keeping the last effect's events instead would answer the
    /// same question by guessing at the order, and would be wrong the moment a card puts a third
    /// sentence between the two.
    /// </remarks>
    [Fact]
    public void The_count_is_the_noun_and_the_verb_and_not_the_whole_batch()
    {
        var quake = Card(
            "Quake Count Test",
            "Destroy all permanents. You gain 2 life for each creature destroyed this way.",
            CardType.Sorcery);

        Assert.True(CardCompiler.Compile(quake).IsComplete);

        var (game, alice, _) = InMainPhase();
        game.Create(alice, TestCards.Creature("Quake Count Bear", 2, 2), Zone.Battlefield);
        game.Create(alice, TestCards.BasicLand("Quake Count Forest"), Zone.Battlefield);
        game.Create(alice, TestCards.BasicLand("Quake Count Island"), Zone.Battlefield);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, quake), []);
        Settle(game);

        // Two per creature, and the two lands are not creatures however they were destroyed.
        Assert.Equal(22, game.State.GetPlayer(alice).Life);
    }

    /// <summary>
    /// "If a creature card is put into a graveyard this way" is asked, not assumed.
    /// </summary>
    /// <remarks>
    /// Both arms, because only the negative one can catch the failure this family is arranged
    /// around: a guard reading an empty record answers no for ever, and a card whose second half
    /// never happens compiles clean, plays without an error, and looks exactly like a card that
    /// works. The positive arm alone would pass against a guard that was always true.
    /// </remarks>
    [Fact]
    public void A_did_it_conditional_is_false_when_it_did_not()
    {
        var wrath = Card(
            "Wrath Conditional Test",
            "Destroy all creatures. If a creature card is put into a graveyard this way, "
                + "you gain 5 life.",
            CardType.Sorcery);

        Assert.True(CardCompiler.Compile(wrath).IsComplete);

        var (game, alice, _) = InMainPhase();

        // Nothing to destroy: the sweeper resolves, the record stays empty, the guard is false.
        game.CastSpell(alice, TestCards.PutInHand(game, alice, wrath), []);
        Settle(game);

        Assert.Equal(20, game.State.GetPlayer(alice).Life);

        game.Create(alice, TestCards.Creature("Wrath Conditional Bear", 2, 2), Zone.Battlefield);
        UntilTheyMayCastAgain(game, alice);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, wrath), []);
        Settle(game);

        Assert.Equal(25, game.State.GetPlayer(alice).Life);
    }

    /// <summary>
    /// "If two or more ... this way" is a threshold, and one is not two (CR 608.2).
    /// </summary>
    /// <remarks>
    /// The number in the clause is read rather than treated as "at least one". A reader that took
    /// only the commonest opening would file the plural forms as understood while answering a
    /// different question, which is the failure mode a coverage number cannot see.
    /// </remarks>
    [Fact]
    public void A_did_it_conditional_counts_up_to_its_threshold()
    {
        var wrath = Card(
            "Wrath Threshold Test",
            "Destroy all creatures. If two or more creature cards are put into a graveyard "
                + "this way, you gain 5 life.",
            CardType.Sorcery);

        Assert.True(CardCompiler.Compile(wrath).IsComplete);

        var (game, alice, _) = InMainPhase();
        game.Create(alice, TestCards.Creature("Wrath Threshold One", 2, 2), Zone.Battlefield);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, wrath), []);
        Settle(game);

        Assert.Equal(20, game.State.GetPlayer(alice).Life);

        game.Create(alice, TestCards.Creature("Wrath Threshold Two", 2, 2), Zone.Battlefield);
        game.Create(alice, TestCards.Creature("Wrath Threshold Three", 2, 2), Zone.Battlefield);
        UntilTheyMayCastAgain(game, alice);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, wrath), []);
        Settle(game);

        Assert.Equal(25, game.State.GetPlayer(alice).Life);
    }

    /// <summary>
    /// A verb whose events arrive after the resolution leaves the whole line unread.
    /// </summary>
    /// <remarks>
    /// <b>The refusal is the load-bearing half of this round.</b> Every question a player has to
    /// answer — a reveal, a search, a chosen discard, a chosen sacrifice — is deferred by this
    /// engine to the settle *after* the resolution, precisely so that a resolution is never
    /// stopped half way through. A sentence asking about one of those from inside the same
    /// resolution would be asking about events that have not happened, would answer nought every
    /// time, and would do it on a card that coverage counts as complete and that no downstream
    /// test can tell from a working one.
    /// <para>
    /// So the verb table is short on purpose, and this asserts what it refuses rather than what it
    /// takes. The line stays unread, which is the one outcome an instrument can see.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_verb_the_record_cannot_answer_leaves_the_line_unread()
    {
        foreach (var deferred in new[] { "revealed", "sacrificed", "discarded", "tapped" })
        {
            var card = Card(
                "Unrecorded " + deferred + " Test",
                "Destroy all creatures. You gain 2 life for each creature " + deferred
                    + " this way.",
                CardType.Sorcery);

            var compiled = CardCompiler.Compile(card);

            Assert.False(compiled.IsComplete);

            // And not half of it either: the sweeper on the front of the line is not compiled
            // into a spell that quietly drops the clause it could not read.
            Assert.Null(compiled.Spell);
        }
    }

    /// <summary>
    /// "For each X this way, its controller ..." is distributive, and fronting it would be a lie.
    /// </summary>
    /// <remarks>
    /// The count in front of the instruction is read by rewriting it to the back, which every verb
    /// here already understands. That rewrite is meaning-preserving only while nothing inside the
    /// instruction points back at the thing being counted: "for each permanent destroyed this way,
    /// its controller draws a card" is one draw for each permanent's <em>own</em> controller, and
    /// fronted it becomes N draws for whoever "its" resolves to once — which on a sweeper that
    /// targets nothing is nobody, or the wrong player.
    /// <para>
    /// Half of the corpus lines in this family print such a pronoun, and reading them would have
    /// been four more complete cards with the tokens going to the wrong side of the table.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_fronted_count_whose_instruction_points_back_is_refused()
    {
        var distributive = Card(
            "Fronted Pronoun Test",
            "Destroy all creatures. For each permanent destroyed this way, its controller "
                + "draws a card.",
            CardType.Sorcery);

        Assert.False(CardCompiler.Compile(distributive).IsComplete);

        // The same sentence with nothing pointing back is the amount it looks like, and reads.
        var plain = Card(
            "Fronted Plain Test",
            "Destroy all creatures. For each creature destroyed this way, you gain 2 life.",
            CardType.Sorcery);

        Assert.True(CardCompiler.Compile(plain).IsComplete);

        var (game, alice, _) = InMainPhase();
        game.Create(alice, TestCards.Creature("Fronted Bear A", 2, 2), Zone.Battlefield);
        game.Create(alice, TestCards.Creature("Fronted Bear B", 2, 2), Zone.Battlefield);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, plain), []);
        Settle(game);

        // The fronted form is the trailing form, so it had better come to the same number.
        Assert.Equal(24, game.State.GetPlayer(alice).Life);
    }

    /// <summary>
    /// The record belongs to one resolution and does not survive into the next (CR 608.2).
    /// </summary>
    /// <remarks>
    /// "This way" means "by this instruction", not "this turn" — the game already has a separate
    /// vocabulary for the turn-wide question, and a record that leaked would make the two silently
    /// the same. Asserted by casting the counting spell a second time with nothing to destroy: a
    /// leak shows up as life gained for creatures the previous spell killed.
    /// </remarks>
    [Fact]
    public void A_record_does_not_survive_its_own_resolution()
    {
        var wrath = Card(
            "Wrath Leak Test",
            "Destroy all creatures. You gain 2 life for each creature destroyed this way.",
            CardType.Sorcery);

        var (game, alice, _) = InMainPhase();
        game.Create(alice, TestCards.Creature("Leak Bear A", 2, 2), Zone.Battlefield);
        game.Create(alice, TestCards.Creature("Leak Bear B", 2, 2), Zone.Battlefield);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, wrath), []);
        Settle(game);

        Assert.Equal(24, game.State.GetPlayer(alice).Life);

        UntilTheyMayCastAgain(game, alice);
        game.CastSpell(alice, TestCards.PutInHand(game, alice, wrath), []);
        Settle(game);

        Assert.Equal(24, game.State.GetPlayer(alice).Life);
    }

    /// <summary>
    /// Where a card went is part of what the participle means: an exile is not a destruction.
    /// </summary>
    /// <remarks>
    /// The record keeps the move rather than a label, and each printed participle asks its own
    /// question of it — which is what stops "exiled this way" and "destroyed this way" being one
    /// entry that answers both. Two spells that do the same amount of work to the same board have
    /// to come out with different numbers here, or the distinction is not being made.
    /// </remarks>
    [Fact]
    public void An_exile_is_not_a_destruction_in_the_record()
    {
        var exiling = Card(
            "Exile Count Test",
            "Exile all creatures. You gain 2 life for each creature card exiled this way.",
            CardType.Sorcery);

        Assert.True(CardCompiler.Compile(exiling).IsComplete);

        var (game, alice, _) = InMainPhase();
        game.Create(alice, TestCards.Creature("Exile Count Bear A", 2, 2), Zone.Battlefield);
        game.Create(alice, TestCards.Creature("Exile Count Bear B", 2, 2), Zone.Battlefield);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, exiling), []);
        Settle(game);

        Assert.Equal(24, game.State.GetPlayer(alice).Life);

        // The same board, destroyed rather than exiled, counts nothing for a sentence about exile.
        var crossed = Card(
            "Exile Crossed Test",
            "Destroy all creatures. You gain 2 life for each creature card exiled this way.",
            CardType.Sorcery);

        Assert.True(CardCompiler.Compile(crossed).IsComplete);

        game.Create(alice, TestCards.Creature("Exile Crossed Bear", 2, 2), Zone.Battlefield);
        UntilTheyMayCastAgain(game, alice);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, crossed), []);
        Settle(game);

        Assert.Equal(24, game.State.GetPlayer(alice).Life);
    }

    // ---- "This way" as an object: the set, a member, and its size (CR 608.2c, 608.2h) ----

    /// <summary>
    /// A member of what this resolution just did, chosen from the record and not from the zone.
    /// </summary>
    /// <remarks>
    /// The other half of the family: the count and the condition ask how many and whether, and
    /// this asks for the things themselves. "From among the cards milled this way" is a set the
    /// board cannot answer for — the cards are in a graveyard that also holds everything else
    /// that ever went there, and a reader that offered the graveyard would offer a card this
    /// spell never touched.
    /// <para>
    /// The noun narrows what may be taken and the rest of the mill still happens: three of the
    /// five are permanents and two are not, so a menu of five would be a card that takes what it
    /// does not say it may.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_member_of_the_recorded_set_is_offered_and_the_noun_narrows_it()
    {
        var harvest = Card(
            "Set Harvest Test",
            "Mill five cards. You may put a permanent card from among the cards milled this way "
                + "into your hand.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(harvest);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();

        // Most recently created is on top, so this is the fifth card down first.
        game.Create(alice, Card("Set Harvest Ritual", string.Empty, CardType.Sorcery), Zone.Library);
        game.Create(alice, Card("Set Harvest Bolt", string.Empty), Zone.Library);
        game.Create(alice, Card("Set Harvest Waste", string.Empty, CardType.Land), Zone.Library);
        game.Create(alice, TestCards.Creature("Set Harvest Ox", 1, 1), Zone.Library);
        game.Create(alice, TestCards.Creature("Set Harvest Bear", 2, 2), Zone.Library);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, harvest), []);
        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.TakeFromTouched });

        var asked = game.State.Choice!;

        Assert.Equal(
            ["Set Harvest Bear", "Set Harvest Ox", "Set Harvest Waste"],
            asked.Options.Select(o => o.Label).OrderBy(l => l, StringComparer.Ordinal));

        // "You may" is the whole difference between this and its instructed twin below.
        Assert.Equal(0, asked.MinPicks);
        Assert.Equal(1, asked.MaxPicks);

        game.Choose(
            asked.PlayerId,
            [asked.Options.Single(o => o.Label == "Set Harvest Bear").Id]);
        Settle(game);

        Assert.Contains(
            game.State.GetPlayer(alice).Hand,
            id => game.State.GetObject(id).Card.Name == "Set Harvest Bear");

        // The four not taken are where the mill left them. Named one at a time rather than
        // counted by prefix, because the spell itself is in that graveyard too.
        var buried = game.State.GetPlayer(alice).Graveyard
            .Select(id => game.State.GetObject(id).Card.Name)
            .ToList();

        Assert.Contains("Set Harvest Ox", buried);
        Assert.Contains("Set Harvest Waste", buried);
        Assert.Contains("Set Harvest Bolt", buried);
        Assert.Contains("Set Harvest Ritual", buried);
        Assert.DoesNotContain("Set Harvest Bear", buried);
    }

    /// <summary>
    /// Only what this sentence touched, not everything of that kind sitting in the zone.
    /// </summary>
    /// <remarks>
    /// The failure this guards is the tempting one: a graveyard is right there, it holds cards of
    /// the right kind, and reading it would make the card look like it works. Cache Grab on an
    /// eight-card graveyard would offer all eight.
    /// </remarks>
    [Fact]
    public void The_set_is_what_the_sentence_did_and_not_what_the_zone_holds()
    {
        var dowser = Card(
            "Set Dowser Test",
            "Mill a card. You may put a permanent card milled this way into your hand.",
            CardType.Sorcery);

        Assert.True(CardCompiler.Compile(dowser).IsComplete);

        var (game, alice, _) = InMainPhase();

        game.Create(alice, TestCards.Creature("Set Dowser Buried", 3, 3), Zone.Graveyard);
        game.Create(alice, TestCards.Creature("Set Dowser Milled", 2, 2), Zone.Library);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, dowser), []);
        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.TakeFromTouched });

        var asked = game.State.Choice!;
        Assert.Equal(["Set Dowser Milled"], asked.Options.Select(o => o.Label));
    }

    /// <summary>
    /// An instruction takes one; only "you may" offers none (CR 608.2, 118.3).
    /// </summary>
    /// <remarks>
    /// One effect for both wordings, so the minimum is the only thing that moves. A reader that
    /// made every one of these optional would give the player a decline the card never printed,
    /// and one that made them all mandatory would take a card Wasteful Harvest lets them leave.
    /// </remarks>
    [Fact]
    public void An_instruction_over_the_set_has_no_declining_option()
    {
        var manual = Card(
            "Set Manual Test",
            "Mill five cards, then return a creature card milled this way to your hand.",
            CardType.Sorcery);

        Assert.True(CardCompiler.Compile(manual).IsComplete);

        var (game, alice, _) = InMainPhase();
        game.Create(alice, TestCards.Creature("Set Manual Ox", 1, 1), Zone.Library);
        game.Create(alice, TestCards.Creature("Set Manual Bear", 2, 2), Zone.Library);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, manual), []);
        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.TakeFromTouched });

        Assert.Equal(1, game.State.Choice!.MinPicks);
        Assert.Equal(1, game.State.Choice!.MaxPicks);
    }

    /// <summary>
    /// "Up to two" raises the ceiling and lowers the floor at once (CR 601.2d, 118.3).
    /// </summary>
    /// <remarks>
    /// The printed ceiling is a ceiling and not a quantity: taking fewer is allowed, and taking
    /// none is a legal answer to "up to". Asserted on its own because Stitcher Geralf is the only
    /// card in the corpus printing this arm and it stays incomplete for a reason two sentences
    /// further on — so nothing else would ever exercise the multi-pick path.
    /// </remarks>
    [Fact]
    public void Up_to_two_of_the_set_is_a_ceiling_and_not_a_quantity()
    {
        var geralf = Card(
            "Set Geralf Test",
            "Mill three cards. Exile up to two creature cards put into graveyards this way.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(geralf);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        game.Create(alice, Card("Set Geralf Waste", string.Empty, CardType.Land), Zone.Library);
        game.Create(alice, TestCards.Creature("Set Geralf Ox", 1, 1), Zone.Library);
        game.Create(alice, TestCards.Creature("Set Geralf Bear", 2, 2), Zone.Library);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, geralf), []);
        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.TakeFromTouched });

        var asked = game.State.Choice!;
        Assert.Equal(0, asked.MinPicks);
        Assert.Equal(2, asked.MaxPicks);
        Assert.Equal(
            ["Set Geralf Bear", "Set Geralf Ox"],
            asked.Options.Select(o => o.Label).OrderBy(l => l, StringComparer.Ordinal));

        game.Choose(asked.PlayerId, [.. asked.Options.Select(o => o.Id)]);
        Settle(game);

        Assert.Equal(
            2,
            game.State.Exile.Count(
                id => game.State.GetObject(id).Card.Name.StartsWith(
                    "Set Geralf ", StringComparison.Ordinal)));
    }

    /// <summary>
    /// A set with nothing in it asks nothing and stops nothing (CR 118.3).
    /// </summary>
    /// <remarks>
    /// A mill that turns up no card of the named kind is the card working, not a game waiting on
    /// an answer with no options — and a question raised with an empty menu is a hung game rather
    /// than a wrong one, which is why this half is asserted at all.
    /// </remarks>
    [Fact]
    public void A_set_with_no_member_of_the_named_kind_asks_nothing()
    {
        var dowser = Card(
            "Set Empty Test",
            "Mill two cards. You may put an instant or sorcery card milled this way into your hand.",
            CardType.Sorcery);

        Assert.True(CardCompiler.Compile(dowser).IsComplete);

        var (game, alice, _) = InMainPhase();
        game.Create(alice, TestCards.Creature("Set Empty Ox", 1, 1), Zone.Library);
        game.Create(alice, TestCards.Creature("Set Empty Bear", 2, 2), Zone.Library);

        var before = game.State.GetPlayer(alice).Hand.Count;

        game.CastSpell(alice, TestCards.PutInHand(game, alice, dowser), []);
        Settle(game);

        Assert.Null(game.State.Choice);

        // The card cast came from the hand and went back to a count of nothing gained: no member
        // of the named kind was there to take, so nothing was put anywhere.
        Assert.Equal(before, game.State.GetPlayer(alice).Hand.Count);

        var buried = game.State.GetPlayer(alice).Graveyard
            .Select(id => game.State.GetObject(id).Card.Name)
            .ToList();

        Assert.Contains("Set Empty Bear", buried);
        Assert.Contains("Set Empty Ox", buried);
    }

    /// <summary>
    /// The set as a permission rather than a move — "you may play cards exiled this way".
    /// </summary>
    /// <remarks>
    /// The same window the impulse-draw pair grants, given to the cards the record names instead
    /// of to the cards one adjacent sentence exiled. Nothing is chosen, so this arm of the family
    /// carries none of the deferred-answer difficulty the taking arm does.
    /// </remarks>
    [Fact]
    public void The_recorded_set_can_be_given_a_window_to_be_played_in()
    {
        var escape = Card(
            "Set Escape Test",
            "Exile the top three cards of your library. You may play cards exiled this way "
                + "until the end of your next turn.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(escape);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        game.Create(alice, TestCards.Creature("Set Escape Third", 1, 1), Zone.Library);
        game.Create(alice, TestCards.Creature("Set Escape Second", 2, 2), Zone.Library);
        game.Create(alice, TestCards.Creature("Set Escape First", 3, 3), Zone.Library);

        var turn = game.State.TurnNumber;

        game.CastSpell(alice, TestCards.PutInHand(game, alice, escape), []);
        Settle(game);

        var exiled = game.State.Exile
            .Select(game.State.GetObject)
            .Where(o => o.Card.Name.StartsWith("Set Escape ", StringComparison.Ordinal))
            .ToList();

        Assert.Equal(3, exiled.Count);
        Assert.All(exiled, o => Assert.Equal(turn, o.MayPlayThroughOwnersNextTurn));
    }

    /// <summary>
    /// An amount that is a characteristic of the one thing touched, not a count of them.
    /// </summary>
    /// <remarks>
    /// "Where X is the mana value of the permanent exiled this way" is the fourth grammar of this
    /// family and the only one that is not a number of things. It is written in the singular and
    /// answered in the singular: nothing touched and several touched both come to zero, because a
    /// phrase saying "the permanent" has not said which one.
    /// </remarks>
    [Fact]
    public void An_amount_reads_a_characteristic_of_the_one_thing_touched()
    {
        var intrusion = Card(
            "Set Intrusion Test",
            "Exile target artifact or enchantment. Put X +1/+1 counters on target creature you "
                + "control, where X is the mana value of the permanent exiled this way.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(intrusion);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();

        var relic = game.Create(
            alice,
            new CardDefinition
            {
                OracleId = "oracle-set-intrusion-relic",
                Name = "Set Intrusion Relic",
                CardTypes = CardType.Artifact,
                ManaCostRaw = "{3}",
                Cmc = 3,
            },
            Zone.Battlefield);

        var bear = game.Create(alice, TestCards.Creature("Set Intrusion Bear", 2, 2), Zone.Battlefield);

        game.CastSpell(
            alice,
            TestCards.PutInHand(game, alice, intrusion),
            [Target.ToPermanent(relic), Target.ToPermanent(bear)]);
        Settle(game);

        Assert.Equal(
            3,
            game.State.GetObject(bear).Permanent!.Counters
                .GetValueOrDefault(CounterKinds.PlusOnePlusOne));
    }

    /// <summary>
    /// The characteristic is what it last had, not what it printed (CR 608.2h).
    /// </summary>
    /// <remarks>
    /// The object is gone by the time the sentence asks, so the record has to have kept the
    /// answer — and the answer is last known information, which on a battlefield means after the
    /// layers. A record that kept the printed card and read the number off that would give three
    /// counters here rather than five, on a card that compiles and plays and looks right.
    /// </remarks>
    [Fact]
    public void The_characteristic_asked_of_the_record_is_the_last_one_it_had()
    {
        var thirst = Card(
            "Set Thirst Test",
            "Exile target creature. Put X +1/+1 counters on target creature you control, "
                + "where X is the power of the creature exiled this way.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(thirst);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();

        game.Create(
            alice,
            Card("Set Thirst Anthem", "Creatures you control get +2/+0.", CardType.Enchantment),
            Zone.Battlefield);

        var doomed = game.Create(alice, TestCards.Creature("Set Thirst Doomed", 3, 3), Zone.Battlefield);
        var kept = game.Create(alice, TestCards.Creature("Set Thirst Kept", 1, 1), Zone.Battlefield);

        // Five under the anthem, three on the card. The whole point of the test.
        Assert.Equal(5, Characteristics.Of(game.State, Pool, game.State.GetObject(doomed)).Power);

        game.CastSpell(
            alice,
            TestCards.PutInHand(game, alice, thirst),
            [Target.ToPermanent(doomed), Target.ToPermanent(kept)]);
        Settle(game);

        Assert.Equal(
            5,
            game.State.GetObject(kept).Permanent!.Counters
                .GetValueOrDefault(CounterKinds.PlusOnePlusOne));
    }

    /// <summary>
    /// A subtype in the noun is read, and narrows what the clause is about (CR 205.3).
    /// </summary>
    /// <remarks>
    /// Both answers are asserted, because a filter that ignored the word would draw the card on
    /// every creature and would look exactly like a card that works. The Bear is the control: it
    /// is exiled by the same sentence, so the only thing that can tell the two runs apart is the
    /// subtype.
    /// </remarks>
    [Fact]
    public void A_subtype_in_the_noun_narrows_what_the_clause_asks_about()
    {
        var ruse = Card(
            "Set Ruse Test",
            "Exile target creature you control, then return that card to the battlefield under "
                + "its owner's control. If a Pirate was exiled this way, draw a card.",
            CardType.Instant);

        var compiled = CardCompiler.Compile(ruse);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        // One game per answer. Two casts in one game would put a draw step between them, and a
        // hand count is only evidence while nothing else is filling the hand.
        Assert.Equal(1, Drawn(blinked: "Set Ruse Pirate", subtype: "Pirate", card: ruse));
        Assert.Equal(0, Drawn(blinked: "Set Ruse Bear", subtype: "Bear", card: ruse));

        static int Drawn(string blinked, string subtype, CardDefinition card)
        {
            var (game, alice, _) = InMainPhase();

            var creature = game.Create(
                alice,
                Card(blinked, string.Empty, CardType.Creature, 2, 2, KeywordAbility.None, subtype),
                Zone.Battlefield);

            var held = TestCards.PutInHand(game, alice, card);
            var before = game.State.GetPlayer(alice).Hand.Count;

            game.CastSpell(alice, held, [Target.ToPermanent(creature)]);
            Settle(game);

            // The card cast has left the hand, so anything above that count was drawn.
            return game.State.GetPlayer(alice).Hand.Count - (before - 1);
        }
    }

    /// <summary>
    /// A capitalised word is a subtype unless it is a card type (CR 205.2a, 205.3).
    /// </summary>
    /// <remarks>
    /// The capital is the only thing on the page that marks a subtype, and the first word of a
    /// sentence carries one whether it is a subtype or not. Read the other way round, "Land card
    /// milled this way" would ask for the Land <em>subtype</em> — which no card in the game has,
    /// so the clause would answer no for ever on a card that compiles clean.
    /// </remarks>
    [Fact]
    public void A_capitalised_card_type_is_still_a_card_type()
    {
        var reaper = Card(
            "Set Capital Test",
            "Mill two cards. If at least one Land card is milled this way, you gain 4 life.",
            CardType.Sorcery);

        Assert.True(CardCompiler.Compile(reaper).IsComplete);

        var (game, alice, _) = InMainPhase();
        game.Create(alice, TestCards.Creature("Set Capital Bear", 2, 2), Zone.Library);
        game.Create(alice, Card("Set Capital Waste", string.Empty, CardType.Land), Zone.Library);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, reaper), []);
        Settle(game);

        Assert.Equal(24, game.State.GetPlayer(alice).Life);
    }

    /// <summary>
    /// A sentence asking about the taking is refused, because the taking has not happened.
    /// </summary>
    /// <remarks>
    /// The fail-closed line the whole family is drawn on, one step further out than the verb
    /// list. Which card to take is a decision, and this engine settles decisions <em>after</em>
    /// the resolution — so a later sentence of the same instruction asking what was taken is
    /// asking about an event that does not exist yet, and would answer no for ever.
    /// <para>
    /// Cache Grab prints exactly this and is left unread for it, while Sparring Dummy's second
    /// sentence asks about the mill instead and is answerable. Nothing downstream could tell a
    /// card that answers wrongly from one that answers.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_clause_asking_about_the_deferred_taking_is_left_unread()
    {
        var grab = Card(
            "Set Grab Test",
            "Mill four cards. You may put a permanent card from among the cards milled this way "
                + "into your hand. If you returned a card to your hand this way, you gain 2 life.",
            CardType.Sorcery);

        Assert.False(CardCompiler.Compile(grab).IsComplete);
    }

    /// <summary>
    /// A rider the permission cannot express takes the sentence with it (CR 601.3e, 118.5).
    /// </summary>
    /// <remarks>
    /// "Without paying their mana costs" is not a longer window, it is a different permission, and
    /// the window this grants would let the cards be played only for their costs. A reader that
    /// took the part it understood would print a strictly worse card than the one on the page and
    /// count it as read.
    /// </remarks>
    [Fact]
    public void A_permission_with_a_cost_rider_is_left_unread()
    {
        var harvest = Card(
            "Set Rider Test",
            "Exile the top three cards of your library. Until end of turn, you may cast cards "
                + "exiled this way without paying their mana costs.",
            CardType.Sorcery);

        Assert.False(CardCompiler.Compile(harvest).IsComplete);
    }

    // ---- A shield round a source of your choice (CR 609.7b, 615.8) -----------

    /// <summary>A creature that can ping repeatedly, so one source can deal damage twice.</summary>
    /// <remarks>
    /// The cost is mana rather than a tap because CR 615.8 is a rule about the <em>second</em>
    /// instance of damage from a source, and a source that taps to deal its first cannot deal
    /// one. Nothing in the mechanism cares which cost it is; the test does.
    /// </remarks>
    private static CardDefinition Pinger(string name, ManaColor? colour = null) => new()
    {
        OracleId = "oracle-" + name.ToLowerInvariant().Replace(' ', '-'),
        Name = name,
        OracleText = "{1}: ~ deals 1 damage to any target.",
        CardTypes = CardType.Creature,
        Power = 1,
        Toughness = 1,
        Colors = colour is { } one ? [one] : [],
        ColorIdentity = colour is { } same ? [same] : [],
    };

    /// <summary>
    /// Empties the stack and stops there, leaving the step where it was.
    /// </summary>
    /// <remarks>
    /// <see cref="Settle"/> passes priority once more on an empty stack, which ends the step and
    /// with it any unspent mana (CR 500.4) - so a test that activates an ability twice cannot use
    /// it in between. This stops the moment the stack is clear, which is where the active player
    /// has priority again, and it still asserts the founding invariant that every other settle
    /// here asserts.
    /// </remarks>
    private static void ResolveStack(Game game)
    {
        for (var guard = 0; guard < 40; guard++)
        {
            if (game.State.Choice is not null || game.State.Stack.IsEmpty)
                break;

            if (game.State.Priority.Holder is not { } holder)
                break;

            game.PassPriority(holder);
        }

        Assert.Equal(game.State, GameReducer.Replay(game.Log));
    }

    /// <summary>
    /// CR 615.8: the shield stops one instance from the named source and no more.
    /// </summary>
    /// <remarks>
    /// The whole of what "the next time" means, and the reading that has to be proved rather than
    /// assumed: a Circle of Protection read as an ordinary turn-long shield would make its owner
    /// immune to the chosen source for the rest of the turn, which is a strictly better card than
    /// the one printed and is exactly the direction this family fails in. The second activation
    /// is the control - it must connect, and asserting only that the first was prevented would
    /// pass just as happily on the wrong reading.
    /// </remarks>
    [Fact]
    public void A_shield_on_a_chosen_source_stops_one_instance_and_lets_the_next_through()
    {
        var circle = Card(
            "Chosen Source Test",
            "The next time a source of your choice would deal damage to you this turn, prevent "
                + "that damage.");

        var compiled = CardCompiler.Compile(circle);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var pinger = game.Create(alice, Pinger("Chosen Pinger Test"), Zone.Battlefield);

        // A second object on the board, so there is a question to ask: with one legal
        // source the engine settles the choice itself (CR 118.3), which is what the
        // forced-arm test below is for.
        game.Create(alice, TestCards.Creature("Chosen Bystander Test", 2, 2), Zone.Battlefield);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, circle), targets: null);
        TestCards.PassUntil(game, () => game.State.Choice is not null);

        var choice = game.State.Choice!;
        Assert.Equal(ChoiceKind.ChooseDamageSource, choice.Kind);
        Assert.Contains(choice.Options, o => o.Label == "Chosen Pinger Test");

        game.Choose(alice, [choice.Options.Single(o => o.Label == "Chosen Pinger Test").Id]);
        ResolveStack(game);

        Assert.Single(game.State.Preventions);

        TapLands(game, alice, 1);
        game.ActivateAbility(alice, pinger, "a", [Target.ToPlayer(alice)]);
        ResolveStack(game);

        Assert.Equal(20, game.State.GetPlayer(alice).Life);

        // Spent, not merely inapplicable. The shield has to be gone from state as well as have
        // stopped preventing, or the next turn's cleanup is the only thing removing it.
        Assert.Empty(game.State.Preventions);

        TapLands(game, alice, 1);
        game.ActivateAbility(alice, pinger, "a", [Target.ToPlayer(alice)]);
        ResolveStack(game);

        Assert.Equal(19, game.State.GetPlayer(alice).Life);

        // Two new events in one round - the request and the spending - and both have to survive
        // the round trip, because a log that writes and will not read is a saved game lost.
        Assert.Equal(
            game.State,
            GameReducer.Replay(EventLogSerializer.Read(EventLogSerializer.Write(game.Log))));
    }

    /// <summary>
    /// CR 609.7a: the shield names one object, and every other source is untouched.
    /// </summary>
    /// <remarks>
    /// The failure a count of compiling cards cannot see. A shield built with an empty source
    /// slot means "any source" - it would fog the table from a card that named one creature -
    /// and it would still report itself created, still show up in state, and still prevent the
    /// damage this test aims at the chosen pinger. Only the other pinger tells the two apart.
    /// </remarks>
    [Fact]
    public void A_shield_on_a_chosen_source_ignores_damage_from_a_different_source()
    {
        var circle = Card(
            "One Source Test",
            "The next time a source of your choice would deal damage to you this turn, prevent "
                + "that damage.");

        var (game, alice, _) = InMainPhase();
        var named = game.Create(alice, Pinger("Named Pinger Test"), Zone.Battlefield);
        var other = game.Create(alice, Pinger("Other Pinger Test"), Zone.Battlefield);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, circle), targets: null);
        TestCards.PassUntil(game, () => game.State.Choice is not null);

        var choice = game.State.Choice!;
        game.Choose(alice, [choice.Options.Single(o => o.Label == "Named Pinger Test").Id]);
        ResolveStack(game);

        TapLands(game, alice, 1);
        game.ActivateAbility(alice, other, "a", [Target.ToPlayer(alice)]);
        ResolveStack(game);

        // The unnamed source connects, and the shield is still whole: CR 615.8 spends it on
        // damage it prevented, not on damage that happened to be dealt while it stood.
        Assert.Equal(19, game.State.GetPlayer(alice).Life);
        Assert.Single(game.State.Preventions);

        TapLands(game, alice, 1);
        game.ActivateAbility(alice, named, "a", [Target.ToPlayer(alice)]);
        ResolveStack(game);

        Assert.Equal(19, game.State.GetPlayer(alice).Life);
        Assert.Empty(game.State.Preventions);
    }

    /// <summary>
    /// CR 615.9: a Circle of Protection may only name a source with the property it prints.
    /// </summary>
    /// <remarks>
    /// The five Circles differ from each other in one adjective, and the adjective is the card.
    /// It is asked twice - once to build the menu, once when the damage would happen - and both
    /// are proved here: the white pinger is not on the list, and its damage arrives.
    /// </remarks>
    [Fact]
    public void A_circle_of_protection_offers_only_the_colour_it_names()
    {
        var circle = Card(
            "Red Circle Test",
            "The next time a red source of your choice would deal damage to you this turn, "
                + "prevent that damage.");

        var compiled = CardCompiler.Compile(circle);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var red = game.Create(alice, Pinger("Red Pinger Test", ManaColor.Red), Zone.Battlefield);
        game.Create(alice, Pinger("Second Red Pinger Test", ManaColor.Red), Zone.Battlefield);
        var white = game.Create(
            alice, Pinger("White Pinger Test", ManaColor.White), Zone.Battlefield);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, circle), targets: null);
        TestCards.PassUntil(game, () => game.State.Choice is not null);

        var choice = game.State.Choice!;
        var offered = choice.Options.Select(o => o.Label).ToList();

        // The two red creatures and nothing else. The white pinger is on the battlefield and is
        // not a source this card may name.
        Assert.Equal(2, offered.Count);
        Assert.Contains("Red Pinger Test", offered);
        Assert.Contains("Second Red Pinger Test", offered);
        Assert.DoesNotContain("White Pinger Test", offered);

        game.Choose(alice, [choice.Options.Single(o => o.Label == "Red Pinger Test").Id]);
        ResolveStack(game);

        TapLands(game, alice, 1);
        game.ActivateAbility(alice, white, "a", [Target.ToPlayer(alice)]);
        ResolveStack(game);
        Assert.Equal(19, game.State.GetPlayer(alice).Life);

        TapLands(game, alice, 1);
        game.ActivateAbility(alice, red, "a", [Target.ToPlayer(alice)]);
        ResolveStack(game);
        Assert.Equal(19, game.State.GetPlayer(alice).Life);
    }

    /// <summary>
    /// A source choice with one possible answer is not asked (CR 118.3).
    /// </summary>
    /// <remarks>
    /// The mana colour's forced arm in a second place, and the same rule the optional payment and
    /// the look-and-take state in as many words. What matters is that the shield is still made:
    /// settling a question is carrying it out, not dropping it, and a dropped one here leaves a
    /// card that resolved and did nothing.
    /// </remarks>
    [Fact]
    public void A_source_choice_with_one_answer_is_settled_without_asking()
    {
        var circle = Card(
            "Forced Circle Test",
            "The next time a red source of your choice would deal damage to you this turn, "
                + "prevent that damage.");

        var (game, alice, _) = InMainPhase();
        var red = game.Create(
            alice, Pinger("Only Red Pinger Test", ManaColor.Red), Zone.Battlefield);

        game.Create(alice, Pinger("Ignored White Pinger Test", ManaColor.White), Zone.Battlefield);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, circle), targets: null);
        ResolveStack(game);

        Assert.DoesNotContain(
            game.Log.OfType<ChoiceRequested>(),
            e => e.Choice.Kind == ChoiceKind.ChooseDamageSource);

        Assert.Single(game.State.Preventions);

        TapLands(game, alice, 1);
        game.ActivateAbility(alice, red, "a", [Target.ToPlayer(alice)]);
        ResolveStack(game);

        Assert.Equal(20, game.State.GetPlayer(alice).Life);
    }

    /// <summary>
    /// With nothing the card may name, no shield is made at all (CR 609.7b).
    /// </summary>
    /// <remarks>
    /// The most dangerous case in the whole family, and the one a coverage count scores as a win
    /// either way. A shield whose source slot was left empty because there was nobody to name
    /// prevents damage from <em>every</em> source, so the safe answer to an empty menu is no
    /// effect - and the proof of it is a life total that goes down.
    /// </remarks>
    [Fact]
    public void A_source_choice_with_nothing_to_name_makes_no_shield()
    {
        var circle = Card(
            "Empty Circle Test",
            "The next time a red source of your choice would deal damage to you this turn, "
                + "prevent that damage.");

        var (game, alice, _) = InMainPhase();
        var white = game.Create(
            alice, Pinger("Lone White Pinger Test", ManaColor.White), Zone.Battlefield);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, circle), targets: null);
        ResolveStack(game);

        Assert.Empty(game.State.Preventions);

        TapLands(game, alice, 1);
        game.ActivateAbility(alice, white, "a", [Target.ToPlayer(alice)]);
        ResolveStack(game);

        Assert.Equal(19, game.State.GetPlayer(alice).Life);
    }

    /// <summary>
    /// "Prevent all damage a source of your choice would deal this turn" is not spent (CR 615.3).
    /// </summary>
    /// <remarks>
    /// Pay No Heed against a Circle of Protection: the same chosen source, the same turn, and the
    /// opposite answer to "how many instances". The two wordings are three words apart and both
    /// are printed, so the flag that separates them is read from the sentence rather than implied
    /// - and this is the half that would go unnoticed, because a shield that ends too early looks
    /// like a card working once.
    /// </remarks>
    [Fact]
    public void Preventing_all_damage_from_a_chosen_source_is_not_spent_by_the_first_instance()
    {
        var heed = Card(
            "Chosen All Test", "Prevent all damage a source of your choice would deal this turn.");

        var compiled = CardCompiler.Compile(heed);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var pinger = game.Create(alice, Pinger("Heeded Pinger Test"), Zone.Battlefield);
        game.Create(alice, TestCards.Creature("Heeded Bystander Test", 2, 2), Zone.Battlefield);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, heed), targets: null);
        TestCards.PassUntil(game, () => game.State.Choice is not null);

        var choice = game.State.Choice!;
        game.Choose(alice, [choice.Options.Single(o => o.Label == "Heeded Pinger Test").Id]);
        ResolveStack(game);

        TapLands(game, alice, 1);
        game.ActivateAbility(alice, pinger, "a", [Target.ToPlayer(alice)]);
        ResolveStack(game);
        Assert.Equal(20, game.State.GetPlayer(alice).Life);

        TapLands(game, alice, 1);
        game.ActivateAbility(alice, pinger, "a", [Target.ToPlayer(alice)]);
        ResolveStack(game);

        // Still 20, and the shield is still there: this one runs to the end of the turn.
        Assert.Equal(20, game.State.GetPlayer(alice).Life);
        Assert.Single(game.State.Preventions);
    }

    /// <summary>
    /// The chosen source and a targeted victim are two different slots (CR 609.7b).
    /// </summary>
    /// <remarks>
    /// Charm Peddler and the three "any target" circles: the victim is chosen as the spell is
    /// cast and the source as it resolves, which is two questions about the same effect. They
    /// share one index on <see cref="PreventDescribedDamage"/>, told apart by the flag that says
    /// which slot the target fills, so a sentence naming both has to be refused or read
    /// correctly - never merged.
    /// </remarks>
    [Fact]
    public void A_chosen_source_shield_can_still_be_aimed_at_a_target()
    {
        var peddler = Card(
            "Aimed Circle Test",
            "The next time a source of your choice would deal damage to target creature this "
                + "turn, prevent that damage.");

        var compiled = CardCompiler.Compile(peddler);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var pinger = game.Create(alice, Pinger("Aiming Pinger Test"), Zone.Battlefield);
        var bear = game.Create(
            alice, TestCards.Creature("Aimed Bear Test", 2, 2), Zone.Battlefield);

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, peddler), [Target.ToPermanent(bear)]);

        TestCards.PassUntil(game, () => game.State.Choice is not null);

        var choice = game.State.Choice!;
        game.Choose(alice, [choice.Options.Single(o => o.Label == "Aiming Pinger Test").Id]);
        ResolveStack(game);

        TapLands(game, alice, 1);
        game.ActivateAbility(alice, pinger, "a", [Target.ToPermanent(bear)]);
        ResolveStack(game);
        Assert.Equal(0, game.State.GetObject(bear).Permanent?.DamageMarked);

        // The shield covered one creature and one source. Alice takes the second ping, which is
        // the control for the victim slot: a shield that forgot what it was aimed at would stop
        // this too.
        TapLands(game, alice, 1);
        game.ActivateAbility(alice, pinger, "a", [Target.ToPlayer(alice)]);
        ResolveStack(game);
        Assert.Equal(19, game.State.GetPlayer(alice).Life);
    }

    /// <summary>
    /// "To any target" reaches a player, and shields that player alone (CR 615.1).
    /// </summary>
    /// <remarks>
    /// Found by <c>Every_effect_aimed_at_any_target_answers_for_a_player</c>, which asks of every
    /// effect that can be aimed at "any target" whether anybody has read what it does with a
    /// player. <see cref="PreventDescribedDamage"/> could not be aimed at one at all until the
    /// CR 615.8 reader arrived — the only targeted prevention before it named a <em>source</em>,
    /// which is never a player — so a whole arm became reachable with nothing playing it. The
    /// generalisable half is written down elsewhere in this file and holds here: an effect whose
    /// Resolve returns nothing on an input its own grammar admits is indistinguishable from a
    /// working one, and the card still reports itself complete.
    /// <para>
    /// Alice is the control. A shield that lost which player it was aimed at would cover her too,
    /// and every other assertion here would pass.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_chosen_source_shield_aimed_at_a_player_covers_that_player_alone()
    {
        var circle = Card(
            "Any Target Circle Test",
            "The next time a source of your choice would deal damage to any target this turn, "
                + "prevent that damage.");

        var compiled = CardCompiler.Compile(circle);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var pinger = game.Create(alice, Pinger("Any Target Pinger Test"), Zone.Battlefield);
        game.Create(alice, TestCards.Creature("Any Target Bystander Test", 2, 2), Zone.Battlefield);

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, circle), [Target.ToPlayer(bob)]);

        TestCards.PassUntil(game, () => game.State.Choice is not null);

        var choice = game.State.Choice!;
        game.Choose(alice, [choice.Options.Single(o => o.Label == "Any Target Pinger Test").Id]);
        ResolveStack(game);

        TapLands(game, alice, 1);
        game.ActivateAbility(alice, pinger, "a", [Target.ToPlayer(alice)]);
        ResolveStack(game);

        // The shield was aimed at Bob and does not cover Alice - and it is not spent by damage
        // it did not prevent.
        Assert.Equal(19, game.State.GetPlayer(alice).Life);
        Assert.Single(game.State.Preventions);

        TapLands(game, alice, 1);
        game.ActivateAbility(alice, pinger, "a", [Target.ToPlayer(bob)]);
        ResolveStack(game);

        Assert.Equal(20, game.State.GetPlayer(bob).Life);
        Assert.Empty(game.State.Preventions);

        TapLands(game, alice, 1);
        game.ActivateAbility(alice, pinger, "a", [Target.ToPlayer(bob)]);
        ResolveStack(game);

        Assert.Equal(19, game.State.GetPlayer(bob).Life);
    }

    /// <summary>
    /// A static ability may not say "of your choice" (CR 604.3).
    /// </summary>
    /// <remarks>
    /// The control for the reader, and it asserts both directions of the mistake. A permanent is
    /// not resolving and has no moment at which to ask, so the words have nowhere to be answered;
    /// read as the bare description they leave behind, the same sentence is a permanent that
    /// shields against every red source on the table for as long as it is on the battlefield.
    /// The one-shot with a duration is the same words and is read.
    /// </remarks>
    [Fact]
    public void A_prevention_of_your_choice_is_read_as_a_one_shot_and_refused_as_a_static()
    {
        var spell = Card(
            "Choice Duration Test",
            "Prevent all damage a red source of your choice would deal this turn.");

        Assert.True(CardCompiler.Compile(spell).IsComplete);

        var permanent = Card(
            "Choice Static Test",
            "Prevent all damage a red source of your choice would deal.",
            CardType.Enchantment);

        Assert.False(CardCompiler.Compile(permanent).IsComplete);
    }

    // ---- Station (CR 702.184, 721) -------------------------------------------

    /// <summary>A Spacecraft printed the way the real ones are.</summary>
    private static CardDefinition Spacecraft() => new()
    {
        OracleId = "oracle-test-rammer",
        Name = "Test Rammer",
        OracleText = "Station\n4+ | Flying",
        CardTypes = CardType.Artifact,
        Subtypes = ["Spacecraft"],
        Power = 3,
        Toughness = 4,
    };

    /// <summary>
    /// Stationing charges it by the tapped creature's power, and the threshold does the rest
    /// (CR 702.184a, 721.2b).
    /// </summary>
    /// <remarks>
    /// Below the threshold it is an artifact and nothing else: not a creature, no power, no
    /// flying. That half is the one worth asserting, because a Spacecraft that arrives already
    /// animated is a card that looks like it works.
    /// <para>
    /// The counters come from the power of the creature tapped to pay, which is known when the
    /// cost is paid and gone by the time the ability resolves — so the 4-power creature is
    /// chosen deliberately: it charges past the threshold in one activation and a fixed
    /// "one counter" implementation would still be sitting at 1.
    /// </para>
    /// </remarks>
    [Fact]
    public void Stationing_charges_a_Spacecraft_by_the_tapped_creatures_power()
    {
        var rammer = Spacecraft();
        var compiled = CardCompiler.Compile(rammer);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var ship = game.Create(alice, rammer, Zone.Battlefield);

        var crew = game.Create(
            alice,
            Card("Test Station Hand", string.Empty, CardType.Creature, 4, 4, KeywordAbility.Haste),
            Zone.Battlefield);

        // Before: an artifact, and only that.
        var cold = Characteristics.Of(game.State, Pool, game.State.GetObject(ship));
        Assert.False(cold.CardTypes.HasFlag(CardType.Creature));
        Assert.False(cold.Keywords.HasFlag(KeywordAbility.Flying));

        game.ActivateAbility(alice, ship, "station", [], [crew]);
        Settle(game);

        Assert.Equal(
            4,
            game.State.GetObject(ship).Permanent!.Counters.GetValueOrDefault(CounterKinds.Charge));

        var hot = Characteristics.Of(game.State, Pool, game.State.GetObject(ship));
        Assert.True(hot.CardTypes.HasFlag(CardType.Creature));
        Assert.True(hot.Keywords.HasFlag(KeywordAbility.Flying));
        Assert.Equal(3, hot.Power);
        Assert.Equal(4, hot.Toughness);

        // The creature that paid is tapped (CR 702.184a).
        Assert.True(game.State.GetObject(crew).Permanent!.IsTapped);
    }
    // ---- Conjoined statics on an attached subject (CR 301.5f, 303.4m, 613.1d) --

    /// <summary>An Aura on one line of enchant plus one line of statics.</summary>
    private static CardDefinition AttachedAura(string name, string statics) => Card(
        name,
        "Enchant creature" + (char)10 + statics,
        CardType.Enchantment,
        null,
        null,
        KeywordAbility.None,
        "Aura");

    /// <summary>An Equipment with one line of statics and an equip cost.</summary>
    private static CardDefinition AttachedEquipment(string name, string statics) => Card(
        name,
        statics + (char)10 + "Equip {2}",
        CardType.Artifact,
        null,
        null,
        KeywordAbility.None,
        "Equipment");

    /// <summary>
    /// Both halves of a conjoined static line apply, not just the one the pattern could name.
    /// </summary>
    /// <remarks>
    /// The bonus and the untap restriction are two different layers on two different rules
    /// (CR 613.4c and CR 502.3), and until the fold existed the line carrying both was refused
    /// outright while each half alone was read. The failure worth guarding is the *other* one:
    /// a fold that took the clause it recognised and dropped the rest would pump the creature
    /// and quietly let it untap, which is a strictly better card than the one printed and
    /// nothing downstream would notice.
    /// <para>
    /// The bear beside it is the control that says the untap step ran at all. Without it, an
    /// engine that simply stopped untapping would pass.
    /// </para>
    /// </remarks>
    [Fact]
    public void Both_halves_of_a_conjoined_attached_static_apply()
    {
        var cuffs = AttachedEquipment(
            "Fold Cuffs Test",
            "Equipped creature gets +2/+2 and doesn't untap during its controller's untap step.");

        var compiled = CardCompiler.Compile(cuffs);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var wearer = game.Create(alice, TestCards.Creature("Fold Wearer Test", 2, 2), Zone.Battlefield);
        var ordinary = game.Create(alice, TestCards.Creature("Fold Bystander Test", 2, 2), Zone.Battlefield);
        var gear = game.Create(alice, cuffs, Zone.Battlefield);

        game.Attach(gear, wearer);
        Settle(game);

        // The clause the old pattern could read.
        Assert.Equal(4, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(wearer)));

        game.Tap(wearer);
        game.Tap(ordinary);
        Settle(game);

        TestCards.PassToTurn(game, 3);

        // The clause it could not: still held down, while the creature beside it woke up.
        Assert.True(game.State.GetObject(wearer).Permanent?.IsTapped);
        Assert.False(game.State.GetObject(ordinary).Permanent?.IsTapped);
    }

    /// <summary>
    /// A comma list of clauses folds, and the creature type it adds is real to the rest of the
    /// engine (CR 205.1a, 613.1d).
    /// </summary>
    /// <remarks>
    /// Reading the subtype back off the computed characteristics would only prove the string was
    /// stored. The lord is what proves it is a *type*: "Birds you control get +1/+1" is written
    /// by a different reader that knows nothing about Auras, and it has to find this Bear because
    /// layer 4 ran before layer 6 (CR 613.1d, 613.1f). A subtype that nothing matches compiles
    /// perfectly and does nothing, which is the failure this file exists to catch.
    /// <para>
    /// The card types are asserted *unchanged*. "Is a Bird in addition to its other types" says
    /// nothing about card types, and a reader that added the type a subtype implies would animate
    /// whatever the Aura was on.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_comma_list_folds_and_the_creature_type_it_adds_is_real()
    {
        var wings = AttachedAura(
            "Fold Wings Test",
            "Enchanted creature gets +2/+2, has flying, and is a Bird in addition to its other types.");

        var compiled = CardCompiler.Compile(wings);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var bear = game.Create(alice, TestCards.Creature("Fold Sky Bear Test", 2, 2), Zone.Battlefield);
        var aura = game.Create(alice, wings, Zone.Battlefield);
        game.Attach(aura, bear);
        Settle(game);

        var worn = Characteristics.Of(game.State, Pool, game.State.GetObject(bear));
        Assert.Equal(4, worn.Power);
        Assert.True(worn.Keywords.HasFlag(KeywordAbility.Flying));
        Assert.Contains("Bird", worn.Subtypes);

        // A Bear is not an artifact or an enchantment because its Aura named a creature type.
        Assert.False(worn.CardTypes.HasFlag(CardType.Artifact));
        Assert.False(worn.CardTypes.HasFlag(CardType.Enchantment));

        // The lord finds it, which is what makes the added type a type rather than a string.
        game.Create(
            alice,
            Card("Fold Bird Lord Test", "Birds you control get +1/+1.", CardType.Enchantment),
            Zone.Battlefield);

        Settle(game);
        Assert.Equal(5, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(bear)));
    }

    /// <summary>
    /// A keyword list is read whole rather than split at its commas (CR 613.1f).
    /// </summary>
    /// <remarks>
    /// The fold splits on commas as well as on "and", so "flying, first strike, trample, and
    /// haste" is exactly the shape it could shred: four fragments, three of which are not
    /// sentences. It survives because the longest join is offered first, and the whole list is a
    /// clause the keyword reader already understands. Asserting all four keywords is the point —
    /// a fold that kept only the first would leave a card with flying and nothing else, and its
    /// line would still be reported as read.
    /// </remarks>
    [Fact]
    public void A_keyword_list_inside_a_folded_line_is_not_split_at_its_commas()
    {
        var mask = AttachedAura(
            "Fold Mask Test",
            "Enchanted creature has base power and toughness 9/9 "
                + "and has flying, first strike, trample, and haste.");

        var compiled = CardCompiler.Compile(mask);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var bear = game.Create(alice, TestCards.Creature("Fold Masked Bear Test", 2, 2), Zone.Battlefield);
        var aura = game.Create(alice, mask, Zone.Battlefield);
        game.Attach(aura, bear);
        Settle(game);

        var worn = Characteristics.Of(game.State, Pool, game.State.GetObject(bear));
        Assert.Equal(9, worn.Power);
        Assert.Equal(9, worn.Toughness);
        Assert.True(worn.Keywords.HasFlag(KeywordAbility.Flying));
        Assert.True(worn.Keywords.HasFlag(KeywordAbility.FirstStrike));
        Assert.True(worn.Keywords.HasFlag(KeywordAbility.Trample));
        Assert.True(worn.Keywords.HasFlag(KeywordAbility.Haste));
    }

    /// <summary>
    /// A clause the compiler cannot read leaves the whole line unread, bonus included.
    /// </summary>
    /// <remarks>
    /// The clause is invented — no rule says "is beguiled" — so this Aura says one thing the
    /// engine knows and one nothing ever will. It used to say "is goaded", and implementing the
    /// Impetus cycle turned that half real; a fail-closed fixture written in words a future
    /// mechanic can claim is a test that a feature quietly turns green, which has happened here
    /// twice before. The fold refuses the line rather than keeping the half it understood: a
    /// creature that got +2/+2 without the rest is a better card than the one printed, and a
    /// card that is merely unread is refused by the deck gate where a card that is quietly
    /// wrong is not.
    /// <para>
    /// Playing it is the half that earns the test. <c>IsComplete</c> alone would still pass if
    /// the refused clause had already been added to the card's statics on the way out.
    /// </para>
    /// </remarks>
    [Fact]
    public void An_unreadable_clause_leaves_the_whole_conjoined_line_unread()
    {
        var taunt = AttachedAura(
            "Fold Taunt Test",
            "Enchanted creature gets +2/+2 and is beguiled.");

        var compiled = CardCompiler.Compile(taunt);
        Assert.False(compiled.IsComplete);

        var (game, alice, _) = InMainPhase();
        var bear = game.Create(alice, TestCards.Creature("Fold Taunted Bear Test", 2, 2), Zone.Battlefield);
        var aura = game.Create(alice, taunt, Zone.Battlefield);
        game.Attach(aura, bear);
        Settle(game);

        // No half-card: the bonus is not applied on its own.
        Assert.Equal(2, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(bear)));
    }

    /// <summary>
    /// The capital letter decides: a subtype is added as a subtype, a card type as a card type.
    /// </summary>
    /// <remarks>
    /// Both spellings are printed on real cards and they mean different things (CR 205.1a,
    /// 205.3). Reading every capitalised word as a creature type is the mistake that made "for
    /// each Equipment you control" count zero while compiling perfectly; reading the lowercase
    /// one as a subtype would give a creature the *subtype* "artifact" and leave artifact removal
    /// unable to touch it.
    /// </remarks>
    [Fact]
    public void A_type_addition_tells_a_subtype_from_a_card_type_by_its_capital()
    {
        var (game, alice, _) = InMainPhase();

        var spurs = AttachedEquipment(
            "Fold Spurs Test", "Equipped creature is a Knight in addition to its other types.");

        Assert.True(CardCompiler.Compile(spurs).IsComplete);

        var rider = game.Create(alice, TestCards.Creature("Fold Rider Test", 2, 2), Zone.Battlefield);
        var gear = game.Create(alice, spurs, Zone.Battlefield);
        game.Attach(gear, rider);
        Settle(game);

        var mounted = Characteristics.Of(game.State, Pool, game.State.GetObject(rider));
        Assert.Contains("Knight", mounted.Subtypes);
        Assert.False(mounted.CardTypes.HasFlag(CardType.Artifact));

        // The lowercase word is a card type, and it does not become a subtype.
        var plating = AttachedAura(
            "Fold Plating Test",
            "Enchanted creature gets +1/+1 and is an artifact in addition to its other types.");

        Assert.True(CardCompiler.Compile(plating).IsComplete);

        var bear = game.Create(alice, TestCards.Creature("Fold Plated Bear Test", 2, 2), Zone.Battlefield);
        var aura = game.Create(alice, plating, Zone.Battlefield);
        game.Attach(aura, bear);
        Settle(game);

        var plated = Characteristics.Of(game.State, Pool, game.State.GetObject(bear));
        Assert.Equal(3, plated.Power);
        Assert.True(plated.CardTypes.HasFlag(CardType.Artifact));
        Assert.DoesNotContain("artifact", plated.Subtypes);
    }

    /// <summary>
    /// The wordings the fold sits behind still read, one by one.
    /// </summary>
    /// <remarks>
    /// A new reader can claim a clause an existing one handled and disable it silently while the
    /// coverage total still rises, because it gains more than its neighbour loses. That has
    /// happened here before and cost sixteen corpus lines. The fold is placed after every other
    /// matcher precisely so it cannot, and this is the assertion that says so: each neighbouring
    /// wording is checked for being read on every run, not inferred from a net figure.
    /// </remarks>
    [Fact]
    public void The_wordings_the_conjunction_fold_sits_behind_still_read()
    {
        string[] neighbours =
        [
            "Enchanted creature gets +2/+2 and has flying.",
            "Enchanted creature gets +2/+2 and can't attack or block.",
            "Enchanted creature doesn't untap during its controller's untap step.",
            "Enchanted creature can't be blocked by creatures with flying.",
            "Enchanted creature has base power and toughness 9/9.",
            "Enchanted creature has flying, first strike, trample, and haste.",
            "Enchanted creature gets +1/+1 for each Plains you control.",
            "Enchanted creature is a creature with base power and toughness 5/4 "
                + "in addition to its other types.",
        ];

        for (var i = 0; i < neighbours.Length; i++)
        {
            var compiled = CardCompiler.Compile(
                AttachedAura("Fold Control Test " + i, neighbours[i]));

            Assert.True(
                compiled.IsComplete,
                neighbours[i] + " -> " + string.Join(" | ", compiled.Unhandled));
        }
    }

    // ---- Licids: a creature that becomes its own Aura (CR 205.1b, 613.1d) ----

    /// <summary>The printed line, once, so every Licid test is playing the real card.</summary>
    /// <remarks>
    /// All twelve write it identically apart from the two costs and the Aura's own rider, which is
    /// why the rider is the parameter: the ability under test is the same ability on every one of
    /// them, and a test per card would be twelve copies of one template.
    /// </remarks>
    private static CardDefinition Licid(string name, string rider) => Card(
        name,
        "{1}{W}, {T}: ~ loses this ability and becomes an Aura enchantment with enchant "
            + "creature. Attach it to target creature. You may pay {W} to end this effect.\n"
            + rider,
        CardType.Creature,
        1,
        1,
        subtypes: "Licid");

    /// <summary>Mana enough for one activation, from lands that are not summoning sick.</summary>
    private static void TapPlains(Game game, Guid player, int count)
    {
        for (var i = 0; i < count; i++)
        {
            var land = game.Create(player, TestCards.BasicLand("Plains"), Zone.Battlefield);
            game.ActivateAbility(player, land, "mana");
        }
    }

    /// <summary>Turn three, main phase: the Licid has been around since the turn began.</summary>
    /// <remarks>
    /// CR 302.6. The {T} in the activation cost is what needs it, and a Licid made on the turn it
    /// is activated cannot pay — which would make every assertion below vacuous.
    /// </remarks>
    private static void SettleIn(Game game)
    {
        TestCards.PassToTurn(game, 3);
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.PrecombatMain);
    }

    [Fact]
    public void A_licid_becomes_an_aura_attaches_and_stops_being_a_creature()
    {
        // Quickening Licid's own wording. Three things happen at once and each is a different
        // layer: the types are replaced in layer 4 (CR 205.1b), the permanent attaches, and the
        // Aura's rider starts granting from layer 6 to the creature it is now on.
        var licid = Licid("Licid Test", "Enchanted creature has first strike.");

        var (game, alice, _) = InMainPhase();
        var wearer = game.Create(alice, licid, Zone.Battlefield);
        var bear = game.Create(alice, TestCards.Creature("Licid Host", 2, 2), Zone.Battlefield);
        SettleIn(game);

        Assert.True(Characteristics.IsCreature(game.State, Pool, game.State.GetObject(wearer)));

        TapPlains(game, alice, 2);
        game.ActivateAbility(alice, wearer, "a", [Target.ToPermanent(bear)]);
        Settle(game);

        var now = Characteristics.Of(game.State, Pool, game.State.GetObject(wearer));

        // A Licid that kept its creature type while enchanting would be able to attack and block
        // as well, which is a strictly better card than the printed one.
        Assert.False(now.CardTypes.HasFlag(CardType.Creature));
        Assert.True(now.CardTypes.HasFlag(CardType.Enchantment));
        Assert.Contains("Aura", now.Subtypes);
        Assert.DoesNotContain("Licid", now.Subtypes);

        Assert.Equal(bear, game.State.GetObject(wearer).Permanent!.AttachedTo);
        Assert.True(Characteristics.HasKeyword(
            game.State, Pool, game.State.GetObject(bear), KeywordAbility.FirstStrike));
    }

    [Fact]
    public void A_licid_that_has_become_an_aura_has_lost_the_ability_that_made_it_one()
    {
        // "~ loses this ability": an Aura already on one creature may not be activated to go and
        // enchant a second. Refused before any cost is paid (CR 602.5b).
        var licid = Licid("Licid Loss Test", "Enchanted creature has first strike.");

        var (game, alice, _) = InMainPhase();
        var wearer = game.Create(alice, licid, Zone.Battlefield);
        var first = game.Create(
            alice, TestCards.Creature("Licid Loss Host", 2, 2), Zone.Battlefield);
        var second = game.Create(
            alice, TestCards.Creature("Licid Loss Other", 2, 2), Zone.Battlefield);
        SettleIn(game);

        TapPlains(game, alice, 2);
        game.ActivateAbility(alice, wearer, "a", [Target.ToPermanent(first)]);
        Settle(game);

        TapPlains(game, alice, 2);
        var why = Assert.Throws<InvalidOperationException>(
            () => game.ActivateAbility(alice, wearer, "a", [Target.ToPermanent(second)]));

        Assert.Contains("602.5b", why.Message, StringComparison.Ordinal);
        Assert.Equal(first, game.State.GetObject(wearer).Permanent!.AttachedTo);
    }

    [Fact]
    public void A_licid_cannot_pay_to_end_an_effect_it_has_not_started()
    {
        // The other direction, and the half that makes the pair a switch rather than two
        // unrelated abilities: a Licid that is still a creature has nothing to come back from.
        var licid = Licid("Licid Early Test", "Enchanted creature has first strike.");

        var (game, alice, _) = InMainPhase();
        var wearer = game.Create(alice, licid, Zone.Battlefield);
        SettleIn(game);
        TapPlains(game, alice, 1);

        var why = Assert.Throws<InvalidOperationException>(
            () => game.ActivateAbility(alice, wearer, "a1"));

        Assert.Contains("602.5b", why.Message, StringComparison.Ordinal);
    }

    [Fact]
    public void Paying_the_licids_price_turns_it_back_into_a_creature_and_takes_the_aura_off()
    {
        // "You may pay {W} to end this effect." The half that makes the card reversible, and the
        // half a one-way reading would have quietly dropped.
        var licid = Licid("Licid Return Test", "Enchanted creature has first strike.");

        var (game, alice, _) = InMainPhase();
        var wearer = game.Create(alice, licid, Zone.Battlefield);
        var bear = game.Create(
            alice, TestCards.Creature("Licid Return Host", 2, 2), Zone.Battlefield);
        SettleIn(game);

        TapPlains(game, alice, 2);
        game.ActivateAbility(alice, wearer, "a", [Target.ToPermanent(bear)]);
        Settle(game);

        TapPlains(game, alice, 1);
        game.ActivateAbility(alice, wearer, "a1");
        Settle(game);

        Assert.True(Characteristics.IsCreature(game.State, Pool, game.State.GetObject(wearer)));

        // Unattached with it. A Licid that came back as a creature while still sitting on its host
        // would go on granting first strike from an Aura ability it no longer has any business
        // applying — the one direction this may not fail in.
        Assert.Null(game.State.GetObject(wearer).Permanent!.AttachedTo);
        Assert.False(Characteristics.HasKeyword(
            game.State, Pool, game.State.GetObject(bear), KeywordAbility.FirstStrike));

        // Still tapped: the {T} was spent on the way out and coming back does not refund it, so
        // the ability it has just got back cannot be paid for until it untaps.
        Assert.True(game.State.GetObject(wearer).Permanent!.IsTapped);

        TestCards.PassToTurn(game, 5);
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.PrecombatMain);

        // And then it can go again, which is what "loses this ability" giving the ability back
        // means: the refusal above was the effect, not a card that had run out of ability.
        TapPlains(game, alice, 2);
        game.ActivateAbility(alice, wearer, "a", [Target.ToPermanent(bear)]);
        Settle(game);

        Assert.Equal(bear, game.State.GetObject(wearer).Permanent!.AttachedTo);
    }

    [Fact]
    public void A_licid_enchanting_a_creature_dies_with_it()
    {
        // CR 704.5m, reached through the computed subtypes rather than the printed ones: the card
        // still says Creature — Licid, and a printed-subtype reading left it on the battlefield
        // holding nothing, which is a card strictly better than the printed one.
        var licid = Licid("Licid Death Test", "Enchanted creature has first strike.");

        var (game, alice, _) = InMainPhase();
        var wearer = game.Create(alice, licid, Zone.Battlefield);
        var bear = game.Create(
            alice, TestCards.Creature("Licid Death Host", 2, 2), Zone.Battlefield);
        SettleIn(game);

        TapPlains(game, alice, 2);
        game.ActivateAbility(alice, wearer, "a", [Target.ToPermanent(bear)]);
        Settle(game);

        game.Move(bear, Zone.Graveyard, MoveCause.Destroy);
        Settle(game);

        Assert.DoesNotContain(
            game.State.Battlefield.Select(game.State.GetObject),
            o => o.Card.Name == "Licid Death Test");
    }

    [Fact]
    public void A_licids_rider_can_be_an_ability_of_its_own_rather_than_a_keyword()
    {
        // Nurturing Licid: the Aura half is an activated ability that acts on what it is attached
        // to, so the card compiles to three abilities and the third only means anything once the
        // first has run. Proof that "loses this ability" takes one ability and not all of them.
        var licid = Licid("Licid Rider Test", "{G}: Regenerate enchanted creature.");

        var (game, alice, _) = InMainPhase();
        var wearer = game.Create(alice, licid, Zone.Battlefield);
        var bear = game.Create(
            alice, TestCards.Creature("Licid Rider Host", 1, 1), Zone.Battlefield);
        SettleIn(game);

        TapPlains(game, alice, 2);
        game.ActivateAbility(alice, wearer, "a", [Target.ToPermanent(bear)]);
        Settle(game);

        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, forest, "mana");
        game.ActivateAbility(alice, wearer, "a2");
        Settle(game);

        game.MarkDamage(bear, 3);
        Settle(game);

        // Regenerated rather than destroyed: the shield was up, so lethal damage did not kill it
        // (CR 701.15a).
        Assert.Contains(
            game.State.Battlefield.Select(game.State.GetObject),
            o => o.Card.Name == "Licid Rider Host");
    }

    // ---- Prevention shields that have no duration (CR 615.1, 611.2c) ---------

    /// <summary>
    /// Tajic: "Prevent all noncombat damage that would be dealt to other creatures you control."
    /// </summary>
    /// <remarks>
    /// A static prevention over a <em>described set</em> rather than over the permanent itself,
    /// which is the shape the compiler refused until now: the reader knew "~", "enchanted
    /// creature" and "equipped creature" and nothing else, so every line naming a group stayed
    /// unread.
    /// <para>
    /// Three words in that sentence each do work, and each is a way to compile a strictly better
    /// card than the printed one. <strong>"Noncombat"</strong> — the blocked bear still dies to
    /// three points of combat damage. <strong>"You control"</strong> — Bob's brute is not
    /// shielded by Alice's enchantment. <strong>"Other"</strong> — Tajic is not covered by his
    /// own sentence, and no filter over card types can say so, because what is excluded is an
    /// object rather than a kind of card.
    /// </para>
    /// <para>
    /// The last assertion is the one the whole design turns on: with Tajic dead, the next bolt
    /// kills the creature the shield had been covering. A described prevention with no duration
    /// would have gone on shielding it for the rest of the turn — the card would look
    /// implemented, play correctly all game, and be wrong exactly once.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_group_shield_leaves_out_its_own_permanent_and_stops_when_that_permanent_does()
    {
        var tajic = Card(
            "Tajic Shield Test",
            "Prevent all noncombat damage that would be dealt to other creatures you control.",
            CardType.Creature,
            3,
            2);

        var bolt = Card("Tajic Bolt Test", "~ deals 3 damage to any target.");

        Assert.True(
            CardCompiler.Compile(tajic).IsComplete,
            string.Join(" | ", CardCompiler.Compile(tajic).Unhandled));

        var (game, alice, bob) = InMainPhase();
        var captain = game.Create(alice, tajic, Zone.Battlefield);
        var blocker = game.Create(
            alice, TestCards.Creature("Tajic Blocker Test", 2, 2), Zone.Battlefield);
        var spare = game.Create(
            alice, TestCards.Creature("Tajic Spare Test", 2, 2), Zone.Battlefield);
        var brute = game.Create(bob, TestCards.Creature("Tajic Brute Test", 3, 3), Zone.Battlefield);

        // Combat first, because "noncombat" is the word most easily lost: a shield that dropped
        // it would keep this blocker alive and pass every other assertion below.
        PassTo(game, 2, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            bob,
            new Dictionary<ObjectId, AttackTarget> { [brute] = AttackTarget.Player(alice) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);
        game.DeclareBlockers(
            alice,
            new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [brute] = [blocker] });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Settle(game);

        Assert.DoesNotContain(blocker, game.State.Battlefield);

        // Noncombat damage to another creature Alice controls is prevented outright.
        PassToMainPhaseOfTurn(game, 3);
        game.CastSpell(alice, TestCards.PutInHand(game, alice, bolt), [Target.ToPermanent(spare)]);
        Settle(game);

        Assert.Contains(spare, game.State.Battlefield);
        Assert.Equal(0, game.State.GetObject(spare).Permanent?.DamageMarked);

        // Bob's creature is nobody's "you control".
        game.CastSpell(alice, TestCards.PutInHand(game, alice, bolt), [Target.ToPermanent(brute)]);
        Settle(game);

        Assert.DoesNotContain(brute, game.State.Battlefield);

        // "Other": the shield covers everything Alice controls except the permanent saying it.
        game.CastSpell(alice, TestCards.PutInHand(game, alice, bolt), [Target.ToPermanent(captain)]);
        Settle(game);

        Assert.DoesNotContain(captain, game.State.Battlefield);

        // And with it gone the shield is gone, on the same turn it was working.
        game.CastSpell(alice, TestCards.PutInHand(game, alice, bolt), [Target.ToPermanent(spare)]);
        Settle(game);

        Assert.DoesNotContain(spare, game.State.Battlefield);
    }

    /// <summary>
    /// Personal Sanctuary: "During your turn, prevent all damage that would be dealt to you."
    /// </summary>
    /// <remarks>
    /// Two things at once. A shield around a <em>player</em>, which is a different field from
    /// the one that holds permanents and a different event to watch — damage to a player is life
    /// loss (CR 120.3c) and never passes the permanent arm at all. And a condition on a static
    /// ability (CR 604.3), which a replacement effect gets for free: it asks its question when
    /// the event would happen, which is exactly when the condition has to hold.
    /// <para>
    /// The opponent's turn is the control. Read without its condition this is a card that stops
    /// every burn spell in the game, and it would compile just as cleanly.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_conditional_shield_around_a_player_holds_only_while_its_condition_does()
    {
        var sanctuary = Card(
            "Personal Sanctuary Test",
            "During your turn, prevent all damage that would be dealt to you.",
            CardType.Enchantment);

        var bolt = Card("Sanctuary Bolt Test", "~ deals 3 damage to any target.");

        Assert.True(
            CardCompiler.Compile(sanctuary).IsComplete,
            string.Join(" | ", CardCompiler.Compile(sanctuary).Unhandled));

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, sanctuary, Zone.Battlefield);
        var bear = game.Create(
            alice, TestCards.Creature("Sanctuary Bear Test", 2, 2), Zone.Battlefield);
        SettleIn(game);

        // Alice's own turn: the damage never arrives.
        game.CastSpell(alice, TestCards.PutInHand(game, alice, bolt), [Target.ToPlayer(alice)]);
        Settle(game);

        Assert.Equal(20, game.State.GetPlayer(alice).Life);

        // A player is not a permanent, and the sentence names one of them. Her creature is not
        // covered by a shield that says "to you".
        game.CastSpell(alice, TestCards.PutInHand(game, alice, bolt), [Target.ToPermanent(bear)]);
        Settle(game);

        Assert.DoesNotContain(bear, game.State.Battlefield);

        // Bob's turn, same enchantment, same target: the condition no longer holds.
        PassToMainPhaseOfTurn(game, 4);
        game.CastSpell(bob, TestCards.PutInHand(game, bob, bolt), [Target.ToPlayer(alice)]);
        Settle(game);

        Assert.Equal(17, game.State.GetPlayer(alice).Life);
    }

    /// <summary>
    /// Statecraft: "Prevent all combat damage that would be dealt to and dealt by creatures you
    /// control."
    /// </summary>
    /// <remarks>
    /// One noun in both slots, which is two shields and not one. A single shield with both slots
    /// filled would be their conjunction — only the damage a creature you control dealt to
    /// another creature you control — and the card would do almost nothing while reporting
    /// itself complete.
    /// <para>
    /// The unblocked attacker is the control that keeps the two shields honest: the sentence is
    /// about creatures, so Alice's life total is not covered by either half.
    /// </para>
    /// </remarks>
    [Fact]
    public void One_noun_in_both_directions_is_two_shields_rather_than_their_conjunction()
    {
        var statecraft = Card(
            "Statecraft Test",
            "Prevent all combat damage that would be dealt to and dealt by creatures you control.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(statecraft);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.Equal(2, compiled.Replacements.Count);

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, statecraft, Zone.Battlefield);
        var bear = game.Create(
            alice, TestCards.Creature("Statecraft Bear Test", 2, 2), Zone.Battlefield);
        var brute = game.Create(
            bob, TestCards.Creature("Statecraft Brute Test", 3, 3), Zone.Battlefield);
        var raider = game.Create(
            bob, TestCards.Creature("Statecraft Raider Test", 3, 3), Zone.Battlefield);

        PassTo(game, 2, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            bob,
            new Dictionary<ObjectId, AttackTarget>
            {
                [brute] = AttackTarget.Player(alice),
                [raider] = AttackTarget.Player(alice),
            });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);
        game.DeclareBlockers(
            alice,
            new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [brute] = [bear] });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Settle(game);

        // Damage reaching Alice's creature is prevented, and so is the damage it deals.
        Assert.Equal(0, game.State.GetObject(bear).Permanent?.DamageMarked);
        Assert.Equal(0, game.State.GetObject(brute).Permanent?.DamageMarked);

        // The unblocked attacker still connects: neither shield says anything about a player.
        Assert.Equal(17, game.State.GetPlayer(alice).Life);

        // And neither says anything about noncombat damage.
        PassToMainPhaseOfTurn(game, 3);
        game.CastSpell(
            alice,
            TestCards.PutInHand(game, alice, Card("Statecraft Bolt Test", "~ deals 3 damage to any target.")),
            [Target.ToPermanent(bear)]);

        Settle(game);
        Assert.DoesNotContain(bear, game.State.Battlefield);
    }

    /// <summary>
    /// Kor Haven: "Prevent all combat damage that would be dealt by target attacking creature
    /// this turn."
    /// </summary>
    /// <remarks>
    /// The half of prevention that names <em>one object</em> as the damage's source (CR 609.7a).
    /// It is a field on the shield rather than a filter, and the second attacker is why: a
    /// reading that turned the chosen creature into a description of its kind would fog the
    /// whole attack, because both of these creatures are attacking creatures. Alice takes three
    /// and not six, and not none.
    /// </remarks>
    [Fact]
    public void A_shield_aimed_at_one_dealer_stops_that_creature_and_no_other()
    {
        var haven = Card(
            "Kor Haven Test",
            "{T}: Prevent all combat damage that would be dealt by target attacking creature this turn.",
            CardType.Land);

        Assert.True(
            CardCompiler.Compile(haven).IsComplete,
            string.Join(" | ", CardCompiler.Compile(haven).Unhandled));

        var (game, alice, bob) = InMainPhase();
        var sanctuary = game.Create(alice, haven, Zone.Battlefield);
        var first = game.Create(bob, TestCards.Creature("Haven Brute Test", 3, 3), Zone.Battlefield);
        var second = game.Create(bob, TestCards.Creature("Haven Raider Test", 3, 3), Zone.Battlefield);

        PassTo(game, 2, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            bob,
            new Dictionary<ObjectId, AttackTarget>
            {
                [first] = AttackTarget.Player(alice),
                [second] = AttackTarget.Player(alice),
            });

        // The active player receives priority first once attackers are declared (CR 117.3c), so
        // Alice's answer comes after Bob has passed on his own attack.
        if (game.State.Priority.Holder == bob)
            game.PassPriority(bob);

        game.ActivateAbility(alice, sanctuary, "a", [Target.ToPermanent(first)]);
        Settle(game);

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Settle(game);

        Assert.Equal(17, game.State.GetPlayer(alice).Life);
    }

    /// <summary>
    /// Goblin Furrier: "Prevent all damage that ~ would deal to snow creatures."
    /// </summary>
    /// <remarks>
    /// The active voice, where the dealer is the sentence's subject and the two halves swap
    /// places. Both slots are filled at once here — the source is this permanent, the victims
    /// answer a filter — which is the combination the old reader could not express in either
    /// direction.
    /// <para>
    /// Damage <em>to</em> the Furrier is the control. A shield read as covering its own permanent
    /// rather than describing what it deals would make this creature very hard to remove in
    /// combat, and the card would still compile.
    /// </para>
    /// </remarks>
    [Fact]
    public void An_active_voice_shield_names_the_source_and_describes_the_victims()
    {
        var furrier = Card(
            "Goblin Furrier Test",
            "Prevent all damage that ~ would deal to Goblins.",
            CardType.Creature,
            2,
            5,
            KeywordAbility.None,
            "Goblin");

        Assert.True(
            CardCompiler.Compile(furrier).IsComplete,
            string.Join(" | ", CardCompiler.Compile(furrier).Unhandled));

        var (game, alice, bob) = InMainPhase();
        var wolf = game.Create(alice, furrier, Zone.Battlefield);
        var goblin = game.Create(
            bob,
            Card("Furrier Goblin Test", string.Empty, CardType.Creature, 3, 3, KeywordAbility.None, "Goblin"),
            Zone.Battlefield);

        var bear = game.Create(bob, TestCards.Creature("Furrier Bear Test", 3, 3), Zone.Battlefield);

        PassTo(game, 2, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            bob,
            new Dictionary<ObjectId, AttackTarget> { [goblin] = AttackTarget.Player(alice) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);
        game.DeclareBlockers(
            alice,
            new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [goblin] = [wolf] });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Settle(game);

        // Nothing reached the Goblin, and the Furrier took its three all the same.
        Assert.Equal(0, game.State.GetObject(goblin).Permanent?.DamageMarked);
        Assert.Equal(3, game.State.GetObject(wolf).Permanent?.DamageMarked);

        // A creature that is not a Goblin is not described by the sentence.
        PassTo(game, 4, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            bob,
            new Dictionary<ObjectId, AttackTarget> { [bear] = AttackTarget.Player(alice) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);
        game.DeclareBlockers(
            alice,
            new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [bear] = [wolf] });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Settle(game);

        Assert.Equal(2, game.State.GetObject(bear).Permanent?.DamageMarked);
    }

    /// <summary>
    /// The duration is what decides which reader owns the sentence, and neither may take both.
    /// </summary>
    /// <remarks>
    /// The control for this whole section. A single pattern loose enough to claim both wordings
    /// would pass every test above and fail this one, and both directions of that mistake are
    /// bad in the same way:
    /// <list type="bullet">
    /// <item>
    /// "…this turn" on a permanent compiled as a static ability is a shield that never comes
    /// down — the fog on Isochron Scepter would fog every turn of the game.
    /// </item>
    /// <item>
    /// A line with no duration on an instant compiled as a described prevention is a shield the
    /// engine keeps until the turn ends, put up by a card that is already in a graveyard.
    /// </item>
    /// </list>
    /// Both are left unread instead, which is what <c>Unhandled</c> is for.
    /// </remarks>
    [Fact]
    public void The_no_duration_wording_is_a_static_and_the_this_turn_wording_is_not()
    {
        var permanent = CardCompiler.Compile(Card(
            "Duration Permanent Test",
            "Prevent all combat damage that would be dealt to ~ this turn.",
            CardType.Creature,
            2,
            2));

        Assert.False(permanent.IsComplete);
        Assert.Empty(permanent.Replacements);

        var spell = CardCompiler.Compile(Card(
            "Duration Spell Test",
            "Prevent all damage that would be dealt to creatures you control."));

        Assert.False(spell.IsComplete);
        Assert.Empty(spell.Replacements);
        Assert.Null(spell.Spell);

        // And the two readings that *are* right still are: the same sentence with its duration
        // on an instant, and without one on a permanent.
        var fog = CardCompiler.Compile(Card(
            "Duration Fog Test",
            "Prevent all damage that would be dealt to creatures you control this turn."));

        Assert.True(fog.IsComplete, string.Join(" | ", fog.Unhandled));

        var wall = CardCompiler.Compile(Card(
            "Duration Wall Test",
            "Prevent all combat damage that would be dealt to ~.",
            CardType.Creature,
            0,
            4));

        Assert.True(wall.IsComplete, string.Join(" | ", wall.Unhandled));
        Assert.Single(wall.Replacements);
    }

    // ---- Round thirteen, sweep B: ranks 51-100 of the work queue --------------

    /// <summary>
    /// "Enchant red or green creature" restricts the Aura to the two colours it names (CR 303.4a).
    /// </summary>
    /// <remarks>
    /// The enchant line is a targeting restriction and nothing else, so getting it wrong does not
    /// look like a bug - the Aura still attaches and still does what it says, just to creatures it
    /// may not legally go on. The refusal is the whole assertion.
    /// <para>
    /// The pattern read "red or green" and then had nowhere to put "creature", so the line matched
    /// nothing and the whole card stayed unread. The target grammar beside it has known this
    /// phrase for a long time; only the enchant matcher could not reach it.
    /// </para>
    /// </remarks>
    [Fact]
    public void Enchant_naming_two_colours_refuses_a_creature_of_neither()
    {
        var ice = Card(
            "Encase Test",
            "Enchant red or green creature" + "\n"
                + "Enchanted creature doesn't untap during its controller's untap step.",
            CardType.Enchantment,
            subtypes: "Aura");

        var compiled = CardCompiler.Compile(ice);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.Single(compiled.Spell!.Targets);

        var (game, alice, bob) = InMainPhase();
        var drake = game.Create(bob, Coloured("Encase Drake Test", ManaColor.Blue), Zone.Battlefield);
        var goblin = game.Create(bob, Coloured("Encase Goblin Test", ManaColor.Red), Zone.Battlefield);

        var wrong = TestCards.PutInHand(game, alice, ice);
        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, wrong, [Target.ToPermanent(drake)]));

        game.CastSpell(alice, wrong, [Target.ToPermanent(goblin)]);
        Settle(game);

        // Found by name rather than by the id it had in hand: a spell that resolves into a
        // permanent is a new object (CR 400.7).
        var attached = game.State.Battlefield.Single(
            id => game.State.GetObject(id).Card.Name == "Encase Test");

        Assert.Equal(goblin, game.State.GetObject(attached).Permanent!.AttachedTo);
    }

    /// <summary>
    /// One sentence holding a permanent down and silencing it is two continuous effects
    /// (CR 613.1f, 602.5c).
    /// </summary>
    /// <remarks>
    /// Encrust prints both halves in one line, and the untap reader stopped at the untap step -
    /// so the line matched nothing at all and the Aura did neither. Reading only the first half
    /// would have been worse than that: a card that taps a creature down and leaves its abilities
    /// switched on is a different, weaker card that no test on the untap half would notice.
    /// </remarks>
    [Fact]
    public void An_aura_that_stops_the_untap_can_also_stop_the_activations()
    {
        var encrust = Card(
            "Encrust Test",
            "Enchant artifact or creature" + "\n"
                + "Enchanted permanent doesn't untap during its controller's untap step and its "
                + "activated abilities can't be activated.",
            CardType.Enchantment,
            subtypes: "Aura");

        var compiled = CardCompiler.Compile(encrust);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.Equal(2, compiled.Statics.Count);

        var engine = Card("Encrust Engine Test", "{T}: Draw a card.", CardType.Creature, 1, 1);
        var ability = CardCompiler.Compile(engine).Activated.Single().Id;

        var (game, alice, _) = InMainPhase();
        var machine = game.Create(alice, engine, Zone.Battlefield);

        // Past the summoning sickness (CR 302.6), so the refusal below is the Aura's doing and
        // not some other reason the ability was never available.
        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber == 3 && game.State.CurrentStep == TurnStep.PrecombatMain);

        game.ActivateAbility(alice, machine, ability);
        Settle(game);

        Assert.True(game.State.GetObject(machine).Permanent!.IsTapped);

        var aura = game.Create(alice, encrust, Zone.Battlefield);
        game.Attach(aura, machine);
        Settle(game);

        var held = Characteristics.Of(game.State, Pool, game.State.GetObject(machine));
        Assert.True(held.DoesNotUntap);
        Assert.True(held.AbilitiesCantBeActivated);

        Assert.Throws<InvalidOperationException>(
            () => game.ActivateAbility(alice, machine, ability));

        // And the holding half really holds: the creature tapped for that activation is still
        // tapped after its controller's untap step has come round again.
        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber == 5 && game.State.CurrentStep == TurnStep.PrecombatMain);

        Assert.True(game.State.GetObject(machine).Permanent!.IsTapped);
    }

    /// <summary>
    /// "Cumulative upkeep {W} or {U}" is a hybrid symbol written the long way (CR 107.4e, 702.24a).
    /// </summary>
    /// <remarks>
    /// The equivalence is exact rather than convenient. The cost is charged once per age counter
    /// and each of those payments is independently either colour, which is precisely what
    /// repeating one {W/U} means - so folding the two symbols into one is the same cost, not a
    /// cheaper one. Both colours are played through the game here because a fold that quietly
    /// picked the first colour would still compile, still charge one mana, and still pass any
    /// test that only ever paid with white.
    /// </remarks>
    [Fact]
    public void Cumulative_upkeep_of_two_colours_is_paid_with_either_of_them()
    {
        var keeper = Card(
            "Owl Keeper Test",
            "Cumulative upkeep {W} or {U}",
            CardType.Creature,
            2,
            2);

        var compiled = CardCompiler.Compile(keeper);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var charged = Assert.IsType<MayPay>(compiled.Triggers.Single().Effects[1]);
        var symbol = Assert.Single(charged.Cost.Symbols);
        Assert.True(symbol.IsHybrid);
        Assert.Contains(ManaColor.White, symbol.Colors);
        Assert.Contains(ManaColor.Blue, symbol.Colors);

        foreach (var basic in (string[])["Plains", "Island"])
        {
            var (game, alice, _) = InMainPhase();
            game.Create(alice, keeper, Zone.Battlefield);
            var land = game.Create(alice, TestCards.BasicLand(basic), Zone.Battlefield);

            TestCards.PassUntil(
                game,
                () => game.State.TurnNumber == 3 && game.State.CurrentStep == TurnStep.Upkeep);

            game.ActivateAbility(alice, land, "mana");
            Settle(game);

            for (var guard = 0; guard < 10 && game.State.Choice is { } choice; guard++)
                game.Choose(choice.PlayerId, [choice.Options[0].Id]);

            Settle(game);

            // Paid with one colour or the other, so it is alive and carrying its first age
            // counter rather than sitting in the graveyard.
            var alive = game.State.Battlefield.Single(
                id => game.State.GetObject(id).Card.Name == "Owl Keeper Test");

            Assert.Equal(
                1,
                game.State.GetObject(alive).Permanent?.Counters.GetValueOrDefault("age", 0));
        }
    }

    /// <summary>
    /// "Your maximum hand size is reduced by three" moves the number rather than removing it
    /// (CR 402.2).
    /// </summary>
    /// <remarks>
    /// The engine could say "no maximum hand size" and nothing in between, because the limit was a
    /// bool: a card that shrinks it had nowhere to land. It is deliberately not a continuous
    /// effect - CR 613 orders changes to <em>objects</em>, and this one is about a seat - so it
    /// travels the way a cost reducer does, as a fact about a permanent that the cleanup step
    /// looks up and subtracts.
    /// </remarks>
    [Fact]
    public void A_reduced_maximum_hand_size_is_what_its_controller_discards_to()
    {
        var eater = Card(
            "Thought Eater Test",
            "Your maximum hand size is reduced by three.",
            CardType.Creature,
            1,
            1);

        var compiled = CardCompiler.Compile(eater);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, eater, Zone.Battlefield);

        for (var i = 0; i < 12; i++)
        {
            TestCards.PutInHand(game, alice, TestCards.Creature($"Eater Alice {i} Test", 1, 1));
            TestCards.PutInHand(game, bob, TestCards.Creature($"Eater Bob {i} Test", 1, 1));
        }

        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber == 2 && game.State.CurrentStep == TurnStep.PrecombatMain);

        // Seven less three, and not seven: a reduction that failed to reach the cleanup step
        // would leave this at 7 with everything else about the card looking correct.
        Assert.Equal(4, game.State.GetPlayer(alice).Hand.Count);

        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber == 3 && game.State.CurrentStep == TurnStep.PrecombatMain);

        // Bob's own limit is untouched - the sentence says "your".
        Assert.Equal(7, game.State.GetPlayer(bob).Hand.Count);
    }

    /// <summary>
    /// "Each opponent's maximum hand size is reduced by two" points the same rule the other way.
    /// </summary>
    /// <remarks>
    /// Which players a reduction reaches is decided by who controls the permanent, not by the
    /// reduction naming them - so the two directions are one mechanism read twice. Asserting the
    /// controller's own hand is untouched is the half that catches a scope applied to everybody.
    /// </remarks>
    [Fact]
    public void A_reduction_aimed_at_opponents_leaves_its_controllers_own_limit_alone()
    {
        var miser = Card(
            "Gnat Miser Test",
            "Each opponent's maximum hand size is reduced by two.",
            CardType.Creature,
            1,
            1);

        var compiled = CardCompiler.Compile(miser);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, miser, Zone.Battlefield);

        for (var i = 0; i < 12; i++)
        {
            TestCards.PutInHand(game, alice, TestCards.Creature($"Miser Alice {i} Test", 1, 1));
            TestCards.PutInHand(game, bob, TestCards.Creature($"Miser Bob {i} Test", 1, 1));
        }

        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber == 2 && game.State.CurrentStep == TurnStep.PrecombatMain);

        Assert.Equal(7, game.State.GetPlayer(alice).Hand.Count);

        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber == 3 && game.State.CurrentStep == TurnStep.PrecombatMain);

        Assert.Equal(5, game.State.GetPlayer(bob).Hand.Count);
    }

    /// <summary>
    /// "Defending player gets a poison counter" as a sentence, not as a keyword (CR 122.1, 704.5c).
    /// </summary>
    /// <remarks>
    /// The poison effect had been in the engine since toxic was read, and toxic was the only thing
    /// that could produce one: the keyword assembles its ability inside the compiler instead of
    /// going through a sentence, so every card printing the instruction outright was unread. The
    /// sentence reaches spells, activated abilities and triggers at once, which is why fixing one
    /// three-card row moved fifteen cards.
    /// </remarks>
    [Fact]
    public void An_unblocked_attacker_can_poison_the_player_it_got_through_to()
    {
        var cobra = Card(
            "Crypt Cobra Test",
            "Whenever ~ attacks and isn't blocked, defending player gets a poison counter.",
            CardType.Creature,
            2,
            2);

        var compiled = CardCompiler.Compile(cobra);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var snake = game.Create(alice, cobra, Zone.Battlefield);
        var wall = game.Create(bob, TestCards.Creature("Cobra Wall Test", 0, 4), Zone.Battlefield);

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [snake] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);
        game.DeclareBlockers(
            bob,
            new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [snake] = [wall] });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Settle(game);

        // Blocked, so nothing got through and the trigger did not fire. Asserting this first is
        // what separates the template from "whenever ~ attacks".
        Assert.Equal(0, game.State.GetPlayer(bob).PoisonCounters);

        PassTo(game, 5, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [snake] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Settle(game);

        Assert.Equal(1, game.State.GetPlayer(bob).PoisonCounters);
    }

    /// <summary>
    /// "Equipped creature gets +10/+10 and loses flying" takes an ability away in layer 6
    /// (CR 613.1f).
    /// </summary>
    /// <remarks>
    /// The removal sits in the same slot of the same sentence as the grant beside it, so it is the
    /// grant with the bits cleared instead of set. The line was unread whole, and the tempting
    /// half-reading is the dangerous one: a Colossus Hammer that gives +10/+10 and leaves the
    /// flying on is a strictly better card than the one printed, which is the failure the compiler
    /// refuses by leaving a line it cannot fully read alone.
    /// </remarks>
    [Fact]
    public void Equipment_that_pumps_and_takes_flying_away_does_both()
    {
        var hammer = Card(
            "Colossus Hammer Test",
            "Equipped creature gets +10/+10 and loses flying." + "\n" + "Equip {8}",
            CardType.Artifact,
            subtypes: "Equipment");

        var compiled = CardCompiler.Compile(hammer);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var drake = game.Create(
            alice,
            TestCards.WithKeyword("Hammer Drake Test", KeywordAbility.Flying, 2, 2),
            Zone.Battlefield);

        var before = Characteristics.Of(game.State, Pool, game.State.GetObject(drake));
        Assert.True(before.Has(KeywordAbility.Flying));

        var equipment = game.Create(alice, hammer, Zone.Battlefield);
        game.Attach(equipment, drake);
        Settle(game);

        var after = Characteristics.Of(game.State, Pool, game.State.GetObject(drake));
        Assert.Equal(12, after.Power);
        Assert.Equal(12, after.Toughness);
        Assert.False(after.Has(KeywordAbility.Flying));
    }

    /// <summary>
    /// "Target player shuffles their graveyard into their library" (CR 701.23).
    /// </summary>
    /// <remarks>
    /// The untargeted form - "shuffle your graveyard into your library" after a search - has been
    /// read for a long time, and this is the same instruction pointed at somebody else. Kept as a
    /// matcher of its own rather than widened into that one, because the untargeted pattern is
    /// anchored on "shuffle" as the sentence's first word and would sooner drop the target than
    /// refuse it: a spell that quietly shuffled the caster's own graveyard is worse than one
    /// left unread.
    /// </remarks>
    [Fact]
    public void A_targeted_graveyard_shuffle_empties_the_graveyard_it_was_aimed_at()
    {
        var reminisce = Card(
            "Reminisce Test",
            "Target player shuffles their graveyard into their library.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(reminisce);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();

        for (var i = 0; i < 3; i++)
        {
            game.Create(bob, TestCards.Creature($"Reminisce Bob {i} Test", 1, 1), Zone.Graveyard);
            game.Create(alice, TestCards.Creature($"Reminisce Alice {i} Test", 1, 1), Zone.Graveyard);
        }

        var bobLibrary = game.State.GetPlayer(bob).Library.Count;
        var aliceGraveyard = game.State.GetPlayer(alice).Graveyard.Count;

        var card = TestCards.PutInHand(game, alice, reminisce);
        game.CastSpell(alice, card, [Target.ToPlayer(bob)]);
        Settle(game);

        Assert.Empty(game.State.GetPlayer(bob).Graveyard);
        Assert.Equal(bobLibrary + 3, game.State.GetPlayer(bob).Library.Count);

        // Alice's own graveyard is untouched apart from the spell that just resolved into it,
        // which is what "target player" buys over the untargeted sentence.
        Assert.Equal(aliceGraveyard + 1, game.State.GetPlayer(alice).Graveyard.Count);
    }

    /// <summary>
    /// "Discard all the cards in your hand, then draw that many cards" is one effect (CR 608.2).
    /// </summary>
    /// <remarks>
    /// Not a discard followed by a draw. The instructions of an ability resolve one at a time
    /// against the state the one before it left, so by the time a draw could ask how big the hand
    /// was, the hand is empty and "that many" is zero - a card that compiled into two effects
    /// would discard everything and draw nothing while looking perfectly well read. The count is
    /// taken once, before either half happens.
    /// </remarks>
    [Fact]
    public void Discarding_a_whole_hand_draws_back_as_many_cards_as_it_held()
    {
        var winds = Card(
            "Tolarian Winds Test",
            "Discard all the cards in your hand, then draw that many cards.");

        var compiled = CardCompiler.Compile(winds);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, winds);
        game.CastSpell(alice, card, []);

        // Taken with the spell already on the stack, so this is the hand the effect will see.
        // The names are read now rather than afterwards: a card that changes zone becomes a new
        // object (CR 400.7), and the ids held here name nothing once the discard has happened.
        var thrown = game.State.GetPlayer(alice).Hand.ToList();
        var names = thrown.Select(id => game.State.GetObject(id).Card.Name).ToList();
        var library = game.State.GetPlayer(alice).Library.Count;

        Assert.NotEmpty(thrown);
        Settle(game);

        var now = game.State.GetPlayer(alice).Hand;

        Assert.Equal(thrown.Count, now.Count);
        Assert.Equal(library - thrown.Count, game.State.GetPlayer(alice).Library.Count);

        // Every card is a different card: the hand was emptied and refilled, not left alone.
        Assert.Empty(now.Intersect(thrown));

        var graveyard = game.State.GetPlayer(alice).Graveyard
            .Select(id => game.State.GetObject(id).Card.Name)
            .ToList();

        Assert.All(names, name => Assert.Contains(name, graveyard));
    }

    // ---- Round fourteen: seven queue rows, five causes ------------------------

    /// <summary>
    /// "Each creature you control can block an additional creature each combat" (CR 509.1a).
    /// </summary>
    /// <remarks>
    /// The single-creature form has been read for a long time, and the reason the group form was
    /// not is worth keeping: its reader knows three subjects — "~", enchanted, equipped — and
    /// nothing else, so a line naming a group fell straight through. The allowance now comes off
    /// the same mass-static grammar the lords use, which is what makes the second half of this
    /// work possible: "each creature you control with a +1/+1 counter on it" is a filter that
    /// vocabulary already had, and no reader had to learn it twice.
    /// <para>
    /// The assertion about Alice's creature is the one that matters. A group reader that ignored
    /// the ownership clause would pass every line about the enchantment's own side and quietly
    /// hand the allowance to the whole table — the failure this compiler has recorded before,
    /// where the card reads as complete and applies to half the board.
    /// </para>
    /// </remarks>
    [Fact]
    public void An_extra_block_can_be_given_to_a_whole_side_of_the_board()
    {
        var sands = Card(
            "Test Brave the Sands",
            "Each creature you control can block an additional creature each combat.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(sands);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var wall = game.Create(bob, TestCards.Creature("Test Sands Wall", 1, 6), Zone.Battlefield);
        var theirs = game.Create(
            alice, TestCards.Creature("Test Sands Interloper", 1, 6), Zone.Battlefield);

        Assert.Equal(
            0, Characteristics.Of(game.State, Pool, game.State.GetObject(wall)).ExtraBlocks);

        game.Create(bob, sands, Zone.Battlefield);

        Assert.Equal(
            1, Characteristics.Of(game.State, Pool, game.State.GetObject(wall)).ExtraBlocks);

        // Bob's enchantment, so Alice's creature is not one of "each creature you control".
        Assert.Equal(
            0, Characteristics.Of(game.State, Pool, game.State.GetObject(theirs)).ExtraBlocks);

        var first = game.Create(alice, TestCards.Creature("Test Sands Raider", 2, 2), Zone.Battlefield);
        var second = game.Create(alice, TestCards.Creature("Test Sands Rider", 2, 2), Zone.Battlefield);

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget>
            {
                [first] = AttackTarget.Player(bob),
                [second] = AttackTarget.Player(bob),
            });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);
        game.DeclareBlockers(
            bob,
            new Dictionary<ObjectId, IReadOnlyList<ObjectId>>
            {
                [first] = [wall],
                [second] = [wall],
            });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);

        Assert.Equal(20, game.State.GetPlayer(bob).Life);
        Assert.Equal(4, game.State.GetObject(wall).Permanent!.DamageMarked);

        Settle(game);
    }

    /// <summary>
    /// The group's filter is the lords' filter, so a counter narrows who may block twice.
    /// </summary>
    /// <remarks>
    /// Cenn's Tactician's wording, and the whole argument for putting the allowance in the mass
    /// static reader rather than widening the single-creature one: nothing here was written for
    /// counters. A creature that picks one up joins the group and one that never had one does
    /// not, because the filter is asked of the permanent every time the characteristics are
    /// computed.
    /// </remarks>
    [Fact]
    public void The_group_that_gets_the_extra_block_can_be_narrowed_by_a_counter()
    {
        var tactician = Card(
            "Test Cenn's Tactician",
            "Each creature you control with a +1/+1 counter on it can block an additional "
                + "creature each combat.",
            CardType.Creature,
            1,
            1);

        var compiled = CardCompiler.Compile(tactician);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        game.Create(alice, tactician, Zone.Battlefield);

        var marked = game.Create(alice, TestCards.Creature("Test Tactician Marked", 2, 2), Zone.Battlefield);
        var plain = game.Create(alice, TestCards.Creature("Test Tactician Plain", 2, 2), Zone.Battlefield);

        Assert.Equal(
            0, Characteristics.Of(game.State, Pool, game.State.GetObject(marked)).ExtraBlocks);

        game.AddCounters(marked, CounterKinds.PlusOnePlusOne, 1);

        Assert.Equal(
            1, Characteristics.Of(game.State, Pool, game.State.GetObject(marked)).ExtraBlocks);

        Assert.Equal(
            0, Characteristics.Of(game.State, Pool, game.State.GetObject(plain)).ExtraBlocks);
    }

    /// <summary>
    /// A number word the compiler cannot count leaves the line unread rather than meaning one.
    /// </summary>
    /// <remarks>
    /// The fail-open this project keeps finding, in the one reader that still had it: the number
    /// in "can block an additional seven creatures each combat" went through a helper that
    /// answers 1 to any word it does not know, so Hundred-Handed One's "ninety-nine" would have
    /// compiled into a permission to block one more creature — a complete card, a legal card, and
    /// not the printed one. The cardinal is checked before it is read, so the seven is read and
    /// the ninety-nine is refused.
    /// </remarks>
    [Fact]
    public void A_number_of_extra_blocks_is_read_only_when_the_word_can_be_counted()
    {
        var spider = Card(
            "Test Watcher in the Web",
            "~ can block an additional seven creatures each combat.",
            CardType.Creature,
            2,
            5);

        Assert.True(CardCompiler.Compile(spider).IsComplete);

        var (game, alice, _) = InMainPhase();
        var web = game.Create(alice, spider, Zone.Battlefield);

        Assert.Equal(
            7, Characteristics.Of(game.State, Pool, game.State.GetObject(web)).ExtraBlocks);

        var hundred = Card(
            "Test Hundred-Handed Guard",
            "~ can block an additional ninety-nine creatures each combat.",
            CardType.Creature,
            3,
            5);

        // Unread rather than read as one. The refusal is the point: a card blocking one more is
        // a different card from one blocking ninety-nine more.
        Assert.False(CardCompiler.Compile(hundred).IsComplete);
    }

    /// <summary>
    /// "Target permanent becomes white until end of turn" (CR 105.2, 613.1e).
    /// </summary>
    /// <remarks>
    /// Becoming a colour <em>sets</em> the colours rather than adding to them, which is the half
    /// worth asserting: the Elf under this ability stops being green. Reading it as an addition
    /// would leave every "protection from green" and every "green creatures get +1/+1" still
    /// applying to it, on a card that says otherwise.
    /// </remarks>
    [Fact]
    public void A_permanent_told_to_become_a_colour_stops_being_the_colour_it_was()
    {
        var kestrel = Card(
            "Test Cloudchaser Kestrel",
            "{W}: Target permanent becomes white until end of turn.",
            CardType.Creature,
            2,
            2);

        var compiled = CardCompiler.Compile(kestrel);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var bird = game.Create(alice, kestrel, Zone.Battlefield);
        var elf = game.Create(alice, Coloured("Test Kestrel Elf", ManaColor.Green), Zone.Battlefield);

        Assert.Contains(
            ManaColor.Green,
            Characteristics.Of(game.State, Pool, game.State.GetObject(elf)).Colors);

        game.AddMana(alice, ManaColor.White);
        game.ActivateAbility(
            alice, bird, compiled.Activated.Single().Id, [Target.ToPermanent(elf)]);

        Settle(game);

        var painted = Characteristics.Of(game.State, Pool, game.State.GetObject(elf));

        Assert.Contains(ManaColor.White, painted.Colors);
        Assert.DoesNotContain(ManaColor.Green, painted.Colors);

        // CR 514.2: the effect ends in the cleanup step, and the Elf is green again.
        TestCards.PassUntil(game, () => game.State.TurnNumber >= 2);

        Assert.Contains(
            ManaColor.Green,
            Characteristics.Of(game.State, Pool, game.State.GetObject(elf)).Colors);
    }

    /// <summary>
    /// A recolouring with no stated duration is refused rather than made to expire.
    /// </summary>
    /// <remarks>
    /// The lace cycle — "Target spell or permanent becomes red" — changes a colour for good. The
    /// effect this template builds ends in the cleanup step, so reading those words here would
    /// give a card that undoes itself while counting towards coverage. Same refusal the animation
    /// reader makes, and made for the same reason.
    /// </remarks>
    [Fact]
    public void A_recolouring_without_a_duration_is_left_unread()
    {
        var lace = Card("Test Purelace", "Target permanent becomes white.");

        Assert.False(CardCompiler.Compile(lace).IsComplete);
    }

    /// <summary>
    /// "Double the number of +1/+1 counters on ~" (CR 121.3).
    /// </summary>
    /// <remarks>
    /// Doubling is putting on as many as are already there, so it needs no event of its own — and
    /// the count has to be taken when the ability resolves rather than when the card compiles,
    /// which is what the second activation here proves: the same ability doubles a different
    /// number the second time.
    /// <para>
    /// The permanent with no counters is the guard against the obvious wrong reading. "Double"
    /// on nothing is nothing; a reader that put one on would look right on every card that
    /// already had some.
    /// </para>
    /// </remarks>
    [Fact]
    public void Doubling_counters_adds_as_many_as_are_already_there()
    {
        // A 1/1 rather than the printed 0/0: Solarion is kept alive by the sunburst counters it
        // enters with, and a 0/0 with none of them is put into a graveyard by a state-based
        // action before it can be tapped for anything (CR 704.5f).
        var hydra = Card(
            "Test Solarion",
            "{T}: Double the number of +1/+1 counters on ~.",
            CardType.Creature,
            1,
            1);

        var compiled = CardCompiler.Compile(hydra);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var sun = game.Create(alice, hydra, Zone.Battlefield);

        // CR 302.6: the tap is part of the cost, so nothing can be doubled until the creature has
        // been under its controller's command since the turn began.
        PassToMainPhaseOfTurn(game, 3);

        // Nothing to double yet, and doubling nothing is nothing.
        game.ActivateAbility(alice, sun, compiled.Activated.Single().Id);
        Settle(game);

        Assert.Equal(
            0,
            game.State.GetObject(sun).Permanent!.Counters
                .GetValueOrDefault(CounterKinds.PlusOnePlusOne));

        game.AddCounters(sun, CounterKinds.PlusOnePlusOne, 3);
        PassToMainPhaseOfTurn(game, 5);

        game.ActivateAbility(alice, sun, compiled.Activated.Single().Id);
        Settle(game);

        Assert.Equal(
            6,
            game.State.GetObject(sun).Permanent!.Counters[CounterKinds.PlusOnePlusOne]);
        Assert.Equal(
            7, Characteristics.Of(game.State, Pool, game.State.GetObject(sun)).Power);
    }

    /// <summary>
    /// "Double the number of each kind of counter on target permanent" (CR 121.3).
    /// </summary>
    /// <remarks>
    /// Not the named form with the noun left out. This one doubles every kind the permanent is
    /// carrying, which is a set the compiler cannot know — it is a fact of the board when the
    /// ability resolves — and that is why the two wordings are told apart in the reader rather
    /// than folded together with a nullable name.
    /// </remarks>
    [Fact]
    public void Doubling_every_kind_of_counter_doubles_each_of_them()
    {
        var bairn = Card(
            "Test Gilder Bairn",
            "{2}: Double the number of each kind of counter on target permanent.",
            CardType.Creature,
            1,
            3);

        var compiled = CardCompiler.Compile(bairn);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var ouphe = game.Create(alice, bairn, Zone.Battlefield);
        var relic = game.Create(alice, TestCards.Creature("Test Bairn Relic", 1, 1), Zone.Battlefield);

        game.AddCounters(relic, CounterKinds.PlusOnePlusOne, 2);
        game.AddCounters(relic, "charge", 3);

        game.AddMana(alice, null, 2);
        game.ActivateAbility(
            alice, ouphe, compiled.Activated.Single().Id, [Target.ToPermanent(relic)]);

        Settle(game);

        var counters = game.State.GetObject(relic).Permanent!.Counters;

        Assert.Equal(4, counters[CounterKinds.PlusOnePlusOne]);
        Assert.Equal(6, counters["charge"]);
    }

    /// <summary>
    /// "~ deals 4 damage to target creature and 2 damage to that creature's controller."
    /// </summary>
    /// <remarks>
    /// The player is decided by the first half of the same sentence and is not a target: nothing
    /// about the words chooses them, so hexproof has nothing to say and the board must not offer
    /// them as a second pick. The spell is cast with one target here, which is the assertion the
    /// call itself makes.
    /// <para>
    /// It is damage rather than life loss, and the difference is not cosmetic — it is dealt by
    /// the source, so it can be prevented, and it is what lifelink and every "whenever this deals
    /// damage" trigger watch. A card of this shape compiled as life loss would be wrong in all
    /// three ways while reading as complete.
    /// </para>
    /// </remarks>
    [Fact]
    public void Damage_to_a_creature_can_carry_damage_to_whoever_controls_it()
    {
        var outrage = Card(
            "Test Chandra's Outrage",
            "~ deals 4 damage to target creature and 2 damage to that creature's controller.");

        var compiled = CardCompiler.Compile(outrage);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var bear = game.Create(bob, TestCards.Creature("Test Outrage Bear", 5, 5), Zone.Battlefield);
        var card = TestCards.PutInHand(game, alice, outrage);

        game.CastSpell(alice, card, [Target.ToPermanent(bear)]);
        Settle(game);

        Assert.Equal(4, game.State.GetObject(bear).Permanent!.DamageMarked);
        Assert.Equal(18, game.State.GetPlayer(bob).Life);

        // Alice is not "that creature's controller", and nothing chose her.
        Assert.Equal(20, game.State.GetPlayer(alice).Life);
    }

    /// <summary>
    /// The creature can be dead by the time its controller is damaged, and still names them.
    /// </summary>
    /// <remarks>
    /// The awkward half, and the reason this reuses the ownership reader the life and draw
    /// clauses already share. Effects in one resolution each see what the previous left behind
    /// (CR 608.2c), so a creature killed by the first half of the sentence is a card in a
    /// graveyard under a new id by the time the second half runs (CR 400.7) — and a lookup on the
    /// battlefield finds nothing. Whose it was is still a fact about the game, so the controller
    /// is followed back through the log.
    /// </remarks>
    [Fact]
    public void A_creature_killed_by_the_first_half_still_names_its_controller()
    {
        var volley = Card(
            "Test First Volley",
            "~ deals 1 damage to target creature and 1 damage to that creature's controller.");

        Assert.True(CardCompiler.Compile(volley).IsComplete);

        var (game, alice, bob) = InMainPhase();
        var mite = game.Create(bob, TestCards.Creature("Test Volley Mite", 1, 1), Zone.Battlefield);
        var card = TestCards.PutInHand(game, alice, volley);

        game.CastSpell(alice, card, [Target.ToPermanent(mite)]);
        Settle(game);

        Assert.Empty(game.State.Battlefield);
        Assert.Equal(19, game.State.GetPlayer(bob).Life);
    }

    /// <summary>
    /// "When ~ enters, target opponent exiles a card from their hand" (CR 609.4).
    /// </summary>
    /// <remarks>
    /// Two rows of the work queue that look nothing alike — this one and "target player exiles a
    /// card from their graveyard" — and one cause between them: a player other than the
    /// controller is told to pick one of their own cards, which is the choice-on-resolution
    /// machinery a sacrifice already uses, pointed at a zone it had never been pointed at.
    /// <para>
    /// The assertion about who is asked is the rule. The opponent chooses, not the caster, and a
    /// hand is hidden — what keeps it hidden is that a pending choice's options are projected
    /// only to the player being asked, and the player being asked here is the one whose hand it
    /// is.
    /// </para>
    /// <para>
    /// And it is an exile, not a discard: the card never reaches a graveyard, so nothing watching
    /// for a discard fires and madness never gets its chance to apply.
    /// </para>
    /// </remarks>
    [Fact]
    public void An_opponent_exiles_a_card_of_their_own_choosing_from_their_hand()
    {
        var agent = Card(
            "Test Unscrupulous Agent",
            "When ~ enters, target opponent exiles a card from their hand.",
            CardType.Creature,
            2,
            2);

        var compiled = CardCompiler.Compile(agent);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        TestCards.PutInHand(game, bob, TestCards.Creature("Test Agent Hostage", 3, 3));

        var held = game.State.GetPlayer(bob).Hand.Count;
        var card = TestCards.PutInHand(game, alice, agent);

        // The creature spell targets nothing; its trigger does (CR 603.3d), and the target is
        // chosen when the trigger goes on the stack rather than when the card is cast.
        game.CastSpell(alice, card, []);

        for (var guard = 0; guard < 40; guard++)
        {
            if (game.State.Choice is { Kind: ChoiceKind.ChoosePermanent })
                break;

            if (game.State.Choice is { } pending)
            {
                game.Choose(
                    pending.PlayerId,
                    [.. pending.Options.Take(Math.Max(pending.MinPicks, 1)).Select(o => o.Id)]);
                continue;
            }

            if (game.State.Priority.Holder is not { } holder)
                break;

            game.PassPriority(holder);
        }

        var asked = game.State.Choice!;
        Assert.Equal(bob, asked.PlayerId);

        game.Choose(bob, [asked.Options[0].Id]);
        Settle(game);

        Assert.Equal(held - 1, game.State.GetPlayer(bob).Hand.Count);
        Assert.Single(game.State.Exile);

        // Exiled, not discarded: nothing of Bob's reached a graveyard.
        Assert.Empty(game.State.GetPlayer(bob).Graveyard);
    }

    /// <summary>
    /// The same sentence asked of a graveyard (CR 609.4).
    /// </summary>
    /// <remarks>
    /// The other row, and the reason to write both: one reader, two zones, and the zone is the
    /// only thing that differs. A graveyard is public where a hand is not, which changes nothing
    /// about who is asked — the card says "target player exiles", and the player exiling is the
    /// one who chooses.
    /// </remarks>
    [Fact]
    public void A_player_exiles_a_card_of_their_own_choosing_from_their_graveyard()
    {
        var claws = Card(
            "Test Scrabbling Claws",
            "{T}: Target player exiles a card from their graveyard.",
            CardType.Artifact);

        var compiled = CardCompiler.Compile(claws);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var tool = game.Create(alice, claws, Zone.Battlefield);
        game.Create(bob, TestCards.Creature("Test Claws Corpse", 2, 2), Zone.Graveyard);

        game.ActivateAbility(
            alice, tool, compiled.Activated.Single().Id, [Target.ToPlayer(bob)]);

        TestCards.PassUntil(
            game,
            () => game.State.Choice is { Kind: ChoiceKind.ChoosePermanent });

        Assert.Equal(bob, game.State.Choice!.PlayerId);
        game.Choose(bob, [game.State.Choice!.Options[0].Id]);
        Settle(game);

        Assert.Empty(game.State.GetPlayer(bob).Graveyard);
        Assert.Single(game.State.Exile);
    }

    /// <summary>
    /// "You lose half your life, rounded up" (CR 119.3, 107.15).
    /// </summary>
    /// <remarks>
    /// The reason this could not be written as an amount, played out: the number is taken from
    /// the player when the effect resolves, so the same printed sentence takes ten from a player
    /// on twenty and four from one on seven. Anything the compiler could have worked out in
    /// advance would be wrong for one of them.
    /// <para>
    /// The odd total is the assertion that separates the two roundings. Seven rounded up is four
    /// and rounded down is three, and every card that prints this sentence says which — so a
    /// reader that picked one would be right on half the corpus and quietly wrong on the rest.
    /// </para>
    /// </remarks>
    [Fact]
    public void Losing_half_your_life_takes_a_number_read_from_the_player()
    {
        var contract = Card(
            "Test Infernal Contract",
            "Draw four cards. You lose half your life, rounded up.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(contract);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, contract);
        var hand = game.State.GetPlayer(alice).Hand.Count;

        game.CastSpell(alice, card, []);
        Settle(game);

        // Twenty, halved and rounded up.
        Assert.Equal(10, game.State.GetPlayer(alice).Life);

        // The spell left the hand and four cards arrived, which is the other half of the line.
        Assert.Equal(hand - 1 + 4, game.State.GetPlayer(alice).Hand.Count);
    }

    /// <summary>
    /// The trigger's subject is halved, and the rounding is the card's rather than the reader's.
    /// </summary>
    /// <remarks>
    /// Quietus Spike's wording against Raving Dead's: one sentence, one word apart, and on an odd
    /// life total they take a different number. Both are played, because the pair is the control -
    /// a reader that defaulted the rounding would pass whichever of these it happened to agree
    /// with and this test would only find it if the other one ran too.
    /// </remarks>
    [Fact]
    public void The_two_roundings_of_half_a_life_total_take_different_numbers()
    {
        static int LifeLeftAfterOneHit(CardDefinition attacker)
        {
            var compiled = CardCompiler.Compile(attacker);
            Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

            var (game, alice, bob) = InMainPhase();
            var carrier = game.Create(alice, attacker, Zone.Battlefield);

            PassTo(game, 3, TurnStep.DeclareAttackers);
            game.DeclareAttackers(
                alice,
                new Dictionary<ObjectId, AttackTarget> { [carrier] = AttackTarget.Player(bob) });

            TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
            Settle(game);

            return game.State.GetPlayer(bob).Life;
        }

        var up = Card(
            "Test Quietus Spike",
            "Whenever ~ deals combat damage to a player, that player loses half their life, "
                + "rounded up.",
            CardType.Creature,
            1,
            1);

        var down = Card(
            "Test Raving Dead",
            "Whenever ~ deals combat damage to a player, that player loses half their life, "
                + "rounded down.",
            CardType.Creature,
            1,
            1);

        // One combat damage takes Bob to 19. Half of nineteen rounded up is ten, leaving nine;
        // rounded down it is nine, leaving ten. The whole family turns on that one word.
        Assert.Equal(9, LifeLeftAfterOneHit(up));
        Assert.Equal(10, LifeLeftAfterOneHit(down));
    }

    /// <summary>
    /// A halving with no rounding printed in the sentence is left unread.
    /// </summary>
    /// <remarks>
    /// CR 107.15 leaves the direction to the card, and several cards put it a clause away —
    /// "Each player loses half their life, then discards half the cards in their hand … Round up
    /// each time." Reading the first clause alone would pick a direction the card did not say,
    /// on a card whose other clauses are unread anyway.
    /// </remarks>
    [Fact]
    public void A_halving_that_does_not_say_which_way_it_rounds_is_left_unread()
    {
        var vague = Card("Test Vague Halving", "Each player loses half their life.");

        Assert.False(CardCompiler.Compile(vague).IsComplete);
    }

    // ---- Dividing and distributing (CR 601.2d) -------------------------------

    [Fact]
    public void Distributed_counters_are_announced_with_the_cast_and_land_as_announced()
    {
        var rite = Card(
            "Elven Rite Test",
            "Distribute two +1/+1 counters among one or two target creatures.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(rite);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        // "One or two" is at least one and at most two, which is one required spec and one
        // optional - the same shape divided damage already compiles to.
        Assert.Equal(2, compiled.Spell!.Targets.Count);
        Assert.False(compiled.Spell.Targets[0].Optional);
        Assert.True(compiled.Spell.Targets[1].Optional);

        var (game, alice, _) = InMainPhase();
        var first = game.Create(alice, TestCards.Creature("Counted One Test", 1, 1), Zone.Battlefield);
        var second = game.Create(alice, TestCards.Creature("Counted Two Test", 1, 1), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, rite);
        game.CastSpell(
            alice,
            card,
            [Target.ToPermanent(first), Target.ToPermanent(second)],
            damageDivision: [1, 1]);

        Settle(game);

        // One each, and each of them a 2/2 - the counters went where the announcement said and
        // not both onto the first creature.
        foreach (var id in new[] { first, second })
        {
            var creature = game.State.GetObject(id);
            Assert.Equal(
                1,
                creature.Permanent!.Counters.GetValueOrDefault(CounterKinds.PlusOnePlusOne));

            var computed = Characteristics.Of(game.State, Pool, creature);
            Assert.Equal(2, computed.Power);
            Assert.Equal(2, computed.Toughness);
        }
    }

    [Fact]
    public void A_distribution_that_leaves_a_target_with_nothing_is_refused()
    {
        var rite = Card(
            "Greedy Rite Test",
            "Distribute two +1/+1 counters among one or two target creatures.",
            CardType.Sorcery);

        var (game, alice, _) = InMainPhase();
        var first = game.Create(alice, TestCards.Creature("Greedy One Test", 1, 1), Zone.Battlefield);
        var second = game.Create(alice, TestCards.Creature("Greedy Two Test", 1, 1), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, rite);

        // The rule this family turns on. Naming two creatures and giving one of them nothing is
        // an illegal announcement, not a legal one that happens to do nothing (CR 601.2d) - it is
        // how a player would put both counters on one creature while appearing to spread them.
        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(
                alice,
                card,
                [Target.ToPermanent(first), Target.ToPermanent(second)],
                damageDivision: [2, 0]));

        // And the total has to be exactly what the card distributes.
        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(
                alice,
                card,
                [Target.ToPermanent(first), Target.ToPermanent(second)],
                damageDivision: [1, 2]));

        // Nothing happened either time. The refusal is a refusal to cast, taken before the cost
        // is paid (CR 601.2d before 601.2h), so no counter reached the board and no mana left the
        // pool - an illegal announcement cannot be used to drain an opponent's response window.
        Assert.All(
            new[] { first, second },
            id => Assert.Empty(game.State.GetObject(id).Permanent!.Counters));
    }

    [Fact]
    public void Divided_damage_reads_the_noun_form_and_spends_the_announcement()
    {
        var volley = Card(
            "Forked Volley Test",
            "~ deals 3 damage divided as you choose among one, two, or three target creatures.",
            CardType.Instant);

        var compiled = CardCompiler.Compile(volley);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        // The noun is what the division is spread over, so it is a creature target and not "any
        // target" - a player may not be given a share of this one.
        Assert.Equal(3, compiled.Spell!.Targets.Count);
        Assert.Equal(TargetKind.Permanent, compiled.Spell.Targets[0].Kind);

        var (game, alice, bob) = InMainPhase();
        var small = game.Create(bob, TestCards.Creature("Volleyed One Test", 1, 1), Zone.Battlefield);
        var big = game.Create(bob, TestCards.Creature("Volleyed Two Test", 3, 3), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, volley);
        game.CastSpell(
            alice,
            card,
            [Target.ToPermanent(small), Target.ToPermanent(big)],
            damageDivision: [1, 2]);

        Settle(game);

        Assert.Contains(
            game.State.GetPlayer(bob).Graveyard.Select(game.State.GetObject),
            o => o.Card.Name == "Volleyed One Test");

        var survivor = game.State.Battlefield.Select(game.State.GetObject)
            .Single(o => o.Card.Name == "Volleyed Two Test");

        Assert.Equal(2, survivor.Permanent?.DamageMarked);
    }

    [Fact]
    public void A_triggered_ability_is_asked_how_it_divides_before_anybody_has_priority()
    {
        var corps = Card(
            "Armament Corps Test",
            "When ~ enters, distribute two +1/+1 counters among one or two target creatures "
                + "you control.",
            CardType.Creature,
            power: 4,
            toughness: 3);

        var compiled = CardCompiler.Compile(corps);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var first = game.Create(alice, TestCards.Creature("Armed One Test", 1, 1), Zone.Battlefield);
        var second = game.Create(alice, TestCards.Creature("Armed Two Test", 1, 1), Zone.Battlefield);

        // Created in hand and moved, because an enters-the-battlefield trigger watches the move
        // (CR 603.6a) and a permanent conjured straight onto the battlefield never made one.
        game.Move(game.Create(alice, corps, Zone.Hand), Zone.Battlefield, MoveCause.Resolve);
        TestCards.PassUntil(game, () => game.State.IsWaitingForChoice);

        // The trigger picks its targets one question at a time (CR 603.3d) and only then is the
        // division asked - which is the announcement, made before anybody may respond to it.
        var targets = new[] { first, second };
        var picked = 0;

        for (var guard = 0; guard < 8 && game.State.Choice is { } choice; guard++)
        {
            if (choice.Kind != ChoiceKind.ChooseTriggerTargets)
                break;

            // The option's id carries which kind of target it is, because the id is all that
            // survives the question.
            var wanted = "object:" + targets[picked++].Value.ToString("N");
            game.Choose(choice.PlayerId, [wanted]);
        }

        var division = game.State.Choice;
        Assert.NotNull(division);
        Assert.Equal(ChoiceKind.DivideAmongTargets, division!.Kind);
        Assert.True(division.IsDivision);
        Assert.Equal(2, division.TotalToDivide);

        // One pick per counter, which is what makes every legal division sayable: two counters
        // between two creatures is two picks from two answers.
        Assert.Equal(2, division.MinPicks);
        Assert.Equal(2, division.MaxPicks);

        // Nothing may happen while the question is outstanding - the ability has not resolved and
        // no counter has reached the board.
        Assert.Empty(game.State.GetObject(first).Permanent!.Counters);

        // Both counters onto the first creature is an illegal announcement, because the second
        // was chosen as a target and CR 601.2d gives every chosen target at least one.
        var onlyTheFirst = division.Options[0].Id;
        Assert.Throws<InvalidOperationException>(
            () => game.Choose(division.PlayerId, [onlyTheFirst, onlyTheFirst]));

        // The question is still outstanding after the refusal, so the ability cannot slip past it.
        Assert.Equal(ChoiceKind.DivideAmongTargets, game.State.Choice!.Kind);

        game.Choose(
            division.PlayerId,
            [division.Options[0].Id, division.Options[1].Id]);

        Settle(game);

        foreach (var id in targets)
        {
            Assert.Equal(
                1,
                game.State.GetObject(id).Permanent!.Counters
                    .GetValueOrDefault(CounterKinds.PlusOnePlusOne));
        }
    }

    [Fact]
    public void An_activated_ability_divides_its_damage_from_a_question_of_its_own()
    {
        var fist = Card(
            "Iron Fist Test",
            "{T}: ~ deals 2 damage divided as you choose among one or two target creatures.",
            CardType.Creature,
            power: 2,
            toughness: 2,
            keywords: KeywordAbility.Haste);

        var compiled = CardCompiler.Compile(fist);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var source = game.Create(alice, fist, Zone.Battlefield);
        var first = game.Create(bob, TestCards.Creature("Punched One Test", 1, 1), Zone.Battlefield);
        var second = game.Create(bob, TestCards.Creature("Punched Two Test", 1, 1), Zone.Battlefield);

        // Haste, because the cost taps it and the permanent arrived this turn (CR 302.6). The
        // rule under test is the division, not summoning sickness.
        game.ActivateAbility(
            alice,
            source,
            compiled.Activated[0].Id,
            [Target.ToPermanent(first), Target.ToPermanent(second)]);

        var division = game.State.Choice;
        Assert.NotNull(division);
        Assert.Equal(ChoiceKind.DivideAmongTargets, division!.Kind);
        Assert.Equal(2, division.TotalToDivide);

        game.Choose(division.PlayerId, [division.Options[0].Id, division.Options[1].Id]);
        Settle(game);

        // One damage each killed both 1/1s. An unannounced division would have dealt nothing at
        // all, which is the failure this question exists to make impossible.
        Assert.Equal(2, game.State.GetPlayer(bob).Graveyard.Count);
    }

    // ---- One trigger per blocking pair (CR 509.3c/d, 603.2b) -----------------

    /// <summary>Every trigger this ability filed, in the order it filed them.</summary>
    /// <remarks>
    /// Read off the log rather than off the board, because the count and the subject are the two
    /// halves of what CR 603.2b decides and only one of them is visible from the battlefield. A
    /// card that fired twice where it should have fired once can leave a board indistinguishable
    /// from one that fired once, and a card that damaged the wrong creature can leave one that
    /// looks right for the turn it happened on.
    /// </remarks>
    private static List<AbilityTriggered> TriggersFiledBy(Game game, ObjectId source) =>
        [.. game.Log.OfType<AbilityTriggered>().Where(t => t.SourceId == source)];

    [Fact]
    public void A_block_pair_trigger_damages_the_creature_it_blocked_and_not_itself()
    {
        var hound = Card(
            "Ashmouth Pair Test",
            "Whenever ~ blocks or becomes blocked by a creature, ~ deals 1 damage to that creature.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var compiled = CardCompiler.Compile(hound);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.True(compiled.Triggers[0].PerDeclaredCreature);

        var (game, alice, bob) = InMainPhase();

        // A 0/1, so nothing it does in combat can be mistaken for what the ability did. The
        // ability's one damage is the only damage in this test.
        var attacker = game.Create(
            alice, TestCards.Creature("Ashmouth Attacker Test", 0, 1), Zone.Battlefield);

        var blocker = game.Create(bob, hound, Zone.Battlefield);

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);
        game.DeclareBlockers(
            bob,
            new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [attacker] = [blocker] });

        Settle(game);

        // The subject is the other creature in the pair - here the attacker, because the source
        // is on the blocking side of it. This is the assertion the whole mechanism exists for:
        // "that creature" resolved to something the ability never chose and never targeted.
        var filed = TriggersFiledBy(game, blocker);
        Assert.Single(filed);
        Assert.Equal(attacker, filed[0].SubjectObject);

        // And it went where the subject said. A pronoun falling back to the permanent with the
        // ability - the failure this codebase reverted a first attempt for - would have left the
        // 0/1 alive and put a damage marker on the Hound instead.
        Assert.DoesNotContain(attacker, game.State.Battlefield);
        Assert.Contains(blocker, game.State.Battlefield);
        Assert.Equal(0, game.State.GetObject(blocker).Permanent!.DamageMarked);
    }

    /// <summary>
    /// CR 509.3d: "becomes blocked <em>by a creature</em>" fires once for each of them.
    /// </summary>
    /// <remarks>
    /// CR 603.2b's own example is this sentence beside the one below it: an attacker blocked by
    /// two creatures is one event for "whenever this creature becomes blocked" and two events for
    /// "whenever this creature becomes blocked by a creature". A declaration is a batch of pairs,
    /// and this is the family for which a batch is not one occurrence.
    /// <para>
    /// Both subjects are asserted, not just the count. A trigger that fired twice with the same
    /// subject would kill one creature twice and leave the other alone, and a board with two
    /// blockers dead is the only thing that tells the two apart.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_block_pair_trigger_fires_once_for_each_creature_that_blocks_it()
    {
        var slinger = Card(
            "Skewer Pair Test",
            "Whenever ~ becomes blocked by a creature, ~ deals 1 damage to that creature.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var compiled = CardCompiler.Compile(slinger);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, slinger, Zone.Battlefield);
        var first = game.Create(
            bob, TestCards.Creature("Skewer Blocker One Test", 0, 1), Zone.Battlefield);

        var second = game.Create(
            bob, TestCards.Creature("Skewer Blocker Two Test", 0, 1), Zone.Battlefield);

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);
        game.DeclareBlockers(
            bob,
            new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [attacker] = [first, second] });

        Settle(game);

        var filed = TriggersFiledBy(game, attacker);
        Assert.Equal(2, filed.Count);
        Assert.Equal(
            new HashSet<ObjectId> { first, second },
            [.. filed.Select(t => t.SubjectObject!.Value)]);

        // One damage each is lethal to a 0/1, so both are gone and the attacker took nothing.
        // Asked of the battlefield rather than of the graveyard, because a graveyard collects
        // everything a player discarded on the way here and would have counted a card the test
        // never played.
        Assert.DoesNotContain(first, game.State.Battlefield);
        Assert.DoesNotContain(second, game.State.Battlefield);
        Assert.Contains(attacker, game.State.Battlefield);
        Assert.Equal(0, game.State.GetObject(attacker).Permanent!.DamageMarked);
    }

    /// <summary>
    /// CR 509.3c: "becomes blocked" with no creature named fires once for the whole declaration.
    /// </summary>
    /// <remarks>
    /// The half that keeps the family honest. Paying this trigger once per blocker would print a
    /// strictly better card than the one on the table, and the only thing separating it from the
    /// test above is whether the sentence names an object - so the two are written side by side.
    /// </remarks>
    [Fact]
    public void A_becomes_blocked_trigger_naming_no_creature_fires_once_for_the_batch()
    {
        var afflict = Card(
            "Afflict Batch Test",
            "Whenever ~ becomes blocked, you gain 2 life.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var compiled = CardCompiler.Compile(afflict);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.False(compiled.Triggers[0].PerDeclaredCreature);

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, afflict, Zone.Battlefield);
        var first = game.Create(
            bob, TestCards.Creature("Afflict Blocker One Test", 0, 1), Zone.Battlefield);

        var second = game.Create(
            bob, TestCards.Creature("Afflict Blocker Two Test", 0, 1), Zone.Battlefield);

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);

        var before = game.State.GetPlayer(alice).Life;

        game.DeclareBlockers(
            bob,
            new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [attacker] = [first, second] });

        Settle(game);

        Assert.Single(TriggersFiledBy(game, attacker));
        Assert.Equal(before + 2, game.State.GetPlayer(alice).Life);
    }

    /// <summary>
    /// CR 509.1h: an attacker nobody blocked did not become blocked, however it was declared.
    /// </summary>
    /// <remarks>
    /// A declaration may name an attacker and give it no blockers, and the reader for "blocks or
    /// becomes blocked" asked only whether the id was in the declaration at all - so bushido fired
    /// for an attacker that got through. Its sibling reader for "becomes blocked" had the emptiness
    /// check from the start, which is the shape of defect this file keeps recording: two spellings
    /// of one rule, and only one of them right.
    /// </remarks>
    [Fact]
    public void A_block_trigger_does_not_fire_for_an_attacker_nobody_blocked()
    {
        var bushido = Card(
            "Bushido Empty Test",
            "Whenever ~ blocks or becomes blocked, you gain 2 life.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var compiled = CardCompiler.Compile(bushido);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, bushido, Zone.Battlefield);

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);

        var before = game.State.GetPlayer(alice).Life;

        // Named in the declaration, with nothing declared as blocking it.
        game.DeclareBlockers(
            bob,
            new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [attacker] = [] });

        Settle(game);

        Assert.Empty(TriggersFiledBy(game, attacker));
        Assert.Equal(before, game.State.GetPlayer(alice).Life);
    }

    /// <summary>
    /// A block sentence with no creature in it leaves the pronoun unread rather than aiming it.
    /// </summary>
    /// <remarks>
    /// The fail-closed half, and the reason both halves of this feature had to be built together.
    /// "Whenever ~ becomes blocked" supplies no subject - CR 509.3c makes it one trigger for a
    /// batch of pairs, and no one creature is what it was about - so a "that creature" beside it
    /// has nothing to mean. Compiling it anyway is what made an earlier attempt aim the damage at
    /// the permanent with the ability, and this asserts the card is refused instead.
    /// </remarks>
    [Fact]
    public void A_block_pronoun_with_no_creature_named_leaves_the_card_unread()
    {
        var refused = Card(
            "Blocked Pronoun Refused Test",
            "Whenever ~ becomes blocked, ~ deals 1 damage to that creature.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        Assert.False(CardCompiler.Compile(refused).IsComplete);

        // The same sentence with the creature named reads, which is what makes the refusal above
        // a reading of the rule rather than a gap in the grammar.
        var read = Card(
            "Blocked Pronoun Read Test",
            "Whenever ~ becomes blocked by a creature, ~ deals 1 damage to that creature.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var compiled = CardCompiler.Compile(read);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.True(compiled.Triggers[0].PerDeclaredCreature);
    }

    /// <summary>
    /// The same subject on the same verb, one trigger family along (CR 603.2).
    /// </summary>
    /// <remarks>
    /// Damage was the last of the pronoun verbs without a subject, and the gap was never only
    /// about blocking: Aether Flash says "whenever a creature enters, ~ deals 2 damage to it", an
    /// arrival names exactly one object, and the sentence was unread for want of the same field.
    /// </remarks>
    [Fact]
    public void Damage_to_the_trigger_subject_reaches_the_creature_that_arrived()
    {
        var flash = Card(
            "Aether Flash Test",
            "Whenever a creature enters, ~ deals 2 damage to it.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(flash);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var enchantment = game.Create(alice, flash, Zone.Battlefield);
        var arriving = game.Create(
            bob, TestCards.Creature("Aether Flash Victim Test", 2, 2), Zone.Battlefield);

        Settle(game);

        var filed = TriggersFiledBy(game, enchantment);
        Assert.Single(filed);
        Assert.Equal(arriving, filed[0].SubjectObject);

        // Two damage on a 2/2 is lethal, and the enchantment is not a creature to damage instead.
        Assert.DoesNotContain(arriving, game.State.Battlefield);
        Assert.Contains(enchantment, game.State.Battlefield);
    }

    // ---- One trigger per attacking creature (CR 508.3a, 603.2c) --------------

    /// <summary>
    /// CR 508.3a: a declaration of attackers is one occurrence for each creature in it.
    /// </summary>
    /// <remarks>
    /// The attack half of the decomposition the block family already had, and the same rule read
    /// one batch along. CR 508.3a says "whenever <em>a creature</em> attacks" triggers if that
    /// creature is declared as an attacker; CR 603.2c says one event can hold an occurrence for
    /// each of them. So two attackers are two triggers, and the subject of each is its own
    /// attacker - which is the half a count cannot see. Before this, Caltrops read, compiled,
    /// counted as a complete card, fired once, and dealt its damage to nothing at all whenever two
    /// creatures attacked: <see cref="Game.SubjectObjectOf"/> answers a declaration only when it
    /// holds exactly one attacker.
    /// <para>
    /// Both subjects are asserted, not just the count. A trigger that fired twice with the same
    /// subject would kill one attacker twice and leave the other alone, and a board with both
    /// attackers dead is the only thing that tells the two apart.
    /// </para>
    /// </remarks>
    [Fact]
    public void An_attack_trigger_fires_once_for_each_attacking_creature()
    {
        var caltrops = Card(
            "Caltrops Occurrence Test",
            "Whenever a creature attacks, ~ deals 1 damage to it.",
            CardType.Artifact);

        var compiled = CardCompiler.Compile(caltrops);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.True(compiled.Triggers[0].PerDeclaredCreature);

        var (game, alice, bob) = InMainPhase();

        // The defending player's artifact, so nothing about the source is in the declaration it is
        // asking about - which is the case the pair machinery had to grow a second shape for.
        var artifact = game.Create(bob, caltrops, Zone.Battlefield);

        var first = game.Create(
            alice, TestCards.Creature("Caltrops Attacker One Test", 2, 1), Zone.Battlefield);

        var second = game.Create(
            alice, TestCards.Creature("Caltrops Attacker Two Test", 2, 1), Zone.Battlefield);

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget>
            {
                [first] = AttackTarget.Player(bob),
                [second] = AttackTarget.Player(bob),
            });

        Settle(game);

        var filed = TriggersFiledBy(game, artifact);
        Assert.Equal(2, filed.Count);
        Assert.Equal(
            new HashSet<ObjectId> { first, second },
            [.. filed.Select(t => t.SubjectObject!.Value)]);

        // One damage each is lethal to a 2/1, so both are gone before they could connect and the
        // artifact - which is not a creature to damage instead - is still there.
        Assert.DoesNotContain(first, game.State.Battlefield);
        Assert.DoesNotContain(second, game.State.Battlefield);
        Assert.Contains(artifact, game.State.Battlefield);
        Assert.Equal(20, game.State.GetPlayer(bob).Life);
    }

    /// <summary>
    /// CR 508.3d: the same event said as a batch is one occurrence, however many attacked.
    /// </summary>
    /// <remarks>
    /// The half that keeps the family honest, and the only thing separating it from the test above
    /// is the two words the sentence opens with. "One or more creatures you control attack" is the
    /// declaration described as a whole - it is why the six corpus lines that go on to say "that
    /// many" mean the batch - and paying it once per attacker would print a strictly better card
    /// than the one on the table while the coverage number scored it as a win.
    /// </remarks>
    [Fact]
    public void An_attack_trigger_written_as_a_batch_fires_once_for_the_declaration()
    {
        var muster = Card(
            "Attack Batch Occurrence Test",
            "Whenever one or more creatures you control attack, you gain 2 life.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(muster);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.False(compiled.Triggers[0].PerDeclaredCreature);

        var (game, alice, bob) = InMainPhase();
        var enchantment = game.Create(alice, muster, Zone.Battlefield);
        var first = game.Create(
            alice, TestCards.Creature("Batch Attacker One Test", 2, 2), Zone.Battlefield);

        var second = game.Create(
            alice, TestCards.Creature("Batch Attacker Two Test", 2, 2), Zone.Battlefield);

        PassTo(game, 3, TurnStep.DeclareAttackers);

        var before = game.State.GetPlayer(alice).Life;

        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget>
            {
                [first] = AttackTarget.Player(bob),
                [second] = AttackTarget.Player(bob),
            });

        Settle(game);

        Assert.Single(TriggersFiledBy(game, enchantment));
        Assert.Equal(before + 2, game.State.GetPlayer(alice).Life);
    }

    /// <summary>
    /// A per-attacker trigger answers for the attackers its own sentence describes, and no others.
    /// </summary>
    /// <remarks>
    /// The decomposition asks the ability's own predicate about each attacker alone rather than
    /// re-reading the condition, which is what keeps every qualifier the sentence prints - the
    /// tribe here, the defending player below, and the colour, side and power beside them -
    /// applied per creature without being restated in the engine. A decomposition that counted
    /// attackers instead would fire twice here, and the card says once.
    /// </remarks>
    [Fact]
    public void A_per_attacker_trigger_answers_only_for_the_creatures_it_describes()
    {
        var warcaller = Card(
            "Tribal Occurrence Test",
            "Whenever a Goblin you control attacks, you gain 1 life.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(warcaller);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.True(compiled.Triggers[0].PerDeclaredCreature);

        var (game, alice, bob) = InMainPhase();
        var enchantment = game.Create(alice, warcaller, Zone.Battlefield);
        var goblin = game.Create(
            alice,
            Card("Tribal Goblin Test", string.Empty, CardType.Creature, 2, 2, subtypes: "Goblin"),
            Zone.Battlefield);

        var bear = game.Create(
            alice, TestCards.Creature("Tribal Bear Test", 2, 2), Zone.Battlefield);

        PassTo(game, 3, TurnStep.DeclareAttackers);

        var before = game.State.GetPlayer(alice).Life;

        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget>
            {
                [goblin] = AttackTarget.Player(bob),
                [bear] = AttackTarget.Player(bob),
            });

        Settle(game);

        var filed = TriggersFiledBy(game, enchantment);
        Assert.Single(filed);
        Assert.Equal(goblin, filed[0].SubjectObject);
        Assert.Equal(before + 1, game.State.GetPlayer(alice).Life);
    }

    /// <summary>
    /// CR 508.1b: who each attacker was declared against is asked of each attacker, not the batch.
    /// </summary>
    /// <remarks>
    /// "Attacks you" is the player and not a planeswalker they control, and the declaration says
    /// which of the two each creature was aimed at. The occurrence carries its own
    /// <see cref="AttackTarget"/> for exactly this: cut into attackers without it, both halves of
    /// a split declaration would look alike and Hissing Miasma would charge for a creature that
    /// attacked a planeswalker.
    /// </remarks>
    [Fact]
    public void A_per_attacker_trigger_reads_the_defender_each_attacker_was_declared_against()
    {
        var miasma = Card(
            "Defender Occurrence Test",
            "Whenever a creature attacks you, ~ deals 1 damage to it.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(miasma);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.True(compiled.Triggers[0].PerDeclaredCreature);

        var (game, alice, bob) = InMainPhase();
        var enchantment = game.Create(alice, miasma, Zone.Battlefield);
        var walker = game.Create(
            alice, Walker("Defender Occurrence Walker Test", 5, string.Empty), Zone.Battlefield);

        var atPlayer = game.Create(
            bob, TestCards.Creature("Defender At Player Test", 2, 1), Zone.Battlefield);

        var atWalker = game.Create(
            bob, TestCards.Creature("Defender At Walker Test", 2, 1), Zone.Battlefield);

        PassTo(game, 2, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            bob,
            new Dictionary<ObjectId, AttackTarget>
            {
                [atPlayer] = AttackTarget.Player(alice),
                [atWalker] = AttackTarget.At(alice, walker),
            });

        Settle(game);

        var filed = TriggersFiledBy(game, enchantment);
        Assert.Single(filed);
        Assert.Equal(atPlayer, filed[0].SubjectObject);

        // One damage is lethal to a 2/1, and only the one that attacked the player took it.
        Assert.DoesNotContain(atPlayer, game.State.Battlefield);
        Assert.Contains(atWalker, game.State.Battlefield);
    }

    /// <summary>
    /// "Whenever ~ attacks" is a sentence about one creature already, and is not decomposed.
    /// </summary>
    /// <remarks>
    /// The source family sits outside this mechanism on purpose: its own reader answers whether
    /// the source is in the declaration, there is no second creature for a pronoun to mean, and
    /// flagging it would put a batch through a decomposition that has nothing to decompose. The
    /// flag is asserted as well as the count, because the two say different things - a flag set
    /// here would still fire once, and would start supplying a subject the sentence never named.
    /// </remarks>
    [Fact]
    public void A_trigger_about_the_source_attacking_fires_once_and_is_not_decomposed()
    {
        var raider = Card(
            "Source Attack Once Test",
            "Whenever ~ attacks, you gain 2 life.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var compiled = CardCompiler.Compile(raider);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.False(compiled.Triggers[0].PerDeclaredCreature);

        var (game, alice, bob) = InMainPhase();
        var source = game.Create(alice, raider, Zone.Battlefield);
        var friend = game.Create(
            alice, TestCards.Creature("Source Attack Friend Test", 2, 2), Zone.Battlefield);

        PassTo(game, 3, TurnStep.DeclareAttackers);

        var before = game.State.GetPlayer(alice).Life;

        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget>
            {
                [source] = AttackTarget.Player(bob),
                [friend] = AttackTarget.Player(bob),
            });

        Settle(game);

        Assert.Single(TriggersFiledBy(game, source));
        Assert.Equal(before + 2, game.State.GetPlayer(alice).Life);
    }

    /// <summary>
    /// "That creature gets +N/+N" means the creature the trigger was about, not the source.
    /// </summary>
    /// <remarks>
    /// A second reader for this sentence sat in front of the pronoun ladder and aimed the pump at
    /// the permanent with the ability <em>unconditionally</em>. It had been written for exalted,
    /// where the sentence is about a lone attacker and the source is usually that attacker, so
    /// every game where it mattered looked like a game where it did not - and every card whose
    /// trigger names an object reached it first and buffed the wrong creature. Primal Forcemage,
    /// Ambuscade Shaman and Ardoz all pumped themselves; Flailing Drake pumped itself while a
    /// previous round recorded it as fixed.
    /// <para>
    /// The fix was to delete the second reader rather than teach it the ladder. The three answers
    /// a pronoun has - the target, then the object the trigger was about, then the permanent with
    /// the ability - are one list in one place, and a second copy of a list is how they come to
    /// disagree.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_pump_on_a_trigger_that_names_an_object_reaches_that_object()
    {
        var forcemage = Card(
            "Forcemage Subject Test",
            "Whenever another creature you control enters, that creature gets +3/+3 until end of turn.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var compiled = CardCompiler.Compile(forcemage);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var source = game.Create(alice, forcemage, Zone.Battlefield);
        var arriving = game.Create(
            alice, TestCards.Creature("Forcemage Arrival Test", 1, 1), Zone.Battlefield);

        Settle(game);

        var filed = TriggersFiledBy(game, source);
        Assert.Single(filed);
        Assert.Equal(arriving, filed[0].SubjectObject);

        // The creature that arrived is 4/4; the one that said so is still 2/2. Both are asserted,
        // because a pump that reached neither would leave the first number right by accident.
        Assert.Equal(
            4, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(arriving)));

        Assert.Equal(
            2, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(source)));
    }

    // ---- A token that's a copy, and its exceptions (CR 707.2, 707.9b) --------

    /// <summary>
    /// A token created as a copy is the copied card, abilities and all (CR 707.2a).
    /// </summary>
    /// <remarks>
    /// The size is not the assertion that earns its place. A token minted at the right power and
    /// toughness with none of the copied card's behaviour passes every characteristic check and
    /// is the wrong card at the only moment anybody notices - so the copied <c>{T}</c> ability is
    /// made to resolve and the copied attack trigger is made to fire, on a token that came from a
    /// spell printing neither.
    /// <para>
    /// The two life totals are the whole test: 1 from the copied tap ability and 3 from the
    /// copied trigger, against a starting 20. An engine that copied the numbers and dropped the
    /// abilities leaves Alice on 20 with every other assertion still green.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_token_copy_plays_the_copied_cards_abilities()
    {
        var original = Card(
            "Token Copy Source Test",
            "Whenever this creature attacks, you gain 3 life.\n{T}: You gain 1 life.",
            CardType.Creature,
            3,
            3,
            KeywordAbility.Flying,
            "Bird");

        var compiled = CardCompiler.Compile(original);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var maker = Card(
            "Token Copy Maker Test",
            "Create a token that's a copy of target creature you control.");

        Assert.True(CardCompiler.Compile(maker).IsComplete);

        var (game, alice, bob) = InMainPhase();
        var bird = game.Create(alice, original, Zone.Battlefield);

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, maker), [Target.ToPermanent(bird)]);

        Settle(game);

        var token = TokenNamed(game, "Token Copy Source Test");
        var now = Characteristics.Of(game.State, Pool, game.State.GetObject(token));

        Assert.Equal(3, now.Power);
        Assert.Equal(3, now.Toughness);
        Assert.True(now.Has(KeywordAbility.Flying));
        Assert.Contains("Bird", now.Subtypes, StringComparer.OrdinalIgnoreCase);

        // Summoning sickness is the token's too (CR 302.6): it waits a turn like anything else,
        // and then the copied attack trigger fires - 20 -> 23, with Bob taking the copied card's
        // 3 power rather than anything the spell printed.
        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice, new Dictionary<ObjectId, AttackTarget> { [token] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Settle(game);

        Assert.Equal(23, game.State.GetPlayer(alice).Life);
        Assert.Equal(17, game.State.GetPlayer(bob).Life);

        // And the copied activated ability is offered on the token and resolves: 23 -> 24. A turn
        // later than the attack because it costs {T} and the token spent its untapped turn
        // attacking.
        PassTo(game, 5, TurnStep.PrecombatMain);

        var granted = Assert.Single(
            Game.ActivatedAbilitiesOf(game.State, Pool, game.State.GetObject(token)));

        game.ActivateAbility(alice, token, granted.Id);
        Settle(game);

        Assert.Equal(24, game.State.GetPlayer(alice).Life);
    }

    /// <summary>
    /// An "except" clause changes the copied card and nothing else (CR 707.9b).
    /// </summary>
    /// <remarks>
    /// Ratadrabik of Urborg's clause, which is the one that separates an added characteristic
    /// from a replaced one: "in addition to its other <em>colors and</em> types" adds black to
    /// what the creature already was, while the same sentence without those two words would
    /// replace the colour outright. Both halves are asserted, because a reader that treated every
    /// colour as a replacement would leave this token black and not green and look perfectly
    /// reasonable doing it.
    /// <para>
    /// The copied ability is asserted as well. CR 707.9b modifies a <em>characteristic</em>, so
    /// the exception must not cost the copy its behaviour - a Zombie that forgot what it copied
    /// is the failure this whole family fails towards.
    /// </para>
    /// </remarks>
    [Fact]
    public void An_except_clause_adds_a_colour_and_keeps_the_copied_ability()
    {
        var lord = new CardDefinition
        {
            OracleId = "oracle-token-copy-legend-test",
            Name = "Token Copy Legend Test",
            OracleText = "Other creatures you control get +1/+1.",
            CardTypes = CardType.Creature,
            Supertypes = ["Legendary"],
            Subtypes = ["Elf"],
            Colors = [ManaColor.Green],
            ColorIdentity = [ManaColor.Green],
            Power = 4,
            Toughness = 4,
        };

        var compiled = CardCompiler.Compile(lord);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var maker = Card(
            "Token Copy Zombie Maker Test",
            "Create a token that's a copy of target creature you control, except it's not "
                + "legendary and it's a 2/2 black Zombie in addition to its other colors and types.");

        Assert.True(
            CardCompiler.Compile(maker).IsComplete,
            string.Join(" | ", CardCompiler.Compile(maker).Unhandled));

        var (game, alice, _) = InMainPhase();
        var elf = game.Create(alice, lord, Zone.Battlefield);

        // A third creature the spell never touches, so the copied anthem has somewhere to show.
        var bystander = game.Create(
            alice, TestCards.Creature("Token Copy Bystander Test", 1, 1), Zone.Battlefield);

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, maker), [Target.ToPermanent(elf)]);

        Settle(game);

        var token = TokenNamed(game, "Token Copy Legend Test");
        var now = Characteristics.Of(game.State, Pool, game.State.GetObject(token));

        // The size the clause names is written onto the copied card, which is what CR 707.9b
        // says the exception does - and the board then reads 3/3, because the creature it copied
        // is a lord and pumps it. Both are asserted: the copiable value proves the exception
        // landed, and the computed one proves it landed in layer 1 rather than on top of the
        // layers, where an anthem would have been overwritten by it.
        Assert.Equal(2, now.Card.Power);
        Assert.Equal(2, now.Card.Toughness);
        Assert.Equal(3, now.Power);
        Assert.Equal(3, now.Toughness);

        // "Not legendary" is why the token is on the battlefield at all: kept, the legend rule
        // would have made Alice bin one of the two (CR 704.5j).
        Assert.DoesNotContain(
            "Legendary", now.Card.Supertypes, StringComparer.OrdinalIgnoreCase);

        Assert.Equal(
            2,
            game.State.Battlefield.Count(
                id => game.State.GetObject(id).Card.Name == "Token Copy Legend Test"));

        // Added, not replaced: the token is a green Elf *and* a black Zombie.
        Assert.Contains(ManaColor.Green, now.Colors);
        Assert.Contains(ManaColor.Black, now.Colors);
        Assert.Contains("Elf", now.Subtypes, StringComparer.OrdinalIgnoreCase);
        Assert.Contains("Zombie", now.Subtypes, StringComparer.OrdinalIgnoreCase);

        // Two anthems now, on a creature neither of them was aimed at: the exception changed the
        // card's characteristics and left its static ability exactly where it was.
        Assert.Equal(
            3, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(bystander)));
    }

    /// <summary>
    /// A clause with no "in addition" replaces what it names (CR 707.9b).
    /// </summary>
    /// <remarks>
    /// Croaking Counterpart, and the other side of the sentence above. Its token is a 1/1 green
    /// Frog and nothing else - not a green Frog Beast, and not a green and white one - which is
    /// the whole reason the two clauses have to be read as different rules rather than as one
    /// permissive pattern.
    /// </remarks>
    [Fact]
    public void An_except_clause_without_in_addition_replaces_the_colour_and_the_types()
    {
        var beast = new CardDefinition
        {
            OracleId = "oracle-token-copy-beast-test",
            Name = "Token Copy Beast Test",
            OracleText = string.Empty,
            CardTypes = CardType.Creature,
            Subtypes = ["Beast", "Warrior"],
            Colors = [ManaColor.White],
            ColorIdentity = [ManaColor.White],
            Power = 5,
            Toughness = 5,
        };

        var maker = Card(
            "Token Copy Frog Maker Test",
            "Create a token that's a copy of target non-Frog creature, except it's a 1/1 green Frog.");

        Assert.True(
            CardCompiler.Compile(maker).IsComplete,
            string.Join(" | ", CardCompiler.Compile(maker).Unhandled));

        var (game, alice, _) = InMainPhase();
        var target = game.Create(alice, beast, Zone.Battlefield);

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, maker), [Target.ToPermanent(target)]);

        Settle(game);

        var token = TokenNamed(game, "Token Copy Beast Test");
        var now = Characteristics.Of(game.State, Pool, game.State.GetObject(token));

        Assert.Equal(1, now.Power);
        Assert.Equal(1, now.Toughness);
        Assert.Equal([ManaColor.Green], now.Colors);
        Assert.Contains("Frog", now.Subtypes, StringComparer.OrdinalIgnoreCase);
        Assert.DoesNotContain("Beast", now.Subtypes, StringComparer.OrdinalIgnoreCase);
        Assert.DoesNotContain("Warrior", now.Subtypes, StringComparer.OrdinalIgnoreCase);
    }

    /// <summary>A sentence may ask for more than one copy, and for a tapped one (CR 111.6).</summary>
    /// <remarks>
    /// Skitterbeam Battalion's count and Compy Swarm's tapped arrival, which had both been read
    /// as "a token" because the pattern only knew the article. The count is asserted as two
    /// distinct objects rather than as a number on the effect, because a count read into the
    /// wrong field compiles just as cleanly and makes one.
    /// </remarks>
    [Fact]
    public void A_sentence_can_ask_for_two_copies_and_for_a_tapped_one()
    {
        var battalion = Card(
            "Token Copy Battalion Test",
            "When this creature enters, if you cast it, create two tokens that are copies of it.",
            CardType.Creature,
            1,
            1);

        Assert.True(
            CardCompiler.Compile(battalion).IsComplete,
            string.Join(" | ", CardCompiler.Compile(battalion).Unhandled));

        var (game, alice, _) = InMainPhase();

        game.CastSpell(alice, TestCards.PutInHand(game, alice, battalion), targets: null);
        Settle(game);

        var copies = game.State.Battlefield
            .Select(id => game.State.GetObject(id))
            .Where(o => o.Card.Name == "Token Copy Battalion Test")
            .ToList();

        // Three in all: the creature that was cast and the two tokens its trigger made. The
        // tokens do not go on making more, because they were created rather than cast and the
        // intervening "if you cast it" is false for them (CR 603.4).
        Assert.Equal(3, copies.Count);
        Assert.Equal(2, copies.Count(o => o.Card.CardTypes.HasFlag(CardType.Token)));

        var swarm = Card(
            "Token Copy Swarm Test",
            "At the beginning of your end step, if a creature died this turn, create a tapped "
                + "token that's a copy of this creature.",
            CardType.Creature,
            2,
            2);

        Assert.True(
            CardCompiler.Compile(swarm).IsComplete,
            string.Join(" | ", CardCompiler.Compile(swarm).Unhandled));

        // A second game, because the first has three creatures named for the card above and the
        // tapped token has to be the only one of its own name on the board to be found.
        var (second, owner, _) = InMainPhase();
        second.Create(owner, swarm, Zone.Battlefield);

        var doomed = second.Create(
            owner, TestCards.Creature("Token Copy Doomed Test", 1, 1), Zone.Battlefield);

        second.CastSpell(
            owner,
            TestCards.PutInHand(
                second, owner, Card("Token Copy Kill Test", "Destroy target creature.")),
            [Target.ToPermanent(doomed)]);

        Settle(second);
        TestCards.PassUntil(second, () => second.State.CurrentStep == TurnStep.End);
        Settle(second);

        var tapped = TokenNamed(second, "Token Copy Swarm Test");
        Assert.True(second.State.GetObject(tapped).Permanent?.IsTapped);
    }

    /// <summary>
    /// A token can be a copy of a card, which is read from the card itself (CR 707.2).
    /// </summary>
    /// <remarks>
    /// Restore Relic's wording, and this round's one repair rather than addition. The sentence
    /// aims its pronoun at a card in a graveyard, and the effect took every pronoun for a
    /// permanent - so it looked for a permanent that was not on the battlefield, found none, and
    /// made no token at all. The card was filed as fully read the whole time, which is the quiet
    /// half of this failure: coverage counted it and nothing played it.
    /// <para>
    /// The exile in the sentence before is what makes the last-known-information path
    /// load-bearing (CR 400.7, 608.2g): by the time the copy runs, the id the spell targeted
    /// names nothing and the card it became is in exile.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_token_copy_of_a_card_in_a_graveyard_brings_that_cards_abilities()
    {
        var buried = Card(
            "Token Copy Buried Test",
            "{T}: You gain 1 life.",
            CardType.Creature,
            2,
            2,
            KeywordAbility.Flying,
            "Spirit");

        Assert.True(CardCompiler.Compile(buried).IsComplete);

        var relic = Card(
            "Token Copy Relic Test",
            "Exile target artifact or creature card from your graveyard. Create a token that's a "
                + "copy of it.",
            CardType.Sorcery);

        Assert.True(
            CardCompiler.Compile(relic).IsComplete,
            string.Join(" | ", CardCompiler.Compile(relic).Unhandled));

        var (game, alice, _) = InMainPhase();
        var card = game.Create(alice, buried, Zone.Graveyard);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, relic), [Target.ToCard(card)]);
        Settle(game);

        var token = TokenNamed(game, "Token Copy Buried Test");
        var now = Characteristics.Of(game.State, Pool, game.State.GetObject(token));

        Assert.Equal(2, now.Power);
        Assert.True(now.Has(KeywordAbility.Flying));
        Assert.Contains("Spirit", now.Subtypes, StringComparer.OrdinalIgnoreCase);

        // The abilities came with it, which is the assertion the blank could never have passed.
        PassTo(game, 3, TurnStep.PrecombatMain);

        var granted = Assert.Single(
            Game.ActivatedAbilitiesOf(game.State, Pool, game.State.GetObject(token)));

        game.ActivateAbility(alice, token, granted.Id);
        Settle(game);

        Assert.Equal(21, game.State.GetPlayer(alice).Life);
    }

    /// <summary>
    /// The exception's quoted ability is the token's own, so "sacrifice this token" means the
    /// token (CR 707.9b).
    /// </summary>
    /// <remarks>
    /// Electroduplicate's clause, which was declined for a round because the quotation had
    /// nowhere to go - a token's abilities come from the card it copies, and that card's text
    /// cannot be edited without giving it an identity of its own. Now that the grant re-keys the
    /// definition, it goes exactly where it belongs and the pronoun stops being ambiguous: the
    /// ability is <em>on the token</em>, so its "this token" is the token and nothing else.
    /// <para>
    /// That is worth asserting from the other end. The same sentence printed <em>outside</em> the
    /// quotation - Kiki-Jiki's "Sacrifice it at the beginning of the next end step" - is still
    /// refused, because there "it" is read by the pronoun ladder and answers with the creature
    /// that was copied. Two sentences with the same words, one of which the engine can attribute
    /// and one of which it cannot; the test below this one holds the refusal.
    /// </para>
    /// </remarks>
    [Fact]
    public void An_exception_naming_a_quoted_ability_puts_it_on_the_token_it_names()
    {
        var duplicate = Card(
            "Token Copy Quoted Test",
            "Create a token that's a copy of target creature you control, except it has haste "
                + "and \"At the beginning of the end step, sacrifice this token.\"");

        var compiled = CardCompiler.Compile(duplicate);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var bear = game.Create(
            alice, TestCards.Creature("Token Copy Quoted Bear Test", 3, 3), Zone.Battlefield);

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, duplicate), [Target.ToPermanent(bear)]);

        Settle(game);

        var token = TokenNamed(game, "Token Copy Quoted Bear Test");
        Assert.NotEqual(default, token);

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.End);
        Settle(game);

        // The token sacrificed itself and the creature it copied is still standing - which is the
        // whole difference between a granted ability and a sentence beside the copy clause.
        Assert.DoesNotContain(token, game.State.Battlefield);
        Assert.Contains(bear, game.State.Battlefield);
    }

    /// <summary>
    /// "Except it has haste" is the whole of Kiki-Jiki, and it has to play (CR 707.9b).
    /// </summary>
    /// <remarks>
    /// The keyword arm of the exception grammar, asserted by attacking rather than by reading the
    /// keyword off the token. A copy that carried the word and not the permission would pass a
    /// characteristic check and be the wrong card at the only moment the card exists for - the
    /// combat it was made to join. The declaration is the assertion: without haste the engine
    /// refuses it outright (CR 302.6).
    /// <para>
    /// The printed card is <em>not</em> this ability. Kiki-Jiki ends "Sacrifice it at the
    /// beginning of the next end step", and that sentence is refused - see below.
    /// </para>
    /// </remarks>
    [Fact]
    public void An_except_clause_granting_haste_lets_the_token_attack_at_once()
    {
        var kiki = Card(
            "Token Copy Haste Test",
            "{T}: Create a token that's a copy of target nonlegendary creature you control, "
                + "except it has haste.",
            CardType.Creature,
            2,
            2);

        var compiled = CardCompiler.Compile(kiki);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var mirror = game.Create(alice, kiki, Zone.Battlefield);
        var bear = game.Create(
            alice, TestCards.Creature("Token Copy Hasty Bear Test", 3, 3), Zone.Battlefield);

        // Alice's next turn, so the permanent with the {T} ability may use it.
        PassTo(game, 3, TurnStep.PrecombatMain);

        var ability = Assert.Single(
            Game.ActivatedAbilitiesOf(game.State, Pool, game.State.GetObject(mirror)));

        game.ActivateAbility(alice, mirror, ability.Id, [Target.ToPermanent(bear)]);
        Settle(game);

        var token = TokenNamed(game, "Token Copy Hasty Bear Test");

        // The token was made this turn and attacks anyway, which only the exception can explain.
        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice, new Dictionary<ObjectId, AttackTarget> { [token] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Settle(game);

        Assert.Equal(17, game.State.GetPlayer(bob).Life);
    }

    /// <summary>
    /// "Sacrifice it" after a token copy means the token, and Kiki-Jiki's whole ability plays.
    /// </summary>
    /// <remarks>
    /// This asserted a <em>refusal</em> for one round, and the refusal existed only because the
    /// delayed vocabulary could not name a token. The pronoun ladder answered "it" with the
    /// target an earlier sentence chose, which on this card is the creature that was copied, so
    /// the compiled ability sacrificed the original at end of turn and let the token live for
    /// ever - two different cards, both of them not Kiki-Jiki, and the line read perfectly.
    /// <para>
    /// It can be named now, because the delay is folded into the effect that mints the token
    /// (<see cref="DelayedTokenAction"/>) rather than added beside it. So the card is played
    /// rather than refused, and both halves are asserted in the one game: the copy goes, and
    /// the creature it was copied from stays. Asserting only the first would pass on the old
    /// reading too, where something was sacrificed at end of turn and it was the wrong thing.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_delayed_sacrifice_after_a_token_copy_takes_the_token_and_not_what_it_copied()
    {
        var kiki = Card(
            "Token Copy Sacrifice Test",
            "{T}: Create a token that's a copy of target nonlegendary creature you control, "
                + "except it has haste. Sacrifice it at the beginning of the next end step.",
            CardType.Creature,
            2,
            2);

        var compiled = CardCompiler.Compile(kiki);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var mirror = game.Create(alice, kiki, Zone.Battlefield);
        var bear = game.Create(
            alice, TestCards.Creature("Token Copy Sacrifice Bear Test", 3, 3), Zone.Battlefield);

        // Alice's next turn, so the permanent with the {T} ability may use it.
        PassTo(game, 3, TurnStep.PrecombatMain);

        var ability = Assert.Single(
            Game.ActivatedAbilitiesOf(game.State, Pool, game.State.GetObject(mirror)));

        game.ActivateAbility(alice, mirror, ability.Id, [Target.ToPermanent(bear)]);
        Settle(game);

        var token = TokenNamed(game, "Token Copy Sacrifice Bear Test");

        TestCards.PassUntil(game, () => game.State.CurrentStep >= TurnStep.Cleanup);

        Assert.DoesNotContain(token, game.State.Battlefield);
        Assert.Contains(bear, game.State.Battlefield);
        Assert.Contains(mirror, game.State.Battlefield);
    }

    /// <summary>The control: a card whose "it" really is the permanent with the ability.</summary>
    /// <remarks>
    /// Nothing this ability does makes a token, so the fallback below the token arm is the only
    /// answer left and it is the right one. Kept beside the Kiki-Jiki game because the token arm
    /// sits in front of this fallback: a reader that took every delayed pronoun as a token would
    /// leave this creature on the battlefield for ever and no other test would notice.
    /// </remarks>
    [Fact]
    public void A_delayed_sacrifice_with_no_token_in_the_ability_still_means_the_source()
    {
        var brute = Card(
            "Token Copy Self Sacrifice Test",
            "When this creature enters, sacrifice it at the beginning of the next end step.",
            CardType.Creature,
            4,
            4);

        var compiled = CardCompiler.Compile(brute);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, brute);

        game.CastSpell(alice, card, []);
        Settle(game);

        var creature = game.State.Battlefield
            .Select(game.State.GetObject)
            .Single(o => o.Card.Name == "Token Copy Self Sacrifice Test");

        TestCards.PassUntil(game, () => game.State.CurrentStep >= TurnStep.Cleanup);

        Assert.DoesNotContain(creature.Id, game.State.Battlefield);
    }

    /// <summary>The one token on the battlefield copying this card.</summary>
    private static ObjectId TokenNamed(Game game, string name) =>
        game.State.Battlefield.Single(
            id => game.State.GetObject(id) is { } o
                && o.Card.Name == name
                && o.Card.CardTypes.HasFlag(CardType.Token));

    /// <summary>
    /// A count naming a seat the sentence chose is refused, not taken off the whole board
    /// (CR 109.5).
    /// </summary>
    /// <remarks>
    /// Found by the invariant suite, from one card this round completed. Curious Herd is
    /// "Choose target opponent. You create X 3/3 green Beast creature tokens, where X is the
    /// number of artifacts <em>that player</em> controls", and the moment it compiled the
    /// structural check said its target was chosen and never used. It was right, and the cause
    /// was older and wider than the line that exposed it: a counted group's filter is handed one
    /// player - the controller of what is counting - so a clause naming a seat only the
    /// resolution knows had nothing to compare against, and the filter answered true for
    /// <em>every</em> permanent.
    /// <para>
    /// <strong>Four cards were complete and playing a strictly better version of themselves.</strong>
    /// Anathemancer dealt damage equal to every nonbasic land on the battlefield rather than its
    /// target's; Emissary of Hope gained life for every artifact in play; Terra Ravager and
    /// Coastline Marauders each got +X/+0 for every land anybody controlled. All four now leave
    /// the line unread, which is this codebase's standing trade: a card that compiles and plays
    /// wrongly is worse than one a deck check can refuse.
    /// </para>
    /// <para>
    /// The refusal is exactly as wide as the defect. "An opponent controls" is answerable from
    /// the controller alone and still counts; only the two clauses that name a seat the sentence
    /// picked are refused.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_count_naming_a_seat_the_sentence_chose_is_left_unread()
    {
        var herd = Card(
            "Seat Count Herd Test",
            "Choose target opponent. You create X 3/3 green Beast creature tokens, "
                + "where X is the number of artifacts that player controls.",
            CardType.Sorcery);

        Assert.False(CardCompiler.Compile(herd).IsComplete);

        var ravager = Card(
            "Seat Count Ravager Test",
            "Whenever ~ attacks, it gets +X/+0 until end of turn, where X is the number of "
                + "lands defending player controls.",
            CardType.Creature,
            2,
            2);

        Assert.False(CardCompiler.Compile(ravager).IsComplete);

        // And the clauses a count *can* answer are untouched, which is what keeps this a refusal
        // of the unanswerable rather than of the possessive.
        var opponents = Card(
            "Seat Count Opponents Test",
            "You create X 3/3 green Beast creature tokens, where X is the number of artifacts "
                + "an opponent controls.",
            CardType.Sorcery);

        var counted = CardCompiler.Compile(opponents);
        Assert.True(counted.IsComplete, string.Join(" | ", counted.Unhandled));

        var (game, alice, bob) = InMainPhase();

        for (var i = 0; i < 3; i++)
        {
            game.Create(
                bob,
                Card(
                    "Seat Count Relic " + i.ToString(CultureInfo.InvariantCulture),
                    string.Empty,
                    CardType.Artifact),
                Zone.Battlefield);
        }

        game.CastSpell(alice, TestCards.PutInHand(game, alice, opponents), []);
        Settle(game);

        Assert.Equal(
            3,
            game.State.Battlefield.Select(game.State.GetObject).Count(o => o.Card.Name == "Beast"));
    }

    // ---- A token that carries the abilities its card granted it (CR 111.10, 707.9b) ----

    /// <summary>
    /// A token's granted abilities live on the token's own card definition, and nowhere else.
    /// </summary>
    /// <remarks>
    /// Three separate rounds arrived at this wall from three directions - a frame round that could
    /// read "As long as …, ~ has 'Q'" and declined the token frames, a copy round that could read
    /// every printed exception except the one granting a quoted ability, and a prohibition round
    /// that found its "can't block" family blocked by the token line rather than by the
    /// prohibition. All three wanted the same thing: somewhere on a token to put an ability the
    /// card gave it.
    /// <para>
    /// The answer is that there was already somewhere, and only half of it was reachable. A token
    /// <em>is</em> a <see cref="CardDefinition"/> and the pool compiles its text, so a granted
    /// ability is rules text - which is how a printed token card says it too. What was missing was
    /// a slot that could hold a keyword list <em>and</em> a quotation rather than one or the other,
    /// and, for a token that is a copy, an id that could tell the granted card from the card it
    /// copied. <c>CompiledPool</c> throws when two cards share an id with different text, which is
    /// exactly right, and is why the grant re-keys the definition.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_minted_token_plays_both_the_keyword_and_the_quoted_ability_it_was_granted()
    {
        var roost = Card(
            "Granted Token Roost Test",
            "When ~ enters, create a 1/1 white Bird creature token with flying and "
                + "\"Whenever this creature attacks, you gain 2 life.\"",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(roost);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, roost, Zone.Battlefield);
        Settle(game);

        var bird = game.State.Battlefield
            .Single(id => game.State.GetObject(id).Card.Name == "Bird");

        // The keyword half, off the computed characteristics rather than off the printed card:
        // an ability the sentence granted has to survive the whole layer pass to mean anything.
        Assert.True(Characteristics.Of(game.State, Pool, game.State.GetObject(bird))
            .Has(KeywordAbility.Flying));

        // And the quoted half, by playing it. A token carrying the words and not the ability
        // would pass every characteristic check and do nothing at the only moment it matters.
        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice, new Dictionary<ObjectId, AttackTarget> { [bird] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Settle(game);

        Assert.Equal(22, game.State.GetPlayer(alice).Life);
        Assert.Equal(19, game.State.GetPlayer(bob).Life);
    }

    /// <summary>
    /// Two quotations after one token are two abilities, not one (CR 111.10).
    /// </summary>
    /// <remarks>
    /// Pursued Whale's Pirate is printed this way - with "this creature can't block" and
    /// "Creatures you control attack each combat if able" - and a slot holding one quotation would
    /// have taken half the card while reporting the line read. Both halves are asserted from the
    /// game rather than from the parse: the prohibition off the computed characteristics, the
    /// trigger by attacking.
    /// </remarks>
    [Fact]
    public void A_token_granted_two_quoted_abilities_carries_both_of_them()
    {
        var whale = Card(
            "Granted Token Whale Test",
            "When ~ enters, create a 1/1 red Pirate creature token with "
                + "\"This creature can't block.\" and "
                + "\"Whenever this creature attacks, you gain 2 life.\"",
            CardType.Creature,
            power: 5,
            toughness: 5);

        var compiled = CardCompiler.Compile(whale);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, whale, Zone.Battlefield);
        Settle(game);

        var pirate = game.State.Battlefield
            .Single(id => game.State.GetObject(id).Card.Name == "Pirate");

        Assert.True(Characteristics.Of(game.State, Pool, game.State.GetObject(pirate))
            .Has(KeywordAbility.CantBlock));

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice, new Dictionary<ObjectId, AttackTarget> { [pirate] = AttackTarget.Player(bob) });

        Settle(game);

        Assert.Equal(22, game.State.GetPlayer(alice).Life);
    }

    /// <summary>
    /// "Except it has haste and 'Q'" grants the quotation to the copy (CR 707.9b).
    /// </summary>
    /// <remarks>
    /// The clause that had nowhere to go. A token copy keeps the copied card's oracle id on
    /// purpose, so that an ability source keyed by it serves abilities already compiled rather
    /// than compiling a second, equal card - and that is precisely what stopped the quotation
    /// being appended to the copy's rules text, because two cards under one id with different text
    /// is the one thing <c>CompiledPool</c> refuses. The grant therefore re-keys the card, and the
    /// assertions below are both halves of that: the token plays the granted trigger, and the card
    /// it copied still compiles as itself.
    /// <para>
    /// The clause splitter had to learn the rule three readers have now learnt: <strong>a join
    /// inside a quotation is not a join.</strong> It was cutting this exception into "it has
    /// haste" and two sentence fragments, none of which is a clause.
    /// </para>
    /// </remarks>
    [Fact]
    public void An_except_clause_granting_a_quoted_ability_puts_it_on_the_token()
    {
        var duplicator = Card(
            "Granted Copy Duplicator Test",
            "{T}: Create a token that's a copy of target creature you control, except it has "
                + "haste and \"Whenever this creature attacks, you gain 2 life.\"",
            CardType.Creature,
            2,
            2);

        var compiled = CardCompiler.Compile(duplicator);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var bearCard = TestCards.Creature("Granted Copy Bear Test", 3, 3);

        var (game, alice, bob) = InMainPhase();
        var mirror = game.Create(alice, duplicator, Zone.Battlefield);
        var bear = game.Create(alice, bearCard, Zone.Battlefield);

        PassTo(game, 3, TurnStep.PrecombatMain);

        var ability = Assert.Single(
            Game.ActivatedAbilitiesOf(game.State, Pool, game.State.GetObject(mirror)));

        game.ActivateAbility(alice, mirror, ability.Id, [Target.ToPermanent(bear)]);
        Settle(game);

        var token = TokenNamed(game, "Granted Copy Bear Test");

        // The copy is a card of its own as far as the pool is concerned, which is what lets it
        // carry text the card it copied does not have - and the card it copied is untouched.
        Assert.NotEqual(bearCard.OracleId, game.State.GetObject(token).Card.OracleId);
        Assert.Empty(Pool.TriggersOf(bearCard));
        Assert.Single(Pool.TriggersOf(game.State.GetObject(token).Card));

        // Both halves of the exception, played rather than read: haste lets it attack the turn it
        // was made, and the granted trigger is what pays for the attack.
        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice, new Dictionary<ObjectId, AttackTarget> { [token] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Settle(game);

        Assert.Equal(22, game.State.GetPlayer(alice).Life);
        Assert.Equal(17, game.State.GetPlayer(bob).Life);
    }

    /// <summary>
    /// A granted token may itself be copied, and its card has to survive the log (CR 707.3).
    /// </summary>
    /// <remarks>
    /// The journey a token definition has to make, end to end: it is minted with an ability its
    /// card granted it, copied - so the grant has to be one of the copy's copiable values, which
    /// it is because it lives on the definition rather than beside it - and folded back out of the
    /// event log. <c>AsToken</c> has been caught dropping a field on this journey once already,
    /// and the field it dropped (the faces) was invisible until a token could not turn over; a
    /// dropped grant would be invisible until a token quietly stopped triggering.
    /// <para>
    /// The round trip goes through <see cref="EventLogSerializer"/> rather than through
    /// <c>GameReducer.Replay</c> alone, because the two fail differently: a replay reads objects
    /// this process built, and only the serializer proves the definition survives being written
    /// down and read back.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_granted_token_keeps_its_ability_when_it_is_copied_and_when_the_log_is_reread()
    {
        var roost = Card(
            "Granted Token Reread Test",
            "When ~ enters, create a 1/1 white Bird creature token with flying and "
                + "\"Whenever this creature attacks, you gain 2 life.\"",
            CardType.Enchantment);

        var cloner = Card(
            "Granted Token Cloner Test",
            "{T}: Create a token that's a copy of target creature you control.",
            CardType.Creature,
            1,
            1);

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, roost, Zone.Battlefield);
        var mimic = game.Create(alice, cloner, Zone.Battlefield);
        Settle(game);

        var bird = game.State.Battlefield
            .Single(id => game.State.GetObject(id).Card.Name == "Bird");

        PassTo(game, 3, TurnStep.PrecombatMain);

        var ability = Assert.Single(
            Game.ActivatedAbilitiesOf(game.State, Pool, game.State.GetObject(mimic)));

        game.ActivateAbility(alice, mimic, ability.Id, [Target.ToPermanent(bird)]);
        Settle(game);

        var birds = game.State.Battlefield
            .Where(id => game.State.GetObject(id).Card.Name == "Bird")
            .ToList();

        Assert.Equal(2, birds.Count);

        // CR 707.3: the copy is made from what the permanent is now, and what it is now includes
        // the ability its card was granted - so both Birds trigger.
        PassTo(game, 5, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            birds.ToDictionary(id => id, _ => AttackTarget.Player(bob)));

        Settle(game);

        Assert.Equal(24, game.State.GetPlayer(alice).Life);

        // Written down and read back: the token's whole definition, granted text and re-keyed id,
        // has to come back the card it was or the replay is a different game.
        Assert.Equal(
            game.State,
            GameReducer.Replay(EventLogSerializer.Read(EventLogSerializer.Write(game.Log))));
    }

    // ---- An ability's own cost reduction (CR 601.2f, 602.2b) ------------------

    /// <summary>
    /// "This ability costs {1} less to activate for each Island you control" (CR 601.2f).
    /// </summary>
    /// <remarks>
    /// The sentence is not a line. Every one of the fifty-six corpus cards printing it writes it
    /// <em>inside</em> the ability it discounts, so the whole-line reader that gathers
    /// <c>CostModifier</c>s - which has read the rest of that grid for several rounds - is never
    /// offered it, and all fifty-six were unread. <c>CostModifier.SourceOnly</c> was built for
    /// exactly this wording and had never had a line to read.
    /// <para>
    /// Bob's Island is on the board to fail the reading that counts every Island there is. "You
    /// control" is the whole of the difference, and a discount that took his in would make the
    /// ability a mana cheaper than the card prints - which coverage scores as a win.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_counted_activation_discount_counts_only_what_its_controller_has()
    {
        var scroll = Card(
            "Costs Less Scroll Test",
            "{6}, {T}: Draw a card. This ability costs {1} less to activate for each Island you "
                + "control.",
            CardType.Artifact);

        var compiled = CardCompiler.Compile(scroll);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var artifact = game.Create(alice, scroll, Zone.Battlefield);

        game.Create(alice, TestCards.BasicLand("Island"), Zone.Battlefield);
        game.Create(alice, TestCards.BasicLand("Island"), Zone.Battlefield);
        game.Create(bob, TestCards.BasicLand("Island"), Zone.Battlefield);

        // {6} less two Islands is {4}, so three mana is one short. The refusal is the half that
        // matters: a discount read too widely still pays, and only the failure tells them apart.
        TapForestsFor(game, alice, 3);
        Assert.Throws<InvalidOperationException>(() => game.ActivateAbility(alice, artifact, "a"));

        TapForestsFor(game, alice, 1);

        var held = game.State.GetPlayer(alice).Hand.Count;
        game.ActivateAbility(alice, artifact, "a");
        Assert.True(game.State.GetPlayer(alice).ManaPool.IsEmpty);
        Settle(game);

        Assert.Equal(held + 1, game.State.GetPlayer(alice).Hand.Count);
    }

    /// <summary>
    /// The discount is the ability's own, and reaches no other permanent (CR 601.2f).
    /// </summary>
    /// <remarks>
    /// The failure this file exists to catch: read as "abilities you activate cost {1} less to
    /// activate" the sentence would discount everything its controller has, which is a strictly
    /// better card than the printed one and compiles just as cleanly. Two permanents with the
    /// same printed activation cost, one carrying the sentence and one not, is the smallest board
    /// that can tell those two readings apart.
    /// </remarks>
    [Fact]
    public void A_counted_activation_discount_reaches_no_other_permanents_ability()
    {
        var discounted = Card(
            "Costs Less Ledger Test",
            "{4}, {T}: Draw a card. This ability costs {1} less to activate for each Island you "
                + "control.",
            CardType.Artifact);

        var plain = Card("Costs Less Neighbour Test", "{4}, {T}: Draw a card.", CardType.Artifact);

        Assert.True(CardCompiler.Compile(discounted).IsComplete);
        Assert.True(CardCompiler.Compile(plain).IsComplete);

        var (game, alice, _) = InMainPhase();
        var ledger = game.Create(alice, discounted, Zone.Battlefield);
        var neighbour = game.Create(alice, plain, Zone.Battlefield);

        game.Create(alice, TestCards.BasicLand("Island"), Zone.Battlefield);
        game.Create(alice, TestCards.BasicLand("Island"), Zone.Battlefield);

        // {4} less two Islands is {2}, and the ledger pays it exactly.
        TapForestsFor(game, alice, 2);
        game.ActivateAbility(alice, ledger, "a");
        Assert.True(game.State.GetPlayer(alice).ManaPool.IsEmpty);
        Settle(game);

        // The permanent beside it prints the same {4} and no discount, so two mana is two short.
        TapForestsFor(game, alice, 2);
        Assert.Throws<InvalidOperationException>(
            () => game.ActivateAbility(alice, neighbour, "a"));

        TapForestsFor(game, alice, 2);
        game.ActivateAbility(alice, neighbour, "a");
        Assert.True(game.State.GetPlayer(alice).ManaPool.IsEmpty);
        Settle(game);
    }

    /// <summary>
    /// "This ability costs {1} less to activate for each page counter on this artifact."
    /// </summary>
    /// <remarks>
    /// The count that says which vocabulary this reader reaches. <c>EffectPhrase.Counting</c> is
    /// asked with a source, because an activation has the permanent in hand - and that is the
    /// whole difference from the spell-side reader beside it, which goes through
    /// <c>DefinedCount</c> with none and so cannot answer a phrase that points at a permanent at
    /// all. Four corpus cards count counters on themselves this way; a private copy of the
    /// counting vocabulary would have had to learn it again.
    /// </remarks>
    [Fact]
    public void A_counted_activation_discount_reads_the_sources_own_counters()
    {
        var diary = Card(
            "Costs Less Diary Test",
            "~ enters with three page counters on it.\n"
                + "{5}, {T}: Draw a card. This ability costs {1} less to activate for each page "
                + "counter on ~.",
            CardType.Artifact);

        var compiled = CardCompiler.Compile(diary);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();

        // The counters are a replacement rather than a trigger (CR 614.1c), so they are on
        // the permanent the moment it arrives and nothing has to resolve first.
        var book = game.Create(alice, diary, Zone.Battlefield);
        Assert.Equal(3, game.State.GetObject(book).Permanent!.Counters["page"]);

        // {5} less three counters is {2}. One mana is one short of that.
        TapForestsFor(game, alice, 1);
        Assert.Throws<InvalidOperationException>(() => game.ActivateAbility(alice, book, "a"));

        TapForestsFor(game, alice, 1);
        game.ActivateAbility(alice, book, "a");
        Assert.True(game.State.GetPlayer(alice).ManaPool.IsEmpty);
        Settle(game);
    }

    /// <summary>
    /// "This ability costs {2} less to activate if you control a legendary creature."
    /// </summary>
    /// <remarks>
    /// Fourteen corpus cards put a board question where the counted ones put a count, and the
    /// condition goes through the same <c>BoardConditions</c> vocabulary an "activate only if"
    /// restriction does. Both arms are played on one board: a condition that never held would
    /// pass the first half and a condition always true would pass the second.
    /// </remarks>
    [Fact]
    public void A_conditional_activation_discount_applies_only_while_the_condition_holds()
    {
        var herald = Card(
            "Costs Less Herald Test",
            "{4}, {T}: Draw a card. This ability costs {2} less to activate if you control a "
                + "legendary creature.",
            CardType.Artifact);

        var compiled = CardCompiler.Compile(herald);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var legend = new CardDefinition
        {
            OracleId = "oracle-costs-less-legend-test",
            Name = "Costs Less Legend Test",
            CardTypes = CardType.Creature,
            Supertypes = ["Legendary"],
            Power = 2,
            Toughness = 2,
        };

        var (game, alice, _) = InMainPhase();
        var first = game.Create(alice, herald, Zone.Battlefield);
        var second = game.Create(alice, herald, Zone.Battlefield);

        // No legendary creature yet, so the printed {4} stands and three mana is one short.
        TapForestsFor(game, alice, 3);
        Assert.Throws<InvalidOperationException>(() => game.ActivateAbility(alice, first, "a"));

        TapForestsFor(game, alice, 1);
        game.ActivateAbility(alice, first, "a");
        Assert.True(game.State.GetPlayer(alice).ManaPool.IsEmpty);
        Settle(game);

        // With one on the battlefield the same ability costs {2}, and one mana is one short.
        game.Create(alice, legend, Zone.Battlefield);

        TapForestsFor(game, alice, 1);
        Assert.Throws<InvalidOperationException>(() => game.ActivateAbility(alice, second, "a"));

        TapForestsFor(game, alice, 1);
        game.ActivateAbility(alice, second, "a");
        Assert.True(game.State.GetPlayer(alice).ManaPool.IsEmpty);
        Settle(game);
    }

    /// <summary>
    /// "Equip {3}. This ability costs {1} less to activate for each other Equipment you control."
    /// </summary>
    /// <remarks>
    /// Equip is the one activated ability printed without a colon, so it never reaches the reader
    /// that lifts this sentence for every other one - and both equip patterns are anchored whole,
    /// deliberately, so the trailing sentence left them matching nothing at all.
    /// <para>
    /// "Other" is the half this asserts. A count that took the Equipment itself in would discount
    /// the equip by a mana on an empty board, which is the printed card minus one - and the board
    /// with a second Equipment on it would still pay, so only the first half fails.
    /// </para>
    /// </remarks>
    [Fact]
    public void An_equip_ability_carries_its_own_discount_and_does_not_count_itself()
    {
        var plate = Card(
            "Costs Less Plate Test",
            "Equip {3}. This ability costs {1} less to activate for each other Equipment you "
                + "control.",
            CardType.Artifact,
            subtypes: "Equipment");

        var compiled = CardCompiler.Compile(plate);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var spare = Card(
            "Costs Less Spare Plate Test", "Equip {1}", CardType.Artifact, subtypes: "Equipment");

        var (game, alice, _) = InMainPhase();
        var armour = game.Create(alice, plate, Zone.Battlefield);
        var bearer = game.Create(
            alice, TestCards.Creature("Costs Less Bearer Test", 2, 2), Zone.Battlefield);

        // Nothing else on the board, so the Equipment must not count itself: {3} stands and two
        // mana is one short.
        TapForestsFor(game, alice, 2);
        Assert.Throws<InvalidOperationException>(
            () => game.ActivateAbility(alice, armour, "equip", [Target.ToPermanent(bearer)]));

        // One other Equipment takes it to {2}, which the two mana already in the pool pay.
        game.Create(alice, spare, Zone.Battlefield);
        game.ActivateAbility(alice, armour, "equip", [Target.ToPermanent(bearer)]);
        Assert.True(game.State.GetPlayer(alice).ManaPool.IsEmpty);
        Settle(game);

        Assert.Equal(bearer, game.State.GetObject(armour).Permanent!.AttachedTo);
    }

    /// <summary>
    /// A reduction takes generic mana and stops at {0} (CR 601.2f, 118.7a).
    /// </summary>
    /// <remarks>
    /// The two ways a discount can be wrong in the direction that makes a card cheaper than it
    /// prints, on one board. Five Islands against a {2}{W} ability is a reduction larger than the
    /// generic there is to take: the {2} goes, the {W} may not (CR 118.7a), and the remainder is
    /// not carried anywhere - a cost cannot be reduced below {0}.
    /// <para>
    /// Asserted from an empty pool first, because that is the assertion a cost wrongly floored at
    /// {0} fails and nothing else does; then with green mana, which cannot pay a white pip; then
    /// with white, which pays it exactly and leaves the green untouched.
    /// </para>
    /// </remarks>
    [Fact]
    public void An_activation_discount_cannot_take_a_coloured_pip_or_pass_below_zero()
    {
        var pip = Card(
            "Costs Less Pip Test",
            "{2}{W}, {T}: Draw a card. This ability costs {1} less to activate for each Island "
                + "you control.",
            CardType.Artifact);

        var compiled = CardCompiler.Compile(pip);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var relic = game.Create(alice, pip, Zone.Battlefield);

        foreach (var _ in Enumerable.Range(0, 5))
            game.Create(alice, TestCards.BasicLand("Island"), Zone.Battlefield);

        // Five off {2}{W} is not {0}: the pip survives, so an empty pool cannot pay it.
        Assert.Throws<InvalidOperationException>(() => game.ActivateAbility(alice, relic, "a"));

        // Nor can green.
        TapForestsFor(game, alice, 1);
        Assert.Throws<InvalidOperationException>(() => game.ActivateAbility(alice, relic, "a"));

        var plains = game.Create(alice, TestCards.BasicLand("Plains"), Zone.Battlefield);
        game.ActivateAbility(alice, plains, "mana");
        game.ActivateAbility(alice, relic, "a");

        // Exactly the white was spent. The green is still there, which is what says the total
        // was {W} and not {W} plus whatever the reduction failed to take off.
        Assert.Equal(1, game.State.GetPlayer(alice).ManaPool.Total);
        Settle(game);
    }

    /// <summary>Creates that many Forests and taps each of them for {G}.</summary>
    /// <remarks>
    /// The cost tests above are about what a price comes to, so the mana behind them has to be
    /// exact and countable. Making the land here rather than up front keeps each test's board to
    /// the permanents it is actually about.
    /// </remarks>
    private static void TapForestsFor(Game game, Guid who, int howMany)
    {
        foreach (var _ in Enumerable.Range(0, howMany))
        {
            var forest = game.Create(who, TestCards.BasicLand("Forest"), Zone.Battlefield);
            game.ActivateAbility(who, forest, "mana");
        }
    }

    // ---- Cases (CR 719) ------------------------------------------------------

    /// <summary>
    /// A Case solves at the end step once its condition holds, and not before (CR 719.3a).
    /// </summary>
    /// <remarks>
    /// The anthem under "Solved -" is what makes the designation visible from outside. Asserting
    /// it is <em>absent</em> first is the half that matters: a Case whose solved ability worked
    /// from the moment it entered would pass every test that only looked at the end.
    /// <para>
    /// It also has to solve at the end step rather than the instant the condition becomes true -
    /// CR 719.3a is a triggered ability, not a state trigger - so the third artifact arrives and
    /// nothing happens until the turn is nearly over.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_Case_solves_at_your_end_step_and_not_before()
    {
        var investigation = Card(
            "Test Case File",
            "To solve \u2014 You control three or more artifacts.\n"
                + "Solved \u2014 Creatures you control get +1/+1.",
            CardType.Enchantment,
            null,
            null,
            KeywordAbility.None,
            "Case");

        var compiled = CardCompiler.Compile(investigation);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var bear = game.Create(alice, TestCards.Creature("Test Case Bear", 2, 2), Zone.Battlefield);
        var card = TestCards.PutInHand(game, alice, investigation);

        game.CastSpell(alice, card, []);
        Settle(game);

        var file = game.State.Battlefield
            .Single(id => game.State.GetObject(id).Card.Name == "Test Case File");

        Assert.False(game.State.GetObject(file).Permanent!.IsSolved);
        Assert.Equal(2, Characteristics.Of(game.State, Pool, game.State.GetObject(bear)).Power);

        for (var i = 0; i < 3; i++)
        {
            game.Create(
                alice,
                Card(
                    "Test Case Relic " + i.ToString(System.Globalization.CultureInfo.InvariantCulture),
                    string.Empty,
                    CardType.Artifact),
                Zone.Battlefield);
        }

        Settle(game);

        // The condition holds, and the Case is still unsolved: it is a trigger, not a state
        // trigger, and its moment has not come.
        Assert.False(game.State.GetObject(file).Permanent!.IsSolved);

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.End);
        Settle(game);

        Assert.True(game.State.GetObject(file).Permanent!.IsSolved);
        Assert.Equal(3, Characteristics.Of(game.State, Pool, game.State.GetObject(bear)).Power);
    }
    // ---- Who is being attacked, and the player an Aura is on (CR 508.1b, 303.4b) ----

    /// <summary>
    /// "Whenever a creature attacks you" is about the player, not about the attack.
    /// </summary>
    /// <remarks>
    /// An attack is declared against a particular player or a planeswalker they control
    /// (CR 508.1b), and the declaration has carried that all along — only the sentence had
    /// nowhere to say it, so "whenever a creature attacks" was read and "whenever a creature
    /// attacks you" was not. At two seats the difference is invisible, because the only player
    /// anybody can attack is the one who is not attacking; it takes three to see an attack that
    /// this enchantment must not notice.
    /// </remarks>
    [Fact]
    public void An_attack_trigger_that_names_you_ignores_an_attack_on_another_player()
    {
        var watch = Card(
            "Hissing Watch Test",
            "Whenever a creature attacks you, its controller loses 1 life.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(watch);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, seats) = FourPlayers();
        game.Create(seats[0], watch, Zone.Battlefield);

        var raider = game.Create(
            seats[1], TestCards.Creature("Watch Raider Test", 2, 2), Zone.Battlefield);

        var rider = game.Create(
            seats[2], TestCards.Creature("Watch Rider Test", 2, 2), Zone.Battlefield);

        // Seat 1 attacks seat 2. The enchantment belongs to seat 0 and nothing about this attack
        // is its business.
        TestCards.PassUntil(
            game,
            () => game.State.ActivePlayerId == seats[1]
                && game.State.CurrentStep == TurnStep.DeclareAttackers);

        var raidersLife = game.State.GetPlayer(seats[1]).Life;

        game.DeclareAttackers(
            seats[1],
            new Dictionary<ObjectId, AttackTarget> { [raider] = AttackTarget.Player(seats[2]) });

        Settle(game);
        Assert.Equal(raidersLife, game.State.GetPlayer(seats[1]).Life);

        // Seat 2 attacks the enchantment's controller, and pays for it.
        TestCards.PassUntil(
            game,
            () => game.State.ActivePlayerId == seats[2]
                && game.State.CurrentStep == TurnStep.DeclareAttackers);

        var ridersLife = game.State.GetPlayer(seats[2]).Life;

        game.DeclareAttackers(
            seats[2],
            new Dictionary<ObjectId, AttackTarget> { [rider] = AttackTarget.Player(seats[0]) });

        Settle(game);

        // "Its controller" is the attacking creature's controller, which is neither the player
        // being attacked nor the one who owns the enchantment.
        Assert.Equal(ridersLife - 1, game.State.GetPlayer(seats[2]).Life);
    }

    /// <summary>
    /// "Attacks you" and "attacks you or a planeswalker you control" are two different triggers.
    /// </summary>
    /// <remarks>
    /// A creature attacking a planeswalker is not attacking its controller (CR 508.1b), which is
    /// exactly why eight corpus cards print the longer phrase. Both are on the board at once here
    /// because the claim is a difference between them, and one enchantment can only show half of
    /// it.
    /// </remarks>
    [Fact]
    public void An_attack_trigger_naming_a_planeswalker_fires_where_the_bare_one_does_not()
    {
        var bare = Card(
            "Bare Watch Test",
            "Whenever a creature attacks you, you gain 1 life.",
            CardType.Enchantment);

        var wider = Card(
            "Wide Watch Test",
            "Whenever a creature attacks you or a planeswalker you control, put a +1/+1 counter on ~.",
            CardType.Enchantment);

        var bareRead = CardCompiler.Compile(bare);
        Assert.True(bareRead.IsComplete, string.Join(" | ", bareRead.Unhandled));

        var widerRead = CardCompiler.Compile(wider);
        Assert.True(widerRead.IsComplete, string.Join(" | ", widerRead.Unhandled));

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, bare, Zone.Battlefield);
        var watched = game.Create(alice, wider, Zone.Battlefield);
        var walker = game.Create(
            alice, Walker("Watch Walker Test", 5, string.Empty), Zone.Battlefield);

        var attacker = game.Create(
            bob, TestCards.Creature("Watch Attacker Test", 2, 2), Zone.Battlefield);

        PassTo(game, 2, TurnStep.DeclareAttackers);

        var life = game.State.GetPlayer(alice).Life;

        game.DeclareAttackers(
            bob,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.At(alice, walker) });

        Settle(game);

        Assert.Equal(life, game.State.GetPlayer(alice).Life);
        Assert.Equal(
            1,
            game.State.GetObject(watched).Permanent!.Counters
                .GetValueOrDefault(CounterKinds.PlusOnePlusOne));
    }

    /// <summary>
    /// A Curse watches the player it is on, from a seat that is nobody's opponent in particular.
    /// </summary>
    /// <remarks>
    /// CR 303.4b: the player an Aura is attached to is "enchanted player", and the whole Curse
    /// family is written about them. The Aura's controller is a third party to the attack it
    /// notices, so this cannot be spelled with "you" or with "an opponent" — which is why the
    /// relation had to reach the trigger grammar rather than being reworded into it.
    /// </remarks>
    [Fact]
    public void A_curse_fires_for_an_attack_on_the_player_it_is_attached_to()
    {
        var curse = Card(
            "Forsaken Curse Test",
            "Enchant player\n"
                + "Whenever a creature attacks enchanted player, its controller gains 1 life.",
            CardType.Enchantment,
            subtypes: "Aura");

        var compiled = CardCompiler.Compile(curse);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, seats) = FourPlayers();

        var card = TestCards.PutInHand(game, seats[0], curse);
        game.CastSpell(seats[0], card, [Target.ToPlayer(seats[1])]);
        Settle(game);

        var rider = game.Create(
            seats[2], TestCards.Creature("Forsaken Rider Test", 2, 2), Zone.Battlefield);

        var raider = game.Create(
            seats[3], TestCards.Creature("Forsaken Raider Test", 2, 2), Zone.Battlefield);

        // Seat 2 attacks the Curse's controller, which is not the player it is on.
        TestCards.PassUntil(
            game,
            () => game.State.ActivePlayerId == seats[2]
                && game.State.CurrentStep == TurnStep.DeclareAttackers);

        var ridersLife = game.State.GetPlayer(seats[2]).Life;

        game.DeclareAttackers(
            seats[2],
            new Dictionary<ObjectId, AttackTarget> { [rider] = AttackTarget.Player(seats[0]) });

        Settle(game);
        Assert.Equal(ridersLife, game.State.GetPlayer(seats[2]).Life);

        // Seat 3 attacks the enchanted player, and is paid for it.
        TestCards.PassUntil(
            game,
            () => game.State.ActivePlayerId == seats[3]
                && game.State.CurrentStep == TurnStep.DeclareAttackers);

        var raidersLife = game.State.GetPlayer(seats[3]).Life;

        game.DeclareAttackers(
            seats[3],
            new Dictionary<ObjectId, AttackTarget> { [raider] = AttackTarget.Player(seats[1]) });

        Settle(game);
        Assert.Equal(raidersLife + 1, game.State.GetPlayer(seats[3]).Life);
    }

    /// <summary>
    /// The same relation on the damage verb: "deals combat damage to enchanted player".
    /// </summary>
    /// <remarks>
    /// The recipient was on the damage event all along (CR 510.2) and the sentence could not name
    /// anyone but "a player", so a Curse of Stalked Prey would have rewarded a creature for
    /// connecting with anybody at all — including the Curse's own controller.
    /// </remarks>
    [Fact]
    public void A_curse_reads_combat_damage_dealt_to_the_player_it_is_attached_to()
    {
        var curse = Card(
            "Stalked Curse Test",
            "Enchant player\n"
                + "Whenever a creature deals combat damage to enchanted player, "
                + "put a +1/+1 counter on that creature.",
            CardType.Enchantment,
            subtypes: "Aura");

        var compiled = CardCompiler.Compile(curse);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, seats) = FourPlayers();

        var card = TestCards.PutInHand(game, seats[0], curse);
        game.CastSpell(seats[0], card, [Target.ToPlayer(seats[1])]);
        Settle(game);

        var wrong = game.Create(
            seats[2], TestCards.Creature("Stalked Wrong Test", 2, 2), Zone.Battlefield);

        var right = game.Create(
            seats[3], TestCards.Creature("Stalked Right Test", 2, 2), Zone.Battlefield);

        TestCards.PassUntil(
            game,
            () => game.State.ActivePlayerId == seats[2]
                && game.State.CurrentStep == TurnStep.DeclareAttackers);

        game.DeclareAttackers(
            seats[2],
            new Dictionary<ObjectId, AttackTarget> { [wrong] = AttackTarget.Player(seats[0]) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Settle(game);

        Assert.Equal(
            0,
            game.State.GetObject(wrong).Permanent!.Counters
                .GetValueOrDefault(CounterKinds.PlusOnePlusOne));

        TestCards.PassUntil(
            game,
            () => game.State.ActivePlayerId == seats[3]
                && game.State.CurrentStep == TurnStep.DeclareAttackers);

        game.DeclareAttackers(
            seats[3],
            new Dictionary<ObjectId, AttackTarget> { [right] = AttackTarget.Player(seats[1]) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Settle(game);

        Assert.Equal(
            1,
            game.State.GetObject(right).Permanent!.Counters
                .GetValueOrDefault(CounterKinds.PlusOnePlusOne));
    }

    /// <summary>
    /// "A creature enchanted player controls" — the possessive, one relation further out.
    /// </summary>
    /// <remarks>
    /// The trigger grammar could say "you control" and "an opponent controls"; a Curse's group is
    /// neither, because the player it describes is decided when the Aura is attached and not by
    /// who is playing it. Trespasser's Curse is the printed card.
    /// </remarks>
    [Fact]
    public void A_curse_describes_the_permanents_the_enchanted_player_controls()
    {
        var curse = Card(
            "Trespass Curse Test",
            "Enchant player\n"
                + "Whenever a creature enchanted player controls enters, "
                + "that player loses 1 life and you gain 1 life.",
            CardType.Enchantment,
            subtypes: "Aura");

        var compiled = CardCompiler.Compile(curse);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, seats) = FourPlayers();

        var card = TestCards.PutInHand(game, seats[0], curse);
        game.CastSpell(seats[0], card, [Target.ToPlayer(seats[1])]);
        Settle(game);

        var casterLife = game.State.GetPlayer(seats[0]).Life;
        var enchantedLife = game.State.GetPlayer(seats[1]).Life;

        // Somebody else's creature arrives, and the Curse is about one player's board only.
        game.Create(seats[2], TestCards.Creature("Trespass Stranger Test", 2, 2), Zone.Battlefield);
        Settle(game);

        Assert.Equal(casterLife, game.State.GetPlayer(seats[0]).Life);
        Assert.Equal(enchantedLife, game.State.GetPlayer(seats[1]).Life);

        game.Create(seats[1], TestCards.Creature("Trespass Guest Test", 2, 2), Zone.Battlefield);
        Settle(game);

        // "That player" is the one the trigger was about, and here that is the enchanted player
        // because the creature that arrived is theirs.
        Assert.Equal(enchantedLife - 1, game.State.GetPlayer(seats[1]).Life);
        Assert.Equal(casterLife + 1, game.State.GetPlayer(seats[0]).Life);
    }

    /// <summary>
    /// "Enchanted player" as the subject of an ordinary sentence, through the shared vocabulary.
    /// </summary>
    /// <remarks>
    /// Every verb that takes a player takes this one, because it is a word in the player list
    /// rather than a matcher of its own — the same reason "each opponent" costs nothing per verb.
    /// Fraying Sanity and Volrath's Motion Sensor are the printed cards that write it this way.
    /// </remarks>
    [Fact]
    public void The_shared_player_vocabulary_names_the_player_an_aura_is_attached_to()
    {
        var curse = Card(
            "Fraying Curse Test",
            "Enchant player\nAt the beginning of your end step, enchanted player mills two cards.",
            CardType.Enchantment,
            subtypes: "Aura");

        var compiled = CardCompiler.Compile(curse);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();

        var card = TestCards.PutInHand(game, alice, curse);
        game.CastSpell(alice, card, [Target.ToPlayer(bob)]);
        Settle(game);

        var mine = game.State.GetPlayer(alice).Graveyard.Count;
        var theirs = game.State.GetPlayer(bob).Graveyard.Count;

        // The Aura controller's own end step, on the turn it was cast: no draw and no cleanup
        // discard happens in between, so every card that reaches a graveyard here was milled.
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.End);
        Settle(game);

        // The clock is the Aura's controller's and the mill is the enchanted player's — the two
        // halves of the sentence name different people, and the card is only right if both do.
        Assert.Equal(mine, game.State.GetPlayer(alice).Graveyard.Count);
        Assert.Equal(theirs + 2, game.State.GetPlayer(bob).Graveyard.Count);
    }

    /// <summary>
    /// "It" in an attack trigger is the creature that attacked, not the card that said so.
    /// </summary>
    /// <remarks>
    /// The pronoun order is written down — the target the sentence before chose, then the object
    /// the trigger was about, then the permanent with the ability — and the pump verb was missing
    /// its middle answer. Briar Patch is the card that shows it: "whenever a creature attacks
    /// you, it gets -1/-0" shrank the enchantment, which is not a creature, so the card compiled
    /// complete and did nothing whatsoever.
    /// </remarks>
    [Fact]
    public void A_pronoun_in_an_attack_trigger_means_the_attacker_and_not_the_enchantment()
    {
        var patch = Card(
            "Bramble Patch Test",
            "Whenever a creature attacks you, it gets -1/-0 until end of turn.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(patch);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, patch, Zone.Battlefield);

        var attacker = game.Create(
            bob, TestCards.Creature("Bramble Attacker Test", 2, 2), Zone.Battlefield);

        PassTo(game, 2, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            bob,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(alice) });

        Settle(game);

        Assert.Equal(
            1,
            Characteristics.Of(game.State, Pool, game.State.GetObject(attacker)).Power);
    }

    /// <summary>
    /// The batched damage event cannot say who took the damage, so the plural sentence is refused.
    /// </summary>
    /// <remarks>
    /// "One or more creatures deal combat damage to a player" fires once for the whole damage
    /// step, and the event that makes that possible records who dealt the damage and not who took
    /// it. A trigger that fired for damage dealt to anybody would be a strictly better card than
    /// the one printed, so the recipient is admitted on the singular sentence only.
    /// </remarks>
    [Fact]
    public void A_batched_combat_damage_trigger_that_names_a_recipient_is_left_unread()
    {
        var batched = Card(
            "Batched Watch Test",
            "Whenever one or more creatures deal combat damage to you, you gain 2 life.",
            CardType.Enchantment);

        Assert.False(CardCompiler.Compile(batched).IsComplete);

        // The same sentence without a recipient is read, so the refusal is about the recipient
        // and not about the plural.
        var anybody = Card(
            "Batched Anybody Test",
            "Whenever one or more creatures deal combat damage to a player, you gain 2 life.",
            CardType.Enchantment);

        Assert.True(CardCompiler.Compile(anybody).IsComplete);
    }

    // ---- Source-scoped groups and grants (CR 613.1b, 613.8) -------------------

    /// <summary>
    /// "Creatures enchanted player controls get -1/-1" — a group defined by the source's own
    /// attachment (CR 303.4), not by anybody's seat.
    /// </summary>
    /// <remarks>
    /// Four seats, because at two players "enchanted player controls" and "an opponent controls"
    /// pick out the same person and a filter that read the wrong relation would pass. The
    /// bystander's untouched bear is what carries the test.
    /// </remarks>
    [Fact]
    public void A_curse_shrinks_only_the_creatures_the_enchanted_player_controls()
    {
        var curse = Card(
            "Deaths Hold Curse Test",
            "Enchant player\nCreatures enchanted player controls get -1/-1.",
            CardType.Enchantment,
            subtypes: "Aura");

        var compiled = CardCompiler.Compile(curse);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, seats) = FourPlayers();

        var casters = game.Create(
            seats[0], TestCards.Creature("Caster Bear Test", 2, 2), Zone.Battlefield);
        var held = game.Create(
            seats[1], TestCards.Creature("Held Bear Test", 2, 2), Zone.Battlefield);
        var frail = game.Create(
            seats[1], TestCards.Creature("Frail Goat Test", 1, 1), Zone.Battlefield);
        var bystanders = game.Create(
            seats[2], TestCards.Creature("Bystander Bear Test", 2, 2), Zone.Battlefield);

        game.CastSpell(
            seats[0], TestCards.PutInHand(game, seats[0], curse), [Target.ToPlayer(seats[1])]);
        Settle(game);

        // The 1/1 died to the shrink (CR 704.5f) — the effect reached the game, not only the
        // characteristics read below.
        Assert.Contains(
            game.State.GetPlayer(seats[1]).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Frail Goat Test");
        Assert.DoesNotContain(frail, game.State.Battlefield);

        Assert.Equal(1, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(held)));

        // The caster's own creature and the third seat's — an opponent of the caster, and not
        // the enchanted player — are untouched. Either wrong relation fails here.
        Assert.Equal(2, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(casters)));
        Assert.Equal(
            2, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(bystanders)));
    }

    /// <summary>
    /// A stolen lord buffs its thief's creatures and stops buffing its old controller's
    /// (CR 613.1b) — and two lords on one battlefield do not loop (CR 613.8).
    /// </summary>
    /// <remarks>
    /// The board is the loop hazard on purpose. A lord's filter needs its own controller, and
    /// the obvious fix — computing the source's full characteristics from inside the layers —
    /// recurses without bottom the moment two lords can see each other: computing either lord
    /// applies the other's effect, whose filter computes the first again. Under that
    /// implementation this test does not fail an assertion, it kills the test host. The engine
    /// answers the controller question from layer 2 alone, which nothing after layer 2 changes.
    /// <para>
    /// The theft is the recorded stolen-lord defect: the filter read the controller stored on
    /// the object, which is only where control started, so a Threaten on a lord moved every
    /// creature it pumps except its own.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_stolen_lord_buffs_its_new_controllers_creatures_and_two_lords_do_not_loop()
    {
        var mine = Card(
            "Marching Lord Test", "Creatures you control get +1/+1.", CardType.Creature, 2, 2);
        var theirs = Card(
            "Rallying Lord Test", "Creatures you control get +1/+1.", CardType.Creature, 2, 2);
        var theft = Card(
            "Lord Theft Test",
            "Gain control of target creature until end of turn. Untap that creature. "
                + "It gains haste until end of turn.");

        Assert.True(CardCompiler.Compile(mine).IsComplete);
        Assert.True(CardCompiler.Compile(theirs).IsComplete);
        Assert.True(CardCompiler.Compile(theft).IsComplete);

        var (game, alice, bob) = InMainPhase();
        var marching = game.Create(alice, mine, Zone.Battlefield);
        var myBear = game.Create(
            alice, TestCards.Creature("Marching Bear Test", 2, 2), Zone.Battlefield);
        var rallying = game.Create(bob, theirs, Zone.Battlefield);
        var theirBear = game.Create(
            bob, TestCards.Creature("Rallying Bear Test", 2, 2), Zone.Battlefield);

        // Two lords, each pumping only its own side — and the computation terminating at all is
        // half the claim.
        Assert.Equal(3, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(myBear)));
        Assert.Equal(
            3, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(theirBear)));

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, theft), [Target.ToPermanent(rallying)]);
        Settle(game);

        // The stolen lord pumps Alice's side now: her bear stands under both lords, Bob's under
        // none, and the lord itself — a creature its new controller controls — is in its own
        // group and her other lord's.
        Assert.Equal(4, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(myBear)));
        Assert.Equal(
            2, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(theirBear)));
        Assert.Equal(
            4, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(rallying)));
        Assert.Equal(
            4, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(marching)));

        // Until end of turn (CR 611.2a): the theft ends at cleanup and the lord goes home.
        TestCards.PassUntil(
            game,
            () => game.State.ActivePlayerId == bob
                && game.State.CurrentStep == TurnStep.PrecombatMain);

        Assert.Equal(3, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(myBear)));
        Assert.Equal(
            3, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(theirBear)));
    }

    /// <summary>
    /// "It gets an additional +1/+0" is the pump it says — every 7c bonus is additional
    /// (CR 613.4c) — and the condition is asked of the host.
    /// </summary>
    [Fact]
    public void An_additional_bonus_applies_while_the_equipped_creature_answers_the_condition()
    {
        var censer = Card(
            "Faith Censer Test",
            "Equipped creature gets +1/+1 and has vigilance.\n"
                + "As long as equipped creature is a Human, it gets an additional +1/+0.\n"
                + "Equip {2}",
            CardType.Artifact,
            subtypes: "Equipment");

        var compiled = CardCompiler.Compile(censer);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var relic = game.Create(alice, censer, Zone.Battlefield);
        var human = game.Create(
            alice,
            Card("Censer Human Test", string.Empty, CardType.Creature, 2, 2,
                KeywordAbility.None, "Human", "Soldier"),
            Zone.Battlefield);
        var bear = game.Create(
            alice, TestCards.Creature("Censer Bear Test", 2, 2), Zone.Battlefield);

        game.Attach(relic, human);
        Settle(game);

        var faithful = Characteristics.Of(game.State, Pool, game.State.GetObject(human));
        Assert.Equal(4, faithful.Power);
        Assert.Equal(3, faithful.Toughness);

        // On a creature that is not a Human, only the unconditional line applies — a reader
        // that dropped the condition with the word "additional" would give 4 here too.
        game.Attach(relic, bear);
        Settle(game);

        Assert.Equal(3, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(bear)));
        Assert.Equal(2, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(human)));
    }

    /// <summary>
    /// A granted ward taxes and counters like the printed keyword (CR 702.21a).
    /// </summary>
    /// <remarks>
    /// Granting ward was measured inert once — the spell resolved untaxed and no question was
    /// asked — and reverted rather than shipped, so the assertions here are the question being
    /// asked at all and the counter landing when it is declined. The lord itself is the "other"
    /// control: a grant that leaked onto its own source would tax the second bolt too.
    /// </remarks>
    [Fact]
    public void A_granted_ward_taxes_an_opponents_spell_and_counters_it_when_unpaid()
    {
        var herald = Card(
            "Ward Herald Test",
            "Other creatures you control have ward {2}.",
            CardType.Creature,
            3,
            3);

        var compiled = CardCompiler.Compile(herald);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var lord = game.Create(alice, herald, Zone.Battlefield);
        var shielded = game.Create(
            alice, TestCards.Creature("Ward Shielded Bear Test", 2, 2), Zone.Battlefield);

        TestCards.PassUntil(
            game,
            () => game.State.ActivePlayerId == bob
                && game.State.CurrentStep == TurnStep.PrecombatMain);

        // Two mana floating, so that declining is a decision. An offer nobody can afford is not
        // put to the player at all — the engine runs the "if you don't" branch straight away
        // (CR 118.3), which counters the spell without ever asking, and a pool-less Bob would
        // have proved the counter while proving nothing about the question.
        var rock = Card("Ward Probe Peak Test", "{T}: Add {C}.", CardType.Land);
        game.ActivateAbility(bob, game.Create(bob, rock, Zone.Battlefield), "mana");
        game.ActivateAbility(bob, game.Create(bob, rock, Zone.Battlefield), "mana");

        var bolt = Card("Ward Probe Bolt Test", "~ deals 3 damage to any target.");
        game.CastSpell(
            bob, TestCards.PutInHand(game, bob, bolt), [Target.ToPermanent(shielded)]);

        // The granted trigger fires and asks the player who aimed the spell, exactly as a
        // printed ward would.
        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.OptionalPayment });
        Assert.Equal(bob, game.State.Choice!.PlayerId);

        game.Choose(bob, ["no"]);
        Settle(game);

        // Unpaid, the spell is countered: the bear stands, the bolt is in its owner's graveyard.
        Assert.Contains(shielded, game.State.Battlefield);
        Assert.Contains(
            game.State.GetPlayer(bob).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Ward Probe Bolt Test");

        // "Other creatures" leaves the herald itself outside its own grant: the second bolt is
        // never taxed and kills it. Settling handed priority on, so it is taken back first.
        TestCards.PassUntil(game, () => game.State.Priority.Holder == bob);

        var second = Card("Ward Second Bolt Test", "~ deals 3 damage to any target.");
        game.CastSpell(bob, TestCards.PutInHand(game, bob, second), [Target.ToPermanent(lord)]);
        Settle(game);

        Assert.DoesNotContain(lord, game.State.Battlefield);
        Assert.Contains(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Ward Herald Test");
    }

    /// <summary>
    /// The printed mana ward beside the granted one — the neighbouring wording as a control,
    /// and the paying branch of the same question.
    /// </summary>
    [Fact]
    public void The_printed_ward_cost_is_paid_in_mana_and_the_spell_resolves()
    {
        var sentinel = Card(
            "Ward Cost Sentinel Test", "Ward {2}", CardType.Creature, 2, 2);

        var compiled = CardCompiler.Compile(sentinel);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var warded = game.Create(alice, sentinel, Zone.Battlefield);

        TestCards.PassUntil(
            game,
            () => game.State.ActivePlayerId == bob
                && game.State.CurrentStep == TurnStep.PrecombatMain);

        // A printed mana ability rather than TestCards.BasicLand: a basic land's mana comes from
        // its subtype, so a uniquely named "basic" has no ability at all and the activation
        // throws before the ward is ever asked.
        var rock = Card("Ward Peak Test", "{T}: Add {C}.", CardType.Land);
        var one = game.Create(bob, rock, Zone.Battlefield);
        var two = game.Create(bob, rock, Zone.Battlefield);
        game.ActivateAbility(bob, one, "mana");
        game.ActivateAbility(bob, two, "mana");

        var bolt = Card("Ward Paid Bolt Test", "~ deals 3 damage to any target.");
        game.CastSpell(bob, TestCards.PutInHand(game, bob, bolt), [Target.ToPermanent(warded)]);

        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.OptionalPayment });
        Assert.Equal(bob, game.State.Choice!.PlayerId);

        game.Choose(bob, ["yes"]);
        Settle(game);

        // Paid, the spell does its work — and the tax actually left the pool.
        Assert.DoesNotContain(warded, game.State.Battlefield);
        Assert.True(game.State.GetPlayer(bob).ManaPool.IsEmpty);
    }

    /// <summary>
    /// "Enchanted creature gets +2/+2 and is goaded" — the Impetus cycle. Goaded is a
    /// designation with a player in it (CR 701.15b), and the static form lasts exactly as long
    /// as the attachment.
    /// </summary>
    [Fact]
    public void An_impetus_goads_its_host_for_as_long_as_it_is_attached()
    {
        var impetus = Card(
            "Shiny Impetus Test",
            "Enchant creature\nEnchanted creature gets +2/+2 and is goaded.",
            CardType.Enchantment,
            subtypes: "Aura");

        var compiled = CardCompiler.Compile(impetus);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, seats) = FourPlayers();
        var (alice, bob, carol) = (seats[0], seats[1], seats[2]);

        // Hasty, like the goad-verb test's bear next door: the question here is who the goad
        // takes off the menu, and a creature that arrived this turn is refused every attack for
        // a reason that has nothing to do with goad (CR 302.6).
        var bear = game.Create(
            bob,
            Card("Impetus Bear Test", string.Empty, CardType.Creature, 2, 2, KeywordAbility.Haste),
            Zone.Battlefield);

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, impetus), [Target.ToPermanent(bear)]);
        Settle(game);

        var goaded = Characteristics.Of(game.State, Pool, game.State.GetObject(bear));
        Assert.Equal(4, goaded.Power);
        Assert.True(goaded.Has(KeywordAbility.MustAttack));

        // Goaded *by the Aura's controller*: Alice is off the menu while anybody else is on it
        // (CR 701.15b), which is why this needs four seats.
        Assert.Contains(alice, goaded.GoadedBy);
        Assert.NotNull(CombatRules.CannotAttack(
            game.State, Pool, game.State.GetObject(bear), bob, alice));
        Assert.Null(CombatRules.CannotAttack(
            game.State, Pool, game.State.GetObject(bear), bob, carol));

        // The static ends with the attachment — no duration, no memory. The goad verb's
        // floating effect would keep this true until the goader's next turn; the Aura's stops
        // the moment it leaves.
        var aura = game.State.Battlefield
            .Select(id => game.State.GetObject(id))
            .Single(o => o.Card.Name == "Shiny Impetus Test").Id;

        game.Move(aura, Zone.Graveyard, MoveCause.Destroy);
        Settle(game);

        var released = Characteristics.Of(game.State, Pool, game.State.GetObject(bear));
        Assert.Equal(2, released.Power);
        Assert.Empty(released.GoadedBy);
        Assert.False(released.Has(KeywordAbility.MustAttack));
    }

    /// <summary>
    /// "Each opponent attacking that player does the same" repeats the sentence before it for
    /// each opponent attacking the enchanted player, as that opponent (CR 508.1b, 506.2).
    /// </summary>
    /// <remarks>
    /// Four seats, because the sentence needs three distinct people to mean anything: the
    /// Curse's controller (paid by the head effect), an opponent attacking the enchanted player
    /// (paid by the repeat), and one who is attacking nobody (paid by neither). The second
    /// combat — an attack on a player the Curse does not enchant — is what proves the trigger
    /// is scoped by the attachment rather than firing on every declaration.
    /// </remarks>
    [Fact]
    public void Each_opponent_attacking_the_enchanted_player_repeats_the_effect_as_themselves()
    {
        var curse = Card(
            "Vitality Curse Test",
            "Enchant player\nWhenever enchanted player is attacked, you gain 2 life. "
                + "Each opponent attacking that player does the same.",
            CardType.Enchantment,
            subtypes: "Aura");

        var compiled = CardCompiler.Compile(curse);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, seats) = FourPlayers();

        var rider = game.Create(
            seats[2], TestCards.Creature("Vitality Rider Test", 2, 2), Zone.Battlefield);
        var raider = game.Create(
            seats[3], TestCards.Creature("Vitality Raider Test", 2, 2), Zone.Battlefield);

        game.CastSpell(
            seats[0], TestCards.PutInHand(game, seats[0], curse), [Target.ToPlayer(seats[1])]);
        Settle(game);

        // Seat 2 attacks the enchanted player: the controller gains 2 by the head sentence and
        // seat 2 gains 2 as themselves by the repeat. Nobody else moves — the enchanted player
        // is not an opponent attacking themself, and seat 3 is attacking nobody.
        TestCards.PassUntil(
            game,
            () => game.State.ActivePlayerId == seats[2]
                && game.State.CurrentStep == TurnStep.DeclareAttackers);

        game.DeclareAttackers(
            seats[2],
            new Dictionary<ObjectId, AttackTarget> { [rider] = AttackTarget.Player(seats[1]) });
        Settle(game);

        Assert.Equal(22, game.State.GetPlayer(seats[0]).Life);
        Assert.Equal(20, game.State.GetPlayer(seats[1]).Life);
        Assert.Equal(22, game.State.GetPlayer(seats[2]).Life);
        Assert.Equal(20, game.State.GetPlayer(seats[3]).Life);

        // Seat 3 attacks the *caster*: the Curse enchants somebody else, so the trigger does
        // not fire and nobody gains anything.
        TestCards.PassUntil(
            game,
            () => game.State.ActivePlayerId == seats[3]
                && game.State.CurrentStep == TurnStep.DeclareAttackers);

        var casterBefore = game.State.GetPlayer(seats[0]).Life;
        var attackerBefore = game.State.GetPlayer(seats[3]).Life;

        game.DeclareAttackers(
            seats[3],
            new Dictionary<ObjectId, AttackTarget> { [raider] = AttackTarget.Player(seats[0]) });
        Settle(game);

        Assert.Equal(casterBefore, game.State.GetPlayer(seats[0]).Life);
        Assert.Equal(attackerBefore, game.State.GetPlayer(seats[3]).Life);
        Assert.Equal(22, game.State.GetPlayer(seats[2]).Life);
    }

    // ---- A player can have a keyword (CR 702.11c, 702.18a) --------------------

    /// <summary>
    /// "You have hexproof" stops an opponent naming that player as a target (CR 702.11c).
    /// </summary>
    /// <remarks>
    /// The line this whole section exists for, and what blocked it was not the wording. Every
    /// static ability the compiler read described a <em>group of permanents</em>, and
    /// <c>TargetSpec.IsLegal</c>'s player arm asked three questions — does the seat exist, has
    /// it lost, does the filter admit it — before returning, so the hexproof check underneath it
    /// was reached only by objects. A player is not an object: <see cref="PlayerState"/> carried
    /// no keywords, and there was nothing for a reader to produce even if one had existed.
    /// <para>
    /// The second cast is what makes the first one evidence. A refusal alone would also be
    /// produced by a spell that could not be cast at all, or by a target the engine had stopped
    /// offering for some unrelated reason; the same card, from the same hand, on the same turn,
    /// aimed one seat over, separates "hexproof refused it" from "nothing worked".
    /// </para>
    /// </remarks>
    [Fact]
    public void A_player_with_hexproof_cannot_be_targeted_by_an_opponent()
    {
        var aegis = Card(
            "Aegis Of The Gods Test",
            "You have hexproof.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var compiled = CardCompiler.Compile(aegis);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, aegis, Zone.Battlefield);

        TestCards.PassUntil(
            game,
            () => game.State.ActivePlayerId == bob && game.State.CurrentStep == TurnStep.PrecombatMain);

        var card = TestCards.PutInHand(
            game, bob, Card("Aegis Bolt Test", "~ deals 3 damage to any target."));
        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(bob, card, [Target.ToPlayer(alice)]));

        // Targets are chosen before the cost is paid (CR 601.2c before 601.2h), so the refusal
        // leaves the card in hand and the mana in the pool - and the same spell aimed at a player
        // without hexproof is cast without complaint.
        game.CastSpell(bob, card, [Target.ToPlayer(bob)]);
        Settle(game);

        Assert.Equal(20, game.State.GetPlayer(alice).Life);
        Assert.Equal(17, game.State.GetPlayer(bob).Life);
    }

    /// <summary>
    /// Hexproof stops opponents and nobody else, so its holder may still target themselves.
    /// </summary>
    /// <remarks>
    /// CR 702.11c reads "your opponents control", exactly as CR 702.11b does for a permanent.
    /// That clause is the whole difference between hexproof and shroud, and without this half
    /// the two would be indistinguishable from outside the engine.
    /// </remarks>
    [Fact]
    public void Hexproof_on_a_player_still_lets_that_player_target_themselves()
    {
        var aegis = Card(
            "Self Aegis Test",
            "You have hexproof.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var (game, alice, _) = InMainPhase();
        game.Create(alice, aegis, Zone.Battlefield);

        var card = TestCards.PutInHand(
            game, alice, Card("Self Aegis Draw Test", "Target player draws a card."));

        var before = game.State.GetPlayer(alice).Hand.Count;
        game.CastSpell(alice, card, [Target.ToPlayer(alice)]);
        Settle(game);

        // One card left the hand to become the spell and one arrived from the draw.
        Assert.Equal(before, game.State.GetPlayer(alice).Hand.Count);
    }

    /// <summary>
    /// "You have shroud" refuses everybody, its own controller included (CR 702.18a).
    /// </summary>
    /// <remarks>
    /// The negative half of the test above, and the reason the two keywords are asked separately
    /// rather than through one "may this be targeted" question: CR 702.18a says "this permanent
    /// or player can't be the target of spells or abilities" with no owner clause at all. Ivory
    /// Mask and True Believer are printed exactly this way, and a player behind one genuinely
    /// cannot target themselves.
    /// </remarks>
    [Fact]
    public void Shroud_on_a_player_refuses_that_player_as_well()
    {
        var mask = Card("Ivory Mask Test", "You have shroud.", CardType.Enchantment);

        var compiled = CardCompiler.Compile(mask);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, mask, Zone.Battlefield);

        var mine = TestCards.PutInHand(
            game, alice, Card("Ivory Mask Draw Test", "Target player draws a card."));

        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, mine, [Target.ToPlayer(alice)]));

        // Bob is behind nothing, so the same card finds him - which is what says the refusal was
        // about the player rather than about the spell.
        game.CastSpell(alice, mine, [Target.ToPlayer(bob)]);
        Settle(game);

        Assert.Equal(20, game.State.GetPlayer(alice).Life);
    }

    /// <summary>
    /// The keyword lasts exactly as long as the permanent granting it, because it is computed.
    /// </summary>
    /// <remarks>
    /// The founding rule of this engine's characteristics — computed, never stored (CR 613) —
    /// asserted for the one subject it had never reached. A hexproof written onto
    /// <see cref="PlayerState"/> would pass every test above and fail this one: the creature dies
    /// and the player keeps the ability, which is precisely the "the lord died but the bonus
    /// stuck" defect that ended the previous engine.
    /// <para>
    /// Both halves happen on the same turn with the same card in the same hand, so the only
    /// thing that changed between the refusal and the cast is that the source left the
    /// battlefield.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_player_keyword_ends_with_the_permanent_that_grants_it()
    {
        var aegis = Card(
            "Ending Aegis Test",
            "You have hexproof.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var (game, alice, bob) = InMainPhase();
        var source = game.Create(alice, aegis, Zone.Battlefield);

        TestCards.PassUntil(
            game,
            () => game.State.ActivePlayerId == bob && game.State.CurrentStep == TurnStep.PrecombatMain);

        var bolt = TestCards.PutInHand(
            game, bob, Card("Ending Aegis Bolt Test", "~ deals 3 damage to any target."));
        var murder = TestCards.PutInHand(
            game, bob, Card("Ending Aegis Murder Test", "Destroy target creature."));

        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(bob, bolt, [Target.ToPlayer(alice)]));

        game.CastSpell(bob, murder, [Target.ToPermanent(source)]);
        Settle(game);

        Assert.DoesNotContain(source, game.State.Battlefield);

        game.CastSpell(bob, bolt, [Target.ToPlayer(alice)]);
        Settle(game);

        Assert.Equal(17, game.State.GetPlayer(alice).Life);
    }

    /// <summary>
    /// The board is never offered a target the engine would refuse (CR 702.11c).
    /// </summary>
    /// <remarks>
    /// The rule this feature turns on: the board's legality checks are a courtesy and may never
    /// permit what the engine forbids. The list the board renders comes from
    /// <c>Game.LegalTargetsFor</c>, which asks the same <c>TargetSpec.IsLegal</c> a cast does, so
    /// the fix to the player arm reaches both — and this is what says so rather than assuming it.
    /// A trigger carries the test because a trigger's targets are chosen through a halted
    /// question with the options in it, which is where the offered list is observable.
    /// </remarks>
    [Fact]
    public void A_hexproof_player_is_not_offered_as_a_target()
    {
        var aegis = Card(
            "Offered Aegis Test",
            "You have hexproof.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var pinger = Card(
            "Offered Pinger Test",
            "When ~ enters, target player draws a card.",
            CardType.Creature,
            power: 1,
            toughness: 1);

        var compiled = CardCompiler.Compile(pinger);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, aegis, Zone.Battlefield);

        TestCards.PassUntil(
            game,
            () => game.State.ActivePlayerId == bob && game.State.CurrentStep == TurnStep.PrecombatMain);

        game.Create(bob, pinger, Zone.Battlefield);
        TestCards.PassUntil(game, () => game.State.Choice is not null);

        var choice = game.State.Choice!;
        Assert.Equal(bob, choice.PlayerId);

        // Bob is the only seat offered. An option the board could click that the engine would
        // then refuse is the exact failure this rule exists to forbid.
        var offered = Assert.Single(choice.Options!);
        Assert.EndsWith(bob.ToString("N"), offered.Id, StringComparison.Ordinal);
    }

    /// <summary>
    /// "You and Humans you control have hexproof" is one sentence about two kinds of subject.
    /// </summary>
    /// <remarks>
    /// Sigarda, Heron's Grace prints it, and it is the shape that decides whether the player
    /// layer was built beside the object one or instead of it. The player half becomes a
    /// <c>PlayerQualityDefinition</c> and the remainder goes straight back to the group readers
    /// as the ordinary mass static it is — so the group vocabulary needs to know nothing about
    /// players, and each half is enforced by the mechanism that already existed for it.
    /// <para>
    /// The creature that is not a Human is what carries the test. A grant that reached every
    /// creature would look identical from Sigarda's own side.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_player_and_a_group_can_be_granted_hexproof_by_one_line()
    {
        var sigarda = Card(
            "Sigarda Heron Test",
            "You and Humans you control have hexproof.",
            CardType.Creature,
            power: 4,
            toughness: 5);

        var compiled = CardCompiler.Compile(sigarda);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, sigarda, Zone.Battlefield);

        var human = game.Create(
            alice,
            Card("Sigarda Human Test", string.Empty, CardType.Creature, 1, 1, KeywordAbility.None, "Human"),
            Zone.Battlefield);

        var wolf = game.Create(
            alice,
            Card("Sigarda Wolf Test", string.Empty, CardType.Creature, 2, 2, KeywordAbility.None, "Wolf"),
            Zone.Battlefield);

        TestCards.PassUntil(
            game,
            () => game.State.ActivePlayerId == bob && game.State.CurrentStep == TurnStep.PrecombatMain);

        var bolt = TestCards.PutInHand(
            game, bob, Card("Sigarda Bolt Test", "~ deals 3 damage to any target."));
        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(bob, bolt, [Target.ToPlayer(alice)]));

        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(bob, bolt, [Target.ToPermanent(human)]));

        game.CastSpell(bob, bolt, [Target.ToPermanent(wolf)]);
        Settle(game);

        Assert.DoesNotContain(wolf, game.State.Battlefield);
        Assert.Contains(human, game.State.Battlefield);
    }

    /// <summary>
    /// "You" is whoever controls the permanent now, not whoever started with it (CR 613.1b).
    /// </summary>
    /// <remarks>
    /// The stolen-lord defect, in the one place it had never been made. Reading
    /// <c>source.ControllerId</c> raw is where control <em>started</em>, so a stolen Aegis of the
    /// Gods would go on protecting the player it was taken from while giving its new controller
    /// nothing — a card strictly better for the thief's opponent. The player quality asks
    /// <c>Characteristics.ControllerOf</c> instead, which follows the theft.
    /// <para>
    /// Both directions are asserted from the same board, because a filter that had simply
    /// inverted the question would satisfy either one alone.
    /// </para>
    /// </remarks>
    [Fact]
    public void Hexproof_follows_the_permanent_when_control_changes()
    {
        var spirit = Card(
            "Stolen Spirit Test",
            "You have hexproof.",
            CardType.Creature,
            power: 3,
            toughness: 3);

        var (game, alice, bob) = InMainPhase();
        var source = game.Create(alice, spirit, Zone.Battlefield);

        TestCards.PassUntil(
            game,
            () => game.State.ActivePlayerId == bob && game.State.CurrentStep == TurnStep.PrecombatMain);

        var theft = TestCards.PutInHand(
            game,
            bob,
            Card("Stolen Spirit Treason Test", "Gain control of target creature until end of turn."));

        var draw = TestCards.PutInHand(
            game, bob, Card("Stolen Spirit Draw Test", "Target player draws a card."));

        game.CastSpell(bob, theft, [Target.ToPermanent(source)]);
        Settle(game);

        Assert.Equal(bob, Characteristics.ControllerOf(game.State, Pool, game.State.GetObject(source)));

        // Alice no longer has it: the ability went with the permanent, so Bob's spell finds her.
        game.CastSpell(bob, draw, [Target.ToPlayer(alice)]);
        Settle(game);

        // And Bob does have it now, so Alice's spell cannot find him.
        var hers = TestCards.PutInHand(
            game, alice, Card("Stolen Spirit Reply Test", "Target player draws a card."));

        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, hers, [Target.ToPlayer(bob)]));
    }

    /// <summary>
    /// A source that has lost all its abilities has lost this one too (CR 613.1f).
    /// </summary>
    /// <remarks>
    /// The gap the object path already closes and the player path had to close for itself: the
    /// grants are gathered by sweeping the battlefield, and a sweep that never asks whether the
    /// permanent still <em>has</em> the ability would leave a player behind a Humility'd Aegis of
    /// the Gods untargetable. It is asked only of permanents that actually granted something —
    /// on any real board none or one — because the question is a full layer computation.
    /// <para>
    /// Humility's printed wording, and it belongs to the opponent, so the test also says the
    /// silencing is about the permanent rather than about whose side it is on.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_silenced_permanent_grants_a_player_nothing()
    {
        var aegis = Card(
            "Silenced Aegis Test",
            "You have hexproof.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var humility = Card(
            "Humility Test",
            "All creatures lose all abilities and have base power and toughness 1/1.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(humility);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, aegis, Zone.Battlefield);

        TestCards.PassUntil(
            game,
            () => game.State.ActivePlayerId == bob && game.State.CurrentStep == TurnStep.PrecombatMain);

        var bolt = TestCards.PutInHand(
            game, bob, Card("Silenced Aegis Bolt Test", "~ deals 3 damage to any target."));

        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(bob, bolt, [Target.ToPlayer(alice)]));

        // No settle: a static ability's effect is computed from the battlefield rather than
        // resolved, so it applies the moment the enchantment is there - and passing priority
        // here would hand the turn on before the second cast.
        game.Create(bob, humility, Zone.Battlefield);

        game.CastSpell(bob, bolt, [Target.ToPlayer(alice)]);
        Settle(game);

        Assert.Equal(17, game.State.GetPlayer(alice).Life);
    }

    /// <summary>
    /// A quality no player can be given leaves the whole line unread (CR 702.16a).
    /// </summary>
    /// <remarks>
    /// The negative control, and it guards a specific way this reader could go wrong. The keyword
    /// vocabulary it borrows is the one the permanents' readers use, so without a narrowing it
    /// would compile "you have flying" into an ability with no meaning and no reader — a card
    /// that reads as complete and does nothing, which is a worse failure than an unread line
    /// because an unread line is visible.
    /// <para>
    /// The protection line is printed rather than invented: Absolute Virtue says "You have
    /// protection from each of your opponents", and protection genuinely <em>is</em> a player
    /// ability (CR 702.16a). It stays unread because the quality it names is a player, and this
    /// engine's protection flags are colours and artifacts. Refusing it is the honest answer;
    /// reading it as whichever protection the engine happens to have would be a different card.
    /// </para>
    /// </remarks>
    [Theory]
    [InlineData("You have flying.")]
    [InlineData("You have deathtouch.")]
    [InlineData("You have protection from each of your opponents.")]
    public void A_quality_a_player_cannot_have_is_left_unread(string line)
    {
        var card = Card(
            "Unread Player Quality Test " + line.Length,
            line,
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(card);

        Assert.Empty(compiled.PlayerQualities);
        Assert.Contains(line, compiled.Unhandled, StringComparer.Ordinal);
    }

    // ---- Attacking as though it had no defender (CR 609.4, 702.3b) -----------

    /// <summary>
    /// Bristlepack Sentry: the permission is switched on and off by the board (CR 609.4).
    /// </summary>
    /// <remarks>
    /// The engine has had <c>MayAttackAsThoughNoDefender</c> and the combat rule that reads it
    /// since the wall tests were written; nothing in the compiler could produce it, so every card
    /// in the family sat one line short with the whole of the rest of the card read. It is one
    /// grammar item across five printed spellings - a static gated by a condition, the same
    /// static with the condition trailing, a bare static, an activated permission with a pump in
    /// front of it, and the quoted form an Aura grants - and it is worth more than any row of the
    /// work queue naming any one of them, because no row could see the other four.
    /// <para>
    /// The condition is load-bearing here rather than decoration: the wall is refused, the
    /// creature the sentence asks for arrives, and the same wall is then allowed. A reader that
    /// dropped the condition and granted the permission outright would pass every assertion an
    /// only-allowed test could make.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_wall_attacks_only_while_the_condition_it_names_holds()
    {
        var sentry = Card(
            "Conditional Defender Test",
            "Defender\nAs long as you control a creature with power 4 or greater, this creature"
                + " can attack as though it didn't have defender.",
            CardType.Creature,
            power: 1,
            toughness: 4,
            keywords: KeywordAbility.Defender);

        var compiled = CardCompiler.Compile(sentry);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var wall = game.Create(alice, sentry, Zone.Battlefield);

        PassTo(game, 3, TurnStep.DeclareAttackers);

        // Nothing on the board answers the condition, so the printed keyword still stops it.
        Assert.Contains(
            "702.3b",
            CombatRules.CannotAttack(game.State, Pool, game.State.GetObject(wall), alice, bob)
                ?? string.Empty,
            StringComparison.Ordinal);

        game.Create(
            alice, TestCards.Creature("Conditional Defender Ally Test", 4, 4), Zone.Battlefield);

        Assert.Null(CombatRules.CannotAttack(
            game.State, Pool, game.State.GetObject(wall), alice, bob));

        game.DeclareAttackers(
            alice, new Dictionary<ObjectId, AttackTarget> { [wall] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Settle(game);

        Assert.Equal(19, game.State.GetPlayer(bob).Life);
    }

    /// <summary>
    /// Mobile Fort: the activated spelling, where the pump and the permission are one sentence.
    /// </summary>
    /// <remarks>
    /// Two effects for one sentence, in two layers: the size change is 7c and the permission is
    /// not a characteristic change at all (CR 609.4, 613.4c). Reading only the pump leaves a card
    /// that grows and still cannot attack, which is what every wall of this shape did before.
    /// <para>
    /// The turn boundary is asserted because "this turn" is the whole difference between this
    /// spelling and the static one, and the two share the named effect underneath. An
    /// until-end-of-turn effect that was quietly permanent would look identical on the turn it
    /// was activated.
    /// </para>
    /// </remarks>
    [Fact]
    public void An_activated_permission_carries_its_pump_and_ends_with_the_turn()
    {
        var fort = Card(
            "Activated Defender Test",
            "Defender\n{3}: This creature gets +3/-1 until end of turn and can attack this turn"
                + " as though it didn't have defender. Activate only once each turn.",
            CardType.Creature,
            power: 2,
            toughness: 6,
            keywords: KeywordAbility.Defender);

        var compiled = CardCompiler.Compile(fort);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var wall = game.Create(alice, fort, Zone.Battlefield);

        PassTo(game, 3, TurnStep.PrecombatMain);
        game.AddMana(alice, null, 3);
        game.ActivateAbility(alice, wall, "a");
        Settle(game);

        var computed = Characteristics.Of(game.State, Pool, game.State.GetObject(wall));
        Assert.Equal(5, computed.Power);
        Assert.Equal(5, computed.Toughness);
        Assert.True(computed.MayAttackAsThoughNoDefender);

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);

        Assert.Null(CombatRules.CannotAttack(
            game.State, Pool, game.State.GetObject(wall), alice, bob));

        game.DeclareAttackers(
            alice, new Dictionary<ObjectId, AttackTarget> { [wall] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Settle(game);

        Assert.Equal(15, game.State.GetPlayer(bob).Life);

        // And it is gone by the next combat, which is what "this turn" buys over the static.
        PassTo(game, 5, TurnStep.DeclareAttackers);

        Assert.Contains(
            "702.3b",
            CombatRules.CannotAttack(game.State, Pool, game.State.GetObject(wall), alice, bob)
                ?? string.Empty,
            StringComparison.Ordinal);
    }

    /// <summary>
    /// The permission is not the removal of the keyword (CR 609.4).
    /// </summary>
    /// <remarks>
    /// The cheapest wrong implementation of this whole family is one line - take defender out of
    /// the computed keywords - and it passes every assertion about attacking. What it breaks is
    /// everything <em>else</em> that asks: an anthem keyed to "creatures you control with
    /// defender" stops finding the creature, and the card silently plays as better than printed
    /// on exactly the board it was designed for.
    /// <para>
    /// So the assertion is the anthem's, not the attack's: the wall still answers yes to having
    /// defender, and still collects the +0/+2 the enchantment gives creatures that do.
    /// </para>
    /// </remarks>
    [Fact]
    public void The_permission_leaves_defender_on_the_creature()
    {
        var rampart = Card(
            "Permission Keeps Keyword Test",
            "Defender\nThis creature can attack as though it didn't have defender.",
            CardType.Creature,
            power: 3,
            toughness: 4,
            keywords: KeywordAbility.Defender);

        var anthem = Card(
            "Defender Anthem Test",
            "Creatures you control with defender get +0/+2.",
            CardType.Enchantment);

        Assert.True(CardCompiler.Compile(rampart).IsComplete);
        Assert.True(CardCompiler.Compile(anthem).IsComplete);

        var (game, alice, _) = InMainPhase();
        var wall = game.Create(alice, rampart, Zone.Battlefield);
        game.Create(alice, anthem, Zone.Battlefield);
        Settle(game);

        var computed = Characteristics.Of(game.State, Pool, game.State.GetObject(wall));

        Assert.True(computed.Has(KeywordAbility.Defender));
        Assert.True(computed.MayAttackAsThoughNoDefender);
        Assert.Equal(6, computed.Toughness);
    }

    /// <summary>
    /// Animate Wall: an Aura's copy of the permission lands on its host, not on itself.
    /// </summary>
    /// <remarks>
    /// The Aura is an enchantment and can never attack, so a reader that put its own effect on
    /// itself would compile clean, apply cleanly, and do nothing at all - the silent no-op this
    /// file records against several other attached readers. Nothing here asks what the host's
    /// printed noun is: what the Aura could legally be attached to was settled when it was cast
    /// (CR 303.4), and re-testing the word is what stopped an earlier attached reader working on
    /// anything the sentence did not literally name.
    /// </remarks>
    [Fact]
    public void An_aura_gives_the_permission_to_what_it_enchants()
    {
        var animate = Card(
            "Animate Wall Test",
            "Enchant Wall\nEnchanted Wall can attack as though it didn't have defender.",
            CardType.Enchantment,
            subtypes: "Aura");

        var compiled = CardCompiler.Compile(animate);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var wall = Card(
            "Animated Wall Host Test",
            "Defender",
            CardType.Creature,
            power: 2,
            toughness: 5,
            keywords: KeywordAbility.Defender,
            subtypes: "Wall");

        var (game, alice, bob) = InMainPhase();
        var host = game.Create(alice, wall, Zone.Battlefield);
        var aura = TestCards.PutInHand(game, alice, animate);

        game.CastSpell(alice, aura, [Target.ToPermanent(host)]);
        Settle(game);

        PassTo(game, 3, TurnStep.DeclareAttackers);

        Assert.Null(CombatRules.CannotAttack(
            game.State, Pool, game.State.GetObject(host), alice, bob));

        game.DeclareAttackers(
            alice, new Dictionary<ObjectId, AttackTarget> { [host] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Settle(game);

        Assert.Equal(18, game.State.GetPlayer(bob).Life);
    }

    /// <summary>
    /// The plural form names a group and stays unread.
    /// </summary>
    /// <remarks>
    /// "Wall creatures can attack as though they didn't have defender" is Rolling Stones, and it
    /// is a mass static about permanents the source does not own - a different reader entirely,
    /// with a group phrase to parse and a scope clause that decides whose walls it means.
    /// Widening the singular pattern to take it would give one creature's permission to a whole
    /// board, so the plural is left for whoever builds the group form.
    /// </remarks>
    [Theory]
    [InlineData("Wall creatures can attack as though they didn't have defender.")]
    [InlineData("Modified creatures you control can attack as though they didn't have defender.")]
    public void The_group_spelling_of_the_permission_is_left_unread(string line)
    {
        var card = Card(
            "Unread Group Permission Test " + line.Length,
            line,
            CardType.Enchantment);

        Assert.Contains(line, CardCompiler.Compile(card).Unhandled, StringComparer.Ordinal);
    }

    // ---- Moving a maximum hand size (CR 402.2) -------------------------------

    /// <summary>
    /// Thought Eater and Locust Miser: the delta reaches the seat the sentence names.
    /// </summary>
    /// <remarks>
    /// Two rows of the work queue and one missing word. The engine had asked one question about
    /// hand size for a long time - "is there a permanent that removes the limit" - and every card
    /// that <em>moves</em> the limit had nowhere to compile to, however plain its sentence.
    /// <para>
    /// Both scopes are on the board at once and the assertion is that they do not cross. This is
    /// the shape of the 83-card defect this file already records one layer over: a reader that
    /// defaulted the missing scope to the controller would shrink the wrong hand, and with only
    /// one of the two cards in play nothing could tell the difference - Alice's hand would be
    /// short either way.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_hand_size_reduction_reaches_only_the_seat_its_sentence_names()
    {
        var eater = Card(
            "Own Hand Size Test",
            "Your maximum hand size is reduced by three.",
            CardType.Creature,
            power: 1,
            toughness: 1);

        var miser = Card(
            "Opponent Hand Size Test",
            "Each opponent's maximum hand size is reduced by two.",
            CardType.Creature,
            power: 1,
            toughness: 1);

        Assert.True(CardCompiler.Compile(eater).IsComplete);
        Assert.True(CardCompiler.Compile(miser).IsComplete);

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, eater, Zone.Battlefield);
        game.Create(alice, miser, Zone.Battlefield);

        for (var i = 0; i < 12; i++)
        {
            TestCards.PutInHand(game, alice, TestCards.Creature($"Hand Size Alice {i} Test", 1, 1));
            TestCards.PutInHand(game, bob, TestCards.Creature($"Hand Size Bob {i} Test", 1, 1));
        }

        // Through Alice's cleanup: seven less the three her own card takes.
        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber == 2 && game.State.CurrentStep == TurnStep.PrecombatMain);

        Assert.Equal(4, game.State.GetPlayer(alice).Hand.Count);

        // And through Bob's: seven less the two the other card takes from opponents, with
        // Alice's own reduction not reaching him and his not reaching her.
        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber == 3 && game.State.CurrentStep == TurnStep.PrecombatMain);

        Assert.Equal(5, game.State.GetPlayer(bob).Hand.Count);
    }

    /// <summary>
    /// The deltas add, and one of them is an increase (CR 402.2).
    /// </summary>
    /// <remarks>
    /// Addition rather than assignment is the whole reason this is a signed number and not a new
    /// limit: two Misers take four cards between them, and the rules impose no ordering because
    /// none is needed. Trusted Advisor is the increase, held by the player the reductions are
    /// aimed at, so the two directions have to meet on one seat and cancel to a number that is
    /// neither seven nor either card's own answer.
    /// </remarks>
    [Fact]
    public void Hand_size_changes_from_both_sides_add_up()
    {
        var miser = Card(
            "Stacked Hand Size Test",
            "Each opponent's maximum hand size is reduced by two.",
            CardType.Creature,
            power: 1,
            toughness: 1);

        var advisor = Card(
            "Raised Hand Size Test",
            "Your maximum hand size is increased by two.",
            CardType.Creature,
            power: 1,
            toughness: 1);

        Assert.True(CardCompiler.Compile(advisor).IsComplete);

        var (game, alice, bob) = InMainPhase();

        // Two copies of the same card, because that is what stacking means here: the delta is
        // read off the card and applied once per permanent, not once per distinct card.
        game.Create(alice, miser, Zone.Battlefield);
        game.Create(alice, miser, Zone.Battlefield);
        game.Create(bob, advisor, Zone.Battlefield);

        for (var i = 0; i < 12; i++)
            TestCards.PutInHand(game, bob, TestCards.Creature($"Stacked Hand {i} Test", 1, 1));

        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber == 3 && game.State.CurrentStep == TurnStep.PrecombatMain);

        // Seven, less two twice, plus his own two.
        Assert.Equal(5, game.State.GetPlayer(bob).Hand.Count);
    }

    /// <summary>
    /// The forms that set a hand size rather than move it stay unread.
    /// </summary>
    /// <remarks>
    /// Recorded as a decline rather than an omission, and measured: every corpus card printing
    /// "your maximum hand size is eight" is short something else as well, so reading it completes
    /// nobody - and it is a different question. A delta adds; an assignment is two permanents
    /// able to disagree, and CR 613's ordering does not reach the argument because a player is
    /// not an object. "The chosen player's" names a seat chosen as the permanent entered, which
    /// is a third thing again, and reading it as the controller's would put the reduction on the
    /// wrong side of the table on a card whose entire point is choosing a side.
    /// </remarks>
    [Theory]
    [InlineData("Your maximum hand size is eight.")]
    [InlineData("The chosen player's maximum hand size is four.")]
    [InlineData("Players have no maximum hand size.")]
    public void A_hand_size_that_is_set_rather_than_moved_is_left_unread(string line)
    {
        var card = Card(
            "Unread Hand Size Test " + line.Length,
            line,
            CardType.Artifact);

        var compiled = CardCompiler.Compile(card);

        Assert.Empty(compiled.HandSizeChanges);
        Assert.Contains(line, compiled.Unhandled, StringComparer.Ordinal);
    }

    // ---- Lines unread for a joiner, a noun or an apostrophe ------------------

    /// <summary>
    /// A semicolon joins a keyword line exactly as a comma does (CR 702).
    /// </summary>
    /// <remarks>
    /// Pikemen prints "First strike; banding" and Kjeldoran Skyknight "Flying; first strike;
    /// banding". Every keyword on those lines is one the engine models, the line is nothing but
    /// keywords, and it went unread whole because the list reader split on commas alone - so the
    /// card lost its first strike along with its banding. **15 corpus templates and 20 cards are
    /// one such line short**, and what they needed was a separator, not a rule.
    /// <para>
    /// The banding half is granted rather than checked against the card, because banding is not
    /// a flag the bulk data carries: the sentence is what says the card has it, which is how the
    /// whole-line table already reads it standing alone.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_semicolon_joins_a_keyword_line_the_way_a_comma_does()
    {
        var pikemen = Card(
            "Semicolon Pikemen Test",
            "First strike; banding",
            CardType.Creature,
            1,
            2,
            keywords: KeywordAbility.FirstStrike);

        var compiled = CardCompiler.Compile(pikemen);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.True(compiled.GrantedKeywords.HasFlag(KeywordAbility.Banding));

        var (game, alice, _) = InMainPhase();
        var it = game.Create(alice, pikemen, Zone.Battlefield);
        var computed = Characteristics.Of(game.State, Pool, game.State.GetObject(it));

        // Both halves. The printed keyword is asserted as well as the granted one because a
        // reader that claimed the line and dropped the flag would look identical from banding's
        // side, and the first strike is the half the unread line was actually costing.
        Assert.True(computed.Has(KeywordAbility.FirstStrike));
        Assert.True(computed.Has(KeywordAbility.Banding));
    }

    /// <summary>A joined line with one unreadable part stays unread whole.</summary>
    /// <remarks>
    /// The rule every keyword list here follows, and the reason the fix above is safe to make.
    /// Rampage and legendary landwalk are not modelled, so "Trample; rampage 2" is refused
    /// entire rather than compiled as a plain trampler - a card that is strictly simpler than
    /// the printed one looks implemented and plays wrong, and the queue is the right place for
    /// it until the missing half exists.
    /// </remarks>
    [Theory]
    [InlineData("Trample; rampage 2")]
    [InlineData("First strike; legendary landwalk")]
    public void A_joined_keyword_line_is_refused_whole_when_a_part_is_unread(string line)
    {
        var card = Card(
            "Half Joined Test " + line.Length,
            line,
            CardType.Creature,
            2,
            2,
            keywords: KeywordAbility.Trample | KeywordAbility.FirstStrike);

        Assert.Contains(line, CardCompiler.Compile(card).Unhandled, StringComparer.Ordinal);
    }

    /// <summary>
    /// "Protection from black and from red" is two abilities and both of them land (CR 702.16e).
    /// </summary>
    /// <remarks>
    /// Protection from several qualities is one ability per quality, and the engine holds each
    /// as its own flag - it had every flag this line names. The reader looked the whole phrase up
    /// as a single word, so Auriok Champion sat one line short of complete while "Protection from
    /// black" on its own read perfectly.
    /// <para>
    /// The fixture carries no keyword flags at all, on purpose. The bulk data never says which
    /// colour - it prints the bare word "Protection" - so the flags are recovered by looking for
    /// "protection from red" in the text, and a conjunction never writes that phrase: it says red
    /// without ever saying "protection from red". Requiring the flag would have refused the card
    /// on the strength of a substring search, so the line grants what it names.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_protection_conjunction_grants_every_colour_it_names()
    {
        var champion = Card(
            "Conjunction Champion Test",
            "Protection from black and from red",
            CardType.Creature,
            2,
            2);

        var compiled = CardCompiler.Compile(champion);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, champion, Zone.Battlefield);

        var black = game.Create(
            bob, Coloured("Conjunction Black Test", ManaColor.Black), Zone.Battlefield);
        var red = game.Create(
            bob, Coloured("Conjunction Red Test", ManaColor.Red), Zone.Battlefield);
        var green = game.Create(
            bob, Coloured("Conjunction Green Test", ManaColor.Green), Zone.Battlefield);

        // Both named colours, because reading only the head of the conjunction leaves the second
        // one able to block and looks identical from the first one's side.
        foreach (var blocker in new[] { black, red })
        {
            var why = CombatRules.CannotBlock(
                game.State,
                Pool,
                game.State.GetObject(blocker),
                game.State.GetObject(attacker),
                bob);

            Assert.NotNull(why);
            Assert.Contains("702.16e", why, StringComparison.Ordinal);
        }

        // And a colour the line does not name is still let through, so the two above are about
        // the words rather than about protection refusing everything.
        Assert.Null(CombatRules.CannotBlock(
            game.State,
            Pool,
            game.State.GetObject(green),
            game.State.GetObject(attacker),
            bob));
    }

    /// <summary>A conjunction naming a quality that is not a flag stays in the queue.</summary>
    /// <remarks>
    /// Fail closed. The engine's protection is one flag per colour plus artifacts, and a creature
    /// type is not among them, so reading these as the empty set of qualities would compile
    /// Warren-Scourge Elf as a card protected from nothing - complete on the coverage number and
    /// wrong at the table. Four templates and four cards stay unread on purpose.
    /// </remarks>
    [Theory]
    [InlineData("Protection from Spirits and from Arcane")]
    [InlineData("Protection from planeswalkers and from Wizards")]
    public void A_protection_conjunction_naming_no_flag_stays_unread(string line)
    {
        var card = Card(
            "Untyped Protection Test " + line.Length,
            line,
            CardType.Creature,
            2,
            2);

        Assert.Contains(line, CardCompiler.Compile(card).Unhandled, StringComparer.Ordinal);
    }

    /// <summary>
    /// An Aura silences its host in a sentence of its own (CR 602.5c).
    /// </summary>
    /// <remarks>
    /// The effect behind this was built already - it is the clause a pacifism prints after "can't
    /// attack or block" - and Stupefying Touch was unread for want of an apostrophe: the attached
    /// subject was only ever followed by a space, so "Enchanted creature's activated abilities
    /// can't be activated" matched nothing. Worth knowing before deciding a line needs a new
    /// mechanism: the neighbouring wording is the first place to look.
    /// </remarks>
    [Fact]
    public void An_aura_silences_its_host_in_a_sentence_of_its_own()
    {
        var touch = Card(
            "Stupefying Touch Test",
            "Enchant creature\nEnchanted creature's activated abilities can't be activated.",
            CardType.Enchantment,
            subtypes: "Aura");

        var compiled = CardCompiler.Compile(touch);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var pinger = Card(
            "Touched Pinger Test",
            "{T}: ~ deals 1 damage to any target.",
            CardType.Creature,
            1,
            1);

        var (game, alice, bob) = InMainPhase();
        var creature = game.Create(alice, pinger, Zone.Battlefield);

        // Reachable first, so the refusal below is evidence of the Aura rather than of an ability
        // that never worked.
        Assert.Contains(
            Game.ActivatedAbilitiesOf(game.State, Pool, game.State.GetObject(creature)),
            a => a.Id == "a");

        var aura = TestCards.PutInHand(game, alice, touch);
        var land = game.Create(alice, TestCards.BasicLand("Plains"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");
        game.CastSpell(alice, aura, [Target.ToPermanent(creature)]);
        Settle(game);

        var why = Assert.Throws<InvalidOperationException>(
            () => game.ActivateAbility(alice, creature, "a", [Target.ToPlayer(bob)]));

        Assert.Contains("can't be activated", why.Message, StringComparison.Ordinal);
    }

    /// <summary>
    /// "You control enchanted land" takes the land (CR 613.1b).
    /// </summary>
    /// <remarks>
    /// The same effect the mind-control Aura uses, and it never reads the noun: control moves to
    /// whatever the Aura is attached to, and which types that host may have was settled by the
    /// card's own "Enchant ..." line. Two nouns were listed and four went unread, so Annex and
    /// Conquer were one word short of complete.
    /// </remarks>
    [Fact]
    public void An_aura_that_says_you_control_enchanted_land_takes_the_land()
    {
        var annex = Card(
            "Annexed Land Test",
            "Enchant land\nYou control enchanted land.",
            CardType.Enchantment,
            null,
            null,
            KeywordAbility.None,
            "Aura");

        var compiled = CardCompiler.Compile(annex);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var theirs = game.Create(bob, TestCards.BasicLand("Island"), Zone.Battlefield);

        Assert.Equal(
            bob, Characteristics.Of(game.State, Pool, game.State.GetObject(theirs)).ControllerId);

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, annex), [Target.ToPermanent(theirs)]);
        Settle(game);

        Assert.Equal(
            alice, Characteristics.Of(game.State, Pool, game.State.GetObject(theirs)).ControllerId);

        // And the point of taking it: Alice taps it for mana, which only a permanent she controls
        // lets her do.
        game.ActivateAbility(alice, theirs, "mana");
        Assert.True(game.State.GetObject(theirs).Permanent!.IsTapped);
    }

    /// <summary>
    /// A defined power counts domain, and domain counts types rather than lands (CR 305.6).
    /// </summary>
    /// <remarks>
    /// Two vocabularies answered one question. The counting phrases a spell can read live in one
    /// place and knew domain; the ones a characteristic-defining ability can read lived in
    /// another and did not - so "the number of basic land types among lands you control" was read
    /// inside a spell and unread as a creature's own size, with **21 corpus cards one such line
    /// short**. The defining reader now falls through to the shared vocabulary, which is what a
    /// second copy should have been all along.
    /// <para>
    /// Two Forests counting as one is the whole assertion. A reader that counted permanents
    /// instead of types - which is what the arm beside this one does for "the number of lands you
    /// control" - would say two, and that is exactly why domain could not be spelled as a group.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_defined_power_counts_domain_rather_than_lands()
    {
        var kavu = Card(
            "Domain Kavu Test",
            "Domain Kavu Test's power and toughness are each equal to the number of basic land "
                + "types among lands you control.",
            CardType.Creature,
            power: 0,
            toughness: 0);

        var compiled = CardCompiler.Compile(kavu);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.Create(bob, TestCards.BasicLand("Swamp"), Zone.Battlefield);

        var it = game.Create(alice, kavu, Zone.Battlefield);

        // One type from two Forests, and Bob's Swamp is not among "lands you control".
        Assert.Equal(1, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(it)));

        game.Create(alice, TestCards.BasicLand("Island"), Zone.Battlefield);
        Assert.Equal(2, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(it)));
    }

    /// <summary>
    /// The cost reduction counts domain through that same vocabulary (CR 601.2f).
    /// </summary>
    /// <remarks>
    /// The second reader on the far side of the shared count, and the reason the fix was worth
    /// making there rather than beside the defining ability: "costs {1} less to cast for each
    /// basic land type among lands you control" asks the same question, so Leyline Binding and
    /// the Invasion beasts came with it at no extra cost.
    /// </remarks>
    [Fact]
    public void A_cost_reduction_counts_domain_through_the_same_vocabulary()
    {
        var binding = new CardDefinition
        {
            OracleId = "oracle-domain-binding-test",
            Name = "Domain Binding Test",
            ManaCostRaw = "{4}",
            Cmc = 4,
            OracleText = "Domain Binding Test costs {1} less to cast for each basic land type "
                + "among lands you control.",
            CardTypes = CardType.Enchantment,
        };

        var compiled = CardCompiler.Compile(binding);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, binding);

        game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.Create(alice, TestCards.BasicLand("Island"), Zone.Battlefield);
        game.AddMana(alice, ManaColor.Green);

        // Two types off four is two, and there is one mana in the pool. A reader counting lands
        // would have made it three types and cast the spell here.
        Assert.Throws<InvalidOperationException>(() => game.CastSpell(alice, card, []));

        game.Create(alice, TestCards.BasicLand("Plains"), Zone.Battlefield);
        game.Create(alice, TestCards.BasicLand("Swamp"), Zone.Battlefield);

        // Four types off four is nothing left to pay.
        game.CastSpell(alice, card, []);
        Settle(game);

        Assert.Contains(
            game.State.Battlefield,
            id => game.State.GetObject(id).Card.Name == "Domain Binding Test");
    }

    /// <summary>
    /// An Aura's bonus can be counted rather than printed (CR 613.4c).
    /// </summary>
    /// <remarks>
    /// The same shared vocabulary as the two above, reached from the third of the compiler's
    /// readers that needs it. The attached-pump reader took two literal numbers, so Bonehoard,
    /// Runechanter's Pike and Spontaneous Mutation were each one line short of a bonus the engine
    /// could have applied the moment it was told the number - **14 templates and 15 cards**.
    /// <para>
    /// The count is the Aura's controller's and not the host's, which is the half a test
    /// asserting only the size would miss: "your graveyard" on an Aura Alice controls is Alice's
    /// graveyard even while the creature it shrinks belongs to Bob.
    /// </para>
    /// </remarks>
    [Fact]
    public void An_aura_shrinks_its_host_by_a_count_its_own_controller_makes()
    {
        var mutation = Card(
            "Counted Mutation Test",
            "Enchant creature\nEnchanted creature gets -X/-0, where X is the number of cards "
                + "in your graveyard.",
            CardType.Enchantment,
            null,
            null,
            KeywordAbility.None,
            "Aura");

        var compiled = CardCompiler.Compile(mutation);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var theirs = game.Create(
            bob, TestCards.Creature("Mutated Ogre Test", 4, 4), Zone.Battlefield);

        // Two in Alice's, three in Bob's. A reader that asked the creature's controller would
        // say three and shrink the Ogre to a 1/4, which is why the two piles differ.
        game.Create(alice, TestCards.Creature("Mutation Corpse One Test", 1, 1), Zone.Graveyard);
        game.Create(alice, TestCards.Creature("Mutation Corpse Two Test", 1, 1), Zone.Graveyard);
        game.Create(bob, TestCards.Creature("Mutation Enemy One Test", 1, 1), Zone.Graveyard);
        game.Create(bob, TestCards.Creature("Mutation Enemy Two Test", 1, 1), Zone.Graveyard);
        game.Create(bob, TestCards.Creature("Mutation Enemy Three Test", 1, 1), Zone.Graveyard);

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, mutation), [Target.ToPermanent(theirs)]);
        Settle(game);

        var computed = Characteristics.Of(game.State, Pool, game.State.GetObject(theirs));

        Assert.Equal(2, computed.Power);

        // The nought half is a literal in the same sentence, and it stays nought: a reader that
        // let X stand for both would have made this a 2/2.
        Assert.Equal(4, computed.Toughness);

        // And it keeps counting, with nothing going back to adjust it.
        game.Create(alice, TestCards.Creature("Mutation Corpse Three Test", 1, 1), Zone.Graveyard);
        Assert.Equal(
            1, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(theirs)));
    }

    /// <summary>A counted pump whose count needs "it" stays unread.</summary>
    /// <remarks>
    /// Fail closed on the far side of the same reader. A continuous effect is applied with no
    /// source to point "it" at, so a phrase that names one is refused rather than answered as
    /// nought - a pump that quietly comes out at zero compiles as a complete card and plays as a
    /// blank one, which is the failure the whole counting vocabulary exists to avoid.
    /// <para>
    /// "Its controller's graveyard" used to be a second case here and no longer is. It was filed
    /// beside the counter count because both were phrases the layers could not answer, but only
    /// one of them was: an attached effect applies to exactly the permanent it is attached to, so
    /// "its controller" is the seat being computed and needs no resolution to find. Disturbing
    /// Conversion and Death's Approach are the cards, and the Aura test below plays one with the
    /// two hands different sizes, which is the check this refusal could never have been.
    /// </para>
    /// </remarks>
    [Theory]
    [InlineData("Equipped creature gets +X/+X, where X is the number of charge counters on ~.")]
    public void A_counted_attached_pump_that_needs_a_source_stays_unread(string line)
    {
        var card = Card(
            "Sourceless Count Test " + line.Length,
            "Enchant creature\n" + line,
            CardType.Enchantment,
            null,
            null,
            KeywordAbility.None,
            "Aura");

        Assert.Contains(line, CardCompiler.Compile(card).Unhandled, StringComparer.Ordinal);
    }

    // ---- Devotion as a number, and keyword costs that are not mana ------------

    /// <summary>
    /// "You gain life equal to your devotion to green" is a number, not only a condition (CR 700.5).
    /// </summary>
    /// <remarks>
    /// Devotion had been read in exactly one place — the God cycle's "as long as your devotion to
    /// black is less than five" — and every card printed beside those asking for the same number
    /// as a <em>quantity</em> went unread. It counts mana symbols among the costs of the permanents
    /// you control, so the three assertions here are the three ways a permanent count would get it
    /// wrong: three permanents with no green symbol between them are nought devotion, one permanent
    /// costing {G}{G}{G} is three, and an opponent's green permanent is their devotion and not
    /// yours (CR 613.1b — control is computed, so it moves when the permanent does).
    /// </remarks>
    [Fact]
    public void Devotion_is_read_as_a_number_and_counts_symbols_not_permanents()
    {
        var gift = Card("Devotion Number Test", "You gain life equal to your devotion to green.");

        var compiled = CardCompiler.Compile(gift);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();

        foreach (var n in new[] { 1, 2, 3 })
        {
            game.Create(
                alice,
                TestCards.Costed("Devotion Number Peasant " + n, "{1}", 1),
                Zone.Battlefield);
        }

        game.Create(
            alice, TestCards.Costed("Devotion Number Grove", "{G}{G}{G}", 3), Zone.Battlefield);

        game.Create(
            bob, TestCards.Costed("Devotion Number Rival", "{G}{G}", 2), Zone.Battlefield);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, gift));
        Settle(game);

        Assert.Equal(23, game.State.GetPlayer(alice).Life);
    }

    /// <summary>
    /// Devotion reaches every verb that can carry a count, not one verb at a time.
    /// </summary>
    /// <remarks>
    /// The phrase is spelled out into the counting vocabulary's own wording before any matcher
    /// sees the line, so each of these reads through the reader it was already going to use — the
    /// life verb, the "where X is" wrapper, the counter's unless-clause, the draw. Teaching them
    /// one at a time is the work this avoids, and a test per verb is how it stays avoided: a
    /// rewrite that only satisfied the first of them would pass a single-card test.
    /// </remarks>
    [Theory]
    [InlineData("You gain life equal to your devotion to green.")]
    [InlineData("Target creature gets +X/+X until end of turn, where X is your devotion to green.")]
    [InlineData("Counter target spell unless its controller pays {X}, where X is your devotion to blue.")]
    [InlineData("You draw X cards and you lose X life, where X is your devotion to black.")]
    [InlineData("You gain life equal to your devotion to white and black.")]
    public void A_devotion_count_reads_wherever_a_count_is_written(string line)
    {
        var card = Card("Devotion Reach Test " + line.Length, line);

        var compiled = CardCompiler.Compile(card);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
    }

    /// <summary>
    /// A permanent whose power <em>is</em> its controller's devotion tracks the board (CR 700.5).
    /// </summary>
    /// <remarks>
    /// The other shape the same number is printed in, and the one that has to keep answering: it
    /// is a characteristic-defining ability, so the power is recomputed every time anything asks,
    /// and a reader that took the count once when the card was compiled would report the same
    /// number on an empty board and a full one.
    /// </remarks>
    [Fact]
    public void A_power_defined_by_devotion_recounts_as_the_board_changes()
    {
        var nymph = Card(
            "Devotion Power Test",
            "~'s power is equal to your devotion to green.",
            CardType.Creature,
            power: 0,
            toughness: 4);

        var compiled = CardCompiler.Compile(nymph);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var her = game.Create(alice, nymph, Zone.Battlefield);
        Settle(game);

        int PowerOfHer() =>
            Characteristics.Of(game.State, Pool, game.State.GetObject(her)).Power ?? 0;

        Assert.Equal(0, PowerOfHer());

        game.Create(
            alice, TestCards.Costed("Devotion Power Grove", "{G}{G}{G}", 3), Zone.Battlefield);
        Settle(game);

        Assert.Equal(3, PowerOfHer());
    }

    /// <summary>A devotion this cannot colour stays unread rather than counting nothing.</summary>
    /// <remarks>
    /// "Your devotion to Abzan" is three colours named by a clan, "to hybrid" counts a kind of
    /// symbol rather than a colour, and "to that color" means one chosen while the spell resolves.
    /// None of them can be spelled into a colour list, and a rewrite that dropped the word would
    /// leave a count of nothing behind — which compiles as a complete card and plays as a blank
    /// one. That is the failure the whole counting vocabulary exists to avoid, so these are
    /// refused where they are printed.
    /// </remarks>
    [Theory]
    [InlineData("You gain life equal to your devotion to Abzan.")]
    [InlineData("~ gets +X/+X, where X is your devotion to hybrid.")]
    [InlineData("Choose a color. You gain life equal to your devotion to that color.")]
    public void A_devotion_whose_colour_cannot_be_read_stays_unread(string line)
    {
        var card = Card("Devotion Refusal Test " + line.Length, line);

        Assert.Contains(line, CardCompiler.Compile(card).Unhandled, StringComparer.Ordinal);
    }

    /// <summary>
    /// A kicker whose price is a sacrifice is charged, and only when it is taken (CR 702.33a).
    /// </summary>
    /// <remarks>
    /// A keyword cost need not be mana. Every one of these had been assumed to be — the reader
    /// took a run of mana symbols and nothing else — so the whole family sat one line short with
    /// the rest of the card already read.
    /// <para>
    /// Both arms are asserted because only the pair distinguishes a working payment from no
    /// payment at all: an unkicked cast must leave the land alone, and a kicked one with nothing
    /// offered must be refused outright rather than kicked for free (CR 601.2h).
    /// </para>
    /// </remarks>
    [Fact]
    public void A_kicker_paid_by_sacrificing_a_land_charges_only_when_it_is_taken()
    {
        var bolt = Card(
            "Kicker Sacrifice Test",
            "~ deals 2 damage to any target.\nKicker—Sacrifice a land.\n"
                + "If this spell was kicked, you gain 3 life.");

        var compiled = CardCompiler.Compile(bolt);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var swamp = game.Create(alice, TestCards.BasicLand("Swamp"), Zone.Battlefield);

        // Declining pays nothing: the land stays and the kicked half never happens.
        game.CastSpell(alice, TestCards.PutInHand(game, alice, bolt), [Target.ToPlayer(bob)]);
        Settle(game);

        Assert.Contains(swamp, game.State.Battlefield);
        Assert.Equal(20, game.State.GetPlayer(alice).Life);
        Assert.Equal(18, game.State.GetPlayer(bob).Life);

        // CR 601.2h: a cost that cannot be met refuses the whole cast, with nothing spent.
        var second = TestCards.PutInHand(game, alice, bolt);
        Assert.Throws<InvalidOperationException>(() => game.CastSpell(
            alice, second, [Target.ToPlayer(bob)], variableValue: 0, tapToPay: null, modes: null,
            kicked: true));

        Assert.Contains(swamp, game.State.Battlefield);

        game.CastSpell(
            alice, second, [Target.ToPlayer(bob)], variableValue: 0, tapToPay: null, modes: null,
            kicked: true, costPayment: [swamp]);

        Settle(game);

        Assert.DoesNotContain(swamp, game.State.Battlefield);
        Assert.Equal(23, game.State.GetPlayer(alice).Life);
        Assert.Equal(16, game.State.GetPlayer(bob).Life);
    }

    /// <summary>
    /// Buyback bought with a discard still buys the card back (CR 702.27a).
    /// </summary>
    /// <remarks>
    /// Buyback is kicker's shape with a different reward, and its price is read by the same cost
    /// parser — so the discard rides the cast's existing payment list rather than needing a
    /// channel of its own, and the reward at the end of the resolution is untouched by how the
    /// cost was paid.
    /// </remarks>
    [Fact]
    public void A_buyback_paid_by_discarding_still_returns_the_spell_to_hand()
    {
        var chant = Card(
            "Buyback Discard Test", "You gain 2 life.\nBuyback—Discard two cards.");

        var compiled = CardCompiler.Compile(chant);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var spell = TestCards.PutInHand(game, alice, chant);
        var fodder = new[] { 1, 2 }
            .Select(n => TestCards.PutInHand(
                game, alice, TestCards.Creature("Buyback Discard Fodder " + n)))
            .ToList();

        game.CastSpell(
            alice, spell, targets: null, variableValue: 0, tapToPay: null, modes: null,
            kicked: false, costPayment: fodder, faceDown: false, delve: null, buyback: true);

        Settle(game);

        // Asserted by name rather than by id, because a card that changes zone becomes a new
        // object (CR 400.7) — both the discarded pair and the spell coming back.
        Assert.Equal(22, game.State.GetPlayer(alice).Life);
        Assert.Equal(
            2,
            game.State.GetPlayer(alice).Graveyard.Count(
                id => game.State.GetObject(id).Card.Name.StartsWith(
                    "Buyback Discard Fodder", StringComparison.Ordinal)));

        Assert.Contains(
            game.State.GetPlayer(alice).Hand,
            id => game.State.GetObject(id).Card.Name == "Buyback Discard Test");

        Assert.DoesNotContain(
            game.State.GetPlayer(alice).Hand,
            id => game.State.GetObject(id).Card.Name.StartsWith(
                "Buyback Discard Fodder", StringComparison.Ordinal));
    }

    /// <summary>A keyword cost paid in life is charged with the rest of it (CR 118.8).</summary>
    /// <remarks>
    /// Life is neither mana nor a card, so it has nowhere to go but its own field — and it is
    /// checked before anything is spent for the same reason the mana is (CR 601.2h). Nothing is
    /// charged for declining, which is the second assertion.
    /// </remarks>
    [Fact]
    public void A_keyword_cost_paid_in_life_is_charged_only_when_the_offer_is_taken()
    {
        var bolt = Card(
            "Kicker Life Test",
            "~ deals 2 damage to any target.\nKicker—Pay 3 life.\n"
                + "If this spell was kicked, you gain 1 life.");

        var compiled = CardCompiler.Compile(bolt);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();

        game.CastSpell(alice, TestCards.PutInHand(game, alice, bolt), [Target.ToPlayer(bob)]);
        Settle(game);

        Assert.Equal(20, game.State.GetPlayer(alice).Life);

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, bolt), [Target.ToPlayer(bob)],
            variableValue: 0, tapToPay: null, modes: null, kicked: true);

        Settle(game);

        // Three paid, one gained back by the clause that only happens when it was kicked.
        Assert.Equal(18, game.State.GetPlayer(alice).Life);
    }

    /// <summary>An equip cost that is not mana is charged as the ability is activated.</summary>
    /// <remarks>
    /// Equip is an ordinary activated ability with a fixed effect, so its price goes through the
    /// same cost reader every other activation cost does — and the payment travels <em>with</em>
    /// the activation, because a suspended cost payment would be a continuation and a folded log
    /// cannot rebuild one.
    /// </remarks>
    [Fact]
    public void An_equip_cost_that_is_not_mana_is_charged()
    {
        var blade = Card(
            "Equip Sacrifice Test",
            "Equipped creature gets +2/+2.\nEquip—Sacrifice a creature.",
            CardType.Artifact,
            null,
            null,
            KeywordAbility.None,
            "Equipment");

        var compiled = CardCompiler.Compile(blade);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var equipment = game.Create(alice, blade, Zone.Battlefield);
        var bearer = game.Create(
            alice, TestCards.Creature("Equip Sacrifice Bearer"), Zone.Battlefield);
        var offering = game.Create(
            alice, TestCards.Creature("Equip Sacrifice Offering"), Zone.Battlefield);

        game.ActivateAbility(
            alice, equipment, "equip", [Target.ToPermanent(bearer)], costPayment: [offering]);

        Settle(game);

        Assert.DoesNotContain(offering, game.State.Battlefield);
        Assert.Equal(
            4, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(bearer)));
    }

    /// <summary>
    /// A flashback cost that is not mana is charged for the cast from the graveyard (CR 702.34a).
    /// </summary>
    /// <remarks>
    /// The permission already had somewhere to put this — retrace's land discard rides the same
    /// list — and what makes it the zone's cost rather than the spell's is that the same card cast
    /// from hand pays nothing extra. The exile on the way out is untouched by how it was paid.
    /// </remarks>
    [Fact]
    public void A_flashback_cost_that_is_not_mana_is_charged()
    {
        var rite = Card(
            "Flashback Sacrifice Test",
            "You gain 3 life.\nFlashback—Sacrifice a creature.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(rite);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var card = game.Create(alice, rite, Zone.Graveyard);
        var offering = game.Create(
            alice, TestCards.Creature("Flashback Sacrifice Offering"), Zone.Battlefield);

        game.CastSpell(
            alice, card, targets: null, variableValue: 0, tapToPay: null, modes: null,
            kicked: false, costPayment: [offering]);

        Settle(game);

        Assert.Equal(23, game.State.GetPlayer(alice).Life);
        Assert.DoesNotContain(offering, game.State.Battlefield);

        // CR 702.34a: exiled on the way out, so it cannot be cast a second time. By name,
        // because the card became a new object when it left the graveyard (CR 400.7).
        Assert.Contains(
            game.State.Exile,
            id => game.State.GetObject(id).Card.Name == "Flashback Sacrifice Test");
    }

    /// <summary>A keyword cost this cannot charge leaves the line unread.</summary>
    /// <remarks>
    /// Fail closed, and the direction matters: a keyword whose price was read as nothing is
    /// strictly better than the card printed, because an additional cost of nothing is always
    /// worth paying. "Forage" is a keyword action this compiler does not know; "X cards" is a
    /// number chosen as the spell is cast and the cost reader deliberately admits no X, because
    /// the word reader beside it answers one to anything it does not recognise.
    /// </remarks>
    [Theory]
    [InlineData("Kicker—Forage.")]
    [InlineData("Buyback—Discard X cards.")]
    [InlineData("Kicker—Remove a charge counter from ~.")]
    public void A_keyword_cost_this_cannot_charge_stays_unread(string line)
    {
        var card = Card("Keyword Cost Refusal Test " + line.Length, "You gain 2 life.\n" + line);

        Assert.Contains(line, CardCompiler.Compile(card).Unhandled, StringComparer.Ordinal);
    }

    /// <summary>An equip cost printed with a restriction behind it stays unread.</summary>
    /// <remarks>
    /// "Equip—Pay 3 life. Activate only once each turn." is one line carrying two things, and the
    /// price is the easy half. Reading it and dropping the restriction would hand the card an
    /// equip every turn where it prints one — better than printed, which is the one direction
    /// this compiler may not be wrong in — so the whole line is refused instead.
    /// </remarks>
    [Fact]
    public void An_equip_cost_with_a_restriction_behind_it_stays_unread()
    {
        var line = "Equip—Pay 3 life. Activate only once each turn.";

        var blade = Card(
            "Equip Restriction Refusal Test",
            "Equipped creature gets +1/+1.\n" + line,
            CardType.Artifact,
            null,
            null,
            KeywordAbility.None,
            "Equipment");

        Assert.Contains(line, CardCompiler.Compile(blade).Unhandled, StringComparer.Ordinal);
    }

    // ---- Keyword prices that are not mana (CR 702.24a, 702.21a, 702.29a, 702.188a) ----

    /// <summary>
    /// "Cumulative upkeep—Pay 1 life" charges one life per age counter (CR 702.24a).
    /// </summary>
    /// <remarks>
    /// The rule the whole keyword is: the price climbs. Mana said that by repeating its printed
    /// symbols in the offer's text, and nothing repeated a number — so the non-mana forms would
    /// have compiled into a tax that never grew, which is a strictly better card than the one
    /// printed and the failure this compiler may not ship. The multiplier travels on the offer
    /// now, and the two upkeeps below charge 1 and then 2 out of one unchanging life total.
    /// </remarks>
    [Fact]
    public void A_cumulative_upkeep_paid_in_life_costs_one_more_life_every_turn()
    {
        var relic = Card(
            "Ageing Life Relic Test", "Cumulative upkeep—Pay 1 life", CardType.Artifact);

        var compiled = CardCompiler.Compile(relic);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        game.Create(alice, relic, Zone.Battlefield);

        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber == 3
                && game.State.Choice is { Kind: ChoiceKind.OptionalPayment });

        // First age counter: the offer names one life, and the prompt says so. A button reading
        // "Pay ?" is what this looked like before the price had words.
        var first = game.State.Choice;
        Assert.NotNull(first);
        Assert.Contains("1 life", first!.Prompt, StringComparison.Ordinal);

        game.Choose(alice, ["yes"]);
        Settle(game);
        Assert.Equal(19, game.State.GetPlayer(alice).Life);

        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber == 5
                && game.State.Choice is { Kind: ChoiceKind.OptionalPayment });

        // Second age counter, and the price with it. Two lives, not one — the number came off
        // the offer rather than off the printed text.
        var second = game.State.Choice;
        Assert.NotNull(second);
        Assert.Contains("2 life", second!.Prompt, StringComparison.Ordinal);

        game.Choose(alice, ["yes"]);
        Settle(game);

        Assert.Equal(17, game.State.GetPlayer(alice).Life);
        Assert.Contains(
            game.State.Battlefield,
            id => game.State.GetObject(id).Card.Name == "Ageing Life Relic Test");
    }

    /// <summary>
    /// A cumulative upkeep paid in permanents asks for one more of them each turn (CR 702.24a).
    /// </summary>
    /// <remarks>
    /// The half a repeated cost string cannot express. "Sacrifice a land" is one land however
    /// many times you write it out, so this is the case that proves the multiplier and not the
    /// text is what does the work: the second upkeep offers a ceiling of two and takes two.
    /// </remarks>
    [Fact]
    public void A_cumulative_upkeep_paid_in_lands_asks_for_one_more_land_every_turn()
    {
        var kraken = Card(
            "Ageing Kraken Test",
            "Cumulative upkeep—Sacrifice a land",
            CardType.Creature,
            power: 6,
            toughness: 6);

        var compiled = CardCompiler.Compile(kraken);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        game.Create(alice, kraken, Zone.Battlefield);

        foreach (var _ in Enumerable.Range(0, 4))
            game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);

        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber == 3
                && game.State.Choice is { Kind: ChoiceKind.OptionalPayment });

        var first = game.State.Choice;
        Assert.NotNull(first);
        Assert.Equal(1, first!.MaxPicks);

        game.Choose(alice, [first.Options[0].Id]);
        Settle(game);

        Assert.Equal(
            3,
            game.State.Battlefield.Count(id => game.State.GetObject(id).Card.Name == "Forest"));

        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber == 5
                && game.State.Choice is { Kind: ChoiceKind.OptionalPayment });

        // Two age counters, two lands. A cost that stayed at one would leave three Forests here
        // and would have passed every assertion above it.
        var second = game.State.Choice;
        Assert.NotNull(second);
        Assert.Equal(2, second!.MaxPicks);

        game.Choose(alice, [second.Options[0].Id, second.Options[1].Id]);
        Settle(game);

        Assert.Equal(
            1,
            game.State.Battlefield.Count(id => game.State.GetObject(id).Card.Name == "Forest"));
        Assert.Contains(
            game.State.Battlefield,
            id => game.State.GetObject(id).Card.Name == "Ageing Kraken Test");
    }

    /// <summary>"Echo—Discard a card" is echo priced in cards (CR 702.29a).</summary>
    /// <remarks>
    /// Nothing about the trigger changes with the currency, which is the point: the keyword was
    /// unread on three printings for no reason other than that its reader assumed mana. The card
    /// leaving the hand is the assertion that earns its place — an engine that ran the "if you
    /// do" branch without taking the payment keeps the creature and passes everything else.
    /// </remarks>
    [Fact]
    public void Echo_can_be_paid_by_discarding_and_the_card_really_goes()
    {
        var imp = new CardDefinition
        {
            OracleId = "oracle-echo-discard-test",
            Name = "Echo Discard Test",
            OracleText = "Echo—Discard a card.",
            CardTypes = CardType.Creature,
            Power = 3,
            Toughness = 3,
            ManaCostRaw = "{1}",
        };

        var compiled = CardCompiler.Compile(imp);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, imp);
        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, forest, "mana");
        game.CastSpell(alice, card, targets: null);
        Settle(game);

        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber == 3 && game.State.CurrentStep == TurnStep.Upkeep);

        // Put in hand once the turn has come round: a card sitting through a cleanup can be
        // discarded to hand size, and then there is no named card to look for.
        var spare = TestCards.PutInHand(
            game, alice, TestCards.Creature("Echo Discard Fodder Test", 1, 1));

        TestCards.PassUntil(
            game, () => game.State.Choice is { Kind: ChoiceKind.OptionalPayment });

        var offer = game.State.Choice;
        Assert.NotNull(offer);
        Assert.Contains(offer!.Options, o => o.Id == spare.Value.ToString("N"));

        game.Choose(alice, [spare.Value.ToString("N")]);
        Settle(game);

        // Paid: the card left the hand for the graveyard, and the creature stayed. Looked up by
        // name because a discarded card is a new object (CR 400.7) and the id it had in hand
        // names nothing.
        Assert.True(InGraveyard(game, alice, "Echo Discard Fodder Test"));
        Assert.DoesNotContain(
            game.State.GetPlayer(alice).Hand,
            id => game.State.GetObject(id).Card.Name == "Echo Discard Fodder Test");
        Assert.Contains(
            game.State.Battlefield,
            id => game.State.GetObject(id).Card.Name == "Echo Discard Test");
    }

    /// <summary>"Ward—{2}, Pay 3 life" charges both halves (CR 702.21a, 118.8).</summary>
    /// <remarks>
    /// Ward had grown its own three-shape cost vocabulary, and a combination was in none of the
    /// three: this line was unread while "Ward {2}" and "Ward—Pay 3 life" both read. Both prices
    /// are asserted because charging one of them is the failure that looks like success — the
    /// spell still resolves, and the card is quietly cheaper to target than the one printed.
    /// </remarks>
    [Fact]
    public void Ward_can_charge_mana_and_life_at_once()
    {
        var sentinel = Card(
            "Ward Both Test",
            "Ward—{2}, Pay 3 life",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var compiled = CardCompiler.Compile(sentinel);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var warded = game.Create(alice, sentinel, Zone.Battlefield);

        TestCards.PassUntil(
            game,
            () => game.State.ActivePlayerId == bob
                && game.State.CurrentStep == TurnStep.PrecombatMain);

        var bolt = TestCards.PutInHand(
            game, bob, Card("Ward Both Bolt Test", "Destroy target creature."));

        // Exactly the two the ward asks for. The bolt itself is free, so a pool with anything
        // left in it afterwards means the ward charged less than it printed.
        foreach (var _ in Enumerable.Range(0, 2))
        {
            var land = game.Create(bob, TestCards.BasicLand("Mountain"), Zone.Battlefield);
            game.ActivateAbility(bob, land, "mana");
        }

        game.CastSpell(bob, bolt, [Target.ToPermanent(warded)]);
        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.OptionalPayment });

        var before = game.State.GetPlayer(bob).Life;
        game.Choose(bob, ["yes"]);
        Settle(game);

        // Three life and two mana, and the spell got through: the ward was paid, not dodged.
        Assert.Equal(before - 3, game.State.GetPlayer(bob).Life);
        Assert.True(game.State.GetPlayer(bob).ManaPool.IsEmpty);
        Assert.DoesNotContain(warded, game.State.Battlefield);
    }

    /// <summary>"Ward—Sacrifice two permanents" taxes two, not one (CR 702.21a).</summary>
    /// <remarks>
    /// The count is the part ward's own vocabulary could not say at all: it read "a &lt;noun&gt;"
    /// and nothing else, so every counted printing went unread. One is not two, and a ward that
    /// asked for one would be the cheapest ward in the game while looking exactly like this one.
    /// </remarks>
    [Fact]
    public void Ward_can_charge_two_permanents()
    {
        var horror = Card(
            "Ward Two Test",
            "Ward—Sacrifice two permanents",
            CardType.Creature,
            power: 4,
            toughness: 4);

        var compiled = CardCompiler.Compile(horror);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var warded = game.Create(alice, horror, Zone.Battlefield);

        TestCards.PassUntil(
            game,
            () => game.State.ActivePlayerId == bob
                && game.State.CurrentStep == TurnStep.PrecombatMain);

        var bolt = TestCards.PutInHand(
            game, bob, Card("Ward Two Bolt Test", "Destroy target creature."));

        var land = game.Create(bob, TestCards.BasicLand("Mountain"), Zone.Battlefield);
        game.ActivateAbility(bob, land, "mana");
        game.Create(bob, TestCards.Creature("Ward Two Fodder Test", 1, 1), Zone.Battlefield);
        game.Create(bob, TestCards.Creature("Ward Two Spare Test", 1, 1), Zone.Battlefield);

        game.CastSpell(bob, bolt, [Target.ToPermanent(warded)]);
        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.OptionalPayment });

        var offer = game.State.Choice!;
        Assert.Equal(bob, offer.PlayerId);
        Assert.Equal(2, offer.MaxPicks);

        var his = game.State.Battlefield.Count(
            id => game.State.GetObject(id).ControllerId == bob);

        game.Choose(bob, [offer.Options[0].Id, offer.Options[1].Id]);
        Settle(game);

        // Two of Bob's permanents, not one. Counted off his own board so the bolt in his
        // graveyard cannot be mistaken for a payment.
        Assert.Equal(
            his - 2,
            game.State.Battlefield.Count(
                id => game.State.GetObject(id).ControllerId == bob));
        Assert.DoesNotContain(warded, game.State.Battlefield);
    }

    /// <summary>
    /// A ward price the offer cannot ask as one question leaves the line unread (CR 702.21a).
    /// </summary>
    /// <remarks>
    /// The direction this reader has to be wrong in. "Collect evidence 4" is a real cost and not
    /// one the engine can charge; read as an empty price it would be a ward nobody ever pays,
    /// which is a card better than the one printed and indistinguishable from a working one at
    /// the table.
    /// </remarks>
    [Fact]
    public void A_ward_price_the_engine_cannot_charge_leaves_the_line_unread()
    {
        var ferox = Card(
            "Ward Evidence Test",
            "Ward—Collect evidence 4.",
            CardType.Creature,
            power: 4,
            toughness: 4);

        Assert.Contains(
            "Ward—Collect evidence 4.",
            CardCompiler.Compile(ferox).Unhandled,
            StringComparer.Ordinal);
    }

    /// <summary>
    /// A freerunning price that is not mana at all (CR 702.173a).
    /// </summary>
    /// <remarks>
    /// Every alternative cost has been able to ask for a permanent since emerge, so the only
    /// thing between this card and the compiler was the em dash: its reader required mana and
    /// stopped there. The board question is unchanged, which is asserted first — an offer that
    /// forgot the condition would be a free instant on turn one.
    /// </remarks>
    [Fact]
    public void Freerunning_can_be_priced_in_a_creature_rather_than_mana()
    {
        var escape = new CardDefinition
        {
            OracleId = "oracle-freerunning-bounce-test",
            Name = "Freerunning Bounce Test",
            CardTypes = CardType.Instant,
            ManaCostRaw = "{1}{U}{U}",
            Cmc = 3,
            OracleText =
                "Freerunning—Return a blue creature you control to its owner's hand."
                + "\nDraw a card.",
        };

        var compiled = CardCompiler.Compile(escape);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var offer = Assert.Single(compiled.Spell!.ConditionalAlternativeCost!.Payments);
        Assert.Equal(ChosenCostKind.ReturnToHand, offer.Kind);
        Assert.Empty(compiled.Spell.ConditionalAlternativeCost.Cost.Symbols);

        var (game, alice, bob) = InMainPhase();

        var assassin = game.Create(
            alice,
            Card("Freerunning Bounce Assassin Test", string.Empty, CardType.Creature, 2, 2,
                KeywordAbility.None, "Assassin"),
            Zone.Battlefield);

        var blue = game.Create(
            alice, Coloured("Freerunning Bounce Drake Test", ManaColor.Blue), Zone.Battlefield);

        // Nothing has connected yet, so the offer is not open and there is no mana at all for
        // the printed cost.
        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(
                alice,
                TestCards.PutInHand(game, alice, escape),
                targets: null,
                alternativeCost: true,
                costPayment: [blue]));

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [assassin] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.PostcombatMain);

        var held = game.State.GetPlayer(alice).Hand.Count;
        var card = TestCards.PutInHand(game, alice, escape);
        game.CastSpell(
            alice, card, targets: null, alternativeCost: true, costPayment: [blue]);
        Settle(game);

        // No mana was ever floated: the creature was the whole price, and it went home rather
        // than dying.
        Assert.DoesNotContain(blue, game.State.Battlefield);
        Assert.Contains(
            game.State.GetPlayer(alice).Hand,
            id => game.State.GetObject(id).Card.Name == "Freerunning Bounce Drake Test");

        // The spell resolved: a card drawn, and the creature back, is two more than it started
        // with minus the one that was cast.
        Assert.Equal(held + 2, game.State.GetPlayer(alice).Hand.Count);
    }

    /// <summary>
    /// Web-slinging casts a spell for its own price plus a tapped creature (CR 702.188a).
    /// </summary>
    /// <remarks>
    /// Emerge's shape without the discount: an alternative cost paid in mana <em>and</em> a
    /// permanent. The untapped creature being refused is what pins the "tapped" in the rule — an
    /// offer that took any creature would pass every other assertion here and would let five
    /// cards be cast a turn earlier than they can be.
    /// </remarks>
    [Fact]
    public void Web_slinging_pays_with_a_tapped_creature_and_returns_it_to_hand()
    {
        var spider = PricedCard("Web Slinger Test", "{3}{W}", 4, "Web-slinging {W}");

        var compiled = CardCompiler.Compile(spider);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.Equal("web-slinging", compiled.Spell!.ConditionalAlternativeCost!.Keyword);

        var (game, alice, _) = InMainPhase();
        var standing = game.Create(
            alice, TestCards.Creature("Web Standing Test", 1, 1), Zone.Battlefield);
        var swung = game.Create(
            alice, TestCards.Creature("Web Swung Test", 1, 1), Zone.Battlefield);
        game.Tap(swung);

        var card = TestCards.PutInHand(game, alice, spider);
        game.AddMana(alice, ManaColor.White);

        // An untapped creature is not what the rule names, and the payment is refused on its own
        // terms rather than the spell being cast for free.
        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(
                alice, card, targets: null, alternativeCost: true, costPayment: [standing]));

        game.CastSpell(alice, card, targets: null, alternativeCost: true, costPayment: [swung]);
        Settle(game);

        // One white mana bought a four-drop, and the tapped creature went home rather than dying:
        // web-slinging returns, it does not sacrifice.
        Assert.Contains(
            game.State.Battlefield,
            id => game.State.GetObject(id).Card.Name == "Web Slinger Test");
        Assert.DoesNotContain(swung, game.State.Battlefield);
        Assert.Contains(
            game.State.GetPlayer(alice).Hand,
            id => game.State.GetObject(id).Card.Name == "Web Swung Test");
        Assert.Contains(standing, game.State.Battlefield);
    }

    /// <summary>
    /// "Splice onto instant or sorcery" reaches a spell that is not Arcane (CR 702.47a).
    /// </summary>
    /// <remarks>
    /// The keyword names the spells it splices onto and that had been read as a constant, so four
    /// cards whose quality is a card type rather than a subtype went unread whole. Both halves
    /// are asserted: it reaches a plain instant, and it still does not reach a creature — a
    /// splice-onto that had widened to everything would pass the first assertion alone.
    /// </remarks>
    [Fact]
    public void Splice_onto_instant_or_sorcery_reaches_a_spell_that_is_not_arcane()
    {
        var dream = Card(
            "Splice Everdream Test",
            "You gain 2 life.\nSplice onto instant or sorcery {1}");

        var compiled = CardCompiler.Compile(dream);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.NotNull(compiled.Spell!.SpliceCost);
        Assert.Equal("instant|sorcery", compiled.Spell.SpliceOnto);

        var (game, alice, bob) = InMainPhase();
        var land = game.Create(alice, TestCards.BasicLand("Island"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");

        var host = TestCards.PutInHand(
            game, alice, Card("Splice Plain Host Test", "Target player loses 1 life."));
        var spliceCard = TestCards.PutInHand(game, alice, dream);

        game.CastSpell(alice, host, targets: [Target.ToPlayer(bob)], spliced: [spliceCard]);
        Settle(game);

        // Both halves happened, and the spliced card was revealed rather than cast.
        Assert.Equal(22, game.State.GetPlayer(alice).Life);
        Assert.Equal(19, game.State.GetPlayer(bob).Life);
        Assert.Contains(
            game.State.GetPlayer(alice).Hand,
            id => game.State.GetObject(id).Card.Name == "Splice Everdream Test");
    }

    [Fact]
    public void Splice_onto_instant_or_sorcery_is_still_refused_onto_a_creature()
    {
        var dream = Card(
            "Splice Refused Everdream Test",
            "You gain 2 life.\nSplice onto instant or sorcery {1}");

        var (game, alice, _) = InMainPhase();
        var host = TestCards.PutInHand(
            game, alice, TestCards.Creature("Splice Creature Host Test", 2, 2));
        var spliceCard = TestCards.PutInHand(game, alice, dream);

        var refused = Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, host, targets: null, spliced: [spliceCard]));

        Assert.Contains("702.47a", refused.Message, StringComparison.Ordinal);
    }

    // ---- A pronoun that names somebody else (CR 603.2) ------------------------

    /// <summary>
    /// "That creature" in an enters trigger is the creature that entered.
    /// </summary>
    /// <remarks>
    /// The reader for this sentence aimed at the source unconditionally and sat <em>in front of</em>
    /// the reader that knows about a trigger's subject, so Primal Forcemage pumped the Forcemage.
    /// It compiled, it counted as read, and the only way to see it was to play it: the card is
    /// usually on the board beside the creature that just arrived, and a +3/+3 landing on the wrong
    /// one of two creatures looks like a game working.
    /// </remarks>
    [Fact]
    public void That_creature_in_an_enters_trigger_pumps_the_creature_that_entered()
    {
        var forcemage = Card(
            "Forcemage Pronoun Test",
            "Whenever another creature you control enters, that creature gets +3/+3 until end of turn.",
            CardType.Creature, 2, 2);

        var compiled = CardCompiler.Compile(forcemage);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var mage = game.Create(alice, forcemage, Zone.Battlefield);
        var arrival = game.Create(
            alice, TestCards.Creature("Forcemage Arrival Test", 2, 2), Zone.Battlefield);

        Settle(game);

        Assert.Equal(5, Characteristics.Of(game.State, Pool, game.State.GetObject(arrival)).Power);
        Assert.Equal(2, Characteristics.Of(game.State, Pool, game.State.GetObject(mage)).Power);
    }

    /// <summary>
    /// "That creature" behind a target phrase is that target, not the card that said it.
    /// </summary>
    /// <remarks>
    /// The same reader, reached from the other direction. Ana Sanctuary's second sentence and every
    /// kicker rider printing "that creature gets -5/-5 until end of turn instead" name the creature
    /// the sentence in front of them chose; aimed at the source they pumped an enchantment, or a
    /// spell on the stack, which is not a creature and takes no pump at all.
    /// </remarks>
    [Fact]
    public void That_creature_behind_a_target_phrase_means_the_target()
    {
        var blessing = Card(
            "Sanctuary Pronoun Test",
            "Target creature gets +1/+1 until end of turn. That creature gets +5/+5 until end of turn.");

        var compiled = CardCompiler.Compile(blessing);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var bear = game.Create(
            alice, TestCards.Creature("Sanctuary Bear Test", 2, 2), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, blessing);
        game.CastSpell(alice, card, [Target.ToPermanent(bear)]);
        Settle(game);

        // Both sentences are about one creature, so both bonuses are on it (CR 613.4c).
        Assert.Equal(8, Characteristics.Of(game.State, Pool, game.State.GetObject(bear)).Power);
    }

    /// <summary>
    /// "That creature" on a blocking trigger is the other creature in the pair (CR 509.3d).
    /// </summary>
    /// <remarks>
    /// Flailing Drake was recorded as fixed by the round that gave the block family a subject, and
    /// it was not: the subject arrived, and the reader in front of it still took the sentence and
    /// still aimed at the source. The Drake pumped itself in front of the creature it had just
    /// blocked, every time, on a card the census counted as complete.
    /// </remarks>
    [Fact]
    public void That_creature_on_a_block_pair_pumps_the_other_creature()
    {
        var drake = Card(
            "Flailing Pronoun Test",
            "Whenever ~ blocks or becomes blocked by a creature, that creature gets +1/+1 until end of turn.",
            CardType.Creature, 2, 2);

        var compiled = CardCompiler.Compile(drake);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, drake, Zone.Battlefield);
        var blocker = game.Create(bob, TestCards.Creature("Flailing Blocker Test", 1, 4), Zone.Battlefield);

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);
        game.DeclareBlockers(
            bob,
            new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [attacker] = [blocker] });

        Settle(game);

        // The creature it became blocked by grew; the Drake did not.
        Assert.Equal(2, Characteristics.Of(game.State, Pool, game.State.GetObject(blocker)).Power);
        Assert.Equal(2, Characteristics.Of(game.State, Pool, game.State.GetObject(attacker)).Power);
    }

    /// <summary>
    /// "A creature you control attacks alone" names the creature that attacked (CR 702.90a).
    /// </summary>
    /// <remarks>
    /// This is exalted's own sentence, and the cards that print it out rather than saying the
    /// keyword reached a reader that had no subject to give them. The one-word form had been
    /// given the right answer by hand in <c>TryExalted</c>; Agents of S.H.I.E.L.D., Eiganjo
    /// Exemplar, Strategic Intervention and Derelict Attic spell it and pumped themselves.
    /// <para>
    /// The condition is admitted to the allow-list because it already checks what the subject
    /// needs: every spelling of "attacks alone" fires only on a declaration holding exactly one
    /// attacker, which is exactly when <c>Game.SubjectObjectOf</c> answers.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_creature_that_attacks_alone_is_what_that_creature_names()
    {
        var agent = Card(
            "Alone Pronoun Test",
            "Whenever a creature you control attacks alone, that creature gets +1/+1 until end of turn.",
            CardType.Creature, 2, 2);

        var compiled = CardCompiler.Compile(agent);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var watcher = game.Create(alice, agent, Zone.Battlefield);
        var attacker = game.Create(
            alice, TestCards.Creature("Alone Attacker Test", 2, 2), Zone.Battlefield);

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        Settle(game);

        Assert.Equal(3, Characteristics.Of(game.State, Pool, game.State.GetObject(attacker)).Power);
        Assert.Equal(2, Characteristics.Of(game.State, Pool, game.State.GetObject(watcher)).Power);
    }

