        var bystander = game.Create(
            alice, TestCards.Creature("Snoop Bystander Test", 2, 2), Zone.Battlefield);

        var conniver = game.Create(alice, rogue, Zone.Battlefield);
        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.Connive });
        game.Choose(game.State.Choice!.PlayerId, [fodder.Value.ToString("N")]);
        Settle(game);

        Assert.Equal(3, Characteristics.Of(game.State, Pool, game.State.GetObject(conniver)).Power);
        Assert.Equal(2, Characteristics.Of(game.State, Pool, game.State.GetObject(bystander)).Power);
    }

    /// <summary>
    /// "Regenerate it" behind a target phrase shields that creature (CR 701.15a).
    /// </summary>
    /// <remarks>
    /// The reader of this class whose failure is loudest to a player and quietest to every
    /// instrument. Boon of Erebos, Butcher's Glee, Unnatural Endurance and Necrobite are all
    /// "target creature gets +N/+0 until end of turn. Regenerate it." - and "it" was read as the
    /// source, which for a spell is the card on the stack. The shield went onto the instant, the
    /// creature it was cast on died to the next destroy, and the card compiled, counted as read
    /// and played as a strictly worse card than the one printed.
    /// <para>
    /// <c>Regenerate</c> kept its own switch over the three subjects instead of going through
    /// <c>Subjects.Resolve</c>, which is how it stayed the one that could not take a pronoun.
    /// </para>
    /// </remarks>
    [Fact]
    public void Regenerate_it_behind_a_target_phrase_shields_that_creature()
    {
        var boon = Card(
            "Erebos Pronoun Test",
            "Target creature gets +2/+0 until end of turn. Regenerate it.");

        var compiled = CardCompiler.Compile(boon);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var bear = game.Create(alice, TestCards.Creature("Erebos Bear Test", 2, 2), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, boon);
        game.CastSpell(alice, card, [Target.ToPermanent(bear)]);
        Settle(game);

        Assert.Equal(4, Characteristics.Of(game.State, Pool, game.State.GetObject(bear)).Power);
        Assert.Equal(1, game.State.GetObject(bear).Permanent!.RegenerationShields);

        // And it is a shield rather than a number: the destruction is replaced (CR 701.15a) and
        // the creature is still on the battlefield afterwards.
        game.Move(bear, Zone.Graveyard, MoveCause.Destroy);
        Settle(game);

        var survivor = game.State.Battlefield
            .Select(game.State.GetObject)
            .SingleOrDefault(o => o.Card.Name == "Erebos Bear Test");

        Assert.NotNull(survivor);
        Assert.Equal(0, survivor!.Permanent!.RegenerationShields);
    }

    /// <summary>
    /// The control: "regenerate this creature" is still about the permanent that said it.
    /// </summary>
    [Fact]
    public void Regenerate_written_about_the_source_still_shields_the_source()
    {
        var troll = Card(
            "Troll Pronoun Test", "{G}: Regenerate ~.", CardType.Creature, 2, 2);

        var compiled = CardCompiler.Compile(troll);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var beast = game.Create(alice, troll, Zone.Battlefield);
        var bystander = game.Create(
            alice, TestCards.Creature("Troll Bystander Test", 2, 2), Zone.Battlefield);
        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);

        game.ActivateAbility(alice, forest, "mana");
        game.ActivateAbility(alice, beast, "a");
        Settle(game);

        Assert.Equal(1, game.State.GetObject(beast).Permanent!.RegenerationShields);
        Assert.Equal(0, game.State.GetObject(bystander).Permanent!.RegenerationShields);
    }

    /// <summary>
    /// "It deals damage equal to its power" is the creature the sentence named (CR 701.12a).
    /// </summary>
    /// <remarks>
    /// The widest reader of this class and the quietest failure in it. Ambuscade, Clear Shot,
    /// Rabid Gnaw, Wolf Strike, Huatli's Final Strike, Diplomatic Relations and Archdruid's
    /// Charm all pump a creature and then say "it deals damage equal to its power to target
    /// creature you don't control" - and "it" was the source, which for an instant is the card
    /// on the stack. A spell is not on the battlefield, so the effect returned no events at all:
    /// the pump landed, the damage never happened, and nothing anywhere reported a problem.
    /// </remarks>
    [Fact]
    public void It_deals_damage_equal_to_its_power_is_the_creature_the_sentence_named()
    {
        var ambuscade = Card(
            "Ambuscade Pronoun Test",
            "Target creature you control gets +1/+0 until end of turn. It deals damage equal to "
                + "its power to target creature an opponent controls.");

        var compiled = CardCompiler.Compile(ambuscade);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var mine = game.Create(alice, TestCards.Creature("Ambuscade Mine Test", 2, 2), Zone.Battlefield);
        var theirs = game.Create(bob, TestCards.Creature("Ambuscade Theirs Test", 4, 4), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, ambuscade);
        game.CastSpell(alice, card, [Target.ToPermanent(mine), Target.ToPermanent(theirs)]);
        Settle(game);

        // Three, not two: the damage is the pumped power, read when the spell resolves.
        Assert.Equal(3, game.State.GetObject(theirs).Permanent!.DamageMarked);

        // And nothing came back - this is half a fight (CR 701.12a is the two-way form).
        Assert.Equal(0, game.State.GetObject(mine).Permanent!.DamageMarked);
    }

    /// <summary>
    /// The control: an activated ability's "it" is still the permanent that has the ability.
    /// </summary>
    /// <remarks>
    /// Heartfire Immolator and Blazing Bomb say "{R}, Sacrifice this creature: It deals damage
    /// equal to its power to target creature", and there the word can only mean the card. The
    /// reader sees no target and no triggering object, and that is exactly when it must keep the
    /// source.
    /// </remarks>
    [Fact]
    public void An_activated_it_deals_damage_still_means_the_source()
    {
        var immolator = Card(
            "Immolator Pronoun Test",
            "{G}: It deals damage equal to its power to target creature.",
            CardType.Creature, 3, 1);

        var compiled = CardCompiler.Compile(immolator);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var burner = game.Create(alice, immolator, Zone.Battlefield);
        var victim = game.Create(bob, TestCards.Creature("Immolator Victim Test", 4, 4), Zone.Battlefield);
        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);

        game.ActivateAbility(alice, forest, "mana");
        game.ActivateAbility(alice, burner, "a", [Target.ToPermanent(victim)]);
        Settle(game);

        Assert.Equal(3, game.State.GetObject(victim).Permanent!.DamageMarked);
    }

    // ---- Prohibitions: a group's, and a one-shot joined by "and" (CR 509.1b, 702.3b) ----

    /// <summary>
    /// "Target creature gets +1/+0 until end of turn and can't be blocked this turn" (CR 509.1b).
    /// </summary>
    /// <remarks>
    /// Both halves of this sentence have read on their own for a long time - the pump through the
    /// target grammar, the prohibition through the keyword the blocking rules already ask for -
    /// and the word "and" between them was the whole of what defeated 24 corpus cards. So the
    /// sentence is folded into the two the readers know rather than given a matcher of its own.
    /// <para>
    /// The subject is what the fold has to get right, and it is carried over as a <em>pronoun</em>:
    /// repeating "target creature" would announce a second target (CR 601.2c) and the card would
    /// ask for two creatures where it prints one. The bystander here is the assertion that says
    /// so - it is the creature a group reading would have made unblockable as well.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_pump_joined_to_an_unblockable_grant_lands_on_the_one_creature_it_chose()
    {
        var strike = Card(
            "Test Distortion Strike",
            "Target creature gets +1/+0 until end of turn and can't be blocked this turn.");

        var compiled = CardCompiler.Compile(strike);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        // One target, not two: the tail is about the creature the head already chose.
        Assert.Single(compiled.Spell!.Targets);

        var (game, alice, bob) = InMainPhase();
        var sneak = game.Create(alice, TestCards.Creature("Test Strike Sneak", 2, 2), Zone.Battlefield);
        var plain = game.Create(alice, TestCards.Creature("Test Strike Plain", 2, 2), Zone.Battlefield);
        game.Create(bob, TestCards.Creature("Test Strike Guard", 1, 4), Zone.Battlefield);

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, strike), [Target.ToPermanent(sneak)]);

        Settle(game);

        var pumped = Characteristics.Of(game.State, Pool, game.State.GetObject(sneak));
        Assert.Equal(3, pumped.Power);
        Assert.True(pumped.Has(KeywordAbility.CantBeBlocked));

        // The control, and the one a group reading fails: the creature the spell did not choose
        // is an ordinary 2/2 that anything may block.
        Assert.False(Characteristics
            .Of(game.State, Pool, game.State.GetObject(plain))
            .Has(KeywordAbility.CantBeBlocked));

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget>
            {
                [sneak] = AttackTarget.Player(bob),
                [plain] = AttackTarget.Player(bob),
            });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);

        var guard = game.State.Battlefield
            .Single(id => game.State.GetObject(id).Card.Name == "Test Strike Guard");

        // The grant was made on turn 1 and this is turn 3, so it is gone - which is the whole
        // point of the next test, and here it is what lets the block below happen at all.
        Assert.Null(CombatRules.CannotBlock(
            game.State, Pool, game.State.GetObject(guard), game.State.GetObject(plain), bob));

        game.DeclareBlockers(
            bob, new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [plain] = [guard] });

        Settle(game);
    }

    /// <summary>
    /// The prohibition ends with the turn, exactly as the sentence it was cut from does.
    /// </summary>
    /// <remarks>
    /// The failure this family is most prone to, and the reason a fold is safer than a static
    /// reader: read as a continuous ability the creature would be unblockable for ever, which is
    /// strictly better than printed and would pass every assertion the test above makes.
    /// </remarks>
    [Fact]
    public void The_grant_joined_by_and_is_a_one_shot_and_is_gone_by_the_next_turn()
    {
        var strike = Card(
            "Test Taigam Strike",
            "Target creature gets +2/+0 until end of turn and can't be blocked this turn.");

        Assert.True(CardCompiler.Compile(strike).IsComplete);

        var (game, alice, bob) = InMainPhase();
        var sneak = game.Create(alice, TestCards.Creature("Test Taigam Sneak", 2, 2), Zone.Battlefield);

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, strike), [Target.ToPermanent(sneak)]);

        Settle(game);

        Assert.True(Characteristics
            .Of(game.State, Pool, game.State.GetObject(sneak))
            .Has(KeywordAbility.CantBeBlocked));

        // CR 611.2: both halves end in the cleanup step of the turn they were made in, and the
        // grant is asserted beside the pump so a duration lost on one of them is visible.
        PassTo(game, 3, TurnStep.PrecombatMain);

        var later = Characteristics.Of(game.State, Pool, game.State.GetObject(sneak));
        Assert.Equal(2, later.Power);
        Assert.False(later.Has(KeywordAbility.CantBeBlocked));

        // And an opponent's creature may block it again, which is the rule rather than the flag.
        var guard = game.Create(bob, TestCards.Creature("Test Taigam Guard", 1, 4), Zone.Battlefield);

        Assert.Null(CombatRules.CannotBlock(
            game.State, Pool, game.State.GetObject(guard), game.State.GetObject(sneak), bob));
    }

    /// <summary>
    /// The same sentence about the card itself: "~ gets +1/+0 ... and can't be blocked this turn".
    /// </summary>
    /// <remarks>
    /// Twelve of the twenty-four print it this way, and it is the arm where the carried subject
    /// must <em>not</em> become a pronoun: there is no target to point at, and a pronoun with
    /// nothing behind it would aim the grant at whatever the trigger happened to name.
    /// </remarks>
    [Fact]
    public void A_self_pump_joined_to_an_unblockable_grant_stays_on_the_permanent_that_said_it()
    {
        var spellfist = Card(
            "Test Elusive Spellfist",
            "{U}: ~ gets +1/+0 until end of turn and can't be blocked this turn.",
            CardType.Creature,
            power: 2,
            toughness: 1);

        var compiled = CardCompiler.Compile(spellfist);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var fist = game.Create(alice, spellfist, Zone.Battlefield);
        var bystander = game.Create(
            alice, TestCards.Creature("Test Spellfist Ally", 2, 1), Zone.Battlefield);

        game.AddMana(alice, ManaColor.Blue);
        game.ActivateAbility(alice, fist, compiled.Activated.Single().Id);
        Settle(game);

        var pumped = Characteristics.Of(game.State, Pool, game.State.GetObject(fist));
        Assert.Equal(3, pumped.Power);
        Assert.True(pumped.Has(KeywordAbility.CantBeBlocked));

        // The control: nothing else on its controller's board was touched.
        var other = Characteristics.Of(game.State, Pool, game.State.GetObject(bystander));
        Assert.Equal(2, other.Power);
        Assert.False(other.Has(KeywordAbility.CantBeBlocked));
    }

    /// <summary>
    /// "That creature can't block this turn" binds the creature the sentence named (CR 509.1b).
    /// </summary>
    /// <remarks>
    /// A live defect on ten already-complete cards, and invisible to everything: the pronoun was
    /// offered to the <em>group</em> grammar before the pronoun reader, and that grammar reads a
    /// capitalised "That creature" as a creature <em>subtype</em> of that name - the same defect
    /// its own comments record for "Islands" and "You". No card has such a subtype, so Duel
    /// Tactics, Mugging, Blindblast, Blood Aspirant, Stealth Mission, Kappa Cannoneer, Assassin
    /// Den, Razzle-Dazzler, Merciless Javelineer and Creeping Tar Pit all compiled complete and
    /// dealt their damage while the prohibition did nothing at all.
    /// <para>
    /// Capitalisation was what decided it, which is why it survived: the pronoun list is compared
    /// case-insensitively, so a mid-sentence "it" reached the right reader and a sentence-initial
    /// "That creature" did not. Both assertions below are needed - the named creature must be
    /// stopped, and the one beside it must still block, which is what tells a no-op apart from a
    /// prohibition read across the whole board.
    /// </para>
    /// </remarks>
    [Fact]
    public void That_creature_cant_block_stops_the_one_named_and_leaves_the_rest_alone()
    {
        var tactics = Card(
            "Test Duel Tactics",
            "~ deals 1 damage to target creature. That creature can't block this turn.");

        var compiled = CardCompiler.Compile(tactics);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.Single(compiled.Spell!.Targets);

        var (game, alice, bob) = InMainPhase();
        var raider = game.Create(alice, TestCards.Creature("Test Tactics Raider", 3, 3), Zone.Battlefield);
        var stopped = game.Create(bob, TestCards.Creature("Test Tactics Stopped", 2, 3), Zone.Battlefield);
        var free = game.Create(bob, TestCards.Creature("Test Tactics Free", 2, 4), Zone.Battlefield);

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [raider] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.Priority.Holder == alice);
        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, tactics), [Target.ToPermanent(stopped)]);

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);

        Assert.Equal(1, game.State.GetObject(stopped).Permanent!.DamageMarked);
        Assert.True(Characteristics
            .Of(game.State, Pool, game.State.GetObject(stopped))
            .Has(KeywordAbility.CantBlock));

        Assert.False(Characteristics
            .Of(game.State, Pool, game.State.GetObject(free))
            .Has(KeywordAbility.CantBlock));

        Assert.NotNull(CombatRules.CannotBlock(
            game.State, Pool, game.State.GetObject(stopped), game.State.GetObject(raider), bob));

        // The control case, and the half a silent no-op would also pass: the creature the spell
        // never named blocks, and the damage it takes proves the block happened.
        game.DeclareBlockers(
            bob, new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [raider] = [free] });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Settle(game);

        Assert.Equal(3, game.State.GetObject(free).Permanent!.DamageMarked);
        Assert.Equal(20, game.State.GetPlayer(bob).Life);
    }

    /// <summary>
    /// "Creatures you control can't attack" - a prohibition over a group (CR 702.3b).
    /// </summary>
    /// <remarks>
    /// The group readers could grant a keyword and could not forbid anything, so every card of
    /// this shape sat unread while the single-creature spellings of the same rule had worked for
    /// months. Each prohibition it now reads is a keyword this engine already models - "can't
    /// attack" is exactly defender - so the declaration checks that enforce a printed one enforce
    /// this one, with no second path to keep in step.
    /// <para>
    /// The ownership clause is the assertion that matters. Glacial Chasm stops <em>your</em>
    /// creatures and nobody else's, and a reader that dropped the clause would produce a card
    /// that stops the whole table while looking exactly as complete.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_group_that_cant_attack_stops_its_controllers_creatures_and_no_others()
    {
        var chasm = Card(
            "Test Glacial Chasm", "Creatures you control can't attack.", CardType.Enchantment);

        var compiled = CardCompiler.Compile(chasm);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, chasm, Zone.Battlefield);
        var mine = game.Create(alice, TestCards.Creature("Test Chasm Mine", 2, 2), Zone.Battlefield);
        var theirs = game.Create(bob, TestCards.Creature("Test Chasm Theirs", 2, 2), Zone.Battlefield);

        PassTo(game, 3, TurnStep.DeclareAttackers);

        Assert.Contains(
            "702.3b",
            CombatRules.CannotAttack(game.State, Pool, game.State.GetObject(mine), alice, bob)
                ?? string.Empty,
            StringComparison.Ordinal);

        Assert.Throws<InvalidOperationException>(() => game.DeclareAttackers(
            alice, new Dictionary<ObjectId, AttackTarget> { [mine] = AttackTarget.Player(bob) }));

        // The control: the enchantment says "you control", and Bob's creature attacks normally.
        game.DeclareAttackers(alice, new Dictionary<ObjectId, AttackTarget>());
        PassTo(game, 4, TurnStep.DeclareAttackers);

        Assert.Null(CombatRules.CannotAttack(
            game.State, Pool, game.State.GetObject(theirs), bob, alice));

        game.DeclareAttackers(
            bob, new Dictionary<ObjectId, AttackTarget> { [theirs] = AttackTarget.Player(alice) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Assert.Equal(18, game.State.GetPlayer(alice).Life);
    }

    /// <summary>
    /// The same reader with a filtered group: "Beasts can't block" (CR 509.1b).
    /// </summary>
    /// <remarks>
    /// A group with no ownership clause at all means every permanent that answers the
    /// description, an opponent's included - which is what Bedlam, Frenetic Raptor and Razorjaw
    /// Oni print. The filter is the other half: a reader that forbade every creature rather than
    /// the described ones would pass a test that only looked at the Beast.
    /// </remarks>
    [Fact]
    public void A_filtered_group_that_cant_block_stops_only_the_creatures_it_describes()
    {
        var raptor = Card(
            "Test Frenetic Raptor", "Beasts can't block.", CardType.Enchantment);

        var compiled = CardCompiler.Compile(raptor);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, raptor, Zone.Battlefield);
        var raider = game.Create(alice, TestCards.Creature("Test Raptor Raider", 2, 2), Zone.Battlefield);

        var beast = game.Create(
            bob,
            Card("Test Raptor Beast", string.Empty, CardType.Creature, 3, 3, subtypes: "Beast"),
            Zone.Battlefield);

        var bear = game.Create(bob, TestCards.Creature("Test Raptor Bear", 3, 3), Zone.Battlefield);

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [raider] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);

        Assert.True(Characteristics
            .Of(game.State, Pool, game.State.GetObject(beast))
            .Has(KeywordAbility.CantBlock));

        Assert.False(Characteristics
            .Of(game.State, Pool, game.State.GetObject(bear))
            .Has(KeywordAbility.CantBlock));

        Assert.NotNull(CombatRules.CannotBlock(
            game.State, Pool, game.State.GetObject(beast), game.State.GetObject(raider), bob));

        // The control: the creature outside the description blocks, and the damage says so.
        game.DeclareBlockers(
            bob, new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [raider] = [bear] });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Settle(game);

        Assert.Equal(2, game.State.GetObject(bear).Permanent!.DamageMarked);
    }

    /// <summary>
    /// "Boars you control can't be blocked by more than one creature" is menace (CR 702.111a).
    /// </summary>
    /// <remarks>
    /// The spelling menace was made a keyword for, said about a group. It is the same flag rather
    /// than a second rule, so the count is enforced where every printed menace is - and the
    /// difference between menace and being unblockable is the whole of what this asserts: one
    /// blocker is refused, two are allowed, and a card read as "can't be blocked" would let
    /// neither through while looking exactly as complete.
    /// </remarks>
    [Fact]
    public void A_group_that_cant_be_blocked_by_more_than_one_creature_is_menace_and_not_evasion()
    {
        var rocksteady = Card(
            "Test Rocksteady",
            "Boars you control can't be blocked by more than one creature.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(rocksteady);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, rocksteady, Zone.Battlefield);

        var boar = game.Create(
            alice,
            Card("Test Rocksteady Boar", string.Empty, CardType.Creature, 3, 3, subtypes: "Boar"),
            Zone.Battlefield);

        var bear = game.Create(alice, TestCards.Creature("Test Rocksteady Bear", 3, 3), Zone.Battlefield);
        var first = game.Create(bob, TestCards.Creature("Test Rocksteady Guard", 1, 4), Zone.Battlefield);
        var second = game.Create(bob, TestCards.Creature("Test Rocksteady Watch", 1, 4), Zone.Battlefield);

        Assert.True(Characteristics
            .Of(game.State, Pool, game.State.GetObject(boar))
            .Has(KeywordAbility.Menace));

        Assert.False(Characteristics
            .Of(game.State, Pool, game.State.GetObject(bear))
            .Has(KeywordAbility.Menace));

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [boar] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);

        var ex = Assert.Throws<InvalidOperationException>(() => game.DeclareBlockers(
            bob, new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [boar] = [first] }));

        Assert.Contains("702.111b", ex.Message, StringComparison.Ordinal);

        // The control, and the half that tells menace from evasion: two creatures may block it.
        game.DeclareBlockers(
            bob, new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [boar] = [first, second] });

        Settle(game);

        Assert.Equal(20, game.State.GetPlayer(bob).Life);
    }

    /// <summary>
    /// "Target creature can't attack or block this turn" - both halves, for one turn (CR 611.2).
    /// </summary>
    /// <remarks>
    /// The one-shot the target grammar could say for blocking and not for attacking, which is
    /// what left Off Balance, Change of Heart, Briber's Purse, Alchemist's Vial, Thundersong
    /// Trumpeter, Martyred Rusalka and Netter en-Dal unread. Both flags are asserted, because the
    /// pair is a single printed clause and a reader that took only the half it already knew would
    /// produce a creature that still attacks.
    /// </remarks>
    [Fact]
    public void Target_creature_cant_attack_or_block_this_turn_takes_both_and_ends_with_the_turn()
    {
        var balance = Card("Test Off Balance", "Target creature can't attack or block this turn.");

        var compiled = CardCompiler.Compile(balance);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var theirs = game.Create(bob, TestCards.Creature("Test Balance Theirs", 2, 2), Zone.Battlefield);
        var beside = game.Create(bob, TestCards.Creature("Test Balance Beside", 2, 2), Zone.Battlefield);

        // Cast on Bob's own turn, at instant speed, so the prohibition falls on the turn he
        // would attack with it - which is the only turn a "this turn" grant covers.
        PassTo(game, 2, TurnStep.PrecombatMain);
        TestCards.PassUntil(game, () => game.State.Priority.Holder == alice);
        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, balance), [Target.ToPermanent(theirs)]);

        Settle(game);

        var held = Characteristics.Of(game.State, Pool, game.State.GetObject(theirs));
        Assert.True(held.Has(KeywordAbility.Defender));
        Assert.True(held.Has(KeywordAbility.CantBlock));

        // The control: the creature beside it is untouched and attacks in the same declaration.
        Assert.False(Characteristics
            .Of(game.State, Pool, game.State.GetObject(beside))
            .Has(KeywordAbility.Defender));

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);

        Assert.Contains(
            "702.3b",
            CombatRules.CannotAttack(game.State, Pool, game.State.GetObject(theirs), bob, alice)
                ?? string.Empty,
            StringComparison.Ordinal);

        game.DeclareAttackers(
            bob, new Dictionary<ObjectId, AttackTarget> { [beside] = AttackTarget.Player(alice) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Assert.Equal(18, game.State.GetPlayer(alice).Life);

        // CR 611.2: gone by the next turn, so the creature it held back attacks then.
        PassTo(game, 4, TurnStep.DeclareAttackers);

        Assert.Null(CombatRules.CannotAttack(
            game.State, Pool, game.State.GetObject(theirs), bob, alice));
    }

    // ---- A prohibition that takes an argument (CR 702.11b, 702.11d, 701.6a) --

    /// <summary>A spell of one colour, so a targeting restriction has something to judge.</summary>
    /// <remarks>
    /// The <see cref="Card"/> helper leaves a card colourless, which is exactly the answer these
    /// restrictions are asked about — a card with no colour passes every "hexproof from [colour]"
    /// there is, so a test written with it would pass whether the rule worked or not.
    /// </remarks>
    private static CardDefinition ColouredSpell(
        string name, string text, ManaColor colour, CardType types = CardType.Instant) => new()
        {
            OracleId = "oracle-" + name.ToLowerInvariant().Replace(' ', '-'),
            Name = name,
            OracleText = text,
            CardTypes = types,
            ColorIdentity = [colour],
            Colors = [colour],
        };

    /// <summary>An artifact that pings, for the half of these rules that is about abilities.</summary>
    /// <remarks>
    /// An artifact rather than a creature because the ability costs {T} and a creature would be
    /// summoning sick (CR 302.6) — the test would then be measuring the wrong refusal.
    /// </remarks>
    private static CardDefinition PingingArtifact(string name) => new()
    {
        OracleId = "oracle-" + name.ToLowerInvariant().Replace(' ', '-'),
        Name = name,
        OracleText = "{T}: ~ deals 1 damage to target creature.",
        CardTypes = CardType.Artifact,
    };

    /// <summary>The same, killing rather than pinging, for an assertion that has to outlast a step.</summary>
    /// <remarks>
    /// Damage marked on a permanent is wiped in the cleanup step (CR 514.2), so a test that
    /// settles the game twice can watch its control case evaporate and read that as the rule
    /// working. A creature that is gone stays gone.
    /// </remarks>
    private static CardDefinition DestroyingArtifact(string name) => new()
    {
        OracleId = "oracle-" + name.ToLowerInvariant().Replace(' ', '-'),
        Name = name,
        OracleText = "{T}: Destroy target creature.",
        CardTypes = CardType.Artifact,
    };

    [Fact]
    public void Hexproof_from_a_colour_refuses_that_colour_and_lets_the_others_through()
    {
        // CR 702.11d. The quality is about the spell doing the targeting, which is why it cannot
        // be a keyword flag on the creature and is a restriction asked about the source instead.
        var knight = Card(
            "Hexproof From Black Test",
            "Hexproof from black",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var compiled = CardCompiler.Compile(knight);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var guarded = game.Create(alice, knight, Zone.Battlefield);

        // The control, and the reason this test is worth anything: the same spell in another
        // colour lands. Without it a refusal below could be a spell that was never castable.
        TestCards.PassUntil(game, () => game.State.Priority.Holder == bob);
        var red = TestCards.PutInHand(game, bob, ColouredSpell(
            "Red Ping Test", "~ deals 1 damage to target creature.", ManaColor.Red));
        game.CastSpell(bob, red, [Target.ToPermanent(guarded)]);
        Settle(game);

        Assert.Equal(1, DamageOn(game, guarded));

        TestCards.PassUntil(game, () => game.State.Priority.Holder == bob);
        var black = TestCards.PutInHand(game, bob, ColouredSpell(
            "Black Ping Test", "~ deals 1 damage to target creature.", ManaColor.Black));

        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(bob, black, [Target.ToPermanent(guarded)]));
    }

    [Fact]
    public void Hexproof_from_a_colour_leaves_its_own_controller_alone()
    {
        // CR 702.11d says "your opponents control", which is the whole of what separates this
        // family from shroud. Read without that clause the creature would be untargetable by the
        // player who owns it, and every Aura and pump spell in their deck would stop working.
        var knight = Card(
            "Own Hexproof From Black Test",
            "Hexproof from black",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var (game, alice, bob) = InMainPhase();
        var mine = game.Create(alice, knight, Zone.Battlefield);

        var black = TestCards.PutInHand(game, alice, ColouredSpell(
            "Own Black Ping Test", "~ deals 1 damage to target creature.", ManaColor.Black));
        game.CastSpell(alice, black, [Target.ToPermanent(mine)]);
        Settle(game);

        Assert.Equal(1, DamageOn(game, mine));
    }

    [Fact]
    public void Hexproof_from_a_card_type_asks_about_the_type_and_not_the_colour()
    {
        // Elenda, Saint of Dusk's quality. A card type is a quality like a colour (CR 702.11d),
        // and it is the one that shows the flags could never have carried this: there is a flag
        // per protection colour and there is no supply of them for "instants", "planeswalkers"
        // and "artifacts, creatures, and enchantments".
        var saint = Card(
            "Hexproof From Instants Test",
            "Hexproof from instants",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var compiled = CardCompiler.Compile(saint);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var guarded = game.Create(alice, saint, Zone.Battlefield);

        // A sorcery is cast at sorcery speed, so this needs the caster's own main phase — and the
        // passing has to happen before anything reaches his hand. The harness answers a
        // discard-to-hand-size question with the first card it holds, which is how a fixture put
        // in hand a turn early goes missing.
        TestCards.PassUntil(game, () => game.State.ActivePlayerId == bob
            && game.State.CurrentStep == TurnStep.PrecombatMain
            && game.State.Priority.Holder == bob);

        var instant = TestCards.PutInHand(game, bob, ColouredSpell(
            "Instant Ping Test", "~ deals 1 damage to target creature.", ManaColor.Red));

        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(bob, instant, [Target.ToPermanent(guarded)]));

        // The control, in the same colour and at the same creature: only the card type differs,
        // so the refusal above is the quality being read and nothing else.
        var sorcery = TestCards.PutInHand(game, bob, ColouredSpell(
            "Sorcery Ping Test",
            "~ deals 1 damage to target creature.",
            ManaColor.Red,
            CardType.Sorcery));

        game.CastSpell(bob, sorcery, [Target.ToPermanent(guarded)]);
        Settle(game);

        Assert.Equal(1, DamageOn(game, guarded));
    }

    [Fact]
    public void A_keyword_list_ending_in_hexproof_from_keeps_the_keywords_in_front_of_it()
    {
        // Sporeweb Weaver's line. The words are one line and two different things, and the
        // keyword reader could only ever take the whole line or none of it — so a card printing
        // both lost its reach as well as its hexproof.
        var weaver = Card(
            "Reach And Hexproof Test",
            "Reach, hexproof from blue",
            CardType.Creature,
            power: 1,
            toughness: 4,
            keywords: KeywordAbility.Reach);

        var compiled = CardCompiler.Compile(weaver);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var guarded = game.Create(alice, weaver, Zone.Battlefield);

        Assert.True(Characteristics.Of(game.State, Pool, game.State.GetObject(guarded))
            .Has(KeywordAbility.Reach));

        TestCards.PassUntil(game, () => game.State.Priority.Holder == bob);
        var red = TestCards.PutInHand(game, bob, ColouredSpell(
            "Weaver Red Ping Test", "~ deals 1 damage to target creature.", ManaColor.Red));
        game.CastSpell(bob, red, [Target.ToPermanent(guarded)]);
        Settle(game);

        Assert.Equal(1, DamageOn(game, guarded));

        TestCards.PassUntil(game, () => game.State.Priority.Holder == bob);
        var blue = TestCards.PutInHand(game, bob, ColouredSpell(
            "Weaver Blue Ping Test", "~ deals 1 damage to target creature.", ManaColor.Blue));

        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(bob, blue, [Target.ToPermanent(guarded)]));
    }

    [Fact]
    public void A_prohibition_naming_spells_alone_leaves_abilities_free_to_target()
    {
        // Spectral Shield. The printed sentence names one of the two and means one of the two, so
        // an engine that could only say "hexproof" would be reading a strictly better card.
        var shield = Card(
            "Untargetable By Spells Test",
            "Enchant creature\nEnchanted creature gets +0/+2 and can't be the target of spells.",
            CardType.Enchantment,
            subtypes: "Aura");

        var compiled = CardCompiler.Compile(shield);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var bear = game.Create(alice, TestCards.Creature("Shielded Bear", 2, 2), Zone.Battlefield);
        var aura = TestCards.PutInHand(game, alice, shield);
        game.CastSpell(alice, aura, [Target.ToPermanent(bear)]);
        Settle(game);

        Assert.Equal(4, Characteristics.ToughnessOf(game.State, Pool, game.State.GetObject(bear)));

        var rod = game.Create(bob, DestroyingArtifact("Shield Rod Test"), Zone.Battlefield);
        TestCards.PassUntil(game, () => game.State.Priority.Holder == bob);

        var spell = TestCards.PutInHand(
            game, bob, Card("Shield Spell Test", "Destroy target creature."));

        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(bob, spell, [Target.ToPermanent(bear)]));

        // The control, and the half the sentence does not cover: the identical effect from an
        // ability reaches the creature, so the refusal above is the word "spells" being read and
        // not a creature nothing could ever aim at.
        game.ActivateAbility(bob, rod, "a", [Target.ToPermanent(bear)]);
        Settle(game);

        Assert.DoesNotContain(
            game.State.Battlefield.Select(game.State.GetObject),
            o => o.Card.Name == "Shielded Bear");
    }

    [Fact]
    public void A_prohibition_naming_abilities_alone_is_the_mirror_of_it()
    {
        // Shanna, Sisay's Legacy. The same grammar with the other half taken, and it has to be
        // told apart at the moment the question is asked: CR 113.7a says an ability's source is
        // the object it came from, so a permanent doing the targeting is an ability and anything
        // else is a spell.
        var shanna = Card(
            "Untargetable By Abilities Test",
            "~ can't be the target of abilities your opponents control.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var compiled = CardCompiler.Compile(shanna);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var guarded = game.Create(alice, shanna, Zone.Battlefield);
        var rod = game.Create(bob, PingingArtifact("Shanna Ping Rod Test"), Zone.Battlefield);

        TestCards.PassUntil(game, () => game.State.Priority.Holder == bob);
        var spell = TestCards.PutInHand(game, bob, ColouredSpell(
            "Shanna Ping Spell Test", "~ deals 1 damage to target creature.", ManaColor.Red));
        game.CastSpell(bob, spell, [Target.ToPermanent(guarded)]);
        Settle(game);

        Assert.Equal(1, DamageOn(game, guarded));

        TestCards.PassUntil(game, () => game.State.Priority.Holder == bob);

        Assert.Throws<InvalidOperationException>(
            () => game.ActivateAbility(bob, rod, "a", [Target.ToPermanent(guarded)]));
    }

    [Fact]
    public void A_group_prohibition_covers_that_group_and_nobody_else()
    {
        // Spellbane Centaur, and the one line of this family that goes through the mass-static
        // grammar rather than a pattern of its own. That is deliberate: the noun phrase and the
        // ownership clause are the ones every other group prohibition uses, and a second copy of
        // that vocabulary is what read a sentence-opening "That creature" as a creature subtype.
        var centaur = Card(
            "Group Untargetable Test",
            "Creatures you control can't be the targets of blue spells or abilities from blue "
                + "sources.",
            CardType.Creature,
            power: 3,
            toughness: 3);

        var compiled = CardCompiler.Compile(centaur);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, centaur, Zone.Battlefield);
        var mine = game.Create(alice, TestCards.Creature("Guarded Bear", 2, 2), Zone.Battlefield);
        var theirs = game.Create(bob, TestCards.Creature("Open Bear", 2, 2), Zone.Battlefield);

        // Two controls, because the sentence makes two claims. A blue spell reaches a creature
        // the centaur's controller does not control…
        TestCards.PassUntil(game, () => game.State.Priority.Holder == bob);
        var atTheirs = TestCards.PutInHand(game, bob, ColouredSpell(
            "Blue Ping Elsewhere Test", "~ deals 1 damage to target creature.", ManaColor.Blue));
        game.CastSpell(bob, atTheirs, [Target.ToPermanent(theirs)]);
        Settle(game);

        Assert.Equal(1, DamageOn(game, theirs));

        // …and a spell of another colour reaches one they do.
        TestCards.PassUntil(game, () => game.State.Priority.Holder == bob);
        var red = TestCards.PutInHand(game, bob, ColouredSpell(
            "Red Ping Guarded Test", "~ deals 1 damage to target creature.", ManaColor.Red));
        game.CastSpell(bob, red, [Target.ToPermanent(mine)]);
        Settle(game);

        Assert.Equal(1, DamageOn(game, mine));

        TestCards.PassUntil(game, () => game.State.Priority.Holder == bob);
        var blue = TestCards.PutInHand(game, bob, ColouredSpell(
            "Blue Ping Guarded Test", "~ deals 1 damage to target creature.", ManaColor.Blue));

        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(bob, blue, [Target.ToPermanent(mine)]));
    }

    [Fact]
    public void A_quality_the_reader_cannot_name_leaves_the_whole_line_unread()
    {
        // The direction a prohibition must never fail in. Read generously, "hexproof from
        // Dragons" would be plain hexproof and the creature would be untargetable by everything —
        // a strictly better card, and one the coverage figure would score as a win.
        var compiled = CardCompiler.Compile(Card(
            "Unknown Quality Test",
            "Hexproof from Dragons",
            CardType.Creature,
            power: 2,
            toughness: 2));

        Assert.False(compiled.IsComplete);
        Assert.Contains("Hexproof from Dragons", compiled.Unhandled);
    }

    [Fact]
    public void A_permanent_can_say_cant_be_countered_about_a_group_of_spells()
    {
        // Prowling Serpopard. The keyword has existed since the first counterspell and could only
        // ever be said by a spell about itself, because the flag lives on the card being
        // countered. What was missing was a permanent's voice, not a parameter on the keyword.
        var serpopard = Card(
            "Group Uncounterable Test",
            "Creature spells you control can't be countered.",
            CardType.Creature,
            power: 4,
            toughness: 3);

        var compiled = CardCompiler.Compile(serpopard);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, serpopard, Zone.Battlefield);

        var beast = TestCards.PutInHand(
            game, alice, TestCards.Creature("Uncounterable Beast Test", 3, 3));
        var onStack = game.CastSpell(alice, beast, []);

        TestCards.PassUntil(game, () => game.State.Priority.Holder == bob);
        var counter = TestCards.PutInHand(
            game, bob, Card("Serpopard Counter Test", "Counter target spell."));

        // Targeting is legal — CR 701.6a is about the effect, not about the choice of target,
        // which is the same shape the keyword arm already had.
        game.CastSpell(bob, counter, [Target.ToSpell(onStack)]);
        Settle(game);

        Assert.Contains(
            game.State.Battlefield.Select(game.State.GetObject),
            o => o.Card.Name == "Uncounterable Beast Test");
    }

    [Fact]
    public void The_group_ban_reads_both_halves_of_what_it_names()
    {
        // Two controls for one sentence. "Creature spells" is not "spells", and "you control" is
        // not "anybody's" — a ban widened in either direction would make a counterspell useless
        // against half the table, and the count of complete cards would not notice.
        var serpopard = Card(
            "Two Halves Uncounterable Test",
            "Creature spells you control can't be countered.",
            CardType.Creature,
            power: 4,
            toughness: 3);

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, serpopard, Zone.Battlefield);

        var trick = TestCards.PutInHand(
            game, alice, Card("Noncreature Under Ban Test", "You gain 5 life."));
        var onStack = game.CastSpell(alice, trick, []);

        TestCards.PassUntil(game, () => game.State.Priority.Holder == bob);
        var counter = TestCards.PutInHand(
            game, bob, Card("Noncreature Counter Test", "Counter target spell."));
        game.CastSpell(bob, counter, [Target.ToSpell(onStack)]);
        Settle(game);

        Assert.Equal(20, game.State.GetPlayer(alice).Life);

        // The other half: the ban is read around whoever controls the permanent, so the opponent's
        // creature spell is still counterable.
        TestCards.PassUntil(game, () => game.State.ActivePlayerId == bob
            && game.State.CurrentStep == TurnStep.PrecombatMain
            && game.State.Priority.Holder == bob);

        var theirs = TestCards.PutInHand(
            game, bob, TestCards.Creature("Counterable Beast Test", 3, 3));
        var theirSpell = game.CastSpell(bob, theirs, []);

        TestCards.PassUntil(game, () => game.State.Priority.Holder == alice);
        var second = TestCards.PutInHand(
            game, alice, Card("Their Beast Counter Test", "Counter target spell."));
        game.CastSpell(alice, second, [Target.ToSpell(theirSpell)]);
        Settle(game);

        Assert.DoesNotContain(
            game.State.Battlefield.Select(game.State.GetObject),
            o => o.Card.Name == "Counterable Beast Test");
    }

    [Fact]
    public void The_group_ban_stops_dead_when_its_permanent_leaves()
    {
        // CR 611.2c, and the reason this is a ban read off the battlefield rather than anything
        // written into state: there is nothing to sweep. The same creature spell that survived a
        // counter a moment ago is countered once the permanent saying so is in the graveyard.
        var serpopard = Card(
            "Departing Uncounterable Test",
            "Creature spells you control can't be countered.",
            CardType.Creature,
            power: 4,
            toughness: 3);

        var (game, alice, bob) = InMainPhase();
        var host = game.Create(alice, serpopard, Zone.Battlefield);
        game.Move(host, Zone.Graveyard, MoveCause.Destroy);
        Settle(game);

        TestCards.PassUntil(game, () => game.State.ActivePlayerId == alice
            && game.State.CurrentStep == TurnStep.PrecombatMain
            && game.State.Priority.Holder == alice);

        var beast = TestCards.PutInHand(
            game, alice, TestCards.Creature("Unprotected Beast Test", 3, 3));
        var onStack = game.CastSpell(alice, beast, []);

        TestCards.PassUntil(game, () => game.State.Priority.Holder == bob);
        var counter = TestCards.PutInHand(
            game, bob, Card("Departed Counter Test", "Counter target spell."));
        game.CastSpell(bob, counter, [Target.ToSpell(onStack)]);
        Settle(game);

        Assert.DoesNotContain(
            game.State.Battlefield.Select(game.State.GetObject),
            o => o.Card.Name == "Unprotected Beast Test");
    }

    // ---- Emblems (CR 114) ----------------------------------------------------

    /// <summary>Every emblem an object in the command zone, and nothing else in play.</summary>
    private static IEnumerable<GameObject> EmblemsOf(Game game) =>
        game.State.Command.Select(game.State.GetObject).Where(Emblems.IsEmblem);

    /// <summary>
    /// The ultimate makes an emblem, its anthem applies, and neither the sweeper nor the
    /// planeswalker's own death touches it.
    /// </summary>
    /// <remarks>
    /// Elspeth, Sun's Champion's printed text, all three loyalty abilities. It is the whole shape
    /// of CR 114 in one card: the emblem is put into the command zone (114.2), it has no
    /// characteristics but its ability (114.3), that ability functions from there (114.4), and
    /// nothing in the rules can take it away — so the anthem is still pumping a creature that
    /// arrived after the board was wiped and long after the planeswalker that made it died.
    /// <para>
    /// The ultimate spends every counter it has, which makes the last point the test's cheapest:
    /// the source is in the graveyard by the time the emblem is measured, so what is applying the
    /// bonus cannot be a static ability of any permanent.
    /// </para>
    /// </remarks>
    [Fact]
    public void An_emblems_static_applies_from_the_command_zone_and_outlives_a_board_wipe()
    {
        var elspeth = Walker(
            "Command Anthem Walker Test",
            7,
            "+1: Create three 1/1 white Soldier creature tokens.\n"
                + "−2: Destroy all creatures with power 4 or greater.\n"
                + "−7: You get an emblem with \"Creatures you control get +2/+2 and have flying.\"");

        var compiled = CardCompiler.Compile(elspeth);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var walker = game.Create(alice, elspeth, Zone.Battlefield);
        var bear = game.Create(
            alice, TestCards.Creature("Command Anthem Bear Test", 2, 2), Zone.Battlefield);

        game.ActivateAbility(alice, walker, "loyalty2");
        Settle(game);

        // CR 704.5i: seven counters off a seven-loyalty planeswalker is a planeswalker in the
        // graveyard. What follows is being done by something that is not on the battlefield.
        Assert.DoesNotContain(walker, game.State.Battlefield);

        var emblem = Assert.Single(EmblemsOf(game));

        // CR 114.2 and 114.3: owned and controlled by that player, and no card type at all.
        Assert.Equal(alice, emblem.OwnerId);
        Assert.Equal(alice, emblem.ControllerId);
        Assert.Equal(CardType.None, emblem.Card.CardTypes);

        var pumped = Characteristics.Of(game.State, Pool, game.State.GetObject(bear));
        Assert.Equal(4, pumped.Power);
        Assert.Equal(4, pumped.Toughness);
        Assert.True(pumped.Has(KeywordAbility.Flying));

        var wrath = TestCards.PutInHand(
            game, alice, Card("Command Anthem Wrath Test", "Destroy all creatures."));

        game.CastSpell(alice, wrath, []);
        Settle(game);

        Assert.DoesNotContain(bear, game.State.Battlefield);
        Assert.Contains(emblem.Id, game.State.Command);

        var later = game.Create(
            alice, TestCards.Creature("Command Anthem Survivor Test", 2, 2), Zone.Battlefield);

        var still = Characteristics.Of(game.State, Pool, game.State.GetObject(later));
        Assert.Equal(4, still.Power);
        Assert.True(still.Has(KeywordAbility.Flying));

        // The emblem's abilities travel as the words that made it, inside the arrival event, so a
        // game saved and read back in another process has to rebuild the same definition. The
        // ordinary Settle invariant only replays the log in memory; this is the other half.
        Assert.Equal(
            game.State,
            GameReducer.Replay(EventLogSerializer.Read(EventLogSerializer.Write(game.Log))));
    }

    /// <summary>
    /// An emblem's triggered ability watches from the command zone, and keeps watching.
    /// </summary>
    /// <remarks>
    /// Ajani, Adversary of Tyrants' emblem, on a walker given the loyalty to reach it in one
    /// activation. The compiler wrote <see cref="Zone.Battlefield"/> onto the trigger, because
    /// that is what it writes onto every trigger it reads; <c>Emblems.TriggersOf</c> is what moves
    /// it to the zone CR 114.4 says its abilities work in, and without that the emblem would sit
    /// there reading perfectly and firing never.
    /// <para>
    /// Two of Alice's end steps and one of Bob's, because "your end step" has to mean the emblem's
    /// controller. Six Cats and not nine is the assertion that says so.
    /// </para>
    /// </remarks>
    [Fact]
    public void An_emblems_trigger_fires_on_each_of_its_controllers_turns_and_no_others()
    {
        var ajani = Walker(
            "Command Cats Walker Test",
            7,
            "−7: You get an emblem with \"At the beginning of your end step, create three 1/1 "
                + "white Cat creature tokens with lifelink.\"");

        var compiled = CardCompiler.Compile(ajani);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var walker = game.Create(alice, ajani, Zone.Battlefield);

        game.ActivateAbility(alice, walker, "loyalty");
        Settle(game);

        Assert.Single(EmblemsOf(game));

        static int Cats(Game game) => game.State.Battlefield
            .Select(game.State.GetObject)
            .Count(o => string.Equals(o.Card.Name, "Cat", StringComparison.Ordinal));

        Assert.Equal(0, Cats(game));

        PassTo(game, 1, TurnStep.End);
        Settle(game);
        Assert.Equal(3, Cats(game));

        // Turn two is Bob's end step, and the emblem is Alice's. Turn three is hers again.
        PassTo(game, 3, TurnStep.End);
        Settle(game);
        Assert.Equal(6, Cats(game));
    }

    /// <summary>
    /// An emblem is handed to the player the sentence targeted, and watches on their behalf.
    /// </summary>
    /// <remarks>
    /// Garruk, Apex Predator's printed ultimate, which is the only emblem in the corpus whose
    /// whole point is that somebody else gets it. "You" inside the quotation means the emblem's
    /// controller and not the planeswalker's, so Alice attacking Bob is what fires it — and the
    /// creature that gets the bonus is Alice's own attacker.
    /// </remarks>
    [Fact]
    public void An_emblem_given_to_an_opponent_is_theirs_and_triggers_for_them()
    {
        var garruk = Walker(
            "Command Gift Walker Test",
            8,
            "−8: Target opponent gets an emblem with \"Whenever a creature attacks you, it gets "
                + "+5/+5 and gains trample until end of turn.\"");

        var compiled = CardCompiler.Compile(garruk);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var walker = game.Create(alice, garruk, Zone.Battlefield);
        var attacker = game.Create(
            alice,
            Card("Command Gift Attacker Test", string.Empty, CardType.Creature, 2, 2, KeywordAbility.Haste),
            Zone.Battlefield);

        game.ActivateAbility(alice, walker, "loyalty", [Target.ToPlayer(bob)]);
        Settle(game);

        var emblem = Assert.Single(EmblemsOf(game));
        Assert.Equal(bob, emblem.OwnerId);
        Assert.Equal(bob, emblem.ControllerId);

        PassTo(game, 1, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        Settle(game);

        Assert.Single(TriggersFiledBy(game, emblem.Id));

        var buffed = Characteristics.Of(game.State, Pool, game.State.GetObject(attacker));
        Assert.Equal(7, buffed.Power);
        Assert.True(buffed.Has(KeywordAbility.Trample));
    }

    /// <summary>
    /// An emblem whose text the engine could not run leaves the whole line in the work queue.
    /// </summary>
    /// <remarks>
    /// The fail-closed half, and the reason the gate is a comparison against an empty compile
    /// rather than a list of what an emblem may carry. Both of these compile perfectly as
    /// <em>cards</em>, and both would be silent as emblems:
    /// <list type="bullet">
    /// <item>Saheeli, Filigree Master's second quoted ability is a cost reduction. A cost modifier
    /// is gathered from the battlefield, so the emblem would grant the +1/+1 and quietly charge
    /// full price for every artifact spell.</item>
    /// <item>Nissa, Who Shakes the World prints an instruction <em>after</em> the quotation, and
    /// the full stop that would have separated them is inside it — so the clause splitter hands
    /// both halves over as one sentence. Reading the emblem and dropping the rest would have made
    /// a library search for any number of Forests vanish off a card reporting itself understood.
    /// </item>
    /// </list>
    /// A refusal is the honest answer to both: the card stays in the queue with a name on it,
    /// which is how the next round finds it.
    /// </remarks>
    [Fact]
    public void An_emblem_the_engine_cannot_run_leaves_its_line_unread()
    {
        var saheeli = Walker(
            "Command Refused Walker Test",
            4,
            "−4: You get an emblem with \"Artifact creatures you control get +1/+1\" and "
                + "\"Artifact spells you cast cost {1} less to cast.\"");

        var refused = CardCompiler.Compile(saheeli);
        Assert.Contains(
            refused.Unhandled, l => l.Contains("emblem with", StringComparison.Ordinal));

        var nissa = Walker(
            "Command Trailing Walker Test",
            8,
            "−8: You get an emblem with \"Lands you control have indestructible.\" Search your "
                + "library for any number of Forest cards, put them onto the battlefield tapped, "
                + "then shuffle.");

        // The quoted half on its own is an emblem this engine runs, which is what makes the
        // refusal meaningful rather than incidental.
        Assert.True(Emblems.Reads(Emblems.CardFor("Lands you control have indestructible.")));

        var trailing = CardCompiler.Compile(nissa);
        Assert.Contains(
            trailing.Unhandled, l => l.Contains("emblem with", StringComparison.Ordinal));
    }

    /// <summary>
    /// A dungeon and an emblem share the command zone without reading each other.
    /// </summary>
    /// <remarks>
    /// Two kinds of rules object now work from the same zone (CR 114.4, CR 309.4c), and each is
    /// recognised by an id prefix of its own rather than by being the only thing there. The
    /// interesting half is the sweep <c>Characteristics.Candidates</c> gained: it runs inside the
    /// layer computation, where CR 613.8's dependency question has produced a stack overflow in
    /// this engine before, so it reads <em>raw state</em> — the object's zone and its card's id —
    /// and never the computed characteristics of anything.
    /// <para>
    /// The Goblin is what proves both halves at once. It exists because the dungeon's room
    /// ability fired from the command zone with an emblem sitting beside it, and it is 3/3 with
    /// flying because the emblem's anthem reached a token the dungeon made.
    /// </para>
    /// </remarks>
    [Fact]
    public void An_emblem_and_a_dungeon_share_the_command_zone_without_reading_each_other()
    {
        var elspeth = Walker(
            "Command Coexist Walker Test",
            7,
            "−7: You get an emblem with \"Creatures you control get +2/+2 and have flying.\"");

        var (game, alice, _) = InMainPhase();
        var walker = game.Create(alice, elspeth, Zone.Battlefield);

        game.ActivateAbility(alice, walker, "loyalty");
        Settle(game);

        VentureTo(game, alice, "Cave Entrance", "Goblin Lair");

        var dungeon = DungeonOf(game, alice);
        Assert.NotNull(dungeon);

        var emblem = Assert.Single(EmblemsOf(game));
        Assert.NotEqual(dungeon.Id, emblem.Id);

        // Neither reader answers for the other's object, which is what keeps one sweep of the
        // command zone from picking up two kinds of thing.
        Assert.False(Emblems.IsEmblem(dungeon));
        Assert.Empty(Emblems.TriggersOf(dungeon, Pool));
        Assert.Empty(Emblems.StaticsOf(dungeon, Pool));
        Assert.Empty(Dungeons.RoomAbilitiesOf(emblem));

        var goblin = Assert.Single(
            game.State.Battlefield.Select(game.State.GetObject),
            o => string.Equals(o.Card.Name, "Goblin", StringComparison.Ordinal));

        Assert.Equal(3, PowerNow(game, goblin.Id));
        Assert.True(Now(game, goblin.Id).Has(KeywordAbility.Flying));
    }

    // ---- Excess damage (CR 120.4a) -------------------------------------------

    /// <summary>
    /// The damage past lethal goes to the creature's controller, and only the damage past lethal.
    /// </summary>
    /// <remarks>
    /// Pigment Storm's printed text. The engine had every part of this number already — damage
    /// marked, computed toughness, the state-based comparison of one against the other — and had
    /// never subtracted one from the other, so the sentence was unread on every card that prints
    /// it. <c>ExcessDamage.Over</c> is that subtraction, and CR 120.4a is emphatic about when it
    /// happens: it is step one of four, before replacement and prevention, which is why the split
    /// is made where the damage event is built.
    /// <para>
    /// The 6/6 beside the 2/2 is what makes the assertion mean anything. An implementation that
    /// sent the whole five to the player, or none of it, would look identical from one creature.
    /// </para>
    /// </remarks>
    [Fact]
    public void Excess_damage_is_dealt_to_the_creatures_controller_and_the_rest_is_not()
    {
        var storm = Card(
            "Excess Storm Test",
            "~ deals 5 damage to target creature. Excess damage is dealt to that creature's "
                + "controller instead.");

        var compiled = CardCompiler.Compile(storm);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var small = game.Create(bob, TestCards.Creature("Excess Small Test", 2, 2), Zone.Battlefield);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, storm), [Target.ToPermanent(small)]);
        Settle(game);

        // Two of the five were lethal to a 2/2; the other three went to Bob as damage from the
        // same source, which is what "instead" means — not life loss.
        Assert.DoesNotContain(small, game.State.Battlefield);
        Assert.Equal(17, game.State.GetPlayer(bob).Life);

        TestCards.PassUntil(game, () => game.State.ActivePlayerId == alice
            && game.State.CurrentStep == TurnStep.PrecombatMain
            && game.State.Priority.Holder == alice);

        var big = game.Create(bob, TestCards.Creature("Excess Big Test", 6, 6), Zone.Battlefield);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, storm), [Target.ToPermanent(big)]);
        Settle(game);

        // Nothing is in excess of lethal on a 6/6, so the whole five stays on the creature.
        Assert.Contains(big, game.State.Battlefield);
        Assert.Equal(5, game.State.GetObject(big).Permanent!.DamageMarked);
        Assert.Equal(17, game.State.GetPlayer(bob).Life);
    }

    /// <summary>
    /// Damage already marked counts towards lethal, so the excess grows (CR 120.6).
    /// </summary>
    /// <remarks>
    /// Ravenous Tyrannosaurus prints the same rider on a trigger rather than a spell, which is
    /// the other half of why this is a field on the damage effect and not a sentence of its own:
    /// wherever the damage is dealt from, the split is the same.
    /// </remarks>
    [Fact]
    public void Excess_damage_counts_the_damage_already_marked_on_the_creature()
    {
        var storm = Card(
            "Excess Marked Test",
            "~ deals 4 damage to target creature. Excess damage is dealt to that creature's "
                + "controller instead.");

        var ping = Card("Excess Ping Test", "~ deals 3 damage to any target.");

        var (game, alice, bob) = InMainPhase();
        var wall = game.Create(bob, TestCards.Creature("Excess Wall Test", 1, 5), Zone.Battlefield);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, ping), [Target.ToPermanent(wall)]);
        Settle(game);

        Assert.Equal(3, game.State.GetObject(wall).Permanent!.DamageMarked);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, storm), [Target.ToPermanent(wall)]);
        Settle(game);

        // Two more were lethal to a 1/5 already carrying three; the other two went to Bob.
        Assert.DoesNotContain(wall, game.State.Battlefield);
        Assert.Equal(18, game.State.GetPlayer(bob).Life);
    }

    /// <summary>
    /// The rider is refused when it has no damage of its own line to modify.
    /// </summary>
    /// <remarks>
    /// Gandalf's Sanction is the corpus's one case: "~ deals X damage to target creature, where X
    /// is the number of instant and sorcery cards in your graveyard" is read as a counted
    /// variable wrapping the damage, so the rider's search for a top-level hit to modify finds
    /// nothing.
    /// <para>
    /// A rider that quietly found nothing would leave a card printing a redirect and performing
    /// none — the whole five damage on the creature, and a player who should have taken three
    /// taking nothing. Refusing puts the card back in the work queue under its own name, which is
    /// where the next round will find it.
    /// </para>
    /// </remarks>
    [Fact]
    public void An_excess_rider_with_no_damage_to_modify_leaves_its_line_unread()
    {
        var sanction = Card(
            "Excess Counted Test",
            "~ deals X damage to target creature, where X is the number of instant and sorcery "
                + "cards in your graveyard. Excess damage is dealt to that creature's controller "
                + "instead.");

        var compiled = CardCompiler.Compile(sanction);
        Assert.Contains(
            compiled.Unhandled, l => l.Contains("Excess damage", StringComparison.Ordinal));
    }

    /// <summary>
    /// Damage with no excess rider is dealt whole, however far past lethal it goes (CR 120.3e).
    /// </summary>
    /// <remarks>
    /// The control the redirect needs, and it is not optional: splitting a damage event at lethal
    /// is invisible to coverage, because the line reads either way. A rider that fired on every
    /// burn spell in the game would look exactly like the one above working, and the only symptom
    /// would be damage quietly going somewhere else. Six damage to a 2/2 kills the 2/2 and touches
    /// nobody's life total.
    /// </remarks>
    [Fact]
    public void Damage_with_no_excess_rider_is_dealt_whole()
    {
        var bolt = Card("Excess Control Test", "~ deals 6 damage to target creature.");

        var compiled = CardCompiler.Compile(bolt);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        // The flag is off on the compiled effect, not merely unobserved at runtime.
        Assert.All(
            compiled.Spell!.Effects.OfType<DealDamage>(),
            d => Assert.False(d.ExcessToTargetsController));

        var (game, alice, bob) = InMainPhase();
        var bear = game.Create(
            bob, TestCards.Creature("Excess Control Bear Test", 2, 2), Zone.Battlefield);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, bolt), [Target.ToPermanent(bear)]);
        Settle(game);

        Assert.DoesNotContain(bear, game.State.Battlefield);
        Assert.Equal(20, game.State.GetPlayer(bob).Life);
    }

    // ---- Backgrounds (CR 702.123) --------------------------------------------

    /// <summary>
    /// "Commander creatures you own have [ability]" reaches the commander and nothing else.
    /// </summary>
    /// <remarks>
    /// A Background's whole text is this one sentence, and the group it names is the only one in
    /// the corpus picked out by something that is not a characteristic: being a commander is a
    /// designation its owner gave a card before the game began (CR 903.3), so the question has to
    /// be asked of the player rather than of the permanent.
    /// <para>
    /// The ordinary creature beside it is what carries the test. A filter that returned true for
    /// every creature you own would look identical from the commander's side.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_Background_grants_only_to_your_commander()
    {
        var background = Card(
            "Test Background",
            "Commander creatures you own have \"{T}: Draw a card.\"",
            CardType.Enchantment,
            null,
            null,
            KeywordAbility.None,
            "Background");

        var compiled = CardCompiler.Compile(background);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var alice = Guid.Parse("11111111-1111-1111-1111-111111111111");
        var bob = Guid.Parse("22222222-2222-2222-2222-222222222222");

        var boss = Card(
            "Test Background Commander",
            string.Empty,
            CardType.Creature,
            3,
            3,
            KeywordAbility.Haste);

        var game = Game.Start(
            Guid.NewGuid(),
            [
                new PlayerSetup(alice, "Alice", 40, [.. TestCards.Deck(40, "Alice"), boss])
                {
                    CommanderOracleId = boss.OracleId,
                },
                new PlayerSetup(bob, "Bob", 40, TestCards.Deck(40, "Bob")),
            ],
            new GameRandom(3),
            startingPlayerId: alice,
            abilities: Pool);

        game.BeginPlay(withMulligans: false);
        TestCards.PassToStep(game, TurnStep.PrecombatMain);

        var commander = game.Create(alice, boss, Zone.Battlefield);
        var ordinary = game.Create(
            alice,
            Card("Test Background Bear", string.Empty, CardType.Creature, 2, 2, KeywordAbility.Haste),
            Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, background);
        game.CastSpell(alice, card, []);
        Settle(game);

        static IReadOnlyList<string> GrantedOn(Game game, ObjectId id) =>
        [
            .. Game.ActivatedAbilitiesOf(game.State, Pool, game.State.GetObject(id))
                .Select(a => a.Id)
                .Where(a => a.StartsWith("granted:", StringComparison.Ordinal)),
        ];

        Assert.NotEmpty(GrantedOn(game, commander));
        Assert.Empty(GrantedOn(game, ordinary));
    }
    // ---- Modes with a price, and costs paid in something other than mana -----

    /// <summary>A card with a real printed mana cost, so an alternative to it means something.</summary>
    private static CardDefinition PricedCard(
        string name,
        string manaCost,
        int cmc,
        string oracleText,
        CardType types = CardType.Creature) => new()
        {
            OracleId = "oracle-" + name.ToLowerInvariant().Replace(' ', '-'),
            Name = name,
            ManaCostRaw = manaCost,
            Cmc = cmc,
            OracleText = oracleText,
            CardTypes = types,
            Power = types.HasFlag(CardType.Creature) ? 4 : null,
            Toughness = types.HasFlag(CardType.Creature) ? 5 : null,
        };

    private static CardDefinition SpreeRaid() => Card(
        "Requisition Raid Test",
        "Spree (Choose one or more additional costs.)\n"
            + "+ {1} — Destroy target artifact.\n"
            + "+ {1} — Destroy target enchantment.");

    [Fact]
    public void Spree_charges_only_the_mode_that_was_taken()
    {
        var raid = SpreeRaid();

        var compiled = CardCompiler.Compile(raid);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.Equal(2, compiled.Spell!.Modes.Count);
        Assert.Equal(1, compiled.Spell.ModesToChoose);
        Assert.Equal(2, compiled.Spell.ModesMax);

        var (game, alice, bob) = InMainPhase();
        var relic = game.Create(bob, Card("Spree Relic Test", string.Empty, CardType.Artifact), Zone.Battlefield);
        var shrine = game.Create(bob, Card("Spree Shrine Test", string.Empty, CardType.Enchantment), Zone.Battlefield);

        game.AddMana(alice, ManaColor.White);

        var card = TestCards.PutInHand(game, alice, raid);
        game.CastSpell(alice, card, [Target.ToPermanent(relic)], modes: [0]);
        Settle(game);

        // One mode taken, one mode's price paid, and the mode nobody chose did nothing.
        Assert.DoesNotContain(relic, game.State.Battlefield);
        Assert.Contains(shrine, game.State.Battlefield);
        Assert.True(game.State.GetPlayer(alice).ManaPool.IsEmpty);
    }

    [Fact]
    public void Spree_charges_every_mode_that_was_taken()
    {
        var raid = SpreeRaid();
        var (game, alice, bob) = InMainPhase();
        var relic = game.Create(bob, Card("Spree Relic Two Test", string.Empty, CardType.Artifact), Zone.Battlefield);
        var shrine = game.Create(bob, Card("Spree Shrine Two Test", string.Empty, CardType.Enchantment), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, raid);
        game.AddMana(alice, ManaColor.White);

        // CR 700.2h: every chosen mode's cost is paid, so one mana buys one mode and not two. A
        // spree that charged its price once would take both here and leave the pool empty either
        // way, which is why the refusal is asserted as well as the payment.
        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(
                alice,
                card,
                [Target.ToPermanent(relic), Target.ToPermanent(shrine)],
                modes: [0, 1]));

        game.AddMana(alice, ManaColor.White);
        game.CastSpell(
            alice, card, [Target.ToPermanent(relic), Target.ToPermanent(shrine)], modes: [0, 1]);
        Settle(game);

        Assert.Empty(game.State.Battlefield);
        Assert.True(game.State.GetPlayer(alice).ManaPool.IsEmpty);
    }

    [Fact]
    public void The_same_mode_can_be_taken_twice_when_the_card_says_so()
    {
        var confluence = Card(
            "Confluence Test",
            "Choose two. You may choose the same mode more than once.\n"
                + "• You gain 3 life.\n• You draw a card.");

        var compiled = CardCompiler.Compile(confluence);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.True(compiled.Spell!.ModesMayRepeat);

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, confluence);

        // CR 700.2d: the mode is treated as though it appeared twice in sequence, so the life is
        // gained twice. Six rather than three is the whole of what the printed sentence buys.
        game.CastSpell(alice, card, targets: null, modes: [0, 0]);
        Settle(game);

        Assert.Equal(26, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void A_mode_cannot_be_taken_twice_when_the_card_does_not_say_so()
    {
        var charm = Card(
            "Plain Two Modes Test",
            "Choose two —\n• You gain 3 life.\n• You draw a card.");

        var compiled = CardCompiler.Compile(charm);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.False(compiled.Spell!.ModesMayRepeat);

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, charm);

        // The default is a rule, not a convenience (CR 700.2d). Without this half the permission
        // above would be worth nothing, because every modal card would already have it.
        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, card, targets: null, modes: [0, 0]));
    }

    private const string WillCommanderId = "oracle-will-captain-test";

    private static CardDefinition WillCommander() => new()
    {
        OracleId = WillCommanderId,
        Name = "Will's Captain Test",
        Cmc = 3,
        ManaCostRaw = "{1}{G}{G}",
        CardTypes = CardType.Creature,
        Supertypes = ["Legendary"],
        Power = 3,
        Toughness = 3,
    };

    private static (Game Game, Guid Alice, Guid Bob) CommanderTable()
    {
        var alice = Guid.Parse("11111111-1111-1111-1111-111111111111");
        var bob = Guid.Parse("22222222-2222-2222-2222-222222222222");

        var game = Game.Start(
            Guid.NewGuid(),
            [
                new PlayerSetup(
                    alice,
                    "Alice",
                    40,
                    [.. TestCards.Deck(40, "Alice"), WillCommander()])
                {
                    CommanderOracleId = WillCommanderId,
                },
                new PlayerSetup(bob, "Bob", 40, TestCards.Deck(40, "Bob")),
            ],
            new GameRandom(3),
            startingPlayerId: alice,
            abilities: Pool);

        game.BeginPlay(withMulligans: false);
        TestCards.PassToStep(game, TurnStep.PrecombatMain);
        return (game, alice, bob);
    }

    [Fact]
    public void Both_modes_are_offered_only_while_a_commander_is_out()
    {
        var will = Card(
            "Jeska's Will Test",
            "Choose one. If you control a commander as you cast ~, you may choose both instead."
                + "\n• You gain 3 life.\n• You draw a card.");

        var compiled = CardCompiler.Compile(will);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.Equal(1, compiled.Spell!.ModesToChoose);
        Assert.Equal(1, compiled.Spell.ModesMax);
        Assert.Equal(2, compiled.Spell.ExtraModes!.Max);

        var (game, alice, _) = CommanderTable();
        var card = TestCards.PutInHand(game, alice, will);

        // The commander starts in the command zone, so it is not controlled (CR 903.3d) and the
        // wider allowance is not on offer. A maximum compiled as a flat two would take both here.
        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, card, targets: null, modes: [0, 1]));

        game.Create(alice, WillCommander(), Zone.Battlefield);
        var library = game.State.GetPlayer(alice).Library.Count;

        game.CastSpell(alice, card, targets: null, modes: [0, 1]);
        Settle(game);

        Assert.Equal(43, game.State.GetPlayer(alice).Life);
        Assert.Equal(library - 1, game.State.GetPlayer(alice).Library.Count);
    }

    [Fact]
    public void Emerge_pays_with_a_creature_and_takes_its_mana_value_off_the_cost()
    {
        var scuttler = PricedCard("Vexing Scuttler Test", "{8}", 8, "Emerge {6}{U}");

        var compiled = CardCompiler.Compile(scuttler);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.Equal("emerge", compiled.Spell!.ConditionalAlternativeCost!.Keyword);

        var (game, alice, _) = InMainPhase();
        var fodder = game.Create(
            alice, TestCards.Costed("Emerge Fodder Test", "{2}{G}", 3), Zone.Battlefield);
        var card = TestCards.PutInHand(game, alice, scuttler);

        foreach (var _ in Enumerable.Range(0, 3))
            game.AddMana(alice, ManaColor.Blue);

        // {6}{U} less the sacrificed creature's mana value of three is {3}{U}, so three mana is
        // one short. Asserting the refusal as well as the cast is what pins the discount to
        // exactly three: an engine that forgot it would need seven, and one that took too much
        // would let this through.
        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(
                alice, card, targets: null, alternativeCost: true, costPayment: [fodder]));

        game.AddMana(alice, ManaColor.Blue);
        game.CastSpell(
            alice, card, targets: null, alternativeCost: true, costPayment: [fodder]);
        Settle(game);

        Assert.DoesNotContain(fodder, game.State.Battlefield);
        Assert.Contains(
            game.State.Battlefield,
            id => game.State.GetObject(id).Card.Name == "Vexing Scuttler Test");

        Assert.True(game.State.GetPlayer(alice).ManaPool.IsEmpty);
    }

    [Fact]
    public void An_alternative_cost_can_be_paid_by_sacrificing_lands()
    {
        var fireblast = Card(
            "Fireblast Test",
            "You may sacrifice two Mountains rather than pay this spell's mana cost."
                + "\n~ deals 4 damage to any target.");

        var compiled = CardCompiler.Compile(fireblast);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        var offer = Assert.Single(compiled.Spell!.ConditionalAlternativeCost!.Payments);
        Assert.Equal(ChosenCostKind.SacrificePermanents, offer.Kind);
        Assert.Equal(2, offer.Count);

        var (game, alice, bob) = InMainPhase();
        var first = game.Create(alice, TestCards.BasicLand("Mountain"), Zone.Battlefield);
        var second = game.Create(alice, TestCards.BasicLand("Mountain"), Zone.Battlefield);
        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        var card = TestCards.PutInHand(game, alice, fireblast);

        // The cost names Mountains, and a cost that took any land would be a different card.
        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(
                alice,
                card,
                [Target.ToPlayer(bob)],
                alternativeCost: true,
                costPayment: [first, forest]));

        game.CastSpell(
            alice,
            card,
            [Target.ToPlayer(bob)],
            alternativeCost: true,
            costPayment: [first, second]);

        Settle(game);

        Assert.Equal(16, game.State.GetPlayer(bob).Life);
        Assert.Equal(2, game.State.GetPlayer(alice).Graveyard.Count(
            id => game.State.GetObject(id).Card.Name == "Mountain"));

        // Not a single mana was made, which is the point of the whole family.
        Assert.True(game.State.GetPlayer(alice).ManaPool.IsEmpty);
    }

    [Fact]
    public void An_alternative_cost_paid_with_lands_returns_them_rather_than_burying_them()
    {
        var gush = Card(
            "Gush Test",
            "You may return two Islands you control to their owner's hand rather than pay this "
                + "spell's mana cost.\nDraw two cards.");

        var compiled = CardCompiler.Compile(gush);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        var offer = Assert.Single(compiled.Spell!.ConditionalAlternativeCost!.Payments);
        Assert.Equal(ChosenCostKind.ReturnToHand, offer.Kind);

        var (game, alice, _) = InMainPhase();
        var first = game.Create(alice, TestCards.BasicLand("Island"), Zone.Battlefield);
        var second = game.Create(alice, TestCards.BasicLand("Island"), Zone.Battlefield);
        var card = TestCards.PutInHand(game, alice, gush);

        game.CastSpell(alice, card, targets: null, alternativeCost: true, costPayment: [first, second]);
        Settle(game);

        // A cast had never charged this kind before - it reached the engine as ninjutsu's, which
        // is an activated ability - so a spell paying with one put the Islands in the graveyard.
        Assert.Empty(game.State.Battlefield);
