    [Fact]
    public void An_alternative_cost_can_be_paid_by_exiling_a_card_from_hand()
    {
        var force = Card(
            "Force of Will Test",
            "You may pay 1 life and exile a blue card from your hand rather than pay this "
                + "spell's mana cost.\nCounter target spell.");

        var compiled = CardCompiler.Compile(force);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        var offer = compiled.Spell!.ConditionalAlternativeCost!;
        Assert.Equal(1, offer.LifeCost);
        Assert.Equal(ChosenCostKind.ExileFromHand, Assert.Single(offer.Payments).Kind);

        var (game, alice, bob) = InMainPhase();

        TestCards.PassUntil(game, () => game.State.ActivePlayerId == bob
            && game.State.CurrentStep == TurnStep.PrecombatMain
            && game.State.Priority.Holder == bob);

        var theirs = TestCards.PutInHand(game, bob, Card("Pitched At Test", "You gain 5 life."));
        var onStack = game.CastSpell(bob, theirs, []);

        TestCards.PassUntil(game, () => game.State.Priority.Holder == alice);

        var card = TestCards.PutInHand(game, alice, force);
        var blue = TestCards.PutInHand(game, alice, Coloured("Pitch Blue Test", ManaColor.Blue));
        var red = TestCards.PutInHand(game, alice, Coloured("Pitch Red Test", ManaColor.Red));

        // The price names a colour, and a cost that took any card would be the best card in the
        // game rather than the one printed.
        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(
                alice, card, [Target.ToSpell(onStack)], alternativeCost: true, costPayment: [red]));

        game.CastSpell(
            alice, card, [Target.ToSpell(onStack)], alternativeCost: true, costPayment: [blue]);

        Settle(game);

        // Countered, one life lighter, and the blue card exiled rather than discarded - which is
        // the difference the whole family is built on, since a graveyard is somewhere a card can
        // come back from.
        Assert.Equal(20, game.State.GetPlayer(bob).Life);
        Assert.Equal(19, game.State.GetPlayer(alice).Life);
        Assert.Contains(
            game.State.Exile, id => game.State.GetObject(id).Card.Name == "Pitch Blue Test");

        Assert.DoesNotContain(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Pitch Blue Test");
        Assert.True(game.State.GetPlayer(alice).ManaPool.IsEmpty);
    }

    [Fact]
    public void An_alternative_cost_can_ask_for_mana_and_a_tapped_permanent_together()
    {
        var zahid = PricedCard(
            "Zahid Test",
            "{4}{U}{U}",
            6,
            "You may pay {3}{U} and tap an untapped artifact you control rather than pay this "
                + "spell's mana cost.");

        var compiled = CardCompiler.Compile(zahid);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        var offer = compiled.Spell!.ConditionalAlternativeCost!;
        Assert.Equal(ChosenCostKind.TapPermanents, Assert.Single(offer.Payments).Kind);

        var (game, alice, _) = InMainPhase();
        var relic = game.Create(
            alice, Card("Zahid Relic Test", string.Empty, CardType.Artifact), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, zahid);
        foreach (var _ in Enumerable.Range(0, 4))
            game.AddMana(alice, ManaColor.Blue);

        game.CastSpell(
            alice, card, targets: null, alternativeCost: true, costPayment: [relic]);

        Settle(game);

        // Four mana rather than six, and the artifact is turned sideways rather than spent -
        // both halves of one offer, and taking only the cheaper of them is not the printed card.
        Assert.True(game.State.GetObject(relic).Permanent!.IsTapped);
        Assert.True(game.State.GetPlayer(alice).ManaPool.IsEmpty);
        Assert.Contains(
            game.State.Battlefield,
            id => game.State.GetObject(id).Card.Name == "Zahid Test");
    }

    // ---- Facts the cast records, and the clauses that read them back ---------

    /// <summary>
    /// "Kicker [A] and/or [B]" is two kicker abilities, and each read-back clause is linked to
    /// one of them (CR 702.33b, 702.33f, 607.2).
    /// </summary>
    /// <remarks>
    /// Anavolver's wording, because it asks the hardest form of the question: the two clauses
    /// hand out different numbers of counters and different abilities, so a permanent that only
    /// knows it <em>was</em> kicked cannot be told from one that knows <em>which</em> kicker was
    /// paid. The answer also has to survive the move onto the battlefield — CR 400.7 makes that
    /// a new object and CR 607.2 is the exception — which is why every assertion here is about
    /// the permanent rather than the spell.
    /// </remarks>
    [Fact]
    public void A_spell_with_two_kickers_remembers_which_of_them_was_paid()
    {
        var compiled = CardCompiler.Compile(Anavolver());
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.Equal(2, compiled.Spell!.KickerCosts.Count);
        Assert.Equal("{1}{U}", compiled.Spell.KickerCosts[0].Printed);
        Assert.Equal("{B}", compiled.Spell.KickerCosts[1].Printed);

        // The blue kicker alone: two counters and flying, and not the black clause's gift.
        var (blueGame, blue) = CastVolver([0], "Island", "Forest");
        Assert.Equal(2, blue.Permanent!.Counters.GetValueOrDefault("+1/+1"));
        var afterBlue = Characteristics.Of(blueGame.State, Pool, blue);
        Assert.True(afterBlue.Has(KeywordAbility.Flying));
        Assert.Empty(afterBlue.GrantedActivated);

        // The black kicker alone: one counter and the quoted ability, and no flying. A flag that
        // only said "kicked" would hand this creature both clauses.
        var (blackGame, black) = CastVolver([1], "Swamp");
        Assert.Equal(1, black.Permanent!.Counters.GetValueOrDefault("+1/+1"));
        var afterBlack = Characteristics.Of(blackGame.State, Pool, black);
        Assert.False(afterBlack.Has(KeywordAbility.Flying));
        Assert.Single(afterBlack.GrantedActivated);

        // Both, which is three counters — and a spell that paid both has been kicked twice
        // (CR 702.33d), which is a third question again.
        var (bothGame, both) = CastVolver([0, 1], "Island", "Forest", "Swamp");
        Assert.Equal(3, both.Permanent!.Counters.GetValueOrDefault("+1/+1"));
        Assert.Equal(2, both.TimesKicked);
        Assert.True(both.WasKicked);
        var afterBoth = Characteristics.Of(bothGame.State, Pool, both);
        Assert.True(afterBoth.Has(KeywordAbility.Flying));
        Assert.Single(afterBoth.GrantedActivated);
    }

    /// <summary>Each kicker adds its own price to the total cost (CR 702.33b, 601.2f).</summary>
    [Fact]
    public void Both_kickers_of_an_and_or_pair_are_paid_for_separately()
    {
        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, Anavolver());
        TapForMana(game, alice, "Island");
        TapForMana(game, alice, "Forest");

        // {1}{U} and {B} is three mana. Two pays for the blue kicker and nothing else, so a card
        // charging one price for both abilities would be cast here and must not be.
        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, card, targets: null, kickedWith: [0, 1]));

        game.CastSpell(alice, card, targets: null, kickedWith: [0]);
        Settle(game);

        var arrived = game.State.Battlefield
            .Select(game.State.GetObject)
            .Single(o => o.Card.Name == "Anavolver Test");

        Assert.Equal(2, arrived.Permanent!.Counters.GetValueOrDefault("+1/+1"));
    }

    /// <summary>Each of the two kicker abilities may be paid once, and there is no third.</summary>
    [Fact]
    public void A_kicker_from_an_and_or_pair_may_be_paid_only_once()
    {
        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, Anavolver());

        foreach (var land in new[] { "Island", "Forest", "Swamp" })
            TapForMana(game, alice, land);

        // CR 702.33b: two abilities, not one cost paid twice — so the same kicker cannot buy its
        // counters twice, and a card offering two has no third to sell. The mana for both is on
        // the table, so these refusals are about the rule rather than the price.
        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, card, targets: null, kickedWith: [0, 0]));

        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, card, targets: null, kickedWith: [2]));

        // And a card with no such choice refuses the payment by name rather than pocketing it.
        var plain = TestCards.PutInHand(
            game, alice, Card("Volver Plain Test", "You gain 1 life."));

        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, plain, targets: null, kickedWith: [0]));
    }

    /// <summary>Anavolver's printed text, minus the reminder (CR 702.33b, 702.33f).</summary>
    /// <summary>
    /// A multikicker clause that resolves to nothing asks nothing (CR 601.2b, 702.33c).
    /// </summary>
    /// <remarks>
    /// "Target player discards a card for each time it was kicked" on a spell nobody kicked is a
    /// discard of zero cards, and the engine used to stop and ask for it: the options offered
    /// were the whole hand while the range was 0..0, so a player who answered the question the
    /// game had put to them was refused for answering it. It broke three soak tables and no
    /// unit test, because the shape only appears when a real multikicker card is played unkicked
    /// — Bloodhusk Ritualist is the printing.
    /// <para>
    /// The two sibling deferred questions — the mulligan bottom and the cleanup discard — have
    /// always guarded their zero case. This asserts the third one does, from both ends: the
    /// spell resolves, the hand is untouched, and the game is not left waiting.
    /// </para>
    /// </remarks>
    [Fact]
    public void An_unkicked_spell_that_would_discard_nothing_asks_nothing()
    {
        var ritualist = Card(
            "Bloodhusk Ritualist Test",
            "Multikicker {1}{B}\n"
                + "When ~ enters, target player discards a card for each time it was kicked.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var compiled = CardCompiler.Compile(ritualist);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, ritualist);

        // Cards in both hands, so whichever player the trigger picks, the question it would have
        // asked had options to offer - which is the shape that crashed. A hand that is empty
        // takes the other exit and proves nothing.
        TestCards.PutInHand(game, bob, TestCards.Creature("Discard Bait One"));
        TestCards.PutInHand(game, bob, TestCards.Creature("Discard Bait Two"));
        TestCards.PutInHand(game, alice, TestCards.Creature("Discard Bait Three"));

        TapForMana(game, alice, "Swamp");
        TapForMana(game, alice, "Swamp");

        // Counted rather than assumed: both players are holding their opening hands as well.
        var bobHeld = game.State.GetPlayer(bob).Hand.Count;
        var aliceHeld = game.State.GetPlayer(alice).Hand.Count - 1;

        // No targets on the spell: the creature does not target, its enters trigger does, and
        // Settle answers that question the way a player would.
        game.CastSpell(alice, card);
        Settle(game);

        // Unkicked, so nobody discards - whoever the trigger named. Before the guard, the game
        // stopped here and asked for a choice of zero cards out of a full hand.
        Assert.Equal(bobHeld, game.State.GetPlayer(bob).Hand.Count);
        Assert.Equal(aliceHeld, game.State.GetPlayer(alice).Hand.Count);
        Assert.False(game.State.IsWaitingForChoice);
        Assert.Contains(
            game.State.Battlefield.Select(game.State.GetObject),
            o => o.Card.Name == "Bloodhusk Ritualist Test");
    }

    private static CardDefinition Anavolver() => Card(
        "Anavolver Test",
        "Kicker {1}{U} and/or {B}\n"
            + "If ~ was kicked with its {1}{U} kicker, it enters with two +1/+1 counters on it "
            + "and with flying.\n"
            + "If ~ was kicked with its {B} kicker, it enters with a +1/+1 counter on it and "
            + "with \"Pay 3 life: Regenerate this creature.\"",
        CardType.Creature,
        power: 4,
        toughness: 4);

    /// <summary>Casts Anavolver paying the named kickers, and hands back what arrived.</summary>
    private static (Game Game, GameObject Arrived) CastVolver(
        IReadOnlyList<int> kickers, params string[] lands)
    {
        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, Anavolver());

        foreach (var land in lands)
            TapForMana(game, alice, land);

        game.CastSpell(alice, card, targets: null, kickedWith: kickers);
        Settle(game);

        return (game, game.State.Battlefield
            .Select(game.State.GetObject)
            .Single(o => o.Card.Name == "Anavolver Test"));
    }

    /// <summary>A basic land put onto the battlefield and tapped for its mana.</summary>
    private static void TapForMana(Game game, Guid player, string land)
    {
        var source = game.Create(player, TestCards.BasicLand(land), Zone.Battlefield);
        game.ActivateAbility(player, source, "mana");
    }

    /// <summary>
    /// "This spell costs {2} less to cast if it's bargained" is a real reduction, charged at
    /// CR 601.2f against a declaration made at CR 601.2b (CR 702.166b).
    /// </summary>
    /// <remarks>
    /// Johann's Stopgap's wording. The condition is one no board-reading reduction can answer —
    /// it is a choice the caster made moments earlier and nothing on the battlefield records —
    /// so the test is built around the two mana that cannot pay the printed cost and can pay the
    /// bargained one.
    /// </remarks>
    [Fact]
    public void A_bargained_spell_costs_less_because_the_cost_was_paid()
    {
        var stopgap = PricedCard(
            "Johann's Stopgap Test",
            "{3}{U}",
            4,
            "Bargain\n~ costs {2} less to cast if it's bargained.\n"
                + "Return target nonland permanent to its owner's hand. Draw a card.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(stopgap);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.Equal(2, compiled.Spell!.BargainDiscount);
        Assert.NotNull(compiled.Spell.BargainCost);

        var (game, alice, bob) = InMainPhase();
        var relic = game.Create(
            alice, Card("Stopgap Relic Test", string.Empty, CardType.Artifact), Zone.Battlefield);

        var bear = game.Create(
            bob, TestCards.Creature("Stopgap Bear Test", 2, 2), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, stopgap);
        TapForMana(game, alice, "Island");
        TapForMana(game, alice, "Forest");

        // Two mana is not four. Without the sacrifice the printed cost is the price, and the
        // spell is refused rather than cast at a discount nobody bought.
        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, card, [Target.ToPermanent(bear)]));

        var hand = game.State.GetPlayer(alice).Hand.Count;

        game.CastSpell(
            alice, card, [Target.ToPermanent(bear)], costPayment: [relic], bargained: true);

        Settle(game);

        // The same two mana paid for it, the artifact paid for that, and the spell did what it
        // says. A discount given rather than bought would leave the relic on the battlefield.
        Assert.True(game.State.GetPlayer(alice).ManaPool.IsEmpty);
        Assert.DoesNotContain(relic, game.State.Battlefield);
        Assert.DoesNotContain(bear, game.State.Battlefield);
        Assert.Contains(
            game.State.GetPlayer(bob).Hand,
            id => game.State.GetObject(id).Card.Name == "Stopgap Bear Test");

        // One card cast and one card drawn, so the hand is back where it started.
        Assert.Equal(hand, game.State.GetPlayer(alice).Hand.Count);
    }

    /// <summary>
    /// "Choose one. If this spell was cast using teamwork, choose both instead" replaces the
    /// printed count rather than widening it (CR 700.2d, 702.194b).
    /// </summary>
    /// <remarks>
    /// Widow's Bite's wording, and the word that carries it is "instead": both directions are
    /// asserted, because a reading that merely raised the ceiling would let a teamwork caster
    /// take one mode, and a reading that ignored the clause would refuse both. Teamwork's cost
    /// is not mana — it is a team tapped for total power (CR 702.194a) — so the creatures turned
    /// sideways are what prove the fact was earned rather than assumed.
    /// </remarks>
    [Theory]
    [InlineData(false, 3)]
    [InlineData(true, 1)]
    public void Teamwork_swaps_the_mode_count_rather_than_widening_it(
        bool teamwork, int toughness)
    {
        var bite = Card(
            "Widow's Bite Test",
            "Teamwork 3\n"
                + "Choose one. If this spell was cast using teamwork, choose both instead.\n"
                + "• Target creature gains deathtouch until end of turn.\n"
                + "• Target creature gets -2/-2 until end of turn.");

        var compiled = CardCompiler.Compile(bite);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.Equal(1, compiled.Spell!.ModesToChoose);
        Assert.Equal(CastFact.Teamwork, compiled.Spell.ModesOnFact!.Fact);
        Assert.Equal(2, compiled.Spell.ModesOnFact.Min);

        var (game, alice, bob) = InMainPhase();
        var first = game.Create(
            alice, TestCards.Creature("Bite Ally One Test", 2, 2), Zone.Battlefield);

        var second = game.Create(
            alice, TestCards.Creature("Bite Ally Two Test", 1, 1), Zone.Battlefield);

        var bear = game.Create(bob, TestCards.Creature("Bite Bear Test", 3, 3), Zone.Battlefield);
        var card = TestCards.PutInHand(game, alice, bite);

        var taken = teamwork ? new[] { 0, 1 } : [0];
        var refused = teamwork ? new[] { 0 } : [0, 1];
        var team = teamwork ? new[] { first, second } : null;

        // With the cost paid one mode is too few; without it two are too many. Modes are chosen
        // before costs are paid (CR 601.2b, then 601.2f), so the refusal costs nothing.
        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(
                alice,
                card,
                [.. refused.Select(_ => Target.ToPermanent(bear))],
                modes: refused,
                costPayment: team,
                teamwork: teamwork));

        game.CastSpell(
            alice,
            card,
            [.. taken.Select(_ => Target.ToPermanent(bear))],
            modes: taken,
            costPayment: team,
            teamwork: teamwork);

        Settle(game);

        var now = Characteristics.Of(game.State, Pool, game.State.GetObject(bear));
        Assert.True(now.Has(KeywordAbility.Deathtouch));
        Assert.Equal(toughness, now.Toughness);

        // The team is tapped only when it paid, which is the difference between the two runs.
        Assert.Equal(teamwork, game.State.GetObject(first).Permanent!.IsTapped);
        Assert.Equal(teamwork, game.State.GetObject(second).Permanent!.IsTapped);
    }

    /// <summary>
    /// "Choose one. If this spell was kicked, choose any number instead" opens the menu to every
    /// mode the card has (CR 700.2d, 702.33e).
    /// </summary>
    /// <remarks>
    /// The Inscription cycle's wording, and the other half of the clause above: "any number"
    /// moves the ceiling to the whole card while "both" moves floor and ceiling together, so
    /// reading the two as one number would be wrong about one of them whichever number was
    /// picked.
    /// </remarks>
    [Fact]
    public void A_kicked_modal_spell_can_take_every_mode_the_card_has()
    {
        var inscription = Kicked(
            "Inscription Test",
            "{1}",
            "Kicker {2}\nChoose one. If ~ was kicked, choose any number instead.\n"
                + "• You gain 3 life.\n• You gain 5 life.\n• You gain 7 life.");

        var compiled = CardCompiler.Compile(inscription);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.Equal(3, compiled.Spell!.Modes.Count);
        Assert.Equal(CastFact.Kicked, compiled.Spell.ModesOnFact!.Fact);
        Assert.Equal(-1, compiled.Spell.ModesOnFact.Max);

        var (unkicked, alice, _) = InMainPhase();
        var cheap = TestCards.PutInHand(unkicked, alice, inscription);
        TapForMana(unkicked, alice, "Forest");

        // Unkicked it is the plain header: one mode, and three is not a legal choice.
        Assert.Throws<InvalidOperationException>(
            () => unkicked.CastSpell(alice, cheap, targets: null, modes: [0, 1, 2]));

        unkicked.CastSpell(alice, cheap, targets: null, modes: [2]);
        Settle(unkicked);
        Assert.Equal(27, unkicked.State.GetPlayer(alice).Life);

        var (game, ally, _) = InMainPhase();
        var card = TestCards.PutInHand(game, ally, inscription);
        foreach (var _ in Enumerable.Range(0, 3))
            TapForMana(game, ally, "Forest");

        game.CastSpell(ally, card, targets: null, modes: [0, 1, 2], kicked: true);
        Settle(game);

        // Every mode, once each, out of one cast — and the floor of one still stands, so this is
        // a wider menu rather than an optional one.
        Assert.Equal(35, game.State.GetPlayer(ally).Life);
    }

    /// <summary>
    /// "Choose up to four. You may choose the same mode more than once" is a floor of zero under
    /// a printed ceiling (CR 700.2d).
    /// </summary>
    /// <remarks>
    /// Moment of Reckoning's wording. Both numbers are asserted because both are unusual: every
    /// other modal header this engine reads demands at least one mode, and a header read as
    /// "choose four" would refuse the empty cast that this card explicitly allows.
    /// </remarks>
    [Fact]
    public void Choose_up_to_four_allows_none_and_repeats_up_to_its_ceiling()
    {
        var reckoning = Card(
            "Moment Of Reckoning Test",
            "Choose up to four. You may choose the same mode more than once.\n"
                + "• Destroy target nonland permanent.\n"
                + "• Return target nonland permanent card from your graveyard to the "
                + "battlefield.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(reckoning);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.Equal(0, compiled.Spell!.ModesToChoose);
        Assert.Equal(4, compiled.Spell.ModesMax);
        Assert.True(compiled.Spell.ModesMayRepeat);

        // Nothing is a legal choice, and the spell still resolves.
        var (idle, alice, bob) = InMainPhase();
        var spared = idle.Create(
            bob, TestCards.Creature("Reckoning Spared Test", 2, 2), Zone.Battlefield);

        idle.CastSpell(
            alice, TestCards.PutInHand(idle, alice, reckoning), targets: null, modes: []);

        Settle(idle);
        Assert.Contains(spared, idle.State.Battlefield);

        var (game, ally, foe) = InMainPhase();
        var doomed = Enumerable.Range(0, 5)
            .Select(i => game.Create(
                foe,
                TestCards.Creature("Reckoning Doomed " + i + " Test", 2, 2),
                Zone.Battlefield))
            .ToList();

        var card = TestCards.PutInHand(game, ally, reckoning);

        // Four is a ceiling, not a suggestion.
        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(
                ally,
                card,
                [.. doomed.Select(Target.ToPermanent)],
                modes: [0, 0, 0, 0, 0]));

        game.CastSpell(
            ally,
            card,
            [.. doomed.Take(4).Select(Target.ToPermanent)],
            modes: [0, 0, 0, 0]);

        Settle(game);

        // The same mode four times over, each with a target of its own (CR 700.2d).
        foreach (var id in doomed.Take(4))
            Assert.DoesNotContain(id, game.State.Battlefield);

        Assert.Contains(doomed[4], game.State.Battlefield);
    }

    /// <summary>
    /// "Choose X" takes its count from the X announced with the cast, and from nothing else
    /// (CR 700.2d, 601.2b).
    /// </summary>
    /// <remarks>
    /// Doomsday Confluence's wording — the only card that prints this header. The count exists
    /// nowhere on the card, so a reader falling back on a printed number would be reading a card
    /// that does not exist; the refusal at one mode is what separates "choose X" from "choose up
    /// to X".
    /// </remarks>
    [Fact]
    public void Choose_X_takes_its_count_from_the_X_that_was_announced()
    {
        var confluence = Card(
            "Doomsday Confluence Test",
            "Choose X. You may choose the same mode more than once.\n"
                + "• Each player sacrifices a nonartifact creature of their choice.\n"
                + "• Create a 3/3 black Dalek artifact creature token with menace.\n"
                + "• Each opponent discards a card.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(confluence);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.True(compiled.Spell!.ModesFromX);
        Assert.True(compiled.Spell.ModesMayRepeat);
        Assert.Equal(3, compiled.Spell.Modes.Count);

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, confluence);

        // X was announced as two, so two modes is the only legal number: one is as wrong as
        // three, which is what makes this "choose X" rather than "choose up to X".
        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, card, targets: null, variableValue: 2, modes: [1]));

        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, card, targets: null, variableValue: 2, modes: [1, 1, 1]));

        game.CastSpell(alice, card, targets: null, variableValue: 2, modes: [1, 1]);
        Settle(game);

        // The same mode twice, because the card says it may be (CR 700.2d).
        Assert.Equal(
            2,
            game.State.Battlefield.Count(id => game.State.GetObject(id).Card.Name == "Dalek"));

        // A different X is a different menu, which is the whole of what the header says. Two
        // tokens for a count that happened to be right once would pass everything above.
        var (bigger, ally, _) = InMainPhase();
        var again = TestCards.PutInHand(bigger, ally, confluence);

        bigger.CastSpell(ally, again, targets: null, variableValue: 3, modes: [1, 1, 1]);
        Settle(bigger);

        Assert.Equal(
            3,
            bigger.State.Battlefield.Count(
                id => bigger.State.GetObject(id).Card.Name == "Dalek"));
    }

    // ---- Somebody else's arrival, tapped (CR 614.1d) ------------------------

    /// <summary>A group entry replacement, on a permanent that is never the one arriving.</summary>
    private static CardDefinition EntersTappedLock(string name, string oracleText) => new()
    {
        OracleId = "oracle-" + name.ToLowerInvariant().Replace(' ', '-'),
        Name = name,
        OracleText = oracleText,
        CardTypes = CardType.Enchantment,
    };

    /// <summary>A land with no basic supertype, so "nonbasic" has something to be true of.</summary>
    private static CardDefinition NonbasicLand(string name) => new()
    {
        OracleId = "oracle-" + name.ToLowerInvariant().Replace(' ', '-'),
        Name = name,
        CardTypes = CardType.Land,
        Subtypes = ["Gate"],
    };

    /// <summary>
    /// "Creatures your opponents control enter tapped" — Authority of the Consuls (CR 614.1d).
    /// </summary>
    /// <remarks>
    /// Both halves are the test, and the second is the one a loose reading fails. Until this
    /// existed the compiler had no way at all to say "somebody else is entering":
    /// <c>CardCompiler.Arriving</c> matches <c>moved.OldId == source.Id</c>, which asks only
    /// whether the source itself is arriving, and every enters-tapped reader was built on it. So
    /// the failure to avoid is not "the opponent's creature stays upright" — it is a reader that
    /// forgets the ownership clause and taps its own controller's board too, which is a
    /// materially different card and one nothing downstream would notice.
    /// </remarks>
    [Fact]
    public void An_opponents_creature_arrives_tapped_and_your_own_arrives_upright()
    {
        var (game, alice, bob) = InMainPhase();

        var lock1 = game.Create(
            alice,
            EntersTappedLock(
                "Arrival Consuls Test", "Creatures your opponents control enter tapped."),
            Zone.Battlefield);

        var mine = game.Create(
            alice, TestCards.Creature("Arrival Own Bear Test", 2, 2), Zone.Battlefield);
        var theirs = game.Create(
            bob, TestCards.Creature("Arrival Their Bear Test", 2, 2), Zone.Battlefield);
        Settle(game);

        Assert.True(game.State.GetObject(theirs).Permanent!.IsTapped);
        Assert.False(game.State.GetObject(mine).Permanent!.IsTapped);

        // CR 614.12's own example, in the other direction: the permanent carrying the line is
        // never the permanent arriving. The pipeline builds an arriving object out of its own
        // event and offers it its own replacements, so without the identity check this would
        // have tapped itself on the way in.
        Assert.False(game.State.GetObject(lock1).Permanent!.IsTapped);
    }

    /// <summary>
    /// The same replacement against a permanent that was <em>played</em> rather than created.
    /// </summary>
    /// <remarks>
    /// The two arrivals are different events and the wrinkle lives in one of them. A token is
    /// <c>ObjectCreated</c> and carries its card and its controller on the event; a played land
    /// is <c>ObjectMoved</c>, and the object it is about to become <b>does not exist in the state
    /// yet</b> (CR 400.7) — so what is entering has to be read out of the object it still is in
    /// the zone it is leaving. Looking the new id up returns nothing, which is exactly how
    /// landfall once failed to fire at all, and a reader that did it here would leave every
    /// played land upright while tokens tapped correctly.
    /// </remarks>
    [Fact]
    public void A_played_land_is_reached_by_the_same_group_replacement()
    {
        var (game, alice, bob) = InMainPhase();

        game.Create(
            alice,
            EntersTappedLock(
                "Arrival Aether Test",
                "Artifacts, creatures, and lands your opponents control enter tapped."),
            Zone.Battlefield);

        // Alice's own land, played on Alice's turn: the clause says opponents, so it is upright.
        var ours = TestCards.PutInHand(game, alice, TestCards.BasicLand("Forest"));
        game.PlayLand(alice, ours);
        Settle(game);

        Assert.False(
            game.State.Battlefield
                .Select(game.State.GetObject)
                .Single(o => o.Card.Name == "Forest")
                .Permanent!.IsTapped);

        PassToMainPhaseOf(game, bob);

        var theirs = TestCards.PutInHand(game, bob, NonbasicLand("Arrival Their Land Test"));
        game.PlayLand(bob, theirs);
        Settle(game);

        Assert.True(
            game.State.Battlefield
                .Select(game.State.GetObject)
                .Single(o => o.Card.Name == "Arrival Their Land Test")
                .Permanent!.IsTapped);
    }

    /// <summary>
    /// "Artifacts your opponents control enter tapped" — Manglehorn, and the type it leaves out.
    /// </summary>
    /// <remarks>
    /// The noun is a filter and not decoration. A reader that took the ownership clause and threw
    /// the types away would pass the test above and turn Manglehorn into Kismet, so the assertion
    /// that matters here is the opponent's <em>creature</em> arriving upright.
    /// </remarks>
    [Fact]
    public void A_group_taps_only_the_types_its_noun_names()
    {
        var (game, alice, bob) = InMainPhase();

        game.Create(
            alice,
            EntersTappedLock(
                "Arrival Manglehorn Test", "Artifacts your opponents control enter tapped."),
            Zone.Battlefield);

        var relic = game.Create(
            bob,
            Card("Arrival Their Relic Test", string.Empty, CardType.Artifact),
            Zone.Battlefield);
        var beast = game.Create(
            bob, TestCards.Creature("Arrival Untouched Bear Test", 2, 2), Zone.Battlefield);
        Settle(game);

        Assert.True(game.State.GetObject(relic).Permanent!.IsTapped);
        Assert.False(game.State.GetObject(beast).Permanent!.IsTapped);
    }

    /// <summary>
    /// "Creatures and nonbasic lands your opponents control enter tapped" — Thalia, Heretic
    /// Cathar, whose group is two descriptions joined.
    /// </summary>
    /// <remarks>
    /// The printed list is read as "any one of these" (CR 109.4), because nothing is a creature
    /// and a land at once — and the second half carries a supertype that has to be true
    /// <em>with</em> the type rather than instead of it. Bob's basic Forest arriving upright is
    /// what proves the word "nonbasic" survived the read; a list flattened to its card types
    /// would tap it.
    /// </remarks>
    [Fact]
    public void A_two_part_group_keeps_the_qualifier_on_the_part_that_carries_it()
    {
        var (game, alice, bob) = InMainPhase();

        game.Create(
            alice,
            EntersTappedLock(
                "Arrival Thalia Test",
                "Creatures and nonbasic lands your opponents control enter tapped."),
            Zone.Battlefield);

        var basic = game.Create(bob, TestCards.BasicLand("Forest"), Zone.Battlefield);
        var beast = game.Create(
            bob, TestCards.Creature("Arrival Thalia Bear Test", 2, 2), Zone.Battlefield);
        Settle(game);

        Assert.False(game.State.GetObject(basic).Permanent!.IsTapped);
        Assert.True(game.State.GetObject(beast).Permanent!.IsTapped);

        PassToMainPhaseOf(game, bob);

        var nonbasic = TestCards.PutInHand(game, bob, NonbasicLand("Arrival Thalia Gate Test"));
        game.PlayLand(bob, nonbasic);
        Settle(game);

        Assert.True(
            game.State.Battlefield
                .Select(game.State.GetObject)
                .Single(o => o.Card.Name == "Arrival Thalia Gate Test")
                .Permanent!.IsTapped);
    }

    /// <summary>
    /// "Permanents enter tapped" — Orb of Dreams, which names nobody and so means everybody.
    /// </summary>
    /// <remarks>
    /// A missing ownership clause is not a missing "you control". This file already records the
    /// same defect one layer over, where the mass-static reader defaulted a missing clause to its
    /// own controller and left 83 corpus cards quietly applying to half the board — a card that
    /// reads as printed and plays as something weaker. Alice's own creature arriving tapped is
    /// the assertion that keeps this reader on the right side of it.
    /// <para>
    /// The Orb's own arrival is the rule's worked example — "It won't affect itself" — and the
    /// last assertion is that one.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_group_with_no_ownership_clause_taps_the_whole_table()
    {
        var (game, alice, bob) = InMainPhase();

        var orb = game.Create(
            alice,
            EntersTappedLock("Arrival Orb Test", "Permanents enter tapped."),
            Zone.Battlefield);

        var mine = game.Create(
            alice, TestCards.Creature("Arrival Orb Own Bear Test", 2, 2), Zone.Battlefield);
        var theirs = game.Create(
            bob, TestCards.Creature("Arrival Orb Their Bear Test", 2, 2), Zone.Battlefield);
        Settle(game);

        Assert.True(game.State.GetObject(mine).Permanent!.IsTapped);
        Assert.True(game.State.GetObject(theirs).Permanent!.IsTapped);
        Assert.False(game.State.GetObject(orb).Permanent!.IsTapped);
    }

    /// <summary>A static ability functions from the battlefield and nowhere else (CR 604.3).</summary>
    /// <remarks>
    /// This is the guard that the identity check cannot stand in for, and it is not theoretical:
    /// the replacement pipeline walks <em>every</em> object in the game, not the battlefield, so
    /// that "as this enters" can function from the stack. A group replacement left at the same
    /// setting would have a Kismet in its owner's hand locking down a board it is not on.
    /// </remarks>
    [Fact]
    public void A_group_replacement_in_hand_replaces_nothing()
    {
        var (game, alice, bob) = InMainPhase();

        game.Create(
            alice,
            EntersTappedLock(
                "Arrival In Hand Test", "Creatures your opponents control enter tapped."),
            Zone.Hand);

        var theirs = game.Create(
            bob, TestCards.Creature("Arrival In Hand Bear Test", 2, 2), Zone.Battlefield);
        Settle(game);

        Assert.False(game.State.GetObject(theirs).Permanent!.IsTapped);
    }

    /// <summary>
    /// The three neighbouring wordings this reader refuses, and why each refusal is the point.
    /// </summary>
    /// <remarks>
    /// A single pattern loose enough to claim any of these would pass every test above.
    /// <list type="bullet">
    /// <item><description><b>"this turn"</b> is Due Respect, a sorcery. The sentence is identical
    /// and the effect is not: a one-shot with a duration read as a static hands that spell a
    /// permanent lock on the table, which is the harshest possible misreading of the
    /// gentlest available one.</description></item>
    /// <item><description><b>"played by your opponents"</b> is Uphill Battle, and "played" is
    /// narrower than "enters under their control" — a token an opponent creates was never played.
    /// Reading it as the ownership clause would tap permanents the card does not name, and one
    /// card is the right price for not doing that.</description></item>
    /// <item><description><b>"enchanted player controls"</b> names a group by a relation to the
    /// source rather than by a seat at the table. The mass-static reader has a branch for it and
    /// this one does not, so the scope word is matched rather than skipped: an unrecognised
    /// clause leaves the line unread instead of silently meaning everybody.</description></item>
    /// </list>
    /// </remarks>
    [Theory]
    [InlineData("Permanents enter tapped this turn.")]
    [InlineData("Creatures played by your opponents enter tapped.")]
    [InlineData("Creatures enchanted player controls enter tapped.")]
    public void A_wording_the_group_reader_cannot_honour_leaves_the_card_unread(string oracleText)
    {
        var card = EntersTappedLock("Arrival Refusal Test", oracleText);
        Assert.False(CardCompiler.Compile(card).IsComplete);
    }

    /// <summary>
    /// The singular reader still owns the singular sentence, and the plural one the plural.
    /// </summary>
    /// <remarks>
    /// The verb is the only thing telling these two apart, and they mean opposite things about
    /// the same board: "~ enters tapped" is the card arriving and says nothing about anybody
    /// else, while "Creatures enter tapped" is about everybody else and never about the card. A
    /// reader that claimed both would turn every enters-tapped land in the game into a
    /// table-wide lock, and the coverage number would not move a point.
    /// </remarks>
    [Fact]
    public void The_singular_and_plural_enters_tapped_sentences_stay_apart()
    {
        var (game, alice, bob) = InMainPhase();

        var land = SlowLand("Arrival Singular Land Test", "~ enters tapped.");
        var mine = TestCards.PutInHand(game, alice, land);
        game.PlayLand(alice, mine);

        var beast = game.Create(
            bob, TestCards.Creature("Arrival Singular Bear Test", 2, 2), Zone.Battlefield);
        Settle(game);

        // The land taps itself, as it always did.
        Assert.True(
            game.State.Battlefield
                .Select(game.State.GetObject)
                .Single(o => o.Card.Name == "Arrival Singular Land Test")
                .Permanent!.IsTapped);

        // And says nothing at all about Bob's creature.
        Assert.False(game.State.GetObject(beast).Permanent!.IsTapped);
    }

    // ---- The source's own zone change, replaced (CR 614.1a) ------------------

    /// <summary>The Colossus line, on a creature big enough to be worth shuffling back.</summary>
    private static CardDefinition ShufflesBackColossus(string name) => new()
    {
        OracleId = "oracle-" + name.ToLowerInvariant().Replace(' ', '-'),
        Name = name,
        OracleText =
            "If " + name + " would be put into a graveyard from anywhere, reveal " + name
            + " and shuffle it into its owner's library instead.",
        CardTypes = CardType.Artifact | CardType.Creature,
        Subtypes = ["Golem"],
        Power = 11,
        Toughness = 11,
    };

    /// <summary>
    /// "If ~ would be put into a graveyard from anywhere, reveal ~ and shuffle it into its
    /// owner's library instead" — Darksteel Colossus (CR 614.1a).
    /// </summary>
    /// <remarks>
    /// The sibling of the group replacement above: the same rule about a zone change, aimed at
    /// the source's own move rather than somebody else's arrival. Two destinations of this
    /// sentence were already read; this is the third, and it is the one that needed more than a
    /// different zone.
    /// <para>
    /// <b>The graveyard assertion is the one that matters, and the library count is the one that
    /// catches the lazy fix.</b> A reader that moved the card to the library and stopped would
    /// pass "not in the graveyard" while leaving an 11/11 on top of its owner's deck — a card
    /// that draws itself next turn, which is a strictly better card than the one printed. So the
    /// library is counted before and after, and the shuffle is what puts it somewhere unknown.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_card_that_shuffles_itself_back_never_reaches_the_graveyard()
    {
        var colossus = ShufflesBackColossus("Shuffle Back Colossus Test");

        var (game, alice, bob) = InMainPhase();
        var golem = game.Create(bob, colossus, Zone.Battlefield);
        var before = game.State.GetPlayer(bob).Library.Count;

        var murder = TestCards.PutInHand(
            game, alice, Card("Shuffle Back Murder Test", "Destroy target creature."));

        game.CastSpell(alice, murder, [Target.ToPermanent(golem)]);
        Settle(game);

        Assert.DoesNotContain(golem, game.State.Battlefield);

        // CR 614.6: the move to the graveyard never happened, so nothing is there to find.
        Assert.Empty(game.State.GetPlayer(bob).Graveyard);
        Assert.Equal(before + 1, game.State.GetPlayer(bob).Library.Count);
    }

    /// <summary>"From anywhere" is not "from the battlefield" (CR 614.1a).</summary>
    /// <remarks>
    /// The clause the other two destinations of this sentence already honour, asserted here
    /// because the shuffling arm is the one with an owner to get wrong: the card is discarded out
    /// of a hand, so the player whose library it goes into has to be read off the card rather
    /// than off whoever is doing the discarding. Reading the controller instead would send a
    /// stolen or an opponent-discarded card into the wrong deck.
    /// </remarks>
    [Fact]
    public void The_same_replacement_catches_a_discard_out_of_hand()
    {
        var colossus = ShufflesBackColossus("Shuffle Back Discard Test");

        var (game, alice, _) = InMainPhase();
        var held = TestCards.PutInHand(game, alice, colossus);
        var before = game.State.GetPlayer(alice).Library.Count;

        var pitch = TestCards.PutInHand(
            game, alice, Card("Shuffle Back Pitch Test", "Discard a card."));

        game.CastSpell(alice, pitch, []);
        Settle(game);

        Assert.DoesNotContain(held, game.State.GetPlayer(alice).Hand);

        // The sorcery that made her discard is in that graveyard, so the assertion is about the
        // card the replacement was on rather than about the pile being empty.
        Assert.DoesNotContain(
            game.State.GetPlayer(alice).Graveyard.Select(game.State.GetObject),
            o => o.Card.Name == "Shuffle Back Discard Test");

        Assert.Equal(before + 1, game.State.GetPlayer(alice).Library.Count);
    }

    /// <summary>The two older destinations of the same sentence still go where they went.</summary>
    /// <remarks>
    /// One pattern reads all three, so a third alternative is a chance to break the first two.
    /// Exiling is the arm that shares no words with the new one and would fail loudest; the
    /// bottom-of-library arm is the one that shares a destination with it and would fail
    /// quietly, ending up shuffled instead of underneath.
    /// </remarks>
    [Fact]
    public void The_exiling_and_bottoming_arms_of_the_same_sentence_are_unchanged()
    {
        var exiler = Card(
            "Shuffle Back Exile Test",
            "If ~ would be put into a graveyard from anywhere, exile it instead.",
            CardType.Creature, 2, 2);

        var (game, alice, bob) = InMainPhase();
        var beast = game.Create(bob, exiler, Zone.Battlefield);
        var murder = TestCards.PutInHand(
            game, alice, Card("Shuffle Back Exile Murder Test", "Destroy target creature."));

        game.CastSpell(alice, murder, [Target.ToPermanent(beast)]);
        Settle(game);

        Assert.Empty(game.State.GetPlayer(bob).Graveyard);
        Assert.Contains(
            game.State.Exile.Select(game.State.GetObject),
            o => o.Card.Name == "Shuffle Back Exile Test");

        var bottomer = Card(
            "Shuffle Back Bottom Test",
            "If ~ would be put into a graveyard from anywhere, "
                + "put it on the bottom of its owner's library instead.",
            CardType.Creature, 2, 2);

        var (second, ally, foe) = InMainPhase();
        var other = second.Create(foe, bottomer, Zone.Battlefield);
        var again = TestCards.PutInHand(
            second, ally, Card("Shuffle Back Bottom Murder Test", "Destroy target creature."));

        second.CastSpell(ally, again, [Target.ToPermanent(other)]);
        Settle(second);

        Assert.Empty(second.State.GetPlayer(foe).Graveyard);
        Assert.Equal(
            "Shuffle Back Bottom Test",
            second.State.GetObject(second.State.GetPlayer(foe).Library[^1]).Card.Name);
    }

    // ---- Somebody else does it, and three readers that refused their own words ----

    /// <summary>
    /// "When ~ enters, you may have target opponent discard a card." — Ebon Dragon.
    /// </summary>
    /// <remarks>
    /// The causative. "Have somebody do something" is the same instruction as "somebody does
    /// something" with the subject demoted to an object of "have", and every one of those
    /// indicative sentences already had a reader — so the whole family was unread for one word.
    /// It is rewritten before the sentence grammar sees it rather than given matchers of its own,
    /// because a matcher per verb would have to restate the target vocabulary each time.
    /// <para>
    /// Both answers are asserted. An offer whose decline still does the thing is a strictly
    /// harsher card than the one printed, and it is the arm a test that only accepts never runs.
    /// </para>
    /// </remarks>
    [Theory]
    [InlineData(true, 1)]
    [InlineData(false, 0)]
    public void A_causative_offer_is_the_indicative_sentence_it_means(bool accept, int discarded)
    {
        var dragon = Card(
            "Causative Dragon Test",
            "When ~ enters, you may have target opponent discard a card.",
            CardType.Creature,
            power: 5,
            toughness: 4);

        var compiled = CardCompiler.Compile(dragon);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var held = game.State.GetPlayer(bob).Hand.Count;

        game.Create(alice, dragon, Zone.Battlefield);

        // The trigger's target first (CR 603.3d): Bob is the only opponent, so that question has
        // one answer and taking it is not what this test is about.
        TestCards.PassUntil(game, () => game.State.Choice is not null);
        var aiming = game.State.Choice!;
        Assert.Equal(ChoiceKind.ChooseTriggerTargets, aiming.Kind);
        game.Choose(alice, [aiming.Options!.First().Id]);

        // The offer, answered by hand rather than through Settle - which of the two answers is
        // taken is the whole of what this test is about.
        TestCards.PassUntil(game, () => game.State.Choice is not null);
        var offer = game.State.Choice!;
        var no = offer.Options!.Single(
            o => o.Label.Contains("decline", StringComparison.OrdinalIgnoreCase));

        game.Choose(alice, [accept ? offer.Options!.First(o => o.Id != no.Id).Id : no.Id]);
        Settle(game);

        Assert.Equal(held - discarded, game.State.GetPlayer(bob).Hand.Count);
    }

    /// <summary>
    /// The causative reaches whatever the indicative already reached.
    /// </summary>
    /// <remarks>
    /// The point of rewriting rather than matching: these lines share nothing but the word
    /// "have", and their indicative forms are read by unrelated parts of the phrase grammar. Each
    /// was its own row in the work queue, worth about two cards, and none was about the verb.
    /// </remarks>
    [Theory]
    [InlineData("When ~ enters, you may have target opponent discard a card.")]
    [InlineData("When ~ enters, you may have target player mill two cards.")]
    [InlineData("When ~ enters, you may have target player draw a card.")]
    [InlineData("Whenever ~ attacks, you may have target creature get +2/+0 until end of turn.")]
    [InlineData("Whenever ~ attacks, you may have target creature gain flying until end of turn.")]
    public void The_causative_reaches_every_verb_its_indicative_already_read(string text)
    {
        var card = Card("Causative Verbs Test", text, CardType.Creature, power: 2, toughness: 2);

        var compiled = CardCompiler.Compile(card);

        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
    }

    /// <summary>
    /// The causative may not have a pronoun for a subject.
    /// </summary>
    /// <remarks>
    /// The boundary the first cut of the rewrite walked past. "It" and "that creature" are
    /// resolved elsewhere in this compiler under a guard about which trigger events carry an
    /// object, and a rewrite that hands them to the ordinary sentence grammar aims the verb at
    /// the source instead — 54 corpus lines say "you may have it ..." and 16 say "you may have
    /// that creature ...", and reading them that way makes each of those cards a different one.
    /// <para>
    /// The subject is therefore a target phrase or the source, and the eight cards that costs are
    /// eight cards that would have been read wrongly.
    /// </para>
    /// </remarks>
    [Theory]
    [InlineData("Whenever a Beast you control enters, you may have it deal 4 damage to target player.")]
    [InlineData("Whenever a Beast you control enters, you may have that creature draw a card.")]
    public void The_causative_refuses_a_pronoun_for_its_subject(string text)
    {
        var card = Card("Causative Pronoun Test", text, CardType.Enchantment);

        var compiled = CardCompiler.Compile(card);

        Assert.False(compiled.IsComplete);
        Assert.Contains(
            compiled.Unhandled, line => line.Contains("you may have", StringComparison.Ordinal));
    }

    /// <summary>
    /// "Target player shuffles their graveyard into their library." — Clear the Mind (CR 701.24a).
    /// </summary>
    /// <remarks>
    /// "Shuffle your graveyard into your library" had read since the tutors were built; the same
    /// instruction with a subject in front of it had not, and the subject was the whole blocker on
    /// six cards. The effect grew a target index the way drawing and draining already had one,
    /// rather than a second effect that shuffles.
    /// </remarks>
    [Fact]
    public void A_named_player_shuffles_their_own_graveyard_back()
    {
        var clear = Card(
            "Clear Mind Test",
            "Target player shuffles their graveyard into their library.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(clear);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        game.Create(bob, TestCards.Creature("Cleared Bear One Test", 2, 2), Zone.Graveyard);
        game.Create(bob, TestCards.Creature("Cleared Bear Two Test", 2, 2), Zone.Graveyard);
        game.Create(alice, TestCards.Creature("Kept Bear Test", 2, 2), Zone.Graveyard);

        var library = game.State.GetPlayer(bob).Library.Count;

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, clear), [Target.ToPlayer(bob)]);

        Settle(game);

        // Bob's, and only Bob's. A shuffle that read the caster would have emptied the wrong
        // graveyard and left this one exactly as it was.
        Assert.Empty(game.State.GetPlayer(bob).Graveyard);
        Assert.Equal(library + 2, game.State.GetPlayer(bob).Library.Count);
        Assert.Contains(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Kept Bear Test");
    }

    /// <summary>"Each player shuffles their graveyard into their library." — Mnemonic Nexus.</summary>
    /// <remarks>
    /// The first card in the corpus to owe two shuffles at once, and it found a settle that
    /// performed one of them and handed priority back. A shuffle asks nobody anything, so it now
    /// goes round the sweep the way a seek and a roll do; before that, the second player's
    /// graveyard sat unshuffled while the spell was supposedly finished resolving.
    /// </remarks>
    [Fact]
    public void Every_player_shuffles_their_own_graveyard_back()
    {
        var nexus = Card(
            "Mnemonic Nexus Test",
            "Each player shuffles their graveyard into their library.",
            CardType.Instant);

        var compiled = CardCompiler.Compile(nexus);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        game.Create(bob, TestCards.Creature("Nexus Bear Test", 2, 2), Zone.Graveyard);

        var library = game.State.GetPlayer(bob).Library.Count;

        game.CastSpell(alice, TestCards.PutInHand(game, alice, nexus));
        Settle(game);

        Assert.Empty(game.State.GetPlayer(bob).Graveyard);
        Assert.Equal(library + 1, game.State.GetPlayer(bob).Library.Count);
    }

    /// <summary>
    /// "Target creature with flying has base power 0 until end of turn." — Island of Wak-Wak.
    /// </summary>
    /// <remarks>
    /// Layer 7b with one half of it missing (CR 613.4b). "Base power and toughness N/N" had read
    /// for months and the four cards that print a power alone had not, and the fix is not to fill
    /// the toughness in: a 3/3 whose power is set to 0 still has a 3/3's toughness, and a reading
    /// that set both would have made every one of these cards kill what it shrinks.
    /// </remarks>
    [Fact]
    public void A_base_power_alone_leaves_the_printed_toughness_alone()
    {
        var island = Card(
            "Wak-Wak Test",
            "{T}: Target creature with flying has base power 0 until end of turn.",
            CardType.Land);

        var compiled = CardCompiler.Compile(island);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var land = game.Create(alice, island, Zone.Battlefield);

        var flier = game.Create(
            bob,
            Card(
                "Wak-Wak Flier Test",
                string.Empty,
                CardType.Creature,
                power: 3,
                toughness: 3,
                keywords: KeywordAbility.Flying),
            Zone.Battlefield);

        game.ActivateAbility(
            alice, land, compiled.Activated[0].Id, [Target.ToPermanent(flier)]);

        Settle(game);

        var shrunk = game.State.GetObject(flier);
        Assert.Equal(0, Characteristics.PowerOf(game.State, Pool, shrunk));
        Assert.Equal(3, Characteristics.ToughnessOf(game.State, Pool, shrunk));
    }

    /// <summary>
    /// "Whenever ~ is dealt combat damage, you gain that much life." — Wall of Essence.
    /// </summary>
    /// <remarks>
    /// A neighbouring reader that stopped one word early: "is dealt damage" had read since the
    /// damage triggers were built, and the combat form beside it went to the unread pile.
    /// <c>DamageMarked</c> had carried <c>IsCombat</c> the whole time.
    /// <para>
    /// The burn is the half that matters. A combat-damage trigger that fires on a Shock is a
    /// different and better card, and it is exactly what widening the pattern without adding the
    /// term would have produced.
    /// </para>
    /// </remarks>
    [Fact]
    public void Combat_damage_taken_is_told_apart_from_damage_taken()
    {
        var wall = Card(
            "Essence Wall Test",
            "Whenever ~ is dealt combat damage, you gain that much life.",
            CardType.Creature,
            power: 0,
            toughness: 4,
            keywords: KeywordAbility.Defender);

        var compiled = CardCompiler.Compile(wall);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var blocker = game.Create(alice, wall, Zone.Battlefield);
        var attacker = game.Create(
            bob, TestCards.Creature("Essence Attacker Test", 2, 2), Zone.Battlefield);

        // Damage that is not combat damage: the trigger must not fire.
        game.CastSpell(
            alice,
            TestCards.PutInHand(
                game, alice, Card("Essence Ping Test", "~ deals 1 damage to any target.")),
            [Target.ToPermanent(blocker)]);

        Settle(game);
        Assert.Equal(20, game.State.GetPlayer(alice).Life);

        PassTo(game, 2, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            bob,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(alice) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);
        game.DeclareBlockers(
            alice,
            new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [attacker] = [blocker] });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Settle(game);

        // Two, which is the damage that was dealt and not the wall's own size.
        Assert.Equal(22, game.State.GetPlayer(alice).Life);
    }

    /// <summary>
    /// "As an additional cost to cast this spell, return a permanent you control to its owner's
    /// hand." — Fear of Isolation (CR 601.2f).
    /// </summary>
    /// <remarks>
    /// A decline that had outlived its reason. The compiler refused this cost because the cast
    /// path's chosen-cost loop fell through to a graveyard move and would have destroyed what the
    /// card meant to pick up — true when it was written, and untrue from the moment sneak and the
    /// alternative costs gave that loop the return arm the activation path already had. Five cards
    /// sat unread beside working machinery.
    /// <para>
    /// So the assertion is about the zone, not the count: the permanent has to reach its owner's
    /// <em>hand</em>, and a graveyard here would be the old bug wearing a green test.
    /// </para>
    /// </remarks>
    [Fact]
    public void An_additional_cost_can_return_a_permanent_to_its_owners_hand()
    {
        var fear = Card(
            "Isolation Fear Test",
            "As an additional cost to cast ~, return a permanent you control to its owner's hand."
                + "\nFlying",
            CardType.Creature,
            power: 2,
            toughness: 3,
            keywords: KeywordAbility.Flying);

        var compiled = CardCompiler.Compile(fear);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var island = game.Create(
            alice, TestCards.BasicLand("Isolation Island Test"), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, fear);

        // The cost is checked before any of it is spent (CR 601.2h), so a cast that names nothing
        // to return is refused rather than made free.
        Assert.ThrowsAny<InvalidOperationException>(() => game.CastSpell(alice, card, []));

        game.CastSpell(alice, card, [], costPayment: [island]);
        Settle(game);

        Assert.DoesNotContain(island, game.State.Battlefield);
        Assert.Contains(
            game.State.GetPlayer(alice).Hand,
            id => game.State.GetObject(id).Card.Name == "Isolation Island Test");

        Assert.DoesNotContain(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Isolation Island Test");
    }

    /// <summary>
    /// "When ~ enters, exile up to one target creature until ~ leaves the battlefield." — Touch
    /// the Spirit Realm's shape.
    /// </summary>
    /// <remarks>
    /// The target grammar has read "up to one target" for six hundred cards; this pattern reached
    /// its phrase through a literal "target" and so never handed the words over. The spec comes
    /// back optional (CR 115.1) and everything below it is the reader that was already there.
    /// </remarks>
    [Fact]
    public void An_exile_until_it_leaves_may_name_up_to_one_target()
    {
        var touch = Card(
            "Spirit Touch Test",
            "When ~ enters, exile up to one target creature until ~ leaves the battlefield.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(touch);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var bear = game.Create(bob, TestCards.Creature("Touched Bear Test", 2, 2), Zone.Battlefield);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, touch));
        Settle(game);

        Assert.DoesNotContain(bear, game.State.Battlefield);
        Assert.Contains(
            game.State.Exile, id => game.State.GetObject(id).Card.Name == "Touched Bear Test");
    }

    /// <summary>
    /// "Exile up to two target creatures you control, then return those cards to the battlefield
    /// under their owner's control." — Displace.
    /// </summary>
    /// <remarks>
    /// The plural this reader has to count for itself. A flicker is read <em>before</em> the text
    /// is split into sentences — the phrase is written across the ", then" the splitter cuts on —
    /// so the shared multi-target rewrite, which is a sentence matcher, never sees one.
    /// </remarks>
    [Fact]
    public void A_flicker_can_name_two_creatures()
    {
        var watcher = Card(
            "Displace Watcher Test",
            "When ~ enters, you gain 1 life.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var displace = Card(
            "Displace Test",
            "Exile up to two target creatures you control, then return those cards to the "
                + "battlefield under their owner's control.",
            CardType.Instant);

        var compiled = CardCompiler.Compile(displace);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var first = game.Create(alice, watcher, Zone.Battlefield);
        var second = game.Create(alice, watcher, Zone.Battlefield);
        Settle(game);

        Assert.Equal(22, game.State.GetPlayer(alice).Life);

        game.CastSpell(
            alice,
            TestCards.PutInHand(game, alice, displace),
            [Target.ToPermanent(first), Target.ToPermanent(second)]);

        Settle(game);

        // Both entered again, so both triggers fired again: a reader that took only the first
        // target would leave this at 23.
        Assert.Equal(24, game.State.GetPlayer(alice).Life);
        Assert.Equal(2, game.State.Battlefield.Count);
    }

    // ---- A filter measured against X (CR 601.2b, 602.2b, 607.2) --------------

    /// <summary>A spell whose one target is chosen against the X it was cast for.</summary>
    private static CardDefinition KillingGlare() => new()
    {
        OracleId = "oracle-xfilter-killing-glare",
        Name = "Killing Glare Test",
        OracleText = "Destroy target creature with power X or less.",
        CardTypes = CardType.Instant,
        ManaCostRaw = "{X}{B}",
        Cmc = 1,
    };

    /// <summary>An artifact of a known mana value, for the filters that measure one.</summary>
    private static CardDefinition Trinket(string name, int manaValue) => new()
    {
        OracleId = "oracle-xfilter-" + name.ToLowerInvariant().Replace(' ', '-'),
        Name = name,
        CardTypes = CardType.Artifact,
        Cmc = manaValue,
    };

    /// <summary>A creature card of a known mana value, for the tutors that cap one.</summary>
    private static CardDefinition Costed(string name, int manaValue) => new()
    {
        OracleId = "oracle-xfilter-" + name.ToLowerInvariant().Replace(' ', '-'),
        Name = name,
        CardTypes = CardType.Creature,
        Cmc = manaValue,
        Power = 1,
        Toughness = 1,
    };

    /// <summary>
    /// A target filter reads the X its spell was cast for, at both of the moments it is asked
    /// (CR 601.2c, 608.2b).
    /// </summary>
    /// <remarks>
    /// The family this was built for, and the reason it had been declined: a filter is a
    /// predicate the compiler closes over, and there is no number to close over when the number
    /// is chosen as the spell is cast. So the value is threaded to the filter instead, the way
    /// the announced target count already is - which makes X a fourth thing a
    /// <see cref="TargetSpec"/> can be about, beside the candidate, the source and a sibling
    /// target.
    /// <para>
    /// Played at two different values on one board, because a filter that hard-coded any number
    /// at all would pass a test that only ever announced one. The four-power creature is illegal
    /// for X=2 and legal for X=4, and the same spell says both.
    /// </para>
    /// <para>
    /// It resolves rather than merely being castable, and that is the second half: CR 608.2b
    /// asks the question again on resolution, by which time the spell is a different object. A
    /// re-check that had lost X would find a four-power creature illegal for a limit of zero,
    /// the spell would fizzle, and the creature would still be standing.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_target_filter_measures_against_the_X_its_spell_was_cast_for()
    {
        var glare = KillingGlare();
        var compiled = CardCompiler.Compile(glare);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        // The clause hangs off the variable slot rather than the plain object filter, which is
        // what makes a caller with no announced value get a refusal instead of a comparison
        // against zero.
        var spec = compiled.Spell!.Targets[0];
        Assert.NotNull(spec.VariableFilter);
        Assert.Null(spec.ObjectFilter);

        var (game, alice, bob) = InMainPhase();
        var small = game.Create(bob, TestCards.Creature("Glare Small Test", 2, 2), Zone.Battlefield);
        var big = game.Create(bob, TestCards.Creature("Glare Big Test", 4, 4), Zone.Battlefield);

        // Fail closed. An unknown X is not zero: answered as zero this same spec would admit the
        // whole board on "X or greater" and nothing at all on "X or less", and neither is the
        // printed card. A caller that cannot say what X is gets no legal target.
        Assert.False(spec.IsLegal(game.State, Pool, Target.ToPermanent(small), alice));
        Assert.True(
            spec.IsLegal(game.State, Pool, Target.ToPermanent(small), alice, announced: 2));

        var card = TestCards.PutInHand(game, alice, glare);
        game.AddMana(alice, ManaColor.Black, 3);

        // Announced for two, the four-power creature is not a legal target and the cast is
        // refused outright - the card is still in hand, having never been cast (CR 601.2c).
        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, card, [Target.ToPermanent(big)], 2));

        Assert.Contains(card, game.State.GetPlayer(alice).Hand);

        // Announced for four it reaches the same creature, and kills it.
        game.AddMana(alice, ManaColor.Black, 2);
        game.CastSpell(alice, card, [Target.ToPermanent(big)], 4);
        Settle(game);

        Assert.DoesNotContain(big, game.State.Battlefield);
        Assert.Contains(small, game.State.Battlefield);
    }

    /// <summary>
    /// A sweeper finds its set against the X it was cast for (CR 609.2).
    /// </summary>
    /// <remarks>
    /// The same clause on a group rather than on a target, and it needed nothing of its own: a
    /// group phrase is parsed as a target phrase, so the moment the qualifier learned X the
    /// sweepers learned it too. What it does need is the value at resolution rather than at cast
    /// - an untargeted effect finds its set as it resolves - and that is read off the object on
    /// the stack.
    /// <para>
    /// Three artifacts either side of the announced value, because a sweeper that ignored the
    /// cap and one that ignored the announcement both destroy exactly two of a board of two.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_sweeper_measures_each_permanent_against_the_X_it_was_cast_for()
    {
        var meltdown = new CardDefinition
        {
            OracleId = "oracle-xfilter-meltdown",
            Name = "Meltdown Test",
            OracleText = "Destroy each artifact with mana value X or less.",
            CardTypes = CardType.Sorcery,
            ManaCostRaw = "{X}{R}",
            Cmc = 1,
        };

        var compiled = CardCompiler.Compile(meltdown);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var cheap = game.Create(alice, Trinket("Meltdown Cheap Test", 1), Zone.Battlefield);
        var middling = game.Create(alice, Trinket("Meltdown Middling Test", 2), Zone.Battlefield);
        var dear = game.Create(alice, Trinket("Meltdown Dear Test", 4), Zone.Battlefield);

        game.AddMana(alice, ManaColor.Red, 3);
        game.CastSpell(alice, TestCards.PutInHand(game, alice, meltdown), null, 2);
        Settle(game);

        Assert.DoesNotContain(cheap, game.State.Battlefield);
        Assert.DoesNotContain(middling, game.State.Battlefield);
        Assert.Contains(dear, game.State.Battlefield);
    }

    /// <summary>
    /// A tutor capped by X fetches only what that X allows (CR 701.23).
    /// </summary>
    /// <remarks>
    /// The bound on a search is not a filter delegate at all - it is a number that travels in the
    /// event, because a library search has to read back out of a log. So the bound became an
    /// <see cref="Amount"/>, which is this engine's existing answer to "a number that is not
    /// known until the spell is cast", and the effect settles it against the resolution before
    /// the event is emitted. Nothing downstream of the event knows X exists.
    /// <para>
    /// Cast twice at two values, which is the only way to tell a cap that moves from a cap that
    /// happens to be right: the five-drop is out of reach for X=2 and in it for X=5.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_tutor_capped_by_X_offers_only_what_that_X_allows()
    {
        var rhythm = new CardDefinition
        {
            OracleId = "oracle-xfilter-natures-rhythm",
            Name = "Natures Rhythm Test",
            OracleText =
                "Search your library for a creature card with mana value X or less, put it onto "
                + "the battlefield, then shuffle.",
            CardTypes = CardType.Sorcery,
            ManaCostRaw = "{X}{G}{G}",
            Cmc = 2,
        };

        var compiled = CardCompiler.Compile(rhythm);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        // One game per announced value. Settling a search runs the turn on past the main phase,
        // and a second cast in the same game is refused for want of priority rather than for
        // anything this test is about.
        var forTwo = Offered(2);

        Assert.Contains(forTwo, label => label.Contains("Rhythm Cheap", StringComparison.Ordinal));
        Assert.DoesNotContain(
            forTwo, label => label.Contains("Rhythm Dear", StringComparison.Ordinal));

        // The same card announced for five reaches the five-drop, which is what says the bound is
        // the announcement rather than a number the compiler happened to pick.
        Assert.Contains(Offered(5), label => label.Contains("Rhythm Dear", StringComparison.Ordinal));

        // And the card it is allowed to fetch actually arrives, which the offered list alone
        // does not say.
        var (game, alice, _) = InMainPhase();
        game.Create(alice, Costed("Rhythm Cheap Test", 2), Zone.Library);

        game.AddMana(alice, ManaColor.Green, 4);
        game.CastSpell(alice, TestCards.PutInHand(game, alice, rhythm), null, 2);
        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.SearchLibrary });

        var choice = game.State.Choice!;

        game.Choose(
            alice,
            [
                choice.Options
                    .First(o => o.Label.Contains("Rhythm Cheap", StringComparison.Ordinal))
                    .Id,
            ]);

        Settle(game);

        Assert.Contains(
            game.State.Battlefield.Select(game.State.GetObject),
            o => string.Equals(o.Card.Name, "Rhythm Cheap Test", StringComparison.Ordinal));

        List<string> Offered(int announced)
        {
            var (table, searcher, _) = InMainPhase();
            table.Create(searcher, Costed("Rhythm Cheap Test", 2), Zone.Library);
            table.Create(searcher, Costed("Rhythm Dear Test", 5), Zone.Library);

            table.AddMana(searcher, ManaColor.Green, announced + 2);
            table.CastSpell(
                searcher, TestCards.PutInHand(table, searcher, rhythm), null, announced);

            TestCards.PassUntil(
                table, () => table.State.Choice is { Kind: ChoiceKind.SearchLibrary });

            return [.. table.State.Choice!.Options.Select(o => o.Label)];
        }
    }

    /// <summary>
    /// An activation cost of {X} is paid, and the ability reads the value that paid it
    /// (CR 602.2b).
    /// </summary>
    /// <remarks>
    /// Two halves that only work together, and only one of them existed. The engine already
    /// carried an announced number into <c>ActivateAbility</c> - it is how "remove any number of
    /// counters" is paid - but it was never handed to the mana payment, so an activation cost of
    /// <c>{X}</c> charged nothing at all: a tutor for as much as its controller cared to name,
    /// free. And the value never reached the ability's own object on the stack, so the filter
    /// that wanted it would have measured against zero as it resolved.
    /// <para>
    /// The pool is asserted empty afterwards for exactly that reason. A test that only checked
    /// what the search offered would pass with the cost still free.
    /// </para>
    /// </remarks>
    [Fact]
    public void An_activation_cost_of_X_is_paid_and_read_by_its_own_filter()
    {
        var flute = new CardDefinition
        {
            OracleId = "oracle-xfilter-citanul-flute",
            Name = "Citanul Flute Test",
            OracleText =
                "{X}, {T}: Search your library for a creature card with mana value X or less, "
                + "reveal it, put it into your hand, then shuffle.",
            CardTypes = CardType.Artifact,
            ManaCostRaw = "{5}",
            Cmc = 5,
        };

        var compiled = CardCompiler.Compile(flute);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var source = game.Create(alice, flute, Zone.Battlefield);
        game.Create(alice, Costed("Flute Cheap Test", 2), Zone.Library);
        game.Create(alice, Costed("Flute Dear Test", 5), Zone.Library);

        var ability = compiled.Activated[0].Id;

        // The board is told to ask for the number, which is the difference between an ability
        // the engine can run and one a player can reach. Without it the button sends zero and
        // the search finds nothing.
        Assert.True(
            Views.PlayerViewProjector.Project(game.State, alice, Pool)
                .Battlefield
                .Single(o => o.Name == "Citanul Flute Test")
                .Abilities
                .Single(a => string.Equals(a.Id, ability, StringComparison.Ordinal))
                .AnnouncesVariable);

        // One mana does not buy an X of two. The refusal is the whole point: without the
        // announcement reaching the payment this line was free.
        game.AddMana(alice, ManaColor.Green);

        Assert.Throws<InvalidOperationException>(
            () => game.ActivateAbility(alice, source, ability, null, null, 2));

        game.AddMana(alice, ManaColor.Green);
        game.ActivateAbility(alice, source, ability, null, null, 2);

        Assert.True(game.State.GetPlayer(alice).ManaPool.IsEmpty);

        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.SearchLibrary });

        var offered = game.State.Choice!.Options.Select(o => o.Label).ToList();

        Assert.Contains(offered, label => label.Contains("Flute Cheap", StringComparison.Ordinal));
        Assert.DoesNotContain(
            offered, label => label.Contains("Flute Dear", StringComparison.Ordinal));
    }

    /// <summary>
    /// A permanent's own trigger reads the X the spell that became it was cast for (CR 607.2).
    /// </summary>
    /// <remarks>
    /// The third place an X can come from, and the one that needed the value carried further than
    /// it had been. A permanent keeps what its spell announced - the reducer has done that since
    /// ravenous - but a triggered ability is its own object on the stack (CR 113.7a), and it was
    /// being put there with nothing. Its targets would then be chosen against the right number
    /// and re-checked on resolution against zero, so the trigger would fizzle every time and the
    /// card would still look implemented.
    /// </remarks>
    [Fact]
    public void A_triggered_ability_reads_the_X_its_permanent_was_cast_for()
    {
        var drifter = new CardDefinition
        {
            OracleId = "oracle-xfilter-dune-drifter",
            Name = "Dune Drifter Test",
            OracleText =
                "When this creature enters, return target creature card with mana value X or "
                + "less from your graveyard to the battlefield.",
            CardTypes = CardType.Creature,
            ManaCostRaw = "{X}{W}{B}",
            Cmc = 2,
            Power = 2,
            Toughness = 2,
        };

        var compiled = CardCompiler.Compile(drifter);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        game.Create(alice, Costed("Drifter Cheap Test", 3), Zone.Graveyard);
        game.Create(alice, Costed("Drifter Dear Test", 5), Zone.Graveyard);

        game.AddMana(alice, ManaColor.White, 4);
        game.AddMana(alice, ManaColor.Black);
        game.CastSpell(alice, TestCards.PutInHand(game, alice, drifter), null, 3);

        TestCards.PassUntil(
            game, () => game.State.Choice is { Kind: ChoiceKind.ChooseTriggerTargets });

        var choice = game.State.Choice!;
        var offered = choice.Options.Select(o => o.Label).ToList();

        Assert.Contains(offered, label => label.Contains("Drifter Cheap", StringComparison.Ordinal));
        Assert.DoesNotContain(
            offered, label => label.Contains("Drifter Dear", StringComparison.Ordinal));

        game.Choose(
            alice,
            [
                choice.Options
                    .First(o => o.Label.Contains("Drifter Cheap", StringComparison.Ordinal))
                    .Id,
            ]);

        Settle(game);

        // It resolved rather than fizzling, which is what says the ability carried the number
        // onto the stack with it.
        Assert.Contains(
            game.State.Battlefield.Select(game.State.GetObject),
            o => string.Equals(o.Card.Name, "Drifter Cheap Test", StringComparison.Ordinal));
    }

    /// <summary>
    /// A filter whose X nothing announces is left unread (CR 107.3).
    /// </summary>
    /// <remarks>
    /// The refusal that keeps the family honest, and it is worth more than the five cards it
    /// costs. Those five write the same clause about a completely different X - "where X is the
    /// number of Faeries you control", "you may pay {X}. If you do, ..." - and none of those
    /// numbers is one this engine reads. Compiled anyway they would each settle at zero, find
    /// nothing in any zone, and report themselves complete: a card that passes the deck gate and
    /// then does nothing, which this compiler treats as strictly worse than an unread line.
    /// <para>
    /// The contrast is the point of the third case. The same clause with a real announcement
    /// behind it reads perfectly, so what is refused is the missing X and not the sentence.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_filter_whose_X_nothing_announces_is_refused()
    {
        var counted = new CardDefinition
        {
            OracleId = "oracle-xfilter-spellstutter",
            Name = "Spellstutter Sprite Test",
            OracleText =
                "Flying\nWhen this creature enters, counter target spell with mana value X or "
                + "less, where X is the number of Faeries you control.",
            CardTypes = CardType.Creature,
            ManaCostRaw = "{1}{U}",
            Cmc = 2,
            Power = 1,
            Toughness = 1,
        };

        var paidMidway = new CardDefinition
        {
            OracleId = "oracle-xfilter-taj-nar",
            Name = "Taj-Nar Swordsmith Test",
            OracleText =
                "When this creature enters, you may pay {X}. If you do, search your library for "
                + "an Equipment card with mana value X or less, put that card onto the "
                + "battlefield, then shuffle.",
            CardTypes = CardType.Creature,
            ManaCostRaw = "{3}{W}",
            Cmc = 4,
            Power = 2,
            Toughness = 2,
        };

        foreach (var refused in new[] { counted, paidMidway })
        {
            var compiled = CardCompiler.Compile(refused);

            Assert.False(compiled.IsComplete);
            Assert.Contains(
                compiled.Unhandled,
                line => line.Contains("mana value X or less", StringComparison.Ordinal));
        }

        // The same clause, on a card that does announce one.
        var announced = CardCompiler.Compile(KillingGlare());
        Assert.True(announced.IsComplete, string.Join(" | ", announced.Unhandled));
    }

    // ---- A target that can see the other targets of the same spell (CR 601.2c) ----

    /// <summary>
    /// "From a single graveyard" is a restriction between the targets, and it is checked as they
    /// are announced (CR 601.2c).
    /// </summary>
    /// <remarks>
    /// <see cref="TargetSpec.PeerFilter"/> had existed for a while and had never once run while
    /// targets were being <em>chosen</em>. It was built for radiance, where the sibling is found
    /// as the spell resolves and an effect names its index; nothing carried an index at
    /// announcement time, so every card whose restriction is about the announcement stayed
    /// unread. Two families live there, and this is the larger: 14 cards say "exile up to N
    /// target cards from a single graveyard", and "…from a graveyard" already read, plural
    /// machinery and all. Only the word "single" was missing.
    /// <para>
    /// CR 601.2c announces every target at once, so an announcement that breaks the restriction
    /// is <em>illegal</em> — not legal with the offending part quietly skipped. Both refusals are
    /// played here rather than parsed: two cards from different graveyards, and the same card
    /// named twice, which CR 115.3 forbids for one instance of the word "target" and which
    /// nothing in this engine had ever refused.
    /// </para>
    /// </remarks>
    [Fact]
    public void Cards_from_a_single_graveyard_have_to_come_from_one_graveyard()
    {
        var decompose = Card(
            "Decompose Test",
            "Exile up to three target cards from a single graveyard.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(decompose);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        // The first pick is the one the others agree with, so it carries no comparison of its
        // own; every pick after it is measured against that one.
        var specs = compiled.Spell!.Targets;
        Assert.Equal(3, specs.Count);
        Assert.Null(specs[0].PeerIndex);
        Assert.Null(specs[0].PeerFilter);
        Assert.Equal(0, specs[1].PeerIndex);
        Assert.Equal(0, specs[2].PeerIndex);
        Assert.NotNull(specs[1].PeerFilter);

        var (game, alice, bob) = InMainPhase();
        var mine = game.Create(alice, TestCards.Creature("Peer Mine One Test"), Zone.Graveyard);
        var alsoMine = game.Create(
            alice, TestCards.Creature("Peer Mine Two Test"), Zone.Graveyard);
        var theirs = game.Create(bob, TestCards.Creature("Peer Theirs Test"), Zone.Graveyard);

        var card = TestCards.PutInHand(game, alice, decompose);

        // One from each graveyard is the announcement the word "single" exists to forbid. The
        // message names the spec that refused, so the refusal is this rule and not the count.
        var mixed = Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, card, [Target.ToCard(mine), Target.ToCard(theirs)]));

        Assert.Contains("single graveyard", mixed.Message, StringComparison.Ordinal);

        // The same card twice is one graveyard and still illegal: CR 115.3 says a target cannot
        // be chosen twice for one instance of the word "target", and "up to three target cards"
        // is one instance. Without this a one-card graveyard would answer a three-target spell.
        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, card, [Target.ToCard(mine), Target.ToCard(mine)]));

        // Neither refusal half-cast anything: the spell is still in hand (CR 601.2i, 733).
        Assert.Contains(card, game.State.GetPlayer(alice).Hand);

        game.CastSpell(alice, card, [Target.ToCard(mine), Target.ToCard(alsoMine)]);
        Settle(game);

        Assert.DoesNotContain(
            game.State.GetPlayer(alice).Graveyard.Select(game.State.GetObject),
            o => o.Card.Name.StartsWith("Peer Mine", StringComparison.Ordinal));

        // The other graveyard is untouched, which is the half a spell that ignored the word
        // would have got wrong.
        Assert.Contains(theirs, game.State.GetPlayer(bob).Graveyard);
    }

    /// <summary>
    /// A trigger is offered only the picks its earlier answer allows (CR 603.3d, 601.2c).
    /// </summary>
    /// <remarks>
    /// The board may never be shown a pick the engine would refuse, and a trigger chooses its
    /// targets one question at a time — so the second question has to be asked with the first
    /// answer in hand. Four of the fourteen cards in this family are enters-the-battlefield
    /// triggers, so this is where most of them are actually played.
    /// <para>
    /// It also shows the narrowing is a narrowing and not a refusal to offer anything: the first
    /// question offers all four cards, and only the second is cut down.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_triggers_second_pick_comes_from_the_graveyard_its_first_pick_did()
    {
        var sunshield = Card(
            "Sunshield Test",
            "When this creature enters, exile up to two target cards from a single graveyard.",
            CardType.Creature,
            2,
            2);

        var compiled = CardCompiler.Compile(sunshield);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, TestCards.Creature("Trigger Mine One Test"), Zone.Graveyard);
        game.Create(alice, TestCards.Creature("Trigger Mine Two Test"), Zone.Graveyard);
        var theirs = game.Create(
            bob, TestCards.Creature("Trigger Theirs One Test"), Zone.Graveyard);
        var alsoTheirs = game.Create(
            bob, TestCards.Creature("Trigger Theirs Two Test"), Zone.Graveyard);

        var card = TestCards.PutInHand(game, alice, sunshield);
        game.CastSpell(alice, card);

        TestCards.PassUntil(
            game,
            () => game.State.Choice is { Kind: ChoiceKind.ChooseTriggerTargets },
            guard: 200);

        // Nothing has been chosen yet, so every card in every graveyard is on offer.
        var first = game.State.Choice!;
        Assert.Equal(4, first.Options.Count);

        game.Choose(alice, [OptionForCard(theirs)]);

        TestCards.PassUntil(
            game,
            () => game.State.Choice is { Kind: ChoiceKind.ChooseTriggerTargets },
            guard: 200);

        // One option: the other card in the same graveyard. Not the two in Alice's, and not the
        // card already chosen.
        var second = game.State.Choice!;
        Assert.Equal([OptionForCard(alsoTheirs)], second.Options.Select(o => o.Id));

        game.Choose(alice, [second.Options[0].Id]);
        Settle(game);

        Assert.Empty(game.State.GetPlayer(bob).Graveyard);
        Assert.Equal(2, game.State.GetPlayer(alice).Graveyard.Count);
    }

    /// <summary>The option id the engine offers for one card in a graveyard.</summary>
    /// <remarks>
    /// Built here rather than matched by label, because two cards with the same name give the
    /// same label and the whole question this test asks is <em>which</em> card was offered.
    /// </remarks>
    private static string OptionForCard(ObjectId id) =>
        "card:" + id.Value.ToString("N", CultureInfo.InvariantCulture);

    /// <summary>
    /// "Any other target" is other than the target the same spell already chose (CR 115.4).
    /// </summary>
    /// <remarks>
    /// The second family the missing index blocked, and the one that shows why the comparison
    /// could not be an object filter: Arc Trail may not put both halves of its damage on the
    /// same <em>player</em>, and a player is not an object. So the restriction is asked of the
    /// chosen <see cref="Target"/> rather than of anything on the battlefield.
    /// <para>
    /// The word means the source instead when the ability has named no target of its own —
    /// Screaming Nemesis and Invasion of Ulgrotha, where "it deals that much damage to any other
    /// target" means anything but itself — and that reading is the ordinary source exclusion
    /// "another target creature" has always had. Only the sibling reading needed an index.
    /// </para>
    /// </remarks>
    [Fact]
    public void Any_other_target_may_not_be_the_target_already_chosen()
    {
        var arcTrail = Card(
            "Arc Trail Peer Test",
            "~ deals 2 damage to any target and 1 damage to any other target.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(arcTrail);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.Null(compiled.Spell!.Targets[0].PeerIndex);
        Assert.Equal(0, compiled.Spell.Targets[1].PeerIndex);

        var (game, alice, bob) = InMainPhase();
        var bear = game.Create(
            bob, TestCards.Creature("Arc Peer Bear Test", 3, 3), Zone.Battlefield);
        var card = TestCards.PutInHand(game, alice, arcTrail);

        // The same player twice would be three damage to one head off a spell that spreads two
        // and one. No object filter could ever have said so.
        var twice = Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, card, [Target.ToPlayer(bob), Target.ToPlayer(bob)]));

        Assert.Contains("any other target", twice.Message, StringComparison.Ordinal);

        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(
                alice, card, [Target.ToPermanent(bear), Target.ToPermanent(bear)]));

        game.CastSpell(alice, card, [Target.ToPlayer(bob), Target.ToPermanent(bear)]);
        Settle(game);

        Assert.Equal(18, game.State.GetPlayer(bob).Life);
        Assert.Equal(1, game.State.GetObject(bear).Permanent!.DamageMarked);
    }

    /// <summary>
    /// "Each of two targets" is two different targets (CR 115.3, 115.4).
    /// </summary>
    /// <remarks>
    /// The plural of "any target", and the neighbour that fell out of the same index. "Each of
    /// two target creatures" already read; "each of two targets" names no noun because CR 115.4
    /// puts the plural beside "any target" as a way of saying creature, player, planeswalker or
    /// battle at once — so the bare form rewrites to the singular the grammar already knows.
    /// <para>
    /// Its distinctness is not a peer <em>filter</em> at all: it is CR 115.3 alone, and it now
    /// covers every expansion the compiler makes. "Up to two target creatures get +1/+1" was
    /// castable at one creature for +2/+2 until specs could carry an index.
    /// </para>
    /// </remarks>
    [Fact]
    public void Each_of_two_targets_has_to_be_two_of_them()
    {
        var reprisal = Card(
            "Furious Reprisal Test",
            "~ deals 2 damage to each of two targets.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(reprisal);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.Equal(2, compiled.Spell!.Targets.Count);
        Assert.Equal(0, compiled.Spell.Targets[1].PeerIndex);

        var (game, alice, bob) = InMainPhase();
        var bear = game.Create(
            bob, TestCards.Creature("Reprisal Bear Test", 3, 3), Zone.Battlefield);
        var card = TestCards.PutInHand(game, alice, reprisal);

        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, card, [Target.ToPlayer(bob), Target.ToPlayer(bob)]));

        game.CastSpell(alice, card, [Target.ToPlayer(bob), Target.ToPermanent(bear)]);
        Settle(game);

        Assert.Equal(18, game.State.GetPlayer(bob).Life);
        Assert.Equal(2, game.State.GetObject(bear).Permanent!.DamageMarked);
    }

    /// <summary>
    /// A counterspell that asks what the other spell is aimed at (CR 115.1, 601.2c).
    /// </summary>
    /// <remarks>
    /// The adjacent row taken in the same round, and no peer at all: the spell on the stack
    /// already carries the targets it was cast with, so the whole clause is a predicate over that
    /// list. Fourteen cards, and the noun phrase inside the clause is read by the same grammar
    /// that reads it anywhere else — "a creature you control" is not a second vocabulary.
    /// </remarks>
    [Fact]
    public void Counter_target_spell_that_targets_a_creature_reads_what_it_was_aimed_at()
    {
        var confound = Card(
            "Confound Test", "Counter target spell that targets a creature.", CardType.Instant);

        var compiled = CardCompiler.Compile(confound);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var bolt = Card("Peer Bolt Test", "~ deals 3 damage to any target.");

        var (game, alice, bob) = InMainPhase();
        var bear = game.Create(
            bob, TestCards.Creature("Confound Bear Test", 5, 5), Zone.Battlefield);

        // A bolt aimed at a player is not a spell that targets a creature, so the counterspell
        // has no legal target for it. A counterspell that could hit anything is a strictly
        // better card than the one printed, which is the failure this clause exists to avoid.
        var atAPlayer = TestCards.PutInHand(game, alice, bolt);
        var wrongAnswer = TestCards.PutInHand(game, bob, confound);
        var missing = game.CastSpell(alice, atAPlayer, [Target.ToPlayer(bob)]);
        game.PassPriority(alice);

        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(bob, wrongAnswer, [Target.ToSpell(missing)]));

        Settle(game);
        Assert.Equal(17, game.State.GetPlayer(bob).Life);

        // The same bolt aimed at a creature is one it may counter.
        var atACreature = TestCards.PutInHand(game, alice, bolt);
        var answer = TestCards.PutInHand(game, bob, confound);
        var aimed = game.CastSpell(alice, atACreature, [Target.ToPermanent(bear)]);
        game.PassPriority(alice);
        game.CastSpell(bob, answer, [Target.ToSpell(aimed)]);
        Settle(game);

        Assert.Equal(0, game.State.GetObject(bear).Permanent!.DamageMarked);
    }

    /// <summary>
    /// A spell qualifier that was parsed and then dropped (CR 115.1).
    /// </summary>
    /// <remarks>
    /// Found while measuring the row above, and a live bug rather than a gap. "Counter target
    /// spell with mana value 4 or greater" compiled <em>complete</em>: the clause was lifted off
    /// the phrase, checked against the qualifier grammar, and then thrown away, because the arm
    /// that answers "spell" returned before anything applied it. Disdainful Stroke, Thoughtbind,
    /// Liquify, Minor Misstep, Change the Equation, Hypnotic Sprite, Runescale Stormbrood and
    /// Spell Queller were all shipped as unconditional counterspells, and nothing said so —
    /// coverage counted them, and a card that is better than printed passes every gate this
    /// project has except a test that plays it.
    /// </remarks>
    [Fact]
    public void Counter_target_spell_with_mana_value_4_or_greater_leaves_a_cheap_one_alone()
    {
        var stroke = Card(
            "Disdainful Stroke Test",
            "Counter target spell with mana value 4 or greater.",
            CardType.Instant);

        var compiled = CardCompiler.Compile(stroke);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var cheap = TestCards.PutInHand(
            game, alice, TestCards.Costed("Cheap Threat Test", "{G}", 1));
        var dear = TestCards.PutInHand(
            game, alice, TestCards.Costed("Costly Threat Test", "{4}{G}", 5));

        game.AddMana(alice, ManaColor.Green, 1);

        var refused = TestCards.PutInHand(game, bob, stroke);
        var small = game.CastSpell(alice, cheap, []);
        game.PassPriority(alice);

        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(bob, refused, [Target.ToSpell(small)]));

        Settle(game);

        Assert.Contains(
            game.State.Battlefield.Select(game.State.GetObject),
            o => o.Card.Name == "Cheap Threat Test");

        // The same counterspell against the same player's five-drop, which is what it is for.
        game.AddMana(alice, ManaColor.Green, 5);
        var answer = TestCards.PutInHand(game, bob, stroke);
        var big = game.CastSpell(alice, dear, []);
        game.PassPriority(alice);
        game.CastSpell(bob, answer, [Target.ToSpell(big)]);
        Settle(game);

        Assert.DoesNotContain(
            game.State.Battlefield.Select(game.State.GetObject),
            o => o.Card.Name == "Costly Threat Test");
    }

    // ---- The player a sentence already named (CR 603.2, 109.5) ---------------

    /// <summary>
    /// "That player's hand" is the hand of the player this spell targeted, not the caster's.
    /// </summary>
    /// <remarks>
    /// Storm Seeker's wording, and the whole family behind it - Sudden Impact, Gaze of Adamaro,
    /// Toil // Trouble - reads the same sentence. The count was unreadable before because the
    /// counting vocabulary had no word for a player at all: it is handed the state, the
    /// controller and the source, and "that player" is none of those three.
    /// <para>
    /// The two hands are made different sizes on purpose. Equal hands is the shape in which every
    /// possible reading of the pronoun gives the same answer, and it is the shape a two-player
    /// test falls into by default.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_counted_hand_is_the_hand_of_the_player_the_spell_named()
    {
        var seeker = Card(
            "Storm Seeker Test",
            "~ deals damage to target player equal to the number of cards in that player's hand.",
            CardType.Instant);

        var compiled = CardCompiler.Compile(seeker);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, seats) = FourPlayers();

        // Three cards to the seat that will be aimed at, and none to anybody else, so the number
        // the spell arrives at can only have come from the right pile.
        for (var i = 0; i < 3; i++)
            TestCards.PutInHand(game, seats[2], TestCards.Creature($"Held Card {i} Test", 1, 1));

        var mine = game.State.GetPlayer(seats[0]).Hand.Count;
        var theirs = game.State.GetPlayer(seats[2]).Hand.Count;
        Assert.NotEqual(mine, theirs);

        var before = game.State.GetPlayer(seats[2]).Life;
        var card = TestCards.PutInHand(game, seats[0], seeker);
        game.AddMana(seats[0], ManaColor.Green, 4);
        game.CastSpell(seats[0], card, [Target.ToPlayer(seats[2])]);
        Settle(game);

        // The spell itself has left the caster's hand, so "mine" would be one lower again - the
        // point is only that it is not the number that landed.
        Assert.Equal(before - theirs, game.State.GetPlayer(seats[2]).Life);
        Assert.NotEqual(before - mine, game.State.GetPlayer(seats[2]).Life);
    }

    /// <summary>
    /// An activated ability names its own target the same way a spell does (CR 602.2b).
    /// </summary>
    /// <remarks>
    /// Keening Stone. The pronoun is resolved off the announcement rather than off a triggering
    /// event, and an activated ability has no triggering event at all - so a reading that looked
    /// only at the trigger would mill nobody's library and the card would compile perfectly.
    /// </remarks>
    [Fact]
    public void An_activated_ability_counts_the_pile_of_the_player_it_named()
    {
        var stone = Card(
            "Keening Stone Test",
            "{5}, {T}: Target player mills X cards, where X is the number of cards in that"
                + " player's graveyard.",
            CardType.Artifact);

        var compiled = CardCompiler.Compile(stone);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, seats) = FourPlayers();
        var rock = game.Create(seats[0], stone, Zone.Battlefield);

        // Four cards in the victim's graveyard and one in the activating player's, so the two
        // possible answers are four and one.
        for (var i = 0; i < 4; i++)
            game.Create(seats[1], TestCards.Creature($"Dead Card {i} Test", 1, 1), Zone.Graveyard);

        game.Create(seats[0], TestCards.Creature("My Dead Card Test", 1, 1), Zone.Graveyard);

        var before = game.State.GetPlayer(seats[1]).Library.Count;

        game.AddMana(seats[0], null, 5);
        game.ActivateAbility(seats[0], rock, CardCompiler.Compile(stone).Activated[0].Id,
            [Target.ToPlayer(seats[1])]);

        Settle(game);

        Assert.Equal(before - 4, game.State.GetPlayer(seats[1]).Library.Count);
    }

    /// <summary>
    /// "Its controller" after a target is the controller of what was targeted (CR 608.2).
    /// </summary>
    /// <remarks>
    /// Assassin's Strike, Desecrated Earth, Dismal Failure and Pistus Strike are one sentence
    /// apart and were all unread, because the pronoun rewrite refused outright whenever anything
    /// had been targeted. That refusal was written when the readers it protected tested for the
    /// printed spelling; they now test for the rewritten one as well, so the phrase can be
    /// normalised in one place for everything.
    /// </remarks>
    [Fact]
    public void Its_controller_after_a_target_is_the_targets_controller()
    {
        var strike = Card(
            "Assassin's Strike Test",
            "Destroy target creature. Its controller discards a card.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(strike);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var bear = game.Create(bob, TestCards.Creature("Struck Bear Test", 2, 2), Zone.Battlefield);

        var mine = game.State.GetPlayer(alice).Hand.Count;
        var theirs = game.State.GetPlayer(bob).Hand.Count;

        var card = TestCards.PutInHand(game, alice, strike);
        game.CastSpell(alice, card, [Target.ToPermanent(bear)]);
        Settle(game);

        // Bob is one card poorer; Alice is only down the spell she cast.
        Assert.Equal(theirs - 1, game.State.GetPlayer(bob).Hand.Count);
        Assert.Equal(mine, game.State.GetPlayer(alice).Hand.Count);
    }

    /// <summary>
    /// The two-part damage reader still recognises its own second half.
    /// </summary>
    /// <remarks>
    /// The control on the change above. That reader tests the sentence's second clause for the
    /// pronoun by hand, and widening the rewrite is exactly the way a reader loses a clause to
    /// its neighbour - the failure this suite exists to catch. It is here rather than trusted to
    /// the coverage number because every card printing this shape is short something else as
    /// well, so no corpus count would have moved either way.
    /// </remarks>
    [Fact]
    public void Two_part_damage_still_reaches_the_targeted_creatures_controller()
    {
        var shock = Card(
            "Two Part Damage Test",
            "~ deals 2 damage to target creature and 2 damage to that creature's controller.",
            CardType.Instant);

        var compiled = CardCompiler.Compile(shock);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var bear = game.Create(bob, TestCards.Creature("Shocked Bear Test", 3, 3), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, shock);
        game.CastSpell(alice, card, [Target.ToPermanent(bear)]);
        Settle(game);

        Assert.Equal(18, game.State.GetPlayer(bob).Life);
        Assert.Equal(20, game.State.GetPlayer(alice).Life);
        Assert.Equal(2, game.State.GetObject(bear).Permanent!.DamageMarked);
    }

    /// <summary>
    /// "Each other player's draw step" is everybody's but your own (CR 500.1).
    /// </summary>
    /// <remarks>
    /// Well of Ideas, and the only card in the corpus the two step-owner lists were costing. The
    /// words were on sixteen corpus cards and neither list had them, because each list was
    /// written out beside the reader that wanted it rather than taken from the vocabulary next
    /// door - the whole reason this round exists.
    /// </remarks>
    [Fact]
    public void A_trigger_on_each_other_players_step_skips_your_own()
    {
        var well = Card(
            "Well of Ideas Test",
            "At the beginning of each other player's draw step, that player draws an additional"
                + " card.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(well);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, well, Zone.Battlefield);

        // Turn 2 is Bob's: his draw step draws him two cards rather than one.
        var his = game.State.GetPlayer(bob).Library.Count;
        PassTo(game, 2, TurnStep.PrecombatMain);
        Assert.Equal(his - 2, game.State.GetPlayer(bob).Library.Count);

        // Turn 3 is Alice's own, and "each other player" is not her.
        var hers = game.State.GetPlayer(alice).Library.Count;
        PassTo(game, 3, TurnStep.PrecombatMain);
        Assert.Equal(hers - 1, game.State.GetPlayer(alice).Library.Count);
    }

    /// <summary>
    /// A step trigger refuses a possessive that names nobody a turn can belong to.
    /// </summary>
    /// <remarks>
    /// The fail-closed half of sharing the vocabulary, and the reason the reader was rewritten
    /// rather than merely re-pointed. The prefix tests it replaced answered "everybody" to every
    /// word that was not one of the four they knew, so handing them a list of nine would have
    /// turned "that player's upkeep" into a trigger firing on all four turns - a strictly better
    /// card than the one printed, and a change coverage would have counted as a win.
    /// </remarks>
    [Fact]
    public void A_step_trigger_refuses_a_possessive_no_turn_can_belong_to()
    {
        var wrong = Card(
            "Unseated Upkeep Test",
            "At the beginning of that player's upkeep, you gain 1 life.",
            CardType.Enchantment);

        Assert.False(CardCompiler.Compile(wrong).IsComplete);

        var alsoWrong = Card(
            "Unseated Combat Test",
            "At the beginning of combat on that player's turn, you gain 1 life.",
            CardType.Enchantment);

        Assert.False(CardCompiler.Compile(alsoWrong).IsComplete);
    }

    /// <summary>
    /// "Your opponents' graveyards" is all of them, and none of yours (CR 109.5).
    /// </summary>
    /// <remarks>
    /// Wight of Precinct Six. A static pump that counts a zone, and it fell out of sharing the
    /// possessives with no work of its own: the reader that answers it had a private list of two
    /// words and this is a third. Counted at four players because at two, "your opponents'" and
    /// "each opponent's" and "target opponent's" all name the same person.
    /// </remarks>
    [Fact]
    public void A_static_count_of_your_opponents_graveyards_counts_every_opponent()
    {
        var wight = Card(
            "Wight of Precinct Six Test",
            "~ gets +1/+1 for each creature card in your opponents' graveyards.",
            CardType.Creature,
            power: 1,
            toughness: 1);

        var compiled = CardCompiler.Compile(wight);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, seats) = FourPlayers();
        var body = game.Create(seats[0], wight, Zone.Battlefield);

        // One creature card in each opponent's graveyard, and two in the controller's own - so
        // "each player's" would say five and "your" would say two.
        for (var i = 1; i < seats.Count; i++)
            game.Create(seats[i], TestCards.Creature($"Buried Bear {i} Test", 2, 2), Zone.Graveyard);

        game.Create(seats[0], TestCards.Creature("My Buried Bear Test", 2, 2), Zone.Graveyard);
        game.Create(seats[0], TestCards.Creature("My Other Bear Test", 2, 2), Zone.Graveyard);

        Assert.Equal(4, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(body)));
    }

    /// <summary>
    /// On an Aura, "its controller" is whoever controls the creature it is on.
    /// </summary>
    /// <remarks>
    /// Righteous Authority, Death's Approach and Disturbing Conversion. There is no resolution
    /// here to ask - a continuous effect is computed with no targets and no trigger - but there
    /// is a seat, and it is the one being computed: an attached effect only ever applies to the
    /// permanent it is attached to. That is the whole of what the <c>Host</c> reach means.
    /// </remarks>
    [Fact]
    public void An_aura_counting_its_controllers_hand_counts_the_hosts_controller()
    {
        var authority = Card(
            "Righteous Authority Test",
            "Enchant creature\nEnchanted creature gets +1/+1 for each card in its controller's"
                + " hand.",
            CardType.Enchantment,
            subtypes: "Aura");

        var compiled = CardCompiler.Compile(authority);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var theirs = game.Create(bob, TestCards.Creature("Authorised Bear Test", 2, 2), Zone.Battlefield);
        var aura = game.Create(alice, authority, Zone.Battlefield);
        game.Attach(aura, theirs);
        Settle(game);

        // Two more cards in Bob's hand than Alice's, so the two readings cannot agree.
        TestCards.PutInHand(game, bob, TestCards.Creature("Bob Card One Test", 1, 1));
        TestCards.PutInHand(game, bob, TestCards.Creature("Bob Card Two Test", 1, 1));

        var his = game.State.GetPlayer(bob).Hand.Count;
        var hers = game.State.GetPlayer(alice).Hand.Count;
        Assert.NotEqual(his, hers);

        Assert.Equal(
            2 + his, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(theirs)));
    }

    /// <summary>
    /// The same reader still counts <em>your</em> graveyard when the card says "your".
    /// </summary>
    /// <remarks>
    /// The control on the Aura above. "Your" on an Aura means the Aura's controller and not the
    /// enchanted creature's, and the two come apart only when the Aura is on somebody else's
    /// creature - which is what most of them are for.
    /// </remarks>
    [Fact]
    public void An_aura_counting_your_graveyard_still_counts_the_auras_controller()
    {
        var weight = Card(
            "Aura Your Graveyard Test",
            "Enchant creature\nEnchanted creature gets +1/+1 for each creature card in your"
                + " graveyard.",
            CardType.Enchantment,
            subtypes: "Aura");

        var compiled = CardCompiler.Compile(weight);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var theirs = game.Create(bob, TestCards.Creature("Weighed Bear Test", 2, 2), Zone.Battlefield);
        var aura = game.Create(alice, weight, Zone.Battlefield);
        game.Attach(aura, theirs);

        game.Create(alice, TestCards.Creature("Alice Dead Bear Test", 2, 2), Zone.Graveyard);
        game.Create(bob, TestCards.Creature("Bob Dead Bear One Test", 2, 2), Zone.Graveyard);
        game.Create(bob, TestCards.Creature("Bob Dead Bear Two Test", 2, 2), Zone.Graveyard);
        Settle(game);

        // One from Alice's graveyard, not two from Bob's.
        Assert.Equal(3, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(theirs)));
    }

    /// <summary>
    /// A continuous effect refuses a possessive only a resolution could seat.
    /// </summary>
    /// <remarks>
    /// The other half of failing closed. A static ability has no targets and no triggering
    /// event, so "that player" names nobody there - and a count of nobody's pile is nought,
    /// which compiles as a complete card that quietly does nothing. Refused instead.
    /// </remarks>
    [Fact]
    public void A_static_count_refuses_a_player_only_a_resolution_could_find()
    {
        var wrong = Card(
            "Unseated Static Count Test",
            "Enchant creature\nEnchanted creature gets +1/+1 for each card in that player's"
                + " graveyard.",
            CardType.Enchantment,
            subtypes: "Aura");

        Assert.False(CardCompiler.Compile(wrong).IsComplete);
    }

    // ---- Looking at the top, and taking more than one (CR 701.20a) -----------

    /// <summary>A creature that costs something, so a mana-value bound has work to do.</summary>
    private static CardDefinition Priced(string name, int manaValue) => new()
    {
        OracleId = "oracle-r17-" + name.ToLowerInvariant().Replace(' ', '-'),
        Name = name,
        Cmc = manaValue,
        CardTypes = CardType.Creature,
        Subtypes = ["Goblin"],
        Power = 1,
        Toughness = 1,
    };

    /// <summary>
    /// "Put two of them into your hand and the rest into your graveyard" — a look whose answer
    /// is more than one card.
    /// </summary>
    /// <remarks>
    /// The engine took exactly one pick until this family was measured, so every printing that
    /// keeps two was unread. The ceiling is on the answer rather than on the question: taking
    /// fewer stays legal, as it has been for the one-card form since that form existed.
    /// </remarks>
    [Fact]
    public void A_look_that_keeps_two_offers_two_picks_and_takes_both()
    {
        var dig = Card(
            "R17 Stock Up Test",
            "Look at the top four cards of your library. Put two of them into your hand and "
                + "the rest into your graveyard.");

        var compiled = CardCompiler.Compile(dig);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        game.Create(alice, TestCards.Creature("R17 Stock Bear Test", 2, 2), Zone.Library);
        game.Create(alice, TestCards.BasicLand("R17 Stock Forest Test"), Zone.Library);
        game.Create(alice, TestCards.BasicLand("R17 Stock Plains Test"), Zone.Library);
        game.Create(alice, TestCards.BasicLand("R17 Stock Island Test"), Zone.Library);

        var card = TestCards.PutInHand(game, alice, dig);
        game.CastSpell(alice, card, targets: null);
        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.LookAndTake });

        var choice = game.State.Choice!;
        Assert.Equal(4, choice.Options!.Count);
        Assert.Equal(2, choice.MaxPicks);

        var kept = new[] { choice.Options[0], choice.Options[1] };
        game.Choose(alice, [.. kept.Select(o => o.Id)]);
        Settle(game);

        var hand = game.State.GetPlayer(alice).Hand
            .Select(id => game.State.GetObject(id).Card.Name)
            .ToList();

        foreach (var one in kept)
            Assert.Contains(one.Label, hand);

        // The other two were binned rather than buried, which is what this printing says and
        // what the shape it was built from does not. Named rather than counted: the spell itself
        // is in the graveyard too, and a count would have passed on the wrong two cards.
        var graveyard = game.State.GetPlayer(alice).Graveyard
            .Select(id => game.State.GetObject(id).Card.Name)
            .ToHashSet(StringComparer.Ordinal);

        foreach (var binned in choice.Options.Skip(2))
            Assert.Contains(binned.Label, graveyard);
    }

    /// <summary>
    /// "Put all Goblin cards revealed this way into your hand" — every match, and no question.
    /// </summary>
    /// <remarks>
    /// The sentence gives the player nothing to decide, so asking would raise a prompt whose only
    /// legal answer is every option on it — CR 118.3, the rule the empty filter already obeyed
    /// one branch along. This is the half of the family that needs no chooser at all, and reading
    /// it as a chooser with an unlimited ceiling would have been a question nobody can answer
    /// wrongly and everybody has to answer.
    /// </remarks>
    [Fact]
    public void Putting_all_of_a_kind_into_your_hand_asks_nobody()
    {
        var ringleader = Card(
            "R17 Ringleader Test",
            "Reveal the top four cards of your library. Put all Goblin cards revealed this way "
                + "into your hand and the rest on the bottom of your library in any order.");

        var compiled = CardCompiler.Compile(ringleader);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        game.Create(alice, TestCards.BasicLand("R17 Ring Forest Test"), Zone.Library);
        game.Create(alice, Priced("R17 Ring Goblin One Test", 1), Zone.Library);
        game.Create(alice, TestCards.BasicLand("R17 Ring Plains Test"), Zone.Library);
        game.Create(alice, Priced("R17 Ring Goblin Two Test", 2), Zone.Library);

        var card = TestCards.PutInHand(game, alice, ringleader);
        var libraryBefore = game.State.GetPlayer(alice).Library.Count;

        game.CastSpell(alice, card, targets: null);
        Settle(game);

        Assert.DoesNotContain(
            game.Log.OfType<ChoiceRequested>(), e => e.Choice.Kind == ChoiceKind.LookAndTake);

        var hand = game.State.GetPlayer(alice).Hand
            .Select(id => game.State.GetObject(id).Card.Name)
            .ToList();

        Assert.Contains("R17 Ring Goblin One Test", hand);
        Assert.Contains("R17 Ring Goblin Two Test", hand);
        Assert.DoesNotContain("R17 Ring Forest Test", hand);

        // Both Goblins left the library and the two lands went back into it.
        Assert.Equal(libraryBefore - 2, game.State.GetPlayer(alice).Library.Count);
    }

    /// <summary>
    /// "You may put a creature card with mana value 2 or less from among them onto the
    /// battlefield" — the search's own bound, asked of a smaller pile.
    /// </summary>
    [Fact]
    public void A_mana_value_ceiling_keeps_the_bigger_card_off_the_list()
    {
        var company = Card(
            "R17 Company Test",
            "Look at the top three cards of your library. You may put a creature card with mana "
                + "value 2 or less from among them onto the battlefield. Put the rest on the "
                + "bottom of your library in a random order.");

        var compiled = CardCompiler.Compile(company);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        game.Create(alice, Priced("R17 Company Giant Test", 6), Zone.Library);
        game.Create(alice, Priced("R17 Company Whelp Test", 2), Zone.Library);
        game.Create(alice, TestCards.BasicLand("R17 Company Forest Test"), Zone.Library);

        var card = TestCards.PutInHand(game, alice, company);
        game.CastSpell(alice, card, targets: null);
        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.LookAndTake });

        var choice = game.State.Choice!;

        // Two creatures were seen and only the cheap one may be taken. Offering the six-drop
        // would be a strictly better card than the one printed.
        var offered = choice.Options!.Select(o => o.Label).ToList();
        Assert.Contains("R17 Company Whelp Test", offered);
        Assert.DoesNotContain("R17 Company Giant Test", offered);

        game.Choose(alice, [choice.Options[0].Id]);
        Settle(game);

        Assert.Contains(
            game.State.Battlefield,
            id => game.State.GetObject(id).Card.Name == "R17 Company Whelp Test");
    }

    /// <summary>
    /// "With mana value 3 or greater" is a floor, and this reader carries only a ceiling.
    /// </summary>
    /// <remarks>
    /// Left unread rather than taken as the bound beside it. Read as "3 or less" the card would
    /// offer exactly the cards it puts out of reach — a mistake nothing downstream could see,
    /// because the card would compile and play perfectly happily.
    /// </remarks>
    [Fact]
    public void A_mana_value_floor_is_refused_rather_than_read_as_a_ceiling()
    {
        var mayael = Card(
            "R17 Mayael Test",
            "Look at the top five cards of your library. You may put a creature card with mana "
                + "value 6 or greater from among them onto the battlefield. Put the rest on the "
                + "bottom of your library in a random order.");

        Assert.False(CardCompiler.Compile(mayael).IsComplete);
    }

    /// <summary>"Onto the battlefield tapped" — how the taken card arrives (CR 701.26a).</summary>
    [Fact]
    public void A_taken_land_can_arrive_tapped()
    {
        var rejuvenator = Card(
            "R17 Rejuvenator Test",
            "Look at the top three cards of your library. You may put a land card from among "
                + "them onto the battlefield tapped. Put the rest on the bottom of your library "
                + "in a random order.");

        var compiled = CardCompiler.Compile(rejuvenator);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        game.Create(alice, TestCards.Creature("R17 Rejuv Bear Test", 2, 2), Zone.Library);
        game.Create(alice, TestCards.Creature("R17 Rejuv Cub Test", 1, 1), Zone.Library);
        game.Create(alice, TestCards.BasicLand("R17 Rejuv Forest Test"), Zone.Library);

        var card = TestCards.PutInHand(game, alice, rejuvenator);
        game.CastSpell(alice, card, targets: null);
        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.LookAndTake });

        var choice = game.State.Choice!;
        game.Choose(alice, [choice.Options![0].Id]);
        Settle(game);

        var arrived = game.State.Battlefield
            .Select(id => game.State.GetObject(id))
            .Single(o => o.Card.Name == "R17 Rejuv Forest Test");

        Assert.True(arrived.Permanent!.IsTapped);
    }

    /// <summary>"Put one of them into your hand, and exile the rest" — Browse's ending.</summary>
    [Fact]
    public void The_rest_can_be_exiled_rather_than_buried()
    {
        var browse = Card(
            "R17 Browse Test",
            "Look at the top three cards of your library. Put one of them into your hand and "
                + "exile the rest.");

        var compiled = CardCompiler.Compile(browse);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        game.Create(alice, TestCards.BasicLand("R17 Browse Forest Test"), Zone.Library);
        game.Create(alice, TestCards.BasicLand("R17 Browse Plains Test"), Zone.Library);
        game.Create(alice, TestCards.BasicLand("R17 Browse Island Test"), Zone.Library);

        var card = TestCards.PutInHand(game, alice, browse);
        game.CastSpell(alice, card, targets: null);
        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.LookAndTake });

        game.Choose(alice, [game.State.Choice!.Options![0].Id]);
        Settle(game);

        var exiled = game.State.Exile
            .Select(id => game.State.GetObject(id).Card.Name)
            .Count(n => n.StartsWith("R17 Browse ", StringComparison.Ordinal));

        Assert.Equal(2, exiled);
    }

    /// <summary>
    /// A reveal shows everybody what the choice was made from; a look shows only the player.
    /// </summary>
    /// <remarks>
    /// The two verbs are one instruction with different audiences (CR 701.20a, 701.20e), and the
    /// opening verb is the whole of the difference. Reading "reveal the top five cards" as a look
    /// would hide from every opponent which five cards the choice was made from — a card strictly
    /// better than the one printed, and one no assertion about the hand would catch.
    /// </remarks>
    [Fact]
    public void Revealing_records_what_was_seen_and_looking_does_not()
    {
        var revealed = Card(
            "R17 Revealed Dig Test",
            "Reveal the top two cards of your library. Put one of them into your hand and the "
                + "rest into your graveyard.");

        var looked = Card(
            "R17 Looked Dig Test",
            "Look at the top two cards of your library. Put one of them into your hand and the "
                + "rest into your graveyard.");

        Assert.True(CardCompiler.Compile(revealed).IsComplete);
        Assert.True(CardCompiler.Compile(looked).IsComplete);

        var (openly, alice, _) = InMainPhase();
        openly.CastSpell(alice, TestCards.PutInHand(openly, alice, revealed), targets: null);
        Run(openly);
        Assert.Contains(openly.Log.OfType<CardsRevealed>(), e => e.PlayerId == alice);

        var (privately, carol, _) = InMainPhase();
        privately.CastSpell(carol, TestCards.PutInHand(privately, carol, looked), targets: null);
        Run(privately);
        Assert.DoesNotContain(privately.Log.OfType<CardsRevealed>(), e => e.PlayerId == carol);
    }

    /// <summary>Only the player being asked is sent the cards to choose from.</summary>
    /// <remarks>
    /// A look is shown to one player (CR 701.20e), and the options on this question <em>are</em>
    /// the top of that player's library. The projector holds that line for every choice rather
    /// than for each kind in turn, but a look is the kind where getting it wrong hands an
    /// opponent the top of a library — so it is asserted here rather than assumed.
    /// </remarks>
    [Fact]
    public void Only_the_player_looking_is_sent_what_they_are_choosing_from()
    {
        var dig = Card(
            "R17 Private Dig Test",
            "Look at the top three cards of your library. Put one of them into your hand and "
                + "the rest on the bottom of your library in a random order.");

        var (game, alice, bob) = InMainPhase();
        game.CastSpell(alice, TestCards.PutInHand(game, alice, dig), targets: null);
        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.LookAndTake });

        var mine = Views.PlayerViewProjector.Project(game.State, alice, Pool).Choice;
        var theirs = Views.PlayerViewProjector.Project(game.State, bob, Pool).Choice;

        Assert.NotNull(mine!.Options);
        Assert.Equal(3, mine.Options!.Count);
        Assert.Null(theirs!.Options);
    }

    /// <summary>
    /// "…, where X is the number of lands you control" — a count the board decides, in front of
    /// an idiom that has to be read across two sentences.
    /// </summary>
    /// <remarks>
    /// The clause is read here rather than by the sentence-level wrapper that reads it
    /// everywhere else, because that wrapper anchors it to the end of a sentence and here it
    /// ends the <em>first</em> of the two sentences the look needs read together. Splitting the
    /// line to reach the wrapper is the one thing this idiom exists not to do.
    /// </remarks>
    [Fact]
    public void A_look_can_be_as_deep_as_the_board_makes_it()
    {
        var machinate = Card(
            "R17 Machinate Test",
            "Look at the top X cards of your library, where X is the number of lands you "
                + "control. Put one of those cards into your hand and the rest on the bottom of "
                + "your library in any order.");

        var compiled = CardCompiler.Compile(machinate);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        game.Create(alice, TestCards.BasicLand("R17 Mach Land One Test"), Zone.Battlefield);
        game.Create(alice, TestCards.BasicLand("R17 Mach Land Two Test"), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, machinate);
        game.CastSpell(alice, card, targets: null);
        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.LookAndTake });

        // Two lands on the battlefield, so two cards were looked at - not the one a fixed
        // reading of X would have given, and not the zero an uncast X comes to.
        Assert.Equal(2, game.State.Choice!.Options!.Count);
    }

    /// <summary>
    /// The idiom printed after a sentence that has nothing to do with it.
    /// </summary>
    /// <remarks>
    /// Prophetic Bolt's shape. The look and its taking still have to reach the reader together,
    /// so the line is cut in front of the look rather than at every full stop — anchoring the
    /// idiom to the start of the line refused every card with a sentence in front of it, and that
    /// sentence was usually one the vocabulary had read for years.
    /// </remarks>
    [Fact]
    public void A_look_printed_after_another_instruction_is_still_read()
    {
        var bolt = Card(
            "R17 Prophetic Bolt Test",
            "~ deals 4 damage to any target. Look at the top three cards of your library. Put "
                + "one of those cards into your hand and the rest on the bottom of your library "
                + "in any order.");

        var compiled = CardCompiler.Compile(bolt);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, bolt);

        game.CastSpell(alice, card, [Target.ToPlayer(bob)]);
        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.LookAndTake });

        // The damage happened first and the look is waiting, which is the order printed.
        Assert.Equal(16, game.State.GetPlayer(bob).Life);
        Assert.Equal(3, game.State.Choice!.Options!.Count);

        game.Choose(alice, [game.State.Choice.Options[0].Id]);
        Settle(game);

        Assert.Equal(16, game.State.GetPlayer(bob).Life);
    }

    /// <summary>
    /// A filter the vocabulary cannot read leaves the whole line unread.
    /// </summary>
    /// <remarks>
    /// The failure this family is most exposed to is a reader that widens until it claims lines
    /// it half-understands: every one of these sentences ends in a destination and a rest clause,
    /// so a filter quietly dropped would produce a card that digs five cards deep and offers all
    /// five. Refused instead — which is also why "with power 2 or less" is still unread rather
    /// than read as "creature".
    /// </remarks>
    [Fact]
    public void A_filter_the_vocabulary_cannot_read_refuses_the_whole_look()
    {
        var bugler = Card(
            "R17 Bugler Test",
            "Look at the top four cards of your library. You may reveal a creature card with "
                + "power 2 or less from among them and put it into your hand. Put the rest on "
                + "the bottom of your library in any order.");

        Assert.False(CardCompiler.Compile(bugler).IsComplete);
    }

    // ---- A pump whose size is X, in the four spellings that were left behind ---

    /// <summary>
    /// "{1}{R}: ~ gets +X/+0 until end of turn, where X is the number of artifacts you control."
    /// — Hellkite Igniter, the source's own pump with a counted size.
    /// </summary>
    /// <remarks>
    /// A pump's size is one idea however the sentence names what it pumps, and it was written out
    /// five times: once for a target, once for the source, once for the pronoun, once for a group
    /// and once for an Aura's host. Only the targeted one had ever been widened to admit X, so
    /// "target creature gets +X/+X until end of turn, where X is …" read while the same clause on
    /// any of the other four did not — 72 corpus cards, each of them defining X in the same
    /// breath and none of them able to say how big the pump was.
    /// <para>
    /// Two artifacts and a 2/2, so a bonus of two is distinguishable from a bonus of one, of
    /// three, and from the printed size — the failure the shared size exists to prevent is an X
    /// that quietly comes out as nought, and a 2/2 that stayed a 2/2 would look identical to a
    /// card that never compiled.
    /// </para>
    /// </remarks>
    [Fact]
    public void The_source_pumps_itself_by_a_counted_x()
    {
        var igniter = Card(
            "Variable Self Pump Test",
            "{1}{R}: ~ gets +X/+0 until end of turn, "
                + "where X is the number of artifacts you control.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var compiled = CardCompiler.Compile(igniter);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var dragon = game.Create(alice, igniter, Zone.Battlefield);

        game.Create(
            alice,
            Card("Variable Pump Relic Test", string.Empty, CardType.Artifact),
            Zone.Battlefield);
        game.Create(
            alice,
            Card("Variable Pump Idol Test", string.Empty, CardType.Artifact),
            Zone.Battlefield);

        for (var i = 0; i < 2; i++)
        {
            var land = game.Create(alice, TestCards.BasicLand("Mountain"), Zone.Battlefield);
            game.ActivateAbility(alice, land, "mana");
        }

        game.ActivateAbility(alice, dragon, compiled.Activated.Single().Id);
        Settle(game);

        // Two artifacts, so +2/+0 on a 2/2 — and the toughness is untouched, because the card
        // prints "+X/+0" and reading the same X twice would be a different card.
        Assert.Equal(4, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(dragon)));
        Assert.Equal(2, Characteristics.ToughnessOf(game.State, Pool, game.State.GetObject(dragon)));
    }

    /// <summary>
    /// "Whenever ~ attacks, it gets +X/+0 until end of turn, where X is the number of attacking
    /// creatures you control." — Akroan Hoplite, the pronoun form.
    /// </summary>
    /// <remarks>
    /// The pronoun reader answers the same three questions the printed-size one does — the target
    /// the sentence chose, the object the trigger was about, the source — and none of them is
    /// what was missing: it simply could not read a size that was not a digit.
    /// <para>
    /// Three attackers, so the bonus is three rather than one: a test with a single attacker
    /// cannot tell "the number of attacking creatures" from "one", and a count that came out as
    /// the number of attackers minus the two that were not the Hoplite would look right.
    /// </para>
    /// </remarks>
    [Fact]
    public void The_pronoun_pumps_what_the_trigger_was_about_by_a_counted_x()
    {
        var hoplite = Card(
            "Variable Pronoun Pump Test",
            "Whenever ~ attacks, it gets +X/+0 until end of turn, "
                + "where X is the number of attacking creatures you control.",
            CardType.Creature,
            power: 1,
            toughness: 2);

        var compiled = CardCompiler.Compile(hoplite);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, hoplite, Zone.Battlefield);
        var friend = game.Create(
            alice, TestCards.Creature("Variable Pump Ally Test", 1, 1), Zone.Battlefield);
        var other = game.Create(
            alice, TestCards.Creature("Variable Pump Comrade Test", 1, 1), Zone.Battlefield);

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget>
            {
                [attacker] = AttackTarget.Player(bob),
                [friend] = AttackTarget.Player(bob),
                [other] = AttackTarget.Player(bob),
            });

        Run(game);

        // Three attackers, so a 1/2 swings as a 4/2. The two 1/1s beside it are what makes three
        // the only number this can be. Measured before the damage step, because the bonus is
        // what the Hoplite hits with rather than something the combat leaves behind.
        Assert.Equal(4, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(attacker)));
        Assert.Equal(2, Characteristics.ToughnessOf(game.State, Pool, game.State.GetObject(attacker)));

        Settle(game);
    }

    /// <summary>
    /// "All creatures get -X/-X until end of turn, where X is the number of creature cards in your
    /// graveyard." — Terror Tide, the group form, and a sweeper that has to kill.
    /// </summary>
    /// <remarks>
    /// The minus is what makes this worth its own test rather than another size. A negative size
    /// is a negation of the <em>amount</em>, not a negative X — the fixed part of X is zero, so
    /// anything that negated that instead would leave the board untouched and the card would
    /// compile, resolve and sweep nothing.
    /// <para>
    /// Two creature cards in the graveyard against a 2/2 and a 3/3: minus two is exactly lethal
    /// for one and not the other, so a count one high or one low is visible either way round.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_group_shrinks_by_a_counted_x_and_the_lethal_half_dies()
    {
        var tide = Card(
            "Variable Group Shrink Test",
            "All creatures get -X/-X until end of turn, "
                + "where X is the number of creature cards in your graveyard.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(tide);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();

        game.Create(alice, TestCards.Creature("Variable Shrink Corpse Test", 1, 1), Zone.Graveyard);
        game.Create(alice, TestCards.Creature("Variable Shrink Bones Test", 1, 1), Zone.Graveyard);

        var small = game.Create(
            bob, TestCards.Creature("Variable Shrink Bear Test", 2, 2), Zone.Battlefield);
        var large = game.Create(
            bob, TestCards.Creature("Variable Shrink Ogre Test", 3, 3), Zone.Battlefield);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, tide), targets: null);
        Settle(game);

        Assert.DoesNotContain(small, game.State.Battlefield);
        Assert.Contains(large, game.State.Battlefield);
        Assert.Equal(1, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(large)));
    }

    /// <summary>
    /// "Creatures you control get +X/+X until end of turn, where X is the number of creatures you
    /// control." — the fifth spelling, whose group is named by the verb rather than by a phrase.
    /// </summary>
    [Fact]
    public void Creatures_you_control_grow_by_a_counted_x()
    {
        var anthem = Card(
            "Variable Anthem Test",
            "Creatures you control get +X/+X until end of turn, "
                + "where X is the number of creatures you control.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(anthem);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var mine = game.Create(
            alice, TestCards.Creature("Variable Anthem Bear Test", 2, 2), Zone.Battlefield);
        game.Create(alice, TestCards.Creature("Variable Anthem Cub Test", 1, 1), Zone.Battlefield);
        var theirs = game.Create(
            bob, TestCards.Creature("Variable Anthem Rival Test", 2, 2), Zone.Battlefield);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, anthem), targets: null);
        Settle(game);

        // Two of mine, so +2/+2 — and the opponent's creature is untouched, which is the half of
        // "creatures you control" a group phrase would lose by counting the whole battlefield.
        Assert.Equal(4, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(mine)));
        Assert.Equal(2, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(theirs)));
    }

    // ---- "where X is ~'s power": the card measuring itself (CR 107.3) --------

    /// <summary>
    /// "{T}: Target creature gets +X/+X until end of turn, where X is this creature's power."
    /// — Auriok Bladewarden.
    /// </summary>
    /// <remarks>
    /// The compiler puts a tilde where a card's own name was before any of this runs, so
    /// "this creature's power" arrives as "~'s power" and names the source and nothing else.
    /// That is why it may be read where the pronoun may not: "its" has to be worked out from the
    /// shape of the head, and the head here has a target, which is exactly the case the pronoun
    /// reader refuses because it cannot tell Onward's reading from Dying Wish's. There is nothing
    /// to work out for a card that says its own name.
    /// <para>
    /// The Bladewarden is a 1/4 and the bear a 2/2, so the bonus is one — a number that is
    /// neither the target's power nor the printed size of anything on the board, and would come
    /// out as four if the tilde were read as the source's toughness or as two if it were read as
    /// the target's own.
    /// </para>
    /// </remarks>
    [Fact]
    public void X_can_be_the_sources_own_power_even_when_the_sentence_has_a_target()
    {
        var bladewarden = Card(
            "Variable Self Stat Test",
            "{T}: Target creature gets +X/+X until end of turn, where X is ~'s power.",
            CardType.Creature,
            power: 1,
            toughness: 4);

        var compiled = CardCompiler.Compile(bladewarden);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var warden = game.Create(alice, bladewarden, Zone.Battlefield);
        var bear = game.Create(
            alice, TestCards.Creature("Variable Self Stat Bear Test", 2, 2), Zone.Battlefield);

        PassTo(game, 3, TurnStep.PrecombatMain);
        game.ActivateAbility(
            alice, warden, compiled.Activated.Single().Id, [Target.ToPermanent(bear)]);

        Settle(game);

        Assert.Equal(3, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(bear)));
        Assert.Equal(3, Characteristics.ToughnessOf(game.State, Pool, game.State.GetObject(bear)));

        // And the source, which is not what the sentence pumps, is the size it always was.
        Assert.Equal(1, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(warden)));
    }

    /// <summary>
    /// The same clause read off the source as it is <em>now</em>, not as it was printed.
    /// </summary>
    /// <remarks>
    /// Power is a computed characteristic (CR 613.1), so a counter on the source changes what
    /// "~'s power" comes to. Reading the printed card instead would be the same class of bug as
    /// reading a stored controller: it compiles, it resolves, and it plays a different number.
    /// </remarks>
    [Fact]
    public void The_sources_own_power_is_the_one_it_has_now()
    {
        var beastmaster = Card(
            "Variable Grown Stat Test",
            "{T}: Target creature gets +X/+X until end of turn, where X is ~'s power.",
            CardType.Creature,
            power: 1,
            toughness: 1);

        var compiled = CardCompiler.Compile(beastmaster);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var master = game.Create(alice, beastmaster, Zone.Battlefield);
        var bear = game.Create(
            alice, TestCards.Creature("Variable Grown Bear Test", 2, 2), Zone.Battlefield);

        game.ChangeCounters(master, CounterKinds.PlusOnePlusOne, 2);

        PassTo(game, 3, TurnStep.PrecombatMain);
        game.ActivateAbility(
            alice, master, compiled.Activated.Single().Id, [Target.ToPermanent(bear)]);

        Settle(game);

        // Three, not the printed one: a 1/1 wearing two +1/+1 counters is a 3/3.
        Assert.Equal(5, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(bear)));
    }

    // ---- An X nothing can compute leaves the line unread (CR 107.3) ---------

    /// <summary>
    /// A "where X is" clause naming something the amount vocabulary cannot answer must leave the
    /// line unread, never settle X at nought.
    /// </summary>
    /// <remarks>
    /// This is the failure mode the whole family is arranged around, and it is invisible from the
    /// outside: a spell whose X came out as zero compiles, passes the deck check, goes on the
    /// stack, resolves, and does nothing at all. Nothing is logged, nothing goes unread, and the
    /// coverage number goes <em>up</em>. An unread line is the honest answer — a deck check can
    /// refuse it, and the work queue can count it.
    /// <para>
    /// Both cases here are the head this round taught to carry a variable, so they are exactly
    /// the lines that would be admitted by a reader that stopped checking the clause once the
    /// head could take an X. The first names a fact no vocabulary keeps; the second names a
    /// possessive that was deliberately declined — "that creature" is an object this clause has
    /// no way to find, and a stat read off the wrong permanent is a different card.
    /// </para>
    /// </remarks>
    [Theory]
    [InlineData("All creatures get -X/-X until end of turn, "
        + "where X is the number of unique vowels on that sticker.")]
    [InlineData("All creatures get -X/-X until end of turn, where X is that creature's power.")]
    [InlineData("Creatures you control get +X/+X until end of turn, "
        + "where X is the sacrificed creature's power.")]
    public void An_x_the_vocabulary_cannot_compute_leaves_the_line_unread(string printed)
    {
        var spell = Card("Uncomputable X Test", printed, CardType.Sorcery);
        var compiled = CardCompiler.Compile(spell);

        Assert.False(compiled.IsComplete);
        Assert.Contains(compiled.Unhandled, line => line.Contains("where X is", StringComparison.Ordinal));
    }

    /// <summary>
    /// The pumps that print a number are unchanged by all of the above.
    /// </summary>
    /// <remarks>
    /// The size fragment was widened in six readers at once, which is the sort of change that
    /// takes a family with it silently: a group that admits X also admits anything else the
    /// alternation lets through, and a pump reading one size where the card prints another looks
    /// exactly like a pump that works. Both directions of a printed pump, on two of the readers
    /// that were widened.
    /// </remarks>
    [Fact]
    public void A_printed_pump_size_still_reads_as_the_number_it_prints()
    {
        var anthem = Card(
            "Printed Group Pump Test",
            "Creatures you control get +2/+1 until end of turn.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(anthem);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var bear = game.Create(
            alice, TestCards.Creature("Printed Pump Bear Test", 2, 2), Zone.Battlefield);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, anthem), targets: null);
        Settle(game);

        Assert.Equal(4, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(bear)));
        Assert.Equal(3, Characteristics.ToughnessOf(game.State, Pool, game.State.GetObject(bear)));
    }

    // ---- One group predicate, three readers (CR 613.4c, 109.5) ---------------

    /// <summary>
    /// A permanent of a named kind, for the boards the group tests below are judged on.
    /// </summary>
    /// <remarks>
    /// Every member is a control for the others. A group read one word wider makes a lord buff
    /// the wrong board, and a test that only asks about the permanent the group was meant to
    /// reach cannot see that — coverage would score it as a win. So the boards here are always
    /// mixed, and every assertion says what the group does <em>not</em> reach as well.
    /// </remarks>
    private static CardDefinition GroupMember(
        string name,
        CardType types = CardType.Creature,
        ManaColor? colour = null,
        string[]? supertypes = null,
        string[]? subtypes = null) => new()
        {
            OracleId = "oracle-test-group-" + name.ToLowerInvariant().Replace(' ', '-'),
            Name = "Test Group " + name,
            CardTypes = types,
            Power = types.HasFlag(CardType.Creature) ? 2 : null,
            Toughness = types.HasFlag(CardType.Creature) ? 2 : null,
            Subtypes = subtypes ?? [],
            Supertypes = supertypes ?? [],
            Colors = colour is { } c ? [c] : [],
            ColorIdentity = colour is { } id ? [id] : [],
        };

    /// <summary>Whether this permanent came out of the group the card named.</summary>
    /// <remarks>
    /// Read off the computed characteristics rather than off the compiled definition, because the
    /// definition carries its filter as a closure — putting a board in front of it is the only
    /// honest way to ask what it selects (CR 613.1).
    /// </remarks>
    private static bool HasVigilance(Game game, ObjectId id) =>
        Characteristics.Of(game.State, Pool, game.State.GetObject(id))
            .Keywords.HasFlag(KeywordAbility.Vigilance);

    private static bool WasGrantedAnAbility(Game game, ObjectId id) =>
        Characteristics.Of(game.State, Pool, game.State.GetObject(id)).GrantedActivated.Count > 0;

    /// <summary>
    /// A group with no ownership clause is every permanent that answers it (CR 109.5).
    /// </summary>
    /// <remarks>
    /// Zombie Master's printed wording. "Other Zombies have …" says nothing about who controls
    /// them, and the rules answer that silence with "everybody" — the card is a hive lord, and
    /// one that stops at the table edge is a different card.
    /// <para>
    /// The granted-ability reader defaulted the silence to "you control" while the lord beside it
    /// defaulted the same silence to "anybody", so one printed sentence named two different
    /// boards depending on which reader happened to claim the line. Both now read the clause
    /// through one vocabulary, and this is the wording that tells the two answers apart.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_granted_ability_with_no_ownership_clause_reaches_the_whole_table()
    {
        var master = Card(
            "Test Group Zombie Master",
            "Other Zombies have \"{B}: Regenerate this permanent.\"",
            CardType.Creature,
            2,
            3,
            KeywordAbility.None,
            "Zombie");

        var compiled = CardCompiler.Compile(master);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, master, Zone.Battlefield);

        var mine = game.Create(
            alice, GroupMember("Zed", subtypes: ["Zombie"]), Zone.Battlefield);
        var theirs = game.Create(
            bob, GroupMember("Zeb", subtypes: ["Zombie"]), Zone.Battlefield);
        var bystander = game.Create(
            bob, GroupMember("Goblin Bystander", subtypes: ["Goblin"]), Zone.Battlefield);
        Settle(game);

        Assert.True(WasGrantedAnAbility(game, mine));
        Assert.True(WasGrantedAnAbility(game, theirs));

        // The control: the group is a tribe, not "every creature on the battlefield".
        Assert.False(WasGrantedAnAbility(game, bystander));
    }

    /// <summary>
    /// The same sentence with "you control" printed on it stops at the table edge.
    /// </summary>
    /// <remarks>
    /// The neighbouring wording, and the reason the test above means anything: a reader that had
    /// simply stopped asking about ownership would pass that one and fail this.
    /// </remarks>
    [Fact]
    public void The_same_granted_ability_with_you_control_reaches_only_yours()
    {
        var marshal = Card(
            "Test Group Zombie Marshal",
            "Other Zombies you control have \"{B}: Regenerate this permanent.\"",
            CardType.Creature,
            2,
            3,
            KeywordAbility.None,
            "Zombie");

        var compiled = CardCompiler.Compile(marshal);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var lord = game.Create(alice, marshal, Zone.Battlefield);

        var mine = game.Create(
            alice, GroupMember("Zod", subtypes: ["Zombie"]), Zone.Battlefield);
        var theirs = game.Create(
            bob, GroupMember("Zug", subtypes: ["Zombie"]), Zone.Battlefield);
        Settle(game);

        Assert.True(WasGrantedAnAbility(game, mine));
        Assert.False(WasGrantedAnAbility(game, theirs));

        // "Other" is the other half of the subject, and a lord that grants to itself is a
        // different card.
        Assert.False(WasGrantedAnAbility(game, lord));
    }

    /// <summary>
    /// "Each" is how a sentence is written, not whose permanents it is about (CR 109.5).
    /// </summary>
    /// <remarks>
    /// Titan of Eternal Fire's printed wording. The granted-ability reader read "each" and "all"
    /// as "everybody" and let that <em>override</em> an ownership clause the pattern had already
    /// matched, so this card handed a repeatable ping to every Human at the table — the
    /// opponent's included — with the words "you control" printed on it.
    /// <para>
    /// Nothing could see it. The line compiles, the card reads as complete, and the only place
    /// the mistake shows is a board with a Human on the other side of it.
    /// </para>
    /// </remarks>
    [Fact]
    public void Each_does_not_override_a_printed_ownership_clause()
    {
        var titan = Card(
            "Test Group Titan",
            "Each Human creature you control has \"{R}, {T}: This creature deals 1 damage to any"
                + " target.\"",
            CardType.Creature,
            5,
            5,
            KeywordAbility.None,
            "Giant");

        var compiled = CardCompiler.Compile(titan);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, titan, Zone.Battlefield);

        var mine = game.Create(
            alice, GroupMember("Villager", subtypes: ["Human"]), Zone.Battlefield);
        var theirs = game.Create(
            bob, GroupMember("Refugee", subtypes: ["Human"]), Zone.Battlefield);
        Settle(game);

        Assert.True(WasGrantedAnAbility(game, mine));
        Assert.False(WasGrantedAnAbility(game, theirs));
    }

    /// <summary>
    /// "Land creatures" is one noun, not a creature type called "Land" (CR 205.3m).
    /// </summary>
    /// <remarks>
    /// Both Embodiments read as complete cards for as long as they have existed and gave their
    /// keyword to nobody: the shared noun table knew "artifact creature" and "enchantment
    /// creature" and not "land creature", so the group reader stopped at "creature" and took the
    /// word in front of it for a tribe. No card has the creature type "Land".
    /// <para>
    /// It is the failure this family is prone to and the one coverage scores as a win — a line
    /// that reads, compiles, and grants nothing at all. The revived invariant found it; nothing
    /// else in the suite could.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_land_creature_is_a_noun_the_group_reader_knows()
    {
        var embodiment = Card(
            "Test Group Embodiment",
            "Land creatures you control have vigilance.",
            CardType.Creature,
            3,
            3,
            KeywordAbility.None,
            "Elemental");

        var compiled = CardCompiler.Compile(embodiment);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, embodiment, Zone.Battlefield);

        var animated = game.Create(
            alice, GroupMember("Dryad Arbor", CardType.Land | CardType.Creature), Zone.Battlefield);
        var plainLand = game.Create(alice, GroupMember("Waste", CardType.Land), Zone.Battlefield);
        var plainCreature = game.Create(alice, GroupMember("Ox"), Zone.Battlefield);
        var theirs = game.Create(
            bob, GroupMember("Their Arbor", CardType.Land | CardType.Creature), Zone.Battlefield);
        Settle(game);

        Assert.True(HasVigilance(game, animated));

        // Both halves of the noun are load-bearing, and so is the ownership clause.
        Assert.False(HasVigilance(game, plainLand));
        Assert.False(HasVigilance(game, plainCreature));
        Assert.False(HasVigilance(game, theirs));
    }

    /// <summary>
    /// A tribe spelled the same in both numbers is still a tribe (CR 205.3m).
    /// </summary>
    /// <remarks>
    /// Extricator of Sin's printed wording. The group reader proves a capitalised word is a
    /// creature type rather than an adjective by requiring the plural, and for Eldrazi, Merfolk,
    /// Kithkin, Treefolk, Aetherborn and Fish the plural is the singular — so the proof failed on
    /// six real tribes, one of which had been carved out by name.
    /// <para>
    /// The convergence is what surfaced it: the granted-ability reader had no plural test at all,
    /// so "Eldrazi you control have "{T}: Add one mana of any color"" was read by one reader and
    /// refused by the other. Pointing both at the same reader turned the disagreement into a
    /// failure instead of a silence.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_tribe_spelled_the_same_in_both_numbers_is_still_a_tribe()
    {
        var extricator = Card(
            "Test Group Extricator",
            "Eldrazi you control have vigilance.",
            CardType.Creature,
            2,
            1,
            KeywordAbility.None,
            "Human");

        var compiled = CardCompiler.Compile(extricator);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, extricator, Zone.Battlefield);

        var mine = game.Create(
            alice, GroupMember("Horror", subtypes: ["Eldrazi"]), Zone.Battlefield);
        var other = game.Create(alice, GroupMember("Ox Two"), Zone.Battlefield);
        var theirs = game.Create(
            bob, GroupMember("Titan Spawn", subtypes: ["Eldrazi"]), Zone.Battlefield);
        Settle(game);

        Assert.True(HasVigilance(game, mine));
        Assert.False(HasVigilance(game, other));
        Assert.False(HasVigilance(game, theirs));
    }

    /// <summary>
    /// "Commanders" names a designation, not a creature type (CR 903.3).
    /// </summary>
    /// <remarks>
    /// Three cards print this and all three read as complete and gave their keyword to nobody:
    /// the bare-noun arm of the group reader never asked the adjective vocabulary at all, so
    /// "Commanders" became the creature type "Commander", which no card has.
    /// <para>
    /// The designation belongs to the card's <em>owner</em> — a commander stolen by an opponent
    /// is still its owner's commander — while "you control" is a separate question the ownership
    /// clause answers. The granted-ability reader had been answering exactly this question all
    /// along for the Backgrounds; the vocabulary beside it said it could not be asked.
    /// </para>
    /// </remarks>
    [Fact]
    public void Commanders_names_the_designation_rather_than_a_creature_type()
    {
        var guardian = Card(
            "Test Group Guardian",
            "Commanders you control have vigilance.",
            CardType.Artifact);

        var compiled = CardCompiler.Compile(guardian);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var commander = GroupMember(
            "Warchief", CardType.Creature, null, ["Legendary"], ["Orc"]);

        var alice = Guid.Parse("11111111-1111-1111-1111-111111111111");
        var bob = Guid.Parse("22222222-2222-2222-2222-222222222222");

        var game = Game.Start(
            Guid.NewGuid(),
            [
                new PlayerSetup(alice, "Alice", 40, [.. TestCards.Deck(40, "GroupA"), commander])
                {
                    CommanderOracleId = commander.OracleId,
                },
                new PlayerSetup(bob, "Bob", 40, TestCards.Deck(40, "GroupB")),
            ],
            new GameRandom(7),
            startingPlayerId: alice,
            abilities: Pool);

        game.BeginPlay(withMulligans: false);
        TestCards.PassToStep(game, TurnStep.PrecombatMain);

        game.Create(alice, guardian, Zone.Battlefield);

        var hers = game.Create(alice, commander, Zone.Battlefield);
        var ordinary = game.Create(
            alice, GroupMember("Squire", CardType.Creature, null, ["Legendary"]), Zone.Battlefield);
        Settle(game);

        Assert.True(HasVigilance(game, hers));

        // The designation is the whole question: a creature nobody named as their commander is
        // not one of these, however legendary it is.
        Assert.False(HasVigilance(game, ordinary));
    }

    /// <summary>
    /// A word the adjective vocabulary recognises and cannot answer leaves the line unread.
    /// </summary>
    /// <remarks>
    /// The control for every test above, and what keeps them honest. "Modified" wants counters,
    /// Auras and Equipment (CR 700.9) and this filter has no way to ask; the honest outcome is an
    /// unread line, which a deck check refuses and somebody notices. Reading it as a tribe
    /// instead builds a lord for the creature type "Modified", which reads as complete and does
    /// nothing — and that is what the granted-ability reader used to do with it.
    /// <para>
    /// The last case is a group nobody can describe rather than one nobody can answer: "creatures
    /// and enchantments" is two nouns, and a reader that guessed at one of them would be reading
    /// half a card.
    /// </para>
    /// </remarks>
    [Theory]
    [InlineData("Modified creatures you control have vigilance.")]
    [InlineData("Modified creatures you control have \"{T}: Add {G}.\"")]
    [InlineData("Enchanted creatures you control have \"{T}: Add {G}.\"")]
    [InlineData("Creatures and enchantments you control have \"{T}: Add {G}.\"")]
    public void A_group_the_shared_reader_cannot_describe_is_left_unread(string line)
    {
        var card = Card("Test Group Refusal " + line.Length + line[..12], line, CardType.Enchantment);

        var compiled = CardCompiler.Compile(card);

        Assert.False(compiled.IsComplete);
        Assert.Contains(line, compiled.Unhandled);
    }

    /// <summary>
    /// The lord and the granted-ability reader pick out exactly the same permanents.
    /// </summary>
    /// <remarks>
    /// The claim the extraction is for. Two readers worked the same noun phrase out
    /// independently — a different tribe test, a different ownership default and a different
    /// reading of the scope word — and every defect this family has produced was one copy being
    /// right and the other being wrong about the same printed words.
    /// <para>
    /// So this is a comparison rather than a list of expectations: for each group phrase, one
    /// board is shown "&lt;group&gt; have vigilance" and the same board is shown
    /// "&lt;group&gt; have "{T}: Add {G}"", and the permanents each reaches must be the same set.
    /// A reader that drifts fails here without anybody having to guess in advance which board
    /// would show it.
    /// </para>
    /// </remarks>
    [Theory]
    [InlineData("Creatures you control")]
    [InlineData("Creatures")]
    [InlineData("Other creatures you control")]
    [InlineData("Creatures your opponents control")]
    [InlineData("All creatures")]
    [InlineData("Goblins you control")]
    [InlineData("Goblins")]
    [InlineData("Goblin creatures you control")]
    [InlineData("Artifacts you control")]
    [InlineData("Lands you control")]
    [InlineData("Permanents you control")]
    [InlineData("Creature tokens you control")]
    [InlineData("Legendary creatures you control")]
    [InlineData("White creatures you control")]
    [InlineData("Nontoken creatures you control")]
    [InlineData("Land creatures you control")]
    [InlineData("Eldrazi you control")]
    public void The_lord_and_the_granted_ability_reader_read_the_same_group(string group)
    {
        var keyword = Card(
            "Test Group Keyword " + group,
            group + " have vigilance.",
            CardType.Enchantment);

        var quoted = Card(
            "Test Group Quoted " + group,
            group + " have \"{T}: Add {G}.\"",
            CardType.Enchantment);

        foreach (var half in new[] { keyword, quoted })
        {
            var read = CardCompiler.Compile(half);
            Assert.True(read.IsComplete, half.Name + ": " + string.Join(" | ", read.Unhandled));
        }

        var byKeyword = GroupBoard(keyword);
        var byGrant = GroupBoard(quoted);

        Assert.Equal(byKeyword, byGrant);

        // A group that reached nothing at all would pass the comparison above by vacuity, which
        // is the one way this test could be green while both readers were broken.
        Assert.NotEmpty(byKeyword);
    }

    /// <summary>
    /// Plays one group static over a mixed board and reports which permanents it reached.
    /// </summary>
    /// <remarks>
    /// The board is deliberately wider than any one group needs: both seats, four card types, two
    /// tribes, a token, a legendary, a colour and a land creature. A group read one word wider
    /// than printed shows up as an extra label here, and nowhere else.
    /// </remarks>
    private static IReadOnlyList<string> GroupBoard(CardDefinition lord)
    {
        var (game, alice, bob) = InMainPhase();
        var source = game.Create(alice, lord, Zone.Battlefield);

        var board = new List<(string Label, ObjectId Id)>();

        foreach (var (side, who) in new[] { ("mine", alice), ("theirs", bob) })
        {
            void Put(string what, CardDefinition card) =>
                board.Add(($"{side}-{what}", game.Create(who, card, Zone.Battlefield)));

            Put("creature", GroupMember($"{side} Creature"));
            Put("goblin", GroupMember($"{side} Goblin", subtypes: ["Goblin"]));
            Put("eldrazi", GroupMember($"{side} Eldrazi", subtypes: ["Eldrazi"]));
            Put("artifact", GroupMember($"{side} Artifact", CardType.Artifact));
            Put("land", GroupMember($"{side} Land", CardType.Land));
            Put(
                "landcreature",
                GroupMember($"{side} Land Creature", CardType.Land | CardType.Creature));
            Put("enchantment", GroupMember($"{side} Enchantment", CardType.Enchantment));
            Put("token", GroupMember($"{side} Token", CardType.Creature | CardType.Token));
            Put(
                "legendary",
                GroupMember($"{side} Legend", CardType.Creature, null, ["Legendary"]));
            Put("white", GroupMember($"{side} White", CardType.Creature, ManaColor.White));
        }

        board.Add(("source", source));
        Settle(game);

        return
        [
            .. board
                .Where(entry =>
                    HasVigilance(game, entry.Id) || WasGrantedAnAbility(game, entry.Id))
                .Select(entry => entry.Label)
                .Order(StringComparer.Ordinal),
        ];
    }

    /// <summary>
    /// The reader that switches a group's abilities off reads the same group as the lord.
    /// </summary>
    /// <remarks>
    /// The third copy. It has no scope word of its own — nothing prints "Activated abilities of
    /// other artifacts" — but the noun and the ownership clause are the same vocabulary, and this
    /// is where a divergence in it would land: a Null Rod that silenced the wrong half of the
    /// board looks exactly like one that works, because the permanent it wrongly silenced simply
    /// offers one button fewer.
    /// </remarks>
    [Fact]
    public void The_abilities_off_reader_reads_the_same_group_as_the_lord()
    {
        var rod = Card(
            "Test Group Null Rod",
            "Activated abilities of artifacts your opponents control can't be activated.",
            CardType.Artifact);

        var compiled = CardCompiler.Compile(rod);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, rod, Zone.Battlefield);

        var theirs = game.Create(bob, GroupMember("Sol Ring", CardType.Artifact), Zone.Battlefield);
        var mine = game.Create(alice, GroupMember("My Ring", CardType.Artifact), Zone.Battlefield);
        var theirCreature = game.Create(bob, GroupMember("Their Bear"), Zone.Battlefield);
        Settle(game);

        Assert.True(
            Characteristics.Of(game.State, Pool, game.State.GetObject(theirs))
                .AbilitiesCantBeActivated);

        // The ownership clause and the noun are both doing work, and a restriction read one word
        // wider than printed is worse than an unread line.
        Assert.False(
            Characteristics.Of(game.State, Pool, game.State.GetObject(mine))
                .AbilitiesCantBeActivated);
        Assert.False(
            Characteristics.Of(game.State, Pool, game.State.GetObject(theirCreature))
                .AbilitiesCantBeActivated);
    }

    // ---- Land types and the mana they carry (CR 305.6, 305.7) ----------------

    /// <summary>An Aura that sets what land type the land it is on is (CR 205.1a).</summary>
    private static CardDefinition Retyping(string name, string landType) => Card(
        name,
        "Enchant land\nEnchanted land is " + (landType == "Island" ? "an " : "a ") + landType + ".",
        CardType.Enchantment,
        subtypes: "Aura");

    /// <summary>Every mana ability a permanent has right now, as the board would be told.</summary>
    private static IReadOnlyList<ActivatedAbilityDefinition> ManaAbilitiesOf(Game game, ObjectId id) =>
        [.. Game.ActivatedAbilitiesOf(game.State, Pool, game.State.GetObject(id))
            .Where(a => a.IsManaAbility)];

    [Fact]
    public void A_mountain_turned_into_an_island_stops_tapping_for_red()
    {
        // The defect this whole section exists for. CR 305.6 gives a land with a basic land type
        // the matching mana ability "even if the text box doesn't actually contain that text",
        // and the compiler used to build it from the *printed* subtypes - so it was a property of
        // the card, and no effect could take it off. A Mountain under a Spreading Seas kept
        // "{T}: Add {R}" for as long as the game lasted.
        var (game, alice, _) = InMainPhase();
        var land = game.Create(alice, TestCards.BasicLand("Mountain"), Zone.Battlefield);

        // Before: a Mountain, and red mana arrives.
        game.ActivateAbility(alice, land, "mana");
        Assert.Equal(1, game.State.GetPlayer(alice).ManaPool[ManaColor.Red]);

        var seas = Retyping("Spreading Test", "Island");
        var compiled = CardCompiler.Compile(seas);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var card = TestCards.PutInHand(game, alice, seas);
        game.CastSpell(alice, card, [Target.ToPermanent(land)]);
        Settle(game);

        // Round to Alice's own untap step, so the land is untapped and the pool has emptied
        // (CR 500.4) rather than still holding the red from before.
        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber == 3 && game.State.CurrentStep == TurnStep.PrecombatMain);

        // After: the same permanent, the same ability id, and blue mana.
        game.ActivateAbility(alice, land, "mana");
        Assert.Equal(1, game.State.GetPlayer(alice).ManaPool[ManaColor.Blue]);
        Assert.Equal(0, game.State.GetPlayer(alice).ManaPool[ManaColor.Red]);
    }

    [Theory]
    [InlineData("Plains", ManaColor.White)]
    [InlineData("Island", ManaColor.Blue)]
    [InlineData("Swamp", ManaColor.Black)]
    [InlineData("Mountain", ManaColor.Red)]
    [InlineData("Forest", ManaColor.Green)]
    public void Each_basic_land_type_carries_its_own_mana_wherever_it_came_from(
        string landType, ManaColor colour)
    {
        // CR 305.6 names five pairings and the table that holds them is now in the layers rather
        // than in the compiler. All five are played rather than compared against a list, because
        // a list checked against a list is two copies of the same possible mistake.
        var (game, alice, _) = InMainPhase();
        var plain = Card("Colourless Land Test " + landType, "{T}: Add {C}.", CardType.Land);
        var land = game.Create(alice, plain, Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, Retyping("Retype Test " + landType, landType));
        game.CastSpell(alice, card, [Target.ToPermanent(land)]);
        Settle(game);

        var mana = ManaAbilitiesOf(game, land);
        Assert.Single(mana);

        game.ActivateAbility(alice, land, mana[0].Id);
        Assert.Equal(1, game.State.GetPlayer(alice).ManaPool[colour]);
    }

    [Fact]
    public void A_land_set_to_a_basic_type_loses_the_abilities_its_own_text_gave_it()
    {
        // CR 305.7: "It loses all abilities generated from its rules text, its old land types,
        // and any copiable effects affecting that land, and it gains the appropriate mana ability
        // for each new basic land type." Without this half, a Spreading Seas leaves an Ancient
        // Tomb tapping for {C}{C} *and* {U} - a strictly better board than the printed one, and
        // one nothing downstream can see, because the type line is right.
        var tomb = Card("Ancient Test Tomb", "{T}: Add {C}{C}.", CardType.Land);

        var (game, alice, _) = InMainPhase();
        var land = game.Create(alice, tomb, Zone.Battlefield);

        Assert.Equal("{T}: Add {C}{C}.", Assert.Single(ManaAbilitiesOf(game, land)).Text);

        // Written out rather than built by the helper, because MechanicCoverageTests reads the
        // card lines out of this file's own source: a sentence assembled from three fragments is
        // a shape no test appears to play.
        var seas = Card(
            "Seas Test",
            "Enchant land\nEnchanted land is an Island.",
            CardType.Enchantment,
            subtypes: "Aura");

        var card = TestCards.PutInHand(game, alice, seas);
        game.CastSpell(alice, card, [Target.ToPermanent(land)]);
        Settle(game);

        var after = Assert.Single(ManaAbilitiesOf(game, land));
        Assert.Equal("{T}: Add {U}.", after.Text);

        game.ActivateAbility(alice, land, after.Id);
        Assert.Equal(1, game.State.GetPlayer(alice).ManaPool[ManaColor.Blue]);
        Assert.Equal(0, game.State.GetPlayer(alice).ManaPool.Colorless);
    }

    [Fact]
    public void A_land_that_gains_a_basic_type_keeps_its_own_text_and_its_own_types()
    {
        // CR 305.7's last sentence, and the whole of the difference between Urborg and Blood
        // Moon: "If a land gains one or more land types in addition to its own, it keeps its land
        // types and rules text, and it gains the new land types and mana abilities." One clause
        // in the printed sentence decides which of the two rules applies, so the compiler emits
        // two different layer-4 effects for it.
        var urborg = Card(
            "Urborg Test",
            "Each land is a Swamp in addition to its other land types.",
            CardType.Land);

        var compiled = CardCompiler.Compile(urborg);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        var second = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.Create(alice, urborg, Zone.Battlefield);
        Settle(game);

        // Two abilities and one {T} between them (CR 305.6 grants an ability per type, not a
        // second tap), so the two colours are taken off two lands.
        var mana = ManaAbilitiesOf(game, forest);
        Assert.Equal(2, mana.Count);

        game.ActivateAbility(alice, forest, mana.Single(a => a.Text == "{T}: Add {G}.").Id);
        game.ActivateAbility(
            alice, second, ManaAbilitiesOf(game, second).Single(a => a.Text == "{T}: Add {B}.").Id);

        Assert.Equal(1, game.State.GetPlayer(alice).ManaPool[ManaColor.Green]);
        Assert.Equal(1, game.State.GetPlayer(alice).ManaPool[ManaColor.Black]);
    }

    [Fact]
    public void Nonbasic_lands_are_mountains_and_a_basic_land_is_not_one_of_them()
    {
        // Blood Moon, whole. Two rules meet on it: CR 305.7 takes the utility land's own text
        // away and gives it red mana, and CR 305.8 keeps the basics out of the group - "any land
        // that doesn't have this supertype is a nonbasic land, even if it has a basic land type".
        // A reader that asked about subtypes instead would have turned every Forest into a
        // Mountain as well.
        var moon = Card("Moon Test", "Nonbasic lands are Mountains.", CardType.Enchantment);

        var compiled = CardCompiler.Compile(moon);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var utility = game.Create(
            alice, Card("Utility Test Land", "{T}: Add {C}{C}.", CardType.Land), Zone.Battlefield);
        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);

        game.Create(alice, moon, Zone.Battlefield);
        Settle(game);

        var retyped = Assert.Single(ManaAbilitiesOf(game, utility));
        Assert.Equal("{T}: Add {R}.", retyped.Text);
        game.ActivateAbility(alice, utility, retyped.Id);

        var basic = Assert.Single(ManaAbilitiesOf(game, forest));
        Assert.Equal("{T}: Add {G}.", basic.Text);
        game.ActivateAbility(alice, forest, basic.Id);

        Assert.Equal(1, game.State.GetPlayer(alice).ManaPool[ManaColor.Red]);
        Assert.Equal(1, game.State.GetPlayer(alice).ManaPool[ManaColor.Green]);
        Assert.Equal(0, game.State.GetPlayer(alice).ManaPool.Colorless);
    }

    [Fact]
    public void Every_basic_land_type_at_once_is_five_mana_abilities()
    {
        // Prismatic Omen and Dryad of the Ilysian Grove. "Every basic land type" is a way of
        // naming five subtypes rather than a sixth thing to be, and because the sentence says "in
        // addition" the land keeps whatever it could already do.
        var omen = Card(
            "Omen Test",
            "Lands you control are every basic land type in addition to their other types.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(omen);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var mine = game.Create(
            alice, Card("Omen Land Test", "{T}: Add {C}.", CardType.Land), Zone.Battlefield);
        var theirs = game.Create(bob, TestCards.BasicLand("Island"), Zone.Battlefield);

        game.Create(alice, omen, Zone.Battlefield);
        Settle(game);

        Assert.Equal(6, ManaAbilitiesOf(game, mine).Count);

        foreach (var ability in ManaAbilitiesOf(game, mine).Where(a => a.RequiresTap).Take(1))
            game.ActivateAbility(alice, mine, ability.Id);

        // "You control" is doing work: the opponent's Island is not one of these lands.
        Assert.Single(ManaAbilitiesOf(game, theirs));
    }

    [Fact]
    public void A_land_retyped_until_end_of_turn_taps_for_its_old_colour_afterwards()
    {
        // Tidal Warrior. The effect is created with the turn number on it and comes off in the
        // cleanup step, which is why the compiler refuses the same sentence printed without a
        // duration: an indefinite retyping read as this one would quietly undo itself.
        var warrior = Card(
            "Tidal Test",
            "{T}: Target land becomes an Island until end of turn.",
            CardType.Creature,
            1,
            1,

            // Haste only so the ability can be used the turn it arrives (CR 302.6); the template
            // under test is the sentence, and the keyword is not part of it.
            KeywordAbility.Haste);

        var compiled = CardCompiler.Compile(warrior);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var shaper = game.Create(alice, warrior, Zone.Battlefield);
        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);

        game.ActivateAbility(alice, shaper, "a", [Target.ToPermanent(forest)]);
        Settle(game);

        var island = Assert.Single(ManaAbilitiesOf(game, forest));
        Assert.Equal("{T}: Add {U}.", island.Text);
        game.ActivateAbility(alice, forest, island.Id);
        Assert.Equal(1, game.State.GetPlayer(alice).ManaPool[ManaColor.Blue]);

        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber == 3 && game.State.CurrentStep == TurnStep.PrecombatMain);

        var back = Assert.Single(ManaAbilitiesOf(game, forest));
        Assert.Equal("{T}: Add {G}.", back.Text);
        game.ActivateAbility(alice, forest, back.Id);
        Assert.Equal(1, game.State.GetPlayer(alice).ManaPool[ManaColor.Green]);
        Assert.Equal(0, game.State.GetPlayer(alice).ManaPool[ManaColor.Blue]);
    }

    [Fact]
    public void A_lands_printed_mana_ability_and_its_intrinsic_one_do_not_share_an_id()
    {
        // Murmuring Bosk: a Forest that also prints a mana ability of its own. The compiler
        // numbers a printed mana ability "mana", "mana1" and so on from zero and knows nothing
        // about CR 305.6, so the intrinsic one has to take an id the card has not used. The cost
        // of getting this wrong is not a duplicate in a list - an ability goes on the stack and
        // into the log as an id, and a collision resolves the wrong one.
        var bosk = Card(
            "Bosk Test", "{T}: Add {W}.", CardType.Land, subtypes: ["Forest"]);

        var (game, alice, _) = InMainPhase();
        var land = game.Create(alice, bosk, Zone.Battlefield);

        var mana = ManaAbilitiesOf(game, land);
        Assert.Equal(2, mana.Count);
        Assert.Equal(2, mana.Select(a => a.Id).Distinct(StringComparer.Ordinal).Count());

        // Both are reachable by the id the board would send, and each makes its own colour.
        var white = mana.Single(a => a.Text == "{T}: Add {W}.");
        var green = mana.Single(a => a.Text == "{T}: Add {G}.");

        game.ActivateAbility(alice, land, white.Id);
        Assert.Equal(1, game.State.GetPlayer(alice).ManaPool[ManaColor.White]);
        Assert.Equal(0, game.State.GetPlayer(alice).ManaPool[ManaColor.Green]);
        Assert.NotEqual(white.Id, green.Id);
    }

    [Fact]
    public void Landwalk_is_turned_on_by_a_land_type_an_effect_granted()
    {
        // The check that had never been exercised end to end. CombatRules reads the *computed*
        // land types of what the defender controls, which is the right reading of CR 702.14b -
        // but until a card could change a land's type there was no way to reach the half of it
        // that is not the printed subtype, so the rule was correct and untested.
        var walker = Card(
            "Island Walker Test", "Islandwalk", CardType.Creature, 2, 2,
            keywords: KeywordAbility.Islandwalk);

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, walker, Zone.Battlefield);
        var blocker = game.Create(bob, TestCards.Creature("Walk Blocker Test", 2, 2), Zone.Battlefield);
        var theirLand = game.Create(bob, TestCards.BasicLand("Mountain"), Zone.Battlefield);

        // A Mountain is not an Island, so the block is legal.
        Assert.Null(CombatRules.CannotBlock(
            game.State, Pool, game.State.GetObject(blocker), game.State.GetObject(attacker), bob));

        var card = TestCards.PutInHand(game, alice, Retyping("Walk Seas Test", "Island"));
        game.CastSpell(alice, card, [Target.ToPermanent(theirLand)]);
        Settle(game);

        Assert.NotNull(CombatRules.CannotBlock(
            game.State, Pool, game.State.GetObject(blocker), game.State.GetObject(attacker), bob));
    }

    [Fact]
    public void Two_lands_that_retype_each_other_settle_rather_than_recurse()
    {
        // CR 613.8's hazard, written as the test that would hang if the predicate were wrong.
        // Both of these are lands, so each is a member of the other's group *and* of its own, and
        // one of them names an ownership clause - which is the filter that has to ask a question
        // about a permanent that is not the one being computed. It asks it through the
        // control-only reader; a filter that asked for the source's full characteristics instead
        // would compute each land from inside the other without bottom.
        var swamps = Card(
            "Swampbenders Test",
            "Lands you control are Swamps in addition to their other types.",
            CardType.Land);

        var forests = Card(
            "Yavimaya Test",
            "Each land is a Forest in addition to its other land types.",
            CardType.Land);

        Assert.True(CardCompiler.Compile(swamps).IsComplete);
        Assert.True(CardCompiler.Compile(forests).IsComplete);

        var (game, alice, bob) = InMainPhase();
        var mine = game.Create(alice, swamps, Zone.Battlefield);
        var alsoMine = game.Create(alice, forests, Zone.Battlefield);
        var theirs = game.Create(bob, TestCards.BasicLand("Island"), Zone.Battlefield);
        Settle(game);

        // Each land is both of the things the other says, and answers in finite time.
        foreach (var land in new[] { mine, alsoMine })
        {
            var texts = ManaAbilitiesOf(game, land).Select(a => a.Text).ToList();
            Assert.Contains("{T}: Add {B}.", texts, StringComparer.Ordinal);
            Assert.Contains("{T}: Add {G}.", texts, StringComparer.Ordinal);
        }

        // Bob's Island is a Forest - "each land" has no ownership clause - and is not a Swamp,
        // because the other sentence does.
        var acrossTheTable = ManaAbilitiesOf(game, theirs).Select(a => a.Text).ToList();
        Assert.Contains("{T}: Add {U}.", acrossTheTable, StringComparer.Ordinal);
        Assert.Contains("{T}: Add {G}.", acrossTheTable, StringComparer.Ordinal);
        Assert.DoesNotContain("{T}: Add {B}.", acrossTheTable, StringComparer.Ordinal);
    }

