    /// <summary>A card with two castable halves, printed the way the real ones are.</summary>
    private static CardDefinition Adventurer() => new()
    {
        OracleId = "oracle-test-guidemother",
        Name = "Test Guidemother",
        ManaCostRaw = "{1}{W}",
        OracleText = "Flying",
        CardTypes = CardType.Creature,
        Subtypes = ["Faerie"],
        Power = 1,
        Toughness = 1,
        Keywords = KeywordAbility.Flying,
        Faces =
        [
            new CardFace
            {
                Name = "Test Guidemother",
                ManaCostRaw = "{1}{W}",
                TypeLine = "Creature \u2014 Faerie",
                CardTypes = CardType.Creature,
                Subtypes = ["Faerie"],
                OracleText = "Flying",
                Power = 1,
                Toughness = 1,
                Keywords = KeywordAbility.Flying,
            },
            new CardFace
            {
                Name = "Test Gift of the Fae",
                ManaCostRaw = "{W}",
                TypeLine = "Sorcery \u2014 Adventure",
                CardTypes = CardType.Sorcery,
                Subtypes = ["Adventure"],
                OracleText = "You gain 3 life.",
            },
        ],
    };

    /// <summary>
    /// An Adventure resolves as itself, is exiled rather than binned, and the creature can then
    /// be cast from exile (CR 715.3b, 715.3d).
    /// </summary>
    /// <remarks>
    /// This is the shape of card the coverage number is least honest about. Both halves of an
    /// adventurer card read cleanly - they are an ordinary sorcery and an ordinary creature - so
    /// all 170 of them counted as understood while the engine had no way to cast the Adventure at
    /// all. Reading a card and being able to play it are different claims, and only one of them
    /// was being made.
    /// <para>
    /// The life total is what says the <em>Adventure</em> resolved rather than the creature: the
    /// card underneath is a 1/1 Faerie with flying and nothing else, so a resolution that
    /// consulted the card would have put a creature on the battlefield and gained nobody
    /// anything.
    /// </para>
    /// </remarks>
    [Fact]
    public void An_Adventure_resolves_as_itself_and_leaves_the_creature_castable()
    {
        var faerie = Adventurer();

        var compiled = CardCompiler.Compile(faerie);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.NotNull(compiled.Adventure);

        var (game, alice, _) = InMainPhase();
        var before = game.State.GetPlayer(alice).Life;
        var card = TestCards.PutInHand(game, alice, faerie);

        for (var i = 0; i < 4; i++)
            game.AddMana(alice, ManaColor.White);

        game.CastSpell(alice, card, [], asAdventure: true);
        Settle(game);

        // The Adventure did what the Adventure says.
        Assert.Equal(before + 3, game.State.GetPlayer(alice).Life);

        // And it is in exile rather than in the graveyard (CR 715.3d).
        var exiled = Assert.Single(
            game.State.Exile,
            id => game.State.GetObject(id).Card.Name == "Test Guidemother");

        Assert.True(game.State.GetObject(exiled).OnAdventure);
        Assert.DoesNotContain(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Test Guidemother");

        // The creature can be cast from there, and only as the creature.
        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, exiled, [], asAdventure: true));

        game.CastSpell(alice, exiled, []);
        Settle(game);

        Assert.Contains(
            game.State.Battlefield,
            id => game.State.GetObject(id).Card.Name == "Test Guidemother");
    }
    // ---- Combat and board keywords (CR 702) ----------------------------------

    /// <summary>
    /// Ravenous is X counters, and a card when X was big (CR 702.156a).
    /// </summary>
    /// <remarks>
    /// The two halves read the same number and the number is not on the board anywhere: X was
    /// announced as the spell was cast (CR 601.2b) and the spell stopped existing when it
    /// resolved (CR 400.7). So this is the test that says the announced X survives exactly the
    /// one move that turns a spell into a permanent, which is what CR 607.2 asks of a linked
    /// ability and what the intervening-if's second check (CR 603.4) has to read.
    /// </remarks>
    [Fact]
    public void Ravenous_enters_with_X_counters_and_draws_when_X_was_five_or_more()
    {
        var aberrant = new CardDefinition
        {
            OracleId = "oracle-ravenous-big-test",
            Name = "Ravenous Big Test",
            OracleText = "Ravenous",
            CardTypes = CardType.Creature,
            Power = 0,
            Toughness = 0,
            ManaCostRaw = "{X}{B}",
        };

        var compiled = CardCompiler.Compile(aberrant);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, aberrant);

        foreach (var _ in Enumerable.Range(0, 6))
        {
            var land = game.Create(alice, TestCards.BasicLand("Swamp"), Zone.Battlefield);
            game.ActivateAbility(alice, land, "mana");
        }

        var handBefore = game.State.GetPlayer(alice).Hand.Count;

        game.CastSpell(alice, card, targets: null, variableValue: 5);
        Settle(game);

        var creature = game.State.Battlefield.Single(
            id => game.State.GetObject(id).Card.Name == "Ravenous Big Test");

        // A printed 0/0 that arrived with nothing would already be in the graveyard, so being
        // here at all is half the assertion.
        var grown = Characteristics.Of(game.State, Pool, game.State.GetObject(creature));
        Assert.Equal(5, grown.Power);
        Assert.Equal(5, grown.Toughness);

        // The card was cast out of hand and one was drawn, so the hand is where it started.
        Assert.Equal(handBefore, game.State.GetPlayer(alice).Hand.Count);
    }

    /// <summary>A ravenous creature cast for a small X gets the counters and no card.</summary>
    /// <remarks>
    /// The half of CR 603.4 that a single-check reading would get wrong in the player's favour:
    /// the draw is not what ravenous does, it is what ravenous does when X was big enough.
    /// </remarks>
    [Fact]
    public void Ravenous_draws_nothing_when_X_was_under_five()
    {
        var aberrant = new CardDefinition
        {
            OracleId = "oracle-ravenous-small-test",
            Name = "Ravenous Small Test",
            OracleText = "Ravenous",
            CardTypes = CardType.Creature,
            Power = 0,
            Toughness = 0,
            ManaCostRaw = "{X}{B}",
        };

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, aberrant);

        foreach (var _ in Enumerable.Range(0, 5))
        {
            var land = game.Create(alice, TestCards.BasicLand("Swamp"), Zone.Battlefield);
            game.ActivateAbility(alice, land, "mana");
        }

        var handBefore = game.State.GetPlayer(alice).Hand.Count;

        game.CastSpell(alice, card, targets: null, variableValue: 4);
        Settle(game);

        var creature = game.State.Battlefield.Single(
            id => game.State.GetObject(id).Card.Name == "Ravenous Small Test");

        var grown = Characteristics.Of(game.State, Pool, game.State.GetObject(creature));
        Assert.Equal(4, grown.Power);

        // One card left the hand and none came back.
        Assert.Equal(handBefore - 1, game.State.GetPlayer(alice).Hand.Count);
    }

    /// <summary>
    /// Ravenous on a card with no X in its cost is not read at all (CR 702.156a).
    /// </summary>
    /// <remarks>
    /// Both halves of the keyword are about the X that was paid, so on a card that has none the
    /// word means nothing the engine could honour. Left unread rather than compiled into a
    /// creature that quietly enters with no counters, because a card the deck check refuses is
    /// better than one that silently does half of what it prints.
    /// </remarks>
    [Fact]
    public void Ravenous_without_an_X_in_the_mana_cost_stays_unread()
    {
        var wrong = new CardDefinition
        {
            OracleId = "oracle-ravenous-no-x-test",
            Name = "Ravenous No X Test",
            OracleText = "Ravenous",
            CardTypes = CardType.Creature,
            Power = 2,
            Toughness = 2,
            ManaCostRaw = "{2}{B}",
        };

        Assert.Contains("Ravenous", CardCompiler.Compile(wrong).Unhandled);
    }

    /// <summary>
    /// Amplify buys counters by showing the rest of the tribe (CR 702.38a).
    /// </summary>
    /// <remarks>
    /// Two things the shape has to get right, and both are asserted here: only cards sharing a
    /// creature type with the arriving permanent may be shown, and revealing none is a legal
    /// answer — "any number" includes zero, which is why this is one question rather than a
    /// yes/no followed by a selection.
    /// </remarks>
    [Fact]
    public void Amplify_grows_the_creature_by_what_was_revealed_from_hand()
    {
        var dragon = Card(
            "Amplify Dragon Test",
            "Amplify 3",
            CardType.Creature,
            power: 5,
            toughness: 5,
            keywords: KeywordAbility.None,
            "Dragon");

        var compiled = CardCompiler.Compile(dragon);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.Equal(3, compiled.AmplifyCount);

        var (game, alice, _) = InMainPhase();

        var kin = TestCards.PutInHand(
            game, alice, Card(
                "Amplify Kin Test", string.Empty, CardType.Creature, 1, 1,
                KeywordAbility.None, "Dragon"));

        var stranger = TestCards.PutInHand(
            game, alice, Card(
                "Amplify Stranger Test", string.Empty, CardType.Creature, 1, 1,
                KeywordAbility.None, "Goblin"));

        var arriving = game.Create(alice, dragon, Zone.Battlefield);

        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.Amplify });

        var choice = game.State.Choice!;
        Assert.Equal(0, choice.MinPicks);
        Assert.Contains(choice.Options, o => o.Id == kin.Value.ToString("N"));
        Assert.DoesNotContain(choice.Options, o => o.Id == stranger.Value.ToString("N"));

        game.Choose(alice, [kin.Value.ToString("N")]);
        Settle(game);

        var grown = Characteristics.Of(game.State, Pool, game.State.GetObject(arriving));
        Assert.Equal(8, grown.Power);
        Assert.Equal(8, grown.Toughness);

        // Revealing is not discarding: the card is still in hand (CR 701.16a).
        Assert.Contains(kin, game.State.GetPlayer(alice).Hand);
        Assert.Contains(game.Log, e => e is CardsRevealed);
    }

    /// <summary>
    /// Amplify on a card with no creature types is not read (CR 702.38a).
    /// </summary>
    /// <remarks>
    /// What may be revealed is "a card that shares a creature type with this one", and the types
    /// come from the card rather than from the line. Without them the keyword is an offer that
    /// can never find anything, so the line goes back unread instead.
    /// </remarks>
    [Fact]
    public void Amplify_without_a_creature_type_stays_unread()
    {
        var typeless = Card(
            "Amplify Typeless Test", "Amplify 2", CardType.Creature, 2, 2);

        Assert.Contains("Amplify 2", CardCompiler.Compile(typeless).Unhandled);
    }

    /// <summary>Clutch of Currents, printed exactly as it reads.</summary>
    private static CardDefinition AwakenSpell() => new()
    {
        OracleId = "oracle-awaken-clutch-test",
        Name = "Awaken Clutch Test",
        ManaCostRaw = "{U}",
        OracleText = "Return target creature to its owner's hand.\nAwaken 3\u2014{4}{U}",
        CardTypes = CardType.Sorcery,
    };

    /// <summary>
    /// A spell cast for its printed cost has no awaken target at all (CR 702.113b).
    /// </summary>
    /// <remarks>
    /// The half of the rule that a naive reading gets wrong in the player's favour: if the land
    /// were always targeted, an awaken card would stand a land up for its cheap cost. It is not
    /// "targeted and then ignored" - the spell is cast as if it did not have that target.
    /// </remarks>
    [Fact]
    public void An_awaken_spell_cast_for_its_printed_cost_leaves_lands_alone()
    {
        var clutch = AwakenSpell();

        var compiled = CardCompiler.Compile(clutch);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var bear = game.Create(bob, TestCards.Creature("Awaken Bear Test", 2, 2), Zone.Battlefield);
        var land = game.Create(alice, TestCards.BasicLand("Island"), Zone.Battlefield);
        var card = TestCards.PutInHand(game, alice, clutch);

        game.AddMana(alice, ManaColor.Blue);

        game.CastSpell(alice, card, [Target.ToPermanent(bear)]);
        Settle(game);

        Assert.DoesNotContain(bear, game.State.Battlefield);

        var still = Characteristics.Of(game.State, Pool, game.State.GetObject(land));
        Assert.False(still.IsCreature);
    }

    /// <summary>
    /// Awaken stands a land up permanently, on top of what the spell already did (CR 702.113a).
    /// </summary>
    /// <remarks>
    /// Four things in four different layers, which is why the half is four effects rather than
    /// one: the counters are counters, the creature type is layer 4, the 0/0 is layer 7b and
    /// haste is layer 6. And the land is still a land - the type is added, not swapped - which
    /// is what the printed rider goes on to say.
    /// <para>
    /// The animation carries no duration, so it is asserted across a turn boundary. Reading it as
    /// "until end of turn" would have looked right for as long as any single-turn test ran.
    /// </para>
    /// </remarks>
    [Fact]
    public void An_awakened_spell_animates_the_land_and_still_does_what_it_says()
    {
        var clutch = AwakenSpell();

        var (game, alice, bob) = InMainPhase();
        var bear = game.Create(bob, TestCards.Creature("Awaken Bear Test", 2, 2), Zone.Battlefield);
        var land = game.Create(alice, TestCards.BasicLand("Island"), Zone.Battlefield);
        var card = TestCards.PutInHand(game, alice, clutch);

        foreach (var _ in Enumerable.Range(0, 5))
            game.AddMana(alice, ManaColor.Blue);

        game.CastSpell(
            alice,
            card,
            [Target.ToPermanent(bear), Target.ToPermanent(land)],
            awakened: true);

        Settle(game);

        // The printed spell still happened.
        Assert.DoesNotContain(bear, game.State.Battlefield);

        var awoken = Characteristics.Of(game.State, Pool, game.State.GetObject(land));
        Assert.True(awoken.IsCreature);
        Assert.True(awoken.CardTypes.HasFlag(CardType.Land));
        Assert.True(awoken.HasSubtype("Elemental"));
        Assert.True(awoken.Keywords.HasFlag(KeywordAbility.Haste));
        Assert.Equal(3, awoken.Power);
        Assert.Equal(3, awoken.Toughness);

        // And it is not an until-end-of-turn effect: the land is still a creature next turn.
        TestCards.PassToStep(game, TurnStep.PrecombatMain);
        TestCards.PassToStep(game, TurnStep.PrecombatMain);

        var later = Characteristics.Of(game.State, Pool, game.State.GetObject(land));
        Assert.True(later.IsCreature);
        Assert.Equal(3, later.Power);
    }

    /// <summary>Nothing may be awakened that has no awaken (CR 702.113a).</summary>
    [Fact]
    public void Awakening_a_spell_that_has_no_awaken_is_refused()
    {
        var plain = Card("Awaken Plain Test", "Draw a card.");
        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, plain);

        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, card, [], awakened: true));
    }

    /// <summary>A creature with sneak, printed the way the real ones are.</summary>
    private static CardDefinition SneakCreature() => new()
    {
        OracleId = "oracle-sneak-ninja-test",
        Name = "Sneak Ninja Test",
        ManaCostRaw = "{4}{B}",
        OracleText = "Sneak {B}",
        CardTypes = CardType.Creature,
        Power = 3,
        Toughness = 3,
    };

    /// <summary>
    /// Sneak swaps an unblocked attacker for the card, mid-combat (CR 702.190a, 702.190b).
    /// </summary>
    /// <remarks>
    /// Ninjutsu written as a way of casting rather than as an activated ability, and the same
    /// three things have to be true: the attacker goes back to hand rather than to a graveyard,
    /// the arriving permanent is tapped and attacking, and it is attacking whoever the returned
    /// creature was - a fact that only exists while the creature is still in combat, so it is
    /// written down as the cost is paid and read back on resolution.
    /// <para>
    /// The damage at the end is what proves the attack is real rather than a flag: a permanent
    /// merely on the battlefield deals nobody anything.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_sneaked_creature_replaces_its_attacker_and_arrives_swinging()
    {
        var ninja = SneakCreature();

        var compiled = CardCompiler.Compile(ninja);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var scout = game.Create(alice, TestCards.Creature("Sneak Scout Test", 1, 1), Zone.Battlefield);

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [scout] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);
        game.DeclareBlockers(bob, new Dictionary<ObjectId, IReadOnlyList<ObjectId>>());

        // Put in hand here rather than before the turns were passed: a cleanup step in between
        // discards down to hand size, and the card the test is about is one of the ones it takes.
        var card = TestCards.PutInHand(game, alice, ninja);
        game.AddMana(alice, ManaColor.Black);

        game.CastSpell(alice, card, [], costPayment: [scout], sneaked: true);
        Settle(game);

        // The attacker went to hand, not to a graveyard (CR 701.20a).
        Assert.DoesNotContain(scout, game.State.Battlefield);
        Assert.Empty(game.State.GetPlayer(alice).Graveyard);

        var arrived = game.State.Battlefield.Single(
            id => game.State.GetObject(id).Card.Name == "Sneak Ninja Test");

        Assert.True(game.State.GetObject(arrived).Permanent!.IsTapped);
        Assert.Equal(AttackTarget.Player(bob), game.State.Combat.Attackers[arrived]);

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Settle(game);

        // A 3/3 that arrived attacking, and nothing blocked it.
        Assert.Equal(17, game.State.GetPlayer(bob).Life);
    }

    /// <summary>
    /// Sneak buys one window and it is not the main phase (CR 702.190a).
    /// </summary>
    /// <remarks>
    /// "Any time you could cast an instant during your declare blockers step" is the whole of
    /// the permission. Read as an ordinary alternative cost, this would be a five-mana 3/3 that
    /// could be had for one at any time - a strictly better card than the one printed, and the
    /// coverage number would have gone up either way.
    /// </remarks>
    [Fact]
    public void Sneaking_a_creature_in_outside_the_declare_blockers_step_is_refused()
    {
        var ninja = SneakCreature();

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, ninja);
        game.AddMana(alice, ManaColor.Black);

        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, card, [], sneaked: true));
    }

    /// <summary>
    /// The mana is only half the sneak price, and a blocked attacker cannot pay it (CR 702.190a).
    /// </summary>
    /// <remarks>
    /// "An unblocked creature you control" is the whole point of the mechanic: the card takes
    /// the place of something that was about to get through. A blocked attacker was not, and
    /// letting it pay would make sneak a way to un-block your own creature for one mana.
    /// </remarks>
    [Fact]
    public void Sneaking_in_place_of_a_blocked_attacker_is_refused()
    {
        var ninja = SneakCreature();

        var (game, alice, bob) = InMainPhase();
        var scout = game.Create(alice, TestCards.Creature("Sneak Blocked Test", 1, 1), Zone.Battlefield);
        var wall = game.Create(bob, TestCards.Creature("Sneak Wall Test", 0, 4), Zone.Battlefield);

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [scout] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);
        game.DeclareBlockers(
            bob,
            new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [scout] = [wall] });

        var card = TestCards.PutInHand(game, alice, ninja);
        game.AddMana(alice, ManaColor.Black);

        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, card, [], costPayment: [scout], sneaked: true));

        // CR 601.2i: a cast that cannot pay its cost is rewound, so nothing moved.
        Assert.Contains(card, game.State.GetPlayer(alice).Hand);
        Assert.Contains(scout, game.State.Battlefield);
    }

    /// <summary>A three-chapter Saga with read ahead, written the way the real ones are.</summary>
    private static CardDefinition ReadAheadSaga() => new()
    {
        OracleId = "oracle-read-ahead-saga-test",
        Name = "Read Ahead Saga Test",
        ManaCostRaw = "{2}{W}",
        OracleText = "Read ahead\nI — You gain 1 life.\nII — You gain 2 life."
            + "\nIII — You gain 3 life.",
        CardTypes = CardType.Enchantment,
        Subtypes = ["Saga"],
    };

    /// <summary>
    /// A Saga with read ahead starts where its controller says, and skips what it started past
    /// (CR 702.155a, 702.155b).
    /// </summary>
    /// <remarks>
    /// Two rules, and the second is the one a partial reading gets wrong in the player's favour.
    /// The counters arrive in one lump, and CR 714.2b would fire every chapter that lump crossed -
    /// so reading only "enters with the chosen number of counters" turns a Saga started at three
    /// into a Saga that runs all three chapters at once. That reading compiles, plays, and is a
    /// strictly better card than the printed one.
    /// </remarks>
    [Fact]
    public void A_Saga_with_read_ahead_starts_at_the_chosen_chapter_and_skips_the_rest()
    {
        var saga = ReadAheadSaga();

        var compiled = CardCompiler.Compile(saga);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.True(compiled.HasReadAhead);

        var (game, alice, _) = InMainPhase();
        var before = game.State.GetPlayer(alice).Life;
        var chronicle = game.Create(alice, saga, Zone.Battlefield);

        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.ReadAhead });

        // One option per chapter, and the final chapter is the last of them (CR 714.2d).
        var choice = game.State.Choice!;
        Assert.Equal(3, choice.Options.Count);

        game.Choose(alice, ["3"]);
        Settle(game);

        // Chapter three, and only chapter three: one plus two plus three would be six.
        Assert.Equal(before + 3, game.State.GetPlayer(alice).Life);

        // CR 714.4: it reached its final chapter, so it is sacrificed.
        Assert.DoesNotContain(chronicle, game.State.Battlefield);
    }

    /// <summary>
    /// Started at chapter one, a read-ahead Saga runs like any other (CR 702.155a).
    /// </summary>
    /// <remarks>
    /// The restriction is only about the turn it entered. A Saga that chose one still advances a
    /// counter each precombat main phase afterwards and fires each chapter as it gets there -
    /// which is what says the gate is scoped to the entry turn rather than switched on for good.
    /// </remarks>
    [Fact]
    public void A_read_ahead_Saga_that_chose_chapter_one_advances_normally_afterwards()
    {
        var saga = ReadAheadSaga();

        var (game, alice, _) = InMainPhase();
        var before = game.State.GetPlayer(alice).Life;
        game.Create(alice, saga, Zone.Battlefield);

        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.ReadAhead });
        game.Choose(alice, ["1"]);
        Settle(game);

        Assert.Equal(before + 1, game.State.GetPlayer(alice).Life);

        // Alice's next turn: a lore counter, and chapter two with it.
        PassToMainPhaseOfTurn(game, game.State.TurnNumber + 2);
        Settle(game);

        Assert.Equal(before + 3, game.State.GetPlayer(alice).Life);
    }

    /// <summary>
    /// Read ahead on a card with no chapter this compiler could read is left unread.
    /// </summary>
    /// <remarks>
    /// The keyword only says where to start. A Saga started at a chapter that does nothing is a
    /// Saga walking to its own sacrifice, which is worse than a card a deck check refuses.
    /// </remarks>
    [Fact]
    public void Read_ahead_without_a_readable_chapter_stays_unread()
    {
        var wordy = new CardDefinition
        {
            OracleId = "oracle-read-ahead-unreadable-test",
            Name = "Read Ahead Unreadable Test",
            OracleText = "Read ahead\nI — Ponder the meaning of the sea.",
            CardTypes = CardType.Enchantment,
            Subtypes = ["Saga"],
        };

        var compiled = CardCompiler.Compile(wordy);
        Assert.Contains("Read ahead", compiled.Unhandled);
        Assert.False(compiled.HasReadAhead);
    }

    /// <summary>
    /// Hideaway looks at the top N, puts one aside and buries the rest (CR 702.75a).
    /// </summary>
    /// <remarks>
    /// The exiled card is exiled face up here, because this engine has no face-down exile - a
    /// deviation that costs the permanent's controller information and gains them nothing, which
    /// is the direction a reading is allowed to be wrong in. Nothing in a game reaches it either
    /// way: the second line every hideaway card prints, saying when the exiled card may be
    /// played, is not read yet, so no hideaway card compiles completely.
    /// </remarks>
    [Fact]
    public void Hideaway_exiles_one_of_the_top_cards_and_buries_the_rest()
    {
        var vault = Card(
            "Hideaway Vault Test",
            "Hideaway 4",
            CardType.Land);

        var compiled = CardCompiler.Compile(vault);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var library = game.State.GetPlayer(alice).Library.Count;

        game.Create(alice, vault, Zone.Battlefield);
        Settle(game);

        // One card is in exile and the other three went to the bottom, so the library is one
        // shorter and nothing else moved.
        Assert.Single(game.State.Exile);
        Assert.Equal(library - 1, game.State.GetPlayer(alice).Library.Count);
    }

    /// <summary>
    /// A card printing hideaway twice does it twice (CR 702.75a).
    /// </summary>
    /// <remarks>
    /// "Hideaway 3, hideaway 3" is two instances of the keyword on one line, and each is its own
    /// triggered ability. A reader that stopped at the first comma would compile half the card
    /// and report the line as fully read, which is the failure the coverage number cannot see.
    /// </remarks>
    [Fact]
    public void Two_hideaways_on_one_line_are_two_abilities()
    {
        var ursine = Card(
            "Hideaway Ursine Test",
            "Hideaway 3, hideaway 3",
            CardType.Creature,
            power: 4,
            toughness: 4);

        var compiled = CardCompiler.Compile(ursine);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.Equal(2, compiled.Triggers.Count);

        var (game, alice, _) = InMainPhase();
        game.Create(alice, ursine, Zone.Battlefield);
        Settle(game);

        Assert.Equal(2, game.State.Exile.Count);
    }

    /// <summary>
    /// Teamwork is an optional additional cost paid by tapping a team (CR 702.194a).
    /// </summary>
    /// <remarks>
    /// Crew's cost offered rather than demanded: any number of creatures whose power adds up to
    /// N or more. What paying it buys is on the card's other lines - "if this spell was cast
    /// using teamwork, ..." - and those sentences are not read yet, so nothing in the game
    /// consults the fact. It is recorded anyway, because the payment happened and a log that
    /// does not say so cannot be replayed into a game that knows it.
    /// </remarks>
    [Fact]
    public void A_teamwork_cost_taps_a_team_whose_power_adds_up()
    {
        var tactics = Card("Teamwork Tactics Test", "Draw a card.\nTeamwork 3");

        var compiled = CardCompiler.Compile(tactics);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.NotNull(compiled.Spell?.TeamworkCost);

        var (game, alice, _) = InMainPhase();
        var first = game.Create(alice, TestCards.Creature("Teamwork One Test", 2, 2), Zone.Battlefield);
        var second = game.Create(alice, TestCards.Creature("Teamwork Two Test", 1, 1), Zone.Battlefield);
        var card = TestCards.PutInHand(game, alice, tactics);

        // Two power is not three, so one creature cannot pay it alone (CR 702.194a).
        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, card, [], costPayment: [first], teamwork: true));

        game.CastSpell(alice, card, [], costPayment: [first, second], teamwork: true);
        Settle(game);

        Assert.True(game.State.GetObject(first).Permanent!.IsTapped);
        Assert.True(game.State.GetObject(second).Permanent!.IsTapped);
    }

    /// <summary>Declining teamwork taps nothing and casts the spell as printed (CR 702.194a).</summary>
    [Fact]
    public void A_spell_with_teamwork_may_be_cast_without_paying_it()
    {
        var tactics = Card("Teamwork Declined Test", "Draw a card.\nTeamwork 3");

        var (game, alice, _) = InMainPhase();
        var ally = game.Create(alice, TestCards.Creature("Teamwork Idle Test", 4, 4), Zone.Battlefield);
        var card = TestCards.PutInHand(game, alice, tactics);

        game.CastSpell(alice, card, []);
        Settle(game);

        Assert.False(game.State.GetObject(ally).Permanent!.IsTapped);
    }

    /// <summary>
    /// A permanent with phasing leaves and comes back on its controller's untap steps
    /// (CR 702.26a, 702.26c).
    /// </summary>
    /// <remarks>
    /// The whole of what "treated as though it does not exist" means is tested through a
    /// sweeper: while it is phased out, "destroy all creatures" does not find it, and it is back
    /// two turns later with nothing having happened to it (CR 702.26b, 702.26d). A reading that
    /// simply flagged the permanent would pass a test that only looked at the flag.
    /// </remarks>
    [Fact]
    public void A_permanent_with_phasing_stops_existing_and_comes_back()
    {
        var keeper = Card(
            "Phasing Keeper Test",
            "Phasing",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var compiled = CardCompiler.Compile(keeper);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var breeze = game.Create(alice, keeper, Zone.Battlefield);

        Assert.Contains(breeze, game.State.Battlefield);

        // Alice's next untap step: it phases out.
        PassToMainPhaseOfTurn(game, game.State.TurnNumber + 2);

        Assert.DoesNotContain(breeze, game.State.Battlefield);
        Assert.Contains(breeze, game.State.PhasedOut.Keys);

        // CR 702.26b: a sweeper does not find it, because it is not there to find.
        var wrath = Card("Phasing Wrath Test", "Destroy all creatures.", CardType.Sorcery);
        var card = TestCards.PutInHand(game, alice, wrath);
        game.CastSpell(alice, card, []);
        Settle(game);

        Assert.DoesNotContain(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Phasing Keeper Test");

        // And on the untap step after that it is back, untouched.
        PassToMainPhaseOfTurn(game, game.State.TurnNumber + 2);

        Assert.Contains(breeze, game.State.Battlefield);
        Assert.Empty(game.State.PhasedOut);
        Assert.Equal(2, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(breeze)));
    }

    /// <summary>
    /// An Aura goes with what it enchants, and comes back with it (CR 702.26g).
    /// </summary>
    /// <remarks>
    /// The half that a reading of phasing on its own gets wrong <em>in the phasing card's
    /// favour</em>: an Aura left behind on the battlefield is attached to nothing, and the
    /// state-based action for that would bin it (CR 704.5m). The opponent's Pacifism would come
    /// off permanently, which is a strictly better creature than the printed one.
    /// <para>
    /// It returns on the creature's controller's untap step rather than the Aura controller's,
    /// which is why what the engine writes down is whose untap step brings each permanent back
    /// rather than who controls it.
    /// </para>
    /// </remarks>
    [Fact]
    public void An_aura_phases_out_with_the_creature_it_enchants()
    {
        var keeper = Card(
            "Phasing Host Test",
            "Phasing",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var pacifism = Card(
            "Phasing Pacifism Test",
            "Enchant creature\nEnchanted creature can't attack or block.",
            CardType.Enchantment,
            power: null,
            toughness: null,
            keywords: KeywordAbility.None,
            "Aura");

        var (game, alice, bob) = InMainPhase();
        var host = game.Create(alice, keeper, Zone.Battlefield);

        TestCards.PassUntil(
            game,
            () => game.State.ActivePlayerId == bob
                && game.State.CurrentStep == TurnStep.PrecombatMain);

        // Put in hand once the turn has arrived: a cleanup step in between discards down to hand
        // size, and it takes the card the test is about.
        var aura = TestCards.PutInHand(game, bob, pacifism);
        game.CastSpell(bob, aura, [Target.ToPermanent(host)]);
        Settle(game);

        var attached = game.State.Battlefield.Single(
            id => game.State.GetObject(id).Card.Name == "Phasing Pacifism Test");

        Assert.Equal(host, game.State.GetObject(attached).Permanent!.AttachedTo);

        // Alice's untap step: the creature phases out and takes the Aura with it.
        TestCards.PassUntil(
            game,
            () => game.State.ActivePlayerId == alice
                && game.State.CurrentStep == TurnStep.PrecombatMain);

        Assert.DoesNotContain(host, game.State.Battlefield);
        Assert.DoesNotContain(attached, game.State.Battlefield);

        // Not destroyed for being attached to nothing (CR 704.5m) - it is not there to check.
        Assert.DoesNotContain(attached, game.State.GetPlayer(bob).Graveyard);

        // Both return together on Alice's next untap step, still attached (CR 702.26g).
        TestCards.PassUntil(
            game,
            () => game.State.ActivePlayerId == alice
                && game.State.CurrentStep == TurnStep.PrecombatMain
                && game.State.Battlefield.Contains(host));

        Assert.Contains(attached, game.State.Battlefield);
        Assert.Equal(host, game.State.GetObject(attached).Permanent!.AttachedTo);
    }

    /// <summary>
    /// Ripple shows the top cards and hands back the copies for free (CR 702.60a).
    /// </summary>
    /// <remarks>
    /// Three things have to be true and each is asserted: the copy sharing the spell's name is
    /// castable without paying, everything else goes to the bottom rather than staying on top,
    /// and the copy that is cast does what the card says. The last is what separates a ripple
    /// that works from one that merely moves cards about.
    /// </remarks>
    [Fact]
    public void Ripple_offers_the_copies_it_finds_for_free()
    {
        var surge = new CardDefinition
        {
            OracleId = "oracle-ripple-surge-test",
            Name = "Ripple Surge Test",
            ManaCostRaw = "{G}",
            OracleText = "You gain 2 life.\nRipple 4",
            CardTypes = CardType.Instant,
        };

        var compiled = CardCompiler.Compile(surge);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var before = game.State.GetPlayer(alice).Life;

        // A second copy sitting on top of the library, under three cards that are not it.
        game.Create(alice, surge, Zone.Library);
        var library = game.State.GetPlayer(alice).Library.Count;

        var card = TestCards.PutInHand(game, alice, surge);
        game.AddMana(alice, ManaColor.Green);

        game.CastSpell(alice, card, []);

        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.Ripple });

        // Declining is on the menu, because a ripple buries what it showed.
        Assert.Equal(0, game.State.Choice!.MinPicks);

        // Answered and not played on: an offer to cast for free is a window, and passing
        // priority is how a player declines it (CR 601.2b).
        game.Choose(alice, ["ripple"]);

        // The copy is in exile and castable for nothing; the other three went to the bottom.
        // Looked up by name rather than held onto: a card that changes zone becomes a new
        // object and the id it had in the library stopped existing (CR 400.7).
        var copy = Assert.Single(game.State.Exile);
        Assert.Equal("Ripple Surge Test", game.State.GetObject(copy).Card.Name);
        Assert.True(game.State.GetObject(copy).MayCastFree);
        Assert.Equal(library - 1, game.State.GetPlayer(alice).Library.Count);

        game.CastSpell(alice, copy, []);
        Settle(game);

        // Both halves resolved: the spell that was cast and the copy it turned up.
        Assert.Equal(before + 4, game.State.GetPlayer(alice).Life);
    }

    /// <summary>Declining a ripple leaves the library exactly as it was (CR 702.60a).</summary>
    /// <remarks>
    /// "You may" is a real decision here rather than a formality, which is why it is a question
    /// at all: rippling shuffles what it showed into the bottom of the library in a random
    /// order, and a player who has arranged their top cards does not want that.
    /// </remarks>
    [Fact]
    public void Declining_a_ripple_leaves_the_library_alone()
    {
        var surge = new CardDefinition
        {
            OracleId = "oracle-ripple-declined-test",
            Name = "Ripple Declined Test",
            ManaCostRaw = "{G}",
            OracleText = "You gain 2 life.\nRipple 4",
            CardTypes = CardType.Instant,
        };

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, surge);
        var top = game.State.GetPlayer(alice).Library[0];
        var library = game.State.GetPlayer(alice).Library.Count;

        game.AddMana(alice, ManaColor.Green);
        game.CastSpell(alice, card, []);

        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.Ripple });
        game.Choose(alice, []);
        Settle(game);

        Assert.Equal(library, game.State.GetPlayer(alice).Library.Count);
        Assert.Equal(top, game.State.GetPlayer(alice).Library[0]);
        Assert.Empty(game.State.Exile);
    }

    // ---- Soulbond (CR 702.95), and granted phasing (CR 702.26) ---------------

    /// <summary>The reminder text every soulbond printing carries, stripped before compiling.</summary>
    private const string SoulbondReminder =
        " (You may pair this creature with another unpaired creature when either enters. They "
        + "remain paired for as long as you control both of them.)";

    /// <summary>Wingcrafter as printed, shared by two tests so the pool holds one definition.</summary>
    private static CardDefinition Wingcrafter() => Card(
        "Wingcrafter",
        "Soulbond" + SoulbondReminder + "\nAs long as this creature is paired with another "
            + "creature, both creatures have flying.",
        CardType.Creature,
        1,
        1,
        KeywordAbility.Soulbond);

    [Fact]
    public void Soulbond_asks_on_its_own_entry_and_the_bonus_reaches_both()
    {
        // CR 702.95a's first trigger: entering, this creature may pair with another unpaired
        // creature its controller has - a choice made on resolution, so it is a question rather
        // than a target. The payoff is CR 702.95b: a conditional static whose two subjects are
        // the two halves of the pair.
        var wolfir = Card(
            "Wolfir Silverheart",
            "Soulbond\nAs long as this creature is paired with another creature, each of those "
                + "creatures gets +4/+4.",
            CardType.Creature,
            4,
            4,
            KeywordAbility.Soulbond);

        var compiled = CardCompiler.Compile(wolfir);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var mine = game.Create(alice, TestCards.Creature("Bonded Bear Test", 2, 2), Zone.Battlefield);
        var theirs = game.Create(bob, TestCards.Creature("Unbondable Bear Test", 2, 2), Zone.Battlefield);

        var pack = game.Create(alice, wolfir, Zone.Battlefield);
        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.Soulbond });

        // The question offers Alice's unpaired creature and declining, and nobody else's:
        // pairing is "you control both" (CR 702.95a), so Bob's bear is not on the menu.
        var asked = game.State.Choice!;
        Assert.Equal(alice, asked.PlayerId);
        Assert.Contains(asked.Options, o => o.Id == "none");
        Assert.DoesNotContain(asked.Options, o => o.Id == theirs.Value.ToString("N"));

        game.Choose(alice, [mine.Value.ToString("N")]);
        Settle(game);

        // Paired both ways round, and the bonus lands on both halves and nobody else.
        Assert.Equal(mine, game.State.GetObject(pack).Permanent!.PairedWithId);
        Assert.Equal(pack, game.State.GetObject(mine).Permanent!.PairedWithId);
        Assert.Equal(8, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(pack)));
        Assert.Equal(6, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(mine)));
        Assert.Equal(2, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(theirs)));
    }

    [Fact]
    public void Soulbond_offers_the_newcomer_while_it_stands_unpaired()
    {
        // CR 702.95a's second trigger: another creature entering may be paired with this one.
        // That arm pairs the newcomer and nothing else, so the question is one candidate plus
        // declining - and it is guarded by an intervening if (CR 603.4), so a soulbond creature
        // alone never asks at all.
        var mauler = Card(
            "Lightning Mauler",
            "Soulbond\nAs long as this creature is paired with another creature, both creatures "
                + "have haste.",
            CardType.Creature,
            2,
            1,
            KeywordAbility.Soulbond);

        var compiled = CardCompiler.Compile(mauler);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var speedster = game.Create(alice, mauler, Zone.Battlefield);
        Settle(game);

        Assert.DoesNotContain(game.Log, e => e is SoulbondPairRequested);

        var friend = game.Create(alice, TestCards.Creature("Hasty Friend Test", 2, 2), Zone.Battlefield);
        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.Soulbond });

        var asked = game.State.Choice!;
        Assert.Equal(2, asked.Options.Count);
        Assert.Equal(friend.Value.ToString("N"), asked.Options[0].Id);

        game.Choose(alice, [asked.Options[0].Id]);
        Settle(game);

        Assert.True(Characteristics.Of(game.State, Pool, game.State.GetObject(speedster))
            .Has(KeywordAbility.Haste));
        Assert.True(Characteristics.Of(game.State, Pool, game.State.GetObject(friend))
            .Has(KeywordAbility.Haste));
    }

    [Fact]
    public void Declining_leaves_both_unpaired_and_the_next_arrival_asks_again()
    {
        // "You may pair" (CR 702.95a): declining spends the trigger, not the ability. The
        // soulbond creature stays unpaired, so the next arrival triggers the same question -
        // and the creature that was declined is not offered again by it.
        var (game, alice, _) = InMainPhase();
        var flier = game.Create(alice, Wingcrafter(), Zone.Battlefield);
        var first = game.Create(alice, TestCards.Creature("Grounded Bear Test", 2, 2), Zone.Battlefield);

        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.Soulbond });
        game.Choose(alice, ["none"]);
        Settle(game);

        Assert.Null(game.State.GetObject(flier).Permanent!.PairedWithId);
        Assert.False(Characteristics.Of(game.State, Pool, game.State.GetObject(first))
            .Has(KeywordAbility.Flying));

        var second = game.Create(alice, TestCards.Creature("Skybound Bear Test", 2, 2), Zone.Battlefield);
        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.Soulbond });
        game.Choose(alice, [second.Value.ToString("N")]);
        Settle(game);

        Assert.True(Characteristics.Of(game.State, Pool, game.State.GetObject(flier))
            .Has(KeywordAbility.Flying));
        Assert.True(Characteristics.Of(game.State, Pool, game.State.GetObject(second))
            .Has(KeywordAbility.Flying));
        Assert.False(Characteristics.Of(game.State, Pool, game.State.GetObject(first))
            .Has(KeywordAbility.Flying));
    }

    [Fact]
    public void The_pairing_ends_when_the_partner_leaves_and_is_recorded_once()
    {
        // CR 702.95e: a half leaving the battlefield unpairs the survivor. The static reader
        // treats a missing partner as gone at once, and the sweep records the break as one
        // event - both halves of a broken bond report it, and a bond is one thing.
        var pilgrim = Card(
            "Nearheath Pilgrim",
            "Soulbond\nAs long as this creature is paired with another creature, both creatures "
                + "have lifelink.",
            CardType.Creature,
            2,
            1,
            KeywordAbility.Soulbond);

        var compiled = CardCompiler.Compile(pilgrim);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var devout = game.Create(alice, pilgrim, Zone.Battlefield);
        var friend = game.Create(alice, TestCards.Creature("Mortal Friend Test", 2, 2), Zone.Battlefield);

        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.Soulbond });
        game.Choose(alice, [friend.Value.ToString("N")]);
        Settle(game);

        Assert.True(Characteristics.Of(game.State, Pool, game.State.GetObject(devout))
            .Has(KeywordAbility.Lifelink));

        // The question left priority with whoever was owed it; play on to a moment Alice holds it.
        TestCards.PassUntil(game, () => game.State.IsSorcerySpeedFor(alice));
        game.CastSpell(
            alice,
            TestCards.PutInHand(game, alice, Card("Bond Breaker Test", "Destroy target creature.")),
            [Target.ToPermanent(friend)]);
        Settle(game);

        Assert.Null(game.State.GetObject(devout).Permanent!.PairedWithId);
        Assert.False(Characteristics.Of(game.State, Pool, game.State.GetObject(devout))
            .Has(KeywordAbility.Lifelink));
        Assert.Single(game.Log.OfType<CreaturesUnpaired>());
    }

    [Fact]
    public void Another_player_gaining_control_breaks_the_pairing_for_good()
    {
        // CR 702.95e's other half: another player gaining control of either creature unpairs
        // them - and unpairing is for keeps. The theft ends with the turn; the pairing does
        // not resume with it, because only a soulbond trigger ever pairs.
        var shaman = Card(
            "Trusted Forcemage",
            "Soulbond\nAs long as this creature is paired with another creature, each of those "
                + "creatures gets +1/+1.",
            CardType.Creature,
            2,
            2,
            KeywordAbility.Soulbond);

        var compiled = CardCompiler.Compile(shaman);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var thief = Card(
            "Bond Thief Test", "Gain control of target creature until end of turn.", CardType.Sorcery);
        var stealable = CardCompiler.Compile(thief);
        Assert.True(stealable.IsComplete, string.Join(" | ", stealable.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var mage = game.Create(alice, shaman, Zone.Battlefield);
        var friend = game.Create(alice, TestCards.Creature("Loyal Friend Test", 2, 2), Zone.Battlefield);

        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.Soulbond });
        game.Choose(alice, [friend.Value.ToString("N")]);
        Settle(game);

        Assert.Equal(3, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(friend)));

        PassTo(game, 2, TurnStep.PrecombatMain);
        game.CastSpell(
            bob, TestCards.PutInHand(game, bob, thief), [Target.ToPermanent(friend)]);
        Settle(game);

        Assert.Null(game.State.GetObject(mage).Permanent!.PairedWithId);
        Assert.Equal(2, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(mage)));

        PassTo(game, 3, TurnStep.PrecombatMain);
        Assert.Null(game.State.GetObject(friend).Permanent!.PairedWithId);
        Assert.Equal(2, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(friend)));
    }

    [Fact]
    public void A_partner_that_stops_being_a_creature_ends_the_pairing_for_good()
    {
        // CR 702.95e's third arm, and the only one nothing but the sweep can see: leaving the
        // battlefield and changing controller are both events, while ceasing to be a creature
        // is a computed characteristic that simply stops being true. A land animated until end
        // of turn is a legal partner while it is animated - CR 702.95a asks about creatures,
        // not about cards - and takes the bond with it when the animation wears off. Permanent,
        // like every break-up: animating it again does not restore the pairing, because only a
        // soulbond trigger ever pairs.
        var awaken = Card(
            "Bond Animation Test",
            "Target land you control becomes a 3/3 Elemental creature until end of turn.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(awaken);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, awaken), [Target.ToPermanent(forest)]);
        Settle(game);

        var flier = game.Create(alice, Wingcrafter(), Zone.Battlefield);
        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.Soulbond });

        // The land is on the menu because it is a creature right now.
        Assert.Contains(game.State.Choice!.Options, o => o.Id == forest.Value.ToString("N"));
        game.Choose(alice, [forest.Value.ToString("N")]);
        Settle(game);

        Assert.Equal(flier, game.State.GetObject(forest).Permanent!.PairedWithId);
        Assert.True(Characteristics.Of(game.State, Pool, game.State.GetObject(forest))
            .Has(KeywordAbility.Flying));

        // Cleanup ends the animation, so the bond has nothing left to stand on.
        PassTo(game, 2, TurnStep.Upkeep);
        Assert.False(Characteristics.Of(game.State, Pool, game.State.GetObject(forest))
            .CardTypes.HasFlag(CardType.Creature));
        Assert.Null(game.State.GetObject(flier).Permanent!.PairedWithId);
        Assert.Null(game.State.GetObject(forest).Permanent!.PairedWithId);
        Assert.Single(game.Log.OfType<CreaturesUnpaired>());

        // Animated again two turns on: a creature once more, and still unpaired.
        PassTo(game, 3, TurnStep.PrecombatMain);
        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, awaken), [Target.ToPermanent(forest)]);
        Settle(game);

        Assert.True(Characteristics.Of(game.State, Pool, game.State.GetObject(forest))
            .CardTypes.HasFlag(CardType.Creature));
        Assert.Null(game.State.GetObject(forest).Permanent!.PairedWithId);
        Assert.False(Characteristics.Of(game.State, Pool, game.State.GetObject(forest))
            .Has(KeywordAbility.Flying));
    }

    [Fact]
    public void A_quoted_ability_is_granted_to_both_halves_while_paired()
    {
        // "Each of those creatures has ..." is layer 6 for two permanents at once: the quoted
        // ability is compiled once and handed to whichever half is being computed, exactly as
        // an Aura's grant is handed to its host.
        var smith = Card(
            "Stonewright",
            "Soulbond\nAs long as Stonewright is paired with another creature, each of those "
                + "creatures has \"{R}: This creature gets +1/+0 until end of turn.\"",
            CardType.Creature,
            1,
            1,
            KeywordAbility.Soulbond);

        var compiled = CardCompiler.Compile(smith);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var wright = game.Create(alice, smith, Zone.Battlefield);
        var friend = game.Create(alice, TestCards.Creature("Fiery Friend Test", 2, 2), Zone.Battlefield);

        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.Soulbond });
        game.Choose(alice, [friend.Value.ToString("N")]);
        Settle(game);

        Assert.NotEmpty(GrantedIdsOf(game, wright));
        var granted = Game.ActivatedAbilitiesOf(game.State, Pool, game.State.GetObject(friend))
            .Single(a => a.Id.StartsWith("granted:", StringComparison.Ordinal));

        TestCards.PassUntil(game, () => game.State.IsSorcerySpeedFor(alice));
        game.AddMana(alice, ManaColor.Red);
        game.ActivateAbility(alice, friend, granted.Id);
        Settle(game);

        Assert.Equal(3, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(friend)));
    }

    [Fact]
    public void A_granted_trigger_belongs_to_each_half_that_carries_it()
    {
        // The granted ability is as often a trigger as an activated one, and it belongs to the
        // creature holding it: one opponent's spell fires both halves' copies, and each puts
        // its counter on itself.
        var spirit = Card(
            "Thundering Mightmare",
            "Soulbond\nAs long as Thundering Mightmare is paired with another creature, each of "
                + "those creatures has \"Whenever an opponent casts a spell, put a +1/+1 counter "
                + "on this creature.\"",
            CardType.Creature,
            2,
            2,
            KeywordAbility.Soulbond);

        var compiled = CardCompiler.Compile(spirit);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var horse = game.Create(alice, spirit, Zone.Battlefield);
        var friend = game.Create(alice, TestCards.Creature("Startled Friend Test", 2, 2), Zone.Battlefield);

        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.Soulbond });
        game.Choose(alice, [friend.Value.ToString("N")]);
        Settle(game);

        PassTo(game, 2, TurnStep.PrecombatMain);
        game.CastSpell(
            bob,
            TestCards.PutInHand(game, bob, Card("Provocation Test", "Draw a card.", CardType.Sorcery)),
            targets: null);
        Settle(game);

        Assert.Equal(1, game.State.GetObject(horse).Permanent!
            .Counters.GetValueOrDefault(CounterKinds.PlusOnePlusOne));
        Assert.Equal(1, game.State.GetObject(friend).Permanent!
            .Counters.GetValueOrDefault(CounterKinds.PlusOnePlusOne));
    }

    [Fact]
    public void A_creature_that_needs_a_soulbonded_partner_may_attack_once_it_has_one()
    {
        // Flowering Lumberknot has no soulbond of its own: it consults the status from outside,
        // and the qualifier - "a creature with soulbond" - is answered off the partner's
        // computed keywords.
        var knot = Card(
            "Flowering Lumberknot",
            "This creature can't attack or block unless it's paired with a creature with soulbond.",
            CardType.Creature,
            5,
            5);

        var compiled = CardCompiler.Compile(knot);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var trunk = game.Create(alice, knot, Zone.Battlefield);

        PassTo(game, 3, TurnStep.PrecombatMain);
        Assert.NotNull(CombatRules.CannotAttack(
            game.State, Pool, game.State.GetObject(trunk), alice, bob));

        var flier = game.Create(alice, Wingcrafter(), Zone.Battlefield);
        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.Soulbond });
        game.Choose(alice, [trunk.Value.ToString("N")]);
        Settle(game);

        // Paired with a soulbond creature: the restriction lifts, and the bond's own payoff
        // reaches the Lumberknot too.
        Assert.Null(CombatRules.CannotAttack(
            game.State, Pool, game.State.GetObject(trunk), alice, bob));
        Assert.True(Characteristics.Of(game.State, Pool, game.State.GetObject(trunk))
            .Has(KeywordAbility.Flying));
    }

    [Fact]
    public void A_spell_that_consults_the_pairing_reaches_the_partner()
    {
        // Joint Assault, the one spell that reads the status: the partner's bonus rides on the
        // pairing as the spell resolves. The partner is not a second target - nothing about it
        // was chosen - and a target with no partner is simply pumped alone.
        var assault = Card(
            "Joint Assault",
            "Target creature gets +2/+2 until end of turn. If it's paired with a creature, that "
                + "creature also gets +2/+2 until end of turn.");

        var compiled = CardCompiler.Compile(assault);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var flier = game.Create(alice, Wingcrafter(), Zone.Battlefield);
        var friend = game.Create(alice, TestCards.Creature("Charging Friend Test", 2, 2), Zone.Battlefield);

        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.Soulbond });
        game.Choose(alice, [friend.Value.ToString("N")]);
        Settle(game);

        // Arriving beside an already-paired soulbond creature asks nothing (CR 702.95a).
        var bystander = game.Create(alice, TestCards.Creature("Bystander Bear Test", 2, 2), Zone.Battlefield);
        Settle(game);
        Assert.Single(game.Log.OfType<SoulbondPairRequested>());

        TestCards.PassUntil(game, () => game.State.IsSorcerySpeedFor(alice));
        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, assault), [Target.ToPermanent(friend)]);
        Settle(game);

        // The target and its partner, and nobody else.
        Assert.Equal(4, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(friend)));
        Assert.Equal(3, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(flier)));
        Assert.Equal(2, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(bystander)));
    }

    [Fact]
    public void The_soulbond_shelf_compiles_exactly_as_measured()
    {
        // Every printing that mentions the pairing, compiled from its real wording, with the
        // complete set pinned so the round's claim stays measured. The keyword line itself must
        // read on every card that prints it - an incomplete card here is short somewhere else.
        var shelf = new (string Name, string Text, CardType Types, KeywordAbility Keywords)[]
        {
            ("Wingcrafter", "Soulbond" + SoulbondReminder + "\nAs long as this creature is paired with another creature, both creatures have flying.", CardType.Creature, KeywordAbility.Soulbond),
            ("Nearheath Pilgrim", "Soulbond" + SoulbondReminder + "\nAs long as this creature is paired with another creature, both creatures have lifelink.", CardType.Creature, KeywordAbility.Soulbond),
            ("Spectral Gateguards", "Soulbond" + SoulbondReminder + "\nAs long as this creature is paired with another creature, both creatures have vigilance.", CardType.Creature, KeywordAbility.Soulbond),
            ("Hanweir Lancer", "Soulbond" + SoulbondReminder + "\nAs long as this creature is paired with another creature, both creatures have first strike.", CardType.Creature, KeywordAbility.Soulbond),
            ("Lightning Mauler", "Soulbond" + SoulbondReminder + "\nAs long as this creature is paired with another creature, both creatures have haste.", CardType.Creature, KeywordAbility.Soulbond),
            ("Geist Trappers", "Soulbond" + SoulbondReminder + "\nAs long as this creature is paired with another creature, both creatures have reach.", CardType.Creature, KeywordAbility.Soulbond),
            ("Elgaud Shieldmate", "Soulbond" + SoulbondReminder + "\nAs long as this creature is paired with another creature, both creatures have hexproof. (They can't be the targets of spells or abilities your opponents control.)", CardType.Creature, KeywordAbility.Soulbond),
            ("Pathbreaker Wurm", "Soulbond" + SoulbondReminder + "\nAs long as this creature is paired with another creature, both creatures have trample.", CardType.Creature, KeywordAbility.Soulbond),
            ("Nightshade Peddler", "Soulbond" + SoulbondReminder + "\nAs long as this creature is paired with another creature, both creatures have deathtouch.", CardType.Creature, KeywordAbility.Soulbond),
            ("Silverblade Paladin", "Soulbond" + SoulbondReminder + "\nAs long as this creature is paired with another creature, both creatures have double strike.", CardType.Creature, KeywordAbility.Soulbond),
            ("Diregraf Escort", "Soulbond" + SoulbondReminder + "\nAs long as this creature is paired with another creature, both creatures have protection from Zombies.", CardType.Creature, KeywordAbility.Soulbond),
            ("Trusted Forcemage", "Soulbond" + SoulbondReminder + "\nAs long as this creature is paired with another creature, each of those creatures gets +1/+1.", CardType.Creature, KeywordAbility.Soulbond),
            ("Druid's Familiar", "Soulbond" + SoulbondReminder + "\nAs long as this creature is paired with another creature, each of those creatures gets +2/+2.", CardType.Creature, KeywordAbility.Soulbond),
            ("Wolfir Silverheart", "Soulbond" + SoulbondReminder + "\nAs long as this creature is paired with another creature, each of those creatures gets +4/+4.", CardType.Creature, KeywordAbility.Soulbond),
            ("Stonewright", "Soulbond" + SoulbondReminder + "\nAs long as Stonewright is paired with another creature, each of those creatures has \"{R}: This creature gets +1/+0 until end of turn.\"", CardType.Creature, KeywordAbility.Soulbond),
            ("Galvanic Alchemist", "Soulbond" + SoulbondReminder + "\nAs long as this creature is paired with another creature, each of those creatures has \"{2}{U}: Untap this creature.\"", CardType.Creature, KeywordAbility.Soulbond),
            ("Stern Mentor", "Soulbond" + SoulbondReminder + "\nAs long as this creature is paired with another creature, each of those creatures has \"{T}: Target player mills two cards.\"", CardType.Creature, KeywordAbility.Soulbond),
            ("Thundering Mightmare", "Soulbond" + SoulbondReminder + "\nAs long as Thundering Mightmare is paired with another creature, each of those creatures has \"Whenever an opponent casts a spell, put a +1/+1 counter on this creature.\"", CardType.Creature, KeywordAbility.Soulbond),
            ("Tandem Lookout", "Soulbond" + SoulbondReminder + "\nAs long as Tandem Lookout is paired with another creature, each of those creatures has \"Whenever this creature deals damage to an opponent, draw a card.\"", CardType.Creature, KeywordAbility.Soulbond),
            ("Doom Weaver", "Reach\nSoulbond" + SoulbondReminder + "\nAs long as Doom Weaver is paired with another creature, each of those creatures has \"When this creature dies, draw cards equal to its power.\"", CardType.Creature, KeywordAbility.Reach | KeywordAbility.Soulbond),
            ("Imperious Mindbreaker", "Soulbond" + SoulbondReminder + "\nAs long as Imperious Mindbreaker is paired with another creature, each of those creatures has \"Whenever this creature attacks, each opponent mills cards equal to its toughness.\"", CardType.Creature, KeywordAbility.Soulbond),
            ("Deadeye Navigator", "Soulbond" + SoulbondReminder + "\nAs long as Deadeye Navigator is paired with another creature, each of those creatures has \"{1}{U}: Exile this creature, then return it to the battlefield under your control.\"", CardType.Creature, KeywordAbility.Soulbond),
            ("Breathkeeper Seraph", "Flying, soulbond" + SoulbondReminder + "\nAs long as Breathkeeper Seraph is paired with another creature, each of those creatures has \"When this creature dies, you may return it to the battlefield under its owner's control at the beginning of your next upkeep.\"", CardType.Creature, KeywordAbility.Flying | KeywordAbility.Soulbond),
            ("Mirage Phalanx", "Soulbond" + SoulbondReminder + "\nAs long as Mirage Phalanx is paired with another creature, each of those creatures has \"At the beginning of combat on your turn, create a token that's a copy of this creature, except it has haste and loses soulbond. Exile it at end of combat.\"", CardType.Creature, KeywordAbility.Soulbond),
            ("Donna Noble", "Soulbond" + SoulbondReminder + "\nWhenever Donna Noble or a creature it's paired with is dealt damage, Donna Noble deals that much damage to target opponent.\nDoctor's companion (You can have two commanders if the other is the Doctor.)", CardType.Creature, KeywordAbility.Soulbond),
            ("Flowering Lumberknot", "This creature can't attack or block unless it's paired with a creature with soulbond.", CardType.Creature, KeywordAbility.None),
            ("Joint Assault", "Target creature gets +2/+2 until end of turn. If it's paired with a creature, that creature also gets +2/+2 until end of turn.", CardType.Instant, KeywordAbility.None),
        };

        var complete = new List<string>();
        var blocked = new List<string>();

        foreach (var (name, text, types, keywords) in shelf)
        {
            var compiled = CardCompiler.Compile(Card(name, text, types, 2, 2, keywords));

            if (compiled.IsComplete)
                complete.Add(name);
            else
                blocked.Add(name + " -> " + string.Join(" ;; ", compiled.Unhandled));

            // The keyword line always reads; what stops an incomplete card is its other lines.
            Assert.DoesNotContain(
                compiled.Unhandled,
                line => line is "Soulbond" or "Flying, soulbond");
        }

        complete.Sort(StringComparer.Ordinal);

        // Not on the list, and why: Diregraf Escort grants protection from a creature type,
        // which no flag can carry; Doom Weaver and Imperious Mindbreaker count "cards equal to
        // its power/toughness" inside their quoted grants; Breathkeeper Seraph's grant is a
        // delayed return; Mirage Phalanx's is a token copy with exceptions; and Donna Noble's
        // trigger watches damage to either half. Each is short on that line alone - the
        // Soulbond line itself reads on all of them.
        List<string> expected =
        [
            "Deadeye Navigator",
            "Druid's Familiar",
            "Elgaud Shieldmate",
            "Flowering Lumberknot",
            "Galvanic Alchemist",
            "Geist Trappers",
            "Hanweir Lancer",
            "Joint Assault",
            "Lightning Mauler",
            "Nearheath Pilgrim",
            "Nightshade Peddler",
            "Pathbreaker Wurm",
            "Silverblade Paladin",
            "Spectral Gateguards",
            "Stern Mentor",
            "Stonewright",
            "Tandem Lookout",
            "Thundering Mightmare",
            "Trusted Forcemage",
            "Wingcrafter",
            "Wolfir Silverheart",
        ];

        Assert.True(
            expected.SequenceEqual(complete, StringComparer.Ordinal),
            "complete: " + string.Join(", ", complete) + "\n" + string.Join("\n", blocked));
    }

    [Fact]
    public void Granted_phasing_phases_the_host_out_on_its_controllers_untap()
    {
        // Teferi's Curse. The untap action already read the computed keyword (CR 702.26a) and
        // took everything attached along with its host (CR 702.26g); the one word "phasing"
        // was missing from the grantable vocabulary, so no granting line could reach any of it.
        var curse = Card(
            "Phase Curse Test",
            "Enchant permanent\nEnchanted permanent has phasing.",
            CardType.Enchantment,
            null,
            null,
            KeywordAbility.None,
            "Aura");

        var compiled = CardCompiler.Compile(curse);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var bear = game.Create(alice, TestCards.Creature("Phased Bear Test", 2, 2), Zone.Battlefield);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, curse), [Target.ToPermanent(bear)]);
        Settle(game);

        // Alice's next untap: out, and not on the battlefield while it is (CR 702.26c).
        PassTo(game, 3, TurnStep.Upkeep);
        Assert.True(game.State.PhasedOut.ContainsKey(bear));
        Assert.DoesNotContain(bear, game.State.Battlefield);

        // Her untap after that: back, still enchanted, so the cycle goes on (CR 702.26b).
        PassTo(game, 5, TurnStep.Upkeep);
        Assert.False(game.State.PhasedOut.ContainsKey(bear));
        Assert.Contains(bear, game.State.Battlefield);
    }

    // ---- A card name the player chooses (CR 201.4) ---------------------------

    /// <summary>Meddling Mage, printed as it is printed.</summary>
    /// <remarks>
    /// The real wording rather than a paraphrase, because the thing under test is whether the
    /// compiler reads what Wizards writes. Its two lines are the two halves of the whole family:
    /// a question asked as the permanent enters, and a static that refers to the answer.
    /// </remarks>
    private static CardDefinition MeddlingMage() => Card(
        "Meddling Mage Test",
        "As this creature enters, choose a nonland card name.\n"
            + "Spells with the chosen name can't be cast.",
        CardType.Creature,
        2,
        2);

    /// <summary>Answers the entry question with a name, and checks it was that question.</summary>
    private static void NameACard(Game game, Guid chooser, string name)
    {
        TestCards.PassUntil(
            game, () => game.State.Choice is { Kind: ChoiceKind.NameCharacteristic });

        var choice = game.State.Choice!;
        Assert.Contains(choice.Options, o => string.Equals(o.Id, name, StringComparison.Ordinal));

        game.Choose(chooser, [name]);
        Settle(game);
    }

    /// <summary>
    /// A named spell is actually refused, and a spell of another name is not (CR 601.3).
    /// </summary>
    /// <remarks>
    /// The headline of the family, played rather than asserted about: Alice names a card, Bob
    /// tries to cast one, and the engine refuses it at CR 601.3 before anything is spent. The
    /// second half is what stops the test passing for the wrong reason — a ban that refused
    /// <em>every</em> spell would satisfy the first assertion perfectly, and that is exactly the
    /// direction a prohibition built around a null fails in.
    /// <para>
    /// The name comes out of Alice's own hand because that is where the offer can legally find
    /// one: an option list is shown to the player who is choosing, so it is built from the public
    /// zones and the chooser's hand and never from anyone else's.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_chosen_name_refuses_that_spell_and_leaves_the_others_alone()
    {
        var mage = MeddlingMage();
        var compiled = CardCompiler.Compile(mage);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.Equal(ChoiceOnEntry.CardName, compiled.ChoosesOnEntry);
        Assert.Equal("nonland", compiled.ChosenNameFilter);

        var banned = TestCards.Costed("Named Bear Test", "{G}", 1);
        var allowed = TestCards.Costed("Unnamed Bear Test", "{G}", 1);

        var (game, alice, bob) = InMainPhase();
        TestCards.PutInHand(game, alice, banned);
        game.Create(alice, mage, Zone.Battlefield);

        NameACard(game, alice, banned.Name);

        // The answer is on the object, in the field a card name goes in — never in the one a
        // colour or a creature type goes in.
        var onBoard = game.State.Battlefield
            .Select(game.State.GetObject)
            .Single(o => string.Equals(o.Card.Name, mage.Name, StringComparison.Ordinal));

        Assert.Equal(banned.Name, onBoard.ChosenName);
        Assert.Null(onBoard.Chosen);

        PassToMainPhaseOf(game, bob);

        var theirs = TestCards.PutInHand(game, bob, banned);
        TapCompiledForest(game, bob, 1);
        Assert.Throws<InvalidOperationException>(() => game.CastSpell(bob, theirs, []));

        // Refused before anything moved: the card is still in hand and the mana is still in the
        // pool (CR 601.3 — a cast that is prohibited never begins).
        Assert.Equal(Zone.Hand, game.State.GetObject(theirs).Zone);
        Assert.False(game.State.GetPlayer(bob).ManaPool.IsEmpty);

        // And the other name goes through, on the same board, from the same hand, for the same
        // mana. Without this the test would pass just as well against a ban on everything.
        var other = TestCards.PutInHand(game, bob, allowed);
        game.CastSpell(bob, other, []);
        Settle(game);

        Assert.Contains(
            game.State.Battlefield,
            id => string.Equals(
                game.State.GetObject(id).Card.Name, allowed.Name, StringComparison.Ordinal));
    }

    /// <summary>
    /// A ban whose name was never chosen stops nothing (CR 201.4).
    /// </summary>
    /// <remarks>
    /// The arm the whole family turns on. <c>ChosenName</c> is null until the question has been
    /// answered, and null has to mean "this matches nothing"; read the other way round, a
    /// Meddling Mage on the battlefield would make every spell in the game uncastable and the
    /// bug would look like the card working.
    /// <para>
    /// The fixture is a permanent that prints the ban and nothing that ever names — which is a
    /// real reading, not a contrivance: a permanent whose choice was never offered, or an
    /// Alhammarret whose entry line this compiler still cannot read, is in exactly this state.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_ban_on_a_name_nobody_chose_forbids_nothing()
    {
        var mute = Card(
            "Unasked Name Ban Test",
            "Spells with the chosen name can't be cast.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(mute);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.Single(compiled.Bans.NoCastingNamed);
        Assert.Equal(ChoiceOnEntry.None, compiled.ChoosesOnEntry);

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, mute, Zone.Battlefield);
        Settle(game);

        // Nothing was ever asked, so nothing was ever named.
        Assert.All(
            game.State.Battlefield.Select(game.State.GetObject),
            o => Assert.Null(o.ChosenName));

        PassToMainPhaseOf(game, bob);

        var theirs = TestCards.PutInHand(
            game, bob, TestCards.Costed("Unbanned Bear Test", "{G}", 1));

        TapCompiledForest(game, bob, 1);
        game.CastSpell(bob, theirs, []);
        Settle(game);

        // By name, because a resolved spell is a new object (CR 400.7).
        Assert.Contains(
            game.State.Battlefield,
            id => string.Equals(
                game.State.GetObject(id).Card.Name,
                "Unbanned Bear Test",
                StringComparison.Ordinal));
    }

    /// <summary>
    /// Pithing Needle spares mana abilities and Phyrexian Revoker does not (CR 602.5, 605.1a).
    /// </summary>
    /// <remarks>
    /// Both cards print the same sentence and one of them prints five more words, and those five
    /// words are the whole difference between them. Read from the line rather than assumed in
    /// either direction: assume the exemption and the Revoker leaves mana rocks alone, assume its
    /// absence and the Needle turns off a Sol Ring.
    /// <para>
    /// The named permanent belongs to Bob and the naming permanent to Alice, so the ban is also
    /// shown reaching across the table — "sources with the chosen name" says nothing about who
    /// controls them.
    /// </para>
    /// </remarks>
    [Fact]
    public void The_needles_exemption_for_mana_abilities_is_read_and_the_revokers_absence_is_too()
    {
        var needle = Card(
            "Pithing Needle Test",
            "As this artifact enters, choose a card name.\n"
                + "Activated abilities of sources with the chosen name can't be activated "
                + "unless they're mana abilities.",
            CardType.Artifact);

        var revoker = Card(
            "Phyrexian Revoker Test",
            "As this creature enters, choose a nonland card name.\n"
                + "Activated abilities of sources with the chosen name can't be activated.",
            CardType.Creature,
            2,
            1);

        foreach (var card in new[] { needle, revoker })
        {
            var read = CardCompiler.Compile(card);
            Assert.True(read.IsComplete, card.Name + ": " + string.Join(" | ", read.Unhandled));
        }

        Assert.True(
            CardCompiler.Compile(needle).Bans.NoActivatingNamed.Single().ExceptManaAbilities);

        Assert.False(
            CardCompiler.Compile(revoker).Bans.NoActivatingNamed.Single().ExceptManaAbilities);

        // A permanent with a mana ability and a non-mana one, so the two halves of the exemption
        // are asked of the same card.
        var rock = Card(
            "Named Rock Test",
            "{T}: Add {C}.\n{2}, {T}: Draw a card.",
            CardType.Artifact);

        Assert.True(
            CardCompiler.Compile(rock).IsComplete,
            string.Join(" | ", CardCompiler.Compile(rock).Unhandled));

        var (game, alice, bob) = InMainPhase();
        TestCards.PutInHand(game, alice, rock);
        var theirs = game.Create(bob, rock, Zone.Battlefield);
        game.Create(alice, needle, Zone.Battlefield);

        NameACard(game, alice, rock.Name);

        var abilities = AbilitiesOn(game, theirs);
        var manaAbility = abilities.Single(a => a.IsManaAbility).Id;
        var drawAbility = abilities.Single(a => !a.IsManaAbility).Id;

        // The Needle: the draw is refused, the mana is not.
        Assert.Throws<InvalidOperationException>(
            () => game.ActivateAbility(bob, theirs, drawAbility));

        game.ActivateAbility(bob, theirs, manaAbility);
        Assert.False(game.State.GetPlayer(bob).ManaPool.IsEmpty);

        // The Revoker, on its own board, refuses the mana ability too.
        var (second, carol, dave) = InMainPhase();
        TestCards.PutInHand(second, carol, rock);
        var alsoTheirs = second.Create(dave, rock, Zone.Battlefield);
        second.Create(carol, revoker, Zone.Battlefield);

        NameACard(second, carol, rock.Name);

        var alsoMana = AbilitiesOn(second, alsoTheirs).Single(a => a.IsManaAbility).Id;

        Assert.Throws<InvalidOperationException>(
            () => second.ActivateAbility(dave, alsoTheirs, alsoMana));
    }

    /// <summary>The activated abilities the board would offer for one permanent.</summary>
    private static IReadOnlyList<ActivatedAbilityDefinition> AbilitiesOn(Game game, ObjectId id) =>
        Game.ActivatedAbilitiesOf(game.State, Pool, game.State.GetObject(id));

    /// <summary>
    /// "A nonland card name" is never offered a land, and "a card name" is (CR 201.4a).
    /// </summary>
    /// <remarks>
    /// The qualifier is the only thing standing between Meddling Mage and a Meddling Mage that
    /// can also name Island, and a card that may name more than it prints is a strictly better
    /// card than the printed one. Both directions are asserted, because a filter that refused
    /// everything would satisfy the first half alone.
    /// </remarks>
    [Fact]
    public void The_qualifier_on_a_chosen_name_narrows_what_may_be_named()
    {
        var land = TestCards.BasicLand("Nameable Forest Test");
        var spell = TestCards.Costed("Nameable Bear Test", "{G}", 1);

        var (game, alice, _) = InMainPhase();
        TestCards.PutInHand(game, alice, land);
        TestCards.PutInHand(game, alice, spell);
        game.Create(alice, MeddlingMage(), Zone.Battlefield);

        TestCards.PassUntil(
            game, () => game.State.Choice is { Kind: ChoiceKind.NameCharacteristic });

        var offered = game.State.Choice!.Options.Select(o => o.Id).ToList();
        Assert.Contains(spell.Name, offered, StringComparer.Ordinal);
        Assert.DoesNotContain(land.Name, offered, StringComparer.Ordinal);

        game.Choose(alice, [spell.Name]);
        Settle(game);

        // The unqualified spelling names anything, land included — Pithing Needle's wording.
        var needle = Card(
            "Any Name Needle Test",
            "As this artifact enters, choose a card name.\n"
                + "Activated abilities of sources with the chosen name can't be activated.",
            CardType.Artifact);

        Assert.Equal(SearchFilters.AnyCard, CardCompiler.Compile(needle).ChosenNameFilter);

        var (other, carol, _) = InMainPhase();
        TestCards.PutInHand(other, carol, land);
        other.Create(carol, needle, Zone.Battlefield);

        TestCards.PassUntil(
            other, () => other.State.Choice is { Kind: ChoiceKind.NameCharacteristic });

        Assert.Contains(
            other.State.Choice!.Options.Select(o => o.Id).ToList(),
            id => string.Equals(id, land.Name, StringComparison.Ordinal));
    }

    /// <summary>
    /// The names offered never come out of an opponent's hand (CR 201.4).
    /// </summary>
    /// <remarks>
    /// An option list is shown to the player choosing from it, so a list built by scanning every
    /// zone would hand a Meddling Mage's controller the contents of the opponent's hand. That is
    /// not a rounding error in the offer: Sorcerous Spyglass and Anointed Peacekeeper spend real
    /// card text on the words "look at an opponent's hand" before they name, and Meddling Mage
    /// does not. The engine's own rule is that hidden information is projected away rather than
    /// flagged, and an offer is one more place that has to hold.
    /// </remarks>
    [Fact]
    public void A_card_name_is_never_offered_from_an_opponents_hand()
    {
        var secret = TestCards.Costed("Hidden Hand Bear Test", "{G}", 1);
        var seen = TestCards.Costed("Own Hand Bear Test", "{G}", 1);

        var (game, alice, bob) = InMainPhase();
        TestCards.PutInHand(game, bob, secret);
        TestCards.PutInHand(game, alice, seen);
        game.Create(alice, MeddlingMage(), Zone.Battlefield);

        TestCards.PassUntil(
            game, () => game.State.Choice is { Kind: ChoiceKind.NameCharacteristic });

        var offered = game.State.Choice!.Options.Select(o => o.Id).ToList();
        Assert.Contains(seen.Name, offered, StringComparer.Ordinal);
        Assert.DoesNotContain(secret.Name, offered, StringComparer.Ordinal);
    }

    /// <summary>
    /// A tax written against the chosen name is paid by name (CR 601.2f).
    /// </summary>
    /// <remarks>
    /// Disruptor Flute's second line, and the reason the modifier carries a flag rather than a
    /// filter id: a card name is capitalised, and a capitalised word handed to the filter
    /// vocabulary is read as a <em>subtype</em>. "Named Bear Test" as a filter would tax cards
    /// with a creature type nothing has — a card that compiles, looks finished, and never
    /// changes a cost.
    /// </remarks>
    [Fact]
    public void A_tax_on_the_chosen_name_falls_on_that_card_and_no_other()
    {
        var flute = Card(
            "Disruptor Flute Test",
            "As this artifact enters, choose a card name.\n"
                + "Spells with the chosen name cost {2} more to cast.",
            CardType.Artifact);

        var compiled = CardCompiler.Compile(flute);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var modifier = Assert.Single(compiled.CostModifiers);
        Assert.True(modifier.ChosenName);
        Assert.Equal(2, modifier.Amount);
        Assert.Equal(CostChange.Increase, modifier.Change);

        var taxed = TestCards.Costed("Taxed Named Bear Test", "{G}", 1);
        var untaxed = TestCards.Costed("Untaxed Named Bear Test", "{G}", 1);

        var (game, alice, bob) = InMainPhase();
        TestCards.PutInHand(game, alice, taxed);
        game.Create(alice, flute, Zone.Battlefield);

        NameACard(game, alice, taxed.Name);
        PassToMainPhaseOf(game, bob);

        // {G} alone is no longer enough for the named card.
        var theirs = TestCards.PutInHand(game, bob, taxed);
        TapCompiledForest(game, bob, 1);
        Assert.Throws<InvalidOperationException>(() => game.CastSpell(bob, theirs, []));

        TapCompiledForest(game, bob, 2);
        game.CastSpell(bob, theirs, []);
        Assert.True(game.State.GetPlayer(bob).ManaPool.IsEmpty);
        Settle(game);

        // And a card of another name still costs what it prints.
        var other = TestCards.PutInHand(game, bob, untaxed);
        TapCompiledForest(game, bob, 1);
        game.CastSpell(bob, other, []);
        Assert.True(game.State.GetPlayer(bob).ManaPool.IsEmpty);
        Settle(game);
    }

    /// <summary>
    /// The answer survives a round trip through the log (CR 201.4).
    /// </summary>
    /// <remarks>
    /// A card name is a new field on the object and a new event carrying it, so it is a new way
    /// for the engine's founding invariant to break: a game rebuilt from its events has to equal
    /// the game that produced them. Through the serializer rather than only through the reducer,
    /// because a reducer that folds an event the writer cannot name is a game that replays
    /// perfectly in memory and loses the answer the moment it is stored.
    /// </remarks>
    [Fact]
    public void A_chosen_card_name_replays_out_of_a_written_log()
    {
        var banned = TestCards.Costed("Replayed Name Bear Test", "{G}", 1);

        var (game, alice, _) = InMainPhase();
        TestCards.PutInHand(game, alice, banned);
        game.Create(alice, MeddlingMage(), Zone.Battlefield);

        NameACard(game, alice, banned.Name);

        Assert.Contains(game.Log, e => e is NameChosen);
        Assert.Equal(
            game.State,
            GameReducer.Replay(EventLogSerializer.Read(EventLogSerializer.Write(game.Log))));
    }

    /// <summary>
    /// The printed cards this family reads, and the ones it still does not.
    /// </summary>
    /// <remarks>
    /// Real oracle text, so what is asserted is what Wizards prints rather than a paraphrase of
    /// it. The second list is the honest half: the census ranked "named" at 169 cards, and the
    /// cards whose <em>every</em> unread line is in this family measure 341 — but cutting the
    /// entry line alone from the corpus completes <strong>zero</strong> of them, because the
    /// question is never a card's only unread line. What the readers here are worth was measured
    /// by excision instead: the entry choice plus the cast ban is 2 cards, plus the activation
    /// ban is 5, plus the two cost cells is 8.
    /// <para>
    /// Declined, with what each is worth: <em>look at an opponent's hand, then choose any card
    /// name</em> (2 — Sorcerous Spyglass, Anointed Peacekeeper), because the offer would either
    /// need a second question naming which opponent or would show a multiplayer chooser every
    /// hand at the table, which is more than the card grants; <em>you have protection from the
    /// chosen card name</em> (1 — Runed Halo), a protection whose subject is a player and whose
    /// parameter is a name; <em>choose a card name, then search a player's graveyard, hand and
    /// library for cards with that name and exile them</em> (6 — Cranial Extraction and its
    /// kin), which needs a multi-zone search and a hand reveal before the name matters at all;
    /// and the literal-name families the same substring collects but this is not about —
    /// "conjure a card named X" (34) and the two-zone "search your library or graveyard for a
    /// card named X" (45).
    /// </para>
    /// </remarks>
    [Fact]
    public void The_printed_cards_that_choose_a_name_compile()
    {
        (string Name, string Text, CardType Types, KeywordAbility Keywords)[] shelf =
        [
            ("Meddling Mage", "As this creature enters, choose a nonland card name.\nSpells with the chosen name can't be cast.", CardType.Creature, KeywordAbility.None),
            ("Nevermore", "As this enchantment enters, choose a nonland card name.\nSpells with the chosen name can't be cast.", CardType.Enchantment, KeywordAbility.None),
            ("Voidstone Gargoyle", "Flying\nAs this creature enters, choose a nonland card name.\nSpells with the chosen name can't be cast.\nActivated abilities of sources with the chosen name can't be activated.", CardType.Creature, KeywordAbility.Flying),
            ("Pithing Needle", "As this artifact enters, choose a card name.\nActivated abilities of sources with the chosen name can't be activated unless they're mana abilities.", CardType.Artifact, KeywordAbility.None),
            ("Phyrexian Revoker", "As this creature enters, choose a nonland card name.\nActivated abilities of sources with the chosen name can't be activated.", CardType.Creature, KeywordAbility.None),
            ("Council of the Absolute", "As this creature enters, choose a noncreature, nonland card name.\nYour opponents can't cast spells with the chosen name.\nSpells with the chosen name you cast cost {2} less to cast.", CardType.Creature, KeywordAbility.None),
            ("Skyseer's Chariot", "Flying\nAs this Vehicle enters, choose a nonland card name.\nActivated abilities of sources with the chosen name cost {2} more to activate.\nCrew 2", CardType.Artifact, KeywordAbility.Flying),
            ("Disruptor Flute", "Flash\nAs this artifact enters, choose a card name.\nSpells with the chosen name cost {3} more to cast.\nActivated abilities of sources with the chosen name can't be activated unless they're mana abilities.", CardType.Artifact, KeywordAbility.Flash),
        ];

        var blocked = new List<string>();

        foreach (var (name, text, types, keywords) in shelf)
        {
            var compiled = CardCompiler.Compile(
                Card(name + " Shelf Test", text, types, 2, 2, keywords, "Vehicle"));

            if (!compiled.IsComplete)
            {
                blocked.Add(name + " -> " + string.Join(" ;; ", compiled.Unhandled));
                continue;
            }

            // Every one of them asks the question, and none of them asks for a characteristic.
            Assert.Equal(ChoiceOnEntry.CardName, compiled.ChoosesOnEntry);
            Assert.NotNull(compiled.ChosenNameFilter);
        }

        Assert.True(blocked.Count == 0, string.Join("\n", blocked));

        // The half that is still unread, asserted so it stays measured rather than remembered.
        (string Name, string Text, CardType Types)[] declined =
        [
            ("Sorcerous Spyglass", "As this artifact enters, look at an opponent's hand, then choose any card name.\nActivated abilities of sources with the chosen name can't be activated unless they're mana abilities.", CardType.Artifact),
            ("Runed Halo", "As this enchantment enters, choose a card name.\nYou have protection from the chosen card name.", CardType.Enchantment),
        ];

        foreach (var (name, text, types) in declined)
        {
            Assert.False(
                CardCompiler.Compile(Card(name + " Declined Test", text, types)).IsComplete,
                name + " now compiles — move it onto the shelf above.");
        }
    }

    // ---- Split cards (CR 709) ------------------------------------------------

    /// <summary>Two spells on one card, printed the way the real ones are.</summary>
    private static CardDefinition SplitCard() => new()
    {
        OracleId = "oracle-test-fire-ice",
        Name = "Test Blaze // Test Chill",
        ManaCostRaw = "{1}{R}",
        OracleText = "Test Blaze deals 2 damage to any target.",
        CardTypes = CardType.Instant,
        Faces =
        [
            new CardFace
            {
                Name = "Test Blaze",
                ManaCostRaw = "{1}{R}",
                TypeLine = "Instant",
                CardTypes = CardType.Instant,
                OracleText = "Test Blaze deals 2 damage to any target.",
            },
            new CardFace
            {
                Name = "Test Chill",
                ManaCostRaw = "{1}{U}",
                TypeLine = "Instant",
                CardTypes = CardType.Instant,
                OracleText = "You gain 4 life.",
            },
        ],
    };

    /// <summary>
    /// Casting a split card's second half runs that half, not the one printed first (CR 709.4).
    /// </summary>
    /// <remarks>
    /// The whole card is one object with two spells on it, and everything that resolves a spell
    /// looks its effects up from the card - so without recording which half was chosen, the
    /// second half resolves as the first. The life total and the untouched life total of the
    /// opponent are what tell the two apart: one deals damage and the other does not.
    /// </remarks>
    [Fact]
    public void Casting_the_second_half_of_a_split_card_runs_that_half()
    {
        var split = SplitCard();

        var compiled = CardCompiler.Compile(split);
        Assert.Equal(2, compiled.Halves.Count);

        var (game, alice, bob) = InMainPhase();
        var mine = game.State.GetPlayer(alice).Life;
        var theirs = game.State.GetPlayer(bob).Life;
        var card = TestCards.PutInHand(game, alice, split);

        for (var i = 0; i < 4; i++)
            game.AddMana(alice, ManaColor.Blue);

        game.CastSpell(alice, card, [], half: 1);
        Settle(game);

        Assert.Equal(mine + 4, game.State.GetPlayer(alice).Life);

        // Nobody was burned: the other half never ran.
        Assert.Equal(theirs, game.State.GetPlayer(bob).Life);

        // And it is a spell, so it is in the graveyard rather than on the battlefield.
        Assert.Contains(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Test Blaze // Test Chill");
    }

    /// <summary>
    /// A half that is a permanent resolves into one, and a half that is not does not.
    /// </summary>
    /// <remarks>
    /// Where a resolving spell goes was decided by asking whether the <em>card</em> is a
    /// permanent card. A card with two halves is whichever half is on the stack, and asking the
    /// card put an Adventure's creature onto the battlefield the moment its sorcery resolved.
    /// This is the same question asked of a split card, where the two halves can differ.
    /// </remarks>
    [Fact]
    public void A_permanent_half_resolves_into_a_permanent()
    {
        var split = new CardDefinition
        {
            OracleId = "oracle-test-split-permanent",
            Name = "Test Bolt // Test Bear",
            ManaCostRaw = "{R}",
            OracleText = "Test Bolt deals 2 damage to any target.",
            CardTypes = CardType.Instant,
            Faces =
            [
                new CardFace
                {
                    Name = "Test Bolt",
                    ManaCostRaw = "{R}",
                    TypeLine = "Instant",
                    CardTypes = CardType.Instant,
                    OracleText = "Test Bolt deals 2 damage to any target.",
                },
                new CardFace
                {
                    Name = "Test Bear",
                    ManaCostRaw = "{1}{G}",
                    TypeLine = "Creature \u2014 Bear",
                    CardTypes = CardType.Creature,
                    Subtypes = ["Bear"],
                    OracleText = string.Empty,
                    Power = 2,
                    Toughness = 2,
                },
            ],
        };

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, split);

        for (var i = 0; i < 4; i++)
            game.AddMana(alice, ManaColor.Green);

        game.CastSpell(alice, card, [], half: 1);
        Settle(game);

        Assert.Contains(
            game.State.Battlefield,
            id => game.State.GetObject(id).Card.Name == "Test Bolt // Test Bear");
    }
    // ---- Seek, a tutor whose card the player does not get to choose ----------

    /// <summary>
    /// A game in its first main phase with a chosen seed, so a random outcome can be varied.
    /// </summary>
    /// <remarks>
    /// <see cref="InMainPhase"/> fixes the seed at 1, which is exactly right for every test that
    /// wants a repeatable board and useless for the one question seeking raises: whether the card
    /// it takes is picked or chosen. One seed cannot tell a random pick from "the first match".
    /// </remarks>
    private static (Game Game, Guid Alice) InMainPhaseSeeded(int seed)
    {
        var alice = Guid.Parse("11111111-1111-1111-1111-111111111111");
        var bob = Guid.Parse("22222222-2222-2222-2222-222222222222");
        var game = Game.Start(
            Guid.NewGuid(),
            [
                new PlayerSetup(alice, "Alice", 20, TestCards.Deck(40, "Alice")),
                new PlayerSetup(bob, "Bob", 20, TestCards.Deck(40, "Bob")),
            ],
            new GameRandom(seed),
            startingPlayerId: alice,
            abilities: Pool);

        game.BeginPlay(withMulligans: false);
        TestCards.PassToStep(game, TurnStep.PrecombatMain);
        return (game, alice);
    }

    [Fact]
    public void A_seek_takes_a_matching_card_out_of_the_library()
    {
        // Skyshroud Lookout's wording, with a card type the forty-card test deck cannot supply,
        // so the card that arrives can only be the planted one.
        var lookout = Card(
            "Seek Herald Test",
            "When this creature enters, seek a land card.",
            CardType.Creature,
            2,
            2);

        var (game, alice, _) = InMainPhase();
        game.Create(alice, TestCards.BasicLand("Seekable Forest Test"), Zone.Library);
        var before = game.State.GetPlayer(alice).Library.Count;

        var card = TestCards.PutInHand(game, alice, lookout);
        game.CastSpell(alice, card);
        Settle(game);

        Assert.Contains(
            game.State.GetPlayer(alice).Hand,
            id => game.State.GetObject(id).Card.Name == "Seekable Forest Test");
        Assert.Equal(before - 1, game.State.GetPlayer(alice).Library.Count);
    }

    /// <summary>
    /// Seeking leaves the library in the order it found it, and the search beside it does not.
    /// </summary>
    /// <remarks>
    /// This is one of the two things that separate the two mechanics, and the reason the effect
    /// is its own rather than a flag on the search: a search shuffles when it is done
    /// (CR 701.23e) and a seek must not, or every card that seeks quietly gains a side effect it
    /// does not print.
    /// <para>
    /// The search half is here as a control rather than for its own sake. A new reader placed
    /// beside an existing one can claim its wording and then refuse it, which takes the line off
    /// the neighbour while the coverage total still rises - so the neighbour's own wording is
    /// played in the same test that plays the new one.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_seek_leaves_the_library_in_order_where_a_search_shuffles_it()
    {
        var seeker = Card(
            "Seek Quiet Test",
            "When this creature enters, seek a land card.",
            CardType.Creature,
            2,
            2);

        var searcher = Card(
            "Seek Neighbour Test",
            "When this creature enters, search your library for a land card, "
                + "put it into your hand, then shuffle.",
            CardType.Creature,
            2,
            2);

        var untouched = OrderedTestDeck();

        Assert.Equal(
            untouched,
            RestOfLibraryAfter(seeker, "Seekable Quiet Forest Test", out var soughtQuietly));

        Assert.True(soughtQuietly, "the seek did not find the land it was planted for.");

        Assert.NotEqual(
            untouched,
            RestOfLibraryAfter(searcher, "Seekable Noisy Forest Test", out var searchedOut));

        Assert.True(
            searchedOut, "the search beside it stopped finding the land - its line was eaten.");
    }

    /// <summary>The library's remaining cards, in order, once a fetcher has taken its land.</summary>
    private static List<string> RestOfLibraryAfter(
        CardDefinition fetcher, string landName, out bool found)
    {
        var (game, alice, _) = InMainPhase();
        game.Create(alice, TestCards.BasicLand(landName), Zone.Library);

        var card = TestCards.PutInHand(game, alice, fetcher);
        game.CastSpell(alice, card);
        Settle(game);

        found = game.State.GetPlayer(alice).Hand
            .Any(id => game.State.GetObject(id).Card.Name == landName);

        return
        [
            .. game.State.GetPlayer(alice).Library
                .Select(id => game.State.GetObject(id).Card.Name)
                .Where(name => name != landName),
        ];
    }

    /// <summary>
    /// The forty-card test deck in the order the opening of a game leaves it, which is the order
    /// a library nothing has shuffled still has.
    /// </summary>
    private static List<string> OrderedTestDeck()
    {
        var (game, alice, _) = InMainPhase();
        return
        [
            .. game.State.GetPlayer(alice).Library
                .Select(id => game.State.GetObject(id).Card.Name),
        ];
    }

    /// <summary>
    /// The card a seek takes is picked by the game, not chosen by its controller.
    /// </summary>
    /// <remarks>
    /// The assertion that can tell those apart is variation across seeds. A choice would be
    /// answered the same way every time by the harness - which takes the first option - and "the
    /// first match in the library" would answer the same way too, so a single game proves
    /// neither. Reading a seek as a search is the one misreading that matters here: it would hand
    /// the player the pick of their library, which is a strictly better card than the printed one.
    /// </remarks>
    [Fact]
    public void A_seek_picks_at_random_rather_than_letting_its_controller_choose()
    {
        var lottery = Card(
            "Seek Lottery Test",
            "When this creature enters, seek a land card.",
            CardType.Creature,
            2,
            2);

        string[] planted =
        [
            "Seekable Plains Test",
            "Seekable Island Test",
            "Seekable Swamp Test",
            "Seekable Waste Test",
        ];

        var taken = new HashSet<string>(StringComparer.Ordinal);

        for (var seed = 1; seed <= 8; seed++)
        {
            var (game, alice) = InMainPhaseSeeded(seed);

            foreach (var name in planted)
                game.Create(alice, TestCards.BasicLand(name), Zone.Library);

            var card = TestCards.PutInHand(game, alice, lottery);
            game.CastSpell(alice, card);
            Settle(game);

            taken.UnionWith(game.State.GetPlayer(alice).Hand
                .Select(id => game.State.GetObject(id).Card.Name)
                .Where(planted.Contains));
        }

        Assert.True(
            taken.Count > 1,
            "every seed took the same card, so the pick is not random: "
                + string.Join(", ", taken));
    }

    [Fact]
    public void A_seek_can_put_what_it_finds_onto_the_battlefield_tapped()
    {
        // Spirited Simulacrum's wording, which is what took that card from unread to complete.
        var simulacrum = Card(
            "Seek Grounded Test",
            "When this creature enters, seek a land card and put it onto the battlefield tapped.",
            CardType.Creature,
            2,
            2);

        var (game, alice, _) = InMainPhase();
        game.Create(alice, TestCards.BasicLand("Seekable Tapped Forest Test"), Zone.Library);

        var card = TestCards.PutInHand(game, alice, simulacrum);
        game.CastSpell(alice, card);
        Settle(game);

        var landed = Assert.Single(
            game.State.Battlefield,
            id => game.State.GetObject(id).Card.Name == "Seekable Tapped Forest Test");

        Assert.True(
            game.State.GetObject(landed).Permanent?.IsTapped,
            "the land arrived untapped, and the card says tapped.");
    }

    /// <summary>
    /// A seek finds only what the card describes, and finding nothing is not a failure.
    /// </summary>
    /// <remarks>
    /// Both halves in one test because each is worth little without the other: a seek that finds
    /// nothing looks identical to a seek that never ran, so the same card is played twice - once
    /// against a library nothing in which answers its description, and once against one where a
    /// planted card does.
    /// </remarks>
    [Fact]
    public void A_seek_finds_only_what_the_card_describes()
    {
        var picky = Card(
            "Seek Picky Test",
            "When this creature enters, seek an artifact card.",
            CardType.Creature,
            2,
            2);

        var (game, alice, _) = InMainPhase();

        // Everything in the deck, and the planted card, is a creature or a land, so nothing
        // answers to "artifact" yet.
        game.Create(alice, TestCards.BasicLand("Seekable Ignored Forest Test"), Zone.Library);
        var library = game.State.GetPlayer(alice).Library.Count;
        var hand = game.State.GetPlayer(alice).Hand.Count;

        var first = TestCards.PutInHand(game, alice, picky);
        game.CastSpell(alice, first);
        Settle(game);

        Assert.Equal(library, game.State.GetPlayer(alice).Library.Count);
        Assert.Equal(hand, game.State.GetPlayer(alice).Hand.Count);

        // The same card again, now that the library holds something that does answer.
        game.Create(alice, Card("Seekable Relic Test", string.Empty, CardType.Artifact), Zone.Library);

        var second = TestCards.PutInHand(game, alice, picky);
        game.CastSpell(alice, second);
        Settle(game);

        Assert.Contains(
            game.State.GetPlayer(alice).Hand,
            id => game.State.GetObject(id).Card.Name == "Seekable Relic Test");
    }

    /// <summary>
    /// A seek can be an activated ability, can take more than one card, and is bound by the mana
    /// value its card names.
    /// </summary>
    /// <remarks>
    /// The ceiling is the half worth playing rather than reading. A seek that ignored the mana
    /// value its card prints would fetch anything, which is the failure this whole file exists to
    /// catch: a card that compiles perfectly and plays as a better card than the printed one.
    /// </remarks>
    [Fact]
    public void A_seek_takes_the_number_it_names_and_obeys_the_mana_value_it_names()
    {
        var engine = Card(
            "Seek Twice Test",
            "{T}: Seek two artifact cards with mana value 2 or less.",
            CardType.Artifact);

        var (game, alice, _) = InMainPhase();
        var dear = new CardDefinition
        {
            OracleId = "oracle-seekable-dear-relic-test",
            Name = "Seekable Dear Relic Test",
            CardTypes = CardType.Artifact,
            ManaCostRaw = "{5}",
            Cmc = 5,
        };

        game.Create(alice, Card("Seekable Cheap Relic Test", string.Empty, CardType.Artifact), Zone.Library);
        game.Create(alice, Card("Seekable Second Relic Test", string.Empty, CardType.Artifact), Zone.Library);
        game.Create(alice, dear, Zone.Library);

        var permanent = game.Create(alice, engine, Zone.Battlefield);
        game.ActivateAbility(alice, permanent, "a");
        Settle(game);

        var held = game.State.GetPlayer(alice).Hand
            .Select(id => game.State.GetObject(id).Card.Name)
            .ToList();

        Assert.Contains("Seekable Cheap Relic Test", held);
        Assert.Contains("Seekable Second Relic Test", held);

        // The dear one answers every word of the description except the ceiling.
        Assert.DoesNotContain("Seekable Dear Relic Test", held);
    }

    // ---- Cleave, gift, and the bracket rule (CR 702.148, 702.174) ------------

    /// <summary>
    /// A line containing square brackets that no cleave-aware reader claimed is refused, not
    /// silently read without its brackets.
    /// </summary>
    /// <remarks>
    /// Before the guard, this exact sentence compiled as the flier-less draw — a card read
    /// <em>better</em> than printed, which is the one class of error the fail-closed rule
    /// exists to prevent. Nothing playable was affected only because every bracketed line sat
    /// on an incomplete card; that was luck, and this assertion is the lock.
    /// </remarks>
    [Fact]
    public void A_bracketed_line_is_refused_rather_than_read_without_its_brackets()
    {
        var sneaky = Card(
            "Bracket Refusal Test",
            "Draw a card for each creature you control [with flying].");

        var compiled = CardCompiler.Compile(sneaky);

        Assert.False(compiled.IsComplete);
        Assert.Contains(compiled.Unhandled, l => l.Contains("[with flying]", StringComparison.Ordinal));
        Assert.Null(compiled.Spell);
    }

    /// <summary>
    /// A cleave card carries two readings, and the one that resolves is the one that was paid
    /// for (CR 702.148a).
    /// </summary>
    /// <remarks>
    /// Winged Portent's wording, with a board built so the two readings must answer
    /// differently: one flier among two creatures, so the printed reading draws one card and
    /// the cleaved reading draws two. The middle refusal is the cost half of the rule — cleave
    /// is an alternative cost, and the printed mana must not buy the cleaved text.
    /// </remarks>
    [Fact]
    public void A_cleave_card_resolves_the_reading_that_was_paid_for()
    {
        var portent = new CardDefinition
        {
            OracleId = "oracle-cleave-portent-test",
            Name = "Cleave Portent Test",
            ManaCostRaw = "{1}{U}{U}",
            Cmc = 3,
            CardTypes = CardType.Instant,
            OracleText =
                "Cleave {4}{G}{U} (You may cast this spell for its cleave cost. If you do, "
                + "remove the words in square brackets.)\n"
                + "Draw a card for each creature you control [with flying].",
        };

        var compiled = CardCompiler.Compile(portent);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.NotNull(compiled.CleaveSpell);
        Assert.Equal("{4}{G}{U}", compiled.CleaveCostRaw);

        var (game, alice, _) = InMainPhase();
        game.Create(alice, TestCards.Creature("Cleave Grounded Bear Test", 2, 2), Zone.Battlefield);
        game.Create(
            alice,
            Card("Cleave Flier Test", string.Empty, CardType.Creature, 1, 1, KeywordAbility.Flying),
            Zone.Battlefield);

        // Printed, the words in brackets are on the card: only the flier counts.
        var printedCast = TestCards.PutInHand(game, alice, portent);
        game.AddMana(alice, ManaColor.Blue, 3);
        var before = game.State.GetPlayer(alice).Hand.Count;
        game.CastSpell(alice, printedCast);
        Settle(game);

        Assert.Equal(before, game.State.GetPlayer(alice).Hand.Count);

        // The printed mana does not buy the cleaved reading: cleave replaces the cost.
        var cleavedCast = TestCards.PutInHand(game, alice, portent);
        game.AddMana(alice, ManaColor.Blue, 3);
        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, cleavedCast, cleaved: true));

        // Paid for, the bracketed words come off and every creature counts.
        game.AddMana(alice, ManaColor.Green, 5);
        before = game.State.GetPlayer(alice).Hand.Count;
        game.CastSpell(alice, cleavedCast, cleaved: true);
        Settle(game);

        Assert.Equal(before + 1, game.State.GetPlayer(alice).Hand.Count);
    }

    /// <summary>
    /// The chosen reading decides what the spell may even target (CR 702.148a, 601.2c).
    /// </summary>
    /// <remarks>
    /// Fierce Retribution's wording. "Destroy target [attacking] creature" printed takes only
    /// an attacker, so aiming it at an idle creature is refused at cast — and the same aim is
    /// legal the moment the cleave cost removes the word. A swap that only reached the effects
    /// would pass the first half of this test and fail the second.
    /// </remarks>
    [Fact]
    public void The_reading_chooses_what_a_cleave_card_may_target()
    {
        var retribution = new CardDefinition
        {
            OracleId = "oracle-cleave-retribution-test",
            Name = "Cleave Retribution Test",
            ManaCostRaw = "{1}{W}",
            Cmc = 2,
            CardTypes = CardType.Instant,
            OracleText =
                "Cleave {5}{W} (You may cast this spell for its cleave cost. If you do, "
                + "remove the words in square brackets.)\n"
                + "Destroy target [attacking] creature.",
        };

        var compiled = CardCompiler.Compile(retribution);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var idler = game.Create(bob, TestCards.Creature("Cleave Idler Test", 3, 3), Zone.Battlefield);
        var card = TestCards.PutInHand(game, alice, retribution);

        // Printed, the spell wants an attacking creature and the idler is not one.
        game.AddMana(alice, ManaColor.White, 2);
        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, card, [Target.ToPermanent(idler)]));

        // Cleaved, "attacking" is one of the removed words.
        game.AddMana(alice, ManaColor.White, 4);
        game.CastSpell(alice, card, [Target.ToPermanent(idler)], cleaved: true);
        Settle(game);

        Assert.DoesNotContain(idler, game.State.Battlefield);
        Assert.Contains(
            game.State.GetPlayer(bob).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Cleave Idler Test");
    }

    /// <summary>
    /// A cleave card either of whose readings has an unreadable line stays unread, and reports
    /// only the sentence that actually blocks it.
    /// </summary>
    /// <remarks>
    /// Wash Away's wording: the cleaved reading is a plain counterspell the compiler knows,
    /// and the printed reading's "wasn't cast from its owner's hand" is not yet vocabulary.
    /// Shipping the readable half would sell a strictly smaller card as the printed one, so
    /// the whole card refuses — with no <see cref="CompiledCard.CleaveSpell"/> for a cast to
    /// reach past the deck gate.
    /// </remarks>
    [Fact]
    public void A_cleave_card_with_an_unreadable_reading_stays_unread()
    {
        var washAway = new CardDefinition
        {
            OracleId = "oracle-cleave-wash-test",
            Name = "Cleave Wash Test",
            ManaCostRaw = "{U}",
            Cmc = 1,
            CardTypes = CardType.Instant,
            OracleText =
                "Cleave {1}{U}{U} (You may cast this spell for its cleave cost. If you do, "
                + "remove the words in square brackets.)\n"
                + "Counter target spell [that wasn't cast from its owner's hand].",
        };

        var compiled = CardCompiler.Compile(washAway);

        Assert.False(compiled.IsComplete);
        Assert.Null(compiled.CleaveSpell);

        var blocker = Assert.Single(compiled.Unhandled);
        Assert.Contains("wasn't cast from its owner's hand", blocker, StringComparison.Ordinal);
    }

    /// <summary>
    /// A promised gift swaps in the promised reading, and the present is delivered before the
    /// spell's own effects (CR 702.174j, 702.174m).
    /// </summary>
    /// <remarks>
    /// Into the Flood Maw's wording, whose two readings take different targets: unpromised it
    /// bounces only a creature, promised any nonland permanent. Aiming the unpromised cast at
    /// an artifact is refused — CR 702.174m says those targets exist only if the gift was
    /// promised — and the promised cast bounces it while the chosen opponent's Fish arrives
    /// tapped, and arrives <em>first</em>.
    /// </remarks>
    [Fact]
    public void A_promised_gift_delivers_first_and_swaps_in_the_promised_reading()
    {
        var maw = new CardDefinition
        {
            OracleId = "oracle-gift-maw-test",
            Name = "Gift Maw Test",
            ManaCostRaw = "{U}",
            Cmc = 1,
            CardTypes = CardType.Instant,
            OracleText =
                "Gift a tapped Fish (You may promise an opponent a gift as you cast this "
                + "spell. If you do, they create a tapped 1/1 blue Fish creature token before "
                + "its other effects.)\n"
                + "Return target creature an opponent controls to its owner's hand. If the "
                + "gift was promised, instead return target nonland permanent an opponent "
                + "controls to its owner's hand.",
        };

        var compiled = CardCompiler.Compile(maw);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.True(compiled.HasGift);
        Assert.NotNull(compiled.GiftSpell);

        var (game, alice, bob) = InMainPhase();
        var relic = game.Create(
            bob, Card("Gift Relic Test", string.Empty, CardType.Artifact), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, maw);
        game.AddMana(alice, ManaColor.Blue);

        // Unpromised, the spell takes only a creature (CR 702.174m).
        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, card, [Target.ToPermanent(relic)]));

        var handBefore = game.State.GetPlayer(bob).Hand.Count;
        game.CastSpell(alice, card, [Target.ToPermanent(relic)], giftTo: bob);
        Settle(game);

        // The artifact went home, and the present arrived - tapped, Bob's, and 1/1.
        Assert.Equal(handBefore + 1, game.State.GetPlayer(bob).Hand.Count);

        var fish = Assert.Single(
            game.State.Battlefield,
            id => game.State.GetObject(id).Card.Subtypes.Contains("Fish", StringComparer.Ordinal));
        var present = game.State.GetObject(fish);
        Assert.Equal(bob, present.ControllerId);
        Assert.True(present.Permanent?.IsTapped);
        Assert.Equal(1, present.Card.Power);
        Assert.Equal(1, present.Card.Toughness);

        // CR 702.174j: the gift happens before any other spell ability - so the Fish was
        // created before the artifact left the battlefield.
        var log = game.Log.ToList();
        var delivered = log.FindIndex(e => e is ObjectCreated made && made.Id == fish);
        var bounced = log.FindIndex(e =>
            e is ObjectMoved moved && moved.From == Zone.Battlefield && moved.To == Zone.Hand);

        Assert.True(delivered >= 0 && bounced >= 0);
        Assert.True(
            delivered < bounced,
            "the spell's own effect resolved before the gift was delivered (CR 702.174j).");
    }

    /// <summary>
    /// Declining the gift is what costs, and a promise names one opponent at a table of three
    /// (CR 702.174a-b).
    /// </summary>
    /// <remarks>
    /// Nocturnal Hunger's wording. Unpromised, the rider "if the gift wasn't promised, you
    /// lose 2 life" fires; promised, it does not, and only the opponent chosen at cast gets
    /// the Food — who receives is a cast-time choice, not "an opponent" resolved later. The
    /// two refusals pin the promise down as a real cost declaration: no promising yourself,
    /// and no promising on a card that offers nothing.
    /// </remarks>
    [Fact]
    public void Declining_the_gift_costs_and_a_promise_names_one_opponent()
    {
        var hunger = new CardDefinition
        {
            OracleId = "oracle-gift-hunger-test",
            Name = "Gift Hunger Test",
            ManaCostRaw = "{2}{B}",
            Cmc = 3,
            CardTypes = CardType.Instant,
            OracleText =
                "Gift a Food (You may promise an opponent a gift as you cast this spell. If "
                + "you do, they create a Food token before its other effects. It's an artifact "
                + "with \"{2}, {T}, Sacrifice this token: You gain 3 life.\")\n"
                + "Destroy target creature. If the gift wasn't promised, you lose 2 life.",
        };

        var compiled = CardCompiler.Compile(hunger);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var alice = Guid.Parse("11111111-1111-1111-1111-111111111111");
        var bob = Guid.Parse("22222222-2222-2222-2222-222222222222");
        var carol = Guid.Parse("33333333-3333-3333-3333-333333333333");

        var game = Game.Start(
            Guid.NewGuid(),
            [
                new PlayerSetup(alice, "Alice", 20, TestCards.Deck(40, "Alice")),
                new PlayerSetup(bob, "Bob", 20, TestCards.Deck(40, "Bob")),
                new PlayerSetup(carol, "Carol", 20, TestCards.Deck(40, "Carol")),
            ],
            new GameRandom(1),
            startingPlayerId: alice,
            abilities: Pool);

        game.BeginPlay(withMulligans: false);
        TestCards.PassToStep(game, TurnStep.PrecombatMain);

        var first = game.Create(bob, TestCards.Creature("Gift Victim One Test", 2, 2), Zone.Battlefield);
        var second = game.Create(bob, TestCards.Creature("Gift Victim Two Test", 2, 2), Zone.Battlefield);

        // Unpromised: the creature dies and Alice pays the printed price.
        var declined = TestCards.PutInHand(game, alice, hunger);
        game.AddMana(alice, ManaColor.Black, 3);
        var life = game.State.GetPlayer(alice).Life;
        game.CastSpell(alice, declined, [Target.ToPermanent(first)]);
        Settle(game);

        Assert.DoesNotContain(first, game.State.Battlefield);
        Assert.Equal(life - 2, game.State.GetPlayer(alice).Life);
        Assert.DoesNotContain(
            game.State.Battlefield,
            id => game.State.GetObject(id).Card.Name == "Food");

        // Promised to Carol: no life lost, and the Food is Carol's alone.
        var promised = TestCards.PutInHand(game, alice, hunger);
        game.AddMana(alice, ManaColor.Black, 3);
        life = game.State.GetPlayer(alice).Life;
        game.CastSpell(alice, promised, [Target.ToPermanent(second)], giftTo: carol);
        Settle(game);

        Assert.Equal(life, game.State.GetPlayer(alice).Life);

        var food = Assert.Single(
            game.State.Battlefield,
            id => game.State.GetObject(id).Card.Name == "Food");
        Assert.Equal(carol, game.State.GetObject(food).ControllerId);

        // A gift is promised to an opponent - not to yourself, and not off a card that
        // offers none.
        var third = TestCards.PutInHand(game, alice, hunger);
        game.AddMana(alice, ManaColor.Black, 3);
        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, third, [Target.ToPermanent(second)], giftTo: alice));

        var giftless = TestCards.PutInHand(
            game, alice, Card("Gift Murder Test", "Destroy target creature."));
        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, giftless, [Target.ToPermanent(second)], giftTo: bob));
    }

    /// <summary>
    /// A permanent's gift rides the resolution onto the battlefield, where the enters trigger
    /// CR 702.174b defines reads it - and so does the card's own intervening-if.
    /// </summary>
    /// <remarks>
    /// Scrapshooter's wording. The promise is made on the spell and asked about on the
    /// permanent, which is a different object (CR 400.7); the fact rides the one move that
    /// turns one into the other, exactly as kicker's flag does (CR 607.2). Cast plain, the
    /// creature arrives and neither trigger fires; cast promising, the chosen opponent draws
    /// and the printed trigger destroys their artifact.
    /// </remarks>
    [Fact]
    public void A_permanents_gift_rides_the_resolution_into_its_enters_trigger()
    {
        var shooter = new CardDefinition
        {
            OracleId = "oracle-gift-shooter-test",
            Name = "Gift Shooter Test",
            ManaCostRaw = "{1}{G}{G}",
            Cmc = 3,
            CardTypes = CardType.Creature,
            Power = 4,
            Toughness = 3,
            Keywords = KeywordAbility.Reach,
            OracleText =
                "Gift a card (You may promise an opponent a gift as you cast this spell. If "
                + "you do, when it enters, they draw a card.)\n"
                + "Reach\n"
                + "When this creature enters, if the gift was promised, destroy target "
                + "artifact or enchantment an opponent controls.",
        };

        var compiled = CardCompiler.Compile(shooter);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.True(compiled.HasGift);

        // The permanent route: no second spell, a synthesized delivery trigger instead.
        Assert.Null(compiled.GiftSpell);
        Assert.Contains(compiled.Triggers, t => t.Id == "gift");

        var (game, alice, bob) = InMainPhase();
        var relic = game.Create(
            bob, Card("Gift Shooter Relic Test", string.Empty, CardType.Artifact), Zone.Battlefield);

        // Cast plain: it arrives, nobody draws, nothing is destroyed.
        var plain = TestCards.PutInHand(game, alice, shooter);
        game.AddMana(alice, ManaColor.Green, 3);
        var handBefore = game.State.GetPlayer(bob).Hand.Count;
        game.CastSpell(alice, plain);
        Settle(game);

        Assert.Equal(handBefore, game.State.GetPlayer(bob).Hand.Count);
        Assert.Contains(relic, game.State.Battlefield);

        // Cast promising Bob: he draws, and the trigger takes his artifact.
        var promising = TestCards.PutInHand(game, alice, shooter);
        game.AddMana(alice, ManaColor.Green, 3);
        handBefore = game.State.GetPlayer(bob).Hand.Count;
        game.CastSpell(alice, promising, giftTo: bob);
        Settle(game);

        Assert.Equal(handBefore + 1, game.State.GetPlayer(bob).Hand.Count);
        Assert.DoesNotContain(relic, game.State.Battlefield);
    }

    /// <summary>
    /// The aftermath and fuse flags are read through the reminder text every real printing
    /// carries.
    /// </summary>
    /// <remarks>
    /// The fixtures above say a bare "Aftermath" and "Fuse", and the cardboard never does -
    /// it says "Aftermath (Cast this spell only from your graveyard. ...)". The bare-word
    /// match read raw face text, found nothing on any of the 27 real aftermath cards, and
    /// thirteen "complete" split cards were quietly castable from hand twice; the 22 fuse
    /// cards lost their fused cast the same way. So this fixture is shaped exactly like the
    /// printing, and the play half proves the flag bites: the aftermath half refuses to cast
    /// from hand.
    /// </remarks>
    [Fact]
    public void Aftermath_and_fuse_are_read_through_the_printed_reminder_text()
    {
        var split = new CardDefinition
        {
            OracleId = "oracle-test-aftermath-reminder",
            Name = "Reminder Strike Test // Reminder Echo Test",
            ManaCostRaw = "{R}",
            OracleText = "You gain 1 life.",
            CardTypes = CardType.Sorcery,
            Faces =
            [
                new CardFace
                {
                    Name = "Reminder Strike Test",
                    ManaCostRaw = "{R}",
                    TypeLine = "Sorcery",
                    CardTypes = CardType.Sorcery,
                    OracleText = "You gain 1 life.",
                },
                new CardFace
                {
                    Name = "Reminder Echo Test",
                    ManaCostRaw = "{2}{R}",
                    TypeLine = "Sorcery",
                    CardTypes = CardType.Sorcery,
                    OracleText =
                        "You gain 5 life.\n"
                        + "Aftermath (Cast this spell only from your graveyard. Then exile it.)",
                },
            ],
        };

        var compiled = CardCompiler.Compile(split);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.True(compiled.Halves[1].HasAftermath);

        var fused = new CardDefinition
        {
            OracleId = "oracle-test-fuse-reminder",
            Name = "Reminder Pull Test // Reminder Push Test",
            ManaCostRaw = "{G}",
            OracleText = "You gain 1 life.",
            CardTypes = CardType.Sorcery,
            Faces =
            [
                new CardFace
                {
                    Name = "Reminder Pull Test",
                    ManaCostRaw = "{G}",
                    TypeLine = "Sorcery",
                    CardTypes = CardType.Sorcery,
                    OracleText =
                        "You gain 1 life.\n"
                        + "Fuse (You may cast one or both halves of this card from your hand.)",
                },
                new CardFace
                {
                    Name = "Reminder Push Test",
                    ManaCostRaw = "{1}{G}",
                    TypeLine = "Sorcery",
                    CardTypes = CardType.Sorcery,
                    OracleText = "You gain 2 life.",
                },
            ],
        };

        Assert.True(CardCompiler.Compile(fused).HasFuse);

        // The flag bites: from hand the aftermath half refuses (CR 702.127a).
        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, split);
        game.AddMana(alice, ManaColor.Red, 3);

        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, card, [], half: 1));

        game.CastSpell(alice, card, [], half: 0);
        Settle(game);
    }

    // ---- A delayed destroy, and which permanent "it" means (CR 603.7, 701.7a) ---

    /// <summary>
    /// "When ~ attacks or blocks, destroy it at end of combat." - Ceremonial Guard.
    /// </summary>
    /// <remarks>
    /// The delayed vocabulary had three words and none of them was this one, so the line stayed
    /// unread on purpose: its default arm is a sacrifice, and CR 701.21a says outright that
    /// sacrificing a permanent does not destroy it. The two tests after this one are what make
    /// the new word worth having rather than a rename - the drawback is one that indestructible
    /// refuses (CR 702.12b) and regeneration replaces (CR 701.19b), and a sacrifice is neither.
    /// </remarks>
    [Fact]
    public void A_delayed_destroy_takes_the_attacker_at_the_end_of_combat()
    {
        var guard = Card(
            "End Of Combat Destroy Test",
            "When ~ attacks or blocks, destroy it at end of combat.",
            CardType.Creature,
            power: 3,
            toughness: 3);

        var compiled = CardCompiler.Compile(guard);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var soldier = game.Create(alice, guard, Zone.Battlefield);

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [soldier] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.CombatDamage);

        // Still there when the damage is dealt: the destruction is owed, not done.
        Assert.Contains(soldier, game.State.Battlefield);

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.PostcombatMain);
        Settle(game);

        // Three damage got through first, and only then did it go. The card in the graveyard is
        // a new object (CR 400.7), so it is found by what it is rather than by the id that
        // attacked.
        Assert.Equal(17, game.State.GetPlayer(bob).Life);
        Assert.DoesNotContain(soldier, game.State.Battlefield);
        Assert.Contains(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == guard.Name);
    }

    /// <summary>
    /// Indestructible refuses it, which a sacrifice would not have (CR 702.12b, 701.21a).
    /// </summary>
    /// <remarks>
    /// The assertion that separates the two instructions. Compiled as the sacrifice the
    /// vocabulary already had, this creature would be in the graveyard - a card strictly harsher
    /// than the one printed, on every board where the drawback was meant to be answerable.
    /// </remarks>
    [Fact]
    public void An_indestructible_creature_survives_its_own_delayed_destroy()
    {
        var guard = Card(
            "Indestructible Destroy Test",
            "When ~ attacks or blocks, destroy it at end of combat.",
            CardType.Creature,
            power: 3,
            toughness: 3,
            keywords: KeywordAbility.Indestructible);

        var compiled = CardCompiler.Compile(guard);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var soldier = game.Create(alice, guard, Zone.Battlefield);

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [soldier] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.PostcombatMain);
        Settle(game);

        Assert.Contains(soldier, game.State.Battlefield);
        Assert.DoesNotContain(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == guard.Name);
    }

    /// <summary>
    /// A regeneration shield replaces it with a tap (CR 701.19b), which is the other half.
    /// </summary>
    /// <remarks>
    /// Nothing in the arm checks for a shield: it emits a move whose cause is <c>Destroy</c>, and
    /// regeneration is already a replacement watching for that event. That is the point of the
    /// test - the arm goes through the same door every other destruction does, where a delayed
    /// destroy written as its own zone change would have walked past it.
    /// </remarks>
    [Fact]
    public void A_regeneration_shield_answers_a_delayed_destroy()
    {
        var troll = Card(
            "Regenerating Destroy Test",
            "{G}: Regenerate ~.\nWhen ~ attacks or blocks, destroy it at end of combat.",
            CardType.Creature,
            power: 3,
            toughness: 3);

        var compiled = CardCompiler.Compile(troll);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var creature = game.Create(alice, troll, Zone.Battlefield);
        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);

        // The shield lasts until end of turn (CR 701.19b), so it is raised on the turn it has to
        // answer for rather than on the one the creature arrived.
        PassTo(game, 3, TurnStep.PrecombatMain);
        game.ActivateAbility(alice, forest, "mana");
        game.ActivateAbility(alice, creature, "a");
        Settle(game);

        Assert.Equal(1, game.State.GetObject(creature).Permanent!.RegenerationShields);

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [creature] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.PostcombatMain);
        Settle(game);

        var survivor = game.State.Battlefield
            .Select(game.State.GetObject)
            .SingleOrDefault(o => o.Card.Name == troll.Name);

        Assert.NotNull(survivor);
        Assert.Equal(0, survivor!.Permanent!.RegenerationShields);
    }

    /// <summary>
    /// "Whenever ~ deals combat damage to a creature, destroy that creature at end of combat."
    /// - Ohran Viper.
    /// </summary>
    /// <remarks>
    /// The delay is about the creature the trigger was about and not about the permanent whose
    /// ability it is. Both halves are asserted, and the second is the one that matters: a
    /// delayed action that could only name its own source would have destroyed the snake.
    /// </remarks>
    [Fact]
    public void A_delayed_destroy_names_the_creature_the_trigger_was_about()
    {
        var viper = Card(
            "Ohran Viper Test",
            "Whenever ~ deals combat damage to a creature, destroy that creature at end of combat.",
            CardType.Creature,
            power: 3,
            toughness: 3);

        var compiled = CardCompiler.Compile(viper);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var snake = game.Create(alice, viper, Zone.Battlefield);
        var wall = game.Create(bob, TestCards.Creature("Viper Blocker Test", 2, 6), Zone.Battlefield);

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [snake] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);
        game.DeclareBlockers(
            bob,
            new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [snake] = [wall] });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.PostcombatMain);
        Settle(game);

        // The blocker took three damage and would have lived; the delayed destroy is what killed
        // it, at the end of combat rather than when the damage was dealt.
        Assert.DoesNotContain(wall, game.State.Battlefield);
        Assert.Contains(
            game.State.GetPlayer(bob).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Viper Blocker Test");

        // And the snake is still standing, which is the whole of what the subject reader buys.
        Assert.Contains(snake, game.State.Battlefield);
    }

    /// <summary>
    /// "Target creature gets +2/+0 until end of turn. Destroy it at the beginning of the next
    /// end step." - the Puffer Extract shape.
    /// </summary>
    /// <remarks>
    /// "It" after a target means that target, and this is the reading a source-only delay could
    /// not have. The source here is a spell, which is in a graveyard by the time the end step
    /// arrives, so a delay aimed at the source would have left the creature pumped and alive.
    /// </remarks>
    [Fact]
    public void A_delayed_destroy_names_the_creature_the_spell_targeted()
    {
        var extract = Card(
            "Puffer Extract Test",
            "Target creature gets +2/+0 until end of turn. "
                + "Destroy it at the beginning of the next end step.");

        var compiled = CardCompiler.Compile(extract);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var bear = game.Create(bob, TestCards.Creature("Puffed Bear Test", 2, 2), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, extract);
        var land = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");
        game.CastSpell(alice, card, [Target.ToPermanent(bear)]);
        Settle(game);

        // Still there, pumped, with the destruction owed.
        Assert.Contains(bear, game.State.Battlefield);
        Assert.Equal(
            4, Characteristics.Of(game.State, Pool, game.State.GetObject(bear)).Power);

        TestCards.PassToStep(game, TurnStep.End);
        Settle(game);

        Assert.DoesNotContain(bear, game.State.Battlefield);
        Assert.Contains(
            game.State.GetPlayer(bob).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Puffed Bear Test");
    }

    /// <summary>
    /// "Whenever ~ blocks or becomes blocked by a creature, destroy that creature at end of
    /// combat." - Tangle Asp, and the reading this family must never take.
    /// </summary>
    /// <remarks>
    /// The reading it must never take is that "that creature" is the Asp. The first cut of the
    /// destroy arm let the pronoun fall back to the source the way "it" may, and Tangle Asp,
    /// Venomous Dragonfly and Infernal Medusa compiled into creatures that destroyed themselves
    /// whenever they blocked - the complete-card count went up by three and all three were wrong,
    /// which is why the measurement that matters is the set and not the number.
    /// <para>
    /// The three read now, and the difference is where the subject comes from: the pair rather
    /// than the batch. So this asserts what it always meant to - the creature on the other side of
    /// the declaration is destroyed and the Asp is not - instead of asserting that nothing happens
    /// at all, which is what it had to say while there was no subject to hand it.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_delayed_destroy_after_a_blocks_trigger_takes_the_creature_it_blocked()
    {
        var asp = Card(
            "Tangle Asp Test",
            "Whenever ~ blocks or becomes blocked by a creature, "
                + "destroy that creature at end of combat.",
            CardType.Creature,
            power: 1,
            toughness: 2);

        var compiled = CardCompiler.Compile(asp);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();

        // A 0/4: it survives the Asp's one point of combat damage, so anything that happens to it
        // happened because the delayed ability said so.
        var attacker = game.Create(
            alice, TestCards.Creature("Tangle Victim Test", 0, 4), Zone.Battlefield);

        var blocker = game.Create(bob, asp, Zone.Battlefield);

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);
        game.DeclareBlockers(
            bob,
            new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [attacker] = [blocker] });

        // Still there while the combat runs: the destruction is owed at end of combat, not now.
        Settle(game);
        Assert.Contains(attacker, game.State.Battlefield);

        TestCards.PassUntil(game, () => game.State.CurrentStep >= TurnStep.PostcombatMain);
        Settle(game);

        Assert.DoesNotContain(attacker, game.State.Battlefield);
        Assert.Contains(blocker, game.State.Battlefield);
    }

    /// <summary>
    /// "Create a 1/1 white Soldier creature token. Destroy it at the beginning of the next end
    /// step." - the Hornet Cannon shape, and both verbs now take the token.
    /// </summary>
    /// <remarks>
    /// This asserted a refusal on the destroy and a source fallback on the sacrifice, and the
    /// two halves disagreed for a reason that has gone. The destroy refused because a token made
    /// a sentence earlier is something else "it" could mean; the sacrifice kept a fallback that
    /// was wrong about exactly those cards. Eleven fully compiled cards were taking it - Lagomos,
    /// Hand of Hatred sacrificed <em>itself</em> at the beginning of every end step instead of
    /// the Elemental it had just made, and Rakdos Guildmage exiled itself instead of the Goblin.
    /// <para>
    /// Both verbs now fold the delay into the creation, so both are played rather than asserted
    /// about, and the permanent that made the token is checked in the same game. That second
    /// claim is the one the old reading failed: something did go away at end of turn, and it was
    /// the card that made the token.
    /// </para>
    /// </remarks>
    [Theory]
    [InlineData("Destroy")]
    [InlineData("Sacrifice")]
    public void A_delayed_action_after_a_token_takes_the_token_and_not_the_permanent_that_made_it(
        string verb)
    {
        var cannon = Card(
            "Token Delay Test " + verb,
            "{T}: Create a 1/1 white Soldier creature token. "
                + verb + " it at the beginning of the next end step.",
            CardType.Artifact | CardType.Creature,
            1,
            3);

        var compiled = CardCompiler.Compile(cannon);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var machine = game.Create(alice, cannon, Zone.Battlefield);

        PassTo(game, 3, TurnStep.PrecombatMain);

        var ability = Assert.Single(
            Game.ActivatedAbilitiesOf(game.State, Pool, game.State.GetObject(machine)));

        game.ActivateAbility(alice, machine, ability.Id, []);
        Settle(game);

        var soldier = TokenNamed(game, "Soldier");

        TestCards.PassUntil(game, () => game.State.CurrentStep >= TurnStep.Cleanup);

        Assert.DoesNotContain(soldier, game.State.Battlefield);
        Assert.Contains(machine, game.State.Battlefield);
    }

    // ---- The impulse, and the sentence beside it (CR 601.3e) ------------------

    /// <summary>
    /// "Exile the top two cards of your library. Until the end of your next turn, you may play
    /// those cards. If this spell was cast using teamwork, create a Treasure token." - Crossover
    /// Collaboration.
    /// </summary>
    /// <remarks>
    /// The idiom was anchored to the end of the line, so one sentence behind it threw the whole
    /// match away and left a card unread whose exile half the compiler had understood all along.
    /// The look-and-take idiom in the same method had already been through this and already had
    /// the answer: match the pair, then read whatever follows the ordinary way. The tail is read
    /// and not dropped - a tail nothing can read still refuses the line, which is the last test
    /// in this section.
    /// </remarks>
    [Fact]
    public void An_impulse_reads_the_sentence_printed_after_it()
    {
        var spell = Card(
            "Impulse Tail Test",
            "Exile the top card of your library. You may play that card this turn. "
                + "You gain 2 life.");

        var compiled = CardCompiler.Compile(spell);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        game.Create(alice, TestCards.Creature("Tailed Bear Test", 2, 2), Zone.Library);

        var card = TestCards.PutInHand(game, alice, spell);
        var land = game.Create(alice, TestCards.BasicLand("Mountain"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");

        game.CastSpell(alice, card, targets: null);
        Settle(game);

        // Both halves ran: the exile is playable this turn, and the sentence behind it happened.
        var exiled = game.State.Exile
            .Select(game.State.GetObject)
            .Single(o => o.Card.Name == "Tailed Bear Test");

        Assert.Equal(game.State.TurnNumber, exiled.MayPlayUntilTurn);
        Assert.Equal(22, game.State.GetPlayer(alice).Life);
    }

    /// <summary>
    /// "Exile the top card of your library. You may play it this turn." - Prophetic Flamespeaker.
    /// </summary>
    /// <remarks>
    /// The same sentence with the pronoun the card actually prints. Six corpus cards say "it"
    /// and were refused by a reader that only knew "that card", which is a vocabulary gap
    /// wearing a mechanic's clothes.
    /// </remarks>
    [Fact]
    public void An_impulse_reads_the_pronoun_the_card_prints()
    {
        var spell = Card(
            "Impulse Pronoun Test",
            "Exile the top card of your library. You may play it this turn.");

        var compiled = CardCompiler.Compile(spell);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        game.Create(alice, TestCards.Creature("Pronoun Bear Test", 2, 2), Zone.Library);

        var card = TestCards.PutInHand(game, alice, spell);
        var land = game.Create(alice, TestCards.BasicLand("Mountain"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");

        game.CastSpell(alice, card, targets: null);
        Settle(game);

        var exiled = game.State.Exile
            .Select(game.State.GetObject)
            .Single(o => o.Card.Name == "Pronoun Bear Test");

        Assert.Equal(game.State.TurnNumber, exiled.MayPlayUntilTurn);
    }

    /// <summary>
    /// "Exile the top card of your library. You may play that card until the end of your next
    /// turn." - Clockwork Percussionist.
    /// </summary>
    /// <remarks>
    /// The longer window, written behind the permission rather than in front of it. Cards spell
    /// it both ways round about equally often and only one of the two was read, so five cards
    /// were refused over a word order - and the duration is the half that must not be quietly
    /// dropped, since the shorter one is a strictly worse card.
    /// </remarks>
    [Fact]
    public void An_impulse_reads_a_duration_written_behind_the_permission()
    {
        var spell = Card(
            "Impulse Duration Test",
            "Exile the top card of your library. "
                + "You may play that card until the end of your next turn.");

        var compiled = CardCompiler.Compile(spell);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        game.Create(alice, TestCards.Creature("Duration Bear Test", 2, 2), Zone.Library);

        var card = TestCards.PutInHand(game, alice, spell);
        var land = game.Create(alice, TestCards.BasicLand("Mountain"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");

        game.CastSpell(alice, card, targets: null);
        Settle(game);

        var exiled = game.State.Exile
            .Select(game.State.GetObject)
            .Single(o => o.Card.Name == "Duration Bear Test");

        // The longer duration is not writable as a turn number, so it rides as its own field -
        // and the turn number stays empty rather than being filled in with this turn's, which
        // would have made the permission expire tonight.
        Assert.Null(exiled.MayPlayUntilTurn);
        Assert.NotNull(exiled.MayPlayThroughOwnersNextTurn);
    }

    /// <summary>
    /// A tail nothing can read still refuses the whole line.
    /// </summary>
    /// <remarks>
    /// The control that makes the three tests above mean something. Letting an idiom match a
    /// prefix is only safe while the remainder is read rather than discarded: an impulse that
    /// quietly swallowed the sentence behind it would compile Hidetsugu, Devouring Chaos into a
    /// card that exiles and never deals the damage, and the coverage figure would go up while
    /// the card got worse.
    /// <para>
    /// The tail here is that card's reflexive trigger. If it ever becomes readable this test
    /// fails, and that is the right prompt: the assertion is about a line the compiler cannot
    /// read, not about that particular mechanic.
    /// </para>
    /// </remarks>
    [Fact]
    public void An_impulse_with_an_unreadable_tail_stays_unread()
    {
        var spell = Card(
            "Impulse Refused Tail Test",
            "Exile the top card of your library. You may play that card this turn. "
                + "When you exile a nonland card this way, ~ deals damage equal to the exiled "
                + "card's mana value to any target.");

        var compiled = CardCompiler.Compile(spell);

        Assert.False(compiled.IsComplete);
        Assert.Contains(
            compiled.Unhandled,
            line => line.Contains(
                "Exile the top card of your library", StringComparison.Ordinal));
    }

    // ---- Mana whose colour is chosen on resolution (CR 106.1a) ----------------

    /// <summary>A ritual with a real cost, so the mana it makes has to be paid for first.</summary>
    private static CardDefinition Ritual(string name, string text) => new()
    {
        OracleId = "oracle-" + name.ToLowerInvariant().Replace(' ', '-'),
        Name = name,
        ManaCostRaw = "{G}",
        Cmc = 1,
        CardTypes = CardType.Sorcery,
        OracleText = text,
    };

    /// <summary>A sorcery that draws, priced in whatever colours the test needs to prove.</summary>
    private static CardDefinition Draws(string name, string cost, int cmc) => new()
    {
        OracleId = "oracle-" + name.ToLowerInvariant().Replace(' ', '-'),
        Name = name,
        ManaCostRaw = cost,
        Cmc = cmc,
        CardTypes = CardType.Sorcery,
        OracleText = "Draw a card.",
    };

    /// <summary>A land with two basic land types, so it could produce two things (CR 305.6).</summary>
    private static CardDefinition DualLand(string name) => new()
    {
        OracleId = "oracle-" + name.ToLowerInvariant().Replace(' ', '-'),
        Name = name,
        CardTypes = CardType.Land,
        Subtypes = ["Forest", "Island"],
    };

    /// <summary>
    /// "Add two mana of any one color" makes mana that pays for a spell nothing else could
    /// (CR 106.1a, 106.4).
    /// </summary>
    /// <remarks>
    /// The point of the whole mechanism, and the reason the assertion is a cast rather than a
    /// pool reading. A pool entry proves an event was emitted; it does not prove the mana is the
    /// colour it claims or that anything can spend it. The blue spell here is refused before the
    /// ritual and cast after it, off one Forest, so only real blue mana makes both halves true.
    /// <para>
    /// "Any one color" is one colour for all of it, which is why one answer buys two blue.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_colour_named_on_resolution_pays_for_a_spell_nothing_else_could()
    {
        var ritual = Ritual("Chosen Mana Ritual Test", "Add two mana of any one color.");

        var compiled = CardCompiler.Compile(ritual);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, forest, "mana");

        // Green in the pool and nothing else, so the blue spell is unpayable - which is what
        // makes casting it later evidence rather than coincidence.
        var refused = TestCards.PutInHand(
            game, alice, Draws("Chosen Mana Blue Test", "{U}{U}", 2));

        Assert.Throws<InvalidOperationException>(() => game.CastSpell(alice, refused));

        game.CastSpell(alice, TestCards.PutInHand(game, alice, ritual));
        TestCards.PassUntil(game, () => game.State.Choice is not null);

        var choice = game.State.Choice;
        Assert.NotNull(choice);
        Assert.Equal(ChoiceKind.ChooseManaColor, choice.Kind);

        // The five colours and no more: colourless is a type of mana but not a colour
        // (CR 106.1b), and a card that meant to offer it says "any type".
        Assert.Equal(5, choice.Options.Count);
        Assert.DoesNotContain(choice.Options, o => o.Id == nameof(ManaColor.Colorless));

        game.Choose(alice, [nameof(ManaColor.Blue)]);

        Assert.Equal(2, game.State.GetPlayer(alice).ManaPool[ManaColor.Blue]);

        var before = game.State.GetPlayer(alice).Hand.Count;
        game.CastSpell(alice, refused);
        Settle(game);

        // The card left the hand and one was drawn, and the blue is spent: it was real mana.
        Assert.Equal(before, game.State.GetPlayer(alice).Hand.Count);
        Assert.Equal(0, game.State.GetPlayer(alice).ManaPool[ManaColor.Blue]);
    }

    /// <summary>
    /// "In any combination of colors" gives each mana its own colour, and so its own question.
    /// </summary>
    /// <remarks>
    /// The other half of the pair above, and the half that one flag decides. Two mana "of any one
    /// color" is one answer for both; two "in any combination" is two answers, because each mana
    /// is a colour of its own (CR 106.1a). A reader that collapsed them would pass the test above
    /// and hand this one two blue.
    /// <para>
    /// Asserted by casting a spell that needs one of each, which no single answer could pay for.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_combination_of_colours_is_a_colour_for_each_mana()
    {
        var ritual = Ritual(
            "Combination Mana Ritual Test", "Add two mana in any combination of colors.");

        var compiled = CardCompiler.Compile(ritual);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, forest, "mana");

        game.CastSpell(alice, TestCards.PutInHand(game, alice, ritual));

        TestCards.PassUntil(game, () => game.State.Choice is not null);
        Assert.Equal(ChoiceKind.ChooseManaColor, game.State.Choice!.Kind);
        game.Choose(alice, [nameof(ManaColor.Blue)]);

        // A second question, because the second mana is a second colour.
        Assert.NotNull(game.State.Choice);
        Assert.Equal(ChoiceKind.ChooseManaColor, game.State.Choice!.Kind);
        game.Choose(alice, [nameof(ManaColor.Red)]);

        Assert.Equal(1, game.State.GetPlayer(alice).ManaPool[ManaColor.Blue]);
        Assert.Equal(1, game.State.GetPlayer(alice).ManaPool[ManaColor.Red]);

        var twoColours = TestCards.PutInHand(
            game, alice, Draws("Combination Mana Spell Test", "{U}{R}", 2));

        var before = game.State.GetPlayer(alice).Hand.Count;
        game.CastSpell(alice, twoColours);
        Settle(game);

        // Cast and drawn from: one out, one in. Neither colour alone could have paid for it.
        Assert.Equal(before, game.State.GetPlayer(alice).Hand.Count);
    }

    /// <summary>
    /// A Forest can only make green, so the game does not stop to ask which (CR 118.3).
    /// </summary>
    /// <remarks>
    /// The trap this mechanism is most likely to fall into, and the one <c>Game.AskOwedPayment</c>
    /// already states in as many words: a question with one possible answer is not a question,
    /// and putting it is how a game stalls. Dictate of Karametra's wording sees every land
    /// anybody taps, so a question per tap would make the card unplayable rather than annoying.
    /// <para>
    /// Asserted against the log rather than the current state: a question asked and answered
    /// leaves no trace in the state, so "nothing outstanding now" would pass either way.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_land_with_one_type_is_not_asked_which_colour_it_made()
    {
        var dictate = Card(
            "Karametra Dictate Test",
            "Whenever a player taps a land for mana, that player adds one mana of any type "
                + "that land produced.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(dictate);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        game.Create(alice, dictate, Zone.Battlefield);
        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);

        game.ActivateAbility(alice, forest, "mana");

        // Not "the stack is empty": a trigger waits in PendingTriggers before it is put there
        // (CR 603.3), so that is true the instant the land taps and nothing would have resolved.
        // PassUntil throws if a question appears, which is the assertion below asked twice.
        TestCards.PassUntil(
            game, () => game.State.GetPlayer(alice).ManaPool[ManaColor.Green] == 2);

        Assert.DoesNotContain(
            game.Log,
            e => e is ChoiceRequested { Choice.Kind: ChoiceKind.ChooseManaColor });

        // One Forest, two green - and the second is spendable, which a bare count of two would
        // read the same way even if the doubling had produced colourless.
        Assert.Equal(2, game.State.GetPlayer(alice).ManaPool[ManaColor.Green]);

        var doubled = TestCards.PutInHand(
            game, alice, Draws("Karametra Doubled Test", "{G}{G}", 2));

        var before = game.State.GetPlayer(alice).Hand.Count;
        game.CastSpell(alice, doubled);
        Settle(game);

        Assert.Equal(before, game.State.GetPlayer(alice).Hand.Count);
    }

    /// <summary>
    /// A land that could make two types is asked which one this was (CR 106.7).
    /// </summary>
    /// <remarks>
    /// The other side of the test above: the same card, the same trigger, and a land with two
    /// basic land types. The menu is read as the trigger resolves rather than when the card was
    /// compiled, which is the only reason one effect serves both boards.
    /// <para>
    /// The answer taken is the colour the land did <em>not</em> tap for, so an implementation
    /// that quietly repeated the produced mana would fail here and pass everything else.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_land_that_could_make_two_types_is_asked_which()
    {
        var dictate = Card(
            "Karametra Dual Dictate Test",
            "Whenever a player taps a land for mana, that player adds one mana of any type "
                + "that land produced.",
            CardType.Enchantment);

        var (game, alice, _) = InMainPhase();
        game.Create(alice, dictate, Zone.Battlefield);
        var dual = game.Create(alice, DualLand("Karametra Dual Test"), Zone.Battlefield);

        // "mana1" is the Forest half: the intrinsic abilities are built in the rules' own order
        // of the basic land types, and Island comes before Forest (CR 305.6).
        game.ActivateAbility(alice, dual, "mana1");
        TestCards.PassUntil(game, () => game.State.Choice is not null);

        var choice = game.State.Choice;
        Assert.NotNull(choice);
        Assert.Equal(ChoiceKind.ChooseManaColor, choice.Kind);
        Assert.Equal(
            [nameof(ManaColor.Blue), nameof(ManaColor.Green)],
            choice.Options.Select(o => o.Id).Order(StringComparer.Ordinal));

        game.Choose(alice, [nameof(ManaColor.Blue)]);

        Assert.Equal(1, game.State.GetPlayer(alice).ManaPool[ManaColor.Green]);
        Assert.Equal(1, game.State.GetPlayer(alice).ManaPool[ManaColor.Blue]);

        var simic = TestCards.PutInHand(
            game, alice, Draws("Karametra Simic Test", "{G}{U}", 2));

        var before = game.State.GetPlayer(alice).Hand.Count;
        game.CastSpell(alice, simic);
        Settle(game);

        Assert.Equal(before, game.State.GetPlayer(alice).Hand.Count);
    }

    /// <summary>
    /// "That player adds" fills the pool of whoever tapped the land, not the enchantment's
    /// controller (CR 603.2).
    /// </summary>
    /// <remarks>
    /// The half of this family that has nothing to do with colours, and the one an effect with
    /// no player scope could not say at all. Dictate of Karametra is symmetrical - it doubles
    /// everybody's lands, opponents included - and an effect that could only fill its
    /// controller's pool would turn it into a one-sided ritual, a far better card than the one
    /// printed.
    /// <para>
    /// The controller's pool is asserted too: mana appearing in the right place is half a claim
    /// while it might also be appearing in the wrong one.
    /// </para>
    /// </remarks>
    [Fact]
    public void The_mana_goes_to_the_player_who_tapped_the_land()
    {
        var dictate = Card(
            "Karametra Symmetry Test",
            "Whenever a player taps a land for mana, that player adds one mana of any type "
                + "that land produced.",
            CardType.Enchantment);

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, dictate, Zone.Battlefield);
        var theirs = game.Create(bob, TestCards.BasicLand("Forest"), Zone.Battlefield);

        // CR 605.3a: a mana ability may be activated whenever its controller could pay for
        // something, which is why Bob does not have to wait for his own turn.
        game.ActivateAbility(bob, theirs, "mana");
        TestCards.PassUntil(
            game, () => game.State.GetPlayer(bob).ManaPool[ManaColor.Green] == 2);

        Assert.Equal(2, game.State.GetPlayer(bob).ManaPool[ManaColor.Green]);
        Assert.Equal(0, game.State.GetPlayer(alice).ManaPool[ManaColor.Green]);
    }

    /// <summary>
    /// "Its controller adds an additional one mana of any color" reads the land's controller off
    /// the trigger (CR 603.2).
    /// </summary>
    /// <remarks>
    /// Verdant Haven's wording, and the commonest shape in this family - eight Auras print some
    /// version of it. What is checkable is asserted: the extra mana arrives, it is the colour
    /// that was named, and it pays for a spell the Forest under it could never have paid for.
    /// </remarks>
    [Fact]
    public void An_aura_can_add_an_extra_mana_of_a_colour_named_on_resolution()
    {
        var haven = new CardDefinition
        {
            OracleId = "oracle-verdant-haven-test",
            Name = "Verdant Haven Test",
            ManaCostRaw = "{1}{G}",
            Cmc = 2,
            CardTypes = CardType.Enchantment,
            Subtypes = ["Aura"],
            OracleText =
                "Enchant land\nWhenever enchanted land is tapped for mana, its controller adds "
                + "an additional one mana of any color.",
        };

        var compiled = CardCompiler.Compile(haven);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        var aura = game.Create(alice, haven, Zone.Battlefield);
        game.Attach(aura, forest);

        game.ActivateAbility(alice, forest, "mana");
        TestCards.PassUntil(game, () => game.State.Choice is not null);

        Assert.Equal(ChoiceKind.ChooseManaColor, game.State.Choice!.Kind);
        game.Choose(alice, [nameof(ManaColor.Black)]);

        Assert.Equal(1, game.State.GetPlayer(alice).ManaPool[ManaColor.Green]);
        Assert.Equal(1, game.State.GetPlayer(alice).ManaPool[ManaColor.Black]);

        var golgari = TestCards.PutInHand(
            game, alice, Draws("Verdant Haven Spell Test", "{B}{G}", 2));

        var before = game.State.GetPlayer(alice).Hand.Count;
        game.CastSpell(alice, golgari);
        Settle(game);

        Assert.Equal(before, game.State.GetPlayer(alice).Hand.Count);
    }

    /// <summary>
    /// The answered question replays: a game rebuilt from its written log makes the same mana.
    /// </summary>
    /// <remarks>
    /// The founding invariant, checked on the one thing this feature adds that could break it. A
    /// colour named mid-resolution is the shape most likely to be built as a captured
    /// continuation by accident, and a continuation cannot be folded from a log - so the log is
    /// written out and read back here rather than only being folded in memory.
    /// </remarks>
    [Fact]
    public void A_chosen_mana_colour_survives_being_written_out_and_replayed()
    {
        var ritual = Ritual("Replayed Mana Ritual Test", "Add two mana of any one color.");

        var (game, alice, _) = InMainPhase();
        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, forest, "mana");

        game.CastSpell(alice, TestCards.PutInHand(game, alice, ritual));
        TestCards.PassUntil(game, () => game.State.Choice is not null);
        game.Choose(alice, [nameof(ManaColor.Red)]);

        Assert.Equal(2, game.State.GetPlayer(alice).ManaPool[ManaColor.Red]);

        var written = EventLogSerializer.Write(game.Log);
        var replayed = GameReducer.Replay(EventLogSerializer.Read(written));

        Assert.Equal(game.State, replayed);
        Assert.Equal(2, replayed.GetPlayer(alice).ManaPool[ManaColor.Red]);
    }

    /// <summary>
    /// An activated ability whose whole effect is mana never becomes one that uses the stack
    /// (CR 605.1a, 605.3b).
    /// </summary>
    /// <remarks>
    /// The control that makes the rest of this section safe. "Add three mana in any combination
    /// of colors" is more payouts than the mana path will enumerate, so that path refuses the
    /// line - and the general activated-ability path can now read the sentence, which would have
    /// built it as an ability that goes on the stack. A mana ability never does: an opponent
    /// could respond to it, and it could not be activated while paying for a spell, which is the
    /// only thing it is for.
    /// <para>
    /// That is the shape of bug this engine has been bitten by before - the card compiles, counts
    /// as covered, offers its button and plays differently from what it prints - so the line is
    /// left unread instead. If the mana path ever learns to enumerate three colours this test
    /// fails, and that is the right prompt: it is an assertion about a line nothing can read.
    /// </para>
    /// </remarks>
    [Fact]
    public void An_ability_that_only_makes_mana_never_becomes_a_stack_ability()
    {
        var land = new CardDefinition
        {
            OracleId = "oracle-three-colour-storage-test",
            Name = "Three Colour Storage Test",
            CardTypes = CardType.Land,
            OracleText = "{T}: Add three mana in any combination of colors.",
        };

        var compiled = CardCompiler.Compile(land);

        Assert.False(compiled.IsComplete);
        Assert.Contains(
            compiled.Unhandled,
            line => line.Contains("in any combination of colors", StringComparison.Ordinal));

        // Nothing was built from it at all - neither a mana ability nor, worse, one that would
        // have gone on the stack.
        Assert.Empty(compiled.Activated);
    }

    // ---- A settle step that asks nobody anything (CR 117.5, 118.3) ------------

    // Four rounds have now found the same bug in a different owed-settle step: a step that did
    // its work without putting a question to anybody returned from the settle sweep as though
    // one were outstanding, so everything after it in that sweep - the state-based actions among
    // them - was abandoned. The roll left a creature standing with lethal damage marked on it;
    // the shuffle performed one of two and handed priority back with the other graveyard
    // untouched. These are the rest of them, found by reading every arm of the sweep against
    // that rule rather than by waiting for the next soak to trip over one.
    //
    // Each is written as a card that owes two things at once: the settling step under test, and
    // a scry, which sits later in the same sweep. The scry never being asked is the sweep having
    // stopped - and it is observable where the abandoned state-based actions are not, because
    // the driver's next pass finds an empty stack and stops passing.

    /// <summary>
    /// A coin flip is settled, not asked, so the sweep carries on to what is owed after it.
    /// </summary>
    /// <remarks>
    /// Nobody chooses anything about a flip: the outcome comes from the one seeded source and
    /// only the result goes in the log, exactly as a shuffle records its order. It nevertheless
    /// returned from the sweep as though a player were being asked, which meant the branch it had
    /// just run went unchecked by the state-based actions - and anything owed behind it, like the
    /// scry here, was left where it stood.
    /// </remarks>
    [Fact]
    public void A_settled_coin_flip_does_not_end_the_sweep()
    {
        var spell = Card(
            "Flip Settle Test",
            "Flip a coin. If you win the flip, you gain 4 life. If you lose the flip, "
                + "you lose 2 life.\nScry 1.");

        var compiled = CardCompiler.Compile(spell);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        game.CastSpell(alice, TestCards.PutInHand(game, alice, spell));
        Settle(game);

        Assert.Single(game.Log.OfType<CoinFlipped>());
        Assert.Contains(
            game.Log.OfType<ChoiceRequested>(), e => e.Choice.Kind == ChoiceKind.Scry);
    }

    /// <summary>
    /// A discover is settled, not asked, so the sweep carries on to what is owed after it.
    /// </summary>
    /// <remarks>
    /// Its own remark said so - "nobody is asked anything here; what the player gets is the offer
    /// at the end, and they take it by casting the card like any other" - and it returned from the
    /// sweep regardless. Cascade, written beside it and identical in this respect, had the same
    /// mistake and is fixed with it; cascade cannot be caught by a card the way this can, because
    /// it always settles with the cascading spell still on the stack, so the next pass re-enters
    /// the sweep and finishes it. The structural guard below is what covers that arm.
    /// </remarks>
    [Fact]
    public void A_settled_discover_does_not_end_the_sweep()
    {
        var spell = Card("Discover Settle Test", "Discover 3.\nScry 1.");

        var compiled = CardCompiler.Compile(spell);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        game.CastSpell(alice, TestCards.PutInHand(game, alice, spell));
        Settle(game);

        Assert.Single(game.Log.OfType<FreeCastOffered>());
        Assert.Contains(
            game.Log.OfType<ChoiceRequested>(), e => e.Choice.Kind == ChoiceKind.Scry);
    }

    /// <summary>
    /// Finishing a clash asks nobody anything, so the sweep carries on (CR 701.30d).
    /// </summary>
    /// <remarks>
    /// A clash is three steps and only the middle one is a question. It reveals, it asks each
    /// clashing player where their card goes, and then it works out who won and runs the branch -
    /// and that last step, reached from the sweep after the final answer, returned as though
    /// somebody were still being asked. So a clash paid out and priority went back with the
    /// state-based actions unchecked and the scry below unasked.
    /// </remarks>
    [Fact]
    public void A_finished_clash_does_not_end_the_sweep()
    {
        var spell = Card(
            "Clash Settle Test",
            "Clash with an opponent. If you win, draw a card.\nScry 1.");

        var compiled = CardCompiler.Compile(spell);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        game.CastSpell(alice, TestCards.PutInHand(game, alice, spell));
        Settle(game);

        // Both clashing players were asked, so the sweep was still working when it reached the
        // finish - which is the moment under test.
        Assert.Equal(
            2,
            game.Log.OfType<ChoiceRequested>()
                .Count(e => e.Choice.Kind == ChoiceKind.ClashKeepOnTop));

        Assert.Contains(
            game.Log.OfType<ChoiceRequested>(), e => e.Choice.Kind == ChoiceKind.Scry);
    }

    /// <summary>
    /// A miracle is an offer rather than a question, so the sweep carries on (CR 702.94a).
    /// </summary>
    /// <remarks>
    /// The card is turned face up and may be cast for its miracle cost; nobody is stopped to
    /// answer anything, and the player takes it by casting like a cascade's hit. This one sits
    /// near the top of the sweep, so returning from it abandoned nearly the whole of the rest -
    /// every owed question, the state-based actions, and the triggers waiting to go on the stack.
    /// </remarks>
    [Fact]
    public void A_miracle_offer_does_not_end_the_sweep()
    {
        var spell = Card("Miracle Settle Test", "Scry 1, then draw a card.");

        var compiled = CardCompiler.Compile(spell);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var miracle = new CardDefinition
        {
            OracleId = "oracle-miracle-settle-card-test",
            Name = "Miracle Settle Card Test",
            CardTypes = CardType.Sorcery,
            ManaCostRaw = "{2}{W}",
            OracleText = "Miracle {W}\nYou gain 3 life.",
        };

        var (game, alice, _) = InMainPhase();

        // On top, so it is the card the spell's own draw turns up - which is what owes a miracle
        // offer in the same settle as the scry the spell asked for first.
        game.Create(alice, miracle, Zone.Library);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, spell));
        Settle(game);

        Assert.Single(game.Log.OfType<FreeCastOffered>());
        Assert.Contains(
            game.Log.OfType<ChoiceRequested>(), e => e.Choice.Kind == ChoiceKind.Scry);
    }

    /// <summary>
    /// Nothing among them worth taking is not a question, and is not asked (CR 118.3).
    /// </summary>
    /// <remarks>
    /// "You may reveal a creature card from among them" over four cards holding no creature was
    /// stopping the game on a prompt with an empty list on it - the zero-card discard's mistake in
    /// a second place, and the two sibling sites that have always guarded it (the mulligan bottom
    /// and the cleanup discard) are what say this one was missing it.
    /// <para>
    /// The rest of the instruction still has to run, which is why the guard resolves the request
    /// rather than dropping it: "put the rest on the bottom of your library" happens whether or
    /// not anything was taken, and skipping the request outright would have left four cards
    /// sitting on top of the library instead.
    /// </para>
    /// </remarks>
    [Fact]
    public void Nothing_worth_taking_among_them_is_not_asked()
    {
        var spell = Card(
            "Take Settle Test",
            "Look at the top four cards of your library. You may reveal a land card from among "
                + "them and put it into your hand. Put the rest on the bottom of your library in "
                + "a random order.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(spell);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();

        // Every card in a test deck is a creature, so no land is among the four and there is
        // nothing the filter admits. Held by name rather than by id: a card put back into the
        // library is a new object (CR 400.7), so the ids do not survive the move.
        var top = game.State.GetPlayer(alice).Library
            .Take(4)
            .Select(id => game.State.GetObject(id).Card.Name)
            .ToHashSet(StringComparer.Ordinal);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, spell));
        Settle(game);

        Assert.DoesNotContain(
            game.Log.OfType<ChoiceRequested>(), e => e.Choice.Kind == ChoiceKind.LookAndTake);

        // And the instruction ran anyway: the four are on the bottom, not still on top. The
        // order among them is the game's own random one, so the set is what can be asserted.
        var library = game.State.GetPlayer(alice).Library
            .Select(id => game.State.GetObject(id).Card.Name)
            .ToList();

        Assert.Equal(top, library.TakeLast(4).ToHashSet(StringComparer.Ordinal));
        Assert.DoesNotContain(library.Take(4), top.Contains);
    }

    /// <summary>
    /// Every settling step of the sweep goes round again rather than returning from it.
    /// </summary>
    /// <remarks>
    /// The behaviour tests above each catch one arm. This catches the class, which is what four
    /// rounds of finding the same bug by accident argues for - and it is the only thing that
    /// covers the cascade arm, whose harm no card can show on its own.
    /// <para>
    /// The rule it enforces is the naming convention <c>SettleBeforePriority</c> runs on: a step
    /// called <c>Ask…</c> only ever puts a question to somebody, so returning is the whole point
    /// of it; every other step can finish without asking anybody anything, so the sweep has to go
    /// round again after it. Written against the source rather than against behaviour because that
    /// is the form the mistake takes - a one-line arm that reads perfectly, in a method whose
    /// other forty arms are written the other way.
    /// </para>
    /// </remarks>
    [Fact]
    public void Every_settling_step_of_the_sweep_goes_round_rather_than_returning()
    {
        var path = Path.Combine(RulesEngineDirectory(), "Game.cs");
        var source = File.ReadAllLines(path);

        var start = Array.FindIndex(
            source,
            line => line.Contains("private bool SettleBeforePriority()", StringComparison.Ordinal));

        Assert.True(start >= 0, "SettleBeforePriority has been renamed; this guard has to follow it.");

        var end = Array.FindIndex(
            source,
            start,
            line => line.Contains(
                "State-based actions and triggers did not settle", StringComparison.Ordinal));

        Assert.True(end > start, "the end of the sweep moved; this guard has to follow it.");

        var asking = 0;
        var settling = 0;
        var offenders = new List<string>();

        for (var i = start; i < end; i++)
        {
            var line = source[i].Trim();

            // An arm of the sweep, which is a bare no-argument call: `if (AskOwedLook())`. Any
            // other condition here - a count, a field, a call with arguments - is not one.
            if (!line.StartsWith("if (", StringComparison.Ordinal)
                || !line.EndsWith("())", StringComparison.Ordinal))
            {
                continue;
            }

            var step = line[4..^3];
            if (step.Contains('.', StringComparison.Ordinal)
                || step.Contains(' ', StringComparison.Ordinal))
            {
                continue;
            }

            // A question may return: the game halts, and nothing else in this sweep may happen
            // until the answer comes back.
            if (step.StartsWith("Ask", StringComparison.Ordinal))
            {
                asking++;
                continue;
            }

            settling++;

            // Everything else can finish without asking anybody, so it has to send the sweep
            // round again: `{ didSomething = true; continue; }`. A bare `return true` on the
            // next line is the bug this whole section is about.
            if (!string.Equals(source[i + 1].Trim(), "{", StringComparison.Ordinal))
                offenders.Add($"Game.cs:{i + 1}  {line}  ->  {source[i + 1].Trim()}");
        }

        // A guard that matched nothing would pass for the wrong reason, which is how a check
        // quietly stops being one. Both halves, because either could stop matching on its own.
        Assert.True(settling >= 12, $"only {settling} settling arms found; the sweep changed shape.");
        Assert.True(asking >= 20, $"only {asking} asking arms found; the sweep changed shape.");

        Assert.True(
            offenders.Count == 0,
            "a step of the sweep that can finish without asking anybody must send it round "
                + "again — `{ didSomething = true; continue; }`, not `return true`. Rename it to "
                + "Ask… only if it truly cannot finish without a question outstanding:"
                + Environment.NewLine
                + string.Join(Environment.NewLine, offenders));
    }

    /// <summary>Where the rules engine's source lives, for the guard above.</summary>
    private static string RulesEngineDirectory()
    {
        var directory = new DirectoryInfo(AppContext.BaseDirectory);
        while (directory is not null
            && !File.Exists(Path.Combine(directory.FullName, "MtgEngine.sln")))
        {
            directory = directory.Parent;
        }

        Assert.NotNull(directory);
        return Path.Combine(directory.FullName, "MtgEngine.Rules", "Engine");
    }

    // ---- A trigger that watches a batch (CR 603.2c) --------------------------

    /// <summary>The +1/+1 counters a permanent is carrying, or none.</summary>
    private static int GrowthOn(Game game, ObjectId id) =>
        game.State.GetObject(id).Permanent?.Counters
            .GetValueOrDefault(CounterKinds.PlusOnePlusOne) ?? 0;

    /// <summary>How many times one permanent's abilities have triggered so far.</summary>
    private static int TimesTriggered(Game game, ObjectId id) =>
        game.Log.OfType<AbilityTriggered>().Count(fired => fired.SourceId == id);

    /// <summary>
    /// Three cards leaving a graveyard together fire the trigger once, not three times.
    /// </summary>
    /// <remarks>
    /// The whole content of "one or more", and the only difference that survives normalising the
    /// sentence back to the singular. CR 603.2c: an ability triggers once each time its trigger
    /// event occurs, and a plural sentence makes a whole batch one occurrence - so reusing the
    /// singular reader unchanged would have fired this once per card and printed a strictly
    /// better card than the one on the table.
    /// <para>
    /// Played rather than asserted against the parse tree, and the count is read off the
    /// permanent: one counter is what a player would see, and three is the bug.
    /// </para>
    /// </remarks>
    [Fact]
    public void Cards_leaving_a_graveyard_together_trigger_the_ability_once()
    {
        var mascot = Card(
            "Batch Mascot Test",
            "Whenever one or more cards leave your graveyard, put a +1/+1 counter on "
                + "Batch Mascot Test.",
            CardType.Creature,
            1,
            1);

        var compiled = CardCompiler.Compile(mascot);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var watcher = game.Create(alice, mascot, Zone.Battlefield);

        game.Create(alice, TestCards.Creature("Batch Ally Test", 2, 2), Zone.Graveyard);
        game.Create(alice, TestCards.Creature("Batch Scout Test", 2, 2), Zone.Graveyard);
        game.Create(alice, TestCards.BasicLand("Batch Waste Test"), Zone.Graveyard);

        // One effect empties the graveyard, so all three leave at the same moment.
        var rake = Card("Batch Rake Test", "Exile target player's graveyard.", CardType.Sorcery);
        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, rake), [Target.ToPlayer(alice)]);

        Settle(game);

        Assert.Equal(1, TimesTriggered(game, watcher));
        Assert.Equal(1, GrowthOn(game, watcher));
    }

    /// <summary>
    /// A batch the sentence describes narrowly fires once, and one it does not describe at all
    /// does not fire.
    /// </summary>
    /// <remarks>
    /// "One or more <em>creature</em> cards" is the same trigger with the batch filtered, and the
    /// two halves fail in opposite directions: a filter nobody applied fires on a graveyard of
    /// lands, and a filter applied per card fires once for each creature. Both are asserted here,
    /// in one game, because a test that only proved the first would pass on an engine that fired
    /// twice for two creatures.
    /// </remarks>
    [Fact]
    public void Only_the_cards_the_sentence_describes_fire_the_batch_trigger()
    {
        var watchtower = Card(
            "Bone Watcher Test",
            "Whenever one or more creature cards leave your graveyard, put a +1/+1 counter on "
                + "Bone Watcher Test.",
            CardType.Creature,
            2,
            2);

        var compiled = CardCompiler.Compile(watchtower);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var watcher = game.Create(alice, watchtower, Zone.Battlefield);

        game.Create(alice, TestCards.BasicLand("Bone Waste One Test"), Zone.Graveyard);
        game.Create(alice, TestCards.BasicLand("Bone Waste Two Test"), Zone.Graveyard);

        var rake = Card("Bone Rake Test", "Exile target player's graveyard.", CardType.Sorcery);
        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, rake), [Target.ToPlayer(alice)]);

        Settle(game);

        // Two lands left the graveyard and no creature card did, so nothing triggered.
        Assert.Equal(0, TimesTriggered(game, watcher));
        Assert.Equal(0, GrowthOn(game, watcher));

        game.Create(alice, TestCards.Creature("Bone Ally Test", 2, 2), Zone.Graveyard);
        game.Create(alice, TestCards.Creature("Bone Scout Test", 2, 2), Zone.Graveyard);
        game.Create(alice, TestCards.BasicLand("Bone Waste Three Test"), Zone.Graveyard);

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, rake), [Target.ToPlayer(alice)]);

        Settle(game);

        // Two creature cards among them, and the ability still fired exactly once.
        Assert.Equal(1, TimesTriggered(game, watcher));
        Assert.Equal(1, GrowthOn(game, watcher));
    }

    /// <summary>
    /// Discarding a whole hand is one discard, and "that many" is how many went.
    /// </summary>
    /// <remarks>
    /// The counter total alone cannot tell the two failures apart - seven triggers of one counter
    /// each and one trigger of seven counters both leave seven counters on the permanent - so the
    /// trigger is counted as well. The second failure is the one this file records against the
    /// attack batch, where the trigger fired and added nothing because the declaration carried no
    /// amount, and it is why a batch has to say how big it was.
    /// </remarks>
    [Fact]
    public void Discarding_a_whole_hand_triggers_once_and_says_how_many_went()
    {
        var mako = Card(
            "Batch Mako Test",
            "Whenever you discard one or more cards, put that many +1/+1 counters on "
                + "Batch Mako Test.",
            CardType.Creature,
            3,
            3);

        var compiled = CardCompiler.Compile(mako);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var watcher = game.Create(alice, mako, Zone.Battlefield);

        var dump = Card("Batch Dump Test", "Discard your hand.", CardType.Sorcery);
        var card = TestCards.PutInHand(game, alice, dump);
        var held = game.State.GetPlayer(alice).Hand.Count - 1;

        game.CastSpell(alice, card, []);
        Settle(game);

        Assert.Empty(game.State.GetPlayer(alice).Hand);

        // One trigger for the whole hand, carrying the size of the batch it was about.
        Assert.Equal(1, TimesTriggered(game, watcher));
        Assert.Equal(held, GrowthOn(game, watcher));
    }

    /// <summary>An opponent's discard does not fire a trigger that says "you discard".</summary>
    /// <remarks>
    /// The batch event names one player and the sentence is possessive. Without the comparison
    /// the trigger would watch the table, which is a wider card than the one printed - and the
    /// wording that really does watch the table ("whenever one or more players discard one or
    /// more cards") is read separately for exactly that reason.
    /// </remarks>
    [Fact]
    public void A_discard_trigger_that_says_you_ignores_an_opponents_discard()
    {
        var mako = Card(
            "Watchful Mako Test",
            "Whenever you discard one or more cards, put a +1/+1 counter on Watchful Mako Test.",
            CardType.Creature,
            3,
            3);

        var (game, alice, bob) = InMainPhase();
        var watcher = game.Create(alice, mako, Zone.Battlefield);

        var dump = Card(
            "Enemy Dump Test", "Target player discards two cards.", CardType.Sorcery);

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, dump), [Target.ToPlayer(bob)]);

        Settle(game);

        Assert.Equal(0, TimesTriggered(game, watcher));
        Assert.Equal(0, GrowthOn(game, watcher));
    }

    // ---- A mana payment asked mid-resolution (CR 605.3a) ---------------------

    /// <summary>A land with two basic types, which still taps only once.</summary>
    /// <remarks>
    /// The fixture the per-permanent half of the search needs. Its two mana abilities come from
    /// its two subtypes (CR 305.6), so it offers a choice of two colours and delivers one of
    /// them - which is exactly the case a "how much mana could you make" total gets wrong.
    /// </remarks>
    private static CardDefinition Dual(string name) => new()
    {
        OracleId = "oracle-" + name.ToLowerInvariant().Replace(' ', '-'),
        Name = name,
        Cmc = 0,
        CardTypes = CardType.Land,
        Subtypes = ["Forest", "Island"],
        ColorIdentity = [ManaColor.Green, ManaColor.Blue],
    };

    /// <summary>
    /// Walks a game to Bob's main phase with a spell of his on the stack, taxed by Alice.
    /// </summary>
    /// <remarks>
    /// Every test in this section needs the same six steps, and the interesting line is always
    /// the one after them. The threat gains life rather than doing nothing so that whether it
    /// resolved is a number on the board and not an absence.
    /// </remarks>
    private static (Game Game, Guid Alice, Guid Bob) TaxedSpell(string label, string cost)
    {
        var (game, alice, bob) = InMainPhase();

        TestCards.PassUntil(game, () => game.State.ActivePlayerId == bob
            && game.State.CurrentStep == TurnStep.PrecombatMain
            && game.State.Priority.Holder == bob);

        var threat = TestCards.PutInHand(
            game, bob, Card($"{label} Threat Test", "You gain 6 life."));

        // A card becomes a new object when it moves to the stack (CR 400.7), so the id to target
        // is the one casting returns - not the one it had in hand.
        var onStack = game.CastSpell(bob, threat, []);

        TestCards.PassUntil(game, () => game.State.Priority.Holder == alice);

        var leak = Card(
            $"{label} Leak Test", $"Counter target spell unless its controller pays {cost}.");

        var compiled = CardCompiler.Compile(leak);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        game.CastSpell(alice, TestCards.PutInHand(game, alice, leak), [Target.ToSpell(onStack)]);
        return (game, alice, bob);
    }

    /// <summary>Every land Bob controls, so a test can tap them one at a time.</summary>
    private static List<ObjectId> LandsOf(Game game, Guid playerId) =>
        [.. game.State.Battlefield
            .Where(id => game.State.GetObject(id).OwnerId == playerId
                && game.State.GetObject(id).Card.CardTypes.HasFlag(CardType.Land))];

    /// <summary>
    /// A player with untapped lands is asked for the tax and may tap them to pay it (CR 605.3a).
    /// </summary>
    /// <remarks>
    /// The largest "the answer is forced" surface this engine had. CR 605.3a lets a player
    /// activate mana abilities whenever a rule or effect asks them for a mana payment, including
    /// in the middle of a resolution; this engine read the mana <em>pool</em> instead, so every
    /// "counter target spell unless its controller pays {3}" auto-declined against anyone who had
    /// not floated the mana before the counterspell was even cast. CR 118.3 was declining on
    /// their behalf, correctly, from a false premise.
    /// <para>
    /// Bob's pool is empty when the question arrives and he pays anyway, which is the whole
    /// claim. The two halves that make it work were already in the engine and had never met:
    /// <c>Game.ActivateAbility</c> requires priority only for an ability that is not a mana
    /// ability, and a mana ability returns from it without settling, so the pending question
    /// survives the three activations below.
    /// </para>
    /// <para>
    /// <c>Settle</c> asserts the log replays to this state, which is the other thing worth
    /// proving here: nothing about this is a suspended continuation. The taps are ordinary
    /// logged activations and the answer is an ordinary <c>ChoiceMade</c>.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_player_with_untapped_lands_is_asked_the_tax_and_may_tap_to_pay_it()
    {
        var (game, _, bob) = TaxedSpell("Untapped", "{3}");

        for (var i = 0; i < 3; i++)
            game.Create(bob, TestCards.BasicLand("Forest"), Zone.Battlefield);

        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.OptionalPayment });

        // Asked, with nothing floated - which is the line that used to be unreachable.
        Assert.Equal(bob, game.State.Choice!.PlayerId);
        Assert.True(game.State.GetPlayer(bob).ManaPool.IsEmpty);

        // CR 605.3a: the mana abilities are activated while the question stands, and the
        // question is still standing after each of them.
        foreach (var land in LandsOf(game, bob))
        {
            game.ActivateAbility(bob, land, "mana");
            Assert.NotNull(game.State.Choice);
        }

        Assert.Equal(3, game.State.GetPlayer(bob).ManaPool[ManaColor.Green]);

        game.Choose(bob, ["yes"]);
        Settle(game);

        // The spell resolved and the tax was actually charged.
        Assert.Equal(26, game.State.GetPlayer(bob).Life);
        Assert.True(game.State.GetPlayer(bob).ManaPool.IsEmpty);
    }

    /// <summary>
    /// A player who could not make the mana is still not asked (CR 118.3).
    /// </summary>
    /// <remarks>
    /// The half of the old behaviour that was right, and the one the fix must not lose: a
    /// question with one possible answer is not a question, and stopping the game to put it is
    /// how a game stalls. One Forest cannot pay {3}, so nothing is asked and the counter simply
    /// resolves.
    /// <para>
    /// Asserted against the log rather than the state: a question asked and answered leaves no
    /// trace in the state, so "nothing outstanding now" would pass either way.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_player_who_could_not_make_the_mana_is_not_asked_at_all()
    {
        var (game, _, bob) = TaxedSpell("Short", "{3}");

        game.Create(bob, TestCards.BasicLand("Forest"), Zone.Battlefield);

        Settle(game);

        Assert.DoesNotContain(
            game.Log,
            e => e is ChoiceRequested { Choice.Kind: ChoiceKind.OptionalPayment });

        // Countered, so he gained nothing.
        Assert.Equal(20, game.State.GetPlayer(bob).Life);
        Assert.Empty(game.State.Stack);
    }

    /// <summary>
    /// A tapped land is not mana the player has (CR 602.5b).
    /// </summary>
    /// <remarks>
    /// The same board as the paying test and the same cost, with the lands already down. Without
    /// this the check could have counted every permanent on the battlefield and passed everything
    /// else in this section.
    /// </remarks>
    [Fact]
    public void Lands_already_tapped_do_not_make_the_question_worth_asking()
    {
        var (game, _, bob) = TaxedSpell("Tapped", "{3}");

        foreach (var land in Enumerable.Range(0, 3)
            .Select(_ => game.Create(bob, TestCards.BasicLand("Forest"), Zone.Battlefield))
            .ToList())
        {
            game.Tap(land);
        }

        Settle(game);

        Assert.DoesNotContain(
            game.Log,
            e => e is ChoiceRequested { Choice.Kind: ChoiceKind.OptionalPayment });

        Assert.Equal(20, game.State.GetPlayer(bob).Life);
    }

    /// <summary>
    /// Saying yes without tapping anything is a decline (CR 601.2h).
    /// </summary>
    /// <remarks>
    /// What makes it safe for the gate to be optimistic. The question is now asked on the
    /// strength of what a player <em>could</em> produce, so the answer alone can no longer be
    /// trusted - <c>ResolveOptionalPayment</c> re-checks the real pool before charging it, and a
    /// yes it cannot honour runs the "if you don't" branch instead of granting the cost for free.
    /// <para>
    /// This is the failure mode a looser fix would have shipped: an offer that pays out on the
    /// word rather than on the mana is a card strictly better than the one printed.
    /// </para>
    /// </remarks>
    [Fact]
    public void Answering_yes_without_tapping_anything_declines()
    {
        var (game, _, bob) = TaxedSpell("Bluff", "{3}");

        for (var i = 0; i < 3; i++)
            game.Create(bob, TestCards.BasicLand("Forest"), Zone.Battlefield);

        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.OptionalPayment });

        game.Choose(bob, ["yes"]);
        Settle(game);

        // Countered anyway, and the lands are all still untapped: nothing was taken and nothing
        // was given.
        Assert.Equal(20, game.State.GetPlayer(bob).Life);
        Assert.All(
            LandsOf(game, bob),
            id => Assert.False(game.State.GetObject(id).Permanent!.IsTapped));
    }

    /// <summary>
    /// A land with two types taps once, so two colours want two lands (CR 106.7).
    /// </summary>
    /// <remarks>
    /// The reason the check is a search rather than a total. One land that could make {G} or {U}
    /// cannot pay {G}{U}: it taps once and makes one of them. Adding up everything the board
    /// could produce says yes, and a game that asks the question then hands the player a decision
    /// they cannot carry out - which is the same defect as the auto-decline, pointing the other
    /// way.
    /// </remarks>
    [Fact]
    public void One_dual_land_cannot_pay_a_cost_of_two_colours()
    {
        var (game, _, bob) = TaxedSpell("Single Dual", "{G}{U}");

        game.Create(bob, Dual("Solo Dual Test"), Zone.Battlefield);

        Settle(game);

        Assert.DoesNotContain(
            game.Log,
            e => e is ChoiceRequested { Choice.Kind: ChoiceKind.OptionalPayment });

        Assert.Equal(20, game.State.GetPlayer(bob).Life);
    }

    /// <summary>
    /// Two of them can, and the second colour comes from the second land (CR 605.3a).
    /// </summary>
    /// <remarks>
    /// The other side of the test above, on a board one land larger. Bob taps each for a
    /// different colour, which is a choice the engine could not have made for him - and the
    /// reason the payment is a question at all rather than something the settle could pay off.
    /// </remarks>
    [Fact]
    public void Two_dual_lands_pay_a_cost_of_two_colours()
    {
        var (game, _, bob) = TaxedSpell("Pair Dual", "{G}{U}");

        game.Create(bob, Dual("First Dual Test"), Zone.Battlefield);
        game.Create(bob, Dual("Second Dual Test"), Zone.Battlefield);

        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.OptionalPayment });
        Assert.Equal(bob, game.State.Choice!.PlayerId);

        // The subtypes are read in order, so "mana" is the Forest half and "mana1" the Island
        // half (CR 305.6).
        var lands = LandsOf(game, bob);
        game.ActivateAbility(bob, lands[0], "mana");
        game.ActivateAbility(bob, lands[1], "mana1");

        Assert.Equal(1, game.State.GetPlayer(bob).ManaPool[ManaColor.Green]);
        Assert.Equal(1, game.State.GetPlayer(bob).ManaPool[ManaColor.Blue]);

        game.Choose(bob, ["yes"]);
        Settle(game);

        Assert.Equal(26, game.State.GetPlayer(bob).Life);
    }

    /// <summary>
    /// A creature's mana ability is not available the turn it arrives (CR 302.6).
    /// </summary>
    /// <remarks>
    /// A mana creature is the other thing that pays a tax, and summoning sickness is the one
    /// restriction on it that a land never shows. The same board, one turn later, is the paying
    /// test above; here the question is never put, because the {T} cost cannot be paid.
    /// </remarks>
    [Fact]
    public void A_summoning_sick_mana_creature_does_not_make_the_question_worth_asking()
    {
        var elf = Card(
            "Sick Elf Test", "{T}: Add {G}.", CardType.Creature, 1, 1, KeywordAbility.None, "Elf");

        var compiled = CardCompiler.Compile(elf);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, _, bob) = TaxedSpell("Sick", "{1}");

        game.Create(bob, elf, Zone.Battlefield);

        Settle(game);

        Assert.DoesNotContain(
            game.Log,
            e => e is ChoiceRequested { Choice.Kind: ChoiceKind.OptionalPayment });

        Assert.Equal(20, game.State.GetPlayer(bob).Life);
    }

    // ---- "Instead": one instruction with two arms (CR 614.15) ----------------

    /// <summary>
    /// "[A]. If [condition], [B] instead." — B happens <em>rather than</em> A.
    /// </summary>
    /// <remarks>
    /// The card count is the assertion rather than "something was drawn", because only a count
    /// separates the three readings: two cards is the sentence in front of the clause, three is
    /// the replacement, and five is the misreading — "instead" read as "as well", which compiles
    /// clean and plays a strictly better card than the one printed.
    /// </remarks>
    [Theory]
    [InlineData(false, 2)]
    [InlineData(true, 3)]
    public void An_instead_clause_replaces_the_sentence_in_front_of_it(bool kicked, int drawn)
    {
        // Field Research.
        var research = Kicked(
            "Instead Draw Test", "{1}",
            "Kicker {1}" + (char)10
                + "Draw two cards. If this spell was kicked, draw three cards instead.");

        var compiled = CardCompiler.Compile(research);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, research);

        foreach (var _ in Enumerable.Range(0, 2))
        {
            var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
            game.ActivateAbility(alice, forest, "mana");
        }

        var before = game.State.GetPlayer(alice).Library.Count;

        game.CastSpell(
            alice, card, targets: null, variableValue: 0, tapToPay: null, modes: null,
            kicked: kicked);

        Settle(game);

        Assert.Equal(before - drawn, game.State.GetPlayer(alice).Library.Count);
    }

    /// <summary>
    /// "That creature" in the replacement is the creature the sentence in front of it targeted.
    /// </summary>
    /// <remarks>
    /// The printed replacement almost never repeats the target phrase, so this pronoun is what
    /// makes the family readable at all — and it was read wrongly. A matcher for the bare "that
    /// creature gets +N/+N until end of turn" sat in front of the pronoun reader that knows the
    /// order and aimed the pump at the <em>source</em>: on an instant that is the spell itself,
    /// so the kicked half of every card of this shape did nothing whatsoever. A 2/2 left at 2/2
    /// is the fourth reading this one number tells apart, beside 5, 7 and the additive 10.
    /// </remarks>
    [Theory]
    [InlineData(false, 5)]
    [InlineData(true, 7)]
    public void The_replacement_is_aimed_at_what_the_sentence_before_it_targeted(
        bool kicked, int power)
    {
        // Might of Murasa.
        var might = Kicked(
            "Instead Pump Test", "{1}",
            "Kicker {1}" + (char)10
                + "Target creature gets +3/+3 until end of turn. If this spell was kicked, "
                + "that creature gets +5/+5 until end of turn instead.");

        var compiled = CardCompiler.Compile(might);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var bear = game.Create(alice, TestCards.Creature("Instead Pump Bear", 2, 2), Zone.Battlefield);
        var card = TestCards.PutInHand(game, alice, might);

        foreach (var _ in Enumerable.Range(0, 2))
        {
            var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
            game.ActivateAbility(alice, forest, "mana");
        }

        game.CastSpell(
            alice, card, [Target.ToPermanent(bear)], variableValue: 0, tapToPay: null,
            modes: null, kicked: kicked);

        Settle(game);

        Assert.Equal(power, Characteristics.Of(game.State, Pool, game.State.GetObject(bear)).Power);
    }

    /// <summary>Only the sentence in front of the clause is replaced, not the whole phrase.</summary>
    /// <remarks>
    /// Gift of Growth is three sentences and "instead" replaces one of them: the untap happens
    /// whether the spell was kicked or not. A rider that swallowed everything read so far would
    /// print a card that stops untapping the moment you pay more for it, and nothing about the
    /// compile would look wrong.
    /// </remarks>
    [Fact]
    public void An_instead_replaces_one_sentence_rather_than_everything_before_it()
    {
        var gift = Kicked(
            "Instead Untap Test", "{1}",
            "Kicker {1}" + (char)10
                + "Untap target creature. It gets +2/+2 until end of turn. If this spell was "
                + "kicked, that creature gets +4/+4 until end of turn instead.");

        var compiled = CardCompiler.Compile(gift);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var bear = game.Create(alice, TestCards.Creature("Instead Untap Bear", 2, 2), Zone.Battlefield);

        var tapper = Card("Instead Tapper Test", "Tap target creature.");
        var tap = TestCards.PutInHand(game, alice, tapper);
        game.CastSpell(alice, tap, [Target.ToPermanent(bear)]);
        Settle(game);
        Assert.True(game.State.GetObject(bear).Permanent?.IsTapped);

        var card = TestCards.PutInHand(game, alice, gift);

        foreach (var _ in Enumerable.Range(0, 2))
        {
            var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
            game.ActivateAbility(alice, forest, "mana");
        }

        game.CastSpell(
            alice, card, [Target.ToPermanent(bear)], variableValue: 0, tapToPay: null,
            modes: null, kicked: true);

        Settle(game);

        // The untap is the sentence before the one that was replaced, so it still happens; the
        // pump is 4 rather than 2, and not 6, which is what running both arms would give.
        Assert.False(game.State.GetObject(bear).Permanent?.IsTapped);
        Assert.Equal(6, Characteristics.Of(game.State, Pool, game.State.GetObject(bear)).Power);
    }

    /// <summary>A board condition decides which of the two arms happens.</summary>
    /// <remarks>
    /// The control case is the point: with the condition false the card has to do exactly what
    /// its first sentence says. A replacement that applied either way, or one that never applied,
    /// both compile — and only playing the card with the condition unmet can tell them apart.
    /// </remarks>
    [Theory]
    [InlineData(1, 4)]
    [InlineData(4, 6)]
    public void A_board_condition_chooses_which_arm_of_the_instruction_happens(
        int creatures, int power)
    {
        // For the Family.
        var family = Card(
            "Instead Condition Test",
            "Target creature gets +2/+2 until end of turn. If you control four or more creatures, "
                + "that creature gets +4/+4 until end of turn instead.");

        var compiled = CardCompiler.Compile(family);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();

        var bear = game.Create(
            alice, TestCards.Creature("Instead Condition Bear", 2, 2), Zone.Battlefield);

        foreach (var extra in Enumerable.Range(1, creatures - 1))
        {
            game.Create(
                alice,
                TestCards.Creature(
                    "Instead Condition Friend "
                        + extra.ToString(CultureInfo.InvariantCulture),
                    1,
                    1),
                Zone.Battlefield);
        }

        var card = TestCards.PutInHand(game, alice, family);
        game.CastSpell(alice, card, [Target.ToPermanent(bear)]);
        Settle(game);

        Assert.Equal(power, Characteristics.Of(game.State, Pool, game.State.GetObject(bear)).Power);
    }

    /// <summary>
    /// The other word order, and the line break the ability word forces in front of it.
    /// </summary>
    /// <remarks>
    /// Mirran Mettle prints one instruction across two lines: an ability word is flavour with no
    /// rules meaning (CR 207.2c), and what follows it is half a sentence — a replacement whose
    /// branch is on the line above. A line is the unit the compiler reads, so both halves of this
    /// family meet here: the trailing word order, and the fold that gives the clause something to
    /// replace. Forty-six cards print the replacement this way round and every one of them is
    /// behind an ability word.
    /// <para>
    /// The control case is the assertion that matters. With no artifacts out the card has to be
    /// the +2/+2 its first line prints; a fold that ran both lines would be +6/+6, and one that
    /// ran only the second would be +4/+4 for free.
    /// </para>
    /// </remarks>
    [Theory]
    [InlineData(0, 4)]
    [InlineData(3, 6)]
    public void The_other_word_order_survives_the_line_the_ability_word_broke(
        int artifacts, int power)
    {
        var mettle = Card(
            "Instead Trailing Test",
            "Target creature gets +2/+2 until end of turn." + (char)10
                + "Metalcraft — That creature gets +4/+4 until end of turn instead if you "
                + "control three or more artifacts.");

        var compiled = CardCompiler.Compile(mettle);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var bear = game.Create(
            alice, TestCards.Creature("Instead Trailing Bear", 2, 2), Zone.Battlefield);

        foreach (var made in Enumerable.Range(1, artifacts))
        {
            game.Create(
                alice,
                Card(
                    "Instead Trailing Relic " + made.ToString(CultureInfo.InvariantCulture),
                    string.Empty,
                    CardType.Artifact),
                Zone.Battlefield);
        }

        var card = TestCards.PutInHand(game, alice, mettle);
        game.CastSpell(alice, card, [Target.ToPermanent(bear)]);
        Settle(game);

        Assert.Equal(power, Characteristics.Of(game.State, Pool, game.State.GetObject(bear)).Power);
    }

    /// <summary>A replaced instruction goes into the branch whole, clauses and all.</summary>
    /// <remarks>
    /// Primal Growth is one printed sentence cut into three clauses by ", then", and the unit the
    /// word "instead" replaces is the sentence. Taking only the last clause would leave the search
    /// outside the swap, so a kicked spell would search twice and fetch three lands.
    /// </remarks>
    [Theory]
    [InlineData(false, 1)]
    [InlineData(true, 2)]
    public void A_multi_clause_instruction_is_replaced_whole(bool kicked, int fetched)
    {
        var growth = Kicked(
            "Instead Search Test", "{1}",
            "Kicker {1}" + (char)10
                + "Search your library for a basic land card, put that card onto the battlefield, "
                + "then shuffle. If this spell was kicked, instead search your library for up to "
                + "two basic land cards, put them onto the battlefield, then shuffle.");

        var compiled = CardCompiler.Compile(growth);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();

        foreach (var _ in Enumerable.Range(0, 2))
            game.Create(alice, TestCards.BasicLand("Instead Search Forest"), Zone.Library);

        var card = TestCards.PutInHand(game, alice, growth);

        foreach (var _ in Enumerable.Range(0, 2))
        {
            var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
            game.ActivateAbility(alice, forest, "mana");
        }

        game.CastSpell(
            alice, card, targets: null, variableValue: 0, tapToPay: null, modes: null,
            kicked: kicked);

        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.SearchLibrary });
        game.Choose(alice, [.. game.State.Choice!.Options!.Take(fetched).Select(o => o.Id)]);

        Settle(game);

        Assert.Equal(
            fetched,
            game.State.Battlefield.Count(
                id => game.State.GetObject(id).Card.Name == "Instead Search Forest"));
    }

    /// <summary>An "instead" whose branch cannot be found stays unread.</summary>
    /// <remarks>
    /// The other side of the fold above, and the reason the fold can be as blunt as it is: the
    /// two lines are joined only when they read as one phrase together, so a pair that does not
    /// is left exactly as it was.
    /// <para>
    /// Two ways that happens, and both are here. A clause with no line at all in front of it has
    /// nothing to replace — it is the whole card — and one whose condition
    /// <see cref="BoardConditions"/> cannot answer has no branch to guard. Read either way, the
    /// card would deal its bigger damage <em>as well as</em> its smaller, which is the worst
    /// available misreading of the word on the gentlest available wording. Unread is a card the
    /// deck check refuses rather than one that plays wrongly.
    /// </para>
    /// <para>
    /// Galvanic Blast used to be the example here, and is not any more: its clause is elliptical
    /// rather than orphaned, and the recipient it leaves out is the one the line above named. It
    /// now reads, and
    /// <see cref="An_ability_words_instead_resizes_the_damage_on_the_line_above_it"/> plays it.
    /// </para>
    /// </remarks>
    [Fact]
    public void An_instead_with_nothing_in_front_of_it_stays_unread()
    {
        var orphan = CardCompiler.Compile(Card(
            "Instead Orphan Test",
            "Metalcraft — ~ deals 4 damage instead if you control three or more artifacts."));

        Assert.False(orphan.IsComplete);
        Assert.Contains(
            orphan.Unhandled,
            line => line.Contains("instead", StringComparison.Ordinal));

        Assert.Null(BoardConditions.Parse("you flipped a coin and won three times this turn"));

        var unaskable = CardCompiler.Compile(Card(
            "Instead Unaskable Test",
            "~ deals 2 damage to any target." + (char)10
                + "Metalcraft — ~ deals 4 damage instead if you flipped a coin and won three "
                + "times this turn."));

        Assert.False(unaskable.IsComplete);
        Assert.Contains(
            unaskable.Unhandled,
            line => line.Contains("instead", StringComparison.Ordinal));
    }

    /// <summary>A replacement that lands somewhere else than the sentence it replaces is refused.</summary>
    /// <remarks>
    /// Blade of the Bloodchief. "It" is the equipped creature the sentence in front named, and the
    /// pronoun readers answer with the creature the trigger was about — the one that just died.
    /// Two counters on a card in a graveyard is not the card, so the reader refuses: the two arms
    /// of one instruction have to be about the same thing, and where they are aimed is asked
    /// through the one thing that knows whether an index is a target at all.
    /// </remarks>
    [Fact]
    public void A_replacement_aimed_elsewhere_than_what_it_replaces_stays_unread()
    {
        var blade = Card(
            "Instead Aim Test",
            "Whenever a creature dies, put a +1/+1 counter on equipped creature. If equipped "
                + "creature is a Vampire, put two +1/+1 counters on it instead."
                + (char)10 + "Equip {1}",
            CardType.Artifact,
            null,
            null,
            KeywordAbility.None,
            "Equipment");

        var compiled = CardCompiler.Compile(blade);

        Assert.False(compiled.IsComplete);
        Assert.Contains(
            compiled.Unhandled,
            line => line.Contains("two +1/+1 counters on it instead", StringComparison.Ordinal));
    }

    // ---- The shorter twin, and an id that changed every run -------------------

    /// <summary>
    /// "Creatures you control get +N/+N until end of turn" reaches your creatures and no others.
    /// </summary>
    /// <remarks>
    /// Two readers used to answer this sentence. <c>MassPumpLine</c> reads the noun phrase through
    /// the group vocabulary and builds a <c>PumpGroup</c> over the parsed spec; a second matcher
    /// further down spelled this one group out in its own pattern and built a different effect,
    /// <c>PumpCreaturesYouControl</c>, which selected its creatures by reading
    /// <c>obj.ControllerId</c> — where control <em>started</em> rather than where it is
    /// (CR 613.1b). Nothing could reach it, because the first reader claims every sentence the
    /// second could match, so the wrong half was never run and never noticed.
    /// <para>
    /// It is gone, and this is the test that the surviving reader does the whole job: the group
    /// is "you control", so the creature across the table is not in it.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_group_pump_reaches_your_creatures_and_stops_at_the_table_edge()
    {
        var rite = Card(
            "Test Pump Rite",
            "Creatures you control get +2/+2 until end of turn.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(rite);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();

        var mine = game.Create(alice, TestCards.Creature("Test Twin Rite Bear", 2, 2), Zone.Battlefield);
        var alsoMine = game.Create(
            alice, TestCards.Creature("Test Twin Rite Ox", 1, 1), Zone.Battlefield);
        var theirs = game.Create(bob, TestCards.Creature("Test Twin Rite Wolf", 2, 2), Zone.Battlefield);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, rite), []);
        Settle(game);

        Assert.Equal(4, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(mine)));
        Assert.Equal(3, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(alsoMine)));
        Assert.Equal(2, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(theirs)));
    }

    /// <summary>
    /// A counter the group action cannot name is refused rather than rounded down to +1/+1.
    /// </summary>
    /// <remarks>
    /// The counter half of the same pair. <c>MassCountersLine</c> read "put a +1/+1 counter on
    /// each …" beneath <c>CounterOnEachLine</c>, whose language strictly contains it, so control
    /// never arrived there with a sentence it could take — and where the two would have differed
    /// the twin was the weaker one twice over. It had no reading for "other", which
    /// <see cref="A_counter_on_each_other_creature_leaves_the_source_out"/> covers, and no
    /// refusal for the mis-sized counter, which is this. Compiled as a +1/+1 it would have read
    /// complete and done a quarter of what it printed.
    /// </remarks>
    [Fact]
    public void A_counter_the_group_action_cannot_name_is_refused()
    {
        var compiled = CardCompiler.Compile(Card(
            "Test Oversized Counters",
            "Put a +4/+4 counter on each creature you control.",
            CardType.Sorcery));

        Assert.False(compiled.IsComplete);
        Assert.Contains(
            compiled.Unhandled,
            line => line.Contains("+4/+4 counter on each", StringComparison.Ordinal));
    }

    /// <summary>
    /// An adjective in front of a granted group is read as one, not as a creature type.
    /// </summary>
    /// <remarks>
    /// The bug <c>ReadStaticGroup</c> was written to end for the lord, still standing one reader
    /// over: the granted-ability matcher kept its own noun grammar, whose tribe slot is "a
    /// capitalised word" — and so is every adjective that can stand there. "Green creatures you
    /// control have …" compiled to a grant for the creature type "Green", which no card has, so
    /// it read as complete and handed the ability to nobody. A reader that never fires looks
    /// exactly like a reader that works.
    /// <para>
    /// The white bear is the half that carries the test: before the fix <em>neither</em> creature
    /// had the ability, and an assertion that only asked about the green one would have passed on
    /// a card that granted nothing at all.
    /// </para>
    /// </remarks>
    [Fact]
    public void An_adjective_in_front_of_a_granted_group_is_read_as_one()
    {
        var chant = Card(
            "Test Verdant Chant",
            "Green creatures you control have \"{T}: Add {G}.\"",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(chant);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();

        var green = game.Create(alice, Coloured("Test Chant Elf", ManaColor.Green), Zone.Battlefield);
        var white = game.Create(alice, Coloured("Test Chant Cleric", ManaColor.White), Zone.Battlefield);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, chant), []);
        Settle(game);

        Assert.Single(
            Characteristics.Of(game.State, Pool, game.State.GetObject(green)).GrantedActivated);

        Assert.Empty(
            Characteristics.Of(game.State, Pool, game.State.GetObject(white)).GrantedActivated);
    }

    /// <summary>
    /// A granted group whose adjective cannot be answered leaves the line unread.
    /// </summary>
    /// <remarks>
    /// The third answer the shared adjective vocabulary gives, and the one that matters: a word
    /// recognised as an adjective and not answerable refuses the line rather than falling through
    /// to the tribe reading. "Modified" wants counters, Auras and Equipment (CR 700.9); read as a
    /// creature type it compiled complete and granted to nobody, which is the silent no-op this
    /// whole path exists to stop. Unread is the honest outcome — a card a deck check refuses is a
    /// card somebody notices.
    /// </remarks>
    [Fact]
    public void A_granted_group_whose_adjective_cannot_be_answered_is_left_unread()
    {
        var compiled = CardCompiler.Compile(Card(
            "Test Modified Chant",
            "Modified creatures you control have \"{T}: Add {G}.\"",
            CardType.Enchantment));

        Assert.False(compiled.IsComplete);
        Assert.Contains(
            compiled.Unhandled,
            line => line.Contains("Modified creatures", StringComparison.Ordinal));
    }

    /// <summary>
    /// A definition id is the same string in every process.
    /// </summary>
    /// <remarks>
    /// The attached-count static folded <c>string.GetHashCode</c> into its id, and that is
    /// randomised per process on .NET Core — a fact this codebase had already written down twice,
    /// in <c>EffectPhrase.StableHash</c> and in <c>DeterministicSample</c>, and still had one
    /// place that did not follow it. Eleven cards — Kor Spiritdancer, Uril, Rabid Wombat, Goblin
    /// Gaveleer and the rest of the Aura and Equipment counters — compiled to a different id every
    /// run.
    /// <para>
    /// Nothing in a running game noticed, because ids are only ever compared inside one process.
    /// What noticed was a compiled-effect diff across two runs, which reported those eleven as
    /// changed by a commit that could not have touched them: a comparison that cannot tell a real
    /// change from a re-run is the cost of a per-process id long before a replayed log is.
    /// </para>
    /// <para>
    /// The expected value is written out rather than recomputed, because a test that hashes the
    /// line itself would agree with any hash at all, including the one this replaced.
    /// </para>
    /// </remarks>
    [Fact]
    public void An_attached_count_static_keeps_its_id_between_processes()
    {
        var compiled = CardCompiler.Compile(Card(
            "Test Aura Counter",
            "~ gets +2/+2 for each Aura attached to it.",
            CardType.Creature,
            2,
            2));

        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        Assert.Equal(
            "attached-count:Test Aura Counter:2/2:Aura:0ff8e996",
            Assert.Single(compiled.Statics).Id);
    }

    /// <summary>
    /// "…, then shuffle" after a search is read as the search having already done it
    /// (CR 701.23e).
    /// </summary>
    /// <remarks>
    /// The largest of the duplicate pairs and the only one where the shadowed reader was the
    /// right one. A reader beside the search vocabulary said exactly this and cited this rule,
    /// and it could never run: the general shuffle matches the same clause 2,200 lines earlier
    /// and adds its effect unconditionally, so <strong>465 cards</strong> — every fetchland,
    /// every basic-land ramp spell, Solemn Simulacrum, Prismatic Vista — compiled a second
    /// shuffle after the search.
    /// <para>
    /// Two shuffles are not illegal, which is why nothing failed. They are not what the card
    /// says: each one takes a draw from the seeded random and writes another
    /// <c>LibraryShuffled</c> into the log a replay has to carry, so two games that should be
    /// identical part company the moment one of them fetches.
    /// </para>
    /// <para>
    /// Counted in the log rather than in the parse tree, because the parse tree is where the
    /// reader that was already there put its claim, and that claim was not true of the game.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_shuffle_printed_after_a_search_is_not_a_second_shuffle()
    {
        var quest = Card(
            "Test Fetch Quest",
            "Search your library for a basic land card, put it onto the battlefield tapped,"
                + " then shuffle.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(quest);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.Empty(compiled.Spell!.Effects.OfType<ShuffleLibrary>());

        var alice = Guid.Parse("11111111-1111-1111-1111-111111111111");
        var bob = Guid.Parse("22222222-2222-2222-2222-222222222222");
        var forests = Enumerable.Range(1, 20).Select(_ => TestCards.BasicLand("Forest")).ToList();

        var game = Game.Start(
            Guid.NewGuid(),
            [
                new PlayerSetup(alice, "Alice", 20, forests),
                new PlayerSetup(bob, "Bob", 20, TestCards.Deck(40, "Bob")),
            ],
            new GameRandom(1),
            startingPlayerId: alice,
            abilities: Pool);

        game.BeginPlay(withMulligans: false);
        TestCards.PassToStep(game, TurnStep.PrecombatMain);

        var card = TestCards.PutInHand(game, alice, quest);
        var land = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");

        // Everything the opening shuffle and the draws already wrote, so the count below is the
        // spell's own and not the game's.
        var before = game.Log.Count(e => e is LibraryShuffled);

        game.CastSpell(alice, card, targets: null);
        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.SearchLibrary });

        game.Choose(alice, [game.State.Choice!.Options[0].Id]);
        Settle(game);

        Assert.Equal(before + 1, game.Log.Count(e => e is LibraryShuffled));
    }

    /// <summary>
    /// A shuffle that follows anything else, or nothing, is still a shuffle.
    /// </summary>
    /// <remarks>
    /// The half that makes the guard above a reading rather than a deletion. The reader it
    /// replaced was gated on "something has already been read", which would have swallowed the
    /// shuffle after any instruction at all; this one asks whether the last thing compiled was a
    /// <em>search</em>, walking the tree so that the conditional wording — where the search sits
    /// inside an intervening if and the shuffle does not — is answered too. Primal Command is the
    /// printed card that makes the distinction load-bearing: one of its modes really does shuffle.
    /// </remarks>
    [Fact]
    public void A_shuffle_that_is_not_a_search_s_own_is_still_read()
    {
        var bare = CardCompiler.Compile(
            Card("Test Bare Shuffle", "Shuffle your library.", CardType.Sorcery));

        Assert.True(bare.IsComplete, string.Join(" | ", bare.Unhandled));
        Assert.Single(bare.Spell!.Effects.OfType<ShuffleLibrary>());

        var afterDraw = CardCompiler.Compile(
            Card("Test Draw Then Shuffle", "Draw a card, then shuffle.", CardType.Sorcery));

        Assert.True(afterDraw.IsComplete, string.Join(" | ", afterDraw.Unhandled));
        Assert.Single(afterDraw.Spell!.Effects.OfType<ShuffleLibrary>());

        // The graveyard arm is a different instruction and never was the search's.
        var yard = CardCompiler.Compile(Card(
            "Test Yard Shuffle", "Shuffle your graveyard into your library.", CardType.Sorcery));

        Assert.True(yard.IsComplete, string.Join(" | ", yard.Unhandled));
        Assert.True(yard.Spell!.Effects.OfType<ShuffleLibrary>().Single().GraveyardFirst);

        // And the conditional wording, where the search is inside the if and the shuffle is not.
        var conditional = CardCompiler.Compile(Card(
            "Test Conditional Fetch",
            "If you control four or fewer lands, search your library for a basic land card, put"
                + " it onto the battlefield tapped, then shuffle.",
            CardType.Sorcery));

        Assert.True(conditional.IsComplete, string.Join(" | ", conditional.Unhandled));
        Assert.Empty(conditional.Spell!.Effects.OfType<ShuffleLibrary>());
    }

    // ---- Prevention both ways (CR 615.1) -------------------------------------

    /// <summary>
    /// Maze of Ith: "to and dealt by that creature" is two shields, not one.
    /// </summary>
    /// <remarks>
    /// The sentence was refused outright until the excision census put it at the top of the
    /// corpus - five cards print this exact shape and no other unread sentence is on more than
    /// five. Both directions are asserted in one combat because the failure that matters is a
    /// single shield holding both slots: PreventionEffect reads its victim and its source as an
    /// AND, so one effect naming the creature twice would shield only the damage it dealt to
    /// itself, and the card would do nothing at all while still counting as read.
    /// <para>
    /// The pronoun is the other half of the difficulty. "That creature" is whatever the sentence
    /// in front of it untapped, so the shield has to reuse the target the ability already chose
    /// rather than ask for a second one - a card that asked twice would let the player fog one
    /// creature and untap another.
    /// </para>
    /// </remarks>
    [Fact]
    public void Preventing_damage_both_ways_stops_what_the_creature_deals_and_what_reaches_it()
    {
        var maze = Card(
            "Test Maze of Prevention",
            "{T}: Untap target attacking creature. Prevent all combat damage that would be dealt"
                + " to and dealt by that creature this turn.",
            CardType.Land);

        var compiled = CardCompiler.Compile(maze);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var wall = game.Create(alice, TestCards.Creature("Test Maze Wall", 1, 4), Zone.Battlefield);
        var ogre = game.Create(bob, TestCards.Creature("Test Maze Ogre", 3, 3), Zone.Battlefield);
        var land = game.Create(alice, maze, Zone.Battlefield);

        // Turn 2 is Bob's, so his creature is the one attacking.
        PassTo(game, 2, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            bob,
            new Dictionary<ObjectId, AttackTarget> { [ogre] = AttackTarget.Player(alice) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);
        game.DeclareBlockers(
            alice,
            new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [ogre] = [wall] });

        // The active player gets priority first in every step (CR 117.3a), and on turn 2 that is
        // Bob. Alice cannot activate anything until he has passed it to her.
        TestCards.PassUntil(game, () => game.State.Priority.Holder == alice);

        game.ActivateAbility(alice, land, "a", [Target.ToPermanent(ogre)]);
        Settle(game);

        TestCards.PassUntil(game, () => game.State.CurrentStep > TurnStep.CombatDamage);

        // What it deals: the 1/4 blocking it takes nothing, and neither does Alice.
        Assert.Equal(0, game.State.GetObject(wall).Permanent!.DamageMarked);
        Assert.Equal(20, game.State.GetPlayer(alice).Life);

        // What reaches it: the blocker's one point is prevented too. Without the second shield
        // this is 1 and the card is half of what it prints.
        Assert.Equal(0, game.State.GetObject(ogre).Permanent!.DamageMarked);

        // Two entries and not one, written and read back, so a shield lost on the way through
        // the log shows up here rather than as a card that quietly stops working on replay.
        Assert.Equal(2, game.State.Preventions.Count);
        Assert.Equal(
            game.State,
            GameReducer.Replay(EventLogSerializer.Read(EventLogSerializer.Write(game.Log))));
    }

    /// <summary>
    /// Urborg Phantom: the same sentence about the permanent whose ability it is.
    /// </summary>
    /// <remarks>
    /// Three cards say "this creature" where Maze of Ith says "that creature", and it is a
    /// different thing to resolve: no target is chosen at all, so the shield goes round
    /// <see cref="ResolutionContext.PhysicalSourceId"/> - the creature, not the ability that is
    /// resolving on the stack.
    /// </remarks>
    [Fact]
    public void Preventing_damage_both_ways_around_this_creature_needs_no_target()
    {
        var phantom = Card(
            "Test Phantom Guard",
            "{U}: Prevent all combat damage that would be dealt to and dealt by this creature"
                + " this turn.",
            CardType.Creature,
            power: 3,
            toughness: 3);

        var compiled = CardCompiler.Compile(phantom);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        // No target is asked for, which is the whole difference from the pronoun form.
        Assert.Empty(compiled.Activated.Single().Targets);

        var (game, alice, bob) = InMainPhase();
        var guard = game.Create(alice, phantom, Zone.Battlefield);
        var ogre = game.Create(bob, TestCards.Creature("Test Phantom Ogre", 4, 4), Zone.Battlefield);

        var island = game.Create(alice, TestCards.BasicLand("Island"), Zone.Battlefield);

        PassTo(game, 2, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            bob,
            new Dictionary<ObjectId, AttackTarget> { [ogre] = AttackTarget.Player(alice) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);
        game.DeclareBlockers(
            alice,
            new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [ogre] = [guard] });

        // In the same turn the damage is dealt in: "this turn" is CR 514.2's duration, so a
        // shield put up on turn 1 is gone before turn 2's combat and the guard dies.
        TestCards.PassUntil(game, () => game.State.Priority.Holder == alice);
        game.ActivateAbility(alice, island, "mana");
        game.ActivateAbility(alice, guard, "a");
        Settle(game);

        TestCards.PassUntil(game, () => game.State.CurrentStep > TurnStep.CombatDamage);

        // A 3/3 blocking a 4/4 and neither of them marked: the shield covers both directions,
        // and the guard is still on the battlefield rather than in a graveyard.
        Assert.Contains(guard, game.State.Battlefield);
        Assert.Equal(0, game.State.GetObject(guard).Permanent!.DamageMarked);
        Assert.Equal(0, game.State.GetObject(ogre).Permanent!.DamageMarked);
    }

    /// <summary>
    /// The target-phrase arm, and the two the reader still refuses.
    /// </summary>
    /// <remarks>
    /// A prevention read wider than printed is what makes a creature invulnerable, so the noun
    /// this reader cannot resolve leaves the line unread rather than being widened. Goblin
    /// Snowman is the case that has to fail closed: "Whenever ~ blocks, prevent all combat damage
    /// that would be dealt to and dealt by <em>it</em>" says the same word Maze of Ith does and
    /// means the opposite thing - the permanent rather than a target - and nothing in the
    /// sentence tells them apart. Energy Arc's "those creatures" is the plural of the same
    /// problem.
    /// </remarks>
    [Fact]
    public void Preventing_damage_both_ways_reads_a_target_phrase_and_refuses_a_loose_pronoun()
    {
        var chariot = CardCompiler.Compile(Card(
            "Test Cloud Chariot",
            "{2}: Prevent all combat damage that would be dealt to and dealt by target creature"
                + " you control this turn.",
            CardType.Artifact));

        Assert.True(chariot.IsComplete, string.Join(" | ", chariot.Unhandled));

        var ability = chariot.Activated.Single();
        Assert.Single(ability.Targets);
        Assert.Equal(
            [false, true],
            ability.Effects.OfType<PreventDescribedDamage>().Select(e => e.TargetIsSource));

        // Both shields point at the one creature the ability asked for, never at a second.
        Assert.All(
            ability.Effects.OfType<PreventDescribedDamage>(),
            e => Assert.Equal(0, e.TargetIndex));

        var snowman = CardCompiler.Compile(Card(
            "Test Snowman Refusal",
            "Whenever ~ blocks, prevent all combat damage that would be dealt to and dealt by it"
                + " this turn.",
            CardType.Creature,
            power: 1,
            toughness: 3));

        Assert.False(snowman.IsComplete);

        var arc = CardCompiler.Compile(Card(
            "Test Energy Arc Refusal",
            "Untap any number of target creatures. Prevent all combat damage that would be dealt"
                + " to and dealt by those creatures this turn.",
            CardType.Instant));

        Assert.False(arc.IsComplete);
    }

    // ---- A full stop inside a quotation, and what undying spells out ---------

    /// <summary>
    /// An offer's branches run past a full stop that is inside a quotation — Digsite Engineer.
    /// </summary>
    /// <remarks>
    /// The third time this codebase has paid for the same rule: <strong>a sentence boundary
    /// inside a quotation is not a sentence boundary.</strong> The clause splitter learned it
    /// about the comma, the exception's quote tally learned it needed its own cursor, and this is
    /// the full stop where a <em>regex</em> does the cutting — <c>[^.]+</c> stopped one character
    /// short of the closing quote, so the anchor could never be reached and the whole offer went
    /// unread on cards whose every part the engine can already play.
    /// <para>
    /// The token's own size is the assertion that earns its place. A reader that took the offer
    /// and dropped the quoted text would mint a 0/0 Construct, which state-based actions bury
    /// before anybody looks at it — so the number proves the words inside the quotation marks
    /// arrived, were compiled, and are being applied.
    /// </para>
    /// </remarks>
    [Fact]
    public void An_offer_reads_past_the_full_stop_inside_its_own_quotation()
    {
        var engineer = Card(
            "Quoted Offer Test",
            "Whenever you cast an artifact spell, you may pay {2}. If you do, create a 0/0"
                + " colorless Construct artifact creature token with \"~ gets +1/+1 for each"
                + " artifact you control.\"",
            CardType.Creature,
            power: 2,
            toughness: 3);

        var compiled = CardCompiler.Compile(engineer);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        game.Create(alice, engineer, Zone.Battlefield);

        // Mana floated before the cast: an offer the player plainly cannot take is skipped
        // without asking, which would hide the very thing being measured.
        foreach (var _ in Enumerable.Range(0, 2))
        {
            var land = game.Create(alice, TestCards.BasicLand("Island"), Zone.Battlefield);
            game.ActivateAbility(alice, land, "mana");
        }

        var relic = TestCards.PutInHand(
            game, alice, Card("Quoted Offer Relic Test", string.Empty, CardType.Artifact));

        game.CastSpell(alice, relic);
        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.OptionalPayment });
        game.Choose(alice, ["yes"]);
        Settle(game);

        var construct = game.State.Battlefield
            .Select(game.State.GetObject)
            .Single(o => o.Card.Name.StartsWith("Construct", StringComparison.Ordinal)
                || o.Card.Subtypes.Contains("Construct"));

        // Two artifacts on the board — the Relic that was cast and the Construct itself — so the
        // quoted static makes the 0/0 a 2/2. Printed as 0/0 it would not have survived to here.
        var now = Characteristics.Of(game.State, Pool, construct);
        Assert.Equal(2, now.Power);
        Assert.Equal(2, now.Toughness);
    }

    /// <summary>
    /// A Clone's exception may grant a whole ability, and the copy can use it — Machine God's
    /// Effigy (CR 707.9b).
    /// </summary>
    /// <remarks>
    /// The clause reader has been able to carry a granted ability since the token copies learned
    /// it, and <see cref="GenerativeEffects.Excepting"/> is the same call on both paths — but the
    /// line's own pattern still refused any exception containing a full stop, which is every
    /// exception that quotes one. The refusal outlived the thing it was protecting.
    /// <para>
    /// The mana in the pool is the assertion that matters. A copy carrying the ability in name
    /// only would answer every characteristic question correctly and do nothing at the one moment
    /// a player notices, which is this family's standing failure mode.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_clone_can_be_excepted_into_having_a_quoted_ability()
    {
        var effigy = Card(
            "Quoted Clone Test",
            "You may have this creature enter as a copy of any creature on the battlefield,"
                + " except it's an artifact and it has \"{T}: Add {U}.\"",
            CardType.Creature,
            0,
            0);

        var compiled = CardCompiler.Compile(effigy);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        game.Create(alice, TestCards.Creature("Quoted Clone Bear Test", 2, 2), Zone.Battlefield);
        Settle(game);

        var arrived = game.Create(alice, effigy, Zone.Battlefield);
        SettleCopying(game, "Quoted Clone Bear Test");

        var now = Characteristics.Of(game.State, Pool, game.State.GetObject(arrived));
        Assert.Equal("Quoted Clone Bear Test", now.Name);
        Assert.Equal(2, now.Power);

        // The exception's other clause, which is what proves the two are read together rather
        // than the quoted half quietly replacing the rest.
        Assert.True(now.CardTypes.HasFlag(CardType.Artifact));

        Assert.Contains(
            Game.ActivatedAbilitiesOf(game.State, Pool, game.State.GetObject(arrived)),
            a => a.Id == "mana");

        // The copy is a creature and the ability costs {T}, so it has to have been under its
        // controller's command since their turn began (CR 302.6).
        PassTo(game, 3, TurnStep.PrecombatMain);
        Settle(game);

        // Asserted before anything settles: a mana ability does not use the stack (CR 605.3a)
        // and the pool empties at the end of the step (CR 500.4).
        game.ActivateAbility(alice, arrived, "mana");
        Assert.Equal(1, game.State.GetPlayer(alice).ManaPool[ManaColor.Blue]);

        Settle(game);
    }

    /// <summary>
    /// "When this creature dies, return it to the battlefield tapped under its owner's control" —
    /// undying's own sentence, written out, and handed to something else for a turn.
    /// </summary>
    /// <remarks>
    /// The commonest thing printed inside a one-turn grant, on nine corpus cards that were each a
    /// single line short: Supernatural Stamina, Feign Death, Undying Malice, Demonic Gifts,
    /// Abnormal Endurance and their kin. The frame — <c>target creature gains "…" until end of
    /// turn</c> — has read for a round; the words inside the quotation had no reader at all, and a
    /// grant only reaches as far as its own text can be parsed back.
    /// <para>
    /// The whole test is what happens after the creature dies. A grant that was present and inert
    /// leaves a graveyard with a Bear in it and every other assertion here still green, so the
    /// board is asserted rather than the parse tree — and it is asserted <em>tapped</em>, because
    /// the word is the only thing separating this sentence from the keyword the engine already
    /// had.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_granted_dies_trigger_brings_the_creature_back_tapped()
    {
        var stamina = Card(
            "Quoted Stamina Test",
            "Until end of turn, target creature gets +2/+0 and gains \"When ~ dies, return it to"
                + " the battlefield tapped under its owner's control.\"",
            CardType.Instant);

        var compiled = CardCompiler.Compile(stamina);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var bear = game.Create(
            alice, TestCards.Creature("Quoted Stamina Bear Test", 2, 2), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, stamina);
        game.CastSpell(alice, card, [Target.ToPermanent(bear)]);
        Settle(game);

        // The pump is layer 7c and the ability is layer 6: one sentence, two effects, and both
        // have to have landed before the creature dies.
        Assert.Equal(4, Characteristics.Of(game.State, Pool, game.State.GetObject(bear)).Power);

        game.Move(bear, Zone.Graveyard, MoveCause.Destroy);
        Settle(game);

        // Back, and it is a new object: the id that died named nothing once it left (CR 400.7).
        var returned = game.State.Battlefield
            .Select(game.State.GetObject)
            .Single(o => o.Card.Name == "Quoted Stamina Bear Test");

        Assert.NotEqual(bear, returned.Id);
        Assert.True(returned.Permanent!.IsTapped);

        // The graveyard is empty of it, which is the half a "return" that merely made a token
        // would leave behind.
        Assert.DoesNotContain(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Quoted Stamina Bear Test");

        // And the grant is gone with the turn: the creature that came back is the printed one,
        // not a 4/2 carrying a second life.
        Assert.Equal(2, Characteristics.Of(game.State, Pool, returned).Power);
    }

    /// <summary>
    /// Undying still comes back untapped and with its counter (CR 702.92a).
    /// </summary>
    /// <remarks>
    /// The keyword and the printed sentence are now one effect, so the keyword is what says the
    /// sentence did not quietly change it: undying prints no "tapped" and brings a counter, and
    /// this is the arm that would break if the new flag or the new counter guard were wrong.
    /// </remarks>
    [Fact]
    public void Undying_returns_the_creature_untapped_with_its_counter()
    {
        var ghoul = Card(
            "Quoted Undying Test",
            "Undying",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var compiled = CardCompiler.Compile(ghoul);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var dying = game.Create(alice, ghoul, Zone.Battlefield);

        game.Move(dying, Zone.Graveyard, MoveCause.Destroy);
        Settle(game);

        var back = game.State.Battlefield
            .Select(game.State.GetObject)
            .Single(o => o.Card.Name == "Quoted Undying Test");

        Assert.False(back.Permanent!.IsTapped);
        Assert.Equal(1, back.Permanent!.Counters.GetValueOrDefault(CounterKinds.PlusOnePlusOne));
    }

    /// <summary>
    /// Three neighbouring sentences this reader must not take, each for its own reason.
    /// </summary>
    /// <remarks>
    /// The effect fetches the card from its owner's <em>graveyard</em>, and every refusal here is
    /// a sentence that means somewhere else or someone else:
    /// <list type="bullet">
    /// <item>"under your control" is a different player — the card would go home to the wrong
    /// side of the table on nine corpus lines.</item>
    /// <item>"at the beginning of the next end step" is a delayed ability, and a reader loose
    /// enough to take it would fire the return immediately.</item>
    /// <item>"exile this creature, then return it to the battlefield" is a blink. The card is in
    /// exile, not in a graveyard, so this effect would find nothing — a card that compiles clean
    /// and does nothing at all, which is worth strictly less than an unread line. It is refused
    /// from outside the sentence because the two halves of an offer are parsed one at a time and
    /// neither can see the other.</item>
    /// </list>
    /// </remarks>
    [Fact]
    public void The_neighbouring_returns_this_reader_must_refuse_stay_unread()
    {
        Assert.False(CardCompiler.Compile(Card(
            "Quoted Return Wrong Player Test",
            "When ~ dies, return it to the battlefield under your control.",
            CardType.Creature,
            2,
            2)).IsComplete);

        Assert.False(CardCompiler.Compile(Card(
            "Quoted Return Later Test",
            "When ~ dies, return it to the battlefield tapped under its owner's control at the"
                + " beginning of the next end step.",
            CardType.Creature,
            2,
            2)).IsComplete);

        Assert.False(CardCompiler.Compile(Card(
            "Quoted Return Blink Test",
            "Exile ~, then return it to the battlefield tapped under its owner's control.",
            CardType.Instant)).IsComplete);

        Assert.False(CardCompiler.Compile(Card(
            "Quoted Return Offered Blink Test",
            "At the beginning of your upkeep, you may exile ~. If you do, return it to the"
                + " battlefield under its owner's control.",
            CardType.Enchantment)).IsComplete);
    }

    // ---- Rooms (CR 709.5) ----------------------------------------------------

    /// <summary>A Room, printed the way the real ones are: two doors, each with a cost.</summary>
    private static CardDefinition Room() => new()
    {
        OracleId = "oracle-test-room",
        Name = "Test Vents // Test Maze",
        ManaCostRaw = "{R}",
        OracleText = "Creatures you control get +1/+0.",
        CardTypes = CardType.Enchantment,
        Subtypes = ["Room"],
        Faces =
        [
            new CardFace
            {
                Name = "Test Vents",
                ManaCostRaw = "{R}",
                TypeLine = "Enchantment \u2014 Room",
                CardTypes = CardType.Enchantment,
                Subtypes = ["Room"],
                OracleText = "Creatures you control get +1/+0.",
            },
            new CardFace
            {
                Name = "Test Maze",
                ManaCostRaw = "{2}{R}",
                TypeLine = "Enchantment \u2014 Room",
                CardTypes = CardType.Enchantment,
                Subtypes = ["Room"],
                OracleText = "Creatures you control get +0/+2.",
            },
        ],
    };

    /// <summary>
    /// Only the door that was paid for is open, and paying the other one opens it
    /// (CR 709.5d, 709.5e).
    /// </summary>
    /// <remarks>
    /// Both halves of a Room are on the same permanent at the same time, so the whole mechanic is
    /// the gate: a locked half "doesn't have the name, mana cost, or rules text" of that half
    /// (CR 709.5). Without it a player pays for one door and gets both, which is the card doing
    /// twice what it says while looking entirely normal.
    /// <para>
    /// The two doors give different bonuses on purpose - one power, one toughness - because a
    /// gate that leaked would be invisible if both halves did the same thing.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_Room_opens_only_the_door_that_was_paid_for()
    {
        var room = Room();

        var compiled = CardCompiler.Compile(room);
        Assert.Equal(2, compiled.Halves.Count);

        var (game, alice, _) = InMainPhase();
        var bear = game.Create(alice, TestCards.Creature("Test Room Bear", 2, 2), Zone.Battlefield);
        var card = TestCards.PutInHand(game, alice, room);

        for (var i = 0; i < 6; i++)
            game.AddMana(alice, ManaColor.Red);

        game.CastSpell(alice, card, [], half: 0);
        Settle(game);

        var permanent = game.State.Battlefield
            .Single(id => game.State.GetObject(id).Card.Name == "Test Vents // Test Maze");

        Assert.Equal([0], game.State.GetObject(permanent).Permanent!.UnlockedHalves);

        var open = Characteristics.Of(game.State, Pool, game.State.GetObject(bear));
        Assert.Equal(3, open.Power);

        // The other door is shut: its bonus is not there.
        Assert.Equal(2, open.Toughness);

        game.UnlockDoor(alice, permanent, 1);
        Settle(game);

        var both = Characteristics.Of(game.State, Pool, game.State.GetObject(bear));
        Assert.Equal(3, both.Power);
        Assert.Equal(4, both.Toughness);
    }

    /// <summary>A door that is already open cannot be paid for again (CR 709.5c).</summary>
    [Fact]
    public void An_open_door_cannot_be_unlocked_twice()
    {
        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, Room());

        for (var i = 0; i < 6; i++)
            game.AddMana(alice, ManaColor.Red);

        game.CastSpell(alice, card, [], half: 0);
        Settle(game);

        var permanent = game.State.Battlefield
            .Single(id => game.State.GetObject(id).Card.Name == "Test Vents // Test Maze");

        Assert.Throws<InvalidOperationException>(() => game.UnlockDoor(alice, permanent, 0));
    }
    /// <summary>
    /// "When you unlock this door" fires as its own door opens, and only then (CR 709.5f).
    /// </summary>
    /// <remarks>
    /// Third time this shape has appeared: an ability printed behind the switch it fires on. A
    /// Saga's chapter, a Class's level, and now a Room's door - each of them is checked against
    /// a state that has not changed yet, so each needs its gate lifted for its own event and no
    /// other.
    /// <para>
    /// The other door is what carries the test. A trigger that fired on any unlock would look
    /// right until the second door opened and the first one's trigger went off again.
    /// </para>
    /// </remarks>
    [Fact]
    public void An_unlock_trigger_fires_for_its_own_door_only()
    {
        var room = new CardDefinition
        {
            OracleId = "oracle-test-door-room",
            Name = "Test Hall // Test Cellar",
            ManaCostRaw = "{R}",
            OracleText = "When you unlock this door, you gain 2 life.",
            CardTypes = CardType.Enchantment,
            Subtypes = ["Room"],
            Faces =
            [
                new CardFace
                {
                    Name = "Test Hall",
                    ManaCostRaw = "{R}",
                    TypeLine = "Enchantment \u2014 Room",
                    CardTypes = CardType.Enchantment,
                    Subtypes = ["Room"],
                    OracleText = "When you unlock this door, you gain 2 life.",
                },
                new CardFace
                {
                    Name = "Test Cellar",
                    ManaCostRaw = "{2}{R}",
                    TypeLine = "Enchantment \u2014 Room",
                    CardTypes = CardType.Enchantment,
                    Subtypes = ["Room"],
                    OracleText = "Creatures you control get +1/+0.",
                },
            ],
        };

        var compiled = CardCompiler.Compile(room);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var start = game.State.GetPlayer(alice).Life;
        var card = TestCards.PutInHand(game, alice, room);

        for (var i = 0; i < 6; i++)
            game.AddMana(alice, ManaColor.Red);

        // Open the *other* door first. The trigger belongs to the hall, not the cellar.
        game.CastSpell(alice, card, [], half: 1);
        Settle(game);

        Assert.Equal(start, game.State.GetPlayer(alice).Life);

        var permanent = game.State.Battlefield
            .Single(id => game.State.GetObject(id).Card.Name == "Test Hall // Test Cellar");

        game.UnlockDoor(alice, permanent, 0);
        Settle(game);

        Assert.Equal(start + 2, game.State.GetPlayer(alice).Life);
    }

    // ---- Shuffling back in, stun counters, and "each of them" -----------------

    /// <summary>
    /// Timetwister: "Each player shuffles their hand and graveyard into their library, then
    /// draws seven cards" (CR 701.24a).
    /// </summary>
    /// <remarks>
    /// The shuffle already carried a graveyard; the hand it names in the same breath had nowhere
    /// to go, and the settle that performs the shuffle only moved cards that were in a graveyard.
    /// Both halves are asserted here, because a shuffle that took the graveyard and left the hand
    /// alone would still have produced a bigger library and a fresh seven cards.
    /// </remarks>
    [Fact]
    public void Shuffling_a_hand_and_graveyard_back_in_empties_both()
    {
        var twister = Card(
            "Acc Timetwister Test",
            "Each player shuffles their hand and graveyard into their library, then draws "
                + "seven cards.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(twister);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, TestCards.Creature("Acc Buried Bear Test", 2, 2), Zone.Graveyard);
        game.Create(bob, TestCards.BasicLand("Acc Buried Forest Test"), Zone.Graveyard);

        var card = TestCards.PutInHand(game, alice, twister);
        game.CastSpell(alice, card, []);
        Settle(game);

        // Seven each, from a library that everything they held has gone back into.
        Assert.Equal(7, game.State.GetPlayer(alice).Hand.Count);
        Assert.Equal(7, game.State.GetPlayer(bob).Hand.Count);

        // The graveyards went in too - and the spell itself is the one card that is allowed to
        // be in one afterwards, because it reached the graveyard after the shuffle named its
        // cards (CR 608.2m).
        Assert.DoesNotContain(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Acc Buried Bear Test");

        Assert.Empty(game.State.GetPlayer(bob).Graveyard);
    }

    /// <summary>
    /// The subject of "each player does A, then does B" governs both halves (CR 608.2c).
    /// </summary>
    /// <remarks>
    /// Wheel of Fortune, and five cards printed like it. The clause splitter cuts at ", then" and
    /// offers the halves to the readers one at a time, which left "draws seven cards" standing
    /// with nobody in front of it - so it compiled as the controller's draw and the card dealt
    /// every player a fresh hand while drawing for one of them.
    /// <para>
    /// Bob is the assertion. Alice drawing seven proves nothing at all: she draws seven under
    /// both readings.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_group_subject_carries_over_the_clause_after_then()
    {
        var wheel = Card(
            "Acc Wheel Test",
            "Each player discards their hand, then draws seven cards.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(wheel);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, wheel);

        game.CastSpell(alice, card, []);
        Settle(game);

        Assert.Equal(7, game.State.GetPlayer(alice).Hand.Count);
        Assert.Equal(7, game.State.GetPlayer(bob).Hand.Count);
    }

    /// <summary>
    /// "Shuffle up to two target cards from your graveyard into your library" (CR 404.2).
    /// </summary>
    /// <remarks>
    /// A graveyard is a public zone, so the cards are ordinary targets and every slot is optional
    /// - which is what "up to" says, and what lets this be cast with one card in the graveyard.
    /// The card left behind is the assertion that matters: an effect that shuffled the whole
    /// graveyard back would pass every other check here.
    /// </remarks>
    [Fact]
    public void Shuffling_targeted_cards_back_leaves_the_rest_in_the_graveyard()
    {
        var journey = Card(
            "Acc Memory Journey Test",
            "Shuffle up to two target cards from your graveyard into your library.",
            CardType.Instant);

        var compiled = CardCompiler.Compile(journey);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var kept = game.Create(alice, TestCards.Creature("Acc Kept Bear Test", 2, 2), Zone.Graveyard);
        var taken = game.Create(alice, TestCards.Creature("Acc Taken Bear Test", 2, 2), Zone.Graveyard);
        var library = game.State.GetPlayer(alice).Library.Count;

        var card = TestCards.PutInHand(game, alice, journey);
        game.CastSpell(alice, card, [Target.ToCard(taken)]);
        Settle(game);

        Assert.Equal(library + 1, game.State.GetPlayer(alice).Library.Count);

        Assert.Contains(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Acc Kept Bear Test");

        Assert.DoesNotContain(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Acc Taken Bear Test");

        Assert.NotEqual(kept, taken);
    }

    /// <summary>
    /// "Shuffle all creature cards from your graveyard into your library" (CR 701.24a).
    /// </summary>
    /// <remarks>
    /// The filter is the one a tutor names its card with, asked of the graveyard rather than of
    /// the library. A land in the same graveyard is what proves it is a filter at all.
    /// </remarks>
    [Fact]
    public void Shuffling_all_cards_of_a_kind_back_leaves_the_others()
    {
        var spiral = Card(
            "Acc Psychic Spiral Test",
            "Shuffle all creature cards from your graveyard into your library.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(spiral);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        game.Create(alice, TestCards.Creature("Acc Spiral Bear Test", 2, 2), Zone.Graveyard);
        game.Create(alice, TestCards.BasicLand("Acc Spiral Forest Test"), Zone.Graveyard);

        var card = TestCards.PutInHand(game, alice, spiral);
        game.CastSpell(alice, card, []);
        Settle(game);

        Assert.DoesNotContain(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Acc Spiral Bear Test");

        Assert.Contains(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Acc Spiral Forest Test");
    }

    /// <summary>
    /// "At the beginning of the end step, ~'s owner shuffles it into their library."
    /// </summary>
    /// <remarks>
    /// The same instruction the beacons print, said of a permanent rather than of a resolving
    /// sorcery - so the card being shuffled is on the battlefield when the request is settled.
    /// The settle used to move only cards it found in a graveyard, which would have left this
    /// creature exactly where it was on a card that compiled and looked finished.
    /// </remarks>
    [Fact]
    public void A_permanent_that_shuffles_itself_away_leaves_the_battlefield()
    {
        var hellion = new CardDefinition
        {
            OracleId = "oracle-acc-blitz-hellion-test",
            Name = "Acc Blitz Hellion Test",
            OracleText = "At the beginning of the end step, ~'s owner shuffles it into their "
                + "library.",
            CardTypes = CardType.Creature,
            Power = 7,
            Toughness = 7,
        };

        var compiled = CardCompiler.Compile(hellion);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var library = game.State.GetPlayer(alice).Library.Count;
        game.Create(alice, hellion, Zone.Battlefield);

        TestCards.PassToStep(game, TurnStep.End);
        Settle(game);

        Assert.DoesNotContain(
            game.State.Battlefield,
            id => game.State.GetObject(id).Card.Name == "Acc Blitz Hellion Test");

        Assert.Equal(library + 1, game.State.GetPlayer(alice).Library.Count);
        Assert.Empty(game.State.GetPlayer(alice).Graveyard);
    }

    /// <summary>
    /// A stun counter is spent instead of the untap step's untap (CR 122.1c).
    /// </summary>
    /// <remarks>
    /// The counter compiled from the day named counters did - "put a stun counter on it" is a
    /// counter like any other - and nothing anywhere read it, so eighty-seven corpus cards put
    /// their counters on and then watched the creature untap on schedule. This is the rule those
    /// cards are for.
    /// <para>
    /// Two untap steps, because one proves only half of it: the counter has to stop the first
    /// untap <em>and</em> be spent doing so, or a stunned creature would never untap again.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_stun_counter_is_spent_instead_of_untapping()
    {
        var chill = Card(
            "Acc Rime Chill Test",
            "Tap target creature. Put a stun counter on it.",
            CardType.Instant);

        var compiled = CardCompiler.Compile(chill);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var bear = game.Create(alice, TestCards.Creature("Acc Stunned Bear Test", 2, 2), Zone.Battlefield);
        var card = TestCards.PutInHand(game, alice, chill);

        game.CastSpell(alice, card, [Target.ToPermanent(bear)]);
        Settle(game);

        Assert.True(game.State.GetObject(bear).Permanent?.IsTapped);
        Assert.Equal(1, game.State.GetObject(bear).Permanent?.Counters[CounterKinds.Stun]);

        // Alice's next turn: the untap step finds the counter and spends it instead.
        TestCards.PassToTurn(game, 3);
        TestCards.PassToStep(game, TurnStep.PrecombatMain);

        Assert.True(game.State.GetObject(bear).Permanent?.IsTapped);
        Assert.DoesNotContain(CounterKinds.Stun, game.State.GetObject(bear).Permanent!.Counters);

        // And the turn after that, with the counter gone, it untaps as it always did.
        TestCards.PassToTurn(game, 5);
        TestCards.PassToStep(game, TurnStep.PrecombatMain);

        Assert.False(game.State.GetObject(bear).Permanent?.IsTapped);
    }

    /// <summary>
    /// The same replacement applies to an untap an effect asks for (CR 122.1c).
    /// </summary>
    /// <remarks>
    /// "Would become untapped" is every untap, not the untap step's. A rule implemented only
    /// where it is commonest is the kind that looks right for a year.
    /// </remarks>
    [Fact]
    public void A_stun_counter_is_spent_instead_of_an_untap_effect()
    {
        var chill = Card(
            "Acc Cooldown Test",
            "Tap target creature. Put a stun counter on it.",
            CardType.Instant);

        var wake = Card("Acc Wake Test", "Untap target creature.", CardType.Instant);

        var (game, alice, _) = InMainPhase();
        var bear = game.Create(alice, TestCards.Creature("Acc Woken Bear Test", 2, 2), Zone.Battlefield);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, chill), [Target.ToPermanent(bear)]);
        Settle(game);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, wake), [Target.ToPermanent(bear)]);
        Settle(game);

        Assert.True(game.State.GetObject(bear).Permanent?.IsTapped);
        Assert.DoesNotContain(CounterKinds.Stun, game.State.GetObject(bear).Permanent!.Counters);
    }

    /// <summary>
    /// "Tap up to two target creatures. Put a stun counter on each of them" (CR 608.2c).
    /// </summary>
    /// <remarks>
    /// The second sentence chooses nothing. "Them" is every target the sentence before it chose,
    /// which is the one thing a target spec cannot say, because a spec names one thing - so the
    /// sentence is read once in the singular and copied once per target.
    /// <para>
    /// Both creatures are asserted. Copying the effect onto the last target alone is the reading
    /// every other pronoun in this file takes, and it would look right on any card that chose one.
    /// </para>
    /// </remarks>
    [Fact]
    public void Each_of_them_reaches_every_target_the_sentence_before_chose()
    {
        var chill = Card(
            "Acc Succumb Test",
            "Tap up to two target creatures. Put a stun counter on each of them.",
            CardType.Instant);

        var compiled = CardCompiler.Compile(chill);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var first = game.Create(bob, TestCards.Creature("Acc First Bear Test", 2, 2), Zone.Battlefield);
        var second = game.Create(bob, TestCards.Creature("Acc Second Bear Test", 2, 2), Zone.Battlefield);
        var card = TestCards.PutInHand(game, alice, chill);

        game.CastSpell(alice, card, [Target.ToPermanent(first), Target.ToPermanent(second)]);
        Settle(game);

        foreach (var id in new[] { first, second })
        {
            Assert.True(game.State.GetObject(id).Permanent?.IsTapped);
            Assert.Equal(1, game.State.GetObject(id).Permanent?.Counters[CounterKinds.Stun]);
        }
    }

    /// <summary>
    /// A second sentence that <em>narrows</em> the group is not "each of them" (CR 601.2c).
    /// </summary>
    /// <remarks>
    /// "Tap X target creatures. Put a stun counter on each of those creatures you don't control."
    /// The counters go on some of the targets and the pronoun cannot say which, so the card is
    /// left unread rather than compiled into one that stuns every creature it tapped - which is
    /// a strictly better card than the one printed.
    /// <para>
    /// The refusal is structural rather than a special case: swapping the pronoun for "it" leaves
    /// the qualifier standing, and no reader takes "on it you don't control".
    /// </para>
    /// </remarks>
    [Fact]
    public void Each_of_those_with_a_qualifier_after_it_is_left_unread()
    {
        var maze = Card(
            "Acc Lost In The Maze Test",
            "Tap up to two target creatures. Put a stun counter on each of those creatures you "
                + "don't control.",
            CardType.Instant);

        Assert.False(CardCompiler.Compile(maze).IsComplete);
    }

    /// <summary>
    /// "You may tap or untap target artifact, creature, or land" (CR 115.1).
    /// </summary>
    /// <remarks>
    /// The choice reader had a noun grammar of its own that took one unbroken word after
    /// "target", so the commonest phrase in the family - three types in a list - went unread on
    /// cards whose every other line compiled. It asks <see cref="Specs"/> the same question every
    /// other verb asks now.
    /// </remarks>
    [Fact]
    public void Tap_or_untap_reads_the_shared_target_grammar()
    {
        var twiddle = Card(
            "Acc Twiddle Test",
            "You may tap or untap target artifact, creature, or land.",
            CardType.Instant);

        var compiled = CardCompiler.Compile(twiddle);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var land = game.Create(alice, TestCards.BasicLand("Acc Twiddled Forest Test"), Zone.Battlefield);
        var card = TestCards.PutInHand(game, alice, twiddle);

        Assert.False(game.State.GetObject(land).Permanent?.IsTapped);

        // The harness takes the first option of every question, which is the offer and then the
        // tap - so a land the spell reached is a tapped land, and a land it could not target
        // would still be untapped.
        game.CastSpell(alice, card, [Target.ToPermanent(land)]);
        Settle(game);

        Assert.True(game.State.GetObject(land).Permanent?.IsTapped);
    }

    /// <summary>
    /// "Another target permanent" is the same phrase with one word (CR 115.1).
    /// </summary>
    [Fact]
    public void Tap_or_untap_reads_another_target()
    {
        var strings = Card(
            "Acc Fatestitcher Test",
            "You may tap or untap another target permanent.",
            CardType.Instant);

        var compiled = CardCompiler.Compile(strings);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.Single(compiled.Spell!.Targets);
        Assert.Contains("another", compiled.Spell!.Targets[0].Description, StringComparison.Ordinal);
    }

    // ---- Prevention described rather than aimed (CR 615.1) --------------------

    /// <summary>
    /// "Prevent all damage that would be dealt this turn by creatures" (CR 615.1, 609.7).
    /// </summary>
    /// <remarks>
    /// The whole described-prevention engine — <see cref="PreventDescribedDamage"/>,
    /// <see cref="PreventionEffect"/>, the two arms in the replacement pass — was built, tested
    /// and unreachable: nothing in the compiler emitted one, so every card of this shape was
    /// unread while the machinery that answers it sat finished. A hundred and eighteen corpus
    /// lines start "Prevent all".
    /// <para>
    /// The burn spell is the control. A shield that forgot the "by creatures" half would stop
    /// everything, which is a strictly better card than Ethereal Haze — and the countdown shield
    /// the compiler already had could not have asked the question at all, because a shield
    /// sitting on the thing being hit cannot see what is hitting it.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_prevention_that_names_the_dealer_stops_creatures_and_not_burn()
    {
        var haze = Card(
            "Ethereal Haze Test",
            "Prevent all damage that would be dealt this turn by creatures.");

        var bolt = Card("Haze Bolt Test", "~ deals 3 damage to any target.");

        Assert.True(
            CardCompiler.Compile(haze).IsComplete,
            string.Join(" | ", CardCompiler.Compile(haze).Unhandled));

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(
            alice, TestCards.Creature("Hazed Attacker Test", 3, 3), Zone.Battlefield);

        // Cast on the turn it is going to matter: the shield says "this turn" and is gone by the
        // next one, which the expiry test elsewhere in this file proves on its own.
        PassToMainPhaseOfTurn(game, 3);
        game.CastSpell(alice, TestCards.PutInHand(game, alice, haze), []);
        Settle(game);

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Settle(game);

        // The creature's combat damage never landed.
        Assert.Equal(20, game.State.GetPlayer(bob).Life);

        // The same shield, on the same turn, asked about a spell. It is not a creature, so
        // nothing stops it.
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.PostcombatMain);
        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, bolt), [Target.ToPlayer(bob)]);

        Settle(game);
        Assert.Equal(17, game.State.GetPlayer(bob).Life);
    }

    /// <summary>
    /// "Prevent all damage that would be dealt to creatures you control this turn."
    /// </summary>
    /// <remarks>
    /// The other half of the grammar: a described set of victims rather than a described dealer.
    /// Bob's creature is what catches the wrong reading — a shield that lost the possessive
    /// would fog the whole board, and the card would compile just as cleanly.
    /// </remarks>
    [Fact]
    public void A_prevention_for_your_own_creatures_leaves_an_opponents_exposed()
    {
        var light = Card(
            "Divine Light Test",
            "Prevent all damage that would be dealt to creatures you control this turn.");

        var bolt = Card("Light Bolt Test", "~ deals 3 damage to any target.");

        Assert.True(
            CardCompiler.Compile(light).IsComplete,
            string.Join(" | ", CardCompiler.Compile(light).Unhandled));

        var (game, alice, bob) = InMainPhase();
        var hers = game.Create(alice, TestCards.Creature("Lit Bear Test", 2, 2), Zone.Battlefield);
        var theirs = game.Create(bob, TestCards.Creature("Dark Bear Test", 2, 2), Zone.Battlefield);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, light), []);
        Settle(game);

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, bolt), [Target.ToPermanent(hers)]);
        Settle(game);

        Assert.Contains(hers, game.State.Battlefield);
        Assert.Equal(0, game.State.GetObject(hers).Permanent?.DamageMarked);

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, bolt), [Target.ToPermanent(theirs)]);
        Settle(game);

        Assert.DoesNotContain(theirs, game.State.Battlefield);
    }

    /// <summary>
    /// "Prevent all damage that would be dealt to creatures this turn" is every creature.
    /// </summary>
    /// <remarks>
    /// The same sentence without the possessive, and the control for the test above it. A reader
    /// that defaulted the missing "you control" to "you" compiles Forfend perfectly and plays it
    /// as a narrower card — which is the quiet direction of the fail-closed rule, and just as
    /// wrong as the loud one.
    /// </remarks>
    [Fact]
    public void A_prevention_naming_no_controller_covers_every_creature()
    {
        var forfend = Card(
            "Forfend Test",
            "Prevent all damage that would be dealt to creatures this turn.");

        var bolt = Card("Forfend Bolt Test", "~ deals 3 damage to any target.");

        Assert.True(
            CardCompiler.Compile(forfend).IsComplete,
            string.Join(" | ", CardCompiler.Compile(forfend).Unhandled));

        var (game, alice, bob) = InMainPhase();
        var theirs = game.Create(bob, TestCards.Creature("Forfend Bear Test", 2, 2), Zone.Battlefield);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, forfend), []);
        Settle(game);

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, bolt), [Target.ToPermanent(theirs)]);
        Settle(game);

        Assert.Contains(theirs, game.State.Battlefield);
        Assert.Equal(0, game.State.GetObject(theirs).Permanent?.DamageMarked);

        // A player is not a creature, so the same shield does nothing for Bob's life total.
        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, bolt), [Target.ToPlayer(bob)]);
        Settle(game);

        Assert.Equal(17, game.State.GetPlayer(bob).Life);
    }

    /// <summary>
    /// Fog Bank: "Prevent all combat damage that would be dealt to and dealt by ~."
    /// </summary>
    /// <remarks>
    /// The static half of prevention, and the reason it compiles to a replacement effect rather
    /// than to the described prevention above: a described prevention is state the engine keeps
    /// until the turn ends, and this one has no duration at all, so it would still be shielding
    /// after the permanent holding it had been destroyed. A replacement functions from the
    /// battlefield and therefore stops when its permanent does (CR 611.2c).
    /// <para>
    /// The burn spell is again the control, for the word "combat": a shield that dropped it
    /// would make this creature immortal.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_static_shield_stops_combat_damage_both_ways_and_nothing_else()
    {
        var bank = Card(
            "Fog Bank Test",
            "Defender\nPrevent all combat damage that would be dealt to and dealt by ~.",
            CardType.Creature,
            0,
            2,
            KeywordAbility.Defender);

        var bolt = Card("Bank Bolt Test", "~ deals 3 damage to any target.");

        Assert.True(
            CardCompiler.Compile(bank).IsComplete,
            string.Join(" | ", CardCompiler.Compile(bank).Unhandled));

        var (game, alice, bob) = InMainPhase();
        var wall = game.Create(alice, bank, Zone.Battlefield);
        var attacker = game.Create(
            bob, TestCards.Creature("Bank Attacker Test", 3, 3), Zone.Battlefield);

        PassTo(game, 2, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            bob,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(alice) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);
        game.DeclareBlockers(
            alice,
            new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [attacker] = [wall] });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Settle(game);

        // Neither direction: the 3/3 marked nothing on the wall, and the wall is still 0 power
        // so the attacker was never going to take any either.
        Assert.Contains(wall, game.State.Battlefield);
        Assert.Equal(0, game.State.GetObject(wall).Permanent?.DamageMarked);
        Assert.Equal(20, game.State.GetPlayer(alice).Life);

        // Noncombat damage is not what the card names, and it kills a 0/2 outright.
        PassToMainPhaseOfTurn(game, 3);
        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, bolt), [Target.ToPermanent(wall)]);
        Settle(game);

        Assert.DoesNotContain(wall, game.State.Battlefield);
    }

    /// <summary>
    /// Defang: an Aura whose shield goes away with it.
    /// </summary>
    /// <remarks>
    /// The assertion that pays for the whole design decision. The same words compiled as a
    /// described prevention would have left a shield standing on a creature whose Aura was in
    /// the graveyard — the card would look implemented, play correctly all game, and be wrong
    /// exactly once.
    /// </remarks>
    [Fact]
    public void An_auras_shield_is_gone_when_the_aura_is()
    {
        var defang = Card(
            "Defang Test",
            "Enchant creature\nPrevent all combat damage that would be dealt by enchanted creature.",
            CardType.Enchantment,
            subtypes: "Aura");

        Assert.True(
            CardCompiler.Compile(defang).IsComplete,
            string.Join(" | ", CardCompiler.Compile(defang).Unhandled));

        var (game, alice, bob) = InMainPhase();
        var brute = game.Create(bob, TestCards.Creature("Defanged Brute Test", 3, 3), Zone.Battlefield);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, defang), [Target.ToPermanent(brute)]);
        Settle(game);

        var aura = game.State.Battlefield
            .Single(id => game.State.GetObject(id).Card.Name == "Defang Test");

        PassTo(game, 2, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            bob,
            new Dictionary<ObjectId, AttackTarget> { [brute] = AttackTarget.Player(alice) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Settle(game);

        Assert.Equal(20, game.State.GetPlayer(alice).Life);

        // Take the Aura away and the creature is a 3/3 again.
        game.Move(aura, Zone.Graveyard, MoveCause.Destroy);
        Settle(game);

        PassTo(game, 4, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            bob,
            new Dictionary<ObjectId, AttackTarget> { [brute] = AttackTarget.Player(alice) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Settle(game);

        Assert.Equal(17, game.State.GetPlayer(alice).Life);
    }

    // ---- Rules that are settled before a game starts (CR 100.2a, 903.3a) -----

    /// <summary>
    /// "A deck can have any number of cards named ~" is read, and builds nothing.
    /// </summary>
    /// <remarks>
    /// Partner's siblings. These say nothing about a game in progress, so the honest reading is
    /// to record them and produce no ability at all — and the assertion that matters is the
    /// second one: a no-op reader that quietly built something would be worse than leaving the
    /// line unread, because the card would report itself understood either way.
    /// <para>
    /// <strong>The Leyline line is deliberately absent from this list, and now for a second
    /// reason.</strong> "If ~ is in your opening hand, you may begin the game with it on the
    /// battlefield" is CR 103.6 and a real game rule — twenty corpus cards genuinely start in
    /// play — so recording it here as text nothing acts on would file them as understood while
    /// removing the only thing they do. It was left unread for exactly that reason until the
    /// engine had an opening-hand step to hang it on; it now compiles to
    /// <c>MayBeginOnBattlefield</c>, which is an answer the game asks for rather than a string
    /// filed away, and the assertion below is what keeps it out of the no-op list.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_deck_construction_rule_is_read_and_produces_no_ability()
    {
        var rat = Card(
            "Rat Colony Test",
            "A deck can have any number of cards named ~.",
            CardType.Creature,
            1,
            1,
            subtypes: "Rat");

        var compiled = CardCompiler.Compile(rat);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        // The name, not "~". Deck construction is the reader that wants these lines, and the
        // question it asks is "how many cards with this name" (CR 100.2a) - so the recorded rule
        // has to carry the name. The self-name substitution used to blank it and this assertion
        // was written around the blank.
        Assert.Contains(
            "A deck can have any number of cards named Rat Colony Test", compiled.DeckRules);

        var planeswalker = CardCompiler.Compile(Card(
            "Commodore Guff Test",
            "~ can be your commander.",
            CardType.Planeswalker,
            subtypes: "Guff"));

        Assert.True(planeswalker.IsComplete, string.Join(" | ", planeswalker.Unhandled));
        Assert.Contains("~ can be your commander", planeswalker.DeckRules);

        // Nothing was built from it: no spell, no ability, no replacement.
        Assert.False(planeswalker.HasAbilities);
        Assert.Null(planeswalker.Spell);

        var leyline = CardCompiler.Compile(Card(
            "Leyline Test",
            "If ~ is in your opening hand, you may begin the game with it on the battlefield.",
            CardType.Enchantment));

        // Read, and read as a permission the game acts on rather than as deck-construction
        // text: it is a pre-game action (CR 103.6a), so it belongs to the step that offers it.
        Assert.True(leyline.IsComplete, string.Join(" | ", leyline.Unhandled));
        Assert.Empty(leyline.DeckRules);
        Assert.True(leyline.MayBeginOnBattlefield);
        Assert.True(leyline.HasAbilities);
    }

    // ---- Battles (CR 310) ----------------------------------------------------

    /// <summary>
    /// A Siege from the real printed wording of Invasion of Moag, faces and all.
    /// </summary>
    /// <remarks>
    /// One of the ten battles the round-end gate found compiling "complete" against an engine
    /// with no CR 310 — the shape this section exists to make true. The front's reminder text is
    /// the printed reminder verbatim, because the intrinsic abilities it describes are exactly
    /// the ones nothing on the card carries: entering with defense counters (CR 310.4b), the
    /// protector (CR 310.9a), and the defeat that exiles and recasts (CR 310.12b).
    /// </remarks>
    private static CardDefinition MoagSiege() => new()
    {
        OracleId = "oracle-r10-moag-siege",
        Name = "Invasion of Moag Test",
        CardTypes = CardType.Battle,
        Subtypes = ["Siege"],
        Defense = 5,
        OracleText = "When this Siege enters, put a +1/+1 counter on each creature you control.",
        Faces =
        [
            new CardFace
            {
                Name = "Invasion of Moag Test",
                TypeLine = "Battle — Siege",
                CardTypes = CardType.Battle,
                Subtypes = ["Siege"],
                Defense = 5,
                ManaCostRaw = "{2}{G}{W}",
                OracleText = "(As a Siege enters, choose an opponent to protect it. You and "
                    + "others can attack it. When it's defeated, exile it, then cast it "
                    + "transformed.)\nWhen this Siege enters, put a +1/+1 counter on each "
                    + "creature you control.",
            },
            new CardFace
            {
                Name = "Bloomwielder Dryads Test",
                TypeLine = "Creature — Dryad",
                CardTypes = CardType.Creature,
                Subtypes = ["Dryad"],
                Power = 3,
                Toughness = 3,
                OracleText = "Ward {2} (Whenever this creature becomes the target of a spell or "
                    + "ability an opponent controls, counter it unless that player pays {2}.)\n"
                    + "At the beginning of your end step, put a +1/+1 counter on target "
                    + "creature you control.",
            },
        ],
    };

    private static int DefenseOf(Game game, ObjectId id) =>
        game.State.GetObject(id).Permanent!.Counters.GetValueOrDefault(CounterKinds.Defense);

    private static Guid? ProtectorOf(Game game, ObjectId id) =>
        game.State.GetObject(id).Permanent!.ProtectorId;

    [Fact]
    public void A_siege_enters_with_defense_counters_and_a_forced_duel_protector()
    {
        var compiled = CardCompiler.Compile(MoagSiege());
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var bear = game.Create(alice, TestCards.Creature("Moag Bear Test", 2, 2), Zone.Battlefield);
        var card = TestCards.PutInHand(game, alice, MoagSiege());

        game.CastSpell(alice, card);
        Settle(game);

        var siege = Assert.Single(
            game.State.Battlefield,
            id => game.State.GetObject(id).Card.Name == "Invasion of Moag Test");

        // CR 310.4b: it entered with defense counters equal to its printed defense, and its
        // printed enters trigger played alongside the intrinsic rules.
        Assert.Equal(5, DefenseOf(game, siege));
        Assert.Equal(
            1,
            game.State.GetObject(bear).Permanent!.Counters
                .GetValueOrDefault(CounterKinds.PlusOnePlusOne));

        // CR 310.12a at two players: the only opponent is the only legal protector, so the
        // choice is forced — made, never asked.
        Assert.Equal(bob, ProtectorOf(game, siege));
        Assert.DoesNotContain(
            game.Log.OfType<ChoiceRequested>(),
            asked => asked.Choice.Kind == ChoiceKind.ChooseProtector);

        // The board is told all three facts, in the opponent's own view: what it is, who
        // protects it, and what its defense is — a battle shown without its counters is a board
        // lying about the number the fight is about.
        var seen = Views.PlayerViewProjector.Project(game.State, bob, Pool)
            .Battlefield.Single(o => o.Name == "Invasion of Moag Test");
        Assert.True(seen.IsBattle);
        Assert.Equal(bob, seen.ProtectorId);
        Assert.Equal(5, seen.Counters!.GetValueOrDefault(CounterKinds.Defense));
    }

    [Fact]
    public void A_bigger_table_asks_the_sieges_controller_to_choose_its_protector()
    {
        // CR 310.9a, 310.12a: any opponent may protect it, so at four seats the designation is a
        // real question — asked of the controller, answered like any other choice.
        var (game, seats) = FourPlayers();
        var (alice, carol) = (seats[0], seats[2]);

        var siege = game.Create(alice, MoagSiege(), Zone.Battlefield);
        game.PassPriority(game.State.Priority.Holder!.Value);

        var choice = Assert.IsType<PendingChoice>(game.State.Choice);
        Assert.Equal(ChoiceKind.ChooseProtector, choice.Kind);
        Assert.Equal(alice, choice.PlayerId);
        Assert.Equal(3, choice.Options.Count);

        game.Choose(alice, [carol.ToString("N")]);
        Settle(game);

        Assert.Equal(carol, ProtectorOf(game, siege));
    }

    [Fact]
    public void A_sieges_own_controller_attacks_it_and_combat_damage_removes_defense()
    {
        // CR 310.9b: a battle is attacked by any player for whom its protector is a defending
        // player — "notably, a Siege battle can be attacked by its own controller", which is the
        // whole play pattern of the type. CR 120.3h, 310.6: the damage removes defense counters;
        // nothing reaches the protector's life.
        var (game, alice, bob) = InMainPhase();
        var siege = game.Create(alice, MoagSiege(), Zone.Battlefield);
        var runner = game.Create(
            alice,
            Card("Siege Runner Test", string.Empty, CardType.Creature, 2, 2, KeywordAbility.Haste),
            Zone.Battlefield);

        TestCards.PassToStep(game, TurnStep.DeclareAttackers);
        game.DeclareAttackers(alice, new Dictionary<ObjectId, AttackTarget>
        {
            [runner] = AttackTarget.At(bob, siege),
        });
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);

        // The Siege's own enters trigger made the runner a 3/3 — its counter fell on "each
        // creature you control" — so three counters came off, not two. The battle plays its own
        // besieger up, which is the printed card working, not a test convenience.
        Assert.Equal(2, DefenseOf(game, siege));
        Assert.Equal(20, game.State.GetPlayer(bob).Life);
        Assert.Contains(siege, game.State.Battlefield);
    }

    [Fact]
    public void The_protector_blocks_for_a_battle_it_does_not_control()
    {
        // CR 310.9c: the protector may block creatures attacking the battle with creatures they
        // control — the defending player for the attack is the protector (CR 310.9d), and a
        // blocked attacker deals its damage to the blocker rather than the battle.
        var (game, alice, bob) = InMainPhase();
        var siege = game.Create(alice, MoagSiege(), Zone.Battlefield);
        var runner = game.Create(
            alice,
            Card("Siege Runner Test", string.Empty, CardType.Creature, 2, 2, KeywordAbility.Haste),
            Zone.Battlefield);
        var warden = game.Create(
            bob, Card("Moag Warden Test", string.Empty, CardType.Creature, 1, 4), Zone.Battlefield);

        TestCards.PassToStep(game, TurnStep.DeclareAttackers);
        game.DeclareAttackers(alice, new Dictionary<ObjectId, AttackTarget>
        {
            [runner] = AttackTarget.At(bob, siege),
        });
        TestCards.PassToStep(game, TurnStep.DeclareBlockers);
        game.DeclareBlockers(bob, new Dictionary<ObjectId, IReadOnlyList<ObjectId>>
        {
            [runner] = [warden],
        });
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);

        // The block stood between the attacker and the battle: full defense, traded damage —
        // three from the runner, which the Siege's own enters trigger had made a 3/3.
        Assert.Equal(5, DefenseOf(game, siege));
        Assert.Equal(3, game.State.GetObject(warden).Permanent!.DamageMarked);
        Assert.Equal(1, game.State.GetObject(runner).Permanent!.DamageMarked);
    }

    [Fact]
    public void A_battle_is_attacked_only_through_its_protector()
    {
        // CR 310.9b's other half: a player for whom the protector is not a defending player
        // cannot send an attack at the battle — naming anyone else is refused whole.
        var (game, seats) = FourPlayers();
        var (alice, bob, carol) = (seats[0], seats[1], seats[2]);

        var siege = game.Create(alice, MoagSiege(), Zone.Battlefield);
        game.PassPriority(game.State.Priority.Holder!.Value);
        game.Choose(alice, [bob.ToString("N")]);

        var runner = game.Create(
            alice,
            Card("Siege Runner Test", string.Empty, CardType.Creature, 2, 2, KeywordAbility.Haste),
            Zone.Battlefield);
        TestCards.PassToStep(game, TurnStep.DeclareAttackers);

        var refused = Assert.Throws<InvalidOperationException>(() =>
            game.DeclareAttackers(alice, new Dictionary<ObjectId, AttackTarget>
            {
                [runner] = AttackTarget.At(carol, siege),
            }));
        Assert.Contains("protects it", refused.Message, StringComparison.Ordinal);

        game.DeclareAttackers(alice, new Dictionary<ObjectId, AttackTarget>
        {
            [runner] = AttackTarget.At(bob, siege),
        });
        Assert.True(game.State.Combat.Attackers.ContainsKey(runner));
    }

    [Fact]
    public void Removing_the_last_defense_counter_exiles_the_siege_and_casts_the_back_face_free()
    {
        // CR 310.12b: "When the last defense counter is removed from this permanent, exile it,
        // then you may cast it transformed without paying its mana cost." The offer is the
        // standing free-cast machinery; taking it puts the back face up on the stack
        // (CR 712.11a) and it resolves as that face alone (CR 712.8c).
        var (game, alice, bob) = InMainPhase();
        var siege = game.Create(alice, MoagSiege(), Zone.Battlefield);
        var breaker = game.Create(
            alice,
            Card("Siege Breaker Test", string.Empty, CardType.Creature, 6, 6, KeywordAbility.Haste),
            Zone.Battlefield);

        TestCards.PassToStep(game, TurnStep.DeclareAttackers);
        game.DeclareAttackers(alice, new Dictionary<ObjectId, AttackTarget>
        {
            [breaker] = AttackTarget.At(bob, siege),
        });

        // Six damage takes all five counters; the defeat trigger fires, resolves, and leaves
        // the card in exile under a standing offer to its controller.
        TestCards.PassUntil(game, () => game.State.Exile
            .Select(game.State.GetObject)
            .Any(o => o.Card.Name == "Invasion of Moag Test" && o.MayCastFree));

        Assert.DoesNotContain(siege, game.State.Battlefield);
        Assert.Empty(game.State.GetPlayer(alice).Graveyard);

        var exiled = game.State.Exile
            .Single(id => game.State.GetObject(id).Card.Name == "Invasion of Moag Test");

        // Cast it, mid-combat and with an empty mana pool: the offer covers both.
        game.CastSpell(alice, exiled);

        var onStack = game.State.GetObject(Assert.Single(game.State.Stack));
        Assert.Equal("Bloomwielder Dryads Test", onStack.Card.Name);

        Settle(game);

        var flipped = Assert.Single(
            game.State.Battlefield,
            id => game.State.GetObject(id).Card.Name == "Bloomwielder Dryads Test");
        var dryads = game.State.GetObject(flipped);
        Assert.Equal(1, dryads.Permanent!.FaceIndex);
        Assert.Equal(0, dryads.Permanent.Counters.GetValueOrDefault(CounterKinds.Defense));
        Assert.Equal(3, Characteristics.Of(game.State, Pool, dryads).Power);

        // The whole exchange — the protector, the defeat, the transformed cast — survives the
        // written log, not only the in-memory fold Settle already asserted.
        Assert.Equal(
            game.State,
            GameReducer.Replay(EventLogSerializer.Read(EventLogSerializer.Write(game.Log))));
    }

    [Fact]
    public void A_defeat_offer_declined_lapses_and_the_siege_stays_in_exile()
    {
        // CR 310.12b says "may": passing priority is declining, the window closes, and the card
        // is simply an exiled card for the rest of the game.
        var (game, alice, bob) = InMainPhase();
        var siege = game.Create(alice, MoagSiege(), Zone.Battlefield);
        var breaker = game.Create(
            alice,
            Card("Siege Breaker Test", string.Empty, CardType.Creature, 6, 6, KeywordAbility.Haste),
            Zone.Battlefield);

        TestCards.PassToStep(game, TurnStep.DeclareAttackers);
        game.DeclareAttackers(alice, new Dictionary<ObjectId, AttackTarget>
        {
            [breaker] = AttackTarget.At(bob, siege),
        });
        TestCards.PassUntil(game, () => game.State.Exile
            .Select(game.State.GetObject)
            .Any(o => o.Card.Name == "Invasion of Moag Test" && o.MayCastFree));

        Settle(game);

        var exiled = game.State.Exile
            .Single(id => game.State.GetObject(id).Card.Name == "Invasion of Moag Test");
        var declined = game.State.GetObject(exiled);
        Assert.False(declined.MayCastFree);
        Assert.False(declined.CastsTransformed);
        Assert.Throws<InvalidOperationException>(() => game.CastSpell(alice, exiled));
    }

    [Fact]
    public void A_siege_at_zero_defense_with_no_defeat_trigger_pending_is_buried()
    {
        // CR 704.5v: a Siege whose defense is 0 and which is not the source of an ability that
        // has triggered but not yet left the stack goes to its owner's graveyard. No printed
        // Siege has defense 0, but the rule contemplates reaching it without a removal — enter
        // that way and nothing was ever removed, so the defeat trigger (CR 310.12b) never fired
        // and the state-based action is all that speaks.
        var collapsed = new CardDefinition
        {
            OracleId = "oracle-r10-collapsed-siege",
            Name = "Collapsed Siege Test",
            CardTypes = CardType.Battle,
            Subtypes = ["Siege"],
            Defense = 0,
        };

        var (game, alice, _) = InMainPhase();
        var siege = game.Create(alice, collapsed, Zone.Battlefield);
        Settle(game);

        Assert.DoesNotContain(siege, game.State.Battlefield);
        Assert.Contains(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Collapsed Siege Test");
    }

    [Fact]
    public void A_protector_who_leaves_the_game_is_replaced_by_the_controllers_choice()
    {
        // CR 704.5y: a battle whose protector can no longer be its protector has a new one
        // chosen by its controller — a question again at a table where the answer could differ.
        var (game, seats) = FourPlayers();
        var (alice, bob, carol) = (seats[0], seats[1], seats[2]);

        var siege = game.Create(alice, MoagSiege(), Zone.Battlefield);
        game.PassPriority(game.State.Priority.Holder!.Value);
        game.Choose(alice, [bob.ToString("N")]);
        Assert.Equal(bob, ProtectorOf(game, siege));

        // The choice resumed priority onward; the burn is an instant, so any window of Alice's
        // will do.
        TestCards.PassUntil(game, () => game.State.Priority.Holder == alice);

        var burn = Card("Overwhelm Protector Test", "~ deals 20 damage to any target.");
        var card = TestCards.PutInHand(game, alice, burn);
        game.CastSpell(alice, card, [Target.ToPlayer(bob)]);
        Settle(game);

        // Bob is gone; the settle asked again and the harness answered with the first eligible
        // player in turn order, which is Carol.
        Assert.True(game.State.GetPlayer(bob).HasLost);
        Assert.Equal(carol, ProtectorOf(game, siege));
        Assert.Equal(
            2,
            game.Log.OfType<ChoiceRequested>()
                .Count(asked => asked.Choice.Kind == ChoiceKind.ChooseProtector));
    }

    // ---- The punisher: an offer to the player a sentence named (CR 601.2b) ---

    /// <summary>
    /// "That player loses 5 life unless they discard a card" asks the player the trigger named.
    /// </summary>
    /// <remarks>
    /// The counterspell tax had been the only shape of this the compiler read: three verbs, one
    /// target, one payer word ("its controller") and mana only. Every other punisher in the
    /// corpus is the same two halves in a different order and stayed unread — 83 lines of it.
    /// <para>
    /// Four seats, because at two the offer going to the wrong player is invisible: whoever is
    /// not the controller is the only opponent there is. Here three players cast nothing and one
    /// does, and only that one may be charged.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_punisher_asks_the_player_the_trigger_named_and_nobody_else()
    {
        var quandary = Card(
            "Painful Quandary Test",
            "Whenever an opponent casts a spell, that player loses 5 life unless they discard a card.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(quandary);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, seats) = FourPlayers();
        game.Create(seats[0], quandary, Zone.Battlefield);

        var before = seats.Select(id => game.State.GetPlayer(id).Life).ToList();

        // A card to discard as well as one to cast, so the offer is a real question rather than
        // one answered for him because he has nothing to pay with (CR 118.3).
        TestCards.PutInHand(game, seats[1], Card("Quandary Spare Test", "Draw a card."));
        var bait = TestCards.PutInHand(game, seats[1], Card("Quandary Bait Test", "Draw a card."));

        TestCards.PassUntil(game, () => game.State.Priority.Holder == seats[1]);
        game.AddMana(seats[1], ManaColor.Blue);
        game.CastSpell(seats[1], bait, []);

        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.OptionalPayment });

        // The whole point: seat one cast the spell, so seat one is asked - not the enchantment's
        // controller and not the other two opponents.
        Assert.Equal(seats[1], game.State.Choice!.PlayerId);

        // A price that is a selection is declined by picking nothing, not by saying no.
        game.Choose(seats[1], []);
        Settle(game);

        Assert.Equal(before[1] - 5, game.State.GetPlayer(seats[1]).Life);
        Assert.Equal(before[0], game.State.GetPlayer(seats[0]).Life);
        Assert.Equal(before[2], game.State.GetPlayer(seats[2]).Life);
        Assert.Equal(before[3], game.State.GetPlayer(seats[3]).Life);
    }

    /// <summary>Paying the price is what stops the consequence (CR 601.2b).</summary>
    /// <remarks>
    /// The price is a selection rather than a sum, which is the half ward already knew how to
    /// charge and this reader now borrows: "discard a card" cannot be answered yes or no without
    /// naming the card, so it is one question with a pick in it.
    /// </remarks>
    [Fact]
    public void Paying_a_punisher_leaves_the_player_alone()
    {
        var quandary = Card(
            "Paid Quandary Test",
            "Whenever an opponent casts a spell, that player loses 5 life unless they discard a card.",
            CardType.Enchantment);

        var (game, seats) = FourPlayers();
        game.Create(seats[0], quandary, Zone.Battlefield);

        var before = game.State.GetPlayer(seats[1]).Life;
        TestCards.PutInHand(game, seats[1], Card("Paid Quandary Spare Test", "Draw a card."));
        var bait = TestCards.PutInHand(game, seats[1], Card("Paid Quandary Bait Test", "Draw a card."));

        TestCards.PassUntil(game, () => game.State.Priority.Holder == seats[1]);
        game.AddMana(seats[1], ManaColor.Blue);
        game.CastSpell(seats[1], bait, []);

        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.OptionalPayment });
        var offer = game.State.Choice!;
        Assert.NotEmpty(offer.Options);

        var graveyard = game.State.GetPlayer(seats[1]).Graveyard.Count;
        game.Choose(seats[1], [offer.Options[0].Id]);
        Settle(game);

        Assert.Equal(before, game.State.GetPlayer(seats[1]).Life);
        Assert.True(game.State.GetPlayer(seats[1]).Graveyard.Count > graveyard);
    }

    /// <summary>
    /// The offer and the consequence belong to different players (CR 601.2b).
    /// </summary>
    /// <remarks>
    /// Rhystic Study's shape, and it is why the payer is a field on the offer rather than being
    /// read off whoever the effects are about: the card draws for <em>its controller</em> and
    /// charges <em>the caster</em>. A reader that assumed one player for both would have been
    /// right about half this family and quietly wrong about the other half.
    /// <para>
    /// It asserted <em>one</em> offer for a while and said in this paragraph that what the player
    /// answered was somebody else's business. That was the half that did not work: the draw is an
    /// offer too, and until the two stopped sharing a locator the caster's answer could not find
    /// its own branch, so the second question was never put and nothing was ever drawn. Both are
    /// named here now, and the branch itself is played out on
    /// <see cref="An_offer_inside_a_punisher_still_runs_when_the_price_is_declined"/>.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_punishers_price_is_charged_to_a_different_player_from_its_consequence()
    {
        var study = Card(
            "Rhystic Study Test",
            "Whenever an opponent casts a spell, you may draw a card unless that player pays {1}.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(study);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, seats) = FourPlayers();
        game.Create(seats[0], study, Zone.Battlefield);

        var bait = TestCards.PutInHand(game, seats[1], Card("Rhystic Bait Test", "Draw a card."));

        TestCards.PassUntil(game, () => game.State.Priority.Holder == seats[1]);
        game.CastSpell(seats[1], bait, []);
        Settle(game);

        // Charged to the caster, though the card that would draw belongs to somebody else - and
        // charged to *him* rather than to either of the two opponents who cast nothing. Told
        // apart by the price, because the free offer inside it carries none.
        var offers = game.Log.OfType<OptionalPaymentRequested>().ToList();

        var price = Assert.Single(offers, o => o.CostText.Length > 0);
        Assert.Equal(seats[1], price.PlayerId);

        // And the consequence is offered to the enchantment's controller.
        var draw = Assert.Single(offers, o => o.CostText.Length == 0);
        Assert.Equal(seats[0], draw.PlayerId);
    }

    /// <summary>
    /// A mana-priced punisher takes its life from the player the trigger named, at four seats.
    /// </summary>
    /// <remarks>
    /// Isolation Cell's shape. The consequence is what the whole family turns on: the trigger is
    /// about one opponent, and reading its "that player" as anything wider would take life from a
    /// table that never cast anything. Declined for want of mana rather than by an answer, which
    /// is the same branch a "no" runs.
    /// </remarks>
    [Fact]
    public void A_declined_mana_price_takes_its_consequence_from_the_named_player_only()
    {
        var cell = Card(
            "Isolation Cell Test",
            "Whenever an opponent casts a spell, that player loses 2 life unless they pay {2}.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(cell);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, seats) = FourPlayers();
        game.Create(seats[0], cell, Zone.Battlefield);

        var before = seats.Select(id => game.State.GetPlayer(id).Life).ToList();
        var bait = TestCards.PutInHand(game, seats[2], Card("Cell Bait Test", "Draw a card."));

        TestCards.PassUntil(game, () => game.State.Priority.Holder == seats[2]);
        game.CastSpell(seats[2], bait, []);
        Settle(game);

        Assert.Equal(seats[2], Assert.Single(game.Log.OfType<OptionalPaymentRequested>()).PlayerId);
        Assert.Equal(before[2] - 2, game.State.GetPlayer(seats[2]).Life);
        Assert.Equal(before[0], game.State.GetPlayer(seats[0]).Life);
        Assert.Equal(before[1], game.State.GetPlayer(seats[1]).Life);
        Assert.Equal(before[3], game.State.GetPlayer(seats[3]).Life);
    }

    /// <summary>
    /// "They" is the pronoun spelling of a player the sentence already named (CR 603.2).
    /// </summary>
    /// <remarks>
    /// The shared subject vocabulary knew "that player" and not the pronoun, so a card printing
    /// the shorter word said nothing the compiler could read. It answers
    /// <see cref="PlayerScope.NamedPlayer"/> rather than the trigger's subject for the reason the
    /// possessive does: a pronoun points back at whoever the text picked out, and half the lines
    /// carrying one are on spells with a target and no trigger at all.
    /// <para>
    /// Four seats again. "They lose 2 life" on a trigger about one opponent must reach that one
    /// opponent, and at two players every wrong answer but "you" looks like the right one.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_pronoun_reaches_the_one_player_the_trigger_was_about()
    {
        var sheoldred = Card(
            "Sheoldred Test",
            "Whenever an opponent draws a card, they lose 2 life.",
            CardType.Creature,
            power: 4,
            toughness: 5);

        var compiled = CardCompiler.Compile(sheoldred);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, seats) = FourPlayers();
        game.Create(seats[0], sheoldred, Zone.Battlefield);

        var before = seats.Select(id => game.State.GetPlayer(id).Life).ToList();

        var draw = TestCards.PutInHand(game, seats[2], Card("Sheoldred Draw Test", "Draw a card."));
        TestCards.PassUntil(game, () => game.State.Priority.Holder == seats[2]);
        game.AddMana(seats[2], ManaColor.Blue);
        game.CastSpell(seats[2], draw, []);
        Settle(game);

        Assert.Equal(before[2] - 2, game.State.GetPlayer(seats[2]).Life);
        Assert.Equal(before[0], game.State.GetPlayer(seats[0]).Life);
        Assert.Equal(before[1], game.State.GetPlayer(seats[1]).Life);
        Assert.Equal(before[3], game.State.GetPlayer(seats[3]).Life);
    }

    /// <summary>A pronoun after a target names the target (CR 115.1).</summary>
    /// <remarks>
    /// The other half of <see cref="PlayerScope.NamedPlayer"/>, and the reason a punisher does not
    /// simply read the trigger's subject: Compulsive Research is a sorcery and has no trigger, so
    /// the only player its "they" can mean is the one the target slot chose.
    /// </remarks>
    [Fact]
    public void A_pronoun_after_a_target_charges_that_target()
    {
        var research = Card(
            "Compulsive Research Test",
            "Target player draws three cards. Then that player discards two cards unless they "
                + "discard a land card.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(research);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, seats) = FourPlayers();
        var card = TestCards.PutInHand(game, seats[0], research);

        // The price is a land card, so seat two has to hold one: an offer nobody could
        // take is answered for them rather than put to them (CR 118.3).
        TestCards.PutInHand(game, seats[2], TestCards.BasicLand("Forest"));

        game.AddMana(seats[0], ManaColor.Blue);
        game.AddMana(seats[0], ManaColor.Blue);
        game.CastSpell(seats[0], card, [Target.ToPlayer(seats[2])]);

        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.OptionalPayment });

        // Aimed at seat two, so seat two is asked - not the caster, and not either of the two
        // opponents the spell never mentioned.
        Assert.Equal(seats[2], game.State.Choice!.PlayerId);
    }

    /// <summary>
    /// A punisher aimed at a group is left unread rather than charged to one of them.
    /// </summary>
    /// <remarks>
    /// "Each opponent loses 3 life unless they pay {2}" is three questions at a four-player table
    /// and <see cref="MayPay"/> asks one. Reading it would charge the first opponent and let the
    /// rest of the table off, which is a different card from the one printed and one no coverage
    /// number could tell apart from a working reader. The refusal is the load-bearing half.
    /// </remarks>
    [Theory]
    [InlineData("Each opponent loses 3 life unless they discard a card.")]
    [InlineData("Each opponent sacrifices a permanent of their choice unless they pay {1}.")]
    [InlineData("Each player loses 4 life unless they sacrifice a creature of their choice.")]
    public void A_punisher_aimed_at_a_group_is_left_unread(string text)
    {
        var card = Card("Group Punisher Test", text, CardType.Sorcery);

        Assert.False(CardCompiler.Compile(card).IsComplete);
    }

    /// <summary>
    /// "Unless they're mana abilities" is not a player at all (CR 605.1a).
    /// </summary>
    /// <remarks>
    /// The pronoun is the risk this whole family carries: thirteen corpus lines spell "they"
    /// about a batch of <em>abilities</em>, and a payer vocabulary that took any "they" would
    /// have turned a restriction on activating into an offer nobody is ever made. It stays unread
    /// because the pattern wants a verb of payment after the word, not because anything counted
    /// these thirteen.
    /// </remarks>
    [Theory]
    [InlineData("Activated abilities of artifacts and creatures can't be activated unless "
        + "they're mana abilities.")]
    [InlineData("Activated abilities cost {2} more to activate unless they're mana abilities.")]
    public void A_pronoun_that_names_abilities_is_not_a_payer(string text)
    {
        var card = Card("Damping Test", text, CardType.Artifact);

        Assert.False(CardCompiler.Compile(card).IsComplete);
    }

    /// <summary>
    /// The counterspell tax still asks the controller of the thing it is aimed at.
    /// </summary>
    /// <remarks>
    /// The shape the widened reader grew out of, kept under test at the same door it came in
    /// through: "its controller" is a relation to a target and not a player the text named, so it
    /// must still go through <c>AskTargetController</c> rather than through the scope. The corpus
    /// diff for this change was 25 cards gained, none lost and no compiled ability altered on any
    /// card that already read - this is the behavioural half of that claim.
    /// </remarks>
    [Fact]
    public void The_counterspell_tax_still_asks_the_controller_of_its_target()
    {
        var portal = Card(
            "Erratic Portal Test",
            "{1}, {T}: Return target creature to its owner's hand unless its controller pays {1}.",
            CardType.Artifact);

        var compiled = CardCompiler.Compile(portal);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, seats) = FourPlayers();
        var gate = game.Create(seats[0], portal, Zone.Battlefield);
        var his = game.Create(seats[2], TestCards.Creature("Portal Victim Test", 2, 2), Zone.Battlefield);

        // Untapped mana of his own, so the tax is a question rather than one answered
        // for him (CR 118.3).
        game.Create(seats[2], TestCards.BasicLand("Island"), Zone.Battlefield);

        game.AddMana(seats[0], ManaColor.Blue);
        game.ActivateAbility(seats[0], gate, "a", targets: [Target.ToPermanent(his)]);

        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.OptionalPayment });

        // The creature's controller, who is neither the artifact's controller nor either of the
        // other two seats.
        Assert.Equal(seats[2], game.State.Choice!.PlayerId);

        game.Choose(seats[2], ["no"]);
        Settle(game);

        Assert.DoesNotContain(his, game.State.Battlefield);
    }

    /// <summary>
    /// An offer with nobody to ask is an offer declined, not an effect skipped (CR 118.3).
    /// </summary>
    /// <remarks>
    /// The direction this reader has to be wrong in. A scope that names no seat - a trigger about
    /// a permanent rather than a player, a target that has since gone - could either do nothing
    /// or run the consequence, and only one of those is safe: a punisher that quietly stops
    /// punishing is a card strictly better than the one printed, and nothing downstream would
    /// notice. So the price no player can pay is a price not paid.
    /// <para>
    /// No printed card says this; it is written to reach the branch, because a documented
    /// fallback nothing exercises is a documented guess.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_price_no_player_can_be_asked_for_is_a_price_not_paid()
    {
        var orphan = Card(
            "Orphan Punisher Test",
            "Whenever this creature attacks, you lose 2 life unless they pay {1}.",
            CardType.Creature,
            power: 2,
            toughness: 2,
            keywords: KeywordAbility.Haste);

        var compiled = CardCompiler.Compile(orphan);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, orphan, Zone.Battlefield);
        var before = game.State.GetPlayer(alice).Life;

        TestCards.PassToStep(game, TurnStep.DeclareAttackers);
        game.DeclareAttackers(alice, new Dictionary<ObjectId, AttackTarget>
        {
            [attacker] = AttackTarget.Player(bob),
        });

        Settle(game);

        // Nobody was asked, and the consequence ran anyway.
        Assert.Equal(before - 2, game.State.GetPlayer(alice).Life);
        Assert.DoesNotContain(
            game.Log, e => e is ChoiceRequested { Choice.Kind: ChoiceKind.OptionalPayment });
    }

    // ---- Aftermath (CR 702.127) ----------------------------------------------

    /// <summary>A split card whose second half is cast from the graveyard.</summary>
    private static CardDefinition AftermathCard() => new()
    {
        OracleId = "oracle-test-aftermath",
        Name = "Test Strike // Test Echo",
        ManaCostRaw = "{R}",
        OracleText = "You gain 1 life.",
        CardTypes = CardType.Sorcery,
        Faces =
        [
            new CardFace
            {
                Name = "Test Strike",
                ManaCostRaw = "{R}",
                TypeLine = "Sorcery",
                CardTypes = CardType.Sorcery,
                OracleText = "You gain 1 life.",
            },
            new CardFace
            {
                Name = "Test Echo",
                ManaCostRaw = "{2}{R}",
                TypeLine = "Sorcery",
                CardTypes = CardType.Sorcery,
                OracleText = "You gain 5 life.\nAftermath",
            },
        ],
    };

    /// <summary>
    /// An aftermath half is cast from the graveyard, from nowhere else, and is exiled afterwards
    /// (CR 702.127a).
    /// </summary>
    /// <remarks>
    /// One word, three static abilities, and the two easy to skip are the ones that make it a
    /// two-part card rather than simply a better one: it cannot be cast from hand, and it is
    /// exiled rather than put back where it came from. Without the second, the card returns to
    /// the graveyard it was just cast from and can be cast again every turn.
    /// </remarks>
    [Fact]
    public void An_aftermath_half_is_cast_from_the_graveyard_and_then_exiled()
    {
        var split = AftermathCard();

        var compiled = CardCompiler.Compile(split);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.True(compiled.Halves[1].HasAftermath);

        var (game, alice, _) = InMainPhase();
        var start = game.State.GetPlayer(alice).Life;
        var card = TestCards.PutInHand(game, alice, split);

        for (var i = 0; i < 8; i++)
            game.AddMana(alice, ManaColor.Red);

        // From hand it is only the first half. The second refuses.
        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, card, [], half: 1));

        game.CastSpell(alice, card, [], half: 0);
        Settle(game);

        Assert.Equal(start + 1, game.State.GetPlayer(alice).Life);

        var inGraveyard = Assert.Single(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Test Strike // Test Echo");

        game.CastSpell(alice, inGraveyard, [], half: 1);
        Settle(game);

        Assert.Equal(start + 6, game.State.GetPlayer(alice).Life);

        // Exiled, not returned - so it cannot be cast a third time.
        Assert.Contains(
            game.State.Exile,
            id => game.State.GetObject(id).Card.Name == "Test Strike // Test Echo");

        Assert.DoesNotContain(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Test Strike // Test Echo");
    }
    // ---- Casting a card from where it was hidden (CR 702.75, CR 601.2b, CR 601.3) ----

    /// <summary>The wording every hideaway permanent prints, with its payout line.</summary>
    /// <remarks>
    /// Clive's Hideaway, minus nothing: the keyword, a mana ability, and the line that says when
    /// the buried card may be played. That last line is the one under test, and until now it was
    /// the only thing on all twelve hideaway cards that nothing read — so the keyword compiled,
    /// buried a card, and could never hand it back.
    /// </remarks>
    private static CardDefinition Hideaway(string name) => Card(
        name,
        "Hideaway 4\n{T}: Add {C}.\n{2}, {T}: You may play the exiled card without paying its "
            + "mana cost if you control four or more legendary creatures.",
        CardType.Land);

    /// <summary>The payout ability's id, whatever the compiler numbered it.</summary>
    private static string Payout(CardDefinition card) =>
        CardCompiler.Compile(card).Activated.Single(a => !a.IsManaAbility).Id;

    /// <summary>Four legendary creatures, so a hideaway gate that counts them is open.</summary>
    private static void FourLegends(Game game, Guid who, string prefix)
    {
        for (var i = 0; i < 4; i++)
            game.Create(who, TestCards.Legend($"{prefix} Legend {i} Test"), Zone.Battlefield);
    }

    /// <summary>A card expensive enough that casting it for nothing is unmistakable.</summary>
    private static CardDefinition Payload(string name) => new()
    {
        OracleId = "oracle-" + name.ToLowerInvariant().Replace(' ', '-'),
        Name = name,
        CardTypes = CardType.Sorcery,
        ManaCostRaw = "{5}{W}{W}",
        Cmc = 7,
        OracleText = "You gain 5 life.",
    };

    /// <summary>
    /// Hideaway's payout: the buried card is offered, and taking it costs nothing (CR 702.75a).
    /// </summary>
    /// <remarks>
    /// Played rather than parsed, because a parse tree cannot tell the difference between an offer
    /// and a blank. The land buries a seven-mana sorcery, its ability is paid for with the last
    /// two mana Alice has, and the sorcery then goes on the stack out of exile with an empty pool.
    /// </remarks>
    [Fact]
    public void A_hideaway_permanent_pays_out_the_card_it_buried()
    {
        var vale = Hideaway("Hidden Vale Test");

        var compiled = CardCompiler.Compile(vale);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        game.Create(alice, Payload("Hidden Vale Payload Test"), Zone.Library);
        FourLegends(game, alice, "Hidden Vale");

        var first = game.Create(alice, TestCards.BasicLand("Mountain"), Zone.Battlefield);
        var second = game.Create(alice, TestCards.BasicLand("Mountain"), Zone.Battlefield);
        var land = game.Create(alice, vale, Zone.Battlefield);
        Settle(game);

        // CR 702.75a: the keyword's own half. One card is in exile and it knows which permanent
        // put it there, which is the whole of what "the exiled card" means on the line below.
        var hidden = game.State.Exile.Select(game.State.GetObject).Single();
        Assert.Equal("Hidden Vale Payload Test", hidden.Card.Name);
        Assert.Equal(land, hidden.ExiledBy);

        game.ActivateAbility(alice, first, "mana");
        game.ActivateAbility(alice, second, "mana");
        game.ActivateAbility(alice, land, Payout(vale));
        Run(game);

        Assert.Single(game.Log.OfType<FreeCastOffered>());
        Assert.True(game.State.GetObject(hidden.Id).MayCastFree);

        // Nothing left to pay with, which is what makes the cast below mean something.
        Assert.Equal(0, game.State.GetPlayer(alice).ManaPool.Total);

        game.CastSpell(alice, hidden.Id);
        Settle(game);

        Assert.Equal(25, game.State.GetPlayer(alice).Life);
        Assert.Empty(game.State.Exile);
    }

    /// <summary>
    /// The offer is a window, and passing priority closes it (CR 601.2b).
    /// </summary>
    /// <remarks>
    /// The printed sentence gives the window inside the resolution and this engine gives one that
    /// ends at the offer-holder's next pass — the deviation the whole offer-a-cast family shares.
    /// What it may never become is permanent: a hideaway card that stayed castable for free for
    /// the rest of the game is a strictly better card than the one printed, and coverage would
    /// score that as a win.
    /// </remarks>
    [Fact]
    public void A_hideaway_offer_lapses_when_its_window_closes()
    {
        var vale = Hideaway("Lapsing Vale Test");
        var (game, alice, _) = InMainPhase();
        game.Create(alice, Payload("Lapsing Vale Payload Test"), Zone.Library);
        FourLegends(game, alice, "Lapsing Vale");

        var first = game.Create(alice, TestCards.BasicLand("Mountain"), Zone.Battlefield);
        var second = game.Create(alice, TestCards.BasicLand("Mountain"), Zone.Battlefield);
        var land = game.Create(alice, vale, Zone.Battlefield);
        Settle(game);

        var hidden = game.State.Exile.Select(game.State.GetObject).Single().Id;

        game.ActivateAbility(alice, first, "mana");
        game.ActivateAbility(alice, second, "mana");
        game.ActivateAbility(alice, land, Payout(vale));
        Run(game);

        Assert.True(game.State.GetObject(hidden).MayCastFree);

        game.PassPriority(alice);

        Assert.Single(game.Log.OfType<FreeCastLapsed>());
        Assert.False(game.State.GetObject(hidden).MayCastFree);

        // The card is still in exile and still nobody's to cast: the offer bought the zone, and
        // when it lapsed the zone rule came back with it (CR 601.3a).
        TestCards.PassUntil(game, () => game.State.Priority.Holder == alice);
        Assert.Throws<InvalidOperationException>(() => game.CastSpell(alice, hidden));
        Assert.Single(game.State.Exile);
    }

    /// <summary>
    /// A gate that is shut offers nothing at all (CR 702.75a).
    /// </summary>
    /// <remarks>
    /// Eleven of the twelve hideaway cards hang their payout on the board, and the condition is
    /// the entire price of the mechanic: a Mosswort Bridge that pays out without ten power on the
    /// table is a different card. The ability still resolves — the mana and the tap are spent
    /// — and simply finds nothing to offer.
    /// </remarks>
    [Fact]
    public void A_hideaway_gate_that_is_shut_offers_nothing()
    {
        var vale = Hideaway("Shut Vale Test");
        var (game, alice, _) = InMainPhase();
        game.Create(alice, Payload("Shut Vale Payload Test"), Zone.Library);

        // Three, not four.
        for (var i = 0; i < 3; i++)
            game.Create(alice, TestCards.Legend($"Shut Vale Legend {i} Test"), Zone.Battlefield);

        var first = game.Create(alice, TestCards.BasicLand("Mountain"), Zone.Battlefield);
        var second = game.Create(alice, TestCards.BasicLand("Mountain"), Zone.Battlefield);
        var land = game.Create(alice, vale, Zone.Battlefield);
        Settle(game);

        var hidden = game.State.Exile.Select(game.State.GetObject).Single().Id;

        game.ActivateAbility(alice, first, "mana");
        game.ActivateAbility(alice, second, "mana");
        game.ActivateAbility(alice, land, Payout(vale));
        Run(game);

        Assert.Empty(game.Log.OfType<FreeCastOffered>());
        Assert.False(game.State.GetObject(hidden).MayCastFree);
        Assert.True(game.State.GetObject(land).Permanent?.IsTapped);
        Assert.Throws<InvalidOperationException>(() => game.CastSpell(alice, hidden));
    }

    /// <summary>
    /// The buried card is as often a land as anything else, and "play" covers it (CR 305.1).
    /// </summary>
    /// <remarks>
    /// Every printing of this line says "you may <em>play</em>", not "cast", and the word is
    /// doing work: a hideaway permanent buries whatever the look turned up. An offer that only
    /// ever bought a cast would leave the land sitting in exile with the card saying it may be
    /// played, so the free-cast permission is read as permission to play a land too. It buys the
    /// zone and nothing else — the land drop is still spent.
    /// </remarks>
    [Fact]
    public void A_hidden_land_is_played_rather_than_cast()
    {
        var vale = Hideaway("Land Vale Test");
        var (game, alice, _) = InMainPhase();
        game.Create(alice, Card("Land Vale Payload Test", string.Empty, CardType.Land), Zone.Library);
        FourLegends(game, alice, "Land Vale");

        var first = game.Create(alice, TestCards.BasicLand("Mountain"), Zone.Battlefield);
        var second = game.Create(alice, TestCards.BasicLand("Mountain"), Zone.Battlefield);
        var land = game.Create(alice, vale, Zone.Battlefield);
        Settle(game);

        var hidden = game.State.Exile.Select(game.State.GetObject).Single().Id;

        game.ActivateAbility(alice, first, "mana");
        game.ActivateAbility(alice, second, "mana");
        game.ActivateAbility(alice, land, Payout(vale));
        Run(game);

        // A land is played, never cast (CR 305.1) - so the offer has to be readable by the other
        // door as well as by the casting one.
        Assert.Throws<InvalidOperationException>(() => game.CastSpell(alice, hidden));

        game.PlayLand(alice, hidden);
        Settle(game);

        Assert.Contains(
            game.State.Battlefield.Select(game.State.GetObject),
            o => o.Card.Name == "Land Vale Payload Test");
    }

    /// <summary>
    /// "The exiled card" is the one <em>this</em> permanent buried (CR 702.75a).
    /// </summary>
    /// <remarks>
    /// The reason the link lives on the exiled card rather than being hunted for at pay-out time:
    /// two hideaway permanents on one board put two cards in the same zone, both owned by the
    /// same player, and a hunt would hand over whichever came first.
    /// </remarks>
    [Fact]
    public void Each_hideaway_permanent_offers_only_the_card_it_buried()
    {
        var vale = Hideaway("Twin Vale Test");
        var (game, alice, _) = InMainPhase();
        FourLegends(game, alice, "Twin Vale");

        game.Create(alice, Payload("Twin Vale First Payload Test"), Zone.Library);
        var older = game.Create(alice, vale, Zone.Battlefield);
        Settle(game);

        game.Create(alice, Payload("Twin Vale Second Payload Test"), Zone.Library);
        var newer = game.Create(alice, vale, Zone.Battlefield);
        Settle(game);

        var byOlder = game.State.Exile.Select(game.State.GetObject)
            .Single(o => o.ExiledBy == older);
        var byNewer = game.State.Exile.Select(game.State.GetObject)
            .Single(o => o.ExiledBy == newer);

        Assert.Equal("Twin Vale First Payload Test", byOlder.Card.Name);
        Assert.Equal("Twin Vale Second Payload Test", byNewer.Card.Name);

        var first = game.Create(alice, TestCards.BasicLand("Mountain"), Zone.Battlefield);
        var second = game.Create(alice, TestCards.BasicLand("Mountain"), Zone.Battlefield);

        game.ActivateAbility(alice, first, "mana");
        game.ActivateAbility(alice, second, "mana");
        game.ActivateAbility(alice, newer, Payout(vale));
        Run(game);

        Assert.True(game.State.GetObject(byNewer.Id).MayCastFree);
        Assert.False(game.State.GetObject(byOlder.Id).MayCastFree);
    }

    /// <summary>
    /// "You may cast this card from your graveyard as long as ..." holds only while it does.
    /// </summary>
    /// <remarks>
    /// Gravecrawler's sentence, which is the static ability flashback grants written out in full
    /// instead of behind a keyword: the zone, the card's own cost, and nothing exiled afterwards.
    /// Almost every card that prints it hangs it on the board, and the gate is asked at the moment
    /// of the cast rather than folded in when the card was compiled - which is what "as long as"
    /// means, and the difference between reading the card and inventing a better one.
    /// </remarks>
    [Fact]
    public void A_graveyard_permission_holds_only_while_its_condition_does()
    {
        var crawler = new CardDefinition
        {
            OracleId = "oracle-yard-crawler-test",
            Name = "Yard Crawler Test",
            CardTypes = CardType.Creature,
            Subtypes = ["Zombie"],
            ManaCostRaw = "{1}{B}",
            Cmc = 2,
            Power = 2,
            Toughness = 1,
            OracleText = "You may cast ~ from your graveyard as long as you control a Zombie.",
        };

        var compiled = CardCompiler.Compile(crawler);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var swamp = game.Create(alice, TestCards.BasicLand("Swamp"), Zone.Battlefield);
        var mountain = game.Create(alice, TestCards.BasicLand("Mountain"), Zone.Battlefield);
        var buried = game.Create(alice, crawler, Zone.Graveyard);

        game.ActivateAbility(alice, swamp, "mana");
        game.ActivateAbility(alice, mountain, "mana");

        // No Zombie on the battlefield: the permission is not there, and the zone rule refuses
        // the cast with the mana still floating.
        Assert.Throws<InvalidOperationException>(() => game.CastSpell(alice, buried));

        game.Create(
            alice,
            Card(
                "Yard Crawler Friend Test",
                string.Empty,
                CardType.Creature,
                power: 1,
                toughness: 1,
                subtypes: "Zombie"),
            Zone.Battlefield);

        game.CastSpell(alice, buried);
        Settle(game);

        Assert.Contains(
            game.State.Battlefield.Select(game.State.GetObject),
            o => o.Card.Name == "Yard Crawler Test");
    }

    /// <summary>
    /// A gate the board vocabulary cannot answer leaves the whole line unread (CR 601.3a).
    /// </summary>
    /// <remarks>
    /// The control on the reader above, and the direction it is allowed to be wrong in. Ebondeath
    /// asks whether "a creature not named ~ died this turn" and nothing here can answer that; the
    /// tempting reading takes the permission and drops the condition, which is a Dracolich that
    /// comes back every turn for nothing. So the sentence is refused and the card is reported
    /// unread instead.
    /// </remarks>
    [Fact]
    public void A_graveyard_permission_whose_gate_cannot_be_read_is_not_read_at_all()
    {
        var ebondeath = Card(
            "Unread Gate Test",
            "You may cast ~ from your graveyard if a creature not named ~ died this turn.",
            CardType.Creature,
            power: 3,
            toughness: 4);

        var compiled = CardCompiler.Compile(ebondeath);

        Assert.False(compiled.IsComplete);
        Assert.Contains(
            compiled.Unhandled,
            line => line.Contains("from your graveyard", StringComparison.Ordinal));
    }

    /// <summary>
    /// "Exile the top card ... you may play that card <em>without paying its mana cost</em>" is a
    /// different mechanism from the impulse it is four words longer than (CR 601.2b, CR 601.3e).
    /// </summary>
    /// <remarks>
    /// Oracle's Vault prints both sentences, one per ability, which is what makes the pair worth
    /// a test: the shorter one lends the card at its printed price until end of turn, and the
    /// longer one gives it away. They land on different machinery — a play permission with a
    /// deadline against a standing free-cast offer — and the offer's window is the shorter of the
    /// two, which is the safe direction for it to differ in.
    /// </remarks>
    [Fact]
    public void Exiling_the_top_card_for_a_free_play_offers_it_rather_than_lending_it()
    {
        var vault = Card(
            "Brick Vault Test",
            "{T}: Exile the top card of your library. Until end of turn, you may play that card "
                + "without paying its mana cost.",
            CardType.Artifact);

        var lender = Card(
            "Lending Vault Test",
            "{T}: Exile the top card of your library. Until end of turn, you may play that card.",
            CardType.Artifact);

        foreach (var card in new[] { vault, lender })
        {
            var check = CardCompiler.Compile(card);
            Assert.True(check.IsComplete, string.Join(" | ", check.Unhandled));
        }

        var (game, alice, _) = InMainPhase();
        var free = game.Create(alice, vault, Zone.Battlefield);
        var lent = game.Create(alice, lender, Zone.Battlefield);

        game.ActivateAbility(alice, free, Payout(vault));
        Run(game);

        var offered = game.State.Exile.Select(game.State.GetObject).Single();
        Assert.True(offered.MayCastFree);
        Assert.Null(offered.MayPlayUntilTurn);
        Assert.Single(game.Log.OfType<FreeCastOffered>());

        game.ActivateAbility(alice, lent, Payout(lender));
        Run(game);

        // The control: the same sentence without the four words is the impulse the engine has
        // always read, and it charges.
        var borrowed = game.State.Exile.Select(game.State.GetObject)
            .Single(o => o.Id != offered.Id);

        Assert.False(borrowed.MayCastFree);
        Assert.Equal(game.State.TurnNumber, borrowed.MayPlayUntilTurn);
        Assert.Single(game.Log.OfType<FreeCastOffered>());
    }

    /// <summary>
    /// "The exiled card" is read where the card says <em>play</em>, and nowhere else.
    /// </summary>
    /// <remarks>
    /// All twelve cards printing "you may play the exiled card without paying its mana cost" are
    /// hideaway cards; all fourteen printing "cast" instead mean a card some other sentence of
    /// their own exiled, with no link back to the permanent. Reading the wider verb compiled
    /// Living Lore's attack trigger into an ability that found nothing and did nothing — read,
    /// counted, and silently blank, which is the worse half of the trade. So the verb is the test.
    /// </remarks>
    [Fact]
    public void The_exiled_card_is_read_where_the_card_says_play_and_not_where_it_says_cast()
    {
        var played = Card(
            "Hidden Verb Play Test",
            "Hideaway 4\n{2}, {T}: You may play the exiled card without paying its mana cost.",
            CardType.Land);

        var cast = Card(
            "Hidden Verb Cast Test",
            "Hideaway 4\n{2}, {T}: You may cast the exiled card without paying its mana cost.",
            CardType.Land);

        var readable = CardCompiler.Compile(played);
        Assert.True(readable.IsComplete, string.Join(" | ", readable.Unhandled));

        Assert.False(CardCompiler.Compile(cast).IsComplete);
    }

    // ---- Dungeons and venturing (CR 309, CR 701.49) ---------------------------

    /// <summary>An instant that ventures, so a test can venture as often as it likes.</summary>
    private static CardDefinition VentureCard() =>
        Card("Venture Test", "Venture into the dungeon.");

    /// <summary>Casts one venture and plays on until the game is quiet again.</summary>
    private static void Venture(Game game, Guid who)
    {
        game.CastSpell(who, TestCards.PutInHand(game, who, VentureCard()), []);
        Settle(game);
    }

    /// <summary>The dungeon this player owns in the command zone, or null.</summary>
    private static GameObject? DungeonOf(Game game, Guid who) =>
        Dungeons.OwnedBy(game.State, who);

    /// <summary>What a permanent is now, after the layers (CR 613).</summary>
    private static ComputedCharacteristics Now(Game game, ObjectId id) =>
        Characteristics.Of(game.State, Pool, game.State.GetObject(id));

    /// <summary>The power a creature has now, after the layers (CR 613).</summary>
    private static int PowerNow(Game game, ObjectId id) => Now(game, id).Power ?? 0;

    /// <summary>
    /// Venturing with no dungeon puts one in the command zone and moves the marker onto its
    /// topmost room, whose ability then triggers (CR 701.49a, CR 309.4a, CR 309.4c).
    /// </summary>
    /// <remarks>
    /// The middle assertion is the one worth having: a dungeon card is not a permanent
    /// (CR 309.2c), so a sweeper that destroys all artifacts must not be able to see it, and it
    /// must not be counted as a permanent anybody controls.
    /// </remarks>
    [Fact]
    public void Venturing_with_no_dungeon_starts_one_in_the_command_zone()
    {
        var compiled = CardCompiler.Compile(VentureCard());
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();

        Venture(game, alice);

        var dungeon = DungeonOf(game, alice);
        Assert.NotNull(dungeon);
        Assert.Equal(Dungeons.LostMineOfPhandelver, dungeon.Card.Name);

        // Not a permanent, and not on the battlefield (CR 309.2c).
        Assert.Contains(dungeon.Id, game.State.Command);
        Assert.DoesNotContain(dungeon.Id, game.State.Battlefield);
        Assert.Null(dungeon.Permanent);

        // CR 309.4a: the marker goes on the topmost room.
        Assert.Equal("Cave Entrance", game.State.GetPlayer(alice).DungeonRoom);
    }

    /// <summary>
    /// A room with two arrows out of it asks its owner which to follow, and only the room they
    /// chose triggers (CR 701.49b).
    /// </summary>
    /// <remarks>
    /// The room ability is a real triggered ability whose source is the dungeon card (CR 309.4c),
    /// which is the whole reason a dungeon is an object in the command zone rather than a field
    /// on the player. Running a room's effect inside the venture would be a shorter
    /// implementation and a different game: nobody could respond, and no room could target — two
    /// of Lost Mine's seven rooms do.
    /// </remarks>
    [Fact]
    public void A_fork_asks_which_room_to_enter_and_only_that_room_fires()
    {
        var (game, alice, _) = InMainPhase();

        Venture(game, alice);

        // Cave Entrance leads to Goblin Lair and Mine Tunnels, so the second venture forks.
        game.CastSpell(alice, TestCards.PutInHand(game, alice, VentureCard()), []);

        PassUntilRoomChoice(game);

        var choice = Assert.IsType<PendingChoice>(game.State.Choice);
        Assert.Equal(ChoiceKind.VentureRoom, choice.Kind);
        Assert.Equal(
            ["Goblin Lair", "Mine Tunnels"],
            choice.Options.Select(o => o.Id).Order(StringComparer.Ordinal));

        game.Choose(alice, ["Mine Tunnels"]);
        Settle(game);

        Assert.Equal("Mine Tunnels", game.State.GetPlayer(alice).DungeonRoom);

        // Mine Tunnels creates a Treasure; Goblin Lair, the arrow not taken, creates a Goblin.
        Assert.Contains(
            game.State.Battlefield,
            id => game.State.GetObject(id).Card.Name == "Treasure");

        Assert.DoesNotContain(
            game.State.Battlefield,
            id => game.State.GetObject(id).Card.Name == "Goblin");
    }

    /// <summary>Plays on until the venture fork is the question being asked.</summary>
    private static void PassUntilRoomChoice(Game game)
    {
        for (var guard = 0; guard < 40; guard++)
        {
            if (game.State.Choice is { Kind: ChoiceKind.VentureRoom })
                return;

            if (game.State.Choice is { } other)
            {
                game.Choose(
                    other.PlayerId,
                    [.. other.Options.Take(Math.Max(other.MinPicks, 1)).Select(o => o.Id)]);
                continue;
            }

            if (game.State.Priority.Holder is not { } holder)
                break;

            game.PassPriority(holder);
        }

        Assert.Fail("The venture never reached a fork.");
    }

    /// <summary>Ventures along a named path, answering each fork with the room wanted.</summary>
    private static void VentureTo(Game game, Guid who, params string[] rooms)
    {
        foreach (var room in rooms)
        {
            game.CastSpell(who, TestCards.PutInHand(game, who, VentureCard()), []);

            var passedOnce = false;

            for (var guard = 0; guard < 80; guard++)
            {
                if (game.State.Choice is { } choice)
                {
                    string[] picks = choice.Kind == ChoiceKind.VentureRoom
                        ? [room]
                        : [.. choice.Options
                            .Take(Math.Max(choice.MinPicks, 1))
                            .Select(o => o.Id)];

                    game.Choose(choice.PlayerId, picks);
                    continue;
                }

                if (passedOnce
                    && game.State.Stack.IsEmpty
                    && game.State.PendingTriggers.IsEmpty)
                {
                    break;
                }

                if (game.State.Priority.Holder is not { } holder)
                    break;

                game.PassPriority(holder);
                passedOnce = true;
            }
        }

        Assert.Equal(game.State, GameReducer.Replay(game.Log));
    }

    /// <summary>
    /// A room ability can target, and the target is chosen as the ability goes on the stack
    /// (CR 603.3d).
    /// </summary>
    [Fact]
    public void A_room_ability_targets_a_creature_the_player_chooses()
    {
        var (game, alice, _) = InMainPhase();

        var bear = game.Create(alice, TestCards.Creature("Dungeon Bear"), Zone.Battlefield);

        VentureTo(game, alice, "Cave Entrance", "Goblin Lair", "Storeroom");

        Assert.Equal("Storeroom", game.State.GetPlayer(alice).DungeonRoom);

        // Storeroom is "put a +1/+1 counter on target creature". Two creatures are on the
        // battlefield by now — the bear and the Goblin the previous room made — and the counter
        // is on whichever was chosen, not on both and not on neither.
        var counters = game.State.Battlefield
            .Select(game.State.GetObject)
            .Sum(o => o.Permanent is { } p
                ? p.Counters.GetValueOrDefault(CounterKinds.PlusOnePlusOne)
                : 0);

        Assert.Equal(1, counters);
        Assert.Contains(bear, game.State.Battlefield);
    }

    /// <summary>
    /// A dungeon is completed as its card leaves the game, which is after the bottommost room's
    /// ability has resolved (CR 309.6, CR 309.7).
    /// </summary>
    /// <remarks>
    /// The ordering is the whole rule, and it is the same trap the Saga sacrifice has: the last
    /// room triggers on the marker arriving, so at the moment the marker reaches it the ability
    /// has not resolved. A dungeon removed then is a dungeon whose last room never happened —
    /// here, Temple of Dumathoin's card never drawn.
    /// </remarks>
    [Fact]
    public void Completing_a_dungeon_happens_after_its_last_room_and_removes_it_from_the_game()
    {
        var varis = Card(
            "Varis Test",
            "Whenever you complete a dungeon, create a 2/2 green Wolf creature token.",
            CardType.Creature,
            2,
            2);

        var compiled = CardCompiler.Compile(varis);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        game.Create(alice, varis, Zone.Battlefield);

        var drawn = game.State.GetPlayer(alice).Hand.Count;

        VentureTo(game, alice, "Cave Entrance", "Goblin Lair", "Dark Pool", "Temple of Dumathoin");

        // CR 309.6: the card is gone from the command zone, and CR 309.7 says its owner completed
        // it as that happened.
        Assert.Null(DungeonOf(game, alice));
        Assert.Null(game.State.GetPlayer(alice).DungeonRoom);
        Assert.Equal(
            [Dungeons.LostMineOfPhandelver],
            game.State.GetPlayer(alice).CompletedDungeons);

        // Dark Pool ran on the way past: each opponent lost 1 life and Alice gained 1.
        Assert.Equal(21, game.State.GetPlayer(alice).Life);

        // And the trigger that watches for the completion fired.
        Assert.Contains(
            game.State.Battlefield,
            id => game.State.GetObject(id).Card.Name == "Wolf");

        // The last room's own draw happened before the dungeon left, which is the ordering this
        // test exists for. Four ventures were cast out of hand and one card scried to the bottom,
        // so the hand is compared against what those account for plus Temple of Dumathoin's card.
        Assert.True(
            game.State.GetPlayer(alice).Hand.Count >= drawn - 4,
            $"hand went from {drawn} to {game.State.GetPlayer(alice).Hand.Count}");
    }

    /// <summary>
    /// "As long as you've completed a dungeon" is false until one has been completed, and true
    /// from then on (CR 309.7).
    /// </summary>
    /// <remarks>
    /// It stays true with no dungeon anywhere, which is the point of keeping the completed ones
    /// on the player: completing a dungeon is the moment its card <em>leaves</em>, so a condition
    /// that looked for a dungeon on the board would be false exactly when it must be true.
    /// </remarks>
    [Fact]
    public void A_completed_dungeon_condition_turns_on_when_the_dungeon_finishes()
    {
        var stalker = Card(
            "Gloom Stalker Test",
            "As long as you've completed a dungeon, ~ has double strike.",
            CardType.Creature,
            3,
            2);

        var compiled = CardCompiler.Compile(stalker);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var gloom = game.Create(alice, stalker, Zone.Battlefield);

        Assert.False(Now(game, gloom).Has(KeywordAbility.DoubleStrike));

        VentureTo(game, alice, "Cave Entrance", "Goblin Lair", "Dark Pool", "Temple of Dumathoin");

        // The dungeon card has left the game, and the condition is true from here on.
        Assert.Null(DungeonOf(game, alice));
        Assert.True(Now(game, gloom).Has(KeywordAbility.DoubleStrike));
    }

    /// <summary>
    /// "Until your next turn" outlasts every other player's turn and ends as yours begins
    /// (CR 611.2b).
    /// </summary>
    /// <remarks>
    /// Fungi Cavern is the only room in the shipped dungeon that needed anything the engine did
    /// not have. A floating effect knew one duration — the turn it was made in — and reading this
    /// as "until end of turn" would have been a room that does most of nothing: the creature it
    /// shrinks is untapped and attacking again before the opponent's turn is over.
    /// </remarks>
    [Fact]
    public void A_room_that_lasts_until_your_next_turn_survives_the_opponents_turn()
    {
        var (game, alice, bob) = InMainPhase();

        var bear = game.Create(alice, TestCards.Creature("Fungi Bear"), Zone.Battlefield);

        VentureTo(game, alice, "Cave Entrance", "Mine Tunnels", "Fungi Cavern");

        Assert.Equal("Fungi Cavern", game.State.GetPlayer(alice).DungeonRoom);
        Assert.Equal(-2, PowerNow(game, bear));

        // Still shrunk through Bob's whole turn.
        TestCards.PassToTurn(game, game.State.TurnNumber + 1);
        Assert.Equal(bob, game.State.ActivePlayerId);
        Assert.Equal(-2, PowerNow(game, bear));

        // And back to itself as Alice's next turn begins.
        TestCards.PassToTurn(game, game.State.TurnNumber + 1);
        Assert.Equal(alice, game.State.ActivePlayerId);
        Assert.Equal(2, PowerNow(game, bear));
    }

    /// <summary>
    /// The corpus wordings that reach the dungeon compile, in the shapes the cards print them.
    /// </summary>
    /// <remarks>
    /// Every one of these is a real oracle line. They are checked together because the keyword
    /// action arrives on four different kinds of ability — a trigger, an activated ability, a
    /// spell and a condition — and the reason it is one effect sentence rather than four readers
    /// is that <c>EffectPhrase</c> is shared by all of them.
    /// </remarks>
    [Theory]
    [InlineData("When ~ enters, venture into the dungeon.", CardType.Creature)]
    [InlineData("Whenever ~ attacks, venture into the dungeon.", CardType.Creature)]
    [InlineData("When ~ dies, venture into the dungeon.", CardType.Creature)]
    [InlineData("{3}, {T}: Venture into the dungeon. Activate only as a sorcery.", CardType.Artifact)]
    [InlineData("As long as you've completed a dungeon, ~ has double strike.", CardType.Creature)]
    [InlineData(
        "Whenever you complete a dungeon, you may return ~ from your graveyard to your hand.",
        CardType.Creature)]
    public void The_printed_dungeon_wordings_compile(string text, CardType types)
    {
        var card = Card("Delver Test", text, types, power: 2, toughness: 2);
        var compiled = CardCompiler.Compile(card);

        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
    }

    /// <summary>
    /// "Venture into Undercity" reads now that Undercity ships (CR 701.49d) — and only that
    /// name: a venture naming a dungeon the engine does not have is still left unread.
    /// </summary>
    /// <remarks>
    /// This test held the opposite until the initiative round: the line was deliberately
    /// refused while Undercity's bottommost room could not be said, because a pattern loose
    /// enough to admit it would have sent the initiative's cards into Lost Mine of Phandelver —
    /// a different dungeon with different rooms — while looking implemented. The named arm now
    /// exists because the named dungeon does. The second half is the fail-closed property that
    /// survives the flip: the pattern admits Undercity exactly, so a venture naming anything
    /// else still leaves its card unread rather than guessing a dungeon.
    /// </remarks>
    [Fact]
    public void Venturing_into_a_named_dungeon_reads_exactly_when_the_engine_ships_it()
    {
        var read = CardCompiler.Compile(Card(
            "Initiative Test",
            "When ~ enters, venture into Undercity.",
            CardType.Creature,
            2,
            2));

        Assert.True(read.IsComplete, string.Join(" | ", read.Unhandled));

        var unread = CardCompiler.Compile(Card(
            "Mad Mage Test",
            "When ~ enters, venture into Dungeon of the Mad Mage.",
            CardType.Creature,
            2,
            2));

        Assert.False(unread.IsComplete);
        Assert.Contains(
            "Mad Mage",
            string.Join(" | ", unread.Unhandled),
            StringComparison.Ordinal);
    }

    // ---- "This turn" combat requirements, and the durations that hold them ----

    /// <summary>
    /// "{cost}: ~ can block an additional creature this turn" (CR 509.1a, 611.2).
    /// </summary>
    /// <remarks>
    /// The line this file recorded as declined, in those words: the static layer that reads "can
    /// block an additional creature <em>each combat</em>" has nowhere to put a duration, so
    /// reading the "this turn" wording there would have made it permanent. A floating effect is
    /// where a duration lives, so the grant is that same characteristic with an end on it - and
    /// the last assertion is the one that matters, because every other line here would pass just
    /// as well on a reading that handed the creature the allowance for ever.
    /// </remarks>
    [Fact]
    public void An_extra_block_bought_for_the_turn_is_gone_by_the_next_one()
    {
        var guard = Card(
            "Test Coastline Watch",
            "{1}: ~ can block an additional creature this turn.",
            CardType.Creature, 1, 4);

        var compiled = CardCompiler.Compile(guard);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var watch = game.Create(bob, guard, Zone.Battlefield);
        var first = game.Create(alice, TestCards.Creature("Test Watch Raider", 1, 1), Zone.Battlefield);
        var second = game.Create(alice, TestCards.Creature("Test Watch Rider", 1, 1), Zone.Battlefield);

        Assert.Equal(
            0, Characteristics.Of(game.State, Pool, game.State.GetObject(watch)).ExtraBlocks);

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget>
            {
                [first] = AttackTarget.Player(bob),
                [second] = AttackTarget.Player(bob),
            });

        // Blockers are declared as a turn-based action before anybody has priority (CR 509.1),
        // so the declare attackers step is the only window there is to buy the extra block.
        TestCards.PassUntil(game, () => game.State.Priority.Holder == bob);
        game.AddMana(bob, ManaColor.White);
        game.ActivateAbility(bob, watch, compiled.Activated.Single().Id);

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);
        Assert.Equal(
            1, Characteristics.Of(game.State, Pool, game.State.GetObject(watch)).ExtraBlocks);

        game.DeclareBlockers(
            bob,
            new Dictionary<ObjectId, IReadOnlyList<ObjectId>>
            {
                [first] = [watch],
                [second] = [watch],
            });

        Settle(game);

        // Both attackers blocked by the one creature, so nothing reached Bob.
        TestCards.PassUntil(game, () => game.State.TurnNumber >= 4);
        Assert.Equal(20, game.State.GetPlayer(bob).Life);

        // CR 611.2: the grant ended in the cleanup step of the turn it was made in.
        Assert.Equal(
            0, Characteristics.Of(game.State, Pool, game.State.GetObject(watch)).ExtraBlocks);

        Settle(game);
    }

    /// <summary>
    /// The two readings of the same allowance, held apart (CR 509.1a).
    /// </summary>
    /// <remarks>
    /// The control the gain above needs. "Each combat" is a static ability and is on from the
    /// moment the permanent arrives; "this turn" is a one-shot and is off until somebody pays
    /// for it. A single reader claiming both wordings would pass the test above and fail this
    /// one, which is exactly the mistake the original decline refused to make.
    /// </remarks>
    [Fact]
    public void The_each_combat_wording_is_a_static_and_the_this_turn_wording_is_not()
    {
        var standing = Card(
            "Test Hundred Arms",
            "~ can block an additional creature each combat.",
            CardType.Creature, 1, 4);

        var bought = Card(
            "Test Mounted Watch",
            "{W}: ~ can block an additional creature this turn.",
            CardType.Creature, 1, 4);

        Assert.True(CardCompiler.Compile(standing).IsComplete);
        Assert.True(CardCompiler.Compile(bought).IsComplete);

        var (game, alice, _) = InMainPhase();
        var always = game.Create(alice, standing, Zone.Battlefield);
        var never = game.Create(alice, bought, Zone.Battlefield);

        Assert.Equal(
            1, Characteristics.Of(game.State, Pool, game.State.GetObject(always)).ExtraBlocks);

        Assert.Equal(
            0, Characteristics.Of(game.State, Pool, game.State.GetObject(never)).ExtraBlocks);
    }

    /// <summary>
    /// "Target creature must be blocked this turn if able" (CR 509.1c, 611.2).
    /// </summary>
    /// <remarks>
    /// The sibling the same note declined for the same reason. The requirement itself was already
    /// here - a printed "~ must be blocked if able" compiles to a static continuous effect - and
    /// what was missing was a way to say it for one turn. This test is the duration half: the
    /// lure is put on in one turn and is gone by the combat of the next, so a declaration that
    /// ignores it then is legal.
    /// </remarks>
    [Fact]
    public void A_lure_put_on_a_creature_for_the_turn_binds_only_that_turn()
    {
        var prey = Card(
            "Test Irresistible Prey", "Target creature must be blocked this turn if able.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(prey);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, TestCards.Creature("Test Prey Raider", 2, 2), Zone.Battlefield);
        game.Create(bob, TestCards.Creature("Test Prey Guard", 1, 4), Zone.Battlefield);

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, prey), [Target.ToPermanent(attacker)]);

        Settle(game);

        Assert.True(
            Characteristics.Of(game.State, Pool, game.State.GetObject(attacker)).MustBeBlocked);

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);

        // Turn 3 is a different turn from the one the lure was made on, so the requirement is
        // gone and Bob may keep his creature back.
        Assert.False(
            Characteristics.Of(game.State, Pool, game.State.GetObject(attacker)).MustBeBlocked);

        game.DeclareBlockers(bob, new Dictionary<ObjectId, IReadOnlyList<ObjectId>>());
        Settle(game);
    }

    /// <summary>
    /// The lure refuses a declaration that ignores it, on the turn it was made (CR 509.1c).
    /// </summary>
    /// <remarks>
    /// The half the test above cannot reach, and the one that proves the requirement is real
    /// rather than a flag nothing consults. The lure goes on during the declare attackers step
    /// through an activated ability - which is what Satyr Piper prints - so the block that
    /// follows falls inside the turn it covers.
    /// </remarks>
    [Fact]
    public void A_lure_made_this_turn_refuses_a_declaration_that_ignores_it()
    {
        var piper = Card(
            "Test Satyr Piper",
            "{1}: Target creature must be blocked this turn if able.",
            CardType.Creature, 2, 2);

        var compiled = CardCompiler.Compile(piper);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, piper, Zone.Battlefield);
        var attacker = game.Create(alice, TestCards.Creature("Test Piper Raider", 2, 2), Zone.Battlefield);
        game.Create(bob, TestCards.Creature("Test Piper Guard", 1, 4), Zone.Battlefield);

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        var pipe = game.State.Battlefield
            .Single(id => game.State.GetObject(id).Card.Name == "Test Satyr Piper");

        TestCards.PassUntil(game, () => game.State.Priority.Holder == alice);
        game.AddMana(alice, ManaColor.Green);
        game.ActivateAbility(
            alice, pipe, compiled.Activated.Single().Id, [Target.ToPermanent(attacker)]);

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);

        Assert.True(
            Characteristics.Of(game.State, Pool, game.State.GetObject(attacker)).MustBeBlocked);

        var ex = Assert.Throws<InvalidOperationException>(() =>
            game.DeclareBlockers(bob, new Dictionary<ObjectId, IReadOnlyList<ObjectId>>()));

        Assert.Contains("509.1c", ex.Message, StringComparison.Ordinal);
    }

    // ---- A cost that is mana and life (CR 702.34a, 118.8) ---------------------

    /// <summary>
    /// "Flashback&#8212;{1}{U}, Pay 3 life" (CR 702.34a, 118.8, 601.2h).
    /// </summary>
    /// <remarks>
    /// Flashback was built and the life half was not, because the permission had nowhere to put
    /// a price that is neither mana nor a card: <c>AlternativeCastZone.Extra</c> holds chosen
    /// cards and permanents. The life rides on the permission rather than on the spell for the
    /// reason retrace's land discard does - the same card cast from hand pays none of it.
    /// </remarks>
    [Fact]
    public void Flashback_can_charge_mana_and_life_together()
    {
        var analysis = new CardDefinition
        {
            OracleId = "oracle-r11-flashback-life",
            Name = "Test Deep Analysis",
            OracleText = "You gain 3 life.\nFlashback—{1}, Pay 3 life.",
            CardTypes = CardType.Sorcery,
            ManaCostRaw = "{3}{U}",
        };

        var compiled = CardCompiler.Compile(analysis);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var card = game.Create(alice, analysis, Zone.Graveyard);
        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, forest, "mana");

        game.CastSpell(alice, card);
        Settle(game);

        // Three life paid for the cast and three gained by the spell: the two cancel, which is
        // not the reading a dropped life cost would produce.
        Assert.Equal(20, game.State.GetPlayer(alice).Life);
        Assert.Single(game.State.Exile);
    }

    /// <summary>
    /// A player who cannot pay the life is refused, having spent nothing (CR 118.8).
    /// </summary>
    [Fact]
    public void Flashback_refuses_a_life_cost_the_caster_cannot_pay()
    {
        var ruinous = new CardDefinition
        {
            OracleId = "oracle-r11-flashback-life-too-much",
            Name = "Test Ruinous Recall",
            OracleText = "You gain 3 life.\nFlashback—{1}, Pay 25 life.",
            CardTypes = CardType.Sorcery,
            ManaCostRaw = "{3}{U}",
        };

        Assert.True(CardCompiler.Compile(ruinous).IsComplete);

        var (game, alice, _) = InMainPhase();
        var card = game.Create(alice, ruinous, Zone.Graveyard);
        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, forest, "mana");

        var ex = Assert.Throws<InvalidOperationException>(() => game.CastSpell(alice, card));
        Assert.Contains("118.8", ex.Message, StringComparison.Ordinal);

        // Refused before anything was spent: the card is still in the graveyard and the life is
        // untouched.
        Assert.Contains(card, game.State.GetPlayer(alice).Graveyard);
        Assert.Equal(20, game.State.GetPlayer(alice).Life);
    }

    // ---- A delayed counter change (CR 603.7, 122.1) --------------------------

    /// <summary>
    /// "Whenever ~ attacks or blocks, remove a +1/+1 counter from it at end of combat."
    /// </summary>
    /// <remarks>
    /// The Clockwork cycle. The delayed vocabulary could only move a permanent between zones, and
    /// its unrecognised-instruction arm is a <em>sacrifice</em> - so a counter change handed to
    /// it would have destroyed the creature rather than shrinking it. The battlefield assertion
    /// at the end is therefore not decoration: it is what tells a working reading from that one.
    /// </remarks>
    [Fact]
    public void A_counter_removed_at_end_of_combat_shrinks_the_creature_rather_than_killing_it()
    {
        var beetle = Card(
            "Test Clockwork Beetle",
            "This creature enters with two +1/+1 counters on it.\n"
                + "Whenever this creature attacks or blocks, remove a +1/+1 counter from it at "
                + "end of combat.",
            CardType.Creature, 0, 2);

        var compiled = CardCompiler.Compile(beetle);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var clockwork = game.Create(alice, beetle, Zone.Battlefield);

        Assert.Equal(2, game.State.GetObject(clockwork).Permanent!.Counters["+1/+1"]);

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [clockwork] = AttackTarget.Player(bob) });

        // The trigger has fired and set the delay, and nothing has happened yet: the counter goes
        // at end of combat, not when the creature attacks.
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);
        Assert.Equal(2, game.State.GetObject(clockwork).Permanent!.Counters["+1/+1"]);

        TestCards.PassUntil(game, () => game.State.CurrentStep > TurnStep.EndOfCombat);
        Settle(game);

        Assert.Equal(1, game.State.GetObject(clockwork).Permanent!.Counters["+1/+1"]);

        // Still on the battlefield, which is the whole difference between a counter removal and
        // the sacrifice the delayed vocabulary falls back to.
        Assert.Contains(clockwork, game.State.Battlefield);
        Assert.Equal(
            1, Characteristics.Of(game.State, Pool, game.State.GetObject(clockwork)).Power);
    }

    // ---- A cost modifier that asks what the spell is aimed at (CR 601.2c) -----

    /// <summary>
    /// "Spells your opponents cast that target ~ cost {2} more to cast" (CR 601.2c, 601.2f).
    /// </summary>
    /// <remarks>
    /// The condition the cost-modifier grid refused, because the record had nowhere to put it and
    /// the only available reading was the unconditional one - a tax on every spell an opponent
    /// casts. It costs nothing to ask: CR 601.2c chooses targets before CR 601.2f works the cost
    /// out, so the answer is already in hand. Both arms are played, because a modifier that
    /// taxed everything would pass the first assertion on its own.
    /// </remarks>
    [Fact]
    public void A_spell_is_taxed_only_when_it_targets_the_permanent_that_says_so()
    {
        var regent = Card(
            "Test Icefall Regent",
            "Spells your opponents cast that target ~ cost {2} more to cast.",
            CardType.Creature, 4, 5);

        var compiled = CardCompiler.Compile(regent);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var taxed = game.Create(alice, regent, Zone.Battlefield);

        TestCards.PassUntil(
            game,
            () => game.State.ActivePlayerId == bob
                && game.State.CurrentStep == TurnStep.PrecombatMain);

        var bolt = Card("Test Regent Bolt", "~ deals 3 damage to any target.");
        var atRegent = TestCards.PutInHand(game, bob, bolt);
        var atAlice = TestCards.PutInHand(game, bob, bolt);

        game.AddMana(bob, ManaColor.Red);

        // One mana buys a bolt aimed at anything except the creature that taxes it.
        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(bob, atRegent, [Target.ToPermanent(taxed)]));

        game.CastSpell(bob, atAlice, [Target.ToPlayer(alice)]);
        Settle(game);

        Assert.Equal(17, game.State.GetPlayer(alice).Life);

        // And with the tax paid the same spell reaches the same creature: it is a price, not a
        // prohibition.
        TestCards.PassUntil(
            game,
            () => game.State.ActivePlayerId == bob
                && game.State.CurrentStep == TurnStep.PrecombatMain
                && game.State.TurnNumber >= 4);

        // Put in hand after the turn has passed: a card sitting through a cleanup can be
        // discarded to hand size, and then there is no card to cast.
        var second = TestCards.PutInHand(game, bob, bolt);

        game.AddMana(bob, ManaColor.Red, 3);
        game.CastSpell(bob, second, [Target.ToPermanent(taxed)]);
        Settle(game);

        Assert.Equal(3, game.State.GetObject(taxed).Permanent!.DamageMarked);
    }

    // ---- Any number of targets, and strive (CR 601.2c, 702.122a) -------------

    /// <summary>
    /// A spell whose caster chooses how many things it targets (CR 601.2c).
    /// </summary>
    /// <remarks>
    /// The shape a fixed list of specs could not hold, and the reason the strive cycle and the
    /// whole "any number of target ..." family had been declined: an unbounded target list has no
    /// length to write down. It needs no ceiling. CR 601.2c has the player announce how many
    /// targets they will choose before choosing them, and the announcement is the list the caster
    /// hands over - so the definition keeps one spec and the cast counts it out.
    /// <para>
    /// Played rather than parsed, and played at more than two: two targets would not tell a block
    /// apart from the "up to two target creatures" the engine could already read.
    /// </para>
    /// </remarks>
    [Fact]
    public void Any_number_of_target_players_is_as_many_as_the_caster_chose()
    {
        var feast = new CardDefinition
        {
            OracleId = "oracle-block-hunters-feast",
            Name = "Hunters Feast Test",
            OracleText = "Any number of target players each gain 6 life.",
            CardTypes = CardType.Sorcery,
            ManaCostRaw = "{3}{G}",
            Cmc = 4,
        };

        var compiled = CardCompiler.Compile(feast);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        // One spec for the block, not one per player at the table: the count is not in the card.
        Assert.Single(compiled.Spell!.Targets);
        Assert.True(compiled.Spell.Targets[0].AnyNumber);

        var (game, alice, bob) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, feast);

        game.AddMana(alice, ManaColor.Green, 4);
        game.CastSpell(alice, card, [Target.ToPlayer(alice), Target.ToPlayer(bob)]);
        Settle(game);

        Assert.Equal(26, game.State.GetPlayer(alice).Life);
        Assert.Equal(26, game.State.GetPlayer(bob).Life);
    }

    /// <summary>
    /// Strive charges for each target after the first, against the number announced
    /// (CR 601.2f, 702.122a).
    /// </summary>
    /// <remarks>
    /// The half that was correctly refused on its own. "This spell costs {2}{W} more to cast for
    /// each target beyond the first" reads as a line, but a price on targets the engine could not
    /// let a player choose would have moved a line and finished no card - so it is built here, on
    /// top of the block, and proved by paying it.
    /// <para>
    /// Three casts, because a tax that charged nothing would pass one of them and a tax that
    /// charged always would pass another: one target for the printed {W}, three for {W} and two
    /// strives, and a third refused for being one mana short of those same three.
    /// </para>
    /// </remarks>
    [Fact]
    public void Strive_charges_for_the_second_and_third_target_and_refuses_a_short_pool()
    {
        var presence = new CardDefinition
        {
            OracleId = "oracle-strive-ajanis-presence",
            Name = "Ajanis Presence Test",
            OracleText =
                "Strive — This spell costs {2}{W} more to cast for each target beyond "
                + "the "
                + "first.\nAny number of target creatures each get +1/+1 and gain indestructible "
                + "until end of turn.",
            CardTypes = CardType.Instant,
            ManaCostRaw = "{W}",
            Cmc = 1,
        };

        var compiled = CardCompiler.Compile(presence);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.NotNull(compiled.Spell!.StriveCost);

        var bear = Card("Strive Bear Test", string.Empty, CardType.Creature, 2, 2);

        var (game, alice, _) = InMainPhase();
        var first = game.Create(alice, bear, Zone.Battlefield);
        var second = game.Create(alice, bear, Zone.Battlefield);
        var third = game.Create(alice, bear, Zone.Battlefield);

        // One target is the printed cost and nothing more.
        var alone = TestCards.PutInHand(game, alice, presence);
        game.AddMana(alice, ManaColor.White);
        game.CastSpell(alice, alone, [Target.ToPermanent(first)]);
        Settle(game);

        Assert.Equal(3, Characteristics.Of(game.State, Pool, game.State.GetObject(first)).Power);

        // Three targets is {W} and two strive costs - {2}{W} twice over - so seven mana in all.
        // Six is one short, and being short refuses the whole cast (CR 601.2h): the card is still
        // in hand, having never been cast at all.
        var striving = TestCards.PutInHand(game, alice, presence);
        game.AddMana(alice, ManaColor.White, 6);

        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(
                alice,
                striving,
                [
                    Target.ToPermanent(first),
                    Target.ToPermanent(second),
                    Target.ToPermanent(third),
                ]));

        Assert.Contains(striving, game.State.GetPlayer(alice).Hand);

        // The seventh mana buys the same three targets, and every one of them is pumped: an
        // effect that ran once would leave two of the bears standing at 2/2.
        game.AddMana(alice, ManaColor.White);
        game.CastSpell(
            alice,
            striving,
            [Target.ToPermanent(first), Target.ToPermanent(second), Target.ToPermanent(third)]);

        Settle(game);

        Assert.Equal(4, Characteristics.Of(game.State, Pool, game.State.GetObject(first)).Power);
        Assert.Equal(3, Characteristics.Of(game.State, Pool, game.State.GetObject(second)).Power);
        Assert.Equal(3, Characteristics.Of(game.State, Pool, game.State.GetObject(third)).Power);

        Assert.True(
            Characteristics.Of(game.State, Pool, game.State.GetObject(third))
                .Has(KeywordAbility.Indestructible));
    }

    /// <summary>
    /// "Any number" includes none, and the rules say so outright (CR 601.2c).
    /// </summary>
    /// <remarks>
    /// The comprehensive rules give this as their own example under CR 601.2c: Loaming Shaman's
    /// ability resolves with "no cards are targeted". So an empty block is a legal announcement
    /// rather than a refusal - and such a spell can never fizzle for having no legal target,
    /// because it never had one.
    /// <para>
    /// It settles the price as well as the permission: a strive spell cast for none of its
    /// targets costs what it prints, since there is no target beyond the first when there is no
    /// first.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_block_may_be_left_empty_and_the_spell_then_costs_what_it_prints()
    {
        var presence = new CardDefinition
        {
            OracleId = "oracle-strive-empty-block",
            Name = "Empty Strive Test",
            OracleText =
                "Strive — This spell costs {2}{W} more to cast for each target beyond "
                + "the "
                + "first.\nAny number of target creatures each get +1/+1 and gain indestructible "
                + "until end of turn.",
            CardTypes = CardType.Instant,
            ManaCostRaw = "{W}",
            Cmc = 1,
        };

        Assert.True(CardCompiler.Compile(presence).IsComplete);

        var (game, alice, _) = InMainPhase();
        var bear = game.Create(
            alice,
            Card("Untouched Bear Test", string.Empty, CardType.Creature, 2, 2),
            Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, presence);
        game.AddMana(alice, ManaColor.White);
        game.CastSpell(alice, card, []);
        Settle(game);

        // It resolved rather than fizzling, and touched nothing. The card is looked for by
        // name and not by id: a spell that leaves the stack is a new object (CR 400.7).
        Assert.Equal(2, Characteristics.Of(game.State, Pool, game.State.GetObject(bear)).Power);
        Assert.Contains(
            game.State.Objects.Values,
            o => o.Zone == Zone.Graveyard && o.Card.Name == presence.Name);

        Assert.Empty(game.State.Stack);
    }

    /// <summary>
    /// A block that is not the spell's last target is left unread (CR 601.2c).
    /// </summary>
    /// <remarks>
    /// Everything downstream of a target list reads it by position - the effects' indices, the
    /// slices modes and spliced text take - so a block that grew in the middle would move every
    /// index after it and aim one sentence's effect at another sentence's creature. The compiler
    /// refuses to keep one there, and the coverage figure carries the debt where it can be seen.
    /// <para>
    /// Asserted from both sides, because "does not compile" is a claim a typo would satisfy: the
    /// same sentence on its own reads in full.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_block_followed_by_another_target_is_left_unread()
    {
        var twice = Card(
            "Filigree Vector Test",
            "Any number of target creatures get +1/+1 until end of turn.\n"
                + "Any number of target creatures gain flying until end of turn.");

        Assert.False(CardCompiler.Compile(twice).IsComplete);

        var once = Card(
            "Filigree Vector Half Test",
            "Any number of target creatures get +1/+1 until end of turn.");

        var compiled = CardCompiler.Compile(once);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
    }

    /// <summary>
    /// A target lost from the block costs that share and no other (CR 608.2b).
    /// </summary>
    /// <remarks>
    /// The reason the expanded copies are required specs rather than optional ones. Each of them
    /// is a target in its own right, so each is checked again on resolution and each fails on its
    /// own: CR 608.2b only stops the spell entirely when <em>every</em> target has become illegal.
    /// A block that behaved as one target would either lose all three pumps to one dead creature
    /// or keep all three, and both are a different card.
    /// <para>
    /// The middle creature is the one removed, deliberately - a block that dropped its tail on the
    /// first loss would pass this with the last one taken instead.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_target_lost_from_the_block_costs_only_its_own_share()
    {
        var presence = new CardDefinition
        {
            OracleId = "oracle-strive-partial-fizzle",
            Name = "Partial Strive Test",
            OracleText =
                "Strive — This spell costs {2}{W} more to cast for each target beyond "
                + "the first.\nAny number of target creatures each get +1/+1 and gain "
                + "indestructible until end of turn.",
            CardTypes = CardType.Instant,
            ManaCostRaw = "{W}",
            Cmc = 1,
        };

        Assert.True(CardCompiler.Compile(presence).IsComplete);

        var bear = Card("Doomed Bear Test", string.Empty, CardType.Creature, 2, 2);

        var (game, alice, _) = InMainPhase();
        var first = game.Create(alice, bear, Zone.Battlefield);
        var second = game.Create(alice, bear, Zone.Battlefield);
        var third = game.Create(alice, bear, Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, presence);
        game.AddMana(alice, ManaColor.White, 7);
        game.CastSpell(
            alice,
            card,
            [Target.ToPermanent(first), Target.ToPermanent(second), Target.ToPermanent(third)]);

        // Killed while the spell is still on the stack, so the indestructible it was about to
        // gain arrives too late to save it.
        game.Move(second, Zone.Graveyard, MoveCause.Destroy);
        Settle(game);

        // The spell resolved: one illegal target out of three is not "all of them" (CR 608.2b).
        Assert.Equal(3, Characteristics.Of(game.State, Pool, game.State.GetObject(first)).Power);
        Assert.Equal(3, Characteristics.Of(game.State, Pool, game.State.GetObject(third)).Power);
        Assert.DoesNotContain(second, game.State.Battlefield);
    }

    // ---- Beginning the game with a card on the battlefield (CR 103.6) --------

    /// <summary>The Leyline, exactly as nineteen of them are printed.</summary>
    private static CardDefinition LeylineCard(string name) => new()
    {
        OracleId = "oracle-" + name.ToLowerInvariant().Replace(' ', '-'),
        Name = name,
        ManaCostRaw = "{2}{G}{G}",
        Cmc = 4,
        CardTypes = CardType.Enchantment,
        OracleText =
            "If this card is in your opening hand, you may begin the game with it on the "
            + "battlefield.\nCreatures you control get +0/+1.",
    };

    /// <summary>A game about to ask the opening-hand question, with one deck full of Leylines.</summary>
    /// <remarks>
    /// The whole deck rather than one copy salted into it, because the question is only asked of
    /// a hand that holds one and a shuffle decides what a hand holds. A test that depends on a
    /// seed dealing the right card is a test that starts failing when an unrelated shuffle
    /// changes.
    /// </remarks>
    private static (Game Game, Guid Alice, Guid Bob) DealtLeylines(CardDefinition leyline)
    {
        var alice = Guid.Parse("11111111-1111-1111-1111-111111111111");
        var bob = Guid.Parse("22222222-2222-2222-2222-222222222222");

        var game = Game.Start(
            Guid.NewGuid(),
            [
                new PlayerSetup(alice, "Alice", 20, [.. Enumerable.Repeat(leyline, 40)]),
                new PlayerSetup(bob, "Bob", 20, TestCards.Deck(40, "Bob")),
            ],
            new GameRandom(1),
            startingPlayerId: alice,
            abilities: Pool);

        game.BeginPlay(withMulligans: false);
        return (game, alice, bob);
    }

    /// <summary>
    /// A Leyline kept in the opening hand is on the battlefield before turn one (CR 103.6a).
    /// </summary>
    /// <remarks>
    /// The rule the whole family turns on, and the reason the line could not be filed under
    /// deck-construction text: "the player taking this action puts that card onto the
    /// battlefield", and the battlefield it arrives on is the one the first turn begins with.
    /// <para>
    /// Asserted against the log's own ordering rather than against the board at the end. A
    /// permanent that reached the battlefield at any point in turn one would satisfy "it is on
    /// the battlefield now"; only the position of the move relative to the first turn beginning
    /// says it was there <em>before the game started</em>, which is the whole of what the card
    /// promises.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_leyline_kept_in_hand_begins_the_game_on_the_battlefield()
    {
        var leyline = LeylineCard("Leyline Of Testing");
        var compiled = CardCompiler.Compile(leyline);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.True(compiled.MayBeginOnBattlefield);

        var (game, alice, _) = DealtLeylines(leyline);

        // CR 103.6: the starting player is asked first, and the game has not begun.
        Assert.Equal(ChoiceKind.OpeningHandBattlefield, game.State.Choice!.Kind);
        Assert.Equal(alice, game.State.Choice.PlayerId);
        Assert.Equal(0, game.State.Choice.MinPicks);
        Assert.Equal(7, game.State.Choice.Options.Count);
        Assert.False(game.State.HasBegun);

        game.Choose(alice, [game.State.Choice.Options[0].Id]);

        // It is on the battlefield, it belongs to Alice, and the first turn has begun.
        var permanent = Assert.Single(
            game.State.Battlefield.Select(game.State.GetObject),
            o => o.Card.Name == leyline.Name);

        Assert.Equal(alice, permanent.ControllerId);
        Assert.Equal(1, game.State.TurnNumber);
        Assert.Equal(6, game.State.GetPlayer(alice).Hand.Count);

        // And it arrived before the first turn did, which is the claim the card makes.
        var arrived = game.Log
            .Select((e, i) => (Event: e, Index: i))
            .First(pair => pair.Event is ObjectMoved { To: Zone.Battlefield })
            .Index;

        var began = game.Log
            .Select((e, i) => (Event: e, Index: i))
            .First(pair => pair.Event is TurnBegan)
            .Index;

        Assert.True(began > arrived, $"arrived at {arrived}, turn began at {began}");

        Assert.Equal(game.State, GameReducer.Replay(game.Log));
    }

    /// <summary>Declining leaves it in hand, and the game starts anyway (CR 103.6).</summary>
    /// <remarks>
    /// "May", so nothing is as good an answer as anything else — which is why the choice has no
    /// minimum. A yes/no followed by a selection would let a player answer yes and then have to
    /// name a card, and would give the log two answers where the rules have one decision.
    /// </remarks>
    [Fact]
    public void Declining_the_offer_leaves_the_leyline_in_hand()
    {
        var leyline = LeylineCard("Leyline Of Declining");
        var (game, alice, _) = DealtLeylines(leyline);

        game.Choose(alice, []);

        Assert.Empty(game.State.Battlefield);
        Assert.Equal(7, game.State.GetPlayer(alice).Hand.Count);
        Assert.Equal(1, game.State.TurnNumber);
        Assert.Equal(game.State, GameReducer.Replay(game.Log));
    }

    /// <summary>
    /// A hand with nothing to offer is not asked, and the game starts (CR 118.3's lesson).
    /// </summary>
    /// <remarks>
    /// The negative control for the whole step. Bob holds forty vanilla creatures and is never
    /// stopped for a question; if the step asked everybody, a two-player game would halt twice
    /// before its first untap and every existing test that starts a game would hang.
    /// </remarks>
    [Fact]
    public void A_player_with_no_such_card_is_never_asked()
    {
        var (game, alice, bob) = TestCards.TwoPlayer(40);
        game.BeginPlay(withMulligans: false);

        Assert.Null(game.State.Choice);
        Assert.Equal(1, game.State.TurnNumber);
        Assert.Contains(alice, game.State.OpeningHandActed);
        Assert.Contains(bob, game.State.OpeningHandActed);
    }

    /// <summary>
    /// Each player is offered in turn order, starting with the player who goes first (CR 103.6).
    /// </summary>
    /// <remarks>
    /// The order is the rule rather than a detail: what a Leyline is worth depends on what is
    /// already on the table when the offer reaches you, and the starting player answers first
    /// however the seats are numbered.
    /// </remarks>
    [Fact]
    public void Every_player_is_offered_in_turn_order()
    {
        var leyline = LeylineCard("Leyline Of Turn Order");
        var alice = Guid.Parse("11111111-1111-1111-1111-111111111111");
        var bob = Guid.Parse("22222222-2222-2222-2222-222222222222");

        var game = Game.Start(
            Guid.NewGuid(),
            [
                new PlayerSetup(alice, "Alice", 20, [.. Enumerable.Repeat(leyline, 40)]),
                new PlayerSetup(bob, "Bob", 20, [.. Enumerable.Repeat(leyline, 40)]),
            ],
            new GameRandom(1),
            startingPlayerId: bob,
            abilities: Pool);

        game.BeginPlay(withMulligans: false);

        // Bob starts, so Bob is asked first even though Alice is seated first.
        Assert.Equal(bob, game.State.Choice!.PlayerId);
        game.Choose(bob, [game.State.Choice.Options[0].Id]);

        Assert.Equal(alice, game.State.Choice!.PlayerId);
        game.Choose(alice, [game.State.Choice.Options[0].Id]);

        Assert.Equal(2, game.State.Battlefield.Count);
        Assert.Equal(1, game.State.TurnNumber);
        Assert.Equal(game.State, GameReducer.Replay(game.Log));
    }

    /// <summary>The step survives the mulligan procedure it follows (CR 103.5, 103.6).</summary>
    /// <remarks>
    /// "Once the mulligan process is complete" — so the question comes after the bottoming, not
    /// before it, and a hand that has just been reduced is the hand the offer is made from.
    /// </remarks>
    [Fact]
    public void The_offer_comes_after_the_mulligans()
    {
        var leyline = LeylineCard("Leyline Of Mulligans");
        var alice = Guid.Parse("11111111-1111-1111-1111-111111111111");
        var bob = Guid.Parse("22222222-2222-2222-2222-222222222222");

        var game = Game.Start(
            Guid.NewGuid(),
            [
                new PlayerSetup(alice, "Alice", 20, [.. Enumerable.Repeat(leyline, 40)]),
                new PlayerSetup(bob, "Bob", 20, TestCards.Deck(40, "Bob")),
            ],
            new GameRandom(1),
            startingPlayerId: alice,
            abilities: Pool);

        game.BeginPlay();

        // Alice mulligans once and keeps; Bob keeps.
        game.Choose(alice, ["mulligan"]);
        game.Choose(bob, ["keep"]);
        game.Choose(alice, ["keep"]);

        // The bottoming question comes first (CR 103.5), and only then the opening-hand offer.
        Assert.Equal(ChoiceKind.BottomAfterMulligan, game.State.Choice!.Kind);
        game.Choose(alice, [game.State.Choice.Options[0].Id]);

        Assert.Equal(ChoiceKind.OpeningHandBattlefield, game.State.Choice!.Kind);
        Assert.Equal(6, game.State.Choice.Options.Count);

        game.Choose(alice, [game.State.Choice.Options[0].Id]);

        Assert.Single(game.State.Battlefield);
        Assert.Equal(1, game.State.TurnNumber);
        Assert.Equal(game.State, GameReducer.Replay(game.Log));
    }

    // ---- Pacts: a delayed payment that ends the game (CR 603.7, 104.3e) ------

    /// <summary>Pact of the Titan, printed word for word.</summary>
    /// <remarks>
    /// The token half is deliberately kept: the whole point of a pact is that it does something
    /// now and charges for it later, and a test on the payment alone would pass just as well
    /// against a card that had quietly lost its first line.
    /// </remarks>
    private static CardDefinition PactCard(string name) => new()
    {
        OracleId = "oracle-" + name.ToLowerInvariant().Replace(' ', '-'),
        Name = name,
        ManaCostRaw = "{0}",
        Cmc = 0,
        CardTypes = CardType.Instant,
        OracleText =
            "Create a 4/4 red Giant creature token.\n"
            + "At the beginning of your next upkeep, pay {4}{R}. If you don't, you lose the game.",
    };

    /// <summary>Casts a pact on turn one and walks the game to its caster's next upkeep.</summary>
    private static (Game Game, Guid Alice, Guid Bob) PactCastAndWaiting(CardDefinition pact)
    {
        var (game, alice, bob) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, pact);

        game.CastSpell(alice, card, []);
        Settle(game);

        // The token arrived, so the spell resolved rather than being read as the payment alone.
        Assert.Contains(
            game.State.Battlefield.Select(game.State.GetObject),
            o => o.Card.Name == "Giant");

        // The promise is waiting, and it is waiting for a turn of Alice's.
        var owed = Assert.Single(game.State.Delayed);
        Assert.Equal(alice, owed.ControllerId);
        Assert.Equal(TurnStep.Upkeep, owed.Step);

        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber == 3 && game.State.CurrentStep == TurnStep.Upkeep);

        return (game, alice, bob);
    }

    /// <summary>
    /// A pact that goes unpaid loses its caster the game (CR 104.3e).
    /// </summary>
    /// <remarks>
    /// The half the card is named for, and the reason the line could not compile as a payment
    /// with the tail dropped: a pact read without its consequence is a free spell, which is a
    /// different and much better card than the one printed.
    /// <para>
    /// Alice is given the mana first, so that she is actually <em>asked</em> and answers no. The
    /// case where she has nothing is its own test below, and the two are not the same event: one
    /// is a decision and the other is CR 118.3.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_pact_left_unpaid_loses_the_game()
    {
        var pact = PactCard("Pact Of Testing");
        var compiled = CardCompiler.Compile(pact);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = PactCastAndWaiting(pact);

        // The delayed ability is on the stack, which is what gives Alice a window to find the
        // mana at all — a payment asked at the moment the step began would be one nobody could
        // ever make, because pools empty between steps (CR 500.4).
        Assert.Single(game.State.Stack);

        game.AddMana(alice, ManaColor.Red);
        game.AddMana(alice, null, 4);

        TestCards.PassUntil(
            game,
            () => game.State.Choice is { Kind: ChoiceKind.OptionalPayment });

        Assert.Equal(alice, game.State.Choice!.PlayerId);
        game.Choose(alice, ["no"]);
        Run(game);

        Assert.True(game.State.GetPlayer(alice).HasLost);
        Assert.False(game.State.GetPlayer(bob).HasLost);
        Assert.Equal(game.State, GameReducer.Replay(game.Log));
    }

    /// <summary>Paying it keeps the caster in the game, and costs the mana (CR 601.2h).</summary>
    [Fact]
    public void A_pact_that_is_paid_costs_the_mana_and_nothing_else()
    {
        var pact = PactCard("Pact Of Paying");
        var (game, alice, _) = PactCastAndWaiting(pact);

        game.AddMana(alice, ManaColor.Red);
        game.AddMana(alice, null, 4);

        TestCards.PassUntil(
            game,
            () => game.State.Choice is { Kind: ChoiceKind.OptionalPayment });

        game.Choose(alice, ["yes"]);
        Run(game);

        Assert.False(game.State.GetPlayer(alice).HasLost);
        Assert.True(game.State.GetPlayer(alice).ManaPool.IsEmpty);
        Assert.Equal(game.State, GameReducer.Replay(game.Log));
    }

    /// <summary>
    /// A caster who cannot pay is not asked; the else branch simply runs (CR 118.3).
    /// </summary>
    /// <remarks>
    /// "A player can't pay a cost without having the necessary resources to pay it fully", so
    /// there is nothing to decide and no question to stop the game with. The engine already
    /// answered this for every optional payment; the pact is where the answer is worth the most,
    /// because the alternative — offering a button whose only outcome is losing — is a question
    /// with one possible answer.
    /// </remarks>
    [Fact]
    public void A_caster_who_cannot_pay_is_never_asked()
    {
        var pact = PactCard("Pact Of Poverty Test");
        var (game, alice, _) = PactCastAndWaiting(pact);

        // No mana added: Alice's pool is empty, as it is at the start of every step.
        Run(game);

        Assert.True(game.State.GetPlayer(alice).HasLost);
        Assert.DoesNotContain(
            game.Log,
            e => e is ChoiceRequested { Choice.Kind: ChoiceKind.OptionalPayment });

        Assert.Equal(game.State, GameReducer.Replay(game.Log));
    }

    /// <summary>
    /// It waits for the caster's own upkeep, not the next one in the game (CR 603.7).
    /// </summary>
    /// <remarks>
    /// The rule the whole shape turns on, and the one a step-only delayed trigger cannot express.
    /// A pact cast on turn one comes due on turn three; if it fired on turn two's upkeep it would
    /// demand payment a turn early and, because nobody can pay on an opponent's turn any more
    /// than on their own empty pool, would kill its caster every time.
    /// </remarks>
    [Fact]
    public void A_pact_does_not_come_due_on_the_opponents_upkeep()
    {
        var pact = PactCard("Pact Of Patience Test");
        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, pact);

        game.CastSpell(alice, card, []);
        Settle(game);

        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber == 2 && game.State.CurrentStep == TurnStep.Draw);

        // Bob's upkeep came and went with the promise untouched, and Alice is still playing.
        Assert.False(game.State.GetPlayer(alice).HasLost);
        Assert.Single(game.State.Delayed);
        Assert.Empty(game.State.Stack);
        Assert.Equal(game.State, GameReducer.Replay(game.Log));
    }

    // ---- A limit on how many spells a turn holds (CR 601.3) ------------------

    /// <summary>A spell that needs nothing and does nothing, for counting casts.</summary>
    private static CardDefinition LimitFiller(string name) =>
        Card(name, "Draw a card.");

    /// <summary>
    /// A second spell in a turn is refused, and refused to the enchantment's own side (CR 601.3).
    /// </summary>
    /// <remarks>
    /// Rule of Law's printed line, and five corpus cards share it word for word. The engine had
    /// no way to say it: <c>CastOnlyWhen</c> is a restriction a card prints about <em>itself</em>,
    /// so nothing on the board could prohibit anything, and CR 601.3's second clause — "no rule or
    /// effect prohibits that player from casting it" — had no implementation at all.
    /// <para>
    /// Both halves are asserted because "each player" is the half that is easy to get wrong: a
    /// missing subject read as "you control" is the 83-card defect this suite already records one
    /// layer over, and here it would leave the enchantment's controller free to combo out under
    /// their own Rule of Law.
    /// </para>
    /// <para>
    /// Nothing is resolved in between. The tally moves when a spell is <em>cast</em> (CR 601.2i),
    /// not when it resolves, so the second refusal lands while the first spell is still on the
    /// stack — which is also the position the card is played from.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_cast_limit_refuses_a_second_spell_from_either_player()
    {
        var law = Card(
            "Rule Of Law Test",
            "Each player can't cast more than one spell each turn.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(law);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var limit = Assert.Single(compiled.CastLimits);
        Assert.Equal(1, limit.Max);
        Assert.Equal(PlayerScope.EachPlayer, limit.Who);

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, law, Zone.Battlefield);

        var filler = LimitFiller("Cast Limit Filler Test");
        var aliceFirst = TestCards.PutInHand(game, alice, filler);
        var aliceSecond = TestCards.PutInHand(game, alice, filler);
        var bobFirst = TestCards.PutInHand(game, bob, filler);
        var bobSecond = TestCards.PutInHand(game, bob, filler);

        game.CastSpell(alice, aliceFirst, []);

        var refusedAlice = Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, aliceSecond, []));

        Assert.Contains("Rule Of Law Test", refusedAlice.Message, StringComparison.Ordinal);
        Assert.Contains(aliceSecond, game.State.GetPlayer(alice).Hand);

        // And the opponent, who controls nothing: "each player" is everyone at the table.
        game.PassPriority(alice);
        game.CastSpell(bob, bobFirst, []);

        Assert.Throws<InvalidOperationException>(() => game.CastSpell(bob, bobSecond, []));
        Assert.Contains(bobSecond, game.State.GetPlayer(bob).Hand);
    }

    /// <summary>
    /// A limit that names a kind neither stops nor counts the other kind (CR 601.3).
    /// </summary>
    /// <remarks>
    /// Deafening Silence, and the qualifier is one word doing two jobs: a creature spell is not
    /// refused by it, and casting one does not use up the turn's noncreature spell. Reading the
    /// adjective on only one of the two halves gives a card that is wrong in one direction or the
    /// other — either a Silence that stops everything after the first creature, or one a creature
    /// slips past twice.
    /// </remarks>
    [Fact]
    public void A_cast_limit_that_names_a_kind_leaves_the_other_kind_alone()
    {
        var silence = Card(
            "Deafening Silence Test",
            "Each player can't cast more than one noncreature spell each turn.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(silence);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.Equal(CardType.Creature, Assert.Single(compiled.CastLimits).ExceptTypes);

        var (game, alice, _) = InMainPhase();
        game.Create(alice, silence, Zone.Battlefield);

        var bear = Card("Silence Bear Test", string.Empty, CardType.Creature, 2, 2);
        var filler = LimitFiller("Silence Filler Test");

        var firstBear = TestCards.PutInHand(game, alice, bear);
        var secondBear = TestCards.PutInHand(game, alice, bear);
        var firstFiller = TestCards.PutInHand(game, alice, filler);
        var secondFiller = TestCards.PutInHand(game, alice, filler);

        // Two creature spells: neither is limited, and neither counts. They resolve one at a
        // time because a creature spell wants an empty stack (CR 505.6a), which is a timing rule
        // and nothing to do with the limit under test.
        game.CastSpell(alice, firstBear, []);
        Settle(game);
        game.CastSpell(alice, secondBear, []);
        Settle(game);

        game.CastSpell(alice, firstFiller, []);

        Assert.Throws<InvalidOperationException>(() => game.CastSpell(alice, secondFiller, []));
        Assert.Contains(secondFiller, game.State.GetPlayer(alice).Hand);
    }

    /// <summary>
    /// "You can't cast" limits its controller and nobody else (CR 601.3).
    /// </summary>
    /// <remarks>
    /// Moderation, which is the same sentence with the subject changed — and the negative control
    /// for the reader, because a scope that always meant "each player" would pass every other
    /// test in this section.
    /// </remarks>
    [Fact]
    public void A_cast_limit_on_you_alone_leaves_the_opponent_free()
    {
        var moderation = Card(
            "Moderation Test",
            "You can't cast more than one spell each turn.\n"
                + "Whenever you cast a spell, draw a card.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(moderation);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.Equal(PlayerScope.You, Assert.Single(compiled.CastLimits).Who);

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, moderation, Zone.Battlefield);

        var filler = LimitFiller("Moderation Filler Test");
        var aliceFirst = TestCards.PutInHand(game, alice, filler);
        var aliceSecond = TestCards.PutInHand(game, alice, filler);
        var bobFirst = TestCards.PutInHand(game, bob, filler);
        var bobSecond = TestCards.PutInHand(game, bob, filler);

        game.CastSpell(alice, aliceFirst, []);
        Assert.Throws<InvalidOperationException>(() => game.CastSpell(alice, aliceSecond, []));

        // Bob controls nothing that says this, and casts as many as he likes.
        game.PassPriority(alice);
        game.CastSpell(bob, bobFirst, []);
        game.CastSpell(bob, bobSecond, []);

        Assert.DoesNotContain(bobFirst, game.State.GetPlayer(bob).Hand);
        Assert.DoesNotContain(bobSecond, game.State.GetPlayer(bob).Hand);
        Assert.Contains(aliceSecond, game.State.GetPlayer(alice).Hand);
    }

    /// <summary>
    /// A Curse limits the player it is attached to, not its controller (CR 303.4b, 601.3).
    /// </summary>
    /// <remarks>
    /// Curse of Exhaustion, the ninth card in this family and the one that needs a scope no other
    /// spell restriction in the engine has. The Curse's own controller is deliberately shown
    /// casting twice under it: an Aura on a player says nothing whatever about the player holding
    /// it, and reading "enchanted player" as "you" would turn a Curse into a Moderation.
    /// </remarks>
    [Fact]
    public void A_curse_limits_the_player_it_is_attached_to()
    {
        var curse = Card(
            "Curse Of Exhaustion Test",
            "Enchant player\nEnchanted player can't cast more than one spell each turn.",
            CardType.Enchantment,
            subtypes: "Aura");

        var compiled = CardCompiler.Compile(curse);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.Equal(PlayerScope.EnchantedPlayer, Assert.Single(compiled.CastLimits).Who);

        var (game, alice, bob) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, curse);
        game.CastSpell(alice, card, [Target.ToPlayer(bob)]);
        Settle(game);

        // Bob's turn, so nobody's tally carries over from the turn the Curse was cast on.
        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber == 2 && game.State.CurrentStep == TurnStep.PrecombatMain);

        var filler = LimitFiller("Curse Filler Test");
        var bobFirst = TestCards.PutInHand(game, bob, filler);
        var bobSecond = TestCards.PutInHand(game, bob, filler);
        var aliceFirst = TestCards.PutInHand(game, alice, filler);
        var aliceSecond = TestCards.PutInHand(game, alice, filler);

        game.CastSpell(bob, bobFirst, []);
        Assert.Throws<InvalidOperationException>(() => game.CastSpell(bob, bobSecond, []));

        // The Curse's controller is not the enchanted player and is not limited.
        game.PassPriority(bob);
        game.CastSpell(alice, aliceFirst, []);
        game.CastSpell(alice, aliceSecond, []);

        Assert.Contains(bobSecond, game.State.GetPlayer(bob).Hand);
    }

    /// <summary>
    /// The allowance is per turn, and a new turn is a new allowance (CR 601.3).
    /// </summary>
    /// <remarks>
    /// The half a static field would get wrong. The count it reads is
    /// <c>PlayerState.SpellsCastThisTurn</c>, which the reducer already clears as each turn
    /// begins — so this needed no new state and, more to the point, no second place that has to
    /// remember to clear it.
    /// </remarks>
    [Fact]
    public void A_cast_limit_starts_over_each_turn()
    {
        var law = Card(
            "Renewing Law Test",
            "Each player can't cast more than one spell each turn.",
            CardType.Enchantment);

        var (game, alice, _) = InMainPhase();
        game.Create(alice, law, Zone.Battlefield);

        var filler = LimitFiller("Renewing Filler Test");
        var first = TestCards.PutInHand(game, alice, filler);
        var second = TestCards.PutInHand(game, alice, filler);

        game.CastSpell(alice, first, []);
        Assert.Throws<InvalidOperationException>(() => game.CastSpell(alice, second, []));

        Settle(game);
        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber == 3 && game.State.CurrentStep == TurnStep.PrecombatMain);

        // A fresh card, because the harness discards to hand size at every cleanup it passes
        // through and the one held over may not be the card it was (CR 514.1, 400.7).
        var afterwards = TestCards.PutInHand(game, alice, filler);

        game.CastSpell(alice, afterwards, []);
        Assert.DoesNotContain(afterwards, game.State.GetPlayer(alice).Hand);
    }

    /// <summary>
    /// A qualifier the reader cannot understand leaves the line unread (CR 601.3).
    /// </summary>
    /// <remarks>
    /// Phyrexian Censor is the one corpus card whose qualifier is a subtype rather than a card
    /// type — "non-Phyrexian" with the hyphen the printing uses — and the pair below is the whole
    /// argument for reading the hyphen rather than guessing: one of these is a limit on a card
    /// type and the other on a creature type, and a reader that took them for the same thing
    /// would build a limit matching no card while reporting the card understood.
    /// </remarks>
    [Fact]
    public void A_cast_limit_tells_a_subtype_from_a_card_type()
    {
        var censor = CardCompiler.Compile(Card(
            "Phyrexian Censor Test",
            "Each player can't cast more than one non-Phyrexian spell each turn.",
            CardType.Creature,
            2,
            2));

        Assert.True(censor.IsComplete, string.Join(" | ", censor.Unhandled));

        var bySubtype = Assert.Single(censor.CastLimits);
        Assert.Equal("Phyrexian", bySubtype.ExceptSubtype);
        Assert.Equal(CardType.None, bySubtype.ExceptTypes);

        // A Phyrexian spell is neither counted nor stopped by it; anything else is both.
        Assert.False(bySubtype.Counts(
            Card("Censor Phyrexian Test", string.Empty, CardType.Creature, 1, 1, subtypes: "Phyrexian")));
        Assert.True(bySubtype.Counts(Card("Censor Other Test", string.Empty)));

        // An adjective the reader has no meaning for refuses the whole line rather than
        // building a limit that stops everything.
        var unknown = CardCompiler.Compile(Card(
            "Nonsense Limit Test",
            "Each player can't cast more than one nonpermanent spell each turn.",
            CardType.Enchantment));

        Assert.False(unknown.IsComplete);
        Assert.Empty(unknown.CastLimits);
    }

    // ---- Round fourteen: leads measured and left, taken (CR 700.14, 702.26, 701.19) ----

    /// <summary>
    /// Regeneration removes the creature from combat, the third of its three parts (CR 701.19c).
    /// </summary>
    /// <remarks>
    /// The replacement's own comment had claimed this for months while emitting only the shield,
    /// the tap and the damage removal. Left out, a regenerated blocker is still blocking: the
    /// attacker it was holding up stays blocked, and a later damage step finds the blocker still
    /// in the lists the rules say it has left.
    /// </remarks>
    [Fact]
    public void A_regenerated_blocker_is_removed_from_combat()
    {
        var troll = Card(
            "Fourteen Troll Test",
            "{G}: Regenerate ~.",
            CardType.Creature,
            power: 1,
            toughness: 1,
            subtypes: "Troll");

        var compiled = CardCompiler.Compile(troll);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(
            alice, TestCards.Creature("Fourteen Attacker Test", 3, 3), Zone.Battlefield);
        var blocker = game.Create(bob, troll, Zone.Battlefield);
        var forest = game.Create(
            bob, Card("Fourteen Forest Test", "{T}: Add {G}.", CardType.Land), Zone.Battlefield);

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);
        game.DeclareBlockers(
            bob,
            new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [attacker] = [blocker] });

        Assert.Contains(blocker, game.State.Combat.Blockers[attacker]);

        // The shield goes up while the block still stands, so what takes the Troll out of combat
        // is the destruction being replaced and nothing about the declaration.
        TestCards.PassUntil(game, () => game.State.Priority.Holder == bob, guard: 200);
        game.ActivateAbility(bob, forest, "mana");
        game.ActivateAbility(bob, blocker, "a");
        Settle(game);

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Settle(game);

        var survivor = game.State.Battlefield
            .Select(game.State.GetObject)
            .SingleOrDefault(o => o.Card.Name == "Fourteen Troll Test");

        Assert.NotNull(survivor);
        Assert.True(survivor!.Permanent!.IsTapped);

        // The assertion the missing line was hiding behind: the regenerated creature is out of
        // every combat list, so nothing is still blocking and nothing is still blocked.
        Assert.DoesNotContain(blocker, game.State.Combat.Blockers.SelectMany(pair => pair.Value));
        Assert.DoesNotContain(blocker, game.State.Combat.Blocked);
    }

    /// <summary>
    /// A permanent's hand-size change is the copied card's, not the printed one's (CR 613.2c).
    /// </summary>
    /// <remarks>
    /// Both reads in the cleanup step's limit asked the object's printed card, so a Clone of Gnat
    /// Miser was not a Miser for this purpose and a Clone of Reliquary Tower did not lift the
    /// limit. Closed as a pair on purpose: fixing one would leave the method asking two different
    /// questions about the same battlefield.
    /// </remarks>
    [Fact]
    public void A_copy_of_a_hand_size_reducer_shrinks_the_hand_the_copied_card_names()
    {
        var miser = Card(
            "Fourteen Miser Test",
            "Each opponent's maximum hand size is reduced by two.",
            CardType.Creature,
            1,
            1);

        var clone = Cloning("Fourteen Miser Clone Test");

        var (game, alice, bob) = InMainPhase();
        game.Create(bob, miser, Zone.Battlefield);
        Settle(game);

        // Alice's Clone of it reaches Bob, which is what makes the copy visible: the printed
        // Clone reduces nobody's hand at all.
        game.Create(alice, clone, Zone.Battlefield);
        SettleCopying(game, "Fourteen Miser Test");

        for (var i = 0; i < 12; i++)
        {
            TestCards.PutInHand(
                game, alice, TestCards.Creature($"Fourteen Hand Alice {i} Test", 1, 1));
            TestCards.PutInHand(
                game, bob, TestCards.Creature($"Fourteen Hand Bob {i} Test", 1, 1));
        }

        PassToMainPhaseOfTurn(game, game.State.TurnNumber + 2);

        // Five, not seven: Alice's copy is a Miser and Bob is its opponent.
        Assert.Equal(5, game.State.GetPlayer(bob).Hand.Count);
    }

    /// <summary>The other read of the pair: "you have no maximum hand size" (CR 402.2).</summary>
    [Fact]
    public void A_copy_of_a_tower_lifts_the_limit_for_whoever_controls_the_copy()
    {
        var tower = Card(
            "Fourteen Tower Test",
            "You have no maximum hand size.",
            CardType.Creature,
            1,
            1);

        var clone = Cloning("Fourteen Tower Clone Test");

        var (game, alice, bob) = InMainPhase();
        game.Create(bob, tower, Zone.Battlefield);
        Settle(game);

        game.Create(alice, clone, Zone.Battlefield);
        SettleCopying(game, "Fourteen Tower Test");

        for (var i = 0; i < 12; i++)
            TestCards.PutInHand(
                game, alice, TestCards.Creature($"Fourteen Tower Card {i} Test", 1, 1));

        PassToMainPhaseOfTurn(game, game.State.TurnNumber + 2);

        // Alice discards nothing: the Clone is a Tower, and the limit is gone rather than seven.
        Assert.True(game.State.GetPlayer(alice).Hand.Count > 7);
    }

    /// <summary>"Target creature phases out" — Reality Ripple, and twelve cards beside it.</summary>
    /// <remarks>
    /// The state and the untap sweep have existed since the keyword was built; what was missing
    /// was a verb an effect could use. The return is the half worth asserting: the permanent comes
    /// back on its <em>controller's</em> untap step (CR 702.26c), which is not the caster's, so an
    /// effect that wrote down the wrong player would look right for a turn and never return it.
    /// </remarks>
    [Fact]
    public void A_targeted_phase_out_returns_on_its_controllers_untap_step()
    {
        var ripple = Card(
            "Fourteen Ripple Test", "Target artifact, creature, or land phases out.");

        var compiled = CardCompiler.Compile(ripple);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var bear = game.Create(
            bob, TestCards.Creature("Fourteen Ripple Bear Test", 2, 2), Zone.Battlefield);
        var card = TestCards.PutInHand(game, alice, ripple);

        game.CastSpell(alice, card, [Target.ToPermanent(bear)]);
        Settle(game);

        Assert.DoesNotContain(bear, game.State.Battlefield);
        Assert.Equal(bob, game.State.PhasedOut[bear]);

        // Not gone: a sweeper cannot find it while it is away (CR 702.26b).
        var wrath = TestCards.PutInHand(
            game,
            alice,
            Card("Fourteen Ripple Wrath Test", "Destroy all creatures.", CardType.Sorcery));

        game.CastSpell(alice, wrath, []);
        Settle(game);

        Assert.DoesNotContain(game.State.GetPlayer(bob).Graveyard, id => id == bear);

        TestCards.PassUntil(
            game,
            () => game.State.ActivePlayerId == bob
                && game.State.CurrentStep == TurnStep.PrecombatMain);

        Assert.Contains(bear, game.State.Battlefield);
        Assert.Empty(game.State.PhasedOut);
    }

    /// <summary>
    /// What an effect phases out takes its Auras with it (CR 702.26g).
    /// </summary>
    /// <remarks>
    /// The fan-out is shared with the untap step's own sweep rather than written twice, and this
    /// is the test that says so. Left out of the effect, the Aura would stay on the battlefield
    /// attached to nothing and be binned by CR 704.5m — the creature would come back naked, and a
    /// card that removes a creature for a turn would have removed an Aura for good.
    /// </remarks>
    [Fact]
    public void An_effect_that_phases_a_creature_out_takes_its_aura_with_it()
    {
        var ripple = Card("Fourteen Aura Ripple Test", "Target creature phases out.");

        var pacifism = Card(
            "Fourteen Aura Pacifism Test",
            "Enchant creature\nEnchanted creature can't attack or block.",
            CardType.Enchantment,
            power: null,
            toughness: null,
            keywords: KeywordAbility.None,
            "Aura");

        var (game, alice, bob) = InMainPhase();
        var bear = game.Create(
            bob, TestCards.Creature("Fourteen Aura Bear Test", 2, 2), Zone.Battlefield);

        var aura = TestCards.PutInHand(game, alice, pacifism);
        game.CastSpell(alice, aura, [Target.ToPermanent(bear)]);
        Settle(game);

        var attached = game.State.Battlefield.Single(
            id => game.State.GetObject(id).Card.Name == "Fourteen Aura Pacifism Test");

        var card = TestCards.PutInHand(game, alice, ripple);
        game.CastSpell(alice, card, [Target.ToPermanent(bear)]);
        Settle(game);

        Assert.DoesNotContain(bear, game.State.Battlefield);
        Assert.DoesNotContain(attached, game.State.Battlefield);
        Assert.DoesNotContain(attached, game.State.GetPlayer(alice).Graveyard);

        // The Aura returns on the creature's controller's schedule and not its own controller's
        // (CR 702.26h) — Bob's untap step, though Alice controls the Aura.
        Assert.Equal(bob, game.State.PhasedOut[attached]);
    }

    /// <summary>"{G}: This creature phases out" — Blink Dog, aimed at the source.</summary>
    [Fact]
    public void An_activated_phase_out_takes_the_permanent_that_activated_it()
    {
        var dog = Card(
            "Fourteen Blink Dog Test",
            "{G}: ~ phases out.",
            CardType.Creature,
            power: 1,
            toughness: 1,
            subtypes: "Dog");

        var compiled = CardCompiler.Compile(dog);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var creature = game.Create(alice, dog, Zone.Battlefield);
        var forest = game.Create(
            alice,
            Card("Fourteen Dog Forest Test", "{T}: Add {G}.", CardType.Land),
            Zone.Battlefield);

        game.ActivateAbility(alice, forest, "mana");
        game.ActivateAbility(alice, creature, "a");
        Settle(game);

        Assert.DoesNotContain(creature, game.State.Battlefield);
        Assert.Equal(alice, game.State.PhasedOut[creature]);
    }

    /// <summary>
    /// "Its owner gains 4 life" pays the owner, who is not always the controller (CR 108.3).
    /// </summary>
    /// <remarks>
    /// Path of Peace and Misfortune's Gain. The neighbouring "its controller" clause had read for
    /// months, and reading this one the same way would pay the thief on exactly the board the
    /// sentence exists for — so the line stayed unread until the effect could tell the two
    /// players apart.
    /// </remarks>
    [Fact]
    public void Its_owner_gains_the_life_and_not_whoever_stole_the_creature()
    {
        var theft = Card(
            "Fourteen Theft Test",
            "Gain control of target creature until end of turn.",
            CardType.Sorcery);

        var peace = Card(
            "Fourteen Peace Test",
            "Destroy target creature. Its owner gains 4 life.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(peace);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var bear = game.Create(
            bob, TestCards.Creature("Fourteen Peace Bear Test", 2, 2), Zone.Battlefield);

        var steal = TestCards.PutInHand(game, alice, theft);
        game.CastSpell(alice, steal, [Target.ToPermanent(bear)]);
        Settle(game);

        Assert.Equal(
            alice, Characteristics.ControllerOf(game.State, Pool, game.State.GetObject(bear)));

        var kill = TestCards.PutInHand(game, alice, peace);
        game.CastSpell(alice, kill, [Target.ToPermanent(bear)]);
        Settle(game);

        // Bob owns the card wherever it goes, so Bob is paid — and Alice, who controlled it when
        // it died, is not.
        Assert.Equal(24, game.State.GetPlayer(bob).Life);
        Assert.Equal(20, game.State.GetPlayer(alice).Life);
    }

    /// <summary>
    /// "Black spells you cast cost {B} more to cast" is a coloured tax (CR 601.2f).
    /// </summary>
    /// <remarks>
    /// The Leech cycle, six cards. The engine's only increase added generic mana, which is a
    /// materially cheaper card: the tax could then be paid with anything. The discriminating
    /// board is one black and one green in the pool — enough for a generic surcharge, and not for
    /// this one.
    /// </remarks>
    [Fact]
    public void A_coloured_surcharge_has_to_be_paid_in_its_own_colour()
    {
        var leech = new CardDefinition
        {
            OracleId = "oracle-fourteen-leech-test",
            Name = "Fourteen Leech Test",
            OracleText = "Black spells you cast cost {B} more to cast.",
            CardTypes = CardType.Creature,
            Power = 2,
            Toughness = 2,
        };

        var compiled = CardCompiler.Compile(leech);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var swamp = Card("Fourteen Swamp Test", "{T}: Add {B}.", CardType.Land);
        var forest = Card("Fourteen Leech Forest Test", "{T}: Add {G}.", CardType.Land);

        var spell = new CardDefinition
        {
            OracleId = "oracle-fourteen-black-spell-test",
            Name = "Fourteen Black Spell Test",
            OracleText = "You gain 1 life.",
            CardTypes = CardType.Instant,
            ManaCostRaw = "{B}",
            Cmc = 1,
            Colors = [ManaColor.Black],
            ColorIdentity = [ManaColor.Black],
        };

        var (game, alice, _) = InMainPhase();
        game.Create(alice, leech, Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, spell);

        game.ActivateAbility(alice, game.Create(alice, swamp, Zone.Battlefield), "mana");
        game.ActivateAbility(alice, game.Create(alice, forest, Zone.Battlefield), "mana");

        // {B}{G} in the pool. A generic {1} surcharge would be paid by the green. The message is
        // asserted because "you do not have priority" is also an InvalidOperationException, and a
        // test that accepted either would pass on a board that never charged anything.
        var refused = Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, card, []));

        Assert.Contains("Not enough mana", refused.Message, StringComparison.Ordinal);

        game.ActivateAbility(alice, game.Create(alice, swamp, Zone.Battlefield), "mana");
        game.CastSpell(alice, card, []);
        Settle(game);

        Assert.Equal(21, game.State.GetPlayer(alice).Life);
    }

    /// <summary>
    /// A disjunction of trigger conditions, and the one shape of it that has to be refused
    /// (CR 603.1, 603.6).
    /// </summary>
    /// <remarks>
    /// "You cast or copy an instant or sorcery spell" is two conditions sharing a subject, both
    /// halves already read, and only the conjunction between them was missing. Read by
    /// distributing the words around the disjunction and asking for each half, which makes the
    /// arm self-limiting: it can only admit a pair this parser already reads whole.
    /// <para>
    /// The second half of this test is the refusal, and it is the more interesting one. "When you
    /// cast or cycle <em>this card</em>" needs the ability to watch from two zones at once - the
    /// stack for the cast, the hand for the cycle - and a triggered ability has one. Compiled
    /// with either zone it plays half of what it says, silently, so the line is refused. Two
    /// corpus cards print it.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_disjunction_of_conditions_reads_when_both_halves_watch_from_one_zone()
    {
        var witch = Card(
            "Fourteen Witch Test",
            "Whenever you cast or copy an instant or sorcery spell, you gain 2 life.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(witch);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        game.Create(alice, witch, Zone.Battlefield);

        var salve = TestCards.PutInHand(
            game, alice, Card("Fourteen Witch Salve Test", "You gain 1 life."));

        game.CastSpell(alice, salve, []);
        Settle(game);

        // Two from the trigger and one from the spell.
        Assert.Equal(23, game.State.GetPlayer(alice).Life);

        // The half neither zone can serve, refused rather than half-compiled.
        var lurker = CardCompiler.Compile(Card(
            "Fourteen Lurker Test",
            "Cycling {0}\nWhen you cast or cycle ~, you gain 2 life.",
            CardType.Creature,
            power: 2,
            toughness: 2));

        Assert.False(lurker.IsComplete);
        Assert.Contains(
            lurker.Unhandled, line => line.Contains("cast or cycle", StringComparison.Ordinal));
    }

    /// <summary>
    /// A card's own "when you cast this" watches from the stack, not the battlefield (CR 603.6).
    /// </summary>
    /// <remarks>
    /// The trigger reader had one exception to "everything watches from the battlefield" - the
    /// cycling one, added because a card left at the default compiled cleanly and never fired.
    /// The self-cast trigger is the same shape and had no exception: by the time the cast is
    /// announced the card is on the stack, so a permanent's own cast trigger was watching from a
    /// zone it had already left. Fifty-odd corpus cards print it, and every one of them read
    /// perfectly and did nothing.
    /// </remarks>
    [Fact]
    public void A_cards_own_cast_trigger_fires_from_the_stack()
    {
        var drifter = Card(
            "Fourteen Drifter Test",
            "When you cast ~, you gain 2 life.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var compiled = CardCompiler.Compile(drifter);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, drifter);

        game.CastSpell(alice, card, []);
        Settle(game);

        Assert.Equal(22, game.State.GetPlayer(alice).Life);
    }

    /// <summary>
    /// "~ has persist as long as you control a black creature" (CR 613.1f, 702.78a).
    /// </summary>
    /// <remarks>
    /// Persist is a triggered ability rather than a flag, which is why the grantable-keyword table
    /// leaves it out on purpose — so a conditional one is granted the way a quoted ability is,
    /// from the same definition the printed word builds. Two Scarecrows print it.
    /// </remarks>
    [Fact]
    public void A_conditional_persist_returns_the_creature_only_while_the_condition_holds()
    {
        var scarecrow = Card(
            "Fourteen Scarecrow Test",
            "~ has persist as long as you control a black creature.",
            CardType.Artifact | CardType.Creature,
            power: 2,
            toughness: 2,
            keywords: KeywordAbility.None,
            "Scarecrow");

        var compiled = CardCompiler.Compile(scarecrow);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        // Without a black creature it is an ordinary 2/2 and stays dead.
        var (bare, aliceBare, _) = InMainPhase();
        var alone = bare.Create(aliceBare, scarecrow, Zone.Battlefield);
        bare.Move(alone, Zone.Graveyard, MoveCause.Destroy);
        Settle(bare);

        Assert.DoesNotContain(
            bare.State.Battlefield,
            id => bare.State.GetObject(id).Card.Name == "Fourteen Scarecrow Test");

        // With one, the granted trigger brings it back with a -1/-1 counter.
        var (game, alice, _) = InMainPhase();
        game.Create(
            alice, Coloured("Fourteen Black Creature Test", ManaColor.Black), Zone.Battlefield);

        var body = game.Create(alice, scarecrow, Zone.Battlefield);
        Settle(game);

        game.Move(body, Zone.Graveyard, MoveCause.Destroy);
        Settle(game);

        var returned = game.State.Battlefield
            .Select(game.State.GetObject)
            .SingleOrDefault(o => o.Card.Name == "Fourteen Scarecrow Test");

        Assert.NotNull(returned);
        Assert.Equal(
            1, returned!.Permanent!.Counters.GetValueOrDefault(CounterKinds.MinusOneMinusOne));
    }

    /// <summary>
    /// "Mill three cards, then you may return a creature card from your graveyard to your hand."
    /// </summary>
    /// <remarks>
    /// The odd one of the round: the mill read, the return read, and the pair did not. The offer
    /// refused to carry a deferred question at all — a refusal written when the locator was
    /// resolved against an ability's top-level effects. The tree walker finds a nested one now, so
    /// the refusal narrowed to what still cannot be answered: more than one question in the
    /// branch, or another already compiled that its index could be confused with.
    /// </remarks>
    [Fact]
    public void An_offer_can_carry_one_question_inside_it()
    {
        var churn = Card(
            "Fourteen Churn Test",
            "Mill three cards, then you may return a creature card from your graveyard to your hand.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(churn);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var buried = game.Create(
            alice, TestCards.Creature("Fourteen Churn Body Test", 2, 2), Zone.Graveyard);

        var card = TestCards.PutInHand(game, alice, churn);
        var handBefore = game.State.GetPlayer(alice).Hand.Count;

        game.CastSpell(alice, card, []);

        // Play on until the spell resolves and the game stops to ask.
        for (var guard = 0; guard < 40 && game.State.Choice is null; guard++)
        {
            if (game.State.Priority.Holder is not { } holder)
                break;

            game.PassPriority(holder);
        }

        var offer = Assert.IsType<PendingChoice>(game.State.Choice);
        var yes = offer.Options.Single(
            o => o.Label.StartsWith("Return", StringComparison.OrdinalIgnoreCase));

        game.Choose(offer.PlayerId, [yes.Id]);

        // The question inside the offer's accepted arm, which is the whole point: before this
        // round the offer refused to carry one at all and the line went unread.
        var question = Assert.IsType<PendingChoice>(game.State.Choice);
        var wanted = question.Options.Single(
            o => o.Label.Contains("Fourteen Churn Body Test", StringComparison.Ordinal));

        game.Choose(question.PlayerId, [wanted.Id]);
        Settle(game);

        // The spell left the hand and the named creature came back, so the hand is where it
        // started - and that card is out of the graveyard, which the mill alone cannot do.
        Assert.Equal(handBefore, game.State.GetPlayer(alice).Hand.Count);
        Assert.DoesNotContain(buried, game.State.GetPlayer(alice).Graveyard);
        Assert.Contains(
            game.State.GetPlayer(alice).Hand,
            id => game.State.GetObject(id).Card.Name == "Fourteen Churn Body Test");
    }

    /// <summary>
    /// An arrangement line carries whatever the card says after it.
    /// </summary>
    /// <remarks>
    /// Anchored to the end of the line, one trailing sentence threw the whole match away — Omen
    /// and Ponder differ from Index by "You may shuffle." and nothing else, and Pondering Mage by
    /// a draw. The recorded decision that this family was deferred for want of an in-zone reorder
    /// was stale by then: thirteen cards printing the phrase already read.
    /// </remarks>
    [Fact]
    public void An_arrangement_line_reads_the_sentences_after_it()
    {
        var ponder = Card(
            "Fourteen Ponder Test",
            "Look at the top three cards of your library, then put them back in any order. "
                + "You may shuffle. Draw a card.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(ponder);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, ponder);
        var libraryBefore = game.State.GetPlayer(alice).Library.Count;
        var handBefore = game.State.GetPlayer(alice).Hand.Count;

        game.CastSpell(alice, card, []);
        Settle(game);

        // The trailing draw is the half a match anchored at the end would have thrown away along
        // with the rest of the line.
        Assert.Equal(libraryBefore - 1, game.State.GetPlayer(alice).Library.Count);
        Assert.Equal(handBefore, game.State.GetPlayer(alice).Hand.Count);
    }

    /// <summary>
    /// "Whenever one or more Halflings you control attack a player" (CR 508.1b, 603.2).
    /// </summary>
    /// <remarks>
    /// The tribal narrowing on this family already read; what did not was the defender said out
    /// loud. "A player" names nobody in particular — it rules out a planeswalker and nothing else
    /// — so folding it into the reader that asks whether the attack was aimed at this card's own
    /// controller would have fired for nobody.
    /// </remarks>
    [Fact]
    public void A_tribal_batch_attack_trigger_fires_once_for_the_declaration()
    {
        var meriadoc = Card(
            "Fourteen Meriadoc Test",
            "Whenever one or more Halflings you control attack a player, you gain 2 life.",
            CardType.Creature,
            power: 1,
            toughness: 2,
            keywords: KeywordAbility.None,
            "Halfling");

        var compiled = CardCompiler.Compile(meriadoc);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var halfling = Card(
            "Fourteen Halfling Test",
            string.Empty,
            CardType.Creature,
            power: 1,
            toughness: 1,
            keywords: KeywordAbility.None,
            "Halfling");

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, meriadoc, Zone.Battlefield);
        var first = game.Create(alice, halfling, Zone.Battlefield);
        var second = game.Create(alice, halfling, Zone.Battlefield);
        var bear = game.Create(
            alice, TestCards.Creature("Fourteen Meriadoc Bear Test", 2, 2), Zone.Battlefield);

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget>
            {
                [first] = AttackTarget.Player(bob),
                [second] = AttackTarget.Player(bob),
                [bear] = AttackTarget.Player(bob),
            });

        Settle(game);

        // Once for the batch however many Halflings were in it (CR 603.2), and the Bear in the
        // same declaration adds nothing.
        Assert.Equal(22, game.State.GetPlayer(alice).Life);
    }

    /// <summary>
    /// "Outlaws" is five creature types rather than one (CR 700.12).
    /// </summary>
    /// <remarks>
    /// Printed lowercase beside the capitalised tribes because it is not a type at all, which is
    /// exactly why the subject reader refused it: a lowercase word there is a card type or
    /// nothing. Expanded into the alternation the sentence already supports, so a Pirate Rogue
    /// answers once rather than twice.
    /// </remarks>
    [Fact]
    public void An_outlaw_batch_trigger_answers_to_any_of_the_five_types()
    {
        var olivia = Card(
            "Fourteen Olivia Test",
            "Whenever one or more outlaws you control deal combat damage to a player, "
                + "you gain 3 life.",
            CardType.Creature,
            power: 2,
            toughness: 2,
            keywords: KeywordAbility.None,
            "Vampire");

        var compiled = CardCompiler.Compile(olivia);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var warlock = Card(
            "Fourteen Warlock Test",
            string.Empty,
            CardType.Creature,
            power: 2,
            toughness: 2,
            keywords: KeywordAbility.None,
            "Warlock");

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, olivia, Zone.Battlefield);
        var attacker = game.Create(alice, warlock, Zone.Battlefield);

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Settle(game);

        // A Warlock is an outlaw, and nothing else on the board is.
        Assert.Equal(18, game.State.GetPlayer(bob).Life);
        Assert.Equal(23, game.State.GetPlayer(alice).Life);
    }

    /// <summary>
    /// "Whenever you expend 4" is a threshold being crossed, not a total being reached
    /// (CR 700.14).
    /// </summary>
    /// <remarks>
    /// Ten cards, and what the family needed was a running tally of mana spent casting spells plus
    /// an event saying where a payment left it. Both totals travel on the event because a trigger
    /// predicate is handed the state from one side of it (CR 603.6), and neither side alone says a
    /// line was crossed — which is also why the last third of this test is the part that matters:
    /// it fires once a turn however much else is cast.
    /// </remarks>
    [Fact]
    public void Expend_fires_on_the_payment_that_crosses_the_threshold_and_not_again()
    {
        var boxer = Card(
            "Fourteen Boxer Test",
            "Whenever you expend 4, you gain 2 life.",
            CardType.Creature,
            power: 2,
            toughness: 2);

        var compiled = CardCompiler.Compile(boxer);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var forest = Card("Fourteen Expend Forest Test", "{T}: Add {G}.", CardType.Land);

        var (game, alice, _) = InMainPhase();
        var turn = game.State.TurnNumber;
        game.Create(alice, boxer, Zone.Battlefield);

        var first = TestCards.PutInHand(
            game, alice, TestCards.Costed("Fourteen Expend Two Test", "{2}", 2));

        for (var i = 0; i < 2; i++)
            game.ActivateAbility(alice, game.Create(alice, forest, Zone.Battlefield), "mana");

        game.CastSpell(alice, first, []);
        Settle(game);

        // Two mana spent: under the line, so nothing has happened yet.
        Assert.Equal(2, game.State.GetPlayer(alice).ManaSpentCastingThisTurn);
        Assert.Equal(20, game.State.GetPlayer(alice).Life);

        var second = TestCards.PutInHand(
            game, alice, TestCards.Costed("Fourteen Expend Three Test", "{3}", 3));

        for (var i = 0; i < 3; i++)
            game.ActivateAbility(alice, game.Create(alice, forest, Zone.Battlefield), "mana");

        game.CastSpell(alice, second, []);
        Settle(game);

        // Five now, so that payment took the total from below four to above it.
        Assert.Equal(5, game.State.GetPlayer(alice).ManaSpentCastingThisTurn);
        Assert.Equal(22, game.State.GetPlayer(alice).Life);

        var third = TestCards.PutInHand(
            game, alice, TestCards.Costed("Fourteen Expend Four Test", "{4}", 4));

        for (var i = 0; i < 4; i++)
            game.ActivateAbility(alice, game.Create(alice, forest, Zone.Battlefield), "mana");

        game.CastSpell(alice, third, []);
        Settle(game);

        // Nine mana spent and still one trigger: the line is crossed once a turn.
        Assert.Equal(turn, game.State.TurnNumber);
        Assert.Equal(9, game.State.GetPlayer(alice).ManaSpentCastingThisTurn);
        Assert.Equal(22, game.State.GetPlayer(alice).Life);
    }

    // ---- Damage that can't be prevented, life that can't be gained (CR 615.12, 119.7) -------

    /// <summary>
    /// Plays on until this player can act again, without letting the turn roll over.
    /// </summary>
    /// <remarks>
    /// Every one of these tests needs several casts on one turn, and <see cref="Settle"/> leaves
    /// priority wherever the resolution did. The turn is asserted rather than assumed because
    /// these are the tests where it matters most: a ban reading "this turn" would be swept by a
    /// cleanup the test did not know it had crossed, and the test would pass for the wrong
    /// reason.
    /// </remarks>
    private static void Ready(Game game, Guid playerId)
    {
        var turn = game.State.TurnNumber;
        TestCards.PassUntil(game, () => game.State.Priority.Holder == playerId);
        Assert.Equal(turn, game.State.TurnNumber);
    }

    /// <summary>Whether a card of this name is in that player's graveyard.</summary>
    /// <remarks>
    /// By name rather than by id: a permanent that is sacrificed becomes a new object in the
    /// graveyard (CR 400.7), so the id the battlefield knew it by finds nothing at all.
    /// </remarks>
    private static bool InGraveyard(Game game, Guid playerId, string name) =>
        game.State.GetPlayer(playerId).Graveyard
            .Select(game.State.GetObject)
            .Any(o => o.Card.Name == name);

    /// <summary>A shield that soaks, so the ban below has something to be measured against.</summary>
    private static CardDefinition PreventionShield(string name) => Card(
        name,
        "Prevent the next 2 damage that would be dealt to target creature this turn.");

    [Fact]
    public void A_shield_holds_until_a_ban_says_the_damage_cant_be_prevented()
    {
        // The control half first, because a ban that reads more broadly than it prints makes
        // every shield useless and nothing about the coverage number would notice. The shield
        // has to be seen working before the ban is seen beating it.
        var ban = Card("Flaring Pain Test", "Damage can't be prevented this turn.");

        var compiled = CardCompiler.Compile(ban);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var bear = game.Create(alice, TestCards.Creature("Painless Bear Test", 9, 9), Zone.Battlefield);
        var source = game.Create(alice, TestCards.Creature("Painless Source Test", 1, 1), Zone.Battlefield);

        game.CastSpell(
            alice,
            TestCards.PutInHand(game, alice, PreventionShield("Painless Shield Test")),
            [Target.ToPermanent(bear)]);
        Settle(game);

        game.MarkDamage(bear, 2, sourceId: source);
        Settle(game);

        // Control: the shield really does stop damage arriving.
        Assert.Equal(0, game.State.GetObject(bear).Permanent!.DamageMarked);

        Ready(game, alice);
        game.CastSpell(
            alice,
            TestCards.PutInHand(game, alice, PreventionShield("Painless Shield Two Test")),
            [Target.ToPermanent(bear)]);
        Settle(game);

        Ready(game, alice);
        game.CastSpell(alice, TestCards.PutInHand(game, alice, ban), []);
        Settle(game);

        game.MarkDamage(bear, 2, sourceId: source);
        Settle(game);

        // And with the ban up, the same two points arrive.
        Assert.Equal(2, game.State.GetObject(bear).Permanent!.DamageMarked);
    }

    [Fact]
    public void A_shield_is_not_spent_by_damage_it_could_not_have_prevented()
    {
        // CR 615.12's last sentence, and the half that is invisible unless it is asserted:
        // "existing damage prevention shields won't be reduced by damage that can't be
        // prevented". A prevention arm that ran and prevented nothing would still have emptied
        // the shield, and the card would look right for exactly one damage event.
        var excruciator = Card(
            "Excruciator Test",
            "Damage that would be dealt by ~ can't be prevented.",
            CardType.Creature,
            power: 5,
            toughness: 5);

        var compiled = CardCompiler.Compile(excruciator);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var bear = game.Create(alice, TestCards.Creature("Unsoaked Bear Test", 9, 9), Zone.Battlefield);
        var banned = game.Create(alice, excruciator, Zone.Battlefield);
        var ordinary = game.Create(
            alice, TestCards.Creature("Ordinary Source Test", 1, 1), Zone.Battlefield);

        game.CastSpell(
            alice,
            TestCards.PutInHand(game, alice, PreventionShield("Unsoaked Shield Test")),
            [Target.ToPermanent(bear)]);
        Settle(game);

        game.MarkDamage(bear, 3, sourceId: banned);
        Settle(game);

        // All three arrived, and the shield is untouched.
        Assert.Equal(3, game.State.GetObject(bear).Permanent!.DamageMarked);
        Assert.Equal(2, game.State.GetObject(bear).Permanent!.DamageToPrevent);

        // Which is the whole point: it is still there for the damage it can stop.
        game.MarkDamage(bear, 2, sourceId: ordinary);
        Settle(game);

        Assert.Equal(3, game.State.GetObject(bear).Permanent!.DamageMarked);
        Assert.Equal(0, game.State.GetObject(bear).Permanent!.DamageToPrevent);
    }

    [Fact]
    public void A_bans_source_clause_leaves_every_other_source_preventable()
    {
        // The trap this family is most dangerous for. Read as "damage can't be prevented" with
        // the "by ~" dropped, Excruciator would turn off every shield on the table.
        var excruciator = Card(
            "Narrow Ban Test",
            "Damage that would be dealt by ~ can't be prevented.",
            CardType.Creature,
            power: 5,
            toughness: 5);

        var (game, alice, _) = InMainPhase();
        var bear = game.Create(alice, TestCards.Creature("Narrow Bear Test", 9, 9), Zone.Battlefield);
        game.Create(alice, excruciator, Zone.Battlefield);
        var other = game.Create(alice, TestCards.Creature("Narrow Other Test", 1, 1), Zone.Battlefield);

        game.CastSpell(
            alice,
            TestCards.PutInHand(game, alice, PreventionShield("Narrow Shield Test")),
            [Target.ToPermanent(bear)]);
        Settle(game);

        game.MarkDamage(bear, 2, sourceId: other);
        Settle(game);

        Assert.Equal(0, game.State.GetObject(bear).Permanent!.DamageMarked);
    }

    [Fact]
    public void A_static_ban_stops_the_moment_its_permanent_does()
    {
        // CR 611.2c: a static ability's effect lasts exactly as long as the permanent. Held as
        // state instead, the ban would go on working from the graveyard - the mistake the
        // prevention shield made in the other direction, and which this file records.
        var leyline = Card(
            "Punishment Leyline Test",
            "Players can't gain life.\nDamage can't be prevented.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(leyline);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var bear = game.Create(alice, TestCards.Creature("Leyline Bear Test", 9, 9), Zone.Battlefield);
        var source = game.Create(alice, TestCards.Creature("Leyline Source Test", 1, 1), Zone.Battlefield);
        var enchantment = game.Create(alice, leyline, Zone.Battlefield);

        game.CastSpell(
            alice,
            TestCards.PutInHand(game, alice, PreventionShield("Leyline Shield Test")),
            [Target.ToPermanent(bear)]);
        Settle(game);

        game.MarkDamage(bear, 2, sourceId: source);
        Settle(game);

        Assert.Equal(2, game.State.GetObject(bear).Permanent!.DamageMarked);

        game.Move(enchantment, Zone.Graveyard, MoveCause.Destroy);
        Settle(game);

        // The shield was never spent, so it is still there when the ban goes.
        game.MarkDamage(bear, 2, sourceId: source);
        Settle(game);

        Assert.Equal(2, game.State.GetObject(bear).Permanent!.DamageMarked);
    }

    [Fact]
    public void The_no_duration_ban_is_a_static_and_the_this_turn_ban_is_not()
    {
        // The control that keeps the two readers apart, and it asserts both directions of the
        // mistake. A "this turn" ban compiled as a static would never come down; a no-duration
        // ban compiled as a one-shot would be filed in state by a card already in a graveyard.
        Assert.Contains(
            "Damage can't be prevented.",
            CardCompiler.Compile(Card("Undated Ban Test", "Damage can't be prevented.")).Unhandled);

        Assert.Contains(
            "Damage can't be prevented this turn.",
            CardCompiler.Compile(
                Card(
                    "Dated Ban Test",
                    "Damage can't be prevented this turn.",
                    CardType.Enchantment)).Unhandled);
    }

    [Fact]
    public void The_ban_ends_with_the_turn_that_bought_it()
    {
        // CR 514.2. Left standing, "damage can't be prevented this turn" would go on switching
        // shields off for the rest of the game.
        var ban = Card("Expiring Ban Test", "Damage can't be prevented this turn.");

        var (game, alice, _) = InMainPhase();
        var bear = game.Create(alice, TestCards.Creature("Expiring Bear Test", 9, 9), Zone.Battlefield);
        var source = game.Create(alice, TestCards.Creature("Expiring Source Test", 1, 1), Zone.Battlefield);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, ban), []);
        Settle(game);

        Assert.Single(game.State.Unpreventable);

        TestCards.PassToTurn(game, game.State.TurnNumber + 2);
        Assert.Empty(game.State.Unpreventable);

        Ready(game, alice);
        game.CastSpell(
            alice,
            TestCards.PutInHand(game, alice, PreventionShield("Expiring Shield Test")),
            [Target.ToPermanent(bear)]);
        Settle(game);

        game.MarkDamage(bear, 2, sourceId: source);
        Settle(game);

        Assert.Equal(0, game.State.GetObject(bear).Permanent!.DamageMarked);
    }

    [Fact]
    public void A_combat_only_ban_leaves_noncombat_damage_preventable()
    {
        // Questing Beast's line. "Combat" is the whole difference between a card that turns off
        // one kind of shield and a card that turns off all of them.
        var beast = Card(
            "Questing Ban Test",
            "Combat damage that would be dealt by creatures you control can't be prevented.",
            CardType.Creature,
            power: 4,
            toughness: 4);

        var compiled = CardCompiler.Compile(beast);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var bear = game.Create(alice, TestCards.Creature("Questing Bear Test", 9, 9), Zone.Battlefield);
        game.Create(alice, beast, Zone.Battlefield);
        var pinger = game.Create(alice, TestCards.Creature("Questing Pinger Test", 1, 1), Zone.Battlefield);

        game.CastSpell(
            alice,
            TestCards.PutInHand(game, alice, PreventionShield("Questing Shield Test")),
            [Target.ToPermanent(bear)]);
        Settle(game);

        // Noncombat damage from a creature Alice controls, which the ban does not cover.
        game.MarkDamage(bear, 2, sourceId: pinger);
        Settle(game);

        Assert.Equal(0, game.State.GetObject(bear).Permanent!.DamageMarked);
    }

    [Fact]
    public void A_ban_beats_a_fog_and_the_combat_damage_lands()
    {
        // The fog is applied wholesale in the combat damage step rather than per event, which is
        // the same answer far cheaper - right up until a ban makes some events different from
        // others. Without this the step would short-circuit and the ban would do nothing at all
        // to the commonest prevention effect in the game.
        var fog = Card("Ban Fog Test", "Prevent all combat damage that would be dealt this turn.");
        var ban = Card("Ban Skullcrack Test", "Damage can't be prevented this turn.");

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(
            alice, TestCards.Creature("Ban Attacker Test", 3, 3), Zone.Battlefield);

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);
        game.DeclareBlockers(bob, new Dictionary<ObjectId, IReadOnlyList<ObjectId>>());

        Ready(game, alice);
        game.CastSpell(alice, TestCards.PutInHand(game, alice, ban), []);
        Settle(game);

        Ready(game, bob);
        game.CastSpell(bob, TestCards.PutInHand(game, bob, fog), []);
        Settle(game);

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Settle(game);

        Assert.Equal(17, game.State.GetPlayer(bob).Life);
    }

    [Fact]
    public void A_fog_still_stops_combat_damage_when_no_ban_is_in_play()
    {
        // The other half of the shortcut above, so a change to it cannot quietly turn every fog
        // in the game off.
        var fog = Card("Plain Fog Test", "Prevent all combat damage that would be dealt this turn.");

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(
            alice, TestCards.Creature("Plain Attacker Test", 3, 3), Zone.Battlefield);

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);
        game.DeclareBlockers(bob, new Dictionary<ObjectId, IReadOnlyList<ObjectId>>());

        Ready(game, bob);
        game.CastSpell(bob, TestCards.PutInHand(game, bob, fog), []);
        Settle(game);

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Settle(game);

        Assert.Equal(20, game.State.GetPlayer(bob).Life);
    }

    [Fact]
    public void The_damage_cant_be_prevented_covers_this_spell_and_nothing_else()
    {
        // Combust and Pinpoint Avalanche print the rider *after* the damage it is about, so the
        // ban has to exist before the sentence that deals it - and it names one source, so every
        // other source stays shielded. Both halves are asserted, because the natural mistakes
        // are opposite: a ban created too late does nothing, and a ban with its source slot
        // empty fogs the whole table.
        var combust = Card(
            "Combust Test",
            "~ deals 5 damage to target creature. The damage can't be prevented.");

        var compiled = CardCompiler.Compile(combust);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var bear = game.Create(alice, TestCards.Creature("Combust Bear Test", 9, 9), Zone.Battlefield);
        var other = game.Create(alice, TestCards.Creature("Combust Other Test", 1, 1), Zone.Battlefield);

        game.CastSpell(
            alice,
            TestCards.PutInHand(game, alice, PreventionShield("Combust Shield Test")),
            [Target.ToPermanent(bear)]);
        Settle(game);

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, combust), [Target.ToPermanent(bear)]);
        Settle(game);

        // All five arrived through a shield that is still standing.
        Assert.Equal(5, game.State.GetObject(bear).Permanent!.DamageMarked);
        Assert.Equal(2, game.State.GetObject(bear).Permanent!.DamageToPrevent);

        // And somebody else's damage is prevented exactly as before.
        game.MarkDamage(bear, 2, sourceId: other);
        Settle(game);

        Assert.Equal(5, game.State.GetObject(bear).Permanent!.DamageMarked);
    }

    [Fact]
    public void Players_cant_gain_life_stops_every_seat()
    {
        // CR 119.7. The control comes first for the same reason the shield's does: a ban asserted
        // only by the presence of a state row proves nothing about whether life stops moving.
        var gain = Card("Life Gift Test", "Target player gains 3 life.");
        var festival = Card("Havoc Ban Test", "Players can't gain life.", CardType.Enchantment);

        var compiled = CardCompiler.Compile(festival);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();

        game.CastSpell(alice, TestCards.PutInHand(game, alice, gain), [Target.ToPlayer(bob)]);
        Settle(game);

        Assert.Equal(23, game.State.GetPlayer(bob).Life);

        game.Create(alice, festival, Zone.Battlefield);
        Settle(game);

        Ready(game, alice);
        game.CastSpell(alice, TestCards.PutInHand(game, alice, gain), [Target.ToPlayer(bob)]);
        Settle(game);
        Ready(game, alice);
        game.CastSpell(alice, TestCards.PutInHand(game, alice, gain), [Target.ToPlayer(alice)]);
        Settle(game);

        Assert.Equal(23, game.State.GetPlayer(bob).Life);
        Assert.Equal(20, game.State.GetPlayer(alice).Life);
    }

