    [Fact]
    public void An_or_inside_one_price_is_not_a_choice_between_two()
    {
        // Fourteen corpus cards print "sacrifice an artifact or creature", which is one price
        // with a wider filter. Split into two prices it would become a card that could be paid
        // for by sacrificing an artifact *or* by doing nothing at all.
        var glare = ChoiceSpell(
            "Wide Filter Test", "sacrifice an artifact or creature.", "{B}");

        var compiled = CardCompiler.Compile(glare);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var spell = Pool.For(glare).Spell;
        Assert.NotNull(spell);
        Assert.Empty(spell!.CostChoices);
        Assert.Single(spell.ChosenCosts);
    }

    [Fact]
    public void A_wide_filter_beside_a_mana_price_keeps_both_halves()
    {
        // "Sacrifice an artifact or creature or pay {4}" is three fragments and two prices, and
        // only the longest-first reassembly gets it right: taken shortest-first the reader would
        // be left holding the word "creature" and would have to refuse the line.
        var trouble = ChoiceSpell(
            "Stir Up Trouble Test", "sacrifice an artifact or creature or pay {4}.", "{B}");

        var compiled = CardCompiler.Compile(trouble);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var choice = Assert.Single(Pool.For(trouble).Spell!.CostChoices);
        Assert.Equal(2, choice.Options.Count);

        var sacrifice = Assert.Single(choice.Options[0].Chosen);
        Assert.Equal(ChosenCostKind.SacrificePermanents, sacrifice.Kind);
        Assert.Empty(choice.Options[1].Chosen);
        Assert.Equal(4, choice.Options[1].Mana.ManaValue);
    }

    // ---- What a "spend this mana only" clause says beyond a type mask (CR 106.6) ----

    /// <summary>
    /// "Cast an instant or sorcery spell" is one clause naming two types, not two clauses.
    /// </summary>
    /// <remarks>
    /// The clause separator split on every "or", so the commonest restriction in the corpus came
    /// apart into "cast an instant" and "sorcery spell" — neither of which is a clause, so the
    /// reader returned null and the whole line went unread. Ten cards in the corpus say it
    /// exactly this way, and none of them could be read at all.
    /// <para>
    /// A clause always opens with its verb, so the separator now splits only where a verb follows
    /// the "or". Played rather than asserted against the parse, because the point is not that the
    /// sentence parses: it is that the mana it makes pays for one kind of spell and refuses the
    /// other, which is the whole of what the land is.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_restriction_naming_two_types_in_the_singular_is_read_as_one_clause()
    {
        // Vodalian Arcanist's wording on a land, the way the neighbouring restriction tests are
        // written: the clause is what is under test, and a creature would spend the test on
        // summoning sickness instead (CR 302.6).
        var arcanist = Card(
            "Arcanist Cave Test",
            "{T}: Add {C}. Spend this mana only to cast an instant or sorcery spell.",
            CardType.Land);

        var compiled = CardCompiler.Compile(arcanist);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var produced = Assert.Single(Assert.Single(compiled.Activated).Produces);
        var restriction = Assert.NotNull(produced.Restriction);

        // Both types, from one clause. Before the fix this reader saw two broken halves and
        // reported nothing at all.
        Assert.True(restriction.Allows(ManaPurpose.CastSpell, CardType.Instant));
        Assert.True(restriction.Allows(ManaPurpose.CastSpell, CardType.Sorcery));
        Assert.False(restriction.Allows(ManaPurpose.CastSpell, CardType.Creature));

        var bolt = new CardDefinition
        {
            OracleId = "oracle-arcanist-bolt-test",
            Name = "Arcanist Bolt Test",
            OracleText = "~ deals 1 damage to any target.",
            CardTypes = CardType.Instant,
            ManaCostRaw = "{C}",
            Cmc = 1,
        };

        var (game, alice, _) = InMainPhase();
        var source = game.Create(alice, arcanist, Zone.Battlefield);
        var bear = TestCards.PutInHand(
            game, alice, TestCards.Costed("Arcanist Bear Test", "{C}", 1));

        game.ActivateAbility(alice, source, "mana");
        Assert.Equal(1, game.State.GetPlayer(alice).ManaPool.Total);

        // A creature is neither of the two types the clause named.
        Assert.Throws<InvalidOperationException>(() => game.CastSpell(alice, bear, []));

        var instant = TestCards.PutInHand(game, alice, bolt);
        game.CastSpell(alice, instant, [Target.ToPlayer(alice)]);

        Assert.True(game.State.GetPlayer(alice).ManaPool.IsEmpty);
    }

    /// <summary>
    /// "Cast instant and sorcery spells" — the same restriction, joined with "and".
    /// </summary>
    /// <remarks>
    /// A separate defect from the one above and invisible next to it, because the symptom is
    /// identical: <see cref="System.Text.RegularExpressions.Regex.Split(string)"/> puts the text
    /// of every <em>capturing</em> group into its result, and the type separator captured its
    /// conjunctions. "Instant and sorcery" came back as three parts, the middle one being the
    /// word "and", which was then rejected as a card type and refused the whole restriction.
    /// <para>
    /// The comma arm of that pattern never captured, which is why "instant, sorcery" had worked
    /// all along while the spelling the cards actually use did not — the kind of split that a
    /// ranking by opening words cannot see, because both spellings open identically.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_restriction_joining_its_types_with_and_is_read()
    {
        foreach (var wording in new[]
        {
            "Spend this mana only to cast instant and sorcery spells.",
            "Spend this mana only to cast instant or sorcery spells.",
            "Spend this mana only to cast an instant or sorcery spell.",
        })
        {
            var limit = EffectPhrase.SpendLimitFor(wording);
            Assert.NotNull(limit);

            var restriction = limit!.Value.Restriction;
            Assert.True(restriction.Allows(ManaPurpose.CastSpell, CardType.Instant), wording);
            Assert.True(restriction.Allows(ManaPurpose.CastSpell, CardType.Sorcery), wording);
            Assert.False(restriction.Allows(ManaPurpose.CastSpell, CardType.Creature), wording);

            // Nothing narrower than the mask is being said, so the older signature still answers.
            Assert.False(limit.Value.IsNarrow, wording);
        }
    }

    /// <summary>
    /// "Spend this mana only to cast Myr spells or activate abilities of Myr" (CR 106.6).
    /// </summary>
    /// <remarks>
    /// A tribe is not a card type, and the reader's only output was a type mask — so every clause
    /// naming one was refused outright and the land went unread. The pool has been able to hold
    /// the answer since <c>RestrictedMana.FilterId</c> was added; nothing could read the sentence
    /// that sets it, and the two halves sat a field apart for a whole round.
    /// <para>
    /// The filter goes through the shared vocabulary rather than a table of its own, which is why
    /// one change took tribes, supertypes, colours and negations together instead of four.
    /// </para>
    /// </remarks>
    [Fact]
    public void Mana_restricted_to_a_tribe_is_read_from_the_printed_wording()
    {
        var reservoir = Card(
            "Myr Reservoir Test",
            "{T}: Add {C}{C}. Spend this mana only to cast Myr spells or activate abilities"
                + " of Myr.",
            CardType.Land);

        var compiled = CardCompiler.Compile(reservoir);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var mana = Assert.Single(compiled.Activated);

        // One entry per mana, because the restriction travels with the individual mana.
        Assert.Equal(2, mana.Produces.Count);
        Assert.All(mana.Produces, one => Assert.Equal("Myr", one.RestrictedTo));

        var myr = new CardDefinition
        {
            OracleId = "oracle-reservoir-myr-test",
            Name = "Reservoir Myr Test",
            CardTypes = CardType.Artifact | CardType.Creature,
            Subtypes = ["Myr"],
            ManaCostRaw = "{C}",
            Cmc = 1,
        };

        var golem = new CardDefinition
        {
            OracleId = "oracle-reservoir-golem-test",
            Name = "Reservoir Golem Test",
            CardTypes = CardType.Artifact | CardType.Creature,
            Subtypes = ["Golem"],
            ManaCostRaw = "{C}",
            Cmc = 1,
        };

        var pool = ManaPool.Empty.AddRestricted(
            new RestrictedMana(null, mana.Produces[0].Restriction!.Value)
            {
                FilterId = mana.Produces[0].RestrictedTo,
            });

        Assert.NotNull(ManaPayment.Pay(
            pool, ManaCostSpec.Parse("{C}"), spend: ManaSpend.Casting(myr, Zone.Hand)));

        // Both are artifact creatures costing the same. Only the subtype tells them apart, and a
        // type mask could not have said so.
        Assert.Null(ManaPayment.Pay(
            pool, ManaCostSpec.Parse("{C}"), spend: ManaSpend.Casting(golem, Zone.Hand)));
    }

    /// <summary>
    /// "Cast legendary spells", "cast colorless Eldrazi spells", "cast a Knight or Equipment
    /// spell" — a supertype, a compound and an alternation, all from one vocabulary.
    /// </summary>
    /// <remarks>
    /// Worth asserting together because they are one change rather than three: each phrase is
    /// handed to the same filter reader every tutor in the corpus goes through, so the compound
    /// and the alternation needed no words of their own. The supertype is the exception and says
    /// why — asked alone, that reader answers a card type or a capitalised subtype, and
    /// "legendary" is neither, so it falls through to the atom reader that has known the word
    /// since supertypes existed.
    /// </remarks>
    [Fact]
    public void A_restriction_may_name_a_supertype_a_compound_or_an_alternation()
    {
        Assert.Equal(
            "legendary",
            EffectPhrase.SpendLimitFor("Spend this mana only to cast legendary spells.")
                ?.FilterId);

        Assert.Equal(
            "colorless&Eldrazi",
            EffectPhrase.SpendLimitFor(
                "Spend this mana only to cast colorless Eldrazi spells or activate abilities"
                    + " of colorless Eldrazi.")?.FilterId);

        Assert.Equal(
            "Knight|Equipment",
            EffectPhrase.SpendLimitFor(
                "Spend this mana only to cast a Knight or Equipment spell.")?.FilterId);

        Assert.Equal(
            "noncreature",
            EffectPhrase.SpendLimitFor("Spend this mana only to cast noncreature spells.")
                ?.FilterId);

        var legendary = new CardDefinition
        {
            OracleId = "oracle-untaidake-legend-test",
            Name = "Untaidake Legend Test",
            CardTypes = CardType.Creature,
            Supertypes = ["Legendary"],
            ManaCostRaw = "{C}",
            Cmc = 1,
        };

        var ordinary = TestCards.Costed("Untaidake Commoner Test", "{C}", 1);

        var pool = ManaPool.Empty.AddRestricted(
            new RestrictedMana(null, new ManaRestriction(ManaPurpose.CastSpell, CardType.None))
            {
                FilterId = "legendary",
            });

        Assert.NotNull(ManaPayment.Pay(
            pool, ManaCostSpec.Parse("{C}"), spend: ManaSpend.Casting(legendary, Zone.Hand)));

        Assert.Null(ManaPayment.Pay(
            pool, ManaCostSpec.Parse("{C}"), spend: ManaSpend.Casting(ordinary, Zone.Hand)));
    }

    /// <summary>
    /// "Spend this mana only to cast your commander" — Jeweled Lotus (CR 903.3).
    /// </summary>
    /// <remarks>
    /// Not a filter and never could be: which card is a commander is a fact about this game
    /// rather than about the card, and the same card in somebody else's deck is not one.
    /// <para>
    /// The colour is the part worth checking. "Add three mana of any one color" compiles to five
    /// alternatives, one per colour, and the restriction has to ride on every one of them — an
    /// alternative that lost it would be a Lotus that taps for three unrestricted mana, which is
    /// a materially better card than the one printed and nothing downstream would notice.
    /// </remarks>
    [Fact]
    public void Mana_restricted_to_a_commander_rides_on_every_colour_alternative()
    {
        var lotus = Card(
            "Jeweled Lotus Test",
            "{T}, Sacrifice this artifact: Add three mana of any one color. Spend this mana only"
                + " to cast your commander.",
            CardType.Artifact);

        var compiled = CardCompiler.Compile(lotus);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        // One alternative per colour, and the restriction on all five.
        Assert.Equal(5, compiled.Activated.Count);
        Assert.All(compiled.Activated, ability =>
        {
            var produced = Assert.Single(ability.Produces);
            Assert.Equal(3, produced.Amount);
            Assert.True(produced.RestrictedToCommander);
            Assert.Null(produced.RestrictedTo);
        });

        var general = TestCards.Costed("Jeweled Lotus General Test", "{G}", 1);

        var pool = ManaPool.Empty.AddRestricted(
            new RestrictedMana(
                ManaColor.Green,
                new ManaRestriction(ManaPurpose.CastSpell, CardType.None))
            {
                CommanderOnly = true,
            });

        Assert.NotNull(ManaPayment.Pay(
            pool,
            ManaCostSpec.Parse("{G}"),
            spend: ManaSpend.Casting(general, Zone.Command, isCommander: true)));

        // The same card cast from hand as an ordinary spell is not the commander.
        Assert.Null(ManaPayment.Pay(
            pool, ManaCostSpec.Parse("{G}"), spend: ManaSpend.Casting(general, Zone.Hand)));
    }

    /// <summary>
    /// "Spend this mana only to cast a spell from your graveyard" — the zone, read (CR 400.1).
    /// </summary>
    /// <remarks>
    /// The clause pattern ended at the word "spells", so a zone printed after it left the whole
    /// sentence unmatched. Read from where the card stands as its cost is worked out, before it
    /// moves to the stack and stops being that object (CR 400.7).
    /// </remarks>
    [Fact]
    public void A_restriction_may_name_the_zone_a_spell_is_cast_from()
    {
        var lord = Card(
            "Lord of the Forsaken Test",
            "Pay 1 life: Add {C}. Spend this mana only to cast a spell from your graveyard.",
            CardType.Creature,
            power: 6,
            toughness: 6);

        var compiled = CardCompiler.Compile(lord);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var produced = Assert.Single(Assert.Single(compiled.Activated).Produces);
        Assert.Equal(Zone.Graveyard, produced.RestrictedToZone);

        var bear = TestCards.Costed("Forsaken Bear Test", "{C}", 1);

        var pool = ManaPool.Empty.AddRestricted(
            new RestrictedMana(null, new ManaRestriction(ManaPurpose.CastSpell, CardType.None))
            {
                FromZone = Zone.Graveyard,
            });

        Assert.NotNull(ManaPayment.Pay(
            pool, ManaCostSpec.Parse("{C}"), spend: ManaSpend.Casting(bear, Zone.Graveyard)));

        Assert.Null(ManaPayment.Pay(
            pool, ManaCostSpec.Parse("{C}"), spend: ManaSpend.Casting(bear, Zone.Hand)));
    }

    /// <summary>
    /// A clause the vocabulary cannot read leaves the whole line unread, as it always did.
    /// </summary>
    /// <remarks>
    /// The failure that has to survive widening the reader. Mana that quietly lost its
    /// restriction is strictly better than the mana printed, and a land that taps for
    /// unrestricted mana is a different and better card than the one in the deck — so a clause
    /// with one unread word in it is refused whole rather than kept for the parts that happened
    /// to be understood.
    /// <para>
    /// The second case is the one a widened reader invites: two clauses each readable on their
    /// own, naming two different tribes. There is one field to put a filter in, so a restriction
    /// with two answers is refused rather than resolved to whichever was read last.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_restriction_naming_something_unread_leaves_the_line_unread()
    {
        Assert.Null(EffectPhrase.SpendLimitFor(
            "Spend this mana only to pay cumulative upkeep costs."));

        Assert.Null(EffectPhrase.SpendLimitFor(
            "Spend this mana only to cast Dragon spells or activate abilities of Myr."));

        var land = Card(
            "Unread Restriction Test",
            "{T}: Add {G}. Spend this mana only to pay cumulative upkeep costs.",
            CardType.Land);

        var compiled = CardCompiler.Compile(land);
        Assert.False(compiled.IsComplete);
        Assert.NotEmpty(compiled.Unhandled);
    }

    // ---- A question inside an intervening if (CR 603.4, 609.4) ---------------

    /// <summary>
    /// The offer a CR 603.4 guard used to forbid, put and paid.
    /// </summary>
    /// <remarks>
    /// The compiler refused any line whose intervening "if" guarded a deferred question - an
    /// offer, a search, a flip, a roll - because a question carries a locator back to itself and
    /// the locator was once resolved against an ability's <em>top-level</em> effects, where a
    /// wrapped question named the wrapper. <c>EffectTree.Locate</c> walks the whole tree now, so
    /// the two halves that had never met are the compiler's guard and the engine's lookup.
    /// <para>
    /// Both halves are asserted, and the second is the one worth having: the life is gone. An
    /// engine that ran the branch without taking the payment plays a card strictly cheaper than
    /// the one printed, and the drawn card alone would not notice.
    /// </para>
    /// </remarks>
    [Fact]
    public void An_offer_guarded_by_an_intervening_if_is_put_and_charged()
    {
        var oracle = Card(
            "Guarded Offer Test",
            "At the beginning of your upkeep, if you control an artifact, you may pay 2 life. "
                + "If you do, draw a card.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(oracle);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        game.Create(alice, oracle, Zone.Battlefield);
        game.Create(
            alice, Card("Guarded Trinket Test", string.Empty, CardType.Artifact), Zone.Battlefield);

        var hand = game.State.GetPlayer(alice).Hand.Count;

        PassTo(game, 3, TurnStep.Upkeep);
        TestCards.PassUntil(game, () => game.State.Choice is not null);

        Assert.Equal(ChoiceKind.OptionalPayment, game.State.Choice!.Kind);
        game.Choose(alice, ["yes"]);
        Settle(game);

        Assert.Equal(18, game.State.GetPlayer(alice).Life);
        Assert.Equal(hand + 1, game.State.GetPlayer(alice).Hand.Count);
    }

    /// <summary>
    /// Turning the same offer down leaves both the price and what it would have bought.
    /// </summary>
    /// <remarks>
    /// The branch behind a question is the easiest thing to run unconditionally once the question
    /// is reachable at all, and a wrapper is exactly where that goes unnoticed - the card looks
    /// right on the turn it is paid.
    /// </remarks>
    [Fact]
    public void Declining_an_offer_guarded_by_an_intervening_if_costs_nothing()
    {
        var oracle = Card(
            "Declined Guarded Offer Test",
            "At the beginning of your upkeep, if you control an artifact, you may pay 2 life. "
                + "If you do, draw a card.",
            CardType.Enchantment);

        var (game, alice, _) = InMainPhase();
        game.Create(alice, oracle, Zone.Battlefield);
        game.Create(
            alice,
            Card("Declined Trinket Test", string.Empty, CardType.Artifact),
            Zone.Battlefield);

        var hand = game.State.GetPlayer(alice).Hand.Count;

        PassTo(game, 3, TurnStep.Upkeep);
        TestCards.PassUntil(game, () => game.State.Choice is not null);

        game.Choose(alice, ["no"]);
        Settle(game);

        Assert.Equal(20, game.State.GetPlayer(alice).Life);
        Assert.Equal(hand, game.State.GetPlayer(alice).Hand.Count);
    }

    /// <summary>
    /// A guard that fails puts no question at all - not a question whose answer does nothing.
    /// </summary>
    /// <remarks>
    /// CR 603.4's first check. The assertion is on the log rather than on the life total, because
    /// a game that asks and then discards the answer has the same life total as one that never
    /// asked and is a different game to sit in front of: it stops for a click that decides
    /// nothing, once per upkeep, for as long as the enchantment is out.
    /// </remarks>
    [Fact]
    public void An_offer_guarded_by_a_failing_intervening_if_is_never_put()
    {
        var oracle = Card(
            "Unmet Guarded Offer Test",
            "At the beginning of your upkeep, if you control an artifact, you may pay 2 life. "
                + "If you do, draw a card.",
            CardType.Enchantment);

        var (game, alice, _) = InMainPhase();
        game.Create(alice, oracle, Zone.Battlefield);

        PassTo(game, 3, TurnStep.Draw);
        Settle(game);

        Assert.DoesNotContain(game.Log, e => e is OptionalPaymentRequested);
        Assert.Equal(20, game.State.GetPlayer(alice).Life);
    }

    /// <summary>
    /// The second check (CR 603.4) reaches the question, not merely what it would have bought.
    /// </summary>
    /// <remarks>
    /// The trigger goes on the stack while the artifact is there and resolves after it has gone.
    /// An engine that hoisted the offer out of its guard would put the question anyway and only
    /// swallow the branch behind it, which is the same click-for-nothing the first check refuses
    /// - so the log is what this asserts, and the life total would pass either way.
    /// </remarks>
    [Fact]
    public void A_guarded_offer_is_not_put_when_the_second_check_fails()
    {
        var oracle = Card(
            "Second Check Offer Test",
            "At the beginning of your upkeep, if you control an artifact, you may pay 2 life. "
                + "If you do, draw a card.",
            CardType.Enchantment);

        var (game, alice, _) = InMainPhase();
        game.Create(alice, oracle, Zone.Battlefield);
        var trinket = game.Create(
            alice,
            Card("Second Check Trinket Test", string.Empty, CardType.Artifact),
            Zone.Battlefield);

        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber >= 3
                && game.State.CurrentStep == TurnStep.Upkeep
                && !game.State.Stack.IsEmpty);

        TestCards.PassUntil(game, () => game.State.Priority.Holder == alice);

        var bolt = TestCards.PutInHand(
            game, alice, Card("Second Check Bolt Test", "Destroy target artifact."));

        game.CastSpell(alice, bolt, [Target.ToPermanent(trinket)]);
        Settle(game);

        Assert.DoesNotContain(game.Log, e => e is OptionalPaymentRequested);
        Assert.Equal(20, game.State.GetPlayer(alice).Life);
    }

    /// <summary>
    /// The lookup the guard was protecting: a wrapped question is still found, an ambiguous one
    /// is not.
    /// </summary>
    /// <remarks>
    /// The first half is the mechanism this whole family turns on - the answer to a deferred
    /// question arrives after the resolution that asked it is over, and the effect has to be
    /// found again by its locator. The second half is why the guard is a check rather than a
    /// deletion: <c>Locate</c> answers null rather than guessing between two effects of a kind
    /// carrying the same locator, so a tree holding such a pair would lose its answer, and the
    /// compiler asks that question of the tree it is about to hand over.
    /// </remarks>
    [Fact]
    public void A_question_inside_the_guard_is_still_found_by_its_locator()
    {
        var oracle = Card(
            "Located Offer Test",
            "At the beginning of your upkeep, if you control an artifact, you may pay 2 life. "
                + "If you do, draw a card.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(oracle);
        var trigger = Assert.Single(compiled.Triggers);

        // The wrapper is the top of the tree, and the question is underneath it.
        Assert.IsType<OnlyIf>(Assert.Single(trigger.Effects));
        Assert.NotNull(EffectTree.Locate<MayPay>(trigger.Effects, 0));

        // And the pair the check exists to refuse: two of a kind carrying one locator.
        var twice = ImmutableList.Create<IEffect>(
            new OnlyIf(
                (_, _, _, _) => true,
                [
                    new MayPay(ManaCostSpec.Parse("{1}"), [], []),
                    new MayPay(ManaCostSpec.Parse("{2}"), [], []),
                ]));

        Assert.Null(EffectTree.Locate<MayPay>(twice, 0));
    }

    /// <summary>
    /// Deathreap Ritual, from the corpus: a guard that reads what happened this turn.
    /// </summary>
    /// <remarks>
    /// The printed wording rather than a constructed one, and a condition about the turn instead
    /// of about the board - "a creature died this turn" is answered by a record the game keeps,
    /// so the guard is asked something no permanent can be looked at for. Both ends of it are
    /// played: an end step where nothing has died puts no question, and the one after a creature
    /// has gone does.
    /// </remarks>
    [Fact]
    public void A_guarded_offer_can_read_what_happened_this_turn()
    {
        var oracle = Card(
            "Deathreap Ritual Test",
            "At the beginning of each end step, if a creature died this turn, you may draw a "
                + "card.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(oracle);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        game.Create(alice, oracle, Zone.Battlefield);
        var goat = game.Create(
            alice, TestCards.Creature("Deathreap Goat Test", 1, 1), Zone.Battlefield);

        // Nothing has died, so this end step goes by without a question.
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.End);
        Settle(game);
        Assert.DoesNotContain(game.Log, e => e is OptionalPaymentRequested);

        TestCards.PassUntil(game, () => game.State.Priority.Holder == alice);
        var bolt = TestCards.PutInHand(
            game, alice, Card("Deathreap Bolt Test", "Destroy target creature."));

        game.CastSpell(alice, bolt, [Target.ToPermanent(goat)]);
        Settle(game);

        var hand = game.State.GetPlayer(alice).Hand.Count;

        TestCards.PassUntil(game, () => game.State.Choice is not null);
        Assert.Equal(ChoiceKind.OptionalPayment, game.State.Choice!.Kind);
        game.Choose(alice, ["yes"]);
        Settle(game);

        Assert.Equal(hand + 1, game.State.GetPlayer(alice).Hand.Count);
    }

    /// <summary>
    /// A guard the board vocabulary cannot name still leaves the whole line unread.
    /// </summary>
    /// <remarks>
    /// The failure that has to survive the relaxation above. Only the locator check moved; the
    /// condition is read by <see cref="BoardConditions"/> exactly as before, and a clause it
    /// cannot answer refuses the line rather than compiling to a trigger that fires whenever it
    /// likes. A guard quietly dropped is strictly better than the card printed, which is the one
    /// direction this compiler never goes.
    /// </remarks>
    [Fact]
    public void A_guard_the_board_reader_cannot_name_leaves_the_line_unread()
    {
        Assert.Null(BoardConditions.Parse("you flipped a coin and won three times this turn"));

        var oracle = Card(
            "Unread Guard Test",
            "At the beginning of your upkeep, if you flipped a coin and won three times this "
                + "turn, you may pay 2 life. If you do, draw a card.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(oracle);
        Assert.False(compiled.IsComplete);
        Assert.NotEmpty(compiled.Unhandled);
    }

    // ---- Leftovers: three measured declines, re-measured (CR 608.2c, 614.15) --

    /// <summary>
    /// Galvanic Blast, from the corpus: the ability word's line resizes the damage above it.
    /// </summary>
    /// <remarks>
    /// The commonest replacement the corpus prints, and the elliptical one: an ability word is
    /// flavour with no rules meaning (CR 207.2c) that forces a line break, so the clause after it
    /// names a size and nothing else — the sentence it replaces named the recipient, and no
    /// printed card says it twice. The fold that puts the two lines back together already
    /// existed; what did not is a reading for "~ deals 4 damage", which is not a sentence any
    /// grammar here can read because there is nothing to aim it at.
    /// <para>
    /// Both arms are played, at the same target, because a condition quietly defaulted either way
    /// compiles and passes every test that only ever satisfies it. Two damage without the
    /// artifacts and four with them, and the recipient is the same player each time — which is
    /// the half this reader could get wrong in a way the coverage number would applaud.
    /// </para>
    /// </remarks>
    [Fact]
    public void An_ability_words_instead_resizes_the_damage_on_the_line_above_it()
    {
        var blast = Card(
            "Galvanic Blast Test",
            "~ deals 2 damage to any target.\n"
                + "Metalcraft — ~ deals 4 damage instead if you control three or more artifacts.");

        var compiled = CardCompiler.Compile(blast);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();

        game.CastSpell(alice, TestCards.PutInHand(game, alice, blast), [Target.ToPlayer(bob)]);
        Settle(game);

        Assert.Equal(18, game.State.GetPlayer(bob).Life);

        for (var i = 0; i < 3; i++)
        {
            game.Create(
                alice,
                Card(
                    "Galvanic Relic Test " + i.ToString(CultureInfo.InvariantCulture),
                    string.Empty,
                    CardType.Artifact),
                Zone.Battlefield);
        }

        game.CastSpell(alice, TestCards.PutInHand(game, alice, blast), [Target.ToPlayer(bob)]);
        Settle(game);

        Assert.Equal(14, game.State.GetPlayer(bob).Life);
    }

    /// <summary>
    /// An elliptical "instead" standing in for something other than one plain damage is refused.
    /// </summary>
    /// <remarks>
    /// The fail-closed half, and the reason this reader rebuilds the damage rather than reading
    /// the clause. "~ deals 4 damage" says which verb and how much and nothing about where, so
    /// the recipient can only come from what is being replaced — and a sentence that did two
    /// things has no single answer to give it. Read anyway, the bigger damage would land on
    /// whichever of them happened to be first, on a card that compiled clean.
    /// </remarks>
    [Fact]
    public void An_elliptical_instead_over_two_instructions_leaves_the_line_unread()
    {
        var muddled = Card(
            "Muddled Instead Test",
            "~ deals 2 damage to any target and you gain 2 life.\n"
                + "Metalcraft — ~ deals 4 damage instead if you control three or more artifacts.");

        var compiled = CardCompiler.Compile(muddled);
        Assert.False(compiled.IsComplete);
        Assert.NotEmpty(compiled.Unhandled);
    }

    /// <summary>
    /// Chart a Course, from the corpus: "unless" is "if not", and it resolves off the stack.
    /// </summary>
    /// <remarks>
    /// The direct sibling of the conditional sentence above, and it was left on the belief that
    /// <see cref="OnlyIf"/> could not run from the stack at all — that its source lookup would
    /// come back empty for an instant and the family would compile into blanks. It does not:
    /// <c>ResolveTop</c> runs a spell's effects while the spell is still the object on the stack,
    /// so <c>PhysicalSourceId</c> names it. This is a sorcery, and both arms are played to say so.
    /// </remarks>
    [Fact]
    public void An_unless_clause_guards_its_effect_with_the_condition_negated()
    {
        var chart = Card(
            "Chart a Course Test",
            "Draw two cards. Then discard a card unless you control an artifact.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(chart);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        // Two games rather than two casts, because answering the discard costs the turn: this
        // is a sorcery, and by the time the question has been put and answered its caster no
        // longer has priority in a main phase.
        var (unguarded, alice, _) = InMainPhase();

        var held = unguarded.State.GetPlayer(alice).Hand.Count;
        unguarded.CastSpell(
            alice, TestCards.PutInHand(unguarded, alice, chart), targets: null);

        // The copy cast is gone, two were drawn, and the discard the condition did not stop
        // takes one back — so the question is asked, and answered before anything is counted.
        TestCards.PassUntil(
            unguarded, () => unguarded.State.Choice is { Kind: ChoiceKind.DiscardToEffect });
        unguarded.Choose(alice, [unguarded.State.Choice!.Options![0].Id]);
        Settle(unguarded);

        Assert.Equal(held + 1, unguarded.State.GetPlayer(alice).Hand.Count);

        var (guarded, amy, _) = InMainPhase();
        guarded.Create(
            amy, Card("Chart Relic Test", string.Empty, CardType.Artifact), Zone.Battlefield);

        var before = guarded.State.GetPlayer(amy).Hand.Count;
        guarded.CastSpell(amy, TestCards.PutInHand(guarded, amy, chart), targets: null);
        Settle(guarded);

        // With the artifact out nothing is discarded and nothing is asked.
        Assert.Null(guarded.State.Choice);
        Assert.Equal(before + 2, guarded.State.GetPlayer(amy).Hand.Count);
    }

    /// <summary>
    /// The "unless" that offers a payment is still the payment, not a question about the board.
    /// </summary>
    /// <remarks>
    /// The neighbour the general reader is placed behind. "Sacrifice ~ unless you pay {1}" is an
    /// offer whose decline is what sacrifices the permanent, and a reader that only asked whether
    /// a condition held would sacrifice it without ever offering anything — a strictly worse card
    /// that compiles, plays, and looks implemented. Asserted on the compiled effect, because the
    /// mistake is one of which reader claimed the sentence.
    /// </remarks>
    [Fact]
    public void An_unless_that_names_a_payment_is_still_the_payment()
    {
        var echo = Card(
            "Unless Payment Test",
            "At the beginning of your upkeep, sacrifice ~ unless you pay {1}.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(echo);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var trigger = Assert.Single(compiled.Triggers);
        var offer = Assert.IsType<MayPay>(Assert.Single(trigger.Effects));
        Assert.IsType<SacrificeSource>(Assert.Single(offer.IfYouDont));
    }

    /// <summary>
    /// Coiling Oracle, from the corpus: the branch spelling of a one-card look.
    /// </summary>
    /// <remarks>
    /// Measured as needing "a reveal a condition can then read", which is true of the rest of the
    /// family and not of this shape: the question it asks — is the revealed card a land? — is the
    /// filter the look-and-take idiom already applies to the cards it saw. So it compiles to that
    /// idiom with a pile of one, and nothing new was built. Both branches are played, because a
    /// filter read as "any card" would put every top card on the battlefield and never reach the
    /// hand.
    /// </remarks>
    [Fact]
    public void Revealing_the_top_card_branches_on_what_it_is()
    {
        var oracle = Card(
            "Coiling Oracle Test",
            "When ~ enters, reveal the top card of your library. If it's a land card, put it "
                + "onto the battlefield. Otherwise, put that card into your hand.",
            CardType.Creature,
            1,
            1);

        var compiled = CardCompiler.Compile(oracle);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();

        game.Create(alice, TestCards.BasicLand("Coiling Forest Test"), Zone.Library);
        game.Create(alice, oracle, Zone.Battlefield);
        Settle(game);

        // Nobody was asked: the card names the destination, so there is no choice to stop for
        // (CR 118.3).
        Assert.Null(game.State.Choice);
        Assert.Contains(
            game.State.Battlefield,
            id => game.State.GetObject(id).Card.Name == "Coiling Forest Test");

        var held = game.State.GetPlayer(alice).Hand.Count;
        game.Create(alice, TestCards.Creature("Coiling Bear Test", 2, 2), Zone.Library);
        game.Create(alice, oracle, Zone.Battlefield);
        Settle(game);

        Assert.Equal(held + 1, game.State.GetPlayer(alice).Hand.Count);
        Assert.Contains(
            game.State.GetPlayer(alice).Hand,
            id => game.State.GetObject(id).Card.Name == "Coiling Bear Test");
    }

    /// <summary>
    /// The same sentence with no "otherwise", and a rest clause naming the top of the library,
    /// both stay unread.
    /// </summary>
    /// <remarks>
    /// One refusal with two spellings, and the decline behind both is the same fact: everything a
    /// look did not take goes to the <em>bottom</em>. An unmatched revealed card is left where it
    /// was — on top, face up, and known to the table — so reading the one-branch form would bury
    /// it, and reading Diabolic Vision's "put the rest on top of your library in any order" would
    /// bury four cards it hands the player in an order they chose.
    /// <para>
    /// The second of those needs the ordering question as well as the destination, which is why
    /// it is not simply a wider alternation: on the bottom "in any order" is a difference nobody
    /// can observe, and on top it is the whole of what the sentence gives away.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_revealed_card_that_would_be_left_on_top_leaves_the_line_unread()
    {
        var oneBranch = CardCompiler.Compile(Card(
            "Llanowar Empath Test",
            "When ~ enters, reveal the top card of your library. If it's a creature card, put "
                + "it into your hand.",
            CardType.Creature,
            2,
            2));

        Assert.False(oneBranch.IsComplete);
        Assert.NotEmpty(oneBranch.Unhandled);

        var onTop = CardCompiler.Compile(Card(
            "Diabolic Vision Test",
            "Look at the top five cards of your library. Put one of them into your hand and the "
                + "rest on top of your library in any order.",
            CardType.Sorcery));

        Assert.False(onTop.IsComplete);
        Assert.NotEmpty(onTop.Unhandled);

        // The same sentence with the destination the engine can honour is read, which is what
        // says the refusal is about the top of the library and not about the wording.
        var onBottom = CardCompiler.Compile(Card(
            "Diabolic Bottom Test",
            "Look at the top five cards of your library. Put one of them into your hand and the "
                + "rest on the bottom of your library in any order.",
            CardType.Sorcery));

        Assert.True(onBottom.IsComplete, string.Join(" | ", onBottom.Unhandled));
    }

    // ---- A pronoun the trigger named, for the readers that used to refuse one ----

    /// <summary>
    /// "Whenever this creature blocks a creature, that creature doesn't untap during its
    /// controller's next untap step" - Wall of Frost, and the creature is the one it blocked.
    /// </summary>
    /// <remarks>
    /// The freeze had one answer for its pronoun and it was a target index, so a sentence with
    /// nothing targeted in front of it was refused outright and took the whole line - and with it
    /// the whole card - down with it. Six corpus cards print this shape: Wall of Frost, Labyrinth
    /// Minotaur, Cleric of Chill Depths, Vertigo Spawn, Mercurial Kite and Queen of Ice.
    /// <para>
    /// Both halves are asserted in the one game. "The attacker is frozen" passes on any reading
    /// that freezes something, and the reading this replaced would have frozen the wall - a card
    /// with a permanent drawback where the printed one has a permanent lock.
    /// </para>
    /// <para>
    /// The controls for the other two answers this reader can give are already played elsewhere:
    /// <see cref="A_creature_told_to_skip_its_untap_step_misses_exactly_one"/> is the target form,
    /// and <see cref="A_land_that_pays_double_sits_out_the_next_untap_step"/> is the card that
    /// really does mean itself.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_block_trigger_freezes_the_creature_it_blocked_and_not_itself()
    {
        var wall = Card(
            "Frost Wall Test",
            "Whenever this creature blocks a creature, that creature doesn't untap during "
                + "its controller's next untap step.",
            CardType.Creature,
            0,
            7);

        var compiled = CardCompiler.Compile(wall);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var blocker = game.Create(alice, wall, Zone.Battlefield);
        var attacker = game.Create(
            bob, TestCards.Creature("Frost Wall Bear Test", 2, 2), Zone.Battlefield);

        // Bob's turn, so his bear is the one attacking into the wall.
        PassTo(game, 2, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            bob, new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(alice) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);
        game.DeclareBlockers(
            alice,
            new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [attacker] = [blocker] });

        Settle(game);

        Assert.True(game.State.GetObject(attacker).Permanent?.SkipsNextUntap);
        Assert.False(game.State.GetObject(blocker).Permanent?.SkipsNextUntap);

        // Bob's own next untap step - turn four - comes and goes without the bear.
        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber == 4 && game.State.CurrentStep == TurnStep.PrecombatMain);

        Assert.True(game.State.GetObject(attacker).Permanent?.IsTapped);
    }

    /// <summary>
    /// "Whenever this creature deals combat damage to a creature, tap that creature. That creature
    /// doesn't untap during its controller's next untap step" - Mercurial Kite.
    /// </summary>
    /// <remarks>
    /// Two sentences and two readers, both answering the same pronoun, which is the whole reason
    /// this card is worth its own game: the tap had a subject and the freeze did not, so the
    /// second sentence failed and the first one went down with it. A line is read or unread whole.
    /// </remarks>
    [Fact]
    public void A_combat_damage_trigger_taps_and_freezes_the_creature_it_damaged()
    {
        var kite = Card(
            "Mercurial Kite Test",
            "Whenever this creature deals combat damage to a creature, tap that creature. "
                + "That creature doesn't untap during its controller's next untap step.",
            CardType.Creature,
            2,
            3);

        var compiled = CardCompiler.Compile(kite);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var bird = game.Create(alice, kite, Zone.Battlefield);
        var bear = game.Create(
            bob, TestCards.Creature("Kite Bear Test", 2, 3), Zone.Battlefield);

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice, new Dictionary<ObjectId, AttackTarget> { [bird] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);
        game.DeclareBlockers(
            bob, new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [bird] = [bear] });

        TestCards.PassUntil(game, () => game.State.CurrentStep >= TurnStep.PostcombatMain);
        Settle(game);

        // Both survived the exchange, and the blocker is the one holding the effect.
        Assert.Contains(bear, game.State.Battlefield);
        Assert.Contains(bird, game.State.Battlefield);
        Assert.True(game.State.GetObject(bear).Permanent?.IsTapped);
        Assert.True(game.State.GetObject(bear).Permanent?.SkipsNextUntap);
        Assert.False(game.State.GetObject(bird).Permanent?.SkipsNextUntap);
    }

    /// <summary>
    /// "When enchanted creature dies, return that card to its owner's hand" - Squee's Embrace.
    /// </summary>
    /// <remarks>
    /// Eight corpus cards, all one shape: Squee's Embrace, Demonic Vigor and the six Zendikons.
    /// The pronoun is the card the trigger's own event was about, which is the card now in a
    /// graveyard under a new id (CR 400.7) - never the Aura, which is on its way to the same
    /// graveyard by CR 704.5m.
    /// <para>
    /// The zone is the load-bearing half. <c>ReturnToHand</c> read only from the battlefield,
    /// because a target that has already left is skipped (CR 608.2b) - and a pronoun answered by
    /// the trigger names a card that is <em>expected</em> to have left, so every one of these
    /// eight would have compiled clean and returned nothing at all. A silent no-op on a complete
    /// card is worse than the unread line it replaced, which is why this test moves the card
    /// rather than reading the compiled effect.
    /// </para>
    /// </remarks>
    [Fact]
    public void An_aura_dies_trigger_returns_the_card_that_died_and_not_the_aura()
    {
        var embrace = Card(
            "Squee Embrace Test",
            "Enchant creature\n"
                + "Enchanted creature gets +2/+2 and has haste.\n"
                + "When enchanted creature dies, return that card to its owner's hand.",
            CardType.Enchantment,
            subtypes: "Aura");

        var compiled = CardCompiler.Compile(embrace);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var bear = game.Create(
            alice, TestCards.Creature("Embraced Bear Test", 2, 2), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, embrace);
        game.CastSpell(alice, card, [Target.ToPermanent(bear)]);
        Settle(game);

        Assert.Equal(4, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(bear)));

        game.Move(bear, Zone.Graveyard, MoveCause.Destroy);
        Settle(game);

        Assert.Contains(
            game.State.GetPlayer(alice).Hand,
            id => game.State.GetObject(id).Card.Name == "Embraced Bear Test");

        // The Aura went to the graveyard and stayed there: it is not what the sentence named.
        Assert.Contains(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Squee Embrace Test");
        Assert.DoesNotContain(
            game.State.GetPlayer(alice).Hand,
            id => game.State.GetObject(id).Card.Name == "Squee Embrace Test");
    }

    /// <summary>
    /// The control: "When this creature dies, return it to its owner's hand" is about itself.
    /// </summary>
    /// <remarks>
    /// Mortus Strider, and the same six words as the Aura above with a different subject in front
    /// of them. It has always read as the source and still does - the pronoun ladder gained an
    /// answer, it did not lose one - and the two games are kept side by side because a reader that
    /// took every dies-trigger pronoun as the trigger's object would return the same card here and
    /// pass anyway.
    /// </remarks>
    [Fact]
    public void A_dies_trigger_about_itself_still_returns_the_permanent_with_the_ability()
    {
        var strider = Card(
            "Mortus Strider Test",
            "When this creature dies, return it to its owner's hand.",
            CardType.Creature,
            1,
            1);

        var compiled = CardCompiler.Compile(strider);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var creature = game.Create(alice, strider, Zone.Battlefield);

        game.Move(creature, Zone.Graveyard, MoveCause.Destroy);
        Settle(game);

        Assert.Contains(
            game.State.GetPlayer(alice).Hand,
            id => game.State.GetObject(id).Card.Name == "Mortus Strider Test");
    }

    /// <summary>
    /// "Create a 2/1 red Elemental creature token with trample and haste. Sacrifice it at the
    /// beginning of the next end step" - Lagomos, Hand of Hatred, sacrificing the Elemental.
    /// </summary>
    /// <remarks>
    /// The headline of the delayed pronoun's fallback arm, and the reason it was worth a pass of
    /// its own: this card was fully compiled, it played, and every turn it sacrificed
    /// <em>itself</em>. Eleven complete cards were taking that reading - the exile half of it is
    /// Rakdos Guildmage exiling itself instead of the Goblin it just made.
    /// <para>
    /// The delay is folded into the creating effect (<see cref="DelayedTokenAction"/>), so it
    /// names the token the way mobilize's own sacrifice always has. Asserting that Lagomos is
    /// still on the battlefield is the half that fails on the old reading; asserting that the
    /// token is gone passes on both.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_delayed_sacrifice_takes_the_token_and_leaves_the_permanent_that_made_it()
    {
        var lagomos = Card(
            "Lagomos Test",
            "At the beginning of combat on your turn, create a 2/1 red Elemental creature token "
                + "with trample and haste. Sacrifice it at the beginning of the next end step.",
            CardType.Creature,
            3,
            3);

        var compiled = CardCompiler.Compile(lagomos);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var lord = game.Create(alice, lagomos, Zone.Battlefield);

        TestCards.PassUntil(game, () => game.State.CurrentStep >= TurnStep.EndOfCombat);
        Settle(game);

        var token = game.State.Battlefield.Single(
            id => game.State.GetObject(id).Card.CardTypes.HasFlag(CardType.Token));

        TestCards.PassUntil(game, () => game.State.CurrentStep >= TurnStep.Cleanup);

        Assert.DoesNotContain(token, game.State.Battlefield);
        Assert.Contains(lord, game.State.Battlefield);
    }

    // ---- Which spell aimed at it, and which object the sentence means (CR 603.2) ----

    /// <summary>
    /// Thorn Lieutenant: "a spell or ability <em>an opponent controls</em>".
    /// </summary>
    /// <remarks>
    /// The condition had one reading — the bare "becomes the target of a spell or ability" — and
    /// the corpus prints it 112 times with three independent qualifiers on it: what did the
    /// targeting, whose it was, and which of two permanents the sentence is about. Eight lines
    /// matched the old pattern, so a Thorn Lieutenant and a Frost Titan were unread lines rather
    /// than one read line with a word about whose spell it was.
    /// <para>
    /// Both halves are asserted in one game because the failure that matters is a qualifier that
    /// reads and does nothing: a trigger that fired on its controller's own spell as well would
    /// pass any test that only casts the opponent's, and it would be a strictly better card than
    /// the one printed — every Aura and pump its controller aimed at it would draw a card too.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_targeting_trigger_reads_whose_spell_did_the_targeting()
    {
        var watcher = Card(
            "Whose Spell Test",
            "Whenever ~ becomes the target of a spell or ability an opponent controls,"
                + " you gain 5 life.",
            CardType.Creature, 2, 2);

        var compiled = CardCompiler.Compile(watcher);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var creature = game.Create(alice, watcher, Zone.Battlefield);

        // Its own controller's spell is not "a spell an opponent controls".
        game.CastSpell(
            alice,
            TestCards.PutInHand(game, alice, Card("Whose Spell Mine Test", "Untap target creature.")),
            [Target.ToPermanent(creature)]);
        Settle(game);

        Assert.Equal(20, game.State.GetPlayer(alice).Life);

        TestCards.PassToTurn(game, 2);
        TestCards.PassToStep(game, TurnStep.PrecombatMain);

        game.CastSpell(
            bob,
            TestCards.PutInHand(game, bob, Card("Whose Spell Theirs Test", "Untap target creature.")),
            [Target.ToPermanent(creature)]);
        Settle(game);

        Assert.Equal(25, game.State.GetPlayer(alice).Life);
    }

    /// <summary>
    /// Stormchaser Drake: "a spell you control" is not "a spell or ability you control".
    /// </summary>
    /// <remarks>
    /// CR 113.3: an ability on the stack is an object that is not a spell, and a card that names
    /// only one of them means only one of them. The distinction is free in the engine — a stack
    /// object carries the ability it is, or does not — and it was the whole difference between
    /// reading this line and reading none of it.
    /// </remarks>
    [Fact]
    public void A_targeting_trigger_that_names_a_spell_does_not_fire_on_an_ability()
    {
        var drake = Card(
            "Spell Only Test",
            "Whenever ~ becomes the target of a spell you control, you gain 3 life.",
            CardType.Creature, 2, 2);

        var compiled = CardCompiler.Compile(drake);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var creature = game.Create(alice, drake, Zone.Battlefield);

        // An artifact rather than a creature, so the tap cost is payable the turn it arrives:
        // CR 302.6 is about creatures and about nothing else.
        var pinger = game.Create(
            alice,
            Card(
                "Spell Only Pinger Test",
                "{T}: Target creature gets +1/+1 until end of turn.",
                CardType.Artifact),
            Zone.Battlefield);

        game.ActivateAbility(alice, pinger, "a", [Target.ToPermanent(creature)]);
        Settle(game);

        Assert.Equal(20, game.State.GetPlayer(alice).Life);

        game.CastSpell(
            alice,
            TestCards.PutInHand(game, alice, Card("Spell Only Bolt Test", "Untap target creature.")),
            [Target.ToPermanent(creature)]);
        Settle(game);

        Assert.Equal(23, game.State.GetPlayer(alice).Life);
    }

    /// <summary>
    /// Fugitive Druid: the kind of spell, read from what it <em>is</em> rather than what it says.
    /// </summary>
    /// <remarks>
    /// Computed rather than printed (CR 613), which is the rule every other characteristic
    /// question in this engine answers the same way: a spell can have been given a type on its
    /// way to the stack, and the printed card is the wrong answer for all of those.
    /// </remarks>
    [Fact]
    public void A_targeting_trigger_can_name_the_kind_of_spell_that_aimed_at_it()
    {
        var druid = Card(
            "Aura Watch Test",
            "Whenever ~ becomes the target of an Aura spell, you draw a card.",
            CardType.Creature, 2, 2);

        var compiled = CardCompiler.Compile(druid);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var creature = game.Create(alice, druid, Zone.Battlefield);
        var held = game.State.GetPlayer(alice).Hand.Count;

        game.CastSpell(
            alice,
            TestCards.PutInHand(game, alice, Card("Aura Watch Bolt Test", "Untap target creature.")),
            [Target.ToPermanent(creature)]);
        Settle(game);

        // The bolt left the hand and drew nothing back into it.
        Assert.Equal(held, game.State.GetPlayer(alice).Hand.Count);

        var aura = Card(
            "Aura Watch Aura Test",
            "Enchant creature\nEnchanted creature gets +1/+1.",
            CardType.Enchantment,
            subtypes: "Aura");

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, aura), [Target.ToPermanent(creature)]);
        Settle(game);

        Assert.Equal(held + 1, game.State.GetPlayer(alice).Hand.Count);
    }

    /// <summary>
    /// Heartfire Hero: "put a +1/+1 counter on it", where "it" is the creature and not the spell.
    /// </summary>
    /// <remarks>
    /// The load-bearing test of this family, and the reason the ability carries
    /// <see cref="TriggeredAbilityDefinition.SubjectIsSource"/> at all. A <c>TargetsChosen</c> is
    /// the one event in this engine that names <em>two</em> objects — the spell or ability that
    /// did the targeting, and the permanent it was aimed at — and <c>Game.SubjectObjectOf</c> can
    /// only answer with one. It answers with the spell, because ward's "counter it" is much the
    /// commonest sentence written on that event.
    /// <para>
    /// So the seven corpus cards printing this sentence would have compiled, resolved, and put a
    /// +1/+1 counter on an object in the stack zone: a card that reads perfectly, plays as
    /// nothing, and counts as coverage. The condition already knows which of the two it means —
    /// it said <c>~</c> — so the ability records the answer and the event stops guessing.
    /// </para>
    /// <para>
    /// Asserted on the computed power as well as on the counter, because a counter recorded on a
    /// permanent nothing reads would satisfy the first assertion on its own.
    /// </para>
    /// </remarks>
    [Fact]
    public void The_pronoun_in_a_targeting_trigger_means_the_creature_and_not_the_spell()
    {
        var hero = Card(
            "Targeted Pronoun Test",
            "Whenever ~ becomes the target of a spell or ability you control,"
                + " put a +1/+1 counter on it.",
            CardType.Creature, 2, 2);

        var compiled = CardCompiler.Compile(hero);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var creature = game.Create(alice, hero, Zone.Battlefield);
        var bystander = game.Create(
            alice, TestCards.Creature("Targeted Pronoun Bystander Test", 2, 2), Zone.Battlefield);

        game.CastSpell(
            alice,
            TestCards.PutInHand(
                game, alice, Card("Targeted Pronoun Poke Test", "Untap target creature.")),
            [Target.ToPermanent(creature)]);
        Settle(game);

        Assert.Equal(
            1,
            game.State.GetObject(creature).Permanent!.Counters
                .GetValueOrDefault(CounterKinds.PlusOnePlusOne));

        var computed = Characteristics.Of(game.State, Pool, game.State.GetObject(creature));
        Assert.Equal(3, computed.Power);
        Assert.Equal(3, computed.Toughness);

        // Nothing else on the battlefield was the subject of the sentence.
        Assert.Equal(
            0,
            game.State.GetObject(bystander).Permanent!.Counters
                .GetValueOrDefault(CounterKinds.PlusOnePlusOne));
    }

    /// <summary>
    /// Task Force: the one card already reading this sentence, now reading it as a pronoun.
    /// </summary>
    /// <remarks>
    /// It compiled before this round and it compiled to something else. With no subject for a
    /// pronoun to mean, "it gets +0/+3" fell through to the reader that pumps the source, which
    /// happened to be the right permanent; with a subject it reads as the pronoun the card
    /// actually prints. The two are the same creature and that is the point — a path change on a
    /// card that already worked is exactly the kind that a coverage number cannot see, so the
    /// card is played rather than diffed.
    /// </remarks>
    [Fact]
    public void A_pronoun_pump_in_a_targeting_trigger_still_lands_on_the_creature()
    {
        var force = Card(
            "Targeted Pump Test",
            "Whenever ~ becomes the target of a spell or ability, it gets +0/+3 until end of turn.",
            CardType.Creature, 2, 2);

        var compiled = CardCompiler.Compile(force);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var creature = game.Create(alice, force, Zone.Battlefield);

        game.CastSpell(
            alice,
            TestCards.PutInHand(
                game, alice, Card("Targeted Pump Poke Test", "Untap target creature.")),
            [Target.ToPermanent(creature)]);
        Settle(game);

        var computed = Characteristics.Of(game.State, Pool, game.State.GetObject(creature));
        Assert.Equal(2, computed.Power);
        Assert.Equal(5, computed.Toughness);
    }

    /// <summary>
    /// Valiant: "for the first time each turn" is a limit on the ability, not part of the event.
    /// </summary>
    /// <remarks>
    /// CR 603.1 — the same thing "this ability triggers only once each turn" says after the
    /// effect, written into the condition instead. Lifted off before the condition is read, for
    /// the reason the sentence form is lifted off the effect: every condition reader is written
    /// against the event on its own, so a condition carrying the limit reached each of them as a
    /// shape none of them had.
    /// <para>
    /// Lifted generically rather than inside the targeting grammar because 33 corpus cards print
    /// it across 23 different conditions — life gained, life lost, counters put on, cards
    /// discarded, a surveil, a crew — and twelve cards outside this family completed on the
    /// rewrite alone. A clause in each of those readers would have been the same work 23 times.
    /// </para>
    /// <para>
    /// Both halves are asserted: it fires once however many times the event happens, and it is
    /// watching again next turn. A limit that never released would be as wrong as one that never
    /// applied, and only the second cast in the same turn can tell those two apart.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_condition_limited_to_the_first_time_each_turn_fires_once_and_resets()
    {
        var mouse = Card(
            "First Time Test",
            "Whenever ~ becomes the target of a spell or ability you control for the first time"
                + " each turn, you gain 4 life.",
            CardType.Creature, 2, 2);

        var compiled = CardCompiler.Compile(mouse);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.True(Assert.Single(compiled.Triggers).OncePerTurn);

        var (game, alice, _) = InMainPhase();
        var creature = game.Create(alice, mouse, Zone.Battlefield);

        foreach (var n in Enumerable.Range(0, 2))
        {
            game.CastSpell(
                alice,
                TestCards.PutInHand(
                    game,
                    alice,
                    Card("First Time Poke " + n + " Test", "Untap target creature.")),
                [Target.ToPermanent(creature)]);
            Settle(game);
        }

        Assert.Equal(24, game.State.GetPlayer(alice).Life);

        // Alice's next turn: the budget is spent per turn, so it is back.
        TestCards.PassToTurn(game, 3);
        TestCards.PassToStep(game, TurnStep.PrecombatMain);

        game.CastSpell(
            alice,
            TestCards.PutInHand(
                game, alice, Card("First Time Next Turn Test", "Untap target creature.")),
            [Target.ToPermanent(creature)]);
        Settle(game);

        Assert.Equal(28, game.State.GetPlayer(alice).Life);
    }

    /// <summary>
    /// Sleeping Potion: the same sentence about the permanent the Aura is attached to.
    /// </summary>
    /// <remarks>
    /// CR 702.5c — the Aura is not what was targeted, and a reading that aimed the condition at
    /// the source would make every card of this shape watch an object no spell ever names. The
    /// subject is deliberately <em>not</em> admitted to <c>TriggerConditions.TargetsTheSource</c>:
    /// the host is a third answer and not that one, so these cards read only the sentences whose
    /// effect names no object at all.
    /// </remarks>
    [Fact]
    public void An_aura_can_watch_its_host_being_targeted_rather_than_itself()
    {
        var potion = Card(
            "Host Targeted Test",
            "Enchant creature\n"
                + "When enchanted creature becomes the target of a spell or ability, sacrifice ~.",
            CardType.Enchantment,
            subtypes: "Aura");

        var compiled = CardCompiler.Compile(potion);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var host = game.Create(
            alice, TestCards.Creature("Host Targeted Host Test", 2, 2), Zone.Battlefield);
        var other = game.Create(
            alice, TestCards.Creature("Host Targeted Other Test", 2, 2), Zone.Battlefield);

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, potion), [Target.ToPermanent(host)]);
        Settle(game);

        var aura = game.State.Battlefield.Single(id =>
            game.State.GetObject(id).Card.Name == "Host Targeted Test");

        // A spell aimed somewhere else is not this sentence's event.
        game.CastSpell(
            alice,
            TestCards.PutInHand(
                game, alice, Card("Host Targeted Elsewhere Test", "Untap target creature.")),
            [Target.ToPermanent(other)]);
        Settle(game);

        Assert.Contains(aura, game.State.Battlefield);

        game.CastSpell(
            alice,
            TestCards.PutInHand(
                game, alice, Card("Host Targeted Poke Test", "Untap target creature.")),
            [Target.ToPermanent(host)]);
        Settle(game);

        Assert.DoesNotContain(aura, game.State.Battlefield);
        Assert.Contains(host, game.State.Battlefield);
    }

    /// <summary>
    /// Ward on the same permanent, and the reason the two readings cannot be one.
    /// </summary>
    /// <remarks>
    /// Ward's "counter it" means the spell that did the targeting; the trigger beside it means the
    /// creature that was targeted. Both fire off the same event and each has to get its own
    /// object, so this is the regression that catches the subject override leaking into the
    /// keyword. Countering the creature instead of the spell is a silent no-op —
    /// <c>CounterSubjectSpell</c> checks the zone and returns nothing — so the spell would resolve
    /// and no test that only asserts the trigger would notice.
    /// <para>
    /// The compiler withholds the override from any ability whose effect names "that spell" or
    /// "that ability", for the same reason. Ten corpus cards print both — Frost Titan, Reality
    /// Smasher, Glyph Keeper, the two Glasskites, Bonecrusher Giant, Forsaken Wastes, Lava
    /// Runner, Retromancer and Agrus Kos — and they stay unread rather than wrong.
    /// </para>
    /// </remarks>
    [Fact]
    public void Ward_counters_the_spell_while_the_trigger_beside_it_reads_the_creature()
    {
        var sentinel = Card(
            "Warded Watch Test",
            "Ward {2}\n"
                + "Whenever ~ becomes the target of a spell or ability an opponent controls,"
                + " put a +1/+1 counter on ~.",
            CardType.Creature, 2, 2);

        var compiled = CardCompiler.Compile(sentinel);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var guarded = game.Create(alice, sentinel, Zone.Battlefield);

        TestCards.PassToTurn(game, 2);
        TestCards.PassToStep(game, TurnStep.PrecombatMain);

        foreach (var _ in Enumerable.Range(0, 2))
        {
            var land = game.Create(bob, TestCards.BasicLand("Mountain"), Zone.Battlefield);
            game.ActivateAbility(bob, land, "mana");
        }

        game.CastSpell(
            bob,
            TestCards.PutInHand(
                game, bob, Card("Warded Watch Bolt Test", "Destroy target creature.")),
            [Target.ToPermanent(guarded)]);

        // Both abilities trigger off the one event, so their controller is asked for an order
        // before the tax is offered (CR 603.3b). That question is answered here rather than
        // waited through: it is the proof that this permanent really has two of them.
        for (var guard = 0;
            guard < 12 && game.State.Choice is not { Kind: ChoiceKind.OptionalPayment };
            guard++)
        {
            if (game.State.Choice is { } order)
            {
                Assert.Equal(ChoiceKind.OrderTriggers, order.Kind);
                Assert.Equal(2, order.Options.Count);
                game.Choose(
                    order.PlayerId,
                    [.. order.Options.Take(Math.Max(order.MinPicks, 1)).Select(o => o.Id)]);
                continue;
            }

            if (game.State.Priority.Holder is { } holder)
                game.PassPriority(holder);
        }

        Assert.Equal(bob, game.State.Choice!.PlayerId);
        game.Choose(bob, ["no"]);
        Settle(game);

        // Ward found the spell, so the creature is still here rather than destroyed.
        Assert.Contains(guarded, game.State.Battlefield);

        // And the trigger beside it found the creature.
        Assert.Equal(
            1,
            game.State.GetObject(guarded).Permanent!.Counters
                .GetValueOrDefault(CounterKinds.PlusOnePlusOne));
    }

    // ---- Fuse (CR 702.102) ---------------------------------------------------

    /// <summary>
    /// A fused split spell runs both halves, each at its own target (CR 702.102b).
    /// </summary>
    /// <remarks>
    /// The second half was compiled on its own and numbers its targets from zero. Left alone,
    /// both halves point at whatever the player chose first - one creature taking two spells'
    /// worth of attention while the other stands untouched, which is why this test pumps two
    /// different creatures by two different amounts and checks both.
    /// </remarks>
    [Fact]
    public void A_fused_split_spell_runs_both_halves_at_their_own_targets()
    {
        var split = new CardDefinition
        {
            OracleId = "oracle-test-fused",
            Name = "Test Push // Test Pull",
            ManaCostRaw = "{G}",
            OracleText = "Target creature gets +1/+1 until end of turn.",
            CardTypes = CardType.Instant,
            Faces =
            [
                new CardFace
                {
                    Name = "Test Push",
                    ManaCostRaw = "{G}",
                    TypeLine = "Instant",
                    CardTypes = CardType.Instant,
                    OracleText = "Target creature gets +1/+1 until end of turn.\nFuse",
                },
                new CardFace
                {
                    Name = "Test Pull",
                    ManaCostRaw = "{G}",
                    TypeLine = "Instant",
                    CardTypes = CardType.Instant,
                    OracleText = "Target creature gets +3/+3 until end of turn.\nFuse",
                },
            ],
        };

        var compiled = CardCompiler.Compile(split);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.True(compiled.HasFuse);

        var (game, alice, _) = InMainPhase();
        var first = game.Create(alice, TestCards.Creature("Test Fuse One", 2, 2), Zone.Battlefield);
        var second = game.Create(alice, TestCards.Creature("Test Fuse Two", 2, 2), Zone.Battlefield);
        var card = TestCards.PutInHand(game, alice, split);

        for (var i = 0; i < 4; i++)
            game.AddMana(alice, ManaColor.Green);

        game.CastSpell(
            alice,
            card,
            [Target.ToPermanent(first), Target.ToPermanent(second)],
            fused: true);

        Settle(game);

        // Each half found its own target rather than both landing on the first.
        Assert.Equal(3, Characteristics.Of(game.State, Pool, game.State.GetObject(first)).Power);
        Assert.Equal(5, Characteristics.Of(game.State, Pool, game.State.GetObject(second)).Power);
    }

    /// <summary>Fuse works from hand and nowhere else (CR 702.102a).</summary>
    [Fact]
    public void A_split_card_cannot_be_fused_without_fuse()
    {
        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, SplitCard());

        for (var i = 0; i < 6; i++)
            game.AddMana(alice, ManaColor.Blue);

        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, card, [], fused: true));
    }
    /// <summary>
    /// A spell whose own text moves it off the stack still finishes resolving (CR 608.2m).
    /// </summary>
    /// <remarks>
    /// The last thing a resolving spell does is go to its owner's graveyard, and that step used
    /// to ask the game for the object unconditionally. "Exile Blood for the Blood God!" is the
    /// printed shape that breaks it: the spell's own effects exile the card, so by the time the
    /// step runs there is nothing on the stack to move and the lookup threw.
    /// <para>
    /// Only the soak found this, and only with five cards in front of it - the card costs
    /// {1} less for each creature that died this turn, so it is uncastable on an empty board.
    /// That is the argument for a suite that plays every card in company rather than alone.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_spell_that_exiles_itself_finishes_resolving()
    {
        var selfExiling = Card(
            "Self Exiling Bolt Test",
            "~ deals 2 damage to any target. Exile ~.",
            CardType.Instant);

        var compiled = CardCompiler.Compile(selfExiling);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, selfExiling);
        TapForMana(game, alice, "Mountain");

        var before = game.State.GetPlayer(bob).Life;

        game.CastSpell(alice, card, targets: [Target.ToPlayer(bob)]);
        Settle(game);

        // The damage happened, the card is in exile rather than the graveyard, and the stack is
        // empty - the resolution finished rather than throwing on its way out.
        Assert.Equal(before - 2, game.State.GetPlayer(bob).Life);
        Assert.True(game.State.Stack.IsEmpty);
        Assert.Single(game.State.Exile);
        Assert.Empty(game.State.GetPlayer(alice).Graveyard);
    }

    /// <summary>
    /// A division covers the targets it is among, not every target the spell chose (CR 601.2d).
    /// </summary>
    /// <remarks>
    /// The announcement is checked against all the chosen targets, so the "at least one" rule had
    /// been asked of all of them — and a spell may target something in the same breath that the
    /// division has nothing to do with. Rhino, Terrible Trampler destroys a target artifact or
    /// land and then distributes three counters among up to three <em>other</em> target creatures:
    /// the artifact's zero made every announcement illegal, so a fully read permanent could not
    /// be cast at all. Found by the soak, which is the only thing that tries to cast every card.
    /// </remarks>
    [Fact]
    public void A_division_ignores_a_target_it_is_not_among()
    {
        var rhino = Card(
            "Divided Rhino Test",
            "When ~ enters, destroy target artifact. "
                + "Distribute two +1/+1 counters among up to two other target creatures.",
            CardType.Creature,
            power: 3,
            toughness: 3);

        var compiled = CardCompiler.Compile(rhino);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var bait = Card("Divided Rhino Bait", string.Empty, CardType.Artifact);
        var doomed = game.Create(bob, bait, Zone.Battlefield);
        var one = game.Create(alice, TestCards.Creature("Divided Rhino Friend One"), Zone.Battlefield);
        var two = game.Create(alice, TestCards.Creature("Divided Rhino Friend Two"), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, rhino);
        for (var i = 0; i < 4; i++)
            TapForMana(game, alice, "Forest");

        game.CastSpell(alice, card);
        Settle(game);

        // The announcement that gives the artifact's slot nothing is the only legal one, and it
        // used to be refused outright - so the assertion is that the trigger resolved at all.
        // Where the counters land is the division's own business and its own tests; what this
        // guards is that a spell targeting something outside its division can still be played.
        Assert.DoesNotContain(doomed, game.State.Battlefield);

        var spread = game.State.GetObject(one).Permanent!.Counters.GetValueOrDefault("+1/+1")
            + game.State.GetObject(two).Permanent!.Counters.GetValueOrDefault("+1/+1");

        Assert.Equal(2, spread);
    }

