    }

    /// <summary>
    /// A door is unlocked only by the permanent's controller, and only at sorcery speed
    /// (CR 709.5e, 116.2m).
    /// </summary>
    /// <remarks>
    /// The unlock is a special action rather than an ability, so none of the ordinary activation
    /// checks run over it - which means every restriction on it has to be written out, and every
    /// one of them is a thing that can be left out without anything failing.
    /// </remarks>
    [Fact]
    public void A_door_is_unlocked_only_by_its_controller_at_sorcery_speed()
    {
        var (game, alice, bob) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, Room());

        for (var i = 0; i < 6; i++)
            game.AddMana(alice, ManaColor.Red);

        game.CastSpell(alice, card, [], half: 0);
        Settle(game);

        var permanent = game.State.Battlefield
            .Single(id => game.State.GetObject(id).Card.Name == "Test Vents // Test Maze");

        // Not the opponent's to open.
        Assert.Throws<InvalidOperationException>(() => game.UnlockDoor(bob, permanent, 1));

        var bolt = TestCards.PutInHand(
            game,
            alice,
            Card("Test Door Bolt", "Test Door Bolt deals 2 damage to any target."));

        game.AddMana(alice, ManaColor.Red);
        game.CastSpell(alice, bolt, [Target.ToPlayer(alice)]);

        // Not with a spell waiting.
        Assert.Throws<InvalidOperationException>(() => game.UnlockDoor(alice, permanent, 1));
    }

    /// <summary>
    /// A fused split spell costs both halves (CR 702.102c).
