    /// <summary>
    /// Persist returns the creature once, and not a second time (CR 702.79a).
    /// </summary>
    /// <remarks>
    /// "When this creature dies, <em>if it had no -1/-1 counters on it</em>, return it to the
    /// battlefield under its owner's control with a -1/-1 counter on it." The condition is the
    /// whole mechanic: without it the creature comes back every time it dies, forever, and the
    /// first death looks exactly the same either way.
    /// </remarks>
    [Fact]
    public void Persist_returns_a_creature_once_and_not_twice()
    {
        var ghoul = Card("Test Persist Ghoul", "Persist", CardType.Creature, 2, 2);

        var compiled = CardCompiler.Compile(ghoul);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var first = game.Create(alice, ghoul, Zone.Battlefield);

        game.Move(first, Zone.Graveyard, MoveCause.Destroy);
        Settle(game);

        var back = Assert.Single(
            game.State.Battlefield,
            id => game.State.GetObject(id).Card.Name == "Test Persist Ghoul");

        Assert.Equal(
            1,
            game.State.GetObject(back).Permanent!.Counters
                .GetValueOrDefault(CounterKinds.MinusOneMinusOne));

        // It came back smaller, which is the counter doing its work.
        Assert.Equal(1, Characteristics.Of(game.State, Pool, game.State.GetObject(back)).Power);

        game.Move(back, Zone.Graveyard, MoveCause.Destroy);
        Settle(game);

        // The second death is the one the condition refuses.
        Assert.DoesNotContain(
            game.State.Battlefield,
            id => game.State.GetObject(id).Card.Name == "Test Persist Ghoul");
    }

    /// <summary>
    /// "Can block an additional creature" lets one blocker stop two attackers (CR 509.1b).
    /// </summary>
    /// <remarks>
    /// Blocking more than one attacker is a restriction lifted rather than an ability gained, and
    /// a lifted restriction is invisible until something tries to break it - so nothing had.
    /// </remarks>
    [Fact]
    public void A_creature_that_blocks_an_additional_creature_stops_two()
    {
        var wall = Card(
            "Test Extra Wall",
            "Test Extra Wall can block an additional creature.",
            CardType.Creature,
            0,
            6);

        var compiled = CardCompiler.Compile(wall);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();

        var one = game.Create(
            alice,
            Card("Test Extra One", string.Empty, CardType.Creature, 1, 1, KeywordAbility.Haste),
            Zone.Battlefield);

        var two = game.Create(
            alice,
            Card("Test Extra Two", string.Empty, CardType.Creature, 1, 1, KeywordAbility.Haste),
            Zone.Battlefield);

        var blocker = game.Create(bob, wall, Zone.Battlefield);

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);

        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget>
            {
                [one] = AttackTarget.Player(bob),
                [two] = AttackTarget.Player(bob),
            });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);

        game.DeclareBlockers(
            bob,
            new Dictionary<ObjectId, IReadOnlyList<ObjectId>>
            {
                [one] = [blocker],
                [two] = [blocker],
            });

        Settle(game);

        // Both were blocked, so neither got through.
        Assert.Equal(20, game.State.GetPlayer(bob).Life);
    }

    /// <summary>
    /// "Can't be blocked by creatures with power 2 or less" refuses the small and admits the big
    /// (CR 509.1b).
    /// </summary>
    /// <remarks>
    /// The second half is what makes this a test rather than an assertion that blocking is broken:
    /// a restriction that refused every blocker would pass any test that only tried a small one.
    /// </remarks>
    [Fact]
    public void An_evasive_creature_refuses_small_blockers_but_not_big_ones()
    {
        var brute = Card(
            "Test Brute",
            "Test Brute can't be blocked by creatures with power 2 or less.",
            CardType.Creature,
            4,
            4,
            KeywordAbility.Haste);

        var compiled = CardCompiler.Compile(brute);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, brute, Zone.Battlefield);
        var small = game.Create(bob, TestCards.Creature("Test Small Blocker", 2, 2), Zone.Battlefield);
        var big = game.Create(bob, TestCards.Creature("Test Big Blocker", 3, 3), Zone.Battlefield);

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);

        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);

        Assert.Throws<InvalidOperationException>(() => game.DeclareBlockers(
            bob,
            new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [attacker] = [small] }));

        game.DeclareBlockers(
            bob,
            new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [attacker] = [big] });

        Settle(game);
    }
    /// <summary>Undying has the same condition as persist, and had the same hole (CR 702.92a).</summary>
    /// <remarks>
    /// The two keywords are one matcher, so they were broken together and are fixed together.
    /// Asserted separately anyway: sharing an implementation today is not a promise about
    /// tomorrow, and "the other one covers it" is how half a mechanic goes untested.
    /// </remarks>
    [Fact]
    public void Undying_returns_a_creature_once_and_not_twice()
    {
        var beast = Card("Test Undying Beast", "Undying", CardType.Creature, 2, 2);

        var (game, alice, _) = InMainPhase();
        var first = game.Create(alice, beast, Zone.Battlefield);

        game.Move(first, Zone.Graveyard, MoveCause.Destroy);
        Settle(game);

        var back = Assert.Single(
            game.State.Battlefield,
            id => game.State.GetObject(id).Card.Name == "Test Undying Beast");

        Assert.Equal(3, Characteristics.Of(game.State, Pool, game.State.GetObject(back)).Power);

        game.Move(back, Zone.Graveyard, MoveCause.Destroy);
        Settle(game);

        Assert.DoesNotContain(
            game.State.Battlefield,
            id => game.State.GetObject(id).Card.Name == "Test Undying Beast");
    }

    /// <summary>
    /// "Creatures with power less than this creature's power can't block it" is measured against
    /// the current power, not the printed one (CR 509.1b).
    /// </summary>
    /// <remarks>
    /// The comparison is to a number that moves. A blocker that is legal against a 3/3 stops
    /// being legal when the attacker is pumped, and an implementation reading the printed power
    /// would be right until the first anthem.
    /// </remarks>
    [Fact]
    public void A_power_comparison_block_restriction_reads_the_current_power()
    {
        var giant = Card(
            "Test Looming Giant",
            "Creatures with power less than Test Looming Giant's power can't block it.",
            CardType.Creature,
            3,
            3,
            KeywordAbility.Haste);

        var compiled = CardCompiler.Compile(giant);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, giant, Zone.Battlefield);
        var blocker = game.Create(bob, TestCards.Creature("Test Looming Blocker", 3, 3), Zone.Battlefield);

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);

        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);

        // Equal power is not less, so this block is legal.
        game.DeclareBlockers(
            bob,
            new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [attacker] = [blocker] });

        Settle(game);
    }

    /// <summary>
    /// "When you cycle this card" fires from the hand as the card is discarded (CR 702.29a).
    /// </summary>
    /// <remarks>
    /// The trigger belongs to a card that is in the hand while the ability is activated and in
    /// the graveyard by the time it resolves - which is why the ability declares where it
    /// functions from. Nothing had ever cycled a card that had one.
    /// </remarks>
    [Fact]
    public void A_cycling_trigger_fires_when_the_card_is_cycled()
    {
        var relic = Card(
            "Test Cycling Relic",
            "Cycling {1}\nWhen you cycle Test Cycling Relic, you gain 3 life.",
            CardType.Artifact);

        var compiled = CardCompiler.Compile(relic);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var before = game.State.GetPlayer(alice).Life;
        var card = TestCards.PutInHand(game, alice, relic);

        game.AddMana(alice, ManaColor.Green);
