    /// <summary>
    /// A cost reduction with a condition applies only when the condition holds.
    /// </summary>
    /// <remarks>
    /// A reduction that always applied would make the card cheaper and never fail, which is the
    /// shape of bug this whole pass keeps finding. So the spell is cast with exactly the reduced
    /// amount of mana while the condition is false, and refused.
    /// </remarks>
    [Fact]
    public void A_conditional_cost_reduction_waits_for_its_condition()
    {
        var relic = new CardDefinition
        {
            OracleId = "oracle-test-thrifty-relic",
            Name = "Test Thrifty Relic",
            ManaCostRaw = "{3}",
            Cmc = 3,
            OracleText = "Test Thrifty Relic costs {2} less to cast if you control a Goblin.",
            CardTypes = CardType.Artifact,
        };

        var compiled = CardCompiler.Compile(relic);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, relic);

        // One mana: enough only if the reduction applies, and it must not.
        game.AddMana(alice, ManaColor.Green);

        Assert.Throws<InvalidOperationException>(() => game.CastSpell(alice, card, []));
    }
    /// <summary>
    /// A cost reduction counted "for each" scales with the board.
    /// </summary>
    /// <remarks>
    /// Two assertions, because either alone is satisfied by a broken reduction: with no creatures
    /// the spell must cost full price, and with two it must cost two less. A reduction that always
    /// applied passes the second; one that never applied passes the first.
    /// </remarks>
    [Fact]
    public void A_counted_cost_reduction_scales_with_what_it_counts()
    {
        var engine = new CardDefinition
        {
            OracleId = "oracle-test-counted-relic",
            Name = "Test Counted Relic",
            ManaCostRaw = "{4}",
            Cmc = 4,
            OracleText = "Test Counted Relic costs {1} less to cast for each creature you control.",
            CardTypes = CardType.Artifact,
        };

        var compiled = CardCompiler.Compile(engine);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var bare = TestCards.PutInHand(game, alice, engine);

        // No creatures: two mana is not enough for a {4} spell.
        for (var i = 0; i < 2; i++)
            game.AddMana(alice, ManaColor.Green);

        Assert.Throws<InvalidOperationException>(() => game.CastSpell(alice, bare, []));

        game.Create(alice, TestCards.Creature("Test Counted One", 1, 1), Zone.Battlefield);
        game.Create(alice, TestCards.Creature("Test Counted Two", 1, 1), Zone.Battlefield);

        // Two creatures take {4} down to {2}, which is what is in the pool.
        game.CastSpell(alice, bare, []);
        Settle(game);

        Assert.Contains(
            game.State.Battlefield,
            id => game.State.GetObject(id).Card.Name == "Test Counted Relic");
    }

    /// <summary>
    /// Phantom damage is prevented and pays for itself with a counter (CR 615.1).
    /// </summary>
    /// <remarks>
    /// Two things have to happen together and neither is enough alone: the damage is prevented,
    /// and a +1/+1 counter comes off. A version that only prevented would be an indestructible
    /// creature; one that only removed the counter would be an ordinary creature that shrinks.
    /// </remarks>
    [Fact]
    public void Phantom_damage_is_prevented_and_costs_a_counter()
    {
        var phantom = Card(
            "Test Phantom",
            "Test Phantom enters with two +1/+1 counters on it.\n"
                + "If damage would be dealt to Test Phantom, prevent that damage. "
                + "Remove a +1/+1 counter from Test Phantom.",
            CardType.Creature,
            0,
            2);

        var compiled = CardCompiler.Compile(phantom);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, phantom);

        game.CastSpell(alice, card, []);
        Settle(game);

        var creature = game.State.Battlefield
            .Single(id => game.State.GetObject(id).Card.Name == "Test Phantom");

        Assert.Equal(
            2,
            game.State.GetObject(creature).Permanent!.Counters
                .GetValueOrDefault(CounterKinds.PlusOnePlusOne));

        var bolt = TestCards.PutInHand(
            game,
            alice,
            Card("Test Phantom Bolt", "Test Phantom Bolt deals 3 damage to any target."));

        game.AddMana(alice, ManaColor.Red);
        game.CastSpell(alice, bolt, [Target.ToPermanent(creature)]);
        Settle(game);

        // Still there: the damage was prevented rather than survived.
        Assert.Contains(
            game.State.Battlefield,
            id => game.State.GetObject(id).Card.Name == "Test Phantom");

        var after = game.State.GetObject(creature);
        Assert.Equal(0, after.Permanent!.DamageMarked);

        Assert.Equal(
            1,
            after.Permanent.Counters.GetValueOrDefault(CounterKinds.PlusOnePlusOne));
    }
    /// <summary>
    /// Renown happens once and never again (CR 702.112a, 702.112b).
    /// </summary>
    /// <remarks>
    /// "When this creature deals combat damage to a player, <em>if it isn't renowned</em>, put N
    /// +1/+1 counters on it and it becomes renowned." Renowned is a designation, and once a
    /// permanent has it it keeps it - so the counters arrive exactly once however many times the
    /// creature connects.
    /// <para>
    /// The same shape as persist: a rule whose condition is the whole of what makes it a
    /// mechanic rather than an escalating one, and whose first firing looks identical either way.
    /// </para>
    /// </remarks>
    [Fact]
    public void Renown_happens_once_however_often_the_creature_connects()
    {
        var knight = Card(
            "Test Renown Knight",
            "Renown 1",
            CardType.Creature,
            2,
            2,
            KeywordAbility.Haste);

        var compiled = CardCompiler.Compile(knight);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, knight, Zone.Battlefield);

        void SwingAt(Guid attacking)
        {
            TestCards.PassUntil(
                game,
                () => game.State.ActivePlayerId == attacking
                    && game.State.CurrentStep == TurnStep.DeclareAttackers);

            game.DeclareAttackers(
                alice,
                new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

            TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
            Settle(game);
        }

        SwingAt(alice);

        Assert.Equal(3, Characteristics.Of(game.State, Pool, game.State.GetObject(attacker)).Power);

        SwingAt(alice);

        // Still 3/3: it was already renowned the second time.
        Assert.Equal(3, Characteristics.Of(game.State, Pool, game.State.GetObject(attacker)).Power);
    }
    /// <summary>
    /// Rebound only rebounds a spell cast from hand (CR 702.88a).
    /// </summary>
    /// <remarks>
    /// "<strong>If this spell was cast from your hand</strong>, instead of putting it into your
    /// graveyard as it resolves, exile it and, at the beginning of your next upkeep, you may cast
    /// this card from exile without paying its mana cost."
    /// <para>
    /// The condition is what stops the mechanic eating itself. Rebound's own free cast comes
    /// <em>from exile</em>, so without it the spell rebounds again, and again, and is cast for
    /// nothing at the beginning of every upkeep for the rest of the game. The first rebound looks
    /// perfectly correct.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_rebounding_spell_does_not_rebound_a_second_time()
    {
        var chant = Card("Test Rebound Chant", "You gain 2 life.\nRebound", CardType.Instant);

        var compiled = CardCompiler.Compile(chant);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, chant);

        var start = game.State.GetPlayer(alice).Life;

        game.AddMana(alice, ManaColor.Green);
        game.CastSpell(alice, card, []);
        Settle(game);

        Assert.Equal(start + 2, game.State.GetPlayer(alice).Life);

        // Cast from hand: exiled rather than binned, waiting for the upkeep.
        Assert.Single(
            game.State.Exile,
            id => game.State.GetObject(id).Card.Name == "Test Rebound Chant");

        // Rebound offers the cast rather than making it (CR 702.88a: "you may cast"), and the
        // delayed ability fires as the step is entered - so the wait is for the offer and for
        // Alice to be able to act on it, not for a particular step.
        TestCards.PassUntil(
            game,
            () => game.State.Priority.Holder == alice
                && game.State.Exile.Any(
                    id => game.State.GetObject(id).Card.Name == "Test Rebound Chant"
                        && game.State.GetObject(id).MayCastFree));

        var offered = game.State.Exile.Single(
            id => game.State.GetObject(id).Card.Name == "Test Rebound Chant");

        game.CastSpell(alice, offered, targets: null);
        Settle(game);

        // The free cast happened, and the life total is what says so.
        Assert.Equal(start + 4, game.State.GetPlayer(alice).Life);

        // It was cast from exile rather than from hand, so it does not rebound again: it is in
        // the graveyard, not waiting in exile for another free casting every upkeep forever.
        Assert.DoesNotContain(
            game.State.Exile,
            id => game.State.GetObject(id).Card.Name == "Test Rebound Chant");

        Assert.Contains(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Test Rebound Chant");
    }
    /// <summary>
    /// Training compares the power a creature actually has, not the power it was printed with
    /// (CR 702.149a).
    /// </summary>
    /// <remarks>
    /// "Whenever this creature and at least one other creature <strong>with power greater than
    /// this creature's power</strong> attack..." - power, not printed power. A comparison made
    /// against the card rather than against the permanent is right until the first anthem, and an
    /// anthem is the ordinary reason a 2/2 is bigger than a 2/2.
    /// <para>
    /// The anthem here names a tribe on purpose. One that pumped everything would move both sides
    /// of the comparison and leave it looking untouched.
    /// </para>
    /// </remarks>
    [Fact]
    public void Training_compares_power_as_it_is_now_rather_than_as_printed()
    {
        var student = Card(
            "Test Training Student",
            "Training",
            CardType.Creature,
            2,
            2,
            KeywordAbility.Haste);

        var compiled = CardCompiler.Compile(student);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var trainee = game.Create(alice, student, Zone.Battlefield);

        var mentor = game.Create(
            alice,
            Card(
                "Test Training Goblin",
                string.Empty,
                CardType.Creature,
                2,
                2,
                KeywordAbility.Haste,
                "Goblin"),
            Zone.Battlefield);

        // Only the Goblin grows, so only the Goblin outsizes the student.
        game.Create(
            alice,
            Card("Test Training Banner", "Goblins you control get +1/+1.", CardType.Enchantment),
            Zone.Battlefield);

        Settle(game);

        Assert.Equal(3, Characteristics.Of(game.State, Pool, game.State.GetObject(mentor)).Power);
        Assert.Equal(2, Characteristics.Of(game.State, Pool, game.State.GetObject(trainee)).Power);

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);

        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget>
            {
                [trainee] = AttackTarget.Player(bob),
                [mentor] = AttackTarget.Player(bob),
            });

        Settle(game);

        // 3 is greater than 2, so the counter goes on.
        Assert.Equal(3, Characteristics.Of(game.State, Pool, game.State.GetObject(trainee)).Power);
    }
    /// <summary>
    /// A board condition about a characteristic reads the characteristic as it is now.
    /// </summary>
    /// <remarks>
    /// "If you control a creature with power 4 or greater" is a question about power, and power
    /// is what the layers say it is - not what the card was printed with. The condition
    /// vocabulary computed characteristics with no ability source at all, so every anthem, lord
    /// and pump in the game was invisible to it and 88 cards in the corpus asked their question
    /// against printed values.
    /// <para>
    /// The 3/3 is deliberately printed under the threshold and lifted over it by something else.
    /// A test whose creature was already big enough would pass without the fix.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_board_condition_about_power_sees_an_anthem()
    {
        var watcher = Card(
            "Test Ferocious Watcher",
            "At the beginning of your end step, if you control a creature with power 4 or greater, "
                + "you gain 3 life.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(watcher);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        game.Create(alice, watcher, Zone.Battlefield);

        var goblin = game.Create(
            alice,
            Card("Test Ferocious Goblin", string.Empty, CardType.Creature, 3, 3, KeywordAbility.None, "Goblin"),
            Zone.Battlefield);

        game.Create(
            alice,
            Card("Test Ferocious Banner", "Goblins you control get +1/+1.", CardType.Enchantment),
            Zone.Battlefield);

        Settle(game);

        // Printed 3, actually 4 - which is the whole point.
        Assert.Equal(4, Characteristics.Of(game.State, Pool, game.State.GetObject(goblin)).Power);

        var before = game.State.GetPlayer(alice).Life;

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.End);
        Settle(game);

        Assert.Equal(before + 3, game.State.GetPlayer(alice).Life);
    }
    /// <summary>
    /// A daybound permanent turns over when night falls, and stays turned over (CR 702.145c).
    /// </summary>
    /// <remarks>
    /// The staying is the assertion that matters. The bulk data lists a card's keywords once for
    /// the whole card, so a werewolf arrived <em>daybound and nightbound at once</em> - and the
    /// face rules then found it showing the wrong face whatever the time of day was. It turned
    /// over, and over, and the game stopped with "state-based actions and triggers did not
    /// settle": seventeen cards that could not be played at all, and not one of them reachable
    /// without putting one on a battlefield and waiting for dark.
    /// </remarks>
    [Fact]
    public void A_daybound_permanent_turns_over_at_night_and_stays_turned()
    {
        var werewolf = new CardDefinition
        {
            OracleId = "oracle-test-werewolf",
            Name = "Test Villager",
            ManaCostRaw = "{1}{G}",
            OracleText = "Daybound",
            CardTypes = CardType.Creature,
            Power = 2,
            Toughness = 2,
            Keywords = KeywordAbility.Daybound | KeywordAbility.Nightbound,
            Faces =
            [
                new CardFace
                {
                    Name = "Test Villager",
                    ManaCostRaw = "{1}{G}",
                    TypeLine = "Creature \u2014 Human",
                    CardTypes = CardType.Creature,
                    OracleText = "Daybound",
                    Power = 2,
                    Toughness = 2,
                    Keywords = KeywordAbility.Daybound | KeywordAbility.Nightbound,
                },
                new CardFace
                {
                    Name = "Test Werewolf",
                    ManaCostRaw = string.Empty,
                    TypeLine = "Creature \u2014 Werewolf",
                    CardTypes = CardType.Creature,
                    OracleText = "Nightbound",
                    Power = 4,
                    Toughness = 4,
                    Keywords = KeywordAbility.Daybound | KeywordAbility.Nightbound,
                },
            ],
        };

        var (game, alice, _) = InMainPhase();
        var villager = game.Create(alice, werewolf, Zone.Battlefield);
        Settle(game);

        // A daybound permanent makes it day when it is neither (CR 702.145d).
        Assert.True(game.State.IsDay);
        Assert.Equal(0, game.State.GetObject(villager).Permanent!.FaceIndex);

        // Nobody casts anything, so night falls (CR 702.145e).
        TestCards.PassUntil(game, () => game.State.IsDay == false);
        Settle(game);

        Assert.Equal(1, game.State.GetObject(villager).Permanent!.FaceIndex);

        // And it stays there: a second look, a few steps later, finds the same face.
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.End);
        Settle(game);

        Assert.Equal(1, game.State.GetObject(villager).Permanent!.FaceIndex);
    }
    // ---- Player scopes, counted at a table of four --------------------------

    /// <summary>A four-player game, where the player scopes stop looking alike.</summary>
    /// <remarks>
    /// At two players "each opponent", "target opponent" and "each other player" all pick out the
    /// same person, so a card that means one and does another is right in every game anybody
    /// tests. This is the same shape as exalted, which was correct whenever the exalted creature
    /// was itself the lone attacker - the common case hiding the rule.
    /// </remarks>
    private static (Game Game, IReadOnlyList<Guid> Seats) FourPlayers()
    {
        var seats = Enumerable.Range(1, 4)
            .Select(i => Guid.Parse(string.Concat(Enumerable.Repeat(i.ToString(
                System.Globalization.CultureInfo.InvariantCulture), 8))
                + "-1111-1111-1111-111111111111"))
            .ToList();

        var game = Game.Start(
            Guid.NewGuid(),
            [.. seats.Select((id, i) => new PlayerSetup(id, $"Seat {i}", 20, TestCards.Deck(20, $"S{i}")))],
            new GameRandom(5),
            startingPlayerId: seats[0],
            abilities: Pool);

        game.BeginPlay(withMulligans: false);
        TestCards.PassToStep(game, TurnStep.PrecombatMain);
        return (game, seats);
    }

    /// <summary>
    /// "Each opponent loses 1 life" reaches all three of them (CR 109.5).
    /// </summary>
    /// <remarks>
    /// The caster is what carries this as much as the opponents: an effect that hit "each player"
    /// would take a life from its own controller too, and at two players that is the only thing
    /// telling the two sentences apart.
    /// </remarks>
    [Fact]
    public void Each_opponent_means_all_of_them_and_not_you()
    {
        var drain = Card("Test Drain All", "Each opponent loses 1 life.");

        var compiled = CardCompiler.Compile(drain);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, seats) = FourPlayers();
        var before = seats.Select(id => game.State.GetPlayer(id).Life).ToList();

        var card = TestCards.PutInHand(game, seats[0], drain);
        game.AddMana(seats[0], ManaColor.Black);
        game.CastSpell(seats[0], card, []);
        Settle(game);

        Assert.Equal(before[0], game.State.GetPlayer(seats[0]).Life);

        for (var i = 1; i < seats.Count; i++)
            Assert.Equal(before[i] - 1, game.State.GetPlayer(seats[i]).Life);
    }

    /// <summary>"Each player" includes the caster, which is the whole difference.</summary>
    [Fact]
    public void Each_player_includes_you()
    {
        var wave = Card("Test Drain Everyone", "Each player loses 1 life.");

        var compiled = CardCompiler.Compile(wave);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, seats) = FourPlayers();
        var before = seats.Select(id => game.State.GetPlayer(id).Life).ToList();

        var card = TestCards.PutInHand(game, seats[0], wave);
        game.AddMana(seats[0], ManaColor.Black);
        game.CastSpell(seats[0], card, []);
        Settle(game);

        for (var i = 0; i < seats.Count; i++)
            Assert.Equal(before[i] - 1, game.State.GetPlayer(seats[i]).Life);
    }

    /// <summary>
    /// An amount counted per opponent counts three of them, not one (CR 107.3).
    /// </summary>
    /// <remarks>
    /// "For each opponent" is a multiplier, and at two players a multiplier of one is
    /// indistinguishable from no multiplier at all. Three is the smallest number that can tell
    /// them apart.
    /// </remarks>
    [Fact]
    public void An_amount_counted_for_each_opponent_counts_all_of_them()
    {
        var tithe = Card("Test Tithe", "You gain 2 life for each opponent.");

        var compiled = CardCompiler.Compile(tithe);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, seats) = FourPlayers();
        var before = game.State.GetPlayer(seats[0]).Life;

        var card = TestCards.PutInHand(game, seats[0], tithe);
        game.AddMana(seats[0], ManaColor.White);
        game.CastSpell(seats[0], card, []);
        Settle(game);

        // Three opponents at two life each.
        Assert.Equal(before + 6, game.State.GetPlayer(seats[0]).Life);
    }

    /// <summary>
    /// A mass sweep reaches every player's creatures, not only the two nearest (CR 109.5).
    /// </summary>
    [Fact]
    public void A_sweep_reaches_every_players_creatures()
    {
        var wrath = Card("Test Sweep All", "Destroy all creatures.");

        var (game, seats) = FourPlayers();

        var creatures = seats
            .Select(id => game.Create(id, TestCards.Creature($"Test Sweep Bear {id}", 2, 2), Zone.Battlefield))
            .ToList();

        // Four creatures entering is four triggers' worth of settling, and priority does not
        // necessarily come back to seat zero on its own - so it is waited for rather than
        // assumed.
        TestCards.PassUntil(game, () => game.State.Priority.Holder == seats[0]);

        var card = TestCards.PutInHand(game, seats[0], wrath);
        game.AddMana(seats[0], ManaColor.White);
        game.CastSpell(seats[0], card, []);
        Settle(game);

        foreach (var creature in creatures)
            Assert.DoesNotContain(creature, game.State.Battlefield);
    }
    /// <summary>
    /// Triggers from four controllers go on the stack in turn order from the active player
    /// (CR 603.3b).
    /// </summary>
    /// <remarks>
    /// Another rule that two players cannot tell apart: with one opponent, "active player first,
    /// then the rest in turn order" and "one each" put the same two abilities in the same two
    /// places. Four seats is where the order becomes a claim.
    /// <para>
    /// The active player's ability goes on <em>first</em>, which puts it at the bottom and means
    /// it resolves <em>last</em>. That inversion is the part worth pinning: an implementation
    /// that had the list the right way round and the stack the wrong way round would look
    /// entirely reasonable in the code and be backwards at the table.
    /// </para>
    /// </remarks>
    [Fact]
    public void Triggers_go_on_the_stack_in_turn_order_from_the_active_player()
    {
        var watcher = Card(
            "Test APNAP Watcher",
            "Whenever a creature enters, you gain 1 life.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(watcher);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, seats) = FourPlayers();

        foreach (var seat in seats)
            game.Create(seat, watcher, Zone.Battlefield);

        TestCards.PassUntil(game, () => game.State.Priority.Holder == seats[0]);

        // One creature, four triggers - one for each watcher.
        game.Create(seats[0], TestCards.Creature("Test APNAP Bear", 2, 2), Zone.Battlefield);

        // Waiting triggers go on the stack when a player would receive priority (CR 603.3), so
        // one pass places all four without resolving any of them.
        game.PassPriority(game.State.Priority.Holder!.Value);

        Assert.Empty(game.State.PendingTriggers);

        var owners = game.State.Stack
            .Select(id => game.State.GetObject(id))
            .Where(o => o.Ability is not null)
            .Select(o => o.ControllerId)
            .ToList();

        Assert.Equal(4, owners.Count);

        // Index 0 is the *top* of the stack (CR 405.2), so the list reads in resolution order:
        // the last player round the table resolves first and the active player resolves last.
        // That inversion is the rule doing its work - the active player's ability goes on the
        // stack first, which is why it comes off it last - and reading the list the other way
        // round makes a correct engine look backwards.
        Assert.Equal(seats.Reverse().ToList(), owners);
    }
    /// <summary>
    /// A charged Spacecraft cannot station itself (CR 702.184a).
    /// </summary>
    /// <remarks>
    /// The rule says "tap <strong>another</strong> untapped creature you control", and until this
    /// test nothing checked the word. The obvious test - stationing with no other creature on the
    /// battlefield - cannot see it either: an uncharged Spacecraft is not a creature, so the cost
    /// fails for want of any creature at all rather than for want of <em>another</em> one.
    /// <para>
    /// Once it is charged past its threshold it <em>is</em> a creature, and that is the only board
    /// on which the word does any work: a ship that could tap itself would charge itself for
    /// nothing, for ever. Mutation testing found this - turning the exclusion off broke no test.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_charged_Spacecraft_cannot_station_itself()
    {
        var (game, alice, _) = InMainPhase();
        var ship = game.Create(alice, Spacecraft(), Zone.Battlefield);

        var crew = game.Create(
            alice,
            Card("Test Self Station Hand", string.Empty, CardType.Creature, 4, 4, KeywordAbility.Haste),
            Zone.Battlefield);

        game.ActivateAbility(alice, ship, "station", [], [crew]);
        Settle(game);

        // Charged past its threshold, so it is a creature now - and untapped, and has been
        // controlled since before this turn once we get there.
        Assert.True(
            Characteristics.Of(game.State, Pool, game.State.GetObject(ship))
                .CardTypes.HasFlag(CardType.Creature));

        TestCards.PassUntil(
            game,
            () => game.State.ActivePlayerId == alice
                && game.State.CurrentStep == TurnStep.PrecombatMain
                && game.State.TurnNumber > 1);

        Settle(game);

        // It is a legal creature to tap in every respect except the one that matters.
        Assert.Throws<InvalidOperationException>(
            () => game.ActivateAbility(alice, ship, "station", [], [ship]));
    }
}
